param(
    [switch]$Check,
    [switch]$verbose,
    [switch]$AutoOptimize,
    [switch]$SecretOptimize,
    [ValidateSet('yes','no')]
    [string]$Backup = '',
    [ValidateSet('yes','no')]
    [string]$NicMsi = '',
    [switch]$randomCPPCRatings,
    [switch]$doubleccddebug,
    [switch]$ecoresdebug,
    [switch]$DisableLogs,
    [bool]$DisableRWEnNVMe = $true,
    [switch]$DebugFunctions,
    [switch]$simulate32cores,
    [switch]$simulate32logical16physical,
    [switch]$SwitchRealHyperThreadStatus,
    [switch]$forceNDIS,
    [switch]$forceNetAdapterCx,
    [switch]$rss,
    [switch]$irq,
    [switch]$both,
    [switch]$cppcDebugMode
)

# Exovance v2 is a separate derivative; see CREDITS.md for original attribution.
. (Join-Path $PSScriptRoot 'Exovance.Core.ps1')
try {
    if ($Check) {
        foreach ($file in @($PSCommandPath, (Join-Path $PSScriptRoot 'Exovance.Core.ps1'))) {
            $tokens = $null; $errors = $null
            $null = [Management.Automation.Language.Parser]::ParseFile($file, [ref]$tokens, [ref]$errors)
            if ($errors.Count) { throw ($errors -join '; ') }
        }
        Assert-ExovanceHost
        Write-Host 'PASS: Exovance v2 syntax and basic host prerequisites. No settings applied.'
        exit 0
    }
    Assert-ExovanceHost -RequireAdministrator
} catch { Write-Error $_.Exception.Message; exit 2 }
Reset-ExovanceWriteFailures

$script:DisableRWEnNVMe = [bool]$DisableRWEnNVMe

function Test-DeviceTweakerRWEnNVMeDisabled {
    return [bool]$script:DisableRWEnNVMe
}
$script:ScrollFeel = 'HyperLowLatency'
$script:DebugFunctions = $false
$script:FunctionTimings = [System.Collections.Generic.List[object]]::new()
$script:DebugStopwatch = [System.Diagnostics.Stopwatch]::new()
$script:ScriptLoadStopwatch = [System.Diagnostics.Stopwatch]::StartNew()

function Add-DeviceTweakerFunctionTiming {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][double]$Milliseconds
    )

    if (-not $script:DebugFunctions) { return }

    try {
        [void]$script:FunctionTimings.Add([PSCustomObject]@{
            TimestampTicks = [DateTime]::Now.Ticks
            Name = [string]$Name
            Milliseconds = [double]$Milliseconds
        })
    } catch {}
}

function Measure-Function {
    param([string]$Name, [scriptblock]$Block)
    if ($script:DebugFunctions) {
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        $result = & $Block
        $sw.Stop()
        Add-DeviceTweakerFunctionTiming -Name $Name -Milliseconds $sw.Elapsed.TotalMilliseconds
        return $result
    } else {
        return (& $Block)
    }
}

function Get-DeviceTweakerFirstItem {
    param([AllowNull()][object]$Values)
    if ($null -eq $Values) { return $null }
    foreach ($item in $Values) { return $item }
    return $null
}

function Select-DeviceTweakerFastFirstItems {
    param([AllowNull()][object]$Values, [int]$Count)
    if ($Count -le 0 -or $null -eq $Values) { return @() }
    $result = [System.Collections.Generic.List[object]]::new($Count)
    foreach ($item in $Values) {
        [void]$result.Add($item)
        if ($result.Count -ge $Count) { break }
    }
    return $result.ToArray()
}

function Select-DeviceTweakerFastSkipItems {
    param([AllowNull()][object]$Values, [int]$Skip)
    if ($null -eq $Values) { return @() }
    if ($Skip -lt 0) { $Skip = 0 }
    $result = [System.Collections.Generic.List[object]]::new()
    $index = 0
    foreach ($item in $Values) {
        if ($index -ge $Skip) { [void]$result.Add($item) }
        $index++
    }
    return $result.ToArray()
}

function Select-DeviceTweakerFastLastItems {
    param([AllowNull()][object]$Values, [int]$Count)
    if ($Count -le 0 -or $null -eq $Values) { return @() }
    $buffer = [System.Collections.Generic.List[object]]::new()
    foreach ($item in $Values) { [void]$buffer.Add($item) }
    if ($buffer.Count -le $Count) { return $buffer.ToArray() }
    $result = [System.Collections.Generic.List[object]]::new($Count)
    for ($i = $buffer.Count - $Count; $i -lt $buffer.Count; $i++) { [void]$result.Add($buffer[$i]) }
    return $result.ToArray()
}

function Get-DeviceTweakerFirstNonWhiteSpaceToken {
    param([AllowNull()][string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return '' }
    $start = -1
    $len = $Text.Length
    for ($i = 0; $i -lt $len; $i++) {
        if (-not [char]::IsWhiteSpace($Text[$i])) { $start = $i; break }
    }
    if ($start -lt 0) { return '' }
    $end = $len
    for ($i = $start + 1; $i -lt $len; $i++) {
        if ([char]::IsWhiteSpace($Text[$i])) { $end = $i; break }
    }
    return $Text.Substring($start, $end - $start)
}

function Get-DeviceTweakerFastIntPropertyValue {
    param([AllowNull()][object]$Object, [string]$Property, [int]$Default = 0)
    if ($null -eq $Object -or [string]::IsNullOrEmpty($Property)) { return $Default }
    try {
        $prop = $Object.PSObject.Properties[$Property]
        if ($null -ne $prop -and $null -ne $prop.Value) { return [int]$prop.Value }
    } catch { }
    return $Default
}

function Get-DeviceTweakerFastStringPropertyValue {
    param([AllowNull()][object]$Object, [string]$Property)
    if ($null -eq $Object -or [string]::IsNullOrEmpty($Property)) { return '' }
    try {
        $prop = $Object.PSObject.Properties[$Property]
        if ($null -ne $prop -and $null -ne $prop.Value) { return [string]$prop.Value }
    } catch { }
    return ''
}

function ConvertTo-DeviceTweakerFastSortedByIntProperty {
    param([AllowNull()][object]$Values, [string]$Property, [switch]$Descending)
    if ($null -eq $Values) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($value in $Values) { if ($null -ne $value) { [void]$list.Add($value) } }
    if ($list.Count -le 1) { return $list.ToArray() }

    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $itemKey = Get-DeviceTweakerFastIntPropertyValue $item $Property 0
        $j = $i - 1
        while ($j -ge 0) {
            $leftKey = Get-DeviceTweakerFastIntPropertyValue ($list[$j]) $Property 0
            $move = if ($Descending) { $leftKey -lt $itemKey } else { $leftKey -gt $itemKey }
            if (-not $move) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function ConvertTo-DeviceTweakerFastSortedUniqueIntArray {
    param(
        [AllowNull()][object]$Values,
        [int]$Min = [int]::MinValue,
        [int]$Max = [int]::MaxValue
    )
    if ($null -eq $Values) { return @() }
    $set = [System.Collections.Generic.SortedSet[int]]::new()
    foreach ($value in $Values) {
        if ($null -eq $value) { continue }
        try { $i = [int]$value } catch { continue }
        if ($i -lt $Min -or $i -gt $Max) { continue }
        [void]$set.Add($i)
    }
    if ($set.Count -eq 0) { return @() }
    $result = [int[]]::new($set.Count)
    $set.CopyTo($result)
    return $result
}

function ConvertTo-DeviceTweakerFastSortedUniqueStringArray {
    param([AllowNull()][object]$Values)
    if ($null -eq $Values) { return @() }
    $set = [System.Collections.Generic.SortedSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($value in $Values) {
        if ($null -eq $value) { continue }
        $text = ([string]$value).Trim()
        if ($text.Length -eq 0) { continue }
        [void]$set.Add($text)
    }
    if ($set.Count -eq 0) { return @() }
    $result = [string[]]::new($set.Count)
    $set.CopyTo($result)
    return $result
}

function Get-DeviceTweakerFastUniqueIntCount {
    param([AllowNull()][object]$Values)
    if ($null -eq $Values) { return 0 }
    $set = [System.Collections.Generic.HashSet[int]]::new()
    foreach ($value in $Values) {
        if ($null -eq $value) { continue }
        try { [void]$set.Add([int]$value) } catch { }
    }
    return [int]$set.Count
}

function Get-DeviceTweakerFastUniqueIntSummary {
    param([AllowNull()][object]$Values)
    $set = [System.Collections.Generic.HashSet[int]]::new()
    $first = $null
    if ($null -ne $Values) {
        foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            try { $i = [int]$value } catch { continue }
            if ($set.Add($i) -and $null -eq $first) { $first = $i }
        }
    }
    return [PSCustomObject]@{ Count = [int]$set.Count; First = $first }
}

function Get-DeviceTweakerFastMaxInt {
    param([AllowNull()][object]$Values, [AllowNull()][object]$Default = $null)
    $found = $false
    $max = 0
    if ($null -ne $Values) {
        foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            try { $i = [int]$value } catch { continue }
            if (-not $found -or $i -gt $max) {
                $max = $i
                $found = $true
            }
        }
    }
    if ($found) { return $max }
    return $Default
}

function Get-DeviceTweakerFastUInt64MinMax {
    param([AllowNull()][object]$Values)
    $found = $false
    [uint64]$min = [uint64]0
    [uint64]$max = [uint64]0
    if ($null -ne $Values) {
        foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            try { [uint64]$u = [uint64]$value } catch { continue }
            if (-not $found) {
                $min = $u
                $max = $u
                $found = $true
                continue
            }
            if ($u -lt $min) { $min = $u }
            if ($u -gt $max) { $max = $u }
        }
    }
    return [PSCustomObject]@{ Found = $found; Min = $min; Max = $max }
}

function ConvertTo-DeviceTweakerFastSortedUniqueLogicalProcessors {
    param(
        [AllowNull()][object]$Objects,
        [int]$Min = [int]::MinValue,
        [int]$Max = [int]::MaxValue
    )
    if ($null -eq $Objects) { return @() }
    $set = [System.Collections.Generic.SortedSet[int]]::new()
    foreach ($obj in $Objects) {
        if ($null -eq $obj) { continue }
        try { $logicalProcessors = $obj.LogicalProcessors } catch { $logicalProcessors = $null }
        if ($null -eq $logicalProcessors) { continue }
        foreach ($lp in $logicalProcessors) {
            if ($null -eq $lp) { continue }
            try { $i = [int]$lp } catch { continue }
            if ($i -lt $Min -or $i -gt $Max) { continue }
            [void]$set.Add($i)
        }
    }
    if ($set.Count -eq 0) { return @() }
    $result = [int[]]::new($set.Count)
    $set.CopyTo($result)
    return $result
}

function ConvertTo-DeviceTweakerFastSortedGroupsByFirstLogicalProcessor {
    param([AllowNull()][object]$Groups)
    if ($null -eq $Groups) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($group in $Groups) { if ($null -ne $group) { [void]$list.Add($group) } }
    if ($list.Count -le 1) { return $list.ToArray() }

    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $itemKey = [int]::MaxValue
        try { if ($item.LogicalProcessors.Count -gt 0) { $itemKey = [int]$item.LogicalProcessors[0] } } catch { }
        $j = $i - 1
        while ($j -ge 0) {
            $leftKey = [int]::MaxValue
            try { if ($list[$j].LogicalProcessors.Count -gt 0) { $leftKey = [int]$list[$j].LogicalProcessors[0] } } catch { }
            if ($leftKey -le $itemKey) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function Set-DeviceTweakerCppcRanksFromRatings {
    param([hashtable]$Ratings, [hashtable]$Ranks)
    if ($null -eq $Ratings -or $null -eq $Ranks) { return }

    $ratingSet = [System.Collections.Generic.SortedSet[int]]::new()
    $coresByRating = @{}
    foreach ($coreObj in $Ratings.Keys) {
        try {
            $core = [int]$coreObj
            $rating = [int]$Ratings[$coreObj]
        } catch { continue }
        [void]$ratingSet.Add($rating)
        if (-not $coresByRating.ContainsKey($rating)) {
            $coresByRating[$rating] = [System.Collections.Generic.List[int]]::new()
        }
        [void]$coresByRating[$rating].Add($core)
    }

    if ($ratingSet.Count -eq 0) { return }
    $ratingArray = [int[]]::new($ratingSet.Count)
    $ratingSet.CopyTo($ratingArray)
    $rank = 1
    for ($i = $ratingArray.Length - 1; $i -ge 0; $i--) {
        $rating = [int]$ratingArray[$i]
        $cores = $coresByRating[$rating]
        for ($j = 0; $j -lt $cores.Count; $j++) {
            $Ranks[[int]$cores[$j]] = [int]$rank
        }
        $rank++
    }
}

function Compare-DeviceTweakerEndpointEntry {
    param([AllowNull()][object]$A, [AllowNull()][object]$B, [switch]$ProductRoleOnly)
    if ($null -eq $A -and $null -eq $B) { return 0 }
    if ($null -eq $A) { return 1 }
    if ($null -eq $B) { return -1 }

    if (-not $ProductRoleOnly) {
        $rankA = Get-DeviceTweakerFastIntPropertyValue $A 'Rank' 0
        $rankB = Get-DeviceTweakerFastIntPropertyValue $B 'Rank' 0
        if ($rankA -ne $rankB) { return ($rankB.CompareTo($rankA)) }

        $speedCompare = [string]::Compare((Get-DeviceTweakerFastStringPropertyValue $A 'SpeedToken'), (Get-DeviceTweakerFastStringPropertyValue $B 'SpeedToken'), [System.StringComparison]::OrdinalIgnoreCase)
        if ($speedCompare -ne 0) { return $speedCompare }
    }

    $productCompare = [string]::Compare((Get-DeviceTweakerFastStringPropertyValue $A 'ProductString'), (Get-DeviceTweakerFastStringPropertyValue $B 'ProductString'), [System.StringComparison]::OrdinalIgnoreCase)
    if ($productCompare -ne 0) { return $productCompare }

    return [string]::Compare((Get-DeviceTweakerFastStringPropertyValue $A 'Role'), (Get-DeviceTweakerFastStringPropertyValue $B 'Role'), [System.StringComparison]::OrdinalIgnoreCase)
}

function ConvertTo-DeviceTweakerFastSortedEndpointEntries {
    param([AllowNull()][object]$Entries, [switch]$ProductRoleOnly)
    if ($null -eq $Entries) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($entry in $Entries) { if ($null -ne $entry) { [void]$list.Add($entry) } }
    if ($list.Count -le 1) { return $list.ToArray() }

    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $j = $i - 1
        while ($j -ge 0 -and (Compare-DeviceTweakerEndpointEntry -A $item -B ($list[$j]) -ProductRoleOnly:$ProductRoleOnly) -lt 0) {
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function Get-DeviceTweakerFastEndpointRoleGroups {
    param([AllowNull()][object]$Entries)
    if ($null -eq $Entries) { return @() }
    $groupsBySpeed = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entry in $Entries) {
        if ($null -eq $entry) { continue }
        $speed = (Get-DeviceTweakerFastStringPropertyValue $entry 'SpeedToken').Trim()
        if ($speed.Length -eq 0) { continue }
        if (-not $groupsBySpeed.ContainsKey($speed)) {
            $groupsBySpeed[$speed] = [PSCustomObject]@{
                Name    = $speed
                Group   = [System.Collections.Generic.List[object]]::new()
                MaxRank = 0
            }
        }
        $group = $groupsBySpeed[$speed]
        [void]$group.Group.Add($entry)
        $rank = Get-DeviceTweakerFastIntPropertyValue $entry 'Rank' 0
        if ($rank -gt [int]$group.MaxRank) { $group.MaxRank = $rank }
    }

    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($group in $groupsBySpeed.Values) { [void]$list.Add($group) }
    if ($list.Count -le 1) { return $list.ToArray() }

    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $j = $i - 1
        while ($j -ge 0) {
            $left = $list[$j]
            $move = $false
            if ([int]$left.MaxRank -lt [int]$item.MaxRank) {
                $move = $true
            } elseif ([int]$left.MaxRank -eq [int]$item.MaxRank -and [string]::Compare([string]$left.Name, [string]$item.Name, [System.StringComparison]::OrdinalIgnoreCase) -gt 0) {
                $move = $true
            }
            if (-not $move) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}


function ConvertTo-DeviceTweakerFastSortedByScriptIntKey {
    param([AllowNull()][object]$Values, [scriptblock]$KeyScript, [switch]$Descending)
    if ($null -eq $Values) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($value in $Values) { if ($null -ne $value) { [void]$list.Add($value) } }
    if ($list.Count -le 1 -or $null -eq $KeyScript) { return $list.ToArray() }

    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        try { $itemKey = [int](& $KeyScript $item) } catch { $itemKey = 0 }
        $j = $i - 1
        while ($j -ge 0) {
            try { $leftKey = [int](& $KeyScript ($list[$j])) } catch { $leftKey = 0 }
            $move = if ($Descending) { $leftKey -lt $itemKey } else { $leftKey -gt $itemKey }
            if (-not $move) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function Get-DeviceTweakerFastBestByIntProperty {
    param([AllowNull()][object]$Values, [string]$Property, [switch]$Descending)
    if ($null -eq $Values) { return $null }
    $hasBest = $false
    $best = $null
    $bestKey = 0
    foreach ($value in $Values) {
        if ($null -eq $value) { continue }
        $key = Get-DeviceTweakerFastIntPropertyValue $value $Property 0
        if (-not $hasBest) {
            $best = $value
            $bestKey = $key
            $hasBest = $true
            continue
        }
        if (($Descending -and $key -gt $bestKey) -or ((-not $Descending) -and $key -lt $bestKey)) {
            $best = $value
            $bestKey = $key
        }
    }
    return $best
}

function Get-DeviceTweakerFastFirstWhere {
    param([AllowNull()][object]$Values, [scriptblock]$Predicate)
    if ($null -eq $Values -or $null -eq $Predicate) { return $null }
    foreach ($value in $Values) {
        if ($null -eq $value) { continue }
        try {
            if (& $Predicate $value) { return $value }
        } catch { }
    }
    return $null
}

function Get-DeviceTweakerCppcExtremaCore {
    param([AllowNull()][object]$CoreList, [switch]$Best)
    if ($null -eq $CoreList -or -not $script:cppcEnabled) { return $null }
    $found = $false
    $chosenCore = $null
    $chosenRating = 0
    foreach ($coreObj in $CoreList) {
        if ($null -eq $coreObj) { continue }
        try { $core = [int]$coreObj } catch { continue }
        if (-not $script:cppcRatings.ContainsKey($core)) { continue }
        $rating = [int]$script:cppcRatings[$core]
        if (-not $found) {
            $chosenCore = $core
            $chosenRating = $rating
            $found = $true
            continue
        }
        if (($Best -and $rating -gt $chosenRating) -or ((-not $Best) -and $rating -lt $chosenRating)) {
            $chosenCore = $core
            $chosenRating = $rating
        }
    }
    if ($found) { return $chosenCore }
    return $null
}


function Get-DeviceTweakerUsbRolePriority {
    param([AllowNull()][object]$Device)
    if ($null -eq $Device) { return 3 }
    try { $roles = @(Get-AutoOptRoles $Device) } catch { $roles = @() }
    if ($roles -contains 'Controller') { return 0 }
    if ($roles -contains 'Mouse') { return 1 }
    if (($roles.Count -eq 1 -and $roles -contains 'Keyboard') -or ($roles -contains 'Keyboard')) { return 2 }
    return 3
}

function Get-DeviceTweakerAutoOptRolePriority {
    param([AllowNull()][object]$Device)
    if ($null -eq $Device) { return 6 }
    try {
        $category = [string]$Device.Category
        $role = [string]$Device.Role
        if ($category -eq 'PCI' -and $role -eq 'GPU') { return 0 }
        $roles = @(Get-AutoOptRoles $Device)
        if ($roles -contains 'Controller') { return 1 }
        if ($roles -contains 'Mouse') { return 2 }
        if ($roles -contains 'Keyboard') { return 3 }
        if ($category -eq 'Network') { return 4 }
        if (($category -eq 'PCI' -and $role -eq 'Audio') -or (($roles.Count -eq 1) -and ($roles -contains 'Audio'))) { return 5 }
    } catch { }
    return 6
}

function ConvertTo-DeviceTweakerFastSortedAutoOptDevices {
    param([AllowNull()][object]$Devices)
    if ($null -eq $Devices) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($device in $Devices) { if ($null -ne $device) { [void]$list.Add($device) } }
    if ($list.Count -le 1) { return $list.ToArray() }
    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $itemKey = Get-DeviceTweakerAutoOptRolePriority $item
        try { $itemName = [string]$item.DisplayName } catch { $itemName = '' }
        $j = $i - 1
        while ($j -ge 0) {
            $left = $list[$j]
            $leftKey = Get-DeviceTweakerAutoOptRolePriority $left
            try { $leftName = [string]$left.DisplayName } catch { $leftName = '' }
            $move = $false
            if ($leftKey -gt $itemKey) { $move = $true }
            elseif ($leftKey -eq $itemKey -and [string]::Compare($leftName, $itemName, [System.StringComparison]::OrdinalIgnoreCase) -gt 0) { $move = $true }
            if (-not $move) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function ConvertTo-DeviceTweakerFastSortedUsbDevices {
    param([AllowNull()][object]$Devices)
    if ($null -eq $Devices) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($device in $Devices) { if ($null -ne $device) { [void]$list.Add($device) } }
    if ($list.Count -le 1) { return $list.ToArray() }
    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $itemKey = Get-DeviceTweakerUsbRolePriority $item
        $j = $i - 1
        while ($j -ge 0) {
            $leftKey = Get-DeviceTweakerUsbRolePriority ($list[$j])
            if ($leftKey -le $itemKey) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function Get-DeviceTweakerFastPairIntValue {
    param([AllowNull()][object]$Pair, [string]$Path)
    if ($null -eq $Pair) { return 0 }
    try {
        switch ($Path) {
            'CombinedRating' { return [int]$Pair.CombinedRating }
            'Unit1.Rating' { return [int]$Pair.Unit1.Rating }
            'Unit2.Rating' { return [int]$Pair.Unit2.Rating }
            'Unit1.Id' { return [int]$Pair.Unit1.Id }
            'Unit2.Id' { return [int]$Pair.Unit2.Id }
            'Unit1.PrimaryCore' { return [int]$Pair.Unit1.PrimaryCore }
            'Unit2.PrimaryCore' { return [int]$Pair.Unit2.PrimaryCore }
        }
    } catch { }
    return 0
}

function Compare-DeviceTweakerGpuPair {
    param([AllowNull()][object]$A, [AllowNull()][object]$B, [switch]$Cppc)
    if ($null -eq $A -and $null -eq $B) { return 0 }
    if ($null -eq $A) { return 1 }
    if ($null -eq $B) { return -1 }
    if ($Cppc) {
        foreach ($path in @('CombinedRating','Unit1.Rating','Unit2.Rating')) {
            $av = Get-DeviceTweakerFastPairIntValue $A $path
            $bv = Get-DeviceTweakerFastPairIntValue $B $path
            if ($av -ne $bv) { return $bv.CompareTo($av) }
        }
        foreach ($path in @('Unit1.Id','Unit2.Id')) {
            $av = Get-DeviceTweakerFastPairIntValue $A $path
            $bv = Get-DeviceTweakerFastPairIntValue $B $path
            if ($av -ne $bv) { return $av.CompareTo($bv) }
        }
        return 0
    }
    foreach ($path in @('Unit2.PrimaryCore','Unit1.PrimaryCore')) {
        $av = Get-DeviceTweakerFastPairIntValue $A $path
        $bv = Get-DeviceTweakerFastPairIntValue $B $path
        if ($av -ne $bv) { return $bv.CompareTo($av) }
    }
    return 0
}

function ConvertTo-DeviceTweakerFastSortedGpuPairs {
    param([AllowNull()][object]$Pairs, [switch]$Cppc)
    if ($null -eq $Pairs) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($pair in $Pairs) { if ($null -ne $pair) { [void]$list.Add($pair) } }
    if ($list.Count -le 1) { return $list.ToArray() }
    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $j = $i - 1
        while ($j -ge 0 -and (Compare-DeviceTweakerGpuPair -A $item -B ($list[$j]) -Cppc:$Cppc) -lt 0) {
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function ConvertTo-DeviceTweakerFastSortedECoreSlots {
    param([AllowNull()][object]$Slots)
    if ($null -eq $Slots) { return @() }
    $list = [System.Collections.Generic.List[object]]::new()
    foreach ($slot in $Slots) { if ($null -ne $slot) { [void]$list.Add($slot) } }
    if ($list.Count -le 1) { return $list.ToArray() }
    for ($i = 1; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        try { $itemPriority = [int](Get-AutoOptECorePriorityForSlot $item) } catch { $itemPriority = 0 }
        try { $itemName = [string]$item.Device.DisplayName } catch { $itemName = '' }
        $j = $i - 1
        while ($j -ge 0) {
            $left = $list[$j]
            try { $leftPriority = [int](Get-AutoOptECorePriorityForSlot $left) } catch { $leftPriority = 0 }
            try { $leftName = [string]$left.Device.DisplayName } catch { $leftName = '' }
            $move = $false
            if ($leftPriority -gt $itemPriority) { $move = $true }
            elseif ($leftPriority -eq $itemPriority -and [string]::Compare($leftName, $itemName, [System.StringComparison]::OrdinalIgnoreCase) -gt 0) { $move = $true }
            if (-not $move) { break }
            $list[$j + 1] = $list[$j]
            $j--
        }
        $list[$j + 1] = $item
    }
    return $list.ToArray()
}

function Get-DeviceTweakerFastUnitsContainingCore {
    param([AllowNull()][object]$Units, [int]$Core)
    $list = [System.Collections.Generic.List[object]]::new()
    if ($null -eq $Units) { return $list.ToArray() }
    foreach ($unit in $Units) {
        if ($null -eq $unit) { continue }
        foreach ($c in @($unit.Cores)) {
            try {
                if ([int]$c -eq $Core) { [void]$list.Add($unit); break }
            } catch { }
        }
    }
    return $list.ToArray()
}


function Get-DeviceTweakerFastFirstEligibleGpuPairList {
    param([AllowNull()][object]$Pairs)
    $list = [System.Collections.Generic.List[object]]::new()
    if ($null -eq $Pairs) { return $list.ToArray() }
    foreach ($pair in $Pairs) {
        if ($null -eq $pair) { continue }
        try {
            if ([int]$pair.Unit1.PrimaryCore -ge 2) { [void]$list.Add($pair) }
        } catch { }
    }
    return $list.ToArray()
}



$script:DiscoveryPool = $null
$script:DiscoveryPoolMaxRunspaces = 0
$script:DiscoveryPoolInitError = $null

function Get-DeviceTweakerUsableLogicalProcessorCount {
    $logicalCount = 0

    try { $logicalCount = [int][Environment]::ProcessorCount } catch { $logicalCount = 0 }

    $currentProcess = $null
    try {
        $currentProcess = [System.Diagnostics.Process]::GetCurrentProcess()
        $affinity = $currentProcess.ProcessorAffinity
        $affinityValue = $affinity.ToInt64()
        if ($affinityValue -ne 0) {
            $affinityBytes = [System.BitConverter]::GetBytes($affinityValue)
            $affinityBits = 0
            for ($byteIndex = 0; $byteIndex -lt [IntPtr]::Size; $byteIndex++) {
                $byteValue = [int]$affinityBytes[$byteIndex]
                while ($byteValue -ne 0) {
                    $affinityBits += ($byteValue -band 1)
                    $byteValue = $byteValue -shr 1
                }
            }

            if ($affinityBits -gt 0) {
                if ($logicalCount -lt 1) {
                    $logicalCount = [int]$affinityBits
                } elseif ($affinityBits -lt $logicalCount) {
                    $logicalCount = [int]$affinityBits
                }
            }
        }
    } catch {
    } finally {
        try { if ($currentProcess) { $currentProcess.Dispose() } } catch {}
    }

    if ($logicalCount -lt 1) {
        try {
            $computerSystem = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction Stop
            if ($computerSystem -and $computerSystem.NumberOfLogicalProcessors) {
                $logicalCount = [int]$computerSystem.NumberOfLogicalProcessors
            }
        } catch {
            try {
                $computerSystem = Get-WmiObject -Class Win32_ComputerSystem -ErrorAction Stop
                if ($computerSystem -and $computerSystem.NumberOfLogicalProcessors) {
                    $logicalCount = [int]$computerSystem.NumberOfLogicalProcessors
                }
            } catch { }
        }
    }

    if ($logicalCount -lt 1) { $logicalCount = 1 }
    return [int]$logicalCount
}

function Initialize-DeviceTweakerDiscoveryPool {
    if ($script:DiscoveryPool) {
        try {
            if ($script:DiscoveryPool.RunspacePoolStateInfo.State.ToString() -eq 'Opened') {
                return $script:DiscoveryPool
            }
        } catch {}

        try { $script:DiscoveryPool.Dispose() } catch {}
        $script:DiscoveryPool = $null
    }

    try {
        $maxRunspaces = [int](Get-DeviceTweakerUsableLogicalProcessorCount)
        if ($maxRunspaces -lt 1) { $maxRunspaces = 1 }
        $script:DiscoveryPoolMaxRunspaces = $maxRunspaces
        $script:DiscoveryPool = [runspacefactory]::CreateRunspacePool(1, $maxRunspaces)
        try { $script:DiscoveryPool.ApartmentState = [System.Threading.ApartmentState]::MTA } catch {}
        try { $script:DiscoveryPool.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread } catch {}
        $script:DiscoveryPool.Open()
        $script:DiscoveryPoolInitError = $null
        return $script:DiscoveryPool
    } catch {
        $script:DiscoveryPoolInitError = $_.Exception.Message
        try { if ($script:DiscoveryPool) { $script:DiscoveryPool.Dispose() } } catch {}
        $script:DiscoveryPool = $null
        return $null
    }
}

function New-DeviceTweakerDiscoveryPowerShell {
    $ps = [PowerShell]::Create()
    try {
        $pool = Initialize-DeviceTweakerDiscoveryPool
        if ($pool) { $ps.RunspacePool = $pool }
    } catch {}
    return $ps
}

function Stop-DeviceTweakerDiscoveryPool {
    try {
        if ($script:DiscoveryPool) {
            try { $script:DiscoveryPool.Close() } catch {}
            try { $script:DiscoveryPool.Dispose() } catch {}
        }
    } finally {
        $script:DiscoveryPool = $null
        $script:DiscoveryPoolMaxRunspaces = 0
    }
}

[void](Initialize-DeviceTweakerDiscoveryPool)


function Get-DeviceTweakerInfResourceDisplayFileName {
    param([AllowNull()][string]$FileName)

    if ($null -eq $FileName) { return '' }
    $fileText = ([string]$FileName).Trim().Trim('"').Trim([char]39)
    if ([string]::IsNullOrWhiteSpace($fileText)) { return '' }

    if ($fileText.StartsWith('@')) { $fileText = $fileText.Substring(1).Trim() }
    $fileText = $fileText.Replace('/', '\')

    try {
        $parts = @($fileText -split '[\\/]')
        if ($parts.Count -gt 0) {
            $leaf = ([string]$parts[$parts.Count - 1]).Trim()
            if (-not [string]::IsNullOrWhiteSpace($leaf)) { $fileText = $leaf }
        }
    } catch { }

    return $fileText.Trim()
}

function ConvertTo-DeviceTweakerInfResourceDisplayString {
    param([AllowNull()][object]$Text)

    if ($null -eq $Text) { return $null }
    $value = [string]$Text
    if ([string]::IsNullOrWhiteSpace($value)) { return $value }

    $trimmed = $value.Trim()

    if ($trimmed.Length -ge 2) {
        $first = $trimmed[0]
        $last = $trimmed[$trimmed.Length - 1]
        if (($first -eq [char]39 -or $first -eq [char]34) -and $last -eq $first) {
            $inner = $trimmed.Substring(1, $trimmed.Length - 2)
            $innerDisplay = ConvertTo-DeviceTweakerInfResourceDisplayString $inner
            if ($innerDisplay -ne $inner) { return ([string]$first + $innerDisplay + [string]$first) }
        }
    }

    $match = [regex]::Match($trimmed, '(?i)^@?(?<file>[^,;''"`|\r\n]+?\.inf)\s*,\s*(?<ref>[^;''"`|\r\n]*)\s*;\s*(?<desc>.+?)\s*$')
    if ($match.Success) {
        $file = Get-DeviceTweakerInfResourceDisplayFileName $match.Groups['file'].Value
        $desc = ([string]$match.Groups['desc'].Value).Trim().Trim('"').Trim([char]39)
        $desc = [regex]::Replace($desc, '\s+', ' ').Trim()
        if (-not [string]::IsNullOrWhiteSpace($file) -and -not [string]::IsNullOrWhiteSpace($desc)) {
            return ("$file - $desc")
        }
    }

    return $value
}

function ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay {
    param([AllowNull()][string]$Text)

    if ($null -eq $Text) { return $null }
    if ([string]::IsNullOrWhiteSpace($Text)) { return $Text }

    $pattern = '(?i)@(?<file>[^,;''"`|\r\n]+?\.inf)\s*,\s*(?<ref>[^;''"`|\r\n]*)\s*;\s*(?<desc>.*?)(?=(?:[''"`|\r\n]|$|\s+[A-Za-z][A-Za-z0-9_/\- ]*?\s*=|\s+Reason\s*:))'
    return [regex]::Replace([string]$Text, $pattern, {
        param([System.Text.RegularExpressions.Match]$match)

        $file = Get-DeviceTweakerInfResourceDisplayFileName $match.Groups['file'].Value
        $desc = ([string]$match.Groups['desc'].Value).Trim().Trim('"').Trim([char]39)
        $desc = [regex]::Replace($desc, '\s+', ' ').Trim()
        if ([string]::IsNullOrWhiteSpace($file) -or [string]::IsNullOrWhiteSpace($desc)) { return $match.Value }
        return ("$file - $desc")
    })
}

function ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath {
    param([AllowNull()][object]$Path)

    if ($null -eq $Path) { return $null }

    $text = [string]$Path
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }

    $infDisplayText = ConvertTo-DeviceTweakerInfResourceDisplayString $text
    if ($infDisplayText -ne $text) { return $infDisplayText }

    $text = [regex]::Replace($text, '(?i)\\u0026', '&')
    $text = [regex]::Replace($text, '(?i)\\u003c', '<')
    $text = [regex]::Replace($text, '(?i)\\u003e', '>')
    $text = [regex]::Replace($text, '(?i)\\u0027', "'")
    $text = $text.Trim().Trim('"')
    $text = $text.Replace('/', '\')

    $text = [regex]::Replace($text, '^(?i:Microsoft\.PowerShell\.Core\\Registry::)', '')
    $text = [regex]::Replace($text, '^(?i:Registry::)', '')

    $rootMap = @(
        @{ Drive = 'HKLM'; HivePattern = 'HKEY[_]?LOCAL[_]?MACHINE';   Canonical = 'HKEY_LOCAL_MACHINE' },
        @{ Drive = 'HKCU'; HivePattern = 'HKEY[_]?CURRENT[_]?USER';    Canonical = 'HKEY_CURRENT_USER' },
        @{ Drive = 'HKCR'; HivePattern = 'HKEY[_]?CLASSES[_]?ROOT';    Canonical = 'HKEY_CLASSES_ROOT' },
        @{ Drive = 'HKU';  HivePattern = 'HKEY[_]?USERS';             Canonical = 'HKEY_USERS' },
        @{ Drive = 'HKCC'; HivePattern = 'HKEY[_]?CURRENT[_]?CONFIG'; Canonical = 'HKEY_CURRENT_CONFIG' }
    )

    foreach ($entry in $rootMap) {
        $drive = [regex]::Escape([string]$entry.Drive)
        $hivePattern = [string]$entry.HivePattern
        $canonical = [string]$entry.Canonical

        if ($text -match ('^(?i:{0}):\\+(?<tail>.*)$' -f $drive)) {
            $tail = [string]$Matches['tail']
            if ([string]::IsNullOrEmpty($tail)) { return ($canonical + '\') }
            return ($canonical + '\' + $tail)
        }
        if ($text -match ('^(?i:{0}):$' -f $drive)) { return $canonical }

        if ($text -match ('^(?i:{0})\\+(?<tail>.*)$' -f $drive)) {
            $tail = [string]$Matches['tail']
            if ([string]::IsNullOrEmpty($tail)) { return ($canonical + '\') }
            return ($canonical + '\' + $tail)
        }
        if ($text -match ('^(?i:{0})$' -f $drive)) { return $canonical }

        if ($text -match ('^(?i:{0})\\+(?<tail>.*)$' -f $hivePattern)) {
            $tail = [string]$Matches['tail']
            if ([string]::IsNullOrEmpty($tail)) { return ($canonical + '\') }
            return ($canonical + '\' + $tail)
        }
        if ($text -match ('^(?i:{0})$' -f $hivePattern)) { return $canonical }
    }

    return $text
}

function ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay {
    param([AllowNull()][string]$Text)

    if ($null -eq $Text) { return $null }
    if ([string]::IsNullOrWhiteSpace($Text)) { return $Text }

    $result = ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay ([string]$Text)
    $registryPathPattern = '(?i)(?:Microsoft\.PowerShell\.Core\\Registry::|Registry::)?(?:HKEY[_]?LOCAL[_]?MACHINE|HKEY[_]?CURRENT[_]?USER|HKEY[_]?CLASSES[_]?ROOT|HKEY[_]?USERS|HKEY[_]?CURRENT[_]?CONFIG|HKLM:|HKCU:|HKCR:|HKU:|HKCC:)\\[^\s''"`|;,)]*'

    return [regex]::Replace($result, $registryPathPattern, {
        param([System.Text.RegularExpressions.Match]$match)
        return (ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath $match.Value)
    })
}

function ConvertTo-DeviceTweakerLogRegistryPathValue {
    param([AllowNull()][string]$Value)

    if ($null -eq $Value) { return $null }

    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }

    $infDisplayText = ConvertTo-DeviceTweakerInfResourceDisplayString $text
    if ($infDisplayText -ne $text) { return $infDisplayText }

    if ($text.Length -ge 2) {
        $first = $text[0]
        $last = $text[$text.Length - 1]
        if (($first -eq [char]39 -or $first -eq [char]34) -and $last -eq $first) {
            $inner = $text.Substring(1, $text.Length - 2)
            $displayInner = ConvertTo-DeviceTweakerInfResourceDisplayString $inner
            if ($displayInner -eq $inner) { $displayInner = ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath $inner }
            if ($displayInner -ne $inner) {
                return ([string]$first + $displayInner + [string]$first)
            }
        }
    }

    $display = ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath $text
    if ($display -ne $text) { return $display }

    return (ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay $text)
}

function Add-DeviceTweakerUniquePathText {
    param(
        [Parameter(Mandatory=$true)]$Values,
        [AllowNull()][object]$Value
    )

    if ($null -eq $Value) { return }
    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text) -or $text -eq '(N/A)') { return }
    if (-not $Values.Contains($text)) { [void]$Values.Add($text) }
}

function Get-DeviceTweakerRegistryPathComparisonValues {
    param([AllowNull()][object]$Path)

    $values = [System.Collections.ArrayList]::new()
    if ($null -eq $Path) { return $values.ToArray() }

    $display = Format-RegistryPathForDisplay $Path
    Add-DeviceTweakerUniquePathText -Values $values -Value $display

    $normalized = Normalize-DeviceTweakerPathSeparators $display
    Add-DeviceTweakerUniquePathText -Values $values -Value $normalized

    if (-not [string]::IsNullOrWhiteSpace([string]$normalized)) {
        $legacyEnum = [regex]::Replace([string]$normalized, '^(?i:HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Enum\\)', '')
        Add-DeviceTweakerUniquePathText -Values $values -Value $legacyEnum

        $legacyClass = [regex]::Replace([string]$normalized, '^(?i:HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Control\\Class\\)', '')
        Add-DeviceTweakerUniquePathText -Values $values -Value $legacyClass

        $legacyHiveRelative = [regex]::Replace([string]$normalized, '^(?i:HKEY_LOCAL_MACHINE\\)', '')
        Add-DeviceTweakerUniquePathText -Values $values -Value $legacyHiveRelative
    }

    return $values.ToArray()
}



function Split-DeviceTweakerLogFields {
    param([AllowNull()][string]$Text)

    $items = [System.Collections.Generic.List[object]]::new()
    if ([string]::IsNullOrWhiteSpace($Text)) { return $items.ToArray() }

    $src = [string]$Text
    $idx = 0
    while ($idx -lt $src.Length) {
        while ($idx -lt $src.Length) {
            $ch = $src[$idx]
            if ([char]::IsWhiteSpace($ch) -or $ch -eq '|' -or $ch -eq ';' -or $ch -eq ',' -or $ch -eq '(' -or $ch -eq ')') { $idx++; continue }
            if (($idx + 1) -lt $src.Length -and $src.Substring($idx, 2) -eq '->') { $idx += 2; continue }
            break
        }
        if ($idx -ge $src.Length) { break }

        $remaining = $src.Substring($idx)
        $reasonMatch = [regex]::Match($remaining, '^(?i:Reason)\s*:\s*(.*)$')
        if ($reasonMatch.Success) {
            $items.Add([PSCustomObject]@{ Key = 'Reason'; Value = $reasonMatch.Groups[1].Value.Trim() })
            break
        }

        $keyMatch = [regex]::Match($remaining, '^([A-Za-z][A-Za-z0-9_/\- ]*?)\s*=\s*')
        if (-not $keyMatch.Success) {
            $detail = $remaining.Trim()
            if (-not [string]::IsNullOrWhiteSpace($detail)) {
                $items.Add([PSCustomObject]@{ Key = 'Detail'; Value = $detail })
            }
            break
        }

        $key = $keyMatch.Groups[1].Value.Trim()
        $idx += $keyMatch.Length

        $value = ''
        if ($idx -lt $src.Length -and ($src[$idx] -eq [char]39 -or $src[$idx] -eq [char]34)) {
            $quote = $src[$idx]
            $start = $idx
            $idx++
            while ($idx -lt $src.Length) {
                if ($src[$idx] -eq $quote) { $idx++; break }
                $idx++
            }
            $value = $src.Substring($start, $idx - $start).Trim()
        }
        else {
            $rest = $src.Substring($idx)
            $next = [regex]::Match($rest, '\s+(?=[A-Za-z][A-Za-z0-9_/\- ]*?\s*=)|\s+\|\s*|\s+->\s*')
            if ($next.Success) {
                $value = $rest.Substring(0, $next.Index).Trim()
                $idx += $next.Index + $next.Length
            } else {
                $value = $rest.Trim()
                $idx = $src.Length
            }
        }

        if (-not [string]::IsNullOrWhiteSpace($key)) {
            $items.Add([PSCustomObject]@{ Key = $key; Value = $value })
        }
    }

    return $items.ToArray()
}

function ConvertTo-DeviceTweakerPrettyLogLines {
    param([AllowNull()][object]$Text)

    $raw = if ($null -eq $Text) { '' } else { [string]$Text }
    if ([string]::IsNullOrWhiteSpace($raw)) { return @($raw) }

    $raw = ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay $raw
    $raw = ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay $raw

    if ($raw -match '^\s{2,}.{1,120}\s+:\s') { return @($raw) }

    $indent = ''
    $trimmed = $raw
    if ($raw -match '^(\s+)(.*)$') {
        $indent = $Matches[1]
        $trimmed = $Matches[2]
    }

    $firstField = [regex]::Match($trimmed, '(?<![A-Za-z0-9_/\-])([A-Za-z][A-Za-z0-9_/\- ]*?)\s*=')
    if (-not $firstField.Success) { return @($raw) }

    $title = $trimmed.Substring(0, $firstField.Index).Trim()
    $fieldText = $trimmed.Substring($firstField.Index).Trim()
    $title = [regex]::Replace($title, '\s*(?:->|\|)\s*$', '').Trim()
    $title = $title.TrimEnd([char]40).Trim()
    if ($title -eq '-') { $title = '- Entry' }

    $fields = @(Split-DeviceTweakerLogFields -Text $fieldText)
    if ($fields.Count -lt 1) { return @($raw) }

    $maxKey = 0
    foreach ($field in $fields) {
        $keyText = [string]$field.Key
        if ($keyText.Length -gt $maxKey) { $maxKey = $keyText.Length }
    }

    $lines = [System.Collections.Generic.List[string]]::new()
    $fieldIndent = $indent
    if (-not [string]::IsNullOrWhiteSpace($title)) {
        $lines.Add(($indent + $title.TrimEnd(':') + ':'))
        $fieldIndent = $indent + '  '
    }

    foreach ($field in $fields) {
        $key = [string]$field.Key
        $value = [string]$field.Value
        $value = ConvertTo-DeviceTweakerLogRegistryPathValue $value

        if ($value -match "^'(-?\d+)'$") { $value = $Matches[1] }

        if ($key -eq 'EndpointNames' -and $value -ne "'<none>'" -and $value -ne '<none>') {
            $inner = $value
            if ($inner.Length -ge 2 -and (($inner[0] -eq [char]39 -and $inner[$inner.Length - 1] -eq [char]39) -or ($inner[0] -eq [char]34 -and $inner[$inner.Length - 1] -eq [char]34))) {
                $inner = $inner.Substring(1, $inner.Length - 2)
            }
            $parts = @(($inner -split ';\s*') | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
            if ($parts.Count -gt 1) {
                $lines.Add(("{0}{1}:" -f $fieldIndent, $key))
                foreach ($part in $parts) { $lines.Add(("{0}  - '{1}'" -f $fieldIndent, $part.Trim().Trim([char]39))) }
                continue
            }
        }

        $lines.Add(("{0}{1,-$maxKey} : {2}" -f $fieldIndent, $key, $value))
    }

    return $lines.ToArray()
}

function New-DeviceTweakerRawLogEntryLine {
    param(
        [AllowNull()][object]$Timestamp,
        [AllowNull()][object]$Text
    )

    $prefix = '__DEVICE_TWEAKER_RAW_LOG_ENTRY_V1__|'
    $safeTimestamp = ''
    if ($null -ne $Timestamp) {
        if ($Timestamp -is [DateTime]) {
            $safeTimestamp = 'ticks:' + (([DateTime]$Timestamp).Ticks).ToString([System.Globalization.CultureInfo]::InvariantCulture)
        } else {
            $safeTimestamp = ([string]$Timestamp).Replace('|', ' ')
        }
    }
    $rawText = if ($null -eq $Text) { '' } else { [string]$Text }
    $payload = [Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes($rawText))
    return ($prefix + $safeTimestamp + '|' + $payload)
}

function Add-DeviceTweakerFormattedLogEntry {
    param(
        [Parameter(Mandatory=$true)]$Buffer,
        [AllowNull()][object]$Timestamp,
        [AllowNull()][object]$Text
    )

    try {
        [void]$Buffer.Add((New-DeviceTweakerRawLogEntryLine -Timestamp $Timestamp -Text $Text))
    } catch {}
}

function Append-DeviceTweakerFormattedLogEntry {
    param(
        [Parameter(Mandatory=$true)][System.Text.StringBuilder]$StringBuilder,
        [AllowNull()][object]$Timestamp,
        [AllowNull()][object]$Text
    )

    try {
        [void]$StringBuilder.AppendLine((New-DeviceTweakerRawLogEntryLine -Timestamp $Timestamp -Text $Text))
    } catch {}
}

$script:DeviceTweakerAsyncLogQueue  = [System.Collections.Concurrent.ConcurrentQueue[object]]::new()
$script:DeviceTweakerAsyncLogSignal = [System.Threading.AutoResetEvent]::new($false)
$script:DeviceTweakerAsyncLogState  = [hashtable]::Synchronized(@{ Started = $false; Stop = $false; Errors = [System.Collections.Concurrent.ConcurrentQueue[string]]::new() })
$script:DeviceTweakerAsyncLogWorker = $null
$script:DeviceTweakerAsyncLogHandle = $null

function Queue-DeviceTweakerLogText {
    param(
        [AllowNull()][string]$Path,
        [AllowNull()][string]$Text,
        [ValidateSet('Append','Overwrite')][string]$Mode = 'Append'
    )

    if ($script:DisableLogs) { return }
    if ([string]::IsNullOrWhiteSpace($Path)) { return }
    if ([string]::IsNullOrEmpty($Text)) { return }

    $script:DeviceTweakerAsyncLogQueue.Enqueue([PSCustomObject]@{
        Path = [string]$Path
        Text = [string]$Text
        Mode = [string]$Mode
    })

    try { [void]$script:DeviceTweakerAsyncLogSignal.Set() } catch {}
}

function Start-DeviceTweakerAsyncLogWriter {
    if ($script:DisableLogs) { return }
    if ($script:DeviceTweakerAsyncLogState.Started) { return }

    $script:DeviceTweakerAsyncLogState.Stop = $false
    $script:DeviceTweakerAsyncLogState.Started = $true

    $queue  = $script:DeviceTweakerAsyncLogQueue
    $signal = $script:DeviceTweakerAsyncLogSignal
    $state  = $script:DeviceTweakerAsyncLogState

    $logFormatHelpers = @(
        'function Get-DeviceTweakerInfResourceDisplayFileName {' + ${function:Get-DeviceTweakerInfResourceDisplayFileName}.ToString() + '}',
        'function ConvertTo-DeviceTweakerInfResourceDisplayString {' + ${function:ConvertTo-DeviceTweakerInfResourceDisplayString}.ToString() + '}',
        'function ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay {' + ${function:ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay}.ToString() + '}',
        'function ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath {' + ${function:ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath}.ToString() + '}',
        'function ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay {' + ${function:ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay}.ToString() + '}',
        'function ConvertTo-DeviceTweakerLogRegistryPathValue {' + ${function:ConvertTo-DeviceTweakerLogRegistryPathValue}.ToString() + '}',
        'function Split-DeviceTweakerLogFields {' + ${function:Split-DeviceTweakerLogFields}.ToString() + '}',
        'function ConvertTo-DeviceTweakerPrettyLogLines {' + ${function:ConvertTo-DeviceTweakerPrettyLogLines}.ToString() + '}',
@'
function ConvertFrom-DeviceTweakerRawLogEntryLine {
    param([AllowNull()][string]$Line)

    $prefix = '__DEVICE_TWEAKER_RAW_LOG_ENTRY_V1__|'
    if ([string]::IsNullOrEmpty($Line) -or -not $Line.StartsWith($prefix, [System.StringComparison]::Ordinal)) {
        return $null
    }

    $payload = $Line.Substring($prefix.Length)
    $separatorIndex = $payload.IndexOf('|')
    if ($separatorIndex -lt 0) { return $null }

    $timestamp = $payload.Substring(0, $separatorIndex)
    $encodedText = $payload.Substring($separatorIndex + 1)

    try {
        $bytes = [Convert]::FromBase64String($encodedText)
        $rawText = [System.Text.Encoding]::UTF8.GetString($bytes)
        return [PSCustomObject]@{ Timestamp = $timestamp; Text = $rawText }
    } catch {
        return $null
    }
}

function ConvertTo-DeviceTweakerLogTimestampText {
    param([AllowNull()][string]$Timestamp)

    if ([string]::IsNullOrEmpty($Timestamp)) { return '' }
    if ($Timestamp.StartsWith('ticks:', [System.StringComparison]::Ordinal)) {
        try {
            $ticksText = $Timestamp.Substring(6)
            return ([DateTime]::new([int64]::Parse($ticksText, [System.Globalization.CultureInfo]::InvariantCulture))).ToString('yyyy-MM-dd HH:mm:ss')
        } catch {
            return [string]$Timestamp
        }
    }
    return [string]$Timestamp
}

function ConvertTo-DeviceTweakerQueuedLogText {
    param([AllowNull()][string]$Text)

    if ([string]::IsNullOrEmpty($Text)) { return $Text }

    $rawPrefix = '__DEVICE_TWEAKER_RAW_LOG_ENTRY_V1__|'
    if ($Text.IndexOf($rawPrefix, [System.StringComparison]::Ordinal) -lt 0) {
        try {
            $displayText = ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay ([string]$Text)
            $displayText = ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay $displayText
            return [string]$displayText
        } catch {
            return [string]$Text
        }
    }

    $sb = [System.Text.StringBuilder]::new([Math]::Max(256, $Text.Length + 128))
    $normalized = ([string]$Text).Replace("`r`n", "`n").Replace("`r", "`n")
    $lines = $normalized -split "`n", -1
    $lastIndex = $lines.Length - 1

    for ($i = 0; $i -lt $lines.Length; $i++) {
        $line = [string]$lines[$i]
        if ($i -eq $lastIndex -and $line.Length -eq 0) { continue }

        if ($line.StartsWith($rawPrefix, [System.StringComparison]::Ordinal)) {
            $entry = ConvertFrom-DeviceTweakerRawLogEntryLine -Line $line
            if ($null -ne $entry) {
                $timestampText = ConvertTo-DeviceTweakerLogTimestampText -Timestamp $entry.Timestamp
                foreach ($prettyLine in (ConvertTo-DeviceTweakerPrettyLogLines -Text $entry.Text)) {
                    [void]$sb.AppendLine(('[{0}] {1}' -f $timestampText, $prettyLine))
                }
                continue
            }
        }

        if ($line.Length -eq 0) {
            [void]$sb.AppendLine()
            continue
        }

        try {
            $displayLine = ConvertTo-DeviceTweakerInfResourceStringsInTextForDisplay $line
            $displayLine = ConvertTo-DeviceTweakerRegistryPathsInTextForDisplay $displayLine
            [void]$sb.AppendLine([string]$displayLine)
        } catch {
            [void]$sb.AppendLine($line)
        }
    }

    return $sb.ToString()
}
'@
    ) -join "`n"

    $script:DeviceTweakerAsyncLogWorker = [PowerShell]::Create()
    [void]$script:DeviceTweakerAsyncLogWorker.AddScript({
        param($Queue, $Signal, $State, [string]$LogFormatHelpers)

        try { . ([scriptblock]::Create($LogFormatHelpers)) } catch {}
        $utf8NoBom = [System.Text.UTF8Encoding]::new($false)

        while ($true) {
            $item = $null
            while ($Queue.TryDequeue([ref]$item)) {
                try {
                    if ($null -eq $item) { continue }
                    $path = [string]$item.Path
                    $text = [string]$item.Text
                    $mode = [string]$item.Mode
                    if ([string]::IsNullOrWhiteSpace($path) -or [string]::IsNullOrEmpty($text)) { continue }

                    try { $text = ConvertTo-DeviceTweakerQueuedLogText -Text $text } catch {}
                    if ([string]::IsNullOrEmpty($text)) { continue }

                    $dir = [System.IO.Path]::GetDirectoryName($path)
                    if (-not [string]::IsNullOrWhiteSpace($dir) -and -not [System.IO.Directory]::Exists($dir)) {
                        [System.IO.Directory]::CreateDirectory($dir) | Out-Null
                    }

                    if ($mode -eq 'Overwrite') {
                        [System.IO.File]::WriteAllText($path, $text, $utf8NoBom)
                    } else {
                        [System.IO.File]::AppendAllText($path, $text, $utf8NoBom)
                    }
                } catch {
                    try { if ($State.Errors.Count -lt 64) { $State.Errors.Enqueue($path+': '+$_.Exception.Message) } } catch { }
                }
                $item = $null
            }

            if ($State.Stop -and $Queue.IsEmpty) { break }
            try { [void]$Signal.WaitOne(750) } catch { Start-Sleep -Milliseconds 750 }
        }
        try { $State.Started = $false } catch {}
    })
    [void]$script:DeviceTweakerAsyncLogWorker.AddArgument($queue)
    [void]$script:DeviceTweakerAsyncLogWorker.AddArgument($signal)
    [void]$script:DeviceTweakerAsyncLogWorker.AddArgument($state)
    [void]$script:DeviceTweakerAsyncLogWorker.AddArgument($logFormatHelpers)
    try {
        $script:DeviceTweakerAsyncLogHandle = $script:DeviceTweakerAsyncLogWorker.BeginInvoke()
        try { [void]$script:DeviceTweakerAsyncLogSignal.Set() } catch {}
    } catch {
        try { $script:DeviceTweakerAsyncLogState.Started = $false } catch {}
        try { $script:DeviceTweakerAsyncLogWorker.Dispose() } catch {}
        $script:DeviceTweakerAsyncLogWorker = $null
        $script:DeviceTweakerAsyncLogHandle = $null
    }
}

function Stop-DeviceTweakerAsyncLogWriter {
    param([switch]$Wait)

    try { $script:DeviceTweakerAsyncLogState.Stop = $true } catch {}
    try { [void]$script:DeviceTweakerAsyncLogSignal.Set() } catch {}

    if ($Wait -and $script:DeviceTweakerAsyncLogWorker -and $script:DeviceTweakerAsyncLogHandle) {
        try { $script:DeviceTweakerAsyncLogWorker.EndInvoke($script:DeviceTweakerAsyncLogHandle) } catch {}
        try { $script:DeviceTweakerAsyncLogWorker.Dispose() } catch {}
        $script:DeviceTweakerAsyncLogWorker = $null
        $script:DeviceTweakerAsyncLogHandle = $null
        try { $script:DeviceTweakerAsyncLogState.Started = $false } catch {}
    }
}

function Write-FunctionTimings {
    if (-not $script:DebugFunctions) { return }
    try { $script:ScriptLoadStopwatch.Stop() } catch { }

    $timingLines = [System.Collections.Generic.List[string]]::new()
    [void]$timingLines.Add('=== Function Timing Report ===')
    [void]$timingLines.Add(('Script total load time: {0} ms' -f $script:ScriptLoadStopwatch.Elapsed.TotalMilliseconds.ToString('F4')))
    [void]$timingLines.Add(('Generated: {0}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fffffff')))
    [void]$timingLines.Add('---')

    foreach ($entry in @($script:FunctionTimings.ToArray())) {
        try {
            if ($entry -is [string]) {
                [void]$timingLines.Add([string]$entry)
                continue
            }

            if ($null -ne $entry.TimestampTicks -and
                $null -ne $entry.Name -and
                $null -ne $entry.Milliseconds) {
                $timestamp = ([DateTime]::new([int64]$entry.TimestampTicks)).ToString('yyyy-MM-dd HH:mm:ss.fffffff')
                $name = [string]$entry.Name
                $milliseconds = ([double]$entry.Milliseconds).ToString('F4')
                [void]$timingLines.Add(('{0} | {1} | {2} ms' -f $timestamp, $name, $milliseconds))
                continue
            }

            [void]$timingLines.Add([string]$entry)
        } catch {
            try { [void]$timingLines.Add([string]$entry) } catch {}
        }
    }

    $scriptDir = if ($script:cachedScriptDir) { $script:cachedScriptDir } else { Get-Location }
    $outPath = Join-Path $scriptDir 'Functions.txt'
    $timingText = ([string]::Join([Environment]::NewLine, $timingLines.ToArray()) + [Environment]::NewLine)

    try {
        $outDir = [System.IO.Path]::GetDirectoryName([string]$outPath)
        if (-not [string]::IsNullOrWhiteSpace($outDir) -and -not [System.IO.Directory]::Exists($outDir)) {
            [void][System.IO.Directory]::CreateDirectory($outDir)
        }

        $utf8NoBom = [System.Text.UTF8Encoding]::new($false)
        [System.IO.File]::WriteAllText([string]$outPath, [string]$timingText, $utf8NoBom)
    } catch {
        try { Set-Content -LiteralPath $outPath -Value $timingText -Encoding UTF8 -Force } catch { }
    }
}


$globalInterval = 0x0
$globalHCSPARAMSOffset = 0x4
$globalRTSOFF = 0x18
$userDefinedData = @{"DEV_" = @{"INTERVAL" = 0x4E20}}
$rwePath = "C:\Program Files (x86)\RW-Everything\Rw.exe"

$script:pnpIdCache = @{}
$script:formatPathCache = @{}
$script:isPCoreCache = @{}
$script:reDeviceId = [regex]'DeviceID="([^"]+)"'
$script:cachedLogicalCount = [Environment]::ProcessorCount
$script:startupWorkingDir = try { (Get-Location -ErrorAction Stop).ProviderPath } catch { [Environment]::CurrentDirectory }
$script:cachedScriptPath = if ($PSCommandPath) { $PSCommandPath } elseif ($MyInvocation.PSCommandPath) { $MyInvocation.PSCommandPath } elseif ($MyInvocation.MyCommand.Path) { $MyInvocation.MyCommand.Path } else { $null }
$script:cachedScriptDir = if ($PSScriptRoot) { $PSScriptRoot } elseif ($script:cachedScriptPath) { Split-Path -Parent $script:cachedScriptPath } else { $script:startupWorkingDir }
$script:DeviceTweakerBackupFileName = "exovance_v2_device_settings_backup.json"
$script:uiShuttingDown = $false
$script:polledRunspaceTimers = [System.Collections.ArrayList]::new()

$script:deviceTweakerConsoleCtrlCGuardInstalled = $false
$script:deviceTweakerPreviousTreatControlCAsInput = $null
$script:deviceTweakerCtrlCHandler = $null
$script:deviceTweakerBusy = $false
$script:deviceTweakerBusyOwner = $null
$script:deviceTweakerActionButtons = @()
$script:deviceTweakerActionButtonOriginalText = @{}
$script:deviceTweakerStableButtonTextHandlers = @{}

function Enable-DeviceTweakerConsoleCtrlCGuard {
    if ($script:CLIMode) { return }
    if ($script:deviceTweakerConsoleCtrlCGuardInstalled) { return }

    try {
        try {
            $script:deviceTweakerPreviousTreatControlCAsInput = [Console]::TreatControlCAsInput
            [Console]::TreatControlCAsInput = $true
        } catch { }

        try {
            $script:deviceTweakerCtrlCHandler = [System.ConsoleCancelEventHandler]{
                param($sender, $eventArgs)
                try { $eventArgs.Cancel = $true } catch { }
            }
            [Console]::add_CancelKeyPress($script:deviceTweakerCtrlCHandler)
        } catch { }

        $script:deviceTweakerConsoleCtrlCGuardInstalled = $true
    } catch { }
}

function Disable-DeviceTweakerConsoleCtrlCGuard {
    try {
        if ($script:deviceTweakerCtrlCHandler) {
            try { [Console]::remove_CancelKeyPress($script:deviceTweakerCtrlCHandler) } catch { }
            $script:deviceTweakerCtrlCHandler = $null
        }

        if ($null -ne $script:deviceTweakerPreviousTreatControlCAsInput) {
            try { [Console]::TreatControlCAsInput = [bool]$script:deviceTweakerPreviousTreatControlCAsInput } catch { }
        }
    } catch { }
    finally {
        $script:deviceTweakerConsoleCtrlCGuardInstalled = $false
    }
}

function Get-DeviceTweakerFocusedControl {
    param([object]$Root)

    if ($null -eq $Root) { return $null }

    try {
        if ($Root.Focused) { return $Root }

        foreach ($child in $Root.Controls) {
            if ($child.Focused) { return $child }
            if ($child.ContainsFocus) {
                $found = Get-DeviceTweakerFocusedControl -Root $child
                if ($null -ne $found) { return $found }
            }
        }
    } catch { }

    return $null
}

function Test-DeviceTweakerEditableControl {
    param([object]$Control)

    if ($null -eq $Control) { return $false }

    try {
        if ($Control -is [System.Windows.Forms.TextBoxBase]) {
            return $true
        }

        if ($Control -is [System.Windows.Forms.ComboBox]) {
            return $true
        }
    } catch { }

    return $false
}

function Invoke-DeviceTweakerCtrlCTrap {
    param(
        [object]$Root,
        [object]$KeyEventArgs
    )

    if ($null -eq $KeyEventArgs) { return }

    try {
        if ($KeyEventArgs.Control -and $KeyEventArgs.KeyCode -eq [System.Windows.Forms.Keys]::C) {
            $focused = Get-DeviceTweakerFocusedControl -Root $Root

            if (-not (Test-DeviceTweakerEditableControl -Control $focused)) {
                $KeyEventArgs.SuppressKeyPress = $true
                $KeyEventArgs.Handled = $true
            }
        }
    } catch { }
}

function Set-DeviceTweakerDoubleBuffered {
    param([object]$Control)

    if ($null -eq $Control) { return }

    try {
        [ScrollHelper]::EnableDoubleBuffer([System.Windows.Forms.Control]$Control)
        return
    } catch { }

    try {
        if ($null -eq $script:DoubleBufferedProperty) {
            $script:DoubleBufferedProperty = [System.Windows.Forms.Control].GetProperty(
                'DoubleBuffered',
                [System.Reflection.BindingFlags]::Instance -bor [System.Reflection.BindingFlags]::NonPublic
            )
        }
        if ($null -ne $script:DoubleBufferedProperty) {
            $script:DoubleBufferedProperty.SetValue($Control, $true, $null)
        }
    } catch { }
}

function Register-DeviceTweakerStableButtonText {
    param([object]$Button)

    if ($null -eq $Button) { return }
    if ($Button -is [ExovanceActionButton]) { return }
    try {
        if (-not ($Button -is [System.Windows.Forms.Button])) { return }

        $key = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($Button).ToString()
        if ($script:deviceTweakerStableButtonTextHandlers.ContainsKey($key)) { return }

        $handler = [System.Windows.Forms.PaintEventHandler]{
            param($sender, $e)
            try {
                if ($null -eq $sender -or $null -eq $e) { return }
                if ($sender.Enabled) { return }

                $text = [string]$sender.Text
                if ([string]::IsNullOrEmpty($text)) { return }

                $fg = $sender.ForeColor
                if ($null -eq $fg -or $fg.IsEmpty) {
                    $fg = [System.Drawing.Color]::White
                }

                $rect = [System.Drawing.Rectangle]::new(
                    1,
                    1,
                    [Math]::Max(1, $sender.ClientSize.Width - 2),
                    [Math]::Max(1, $sender.ClientSize.Height - 2)
                )
                $flags = ([System.Windows.Forms.TextFormatFlags]::HorizontalCenter -bor [System.Windows.Forms.TextFormatFlags]::VerticalCenter -bor [System.Windows.Forms.TextFormatFlags]::SingleLine -bor [System.Windows.Forms.TextFormatFlags]::EndEllipsis -bor [System.Windows.Forms.TextFormatFlags]::NoPadding)

                [System.Windows.Forms.TextRenderer]::DrawText($e.Graphics, $text, $sender.Font, $rect, $fg, $flags)
            } catch { }
        }

        $Button.UseVisualStyleBackColor = $false
        try { $Button.FlatAppearance.MouseOverBackColor = $Button.BackColor } catch { }
        try { $Button.FlatAppearance.MouseDownBackColor = [System.Drawing.Color]::FromArgb(45,45,45) } catch { }
        $Button.Add_Paint($handler)
        $script:deviceTweakerStableButtonTextHandlers[$key] = $handler
    } catch { }
}

function Enter-DeviceTweakerUiAction {
    param(
        [string]$Name = 'Action',
        [object]$Button = $null
    )

    if ($script:deviceTweakerBusy) {
        try { [System.Media.SystemSounds]::Beep.Play() } catch { }
        try {
            Write-Host "[UI] Ignored '$Name' click because '$($script:deviceTweakerBusyOwner)' is still running." -ForegroundColor DarkYellow
        } catch { }
        return $false
    }

    Reset-ExovanceWriteFailures
    $script:deviceTweakerBusy = $true
    $script:deviceTweakerBusyOwner = $Name
    Start-ExovanceLoggedAction -Name $Name
    if($script:ExovanceLogSession){try{Update-ExovanceDeviceLogSnapshot -Devices $deviceList -LogicalCount $script:cachedLogicalCount -PhysicalCount (Get-PhysicalCoreCount) -Phase Before}catch{Write-ExovanceLogEvent -Level Warning -Code SnapshotUnavailable -Stage Snapshot -Message ('Снимок до действия недоступен: '+$_.Exception.Message)}}
    $script:ExovanceEditorsWereEnabled = $null
    if ($null -ne $script:scrollInnerPanel) {
        $script:ExovanceEditorsWereEnabled = $script:scrollInnerPanel.Enabled
        $script:scrollInnerPanel.Enabled = $false
    }
    Set-ExovanceUiFeedback -State Working -Text ("Working - " + $Name)

    try {
        $buttons = @()
        if ($script:deviceTweakerActionButtons) { $buttons = @($script:deviceTweakerActionButtons) }

        foreach ($btn in $buttons) {
            if ($null -eq $btn) { continue }
            try {
                if ($btn.IsDisposed) { continue }

                $key = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($btn).ToString()
                if (-not $script:deviceTweakerActionButtonOriginalText.ContainsKey($key)) {
                    $script:deviceTweakerActionButtonOriginalText[$key] = [string]$btn.Text
                }

                if ($null -ne $Button -and [object]::ReferenceEquals($btn, $Button)) {
                    Register-DeviceTweakerStableButtonText -Button $btn
                    $btn.Invalidate()
                    $btn.Update()
                    continue
                }

                Register-DeviceTweakerStableButtonText -Button $btn
                $btn.Enabled = $false
                $btn.Invalidate()
                $btn.Update()
            } catch { }
        }

        if ($null -ne $Button) {
            try {
                if ($Button -is [ExovanceActionButton]) { $Button.Busy = $true; $Button.Enabled = $false }
                if (-not $Button.IsDisposed) {
                    Register-DeviceTweakerStableButtonText -Button $Button
                    $Button.Invalidate()
                    $Button.Update()
                }
            } catch { }
        }

        if ($form -and -not $form.IsDisposed) {
            try { $form.UseWaitCursor = $true } catch { }
            try { $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor } catch { }
            try { $form.Update() } catch { }
        }
    } catch { }

    return $true
}

function Exit-DeviceTweakerUiAction {
    try {
        $buttons = @()
        if ($script:deviceTweakerActionButtons) { $buttons = @($script:deviceTweakerActionButtons) }

        foreach ($btn in $buttons) {
            if ($null -eq $btn) { continue }
            try {
                if ($btn.IsDisposed) { continue }

                $key = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($btn).ToString()
                if ($script:deviceTweakerActionButtonOriginalText.ContainsKey($key)) {
                    $btn.Text = [string]$script:deviceTweakerActionButtonOriginalText[$key]
                }

                if ($btn -is [ExovanceActionButton]) { $btn.Busy = $false }
                $btn.Enabled = $true
                $btn.Invalidate()
            } catch { }
        }

        if ($form -and -not $form.IsDisposed) {
            try { $form.UseWaitCursor = $false } catch { }
            try { $form.Cursor = [System.Windows.Forms.Cursors]::Default } catch { }
            try { $form.Invalidate($true) } catch { }
            try { $form.Update() } catch { }
        }
    } catch { }
    finally {
        if ($null -ne $script:scrollInnerPanel -and $null -ne $script:ExovanceEditorsWereEnabled) { $script:scrollInnerPanel.Enabled = [bool]$script:ExovanceEditorsWereEnabled }
        if ($script:ExovanceUiState -eq 'Working') { Set-ExovanceUiFeedback -State Ready -Text 'Ready - no new changes applied' }
        if ($script:ExovanceLogSession -and $script:ExovanceLogSession.ActiveAction) {
            try { Update-ExovanceDeviceLogSnapshot -Devices $deviceList -LogicalCount $script:cachedLogicalCount -PhysicalCount (Get-PhysicalCoreCount) -Phase After } catch { Write-ExovanceLogEvent -Level Warning -Code SnapshotUnavailable -Stage Snapshot -Message ('Снимок после действия недоступен: '+$_.Exception.Message) }
            Complete-ExovanceLoggedAction -State $script:ExovanceUiState -Text $script:ExovanceUiMessage
        }
        $script:deviceTweakerBusy = $false
        $script:deviceTweakerBusyOwner = $null
    }
}


function Add-DeviceTweakerDirectoryCandidate {
    param(
        [System.Collections.Generic.List[string]]$Directories,
        [object]$Path
    )

    if ($null -eq $Directories -or $null -eq $Path) { return }

    $rawPath = [string]$Path
    if ([string]::IsNullOrWhiteSpace($rawPath)) { return }

    try {
        $rawPath = $rawPath -replace '^Microsoft\.PowerShell\.Core\\FileSystem::', ''

        if (-not [System.IO.Directory]::Exists($rawPath)) {
            $extension = [System.IO.Path]::GetExtension($rawPath)
            if (-not [string]::IsNullOrWhiteSpace($extension)) {
                $parent = [System.IO.Path]::GetDirectoryName($rawPath)
                if (-not [string]::IsNullOrWhiteSpace($parent)) { $rawPath = $parent }
            }
        }

        $fullPath = [System.IO.Path]::GetFullPath($rawPath)
        if (-not [System.IO.Directory]::Exists($fullPath)) { return }

        foreach ($existing in $Directories) {
            if ([string]::Equals($existing, $fullPath, [System.StringComparison]::OrdinalIgnoreCase)) { return }
        }

        [void]$Directories.Add($fullPath)
    } catch { }
}

function Get-DeviceTweakerDirectoryCandidates {
    # Keep v2 backups and logs separate from the original and arbitrary CWD files.
    return @($script:cachedScriptDir)
}

function Get-DeviceTweakerPciIdsPathFast {
    $dirs = [System.Collections.Generic.List[string]]::new()

    $addDir = {
        param([AllowNull()][object]$Path)
        if ($null -eq $Path) { return }
        try {
            $raw = ([string]$Path).Trim()
            if ([string]::IsNullOrWhiteSpace($raw)) { return }
            $raw = $raw -replace '^Microsoft\.PowerShell\.Core\\FileSystem::', ''

            if (-not [System.IO.Directory]::Exists($raw)) {
                $ext = [System.IO.Path]::GetExtension($raw)
                if (-not [string]::IsNullOrWhiteSpace($ext)) {
                    $parent = [System.IO.Path]::GetDirectoryName($raw)
                    if (-not [string]::IsNullOrWhiteSpace($parent)) { $raw = $parent }
                }
            }

            $full = [System.IO.Path]::GetFullPath($raw)
            if (-not [System.IO.Directory]::Exists($full)) { return }
            foreach ($existing in $dirs) {
                if ([string]::Equals($existing, $full, [System.StringComparison]::OrdinalIgnoreCase)) { return }
            }
            [void]$dirs.Add($full)
        } catch { }
    }

    & $addDir $script:cachedScriptDir
    & $addDir $PSScriptRoot
    try { if ($script:cachedScriptPath) { & $addDir ([System.IO.Path]::GetDirectoryName([string]$script:cachedScriptPath)) } } catch { }
    try { if ($PSCommandPath) { & $addDir ([System.IO.Path]::GetDirectoryName([string]$PSCommandPath)) } } catch { }
    try { if ($MyInvocation.PSCommandPath) { & $addDir ([System.IO.Path]::GetDirectoryName([string]$MyInvocation.PSCommandPath)) } } catch { }
    try { if ($MyInvocation.MyCommand.Path) { & $addDir ([System.IO.Path]::GetDirectoryName([string]$MyInvocation.MyCommand.Path)) } } catch { }
    & $addDir $script:startupWorkingDir
    try { $loc = Get-Location -ErrorAction Stop; if ($loc.ProviderPath) { & $addDir $loc.ProviderPath } else { & $addDir $loc.Path } } catch { }
    & $addDir ([Environment]::CurrentDirectory)

    $fallback = $null
    foreach ($dir in $dirs) {
        try {
            $candidate = [System.IO.Path]::Combine([string]$dir, 'pci.ids')
            if ($null -eq $fallback) { $fallback = $candidate }
            if ([System.IO.File]::Exists($candidate)) { return $candidate }
        } catch { }
    }

    if (-not [string]::IsNullOrWhiteSpace([string]$fallback)) { return $fallback }
    try { return [System.IO.Path]::Combine([string](Get-Location), 'pci.ids') } catch { return 'pci.ids' }
}

function Test-DeviceTweakerDirectoryWritable {
    param([string]$Directory)

    if ([string]::IsNullOrWhiteSpace($Directory)) { return $false }
    if (-not [System.IO.Directory]::Exists($Directory)) { return $false }

    try {
        $testFile = [System.IO.Path]::Combine($Directory, ('.device_tweaker_write_test_' + [System.Guid]::NewGuid().ToString('N') + '.tmp'))
        [System.IO.File]::WriteAllText($testFile, 'write-test', [System.Text.Encoding]::UTF8)
        [System.IO.File]::Delete($testFile)
        return $true
    } catch {
        return $false
    }
}

function Get-DeviceTweakerBackupSearchReport {
    $lines = [System.Collections.Generic.List[string]]::new()
    [void]$lines.Add("Expected backup file:")
    [void]$lines.Add("  $script:DeviceTweakerBackupFileName")
    [void]$lines.Add("")
    [void]$lines.Add("Searched locations:")

    $index = 1
    foreach ($dir in (Get-DeviceTweakerDirectoryCandidates)) {
        try {
            $candidate = [System.IO.Path]::Combine($dir, $script:DeviceTweakerBackupFileName)
            $status = if ([System.IO.File]::Exists($candidate)) { 'Found' } else { 'Missing' }
            [void]$lines.Add(("  {0}. {1}:" -f $index, $status))
            [void]$lines.Add(("     {0}" -f $candidate))
            $index++
        } catch { }
    }

    return ($lines -join [Environment]::NewLine)
}

function Find-DeviceTweakerBackupFile {
    foreach ($dir in (Get-DeviceTweakerDirectoryCandidates)) {
        try {
            $exactCandidate = [System.IO.Path]::Combine($dir, $script:DeviceTweakerBackupFileName)
            if ([System.IO.File]::Exists($exactCandidate)) { return $exactCandidate }

            foreach ($jsonFile in [System.IO.Directory]::EnumerateFiles($dir, '*.json')) {
                if ([string]::Equals([System.IO.Path]::GetFileName($jsonFile), $script:DeviceTweakerBackupFileName, [System.StringComparison]::OrdinalIgnoreCase)) {
                    return $jsonFile
                }
            }
        } catch { }
    }

    return $null
}

function Get-DeviceTweakerBackupPath {
    param(
        [switch]$ForRead,
        [switch]$ForWrite
    )

    if ($ForRead) {
        $foundBackup = Find-DeviceTweakerBackupFile
        if ($foundBackup) { return $foundBackup }
    }

    $dirs = @(Get-DeviceTweakerDirectoryCandidates)

    if ($ForWrite) {
        foreach ($dir in $dirs) {
            if (Test-DeviceTweakerDirectoryWritable -Directory $dir) {
                return [System.IO.Path]::Combine($dir, $script:DeviceTweakerBackupFileName)
            }
        }

        $documentsPath = [Environment]::GetFolderPath([System.Environment+SpecialFolder]::MyDocuments)
        if (-not [string]::IsNullOrWhiteSpace($documentsPath) -and (Test-DeviceTweakerDirectoryWritable -Directory $documentsPath)) {
            return [System.IO.Path]::Combine($documentsPath, $script:DeviceTweakerBackupFileName)
        }

        return [System.IO.Path]::Combine([System.IO.Path]::GetTempPath(), $script:DeviceTweakerBackupFileName)
    }

    if ($dirs.Count -gt 0) {
        return [System.IO.Path]::Combine($dirs[0], $script:DeviceTweakerBackupFileName)
    }

    return [System.IO.Path]::Combine([Environment]::CurrentDirectory, $script:DeviceTweakerBackupFileName)
}

function Select-DeviceTweakerBackupFile {
    $dialog = $null
    try {
        $dialog = [System.Windows.Forms.OpenFileDialog]::new()
        $dialog.Title = "Select device settings backup JSON"
        $dialog.Filter = "Device settings backup (device_settings_backup.json)|device_settings_backup.json|JSON files (*.json)|*.json|All files (*.*)|*.*"
        $dialog.FileName = $script:DeviceTweakerBackupFileName
        $dialog.CheckFileExists = $true
        $dialog.CheckPathExists = $true

        $dirs = @(Get-DeviceTweakerDirectoryCandidates)
        if ($dirs.Count -gt 0 -and [System.IO.Directory]::Exists($dirs[0])) {
            $dialog.InitialDirectory = $dirs[0]
        }

        if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
            return $dialog.FileName
        }
    } catch { }
    finally {
        if ($dialog -ne $null) { $dialog.Dispose() }
    }

    return $null
}

function Test-DeviceTweakerBackupJson {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $false }
    if (-not [System.IO.File]::Exists($Path)) { return $false }

    try {
        $jsonContent = [System.IO.File]::ReadAllText($Path, [System.Text.Encoding]::UTF8)
        if ([string]::IsNullOrWhiteSpace($jsonContent)) { return $false }
        $backupData = ConvertFrom-DeviceTweakerBackupJson -JsonContent $jsonContent
        if ($null -eq $backupData) { return $false }
        return ($null -ne $backupData.PSObject.Properties['Devices'])
    } catch {
        return $false
    }
}


function ConvertFrom-DeviceTweakerJsonDisplayEscapes {
    param([AllowNull()][string]$Text)

    if ($null -eq $Text) { return $null }
    $clean = [string]$Text

    $clean = [regex]::Replace($clean, '(?i)\\u0026', '&')
    $clean = [regex]::Replace($clean, '(?i)\\u003c', '<')
    $clean = [regex]::Replace($clean, '(?i)\\u003e', '>')
    $clean = [regex]::Replace($clean, '(?i)\\u0027', "'")

    return $clean
}

function Normalize-DeviceTweakerPathSeparators {
    param([AllowNull()][object]$Path)

    if ($null -eq $Path) { return $null }
    $text = ConvertFrom-DeviceTweakerJsonDisplayEscapes ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($text)) { return $text }

    $text = $text.Trim().Trim('"')
    $text = $text.Replace('/', '\')
    $text = [regex]::Replace($text, '\\{2,}', '\')
    return $text
}

function ConvertTo-DeviceTweakerJsonStringLiteral {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return 'null' }
    $text = [string]$Value

    try {
        $convertToJsonCommand = Get-Command ConvertTo-Json -ErrorAction Stop
        if ($convertToJsonCommand.Parameters.ContainsKey('EscapeHandling')) {
            return ($text | ConvertTo-Json -Compress -EscapeHandling Default)
        }
        return ($text | ConvertTo-Json -Compress)
    } catch {
        $escaped = $text.Replace('\', '\\').Replace('"', '\"').Replace("`r", '\r').Replace("`n", '\n').Replace("`t", '\t')
        return '"' + $escaped + '"'
    }
}

function ConvertTo-DeviceTweakerBackupReadableJson {
    param([AllowNull()][string]$Json)

    if ($null -eq $Json) { return $null }

    $pathPropertyPattern = '("(?:RegistryPath|ConfigPath|ClassPath)"\s*:\s*)"(?<value>(?:\\.|[^"\\])*)"'
    return [regex]::Replace([string]$Json, $pathPropertyPattern, {
        param([System.Text.RegularExpressions.Match]$match)

        $prefix = $match.Groups[1].Value
        $encodedValue = $match.Groups['value'].Value
        $decodedValue = $encodedValue
        try {
            $decodedValue = ('"' + $encodedValue + '"') | ConvertFrom-Json -ErrorAction Stop
        } catch { }

        $displayValue = Format-RegistryPathForDisplay (Normalize-DeviceTweakerPathSeparators $decodedValue)
        $displayValue = Normalize-DeviceTweakerPathSeparators $displayValue
        $displayValue = ([string]$displayValue).Replace('"', '\"').Replace("`r", '\r').Replace("`n", '\n').Replace("`t", '\t')
        return $prefix + '"' + $displayValue + '"'
    })
}

function Repair-DeviceTweakerBackupJsonPathEscapes {
    param([AllowNull()][string]$JsonContent)

    if ($null -eq $JsonContent) { return $null }

    $pathPropertyPattern = '("(?:RegistryPath|ConfigPath|ClassPath)"\s*:\s*)"(?<value>[^"\r\n]*)"'
    return [regex]::Replace([string]$JsonContent, $pathPropertyPattern, {
        param([System.Text.RegularExpressions.Match]$match)

        $prefix = $match.Groups[1].Value
        $pathText = Normalize-DeviceTweakerPathSeparators $match.Groups['value'].Value
        return $prefix + (ConvertTo-DeviceTweakerJsonStringLiteral $pathText)
    })
}

function ConvertFrom-DeviceTweakerBackupJson {
    param([AllowNull()][string]$JsonContent)

    if ([string]::IsNullOrWhiteSpace($JsonContent)) { return $null }

    try {
        return ($JsonContent | ConvertFrom-Json -ErrorAction Stop)
    } catch {
        $repairJson = Repair-DeviceTweakerBackupJsonPathEscapes -JsonContent $JsonContent
        return ($repairJson | ConvertFrom-Json -ErrorAction Stop)
    }
}

function ConvertTo-DeviceTweakerBackupJson {
    param(
        [Parameter(Mandatory=$true)][object]$InputObject,
        [int]$Depth = 10
    )

    $json = $null
    try {
        $convertToJsonCommand = Get-Command ConvertTo-Json -ErrorAction Stop
        if ($convertToJsonCommand.Parameters.ContainsKey('EscapeHandling')) {
            $json = $InputObject | ConvertTo-Json -Depth $Depth -EscapeHandling Default
        } else {
            $json = $InputObject | ConvertTo-Json -Depth $Depth
        }
    } catch {
        $json = $InputObject | ConvertTo-Json -Depth $Depth
    }

    $json = ConvertFrom-DeviceTweakerJsonDisplayEscapes $json
    $json = ConvertTo-DeviceTweakerBackupReadableJson $json
    return $json
}

function Get-DeviceTweakerBackupValue {
    param(
        [AllowNull()][object]$Object,
        [Parameter(Mandatory=$true)][string[]]$Names,
        [AllowNull()][object]$Default = $null
    )

    if ($null -eq $Object -or $null -eq $Object.PSObject) { return $Default }
    foreach ($name in $Names) {
        if ($null -ne $Object.PSObject.Properties[$name]) {
            return $Object.PSObject.Properties[$name].Value
        }
    }
    return $Default
}

function Test-DeviceTweakerNullLike {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return $true }
    if ($Value -is [string]) {
        $text = ([string]$Value).Trim()
        if ($text.Equals('null', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}

function Format-DeviceTweakerNullableValue {
    param(
        [AllowNull()][object]$Value,
        [string]$NullText = 'null'
    )

    if (Test-DeviceTweakerNullLike $Value) { return $NullText }
    return [string]$Value
}

function Test-DeviceTweakerBackupHasProperty {
    param(
        [AllowNull()][object]$Object,
        [Parameter(Mandatory=$true)][string[]]$Names
    )

    if ($null -eq $Object -or $null -eq $Object.PSObject) { return $false }
    foreach ($name in $Names) {
        if ($null -ne $Object.PSObject.Properties[$name]) { return $true }
    }
    return $false
}

function Get-DeviceTweakerRegistryValueState {
    param(
        [AllowNull()][string]$RegistryPath,
        [AllowNull()][string]$SubkeySuffix,
        [Parameter(Mandatory=$true)][string]$ValueName
    )

    $state = [PSCustomObject]@{
        SubkeyExists = $false
        Present      = $false
        Value        = $null
    }

    try {
        $relativePath = Get-RelativeRegistryPath $RegistryPath
        if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { return $state }

        $targetSubkey = if ([string]::IsNullOrWhiteSpace([string]$SubkeySuffix)) {
            $relativePath
        } else {
            "$relativePath\$SubkeySuffix"
        }

        $regKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($targetSubkey, $false)
        if ($regKey -ne $null) {
            $state.SubkeyExists = $true
            $value = $regKey.GetValue($ValueName, $null)
            if ($null -ne $value) {
                $state.Present = $true
                $state.Value = $value
            }
            $regKey.Close()
        }
    } catch { }

    return $state
}

function Set-DeviceTweakerRegistryDWordValue {
    param(
        [AllowNull()][string]$RegistryPath,
        [AllowNull()][string]$SubkeySuffix,
        [Parameter(Mandatory=$true)][string]$ValueName,
        [Parameter(Mandatory=$true)][object]$Value
    )

    try {
        $relativePath = Get-RelativeRegistryPath $RegistryPath
        if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { Add-ExovanceWriteFailure 'Set-DeviceTweakerRegistryDWordValue: registry operation failed.'; return $false }
        $targetSubkey = if ([string]::IsNullOrWhiteSpace([string]$SubkeySuffix)) { $relativePath } else { "$relativePath\$SubkeySuffix" }
        $regKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($targetSubkey, [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
        if ($regKey -ne $null) {
            $regKey.SetValue($ValueName, [int]$Value, [Microsoft.Win32.RegistryValueKind]::DWord)
            $regKey.Close()
            return $true
        }
    } catch { }
    Add-ExovanceWriteFailure 'Set-DeviceTweakerRegistryDWordValue: registry operation failed.'; return $false
}

function Remove-DeviceTweakerRegistryValue {
    param(
        [AllowNull()][string]$RegistryPath,
        [AllowNull()][string]$SubkeySuffix,
        [Parameter(Mandatory=$true)][string]$ValueName
    )

    try {
        $relativePath = Get-RelativeRegistryPath $RegistryPath
        if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { Add-ExovanceWriteFailure 'Remove-DeviceTweakerRegistryValue: registry operation failed.'; return $false }
        $targetSubkey = if ([string]::IsNullOrWhiteSpace([string]$SubkeySuffix)) { $relativePath } else { "$relativePath\$SubkeySuffix" }
        $regKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($targetSubkey, $true)
        if ($regKey -ne $null) {
            if ($regKey.GetValue($ValueName, $null) -ne $null) {
                $regKey.DeleteValue($ValueName, $false)
            }
            $regKey.Close()
        }
        return $true
    } catch { }
    Add-ExovanceWriteFailure 'Remove-DeviceTweakerRegistryValue: registry operation failed.'; return $false
}

function Normalize-DeviceTweakerBackupRegistryPath {
    param([AllowNull()][object]$Path)

    if ($null -eq $Path) { return $null }
    $text = ConvertFrom-DeviceTweakerJsonDisplayEscapes ([string]$Path)
    if ([string]::IsNullOrWhiteSpace($text) -or $text -eq '(N/A)') { return $text }
    return (Format-RegistryPathForDisplay $text)
}

function Get-DeviceTweakerBackupIrqAffinityMask {
    param([AllowNull()][object]$BackupDevice)

    $mask = Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('IRQ affinity mask','IrqAffinityMask','Affinity') -Default $null
    if (-not (Test-DeviceTweakerNullLike $mask) -and -not [string]::IsNullOrWhiteSpace([string]$mask)) {
        return [string]$mask
    }

    $legacyAso = Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('IrqAssignmentSetOverride','IRQ assignment set override') -Default $null
    if (-not (Test-DeviceTweakerNullLike $legacyAso) -and -not [string]::IsNullOrWhiteSpace([string]$legacyAso)) {
        try {
            $bytes = [Convert]::FromBase64String([string]$legacyAso)
            [uint64]$maskInt = [uint64]0
            $max = [Math]::Min($bytes.Length, 8)
            for ($i = 0; $i -lt $max; $i++) {
                $maskInt = $maskInt -bor (([uint64]($bytes[$i])) -shl (8 * $i))
            }
            return ('0x' + $maskInt.ToString('X'))
        } catch { }
    }

    return $null
}

function Get-DeviceTweakerBackupIrqDevicePolicy {
    param([AllowNull()][object]$BackupDevice)
    $value = Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('IRQ device policy','IRQDevicePolicy','IrqDevicePolicy','Policy') -Default $null
    if (Test-DeviceTweakerNullLike $value) { return $null }
    return $value
}

function Get-DeviceTweakerBackupIrqPriority {
    param([AllowNull()][object]$BackupDevice)
    $value = Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('IRQ priority','IRQPriority','IrqPriority','Priority','DevicePriority') -Default $null
    if (Test-DeviceTweakerNullLike $value) { return $null }
    return $value
}

function Get-DeviceTweakerBackupPathDisplayValues {
    param([AllowNull()][object]$BackupDevice)

    $values = @()
    foreach ($name in @('RegistryPath','ClassPath','ConfigPath')) {
        $rawValue = Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @($name) -Default $null
        if ($null -eq $rawValue -or [string]::IsNullOrWhiteSpace([string]$rawValue)) { continue }
        foreach ($formattedValue in (Get-DeviceTweakerRegistryPathComparisonValues $rawValue)) {
            if ([string]::IsNullOrWhiteSpace([string]$formattedValue) -or $formattedValue -eq '(N/A)') { continue }
            if ($values -notcontains $formattedValue) { $values += $formattedValue }
        }
    }
    return $values
}

function Get-DeviceTweakerDevicePathDisplayValues {
    param([AllowNull()][object]$Device)

    $values = @()
    if ($null -eq $Device) { return $values }

    if ($Device.RegistryPath) {
        foreach ($registryDisplay in (Get-DeviceTweakerRegistryPathComparisonValues $Device.RegistryPath)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$registryDisplay) -and $registryDisplay -ne '(N/A)' -and $values -notcontains $registryDisplay) { $values += $registryDisplay }
        }
    }

    if ($Device.ConfigPath) {
        foreach ($configDisplay in (Get-DeviceTweakerRegistryPathComparisonValues $Device.ConfigPath)) {
            if (-not [string]::IsNullOrWhiteSpace([string]$configDisplay) -and $configDisplay -ne '(N/A)' -and $values -notcontains $configDisplay) { $values += $configDisplay }
        }
    }

    return $values
}

function Convert-DeviceTweakerAffinityMaskToUInt64 {
    param([AllowNull()][object]$AffinityMask)

    if ($null -eq $AffinityMask) { return [uint64]0 }
    $maskText = ([string]$AffinityMask).Trim()
    if ([string]::IsNullOrWhiteSpace($maskText)) { return [uint64]0 }
    if ($maskText.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
        $maskText = $maskText.Substring(2)
    }
    if ([string]::IsNullOrWhiteSpace($maskText)) { return [uint64]0 }
    return [Convert]::ToUInt64($maskText, 16)
}

function Convert-DeviceTweakerRegistryAffinityValueToHex {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return $null }

    try {
        [uint64]$maskInt = [uint64]0

        if ($Value -is [byte[]]) {
            $bytes = [byte[]]$Value
            $maxBytes = [Math]::Min($bytes.Length, 8)
            for ($i = 0; $i -lt $maxBytes; $i++) {
                $maskInt = $maskInt -bor (([uint64]($bytes[$i])) -shl (8 * $i))
            }
        } elseif ($Value -is [array]) {
            $bytes = [byte[]]$Value
            $maxBytes = [Math]::Min($bytes.Length, 8)
            for ($i = 0; $i -lt $maxBytes; $i++) {
                $maskInt = $maskInt -bor (([uint64]($bytes[$i])) -shl (8 * $i))
            }
        } else {
            $valueText = ([string]$Value).Trim()
            if ([string]::IsNullOrWhiteSpace($valueText)) { return $null }
            if ($valueText.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
                $maskInt = [Convert]::ToUInt64($valueText.Substring(2), 16)
            } else {
                $maskInt = [Convert]::ToUInt64($Value)
            }
        }

        return ('0x' + $maskInt.ToString('X'))
    } catch {
        return $null
    }
}

function Restore-DeviceTweakerIrqAffinityFromBackup {
    param(
        [Parameter(Mandatory=$true)][string]$RegistryPath,
        [AllowNull()][object]$BackupDevice,
        [string]$LogLabel = 'IRQ Affinity',
        [int]$PadWidth = 18
    )

    $affinitySubkey = 'Device Parameters\Interrupt Management\Affinity Policy'
    $hasMaskEntry = Test-DeviceTweakerBackupHasProperty -Object $BackupDevice -Names @('IRQ affinity mask','IrqAffinityMask','Affinity','IrqAssignmentSetOverride','IRQ assignment set override')
    $hasPolicyEntry = Test-DeviceTweakerBackupHasProperty -Object $BackupDevice -Names @('IRQ device policy','IRQDevicePolicy','IrqDevicePolicy','Policy')

    $backupMask = Get-DeviceTweakerBackupIrqAffinityMask $BackupDevice
    $backupPolicy = Get-DeviceTweakerBackupIrqDevicePolicy $BackupDevice
    $policyText = $null
    if ($null -ne $backupPolicy) {
        try { $policyText = [int]$backupPolicy } catch { $policyText = $null }
    }

    if ($hasMaskEntry) {
        if ($null -ne $backupMask -and -not [string]::IsNullOrWhiteSpace([string]$backupMask)) {
            try { $maskInt = Convert-DeviceTweakerAffinityMaskToUInt64 $backupMask } catch { $maskInt = [uint64]0 }
            if ($maskInt -ne 0) {
                if (Set-DeviceAffinity $RegistryPath $backupMask) {
                    Write-Host ("      {0} : {1}" -f $LogLabel.PadRight($PadWidth), "Restored ($backupMask)") -ForegroundColor Green
                } else {
                    Write-Host ("      {0} : {1}" -f $LogLabel.PadRight($PadWidth), "FAILED - could not write $backupMask") -ForegroundColor Red
                }
            } else {
                Remove-DeviceTweakerRegistryValue -RegistryPath $RegistryPath -SubkeySuffix $affinitySubkey -ValueName 'AssignmentSetOverride' | Out-Null
                Write-Host ("      {0} : {1}" -f $LogLabel.PadRight($PadWidth), "Deleted/absent (backup mask was 0x0)") -ForegroundColor Yellow
            }
        } else {
            Remove-DeviceTweakerRegistryValue -RegistryPath $RegistryPath -SubkeySuffix $affinitySubkey -ValueName 'AssignmentSetOverride' | Out-Null
            Write-Host ("      {0} : {1}" -f $LogLabel.PadRight($PadWidth), "null - deleted/absent") -ForegroundColor Yellow
        }
    } else {
        Write-Host ("      {0} : {1}" -f $LogLabel.PadRight($PadWidth), "not in backup - unchanged") -ForegroundColor DarkGray
    }

    if ($hasPolicyEntry) {
        if ($null -ne $policyText) {
            if (Set-DevicePolicy $RegistryPath $policyText) {
                Write-Host ("      {0} : {1}" -f 'IRQ device policy'.PadRight($PadWidth), "$policyText") -ForegroundColor Green
            } else {
                Write-Host ("      {0} : {1}" -f 'IRQ device policy'.PadRight($PadWidth), "FAILED - could not write $policyText") -ForegroundColor Red
            }
        } else {
            Remove-DeviceTweakerRegistryValue -RegistryPath $RegistryPath -SubkeySuffix $affinitySubkey -ValueName 'DevicePolicy' | Out-Null
            Write-Host ("      {0} : {1}" -f 'IRQ device policy'.PadRight($PadWidth), "null - deleted/absent") -ForegroundColor Yellow
        }
    }
}

$script:cachedWin32Processor = $null
function Get-CachedProcessor {
    if ($null -eq $script:cachedWin32Processor) {
        if ($script:processorAsyncResult -and $script:processorRunspace) {
            try {
                $results = @($script:processorRunspace.EndInvoke($script:processorAsyncResult))
                $script:cachedWin32Processor = if ($results.Count -gt 0) { $results[0] } else { $null }
            } catch {
                $script:cachedWin32Processor = $null
            } finally {
                try { $script:processorRunspace.Dispose() } catch {}
                $script:processorRunspace = $null
                $script:processorAsyncResult = $null
            }
        }
        if ($null -eq $script:cachedWin32Processor) {
            $script:cachedWin32Processor = Get-DeviceTweakerFirstItem (Get-CimInstance Win32_Processor -ErrorAction SilentlyContinue)
        }
    }
    return $script:cachedWin32Processor
}
$script:cachedPnpDevicesAll = $null
function Get-CachedPnpDevices {
    if ($null -eq $script:cachedPnpDevicesAll) {
        if (('DeviceTopologyNative' -as [type]) -and (Get-Command Get-CachedDeviceTopologySnapshot -ErrorAction SilentlyContinue)) {
            try {
                $snap = Get-CachedDeviceTopologySnapshot
                if ($snap -and $snap.DeviceNodes) {
                    $script:cachedPnpDevicesAll = @(Convert-DeviceTopologySnapshotToPnpDeviceCache -Snapshot $snap)
                    return $script:cachedPnpDevicesAll
                }
            } catch {}
        }
        if ($script:pnpDevicesAsyncResult -and $script:pnpDevicesRunspace) {
            try { $script:pnpDevicesRunspace.Dispose() } catch {}
            $script:pnpDevicesRunspace = $null
            $script:pnpDevicesAsyncResult = $null
        }
        if ($null -eq $script:cachedPnpDevicesAll) {
            $script:cachedPnpDevicesAll = @()
        }
    }
    return $script:cachedPnpDevicesAll
}
