$script:usbAssocsRunspace = $null
$script:usbAssocsAsyncResult = $null
$script:cachedWmiInputData = $null

$script:cachedUSBControllerAssocData = $null
$script:usbAssocPrefetchError = $null
$script:cachedHidTypeProperties = $null
