function Convert-DeviceTopologySnapshotToPnpDeviceCache {
    param([AllowNull()][object]$Snapshot)
    $items = [System.Collections.Generic.List[object]]::new()
    if (-not $Snapshot -or -not $Snapshot.DeviceNodes) { return @($items) }
    foreach ($n in @($Snapshot.DeviceNodes)) {
        if (-not $n -or [string]::IsNullOrWhiteSpace([string]$n.InstanceId)) { continue }
        $status = if ($n.IsPresent) { 'OK' } else { 'Unknown' }
        $friendly = if (-not [string]::IsNullOrWhiteSpace([string]$n.FriendlyName)) { [string]$n.FriendlyName } elseif (-not [string]::IsNullOrWhiteSpace([string]$n.DeviceDesc)) { [string]$n.DeviceDesc } else { [string]$n.InstanceId }
        [void]$items.Add([PSCustomObject]@{
            InstanceId     = [string]$n.InstanceId
            Class          = [string]$n.ClassName
            FriendlyName   = $friendly
            Status         = $status
            Service        = [string]$n.Service
            HardwareIds    = @($n.HardwareIds)
            CompatibleIds  = @($n.CompatibleIds)
            DeviceDesc     = [string]$n.DeviceDesc
            EnumeratorName = [string]$n.EnumeratorName
            ParentInstanceId = [string]$n.ParentInstanceId
        })
    }
    return @($items.ToArray())
}

function Convert-DeviceTopologySnapshotToHidPropertyRows {
    param([AllowNull()][object]$Snapshot)
    $rows = [System.Collections.Generic.List[object]]::new()
    if (-not $Snapshot -or -not $Snapshot.DeviceNodes) { return @($rows) }
    foreach ($n in @($Snapshot.DeviceNodes)) {
        if (-not $n -or [string]::IsNullOrWhiteSpace([string]$n.InstanceId)) { continue }
        if (-not [string]::IsNullOrWhiteSpace([string]$n.Service)) {
            [void]$rows.Add([PSCustomObject]@{ InstanceId = [string]$n.InstanceId; KeyName = 'DEVPKEY_Device_Service'; Data = [string]$n.Service })
        }
        if ($n.HardwareIds -and @($n.HardwareIds).Count -gt 0) {
            [void]$rows.Add([PSCustomObject]@{ InstanceId = [string]$n.InstanceId; KeyName = 'DEVPKEY_Device_HardwareIds'; Data = @($n.HardwareIds) })
        }
        if ($n.CompatibleIds -and @($n.CompatibleIds).Count -gt 0) {
            [void]$rows.Add([PSCustomObject]@{ InstanceId = [string]$n.InstanceId; KeyName = 'DEVPKEY_Device_CompatibleIds'; Data = @($n.CompatibleIds) })
        }
    }
    return @($rows.ToArray())
}

function Convert-DeviceTopologySnapshotToParentMap {
    param([AllowNull()][object]$Snapshot)
    $map = @{}
    if ($Snapshot -and $Snapshot.ParentMap) {
        foreach ($key in @($Snapshot.ParentMap.Keys)) {
            if ($key -and $Snapshot.ParentMap[$key]) { $map[[string]$key] = [string]$Snapshot.ParentMap[$key] }
        }
    } elseif ($Snapshot -and $Snapshot.DeviceNodes) {
        foreach ($n in @($Snapshot.DeviceNodes)) {
            if ($n.InstanceId -and $n.ParentInstanceId) { $map[[string]$n.InstanceId] = [string]$n.ParentInstanceId }
        }
    }
    return $map
}

function Set-DeviceTopologyDerivedCaches {
    param([AllowNull()][object]$Snapshot)
    if (-not $Snapshot) { return }
    try { $script:cachedPnpDevicesAll = @(Convert-DeviceTopologySnapshotToPnpDeviceCache -Snapshot $Snapshot) } catch {}
    try { $script:cachedParentMap = Convert-DeviceTopologySnapshotToParentMap -Snapshot $Snapshot } catch {}
    try { if ($Snapshot.ControllerAssociations) { $script:cachedUSBControllerAssocs = @($Snapshot.ControllerAssociations) } } catch {}
    try { if ($Snapshot.UsbEnumeration) { $script:cachedBIntervalResult = $Snapshot.UsbEnumeration } } catch {}
    try {
        $script:cachedHidTypeProperties = @(Convert-DeviceTopologySnapshotToHidPropertyRows -Snapshot $Snapshot)
        $script:hidTypePropsLoaded = $true
    } catch {}
}

function Convert-DeviceTweakerDiscoveryModelToPciDeviceProps {
    param([AllowNull()][object]$Model)

    $items = [System.Collections.Generic.List[object]]::new()
    if (-not $Model -or -not $Model.PciDevicesByPath) { return @($items.ToArray()) }

    foreach ($entry in $Model.PciDevicesByPath.GetEnumerator()) {
        if ($null -eq $entry.Value) { continue }
        [void]$items.Add($entry.Value)
    }

    return @($items.ToArray())
}

function Set-DeviceTweakerDiscoveryModelDerivedCaches {
    param([AllowNull()][object]$Model)

    if (-not $Model) { return }

    try {
        if ($Model.TopologySnapshot) {
            $script:cachedDeviceTopologySnapshot = $Model.TopologySnapshot
            Set-DeviceTopologyDerivedCaches -Snapshot $Model.TopologySnapshot
        }
    } catch {}

    try {
        if ($Model.PciDevicesByPath) {
            $script:cachedPciDeviceProps = @(Convert-DeviceTweakerDiscoveryModelToPciDeviceProps -Model $Model)
        }
    } catch {}

    try {
        if ($script:pciPropsRunspace) { $script:pciPropsRunspace.Dispose() }
    } catch {} finally {
        $script:pciPropsRunspace = $null
        $script:pciPropsAsyncResult = $null
    }
}



function New-DeviceTweakerStartupDiscoveryOptions {
    $opts = $null
    try {
        if ('DeviceTweakerStartupOptions' -as [type]) {
            $opts = [DeviceTweakerStartupOptions]::new()
            try { $opts.IncludeLogs = (-not [bool]$script:DisableLogs) } catch {}
            try { $opts.IncludeUiReadyState = $true } catch {}
            try { $opts.IgnoredAudioNames = [string[]]@($script:ignoredDualSenseAudioNames) } catch {}
            try {
                $opts.PciIdsPath = [string](Get-DeviceTweakerPciIdsPathFast)
            } catch {}
        }
    } catch { $opts = $null }
    return $opts
}

function Set-DeviceTweakerStartupModelDerivedCaches {
    param([AllowNull()][object]$Model)

    if (-not $Model) { return }

    try {
        if ($Model.DiscoveryModel) {
            $script:DiscoveryModel = $Model.DiscoveryModel
            Set-DeviceTweakerDiscoveryModelDerivedCaches -Model $script:DiscoveryModel
        }
    } catch { }

    try {
        if ($Model.CpuTopology) {
            $script:NativeStartupCpuTopology = $Model.CpuTopology
            if ($Model.CpuTopology.LogicalProcessorCount -gt 0) { $script:cachedLogicalCount = [int]$Model.CpuTopology.LogicalProcessorCount }
            if ($Model.CpuTopology.PhysicalCoreCount -gt 0 -and $null -eq $script:cachedPhysicalCount) { $script:cachedPhysicalCount = [int]$Model.CpuTopology.PhysicalCoreCount }
        }
    } catch { }

    try { if ($Model.HidRows -and $Model.HidRows.Count -gt 0) { $script:_cachedHidDevices = @($Model.HidRows) } } catch { }
    try { if ($Model.UsbSourceLogs) { $script:_cachedUsbNativeDiscoveryLogs = @($Model.UsbSourceLogs) } } catch { }
    try { if ($Model.UsbUnusedCpuControllers) { $script:_cachedUsbNativeUnusedCpuControllers = @($Model.UsbUnusedCpuControllers) } } catch { }
    try { if ($Model.PciSourceLogs) { $script:_cachedPciNativeDiscoveryLogs = @($Model.PciSourceLogs) } } catch { }
    try { if ($Model.StorageSourceLogs) { $script:_cachedStorageNativeDiscoveryLogs = @($Model.StorageSourceLogs) } } catch { }
    try { if ($Model.NetworkSourceLogs) { $script:_cachedNetworkNativeDiscoveryLogs = @($Model.NetworkSourceLogs) } } catch { }
    try {
        if ($Model.IrqRowsComplete) {
            $script:cachedIrqAllocations = @($Model.IrqAllocationRows)
            $script:cachedIrqAllocationsComplete = $true
        }
    } catch { }
    try {
        if ($Model.DeviceAddressRowsComplete) {
            $script:cachedDeviceAddressMap = @{}
            if ($Model.DeviceAddressByPnpId) {
                foreach ($k in @($Model.DeviceAddressByPnpId.Keys)) { $script:cachedDeviceAddressMap[[string]$k] = [uint64]$Model.DeviceAddressByPnpId[$k] }
            }
            $script:cachedDeviceAddressMapComplete = $true
        }
    } catch { }
    try {
        if ($Model.UsbAudioEndpointRows -and $Model.UsbAudioEndpointRows.Count -gt 0 -and (Get-Command Set-DeviceTweakerAudioLookupFromDetails -ErrorAction SilentlyContinue)) {
            Set-DeviceTweakerAudioLookupFromDetails -AudioDetails @($Model.UsbAudioEndpointRows)
        }
    } catch { }

    try {
        if ($Model.AudioEndpointParentRows -and $Model.AudioEndpointParentRows.Count -gt 0) {
            if ($null -eq $script:audioEndpointFormFactorCache) { $script:audioEndpointFormFactorCache = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase) }
            foreach ($row in @($Model.AudioEndpointParentRows)) {
                if ($null -eq $row -or [string]::IsNullOrWhiteSpace([string]$row.InstanceId)) { continue }
                $ffv = $null
                try { $ffv = $row.FormFactorValue } catch { $ffv = $null }
                if ($null -eq $ffv) { continue }
                $script:audioEndpointFormFactorCache[[string]$row.InstanceId] = [DeviceTweakerAudioEndpointFormFactorRecord]::new([uint32]$ffv, 'native startup payload')
            }
        }
    } catch { }
}

function Get-DeviceTweakerStartupModel {
    if ($null -ne $script:StartupModel) { return $script:StartupModel }

    [void](Receive-DeviceTweakerDiscoveryModelPrefetch -WaitMilliseconds 120000)
    if ($null -ne $script:StartupModel) { return $script:StartupModel }

    if ('DeviceTweakerDiscovery' -as [type]) {
        try {
            $script:StartupModel = [DeviceTweakerDiscovery]::BuildFullStartupPayload((New-DeviceTweakerStartupDiscoveryOptions))
            Set-DeviceTweakerStartupModelDerivedCaches -Model $script:StartupModel
        } catch {
            $script:discoveryModelPrefetchError = $_.Exception.Message
            try {
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) {
                    Write-DeviceTweakerPerfFallbackLog "DeviceTweakerStartupModel native pass failed | Reason: $($_.Exception.Message)"
                }
            } catch { }
            $script:StartupModel = $null
        }
    }

    return $script:StartupModel
}

function Receive-DeviceTweakerDiscoveryModelPrefetch {
    param([int]$WaitMilliseconds = 0)

    if ($null -ne $script:StartupModel) { return $script:DiscoveryModel }

    if ($script:discoveryModelTask) {
        try {
            if (-not $script:discoveryModelTask.IsCompleted) {
                if ($WaitMilliseconds -le 0) { return $null }
                [void]$script:discoveryModelTask.Wait($WaitMilliseconds)
                if (-not $script:discoveryModelTask.IsCompleted) { return $null }
            }

            if ($script:discoveryModelTask.IsFaulted) {
                $_taskException = $script:discoveryModelTask.Exception
                try { $_taskException = $_taskException.Flatten().InnerException } catch {}
                $script:discoveryModelPrefetchError = if ($_taskException) { $_taskException.Message } else { 'Native startup payload task failed.' }
                $script:StartupModel = $null
                $script:DiscoveryModel = $null
            } elseif ($script:discoveryModelTask.IsCanceled) {
                $script:discoveryModelPrefetchError = 'Native startup payload task was canceled.'
                $script:StartupModel = $null
                $script:DiscoveryModel = $null
            } else {
                $script:StartupModel = [DeviceTweakerDiscovery]::CompleteFullStartupPayloadTask($script:discoveryModelTask)
                Set-DeviceTweakerStartupModelDerivedCaches -Model $script:StartupModel
            }
        } catch {
            $script:discoveryModelPrefetchError = $_.Exception.Message
            $script:StartupModel = $null
            $script:DiscoveryModel = $null
        } finally {
            $script:discoveryModelTask = $null
        }

        return $script:DiscoveryModel
    }

    if ($null -ne $script:DiscoveryModel) { return $script:DiscoveryModel }
    if (-not $script:discoveryModelAsyncResult -or -not $script:discoveryModelRunspace) { return $null }

    try {
        if (-not $script:discoveryModelAsyncResult.IsCompleted) {
            if ($WaitMilliseconds -le 0) { return $null }
            [void]$script:discoveryModelAsyncResult.AsyncWaitHandle.WaitOne($WaitMilliseconds)
            if (-not $script:discoveryModelAsyncResult.IsCompleted) { return $null }
        }

        $raw = @($script:discoveryModelRunspace.EndInvoke($script:discoveryModelAsyncResult))
        if ($raw.Count -gt 0 -and $null -ne $raw[0].__DeviceTweakerDiscoveryModelError) {
            $script:discoveryModelPrefetchError = [string]$raw[0].__DeviceTweakerDiscoveryModelError
            $script:DiscoveryModel = $null
            $script:StartupModel = $null
        } elseif ($raw.Count -gt 0) {
            $prefetched = $raw[0]
            if ($null -ne $prefetched -and ($prefetched -is [DeviceTweakerStartupModel] -or $prefetched.GetType().Name -eq 'DeviceTweakerStartupModel' -or $prefetched.GetType().Name -eq 'DeviceTweakerStartupPayload')) {
                $script:StartupModel = $prefetched
                Set-DeviceTweakerStartupModelDerivedCaches -Model $script:StartupModel
            } else {
                $script:DiscoveryModel = $prefetched
                Set-DeviceTweakerDiscoveryModelDerivedCaches -Model $script:DiscoveryModel
            }
        }
    } catch {
        $script:discoveryModelPrefetchError = $_.Exception.Message
        $script:DiscoveryModel = $null
    } finally {
        try { if ($script:discoveryModelRunspace) { $script:discoveryModelRunspace.Dispose() } } catch {}
        $script:discoveryModelRunspace = $null
        $script:discoveryModelAsyncResult = $null
    }

    return $script:DiscoveryModel
}

function Start-DeviceTweakerDiscoveryModelPrefetch {
    if ($null -ne $script:StartupModel -or $null -ne $script:DiscoveryModel) { return }
    if ($script:discoveryModelTask -or $script:discoveryModelRunspace -or $script:discoveryModelAsyncResult) { return }
    if (-not ('DeviceTweakerDiscovery' -as [type])) { return }

    try {
        $_startupOpts = New-DeviceTweakerStartupDiscoveryOptions
        $script:discoveryModelTask = [DeviceTweakerDiscovery]::StartFullStartupPayloadTask($_startupOpts)
    } catch {
        $script:discoveryModelPrefetchError = $_.Exception.Message
        $script:discoveryModelTask = $null
        try { if ($script:discoveryModelRunspace) { $script:discoveryModelRunspace.Dispose() } } catch {}
        $script:discoveryModelRunspace = $null
        $script:discoveryModelAsyncResult = $null
    }
}

function Get-DeviceTweakerDiscoveryModel {
    if ($null -ne $script:DiscoveryModel) { return $script:DiscoveryModel }
    if ($null -ne $script:StartupModel -and $script:StartupModel.DiscoveryModel) {
        $script:DiscoveryModel = $script:StartupModel.DiscoveryModel
        Set-DeviceTweakerDiscoveryModelDerivedCaches -Model $script:DiscoveryModel
        return $script:DiscoveryModel
    }

    [void](Receive-DeviceTweakerDiscoveryModelPrefetch -WaitMilliseconds 120000)
    if ($null -ne $script:DiscoveryModel) { return $script:DiscoveryModel }

    if ('DeviceTweakerDiscovery' -as [type]) {
        try {
            $script:StartupModel = [DeviceTweakerDiscovery]::BuildFullStartupPayload((New-DeviceTweakerStartupDiscoveryOptions))
            Set-DeviceTweakerStartupModelDerivedCaches -Model $script:StartupModel
        } catch {
            $script:discoveryModelPrefetchError = $_.Exception.Message
            try {
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) {
                    Write-DeviceTweakerPerfFallbackLog "DeviceTweakerStartupModel native pass failed; falling back to DeviceDiscoveryModel only | Reason: $($_.Exception.Message)"
                }
            } catch {}
            try {
                $script:DiscoveryModel = [DeviceTweakerDiscovery]::BuildModel()
                Set-DeviceTweakerDiscoveryModelDerivedCaches -Model $script:DiscoveryModel
            } catch {
                $script:discoveryModelPrefetchError = $_.Exception.Message
                try {
                    if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) {
                        Write-DeviceTweakerPerfFallbackLog "DeviceDiscoveryModel native pass failed | Reason: $($_.Exception.Message)"
                    }
                } catch {}
                $script:DiscoveryModel = $null
            }
        }
    }

    return $script:DiscoveryModel
}

function Start-DeviceTopologySnapshotPrefetch {
    Start-DeviceTweakerDiscoveryModelPrefetch
}

function Test-DeviceTweakerMergedTypesAvailable {
    try {
        return [bool](('DeviceTopologyNative' -as [type]) -and ('DeviceTweakerScrollDynamics' -as [type]) -and ('DeviceTweakerDiscovery' -as [type]))
    } catch {
        return $false
    }
}

function Get-DeviceTweakerMergedTypeCacheAssemblyPath {
    param([Parameter(Mandatory=$true)][string]$CacheKey)

    $fileName = 'DeviceTweakerMergedTypes_' + $CacheKey + '_ps' + ([string]$PSVersionTable.PSVersion.Major) + '_x' + ([string]([IntPtr]::Size * 8)) + '.dll'
    $candidateRoots = [System.Collections.Generic.List[string]]::new()

    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$env:LOCALAPPDATA)) {
            [void]$candidateRoots.Add((Join-Path ([string]$env:LOCALAPPDATA) 'ExovanceDeviceTweakerV2\TypeCache'))
        }
    } catch { }
    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$env:TEMP)) {
            [void]$candidateRoots.Add((Join-Path ([string]$env:TEMP) 'ExovanceDeviceTweakerV2\TypeCache'))
        }
    } catch { }
    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$script:cachedScriptDir)) {
            [void]$candidateRoots.Add((Join-Path ([string]$script:cachedScriptDir) '.device-tweaker-typecache'))
        }
    } catch { }

    foreach ($root in $candidateRoots) {
        try {
            if ([string]::IsNullOrWhiteSpace([string]$root)) { continue }
            if (-not [System.IO.Directory]::Exists([string]$root)) {
                [void][System.IO.Directory]::CreateDirectory([string]$root)
            }
            return (Join-Path ([string]$root) $fileName)
        } catch { }
    }

    return $null
}

function Import-DeviceTweakerCachedMergedTypes {
    param([AllowNull()][string]$CacheAssemblyPath)

    if (Test-DeviceTweakerMergedTypesAvailable) { return $true }
    if ([string]::IsNullOrWhiteSpace([string]$CacheAssemblyPath)) { return $false }
    if (-not [System.IO.File]::Exists([string]$CacheAssemblyPath)) { return $false }

    try {
        [void][System.Reflection.Assembly]::LoadFrom([string]$CacheAssemblyPath)
        if (Test-DeviceTweakerMergedTypesAvailable) { return $true }
    } catch { }

    try {
        Add-Type -Path ([string]$CacheAssemblyPath) -ErrorAction Stop
        return (Test-DeviceTweakerMergedTypesAvailable)
    } catch {
        return $false
    }
}

function Add-DeviceTweakerMergedTypesFromSource {
    param([AllowNull()][string]$CacheAssemblyPath)

    if (Test-DeviceTweakerMergedTypesAvailable) { return }

    $referencedAssemblies = @('System.Windows.Forms', 'System.Drawing', 'System.Management')
    $typeDefinition = @"
using System;
using System.Runtime.InteropServices;
using System.Collections.Generic;
using System.Collections;
using System.Text;
using System.Text.RegularExpressions;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Windows.Forms;
using System.ComponentModel;
using System.Diagnostics;
using System.Globalization;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.Win32.SafeHandles;

public static class ExovancePalette
{
    public static readonly Color Background = Color.FromArgb(13, 18, 28);
    public static readonly Color Card = Color.FromArgb(19, 27, 40);
    public static readonly Color Raised = Color.FromArgb(27, 38, 54);
    public static readonly Color Border = Color.FromArgb(47, 63, 82);
    public static readonly Color Text = Color.FromArgb(234, 242, 250);
    public static readonly Color Muted = Color.FromArgb(154, 173, 194);
    public static readonly Color Accent = Color.FromArgb(83, 235, 195);
    public static readonly Color Violet = Color.FromArgb(166, 150, 255);
    public static readonly Color Warning = Color.FromArgb(255, 200, 113);
    public static readonly Color Error = Color.FromArgb(255, 126, 145);
    public static Color CpuFill(bool selected, bool hovered)
    {
        return selected ? Color.FromArgb(23, 70, 66) : (hovered ? Raised : Card);
    }
    public static Color CpuBorder(bool selected, bool hovered)
    {
        return selected ? Accent : (hovered ? Muted : Border);
    }
}

public static class ExovanceRssTopology
{
    public static int[] PhysicalIds;
    // Same rule as Get-ExovanceRssPlan: one logical processor per physical
    // core, starting at the selected base, never wrapping to CPU zero.
    public static int[] GetProcessors(int baseProcessor, int queueCount, int logicalCount)
    {
        if (logicalCount < 1 || logicalCount > 64 || baseProcessor < 0 || baseProcessor >= logicalCount || queueCount < 1) { return new int[0]; }
        List<int> processors = new List<int>();
        HashSet<int> physical = new HashSet<int>();
        int[] ids = PhysicalIds;
        for (int cpu = baseProcessor; cpu < logicalCount; cpu++)
        {
            int unit = ids != null && ids.Length == logicalCount ? ids[cpu] : cpu;
            if (physical.Add(unit)) {
                processors.Add(cpu);
                if (processors.Count == queueCount) { return processors.ToArray(); }
            }
        }
        return new int[0];
    }
    public static ulong GetMask(int baseProcessor, int queueCount, int logicalCount)
    {
        ulong mask = 0UL;
        foreach (int cpu in GetProcessors(baseProcessor, queueCount, logicalCount)) { mask |= 1UL << cpu; }
        return mask;
    }
}

public static class ExovanceInteractionState
{
    public static event EventHandler SelectionChanged;
    public static void MarkChanged()
    {
        EventHandler handler = SelectionChanged;
        if (handler != null) { handler(null, EventArgs.Empty); }
    }
}

public static class ExovanceVisuals
{
    private static readonly HashSet<Control> Styled = new HashSet<Control>();
    public static GraphicsPath Round(Rectangle r, int radius)
    {
        GraphicsPath path = new GraphicsPath();
        int d = Math.Max(1, Math.Min(radius * 2, Math.Min(r.Width, r.Height)));
        path.AddArc(r.X, r.Y, d, d, 180, 90);
        path.AddArc(r.Right - d, r.Y, d, d, 270, 90);
        path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);
        path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);
        path.CloseFigure();
        return path;
    }
    public static void CardFrame(Graphics g, Rectangle bounds, string title, Font font)
    {
        SmoothingMode old = g.SmoothingMode;
        g.SmoothingMode = SmoothingMode.AntiAlias;
        Rectangle rect = new Rectangle(bounds.X + 1, bounds.Y + 8, Math.Max(2, bounds.Width - 3), Math.Max(2, bounds.Height - 10));
        using (GraphicsPath path = Round(rect, 10))
        using (SolidBrush fill = new SolidBrush(ExovancePalette.Card))
        using (Pen border = new Pen(ExovancePalette.Border)) { g.FillPath(fill, path); g.DrawPath(border, path); }
        Size label = HeaderSurface.MeasureTextSize(title ?? String.Empty, font);
        Rectangle labelRect = new Rectangle(bounds.Left + 14, bounds.Top, Math.Min(Math.Max(1, bounds.Width - 28), label.Width + 12), label.Height + 2);
        using (SolidBrush fill = new SolidBrush(ExovancePalette.Card)) { g.FillRectangle(fill, labelRect); }
        TextRenderer.DrawText(g, title ?? String.Empty, font, labelRect, ExovancePalette.Text, TextFormatFlags.Left | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis | TextFormatFlags.SingleLine);
        g.SmoothingMode = old;
    }
    public static void ApplyTo(Control root)
    {
        if (root == null || root.IsDisposed) { return; }
        if (Styled.Add(root))
        {
            root.ControlAdded += delegate(object sender, ControlEventArgs e) { ApplyTo(e.Control); };
            root.Disposed += delegate { Styled.Remove(root); };
            ComboBox combo = root as ComboBox;
            if (combo != null)
            {
                combo.FlatStyle = FlatStyle.Flat;
                combo.BackColor = ExovancePalette.Raised;
                combo.ForeColor = ExovancePalette.Text;
                combo.DrawMode = DrawMode.OwnerDrawFixed;
                combo.ItemHeight = Math.Max(20, combo.Font.Height + 4);
                combo.DrawItem += DrawComboItem;
                combo.SelectionChangeCommitted += delegate { ExovanceInteractionState.MarkChanged(); };
            }
            TextBoxBase input = root as TextBoxBase;
            if (input != null) { input.BackColor = ExovancePalette.Raised; input.ForeColor = ExovancePalette.Text; }
            Button button = root as Button;
            if (button != null && !(button is ExovanceActionButton))
            {
                button.UseVisualStyleBackColor = false;
                button.FlatStyle = FlatStyle.Flat;
                button.BackColor = ExovancePalette.Raised;
                button.ForeColor = ExovancePalette.Text;
                button.FlatAppearance.BorderColor = ExovancePalette.Border;
                button.FlatAppearance.MouseOverBackColor = Color.FromArgb(36, 56, 70);
                button.FlatAppearance.MouseDownBackColor = Color.FromArgb(24, 73, 68);
            }
        }
        foreach (Control child in root.Controls) { ApplyTo(child); }
    }
    private static void DrawComboItem(object sender, DrawItemEventArgs e)
    {
        ComboBox combo = sender as ComboBox;
        if (combo == null) { return; }
        bool active = (e.State & DrawItemState.Selected) != 0;
        Color fill = active ? Color.FromArgb(30, 72, 70) : ExovancePalette.Raised;
        using (SolidBrush brush = new SolidBrush(fill)) { e.Graphics.FillRectangle(brush, e.Bounds); }
        string text = e.Index >= 0 && e.Index < combo.Items.Count ? combo.GetItemText(combo.Items[e.Index]) : combo.Text;
        Rectangle textBounds = Rectangle.Inflate(e.Bounds, -7, 0);
        bool enabledValue = String.Equals(text, "Enabled", StringComparison.OrdinalIgnoreCase) || String.Equals(text, "On", StringComparison.OrdinalIgnoreCase);
        bool disabledValue = String.Equals(text, "Disabled", StringComparison.OrdinalIgnoreCase) || String.Equals(text, "Off", StringComparison.OrdinalIgnoreCase);
        Color textColor = !combo.Enabled ? ExovancePalette.Muted : (active || enabledValue ? ExovancePalette.Accent : (disabledValue ? ExovancePalette.Muted : ExovancePalette.Text));
        TextRenderer.DrawText(e.Graphics, text, e.Font, textBounds, textColor, TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        e.DrawFocusRectangle();
    }
}

public sealed class ExovanceActionButton : Button
{
    private bool _hover;
    private bool _pressed;
    private bool _busy;
    public bool Primary { get; set; }
    public bool Busy { get { return _busy; } set { _busy = value; Invalidate(); } }
    public ExovanceActionButton()
    {
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        FlatStyle = FlatStyle.Flat;
        FlatAppearance.BorderSize = 0;
        UseVisualStyleBackColor = false;
        Cursor = Cursors.Hand;
        TabStop = true;
        AccessibleRole = AccessibleRole.PushButton;
    }
    protected override void OnMouseEnter(EventArgs e) { _hover = true; Invalidate(); base.OnMouseEnter(e); }
    protected override void OnMouseLeave(EventArgs e) { _hover = false; _pressed = false; Invalidate(); base.OnMouseLeave(e); }
    protected override void OnMouseDown(MouseEventArgs e) { _pressed = true; Invalidate(); base.OnMouseDown(e); }
    protected override void OnMouseUp(MouseEventArgs e) { _pressed = false; Invalidate(); base.OnMouseUp(e); }
    protected override void OnEnabledChanged(EventArgs e) { Invalidate(); base.OnEnabledChanged(e); }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }
    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        g.Clear(Parent != null ? Parent.BackColor : ExovancePalette.Background);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        bool lit = Enabled && (Primary || _hover);
        Color fill = Primary ? ExovancePalette.Accent : (_hover ? Color.FromArgb(31, 53, 65) : ExovancePalette.Raised);
        if (_pressed && Enabled) { fill = Color.FromArgb(42, 151, 130); }
        if (!Enabled) { fill = _busy ? Color.FromArgb(25, 63, 61) : ExovancePalette.Card; }
        Color edge = lit || _busy ? ExovancePalette.Accent : ExovancePalette.Border;
        Rectangle rect = new Rectangle(1, 1, Math.Max(2, Width - 3), Math.Max(2, Height - 3));
        using (GraphicsPath path = ExovanceVisuals.Round(rect, 9))
        using (SolidBrush brush = new SolidBrush(fill))
        using (Pen pen = new Pen(edge, Focused && ShowFocusCues ? 2f : 1f)) { g.FillPath(brush, path); g.DrawPath(pen, path); }
        Color text = Primary && Enabled ? ExovancePalette.Background : (Enabled || _busy ? ExovancePalette.Text : ExovancePalette.Muted);
        TextRenderer.DrawText(g, _busy ? "Working..." : Text, Font, Rectangle.Inflate(ClientRectangle, -9, -3), text,
            TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPrefix);
        if (Focused && ShowFocusCues) { ControlPaint.DrawFocusRectangle(g, Rectangle.Inflate(rect, -5, -5), text, fill); }
    }
}




