public static class DeviceTweakerNvmeProtocol
{
    private const uint GENERIC_READ = 0x80000000;
    private const uint GENERIC_WRITE = 0x40000000;
    private const uint FILE_SHARE_READ = 0x00000001;
    private const uint FILE_SHARE_WRITE = 0x00000002;
    private const uint FILE_SHARE_DELETE = 0x00000004;
    private const uint OPEN_EXISTING = 3;
    private const uint FILE_ATTRIBUTE_NORMAL = 0x00000080;
    private const uint IOCTL_STORAGE_QUERY_PROPERTY = 0x002D1400;
    private const uint IOCTL_STORAGE_SET_PROPERTY = 0x002D940C;
    private const uint IOCTL_STORAGE_PROTOCOL_COMMAND = 0x002DD3C0;
    private const uint StorageAdapterProtocolSpecificProperty = 49;
    private const uint StorageDeviceProtocolSpecificProperty = 50;
    private const uint PropertyStandardQuery = 0;
    private const uint PropertyStandardSet = 0;
    private const uint ProtocolTypeNvme = 3;
    private const uint NVMeDataTypeIdentify = 1;
    private const uint NVMeDataTypeFeature = 3;
    private const uint NVME_IDENTIFY_CNS_CONTROLLER = 1;
    private const int NVME_IDENTIFY_CONTROLLER_DATA_LENGTH = 4096;
    private const int NVME_IDENTIFY_HMPRE_OFFSET = 272;
    private const int NVME_IDENTIFY_HMMIN_OFFSET = 276;
    private const int NVME_IDENTIFY_VWC_OFFSET = 525;
    private const int NVME_IDENTIFY_HCTMA_OFFSET = 322;
    private const int NVME_IDENTIFY_MNTMT_OFFSET = 324;
    private const int NVME_IDENTIFY_MXTMT_OFFSET = 326;
    private const uint NVME_FEATURE_ARBITRATION = 0x01;
    private const uint NVME_FEATURE_POWER_MANAGEMENT = 0x02;
    private const uint NVME_FEATURE_TEMPERATURE_THRESHOLD = 0x04;
    private const uint NVME_FEATURE_ERROR_RECOVERY = 0x05;
    private const uint NVME_FEATURE_VOLATILE_WRITE_CACHE = 0x06;
    private const uint NVME_FEATURE_NUMBER_OF_QUEUES = 0x07;
    private const uint NVME_FEATURE_INTERRUPT_COALESCING = 0x08;
    private const uint NVME_FEATURE_WRITE_ATOMICITY_NORMAL = 0x0A;
    private const uint NVME_FEATURE_AUTONOMOUS_POWER_STATE_TRANSITION = 0x0C;
    private const uint NVME_FEATURE_HOST_MEMORY_BUFFER = 0x0D;
    private const uint NVME_FEATURE_HOST_CONTROLLED_THERMAL_MANAGEMENT = 0x10;
    private const uint STORAGE_PROTOCOL_STRUCTURE_VERSION = 1;
    private const uint STORAGE_PROTOCOL_COMMAND_FLAG_ADAPTER_REQUEST = 0x80000000;
    private const uint STORAGE_PROTOCOL_STATUS_SUCCESS = 1;
    private const uint STORAGE_PROTOCOL_SPECIFIC_NVME_ADMIN_COMMAND = 1;
    private const int STORAGE_PROPERTY_HEADER_SIZE = 8;
    private const int STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE = 40;
    private const int STORAGE_PROTOCOL_SPECIFIC_DATA_EXT_SIZE = 64;
    private const int STORAGE_PROTOCOL_SPECIFIC_DATA_FIXED_RETURN_OFFSET = 24;
    private const int STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND = 80;
    private const int STORAGE_PROTOCOL_COMMAND_SIZEOF = 84;
    private const int STORAGE_PROTOCOL_COMMAND_LENGTH_NVME = 64;
    private const int NVME_COMMAND_OFFSET_CDW0 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 0;
    private const int NVME_COMMAND_OFFSET_NSID = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 4;
    private const int NVME_COMMAND_OFFSET_CDW10 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 40;
    private const int NVME_COMMAND_OFFSET_CDW11 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 44;
    private const int NVME_COMMAND_OFFSET_CDW12 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 48;
    private const int NVME_COMMAND_OFFSET_CDW13 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 52;
    private const int NVME_COMMAND_OFFSET_CDW14 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 56;
    private const int NVME_COMMAND_OFFSET_CDW15 = STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + 60;
    private const int NVME_PROTOCOL_SCRATCH_SIZE = 512;
    private const int NVME_APST_DATA_LENGTH = 256;
    private const int NVME_HMB_ATTRIBUTES_DATA_LENGTH = 16;
    private const int FIXED_RETURN_DATA_OFFSET = STORAGE_PROPERTY_HEADER_SIZE + 24;

    [DllImport("kernel32.dll", SetLastError = true, CharSet = CharSet.Unicode)]
    private static extern SafeFileHandle CreateFile(string lpFileName, uint dwDesiredAccess, uint dwShareMode, IntPtr lpSecurityAttributes, uint dwCreationDisposition, uint dwFlagsAndAttributes, IntPtr hTemplateFile);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool DeviceIoControl(SafeFileHandle hDevice, uint dwIoControlCode, byte[] lpInBuffer, int nInBufferSize, byte[] lpOutBuffer, int nOutBufferSize, out int lpBytesReturned, IntPtr lpOverlapped);

    public static DeviceTweakerNvmeArbitrationState GetArbitration(string drivePath)
    {
        string scope;
        try
        {
            uint raw = GetFeatureFixedData(drivePath, NVME_FEATURE_ARBITRATION, out scope);
            return BuildArbitrationState(drivePath, raw, scope);
        }
        catch (Exception ex)
        {
            if (IsArbitrationUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                return BuildUnsupportedArbitrationState(drivePath, "Unsupported");
            }
            throw;
        }
    }

    public static DeviceTweakerNvmeArbitrationState SetArbitration(string drivePath, int arbitrationBurst, int lowPriorityWeight, int mediumPriorityWeight, int highPriorityWeight)
    {
        if (arbitrationBurst < 0 || arbitrationBurst > 7) { throw new ArgumentOutOfRangeException("arbitrationBurst", "NVMe Arbitration AB must be 0..7, where 7 means no limit."); }
        if (lowPriorityWeight < 0 || lowPriorityWeight > 255) { throw new ArgumentOutOfRangeException("lowPriorityWeight", "NVMe Arbitration LPW must be a zero-based raw byte value in the range 0..255."); }
        if (mediumPriorityWeight < 0 || mediumPriorityWeight > 255) { throw new ArgumentOutOfRangeException("mediumPriorityWeight", "NVMe Arbitration MPW must be a zero-based raw byte value in the range 0..255."); }
        if (highPriorityWeight < 0 || highPriorityWeight > 255) { throw new ArgumentOutOfRangeException("highPriorityWeight", "NVMe Arbitration HPW must be a zero-based raw byte value in the range 0..255."); }
        uint cdw11 = ((uint)arbitrationBurst & 0x7u) | (((uint)lowPriorityWeight & 0xFFu) << 8) | (((uint)mediumPriorityWeight & 0xFFu) << 16) | (((uint)highPriorityWeight & 0xFFu) << 24);
        string setScope = String.Empty;
        try
        {
            SetFeatureFixedData(drivePath, NVME_FEATURE_ARBITRATION, cdw11, 0u, 0u, 0u, 0u, null, out setScope);
        }
        catch (Exception ex)
        {
            if (IsArbitrationUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                throw new NotSupportedException("NVMe Arbitration unsupported on this NVMe controller or blocked by Windows StorNVMe for Set Features FID 0x01.", ex);
            }
            throw;
        }
        DeviceTweakerNvmeArbitrationState readBack = GetArbitration(drivePath);
        if (readBack == null) { throw new InvalidOperationException("NVMe Arbitration Set Features FID 0x01 completed but read-back returned no state for " + drivePath + "."); }
        readBack.RequestedRawValue = cdw11;
        readBack.ReadBackVerified = true;
        readBack.ReadBackMatchesRequest = readBack.RawValue == cdw11;
        readBack.Scope = MergeScope(setScope, readBack.Scope);
        readBack.VerificationText = readBack.ReadBackMatchesRequest ? "Set Features completed and Get Features read-back exactly matches requested CDW11." : "Set Features completed but Get Features read-back does not match requested CDW11.";
        if (!readBack.ReadBackMatchesRequest)
        {
            throw new InvalidOperationException("NVMe Arbitration Set Features FID 0x01 verification failed on " + drivePath + ": requestedCDW11=0x" + cdw11.ToString("X8", CultureInfo.InvariantCulture) + " readBackDW0=0x" + readBack.RawValue.ToString("X8", CultureInfo.InvariantCulture) + " scope=" + readBack.Scope + ".");
        }
        return readBack;
    }

    public static DeviceTweakerNvmeNumberOfQueuesState GetNumberOfQueues(string drivePath)
    {
        string scope;
        try
        {
            uint raw = GetFeatureFixedData(drivePath, NVME_FEATURE_NUMBER_OF_QUEUES, out scope);
            return BuildNumberOfQueuesState(drivePath, raw, 0, 0, scope);
        }
        catch (Exception ex)
        {
            if (IsNumberOfQueuesUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                return BuildUnsupportedNumberOfQueuesState(drivePath, 0, 0, "Unsupported");
            }
            throw;
        }
    }

    public static DeviceTweakerNvmeNumberOfQueuesState SetNumberOfQueues(string drivePath, int submissionQueues, int completionQueues)
    {
        if (submissionQueues < 1 || submissionQueues > 65535) { throw new ArgumentOutOfRangeException("submissionQueues", "NVMe Number of Queues NSQR is zero-based; actual I/O submission queues must be 1..65535, producing raw 0..65534. Raw 0xFFFF is invalid and is never emitted."); }
        if (completionQueues < 1 || completionQueues > 65535) { throw new ArgumentOutOfRangeException("completionQueues", "NVMe Number of Queues NCQR is zero-based; actual I/O completion queues must be 1..65535, producing raw 0..65534. Raw 0xFFFF is invalid and is never emitted."); }
        uint nsqRaw = (uint)(submissionQueues - 1);
        uint ncqRaw = (uint)(completionQueues - 1);
        uint cdw11 = (nsqRaw & 0xFFFFu) | ((ncqRaw & 0xFFFFu) << 16);
        string setScope = String.Empty;
        uint setCompletionRaw;
        try
        {
            setCompletionRaw = SetFeatureFixedData(drivePath, NVME_FEATURE_NUMBER_OF_QUEUES, cdw11, 0u, 0u, 0u, 0u, null, out setScope);
        }
        catch (Exception ex)
        {
            if (IsNumberOfQueuesLifecycleFailure(ex.ToString()))
            {
                throw new InvalidOperationException("NVMe Number of Queues FID 0x07 was rejected in the current Windows StorNVMe lifecycle. The NVMe specification allows this Set Features command only during controller initialization before I/O submission/completion queues are created; after that a Command Sequence Error or Feature Not Changeable status is expected.", ex);
            }
            if (IsNumberOfQueuesUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                throw new NotSupportedException("NVMe Number of Queues unsupported on this NVMe controller or blocked by Windows StorNVMe for Set Features FID 0x07.", ex);
            }
            throw;
        }
        DeviceTweakerNvmeNumberOfQueuesState setState = BuildNumberOfQueuesState(drivePath, setCompletionRaw, submissionQueues, completionQueues, setScope);
        setState.RequestedRawValue = cdw11;
        setState.SetCompletionRawValue = setCompletionRaw;
        setState.SubmissionQueuesRequestedRaw = (int)nsqRaw;
        setState.CompletionQueuesRequestedRaw = (int)ncqRaw;
        setState.AllocatedMatchesRequested = setState.SubmissionQueuesAllocated == submissionQueues && setState.CompletionQueuesAllocated == completionQueues;
        setState.ReadBackVerified = false;
        setState.ReadBackMatchesSetCompletion = false;
        setState.VerificationText = setState.AllocatedMatchesRequested ? "Set Features completed; completion DW0 allocation matches requested queue counts. Immediate Get Features verification is pending." : "Set Features completed; completion DW0 allocation differs from requested queue counts, which NVMe permits for FID 0x07. Immediate Get Features verification is pending.";
        try
        {
            DeviceTweakerNvmeNumberOfQueuesState readBack = GetNumberOfQueues(drivePath);
            if (readBack == null) { return setState; }
            readBack.SubmissionQueuesRequested = submissionQueues;
            readBack.CompletionQueuesRequested = completionQueues;
            readBack.SubmissionQueuesRequestedRaw = (int)nsqRaw;
            readBack.CompletionQueuesRequestedRaw = (int)ncqRaw;
            readBack.RequestedRawValue = cdw11;
            readBack.SetCompletionRawValue = setCompletionRaw;
            readBack.AllocatedMatchesRequested = readBack.SubmissionQueuesAllocated == submissionQueues && readBack.CompletionQueuesAllocated == completionQueues;
            readBack.ReadBackVerified = true;
            readBack.ReadBackMatchesSetCompletion = readBack.RawValue == setCompletionRaw;
            readBack.Scope = MergeScope(setScope, readBack.Scope);
            readBack.VerificationText = readBack.ReadBackMatchesSetCompletion ? "Set Features completion DW0 and immediate Get Features read-back match. Allocation may legally differ from the requested count for NVMe FID 0x07." : "Set Features completed, but immediate Get Features read-back differs from the Set Features completion DW0. Allocation may legally differ from the requested count for NVMe FID 0x07.";
            readBack.DisplayText = FormatNumberOfQueuesDisplay(submissionQueues, completionQueues, readBack.SubmissionQueuesAllocated, readBack.CompletionQueuesAllocated, readBack.RawValue);
            return readBack;
        }
        catch (Exception ex)
        {
            if (IsNumberOfQueuesUnsupportedNvmeFeatureFailure(ex.ToString()) || IsNumberOfQueuesLifecycleFailure(ex.ToString()))
            {
                setState.VerificationText = setState.VerificationText + " Immediate Get Features verification was rejected by the driver/controller; Set Features completion DW0 is retained as the authoritative allocation returned by the Set command.";
                return setState;
            }
            throw;
        }
    }

    public static DeviceTweakerNvmeInterruptCoalescingState GetInterruptCoalescing(string drivePath)
    {
        string scope;
        try
        {
            uint raw = GetFeatureFixedData(drivePath, NVME_FEATURE_INTERRUPT_COALESCING, out scope);
            return BuildInterruptCoalescingState(drivePath, raw, scope);
        }
        catch (Exception ex)
        {
            if (IsInterruptCoalescingUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                return BuildUnsupportedInterruptCoalescingState(drivePath, "Unsupported");
            }
            throw;
        }
    }

    public static DeviceTweakerNvmeInterruptCoalescingState SetInterruptCoalescing(string drivePath, int thresholdRaw, int timeUnits)
    {
        if (thresholdRaw < 0 || thresholdRaw > 255) { throw new ArgumentOutOfRangeException("thresholdRaw", "NVMe interrupt coalescing THR must be a raw byte value in the range 0..255."); }
        if (timeUnits < 0 || timeUnits > 255) { throw new ArgumentOutOfRangeException("timeUnits", "NVMe interrupt coalescing TIME must be a raw byte value in the range 0..255, each unit representing 100 microseconds."); }
        uint cdw11 = ((uint)thresholdRaw & 0xFFu) | (((uint)timeUnits & 0xFFu) << 8);
        try
        {
            SetFeature(drivePath, NVME_FEATURE_INTERRUPT_COALESCING, cdw11);
        }
        catch (Exception ex)
        {
            if (IsInterruptCoalescingUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
