    public static DeviceTweakerNvmeVolatileWriteCacheState GetVolatileWriteCache(string drivePath)
    {
        bool vwcPresent;
        byte vwcAttributes;
        string capabilityScope;
        string capabilityError;
        bool capabilityKnown = TryGetVolatileWriteCacheSupport(drivePath, out vwcPresent, out vwcAttributes, out capabilityScope, out capabilityError);
        if (capabilityKnown && !vwcPresent)
        {
            return BuildUnsupportedVolatileWriteCacheState(drivePath, capabilityScope, vwcAttributes);
        }

        string scope;
        uint raw;
        try
        {
            raw = GetFeatureFixedData(drivePath, NVME_FEATURE_VOLATILE_WRITE_CACHE, 0u, out scope);
        }
        catch (Exception ex)
        {
            if (capabilityKnown && !vwcPresent)
            {
                return BuildUnsupportedVolatileWriteCacheState(drivePath, capabilityScope, vwcAttributes);
            }
            if (IsVolatileWriteCacheUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                return BuildUnsupportedVolatileWriteCacheState(drivePath, "Unsupported", vwcAttributes);
            }
            string suffix = capabilityKnown ? "" : " Identify Controller VWC support probe also failed: " + capabilityError;
            throw new InvalidOperationException("NVMe VWC Get Features failed and the controller was not identified as VWC-unsupported." + suffix + " " + ex.Message, ex);
        }
        DeviceTweakerNvmeVolatileWriteCacheState state = BuildVolatileWriteCacheState(drivePath, raw, scope);
        if (capabilityKnown) { state.Supported = vwcPresent; }
        return state;
    }

