            if (IsErrorRecoveryUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                throw new NotSupportedException("NVMe Error Recovery unsupported on this NVMe controller or blocked by Windows StorNVMe for namespace-specific Set Features FID 0x05.", ex);
            }
            throw;
        }
        return GetErrorRecovery(drivePath, namespaceId);
