    public static DeviceTweakerNvmeHostControlledThermalManagementState GetHostControlledThermalManagement(string drivePath)
    {
        DeviceTweakerNvmeHostControlledThermalManagementCapability capability;
        string capabilityError;
        bool capabilityKnown = TryGetHostControlledThermalManagementCapability(drivePath, out capability, out capabilityError);
        if (capabilityKnown && capability != null && !capability.Supported)
        {
            return BuildUnsupportedHostControlledThermalManagementState(drivePath, capability);
        }
        string scope;
        uint raw;
        try
        {
            raw = GetFeatureFixedData(drivePath, NVME_FEATURE_HOST_CONTROLLED_THERMAL_MANAGEMENT, 0u, out scope);
        }
        catch (Exception ex)
        {
            if (capabilityKnown && capability != null && !capability.Supported) { return BuildUnsupportedHostControlledThermalManagementState(drivePath, capability); }
            if (IsHostControlledThermalManagementUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                return BuildUnsupportedHostControlledThermalManagementState(drivePath, capability, "Unsupported");
            }
            string suffix = capabilityKnown ? "" : " Identify Controller HCTM support probe also failed: " + capabilityError;
            throw new InvalidOperationException("NVMe HCTM Get Features failed and the controller was not identified as HCTM-unsupported." + suffix + " " + ex.Message, ex);
        }
        DeviceTweakerNvmeHostControlledThermalManagementState state = BuildHostControlledThermalManagementState(drivePath, raw, scope);
        if (capabilityKnown && capability != null) { ApplyHostControlledThermalManagementCapability(state, capability); }
        else { state.Supported = true; }
        return state;
    }

    public static DeviceTweakerNvmeHostControlledThermalManagementState SetHostControlledThermalManagementCelsius(string drivePath, int thermalManagementTemperature1Celsius, int thermalManagementTemperature2Celsius)
    {
        DeviceTweakerNvmeHostControlledThermalManagementCapability capability;
        string capabilityError;
        bool capabilityKnown = TryGetHostControlledThermalManagementCapability(drivePath, out capability, out capabilityError);
        if (capabilityKnown && capability != null && !capability.Supported)
        {
            throw new NotSupportedException("HCTM unsupported on this NVMe controller (HCTMA bit0=0, MNTMT=" + capability.MinimumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + "K, MXTMT=" + capability.MaximumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + "K).");
        }
        ValidateHostControlledThermalManagementTemperatures(thermalManagementTemperature1Celsius, thermalManagementTemperature2Celsius, capabilityKnown ? capability : null);
        uint tmt1 = (uint)(thermalManagementTemperature1Celsius + 273);
        uint tmt2 = (uint)(thermalManagementTemperature2Celsius + 273);
        uint cdw11 = ((tmt1 & 0xFFFFu) << 16) | (tmt2 & 0xFFFFu);
        try
        {
            SetFeature(drivePath, NVME_FEATURE_HOST_CONTROLLED_THERMAL_MANAGEMENT, cdw11);
        }
        catch (Exception ex)
        {
            if (IsHostControlledThermalManagementUnsupportedNvmeFeatureFailure(ex.ToString()))
            {
                throw new NotSupportedException("NVMe HCTM unsupported on this NVMe controller or blocked by Windows StorNVMe for Set Features FID 0x10.", ex);
            }
            throw;
        }
        DeviceTweakerNvmeHostControlledThermalManagementState readBack = GetHostControlledThermalManagement(drivePath);
        if (readBack != null && capabilityKnown && capability != null) { ApplyHostControlledThermalManagementCapability(readBack, capability); }
        return readBack;
    }

