    public static DeviceTweakerNvmeHostMemoryBufferState GetHostMemoryBuffer(string drivePath)
    {
        DeviceTweakerNvmeHostMemoryBufferCapability capability;
        string capabilityError;
        bool capabilityKnown = TryGetHostMemoryBufferCapability(drivePath, out capability, out capabilityError);
        if (capabilityKnown && capability != null && !capability.Supported)
        {
            return BuildUnsupportedHostMemoryBufferState(drivePath, capability);
        }

        string scope;
        byte[] data;
        uint raw;
        try
        {
            raw = GetFeatureData(drivePath, NVME_FEATURE_HOST_MEMORY_BUFFER, NVME_HMB_ATTRIBUTES_DATA_LENGTH, out scope, out data);
        }
        catch (Exception ex)
        {
            if (capabilityKnown && capability != null && !capability.Supported)
            {
                return BuildUnsupportedHostMemoryBufferState(drivePath, capability);
            }
            string suffix = capabilityKnown ? "" : " Identify Controller HMB support probe also failed: " + capabilityError;
            throw new InvalidOperationException("NVMe Host Memory Buffer Get Features failed and the controller was not identified as HMB-unsupported." + suffix + " " + ex.Message, ex);
        }
        uint sizeMps = data != null && data.Length >= 4 ? ReadUInt32(data, 0) : 0u;
        uint descriptorListLower = data != null && data.Length >= 8 ? ReadUInt32(data, 4) : 0u;
        uint descriptorListUpper = data != null && data.Length >= 12 ? ReadUInt32(data, 8) : 0u;
        uint descriptorEntryCount = data != null && data.Length >= 16 ? ReadUInt32(data, 12) : 0u;
        DeviceTweakerNvmeHostMemoryBufferState state = BuildHostMemoryBufferState(drivePath, raw, sizeMps, descriptorListLower, descriptorListUpper, descriptorEntryCount, scope);
        if (capabilityKnown && capability != null) { ApplyHostMemoryBufferCapability(state, capability); }
        else { state.Supported = true; }
        return state;
    }

    public static DeviceTweakerNvmeHostMemoryBufferState SetHostMemoryBuffer(string drivePath, bool enabled, bool memoryReturn, uint sizeMps, uint descriptorListLower, uint descriptorListUpper, uint descriptorEntryCount)
    {
        DeviceTweakerNvmeHostMemoryBufferCapability capability;
        string capabilityError;
        if (TryGetHostMemoryBufferCapability(drivePath, out capability, out capabilityError) && capability != null && !capability.Supported)
        {
            throw new NotSupportedException("HMB unsupported on this NVMe controller (Identify Controller HMPRE=0, HMMIN=" + capability.MinimumSize4KiB.ToString(CultureInfo.InvariantCulture) + ").");
        }
        if (!enabled)
        {
            memoryReturn = false;
            sizeMps = 0u;
            descriptorListLower = 0u;
            descriptorListUpper = 0u;
            descriptorEntryCount = 0u;
        }
        else
        {
            if (sizeMps == 0u) { throw new ArgumentOutOfRangeException("sizeMps", "NVMe HMB enable requires HSIZE greater than zero, in controller MPS units."); }
            if (descriptorEntryCount == 0u) { throw new ArgumentOutOfRangeException("descriptorEntryCount", "NVMe HMB enable requires at least one Host Memory Descriptor List entry."); }
            if ((descriptorListLower & 0xFu) != 0u) { throw new ArgumentOutOfRangeException("descriptorListLower", "NVMe HMB Host Memory Descriptor List address lower dword must be 16-byte aligned; bits 3:0 are reserved and must be zero."); }
        }
        uint cdw11 = (enabled ? 1u : 0u) | (memoryReturn ? 2u : 0u);
        SetFeature(drivePath, NVME_FEATURE_HOST_MEMORY_BUFFER, cdw11, sizeMps, descriptorListLower, descriptorListUpper, descriptorEntryCount);
        DeviceTweakerNvmeHostMemoryBufferState readBack = GetHostMemoryBuffer(drivePath);
        if (readBack != null)
        {
            readBack.SizeMps = sizeMps;
            readBack.DescriptorListLower = descriptorListLower;
            readBack.DescriptorListUpper = descriptorListUpper;
            readBack.DescriptorEntryCount = descriptorEntryCount;
            readBack.DescriptorListAddress = (((ulong)descriptorListUpper) << 32) | (ulong)descriptorListLower;
            readBack.DisplayText = FormatHostMemoryBufferDisplay(readBack.Enabled, readBack.MemoryReturn, sizeMps, descriptorListLower, descriptorListUpper, descriptorEntryCount, readBack.RawValue);
            if (capability != null) { ApplyHostMemoryBufferCapability(readBack, capability); }
        }
        return readBack;
    }

    public static string FormatArbitrationDisplay(int arbitrationBurst, int lowPriorityWeight, int mediumPriorityWeight, int highPriorityWeight)
    {
        int ab = Math.Max(0, Math.Min(7, arbitrationBurst));
        int lpw = Math.Max(0, Math.Min(255, lowPriorityWeight));
        int mpw = Math.Max(0, Math.Min(255, mediumPriorityWeight));
        int hpw = Math.Max(0, Math.Min(255, highPriorityWeight));
        uint raw = ((uint)ab & 0x7u) | (((uint)lpw & 0xFFu) << 8) | (((uint)mpw & 0xFFu) << 16) | (((uint)hpw & 0xFFu) << 24);
        return FormatArbitrationDisplay(ab, lpw, mpw, hpw, raw);
    }

    public static string FormatArbitrationDisplay(int arbitrationBurst, int lowPriorityWeight, int mediumPriorityWeight, int highPriorityWeight, uint raw)
    {
        int ab = Math.Max(0, Math.Min(7, arbitrationBurst));
        int lpw = Math.Max(0, Math.Min(255, lowPriorityWeight));
        int mpw = Math.Max(0, Math.Min(255, mediumPriorityWeight));
        int hpw = Math.Max(0, Math.Min(255, highPriorityWeight));
        string abText = ab == 7 ? "AB=no limit" : "AB=" + ab.ToString(CultureInfo.InvariantCulture) + " (" + (1 << ab).ToString(CultureInfo.InvariantCulture) + " cmds)";
        return abText + " | LPW=" + lpw.ToString(CultureInfo.InvariantCulture) + "→" + (lpw + 1).ToString(CultureInfo.InvariantCulture) + " MPW=" + mpw.ToString(CultureInfo.InvariantCulture) + "→" + (mpw + 1).ToString(CultureInfo.InvariantCulture) + " HPW=" + hpw.ToString(CultureInfo.InvariantCulture) + "→" + (hpw + 1).ToString(CultureInfo.InvariantCulture) + " | raw=0x" + raw.ToString("X8", CultureInfo.InvariantCulture);
    }

    public static string FormatArbitrationUnsupportedDisplay()
    {
        return "ARB Unsupported | FID=0x01";
    }

    public static string FormatNumberOfQueuesDisplay(int submissionQueuesRequested, int completionQueuesRequested, int submissionQueuesAllocated, int completionQueuesAllocated, uint raw)
    {
        string requested = submissionQueuesRequested > 0 || completionQueuesRequested > 0 ? "requested SQ=" + Math.Max(0, submissionQueuesRequested).ToString(CultureInfo.InvariantCulture) + " CQ=" + Math.Max(0, completionQueuesRequested).ToString(CultureInfo.InvariantCulture) + " | " : "";
        return "NOQ " + requested + "allocated SQ=" + Math.Max(0, submissionQueuesAllocated).ToString(CultureInfo.InvariantCulture) + " CQ=" + Math.Max(0, completionQueuesAllocated).ToString(CultureInfo.InvariantCulture) + " | raw=0x" + raw.ToString("X8", CultureInfo.InvariantCulture);
    }

    public static string FormatNumberOfQueuesUnsupportedDisplay()
    {
        return "NOQ Unsupported | FID=0x07";
    }

    public static string FormatInterruptCoalescingDisplay(int thresholdRaw, int timeUnits)
    {
        int thr = Math.Max(0, Math.Min(255, thresholdRaw));
        int time = Math.Max(0, Math.Min(255, timeUnits));
        int timeUs = time * 100;
        if (thr == 0 && time == 0) { return "THR=0 TIME=0 | immediate interrupts"; }
        if (thr == 0 || time == 0) { return "THR=" + thr.ToString(CultureInfo.InvariantCulture) + " TIME=" + time.ToString(CultureInfo.InvariantCulture) + " | coalescing disabled by zero field"; }
        int cqes = thr + 1;
        return "THR raw=" + thr.ToString(CultureInfo.InvariantCulture) + " (~" + cqes.ToString(CultureInfo.InvariantCulture) + " CQEs) TIME=" + time.ToString(CultureInfo.InvariantCulture) + " (" + timeUs.ToString(CultureInfo.InvariantCulture) + " µs)";
    }

