    public static string FormatHostControlledThermalManagementDisplay(bool supported, int thermalManagementTemperature1Kelvin, int thermalManagementTemperature2Kelvin, int minimumTemperatureKelvin, int maximumTemperatureKelvin, uint raw)
    {
