        {
            return FormatHostControlledThermalManagementUnsupportedDisplay(minimumTemperatureKelvin, maximumTemperatureKelvin, 0);
        }
        string range = minimumTemperatureKelvin > 0 || maximumTemperatureKelvin > 0 ? " | range=" + minimumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + ".." + maximumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + "K" : "";
        return "HCTM " + FormatHostControlledThermalManagementTemperature("TMT1", thermalManagementTemperature1Kelvin) + " " + FormatHostControlledThermalManagementTemperature("TMT2", thermalManagementTemperature2Kelvin) + range + " | raw=0x" + raw.ToString("X8", CultureInfo.InvariantCulture);
