    public static string FormatHostMemoryBufferDisplay(bool enabled, bool memoryReturn, uint sizeMps, uint descriptorListLower, uint descriptorListUpper, uint descriptorEntryCount, uint raw)
    {
        string text = "HMB " + (enabled ? "Enabled" : "Disabled") + " | EHM=" + (enabled ? "1" : "0") + " MR=" + (memoryReturn ? "1" : "0") + " | raw=0x" + raw.ToString("X8", CultureInfo.InvariantCulture);
        if (sizeMps != 0u || descriptorListLower != 0u || descriptorListUpper != 0u || descriptorEntryCount != 0u)
        {
            ulong addr = (((ulong)descriptorListUpper) << 32) | (ulong)descriptorListLower;
            text += " | HSIZE=" + sizeMps.ToString(CultureInfo.InvariantCulture) + " MPS | HMDL=0x" + addr.ToString("X16", CultureInfo.InvariantCulture) + " | EC=" + descriptorEntryCount.ToString(CultureInfo.InvariantCulture);
        }
        return text;
    }

    public static string FormatTemperatureSensorSelect(int sensorSelect)
    {
        if (sensorSelect == 0) { return "Composite"; }
        if (sensorSelect >= 1 && sensorSelect <= 8) { return "Sensor " + sensorSelect.ToString(CultureInfo.InvariantCulture); }
        return "Reserved sensor " + sensorSelect.ToString(CultureInfo.InvariantCulture);
    }

    public static string FormatTemperatureThresholdType(int thresholdType)
    {
        if (thresholdType == 0) { return "Over"; }
        if (thresholdType == 1) { return "Under"; }
        return "Reserved THSEL " + thresholdType.ToString(CultureInfo.InvariantCulture);
    }

    private static string FormatHostControlledThermalManagementTemperature(string label, int kelvin)
    {
        if (kelvin <= 0) { return label + "=disabled"; }
        return label + "=" + (kelvin - 273).ToString(CultureInfo.InvariantCulture) + "°C (" + kelvin.ToString(CultureInfo.InvariantCulture) + "K)";
    }

    public static string FormatAutonomousPowerStateTransitionDisplay(bool enabled, int activeEntryCount, DeviceTweakerNvmeAutonomousPowerStateTransitionEntry[] entries, uint raw)
    {
        string state = enabled ? "APST Enabled" : "APST Disabled";
        string text = state + " | " + activeEntryCount.ToString(CultureInfo.InvariantCulture) + " active entries | raw=0x" + raw.ToString("X8", CultureInfo.InvariantCulture);
        if (entries == null || activeEntryCount <= 0) { return text; }
        List<string> samples = new List<string>();
        for (int i = 0; i < entries.Length && samples.Count < 3; i++)
        {
            DeviceTweakerNvmeAutonomousPowerStateTransitionEntry e = entries[i];
            if (e != null && e.Enabled) { samples.Add("PS" + e.PowerState.ToString(CultureInfo.InvariantCulture) + "→PS" + e.IdleTransitionPowerState.ToString(CultureInfo.InvariantCulture) + " after " + e.IdleTimeMilliseconds.ToString(CultureInfo.InvariantCulture) + " ms"); }
        }
        if (samples.Count > 0) { text += " | " + String.Join(", ", samples.ToArray()); }
        return text;
    }

    private static DeviceTweakerNvmeArbitrationState BuildArbitrationState(string drivePath, uint raw, string scope)
    {
        int ab = (int)(raw & 0x7u);
        int lpw = (int)((raw >> 8) & 0xFFu);
        int mpw = (int)((raw >> 16) & 0xFFu);
        int hpw = (int)((raw >> 24) & 0xFFu);
        DeviceTweakerNvmeArbitrationState state = new DeviceTweakerNvmeArbitrationState();
        state.DrivePath = drivePath;
        state.Supported = true;
        state.RawValue = raw;
        state.ArbitrationBurst = ab;
        state.ArbitrationBurstCommandLimit = ab == 7 ? 0 : (1 << ab);
        state.NoLimit = ab == 7;
        state.LowPriorityWeight = lpw;
        state.MediumPriorityWeight = mpw;
        state.HighPriorityWeight = hpw;
        state.LowPriorityCommands = lpw + 1;
        state.MediumPriorityCommands = mpw + 1;
        state.HighPriorityCommands = hpw + 1;
        state.Scope = scope;
        state.DisplayText = FormatArbitrationDisplay(ab, lpw, mpw, hpw, raw);
        return state;
    }

    private static DeviceTweakerNvmeArbitrationState BuildUnsupportedArbitrationState(string drivePath, string scope)
    {
        DeviceTweakerNvmeArbitrationState state = new DeviceTweakerNvmeArbitrationState();
        state.DrivePath = drivePath;
        state.Supported = false;
        state.RawValue = 0u;
        state.ArbitrationBurst = 7;
        state.ArbitrationBurstCommandLimit = 0;
        state.NoLimit = true;
        state.LowPriorityWeight = 0;
        state.MediumPriorityWeight = 0;
        state.HighPriorityWeight = 0;
        state.LowPriorityCommands = 1;
        state.MediumPriorityCommands = 1;
        state.HighPriorityCommands = 1;
        state.Scope = String.IsNullOrWhiteSpace(scope) ? "Unsupported" : scope;
        state.DisplayText = FormatArbitrationUnsupportedDisplay();
        return state;
    }

    private static DeviceTweakerNvmeNumberOfQueuesState BuildNumberOfQueuesState(string drivePath, uint raw, int submissionQueuesRequested, int completionQueuesRequested, string scope)
    {
        int nsqRaw = (int)(raw & 0xFFFFu);
        int ncqRaw = (int)((raw >> 16) & 0xFFFFu);
        int allocatedSq = nsqRaw + 1;
        int allocatedCq = ncqRaw + 1;
        DeviceTweakerNvmeNumberOfQueuesState state = new DeviceTweakerNvmeNumberOfQueuesState();
        state.DrivePath = drivePath;
        state.Supported = true;
        state.RawValue = raw;
        state.SubmissionQueuesRaw = nsqRaw;
        state.CompletionQueuesRaw = ncqRaw;
        state.SubmissionQueuesAllocated = allocatedSq;
        state.CompletionQueuesAllocated = allocatedCq;
        state.SubmissionQueuesRequested = Math.Max(0, submissionQueuesRequested);
        state.CompletionQueuesRequested = Math.Max(0, completionQueuesRequested);
        state.Scope = scope;
        state.DisplayText = FormatNumberOfQueuesDisplay(submissionQueuesRequested, completionQueuesRequested, allocatedSq, allocatedCq, raw);
        return state;
    }

    private static DeviceTweakerNvmeNumberOfQueuesState BuildUnsupportedNumberOfQueuesState(string drivePath, int submissionQueuesRequested, int completionQueuesRequested, string scope)
    {
        DeviceTweakerNvmeNumberOfQueuesState state = new DeviceTweakerNvmeNumberOfQueuesState();
        state.DrivePath = drivePath;
        state.Supported = false;
        state.RawValue = 0u;
        state.SubmissionQueuesRaw = 0;
        state.CompletionQueuesRaw = 0;
        state.SubmissionQueuesAllocated = 0;
        state.CompletionQueuesAllocated = 0;
        state.SubmissionQueuesRequested = Math.Max(0, submissionQueuesRequested);
        state.CompletionQueuesRequested = Math.Max(0, completionQueuesRequested);
        state.Scope = String.IsNullOrWhiteSpace(scope) ? "Unsupported" : scope;
        state.DisplayText = FormatNumberOfQueuesUnsupportedDisplay();
        return state;
    }

    private static DeviceTweakerNvmeInterruptCoalescingState BuildInterruptCoalescingState(string drivePath, uint raw, string scope)
    {
        int thr = (int)(raw & 0xFFu);
        int time = (int)((raw >> 8) & 0xFFu);
        DeviceTweakerNvmeInterruptCoalescingState state = new DeviceTweakerNvmeInterruptCoalescingState();
        state.DrivePath = drivePath;
        state.Supported = true;
        state.RawValue = raw;
        state.ThresholdRaw = thr;
        state.CompletionThreshold = thr == 0 ? 0 : thr + 1;
        state.TimeUnits = time;
        state.TimeMicroseconds = time * 100;
        state.ImplicitlyDisabled = thr == 0 || time == 0;
        state.Scope = scope;
        state.DisplayText = FormatInterruptCoalescingDisplay(thr, time);
        return state;
    }

