    private static DeviceTweakerNvmeHostControlledThermalManagementCapability BuildHostControlledThermalManagementCapability(string drivePath, byte[] identify, string scope)
    {
        ushort hctma = identify != null && identify.Length >= NVME_IDENTIFY_HCTMA_OFFSET + 2 ? ReadUInt16(identify, NVME_IDENTIFY_HCTMA_OFFSET) : (ushort)0;
        ushort mntmt = identify != null && identify.Length >= NVME_IDENTIFY_MNTMT_OFFSET + 2 ? ReadUInt16(identify, NVME_IDENTIFY_MNTMT_OFFSET) : (ushort)0;
        ushort mxtmt = identify != null && identify.Length >= NVME_IDENTIFY_MXTMT_OFFSET + 2 ? ReadUInt16(identify, NVME_IDENTIFY_MXTMT_OFFSET) : (ushort)0;
        DeviceTweakerNvmeHostControlledThermalManagementCapability capability = new DeviceTweakerNvmeHostControlledThermalManagementCapability();
        capability.DrivePath = drivePath;
        capability.Attributes = hctma;
        capability.MinimumTemperatureKelvin = (int)mntmt;
        capability.MaximumTemperatureKelvin = (int)mxtmt;
        capability.Supported = (hctma & 1) != 0;
        capability.Scope = scope;
        capability.DisplayText = capability.Supported
            ? "HCTM supported | HCTMA=0x" + hctma.ToString("X4", CultureInfo.InvariantCulture) + " | MNTMT=" + mntmt.ToString(CultureInfo.InvariantCulture) + "K | MXTMT=" + mxtmt.ToString(CultureInfo.InvariantCulture) + "K"
            : FormatHostControlledThermalManagementUnsupportedDisplay(mntmt, mxtmt, hctma);
        return capability;
    }

    private static bool TryGetHostControlledThermalManagementCapability(string drivePath, out DeviceTweakerNvmeHostControlledThermalManagementCapability capability, out string error)
    {
        capability = null;
        error = String.Empty;
        try
        {
            capability = GetHostControlledThermalManagementCapability(drivePath);
            return true;
        }
        catch (Exception ex)
        {
            error = ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static DeviceTweakerNvmeHostControlledThermalManagementState BuildUnsupportedHostControlledThermalManagementState(string drivePath, DeviceTweakerNvmeHostControlledThermalManagementCapability capability)
    {
        return BuildUnsupportedHostControlledThermalManagementState(drivePath, capability, null);
    }

    private static DeviceTweakerNvmeHostControlledThermalManagementState BuildUnsupportedHostControlledThermalManagementState(string drivePath, DeviceTweakerNvmeHostControlledThermalManagementCapability capability, string scopeOverride)
    {
        string scope = !String.IsNullOrWhiteSpace(scopeOverride) ? scopeOverride : (capability == null ? "Unsupported" : capability.Scope);
        DeviceTweakerNvmeHostControlledThermalManagementState state = BuildHostControlledThermalManagementState(drivePath, 0u, scope);
        state.Supported = false;
        if (capability != null)
        {
            state.MinimumTemperatureKelvin = capability.MinimumTemperatureKelvin;
            state.MaximumTemperatureKelvin = capability.MaximumTemperatureKelvin;
            state.Attributes = capability.Attributes;
        }
        state.DisplayText = FormatHostControlledThermalManagementUnsupportedDisplay(state.MinimumTemperatureKelvin, state.MaximumTemperatureKelvin, state.Attributes);
        return state;
    }

    private static void ApplyHostControlledThermalManagementCapability(DeviceTweakerNvmeHostControlledThermalManagementState state, DeviceTweakerNvmeHostControlledThermalManagementCapability capability)
    {
        if (state == null || capability == null) { return; }
        state.Supported = capability.Supported;
        state.MinimumTemperatureKelvin = capability.MinimumTemperatureKelvin;
        state.MaximumTemperatureKelvin = capability.MaximumTemperatureKelvin;
        state.Attributes = capability.Attributes;
        state.DisplayText = FormatHostControlledThermalManagementDisplay(capability.Supported, state.ThermalManagementTemperature1Kelvin, state.ThermalManagementTemperature2Kelvin, capability.MinimumTemperatureKelvin, capability.MaximumTemperatureKelvin, state.RawValue);
        if (!capability.Supported) { state.DisplayText = FormatHostControlledThermalManagementUnsupportedDisplay(capability.MinimumTemperatureKelvin, capability.MaximumTemperatureKelvin, capability.Attributes); }
    }

    private static bool TryGetVolatileWriteCacheSupport(string drivePath, out bool supported, out byte attributes, out string scope, out string error)
    {
        supported = false;
        attributes = 0;
        scope = String.Empty;
        error = String.Empty;
        try
        {
            byte[] identify;
            string localError;
            if (!TryGetIdentifyControllerData(drivePath, out scope, out identify, out localError))
            {
                error = localError;
                return false;
            }
            if (identify == null || identify.Length <= NVME_IDENTIFY_VWC_OFFSET)
            {
                error = "NVMe Identify Controller data did not include byte 525 (VWC) for " + drivePath + ".";
                return false;
            }
            attributes = identify[NVME_IDENTIFY_VWC_OFFSET];
            supported = (attributes & 0x1) != 0;
            return true;
        }
        catch (Exception ex)
        {
            error = ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static DeviceTweakerNvmeHostMemoryBufferCapability BuildHostMemoryBufferCapability(string drivePath, byte[] identify, string scope)
    {
        uint hmpre = identify != null && identify.Length >= NVME_IDENTIFY_HMPRE_OFFSET + 4 ? ReadUInt32(identify, NVME_IDENTIFY_HMPRE_OFFSET) : 0u;
        uint hmmin = identify != null && identify.Length >= NVME_IDENTIFY_HMMIN_OFFSET + 4 ? ReadUInt32(identify, NVME_IDENTIFY_HMMIN_OFFSET) : 0u;
        DeviceTweakerNvmeHostMemoryBufferCapability capability = new DeviceTweakerNvmeHostMemoryBufferCapability();
        capability.DrivePath = drivePath;
        capability.Supported = hmpre != 0u;
        capability.PreferredSize4KiB = hmpre;
        capability.MinimumSize4KiB = hmmin;
        capability.Scope = scope;
        capability.DisplayText = capability.Supported
            ? "HMB supported | HMPRE=" + hmpre.ToString(CultureInfo.InvariantCulture) + " x4KiB | HMMIN=" + hmmin.ToString(CultureInfo.InvariantCulture) + " x4KiB"
            : "HMB unsupported | HMPRE=0 | HMMIN=" + hmmin.ToString(CultureInfo.InvariantCulture) + " x4KiB";
        return capability;
    }

    private static bool TryGetHostMemoryBufferCapability(string drivePath, out DeviceTweakerNvmeHostMemoryBufferCapability capability, out string error)
    {
