    private static DeviceTweakerNvmeHostMemoryBufferState BuildUnsupportedHostMemoryBufferState(string drivePath, DeviceTweakerNvmeHostMemoryBufferCapability capability)
    {
        DeviceTweakerNvmeHostMemoryBufferState state = BuildHostMemoryBufferState(drivePath, 0u, 0u, 0u, 0u, 0u, capability == null ? "Identify" : capability.Scope);
        state.Supported = false;
        if (capability != null)
        {
            state.PreferredSize4KiB = capability.PreferredSize4KiB;
            state.MinimumSize4KiB = capability.MinimumSize4KiB;
        }
        state.DisplayText = "HMB unsupported | HMPRE=0 | HMMIN=" + state.MinimumSize4KiB.ToString(CultureInfo.InvariantCulture) + " x4KiB";
        return state;
    }

    private static void ApplyHostMemoryBufferCapability(DeviceTweakerNvmeHostMemoryBufferState state, DeviceTweakerNvmeHostMemoryBufferCapability capability)
    {
        if (state == null || capability == null) { return; }
        state.Supported = capability.Supported;
        state.PreferredSize4KiB = capability.PreferredSize4KiB;
        state.MinimumSize4KiB = capability.MinimumSize4KiB;
        if (!capability.Supported) { state.DisplayText = "HMB unsupported | HMPRE=0 | HMMIN=" + capability.MinimumSize4KiB.ToString(CultureInfo.InvariantCulture) + " x4KiB"; }
    }

    private static DeviceTweakerNvmeHostMemoryBufferState BuildHostMemoryBufferState(string drivePath, uint raw, uint sizeMps, uint descriptorListLower, uint descriptorListUpper, uint descriptorEntryCount, string scope)
    {
        bool enabled = (raw & 1u) != 0u;
        bool memoryReturn = (raw & 2u) != 0u;
        DeviceTweakerNvmeHostMemoryBufferState state = new DeviceTweakerNvmeHostMemoryBufferState();
        state.DrivePath = drivePath;
        state.RawValue = raw;
        state.Supported = true;
        state.Enabled = enabled;
        state.MemoryReturn = memoryReturn;
        state.SizeMps = sizeMps;
        state.DescriptorListLower = descriptorListLower;
        state.DescriptorListUpper = descriptorListUpper;
        state.DescriptorEntryCount = descriptorEntryCount;
        state.DescriptorListAddress = (((ulong)descriptorListUpper) << 32) | (ulong)descriptorListLower;
        state.Scope = scope;
        state.DisplayText = FormatHostMemoryBufferDisplay(enabled, memoryReturn, sizeMps, descriptorListLower, descriptorListUpper, descriptorEntryCount, raw);
        return state;
    }

    private static void ValidateTemperatureThresholdSelectors(int sensorSelect, int thresholdType)
    {
        if (sensorSelect < 0 || sensorSelect > 8) { throw new ArgumentOutOfRangeException("sensorSelect", "NVMe temperature TMPSEL must be Composite 0 or Sensor 1..8 for read/write with immediate read-back."); }
        if (thresholdType < 0 || thresholdType > 1) { throw new ArgumentOutOfRangeException("thresholdType", "NVMe temperature THSEL must be 0 for over-temperature or 1 for under-temperature."); }
    }

    private static void ValidateErrorRecoveryNamespaceId(uint namespaceId)
    {
        if (namespaceId == 0u || namespaceId >= 0xFFFFFFFEu) { throw new ArgumentOutOfRangeException("namespaceId", "NVMe Error Recovery is namespace-specific; use an active namespace ID in 1..0xFFFFFFFD for read/write read-back."); }
    }

    private static void ValidateHostControlledThermalManagementTemperatures(int thermalManagementTemperature1Celsius, int thermalManagementTemperature2Celsius, DeviceTweakerNvmeHostControlledThermalManagementCapability capability)
    {
        if (thermalManagementTemperature1Celsius < -273 || thermalManagementTemperature1Celsius > 65262) { throw new ArgumentOutOfRangeException("thermalManagementTemperature1Celsius", "NVMe HCTM TMT1 must convert to a 16-bit Kelvin value; valid Celsius range is -273..65262. Use -273°C to encode disabled/0K."); }
        if (thermalManagementTemperature2Celsius < -273 || thermalManagementTemperature2Celsius > 65262) { throw new ArgumentOutOfRangeException("thermalManagementTemperature2Celsius", "NVMe HCTM TMT2 must convert to a 16-bit Kelvin value; valid Celsius range is -273..65262. Use -273°C to encode disabled/0K."); }
        int tmt1 = thermalManagementTemperature1Celsius + 273;
        int tmt2 = thermalManagementTemperature2Celsius + 273;
        if (capability != null && capability.Supported && capability.MinimumTemperatureKelvin > 0 && capability.MaximumTemperatureKelvin > 0 && capability.MinimumTemperatureKelvin <= capability.MaximumTemperatureKelvin)
        {
            if (tmt1 != 0 && (tmt1 < capability.MinimumTemperatureKelvin || tmt1 > capability.MaximumTemperatureKelvin)) { throw new ArgumentOutOfRangeException("thermalManagementTemperature1Celsius", "NVMe HCTM TMT1 " + tmt1.ToString(CultureInfo.InvariantCulture) + "K is outside controller range " + capability.MinimumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + ".." + capability.MaximumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + "K."); }
            if (tmt2 != 0 && (tmt2 < capability.MinimumTemperatureKelvin || tmt2 > capability.MaximumTemperatureKelvin)) { throw new ArgumentOutOfRangeException("thermalManagementTemperature2Celsius", "NVMe HCTM TMT2 " + tmt2.ToString(CultureInfo.InvariantCulture) + "K is outside controller range " + capability.MinimumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + ".." + capability.MaximumTemperatureKelvin.ToString(CultureInfo.InvariantCulture) + "K."); }
        }
        if (tmt1 != 0 && tmt2 != 0 && tmt1 >= tmt2) { throw new ArgumentException("NVMe HCTM requires non-zero TMT1 to be less than non-zero TMT2."); }
    }

    private static DeviceTweakerNvmeAutonomousPowerStateTransitionState BuildAutonomousPowerStateTransitionState(string drivePath, uint raw, byte[] data, string scope)
    {
        DeviceTweakerNvmeAutonomousPowerStateTransitionEntry[] entries = new DeviceTweakerNvmeAutonomousPowerStateTransitionEntry[32];
        int active = 0;
        if (data == null) { data = new byte[0]; }
        for (int i = 0; i < entries.Length; i++)
        {
            int off = i * 8;
            uint low = off + 4 <= data.Length ? ReadUInt32(data, off) : 0u;
            uint high = off + 8 <= data.Length ? ReadUInt32(data, off + 4) : 0u;
            int itps = (int)((low >> 3) & 0x1Fu);
            int itpt = (int)((low >> 8) & 0x00FFFFFFu);
            bool enabled = itpt != 0;
            if (enabled) { active++; }
            DeviceTweakerNvmeAutonomousPowerStateTransitionEntry entry = new DeviceTweakerNvmeAutonomousPowerStateTransitionEntry();
            entry.PowerState = i;
            entry.IdleTransitionPowerState = itps;
            entry.IdleTimeMilliseconds = itpt;
            entry.Enabled = enabled;
            entry.RawLow = low;
            entry.RawHigh = high;
            entry.DisplayText = enabled ? "PS" + i.ToString(CultureInfo.InvariantCulture) + "→PS" + itps.ToString(CultureInfo.InvariantCulture) + " after " + itpt.ToString(CultureInfo.InvariantCulture) + " ms" : "PS" + i.ToString(CultureInfo.InvariantCulture) + " disabled";
            entries[i] = entry;
        }
        DeviceTweakerNvmeAutonomousPowerStateTransitionState state = new DeviceTweakerNvmeAutonomousPowerStateTransitionState();
        state.DrivePath = drivePath;
        state.RawValue = raw;
        state.Enabled = (raw & 1u) != 0u;
        state.ActiveEntryCount = active;
        state.Entries = entries;
        state.Scope = scope;
        state.DisplayText = FormatAutonomousPowerStateTransitionDisplay(state.Enabled, active, entries, raw);
        return state;
    }

    private static uint GetFeatureFixedData(string drivePath, uint featureId, out string scope)
    {
        return GetFeatureFixedData(drivePath, featureId, 0u, out scope);
    }

    private static uint GetFeatureFixedData(string drivePath, uint featureId, uint requestSubValue, out string scope)
    {
        if (String.IsNullOrWhiteSpace(drivePath)) { throw new ArgumentException("NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.", "drivePath"); }
        uint[] properties = new uint[] { StorageAdapterProtocolSpecificProperty, StorageDeviceProtocolSpecificProperty };
        string[] labels = new string[] { "Adapter", "Device" };
        List<string> failures = new List<string>();
        for (int i = 0; i < properties.Length; i++)
        {
            uint fixedData;
            string error;
            if (TryGetFeatureFixedData(drivePath, featureId, requestSubValue, properties[i], labels[i], out fixedData, out error))
            {
                scope = labels[i];
                return fixedData;
            }
            failures.Add(error);
        }
        bool[] adapterRequests = new bool[] { false, true };
        for (int i = 0; i < adapterRequests.Length; i++)
        {
            uint fixedData;
            string error;
            if (TryGetFeatureFixedDataViaProtocolCommand(drivePath, featureId, 0u, requestSubValue, adapterRequests[i], out fixedData, out error))
            {
                scope = adapterRequests[i] ? "ProtocolCommandAdapter" : "ProtocolCommandDevice";
                return fixedData;
            }
            failures.Add(error);
        }
        throw new InvalidOperationException("NVMe Get Features failed for Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " on " + drivePath + " with CDW11 request subvalue=0x" + requestSubValue.ToString("X8", CultureInfo.InvariantCulture) + ". " + String.Join(" | ", failures.ToArray()));
    }

    private static uint GetFeatureData(string drivePath, uint featureId, int dataLength, out string scope, out byte[] data)
    {
        if (String.IsNullOrWhiteSpace(drivePath)) { throw new ArgumentException("NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.", "drivePath"); }
        if (dataLength < 0 || dataLength > 4096) { throw new ArgumentOutOfRangeException("dataLength", "NVMe feature data length must be in 0..4096 bytes."); }
        uint[] properties = new uint[] { StorageAdapterProtocolSpecificProperty, StorageDeviceProtocolSpecificProperty };
        string[] labels = new string[] { "Adapter", "Device" };
        List<string> failures = new List<string>();
        for (int i = 0; i < properties.Length; i++)
        {
            uint fixedData;
            byte[] payload;
            string error;
            if (TryGetFeatureData(drivePath, featureId, dataLength, properties[i], labels[i], out fixedData, out payload, out error))
            {
                scope = labels[i];
                data = payload;
                return fixedData;
            }
            failures.Add(error);
        }
        data = new byte[0];
        throw new InvalidOperationException("NVMe Get Features data read failed for Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " on " + drivePath + " dataLength=" + dataLength.ToString(CultureInfo.InvariantCulture) + ". " + String.Join(" | ", failures.ToArray()));
    }

    private static uint GetFeatureFixedDataNsid(string drivePath, uint featureId, uint namespaceId, uint requestSubValue, out string scope)
    {
        if (String.IsNullOrWhiteSpace(drivePath)) { throw new ArgumentException("NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.", "drivePath"); }
        List<string> failures = new List<string>();
        bool[] adapterRequests = new bool[] { false, true };
        for (int i = 0; i < adapterRequests.Length; i++)
        {
            uint fixedData;
            string error;
            if (TryGetFeatureFixedDataViaProtocolCommand(drivePath, featureId, namespaceId, requestSubValue, adapterRequests[i], out fixedData, out error))
            {
                scope = adapterRequests[i] ? "ProtocolCommandAdapter" : "ProtocolCommandDevice";
                return fixedData;
            }
            failures.Add(error);
        }
        throw new InvalidOperationException("NVMe Get Features failed for namespace-specific Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " on " + drivePath + " NSID=0x" + namespaceId.ToString("X8", CultureInfo.InvariantCulture) + " CDW11 request subvalue=0x" + requestSubValue.ToString("X8", CultureInfo.InvariantCulture) + ". " + String.Join(" | ", failures.ToArray()));
    }

    private static void SetFeatureNsid(string drivePath, uint featureId, uint namespaceId, uint cdw11)
    {
        if (String.IsNullOrWhiteSpace(drivePath)) { throw new ArgumentException("NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.", "drivePath"); }
        List<string> failures = new List<string>();
        bool[] adapterRequests = new bool[] { false, true };
        for (int i = 0; i < adapterRequests.Length; i++)
        {
            string error;
            if (TrySetFeatureViaProtocolCommand(drivePath, featureId, namespaceId, cdw11, 0u, 0u, 0u, 0u, adapterRequests[i], out error)) { return; }
            failures.Add(error);
        }
        throw new InvalidOperationException("NVMe Set Features failed for namespace-specific Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " on " + drivePath + " NSID=0x" + namespaceId.ToString("X8", CultureInfo.InvariantCulture) + " CDW11=0x" + cdw11.ToString("X8", CultureInfo.InvariantCulture) + ". " + String.Join(" | ", failures.ToArray()));
    }

    private static void SetFeature(string drivePath, uint featureId, uint cdw11)
    {
        SetFeature(drivePath, featureId, cdw11, null);
    }

    private static void SetFeature(string drivePath, uint featureId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15)
    {
        SetFeature(drivePath, featureId, cdw11, cdw12, cdw13, cdw14, cdw15, null);
    }

    private static void SetFeature(string drivePath, uint featureId, uint cdw11, byte[] data)
    {
        SetFeature(drivePath, featureId, cdw11, 0u, 0u, 0u, 0u, data);
    }

    private static void SetFeature(string drivePath, uint featureId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, byte[] data)
    {
        string scope;
        SetFeatureFixedData(drivePath, featureId, cdw11, cdw12, cdw13, cdw14, cdw15, data, out scope);
    }

    private static uint SetFeatureFixedData(string drivePath, uint featureId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, byte[] data, out string scope)
    {
        if (String.IsNullOrWhiteSpace(drivePath)) { throw new ArgumentException("NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.", "drivePath"); }
        scope = String.Empty;
        List<string> failures = new List<string>();
        string error;
        uint fixedData;
        uint[] properties = new uint[] { StorageAdapterProtocolSpecificProperty, StorageDeviceProtocolSpecificProperty };
        string[] labels = new string[] { "Adapter", "Device" };
        for (int i = 0; i < properties.Length; i++)
        {
            if (TrySetFeatureViaStorageProperty(drivePath, featureId, cdw11, cdw12, cdw13, cdw14, cdw15, data, properties[i], labels[i], out fixedData, out error))
            {
                scope = labels[i];
                return fixedData;
            }
            failures.Add(error);
        }
        int bytes = data == null ? 0 : data.Length;
        if (bytes == 0)
        {
            bool[] adapterRequests = new bool[] { false, true };
            for (int i = 0; i < adapterRequests.Length; i++)
            {
                if (TrySetFeatureViaProtocolCommand(drivePath, featureId, 0u, cdw11, cdw12, cdw13, cdw14, cdw15, adapterRequests[i], out fixedData, out error))
                {
                    scope = adapterRequests[i] ? "ProtocolCommandAdapter" : "ProtocolCommandDevice";
                    return fixedData;
                }
                failures.Add(error);
            }
        }
        else
        {
            failures.Add("ProtocolCommand fallback skipped for Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " because this path intentionally supports only no-payload Set Features commands; payload-bearing Set Features must use IOCTL_STORAGE_SET_PROPERTY.");
        }
        throw new InvalidOperationException("NVMe Set Features failed for Feature ID 0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " on " + drivePath + " with CDW11=0x" + cdw11.ToString("X8", CultureInfo.InvariantCulture) + " CDW12=0x" + cdw12.ToString("X8", CultureInfo.InvariantCulture) + " CDW13=0x" + cdw13.ToString("X8", CultureInfo.InvariantCulture) + " CDW14=0x" + cdw14.ToString("X8", CultureInfo.InvariantCulture) + " CDW15=0x" + cdw15.ToString("X8", CultureInfo.InvariantCulture) + " dataLength=" + bytes.ToString(CultureInfo.InvariantCulture) + " attemptedScopes=" + failures.Count.ToString(CultureInfo.InvariantCulture) + ". " + String.Join(" | ", failures.ToArray()));
    }

    private static bool TryGetIdentifyControllerData(string drivePath, out string scope, out byte[] identify, out string error)
    {
        scope = String.Empty;
        identify = new byte[0];
        error = String.Empty;
        if (String.IsNullOrWhiteSpace(drivePath))
        {
            error = "NVMe drive path is empty; expected a Win32 physical-drive path such as \\\\.\\PhysicalDrive0.";
            return false;
        }
        uint[] properties = new uint[] { StorageAdapterProtocolSpecificProperty, StorageDeviceProtocolSpecificProperty };
        string[] labels = new string[] { "Adapter", "Device" };
        List<string> failures = new List<string>();
        for (int i = 0; i < properties.Length; i++)
        {
            byte[] data;
            string localError;
            if (TryGetIdentifyControllerData(drivePath, properties[i], labels[i], out data, out localError))
            {
                scope = labels[i];
                identify = data;
                return true;
            }
            failures.Add(localError);
        }
        error = String.Join(" | ", failures.ToArray());
        return false;
    }

    private static bool TryGetIdentifyControllerData(string drivePath, uint propertyId, string scopeLabel, out byte[] identify, out string error)
    {
        identify = new byte[NVME_IDENTIFY_CONTROLLER_DATA_LENGTH];
        error = String.Empty;
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, false))
            {
                int dataLength = NVME_IDENTIFY_CONTROLLER_DATA_LENGTH;
                byte[] buffer = new byte[STORAGE_PROPERTY_HEADER_SIZE + STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE + dataLength];
                WriteUInt32(buffer, 0, propertyId);
                WriteUInt32(buffer, 4, PropertyStandardQuery);
                int p = STORAGE_PROPERTY_HEADER_SIZE;
                WriteUInt32(buffer, p + 0, ProtocolTypeNvme);
                WriteUInt32(buffer, p + 4, NVMeDataTypeIdentify);
                WriteUInt32(buffer, p + 8, NVME_IDENTIFY_CNS_CONTROLLER);
                WriteUInt32(buffer, p + 12, 0u);
                WriteUInt32(buffer, p + 16, STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE);
                WriteUInt32(buffer, p + 20, (uint)dataLength);
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_QUERY_PROPERTY, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatWin32IoctlError("Identify", drivePath, scopeLabel, propertyId, NVME_IDENTIFY_CNS_CONTROLLER, 0u, err);
                    return false;
                }
                if (bytesReturned <= 0)
                {
                    error = "NVMe Identify Controller returned no protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + ". bytes=0";
                    return false;
                }
                if (bytesReturned < FIXED_RETURN_DATA_OFFSET + 4)
                {
                    error = "NVMe Identify Controller returned a truncated protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " expectedAtLeast=" + (FIXED_RETURN_DATA_OFFSET + 4).ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                uint returnedOffset = ReadUInt32(buffer, p + 16);
                uint returnedLength = ReadUInt32(buffer, p + 20);
                long payloadStart = (long)p + (long)returnedOffset;
                long payloadEnd = payloadStart + (long)dataLength;
                if (returnedOffset < STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE || payloadStart < 0 || payloadStart > buffer.Length)
                {
                    error = "NVMe Identify Controller returned invalid ProtocolDataOffset=" + returnedOffset.ToString(CultureInfo.InvariantCulture) + " for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " descriptorBase=" + p.ToString(CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " bufferLength=" + buffer.Length.ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                if (returnedLength < dataLength || payloadEnd > buffer.Length)
                {
                    error = "NVMe Identify Controller returned insufficient payload for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " offset=" + returnedOffset.ToString(CultureInfo.InvariantCulture) + " descriptorBase=" + p.ToString(CultureInfo.InvariantCulture) + " length=" + returnedLength.ToString(CultureInfo.InvariantCulture) + " expected=" + dataLength.ToString(CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " bufferLength=" + buffer.Length.ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                identify = new byte[dataLength];
                Buffer.BlockCopy(buffer, (int)payloadStart, identify, 0, dataLength);
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Identify Controller scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static bool TryGetFeatureFixedData(string drivePath, uint featureId, uint requestSubValue, uint propertyId, string scopeLabel, out uint fixedData, out string error)
    {
        fixedData = 0;
        error = String.Empty;
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, false))
            {
                byte[] buffer = new byte[STORAGE_PROPERTY_HEADER_SIZE + STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE + NVME_PROTOCOL_SCRATCH_SIZE];
                WriteUInt32(buffer, 0, propertyId);
                WriteUInt32(buffer, 4, PropertyStandardQuery);
                int p = STORAGE_PROPERTY_HEADER_SIZE;
                WriteUInt32(buffer, p + 0, ProtocolTypeNvme);
                WriteUInt32(buffer, p + 4, NVMeDataTypeFeature);
                WriteUInt32(buffer, p + 8, featureId);
                WriteUInt32(buffer, p + 12, requestSubValue);
                WriteUInt32(buffer, p + 16, 0);
                WriteUInt32(buffer, p + 20, 0);
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_QUERY_PROPERTY, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatWin32IoctlError("Get", drivePath, scopeLabel, propertyId, featureId, requestSubValue, err);
                    return false;
                }
                if (bytesReturned <= 0)
                {
                    error = "NVMe Get Features returned no protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + ". bytes=0";
                    return false;
                }
                if (bytesReturned < FIXED_RETURN_DATA_OFFSET + 4)
                {
                    error = "NVMe Get Features returned a truncated protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " expectedAtLeast=" + (FIXED_RETURN_DATA_OFFSET + 4).ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                fixedData = ReadUInt32(buffer, FIXED_RETURN_DATA_OFFSET);
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Get Features scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static bool TryGetFeatureData(string drivePath, uint featureId, int dataLength, uint propertyId, string scopeLabel, out uint fixedData, out byte[] payload, out string error)
    {
        fixedData = 0;
        payload = new byte[Math.Max(0, dataLength)];
        error = String.Empty;
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, false))
            {
                int requestLength = Math.Max(Math.Max(dataLength, 0), NVME_PROTOCOL_SCRATCH_SIZE);
                byte[] buffer = new byte[STORAGE_PROPERTY_HEADER_SIZE + STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE + requestLength];
                WriteUInt32(buffer, 0, propertyId);
                WriteUInt32(buffer, 4, PropertyStandardQuery);
                int p = STORAGE_PROPERTY_HEADER_SIZE;
                WriteUInt32(buffer, p + 0, ProtocolTypeNvme);
                WriteUInt32(buffer, p + 4, NVMeDataTypeFeature);
                WriteUInt32(buffer, p + 8, featureId);
                WriteUInt32(buffer, p + 12, 0);
                WriteUInt32(buffer, p + 16, STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE);
                WriteUInt32(buffer, p + 20, (uint)requestLength);
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_QUERY_PROPERTY, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatWin32IoctlError("GetData", drivePath, scopeLabel, propertyId, featureId, 0, err);
                    return false;
                }
                if (bytesReturned <= 0)
                {
                    error = "NVMe Get Features data returned no protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " requestedPayload=" + dataLength.ToString(CultureInfo.InvariantCulture) + ". bytes=0";
                    return false;
                }
                if (bytesReturned < FIXED_RETURN_DATA_OFFSET + 4)
                {
                    error = "NVMe Get Features data returned a truncated protocol descriptor for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " expectedAtLeast=" + (FIXED_RETURN_DATA_OFFSET + 4).ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                fixedData = ReadUInt32(buffer, FIXED_RETURN_DATA_OFFSET);
                if (dataLength <= 0) { payload = new byte[0]; return true; }
                uint returnedOffset = ReadUInt32(buffer, p + 16);
                uint returnedLength = ReadUInt32(buffer, p + 20);
                long payloadStart = (long)p + (long)returnedOffset;
                long payloadEnd = payloadStart + (long)dataLength;
                if (returnedOffset < STORAGE_PROTOCOL_SPECIFIC_DATA_SIZE || payloadStart < 0 || payloadStart > buffer.Length)
                {
                    error = "NVMe Get Features data returned invalid ProtocolDataOffset=" + returnedOffset.ToString(CultureInfo.InvariantCulture) + " for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " descriptorBase=" + p.ToString(CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " bufferLength=" + buffer.Length.ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                if (returnedLength < dataLength || payloadEnd > buffer.Length)
                {
                    error = "NVMe Get Features data returned insufficient payload for " + drivePath + " scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " offset=" + returnedOffset.ToString(CultureInfo.InvariantCulture) + " descriptorBase=" + p.ToString(CultureInfo.InvariantCulture) + " length=" + returnedLength.ToString(CultureInfo.InvariantCulture) + " expected=" + dataLength.ToString(CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture) + " bufferLength=" + buffer.Length.ToString(CultureInfo.InvariantCulture) + ".";
                    return false;
                }
                payload = new byte[dataLength];
                Buffer.BlockCopy(buffer, (int)payloadStart, payload, 0, dataLength);
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Get Features data scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static bool TryGetFeatureFixedDataViaProtocolCommand(string drivePath, uint featureId, uint namespaceId, uint requestSubValue, bool adapterRequest, out uint fixedData, out string error)
    {
        fixedData = 0u;
        error = String.Empty;
        uint cdw10 = featureId & 0xFFu;
        uint flags = adapterRequest ? STORAGE_PROTOCOL_COMMAND_FLAG_ADAPTER_REQUEST : 0u;
        string scopeLabel = adapterRequest ? "ProtocolCommandAdapter" : "ProtocolCommandDevice";
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, false))
            {
                byte[] buffer = BuildNvmeAdminProtocolCommandBuffer(0x0A, namespaceId, cdw10, requestSubValue, 0u, 0u, 0u, 0u, flags, 30);
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_PROTOCOL_COMMAND, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                uint returnStatus = ReadUInt32(buffer, 16);
                uint protocolError = ReadUInt32(buffer, 20);
                uint fixedDw0 = ReadUInt32(buffer, 64);
                uint fixedDw1 = ReadUInt32(buffer, 68);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatProtocolCommandFailure("Get", drivePath, scopeLabel, featureId, namespaceId, requestSubValue, 0u, 0u, 0u, 0u, err, returnStatus, protocolError, fixedDw0, fixedDw1, bytesReturned);
                    return false;
                }
                if (returnStatus != STORAGE_PROTOCOL_STATUS_SUCCESS)
                {
                    error = FormatProtocolCommandFailure("Get", drivePath, scopeLabel, featureId, namespaceId, requestSubValue, 0u, 0u, 0u, 0u, 0, returnStatus, protocolError, fixedDw0, fixedDw1, bytesReturned);
                    return false;
                }
                fixedData = fixedDw0;
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Get Features scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static bool TrySetFeatureViaProtocolCommand(string drivePath, uint featureId, uint cdw11, bool adapterRequest, out string error)
    {
        uint fixedData;
        return TrySetFeatureViaProtocolCommand(drivePath, featureId, 0u, cdw11, 0u, 0u, 0u, 0u, adapterRequest, out fixedData, out error);
    }

    private static bool TrySetFeatureViaProtocolCommand(string drivePath, uint featureId, uint namespaceId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, bool adapterRequest, out string error)
    {
        uint fixedData;
        return TrySetFeatureViaProtocolCommand(drivePath, featureId, namespaceId, cdw11, cdw12, cdw13, cdw14, cdw15, adapterRequest, out fixedData, out error);
    }

    private static bool TrySetFeatureViaProtocolCommand(string drivePath, uint featureId, uint namespaceId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, bool adapterRequest, out uint fixedData, out string error)
    {
        fixedData = 0u;
        error = String.Empty;
        string scopeLabel = adapterRequest ? "ProtocolCommandAdapter" : "ProtocolCommandDevice";
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, true))
            {
                uint flags = adapterRequest ? STORAGE_PROTOCOL_COMMAND_FLAG_ADAPTER_REQUEST : 0u;
                uint cdw10 = featureId & 0xFFu;
                byte[] buffer = BuildNvmeAdminProtocolCommandBuffer(0x09, namespaceId, cdw10, cdw11, cdw12, cdw13, cdw14, cdw15, flags, 30);
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_PROTOCOL_COMMAND, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                uint returnStatus = ReadUInt32(buffer, 16);
                uint protocolError = ReadUInt32(buffer, 20);
                uint fixedDw0 = ReadUInt32(buffer, 64);
                uint fixedDw1 = ReadUInt32(buffer, 68);
                fixedData = fixedDw0;
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatProtocolCommandFailure("Set", drivePath, scopeLabel, featureId, namespaceId, cdw11, cdw12, cdw13, cdw14, cdw15, err, returnStatus, protocolError, fixedDw0, fixedDw1, bytesReturned);
                    return false;
                }
                if (returnStatus != STORAGE_PROTOCOL_STATUS_SUCCESS)
                {
                    error = FormatProtocolCommandFailure("Set", drivePath, scopeLabel, featureId, namespaceId, cdw11, cdw12, cdw13, cdw14, cdw15, 0, returnStatus, protocolError, fixedDw0, fixedDw1, bytesReturned);
                    return false;
                }
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Set Features ProtocolCommand scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static byte[] BuildNvmeAdminProtocolCommandBuffer(byte opcode, uint nsid, uint cdw10, uint cdw11, uint flags, uint timeoutSeconds)
    {
        return BuildNvmeAdminProtocolCommandBuffer(opcode, nsid, cdw10, cdw11, 0u, 0u, 0u, 0u, flags, timeoutSeconds);
    }

    private static byte[] BuildNvmeAdminProtocolCommandBuffer(byte opcode, uint nsid, uint cdw10, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, uint flags, uint timeoutSeconds)
    {
        byte[] buffer = new byte[STORAGE_PROTOCOL_COMMAND_OFFSET_COMMAND + STORAGE_PROTOCOL_COMMAND_LENGTH_NVME];
        WriteUInt32(buffer, 0, STORAGE_PROTOCOL_STRUCTURE_VERSION);
        WriteUInt32(buffer, 4, STORAGE_PROTOCOL_COMMAND_SIZEOF);
        WriteUInt32(buffer, 8, ProtocolTypeNvme);
        WriteUInt32(buffer, 12, flags);
        WriteUInt32(buffer, 24, STORAGE_PROTOCOL_COMMAND_LENGTH_NVME);
        WriteUInt32(buffer, 40, timeoutSeconds);
        WriteUInt32(buffer, 56, STORAGE_PROTOCOL_SPECIFIC_NVME_ADMIN_COMMAND);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW0, opcode);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_NSID, nsid);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW10, cdw10);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW11, cdw11);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW12, cdw12);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW13, cdw13);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW14, cdw14);
        WriteUInt32(buffer, NVME_COMMAND_OFFSET_CDW15, cdw15);
        return buffer;
    }

    private static string FormatProtocolCommandFailure(string op, string drivePath, string scopeLabel, uint featureId, uint cdw11, int win32, uint returnStatus, uint protocolError, uint fixedDw0, uint fixedDw1, int bytesReturned)
    {
        return FormatProtocolCommandFailure(op, drivePath, scopeLabel, featureId, 0u, cdw11, 0u, 0u, 0u, 0u, win32, returnStatus, protocolError, fixedDw0, fixedDw1, bytesReturned);
    }

    private static string FormatProtocolCommandFailure(string op, string drivePath, string scopeLabel, uint featureId, uint namespaceId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, int win32, uint returnStatus, uint protocolError, uint fixedDw0, uint fixedDw1, int bytesReturned)
    {
        string win32Text = win32 == 0 ? "none" : win32.ToString(CultureInfo.InvariantCulture) + " (" + new Win32Exception(win32).Message + ")";
        return "scope=" + scopeLabel + " ioctl=" + op + " path=" + drivePath + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " nsid=0x" + namespaceId.ToString("X8", CultureInfo.InvariantCulture) + " cdw10=0x" + (featureId & 0xFFu).ToString("X8", CultureInfo.InvariantCulture) + " cdw11=0x" + cdw11.ToString("X8", CultureInfo.InvariantCulture) + " cdw12=0x" + cdw12.ToString("X8", CultureInfo.InvariantCulture) + " cdw13=0x" + cdw13.ToString("X8", CultureInfo.InvariantCulture) + " cdw14=0x" + cdw14.ToString("X8", CultureInfo.InvariantCulture) + " cdw15=0x" + cdw15.ToString("X8", CultureInfo.InvariantCulture) + " win32=" + win32Text + " returnStatus=0x" + returnStatus.ToString("X8", CultureInfo.InvariantCulture) + " (" + FormatStorageProtocolStatus(returnStatus) + ") protocolError=0x" + protocolError.ToString("X8", CultureInfo.InvariantCulture) + FormatNvmeProtocolError(protocolError) + " fixedDW0=0x" + fixedDw0.ToString("X8", CultureInfo.InvariantCulture) + " fixedDW1=0x" + fixedDw1.ToString("X8", CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture);
    }

    private static bool IsUnsupportedNvmeFeatureFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        string text = message.ToUpperInvariant();
        if (text.IndexOf("COMMAND SEQUENCE ERROR", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE NOT CHANGEABLE", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSFLAT=GENERIC:0X0C", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSSHIFTED=GENERIC:0X0C", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSFLAT=COMMANDSPECIFIC:0X0E", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSSHIFTED=COMMANDSPECIFIC:0X0E", StringComparison.Ordinal) >= 0)
        {
            return false;
        }
        return text.IndexOf("NOT_SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("REQUEST IS NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("INCORRECT FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("ERROR_INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_REQUEST", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X000000FF", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X00000003", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=1 ", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=50 ", StringComparison.Ordinal) >= 0;
    }

    private static bool IsArbitrationUnsupportedNvmeFeatureFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        string text = message.ToUpperInvariant();
        if (text.IndexOf("NO PHYSICALDRIVE PATH", StringComparison.Ordinal) >= 0
            || text.IndexOf("DRIVE PATH IS EMPTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("ACCESS IS DENIED", StringComparison.Ordinal) >= 0
            || text.IndexOf("UNAUTHORIZEDACCESS", StringComparison.Ordinal) >= 0
            || text.IndexOf("SYSTEM CANNOT FIND THE FILE", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=5 ", StringComparison.Ordinal) >= 0)
        {
            return false;
        }
        bool context = text.IndexOf("ARBITRATION", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME ARB", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE ID 0X01", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE=0X01", StringComparison.Ordinal) >= 0
            || text.IndexOf("FID=0X01", StringComparison.Ordinal) >= 0;
        if (!context) { return false; }
        if (IsUnsupportedNvmeFeatureFailure(message)) { return true; }
        bool storagePropertyAttempt = text.IndexOf("NVME ARBITRATION READ FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME ARBITRATION SET FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME GET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME SET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=GET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=SET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_QUERY_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_SET_PROPERTY", StringComparison.Ordinal) >= 0;
        return storagePropertyAttempt && IsUnsupportedNvmeFeatureFailure(message);
    }

    private static bool IsNumberOfQueuesUnsupportedNvmeFeatureFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        string text = message.ToUpperInvariant();
        bool context = text.IndexOf("NUMBER OF QUEUES", StringComparison.Ordinal) >= 0
            || text.IndexOf("NUM-QUEUES", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME NOQ", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE ID 0X07", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE=0X07", StringComparison.Ordinal) >= 0
            || text.IndexOf("FID=0X07", StringComparison.Ordinal) >= 0;
        if (!context) { return false; }
        if (IsNumberOfQueuesLifecycleFailure(message)) { return false; }

        // FID 0x07 commonly falls through several Windows paths.  On some systems
        // the storage-property attempts report win32=1 / Incorrect function while
        // later protocol-command fallbacks report win32=5 / Access denied.  The
        // explicit unsupported/invalid-function signal must win over generic
        // access-denied fallback noise.
        if (IsUnsupportedNvmeFeatureFailure(message)) { return true; }

        if (text.IndexOf("NO PHYSICALDRIVE PATH", StringComparison.Ordinal) >= 0
            || text.IndexOf("DRIVE PATH IS EMPTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("ACCESS IS DENIED", StringComparison.Ordinal) >= 0
            || text.IndexOf("UNAUTHORIZEDACCESS", StringComparison.Ordinal) >= 0
            || text.IndexOf("SYSTEM CANNOT FIND THE FILE", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=5 ", StringComparison.Ordinal) >= 0)
        {
            return false;
        }
        bool storagePropertyAttempt = text.IndexOf("NVME NUMBER OF QUEUES READ FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME NUMBER OF QUEUES SET FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME GET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME SET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=GET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=SET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_QUERY_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_SET_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_PROTOCOL_COMMAND", StringComparison.Ordinal) >= 0;
        return storagePropertyAttempt && IsUnsupportedNvmeFeatureFailure(message);
    }

