            || text.IndexOf("NVME SET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=GET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=SET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_QUERY_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_SET_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_PROTOCOL_COMMAND", StringComparison.Ordinal) >= 0;
        bool rejectedAsUnsupported = text.IndexOf("NOT_SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("UNSUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("REQUEST IS NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("INCORRECT FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("ERROR_INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_REQUEST", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID FIELD IN COMMAND", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_FIELD_IN_COMMAND", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X00000002", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X00000003", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X000000FF", StringComparison.Ordinal) >= 0
            || text.IndexOf("PROTOCOLERROR=0X", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=1 ", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=50 ", StringComparison.Ordinal) >= 0;
        return storagePropertyAttempt && rejectedAsUnsupported;
    }

    private static bool IsErrorRecoveryUnsupportedNvmeFeatureFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        if (IsUnsupportedNvmeFeatureFailure(message)) { return true; }
        string text = message.ToUpperInvariant();
        bool errorRecoveryContext = text.IndexOf("ERROR RECOVERY", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE ID 0X05", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE=0X05", StringComparison.Ordinal) >= 0
            || text.IndexOf("FID=0X05", StringComparison.Ordinal) >= 0;
        if (!errorRecoveryContext) { return false; }

        // Some NVMe/Windows stacks reject namespace-specific Get/Set Features FID 0x05
        // through IOCTL_STORAGE_PROTOCOL_COMMAND with STORAGE_PROTOCOL_STATUS_ERROR
        // instead of the cleaner NOT_SUPPORTED / INVALID_REQUEST status.  For ERR
        // only, treat that protocol-command rejection as unsupported so the UI
        // matches the existing HMB-style unsupported behavior.
        bool protocolCommandAttempt = text.IndexOf("PROTOCOLCOMMAND", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_PROTOCOL_COMMAND", StringComparison.Ordinal) >= 0
            || text.IndexOf("NAMESPACE-SPECIFIC FEATURE ID 0X05", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME GET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME SET FEATURES FAILED", StringComparison.Ordinal) >= 0;
        bool controllerRejected = text.IndexOf("RETURNSTATUS=0X00000002", StringComparison.Ordinal) >= 0
            || text.IndexOf(" (ERROR)", StringComparison.Ordinal) >= 0
            || text.IndexOf("PROTOCOLERROR=0X", StringComparison.Ordinal) >= 0;
        return protocolCommandAttempt && controllerRejected;
    }

    private static bool IsHostControlledThermalManagementUnsupportedNvmeFeatureFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        string text = message.ToUpperInvariant();
        if (text.IndexOf("NO PHYSICALDRIVE PATH", StringComparison.Ordinal) >= 0
            || text.IndexOf("DRIVE PATH IS EMPTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("ACCESS IS DENIED", StringComparison.Ordinal) >= 0
            || text.IndexOf("UNAUTHORIZEDACCESS", StringComparison.Ordinal) >= 0
            || text.IndexOf("SYSTEM CANNOT FIND THE FILE", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=5 ", StringComparison.Ordinal) >= 0)
        {
            return false;
        }
        bool hctmContext = text.IndexOf("HCTM", StringComparison.Ordinal) >= 0
            || text.IndexOf("HOST CONTROLLED THERMAL MANAGEMENT", StringComparison.Ordinal) >= 0
            || text.IndexOf("HOST-CONTROLLED THERMAL MANAGEMENT", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE ID 0X10", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE=0X10", StringComparison.Ordinal) >= 0
            || text.IndexOf("FID=0X10", StringComparison.Ordinal) >= 0;
        if (!hctmContext) { return false; }
        if (IsUnsupportedNvmeFeatureFailure(message)) { return true; }

        bool storagePropertyAttempt = text.IndexOf("NVME HCTM GET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME HCTM SET FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME GET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVME SET FEATURES FAILED", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=GET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL=SET", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_QUERY_PROPERTY", StringComparison.Ordinal) >= 0
            || text.IndexOf("IOCTL_STORAGE_SET_PROPERTY", StringComparison.Ordinal) >= 0;
        bool rejectedAsUnsupported = text.IndexOf("NOT_SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("REQUEST IS NOT SUPPORTED", StringComparison.Ordinal) >= 0
            || text.IndexOf("INCORRECT FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("ERROR_INVALID_FUNCTION", StringComparison.Ordinal) >= 0
            || text.IndexOf("INVALID_REQUEST", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=1 ", StringComparison.Ordinal) >= 0
            || text.IndexOf("WIN32=50 ", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X000000FF", StringComparison.Ordinal) >= 0
            || text.IndexOf("RETURNSTATUS=0X00000003", StringComparison.Ordinal) >= 0;
        return storagePropertyAttempt && rejectedAsUnsupported;
    }

    private static string MergeScope(string primary, string secondary)
    {
        if (String.IsNullOrWhiteSpace(primary)) { return String.IsNullOrWhiteSpace(secondary) ? String.Empty : secondary; }
        if (String.IsNullOrWhiteSpace(secondary)) { return primary; }
        if (String.Equals(primary, secondary, StringComparison.OrdinalIgnoreCase)) { return primary; }
        return primary + "+" + secondary;
    }

    private static string FormatNvmeProtocolError(uint protocolError)
    {
        if (protocolError == 0u) { return " "; }
        uint flatCode = protocolError & 0xFFu;
        uint flatType = (protocolError >> 8) & 0x7u;
        uint shiftedCode = (protocolError >> 1) & 0xFFu;
        uint shiftedType = (protocolError >> 9) & 0x7u;
        return " nvmeStatusFlat=" + FormatNvmeStatusCode(flatType, flatCode) + " nvmeStatusShifted=" + FormatNvmeStatusCode(shiftedType, shiftedCode) + " ";
    }

    private static string FormatNvmeStatusCode(uint statusType, uint statusCode)
    {
        string typeName;
        if (statusType == 0u) { typeName = "Generic"; }
        else if (statusType == 1u) { typeName = "CommandSpecific"; }
        else if (statusType == 2u) { typeName = "MediaAndDataIntegrity"; }
        else if (statusType == 7u) { typeName = "VendorSpecific"; }
        else { typeName = "Type" + statusType.ToString(CultureInfo.InvariantCulture); }
        string codeName = String.Empty;
        if (statusType == 0u)
        {
            if (statusCode == 0x00u) { codeName = "SuccessfulCompletion"; }
            else if (statusCode == 0x01u) { codeName = "InvalidCommandOpcode"; }
            else if (statusCode == 0x02u) { codeName = "InvalidFieldInCommand"; }
            else if (statusCode == 0x0Cu) { codeName = "CommandSequenceError"; }
        }
        else if (statusType == 1u)
        {
            if (statusCode == 0x0Du) { codeName = "FeatureIdentifierNotSaveable"; }
            else if (statusCode == 0x0Eu) { codeName = "FeatureNotChangeable"; }
            else if (statusCode == 0x0Fu) { codeName = "FeatureNotNamespaceSpecific"; }
        }
        return typeName + ":0x" + statusCode.ToString("X2", CultureInfo.InvariantCulture) + (String.IsNullOrEmpty(codeName) ? String.Empty : "(" + codeName + ")");
    }

    private static bool IsNumberOfQueuesLifecycleFailure(string message)
    {
        if (String.IsNullOrWhiteSpace(message)) { return false; }
        string text = message.ToUpperInvariant();
        bool context = text.IndexOf("NUMBER OF QUEUES", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE ID 0X07", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE=0X07", StringComparison.Ordinal) >= 0
            || text.IndexOf("FID=0X07", StringComparison.Ordinal) >= 0;
        if (!context) { return false; }
        return text.IndexOf("COMMAND SEQUENCE ERROR", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURE NOT CHANGEABLE", StringComparison.Ordinal) >= 0
            || text.IndexOf("COMMANDSEQUENCEERROR", StringComparison.Ordinal) >= 0
            || text.IndexOf("FEATURENOTCHANGEABLE", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSFLAT=GENERIC:0X0C", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSSHIFTED=GENERIC:0X0C", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSFLAT=COMMANDSPECIFIC:0X0E", StringComparison.Ordinal) >= 0
            || text.IndexOf("NVMESTATUSSHIFTED=COMMANDSPECIFIC:0X0E", StringComparison.Ordinal) >= 0;
    }

    private static string FormatStorageProtocolStatus(uint status)
    {
        if (status == 0) { return "SUCCESS"; }
        if (status == 1) { return "PENDING"; }
        if (status == 2) { return "ERROR"; }
        if (status == 3) { return "INVALID_REQUEST"; }
        if (status == 4) { return "NO_DEVICE"; }
        if (status == 5) { return "BUSY"; }
        if (status == 6) { return "DATA_OVERRUN"; }
        if (status == 7) { return "INSUFFICIENT_RESOURCES"; }
        if (status == 0xFF) { return "NOT_SUPPORTED"; }
        return "UNKNOWN";
    }

    private static bool TrySetFeatureViaStorageProperty(string drivePath, uint featureId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, byte[] data, uint propertyId, string scopeLabel, out string error)
    {
        uint fixedData;
        return TrySetFeatureViaStorageProperty(drivePath, featureId, cdw11, cdw12, cdw13, cdw14, cdw15, data, propertyId, scopeLabel, out fixedData, out error);
    }

    private static bool TrySetFeatureViaStorageProperty(string drivePath, uint featureId, uint cdw11, uint cdw12, uint cdw13, uint cdw14, uint cdw15, byte[] data, uint propertyId, string scopeLabel, out uint fixedData, out string error)
    {
        fixedData = 0u;
        error = String.Empty;
        try
        {
            using (SafeFileHandle handle = OpenDevice(drivePath, true))
            {
                int dataLength = data == null ? 0 : data.Length;
                int bufferLength = STORAGE_PROPERTY_HEADER_SIZE + STORAGE_PROTOCOL_SPECIFIC_DATA_EXT_SIZE + dataLength;
                byte[] buffer = new byte[bufferLength];
                WriteUInt32(buffer, 0, propertyId);
                WriteUInt32(buffer, 4, PropertyStandardSet);
                int p = STORAGE_PROPERTY_HEADER_SIZE;
                WriteUInt32(buffer, p + 0, ProtocolTypeNvme);
                WriteUInt32(buffer, p + 4, NVMeDataTypeFeature);
                WriteUInt32(buffer, p + 8, featureId);
                WriteUInt32(buffer, p + 12, cdw11);
                WriteUInt32(buffer, p + 16, dataLength > 0 ? (uint)STORAGE_PROTOCOL_SPECIFIC_DATA_EXT_SIZE : 0u);
                WriteUInt32(buffer, p + 20, (uint)dataLength);
                WriteUInt32(buffer, p + 28, cdw12);
                WriteUInt32(buffer, p + 32, cdw13);
                WriteUInt32(buffer, p + 36, cdw14);
                WriteUInt32(buffer, p + 40, cdw15);
                if (dataLength > 0) { Buffer.BlockCopy(data, 0, buffer, p + STORAGE_PROTOCOL_SPECIFIC_DATA_EXT_SIZE, dataLength); }
                int bytesReturned;
                bool ok = DeviceIoControl(handle, IOCTL_STORAGE_SET_PROPERTY, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
                fixedData = ReadUInt32(buffer, p + STORAGE_PROTOCOL_SPECIFIC_DATA_FIXED_RETURN_OFFSET);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    error = FormatWin32IoctlError("Set", drivePath, scopeLabel, propertyId, featureId, cdw11, err) + " CDW12=0x" + cdw12.ToString("X8", CultureInfo.InvariantCulture) + " CDW13=0x" + cdw13.ToString("X8", CultureInfo.InvariantCulture) + " CDW14=0x" + cdw14.ToString("X8", CultureInfo.InvariantCulture) + " CDW15=0x" + cdw15.ToString("X8", CultureInfo.InvariantCulture) + " dataLength=" + dataLength.ToString(CultureInfo.InvariantCulture) + " fixedDW0=0x" + fixedData.ToString("X8", CultureInfo.InvariantCulture) + " bytes=" + bytesReturned.ToString(CultureInfo.InvariantCulture);
                    return false;
                }
                return true;
            }
        }
        catch (Exception ex)
        {
            error = "NVMe Set Features scope=" + scopeLabel + " failed before IOCTL completion: " + ex.GetType().FullName + ": " + ex.Message;
            return false;
        }
    }

    private static SafeFileHandle OpenDevice(string path, bool write)
    {
        uint access = GENERIC_READ | (write ? GENERIC_WRITE : 0u);
        SafeFileHandle handle = CreateFile(path, access, FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, IntPtr.Zero, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, IntPtr.Zero);
        if (handle == null || handle.IsInvalid)
        {
            int err = Marshal.GetLastWin32Error();
            throw new Win32Exception(err, "CreateFile failed for " + path + " access=0x" + access.ToString("X8", CultureInfo.InvariantCulture) + ". Run elevated and verify the disk is exposed as a local NVMe PhysicalDrive.");
        }
        return handle;
    }

    private static string FormatWin32IoctlError(string op, string drivePath, string scopeLabel, uint propertyId, uint featureId, uint cdw11, int err)
    {
        Win32Exception wex = new Win32Exception(err);
        return "scope=" + scopeLabel + " propertyId=" + propertyId.ToString(CultureInfo.InvariantCulture) + " ioctl=" + op + " path=" + drivePath + " feature=0x" + featureId.ToString("X2", CultureInfo.InvariantCulture) + " cdw11=0x" + cdw11.ToString("X8", CultureInfo.InvariantCulture) + " win32=" + err.ToString(CultureInfo.InvariantCulture) + " (" + wex.Message + ")";
    }

    private static void WriteUInt32(byte[] buffer, int offset, uint value)
    {
        buffer[offset + 0] = (byte)(value & 0xFFu);
        buffer[offset + 1] = (byte)((value >> 8) & 0xFFu);
        buffer[offset + 2] = (byte)((value >> 16) & 0xFFu);
        buffer[offset + 3] = (byte)((value >> 24) & 0xFFu);
    }

    private static ushort ReadUInt16(byte[] buffer, int offset)
    {
        return (ushort)(((uint)buffer[offset + 0]) | ((uint)buffer[offset + 1] << 8));
    }

    private static uint ReadUInt32(byte[] buffer, int offset)
    {
        return ((uint)buffer[offset + 0]) | ((uint)buffer[offset + 1] << 8) | ((uint)buffer[offset + 2] << 16) | ((uint)buffer[offset + 3] << 24);
    }
}



public sealed class DeviceTweakerPciMcfgSegment
{
    public ulong BaseAddress { get; private set; }
    public int SegmentGroup { get; private set; }
    public int StartBus { get; private set; }
    public int EndBus { get; private set; }
    public int EntryIndex { get; private set; }

    public DeviceTweakerPciMcfgSegment(ulong baseAddress, int segmentGroup, int startBus, int endBus, int entryIndex)
    {
        if (startBus < 0 || startBus > 255) { throw new ArgumentOutOfRangeException("startBus", "MCFG start bus must be in 0..255."); }
        if (endBus < startBus || endBus > 255) { throw new ArgumentOutOfRangeException("endBus", "MCFG end bus must be in startBus..255."); }
        BaseAddress = baseAddress;
        SegmentGroup = segmentGroup;
        StartBus = startBus;
        EndBus = endBus;
        EntryIndex = entryIndex;
    }

    public bool Covers(int segmentGroup, int bus)
    {
        return SegmentGroup == segmentGroup && bus >= StartBus && bus <= EndBus;
    }

    public ulong ResolveAddress(int bus, int device, int function, int offset)
    {
        if (!Covers(SegmentGroup, bus)) { throw new ArgumentOutOfRangeException("bus", "Bus is outside this MCFG allocation."); }
        if (device < 0 || device > 31) { throw new ArgumentOutOfRangeException("device", "PCI device number must be in 0..31."); }
        if (function < 0 || function > 7) { throw new ArgumentOutOfRangeException("function", "PCI function number must be in 0..7."); }
        if (offset < 0 || offset > 4095) { throw new ArgumentOutOfRangeException("offset", "PCIe ECAM config-space offset must be in 0..4095."); }
        return BaseAddress + (((ulong)(bus - StartBus)) << 20) + (((ulong)device) << 15) + (((ulong)function) << 12) + (uint)offset;
    }

    public override string ToString()
    {
        return "segment=" + SegmentGroup.ToString(CultureInfo.InvariantCulture) + " bus=" + StartBus.ToString(CultureInfo.InvariantCulture) + ".." + EndBus.ToString(CultureInfo.InvariantCulture) + " base=0x" + BaseAddress.ToString("X", CultureInfo.InvariantCulture) + " entry=" + EntryIndex.ToString(CultureInfo.InvariantCulture);
    }
}

public static class DeviceTweakerPciEcam
{
    // DWORD value for the Win32 firmware provider signature 'ACPI'. Do not byte-reverse provider signatures.
    // EnumSystemFirmwareTables/GetSystemFirmwareTable report ACPI as 0x41435049; only ACPI table IDs such as MCFG are passed reversed ('GFCM' = 0x4746434D).
    private const int FirmwareTableProviderAcpi = 0x41435049;
    private const int AcpiMcfgSignature = 0x4746434D;
    private static readonly object _mcfgLock = new object();
    private static DeviceTweakerPciMcfgSegment[] _mcfgSegments;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint GetSystemFirmwareTable(int firmwareTableProviderSignature, int firmwareTableID, IntPtr pFirmwareTableBuffer, uint bufferSize);

    public static DeviceTweakerPciMcfgSegment[] GetMcfgSegments()
    {
        lock (_mcfgLock)
        {
            if (_mcfgSegments == null) { _mcfgSegments = ParseMcfg(ReadFirmwareTable(FirmwareTableProviderAcpi, AcpiMcfgSignature)); }
            DeviceTweakerPciMcfgSegment[] copy = new DeviceTweakerPciMcfgSegment[_mcfgSegments.Length];
            Array.Copy(_mcfgSegments, copy, _mcfgSegments.Length);
            return copy;
        }
    }

    public static ulong ResolveAddress(int segmentGroup, int bus, int device, int function, int offset)
    {
        ValidateBdf(segmentGroup, bus, device, function);
        if (offset < 0 || offset > 4095) { throw new ArgumentOutOfRangeException("offset", "PCIe ECAM config-space offset must be in 0..4095."); }
        DeviceTweakerPciMcfgSegment[] segments = GetMcfgSegments();
        for (int i = 0; i < segments.Length; i++)
        {
            if (segments[i] != null && segments[i].Covers(segmentGroup, bus)) { return segments[i].ResolveAddress(bus, device, function, offset); }
        }
        throw new InvalidOperationException("ACPI MCFG has no allocation covering " + FormatBdf(segmentGroup, bus, device, function) + ". Available allocations: " + FormatSegments(segments));
    }

    public static string FormatBdf(int segmentGroup, int bus, int device, int function)
    {
        return segmentGroup.ToString("X4", CultureInfo.InvariantCulture) + ":" + bus.ToString("X2", CultureInfo.InvariantCulture) + ":" + device.ToString("X2", CultureInfo.InvariantCulture) + "." + function.ToString(CultureInfo.InvariantCulture);
    }

    public static string FormatSegments(DeviceTweakerPciMcfgSegment[] segments)
    {
        if (segments == null || segments.Length == 0) { return "none"; }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < segments.Length; i++)
        {
            if (i > 0) { sb.Append("; "); }
            sb.Append(segments[i] == null ? "null" : segments[i].ToString());
        }
        return sb.ToString();
    }

    private static void ValidateBdf(int segmentGroup, int bus, int device, int function)
    {
        if (segmentGroup < 0 || segmentGroup > 65535) { throw new ArgumentOutOfRangeException("segmentGroup", "PCI segment group must be in 0..65535."); }
        if (bus < 0 || bus > 255) { throw new ArgumentOutOfRangeException("bus", "PCI bus number must be in 0..255."); }
        if (device < 0 || device > 31) { throw new ArgumentOutOfRangeException("device", "PCI device number must be in 0..31."); }
        if (function < 0 || function > 7) { throw new ArgumentOutOfRangeException("function", "PCI function number must be in 0..7."); }
    }

    private static byte[] ReadFirmwareTable(int provider, int tableId)
    {
        uint bytes = GetSystemFirmwareTable(provider, tableId, IntPtr.Zero, 0);
        if (bytes == 0)
        {
            int err = Marshal.GetLastWin32Error();
            throw new InvalidOperationException("GetSystemFirmwareTable(ACPI, MCFG) length query returned 0. Win32Error=" + err.ToString(CultureInfo.InvariantCulture) + ". This machine may not expose ACPI MCFG or firmware table access is blocked.");
        }
        IntPtr buffer = Marshal.AllocHGlobal((int)bytes);
        try
        {
            uint read = GetSystemFirmwareTable(provider, tableId, buffer, bytes);
            if (read != bytes)
            {
                int err = Marshal.GetLastWin32Error();
                throw new InvalidOperationException("GetSystemFirmwareTable(ACPI, MCFG) returned " + read.ToString(CultureInfo.InvariantCulture) + " bytes after a " + bytes.ToString(CultureInfo.InvariantCulture) + " byte length query. Win32Error=" + err.ToString(CultureInfo.InvariantCulture) + ".");
            }
            byte[] data = new byte[bytes];
            Marshal.Copy(buffer, data, 0, (int)bytes);
            return data;
        }
        finally
        {
            Marshal.FreeHGlobal(buffer);
        }
    }

    private static DeviceTweakerPciMcfgSegment[] ParseMcfg(byte[] table)
    {
        if (table == null || table.Length < 44) { throw new InvalidOperationException("ACPI MCFG table is missing or shorter than the 44-byte ACPI MCFG header/reserved prefix."); }
        uint declaredLength = ReadUInt32(table, 4);
        if (declaredLength < 44 || declaredLength > table.Length) { throw new InvalidOperationException("ACPI MCFG declared length " + declaredLength.ToString(CultureInfo.InvariantCulture) + " is invalid for a returned buffer of " + table.Length.ToString(CultureInfo.InvariantCulture) + " bytes."); }
        if (((declaredLength - 44) % 16) != 0) { throw new InvalidOperationException("ACPI MCFG allocation area length is not a multiple of 16 bytes. DeclaredLength=" + declaredLength.ToString(CultureInfo.InvariantCulture) + "."); }
        int entryCount = (int)((declaredLength - 44) / 16);
        if (entryCount <= 0) { throw new InvalidOperationException("ACPI MCFG contains no PCIe ECAM allocation entries."); }
        DeviceTweakerPciMcfgSegment[] segments = new DeviceTweakerPciMcfgSegment[entryCount];
        for (int i = 0; i < entryCount; i++)
        {
            int off = 44 + (i * 16);
            ulong baseAddress = ReadUInt64(table, off);
            int segment = ReadUInt16(table, off + 8);
            int startBus = table[off + 10];
            int endBus = table[off + 11];
            segments[i] = new DeviceTweakerPciMcfgSegment(baseAddress, segment, startBus, endBus, i);
        }
        return segments;
    }

    private static ushort ReadUInt16(byte[] buffer, int offset)
    {
        return (ushort)(buffer[offset] | (buffer[offset + 1] << 8));
    }

    private static uint ReadUInt32(byte[] buffer, int offset)
    {
        return ((uint)buffer[offset]) | ((uint)buffer[offset + 1] << 8) | ((uint)buffer[offset + 2] << 16) | ((uint)buffer[offset + 3] << 24);
    }

    private static ulong ReadUInt64(byte[] buffer, int offset)
    {
        return ((ulong)ReadUInt32(buffer, offset)) | (((ulong)ReadUInt32(buffer, offset + 4)) << 32);
    }
}

public static class DeviceTweakerTextBoxNative
{
    [StructLayout(LayoutKind.Sequential)]
    public struct RECT
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, ref RECT lParam);

    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);

    [DllImport("user32.dll")]
    private static extern bool InvalidateRect(IntPtr hWnd, IntPtr lpRect, bool bErase);

    private const int EM_SETRECT = 0x00B3;
    private const int EM_SETMARGINS = 0x00D3;
    private const int EC_LEFTMARGIN = 0x0001;
    private const int EC_RIGHTMARGIN = 0x0002;

    public static void SetTextMargins(IntPtr hwnd, int left, int right)
    {
        if (hwnd == IntPtr.Zero) { return; }
        if (left < 0) { left = 0; }
        if (right < 0) { right = 0; }
        int packedMargins = (left & 0xFFFF) | ((right & 0xFFFF) << 16);
        SendMessage(hwnd, EM_SETMARGINS, new IntPtr(EC_LEFTMARGIN | EC_RIGHTMARGIN), new IntPtr(packedMargins));
    }

    public static void SetTextRect(IntPtr hwnd, int left, int top, int right, int bottom)
    {
        if (hwnd == IntPtr.Zero) { return; }
        if (right <= left) { right = left + 1; }
        if (bottom <= top) { bottom = top + 1; }

        RECT r = new RECT { Left = left, Top = top, Right = right, Bottom = bottom };
        SendMessage(hwnd, EM_SETRECT, IntPtr.Zero, ref r);
        InvalidateRect(hwnd, IntPtr.Zero, true);
    }
}


public sealed class DeviceEditorTextElement
{
    private DeviceEditorSurface _owner;
    private string _text;
    private int _left;
    private int _top;
    private int _width;
    private int _height;
    private bool _autoSize;
    private bool _visible;
    private bool _useMnemonic;
    private Font _font;
    private Color _foreColor;
    private Color _backColor;
    private Cursor _cursor;
    private object _tag;
    private Padding _padding;
    private string _accessibleName;
    private string _accessibleDescription;
    private string _measureCacheText;
    private Font _measureCacheFont;
    private bool _measureCacheUseMnemonic;
    private Padding _measureCachePadding;
    private Size _measureCacheSize;
    private bool _measureCacheValid;

    internal DeviceEditorTextElement(DeviceEditorSurface owner)
    {
        _owner = owner;
        _text = String.Empty;
        _left = 0;
        _top = 0;
        _width = 0;
        _height = 0;
        _autoSize = true;
        _visible = true;
        _useMnemonic = true;
        _font = null;
        _foreColor = Color.Empty;
        _backColor = Color.Transparent;
        _cursor = null;
        _tag = null;
        _padding = Padding.Empty;
        _accessibleName = String.Empty;
        _accessibleDescription = String.Empty;
        _measureCacheText = null;
        _measureCacheFont = null;
        _measureCacheUseMnemonic = true;
        _measureCachePadding = Padding.Empty;
        _measureCacheSize = Size.Empty;
        _measureCacheValid = false;
    }

    public DeviceEditorSurface Owner { get { return _owner; } }
    public DeviceEditorSurface Parent { get { return _owner; } }

    public string Text
    {
        get { return _text; }
        set
        {
            string newValue = value ?? String.Empty;
            if (String.Equals(_text, newValue, StringComparison.Ordinal)) { return; }
            Rectangle oldBounds = InvalidationBounds;
            _text = newValue;
            InvalidateMeasureCache();
            if (_autoSize) { UpdateAutoSize(); }
            InvalidateUnion(oldBounds);
        }
    }

    public bool AutoSize
    {
        get { return _autoSize; }
        set
        {
            if (_autoSize == value) { return; }
            Rectangle oldBounds = InvalidationBounds;
            _autoSize = value;
            if (_autoSize) { UpdateAutoSize(); }
            InvalidateUnion(oldBounds);
        }
    }

    public int Left { get { return _left; } set { SetBounds(value, _top, _width, _height); } }
    public int Top { get { return _top; } set { SetBounds(_left, value, _width, _height); } }
    public int Width { get { return _width; } set { SetBounds(_left, _top, value, _height); } }
    public int Height { get { return _height; } set { SetBounds(_left, _top, _width, value); } }
    public int Right { get { return _left + _width; } }
    public int Bottom { get { return _top + _height; } }

    public Font Font
    {
        get { return _font ?? _owner.Font; }
        set
        {
            if (Object.ReferenceEquals(_font, value)) { return; }
            Rectangle oldBounds = InvalidationBounds;
            _font = value;
            InvalidateMeasureCache();
            if (_autoSize) { UpdateAutoSize(); }
            InvalidateUnion(oldBounds);
        }
    }

    public Color ForeColor
    {
        get { return _foreColor.IsEmpty ? _owner.ForeColor : _foreColor; }
        set
        {
            if (_foreColor.ToArgb() == value.ToArgb()) { return; }
            _foreColor = value;
            _owner.Invalidate(InvalidationBounds);
        }
    }

    public Color BackColor
    {
        get { return _backColor; }
        set
        {
            if (_backColor.ToArgb() == value.ToArgb()) { return; }
            _backColor = value;
            _owner.Invalidate(InvalidationBounds);
        }
    }

    public bool Visible
    {
        get { return _visible; }
        set
        {
            if (_visible == value) { return; }
            _visible = value;
            _owner.Invalidate(InvalidationBounds);
        }
    }

    public bool UseMnemonic
    {
        get { return _useMnemonic; }
        set
        {
            if (_useMnemonic == value) { return; }
            _useMnemonic = value;
            InvalidateMeasureCache();
            if (_autoSize) { UpdateAutoSize(); }
            _owner.Invalidate(InvalidationBounds);
        }
    }

    public Cursor Cursor
    {
        get { return _cursor; }
        set { _cursor = value; }
    }

    public object Tag
    {
        get { return _tag; }
        set { _tag = value; }
    }

    public Padding Padding
    {
        get { return _padding; }
        set
        {
            _padding = value;
            InvalidateMeasureCache();
            if (_autoSize) { UpdateAutoSize(); }
            _owner.Invalidate(InvalidationBounds);
        }
    }

    public string AccessibleName
    {
        get { return _accessibleName; }
        set { _accessibleName = value ?? String.Empty; }
    }

    public string AccessibleDescription
    {
        get { return _accessibleDescription; }
        set { _accessibleDescription = value ?? String.Empty; }
    }

    public event EventHandler Click;
    public event EventHandler DoubleClick;
    public event EventHandler MouseEnter;
    public event EventHandler MouseLeave;

    public void SetBounds(int left, int top, int width, int height)
    {
        Rectangle oldBounds = InvalidationBounds;
        _left = left;
        _top = top;
        _width = Math.Max(0, width);
        _height = Math.Max(0, height);
        InvalidateUnion(oldBounds);
    }

    public Size GetPreferredSize(Size proposedSize)
    {
        Font f = Font;
        string measureText = String.IsNullOrEmpty(_text) ? " " : _text;
        if (_measureCacheValid && Object.ReferenceEquals(_measureCacheFont, f) && _measureCacheUseMnemonic == _useMnemonic && _measureCachePadding.Equals(_padding) && String.Equals(_measureCacheText, measureText, StringComparison.Ordinal))
        {
            return _measureCacheSize;
        }
        TextFormatFlags flags = TextFormatFlags.NoPadding;
        if (!_useMnemonic) { flags |= TextFormatFlags.NoPrefix; }
        Size measured = TextRenderer.MeasureText(measureText, f, new Size(32767, 32767), flags);
        Size result = new Size(measured.Width + _padding.Left + _padding.Right, measured.Height + _padding.Top + _padding.Bottom);
        _measureCacheText = measureText;
        _measureCacheFont = f;
        _measureCacheUseMnemonic = _useMnemonic;
        _measureCachePadding = _padding;
        _measureCacheSize = result;
        _measureCacheValid = true;
        return result;
    }

    public void BringToFront() { }
    public void SuspendLayout() { }
    public void ResumeLayout(bool performLayout) { }
    public void Refresh() { _owner.Refresh(); }
    public void Invalidate() { _owner.Invalidate(InvalidationBounds); }

    internal Rectangle Bounds { get { return new Rectangle(_left, _top, _width, _height); } }
    internal Rectangle InvalidationBounds
    {
        get
        {
            Rectangle r = Bounds;
            r.Inflate(3, 3);
            return r;
        }
    }

    internal bool HitTest(Point p)
    {
        return _visible && _width > 0 && _height > 0 && Bounds.Contains(p);
    }

    internal void Draw(Graphics g)
    {
        if (!_visible || _width <= 0 || _height <= 0) { return; }
        Rectangle bounds = Bounds;
        if (!_backColor.IsEmpty && _backColor.A > 0)
        {
            using (SolidBrush b = new SolidBrush(_backColor)) { g.FillRectangle(b, bounds); }
        }
        Rectangle textBounds = new Rectangle(
            bounds.Left + _padding.Left,
            bounds.Top + _padding.Top,
            Math.Max(1, bounds.Width - _padding.Left - _padding.Right),
            Math.Max(1, bounds.Height - _padding.Top - _padding.Bottom));
        TextFormatFlags flags = TextFormatFlags.NoPadding | TextFormatFlags.Left | TextFormatFlags.Top;
        if (!_useMnemonic) { flags |= TextFormatFlags.NoPrefix; }
        TextRenderer.DrawText(g, _text, Font, textBounds, ForeColor, _backColor.IsEmpty ? _owner.BackColor : _backColor, flags);
    }

    internal void RaiseClick()
    {
        EventHandler handler = Click;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void RaiseDoubleClick()
    {
        EventHandler handler = DoubleClick;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void RaiseMouseEnter()
    {
        EventHandler handler = MouseEnter;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void RaiseMouseLeave()
    {
        EventHandler handler = MouseLeave;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void Rehome(DeviceEditorSurface owner, int offsetX, int offsetY)
    {
        if (owner == null) { return; }
        _owner = owner;
        _left += offsetX;
        _top += offsetY;
    }

    private void InvalidateMeasureCache()
    {
        _measureCacheValid = false;
        _measureCacheText = null;
        _measureCacheFont = null;
        _measureCacheSize = Size.Empty;
    }

    private void UpdateAutoSize()
    {
        Size s = GetPreferredSize(Size.Empty);
        _width = s.Width;
        _height = s.Height;
    }

    private void InvalidateUnion(Rectangle oldBounds)
    {
        Rectangle newBounds = InvalidationBounds;
        if (oldBounds.Width > 0 && oldBounds.Height > 0) { newBounds = Rectangle.Union(oldBounds, newBounds); }
        _owner.Invalidate(newBounds);
    }
}

public sealed class DeviceEditorBorderElement
{
    private DeviceEditorSurface _owner;
    private int _left;
    private int _top;
    private int _width;
    private int _height;
    private Color _backColor;
    private Color _borderColor;
    private bool _visible;

    internal DeviceEditorBorderElement(DeviceEditorSurface owner, int left, int top, int width, int height, Color backColor, Color borderColor)
    {
        _owner = owner;
        _left = left;
        _top = top;
        _width = Math.Max(0, width);
        _height = Math.Max(0, height);
        _backColor = backColor;
        _borderColor = borderColor;
        _visible = true;
    }

    public int Left { get { return _left; } set { SetBounds(value, _top, _width, _height); } }
    public int Top { get { return _top; } set { SetBounds(_left, value, _width, _height); } }
    public int Width { get { return _width; } set { SetBounds(_left, _top, value, _height); } }
    public int Height { get { return _height; } set { SetBounds(_left, _top, _width, value); } }
    public int Right { get { return _left + _width; } }
    public int Bottom { get { return _top + _height; } }
    public Color BackColor { get { return _backColor; } set { _backColor = value; _owner.Invalidate(Bounds); } }
    public Color BorderColor { get { return _borderColor; } set { _borderColor = value; _owner.Invalidate(Bounds); } }
    public bool Visible { get { return _visible; } set { _visible = value; _owner.Invalidate(Bounds); } }
    public Rectangle Bounds { get { return new Rectangle(_left, _top, _width, _height); } }
    public void SuspendLayout() { }
    public void ResumeLayout(bool performLayout) { }

    public void SetBounds(int left, int top, int width, int height)
    {
        Rectangle oldBounds = Bounds;
        _left = left;
        _top = top;
        _width = Math.Max(0, width);
        _height = Math.Max(0, height);
        _owner.Invalidate(Rectangle.Union(oldBounds, Bounds));
    }

    internal void Rehome(DeviceEditorSurface owner, int offsetX, int offsetY)
    {
        if (owner == null) { return; }
        _owner = owner;
        _left += offsetX;
        _top += offsetY;
    }

    internal void Draw(Graphics g)
    {
        if (!_visible || _width <= 0 || _height <= 0) { return; }
        Rectangle r = Bounds;
        using (SolidBrush b = new SolidBrush(_backColor)) { g.FillRectangle(b, r); }
        ControlPaint.DrawBorder(g, r, _borderColor, ButtonBorderStyle.Solid);
    }
}

