public class DeviceEditorSurface : Control
{
    private readonly List<DeviceEditorFrameElement> _frameElements;
    private readonly List<DeviceEditorTextElement> _textElements;
    private readonly List<DeviceEditorBorderElement> _borderElements;
    private DeviceEditorTextElement _hoverElement;
    private int _virtualUpdateDepth;
    private bool _hasPendingInvalidation;
    private Rectangle _pendingInvalidation;

    public DeviceEditorSurface()
    {
        _frameElements = new List<DeviceEditorFrameElement>();
        _textElements = new List<DeviceEditorTextElement>();
        _borderElements = new List<DeviceEditorBorderElement>();
        _hoverElement = null;
        _virtualUpdateDepth = 0;
        _hasPendingInvalidation = false;
        _pendingInvalidation = Rectangle.Empty;
        DrawOuterFrame = true;
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        TabStop = false;
        UpdateStyles();
    }

    public bool DrawOuterFrame { get; set; }

    public void MovePaintModelTo(DeviceEditorSurface target, int offsetX, int offsetY)
    {
        if (target == null || Object.ReferenceEquals(target, this)) { return; }
        target.SuspendLayout();
        try
        {
            if (DrawOuterFrame)
            {
                target._frameElements.Add(new DeviceEditorFrameElement(target, Text, Font, ForeColor, BackColor, offsetX, offsetY, Width, Height));
            }
            for (int i = 0; i < _borderElements.Count; i++)
            {
                DeviceEditorBorderElement border = _borderElements[i];
                if (border == null) { continue; }
                border.Rehome(target, offsetX, offsetY);
                target._borderElements.Add(border);
            }
            for (int i = 0; i < _textElements.Count; i++)
            {
                DeviceEditorTextElement element = _textElements[i];
                if (element == null) { continue; }
                element.Rehome(target, offsetX, offsetY);
                target._textElements.Add(element);
            }
            _frameElements.Clear();
            _borderElements.Clear();
            _textElements.Clear();
            target.InvalidateVirtual(Rectangle.Empty);
        }
        finally
        {
            target.ResumeLayout(false);
        }
    }

    public DeviceEditorTextElement CreateTextElement()
    {
        DeviceEditorTextElement element = new DeviceEditorTextElement(this);
        _textElements.Add(element);
        InvalidateVirtual(Rectangle.Empty);
        return element;
    }

    public DeviceEditorBorderElement AddBorderElement(int left, int top, int width, int height, Color backColor, Color borderColor)
    {
        DeviceEditorBorderElement element = new DeviceEditorBorderElement(this, left, top, width, height, backColor, borderColor);
        _borderElements.Add(element);
        InvalidateVirtual(element.Bounds);
        return element;
    }

    public new void SuspendLayout()
    {
        _virtualUpdateDepth++;
        base.SuspendLayout();
    }

    public new void ResumeLayout(bool performLayout)
    {
        if (_virtualUpdateDepth > 0) { _virtualUpdateDepth--; }
        base.ResumeLayout(performLayout);
        if (_virtualUpdateDepth == 0 && _hasPendingInvalidation)
        {
            Rectangle pending = _pendingInvalidation;
            _hasPendingInvalidation = false;
            _pendingInvalidation = Rectangle.Empty;
            if (pending.Width <= 0 || pending.Height <= 0) { base.Invalidate(); }
            else { base.Invalidate(pending); }
        }
    }

    public new void Invalidate()
    {
        InvalidateVirtual(Rectangle.Empty);
    }

    public new void Invalidate(Rectangle rc)
    {
        InvalidateVirtual(rc);
    }

    internal void InvalidateVirtual(Rectangle rc)
    {
        if (IsDisposed) { return; }
        if (_virtualUpdateDepth > 0)
        {
            if (rc.Width <= 0 || rc.Height <= 0)
            {
                _pendingInvalidation = Rectangle.Empty;
                _hasPendingInvalidation = true;
                return;
            }
            if (!_hasPendingInvalidation)
            {
                _pendingInvalidation = rc;
                _hasPendingInvalidation = true;
            }
            else if (_pendingInvalidation.Width > 0 && _pendingInvalidation.Height > 0)
            {
                _pendingInvalidation = Rectangle.Union(_pendingInvalidation, rc);
            }
            return;
        }
        if (rc.Width <= 0 || rc.Height <= 0) { base.Invalidate(); }
        else { base.Invalidate(rc); }
    }

    public int VirtualContentBottom
    {
        get
        {
            int bottom = 0;
            foreach (DeviceEditorFrameElement frame in _frameElements)
            {
                if (frame.Bottom > bottom) { bottom = frame.Bottom; }
            }
            foreach (DeviceEditorTextElement element in _textElements)
            {
                if (element.Visible && element.Bottom > bottom) { bottom = element.Bottom; }
            }
            foreach (DeviceEditorBorderElement element in _borderElements)
            {
                if (element.Visible && element.Bottom > bottom) { bottom = element.Bottom; }
            }
            return bottom;
        }
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);

        Rectangle clip = e.ClipRectangle;
        if (clip.Width <= 0 || clip.Height <= 0) { return; }

        using (SolidBrush b = new SolidBrush(BackColor))
        {
            e.Graphics.FillRectangle(b, clip);
        }

        e.Graphics.TextRenderingHint = System.Drawing.Text.TextRenderingHint.SystemDefault;

        if (DrawOuterFrame && ClientRectangle.IntersectsWith(clip))
        {
            DrawGroupFrame(e.Graphics);
        }

        for (int i = 0; i < _frameElements.Count; i++)
        {
            DeviceEditorFrameElement frame = _frameElements[i];
            if (frame != null && frame.Bounds.IntersectsWith(clip))
            {
                frame.Draw(e.Graphics);
            }
        }

        for (int i = 0; i < _borderElements.Count; i++)
        {
            DeviceEditorBorderElement border = _borderElements[i];
            if (border != null && border.Visible && border.Bounds.IntersectsWith(clip))
            {
                border.Draw(e.Graphics);
            }
        }

        for (int i = 0; i < _textElements.Count; i++)
        {
            DeviceEditorTextElement element = _textElements[i];
            if (element != null && element.Visible && element.Bounds.IntersectsWith(clip))
            {
                element.Draw(e.Graphics);
            }
        }
    }

    private void DrawGroupFrame(Graphics g)
    {
        ExovanceVisuals.CardFrame(g, new Rectangle(0, 0, Width, Height), Text, Font);
    }

    protected override void OnMouseMove(MouseEventArgs e)
    {
        base.OnMouseMove(e);
        DeviceEditorTextElement hit = HitTestTextElement(e.Location);
        if (!Object.ReferenceEquals(hit, _hoverElement))
        {
            if (_hoverElement != null) { _hoverElement.RaiseMouseLeave(); }
            _hoverElement = hit;
            if (_hoverElement != null) { _hoverElement.RaiseMouseEnter(); }
        }
        Cursor targetCursor = (hit != null && hit.Cursor != null) ? hit.Cursor : DefaultCursor;
        if (!Object.ReferenceEquals(Cursor, targetCursor)) { Cursor = targetCursor; }
    }

    protected override void OnMouseLeave(EventArgs e)
    {
        if (_hoverElement != null)
        {
            _hoverElement.RaiseMouseLeave();
            _hoverElement = null;
        }
        Cursor = DefaultCursor;
        base.OnMouseLeave(e);
    }

    protected override void OnMouseClick(MouseEventArgs e)
    {
        DeviceEditorTextElement hit = HitTestTextElement(e.Location);
        if (hit != null) { hit.RaiseClick(); }
        base.OnMouseClick(e);
    }

    protected override void OnMouseDoubleClick(MouseEventArgs e)
    {
        DeviceEditorTextElement hit = HitTestTextElement(e.Location);
        if (hit != null) { hit.RaiseDoubleClick(); }
        base.OnMouseDoubleClick(e);
    }

    private DeviceEditorTextElement HitTestTextElement(Point p)
    {
        for (int i = _textElements.Count - 1; i >= 0; i--)
        {
            DeviceEditorTextElement element = _textElements[i];
            if (element.HitTest(p)) { return element; }
        }
        return null;
    }
}

