public sealed class OrangeCheckBox : CheckBox
{
    private bool _hover;

    public OrangeCheckBox()
    {
        _hover = false;
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        FlatStyle = FlatStyle.Flat;
        TextAlign = ContentAlignment.MiddleLeft;
        TabStop = true;
        UpdateStyles();
    }

    protected override void OnMouseEnter(EventArgs e)
    {
        _hover = true;
        Invalidate();
        base.OnMouseEnter(e);
    }

    protected override void OnMouseLeave(EventArgs e)
    {
        _hover = false;
        Invalidate();
        base.OnMouseLeave(e);
    }

    protected override void OnCheckedChanged(EventArgs e)
    {
        Invalidate();
        if (Focused) { ExovanceInteractionState.MarkChanged(); }
        base.OnCheckedChanged(e);
    }

    protected override void OnEnabledChanged(EventArgs e)
    {
        Invalidate();
        base.OnEnabledChanged(e);
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        g.Clear(BackColor);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        bool active = Enabled && Checked;
        Rectangle rect = new Rectangle(0, 0, Math.Max(2, Width - 1), Math.Max(2, Height - 1));
        Color fill = ExovancePalette.CpuFill(active, Enabled && _hover);
        using (GraphicsPath path = ExovanceVisuals.Round(rect, 5))
        using (SolidBrush brush = new SolidBrush(fill)) { g.FillPath(brush, path); }
        int y = Math.Max(2, (Height - 10) / 2);
        using (Pen edge = new Pen(active ? ExovancePalette.Accent : ExovancePalette.Muted)) { g.DrawRectangle(edge, 3, y, 10, 10); }
        if (Checked) {
            using (Pen check = new Pen(Enabled ? ExovancePalette.Accent : ExovancePalette.Muted, 1.5f)) {
                g.DrawLines(check, new PointF[] { new PointF(4, y+5), new PointF(7, y+8), new PointF(12, y+2) });
            }
        }
        TextRenderer.DrawText(g, Text, Font, new Rectangle(18, 0, Math.Max(1, Width - 18), Height), active ? ExovancePalette.Accent : (Enabled ? ForeColor : ExovancePalette.Muted), fill,
            TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis);
        if (Focused && ShowFocusCues) { ControlPaint.DrawFocusRectangle(g, Rectangle.Inflate(rect, -1, -1)); }
    }
}

