public sealed class DeviceRow
{
    public object Source;
    public string Category;
    public string Role;
    public string DisplayName;
    public string RegistryPath;
    public string ConfigPath;
    public string UsbHeaderTitle;
    public string UsbEndpointUsageLabel;
    public string StorageType;
    public string BusType;
    public string PhysicalDrivePath;
    public string PNPID;
    public string DiskPNPID;
    public string ClassCode;
    public bool IsHdaController;
    public int DiskIndex;
    public string RegistryPathDisplay;
    public string ConfigPathDisplay;
    public bool HasConfigPath;
    public bool HasUsbHeaderTitle;
    public bool IsStorage;

    public static DeviceRow FromObject(object source)
    {
        DeviceRow row = new DeviceRow();
        row.Source = source;
        PropertyDescriptorCollection props = GetPropertiesSafe(source);
        row.Category = GetString(source, props, "Category");
        row.Role = GetString(source, props, "Role");
        row.DisplayName = GetString(source, props, "DisplayName");
        row.RegistryPath = GetString(source, props, "RegistryPath");
        object configPathValue = GetValue(source, props, "ConfigPath");
        object usbHeaderTitleValue = GetValue(source, props, "UsbHeaderTitle");
        row.ConfigPath = configPathValue == null ? String.Empty : Convert.ToString(configPathValue);
        row.UsbHeaderTitle = usbHeaderTitleValue == null ? String.Empty : Convert.ToString(usbHeaderTitleValue);
        row.HasConfigPath = configPathValue != null;
        row.HasUsbHeaderTitle = usbHeaderTitleValue != null;
        row.UsbEndpointUsageLabel = GetString(source, props, "UsbEndpointUsageLabel");
        row.StorageType = GetString(source, props, "StorageType");
        row.BusType = GetString(source, props, "BusType");
        row.PhysicalDrivePath = GetString(source, props, "PhysicalDrivePath");
        row.PNPID = GetString(source, props, "PNPID");
        row.DiskPNPID = GetString(source, props, "DiskPNPID");
        row.ClassCode = GetString(source, props, "ClassCode");
        row.IsHdaController = GetBool(source, props, "IsHdaController", false);
        row.DiskIndex = GetInt(source, props, "DiskIndex", -1);
        row.RegistryPathDisplay = row.RegistryPath;
        row.ConfigPathDisplay = row.ConfigPath;
        row.IsStorage = EqualsIgnoreCase(row.Role, "Storage") || EqualsIgnoreCase(row.Category, "SSD") || EqualsIgnoreCase(row.Category, "HDD");
        return row;
    }

    internal static PropertyDescriptorCollection GetPropertiesSafe(object source)
    {
        if (source == null) { return null; }
        try { return TypeDescriptor.GetProperties(source); } catch { return null; }
    }

    internal static string GetString(object source, string name)
    {
        return GetString(source, GetPropertiesSafe(source), name);
    }

    internal static string GetString(object source, PropertyDescriptorCollection props, string name)
    {
        object value = GetValue(source, props, name);
        return value == null ? String.Empty : Convert.ToString(value);
    }

    internal static int GetInt(object source, string name, int fallback)
    {
        return GetInt(source, GetPropertiesSafe(source), name, fallback);
    }

    internal static int GetInt(object source, PropertyDescriptorCollection props, string name, int fallback)
    {
        object value = GetValue(source, props, name);
        if (value == null) { return fallback; }
        try { return Convert.ToInt32(value); } catch { return fallback; }
    }

    internal static bool GetBool(object source, PropertyDescriptorCollection props, string name, bool fallback)
    {
        object value = GetValue(source, props, name);
        if (value == null) { return fallback; }
        try { return Convert.ToBoolean(value, CultureInfo.InvariantCulture); } catch { return fallback; }
    }

    internal static object GetValue(object source, string name)
    {
        return GetValue(source, GetPropertiesSafe(source), name);
    }

    internal static object GetValue(object source, PropertyDescriptorCollection props, string name)
    {
        if (source == null || String.IsNullOrEmpty(name)) { return null; }
        try
        {
            if (props != null)
            {
                PropertyDescriptor pd = props.Find(name, true);
                if (pd != null) { return pd.GetValue(source); }
            }
        }
        catch { }
        try
        {
            System.Reflection.PropertyInfo pi = source.GetType().GetProperty(name, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.IgnoreCase);
            if (pi != null) { return pi.GetValue(source, null); }
        }
        catch { }
        try
        {
            System.Reflection.FieldInfo fi = source.GetType().GetField(name, System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.IgnoreCase);
            if (fi != null) { return fi.GetValue(source); }
        }
        catch { }
        return null;
    }

    internal static bool EqualsIgnoreCase(string left, string right)
    {
        return String.Equals(left ?? String.Empty, right ?? String.Empty, StringComparison.OrdinalIgnoreCase);
    }
}

