public sealed class StartupUiStateMap
{
    private readonly Dictionary<string, DeviceEditorStartupState> _states;

    public StartupUiStateMap()
    {
        _states = new Dictionary<string, DeviceEditorStartupState>(StringComparer.Ordinal);
    }

    public static StartupUiStateMap FromObject(object source)
    {
        StartupUiStateMap map = new StartupUiStateMap();
        if (source == null) { return map; }

        IDictionary dict = source as IDictionary;
        if (dict != null)
        {
            foreach (DictionaryEntry entry in dict) { map.AddEntry(entry.Key, entry.Value); }
            return map;
        }

        IEnumerable enumerable = source as IEnumerable;
        if (enumerable == null) { return map; }
        foreach (object item in enumerable)
        {
            if (item == null) { continue; }
            object key = null;
            object value = null;
            try
            {
                PropertyDescriptorCollection props = TypeDescriptor.GetProperties(item);
                PropertyDescriptor keyProp = props == null ? null : props["Key"];
                PropertyDescriptor valueProp = props == null ? null : props["Value"];
                if (keyProp != null) { key = keyProp.GetValue(item); }
                if (valueProp != null) { value = valueProp.GetValue(item); }
            }
            catch { }
            map.AddEntry(key, value);
        }
        return map;
    }

    private void AddEntry(object keyObject, object valueObject)
    {
        string key = keyObject == null ? String.Empty : Convert.ToString(keyObject);
        if (String.IsNullOrEmpty(key)) { return; }
        DeviceEditorStartupState state = valueObject as DeviceEditorStartupState;
        if (state == null) { state = DeviceEditorStartupState.FromObject(valueObject); }
        if (state != null) { _states[key] = state; }
    }

    public DeviceEditorStartupState GetForRow(DeviceRow row)
    {
        if (row == null) { return null; }
        DeviceEditorStartupState state;
        string key = DeviceEditorBuilder.BuildCacheKey(row);
        if (!String.IsNullOrEmpty(key) && _states.TryGetValue(key, out state)) { return state; }
        if (!String.IsNullOrEmpty(row.RegistryPath) && _states.TryGetValue(row.RegistryPath, out state)) { return state; }
        return null;
    }
}

