public enum ScrollFeel
{
    Smooth,
    Balanced,
    HyperLowLatency
}

public static class DeviceTweakerScrollDynamics
{
    // Smooth: visually soft, stable on 60/120/144 Hz.
    public const double SmoothTauMs = 42.0;
    public const double SmoothMinAlpha = 0.22;
    public const double SmoothMaxFrameMs = 28.0;

    // Balanced: closest to the old version's feel.
    public const double BalancedTauMs = 30.0;
    public const double BalancedMinAlpha = 0.42;
    public const double BalancedMaxFrameMs = 28.0;

    // HyperLowLatency: mostly used by horizontal/internal smooth helpers;
    // main vertical scroll remains direct.
    public const double HyperLowLatencyTauMs = 18.0;
    public const double HyperLowLatencyMinAlpha = 0.55;
    public const double HyperLowLatencyMaxFrameMs = 12.0;

    // Avoid tiny micro-steps that create too many paint frames.
    public const double MinStepPx = 0.75;
    public const double CompletionPx = 0.55;
    private static int _scrollFeel = (int)ScrollFeel.HyperLowLatency;

    public static ScrollFeel CurrentFeel
    {
        get { return NormalizeFeel((ScrollFeel)Volatile.Read(ref _scrollFeel)); }
        set { Volatile.Write(ref _scrollFeel, (int)NormalizeFeel(value)); }
    }

    public static double VerticalTauMs { get { return TauMs; } }
    public static double HorizontalTextTauMs { get { return TauMs; } }
    public static double HorizontalLabelTauMs { get { return TauMs; } }
    public static double MaxFrameMs { get { return FrameMs; } }
    public static double MinAlpha { get { return AlphaMin; } }

    public static void SetScrollFeel(string value)
    {
        if (value == null) { throw new ArgumentNullException("value", "ScrollFeel cannot be null. Valid values: Smooth, Balanced, Hybrid, HyperLowLatency."); }
        string v = value.Trim();
        if (String.Equals(v, "Smooth", StringComparison.OrdinalIgnoreCase)) { CurrentFeel = ScrollFeel.Smooth; return; }
        if (String.Equals(v, "Balanced", StringComparison.OrdinalIgnoreCase) || String.Equals(v, "Hybrid", StringComparison.OrdinalIgnoreCase)) { CurrentFeel = ScrollFeel.Balanced; return; }
        if (String.Equals(v, "HyperLowLatency", StringComparison.OrdinalIgnoreCase)) { CurrentFeel = ScrollFeel.HyperLowLatency; return; }
        throw new ArgumentException("Unsupported ScrollFeel value '" + value + "'. Valid values: Smooth, Balanced, Hybrid, HyperLowLatency.", "value");
    }

    private static ScrollFeel NormalizeFeel(ScrollFeel feel)
    {
        if (feel == ScrollFeel.Smooth || feel == ScrollFeel.Balanced || feel == ScrollFeel.HyperLowLatency) { return feel; }
        return ScrollFeel.Balanced;
    }

    private static double TauMs
    {
        get
        {
            ScrollFeel feel = CurrentFeel;
            if (feel == ScrollFeel.Smooth) { return SmoothTauMs; }
            if (feel == ScrollFeel.HyperLowLatency) { return HyperLowLatencyTauMs; }
            return BalancedTauMs;
        }
    }

    private static double AlphaMin
    {
        get
        {
            ScrollFeel feel = CurrentFeel;
            if (feel == ScrollFeel.Smooth) { return SmoothMinAlpha; }
            if (feel == ScrollFeel.HyperLowLatency) { return HyperLowLatencyMinAlpha; }
            return BalancedMinAlpha;
        }
    }

    private static double FrameMs
    {
        get
        {
            ScrollFeel feel = CurrentFeel;
            if (feel == ScrollFeel.Smooth) { return SmoothMaxFrameMs; }
            if (feel == ScrollFeel.HyperLowLatency) { return HyperLowLatencyMaxFrameMs; }
            return BalancedMaxFrameMs;
        }
    }

    public static int Round(double value)
    {
        return (int)Math.Round(value, MidpointRounding.AwayFromZero);
    }

    public static bool Arrived(double current, double target, double completionPx)
    {
        double epsilon = completionPx <= 0.0 ? CompletionPx : completionPx;
        return Math.Abs(target - current) <= epsilon;
    }

    public static double ConsumeWheelDistance(ref double remainder, double delta, double minimumDistance)
    {
        if (Double.IsNaN(delta) || Double.IsInfinity(delta)) { return 0.0; }
        remainder += delta;
        double whole = Math.Truncate(remainder);
        remainder -= whole;
        double threshold = minimumDistance <= 0.0 ? CompletionPx : minimumDistance;
        if (whole == 0.0 && Math.Abs(remainder) >= threshold)
        {
            whole = Math.Sign(remainder);
            remainder -= whole;
        }
        return whole;
    }

    public static double Next(double current, double target, Stopwatch frameWatch, double tauMs, double minAlpha, double maxFrameMs, double minStepPx)
    {
        if (Double.IsNaN(current) || Double.IsInfinity(current)) { current = 0.0; }
        if (Double.IsNaN(target) || Double.IsInfinity(target)) { target = 0.0; }
        if (frameWatch == null) { return target; }
        double diff = target - current;
        if (diff == 0.0) { frameWatch.Restart(); return target; }
        double dt = frameWatch.Elapsed.TotalMilliseconds;
        frameWatch.Restart();
        if (Double.IsNaN(dt) || Double.IsInfinity(dt) || dt <= 0.0) { dt = 0.50; }
        double maxFrame = maxFrameMs <= 0.0 ? MaxFrameMs : maxFrameMs;
        if (dt > maxFrame) { dt = maxFrame; }
        double tau = tauMs <= 0.0 ? VerticalTauMs : tauMs;
        double alpha = 1.0 - Math.Exp(-dt / tau);
        double floor = minAlpha < 0.0 ? 0.0 : minAlpha;
        if (alpha < floor) { alpha = floor; }
        if (alpha > 1.0) { alpha = 1.0; }
        double next = current + diff * alpha;
        double step = minStepPx < 0.0 ? 0.0 : minStepPx;
        if (step > 0.0 && Math.Abs(next - current) < step)
        {
            double signed = Math.Sign(diff) * Math.Min(Math.Abs(diff), step);
            next = current + signed;
        }
        if ((diff > 0.0 && next > target) || (diff < 0.0 && next < target)) { next = target; }
        return next;
    }

    public static double WheelPixelsForViewport(int viewportPixels, double basePixels, int burst)
    {
        ScrollFeel feel = CurrentFeel;

        if (feel == ScrollFeel.Smooth)
        {
            return 52.0;
        }

        if (feel == ScrollFeel.Balanced)
        {
            return 58.0;
        }

        // HyperLowLatency: slightly faster, but do not let burst acceleration explode.
        double burstGain = 1.0 + Math.Min(6, Math.Max(0, burst)) * 0.035;
        return 62.0 * burstGain;
    }
}

public sealed class DeviceEditorNativeScrollState : IDisposable
{
    public Form Form;
    public Control Viewport;
    public Control Inner;
    public Panel Track;
    public Panel Thumb;
    public int TrackWidth;
    public int ContentHeight;
    public int ViewHeight;
    public int ViewWidth;
    public int MaxScroll;
    public int TrackAvailable;
    public int ThumbHeight;
    public int LastScrollY;
    public double VisualY;
    public double TargetY;
    public double WheelPixels;
    public double WheelRemainder;
    public double SmoothTauMs;
    public double SmoothMinAlpha;
    public double SmoothMaxFrameMs;
    public double SmoothMinStepPx;
    public bool SmoothActive;
    public bool Dragging;
    public string DragMode;
    public int DragThumbOffset;

    private readonly Stopwatch _frameWatch;
    private readonly Stopwatch _wheelClock;
    private double _wheelLastMs;
    private int _wheelBurst;
    private int _wheelLastSign;
    private LowLatencyUiTicker _ticker;
    private MethodInvoker _frameInvoker;
    private WheelMessageFilter _wheelFilter;
    private bool _messageFilterInstalled;
    private bool _disposed;

    public DeviceEditorNativeScrollState(Form form, Control viewport, Control inner, Panel track, Panel thumb, int contentHeight, int trackWidth)
    {
        if (viewport == null) { throw new ArgumentNullException("viewport", "Native scroll state requires a non-null viewport control."); }
        if (inner == null) { throw new ArgumentNullException("inner", "Native scroll state requires a non-null inner content surface."); }
        if (track == null) { throw new ArgumentNullException("track", "Native scroll state requires a non-null vertical track panel."); }
        if (thumb == null) { throw new ArgumentNullException("thumb", "Native scroll state requires a non-null vertical thumb panel."); }
        Form = form;
        Viewport = viewport;
        Inner = inner;
        Track = track;
        Thumb = thumb;
        TrackWidth = Math.Max(1, trackWidth);
        ContentHeight = Math.Max(1, contentHeight);
        ThumbHeight = 30;
        WheelPixels = 52.0;
        SmoothTauMs = DeviceTweakerScrollDynamics.VerticalTauMs;
        SmoothMinAlpha = DeviceTweakerScrollDynamics.MinAlpha;
        SmoothMaxFrameMs = DeviceTweakerScrollDynamics.MaxFrameMs;
        SmoothMinStepPx = DeviceTweakerScrollDynamics.MinStepPx;
        DragMode = String.Empty;
        _frameWatch = Stopwatch.StartNew();
        _wheelClock = Stopwatch.StartNew();
        _wheelLastMs = -10000.0;
        AttachHandlers();
        UpdateLayout();
    }

    public static DeviceEditorNativeScrollState Attach(Form form, Control viewport, Control inner, Panel track, Panel thumb, int contentHeight, int trackWidth)
    {
        return new DeviceEditorNativeScrollState(form, viewport, inner, track, thumb, contentHeight, trackWidth);
    }

    public void UpdateContentHeight(int contentHeight)
    {
        ThrowIfDisposed();
        ContentHeight = Math.Max(1, contentHeight);
        UpdateLayout();
        RenderPosition(VisualY, true);
    }

    public void UpdateLayout()
    {
        ThrowIfDisposed();
        Size cs = Viewport.ClientSize;
        int viewH = Math.Max(1, cs.Height);
        int pw = Math.Max(1, cs.Width);
        int contentH = Math.Max(1, ContentHeight);
        int tw = Math.Max(1, TrackWidth);
        Inner.Left = 0;
        Inner.Height = contentH;
        Track.Top = 0;
        Track.Width = tw;
        Track.Height = viewH;
        Thumb.Width = tw;
        if (contentH <= viewH)
        {
            Track.Visible = false;
            Inner.Top = 0;
            Inner.Width = pw;
            ViewHeight = viewH;
            ViewWidth = Inner.Width;
            MaxScroll = 0;
            TrackAvailable = 0;
            ContentHeight = contentH;
            LastScrollY = 0;
            VisualY = 0.0;
            TargetY = 0.0;
            WheelRemainder = 0.0;
            StopSmooth();
            UpdateThumb(0.0);
            return;
        }
        Track.Visible = true;
        Inner.Width = Math.Max(1, pw - tw);
        Track.Left = Math.Max(0, pw - tw);
        int thumbH = DeviceTweakerScrollDynamics.Round(((double)viewH * (double)viewH) / (double)Math.Max(1, contentH));
        if (thumbH < 30) { thumbH = 30; }
        if (thumbH > viewH) { thumbH = viewH; }
        ThumbHeight = thumbH;
        SetThumbBoundsStable(Thumb.Top, thumbH);
        int maxScroll = Math.Max(0, contentH - viewH);
        int trackAvailable = Math.Max(0, viewH - thumbH);
        int curTop = Inner.Top;
        int currentScroll = curTop < 0 ? -curTop : 0;
        if (currentScroll > maxScroll) { currentScroll = maxScroll; }
        ViewHeight = viewH;
        ViewWidth = Inner.Width;
        MaxScroll = maxScroll;
        TrackAvailable = trackAvailable;
        LastScrollY = currentScroll;
        if (!SmoothActive) { VisualY = (double)currentScroll; }
        TargetY = Clamp(TargetY);
        VisualY = Clamp(VisualY);
        UpdateThumb(VisualY);
    }

    public void SetPosition(double scrollY, bool immediate, bool forceFull)
    {
        ThrowIfDisposed();
        if (MaxScroll <= 0) { return; }
        double target = Clamp(scrollY);
        TargetY = target;

        // HyperLowLatency is intentionally direct: no animation target, no timer merge, no delayed frame.
        // Every wheel tick / thumb move changes the content position immediately.
        if (immediate || DeviceTweakerScrollDynamics.CurrentFeel == ScrollFeel.HyperLowLatency)
        {
            StopSmooth();
            RenderPosition(target, forceFull);
            return;
        }

        EnsureTicker();
        if (!SmoothActive)
        {
            SmoothActive = true;
            _frameWatch.Restart();
            InvokeSmoothFrame();
            if (SmoothActive) { _ticker.Start(); }
        }
    }

    public void StopSmooth()
    {
        SmoothActive = false;
        if (_ticker != null) { _ticker.Stop(); }
        _frameWatch.Restart();
    }

    public void StopDrag()
    {
        Dragging = false;
        DragMode = String.Empty;
        if (Thumb != null && Thumb.Capture) { Thumb.Capture = false; }
        if (Track != null && Track.Capture) { Track.Capture = false; }
    }

    private void AttachHandlers()
    {
        Inner.MouseWheel += Inner_MouseWheel;
        Viewport.MouseWheel += Inner_MouseWheel;
        Track.MouseWheel += Inner_MouseWheel;
        Thumb.MouseWheel += Inner_MouseWheel;
        Inner.HandleCreated += Inner_HandleCreated;
        Track.MouseDown += Track_MouseDown;
        Track.MouseMove += Track_MouseMove;
        Track.MouseUp += Track_MouseUp;
        Track.MouseCaptureChanged += Track_MouseCaptureChanged;
        Thumb.MouseDown += Thumb_MouseDown;
        Thumb.MouseMove += Thumb_MouseMove;
        Thumb.MouseUp += Thumb_MouseUp;
        Thumb.MouseCaptureChanged += Thumb_MouseCaptureChanged;
        Viewport.Resize += Viewport_Resize;
        Viewport.MouseUp += Viewport_MouseUp;
        if (Form != null) { Form.Deactivate += Form_Deactivate; }
        _wheelFilter = new WheelMessageFilter();
        _wheelFilter.SetTarget(Inner, Viewport, Form);
        Application.AddMessageFilter(_wheelFilter);
        _messageFilterInstalled = true;
    }

    private void DetachHandlers()
    {
        Inner.MouseWheel -= Inner_MouseWheel;
        Viewport.MouseWheel -= Inner_MouseWheel;
        Track.MouseWheel -= Inner_MouseWheel;
        Thumb.MouseWheel -= Inner_MouseWheel;
        Inner.HandleCreated -= Inner_HandleCreated;
        Track.MouseDown -= Track_MouseDown;
        Track.MouseMove -= Track_MouseMove;
        Track.MouseUp -= Track_MouseUp;
        Track.MouseCaptureChanged -= Track_MouseCaptureChanged;
        Thumb.MouseDown -= Thumb_MouseDown;
        Thumb.MouseMove -= Thumb_MouseMove;
        Thumb.MouseUp -= Thumb_MouseUp;
        Thumb.MouseCaptureChanged -= Thumb_MouseCaptureChanged;
        Viewport.Resize -= Viewport_Resize;
        Viewport.MouseUp -= Viewport_MouseUp;
        if (Form != null) { Form.Deactivate -= Form_Deactivate; }
        if (_messageFilterInstalled && _wheelFilter != null)
        {
            Application.RemoveMessageFilter(_wheelFilter);
            _messageFilterInstalled = false;
        }
        _wheelFilter = null;
    }

    private void Inner_HandleCreated(object sender, EventArgs e)
    {
        if (_wheelFilter != null) { _wheelFilter.SetTarget(Inner, Viewport, Form); }
    }

    private double Clamp(double scrollY)
    {
        double m = (double)MaxScroll;
        if (m <= 0.0) { return 0.0; }
        if (Double.IsNaN(scrollY) || Double.IsInfinity(scrollY)) { return 0.0; }
        if (scrollY < 0.0) { return 0.0; }
        if (scrollY > m) { return m; }
        return scrollY;
    }

    private int RoundedY(double scrollY)
    {
        return DeviceTweakerScrollDynamics.Round(Clamp(scrollY));
    }

    private void RepaintThumbTrackUnion(int oldTop, int oldHeight, int newTop, int newHeight)
    {
        if (Track == null || Track.IsDisposed || !Track.IsHandleCreated) { return; }
        int trackH = Math.Max(1, Track.Height);
        int dirtyTop = Math.Max(0, Math.Min(oldTop, newTop) - 2);
        int dirtyBottom = Math.Min(trackH, Math.Max(oldTop + Math.Max(1, oldHeight), newTop + Math.Max(1, newHeight)) + 2);
        if (dirtyBottom <= dirtyTop) { dirtyBottom = Math.Min(trackH, dirtyTop + Math.Max(1, newHeight)); }
        Rectangle dirty = new Rectangle(0, dirtyTop, Math.Max(1, Track.Width), Math.Max(1, dirtyBottom - dirtyTop));
        try
        {
            // Do not synchronously paint the thumb in the middle of a content move; that is what
            // leaves stale mixed frames when the thumb is teleported. The scroll repaint below
            // flushes the final, already-moved state atomically.
            Track.Invalidate(dirty, false);
            if (Thumb != null && !Thumb.IsDisposed && Thumb.IsHandleCreated)
            {
                Thumb.Invalidate(false);
            }
        }
        catch { }
    }

    private void SetThumbBoundsStable(int top, int height)
    {
        if (Thumb == null || Thumb.IsDisposed) { return; }
        int trackH = Track == null ? Math.Max(1, height) : Math.Max(1, Track.Height);
        int safeH = Math.Max(1, Math.Min(trackH, height));
        int safeTop = Math.Max(0, Math.Min(Math.Max(0, trackH - safeH), top));
        int safeW = Math.Max(1, TrackWidth);
        int oldTop = Thumb.Top;
        int oldHeight = Math.Max(1, Thumb.Height);
        int oldWidth = Math.Max(1, Thumb.Width);
        if (oldTop == safeTop && oldHeight == safeH && oldWidth == safeW) { return; }
        Thumb.SetBounds(0, safeTop, safeW, safeH);
        RepaintThumbTrackUnion(oldTop, oldHeight, safeTop, safeH);
    }

    private void UpdateThumb(double scrollY)
    {
        double m = (double)MaxScroll;
        double ta = (double)TrackAvailable;
        if (m <= 0.0 || ta <= 0.0)
        {
            SetThumbBoundsStable(0, ThumbHeight > 0 ? ThumbHeight : Math.Max(1, Thumb.Height));
            return;
        }
        int newTop = DeviceTweakerScrollDynamics.Round((Clamp(scrollY) / m) * ta);
        if (newTop < 0) { newTop = 0; }
        if (newTop > TrackAvailable) { newTop = TrackAvailable; }
        SetThumbBoundsStable(newTop, ThumbHeight);
    }

    private void RenderPosition(double scrollY, bool forceFull)
    {
        int newY = RoundedY(scrollY);
        int prevY = LastScrollY;
        if (newY == prevY && Inner.Top == -newY)
        {
            VisualY = (double)newY;
            UpdateThumb(newY);
            return;
        }

        Inner.Top = -newY;
        VisualY = (double)newY;
        UpdateThumb(newY);

        Repaint(prevY, newY, forceFull);
        LastScrollY = newY;
    }

    private void Repaint(int prevY, int newY, bool forceFull)
    {
        IntPtr viewportHandle = Viewport != null && Viewport.IsHandleCreated ? Viewport.Handle : IntPtr.Zero;
        IntPtr innerHandle = Inner != null && Inner.IsHandleCreated ? Inner.Handle : IntPtr.Zero;
        IntPtr trackHandle = Track != null && Track.IsHandleCreated ? Track.Handle : IntPtr.Zero;

        int jump = Math.Abs(newY - prevY);

        // Same spirit as the old version: only full repaint on true jumps/teleports.
        if (forceFull || jump >= Math.Max(1, (int)(ViewHeight * 0.80)))
        {
            ScrollHelper.ScrollPaintAtomic(viewportHandle, innerHandle, trackHandle);
            return;
        }

        // Cheap path: repaint only the newly exposed strip.
        ScrollHelper.ScrollPaintSmart(innerHandle, prevY, newY, ViewHeight, ViewWidth, 6);

        // Thumb/track are small; repaint them separately.
        ScrollHelper.ScrollPaintTrack(trackHandle);

        // Flush parent once after content + track invalidation.
        ScrollHelper.FlushPaint(viewportHandle);
    }

    private void InvokeSmoothFrame()
    {
        if (_disposed || !SmoothActive) { return; }
        double target = Clamp(TargetY);
        double current = Clamp(VisualY);
        if (DeviceTweakerScrollDynamics.Arrived(current, target, DeviceTweakerScrollDynamics.CompletionPx))
        {
            RenderPosition(target, false);
            TargetY = target;
            StopSmooth();
            return;
        }
        double next = DeviceTweakerScrollDynamics.Next(current, target, _frameWatch, SmoothTauMs, SmoothMinAlpha, SmoothMaxFrameMs, SmoothMinStepPx);
        RenderPosition(Clamp(next), false);
    }

    private void EnsureTicker()
    {
        if (_ticker != null) { return; }
        if (_frameInvoker == null) { _frameInvoker = new MethodInvoker(InvokeSmoothFrame); }
        _ticker = new LowLatencyUiTicker(Inner, _frameInvoker, 1);
    }

    private double GetWheelPixels(int wheelSign)
    {
        double nowMs = _wheelClock.Elapsed.TotalMilliseconds;
        double gap = nowMs - _wheelLastMs;
        if (wheelSign != 0 && wheelSign == _wheelLastSign && gap >= 0.0 && gap <= 58.0)
        {
            if (_wheelBurst < 10) { _wheelBurst++; }
        }
        else
        {
            _wheelBurst = 0;
        }
        _wheelLastMs = nowMs;
        _wheelLastSign = wheelSign;
        return DeviceTweakerScrollDynamics.WheelPixelsForViewport(ViewHeight, WheelPixels, _wheelBurst);
    }

    private double ScrollYFromTrackClientY(int clientY, int thumbOffset)
    {
        double ta = (double)TrackAvailable;
        double m = (double)MaxScroll;
        if (ta <= 0.0 || m <= 0.0) { return 0.0; }
        double y = (double)(clientY - thumbOffset);
        if (y < 0.0) { y = 0.0; }
        if (y > ta) { y = ta; }
        return (y / ta) * m;
    }

    private void SetFromTrackClientY(int clientY, int thumbOffset, bool forceFull)
    {
        SetPosition(ScrollYFromTrackClientY(clientY, thumbOffset), true, forceFull);
    }

    private void Inner_MouseWheel(object sender, MouseEventArgs e)
    {
        if (WheelMessageFilter.SuspendRedirect) { return; }
        if (MaxScroll <= 0) { return; }
        int wheelSign = -Math.Sign(e.Delta);
        double wheelPixels = GetWheelPixels(wheelSign);
        double delta = -((double)e.Delta / 120.0) * wheelPixels;
        WheelRemainder += delta;
        double whole = Math.Truncate(WheelRemainder);
        WheelRemainder -= whole;
        if (whole == 0.0 && Math.Abs(WheelRemainder) >= 0.12)
        {
            whole = Math.Sign(WheelRemainder);
            WheelRemainder -= whole;
        }
        if (whole == 0.0) { return; }
        double baseY = SmoothActive ? TargetY : VisualY;
        SetPosition(baseY + whole, false, false);
        HandledMouseEventArgs handled = e as HandledMouseEventArgs;
        if (handled != null) { handled.Handled = true; }
    }

    private void Track_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Dragging = true;
        DragMode = "track";
        DragThumbOffset = ThumbHeight / 2;
        Track.Capture = true;
        SetFromTrackClientY(e.Y, DragThumbOffset, true);
    }

    private void Track_MouseMove(object sender, MouseEventArgs e)
    {
        if (!Dragging || !String.Equals(DragMode, "track", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopDrag(); return; }
        SetFromTrackClientY(e.Y, DragThumbOffset, false);
    }

    private void Track_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left) { StopDrag(); }
    }

    private void Track_MouseCaptureChanged(object sender, EventArgs e)
    {
        if (String.Equals(DragMode, "track", StringComparison.Ordinal) && !Track.Capture) { StopDrag(); }
    }

    private void Thumb_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Dragging = true;
        DragMode = "thumb";
        DragThumbOffset = e.Y;
        Thumb.Capture = true;
        StopSmooth();
    }

    private void Thumb_MouseMove(object sender, MouseEventArgs e)
    {
        if (!Dragging || !String.Equals(DragMode, "thumb", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopDrag(); return; }
        Point trackPoint = Track.PointToClient(Control.MousePosition);
        SetFromTrackClientY(trackPoint.Y, DragThumbOffset, false);
    }

    private void Thumb_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left) { StopDrag(); }
    }

    private void Thumb_MouseCaptureChanged(object sender, EventArgs e)
    {
        if (String.Equals(DragMode, "thumb", StringComparison.Ordinal) && !Thumb.Capture) { StopDrag(); }
    }

    private void Viewport_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left) { StopDrag(); }
    }

    private void Viewport_Resize(object sender, EventArgs e)
    {
        UpdateLayout();
        RenderPosition(Clamp(VisualY), true);
    }

    private void Form_Deactivate(object sender, EventArgs e)
    {
        StopDrag();
    }

    private void ThrowIfDisposed()
    {
        if (_disposed) { throw new ObjectDisposedException("DeviceEditorNativeScrollState", "Native scroll state was used after disposal."); }
    }

    public void Dispose()
    {
        if (_disposed) { return; }
        List<Exception> failures = new List<Exception>();
        try { StopDrag(); } catch (Exception ex) { failures.Add(new InvalidOperationException("Failed to stop native scrollbar drag during disposal.", ex)); }
        try { StopSmooth(); } catch (Exception ex) { failures.Add(new InvalidOperationException("Failed to stop native smooth-scroll ticker during disposal.", ex)); }
        try { DetachHandlers(); } catch (Exception ex) { failures.Add(new InvalidOperationException("Failed to detach native scrollbar handlers during disposal.", ex)); }
        if (_ticker != null)
        {
            try { _ticker.Dispose(); }
            catch (Exception ex) { failures.Add(new InvalidOperationException("Failed to dispose native smooth-scroll ticker.", ex)); }
            _ticker = null;
        }
        _disposed = true;
        if (failures.Count == 1) { throw failures[0]; }
        if (failures.Count > 1) { throw new AggregateException("Native scroll state disposal encountered multiple failures.", failures); }
    }
}

internal sealed class DeviceEditorScrollableTextLabel : Label
{
    private int _virtualOffset;
    private int _virtualTextWidth;
    private string _lastPaintError = String.Empty;
    private static readonly TextFormatFlags DrawFlags = TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoClipping | TextFormatFlags.VerticalCenter;
    private static readonly TextFormatFlags MeasureFlags = TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoClipping;

    public DeviceEditorScrollableTextLabel()
    {
        SetStyle(ControlStyles.UserPaint, true);
        SetStyle(ControlStyles.AllPaintingInWmPaint, true);
        SetStyle(ControlStyles.OptimizedDoubleBuffer, true);
        SetStyle(ControlStyles.ResizeRedraw, true);
        SetStyle(ControlStyles.SupportsTransparentBackColor, true);
    }

    public int VirtualOffset
    {
        get { return _virtualOffset; }
    }

    public int VirtualTextWidth
    {
        get { return _virtualTextWidth; }
    }

    public string LastPaintError
    {
        get { return _lastPaintError ?? String.Empty; }
    }

    private void SetPaintError(Exception ex, string stage)
    {
        if (ex == null) { return; }
        _lastPaintError = (stage ?? "paint") + ": " + ex.GetType().FullName + ": " + ex.Message;
        try { Console.Error.WriteLine("[NIC ITR][ERROR] Scrollable label paint failed: " + _lastPaintError); } catch { }
    }

    public void SetVirtualTextWidth(int width)
    {
        int safe = Math.Max(1, width);
        if (_virtualTextWidth == safe) { return; }
        _virtualTextWidth = safe;
        Invalidate();
    }

    public void SetVirtualOffset(int offset)
    {
        int safe = Math.Max(0, offset);
        if (_virtualOffset == safe) { return; }
        _virtualOffset = safe;
        Invalidate();
    }

    protected override void OnTextChanged(EventArgs e)
    {
        _lastPaintError = String.Empty;
        base.OnTextChanged(e);
        Invalidate();
    }

    protected override void OnFontChanged(EventArgs e)
    {
        _lastPaintError = String.Empty;
        base.OnFontChanged(e);
        Invalidate();
    }

    protected override void OnForeColorChanged(EventArgs e)
    {
        _lastPaintError = String.Empty;
        base.OnForeColorChanged(e);
        Invalidate();
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaintBackground(e);
        _lastPaintError = String.Empty;
        string text = Text;
        if (String.IsNullOrEmpty(text)) { return; }
        Font f = Font == null ? Control.DefaultFont : Font;
        int clientW = Math.Max(1, ClientSize.Width);
        int clientH = Math.Max(1, ClientSize.Height);
        int offset = Math.Max(0, _virtualOffset);

        // Draw the whole single-line text in one TextRenderer call whenever possible.
        // The old chunked renderer measured/drew 96-character slices independently;
        // GDI overhang/rounding at slice boundaries produced visual holes such as
        // "N IC" or "requir es" inside long NIC ITR diagnostic labels.
        int virtualW = Math.Max(clientW, Math.Max(1, _virtualTextWidth));
        if (virtualW <= 30000 || text.Length <= 4096)
        {
            int drawW = Math.Max(clientW + offset + 16, Math.Min(32760, virtualW + 16));
            Rectangle full = new Rectangle(-offset, 0, Math.Max(1, drawW), clientH);
            try { TextRenderer.DrawText(e.Graphics, text, f, full, ForeColor, DrawFlags); }
            catch (Exception ex) { SetPaintError(ex, "draw-full"); }
            return;
        }

        // Rare pathological fallback for extremely large text: use much larger chunks
        // so any unavoidable seam is far less frequent, and keep exact chunk order.
        int x = -offset;
        const int chunkSize = 1024;
        for (int i = 0; i < text.Length; i += chunkSize)
        {
            int len = Math.Min(chunkSize, text.Length - i);
            string chunk = text.Substring(i, len);
            int w = 0;
            try { w = TextRenderer.MeasureText(chunk, f, new Size(32767, 9999), MeasureFlags).Width; } catch (Exception ex) { SetPaintError(ex, "measure"); w = 0; }
            if (w <= 0) { w = Math.Max(1, len * Math.Max(5, f.Height / 2)); }

            if (x + w >= -8 && x <= clientW + 8)
            {
                Rectangle r = new Rectangle(x, 0, Math.Max(1, w + 16), clientH);
                try { TextRenderer.DrawText(e.Graphics, chunk, f, r, ForeColor, DrawFlags); } catch (Exception ex) { SetPaintError(ex, "draw-chunk"); }
            }

            x += w;
            if (x > clientW + 16) { break; }
        }
    }
}

internal static class DeviceEditorNativeUiSupport
{
    internal static bool DisableRWEnNVMe;
    private static readonly TextFormatFlags NoPad = TextFormatFlags.NoPadding;

    public static Hashtable CreateControlMap(DeviceRow row, DeviceEditorState state)
    {
        Hashtable map = new Hashtable();
        map["CheckBoxes"] = state.Cells;
        map["CpuGrid"] = state.Grid;
        map["MaskLabel"] = state.MaskLabel;
        map["MaskValue"] = state.MaskValue;
        map["InitialValue"] = state.InitialValue;
        map["InitialNumQueues"] = state.InitialNumQueues;
        map["NdisIrqAffinity"] = state.NdisIrqAffinity;
        map["MSICombo"] = state.MsiCombo;
        map["MsgLimitBox"] = state.MsgLimitBox;
        map["PriorityCombo"] = state.PriorityCombo;
        map["PNPID"] = String.IsNullOrWhiteSpace(state.PnpId) ? row.PNPID : state.PnpId;
        map["StorageType"] = row.StorageType;
        map["StorageBusType"] = row.BusType;
        map["StoragePhysicalDrivePath"] = row.PhysicalDrivePath;
        map["StorageDiskIndex"] = row.DiskIndex;
        map["StoragePNPID"] = row.PNPID;
        map["IRQLabel"] = state.IrqLabel;
        map["IRQValueLabel"] = state.IrqValueLabel;
        map["PolicyCombo"] = state.PolicyCombo;
        map["PolicyLabel"] = state.PolicyLabel;
        map["NumQueues"] = state.NumQueues;
        map["NumQueuesLabel"] = state.NumQueuesLabel;
        map["NdisIrqToggle"] = state.NdisIrqToggle;
        map["NativeState"] = state;
        return map;
    }

    public static void AddUsbImodControls(DeviceRow row, DeviceEditorState state, DeviceEditorTheme theme, Hashtable map, List<CheckBox> secretChecks, List<Button> usbSetButtons, List<Button> usbSaveButtons)
    {
        if (DisableRWEnNVMe) { return; }
        DeviceEditorControl groupBox = state.GroupBox;
        if (groupBox == null || state.RegistryPathElement == null) { return; }
        Panel imodPanel = new Panel();
        imodPanel.SuspendLayout();
        imodPanel.Left = 6;
        imodPanel.Top = state.RegistryPathElement.Bottom + 6;
        imodPanel.Width = groupBox.Width - 12;
        imodPanel.Height = 62;
        imodPanel.BackColor = Color.Transparent;
        groupBox.Controls.Add(imodPanel);

        int usbTextBoxH = 36;
        int usbButtonH = 28;
        int usbBottomPad = 2;
        int usbRowTop = imodPanel.Height - usbTextBoxH - usbBottomPad;
        int usbButtonTop = usbRowTop;
        int usbLabelTop = usbRowTop + 5;
        int usbInlineTop = usbRowTop + 2;

        Label lblIMOD = new Label();
        lblIMOD.Text = "IMOD INTERVAL:";
        lblIMOD.AutoSize = true;
        lblIMOD.Left = 0;
        lblIMOD.Top = usbLabelTop;
        if (theme.Font11 != null) { lblIMOD.Font = theme.Font11; }
        lblIMOD.ForeColor = theme.LightGray;
        lblIMOD.BackColor = Color.Transparent;
        imodPanel.Controls.Add(lblIMOD);

        TextBox txtNewIMOD = new TextBox();
        int usbVisibleValueCount = 4;
        txtNewIMOD.Width = GetHexVectorDisplayWidth(lblIMOD.Font, 4, usbVisibleValueCount, 220);
        txtNewIMOD.MaxLength = 32767;
        txtNewIMOD.Left = lblIMOD.Right + 10;
        txtNewIMOD.Top = usbRowTop;
        txtNewIMOD.Height = usbTextBoxH;
        txtNewIMOD.Multiline = true;
        txtNewIMOD.AcceptsReturn = false;
        txtNewIMOD.AcceptsTab = false;
        txtNewIMOD.WordWrap = false;
        txtNewIMOD.ScrollBars = ScrollBars.Horizontal;
        txtNewIMOD.Font = lblIMOD.Font;
        txtNewIMOD.BackColor = theme.DarkGray30;
        txtNewIMOD.ForeColor = theme.LightGray;
        txtNewIMOD.BorderStyle = BorderStyle.FixedSingle;
        txtNewIMOD.Text = "0x";
        Hashtable origTag = new Hashtable();
        origTag["ExpectedCount"] = 0;
        txtNewIMOD.Tag = origTag;
        imodPanel.Controls.Add(txtNewIMOD);

        DeviceEditorNativeHScrollResult usbHScroll = CreateTextBoxHScroll(txtNewIMOD, imodPanel, 10, theme.Black);
        DeviceTweakerUiHandlers.WireHexVectorTextBox(txtNewIMOD, false, 4);

        string usbWorstTime = "16383.75 µs";
        string usbWorstMulti = "Multiple values";
        int usbWTimeW = TextRenderer.MeasureText(usbWorstTime, lblIMOD.Font, new Size(9999, 99), NoPad).Width;
        int usbWMultiW = TextRenderer.MeasureText(usbWorstMulti, lblIMOD.Font, new Size(9999, 99), NoPad).Width;
        int usbNsNeeded = Math.Max(usbWTimeW, usbWMultiW) + 4;
        int usbGap3 = 11;
        int usbGap4 = 10;
        int usbGap5 = 10;
        int usbPadR = 5;
        int usbWSet = 60;
        int usbWSave = 80;
        string usbSecretText = "Per-device IMOD";
        Font usbSecretFont = theme.Font9 ?? lblIMOD.Font;
        Size usbSecretTextSize = TextRenderer.MeasureText(usbSecretText, usbSecretFont, new Size(9999, 99), NoPad);
        int usbSecretH = Math.Max(18, usbSecretTextSize.Height + 4);
        int usbSecretW = Math.Max(1, usbSecretTextSize.Width + 28);
        int usbButtonStackW = usbWSet + usbGap5 + usbWSave;
        int usbNsLeft = usbHScroll.ClipPanel.Right + usbGap3;
        int usbMinRight = usbNsLeft + usbNsNeeded + usbGap4 + usbButtonStackW + usbPadR;
        if (usbMinRight > imodPanel.Width) { imodPanel.Width = usbMinRight; }
        int usbXSet = imodPanel.Width - usbButtonStackW - usbPadR;
        int usbXSave = usbXSet + usbWSet + usbGap5;
        int usbNsW = Math.Max(usbNsNeeded, usbXSet - usbGap4 - usbNsLeft);

        DeviceEditorScrollableLabelResult usbScrollLabel = CreateScrollableLabel(imodPanel, usbNsLeft, usbInlineTop, usbNsW, 18, 8, lblIMOD.Font, theme.MidGray, theme.Black);
        Label lblIMODns = usbScrollLabel.Label;
        lblIMODns.Text = "Reading...";
        Hashtable lblTag = new Hashtable();
        lblTag["ScrollSync"] = usbScrollLabel.Sync;
        lblTag["ScrollState"] = usbScrollLabel.State;
        lblIMODns.Tag = lblTag;

        OrangeCheckBox chkSecretSave = new OrangeCheckBox();
        chkSecretSave.Text = usbSecretText;
        chkSecretSave.AutoSize = false;
        chkSecretSave.Font = usbSecretFont;
        chkSecretSave.ForeColor = theme.LightGray;
        chkSecretSave.BackColor = theme.Black;
        chkSecretSave.FlatStyle = FlatStyle.Flat;
        if (state.Grid != null && state.Grid.TextVerticalOffset != 0) { chkSecretSave.Padding = new Padding(0, state.Grid.TextVerticalOffset, 0, 0); }
        Size secretPreferred = new Size(Math.Max(1, Math.Min(usbSecretW, usbButtonStackW)), usbSecretH);
        chkSecretSave.Width = secretPreferred.Width;
        chkSecretSave.Height = secretPreferred.Height;
        int usbButtonPairW = (usbXSave + usbWSave) - usbXSet;
        int usbSecretCenteredLeft = usbXSet + (int)Math.Round((usbButtonPairW - secretPreferred.Width) / 2.0);
        chkSecretSave.Left = Math.Max(0, Math.Min(usbSecretCenteredLeft, imodPanel.Width - usbPadR - secretPreferred.Width));
        chkSecretSave.Top = Math.Max(0, usbButtonTop - secretPreferred.Height - 2);
        imodPanel.Controls.Add(chkSecretSave);
        if (secretChecks != null) { secretChecks.Add(chkSecretSave); }

        Button btnSetIMOD = CreateDarkButton("SET", usbWSet, usbButtonH, usbXSet, usbButtonTop, row.Source, theme, true);
        imodPanel.Controls.Add(btnSetIMOD);
        if (usbSetButtons != null) { usbSetButtons.Add(btnSetIMOD); }

        Button btnSave = CreateDarkButton("SAVE", usbWSave, usbButtonH, usbXSave, usbButtonTop, row.Source, theme, true);
        imodPanel.Controls.Add(btnSave);
        if (usbSaveButtons != null) { usbSaveButtons.Add(btnSave); }
        imodPanel.Width = btnSave.Right + usbPadR;

        map["CurrentIMOD"] = null;
        map["NewIMOD"] = txtNewIMOD;
        map["IMODNsLabel"] = lblIMODns;
        map["UsbImodPanel"] = imodPanel;
        map["SecretSaveCheckbox"] = chkSecretSave;
        map["UsbSetIMODButton"] = btnSetIMOD;
        map["UsbSaveIMODButton"] = btnSave;

        imodPanel.ResumeLayout(false);
    }

    public static void AddNicImodOrUnsupportedControls(DeviceRow row, DeviceEditorState state, DeviceEditorTheme theme, Hashtable map, List<Button> nicSetButtons, List<Button> nicSaveButtons)
    {
        if (DisableRWEnNVMe) { return; }
        DeviceEditorControl groupBox = state.GroupBox;
        if (groupBox == null || state.RegistryPathElement == null) { return; }
        Hashtable nicInfo = DeviceEditorNicImodCatalog.GetInfo(state.PnpId, row == null ? null : row.DisplayName);
        if (nicInfo == null)
        {
            DeviceEditorTextElement lblNicUnsup = groupBox.CreateTextElement();
            lblNicUnsup.Text = "NIC ITR: Unsupported";
            lblNicUnsup.AutoSize = true;
            lblNicUnsup.Left = 6;
            lblNicUnsup.Top = state.RegistryPathElement.Bottom + 12;
            if (theme.Font11 != null) { lblNicUnsup.Font = theme.Font11; }
            lblNicUnsup.ForeColor = theme.MidGray;
            return;
        }

        Panel nicImodPanel = new Panel();
        nicImodPanel.SuspendLayout();
        nicImodPanel.Left = 6;
        nicImodPanel.Top = state.RegistryPathElement.Bottom + 6;
        nicImodPanel.Width = Math.Max(1, groupBox.Width - 12);
        nicImodPanel.Height = 72;
        nicImodPanel.BackColor = Color.Transparent;
        groupBox.Controls.Add(nicImodPanel);

        int nicTextBoxH = 36;
        int nicButtonH = 28;
        int nicBottomPad = 2;
        int nicFamilyTop = 1;
        int nicFamilyViewH = 20;
        int nicFamilyTrackH = 8;
        int nicRowTop = nicImodPanel.Height - nicTextBoxH - nicBottomPad;
        int nicButtonTop = nicRowTop;
        int nicLabelTop = nicFamilyTop + 1;
        int nicInlineTop = nicRowTop + 2;
        string nicLabelText = "NIC ITR:";
        string nicFamilyText = "[" + Convert.ToString(nicInfo["FamilyName"]) + "]";
        Font nicFont = theme.Font11 ?? groupBox.Font;
        int wLbl = TextRenderer.MeasureText(nicLabelText, nicFont, new Size(9999, 99), NoPad).Width;
        int readWidth = ToInt(nicInfo["ReadWidth"], 32);
        int maxQueues = ToInt(nicInfo["MaxQueues"], 1);
        int nicHexDigits = readWidth == 16 ? 4 : (readWidth == 64 ? 16 : 8);
        int nicMinTextBoxWidth = readWidth == 16 ? 96 : (readWidth == 64 ? 180 : 150);
        // Keep the NIC ITR input compact like USB IMOD, but do not let a 32/64-bit
        // queue vector force the row wider than the screen. The textbox itself keeps
        // its horizontal scrollbar for the full vector.
        int nicVisibleValueCount = readWidth <= 16 ? Math.Max(1, Math.Min(maxQueues, 4)) : Math.Max(1, Math.Min(maxQueues, 2));
        int desiredTxtBoxW = GetHexVectorDisplayWidth(nicFont, nicHexDigits, nicVisibleValueCount, nicMinTextBoxWidth);
        int wSetBtn = 60;
        int wSaveBtn = 65;
        int gap1 = 4;
        int gap2 = 10;
        int gap3 = 11;
        int gap4 = 10;
        int gap5 = 10;
        int padR = 5;
        int minStatusW = 160;

        string worstTimeText;
        string family = Convert.ToString(nicInfo["Family"]);
        if (String.Equals(family, "RealtekIntrMit", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "Rx:u15=75µs@1G(4.8µs-19.661ms)/60f Tx:u15=75µs@1G(4.8µs-19.661ms)/60f"; }
        else if (String.Equals(family, "RealtekIntrMitV2", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "IntMITI dword u127≈127µs/f63"; }
        else if (String.Equals(family, "IntelITR", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "raw irq/s: 1s@1, 15.259µs@65535"; }
        else if (String.Equals(family, "IntelIxgbeEITR", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "1.047ms"; }
        else if (String.Equals(family, "IntelEITR", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "8.388ms"; }
        else if (String.Equals(family, "IntelEITRv2", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "Rx/ITR0:8160µs Tx/ITR1:8160µs"; }
        else if (String.Equals(family, "IntelIceGLINT", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "Rx/ITR0:8160µs Tx/ITR1:8160µs"; }
        else if (String.Equals(family, "AquantiaITR", StringComparison.OrdinalIgnoreCase)) { worstTimeText = "Rx:1022-1022µs Tx:1022-1022µs"; }
        else { worstTimeText = "Rx:u15=75µs@1G(4.8µs-19.661ms)/60f Tx:u15=75µs@1G(4.8µs-19.661ms)/60f"; }
        string worstMultiText = GetNicImodMultipleValuesText(nicInfo);
        int wTimeWorst = TextRenderer.MeasureText(worstTimeText, nicFont, new Size(9999, 99), NoPad).Width;
        int wMultiWorst = TextRenderer.MeasureText(worstMultiText, nicFont, new Size(9999, 99), NoPad).Width;
        int wTimeNeeded = Math.Max(wTimeWorst, wMultiWorst) + 4;

        int panelW = Math.Max(1, nicImodPanel.Width);
        int xLabel = 0;
        int xFamily = xLabel + wLbl + gap1;
        int xTextBox = xLabel + wLbl + gap2;
        int xSave = panelW - wSaveBtn - padR;
        int xSet = xSave - wSetBtn - gap5;
        int maxTextBoxW = xSet - gap4 - minStatusW - gap3 - xTextBox;
        if (maxTextBoxW < 80) { maxTextBoxW = xSet - gap4 - 1 - gap3 - xTextBox; }
        int wTxtBox = Math.Max(80, Math.Min(desiredTxtBoxW, Math.Max(1, maxTextBoxW)));
        int xTime = xTextBox + wTxtBox + gap3;
        int maxTimeW = Math.Max(1, xSet - gap4 - xTime);
        int familyW = Math.Max(1, panelW - xFamily - padR);

        Label lblNicIMOD = new Label();
        lblNicIMOD.Text = nicLabelText;
        lblNicIMOD.AutoSize = false;
        lblNicIMOD.Left = xLabel;
        lblNicIMOD.Top = nicLabelTop;
        lblNicIMOD.Width = wLbl;
        lblNicIMOD.Height = 22;
        lblNicIMOD.Font = nicFont;
        lblNicIMOD.ForeColor = theme.LightGray;
        lblNicIMOD.BackColor = Color.Transparent;
        nicImodPanel.Controls.Add(lblNicIMOD);

        DeviceEditorScrollableLabelResult nicFamilyScroll = CreateScrollableLabel(nicImodPanel, xFamily, nicFamilyTop, familyW, nicFamilyViewH, nicFamilyTrackH, nicFont, theme.MidGray, theme.Black);
        Label lblNicFamily = nicFamilyScroll.Label;
        lblNicFamily.Text = nicFamilyText;
        Hashtable nicFamilyTag = new Hashtable();
        nicFamilyTag["ScrollSync"] = nicFamilyScroll.Sync;
        nicFamilyTag["ScrollState"] = nicFamilyScroll.State;
        lblNicFamily.Tag = nicFamilyTag;
        SyncScrollableLabel(nicFamilyScroll.State);

        TextBox txtNicNewIMOD = new TextBox();
        txtNicNewIMOD.Width = wTxtBox;
        txtNicNewIMOD.MaxLength = 32767;
        txtNicNewIMOD.Left = xTextBox;
        txtNicNewIMOD.Top = nicRowTop;
        txtNicNewIMOD.Height = nicTextBoxH;
        txtNicNewIMOD.Multiline = true;
        txtNicNewIMOD.AcceptsReturn = false;
        txtNicNewIMOD.AcceptsTab = false;
        txtNicNewIMOD.WordWrap = false;
        txtNicNewIMOD.ScrollBars = ScrollBars.Horizontal;
        txtNicNewIMOD.Font = nicFont;
        txtNicNewIMOD.BackColor = theme.DarkGray30;
        txtNicNewIMOD.ForeColor = theme.LightGray;
        txtNicNewIMOD.BorderStyle = BorderStyle.FixedSingle;
        txtNicNewIMOD.Text = "0x";
        txtNicNewIMOD.Tag = nicInfo;
        nicImodPanel.Controls.Add(txtNicNewIMOD);

        CreateTextBoxHScroll(txtNicNewIMOD, nicImodPanel, 10, theme.Black);
        DeviceTweakerUiHandlers.WireHexVectorTextBox(txtNicNewIMOD, true, nicHexDigits);

        DeviceEditorScrollableLabelResult nicScrollLabel = CreateScrollableLabel(nicImodPanel, xTime, nicInlineTop, maxTimeW, 20, 8, nicFont, theme.MidGray, theme.Black);
        Label lblNicIMODTime = nicScrollLabel.Label;
        lblNicIMODTime.Text = "Reading...";
        Hashtable nicLblTag = new Hashtable();
        nicLblTag["ScrollSync"] = nicScrollLabel.Sync;
        nicLblTag["ScrollState"] = nicScrollLabel.State;
        lblNicIMODTime.Tag = nicLblTag;
        SyncScrollableLabel(nicScrollLabel.State);

        Button btnSetNicIMOD = CreateDarkButton("SET", wSetBtn, nicButtonH, xSet, nicButtonTop, row.Source, theme, true);
        nicImodPanel.Controls.Add(btnSetNicIMOD);
        if (nicSetButtons != null) { nicSetButtons.Add(btnSetNicIMOD); }

        Button btnSaveNicIMOD = CreateDarkButton("SAVE", wSaveBtn, nicButtonH, xSave, nicButtonTop, row.Source, theme, true);
        nicImodPanel.Controls.Add(btnSaveNicIMOD);
        if (nicSaveButtons != null) { nicSaveButtons.Add(btnSaveNicIMOD); }

        map["NICNewIMOD"] = txtNicNewIMOD;
        map["NICIMODTimeLabel"] = lblNicIMODTime;
        map["NICFamilyLabel"] = lblNicFamily;
        map["NICFamilyScroll"] = nicFamilyScroll;
        map["NICIMODTimeScroll"] = nicScrollLabel;
        map["NICIMODInfo"] = nicInfo;
        map["NicIMODPanel"] = nicImodPanel;
        map["NICSetIMODButton"] = btnSetNicIMOD;
        map["NICSaveIMODButton"] = btnSaveNicIMOD;
        EnsureExtensionPanelFitsGroupFrame(groupBox, nicImodPanel, 6);
        map["ExtensionBottom"] = nicImodPanel.Bottom;

        nicImodPanel.ResumeLayout(false);
    }


    private static bool RowLooksLikeHdaController(DeviceRow row)
    {
        if (row == null) { return false; }
        if (row.IsHdaController) { return true; }
        string text = (row.ClassCode ?? String.Empty) + " " + (row.PNPID ?? String.Empty) + " " + (row.DisplayName ?? String.Empty) + " " + (row.RegistryPath ?? String.Empty) + " " + (row.Role ?? String.Empty);
        return text.IndexOf("0403", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("High Definition Audio", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("HDAUDIO", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("CC_0403", StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static string FormatHdaRintcntDisplay(int raw)
    {
        int value = Math.Max(0, Math.Min(255, raw));
        int responses = value == 0 ? 256 : value;
        return "RINTCNT=0x" + value.ToString("X2", CultureInfo.InvariantCulture) + " | " + responses.ToString(CultureInfo.InvariantCulture) + " codec responses/IRQ | rate=codec responses/s÷" + responses.ToString(CultureInfo.InvariantCulture);
    }

    public static void AddHdaRintcntControls(DeviceRow row, DeviceEditorState state, DeviceEditorTheme theme, Hashtable map, List<Button> hdaRefreshButtons, List<Button> hdaSetButtons, List<Button> hdaRingSizeSetButtons)
    {
        if (DisableRWEnNVMe) { return; }
        DeviceEditorControl groupBox = state.GroupBox;
        if (groupBox == null || state.RegistryPathElement == null) { return; }
        if (!String.Equals(row.Category, "PCI", StringComparison.OrdinalIgnoreCase)) { return; }
        string hdaOnlyGuardText = (row.DisplayName ?? String.Empty) + " " + (row.Role ?? String.Empty);
        if (String.Equals(row.Role ?? String.Empty, "Audio", StringComparison.OrdinalIgnoreCase) && hdaOnlyGuardText.IndexOf("HD Audio", StringComparison.OrdinalIgnoreCase) >= 0 && hdaOnlyGuardText.IndexOf("Display Audio", StringComparison.OrdinalIgnoreCase) < 0 && hdaOnlyGuardText.IndexOf("GPU", StringComparison.OrdinalIgnoreCase) < 0) { return; }
        if (!RowLooksLikeHdaController(row)) { return; }

        Panel hdaPanel = new Panel();
        hdaPanel.SuspendLayout();
        hdaPanel.Left = 6;
        int top = state.RegistryPathElement.Bottom + 6;
        if (map.ContainsKey("ExtensionBottom"))
        {
            try { top = Math.Max(top, Convert.ToInt32(map["ExtensionBottom"], CultureInfo.InvariantCulture) + 4); } catch { }
        }
        hdaPanel.Top = top;
        hdaPanel.Width = Math.Max(1, groupBox.Width - 12);
        hdaPanel.Height = 112;
        hdaPanel.BackColor = Color.Transparent;
        groupBox.Controls.Add(hdaPanel);

        int rowH = 28;
        int top1 = 4;
        int top2 = 40;
        int top3 = 76;
        int labelTop1 = top1 + 5;
        int labelTop2 = top2 + 5;
        int labelTop3 = top3 + 5;
        int inlineTop1 = top1 + 2;
        int inlineTop2 = top2 + 2;
        int inlineTop3 = top3 + 2;
        Font f = theme.Font11 ?? groupBox.Font;
        string labelText = "HDA RESP IRQ:";
        string corbLabelText = "HDA CORB SZ:";
        string rirbLabelText = "HDA RIRB SZ:";
        string regText = "[MMIO+5Ah]";
        string corbRegText = "[MMIO+4Eh]";
        string rirbRegText = "[MMIO+5Eh]";
        int wLabel = Math.Max(TextRenderer.MeasureText(labelText, f, new Size(9999, 99), NoPad).Width, Math.Max(TextRenderer.MeasureText(corbLabelText, f, new Size(9999, 99), NoPad).Width, TextRenderer.MeasureText(rirbLabelText, f, new Size(9999, 99), NoPad).Width));
        int wReg = Math.Max(TextRenderer.MeasureText(regText, f, new Size(9999, 99), NoPad).Width, Math.Max(TextRenderer.MeasureText(corbRegText, f, new Size(9999, 99), NoPad).Width, TextRenderer.MeasureText(rirbRegText, f, new Size(9999, 99), NoPad).Width));
        int wValue = 58;
        int wCombo = Math.Max(132, TextRenderer.MeasureText("2 | 256 entries", f, new Size(9999, 99), NoPad).Width + 22);
        int wRefresh = Math.Max(64, TextRenderer.MeasureText("READ", f, new Size(9999, 99), NoPad).Width + 22);
        int wSet = Math.Max(60, TextRenderer.MeasureText("SET", f, new Size(9999, 99), NoPad).Width + 22);
        int wSetRing = Math.Max(84, Math.Max(TextRenderer.MeasureText("SET CORB", f, new Size(9999, 99), NoPad).Width, TextRenderer.MeasureText("SET RIRB", f, new Size(9999, 99), NoPad).Width) + 22);
        int gap = 6;
        int padR = 5;
        int xBase = wLabel + 4 + wReg + 10;

        Label lbl = new Label();
        lbl.Text = labelText;
        lbl.AutoSize = false;
        lbl.Left = 0;
        lbl.Top = labelTop1;
        lbl.Width = wLabel;
        lbl.Height = 20;
        lbl.Font = f;
        lbl.ForeColor = theme.LightGray;
        lbl.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lbl);

        Label lblReg = new Label();
        lblReg.Text = regText;
        lblReg.AutoSize = false;
        lblReg.Left = wLabel + 4;
        lblReg.Top = labelTop1;
        lblReg.Width = wReg;
        lblReg.Height = 20;
        lblReg.Font = f;
        lblReg.ForeColor = theme.MidGray;
        lblReg.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lblReg);

        NumericUpDown nud = new NumericUpDown();
        nud.Minimum = 0;
        nud.Maximum = 255;
        nud.Width = wValue;
        nud.Height = rowH;
        nud.Left = xBase;
        nud.Top = top1;
        nud.Font = f;
        nud.BackColor = theme.DarkGray30;
        nud.ForeColor = theme.LightGray;
        nud.BorderStyle = BorderStyle.FixedSingle;
        hdaPanel.Controls.Add(nud);

        int statusLeft = xBase + wValue + gap;
        int minStatusWidth = Math.Max(340, Math.Min(520, TextRenderer.MeasureText("RINTCNT=0x00 | 256 codec responses/IRQ | rate=codec responses/s÷256", f, new Size(9999, 99), NoPad).Width + 4));
        int minRight = statusLeft + minStatusWidth + gap + wRefresh + gap + wSet + padR;
        int ringStatusLeft = xBase + wCombo + gap;
        int ringStatusWidth = Math.Max(390, TextRenderer.MeasureText("RIRBSIZE=2 | 256 entries / 2048 B | cap: 0,1,2 | RIRB DMA RUN", f, new Size(9999, 99), NoPad).Width + 4);
        minRight = Math.Max(minRight, ringStatusLeft + ringStatusWidth + gap + wSetRing + padR);
        hdaPanel.Width = Math.Max(1, minRight);
        int xSet = hdaPanel.Width - wSet - padR;
        int xRefresh = xSet - gap - wRefresh;
        int statusWidth = Math.Max(minStatusWidth, xRefresh - gap - statusLeft);
        int xSetRing = hdaPanel.Width - wSetRing - padR;
        ringStatusWidth = Math.Max(ringStatusWidth, xSetRing - gap - ringStatusLeft);

        DeviceEditorScrollableLabelResult scroll = CreateScrollableLabel(hdaPanel, statusLeft, inlineTop1, statusWidth, 18, 8, f, theme.MidGray, theme.Black);
        Label lblStatus = scroll.Label;
        lblStatus.Text = "Reading...";
        Hashtable tag = new Hashtable();
        tag["ScrollSync"] = scroll.Sync;
        tag["ScrollState"] = scroll.State;
        lblStatus.Tag = tag;

        EventHandler changeHandler = delegate(object sender, EventArgs e)
        {
            lblStatus.Text = FormatHdaRintcntDisplay((int)nud.Value);
            SyncLabelScroll(lblStatus);
        };
        nud.ValueChanged += changeHandler;

        Button btnRead = CreateDarkButton("READ", wRefresh, rowH, xRefresh, top1, row.Source, theme, true);
        hdaPanel.Controls.Add(btnRead);
        if (hdaRefreshButtons != null) { hdaRefreshButtons.Add(btnRead); }

        Button btnSet = CreateDarkButton("SET", wSet, rowH, xSet, top1, row.Source, theme, true);
        btnSet.Enabled = false;
        hdaPanel.Controls.Add(btnSet);
        if (hdaSetButtons != null) { hdaSetButtons.Add(btnSet); }

        Label lblCorb = new Label();
        lblCorb.Text = corbLabelText;
        lblCorb.AutoSize = false;
        lblCorb.Left = 0;
        lblCorb.Top = labelTop2;
        lblCorb.Width = wLabel;
        lblCorb.Height = 20;
        lblCorb.Font = f;
        lblCorb.ForeColor = theme.LightGray;
        lblCorb.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lblCorb);

        Label lblCorbReg = new Label();
        lblCorbReg.Text = corbRegText;
        lblCorbReg.AutoSize = false;
        lblCorbReg.Left = wLabel + 4;
        lblCorbReg.Top = labelTop2;
        lblCorbReg.Width = wReg;
        lblCorbReg.Height = 20;
        lblCorbReg.Font = f;
        lblCorbReg.ForeColor = theme.MidGray;
        lblCorbReg.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lblCorbReg);

        ComboBox cboCorb = new ComboBox();
        cboCorb.Left = xBase;
        cboCorb.Top = inlineTop2 + 1;
        cboCorb.Width = wCombo;
        cboCorb.Height = rowH;
        cboCorb.Font = f;
        cboCorb.DropDownStyle = ComboBoxStyle.DropDownList;
        cboCorb.Items.AddRange(new object[] { "0 | 2 entries", "1 | 16 entries", "2 | 256 entries" });
        cboCorb.SelectedIndex = 2;
        DeviceTweakerUiHandlers.WireDarkCombo(cboCorb);
        hdaPanel.Controls.Add(cboCorb);

        DeviceEditorScrollableLabelResult corbScroll = CreateScrollableLabel(hdaPanel, ringStatusLeft, inlineTop2, ringStatusWidth, 18, 8, f, theme.MidGray, theme.Black);
        Label lblCorbStatus = corbScroll.Label;
        lblCorbStatus.Text = "Reading...";
        Hashtable corbTag = new Hashtable();
        corbTag["ScrollSync"] = corbScroll.Sync;
        corbTag["ScrollState"] = corbScroll.State;
        lblCorbStatus.Tag = corbTag;
        cboCorb.SelectedIndexChanged += delegate(object sender, EventArgs e) { lblCorbStatus.Text = "Selected CORBSIZE " + Convert.ToString(cboCorb.SelectedItem, CultureInfo.InvariantCulture); SyncLabelScroll(lblCorbStatus); };

        Button btnSetCorb = CreateDarkButton("SET CORB", wSetRing, rowH, xSetRing, top2, row.Source, theme, true);
        hdaPanel.Controls.Add(btnSetCorb);
        if (hdaRingSizeSetButtons != null) { hdaRingSizeSetButtons.Add(btnSetCorb); }

        Label lblRirb = new Label();
        lblRirb.Text = rirbLabelText;
        lblRirb.AutoSize = false;
        lblRirb.Left = 0;
        lblRirb.Top = labelTop3;
        lblRirb.Width = wLabel;
        lblRirb.Height = 20;
        lblRirb.Font = f;
        lblRirb.ForeColor = theme.LightGray;
        lblRirb.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lblRirb);

        Label lblRirbReg = new Label();
        lblRirbReg.Text = rirbRegText;
        lblRirbReg.AutoSize = false;
        lblRirbReg.Left = wLabel + 4;
        lblRirbReg.Top = labelTop3;
        lblRirbReg.Width = wReg;
        lblRirbReg.Height = 20;
        lblRirbReg.Font = f;
        lblRirbReg.ForeColor = theme.MidGray;
        lblRirbReg.BackColor = Color.Transparent;
        hdaPanel.Controls.Add(lblRirbReg);

        ComboBox cboRirb = new ComboBox();
        cboRirb.Left = xBase;
        cboRirb.Top = inlineTop3 + 1;
        cboRirb.Width = wCombo;
        cboRirb.Height = rowH;
        cboRirb.Font = f;
        cboRirb.DropDownStyle = ComboBoxStyle.DropDownList;
        cboRirb.Items.AddRange(new object[] { "0 | 2 entries", "1 | 16 entries", "2 | 256 entries" });
        cboRirb.SelectedIndex = 2;
        DeviceTweakerUiHandlers.WireDarkCombo(cboRirb);
        hdaPanel.Controls.Add(cboRirb);

        DeviceEditorScrollableLabelResult rirbScroll = CreateScrollableLabel(hdaPanel, ringStatusLeft, inlineTop3, ringStatusWidth, 18, 8, f, theme.MidGray, theme.Black);
        Label lblRirbStatus = rirbScroll.Label;
        lblRirbStatus.Text = "Reading...";
        Hashtable rirbTag = new Hashtable();
        rirbTag["ScrollSync"] = rirbScroll.Sync;
        rirbTag["ScrollState"] = rirbScroll.State;
        lblRirbStatus.Tag = rirbTag;
        cboRirb.SelectedIndexChanged += delegate(object sender, EventArgs e) { lblRirbStatus.Text = "Selected RIRBSIZE " + Convert.ToString(cboRirb.SelectedItem, CultureInfo.InvariantCulture); SyncLabelScroll(lblRirbStatus); };

        Button btnSetRirb = CreateDarkButton("SET RIRB", wSetRing, rowH, xSetRing, top3, row.Source, theme, true);
        hdaPanel.Controls.Add(btnSetRirb);
        if (hdaRingSizeSetButtons != null) { hdaRingSizeSetButtons.Add(btnSetRirb); }

        map["HDARintcntValue"] = nud;
        map["HDARintcntStatusLabel"] = lblStatus;
        map["HDARintcntRefreshButton"] = btnRead;
        map["HDARintcntSetButton"] = btnSet;
        map["HDACorbSizeCombo"] = cboCorb;
        map["HDACorbSizeStatusLabel"] = lblCorbStatus;
        map["HDACorbSizeSetButton"] = btnSetCorb;
        map["HDARirbSizeCombo"] = cboRirb;
        map["HDARirbSizeStatusLabel"] = lblRirbStatus;
        map["HDARirbSizeSetButton"] = btnSetRirb;
