        map["HDAPanel"] = hdaPanel;
        EnsureExtensionPanelFitsGroupFrame(groupBox, hdaPanel, 6);
        map["ExtensionBottom"] = hdaPanel.Bottom;
        hdaPanel.ResumeLayout(false);
    }

    private static void EnsureExtensionPanelFitsGroupFrame(DeviceEditorControl groupBox, Panel extensionPanel, int rightPadding)
    {
        if (groupBox == null || extensionPanel == null) { return; }
        int requiredWidth = extensionPanel.Left + extensionPanel.Width + Math.Max(0, rightPadding);
        if (requiredWidth > groupBox.Width)
        {
            groupBox.Width = requiredWidth;
        }
    }

    public static void FinalizeExtensionButtonLayout(DeviceEditorControl groupBox, Hashtable map)
    {
        if (groupBox == null || map == null) { return; }
        int rightPadding = 6;
        int finalGroupWidth = groupBox.Width;
        finalGroupWidth = Math.Max(finalGroupWidth, RequiredGroupWidth(map, "UsbImodPanel", rightPadding));
        finalGroupWidth = Math.Max(finalGroupWidth, RequiredGroupWidth(map, "NicIMODPanel", rightPadding));
        finalGroupWidth = Math.Max(finalGroupWidth, RequiredGroupWidth(map, "HDAPanel", rightPadding));
        finalGroupWidth = Math.Max(finalGroupWidth, RequiredGroupWidth(map, "NVMePanel", rightPadding));
        finalGroupWidth = Math.Max(finalGroupWidth, RequiredGroupWidth(map, "PciAspmPanel", rightPadding));
        if (finalGroupWidth > groupBox.Width) { groupBox.Width = finalGroupWidth; }
        StretchMappedPanel(groupBox, map, "UsbImodPanel", rightPadding);
        StretchMappedPanel(groupBox, map, "NicIMODPanel", rightPadding);
        StretchMappedPanel(groupBox, map, "HDAPanel", rightPadding);
        StretchMappedPanel(groupBox, map, "NVMePanel", rightPadding);
        StretchMappedPanel(groupBox, map, "PciAspmPanel", rightPadding);
        ReflowTwoButtonRow(map, "UsbImodPanel", "IMODNsLabel", "UsbSetIMODButton", "UsbSaveIMODButton", 5, 10, 10);
        ReflowControlCenteredOverButtonSpan(map, "SecretSaveCheckbox", "UsbSetIMODButton", "UsbSaveIMODButton");
        ReflowScrollableLabelToPanelRight(map, "NicIMODPanel", "NICFamilyLabel", 5);
        ReflowTwoButtonRow(map, "NicIMODPanel", "NICIMODTimeLabel", "NICSetIMODButton", "NICSaveIMODButton", 5, 10, 10);
        ReflowTwoButtonRow(map, "HDAPanel", "HDARintcntStatusLabel", "HDARintcntRefreshButton", "HDARintcntSetButton", 5, 6, 6);
        ReflowOneButtonRow(map, "HDAPanel", "HDACorbSizeStatusLabel", "HDACorbSizeSetButton", 5, 6);
        ReflowOneButtonRow(map, "HDAPanel", "HDARirbSizeStatusLabel", "HDARirbSizeSetButton", 5, 6);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeTimeLabel", "NVMeRefreshButton", "NVMeSetButton", 5, 6, 10);
        ReflowThreeButtonRow(map, "NVMePanel", "NVMeApstPowerStatusLabel", "NVMePowerRefreshButton", "NVMeApstDisableButton", "NVMeForcePs0Button", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeVwcStatusLabel", "NVMeVwcRefreshButton", "NVMeVwcSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeTempStatusLabel", "NVMeTempRefreshButton", "NVMeTempSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeWanStatusLabel", "NVMeWanRefreshButton", "NVMeWanSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeHmbStatusLabel", "NVMeHmbRefreshButton", "NVMeHmbSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeErrStatusLabel", "NVMeErrRefreshButton", "NVMeErrSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeHctmStatusLabel", "NVMeHctmRefreshButton", "NVMeHctmSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeArbStatusLabel", "NVMeArbRefreshButton", "NVMeArbSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "NVMePanel", "NVMeNoqStatusLabel", "NVMeNoqRefreshButton", "NVMeNoqSetButton", 5, 6, 10);
        ReflowTwoButtonRow(map, "PciAspmPanel", "PciAspmStatusLabel", "PciAspmRefreshButton", "PciAspmSetButton", 5, 6, 6);
        ReflowFourButtonRow(map, "PciAspmPanel", "PciLinkStatusLabel", "PciLinkRefreshButton", "PciMrrsSetButton", "PciMpsSetButton", "PciDeviceControlSetButton", 5, 6, 6);
        ReflowThreeButtonRow(map, "PciAspmPanel", "PciL1ssStatusLabel", "PciL1ssRefreshButton", "PciL1ssSetButton", "PciL1ssThresholdSetButton", 5, 6, 6);
        ReflowTwoButtonRow(map, "PciAspmPanel", "PciLtrObffStatusLabel", "PciLtrObffRefreshButton", "PciLtrObffSetButton", 5, 6, 6);
        ReflowTwoButtonRow(map, "PciAspmPanel", "PciAerDpcAcsStatusLabel", "PciAerDpcAcsRefreshButton", "PciAerDpcAcsSetButton", 5, 6, 6);
        ReflowTwoButtonRow(map, "PciAspmPanel", "PciRebarStatusLabel", "PciRebarRefreshButton", "PciRebarSetButton", 5, 6, 6);
    }

    public static void ReflowMsiPanelToRight(DeviceEditorState state, int rightPadding)
    {
        if (state == null || state.GroupBox == null || state.MsiPanel == null) { return; }
        int targetLeft = Math.Max(0, state.GroupBox.Width - state.MsiPanel.Width - Math.Max(0, rightPadding));
        int dx = targetLeft - state.MsiPanel.Left;
        if (dx == 0) { return; }

        state.MsiPanel.Left = targetLeft;
        MoveTextElementX(state.MsiModeLabel, dx);
        MoveTextElementX(state.MsiLimitLabel, dx);
        MoveTextElementX(state.MsiPriorityLabel, dx);
        MoveTextElementX(state.NumQueuesLabel, dx);
        MoveTextElementX(state.PolicyLabel, dx);

        MoveControlX(state.MsiCombo, dx);
        Control msgLimitHost = state.MsgLimitBox == null ? null : state.MsgLimitBox.Parent;
        MoveControlX(msgLimitHost, dx);
        MoveControlX(state.PriorityCombo, dx);
        MoveControlX(state.NumQueues, dx);
        MoveControlX(state.PolicyCombo, dx);
        MoveControlX(state.NdisIrqToggle, dx);
    }

    private static int RequiredGroupWidth(Hashtable map, string panelKey, int rightPadding)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        if (panel == null) { return 0; }
        return panel.Left + panel.Width + Math.Max(0, rightPadding);
    }

    private static void StretchMappedPanel(DeviceEditorControl groupBox, Hashtable map, string panelKey, int rightPadding)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        if (groupBox == null || panel == null) { return; }
        int targetWidth = Math.Max(1, groupBox.Width - panel.Left - Math.Max(0, rightPadding));
        if (panel.Width < targetWidth) { panel.Width = targetWidth; }
    }

    private static Panel GetMappedPanel(Hashtable map, string key)
    {
        if (map == null || key == null || !map.ContainsKey(key)) { return null; }
        return map[key] as Panel;
    }

    private static Control GetMappedControl(Hashtable map, string key)
    {
        if (map == null || key == null || !map.ContainsKey(key)) { return null; }
        return map[key] as Control;
    }

    private static Label GetMappedLabel(Hashtable map, string key)
    {
        if (map == null || key == null || !map.ContainsKey(key)) { return null; }
        return map[key] as Label;
    }

    private static void ReflowTwoButtonRow(Hashtable map, string panelKey, string labelKey, string leftButtonKey, string rightButtonKey, int padRight, int buttonGap, int labelGap)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        Label label = GetMappedLabel(map, labelKey);
        Control leftButton = GetMappedControl(map, leftButtonKey);
        Control rightButton = GetMappedControl(map, rightButtonKey);
        if (panel == null || leftButton == null || rightButton == null) { return; }
        int right = Math.Max(1, panel.Width - Math.Max(0, padRight));
        rightButton.Left = right - rightButton.Width;
        leftButton.Left = rightButton.Left - Math.Max(0, buttonGap) - leftButton.Width;
        ResizeMappedScrollableLabel(label, Math.Max(1, leftButton.Left - Math.Max(0, labelGap) - GetScrollableContainerLeft(label)));
    }

    private static void ReflowOneButtonRow(Hashtable map, string panelKey, string labelKey, string buttonKey, int padRight, int labelGap)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        Label label = GetMappedLabel(map, labelKey);
        Control button = GetMappedControl(map, buttonKey);
        if (panel == null || button == null) { return; }
        int right = Math.Max(1, panel.Width - Math.Max(0, padRight));
        button.Left = right - button.Width;
        ResizeMappedScrollableLabel(label, Math.Max(1, button.Left - Math.Max(0, labelGap) - GetScrollableContainerLeft(label)));
    }
    private static void ReflowScrollableLabelToPanelRight(Hashtable map, string panelKey, string labelKey, int padRight)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        Label label = GetMappedLabel(map, labelKey);
        if (panel == null || label == null) { return; }
        ResizeMappedScrollableLabel(label, Math.Max(1, panel.Width - Math.Max(0, padRight) - GetScrollableContainerLeft(label)));
    }


    private static void ReflowThreeButtonRow(Hashtable map, string panelKey, string labelKey, string leftButtonKey, string middleButtonKey, string rightButtonKey, int padRight, int buttonGap, int labelGap)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        Label label = GetMappedLabel(map, labelKey);
        Control leftButton = GetMappedControl(map, leftButtonKey);
        Control middleButton = GetMappedControl(map, middleButtonKey);
        Control rightButton = GetMappedControl(map, rightButtonKey);
        if (panel == null || leftButton == null || middleButton == null || rightButton == null) { return; }
        int right = Math.Max(1, panel.Width - Math.Max(0, padRight));
        rightButton.Left = right - rightButton.Width;
        middleButton.Left = rightButton.Left - Math.Max(0, buttonGap) - middleButton.Width;
        leftButton.Left = middleButton.Left - Math.Max(0, buttonGap) - leftButton.Width;
        ResizeMappedScrollableLabel(label, Math.Max(1, leftButton.Left - Math.Max(0, labelGap) - GetScrollableContainerLeft(label)));
    }

    private static void ReflowFourButtonRow(Hashtable map, string panelKey, string labelKey, string firstButtonKey, string secondButtonKey, string thirdButtonKey, string fourthButtonKey, int padRight, int buttonGap, int labelGap)
    {
        Panel panel = GetMappedPanel(map, panelKey);
        Label label = GetMappedLabel(map, labelKey);
        Control firstButton = GetMappedControl(map, firstButtonKey);
        Control secondButton = GetMappedControl(map, secondButtonKey);
        Control thirdButton = GetMappedControl(map, thirdButtonKey);
        Control fourthButton = GetMappedControl(map, fourthButtonKey);
        if (panel == null || firstButton == null || secondButton == null || thirdButton == null || fourthButton == null) { return; }
        int right = Math.Max(1, panel.Width - Math.Max(0, padRight));
        fourthButton.Left = right - fourthButton.Width;
        thirdButton.Left = fourthButton.Left - Math.Max(0, buttonGap) - thirdButton.Width;
        secondButton.Left = thirdButton.Left - Math.Max(0, buttonGap) - secondButton.Width;
        firstButton.Left = secondButton.Left - Math.Max(0, buttonGap) - firstButton.Width;
        ResizeMappedScrollableLabel(label, Math.Max(1, firstButton.Left - Math.Max(0, labelGap) - GetScrollableContainerLeft(label)));
    }

    private static void ReflowControlCenteredOverButtonSpan(Hashtable map, string controlKey, string leftButtonKey, string rightButtonKey)
    {
        Control target = GetMappedControl(map, controlKey);
        Control leftButton = GetMappedControl(map, leftButtonKey);
        Control rightButton = GetMappedControl(map, rightButtonKey);
        if (target == null || leftButton == null || rightButton == null) { return; }

        int spanLeft = Math.Min(leftButton.Left, rightButton.Left);
        int spanRight = Math.Max(leftButton.Right, rightButton.Right);
        int spanWidth = Math.Max(1, spanRight - spanLeft);

        // For the USB "Per-device IMOD" checkbox, the WinForms CheckBox has unused
        // trailing layout space when the width is based on TextRenderer measurement.
        // That makes mathematical centering of the full control look left-shifted.
        // Fit it to the actual SET+SAVE span first, then center against the buttons.
        if (target is CheckBox && target.Width > spanWidth)
        {
            target.Width = spanWidth;
        }

        int desiredLeft = spanLeft + ((spanWidth - target.Width) / 2);
        Control parent = target.Parent;
        if (parent != null)
        {
            int rightLimit = Math.Max(0, parent.ClientSize.Width - 5 - target.Width);
            desiredLeft = Math.Min(desiredLeft, rightLimit);
        }
        target.Left = Math.Max(0, desiredLeft);
    }

    private static void MoveControlX(Control control, int dx)
    {
        if (control == null || dx == 0) { return; }
        control.Left += dx;
    }

    private static void MoveTextElementX(DeviceEditorTextElement element, int dx)
    {
        if (element == null || dx == 0) { return; }
        element.Left += dx;
    }

    private static int GetScrollableContainerLeft(Label label)
    {
        DeviceEditorNativeLabelScrollState state = GetScrollableLabelState(label);
        if (state == null || state.Container == null) { return label == null ? 0 : label.Left; }
        return state.Container.Left;
    }

    private static DeviceEditorNativeLabelScrollState GetScrollableLabelState(Label label)
    {
        if (label == null) { return null; }
        Hashtable tagTable = label.Tag as Hashtable;
        if (tagTable != null && tagTable.ContainsKey("ScrollState")) { return tagTable["ScrollState"] as DeviceEditorNativeLabelScrollState; }
        return label.Tag as DeviceEditorNativeLabelScrollState;
    }

    private static void ResizeMappedScrollableLabel(Label label, int width)
    {
        DeviceEditorNativeLabelScrollState state = GetScrollableLabelState(label);
        if (state == null || state.Container == null) { return; }
        int safeWidth = Math.Max(1, width);
        if (state.Container.Width != safeWidth) { state.Container.Width = safeWidth; }
        if (state.Viewport != null && state.Viewport.Width != safeWidth) { state.Viewport.Width = safeWidth; }
        if (state.Track != null && state.Track.Width != safeWidth) { state.Track.Width = safeWidth; }
        ResizeScrollableLabel(state);
        SyncScrollableLabel(state);
    }

    public static void AddNvmeInterruptCoalescingControls(DeviceRow row, DeviceEditorState state, DeviceEditorTheme theme, Hashtable map, List<Button> nvmeRefreshButtons, List<Button> nvmeSetButtons)
    {
        if (DisableRWEnNVMe) { return; }
        DeviceEditorControl groupBox = state.GroupBox;
        if (groupBox == null || state.RegistryPathElement == null) { return; }
        string combined = (row.StorageType ?? String.Empty) + " " + (row.BusType ?? String.Empty) + " " + (row.DisplayName ?? String.Empty) + " " + (row.PNPID ?? String.Empty);
        if (combined.IndexOf("NVMe", StringComparison.OrdinalIgnoreCase) < 0) { return; }
        string drivePath = row.PhysicalDrivePath;
        if (String.IsNullOrWhiteSpace(drivePath) && row.DiskIndex >= 0) { drivePath = "\\\\.\\PhysicalDrive" + row.DiskIndex.ToString(CultureInfo.InvariantCulture); }

        Panel nvmePanel = new Panel();
        nvmePanel.SuspendLayout();
        nvmePanel.Left = 6;
        nvmePanel.Top = state.RegistryPathElement.Bottom + 6;
        nvmePanel.Width = groupBox.Width - 12;
        nvmePanel.Height = 332;
        nvmePanel.BackColor = Color.Transparent;
        groupBox.Controls.Add(nvmePanel);

        int rowH = 28;
        int row1Top = 4;
        int row2Top = row1Top + rowH + 8;
        int row3Top = row2Top + rowH + 8;
        int row4Top = row3Top + rowH + 8;
        int row5Top = row4Top + rowH + 8;
        int row6Top = row5Top + rowH + 8;
        int row7Top = row6Top + rowH + 8;
        int row8Top = row7Top + rowH + 8;
        int row9Top = row8Top + rowH + 8;
        int row10Top = row9Top + rowH + 8;
        int row11Top = row10Top + rowH + 8;
        nvmePanel.Height = row11Top + rowH + 6;
