        int labelTop5 = row5Top + 5;
        int labelTop6 = row6Top + 5;
        int labelTop7 = row7Top + 5;
        int labelTop8 = row8Top + 5;
        int labelTop9 = row9Top + 5;
        int labelTop10 = row10Top + 5;
        int labelTop11 = row11Top + 5;
        int inlineTop1 = row1Top + 2;
        int inlineTop2 = row2Top + 2;
        int inlineTop3 = row3Top + 2;
        int inlineTop4 = row4Top + 2;
        int inlineTop5 = row5Top + 2;
        int inlineTop6 = row6Top + 2;
        int inlineTop7 = row7Top + 2;
        int inlineTop8 = row8Top + 2;
