    public static void AddPciAspmControls(DeviceRow row, DeviceEditorState state, DeviceEditorTheme theme, Hashtable map, List<Button> pciAspmRefreshButtons, List<Button> pciAspmSetButtons, List<Button> pciLinkRefreshButtons, List<Button> pciMrrsSetButtons, List<Button> pciMpsSetButtons, List<Button> pciDeviceControlSetButtons, List<Button> pciL1ssRefreshButtons, List<Button> pciL1ssSetButtons, List<Button> pciL1ssThresholdSetButtons, List<Button> pciLtrObffRefreshButtons, List<Button> pciLtrObffSetButtons, List<Button> pciAerDpcAcsRefreshButtons, List<Button> pciAerDpcAcsSetButtons)
    {
        if (DisableRWEnNVMe) { return; }
        if (row == null || state == null || map == null) { return; }
        DeviceEditorControl groupBox = state.GroupBox;
        if (groupBox == null || state.RegistryPathElement == null) { return; }
        if (!String.Equals(row.Category, "PCI", StringComparison.OrdinalIgnoreCase)) { return; }
        // Do not suppress the PCIe control block for native High Definition Audio controllers.
        // HDA controllers are PCIe endpoints too, so ASPM / link / DevCtl / L1SS / LTR / OBFF must stay visible when the device exposes the relevant capabilities.
        bool roleEligible = row.IsStorage || String.Equals(row.Role ?? String.Empty, "Storage", StringComparison.OrdinalIgnoreCase) || String.Equals(row.Role ?? String.Empty, "GPU", StringComparison.OrdinalIgnoreCase) || String.Equals(row.Role ?? String.Empty, "Audio", StringComparison.OrdinalIgnoreCase) || String.Equals(row.Role ?? String.Empty, "AudioGPU", StringComparison.OrdinalIgnoreCase) || RowLooksLikeHdaController(row);
        if (!roleEligible) { return; }

        Panel aspmPanel = new Panel();
        aspmPanel.SuspendLayout();
        aspmPanel.Left = 6;
        int top = state.RegistryPathElement.Bottom + 6;
        if (map.ContainsKey("ExtensionBottom"))
        {
            try { top = Math.Max(top, Convert.ToInt32(map["ExtensionBottom"], CultureInfo.InvariantCulture) + 4); } catch { }
        }
        aspmPanel.Top = top;
        aspmPanel.Width = Math.Max(1, groupBox.Width - 12);
        bool rebarEligible = String.Equals(row.Role ?? String.Empty, "GPU", StringComparison.OrdinalIgnoreCase) || String.Equals(row.Role ?? String.Empty, "AudioGPU", StringComparison.OrdinalIgnoreCase) || ((row.ClassCode ?? String.Empty).StartsWith("03", StringComparison.OrdinalIgnoreCase) && ((row.DisplayName ?? String.Empty).IndexOf("Audio", StringComparison.OrdinalIgnoreCase) < 0 || (row.DisplayName ?? String.Empty).IndexOf("GPU", StringComparison.OrdinalIgnoreCase) >= 0));
        aspmPanel.Height = rebarEligible ? 366 : 330;
