        int wReg = Math.Max(Math.Max(Math.Max(Math.Max(Math.Max(Math.Max(TextRenderer.MeasureText(regText, f, new Size(9999, 99), NoPad).Width, TextRenderer.MeasureText(linkRegText, f, new Size(9999, 99), NoPad).Width), TextRenderer.MeasureText(devLinkRegText, f, new Size(9999, 99), NoPad).Width), TextRenderer.MeasureText(l1ssRegText, f, new Size(9999, 99), NoPad).Width), TextRenderer.MeasureText(ltrObffRegText, f, new Size(9999, 99), NoPad).Width), TextRenderer.MeasureText(aerDpcAcsRegText, f, new Size(9999, 99), NoPad).Width), TextRenderer.MeasureText(rebarRegText, f, new Size(9999, 99), NoPad).Width);
