    public static void SyncScrollableLabel(Label label)
    {
        SyncLabelScroll(label);
    }

    public static string DescribeScrollableLabel(Label label)
    {
        if (label == null) { return "<null label>"; }
        DeviceEditorNativeLabelScrollState state = GetScrollableLabelState(label);
        if (state == null) { return "not-scrollable textLen=" + (label.Text == null ? 0 : label.Text.Length).ToString(CultureInfo.InvariantCulture) + " labelBounds=" + label.Bounds.ToString(); }
        int textLen = label.Text == null ? 0 : label.Text.Length;
        int contentW = 0;
        int range = 0;
        int offset = 0;
        try { contentW = LabelContentWidth(state); } catch { contentW = -1; }
        try { range = LabelScrollRange(state); } catch { range = -1; }
        try { offset = GetLabelRenderOffset(state); } catch { offset = -1; }
        DeviceEditorScrollableTextLabel virtualLabel = label as DeviceEditorScrollableTextLabel;
        int virtualW = virtualLabel == null ? -1 : virtualLabel.VirtualTextWidth;
        int virtualOffset = virtualLabel == null ? -1 : virtualLabel.VirtualOffset;
        string paintError = virtualLabel == null ? String.Empty : (virtualLabel.LastPaintError ?? String.Empty);
        string containerBounds = state.Container == null ? "<null>" : state.Container.Bounds.ToString();
        string viewportBounds = state.Viewport == null ? "<null>" : state.Viewport.Bounds.ToString();
        string trackBounds = state.Track == null ? "<null>" : state.Track.Bounds.ToString();
        string thumbBounds = state.Thumb == null ? "<null>" : state.Thumb.Bounds.ToString();
        bool trackVisible = state.Track != null && state.Track.Visible;
        return "textLen=" + textLen.ToString(CultureInfo.InvariantCulture)
            + "; contentW=" + contentW.ToString(CultureInfo.InvariantCulture)
            + "; virtualW=" + virtualW.ToString(CultureInfo.InvariantCulture)
            + "; range=" + range.ToString(CultureInfo.InvariantCulture)
            + "; offset=" + offset.ToString(CultureInfo.InvariantCulture)
            + "; virtualOffset=" + virtualOffset.ToString(CultureInfo.InvariantCulture)
            + "; paintError=" + (String.IsNullOrEmpty(paintError) ? "<none>" : paintError.Replace("\r", " ").Replace("\n", " "))
            + "; dragging=" + state.Dragging.ToString()
            + "; smooth=" + state.SmoothActive.ToString()
            + "; trackVisible=" + trackVisible.ToString()
            + "; labelBounds=" + label.Bounds.ToString()
            + "; container=" + containerBounds
            + "; viewport=" + viewportBounds
            + "; track=" + trackBounds
            + "; thumb=" + thumbBounds;
    }

    private static void SyncLabelScroll(Label label)
    {
        if (label == null) { return; }
        Hashtable tag = label.Tag as Hashtable;
        if (tag == null || !tag.ContainsKey("ScrollSync")) { return; }
        Delegate sync = tag["ScrollSync"] as Delegate;
        if (sync == null) { return; }
        object state = tag.ContainsKey("ScrollState") ? tag["ScrollState"] : null;
        try { sync.DynamicInvoke(new object[] { state }); }
        catch
        {
            try { sync.DynamicInvoke(); } catch { }
        }
    }

    public static void WireSecretSaveCheckboxes(CheckBox[] checks)
    {
        if (checks == null || checks.Length == 0) { return; }
        for (int i = 0; i < checks.Length; i++)
        {
            CheckBox chk = checks[i];
            if (chk == null) { continue; }
            chk.Tag = checks;
            chk.CheckedChanged += SecretSave_CheckedChanged;
        }
    }

    private static void SecretSave_CheckedChanged(object sender, EventArgs e)
    {
        CheckBox source = sender as CheckBox;
        if (source == null) { return; }
        CheckBox[] checks = source.Tag as CheckBox[];
        if (checks == null) { return; }
        bool newValue = source.Checked;
        for (int i = 0; i < checks.Length; i++)
        {
            CheckBox other = checks[i];
            if (other == null || Object.ReferenceEquals(other, source)) { continue; }
            if (other.Checked != newValue) { other.Checked = newValue; }
        }
    }

    public static Button CreateDarkButton(string text, int width, int height, int left, int top, object tag, DeviceEditorTheme theme, bool orangeBorder)
    {
        Button btn = new Button();
        btn.Text = text;
        btn.Width = width;
        btn.Height = height;
        btn.Left = left;
        btn.Top = top;
        btn.Tag = tag;
        btn.BackColor = theme.Black;
        btn.ForeColor = theme.White;
        btn.FlatStyle = FlatStyle.Flat;
        if (theme.Font13 != null) { btn.Font = theme.Font13; }
        btn.UseVisualStyleBackColor = false;
        try { btn.FlatAppearance.MouseOverBackColor = btn.BackColor; } catch { }
        try { btn.FlatAppearance.MouseDownBackColor = Color.FromArgb(45,45,45); } catch { }
        if (orangeBorder)
        {
            btn.FlatAppearance.BorderColor = theme.Orange;
            btn.FlatAppearance.BorderSize = 1;
            btn.MouseEnter += delegate(object s, EventArgs e) { try { ((Button)s).FlatAppearance.BorderColor = Color.White; } catch { } };
            btn.MouseLeave += delegate(object s, EventArgs e) { try { ((Button)s).FlatAppearance.BorderColor = theme.Orange; } catch { } };
        }
        btn.Paint += StableButton_Paint;
        return btn;
    }

    private static void StableButton_Paint(object sender, PaintEventArgs e)
    {
        Button btn = sender as Button;
        if (btn == null || btn.Enabled) { return; }
        string text = btn.Text;
        if (String.IsNullOrEmpty(text)) { return; }
        Color fg = btn.ForeColor.IsEmpty ? Color.White : btn.ForeColor;
        Rectangle rect = new Rectangle(1, 1, Math.Max(1, btn.ClientSize.Width - 2), Math.Max(1, btn.ClientSize.Height - 2));
        TextRenderer.DrawText(e.Graphics, text, btn.Font, rect, fg, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.EndEllipsis | TextFormatFlags.NoPadding);
    }

    public static int GetHexVectorDisplayWidth(Font font, int hexDigits, int valueCount, int minimumWidth)
    {
        int safeDigits = Math.Max(1, hexDigits);
        int safeCount = Math.Max(1, valueCount);
        string sampleToken = "0x" + new String('F', safeDigits);
        StringBuilder sample = new StringBuilder((safeDigits + 3) * safeCount);
        for (int i = 0; i < safeCount; i++)
        {
            if (i > 0) { sample.Append(','); }
            sample.Append(sampleToken);
        }
        int measured = TextRenderer.MeasureText(sample.ToString(), font, new Size(99999, 99), NoPad).Width + 18;
        return minimumWidth > 0 ? Math.Max(measured, minimumWidth) : measured;
    }

    public static DeviceEditorNativeHScrollResult CreateTextBoxHScroll(TextBox textBox, Panel parentPanel, int trackHeight, Color trackBackColor)
    {
        if (textBox == null) { throw new ArgumentNullException("textBox", "TextBox horizontal scroll creation requires a non-null TextBox."); }
        if (parentPanel == null) { throw new ArgumentNullException("parentPanel", "TextBox horizontal scroll creation requires a non-null parent Panel."); }

        Panel clipPanel = new Panel();
        clipPanel.Left = textBox.Left;
        clipPanel.Top = textBox.Top;
        clipPanel.Width = textBox.Width;
        clipPanel.Height = 24;
        clipPanel.BackColor = textBox.BackColor;
        clipPanel.BorderStyle = BorderStyle.FixedSingle;
        clipPanel.Anchor = textBox.Anchor;
        ScrollHelper.EnableDoubleBuffer(clipPanel);
        parentPanel.Controls.Remove(textBox);
        parentPanel.Controls.Add(clipPanel);
        textBox.Left = 0;
        textBox.Top = 0;
        textBox.Height = 50;
        textBox.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
        clipPanel.Controls.Add(textBox);

        Panel hTrack = new Panel();
        hTrack.Left = clipPanel.Left;
        hTrack.Top = clipPanel.Bottom;
        hTrack.Width = clipPanel.Width;
        hTrack.Height = Math.Max(1, trackHeight);
        hTrack.BackColor = trackBackColor;
        hTrack.Anchor = clipPanel.Anchor;
        hTrack.Visible = false;
        ScrollHelper.EnableDoubleBuffer(hTrack);
        parentPanel.Controls.Add(hTrack);

        Panel hThumb = new Panel();
        hThumb.Left = 0;
        hThumb.Top = 0;
        hThumb.Width = 30;
        hThumb.Height = hTrack.Height;
        hThumb.BackColor = Color.FromArgb(32, 32, 32);
        hThumb.Cursor = Cursors.Arrow;
        hThumb.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Bottom;
        ScrollHelper.EnableDoubleBuffer(hThumb);
        hTrack.Controls.Add(hThumb);

        DeviceEditorNativeHScrollState state = new DeviceEditorNativeHScrollState();
        state.TextBox = textBox;
        state.Track = hTrack;
        state.Thumb = hThumb;
        Action<object> sync = delegate(object stObj) { SyncTextBoxHScroll(stObj as DeviceEditorNativeHScrollState); };
        Hashtable tag = new Hashtable();
        tag["HScrollState"] = state;
        tag["HScrollSync"] = sync;
        tag["OrigTag"] = textBox.Tag;
        textBox.Tag = tag;
        clipPanel.Tag = state;
        hThumb.Tag = state;
        hTrack.Tag = state;

        textBox.TextChanged += delegate(object s, EventArgs e) { SyncTextBoxHScroll(state); };
        textBox.KeyUp += delegate(object s, KeyEventArgs e) { SyncTextBoxHScroll(state); };
        textBox.MouseUp += delegate(object s, MouseEventArgs e) { SyncTextBoxHScroll(state); };
        textBox.Resize += delegate(object s, EventArgs e) { ResizeTextBoxHScroll(state); };
        clipPanel.Resize += delegate(object s, EventArgs e) { ResizeTextBoxHScroll(state); };
        hThumb.MouseDown += HScrollThumb_MouseDown;
        hThumb.MouseMove += HScrollThumb_MouseMove;
        hThumb.MouseUp += HScrollThumb_MouseUp;
        hThumb.MouseCaptureChanged += HScrollThumb_MouseCaptureChanged;
        hTrack.MouseDown += HScrollTrack_MouseDown;
        hTrack.MouseMove += HScrollTrack_MouseMove;
        hTrack.MouseUp += HScrollTrack_MouseUp;
        hTrack.MouseCaptureChanged += HScrollTrack_MouseCaptureChanged;
        clipPanel.MouseWheel += TextBoxHScrollSurface_MouseWheel;
        hTrack.MouseWheel += TextBoxHScrollSurface_MouseWheel;
        hThumb.MouseWheel += TextBoxHScrollSurface_MouseWheel;
        clipPanel.Disposed += delegate(object s, EventArgs e) { DisposeTextBoxHScroll(state); };

        ResizeTextBoxHScroll(state);
        SyncTextBoxHScroll(state);

        DeviceEditorNativeHScrollResult result = new DeviceEditorNativeHScrollResult();
        result.ClipPanel = clipPanel;
        result.Track = hTrack;
        result.Thumb = hThumb;
        result.State = state;
        result.Sync = sync;
        return result;
    }

    private static void ResizeTextBoxHScroll(DeviceEditorNativeHScrollState st)
    {
        if (st == null || st.TextBox == null || st.Track == null || st.Thumb == null) { return; }
        if (st.Dragging)
        {
            int h = Math.Max(1, st.Track.Height);
            int w = st.FrozenThumbWidth > 0 ? Math.Max(1, Math.Min(Math.Max(1, st.Track.Width), st.FrozenThumbWidth)) : Math.Max(1, st.Thumb.Width);
            if (st.Thumb.Height != h || st.Thumb.Width != w) { st.Thumb.SetBounds(st.Thumb.Left, 0, w, h); }
            return;
        }
        Control clip = st.TextBox.Parent;
        if (clip != null)
        {
            int w = Math.Max(1, clip.ClientSize.Width);
            if (st.TextBox.Width != w) { st.TextBox.Width = w; }
            Control parent = st.Track.Parent;
            if (parent != null)
            {
                st.Track.Left = clip.Left;
                st.Track.Top = clip.Bottom;
                st.Track.Width = clip.Width;
            }
        }
        st.Thumb.Height = Math.Max(1, st.Track.Height);
        SyncTextBoxHScroll(st);
    }

    private static void DisposeTextBoxHScroll(DeviceEditorNativeHScrollState st)
    {
        if (st == null) { return; }
        StopTextBoxHScrollSmooth(st);
        if (st.Ticker != null)
        {
            st.Ticker.Dispose();
            st.Ticker = null;
        }
    }

    private static int TextBoxHScrollMax(int[] info)
    {
        if (info == null || info.Length < 4) { return 0; }
        int max = info[1] - Math.Max(0, info[2] - 1);
        if (max < info[0]) { max = info[0]; }
        return max;
    }

    private static double ClampTextBoxHScrollPos(DeviceEditorNativeHScrollState st, double pos, int[] info)
    {
        if (Double.IsNaN(pos) || Double.IsInfinity(pos)) { return 0.0; }
        if (info == null || info.Length < 4) { info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle); }
        int min = info[0];
        int max = TextBoxHScrollMax(info);
        if (pos < (double)min) { return (double)min; }
        if (pos > (double)max) { return (double)max; }
        return pos;
    }

    private static int ComputeTextBoxHThumbWidth(DeviceEditorNativeHScrollState st, int[] info)
    {
        int trackW = Math.Max(1, st.Track.Width);
        int minThumb = Math.Min(trackW, Math.Max(12, Math.Min(30, trackW)));
        if (st.Dragging && st.FrozenThumbWidth > 0)
        {
            return Math.Max(minThumb, Math.Min(trackW, st.FrozenThumbWidth));
        }
        if (info == null || info.Length < 4) { return minThumb; }
        int span = Math.Max(1, info[1] - info[0] + 1);
        int page = Math.Max(1, info[2]);
        int thumbW = DeviceTweakerScrollDynamics.Round(((double)page / (double)span) * (double)trackW);
        if (thumbW < minThumb) { thumbW = minThumb; }
        if (thumbW > trackW) { thumbW = trackW; }
        return thumbW;
    }

    private static void UpdateTextBoxHThumbFromPosition(DeviceEditorNativeHScrollState st, double pos, bool allowDuringDrag)
    {
        if (st == null || st.Track == null || st.Thumb == null || st.TextBox == null || st.TextBox.IsDisposed) { return; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        int scrollMax = TextBoxHScrollMax(info);
        int scrollRange = scrollMax - info[0];
        int h = Math.Max(1, st.Track.Height);
        if (scrollRange <= 0)
        {
            st.Track.Visible = false;
            if (st.Thumb.Left != 0 || st.Thumb.Height != h) { st.Thumb.SetBounds(0, 0, Math.Max(1, st.Thumb.Width), h); }
            return;
        }
        st.Track.Visible = true;
        int thumbW = ComputeTextBoxHThumbWidth(st, info);
        int available = Math.Max(0, st.Track.Width - thumbW);
        if (available <= 0)
        {
            if (st.Thumb.Left != 0 || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(0, 0, thumbW, h); }
            return;
        }
        if (st.Dragging && !allowDuringDrag) { return; }
        double clamped = ClampTextBoxHScrollPos(st, pos, info);
        int newLeft = DeviceTweakerScrollDynamics.Round(((clamped - (double)info[0]) / (double)scrollRange) * (double)available);
        if (newLeft < 0) { newLeft = 0; }
        if (newLeft > available) { newLeft = available; }
        if (st.Thumb.Left != newLeft || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(newLeft, 0, thumbW, h); }
    }

    private static void SyncTextBoxHScroll(DeviceEditorNativeHScrollState st)
    {
        if (st == null || st.TextBox == null || st.Track == null || st.Thumb == null || st.TextBox.IsDisposed) { return; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        int scrollMax = TextBoxHScrollMax(info);
        int scrollRange = scrollMax - info[0];
        if (scrollRange <= 0)
        {
            StopTextBoxHScrollSmooth(st);
            st.Track.Visible = false;
            st.Thumb.Left = 0;
            st.VisualPos = 0.0;
            st.TargetPos = 0.0;
            st.LastNativePos = 0;
            st.WheelRemainder = 0.0;
            return;
        }
        st.Track.Visible = true;
        int thumbW = ComputeTextBoxHThumbWidth(st, info);
        if (st.Dragging)
        {
            int h = Math.Max(1, st.Track.Height);
            if (st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(st.Thumb.Left, 0, thumbW, h); }
            return;
        }
        if (st.Thumb.Width != thumbW) { st.Thumb.Width = thumbW; }
        int nPos = Math.Max(info[0], Math.Min(scrollMax, info[3]));
        if (!st.SmoothActive)
        {
            st.VisualPos = (double)nPos;
            st.TargetPos = (double)nPos;
            st.LastNativePos = nPos;
            UpdateTextBoxHThumbFromPosition(st, nPos, true);
        }
    }

    private static void EnsureTextBoxHScrollTicker(DeviceEditorNativeHScrollState st)
    {
        if (st.TickInvoker == null) { st.TickInvoker = delegate() { TextBoxHScrollSmoothFrame(st); }; }
        if (st.Ticker == null) { st.Ticker = new LowLatencyUiTicker(st.TextBox, st.TickInvoker, 1); }
    }

    private static void StopTextBoxHScrollSmooth(DeviceEditorNativeHScrollState st)
    {
        if (st == null) { return; }
        st.SmoothActive = false;
        if (st.Ticker != null) { st.Ticker.Stop(); }
        if (st.FrameWatch != null) { st.FrameWatch.Restart(); }
    }

    private static void SetTextBoxNativeHScrollPosIfChanged(DeviceEditorNativeHScrollState st, int pos, bool tracking)
    {
        if (st == null || st.TextBox == null || st.TextBox.IsDisposed || !st.TextBox.IsHandleCreated) { return; }
        if (pos != st.LastNativePos)
        {
            HScrollHelper.SetHScrollPos(st.TextBox.Handle, pos, tracking);
            st.LastNativePos = pos;
        }
    }

    private static void SetTextBoxHScrollPosition(DeviceEditorNativeHScrollState st, double pos, bool immediate, bool tracking, bool updateThumb)
    {
        if (st == null || st.TextBox == null || st.TextBox.IsDisposed || !st.TextBox.IsHandleCreated) { return; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        double target = ClampTextBoxHScrollPos(st, pos, info);
        st.TargetPos = target;
        if (immediate)
        {
            StopTextBoxHScrollSmooth(st);
            int ipos = DeviceTweakerScrollDynamics.Round(target);
            SetTextBoxNativeHScrollPosIfChanged(st, ipos, tracking);
            st.VisualPos = (double)ipos;
            if (updateThumb) { UpdateTextBoxHThumbFromPosition(st, ipos, true); }
            return;
        }
        EnsureTextBoxHScrollTicker(st);
        if (!st.SmoothActive)
        {
            st.SmoothActive = true;
            st.FrameWatch.Restart();
            TextBoxHScrollSmoothFrame(st);
            if (st.SmoothActive) { st.Ticker.Start(); }
        }
    }

    private static void TextBoxHScrollSmoothFrame(DeviceEditorNativeHScrollState st)
    {
        if (st == null || !st.SmoothActive || st.TextBox == null || st.TextBox.IsDisposed || !st.TextBox.IsHandleCreated) { return; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        double target = ClampTextBoxHScrollPos(st, st.TargetPos, info);
        double current = ClampTextBoxHScrollPos(st, st.VisualPos, info);
        if (DeviceTweakerScrollDynamics.Arrived(current, target, DeviceTweakerScrollDynamics.CompletionPx))
        {
            int finalPos = DeviceTweakerScrollDynamics.Round(target);
            SetTextBoxNativeHScrollPosIfChanged(st, finalPos, false);
            st.VisualPos = (double)finalPos;
            st.TargetPos = (double)finalPos;
            UpdateTextBoxHThumbFromPosition(st, finalPos, true);
            StopTextBoxHScrollSmooth(st);
            return;
        }
        double next = ClampTextBoxHScrollPos(st, DeviceTweakerScrollDynamics.Next(current, target, st.FrameWatch, DeviceTweakerScrollDynamics.HorizontalTextTauMs, DeviceTweakerScrollDynamics.MinAlpha, DeviceTweakerScrollDynamics.MaxFrameMs, DeviceTweakerScrollDynamics.MinStepPx), info);
        int nextPos = DeviceTweakerScrollDynamics.Round(next);
        st.VisualPos = next;
        if (nextPos != st.LastNativePos)
        {
            HScrollHelper.SetHScrollPos(st.TextBox.Handle, nextPos, true);
            st.LastNativePos = nextPos;
            UpdateTextBoxHThumbFromPosition(st, nextPos, true);
        }
    }

    private static bool CaptureTextBoxHScrollDragGeometry(DeviceEditorNativeHScrollState st)
    {
        if (st == null || st.Track == null || st.Thumb == null || st.TextBox == null || st.TextBox.IsDisposed || !st.TextBox.IsHandleCreated) { return false; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        int scrollMax = TextBoxHScrollMax(info);
        int scrollRange = scrollMax - info[0];
        if (scrollRange <= 0) { return false; }
        int trackW = Math.Max(1, st.Track.Width);
        int thumbW = ComputeTextBoxHThumbWidth(st, info);
        int available = trackW - thumbW;
        if (available <= 0) { return false; }
        int h = Math.Max(1, st.Track.Height);
        int nPos = Math.Max(info[0], Math.Min(scrollMax, info[3]));
        st.FrozenThumbWidth = thumbW;
        st.DragThumbWidth = thumbW;
        st.DragTrackWidth = trackW;
        st.DragAvailable = available;
        st.DragScrollMin = info[0];
        st.DragScrollRange = scrollRange;
        st.DragGeometryValid = true;
        st.VisualPos = (double)nPos;
        st.TargetPos = (double)nPos;
        st.LastNativePos = nPos;
        int left = DeviceTweakerScrollDynamics.Round(((double)(nPos - info[0]) / (double)scrollRange) * (double)available);
        if (left < 0) { left = 0; }
        if (left > available) { left = available; }
        if (st.Thumb.Left != left || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(left, 0, thumbW, h); }
        return true;
    }

    private static void ResetTextBoxHScrollDragGeometry(DeviceEditorNativeHScrollState st)
    {
        if (st == null) { return; }
        st.DragScrollMin = 0;
        st.DragScrollRange = 0;
        st.DragTrackWidth = 0;
        st.DragAvailable = 0;
        st.DragGeometryValid = false;
        st.DragStart = 0;
        st.DragTrackStartX = 0;
        st.DragStartThumbLeft = 0;
        st.DragThumbWidth = 0;
    }

    private static void MoveTextBoxHThumb(DeviceEditorNativeHScrollState st, int targetLeft, bool tracking)
    {
        if (st == null || st.Track == null || st.Thumb == null || st.TextBox == null || st.TextBox.IsDisposed) { return; }
        int scrollMin;
        int scrollRange;
        int available;
        int thumbW;
        if (st.Dragging && st.DragGeometryValid)
        {
            scrollMin = st.DragScrollMin;
            scrollRange = st.DragScrollRange;
            available = st.DragAvailable;
            thumbW = st.FrozenThumbWidth > 0 ? st.FrozenThumbWidth : st.DragThumbWidth;
        }
        else
        {
            int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
            int scrollMax = TextBoxHScrollMax(info);
            scrollMin = info[0];
            scrollRange = scrollMax - info[0];
            thumbW = ComputeTextBoxHThumbWidth(st, info);
            available = Math.Max(1, st.Track.Width) - thumbW;
        }
        if (scrollRange <= 0 || available <= 0 || thumbW <= 0) { return; }
        int h = Math.Max(1, st.Track.Height);
        int maxVisualLeft = Math.Max(0, Math.Min(available, Math.Max(1, st.Track.Width) - thumbW));
        int newLeft = Math.Max(0, Math.Min(maxVisualLeft, targetLeft));
        if (st.Thumb.Left != newLeft || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(newLeft, 0, thumbW, h); }
        double newPos = (double)scrollMin + ((double)newLeft / (double)available) * (double)scrollRange;
        SetTextBoxHScrollPosition(st, newPos, true, tracking, false);
    }

    private static void StopTextBoxHScrollDrag(DeviceEditorNativeHScrollState st, Control captureControl)
    {
        if (st != null)
        {
            st.Dragging = false;
            st.DragMode = String.Empty;
            st.FrozenThumbWidth = 0;
            ResetTextBoxHScrollDragGeometry(st);
            if (st.TextBox != null && !st.TextBox.IsDisposed && st.TextBox.IsHandleCreated)
            {
                int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
                int pos = Math.Max(info[0], Math.Min(TextBoxHScrollMax(info), info[3]));
                SetTextBoxNativeHScrollPosIfChanged(st, pos, false);
                st.VisualPos = (double)pos;
                st.TargetPos = (double)pos;
            }
            SyncTextBoxHScroll(st);
        }
        if (captureControl != null && captureControl.Capture) { captureControl.Capture = false; }
    }

    private static DeviceEditorNativeHScrollState GetTextBoxHScrollStateFromSender(object sender)
    {
        Control c = sender as Control;
        while (c != null)
        {
            DeviceEditorNativeHScrollState st = c.Tag as DeviceEditorNativeHScrollState;
            if (st != null) { return st; }
            Hashtable tag = c.Tag as Hashtable;
            if (tag != null && tag.ContainsKey("HScrollState")) { return tag["HScrollState"] as DeviceEditorNativeHScrollState; }
            if (c.Parent == null) { break; }
            c = c.Parent;
        }
        return null;
    }

    private static void TextBoxHScrollSurface_MouseWheel(object sender, MouseEventArgs e)
    {
        TryScrollTextBoxHorizontalWheel(GetTextBoxHScrollStateFromSender(sender), -e.Delta);
    }

    private static bool TryScrollTextBoxHorizontalWheel(DeviceEditorNativeHScrollState st, int signedDelta)
    {
        if (signedDelta == 0) { return false; }
        if (st == null || st.Dragging || st.TextBox == null || st.TextBox.IsDisposed || !st.TextBox.IsHandleCreated) { return false; }
        int[] info = HScrollHelper.GetHScrollInfo(st.TextBox.Handle);
        if (TextBoxHScrollMax(info) - info[0] <= 0) { st.WheelRemainder = 0.0; return false; }
        double basePos = st.SmoothActive ? st.TargetPos : st.VisualPos;
        int span = st.TextBox.Parent == null ? st.TextBox.Width : st.TextBox.Parent.Width;
        double pixels = DeviceTweakerScrollDynamics.WheelPixelsForViewport(span, 42.0, 0);
        double delta = ((double)signedDelta / 120.0) * pixels;
        double distance = DeviceTweakerScrollDynamics.ConsumeWheelDistance(ref st.WheelRemainder, delta, 0.12);
        if (distance == 0.0) { return true; }
        SetTextBoxHScrollPosition(st, basePos + distance, false, false, true);
        return true;
    }

    private static void HScrollThumb_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st == null || st.Track == null || st.Thumb == null) { return; }
        StopTextBoxHScrollSmooth(st);
        if (!CaptureTextBoxHScrollDragGeometry(st)) { return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        st.Dragging = true;
        st.DragMode = "thumb";
        st.DragStart = e.X;
        st.DragTrackStartX = p.X;
        st.DragStartThumbLeft = st.Thumb.Left;
        c.Capture = true;
    }

    private static void HScrollThumb_MouseMove(object sender, MouseEventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st == null || !st.Dragging || !String.Equals(st.DragMode, "thumb", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopTextBoxHScrollDrag(st, c); return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        MoveTextBoxHThumb(st, st.DragStartThumbLeft + (p.X - st.DragTrackStartX), true);
    }

    private static void HScrollThumb_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        StopTextBoxHScrollDrag(st, c);
    }

    private static void HScrollThumb_MouseCaptureChanged(object sender, EventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st != null && c != null && !c.Capture && String.Equals(st.DragMode, "thumb", StringComparison.Ordinal)) { StopTextBoxHScrollDrag(st, c); }
    }

    private static void HScrollTrack_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st == null || st.Thumb == null) { return; }
        StopTextBoxHScrollSmooth(st);
        if (!CaptureTextBoxHScrollDragGeometry(st)) { return; }
        st.Dragging = true;
        st.DragMode = "track";
        c.Capture = true;
        MoveTextBoxHThumb(st, e.X - (st.FrozenThumbWidth / 2), true);
    }

    private static void HScrollTrack_MouseMove(object sender, MouseEventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st == null || !st.Dragging || !String.Equals(st.DragMode, "track", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopTextBoxHScrollDrag(st, c); return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        int thumbHalf = (st.FrozenThumbWidth > 0 ? st.FrozenThumbWidth : st.Thumb.Width) / 2;
        MoveTextBoxHThumb(st, p.X - thumbHalf, true);
    }

    private static void HScrollTrack_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        StopTextBoxHScrollDrag(st, c);
    }

    private static void HScrollTrack_MouseCaptureChanged(object sender, EventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeHScrollState st = c == null ? null : c.Tag as DeviceEditorNativeHScrollState;
        if (st != null && c != null && !c.Capture && String.Equals(st.DragMode, "track", StringComparison.Ordinal)) { StopTextBoxHScrollDrag(st, c); }
    }

    public static DeviceEditorScrollableLabelResult CreateScrollableLabel(Control parentPanel, int left, int top, int viewWidth, int viewHeight, int trackHeight, Font font, Color foreColor, Color trackBackColor)
    {
        if (parentPanel == null) { throw new ArgumentNullException("parentPanel", "Scrollable label creation requires a non-null parent Panel."); }

        Panel container = new Panel();
        container.Left = left;
        container.Top = top;
        container.Width = Math.Max(1, viewWidth);
        container.Height = Math.Max(1, viewHeight) + Math.Max(1, trackHeight);
        container.BackColor = Color.Transparent;
        container.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
        ScrollHelper.EnableDoubleBuffer(container);
        parentPanel.Controls.Add(container);

        Panel viewport = new Panel();
        viewport.Left = 0;
        viewport.Top = 0;
        viewport.Width = Math.Max(1, viewWidth);
        viewport.Height = Math.Max(1, viewHeight);
        viewport.BackColor = Color.Transparent;
        viewport.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
        ScrollHelper.EnableDoubleBuffer(viewport);
        container.Controls.Add(viewport);

        DeviceEditorScrollableTextLabel innerLabel = new DeviceEditorScrollableTextLabel();
        // Do not let WinForms AutoSize decide the virtual width for long PCIe status lines.
        // AutoSize/PreferredWidth can under-report very long single-line labels, which makes
        // the custom horizontal scrollbar clamp before the real end of the text.
        innerLabel.AutoSize = false;
        innerLabel.Left = 0;
        innerLabel.Top = 0;
        innerLabel.Width = Math.Max(1, viewWidth);
        innerLabel.Height = Math.Max(1, viewHeight);
        innerLabel.Font = font;
        innerLabel.ForeColor = foreColor;
        innerLabel.BackColor = Color.Transparent;
        innerLabel.Text = String.Empty;
        viewport.Controls.Add(innerLabel);

        Panel hTrack = new Panel();
        hTrack.Left = 0;
        hTrack.Top = viewport.Height;
        hTrack.Width = viewport.Width;
        hTrack.Height = Math.Max(1, trackHeight);
        hTrack.BackColor = trackBackColor;
        hTrack.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
        hTrack.Visible = false;
        ScrollHelper.EnableDoubleBuffer(hTrack);
        container.Controls.Add(hTrack);

        Panel hThumb = new Panel();
        hThumb.Left = 0;
        hThumb.Top = 0;
        hThumb.Width = 20;
        hThumb.Height = hTrack.Height;
        hThumb.BackColor = Color.FromArgb(32, 32, 32);
        hThumb.Cursor = Cursors.Arrow;
        hThumb.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Bottom;
        ScrollHelper.EnableDoubleBuffer(hThumb);
        hTrack.Controls.Add(hThumb);

        DeviceEditorNativeLabelScrollState state = new DeviceEditorNativeLabelScrollState();
        state.Label = innerLabel;
        state.Viewport = viewport;
        state.Track = hTrack;
        state.Thumb = hThumb;
        state.Container = container;
        Action<object> sync = delegate(object stObj) { SyncScrollableLabel(stObj as DeviceEditorNativeLabelScrollState); };
        container.Tag = state;
        viewport.Tag = state;
        innerLabel.Tag = state;
        hThumb.Tag = state;
        hTrack.Tag = state;
        hThumb.MouseDown += LabelThumb_MouseDown;
        hThumb.MouseMove += LabelThumb_MouseMove;
        hThumb.MouseUp += LabelThumb_MouseUp;
        hThumb.MouseCaptureChanged += LabelThumb_MouseCaptureChanged;
        hTrack.MouseDown += LabelTrack_MouseDown;
        hTrack.MouseMove += LabelTrack_MouseMove;
        hTrack.MouseUp += LabelTrack_MouseUp;
        hTrack.MouseCaptureChanged += LabelTrack_MouseCaptureChanged;
        container.MouseWheel += LabelSurface_MouseWheel;
        viewport.MouseWheel += LabelSurface_MouseWheel;
        innerLabel.MouseWheel += LabelSurface_MouseWheel;
        hTrack.MouseWheel += LabelSurface_MouseWheel;
        hThumb.MouseWheel += LabelSurface_MouseWheel;
        container.Resize += delegate(object s, EventArgs e) { ResizeScrollableLabel(state); };
        container.Disposed += delegate(object s, EventArgs e) { DisposeScrollableLabel(state); };

        ResizeScrollableLabel(state);

        DeviceEditorScrollableLabelResult result = new DeviceEditorScrollableLabelResult();
        result.Container = container;
        result.Label = innerLabel;
        result.Viewport = viewport;
        result.Track = hTrack;
        result.Thumb = hThumb;
        result.State = state;
        result.Sync = sync;
        return result;
    }

    private static void ResizeScrollableLabel(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Container == null || st.Viewport == null || st.Track == null || st.Thumb == null) { return; }
        int w = Math.Max(1, st.Container.ClientSize.Width);
        int viewH = Math.Max(1, st.Viewport.Height);
        st.Viewport.Left = 0;
        st.Viewport.Top = 0;
        if (!st.Dragging)
        {
            st.Viewport.Width = w;
            st.Track.Left = 0;
            st.Track.Top = viewH;
            st.Track.Width = w;
            st.Thumb.Height = Math.Max(1, st.Track.Height);
            SyncScrollableLabel(st);
            return;
        }
        int trackW = st.DragGeometryValid && st.DragTrackWidth > 0 ? st.DragTrackWidth : Math.Max(1, st.Track.Width);
        int thumbW = st.FrozenThumbWidth > 0 ? Math.Max(1, Math.Min(trackW, st.FrozenThumbWidth)) : Math.Max(1, st.Thumb.Width);
        int available = st.DragGeometryValid ? Math.Max(0, st.DragAvailable) : Math.Max(0, trackW - thumbW);
        int left = Math.Max(0, Math.Min(available, st.Thumb.Left));
        st.Track.Left = 0;
        st.Track.Top = viewH;
        st.Track.Width = trackW;
        int h = Math.Max(1, st.Track.Height);
        if (st.Thumb.Left != left || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(left, 0, thumbW, h); }
    }

    private static void DisposeScrollableLabel(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null) { return; }
        StopLabelHScrollSmooth(st);
        if (st.Ticker != null)
        {
            st.Ticker.Dispose();
            st.Ticker = null;
        }
    }

    private static int MeasureLabelTextWidthNoLimit(Label label)
    {
        if (label == null) { return 1; }
        string text = label.Text;
        if (String.IsNullOrEmpty(text)) { return 1; }

        Font font = label.Font == null ? Control.DefaultFont : label.Font;
        TextFormatFlags flags = NoPad | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoClipping;

        try
        {
            int single = TextRenderer.MeasureText(text, font, new Size(32767, 9999), flags).Width;
            if (single > 0 && single < 32760) { return Math.Max(1, single + 12); }
        }
        catch { }

        long total = 0L;
        const int chunkSize = 1024;
        try
        {
            for (int i = 0; i < text.Length; i += chunkSize)
            {
                int len = Math.Min(chunkSize, text.Length - i);
                string chunk = text.Substring(i, len);
                int w = TextRenderer.MeasureText(chunk, font, new Size(32767, 9999), flags).Width;
                if (w > 0) { total += (long)w; }
                if (total > 2000000000L) { total = 2000000000L; break; }
            }
        }
        catch
        {
            total = Math.Max(1L, (long)text.Length * (long)Math.Max(5, font.Height / 2));
        }

        total += 12L;
        if (total > 2000000000L) { return 2000000000; }
        return Math.Max(1, (int)total);
    }

    private static int LabelContentWidth(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null) { return 1; }
        int preferred = 0;
        // For virtual labels, never ask WinForms for PreferredWidth.  PreferredWidth
        // is one of the APIs that becomes unreliable on very long single-line text
        // and was the original source of scrollbar range clamps/teleporting.
        if (!(st.Label is DeviceEditorScrollableTextLabel))
        {
            try { preferred = st.Label.PreferredWidth; } catch { preferred = 0; }
        }
        int measured = MeasureLabelTextWidthNoLimit(st.Label);
        int content = Math.Max(preferred, measured);
        return Math.Max(1, content);
    }

    private static int GetLabelRenderOffset(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null) { return 0; }
        DeviceEditorScrollableTextLabel virtualLabel = st.Label as DeviceEditorScrollableTextLabel;
        if (virtualLabel != null) { return Math.Max(0, virtualLabel.VirtualOffset); }
        return Math.Max(0, -st.Label.Left);
    }

    private static void SetLabelRenderOffset(DeviceEditorNativeLabelScrollState st, int offset, bool flushPaint)
    {
        if (st == null || st.Label == null) { return; }
        int safe = Math.Max(0, offset);
        DeviceEditorScrollableTextLabel virtualLabel = st.Label as DeviceEditorScrollableTextLabel;
        if (virtualLabel != null)
        {
            if (st.Label.Left != 0) { st.Label.Left = 0; }
            virtualLabel.SetVirtualOffset(safe);
            if (flushPaint && virtualLabel.IsHandleCreated) { ScrollHelper.FlushPaint(virtualLabel.Handle); }
            return;
        }
        if (st.Label.Left != -safe) { st.Label.Left = -safe; }
        if (flushPaint && st.Viewport != null && st.Viewport.IsHandleCreated) { ScrollHelper.FlushPaint(st.Viewport.Handle); }
    }

    private static void EnsureLabelContentBounds(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null || st.Viewport == null) { return; }
        int contentW = LabelContentWidth(st);
        int contentH = Math.Max(1, st.Viewport.Height);
        if (st.Label.AutoSize) { st.Label.AutoSize = false; }

        DeviceEditorScrollableTextLabel virtualLabel = st.Label as DeviceEditorScrollableTextLabel;
        if (virtualLabel != null)
        {
            virtualLabel.SetVirtualTextWidth(contentW);
            int viewW = Math.Max(1, st.Viewport.Width);
            if (st.Label.Left != 0 || st.Label.Width != viewW || st.Label.Height != contentH || st.Label.Top != 0)
            {
                st.Label.SetBounds(0, 0, viewW, contentH);
            }
            return;
        }

        int safeContentW = Math.Max(1, Math.Min(contentW, 32760));
        if (st.Label.Width != safeContentW || st.Label.Height != contentH || st.Label.Top != 0)
        {
            st.Label.SetBounds(st.Label.Left, 0, safeContentW, contentH);
        }
    }

    private static int LabelScrollRange(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null || st.Viewport == null) { return 0; }
        int lblW = Math.Max(1, LabelContentWidth(st));
        int vpW = Math.Max(1, st.Viewport.Width);
        return Math.Max(0, lblW - vpW);
    }

    private static double ClampLabelOffset(DeviceEditorNativeLabelScrollState st, double offset)
    {
        if (Double.IsNaN(offset) || Double.IsInfinity(offset)) { return 0.0; }
        double max = (double)LabelScrollRange(st);
        if (offset < 0.0) { return 0.0; }
        if (offset > max) { return max; }
        return offset;
    }

    private static int ComputeLabelThumbWidth(DeviceEditorNativeLabelScrollState st)
    {
        int trackW = Math.Max(1, st.Track.Width);
        int lblW = Math.Max(1, LabelContentWidth(st));
        int vpW = Math.Max(1, st.Viewport.Width);
        int minThumb = Math.Min(trackW, Math.Max(12, Math.Min(24, trackW)));
        if (st.Dragging && st.FrozenThumbWidth > 0)
        {
            return Math.Max(minThumb, Math.Min(trackW, st.FrozenThumbWidth));
        }
        int thumbW = DeviceTweakerScrollDynamics.Round(((double)vpW / (double)lblW) * (double)trackW);
        int maxDynamic = Math.Max(minThumb, Math.Min(trackW, Math.Min(156, Math.Max(48, DeviceTweakerScrollDynamics.Round((double)trackW * 0.36)))));
        if (thumbW < minThumb) { thumbW = minThumb; }
        if (thumbW > maxDynamic) { thumbW = maxDynamic; }
        if (thumbW > trackW) { thumbW = trackW; }
        return thumbW;
    }

    private static void UpdateLabelThumbFromOffset(DeviceEditorNativeLabelScrollState st, double offset, bool allowDuringDrag)
    {
        if (st == null || st.Label == null || st.Viewport == null || st.Track == null || st.Thumb == null) { return; }
        EnsureLabelContentBounds(st);
        int scrollRange = LabelScrollRange(st);
        int h = Math.Max(1, st.Track.Height);
        if (scrollRange <= 0)
        {
            st.Track.Visible = false;
            if (st.Thumb.Left != 0 || st.Thumb.Height != h) { st.Thumb.SetBounds(0, 0, Math.Max(1, st.Thumb.Width), h); }
            SetLabelRenderOffset(st, 0, true);
            st.Container.Height = st.Viewport.Height;
            return;
        }
        st.Track.Visible = true;
        st.Container.Height = st.Viewport.Height + st.Track.Height;
        if (st.Dragging && !allowDuringDrag) { return; }
        int thumbW = ComputeLabelThumbWidth(st);
        int available = Math.Max(0, st.Track.Width - thumbW);
        if (available <= 0)
        {
            if (st.Thumb.Left != 0 || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(0, 0, thumbW, h); }
            return;
        }
        double clamped = ClampLabelOffset(st, offset);
        int newLeft = DeviceTweakerScrollDynamics.Round((clamped / (double)scrollRange) * (double)available);
        if (newLeft < 0) { newLeft = 0; }
        if (newLeft > available) { newLeft = available; }
        if (st.Thumb.Left != newLeft || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(newLeft, 0, thumbW, h); }
    }

    private static void SyncScrollableLabel(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null || st.Viewport == null || st.Track == null || st.Thumb == null) { return; }
        EnsureLabelContentBounds(st);
        int scrollRange = LabelScrollRange(st);
        int h = Math.Max(1, st.Track.Height);
        if (scrollRange <= 0)
        {
            StopLabelHScrollSmooth(st);
            st.Track.Visible = false;
            SetLabelRenderOffset(st, 0, true);
            if (st.Thumb.Left != 0 || st.Thumb.Height != h) { st.Thumb.SetBounds(0, 0, Math.Max(1, st.Thumb.Width), h); }
            st.Container.Height = st.Viewport.Height;
            st.VisualOffset = 0.0;
            st.TargetOffset = 0.0;
            st.WheelRemainder = 0.0;
            return;
        }
        st.Track.Visible = true;
        st.Container.Height = st.Viewport.Height + st.Track.Height;
        if (st.Dragging)
        {
            int trackW = st.DragGeometryValid && st.DragTrackWidth > 0 ? st.DragTrackWidth : Math.Max(1, st.Track.Width);
            int thumbW = st.FrozenThumbWidth > 0 ? Math.Max(1, Math.Min(trackW, st.FrozenThumbWidth)) : Math.Max(1, st.Thumb.Width);
            int available = st.DragGeometryValid ? Math.Max(0, st.DragAvailable) : Math.Max(0, trackW - thumbW);
            int left = Math.Max(0, Math.Min(available, st.Thumb.Left));
            if (st.Track.Width != trackW) { st.Track.Width = trackW; }
            if (st.Thumb.Left != left || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(left, 0, thumbW, h); }
            return;
        }
        int thumbW2 = ComputeLabelThumbWidth(st);
        int currentOffset = Math.Max(0, Math.Min(scrollRange, GetLabelRenderOffset(st)));
        if (GetLabelRenderOffset(st) != currentOffset) { SetLabelRenderOffset(st, currentOffset, true); }
        if (st.Thumb.Width != thumbW2 || st.Thumb.Height != h) { st.Thumb.SetBounds(st.Thumb.Left, 0, thumbW2, h); }
        if (!st.SmoothActive)
        {
            st.VisualOffset = (double)currentOffset;
            st.TargetOffset = (double)currentOffset;
            UpdateLabelThumbFromOffset(st, currentOffset, true);
        }
    }

    private static void EnsureLabelHScrollTicker(DeviceEditorNativeLabelScrollState st)
    {
        if (st.TickInvoker == null) { st.TickInvoker = delegate() { LabelHScrollSmoothFrame(st); }; }
        if (st.Ticker == null) { st.Ticker = new LowLatencyUiTicker(st.Container, st.TickInvoker, 1); }
    }

    private static void StopLabelHScrollSmooth(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null) { return; }
        st.SmoothActive = false;
        if (st.Ticker != null) { st.Ticker.Stop(); }
        if (st.FrameWatch != null) { st.FrameWatch.Restart(); }
    }

    private static void SetLabelOffset(DeviceEditorNativeLabelScrollState st, double offset, bool immediate, bool updateThumb)
    {
        if (st == null || st.Label == null) { return; }
        EnsureLabelContentBounds(st);
        double target = ClampLabelOffset(st, offset);
        st.TargetOffset = target;
        if (immediate)
        {
            StopLabelHScrollSmooth(st);
            int intOffset = DeviceTweakerScrollDynamics.Round(target);
            SetLabelRenderOffset(st, intOffset, true);
            st.VisualOffset = (double)intOffset;
            if (updateThumb) { UpdateLabelThumbFromOffset(st, intOffset, true); }
            return;
        }
        EnsureLabelHScrollTicker(st);
        if (!st.SmoothActive)
        {
            st.SmoothActive = true;
            st.FrameWatch.Restart();
            LabelHScrollSmoothFrame(st);
            if (st.SmoothActive) { st.Ticker.Start(); }
        }
    }

    private static void LabelHScrollSmoothFrame(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || !st.SmoothActive || st.Label == null || st.Label.IsDisposed) { return; }
        double target = ClampLabelOffset(st, st.TargetOffset);
        double current = ClampLabelOffset(st, st.VisualOffset);
        if (DeviceTweakerScrollDynamics.Arrived(current, target, DeviceTweakerScrollDynamics.CompletionPx))
        {
            int finalOffset = DeviceTweakerScrollDynamics.Round(target);
            if (finalOffset != GetLabelRenderOffset(st))
            {
                SetLabelRenderOffset(st, finalOffset, true);
                UpdateLabelThumbFromOffset(st, finalOffset, true);
            }
            st.VisualOffset = (double)finalOffset;
            st.TargetOffset = (double)finalOffset;
            StopLabelHScrollSmooth(st);
            return;
        }
        double next = ClampLabelOffset(st, DeviceTweakerScrollDynamics.Next(current, target, st.FrameWatch, DeviceTweakerScrollDynamics.HorizontalLabelTauMs, DeviceTweakerScrollDynamics.MinAlpha, DeviceTweakerScrollDynamics.MaxFrameMs, DeviceTweakerScrollDynamics.MinStepPx));
        int nextOffset = DeviceTweakerScrollDynamics.Round(next);
        st.VisualOffset = next;
        if (nextOffset != GetLabelRenderOffset(st))
        {
            SetLabelRenderOffset(st, nextOffset, true);
            UpdateLabelThumbFromOffset(st, nextOffset, true);
        }
    }

    private static bool CaptureLabelHScrollDragGeometry(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null || st.Label == null || st.Viewport == null || st.Track == null || st.Thumb == null) { return false; }
        EnsureLabelContentBounds(st);
        int scrollRange = LabelScrollRange(st);
        if (scrollRange <= 0) { return false; }
        int trackW = Math.Max(1, st.Track.Width);
        int thumbW = ComputeLabelThumbWidth(st);
        int available = trackW - thumbW;
        if (available <= 0) { return false; }
        int offset = Math.Max(0, Math.Min(scrollRange, GetLabelRenderOffset(st)));
        int h = Math.Max(1, st.Track.Height);
        int left = DeviceTweakerScrollDynamics.Round(((double)offset / (double)scrollRange) * (double)available);
        if (left < 0) { left = 0; }
        if (left > available) { left = available; }
        st.FrozenThumbWidth = thumbW;
        st.DragThumbWidth = thumbW;
        st.DragTrackWidth = trackW;
        st.DragAvailable = available;
        st.DragScrollRange = scrollRange;
        st.DragGeometryValid = true;
        st.VisualOffset = (double)offset;
        st.TargetOffset = (double)offset;
        if (st.Thumb.Left != left || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(left, 0, thumbW, h); }
        return true;
    }

    private static void ResetLabelHScrollDragGeometry(DeviceEditorNativeLabelScrollState st)
    {
        if (st == null) { return; }
        st.DragScrollRange = 0;
        st.DragTrackWidth = 0;
        st.DragAvailable = 0;
        st.DragGeometryValid = false;
        st.DragStart = 0;
        st.DragTrackStartX = 0;
        st.DragStartThumbLeft = 0;
        st.DragThumbWidth = 0;
    }

    private static void MoveLabelThumb(DeviceEditorNativeLabelScrollState st, int targetLeft)
    {
        if (st == null || st.Track == null || st.Thumb == null) { return; }
        int scrollRange;
        int available;
        int thumbW;
        int trackW;
        if (st.Dragging && st.DragGeometryValid)
        {
            scrollRange = st.DragScrollRange;
            available = st.DragAvailable;
            thumbW = st.FrozenThumbWidth > 0 ? st.FrozenThumbWidth : st.DragThumbWidth;
            trackW = st.DragTrackWidth > 0 ? st.DragTrackWidth : Math.Max(1, st.Track.Width);
        }
        else
        {
            scrollRange = LabelScrollRange(st);
            trackW = Math.Max(1, st.Track.Width);
            thumbW = ComputeLabelThumbWidth(st);
            available = trackW - thumbW;
        }
        if (scrollRange <= 0 || available <= 0 || thumbW <= 0) { return; }
        if (thumbW > trackW) { thumbW = trackW; }
        int h = Math.Max(1, st.Track.Height);
        int maxVisualLeft = Math.Max(0, Math.Min(available, trackW - thumbW));
        int newLeft = Math.Max(0, Math.Min(maxVisualLeft, targetLeft));
        if (st.Thumb.Left != newLeft || st.Thumb.Width != thumbW || st.Thumb.Height != h) { st.Thumb.SetBounds(newLeft, 0, thumbW, h); }
        if (st.Track.IsHandleCreated) { ScrollHelper.FlushPaint(st.Track.Handle); }
        double offset = ((double)newLeft / (double)available) * (double)scrollRange;
        SetLabelOffset(st, offset, true, false);
    }

    private static void StopLabelHScrollDrag(DeviceEditorNativeLabelScrollState st, Control captureControl)
    {
        if (st != null)
        {
            int offset = Math.Max(0, Math.Min(LabelScrollRange(st), GetLabelRenderOffset(st)));
            st.Dragging = false;
            st.DragMode = String.Empty;
            st.FrozenThumbWidth = 0;
            ResetLabelHScrollDragGeometry(st);
            st.VisualOffset = (double)offset;
            st.TargetOffset = (double)offset;
            ResizeScrollableLabel(st);
        }
        if (captureControl != null && captureControl.Capture) { captureControl.Capture = false; }
    }

    private static DeviceEditorNativeLabelScrollState GetLabelScrollStateFromSender(object sender)
    {
        Control c = sender as Control;
        while (c != null)
        {
            DeviceEditorNativeLabelScrollState st = c.Tag as DeviceEditorNativeLabelScrollState;
            if (st != null) { return st; }
            if (c.Parent == null) { break; }
            c = c.Parent;
        }
        return null;
    }

    private static void LabelSurface_MouseWheel(object sender, MouseEventArgs e)
    {
        TryScrollLabelHorizontalWheel(GetLabelScrollStateFromSender(sender), -e.Delta);
    }

    private static bool TryScrollLabelHorizontalWheel(DeviceEditorNativeLabelScrollState st, int signedDelta)
    {
        if (signedDelta == 0) { return false; }
        if (st == null || st.Dragging || LabelScrollRange(st) <= 0) { if (st != null) { st.WheelRemainder = 0.0; } return false; }
        double baseOffset = st.SmoothActive ? st.TargetOffset : st.VisualOffset;
        double pixels = DeviceTweakerScrollDynamics.WheelPixelsForViewport(st.Viewport == null ? 1 : st.Viewport.Width, 34.0, 0);
        double delta = ((double)signedDelta / 120.0) * pixels;
        double distance = DeviceTweakerScrollDynamics.ConsumeWheelDistance(ref st.WheelRemainder, delta, 0.12);
        if (distance == 0.0) { return true; }
        SetLabelOffset(st, baseOffset + distance, false, true);
        return true;
    }

    private static void LabelThumb_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st == null || st.Track == null || st.Thumb == null) { return; }
        StopLabelHScrollSmooth(st);
        if (!CaptureLabelHScrollDragGeometry(st)) { return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        st.Dragging = true;
        st.DragMode = "thumb";
        st.DragStart = e.X;
        st.DragTrackStartX = p.X;
        st.DragStartThumbLeft = st.Thumb.Left;
        c.Capture = true;
    }

    private static void LabelThumb_MouseMove(object sender, MouseEventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st == null || !st.Dragging || !String.Equals(st.DragMode, "thumb", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopLabelHScrollDrag(st, c); return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        MoveLabelThumb(st, st.DragStartThumbLeft + (p.X - st.DragTrackStartX));
    }

    private static void LabelThumb_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        StopLabelHScrollDrag(st, c);
    }

    private static void LabelThumb_MouseCaptureChanged(object sender, EventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st != null && c != null && !c.Capture && String.Equals(st.DragMode, "thumb", StringComparison.Ordinal)) { StopLabelHScrollDrag(st, c); }
    }

    private static void LabelTrack_MouseDown(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st == null || st.Thumb == null) { return; }
        StopLabelHScrollSmooth(st);
        if (!CaptureLabelHScrollDragGeometry(st)) { return; }
        st.Dragging = true;
        st.DragMode = "track";
        c.Capture = true;
        MoveLabelThumb(st, e.X - (st.FrozenThumbWidth / 2));
    }

    private static void LabelTrack_MouseMove(object sender, MouseEventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st == null || !st.Dragging || !String.Equals(st.DragMode, "track", StringComparison.Ordinal)) { return; }
        if ((Control.MouseButtons & MouseButtons.Left) != MouseButtons.Left) { StopLabelHScrollDrag(st, c); return; }
        Point p = st.Track.PointToClient(Control.MousePosition);
        int thumbHalf = (st.FrozenThumbWidth > 0 ? st.FrozenThumbWidth : st.Thumb.Width) / 2;
        MoveLabelThumb(st, p.X - thumbHalf);
    }

    private static void LabelTrack_MouseUp(object sender, MouseEventArgs e)
    {
        if (e.Button != MouseButtons.Left) { return; }
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        StopLabelHScrollDrag(st, c);
    }

    private static void LabelTrack_MouseCaptureChanged(object sender, EventArgs e)
    {
        Control c = sender as Control;
        DeviceEditorNativeLabelScrollState st = c == null ? null : c.Tag as DeviceEditorNativeLabelScrollState;
        if (st != null && c != null && !c.Capture && String.Equals(st.DragMode, "track", StringComparison.Ordinal)) { StopLabelHScrollDrag(st, c); }
    }

    private static int ToInt(object value, int fallback)
    {
        if (value == null) { return fallback; }
        try { return Convert.ToInt32(value); } catch { return fallback; }
    }

    private static string GetNicImodMultipleValuesText(Hashtable nicInfo)
    {
        object labelsObj = nicInfo == null ? null : nicInfo["VectorLabels"];
        string[] labels = labelsObj as string[];
        int maxQueues = ToInt(nicInfo == null ? null : nicInfo["MaxQueues"], 0);
        string family = (nicInfo == null || !nicInfo.ContainsKey("Family") || nicInfo["Family"] == null) ? String.Empty : nicInfo["Family"].ToString();

        if (String.Equals(family, "RealtekIntrMitV2", StringComparison.OrdinalIgnoreCase))
        {
            if (maxQueues > 1) { return "Multiple IntMITI V2 editable 32-bit dword values (IntMITI0-IntMITI" + (maxQueues - 1).ToString() + "; runtime mapping uses RSS_CTRL/Q_NUM/RSS indirection/descriptor/status reads when available; even dwords carry low=RX high=TX, adjacent odd dwords are not exposed as queue banks)"; }
            return "Single IntMITI V2 dword value (low[u6:0/f13:8] + high[u22:16/f29:24], mask 0x3F7F3F7F)";
        }
        if (String.Equals(family, "RealtekIntrMit", StringComparison.OrdinalIgnoreCase))
        {
            return "Single IntrMitigate value (Rx[7:0] + Tx[15:8])";
        }

        if (labels == null || labels.Length == 0)
        {
            if (maxQueues > 1) { return "Multiple values (Q0-Q" + (maxQueues - 1).ToString() + ")"; }
            return "Multiple values";
        }
        bool queueOnly = true;
        for (int i = 0; i < labels.Length; i++)
        {
            if (!String.Equals(labels[i], "Q" + i.ToString(), StringComparison.Ordinal)) { queueOnly = false; break; }
        }
        if (queueOnly && labels.Length > 1) { return "Multiple values (Q0-Q" + (labels.Length - 1).ToString() + ")"; }
        if (labels.Length > 8) { return "Multiple values (" + labels[0] + " ... " + labels[labels.Length - 1] + ")"; }
        return "Multiple values (" + String.Join(", ", labels) + ")";
    }

    [DllImport("user32.dll")]
    private static extern IntPtr WindowFromPoint(Point point);

    private static bool IsScreenPointInsideControl(Control control, Point screenPoint)
    {
        if (control == null || control.IsDisposed || !control.IsHandleCreated) { return false; }
        Point clientPoint = control.PointToClient(screenPoint);
        return control.ClientRectangle.Contains(clientPoint);
    }

    internal static bool TryHandleMouseHWheelAtScreenPoint(Point screenPoint, int signedDelta)
    {
        if (signedDelta == 0) { return false; }
        IntPtr hwnd = WindowFromPoint(screenPoint);
        if (hwnd == IntPtr.Zero) { return false; }
        Control control = Control.FromChildHandle(hwnd);
        if (control == null) { control = Control.FromHandle(hwnd); }
        if (control == null) { return false; }
        DeviceEditorNativeHScrollState textState = GetTextBoxHScrollStateFromSender(control);
        if (textState != null && ((textState.TextBox != null && IsScreenPointInsideControl(textState.TextBox.Parent, screenPoint)) || IsScreenPointInsideControl(textState.Track, screenPoint)))
        {
            return TryScrollTextBoxHorizontalWheel(textState, signedDelta);
        }
        DeviceEditorNativeLabelScrollState labelState = GetLabelScrollStateFromSender(control);
        if (labelState != null && (IsScreenPointInsideControl(labelState.Container, screenPoint) || IsScreenPointInsideControl(labelState.Viewport, screenPoint) || IsScreenPointInsideControl(labelState.Track, screenPoint)))
        {
            return TryScrollLabelHorizontalWheel(labelState, signedDelta);
        }
        return false;
    }
}

