    private static Entry NewEntry(string family, string familyName, string vendorId, string[] deviceIds, int baseOffset, int stride, int maxQueues, int readWidth, ulong readMask, ulong writeOrBits, int txOffset, string[] vectorLabels)
    {
        Entry e = new Entry();
        e.Family = family;
        e.FamilyName = familyName;
        e.VendorId = vendorId;
        e.DeviceIds = deviceIds;
        e.BaseOffset = baseOffset;
        e.Stride = stride;
        e.MaxQueues = maxQueues;
        e.ReadWidth = readWidth;
        e.ReadMask = readMask;
        e.WriteORBits = writeOrBits;
        e.TxOffset = txOffset;
        e.TxBaseOffset = 0;
        e.SegmentBreakIndex = 0;
        e.Segment2BaseOffset = 0;
        e.VectorLabels = vectorLabels;
        e.PerIndexMaskMode = String.Equals(family, "RealtekIntrMitV2", StringComparison.OrdinalIgnoreCase) ? "RealtekV2AlternatingIntMitiLow16" : null;
        return e;
    }

    private static Entry NewEntryWithTxBase(string family, string familyName, string vendorId, string[] deviceIds, int baseOffset, int txBaseOffset, int stride, int maxQueues, int readWidth, ulong readMask, ulong writeOrBits, string[] vectorLabels, string registerPair, int itrIndexCount, int hardwareVectorCount, string lowDwordLabel, string highDwordLabel, string queueOwnershipModel, int swItrBaseOffset)
    {
        Entry e = NewEntry(family, familyName, vendorId, deviceIds, baseOffset, stride, maxQueues, readWidth, readMask, writeOrBits, 0, vectorLabels);
        e.TxBaseOffset = txBaseOffset;
        e.RegisterPair = registerPair;
        e.ItrIndexCount = itrIndexCount;
        e.HardwareVectorCount = hardwareVectorCount;
        e.LowDwordLabel = lowDwordLabel;
        e.HighDwordLabel = highDwordLabel;
        e.QueueOwnershipModel = queueOwnershipModel;
        e.SwItrBaseOffset = swItrBaseOffset;
        return e;
    }

    private static Entry NewSegmentedEntry(string family, string familyName, string vendorId, string[] deviceIds, int baseOffset, int segmentBreakIndex, int segment2BaseOffset, int stride, int maxQueues, int readWidth, ulong readMask, ulong writeOrBits, string[] vectorLabels)
    {
        Entry e = NewEntry(family, familyName, vendorId, deviceIds, baseOffset, stride, maxQueues, readWidth, readMask, writeOrBits, 0, vectorLabels);
        e.SegmentBreakIndex = segmentBreakIndex;
        e.Segment2BaseOffset = segment2BaseOffset;
        return e;
    }

    private static Entry NewRealtekV2Entry(string layoutKey, string familyName, string vendorId, string[] deviceIds, int dwordCount, int queueSlots, int verifiedQueueSlots)
    {
        Entry e = NewEntry("RealtekIntrMitV2", familyName, vendorId, deviceIds, 0x0A00, 0x4, dwordCount, 32, 0x3F7F3F7FUL, 0UL, 0, null);
        e.VectorLabelKind = "RealtekIntMitiV2";
        e.RealtekLayoutKey = layoutKey;
        e.VectorLabelCount = dwordCount;
        e.QueueLayoutKey = layoutKey;
        e.QueueSlots = queueSlots;
        e.VerifiedQueueSlots = verifiedQueueSlots;
        return e;
    }

    private static string[] MakeNumberLabels(string prefix, int count)
    {
        string[] labels = new string[Math.Max(0, count)];
        for (int i = 0; i < labels.Length; i++) { labels[i] = prefix + i.ToString(); }
        return labels;
    }

    private static string[] MakeItrPairVectorLabels(string prefix, int count, string lowLabel, string highLabel)
    {
        string[] labels = new string[Math.Max(0, count)];
        for (int i = 0; i < labels.Length; i++) { labels[i] = string.Format("{0}{1} {2}+{3}", prefix, i, lowLabel, highLabel); }
        return labels;
    }

    private static readonly Dictionary<string, string[]> RealtekV2LabelCache = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase);

    private static string[] GetRealtekV2BankLabelsCached(string layoutKey, int count, int verifiedQueueSlots)
    {
        if (count <= 0) { return new string[0]; }
        string key = (String.IsNullOrWhiteSpace(layoutKey) ? "GENERIC" : layoutKey.Trim().ToUpperInvariant()) + "|" + count.ToString() + "|" + verifiedQueueSlots.ToString();
        lock (RealtekV2LabelCache)
        {
            string[] cached;
            if (RealtekV2LabelCache.TryGetValue(key, out cached)) { return cached; }
            string[] labels = MakeRealtekV2BankLabels(count, layoutKey, verifiedQueueSlots);
            RealtekV2LabelCache[key] = labels;
            return labels;
        }
    }

    private static string[] MakeRealtekV2BankLabels(int count)
    {
        return MakeRealtekV2BankLabels(count, "UNKNOWN", 2);
    }

    private static string[] MakeRealtekV2BankLabels(int count, string layoutKey, int verifiedQueueSlots)
    {
        string[] labels = new string[Math.Max(0, count)];
        for (int i = 0; i < labels.Length; i++)
        {
            int offset = 0x0A00 + (i * 4);
            if ((i % 2) == 0)
            {
                int q = i / 2;
                if (q < verifiedQueueSlots)
                {
                    labels[i] = string.Format("RXQ{0}/TXQ{0} verified -> vector pending -> IntMITI{1}@0x{2:X4} low=RX high=TX [{3}; Q0/Q1 exposed-name evidence]", q, i, offset, layoutKey);
                }
                else
                {
                    labels[i] = string.Format("Unverified queue candidate Q{0} -> vector pending -> IntMITI{1}@0x{2:X4} low=RX high=TX [{3}; raw descriptor/RSS/MSI-X evidence only; not auto-labeled]", q, i, offset, layoutKey);
                }
            }
            else
            {
                labels[i] = string.Format("No queue claim -> IntMITI{0}@0x{1:X4} adjacent low16/RX-only candidate mask=0x00003F7F", i, offset);
            }
        }
        return labels;
    }

    private static Entry FindEntry(string vendorId, string deviceId)
    {
        if (String.IsNullOrEmpty(vendorId) || String.IsNullOrEmpty(deviceId)) { return null; }
        for (int i = 0; i < Entries.Length; i++)
        {
            Entry e = Entries[i];
            if (!String.Equals(e.VendorId, vendorId, StringComparison.OrdinalIgnoreCase)) { continue; }
            for (int d = 0; d < e.DeviceIds.Length; d++)
            {
                if (String.Equals(e.DeviceIds[d], deviceId, StringComparison.OrdinalIgnoreCase)) { return e; }
            }
        }
        return null;
    }

    private static Hashtable ToHashtable(Entry e)
    {
        if (e == null) { return null; }
        Hashtable h = new Hashtable();
        h["Family"] = e.Family;
        h["FamilyName"] = e.FamilyName;
        h["VendorId"] = e.VendorId;
        h["DeviceIds"] = e.DeviceIds;
        h["BaseOffset"] = e.BaseOffset;
        h["Stride"] = e.Stride;
        h["MaxQueues"] = e.MaxQueues;
        h["ReadWidth"] = e.ReadWidth;
        h["ReadMask"] = e.ReadMask;
        h["WriteORBits"] = e.WriteORBits;
        if (e.TxOffset > 0) { h["TxOffset"] = e.TxOffset; }
        if (e.TxBaseOffset > 0) { h["TxBaseOffset"] = e.TxBaseOffset; }
        if (e.SegmentBreakIndex > 0) { h["SegmentBreakIndex"] = e.SegmentBreakIndex; }
        if (e.Segment2BaseOffset > 0) { h["Segment2BaseOffset"] = e.Segment2BaseOffset; }
        if (e.VectorLabels != null) { h["VectorLabels"] = e.VectorLabels; }
        else if (!DeviceEditorBuilder.DisableRWEnNVMe && String.Equals(e.VectorLabelKind, "RealtekIntMitiV2", StringComparison.OrdinalIgnoreCase)) { h["VectorLabels"] = GetRealtekV2BankLabelsCached(e.RealtekLayoutKey, e.VectorLabelCount, e.VerifiedQueueSlots); }
        if (!String.IsNullOrEmpty(e.VectorLabelKind)) { h["VectorLabelKind"] = e.VectorLabelKind; }
        if (!String.IsNullOrEmpty(e.RealtekLayoutKey)) { h["RealtekLayoutKey"] = e.RealtekLayoutKey; }
        if (e.VectorLabelCount > 0) { h["VectorLabelCount"] = e.VectorLabelCount; }
        if (!String.IsNullOrEmpty(e.PerIndexMaskMode)) { h["PerIndexMaskMode"] = e.PerIndexMaskMode; }
        if (!String.IsNullOrEmpty(e.QueueLayoutKey)) { h["QueueLayoutKey"] = e.QueueLayoutKey; }
        if (e.QueueSlots > 0) { h["QueueSlots"] = e.QueueSlots; }
        if (e.VerifiedQueueSlots > 0) { h["VerifiedQueueSlots"] = e.VerifiedQueueSlots; }
        if (!String.IsNullOrEmpty(e.RegisterPair)) { h["RegisterPair"] = e.RegisterPair; }
        if (e.ItrIndexCount > 0) { h["ItrIndexCount"] = e.ItrIndexCount; }
        if (e.HardwareVectorCount > 0) { h["HardwareVectorCount"] = e.HardwareVectorCount; }
        if (!String.IsNullOrEmpty(e.LowDwordLabel)) { h["LowDwordLabel"] = e.LowDwordLabel; }
        if (!String.IsNullOrEmpty(e.HighDwordLabel)) { h["HighDwordLabel"] = e.HighDwordLabel; }
        if (!String.IsNullOrEmpty(e.QueueOwnershipModel)) { h["QueueOwnershipModel"] = e.QueueOwnershipModel; }
        if (e.SwItrBaseOffset > 0) { h["SwItrBaseOffset"] = e.SwItrBaseOffset; }
        return h;
    }

    private static Entry FindRealtekByName(string text)
    {
        if (String.IsNullOrEmpty(text) || text.Trim().Length == 0) { return null; }
        string s = text.ToUpperInvariant();
        bool looksRealtek = s.Contains("REALTEK") || s.Contains("RTL") || s.Contains("KILLER");
        if (!looksRealtek) { return null; }
        if (s.Contains("8127") || s.Contains("0E10")) { return FindEntry("10EC", "8127"); }
        if (s.Contains("8126") || s.Contains("5000") || s.Contains("E5000")) { return FindEntry("10EC", "8126"); }
        if (s.Contains("9151")) { return FindEntry("10EC", "9151"); }
        if (s.Contains("8125") || s.Contains("8225") || s.Contains("8162") || s.Contains("3000") || s.Contains("E3000") || s.Contains("8168KB")) { return FindEntry("10EC", "8125"); }
        if (s.Contains("REALTEK") && (s.Contains("10GBE") || s.Contains("10G"))) { return FindEntry("10EC", "8127"); }
        if (s.Contains("REALTEK") && (s.Contains("5GBE") || s.Contains("5G"))) { return FindEntry("10EC", "8126"); }
        if (s.Contains("REALTEK") && (s.Contains("2.5GBE") || s.Contains("2.5G"))) { return FindEntry("10EC", "8125"); }
        if (s.Contains("E2500") || s.Contains("E2600")) { return FindEntry("10EC", "2500"); }
        if (s.Contains("8111") || s.Contains("8168") || s.Contains("8169") || s.Contains("810X") || s.Contains("8101") || s.Contains("8136") || s.Contains("8137") || s.Contains("8129") || s.Contains("8166") || s.Contains("8167")) { return FindEntry("10EC", "8168"); }
        if (s.Contains("REALTEK") && (s.Contains("PCIE GBE") || s.Contains("GBE FAMILY") || s.Contains("GIGABIT"))) { return FindEntry("10EC", "8168"); }
        return null;
    }

    public static Hashtable GetInfo(string pnpId)
    {
        PciIdentityFields id = DeviceTweakerPathHelpers.ParsePciIdentity(pnpId, null);
        if (id == null || !id.Success) { return null; }
        return ToHashtable(FindEntry(id.VendorId, id.DeviceId));
    }

    public static Hashtable GetInfo(string pnpId, string displayName)
    {
        Hashtable h = GetInfo(pnpId);
        if (h != null) { return h; }
        return ToHashtable(FindRealtekByName(displayName));
    }
}

