{
    public static bool DisableRWEnNVMe;
    private static readonly object[] MsiItems = new object[] { "Disabled", "Enabled" };
    private static readonly object[] PriorityItems = new object[] { "Low", "Normal", "High" };
    private static readonly object[] PolicyItems = new object[] {
        "MachineDefault",
        "AllCloseCPU",
        "OneCloseCPU",
        "AllCPUInMach",
        "SpecCPU",
        "SpreadMsgsCPU",
        "AllCPUInMachSt"
    };

    public static DeviceRow[] BuildDeviceRows(object source)
    {
        List<DeviceRow> rows = new List<DeviceRow>();
        foreach (object item in EnumerateSourceObjects(source))
        {
            DeviceRow row = DeviceRow.FromObject(item);
            NormalizeRowForNativeBuild(row);
            rows.Add(row);
        }
        return rows.ToArray();
    }

    public static string BuildCacheKey(DeviceRow row)
    {
        if (row == null) { return "<null-device>"; }
        return String.Join("|", new string[] {
            row.Category ?? String.Empty,
            row.Role ?? String.Empty,
            row.RegistryPath ?? String.Empty,
            row.ConfigPath ?? String.Empty,
            row.DisplayName ?? String.Empty,
            row.UsbHeaderTitle ?? String.Empty
        });
    }

