    public static void WireDeviceButtonHandlers(DeviceUiBuildResult result, EventHandler usbSetHandler, EventHandler usbSaveHandler, EventHandler nicSetHandler, EventHandler nicSaveHandler, EventHandler nvmeRefreshHandler, EventHandler nvmeSetHandler, EventHandler hdaRefreshHandler, EventHandler hdaSetHandler, EventHandler pciAspmRefreshHandler, EventHandler pciAspmSetHandler, EventHandler pciLinkRefreshHandler, EventHandler pciMrrsSetHandler, EventHandler pciL1ssRefreshHandler = null, EventHandler pciL1ssSetHandler = null, EventHandler pciL1ssThresholdSetHandler = null, EventHandler pciLtrObffRefreshHandler = null, EventHandler pciLtrObffSetHandler = null, EventHandler hdaRingSizeSetHandler = null, EventHandler pciMpsSetHandler = null, EventHandler pciDeviceControlSetHandler = null, EventHandler pciAerDpcAcsRefreshHandler = null, EventHandler pciAerDpcAcsSetHandler = null)
    {
        if (result == null) { return; }
        WireButtons(result.UsbSetButtons, usbSetHandler);
        WireButtons(result.UsbSaveButtons, usbSaveHandler);
        WireButtons(result.NicSetButtons, nicSetHandler);
        WireButtons(result.NicSaveButtons, nicSaveHandler);
        WireButtons(result.NvmeRefreshButtons, nvmeRefreshHandler);
        WireButtons(result.NvmeSetButtons, nvmeSetHandler);
        WireButtons(result.HdaRintcntRefreshButtons, hdaRefreshHandler);
        WireButtons(result.HdaRintcntSetButtons, hdaSetHandler);
        WireButtons(result.HdaRingSizeSetButtons, hdaRingSizeSetHandler);
        WireButtons(result.PciAspmRefreshButtons, pciAspmRefreshHandler);
        WireButtons(result.PciAspmSetButtons, pciAspmSetHandler);
        WireButtons(result.PciLinkRefreshButtons, pciLinkRefreshHandler);
        WireButtons(result.PciMrrsSetButtons, pciMrrsSetHandler);
        WireButtons(result.PciMpsSetButtons, pciMpsSetHandler);
        WireButtons(result.PciDeviceControlSetButtons, pciDeviceControlSetHandler);
        WireButtons(result.PciL1ssRefreshButtons, pciL1ssRefreshHandler);
        WireButtons(result.PciL1ssSetButtons, pciL1ssSetHandler);
        WireButtons(result.PciL1ssThresholdSetButtons, pciL1ssThresholdSetHandler);
        WireButtons(result.PciLtrObffRefreshButtons, pciLtrObffRefreshHandler);
        WireButtons(result.PciLtrObffSetButtons, pciLtrObffSetHandler);
        WireButtons(result.PciAerDpcAcsRefreshButtons, pciAerDpcAcsRefreshHandler);
        WireButtons(result.PciAerDpcAcsSetButtons, pciAerDpcAcsSetHandler);
    }

    private static void WireButtons(Button[] buttons, EventHandler handler)
    {
        if (buttons == null || handler == null) { return; }
        for (int i = 0; i < buttons.Length; i++)
        {
            Button b = buttons[i];
            if (b != null) { b.Click += handler; }
        }
    }

    private static void FlattenDeviceEditorIntoMainSurface(DeviceTweakerMainSurface mainSurface, DeviceEditorControl rowSurface, int rowTop)
    {
        if (mainSurface == null || rowSurface == null) { return; }
        int offsetX = rowSurface.Left;
        int offsetY = rowTop;
        rowSurface.MovePaintModelTo(mainSurface, offsetX, offsetY);
        while (rowSurface.Controls.Count > 0)
        {
            Control child = rowSurface.Controls[0];
            rowSurface.Controls.RemoveAt(0);
            child.Left += offsetX;
            child.Top += offsetY;
            mainSurface.Controls.Add(child);
        }
    }

    public static DeviceUiBuildResult BuildAllDeviceCards(DeviceRow[] rows, DeviceEditorTheme theme, DeviceEditorLayoutMetrics metrics, StartupUiStateMap states)
    {
        return BuildAllDeviceCards(rows, theme, metrics, states, null);
    }

    private static DeviceUiBuildResult BuildAllDeviceCards(DeviceRow[] rows, DeviceEditorTheme theme, DeviceEditorLayoutMetrics metrics, StartupUiStateMap states, DeviceTweakerMainSurface targetSurface)
    {
        if (rows == null) { rows = new DeviceRow[0]; }
        if (theme == null) { theme = new DeviceEditorTheme(); }
        if (metrics == null) { metrics = new DeviceEditorLayoutMetrics(); }
        if (states == null) { states = new StartupUiStateMap(); }
        DeviceEditorNativeUiSupport.DisableRWEnNVMe = DisableRWEnNVMe;

        List<Control> controls = new List<Control>(targetSurface == null ? 1 : 0);
        DeviceTweakerMainSurface mainSurface = targetSurface ?? new DeviceTweakerMainSurface();
        mainSurface.SuspendLayout();
        mainSurface.Left = 0;
        mainSurface.Top = 0;
        mainSurface.Width = Math.Max(1, metrics.AffGroupBoxWidth + 30);
        mainSurface.Height = Math.Max(1, metrics.StartTop + 1);
        if (theme.Black != Color.Empty) { mainSurface.BackColor = theme.Black; }
        List<DeviceEditorState> editorStates = new List<DeviceEditorState>(rows.Length);
        List<CpuAffinityGrid> grids = new List<CpuAffinityGrid>(rows.Length);
        List<CheckBox> secretChecks = new List<CheckBox>();
        List<Button> usbSetButtons = new List<Button>();
        List<Button> usbSaveButtons = new List<Button>();
        List<Button> nicSetButtons = new List<Button>();
        List<Button> nicSaveButtons = new List<Button>();
        List<Button> nvmeRefreshButtons = new List<Button>();
        List<Button> nvmeSetButtons = new List<Button>();
        List<Button> hdaRintcntRefreshButtons = new List<Button>();
        List<Button> hdaRintcntSetButtons = new List<Button>();
        List<Button> hdaRingSizeSetButtons = new List<Button>();
        List<Button> pciAspmRefreshButtons = new List<Button>();
        List<Button> pciAspmSetButtons = new List<Button>();
        List<Button> pciLinkRefreshButtons = new List<Button>();
        List<Button> pciMrrsSetButtons = new List<Button>();
        List<Button> pciMpsSetButtons = new List<Button>();
        List<Button> pciDeviceControlSetButtons = new List<Button>();
        List<Button> pciL1ssRefreshButtons = new List<Button>();
        List<Button> pciL1ssSetButtons = new List<Button>();
        List<Button> pciL1ssThresholdSetButtons = new List<Button>();
        List<Button> pciLtrObffRefreshButtons = new List<Button>();
        List<Button> pciLtrObffSetButtons = new List<Button>();
        List<Button> pciAerDpcAcsRefreshButtons = new List<Button>();
        List<Button> pciAerDpcAcsSetButtons = new List<Button>();
        Hashtable deviceControls = new Hashtable();

        int top = metrics.StartTop;
        int spacing = metrics.DeviceBoxSpacing > 0 ? metrics.DeviceBoxSpacing : 10;
        for (int i = 0; i < rows.Length; i++)
        {
            DeviceRow row = rows[i];
            if (row == null) { continue; }
            NormalizeRowForNativeBuild(row);
            DeviceEditorStartupState state = states.GetForRow(row);
            if (state == null) { state = new DeviceEditorStartupState(); }
            state.DeviceKey = BuildCacheKey(row);
            if (String.IsNullOrWhiteSpace(state.InitialAffinity)) { state.InitialAffinity = "0x0"; }

            DeviceEditorBuildResult build = BuildDeviceEditor(row, theme, state, metrics);
            DeviceEditorControl groupBox = build.GroupBox as DeviceEditorControl;
            if (groupBox == null || build.State == null) { continue; }
            groupBox.Top = top;
            build.State.Device = row.Source ?? (object)row;
            build.State.GroupBox = groupBox;

            Hashtable map = DeviceEditorNativeUiSupport.CreateControlMap(row, build.State);
            if (!DisableRWEnNVMe)
            {
                if (EqualsIgnoreCase(row.Category, "USB"))
                {
                    DeviceEditorNativeUiSupport.AddUsbImodControls(row, build.State, theme, map, secretChecks, usbSetButtons, usbSaveButtons);
                }
                else if (EqualsIgnoreCase(row.Category, "Network"))
                {
                    DeviceEditorNativeUiSupport.AddNicImodOrUnsupportedControls(row, build.State, theme, map, nicSetButtons, nicSaveButtons);
                }
                else if (row.IsStorage || EqualsIgnoreCase(row.Role, "Storage"))
                {
                    DeviceEditorNativeUiSupport.AddNvmeInterruptCoalescingControls(row, build.State, theme, map, nvmeRefreshButtons, nvmeSetButtons);
                }
                if (EqualsIgnoreCase(row.Category, "PCI") && (EqualsIgnoreCase(row.Role, "Audio") || EqualsIgnoreCase(row.Role, "AudioGPU")))
                {
                    DeviceEditorNativeUiSupport.AddHdaRintcntControls(row, build.State, theme, map, hdaRintcntRefreshButtons, hdaRintcntSetButtons, hdaRingSizeSetButtons);
                }
                if (EqualsIgnoreCase(row.Category, "PCI"))
                {
                    DeviceEditorNativeUiSupport.AddPciAspmControls(row, build.State, theme, map, pciAspmRefreshButtons, pciAspmSetButtons, pciLinkRefreshButtons, pciMrrsSetButtons, pciMpsSetButtons, pciDeviceControlSetButtons, pciL1ssRefreshButtons, pciL1ssSetButtons, pciL1ssThresholdSetButtons, pciLtrObffRefreshButtons, pciLtrObffSetButtons, pciAerDpcAcsRefreshButtons, pciAerDpcAcsSetButtons);
                }
                DeviceEditorNativeUiSupport.FinalizeExtensionButtonLayout(groupBox, map);
            }
            DeviceEditorNativeUiSupport.ReflowMsiPanelToRight(build.State, 5);

            ApplySmtOverlays(build.State.Grid, metrics, theme);
            DeviceTweakerUiHandlers.WireDeviceEditorState(build.State);
            if (build.State.Grid != null)
            {
                try { build.State.Grid.ResumeLayout(false); } catch { }
                grids.Add(build.State.Grid);
            }
            if (build.State.AffinityPanel != null) { try { build.State.AffinityPanel.ResumeLayout(false); } catch { } }
            if (build.State.MsiPanel != null) { try { build.State.MsiPanel.ResumeLayout(false); } catch { } }

            int maxBottom = 0;
            foreach (Control child in groupBox.Controls)
            {
                int bottom = child.Top + child.Height;
                if (bottom > maxBottom) { maxBottom = bottom; }
            }
            maxBottom = Math.Max(maxBottom, groupBox.VirtualContentBottom);
            bool hasPciAspmPanel = map.ContainsKey("PciAspmPanel");
            bool hasHdaPanel = map.ContainsKey("HDAPanel");
            int bottomPad = (EqualsIgnoreCase(row.Category, "USB") || EqualsIgnoreCase(row.Category, "Network") || row.IsStorage || EqualsIgnoreCase(row.Role, "Storage") || hasPciAspmPanel || hasHdaPanel) ? 5 : 10;
            groupBox.Height = maxBottom + bottomPad;
            mainSurface.Width = Math.Max(mainSurface.Width, groupBox.Left + groupBox.Width + 20);
            groupBox.ResumeLayout(false);

            object key = row.Source ?? (object)row;
            if (!deviceControls.ContainsKey(key)) { deviceControls.Add(key, map); }
            FlattenDeviceEditorIntoMainSurface(mainSurface, groupBox, top);
            editorStates.Add(build.State);
            top += groupBox.Height + spacing;
        }

        mainSurface.Height = Math.Max(1, top);
        mainSurface.ResumeLayout(false);
        if (targetSurface == null) { controls.Add(mainSurface); }

        CheckBox[] secretArray = secretChecks.ToArray();
        DeviceEditorNativeUiSupport.WireSecretSaveCheckboxes(secretArray);

        DeviceUiBuildResult result = new DeviceUiBuildResult();
        result.Controls = controls.ToArray();
        result.States = editorStates.ToArray();
        result.DeviceControls = deviceControls;
        result.CpuAffinityGrids = grids.ToArray();
        result.SecretSaveCheckboxes = secretArray;
        result.UsbSetButtons = usbSetButtons.ToArray();
        result.UsbSaveButtons = usbSaveButtons.ToArray();
        result.NicSetButtons = nicSetButtons.ToArray();
        result.NicSaveButtons = nicSaveButtons.ToArray();
        result.NvmeRefreshButtons = nvmeRefreshButtons.ToArray();
        result.NvmeSetButtons = nvmeSetButtons.ToArray();
        result.HdaRintcntRefreshButtons = hdaRintcntRefreshButtons.ToArray();
        result.HdaRintcntSetButtons = hdaRintcntSetButtons.ToArray();
        result.HdaRingSizeSetButtons = hdaRingSizeSetButtons.ToArray();
        result.PciAspmRefreshButtons = pciAspmRefreshButtons.ToArray();
        result.PciAspmSetButtons = pciAspmSetButtons.ToArray();
        result.PciLinkRefreshButtons = pciLinkRefreshButtons.ToArray();
        result.PciMrrsSetButtons = pciMrrsSetButtons.ToArray();
        result.PciMpsSetButtons = pciMpsSetButtons.ToArray();
        result.PciDeviceControlSetButtons = pciDeviceControlSetButtons.ToArray();
        result.PciL1ssRefreshButtons = pciL1ssRefreshButtons.ToArray();
        result.PciL1ssSetButtons = pciL1ssSetButtons.ToArray();
        result.PciL1ssThresholdSetButtons = pciL1ssThresholdSetButtons.ToArray();
        result.PciLtrObffRefreshButtons = pciLtrObffRefreshButtons.ToArray();
        result.PciLtrObffSetButtons = pciLtrObffSetButtons.ToArray();
        result.PciAerDpcAcsRefreshButtons = pciAerDpcAcsRefreshButtons.ToArray();
        result.PciAerDpcAcsSetButtons = pciAerDpcAcsSetButtons.ToArray();
        result.FinalTop = top;
        return result;
    }

    public static DeviceTweakerStartupUiBuildResult BuildStartupUi(DeviceTweakerStartupPayload payload, DeviceEditorTheme theme, DeviceEditorLayoutMetrics metrics, StartupUiOptions options)
    {
        return BuildStartupUiCore(payload, theme, metrics, options);
    }

    public static DeviceTweakerStartupUiBuildResult BuildStartupUi(DeviceTweakerStartupModel payload, DeviceEditorTheme theme, DeviceEditorLayoutMetrics metrics, StartupUiOptions options)
    {
        return BuildStartupUiCore(payload, theme, metrics, options);
    }

    private static DeviceTweakerStartupUiBuildResult BuildStartupUiCore(DeviceTweakerStartupModel payload, DeviceEditorTheme theme, DeviceEditorLayoutMetrics metrics, StartupUiOptions options)
    {
        Stopwatch sw = Stopwatch.StartNew();
        if (theme == null) { theme = new DeviceEditorTheme(); }
        if (metrics == null) { metrics = new DeviceEditorLayoutMetrics(); }
        if (options == null) { options = new StartupUiOptions(); }

        DeviceTweakerStartupUiBuildResult result = new DeviceTweakerStartupUiBuildResult();
        Form form = options.ExistingForm;
        Panel outerPanel = options.ExistingPanel;
        if (form == null || outerPanel == null)
        {
            DeviceTweakerMainShellNative shell = DeviceTweakerFormFactory.CreateMainShell(Math.Max(1, options.FormWidth), theme.Font11, theme.Black == Color.Empty ? Color.Black : theme.Black);
            form = shell.Form;
            outerPanel = shell.Panel;
            if (options.FormHeight > 0) { form.Height = options.FormHeight; }
        }
        result.Form = form;
        result.Panel = outerPanel;

        int scrollW = Math.Max(0, options.ScrollTrackWidth);
        int padBottom = Math.Max(0, options.ScrollPaddingBottom);
        int finalTop = Math.Max(0, options.DeviceStartTop);
        Control parentForContent = outerPanel;
        Control inner = null;
        DeviceTweakerMainSurface nativeContentSurface = null;
        Panel track = null;
        Panel thumb = null;

        bool formRedrawSuspended = ScrollHelper.BeginConstructionRedraw(form);
        bool panelRedrawSuspended = ScrollHelper.BeginConstructionRedraw(outerPanel);
        try { form.SuspendLayout(); } catch { }
        try { outerPanel.SuspendLayout(); } catch { }
        try { if (options.EnableDoubleBuffer) { ScrollHelper.EnableDoubleBuffer(form); ScrollHelper.EnableDoubleBuffer(outerPanel); } } catch { }

        try
        {
            if (options.BuildScrollContainer)
            {
                nativeContentSurface = new DeviceTweakerMainSurface();
                inner = nativeContentSurface;
                nativeContentSurface.SuspendLayout();
                inner.Left = 0;
                inner.Top = 0;
                inner.BackColor = theme.Black == Color.Empty ? Color.Black : theme.Black;
                inner.Font = outerPanel.Font;
                inner.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
                try { if (options.EnableDoubleBuffer) { ScrollHelper.EnableDoubleBuffer(inner); } } catch { }

                if (options.PreserveExistingControls && outerPanel.Controls.Count > 0)
                {
                    while (outerPanel.Controls.Count > 0)
                    {
                        Control child = outerPanel.Controls[0];
                        outerPanel.Controls.RemoveAt(0);
                        inner.Controls.Add(child);
                    }
                }
                parentForContent = inner;
            }

            metrics.StartTop = options.DeviceStartTop > 0 ? options.DeviceStartTop : metrics.StartTop;
            metrics.DeviceBoxSpacing = options.DeviceBoxSpacing > 0 ? options.DeviceBoxSpacing : metrics.DeviceBoxSpacing;

            object deviceSource = options.Devices;
            if (deviceSource == null && payload != null) { deviceSource = payload.AllDeviceRows; }
            DeviceRow[] rows = BuildDeviceRows(deviceSource);
            object stateSource = options.UiStateSource;
            if (stateSource == null && payload != null) { stateSource = payload.UiStateByDeviceKey; }
            StartupUiStateMap states = StartupUiStateMap.FromObject(stateSource);

            DeviceUiBuildResult deviceBuild = BuildAllDeviceCards(rows, theme, metrics, states, nativeContentSurface);
            result.DeviceUi = deviceBuild;
            if (deviceBuild != null && deviceBuild.Controls != null && deviceBuild.Controls.Length > 0)
            {
                parentForContent.Controls.AddRange(deviceBuild.Controls);
            }
            if (deviceBuild != null)
            {
                result.DeviceControls = deviceBuild.DeviceControls;
                result.CpuAffinityGrids = deviceBuild.CpuAffinityGrids;
                result.SecretSaveCheckboxes = deviceBuild.SecretSaveCheckboxes;
                result.UsbSetButtons = deviceBuild.UsbSetButtons;
                result.UsbSaveButtons = deviceBuild.UsbSaveButtons;
                result.NicSetButtons = deviceBuild.NicSetButtons;
                result.NicSaveButtons = deviceBuild.NicSaveButtons;
                result.NvmeRefreshButtons = deviceBuild.NvmeRefreshButtons;
                result.NvmeSetButtons = deviceBuild.NvmeSetButtons;
                result.HdaRintcntRefreshButtons = deviceBuild.HdaRintcntRefreshButtons;
                result.HdaRintcntSetButtons = deviceBuild.HdaRintcntSetButtons;
                result.HdaRingSizeSetButtons = deviceBuild.HdaRingSizeSetButtons;
                result.PciAspmRefreshButtons = deviceBuild.PciAspmRefreshButtons;
                result.PciAspmSetButtons = deviceBuild.PciAspmSetButtons;
                result.PciLinkRefreshButtons = deviceBuild.PciLinkRefreshButtons;
                result.PciMrrsSetButtons = deviceBuild.PciMrrsSetButtons;
                result.PciMpsSetButtons = deviceBuild.PciMpsSetButtons;
                result.PciDeviceControlSetButtons = deviceBuild.PciDeviceControlSetButtons;
                result.PciL1ssRefreshButtons = deviceBuild.PciL1ssRefreshButtons;
                result.PciL1ssSetButtons = deviceBuild.PciL1ssSetButtons;
                result.PciL1ssThresholdSetButtons = deviceBuild.PciL1ssThresholdSetButtons;
                result.PciLtrObffRefreshButtons = deviceBuild.PciLtrObffRefreshButtons;
                result.PciLtrObffSetButtons = deviceBuild.PciLtrObffSetButtons;
                result.PciAerDpcAcsRefreshButtons = deviceBuild.PciAerDpcAcsRefreshButtons;
                result.PciAerDpcAcsSetButtons = deviceBuild.PciAerDpcAcsSetButtons;
                finalTop = Math.Max(finalTop, deviceBuild.FinalTop);
            }

            if (options.IncludeReservedCpuSets)
            {
                ReservedCpuSetsInitialState reservedState = new ReservedCpuSetsInitialState();
                reservedState.Metrics = metrics;
                reservedState.StartupModel = payload;
                reservedState.IsHeteroCpu = options.IsHeteroCpu;
                reservedState.IsDualCcdCpu = options.IsDualCcdCpu;
                ReservedCpuSetsBuildResult reserved = BuildReservedCpuSetsSection(
                    finalTop,
                    Math.Max(0, metrics.LogicalCount),
                    Math.Max(1, metrics.AffGroupBoxWidth),
                    Math.Max(1, metrics.AffPanelWidth),
                    theme,
                    reservedState);
                result.ReservedCpuSets = reserved;
                if (reserved != null && reserved.Root != null)
                {
                    parentForContent.Controls.Add(reserved.Root);
                    finalTop = Math.Max(finalTop, reserved.FinalBottom);
                }
            }

            int contentHeight = finalTop + padBottom;
            for (int i = 0; i < parentForContent.Controls.Count; i++)
            {
                Control c = parentForContent.Controls[i];
                if (c == null) { continue; }
                int bottom = c.Top + c.Height + padBottom;
                if (bottom > contentHeight) { contentHeight = bottom; }
            }
            result.ScrollContentHeight = Math.Max(1, contentHeight);

            if (options.BuildScrollContainer && inner != null)
            {
                int panelW = Math.Max(1, outerPanel.ClientSize.Width);
                int panelH = Math.Max(1, outerPanel.ClientSize.Height);
                inner.Width = Math.Max(1, panelW - scrollW);
                inner.Height = result.ScrollContentHeight;

                track = new Panel();
                track.BackColor = theme.Black == Color.Empty ? Color.Black : theme.Black;
                track.Width = scrollW;
                track.Left = Math.Max(0, panelW - scrollW);
                track.Top = 0;
                track.Height = panelH;
                track.Anchor = AnchorStyles.Top | AnchorStyles.Bottom | AnchorStyles.Right;

                thumb = new Panel();
                thumb.BackColor = Color.FromArgb(32, 32, 32);
                thumb.Width = scrollW;
                thumb.Left = 0;
                thumb.Top = 0;
                thumb.Cursor = Cursors.Arrow;
                thumb.Anchor = AnchorStyles.Left | AnchorStyles.Top | AnchorStyles.Right;
                track.Controls.Add(thumb);

                try { if (nativeContentSurface != null) { nativeContentSurface.ResumeLayout(false); } else { inner.ResumeLayout(false); } } catch { }
                outerPanel.Controls.Add(inner);
                outerPanel.Controls.Add(track);
                track.BringToFront();
                result.ScrollInnerPanel = inner;
                result.ScrollTrack = track;
                result.ScrollThumb = thumb;
                result.ScrollState = DeviceEditorNativeScrollState.Attach(form, outerPanel, inner, track, thumb, result.ScrollContentHeight, scrollW);
                try { if (options.EnableDoubleBuffer) { ScrollHelper.EnableDoubleBufferRecursive(inner); ScrollHelper.EnableDoubleBufferRecursive(track); } } catch { }
            }
        }
        finally
        {
            Exception redrawFailure = null;
            try { if (nativeContentSurface != null) { nativeContentSurface.ResumeLayout(false); } else if (inner != null) { inner.ResumeLayout(false); } } catch { }
            try { outerPanel.ResumeLayout(false); } catch { }
            try { form.ResumeLayout(false); } catch { }
            try { ScrollHelper.EndConstructionRedraw(outerPanel, panelRedrawSuspended); } catch (Exception ex) { redrawFailure = ex; }
            try { ScrollHelper.EndConstructionRedraw(form, formRedrawSuspended); } catch (Exception ex) { redrawFailure = redrawFailure == null ? ex : new AggregateException(redrawFailure, ex); }
            if (redrawFailure != null) { throw redrawFailure; }
        }

        result.FinalTop = finalTop;
        sw.Stop();
        result.BuildMilliseconds = sw.Elapsed.TotalMilliseconds;
        return result;
    }

    private static IEnumerable<object> EnumerateSourceObjects(object source)
    {
        if (source == null) { yield break; }
        string stringSource = source as string;
        if (stringSource != null) { yield return source; yield break; }
        IEnumerable enumerable = source as IEnumerable;
        if (enumerable == null) { yield return source; yield break; }
        foreach (object item in enumerable) { if (item != null) { yield return item; } }
    }

    private static void NormalizeRowForNativeBuild(DeviceRow row)
    {
        if (row == null) { return; }
        row.HasUsbHeaderTitle = EqualsIgnoreCase(row.Category, "USB") && !String.IsNullOrEmpty(row.UsbHeaderTitle);
        row.HasConfigPath = EqualsIgnoreCase(row.Category, "Network") && !String.IsNullOrEmpty(row.ConfigPath);
        row.IsStorage = EqualsIgnoreCase(row.Role, "Storage") || EqualsIgnoreCase(row.Category, "SSD") || EqualsIgnoreCase(row.Category, "HDD");
        if (!row.IsHdaController)
        {
            string hdaText = (row.ClassCode ?? String.Empty) + " " + (row.PNPID ?? String.Empty) + " " + (row.DisplayName ?? String.Empty) + " " + (row.RegistryPath ?? String.Empty);
            row.IsHdaController = hdaText.IndexOf("0403", StringComparison.OrdinalIgnoreCase) >= 0 || hdaText.IndexOf("High Definition Audio", StringComparison.OrdinalIgnoreCase) >= 0 || hdaText.IndexOf("HDAUDIO", StringComparison.OrdinalIgnoreCase) >= 0 || hdaText.IndexOf("CC_0403", StringComparison.OrdinalIgnoreCase) >= 0;
        }
        row.RegistryPathDisplay = FormatRegistryPathForDisplay(row.RegistryPath);
        if (row.HasConfigPath) { row.ConfigPathDisplay = FormatRegistryPathForDisplay(row.ConfigPath); }
        else { row.ConfigPathDisplay = row.ConfigPath ?? String.Empty; }
    }

    private static string FormatRegistryPathForDisplay(string registryPath)
    {
        if (String.IsNullOrWhiteSpace(registryPath)) { return "(N/A)"; }
        string text = DecodeRegistryDisplayEscapes(registryPath.Trim().Trim('"'));
        text = NormalizeRegistryDisplaySeparators(text);
        text = StripRegistryProviderPrefix(text);
        text = CanonicalHive(text, "HKLM", "HKEY_LOCAL_MACHINE");
        text = CanonicalHive(text, "HKCU", "HKEY_CURRENT_USER");
        text = CanonicalHive(text, "HKCR", "HKEY_CLASSES_ROOT");
        text = CanonicalHive(text, "HKU", "HKEY_USERS");
        text = CanonicalHive(text, "HKCC", "HKEY_CURRENT_CONFIG");
        return String.IsNullOrWhiteSpace(text) ? "(N/A)" : text;
    }

    private static string DecodeRegistryDisplayEscapes(string text)
    {
        if (String.IsNullOrEmpty(text)) { return text; }
        StringBuilder sb = null;
        for (int i = 0; i < text.Length; i++)
        {
            char replacement = '\0';
            if (text[i] == '\\' && i + 5 < text.Length && (text[i + 1] == 'u' || text[i + 1] == 'U'))
            {
                string code = text.Substring(i + 2, 4);
                if (String.Equals(code, "005c", StringComparison.OrdinalIgnoreCase)) { replacement = '\\'; }
                else if (String.Equals(code, "0026", StringComparison.OrdinalIgnoreCase)) { replacement = '&'; }
                else if (String.Equals(code, "003c", StringComparison.OrdinalIgnoreCase)) { replacement = '<'; }
                else if (String.Equals(code, "003e", StringComparison.OrdinalIgnoreCase)) { replacement = '>'; }
                else if (String.Equals(code, "0027", StringComparison.OrdinalIgnoreCase)) { replacement = '\''; }
            }

            if (replacement != '\0')
            {
                if (sb == null) { sb = new StringBuilder(text.Length); sb.Append(text, 0, i); }
                sb.Append(replacement);
                i += 5;
            }
            else if (sb != null) { sb.Append(text[i]); }
        }
        return sb == null ? text : sb.ToString();
    }

    private static string NormalizeRegistryDisplaySeparators(string text)
    {
        if (String.IsNullOrEmpty(text)) { return text; }
        StringBuilder sb = null;
        bool previousSlash = false;
        for (int i = 0; i < text.Length; i++)
        {
            char c = text[i] == '/' ? '\\' : text[i];
            if (c == '\\')
            {
                if (previousSlash)
                {
                    if (sb == null) { sb = new StringBuilder(text.Length); sb.Append(text, 0, i); }
                    continue;
                }
                previousSlash = true;
            }
            else { previousSlash = false; }
            if (sb != null) { sb.Append(c); }
        }
        return sb == null ? text : sb.ToString();
    }

    private static string StripRegistryProviderPrefix(string text)
    {
        if (String.IsNullOrEmpty(text)) { return text; }
        const string psRegistry = @"Microsoft.PowerShell.Core\Registry::";
        const string registry = @"Registry::";
        if (text.StartsWith(psRegistry, StringComparison.OrdinalIgnoreCase)) { return text.Substring(psRegistry.Length); }
        if (text.StartsWith(registry, StringComparison.OrdinalIgnoreCase)) { return text.Substring(registry.Length); }
        return text;
    }

    private static bool HiveRootEquals(string root, string canonical)
    {
        if (String.Equals(root, canonical, StringComparison.OrdinalIgnoreCase)) { return true; }
        return String.Equals(root.Replace("_", String.Empty), canonical.Replace("_", String.Empty), StringComparison.OrdinalIgnoreCase);
    }

    private static string CanonicalHive(string text, string drive, string canonical)
    {
        if (String.IsNullOrEmpty(text)) { return text; }
        int slash = text.IndexOf('\\');
        string root = slash >= 0 ? text.Substring(0, slash) : text;
        string tail = slash >= 0 ? text.Substring(slash + 1).TrimStart('\\') : String.Empty;
        bool matched = String.Equals(root, drive, StringComparison.OrdinalIgnoreCase)
            || String.Equals(root, drive + ":", StringComparison.OrdinalIgnoreCase)
            || HiveRootEquals(root, canonical);
        if (!matched) { return text; }
        if (tail.Length == 0) { return slash >= 0 ? canonical + "\\" : canonical; }
        return canonical + "\\" + tail;
    }

    private static void ApplySmtOverlays(CpuAffinityGrid grid, DeviceEditorLayoutMetrics metrics, DeviceEditorTheme theme)
    {
        if (grid == null || metrics == null || !metrics.HtEnabled || metrics.SmtLogicalSets == null || metrics.SmtLogicalSets.Length == 0) { return; }
        List<Rectangle> rects = new List<Rectangle>();
        List<string> labels = new List<string>();
        List<Point> points = new List<Point>();
        CpuAffinityGridCell[] cells = grid.Cells ?? new CpuAffinityGridCell[0];
        CpuAffinityGridAnnotation[] annotations = grid.AnnotationCells ?? new CpuAffinityGridAnnotation[0];
        int smtPad = metrics.SmtOverlayPad > 0 ? metrics.SmtOverlayPad : 1;
        int labelGap = metrics.SmtLabelGap > 0 ? metrics.SmtLabelGap : 3;
        int fixedTotalWidth = metrics.SmtOverlayTotalWidth;
        int contentWidth = metrics.SmtOverlayContentWidth;
        Font overlayFont = theme != null && theme.Font7_5 != null ? theme.Font7_5 : grid.Font;
        int setIndex = 0;
        for (int s = 0; s < metrics.SmtLogicalSets.Length; s++)
        {
            int[] members = metrics.SmtLogicalSets[s];
            if (members == null || members.Length < 2) { continue; }
            bool allPresent = true;
            int minChkX = Int32.MaxValue;
            int minChkY = Int32.MaxValue;
            int maxChkB = Int32.MinValue;
            int maxContentR = Int32.MinValue;
            for (int i = 0; i < members.Length; i++)
            {
                int idx = members[i];
                if (idx < 0 || idx >= cells.Length || cells[idx] == null) { allPresent = false; break; }
                CpuAffinityGridCell c = cells[idx];
                if (c.Left < minChkX) { minChkX = c.Left; }
                if (c.Top < minChkY) { minChkY = c.Top; }
                if (c.Bottom > maxChkB) { maxChkB = c.Bottom; }
                int contentRight = c.Right;
                if (metrics.CppcEnabled && idx < annotations.Length && annotations[idx] != null)
                {
                    int annRight = annotations[idx].Right;
                    if (annRight > contentRight) { contentRight = annRight; }
                }
                if (contentRight > maxContentR) { maxContentR = contentRight; }
            }
            if (!allPresent) { continue; }
            string label = "#" + setIndex.ToString();
            Size lblSize = TextRenderer.MeasureText(label, overlayFont);
            int contentRightFinal = contentWidth > 0 ? minChkX + contentWidth : maxContentR;
            int rectTop = minChkY - smtPad;
            int totalHeight = (maxChkB - minChkY) + (smtPad * 2);
            int totalWidth = fixedTotalWidth > 0 ? fixedTotalWidth : (contentRightFinal - minChkX) + (smtPad * 2) + labelGap + lblSize.Width;
            rects.Add(new Rectangle(minChkX - smtPad, rectTop, totalWidth, totalHeight));
            labels.Add(label);
            points.Add(new Point(contentRightFinal + labelGap, rectTop + ((totalHeight - lblSize.Height) / 2)));
            setIndex++;
        }
        if (rects.Count > 0)
        {
            grid.OverlayFont = overlayFont;
            grid.SetSmtOverlays(rects.ToArray(), labels.ToArray(), points.ToArray());
        }
    }

    public static ReservedCpuSetsBuildResult BuildReservedCpuSetsSection(int top, int logicalCount, int groupWidth, int panelWidth, DeviceEditorTheme theme, ReservedCpuSetsInitialState state)
    {
        if (theme == null) { theme = new DeviceEditorTheme(); }
        if (state == null) { state = new ReservedCpuSetsInitialState(); }
        DeviceEditorLayoutMetrics metrics = state.Metrics ?? new DeviceEditorLayoutMetrics();

        int logical = logicalCount < 0 ? 0 : logicalCount;
        int groupW = Math.Max(1, groupWidth);
        int panelW = Math.Max(1, panelWidth);
        int maxRows = Math.Max(1, metrics.MaxCoresPerColumn);
        int columnW = Math.Max(1, metrics.ColumnWidth);
        int rowH = Math.Max(1, metrics.RowHeight);
        int topPad = Math.Max(0, metrics.TopPad);
        int neededColumns = Math.Max(1, (int)Math.Ceiling((double)Math.Max(1, logical) / (double)maxRows));

        ReservedCpuSetsSurface root = new ReservedCpuSetsSurface();
        root.SuspendLayout();
        root.Text = "ReservedCpuSets";
        root.Left = 10;
        root.Top = top;
        root.Width = groupW;
        root.Height = 300;
        if (theme.LightGray != Color.Empty) { root.ForeColor = theme.LightGray; }
        if (theme.Black != Color.Empty) { root.BackColor = theme.Black; }
        if (theme.Font11 != null) { root.Font = theme.Font11; }

        Panel reservedPanel = new Panel();
        reservedPanel.SuspendLayout();
        reservedPanel.Left = 10;
        reservedPanel.Top = 20;
        reservedPanel.Width = panelW;
        reservedPanel.Height = topPad + ((maxRows - 1) * rowH) + Math.Max(20, rowH - 6) + topPad + 2;
        reservedPanel.AutoScroll = false;
        reservedPanel.BorderStyle = BorderStyle.FixedSingle;
        if (theme.Black != Color.Empty) { reservedPanel.BackColor = theme.Black; }
        root.SetPanelBounds(reservedPanel.Left, reservedPanel.Top, reservedPanel.Width, reservedPanel.Height);

        CpuAffinityGrid grid = new CpuAffinityGrid();
        grid.SuspendLayout();
        grid.LogicalCount = logical;
        grid.CpuTexts = metrics.CpuTexts;
        grid.IsPCore = metrics.IsPCore;
        grid.CheckboxWidths = metrics.CheckboxWidths;
        grid.Annotations = metrics.Annotations;
        grid.CppcLabelOffsets = metrics.CppcLabelOffsets;
        grid.CppcEnabled = metrics.CppcEnabled;
        grid.CppcLabelWidth = Math.Max(1, metrics.CppcLabelWidth);
        if (theme.Font9 != null) { grid.Font = theme.Font9; }
        if (theme.Font7_5 != null)
        {
            grid.AnnotationFont = theme.Font7_5;
            grid.OverlayFont = theme.Font7_5;
        }
        if (theme.LightGray != Color.Empty) { grid.PCoreColor = theme.LightGray; }
        if (theme.ECoreBlue != Color.Empty) { grid.ECoreColor = theme.ECoreBlue; }
        if (theme.Orange != Color.Empty) { grid.OrangeColor = theme.Orange; }
        if (theme.Black != Color.Empty) { grid.BackColor = theme.Black; }
        grid.TextVerticalOffset = metrics.CpuTextVerticalOffset;
        grid.SetLayoutMetrics(maxRows, neededColumns, columnW, rowH, topPad);
        int gridW = Math.Max(Math.Max(1, reservedPanel.ClientSize.Width), 2 + (neededColumns * columnW));
        int gridH = Math.Max(1, reservedPanel.ClientSize.Height);
        grid.SetBounds(0, 0, gridW, gridH);

        bool[] initialReserved = state.InitialReserved;
        if (initialReserved == null)
        {
            try { initialReserved = ReservedCpuSetsUiNative.GetReservedCoresLocal(logical, state.StartupModel); }
            catch { initialReserved = new bool[Math.Max(0, logical)]; }
        }
        grid.SetCheckedFromBoolArray(initialReserved);
        ApplySmtOverlays(grid, metrics, theme);

        reservedPanel.Controls.Add(grid);
        grid.ResumeLayout(false);
        reservedPanel.ResumeLayout(false);
        root.Controls.Add(reservedPanel);

        List<RetainedButtonElement> buttons = new List<RetainedButtonElement>(5);
        Font buttonFont = theme.Font11 ?? root.Font;
        Color black = theme.Black == Color.Empty ? Color.Black : theme.Black;
        Color white = theme.White == Color.Empty ? Color.White : theme.White;
        Color orange = theme.Orange == Color.Empty ? Color.FromArgb(255, 100, 45) : theme.Orange;
        Color hover = theme.LightGray == Color.Empty ? Color.FromArgb(234, 234, 234) : theme.LightGray;

        Font regNormalFont = DeviceTweakerUiHandlers.RegistryPathNormalFont ?? (theme.Font9 ?? root.Font);
        Font regHoverFont = DeviceTweakerUiHandlers.RegistryPathHoverFont ?? regNormalFont;
        Color regNormalColor = DeviceTweakerUiHandlers.RegistryPathNormalColor;
        Color regHoverColor = DeviceTweakerUiHandlers.RegistryPathHoverColor;
        Color regTitleColor = theme.DimGray == Color.Empty ? Color.FromArgb(150, 150, 150) : theme.DimGray;
        string regKeyPath = DeviceTweakerRegistrySnapshot.ReservedCpuSetsRegistryPath;
        string regPathDisplay = FormatRegistryPathForDisplay(regKeyPath);
        RetainedRegistryPathElement regPathLink = root.CreateRegistryPathLink("Registry Path:", regPathDisplay, regKeyPath, 10, reservedPanel.Bottom + 8, panelW, 40, regNormalFont, regHoverFont, regTitleColor, regNormalColor, regHoverColor, black);
        root.Width = Math.Max(root.Width, regPathLink.Right + 10);
        regPathLink.DoubleClick += delegate(object sender, EventArgs e) { DeviceTweakerUiHandlers.OpenRegistryPath(regKeyPath); };

        RetainedButtonElement btnSet = root.CreateButton("SET RESERVED CORES", 10, regPathLink.Bottom + 8, panelW, 40, buttonFont, black, white, orange, hover);
        btnSet.Cursor = Cursors.Default;
        buttons.Add(btnSet);

        int nextTop = btnSet.Bottom + 4;
        int halfWidth = Math.Max(1, (int)Math.Floor((panelW - 6) / 2.0));
        if (state.IsHeteroCpu)
        {
            RetainedButtonElement btnE = root.CreateButton("RESERVE E-CORES", 10, nextTop, halfWidth, 40, buttonFont, black, white, orange, hover);
            RetainedButtonElement btnP = root.CreateButton("RESERVE P-CORES", btnE.Right + 6, nextTop, halfWidth, 40, buttonFont, black, white, orange, hover);
            buttons.Add(btnE);
            buttons.Add(btnP);
            nextTop = btnE.Bottom + 4;
        }

        if (state.IsDualCcdCpu)
        {
            RetainedButtonElement btnCcd0 = root.CreateButton("RESERVE CCD0", 10, nextTop, halfWidth, 40, buttonFont, black, white, orange, hover);
            RetainedButtonElement btnCcd1 = root.CreateButton("RESERVE CCD1", btnCcd0.Right + 6, nextTop, halfWidth, 40, buttonFont, black, white, orange, hover);
            buttons.Add(btnCcd0);
            buttons.Add(btnCcd1);
            nextTop = btnCcd0.Bottom + 4;
        }

        root.Height = Math.Max(300, nextTop + 10);
        root.ResumeLayout(false);

        ReservedCpuSetsBuildResult result = new ReservedCpuSetsBuildResult();
        result.Root = root;
        result.Grid = grid;
        result.Cells = grid.Cells;
        result.Buttons = buttons.ToArray();
        result.RegistryPathLink = regPathLink;
        result.FinalBottom = root.Bottom + 10;
        return result;
    }

    private static int AddScrollableGroupTitleIfNeeded(DeviceEditorControl groupBox, string title, DeviceEditorTheme theme)
    {
        if (groupBox == null || String.IsNullOrWhiteSpace(title)) { return 0; }
        Font titleFont = (theme != null && theme.Font11 != null) ? theme.Font11 : (groupBox.Font ?? Control.DefaultFont);
        Color fore = (theme != null && theme.LightGray != Color.Empty) ? theme.LightGray : groupBox.ForeColor;
        Color back = (theme != null && theme.Black != Color.Empty) ? theme.Black : groupBox.BackColor;
        int viewWidth = Math.Max(1, groupBox.Width - 16);
        int measured = TextRenderer.MeasureText(title, titleFont, new Size(32767, 99), TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding).Width + 8;
        if (measured <= viewWidth) { return 0; }

        groupBox.Text = String.Empty;
        DeviceEditorScrollableLabelResult titleScroll = DeviceEditorNativeUiSupport.CreateScrollableLabel(groupBox, 8, 0, viewWidth, 18, 8, titleFont, fore, back);
        if (titleScroll.Container != null)
        {
            titleScroll.Container.BackColor = back;
            titleScroll.Container.Anchor = AnchorStyles.Left | AnchorStyles.Top;
        }
        if (titleScroll.Viewport != null) { titleScroll.Viewport.BackColor = back; }
        if (titleScroll.Label != null)
        {
            titleScroll.Label.BackColor = back;
            titleScroll.Label.ForeColor = fore;
            titleScroll.Label.Text = title;
            Hashtable titleTag = new Hashtable();
            titleTag["ScrollSync"] = titleScroll.Sync;
            titleTag["ScrollState"] = titleScroll.State;
            titleScroll.Label.Tag = titleTag;
            DeviceEditorNativeUiSupport.SyncScrollableLabel(titleScroll.Label);
        }
        return 10;
    }

    public static DeviceEditorBuildResult BuildDeviceEditor(DeviceRow row, DeviceEditorTheme theme, DeviceEditorStartupState state, DeviceEditorLayoutMetrics metrics)
    {
        if (row == null) { row = new DeviceRow(); }
        if (theme == null) { theme = new DeviceEditorTheme(); }
        if (state == null) { state = new DeviceEditorStartupState(); }
        if (metrics == null) { metrics = new DeviceEditorLayoutMetrics(); }

        int logicalCount = Math.Max(0, metrics.LogicalCount);
        DeviceEditorControl groupBox = new DeviceEditorControl();
        groupBox.SuspendLayout();

        bool hasUsbHeader = EqualsIgnoreCase(row.Category, "USB") && row.HasUsbHeaderTitle;
        string groupTitle;
        if (hasUsbHeader) { groupTitle = row.UsbHeaderTitle; }
        else if (row.IsStorage) { groupTitle = String.Format("{0} [Affinity usually doesn't work for {1}]", Safe(row.DisplayName), Safe(ResolveStorageAffinityMediaType(row))); }
        else { groupTitle = Safe(row.DisplayName); }
        groupBox.Text = groupTitle;
        groupBox.Width = Math.Max(1, metrics.AffGroupBoxWidth);
        groupBox.Height = 550;
        groupBox.Left = 10;
        groupBox.Top = 0;
        groupBox.Tag = row.Source ?? (object)row;
        groupBox.ForeColor = theme.LightGray;
        groupBox.BackColor = theme.Black;
        if (theme.Font11 != null) { groupBox.Font = theme.Font11; }

        int titleTopOffset = AddScrollableGroupTitleIfNeeded(groupBox, groupTitle, theme);
        int bodyTopOffset = titleTopOffset + BuildUsbHeader(groupBox, row, theme);

        int maxCoresPerColumn = Math.Max(1, metrics.MaxCoresPerColumn);
        int columns = Math.Max(1, metrics.Columns);
        int columnWidth = Math.Max(1, metrics.ColumnWidth);
        int rowHeight = Math.Max(1, metrics.RowHeight);
        int topPad = Math.Max(0, metrics.TopPad);
        int visibleRows = maxCoresPerColumn;
        int affPanelLeft = 10;
        int affPanelTop = 30 + bodyTopOffset;
        int affPanelWidth = Math.Max(1, metrics.AffPanelWidth);
        int affPanelHeight = topPad + ((visibleRows - 1) * rowHeight) + Math.Max(20, rowHeight - 6) + topPad + 2;
        DeviceEditorBorderElement affPanelBorder = groupBox.AddBorderElement(affPanelLeft, affPanelTop, affPanelWidth, affPanelHeight, theme.Black, SystemColors.ControlDark);

        CpuAffinityGrid cpuGrid = new CpuAffinityGrid();
        cpuGrid.SuspendLayout();
        cpuGrid.LogicalCount = logicalCount;
        cpuGrid.CpuTexts = metrics.CpuTexts ?? new string[0];
        cpuGrid.IsPCore = metrics.IsPCore ?? new bool[0];
        cpuGrid.CheckboxWidths = metrics.CheckboxWidths ?? new int[0];
        cpuGrid.Annotations = metrics.Annotations ?? new string[0];
        if (metrics.CppcLabelOffsets != null && metrics.CppcLabelOffsets.Length > 0) { cpuGrid.CppcLabelOffsets = metrics.CppcLabelOffsets; }
        cpuGrid.CppcEnabled = metrics.CppcEnabled;
        cpuGrid.CppcLabelWidth = Math.Max(1, metrics.CppcLabelWidth);
        if (theme.Font9 != null) { cpuGrid.Font = theme.Font9; }
        cpuGrid.AnnotationFont = theme.Font7_5;
        cpuGrid.OverlayFont = theme.Font7_5;
        cpuGrid.PCoreColor = theme.LightGray;
        cpuGrid.ECoreColor = theme.ECoreBlue;
        cpuGrid.OrangeColor = theme.Orange;
        cpuGrid.BackColor = theme.Black;
        cpuGrid.TextVerticalOffset = metrics.CpuTextVerticalOffset;
        cpuGrid.SetLayoutMetrics(maxCoresPerColumn, columns, columnWidth, rowHeight, topPad);
        cpuGrid.SetBounds(affPanelBorder.Left + 1, affPanelBorder.Top + 1, Math.Max(1, affPanelBorder.Width - 2), Math.Max(1, affPanelBorder.Height - 2));
        groupBox.Controls.Add(cpuGrid);
        CpuAffinityGridCell[] cells = cpuGrid.Cells;

        DeviceEditorTextElement lblMask = Text(groupBox, "IRQ Affinity Mask: ", 7, affPanelBorder.Bottom + 15, theme.Font11, theme.LightGray, true);
        string initialValue = String.IsNullOrWhiteSpace(state.InitialAffinity) ? "0x0" : state.InitialAffinity;
        bool isNdis = EqualsIgnoreCase(row.Category, "Network") && EqualsIgnoreCase(row.Role, "NDIS");
        int selectedBase = -1;
        int currentNumQueues = ObjectToInt(state.NumQueues, 1);
        if (currentNumQueues < 1) { currentNumQueues = 1; }
        if (isNdis)
        {
            selectedBase = ParseHexInt(initialValue, -1);
            if (selectedBase >= 0) { ApplyNdisBaseSelection(cells, selectedBase, currentNumQueues, Math.Max(1, logicalCount), Math.Max(1, metrics.RssHtStep)); }
        }
        else { cpuGrid.Mask = ParseHexUInt64(initialValue); }

        lblMask.Text = "IRQ Affinity Mask:";
        DeviceEditorTextElement lblMaskValue = Text(groupBox, String.Empty, lblMask.Right + 7, lblMask.Top, theme.Font11, theme.Orange, true);
        if (isNdis)
        {
            if (selectedBase >= 0)
            {
                ulong mask = CalculateNdisMask(selectedBase, currentNumQueues, Math.Max(1, logicalCount), Math.Max(1, metrics.RssHtStep));
                lblMaskValue.Text = mask == 0UL ? "Invalid RSS range" : "0x" + mask.ToString("X");
            }
            else { lblMaskValue.Text = "0x0"; }
        }
        else { lblMaskValue.Text = initialValue; }

        int msiPanelWidth = metrics.DeviceTweakerMsiPanelWidth > 0 ? metrics.DeviceTweakerMsiPanelWidth : 360;
        int msiPanelHeight = 195;
        int msiPanelLeft = groupBox.Width - msiPanelWidth - 5;
        int msiPanelTop = 30 + bodyTopOffset;
        DeviceEditorBorderElement msiPanel = groupBox.AddBorderElement(msiPanelLeft, msiPanelTop, msiPanelWidth, msiPanelHeight, theme.Black, SystemColors.ControlDark);
        List<Control> msiPanelControls = new List<Control>(10);
        int msiLabelLeft = msiPanel.Left + 10;
        int msiInputLeft = msiPanel.Left + 170;
        int msiInputRightPadding = 16;
        int msiInputWidth = Math.Max(1, Math.Min(180, msiPanel.Right - msiInputLeft - msiInputRightPadding));
        int msiControlTop = msiPanel.Top + 5;
        int msiRowStep = 42;
        int msiLabelYOffset = 5;

        DeviceEditorTextElement lblMSI = Text(groupBox, "MSI Mode:", msiLabelLeft, msiControlTop + msiLabelYOffset, theme.Font11, theme.LightGray, true);
        ComboBox cboMSI = Combo(msiInputLeft, msiControlTop, msiInputWidth, theme.Font12, theme, MsiItems);
        DeviceTweakerUiHandlers.WireDarkCombo(cboMSI);
        msiPanelControls.Add(cboMSI);

        DeviceEditorTextElement lblMsg = Text(groupBox, "MSI Limit:", msiLabelLeft, msiControlTop + msiRowStep + msiLabelYOffset, theme.Font11, theme.LightGray, true);
        Panel msgLimitHost = new Panel();
        msgLimitHost.BorderStyle = BorderStyle.FixedSingle;
        msgLimitHost.BackColor = theme.Black;
        msgLimitHost.ForeColor = theme.LightGray;
        msgLimitHost.Margin = new Padding(0);
        msgLimitHost.SetBounds(msiInputLeft - 10, msiControlTop + msiRowStep, msiInputWidth, Math.Max(cboMSI.Height, cboMSI.PreferredHeight));

        TextBox msgLimitBox = new TextBox();
        msgLimitBox.AutoSize = true;
        msgLimitBox.Multiline = false;
        msgLimitBox.AcceptsReturn = false;
        msgLimitBox.AcceptsTab = false;
        msgLimitBox.WordWrap = false;
        msgLimitBox.ScrollBars = ScrollBars.None;
        msgLimitBox.BorderStyle = BorderStyle.None;
        msgLimitBox.BackColor = theme.Black;
        msgLimitBox.ForeColor = theme.LightGray;
        if (theme.Font12 != null) { msgLimitBox.Font = theme.Font12; }
        msgLimitBox.Margin = new Padding(0);
        msgLimitHost.Controls.Add(msgLimitBox);
        DeviceTweakerUiHandlers.WireMsiLimitTextBox(msgLimitBox, cboMSI);
        msiPanelControls.Add(msgLimitHost);

        DeviceEditorTextElement lblPri = Text(groupBox, "IRQ Priority:", msiLabelLeft, msiControlTop + (msiRowStep * 2) + msiLabelYOffset, theme.Font11, theme.LightGray, true);
        ComboBox cboPriority = Combo(msiInputLeft, msiControlTop + (msiRowStep * 2), msiInputWidth, theme.Font12, theme, PriorityItems);
        DeviceTweakerUiHandlers.WireDarkCombo(cboPriority);
        msiPanelControls.Add(cboPriority);

        cboMSI.SelectedIndex = state.MsiEnabled == 1 ? 1 : 0;
        string messageLimit = state.MessageLimit == null ? String.Empty : Convert.ToString(state.MessageLimit);
        msgLimitBox.Text = String.IsNullOrEmpty(messageLimit) ? "Unlimited" : messageLimit;
        switch (state.Priority)
        {
            case 1: cboPriority.SelectedIndex = 0; break;
            case 2: cboPriority.SelectedIndex = 1; break;
            case 3: cboPriority.SelectedIndex = 2; break;
            default: cboPriority.SelectedIndex = 1; break;
        }

        DeviceEditorTextElement lblNumQueues = Text(groupBox, "RSS Queues:", msiPanel.Left + 10, lblPri.Bottom + 15, theme.Font11, theme.LightGray, true);
        lblNumQueues.Visible = isNdis;
        NumericUpDown nudNumQueues = new NumericUpDown();
        nudNumQueues.Left = lblNumQueues.Right + 27;
        nudNumQueues.Top = lblNumQueues.Top - 6;
        nudNumQueues.Width = 45;
        nudNumQueues.Minimum = 1;
        nudNumQueues.Maximum = Math.Max(1, logicalCount);
        nudNumQueues.Value = Math.Max(nudNumQueues.Minimum, Math.Min((decimal)currentNumQueues, nudNumQueues.Maximum));
        if (theme.Font12 != null) { nudNumQueues.Font = theme.Font12; }
        nudNumQueues.BorderStyle = BorderStyle.FixedSingle;
        nudNumQueues.BackColor = theme.Black;
        nudNumQueues.ForeColor = theme.LightGray;
        nudNumQueues.Visible = isNdis;
        msiPanelControls.Add(nudNumQueues);

        OrangeCheckBox chkNdisIrqToggle = new OrangeCheckBox();
        chkNdisIrqToggle.Text = "IRQ Policy Mode";
        chkNdisIrqToggle.AutoSize = true;
        chkNdisIrqToggle.Left = msiPanel.Left;
        chkNdisIrqToggle.Top = msiPanel.Bottom + 4;
        if (theme.Font9 != null) { chkNdisIrqToggle.Font = theme.Font9; }
        chkNdisIrqToggle.ForeColor = theme.LightGray;
        chkNdisIrqToggle.BackColor = theme.Black;
        chkNdisIrqToggle.Visible = isNdis;
        chkNdisIrqToggle.Checked = false;
        chkNdisIrqToggle.FlatStyle = FlatStyle.Flat;
        if (metrics.CpuTextVerticalOffset != 0) { chkNdisIrqToggle.Padding = new Padding(0, metrics.CpuTextVerticalOffset, 0, 0); }
        groupBox.Controls.Add(chkNdisIrqToggle);

        string pnpId = Safe(state.PnpId);
        DeviceEditorTextElement lblPolicy = Text(groupBox, "IRQ Policy:", msiLabelLeft, msiControlTop + (msiRowStep * 3) + msiLabelYOffset, theme.Font11, theme.LightGray, true);
        lblPolicy.Visible = !isNdis;
        ComboBox cboPolicy = Combo(msiInputLeft, msiControlTop + (msiRowStep * 3), msiInputWidth, theme.Font12, theme, PolicyItems);
        cboPolicy.Visible = !isNdis;
        DeviceTweakerUiHandlers.WireDarkCombo(cboPolicy);
        msiPanelControls.Add(cboPolicy);
        groupBox.Controls.AddRange(msiPanelControls.ToArray());

        int policyValue = state.Policy;
        if (isNdis)
        {
            cboPolicy.SelectedIndex = policyValue >= 0 && policyValue < cboPolicy.Items.Count ? policyValue : 0;
        }
        else
        {
            if (policyValue < 0 || policyValue >= cboPolicy.Items.Count) { policyValue = 0; }
            cboPolicy.SelectedIndex = policyValue;
            bool enableAffinity = policyValue == 4;
            SetCellsAutoCheck(cells, enableAffinity, true);
        }

        DeviceEditorTextElement lblPNP = Text(groupBox, "PNP ID: ", 6, lblMask.Bottom + 10, theme.Font11, theme.LightGray, true);
        DeviceEditorTextElement lblIRQ = Text(groupBox, "IRQ Count: ", 6, lblPNP.Bottom + 8, theme.Font11, theme.LightGray, true);
        DeviceEditorTextElement lblIRQValue = Text(groupBox, "Loading...", lblIRQ.Right, lblIRQ.Top, theme.Font11, theme.LightGray, true);
        DeviceEditorTextElement lblRegPathTitle = Text(groupBox, String.Empty, 6, lblIRQ.Bottom + 8, theme.Font11, theme.LightGray, true);
        DeviceEditorTextElement lblRegPath = BuildRegistryPathBlock(groupBox, row, theme, lblRegPathTitle);
        BuildPnpDisplay(groupBox, pnpId, lblPNP, theme);

        DeviceEditorState editorState = new DeviceEditorState();
        editorState.Device = row.Source ?? (object)row;
        editorState.IsNdis = isNdis;
        editorState.Grid = cpuGrid;
        editorState.Cells = cells;
        editorState.MaskLabel = lblMask;
        editorState.MaskValue = lblMaskValue;
        editorState.NumQueuesLabel = lblNumQueues;
        editorState.PolicyLabel = lblPolicy;
        editorState.InitialValue = initialValue;
        editorState.InitialNumQueues = currentNumQueues;
        editorState.NdisIrqAffinity = state.NdisIrqAffinity;
        editorState.RssHtStep = Math.Max(1, metrics.RssHtStep);
        editorState.LogicalCount = Math.Max(1, logicalCount);
        editorState.NumQueues = nudNumQueues;
        editorState.PolicyCombo = cboPolicy;
        editorState.NdisIrqToggle = chkNdisIrqToggle;
        editorState.GroupBox = groupBox;
        editorState.AffinityPanel = null;
        editorState.MsiPanel = msiPanel;
        editorState.MsiModeLabel = lblMSI;
        editorState.MsiLimitLabel = lblMsg;
        editorState.MsiPriorityLabel = lblPri;
        editorState.MsiCombo = cboMSI;
        editorState.MsgLimitBox = msgLimitBox;
        editorState.PriorityCombo = cboPriority;
        editorState.PnpId = pnpId;
        editorState.IrqLabel = lblIRQ;
        editorState.IrqValueLabel = lblIRQValue;
        editorState.RegistryPathElement = lblRegPath;
        editorState.BodyTopOffset = bodyTopOffset;

        DeviceEditorBuildResult result = new DeviceEditorBuildResult();
        result.GroupBox = groupBox;
        result.State = editorState;
        return result;
    }

    private static int BuildUsbHeader(DeviceEditorControl groupBox, DeviceRow row, DeviceEditorTheme theme)
    {
        if (!EqualsIgnoreCase(row.Category, "USB") || !row.HasUsbHeaderTitle) { return 0; }
        int maxWidth = Math.Max(360, groupBox.Width - 24);
        string endpointText = !String.IsNullOrEmpty(row.UsbEndpointUsageLabel) ? row.UsbEndpointUsageLabel : "Endpoint use: not detected";
        string[] lines = SplitTextByWidth(endpointText, theme.Font9 ?? groupBox.Font, Math.Max(80, maxWidth - 2));
        int top = 27;
        int lastBottom = top;
        for (int i = 0; i < lines.Length; i++)
        {
            DeviceEditorTextElement label = Text(groupBox, lines[i], 8, top, theme.Font9, theme.Orange, true);
            label.BackColor = theme.Black;
            label.Padding = new Padding(0, 0, 0, 2);
            label.UseMnemonic = false;
            if (i == 0 && endpointText.Length > 0)
            {
                label.AccessibleName = "USB endpoint use";
                label.AccessibleDescription = endpointText;
            }
            label.BringToFront();
            lastBottom = label.Bottom;
            top = label.Bottom;
        }
        return Math.Max(0, lastBottom + 8 - 20);
    }

    private static DeviceEditorTextElement BuildRegistryPathBlock(DeviceEditorControl groupBox, DeviceRow row, DeviceEditorTheme theme, DeviceEditorTextElement lblRegPathTitle)
    {
        if (EqualsIgnoreCase(row.Category, "Network") && row.HasConfigPath)
        {
            lblRegPathTitle.Text = "Registry Paths: ";
            DeviceEditorTextElement lblClassPathLabel = Text(groupBox, "Class Path: ", 6, lblRegPathTitle.Bottom + 2, theme.Font9, theme.DimGray, true);
            DeviceEditorTextElement lblClassPath = Text(groupBox, DisplayPath(row.RegistryPathDisplay), 6, lblClassPathLabel.Bottom + 2, theme.Font9, theme.Orange, false);
            lblClassPath.Width = groupBox.Width - 21;
            lblClassPath.Height = 20;
            lblClassPath.UseMnemonic = false;
            lblClassPath.Cursor = Cursors.Hand;
            lblClassPath.Tag = row.RegistryPath;
            DeviceTweakerUiHandlers.WireRegistryPathElement(lblClassPath);

            DeviceEditorTextElement lblConfigPathLabel = Text(groupBox, "Config Path: ", 6, lblClassPath.Bottom + 1, theme.Font9, theme.DimGray, true);
            DeviceEditorTextElement lblConfigPath = Text(groupBox, DisplayPath(row.ConfigPathDisplay), 6, lblConfigPathLabel.Bottom + 2, theme.Font9, theme.Orange, false);
            lblConfigPath.Width = groupBox.Width - 21;
            lblConfigPath.Height = 20;
            lblConfigPath.UseMnemonic = false;
            lblConfigPath.Cursor = Cursors.Hand;
            lblConfigPath.Tag = row.ConfigPath;
            DeviceTweakerUiHandlers.WireRegistryPathElement(lblConfigPath);
            return lblConfigPath;
        }
        else
        {
            lblRegPathTitle.Text = "Registry Path: ";
            DeviceEditorTextElement lblRegPath = Text(groupBox, DisplayPath(row.RegistryPathDisplay), 6, lblRegPathTitle.Bottom + 2, theme.Font9, theme.Orange, false);
            lblRegPath.Width = groupBox.Width - 21;
            lblRegPath.Height = 20;
            lblRegPath.UseMnemonic = false;
            lblRegPath.Cursor = Cursors.Hand;
            lblRegPath.Tag = row.RegistryPath;
            DeviceTweakerUiHandlers.WireRegistryPathElement(lblRegPath);
            return lblRegPath;
        }
    }

    private static void BuildPnpDisplay(DeviceEditorControl groupBox, string pnpId, DeviceEditorTextElement lblPNP, DeviceEditorTheme theme)
    {
        int currentLeft = lblPNP.Right;
        Match m = Regex.Match(Safe(pnpId), "^([^_]+)(_VEN_)([^_]+)(_DEV_)([^_]+)(.*)$");
        if (m.Success)
        {
            Font font = theme.Font11;
            int offset = -4;
            DeviceEditorTextElement e;
            e = Text(groupBox, m.Groups[1].Value, currentLeft, lblPNP.Top, font, theme.LightGray, true); e.UseMnemonic = false; currentLeft = e.Right + offset;
            e = Text(groupBox, m.Groups[2].Value, currentLeft, lblPNP.Top, font, theme.LightGray, true); e.UseMnemonic = false; currentLeft = e.Right + offset;
            e = Text(groupBox, m.Groups[3].Value, currentLeft, lblPNP.Top, font, theme.Orange, true); e.UseMnemonic = false; currentLeft = e.Right + offset;
            e = Text(groupBox, m.Groups[4].Value, currentLeft, lblPNP.Top, font, theme.LightGray, true); e.UseMnemonic = false; currentLeft = e.Right + offset;
            e = Text(groupBox, m.Groups[5].Value, currentLeft, lblPNP.Top, font, theme.Orange, true); e.UseMnemonic = false; currentLeft = e.Right + offset;
            if (m.Groups[6].Length > 0) { e = Text(groupBox, m.Groups[6].Value, currentLeft, lblPNP.Top, font, theme.LightGray, true); e.UseMnemonic = false; }
        }
        else
        {
            DeviceEditorTextElement e = Text(groupBox, Safe(pnpId), currentLeft, lblPNP.Top, theme.Font11, theme.LightGray, true);
            e.UseMnemonic = false;
        }
    }

    private static DeviceEditorTextElement Text(DeviceEditorControl owner, string text, int left, int top, Font font, Color color, bool autoSize)
    {
        DeviceEditorTextElement e = owner.CreateTextElement();
        e.Text = text ?? String.Empty;
        e.AutoSize = autoSize;
        e.Left = left;
        e.Top = top;
        if (font != null) { e.Font = font; }
        e.ForeColor = color;
        return e;
    }

    private static ComboBox Combo(int left, int top, int width, Font font, DeviceEditorTheme theme, object[] items)
    {
        ComboBox combo = new ComboBox();
        combo.Left = left;
        combo.Top = top;
        combo.Width = width;
        combo.DropDownStyle = ComboBoxStyle.DropDownList;
        combo.BackColor = theme.Black;
        combo.ForeColor = theme.LightGray;
        combo.FlatStyle = FlatStyle.Flat;
        combo.DrawMode = DrawMode.OwnerDrawFixed;
        if (font != null) { combo.Font = font; }
        combo.Items.AddRange(items);
        return combo;
    }

    private static string[] SplitTextByWidth(string text, Font font, int maxWidth)
    {
        List<string> lines = new List<string>();
        if (String.IsNullOrWhiteSpace(text)) { return new string[] { String.Empty }; }
        int maxW = Math.Max(80, maxWidth);
        string normalized = Regex.Replace(text, "[\r\n\t]+", " ");
        MatchCollection tokens = Regex.Matches(normalized, "\\s+|\\S+");
        string line = String.Empty;
        foreach (Match tokenMatch in tokens)
        {
            string token = tokenMatch.Value;
            if (String.IsNullOrEmpty(token)) { continue; }
            if (Regex.IsMatch(token, "^\\s+$"))
            {
                if (line.Length > 0 && !line.EndsWith(" ")) { line += " "; }
                continue;
            }
            string candidate = line.Length == 0 ? token : line + token;
            if (Measure(candidate, font) <= maxW) { line = candidate; continue; }
            if (Measure(token, font) <= maxW)
            {
                if (line.TrimEnd().Length > 0) { lines.Add(line.TrimEnd()); }
                line = token;
                continue;
            }
            string remaining = token;
            while (remaining.Length > 0)
            {
                string prefixBase = line.Length == 0 ? String.Empty : line;
                int lo = 1;
                int hi = remaining.Length;
                int best = 0;
                while (lo <= hi)
                {
                    int mid = (lo + hi) / 2;
                    string candidate2 = prefixBase + remaining.Substring(0, mid);
                    if (Measure(candidate2, font) <= maxW) { best = mid; lo = mid + 1; }
                    else { hi = mid - 1; }
                }
                if (best <= 0)
                {
                    if (line.TrimEnd().Length > 0)
                    {
                        lines.Add(line.TrimEnd());
                        line = String.Empty;
                        continue;
                    }
                    best = 1;
                }
                line = prefixBase + remaining.Substring(0, best);
                remaining = remaining.Substring(best);
                if (remaining.Length > 0)
                {
                    if (line.TrimEnd().Length > 0) { lines.Add(line.TrimEnd()); }
                    line = String.Empty;
                }
            }
        }
        if (line.TrimEnd().Length > 0) { lines.Add(line.TrimEnd()); }
        if (lines.Count == 0) { lines.Add(String.Empty); }
        return lines.ToArray();
    }

    private static int Measure(string text, Font font)
    {
        return TextRenderer.MeasureText(text ?? String.Empty, font, new Size(32767, 100), TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding).Width;
    }

    private static void SetCellsAutoCheck(CpuAffinityGridCell[] cells, bool autoCheck, bool enabled)
    {
        if (cells == null) { return; }
        for (int i = 0; i < cells.Length; i++)
        {
            CpuAffinityGridCell cell = cells[i];
            if (cell == null) { continue; }
            cell.AutoCheck = autoCheck;
            cell.Enabled = enabled;
        }
    }

    private static ulong ApplyNdisBaseSelection(CpuAffinityGridCell[] cells, int baseCore, int queueCount, int logicalCount, int step)
    {
        if (cells == null) { return 0UL; }
        bool[] selected = new bool[Math.Max(logicalCount, cells.Length)];
        ulong mask = 0UL;
        int[] processors = ExovanceRssTopology.GetProcessors(baseCore, queueCount, logicalCount);
        foreach (int core in processors) { selected[core] = true; mask |= 1UL << core; }
        // Keep the requested base visible on an invalid range so Apply can
        // reject that exact selection before making any registry changes.
        if (processors.Length == 0 && baseCore >= 0 && baseCore < selected.Length) { selected[baseCore] = true; }
        for (int i = 0; i < cells.Length; i++)
        {
            CpuAffinityGridCell cell = cells[i];
            if (cell == null) { continue; }
            bool isSelected = i < selected.Length && selected[i];
            cell.Checked = isSelected;
            cell.AutoCheck = !isSelected;
            cell.Enabled = true;
        }
        return mask;
    }

    private static ulong CalculateNdisMask(int baseCore, int queueCount, int logicalCount, int step)
    {
        return ExovanceRssTopology.GetMask(baseCore, queueCount, logicalCount);
    }

    private static int PositiveModulo(int value, int divisor)
    {
        if (divisor <= 0) { return 0; }
        int result = value % divisor;
        return result < 0 ? result + divisor : result;
    }

    private static ulong ParseHexUInt64(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return 0UL; }
        string hex = text.Trim();
        if (hex.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { hex = hex.Substring(2); }
        if (String.IsNullOrWhiteSpace(hex)) { return 0UL; }
        try { return Convert.ToUInt64(hex, 16); } catch { return 0UL; }
    }

    private static int ParseHexInt(string text, int fallback)
    {
        if (String.IsNullOrWhiteSpace(text)) { return fallback; }
        string hex = text.Trim();
        if (hex.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { hex = hex.Substring(2); }
        try { return Convert.ToInt32(hex, 16); } catch { return fallback; }
    }

    private static int ObjectToInt(object value, int fallback)
    {
        if (value == null) { return fallback; }
        try { return Convert.ToInt32(value); } catch { return fallback; }
    }

    private static string DisplayPath(string value)
    {
        return String.IsNullOrWhiteSpace(value) ? "(N/A)" : value;
    }

    private static string Safe(string value)
    {
        return value ?? String.Empty;
    }

    private static string ResolveStorageAffinityMediaType(DeviceRow row)
    {
        if (row == null) { return String.Empty; }
        string storageType = row.StorageType;
        if (!String.IsNullOrWhiteSpace(storageType)) { return storageType.Trim(); }
        string category = row.Category;
        if (!String.IsNullOrWhiteSpace(category) && !String.Equals(category.Trim(), "PCI", StringComparison.OrdinalIgnoreCase)) { return category.Trim(); }
        string displayName = row.DisplayName ?? String.Empty;
        if (displayName.IndexOf("SSD", StringComparison.OrdinalIgnoreCase) >= 0 || displayName.IndexOf("NVMe", StringComparison.OrdinalIgnoreCase) >= 0) { return "SSD"; }
        if (displayName.IndexOf("HDD", StringComparison.OrdinalIgnoreCase) >= 0 || displayName.IndexOf("Hard Disk", StringComparison.OrdinalIgnoreCase) >= 0 || displayName.IndexOf("Hard Drive", StringComparison.OrdinalIgnoreCase) >= 0) { return "HDD"; }
        return String.IsNullOrWhiteSpace(category) ? "Storage" : category.Trim();
    }

    private static bool EqualsIgnoreCase(string a, string b)
    {
        return String.Equals(a ?? String.Empty, b ?? String.Empty, StringComparison.OrdinalIgnoreCase);
    }
}

public static class DeviceTweakerUiHandlers
{
    public static bool NdisUpdating;
    public static EventHandler ReservedColoringCallback;

    private static Font _regPathNormalFont;
    private static Font _regPathHoverFont;
    private static Color _regPathNormalColor = Color.FromArgb(255, 100, 45);
    private static Color _regPathHoverColor = Color.FromArgb(234, 234, 234);

    public static Font RegistryPathNormalFont { get { return _regPathNormalFont; } }
    public static Font RegistryPathHoverFont { get { return _regPathHoverFont; } }
    public static Color RegistryPathNormalColor { get { return _regPathNormalColor; } }
    public static Color RegistryPathHoverColor { get { return _regPathHoverColor; } }

    private sealed class MsiLimitBoxState
    {
        public TextBox Box;
        public ComboBox Combo;
        public Control Host;
    }

    private sealed class HexVectorBoxState
    {
        public bool NicMode;
        public int FixedMaxHexDigits;
    }

    private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Control, MsiLimitBoxState> _msiLimitStates = new System.Runtime.CompilerServices.ConditionalWeakTable<Control, MsiLimitBoxState>();
    private static readonly System.Runtime.CompilerServices.ConditionalWeakTable<TextBox, HexVectorBoxState> _hexVectorStates = new System.Runtime.CompilerServices.ConditionalWeakTable<TextBox, HexVectorBoxState>();

    public static void ConfigureRegistryPathStyle(Font normalFont, Font hoverFont, Color normalColor, Color hoverColor)
    {
        _regPathNormalFont = normalFont;
        _regPathHoverFont = hoverFont;
        _regPathNormalColor = normalColor;
        _regPathHoverColor = hoverColor;
    }

    public static void SetNdisUpdating(bool value)
    {
        NdisUpdating = value;
    }

    public static void WireDarkCombo(ComboBox combo)
    {
        if (combo == null) { return; }
        combo.DrawMode = DrawMode.OwnerDrawFixed;
        combo.DrawItem -= DarkCombo_DrawItem;
        combo.DrawItem += DarkCombo_DrawItem;
        combo.DropDown -= Combo_DropDown;
        combo.DropDown += Combo_DropDown;
        combo.DropDownClosed -= Combo_DropDownClosed;
        combo.DropDownClosed += Combo_DropDownClosed;
        AutoSizeComboDropDown(combo);
    }

    public static int MeasureComboItemTextWidth(ComboBox combo)
    {
        if (combo == null) { return 1; }
        Font font = combo.Font ?? Control.DefaultFont;
        int max = Math.Max(1, combo.Width);
        TextFormatFlags flags = TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        foreach (object item in combo.Items)
        {
            string text = Convert.ToString(item) ?? String.Empty;
            int width = TextRenderer.MeasureText(text, font, new Size(32767, 32767), flags).Width;
            if (width > max) { max = width; }
        }
        return max;
    }

    public static void AutoSizeComboDropDown(ComboBox combo)
    {
        if (combo == null) { return; }
        int width = MeasureComboItemTextWidth(combo) + SystemInformation.VerticalScrollBarWidth + 18;
        width = Math.Max(combo.Width, width);
        try
        {
            Screen screen = Screen.FromControl(combo);
            if (screen != null && screen.WorkingArea.Width > 0) { width = Math.Min(width, Math.Max(combo.Width, screen.WorkingArea.Width - 24)); }
        }
        catch { }
        combo.DropDownWidth = Math.Max(1, width);
    }

    public static int FitComboBoxToItems(ComboBox combo, int minWidth, int maxWidth)
    {
        if (combo == null) { return 0; }
        int measured = MeasureComboItemTextWidth(combo) + 28;
        int lower = Math.Max(1, minWidth);
        int upper = Math.Max(lower, maxWidth <= 0 ? measured : maxWidth);
        combo.Width = Math.Max(lower, Math.Min(upper, measured));
        AutoSizeComboDropDown(combo);
        return combo.Width;
    }

    private static void Combo_DropDown(object sender, EventArgs e)
    {
        ComboBox combo = sender as ComboBox;
        if (combo != null) { AutoSizeComboDropDown(combo); }
        WheelMessageFilter.SuspendRedirect = true;
    }

    private static void Combo_DropDownClosed(object sender, EventArgs e)
    {
        WheelMessageFilter.SuspendRedirect = false;
    }

    private static void DarkCombo_DrawItem(object sender, DrawItemEventArgs e)
    {
        if (e.Index < 0) { return; }
        ComboBox combo = sender as ComboBox;
        if (combo == null || e.Index >= combo.Items.Count) { return; }
        bool isComboBoxEdit = ((e.State & DrawItemState.ComboBoxEdit) == DrawItemState.ComboBoxEdit);
        bool isSelectedDropDownItem = !isComboBoxEdit && ((e.State & DrawItemState.Selected) == DrawItemState.Selected);
        Color bg = isSelectedDropDownItem ? Color.FromArgb(255, 100, 45) : Color.FromArgb(0, 0, 0);
        Color fg = Color.FromArgb(219, 219, 219);
        using (SolidBrush brush = new SolidBrush(bg)) { e.Graphics.FillRectangle(brush, e.Bounds); }
        TextRenderer.DrawText(e.Graphics, Convert.ToString(combo.Items[e.Index]), e.Font, e.Bounds, fg, bg,
            TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPrefix);
    }

    private const int MsiLimitPanelLeftPad = 7;
    private const int MsiLimitPanelRightPad = 6;
    private const int MsiLimitNativeLeftPad = 8;
    private const int MsiLimitNativeRightPad = 6;

    public static void WireMsiLimitTextBox(TextBox box, ComboBox combo)
    {
        if (box == null || combo == null) { return; }
        Control host = box.Parent as Panel;
        if (host == null) { host = box; }
        MsiLimitBoxState state = new MsiLimitBoxState { Box = box, Combo = combo, Host = host };
        _msiLimitStates.Remove(box);
        _msiLimitStates.Remove(combo);
        _msiLimitStates.Remove(host);
        _msiLimitStates.Add(box, state);
        _msiLimitStates.Add(combo, state);
        if (!Object.ReferenceEquals(host, box)) { _msiLimitStates.Add(host, state); }

        box.HandleCreated += MsiLimitBox_Layout;
        box.SizeChanged += MsiLimitBox_Layout;
        box.FontChanged += MsiLimitBox_LayoutAndSync;
        box.KeyDown += MsiLimitBox_KeyDown;
        box.TextChanged += MsiLimitBox_TextChanged;
        if (!Object.ReferenceEquals(host, box))
        {
            host.HandleCreated += MsiLimitHost_Layout;
            host.SizeChanged += MsiLimitHost_Layout;
        }
        combo.HandleCreated += MsiLimitCombo_Sync;
        combo.SizeChanged += MsiLimitCombo_Sync;
        combo.FontChanged += MsiLimitCombo_Sync;
        SyncMsiLimitBox(state);
    }

    private static void MsiLimitBox_KeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Enter)
        {
            e.SuppressKeyPress = true;
            e.Handled = true;
        }
    }

    private static void MsiLimitBox_TextChanged(object sender, EventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box == null || box.IsDisposed) { return; }
        string clean = (box.Text ?? String.Empty).Replace("\r", String.Empty).Replace("\n", String.Empty);
        if (!String.Equals(clean, box.Text, StringComparison.Ordinal))
        {
            int sel = Math.Min(Math.Max(0, box.SelectionStart), clean.Length);
            box.Text = clean;
            box.SelectionStart = sel;
        }
    }

    private static void MsiLimitBox_Layout(object sender, EventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box != null) { ApplyMsiLimitTextBoxLayout(box); }
    }

    private static void MsiLimitHost_Layout(object sender, EventArgs e)
    {
        Control host = sender as Control;
        if (host == null) { return; }
        MsiLimitBoxState state;
        if (_msiLimitStates.TryGetValue(host, out state)) { ApplyMsiLimitTextBoxLayout(state.Box); }
    }

    private static void MsiLimitBox_LayoutAndSync(object sender, EventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box == null) { return; }
        MsiLimitBoxState state;
        if (_msiLimitStates.TryGetValue(box, out state)) { SyncMsiLimitBox(state); }
        else { ApplyMsiLimitTextBoxLayout(box); }
    }

    private static void MsiLimitCombo_Sync(object sender, EventArgs e)
    {
        Control c = sender as Control;
        if (c == null) { return; }
        MsiLimitBoxState state;
        if (_msiLimitStates.TryGetValue(c, out state)) { SyncMsiLimitBox(state); }
    }

    private static void SyncMsiLimitBox(MsiLimitBoxState state)
    {
        if (state == null || state.Box == null || state.Combo == null || state.Box.IsDisposed || state.Combo.IsDisposed) { return; }
        int targetHeight = Math.Max(state.Combo.Height, state.Combo.PreferredHeight);
        Control host = state.Host;
        if (host == null || host.IsDisposed) { host = state.Box; }
        SetControlBoundsIfChanged(host, state.Combo.Left - 10, host.Top, state.Combo.Width, targetHeight);
        ApplyMsiLimitTextBoxLayout(state.Box);
    }

    private static void ApplyMsiLimitTextBoxLayout(TextBox box)
    {
        if (box == null || box.IsDisposed) { return; }
        try
        {
            Control host = box.Parent;
            if (host != null && !host.IsDisposed && host is Panel)
            {
                int clientW = Math.Max(1, host.ClientSize.Width);
                int clientH = Math.Max(1, host.ClientSize.Height);
                int preferredH = Math.Max(8, box.PreferredHeight);
                int topOffset = Math.Max(0, (clientH - preferredH) / 2);
                int innerW = Math.Max(1, clientW - MsiLimitPanelLeftPad - MsiLimitPanelRightPad);
                if (box.IsHandleCreated) { DeviceTweakerTextBoxNative.SetTextMargins(box.Handle, 0, 0); }
                SetControlBoundsIfChanged(box, MsiLimitPanelLeftPad, topOffset, innerW, preferredH);
                return;
            }

            if (!box.IsHandleCreated) { return; }
            int w = Math.Max(1, box.ClientSize.Width);
            int h = Math.Max(1, box.ClientSize.Height);
            int preferred = Math.Max(8, box.PreferredHeight);
            int top = Math.Max(0, (h - preferred) / 2);
            DeviceTweakerTextBoxNative.SetTextMargins(box.Handle, MsiLimitNativeLeftPad, MsiLimitNativeRightPad);
            DeviceTweakerTextBoxNative.SetTextRect(box.Handle, MsiLimitNativeLeftPad, top, Math.Max(MsiLimitNativeLeftPad + 1, w - MsiLimitNativeRightPad), Math.Max(top + 1, h));
        }
        catch { }
    }

    private static void SetControlBoundsIfChanged(Control control, int left, int top, int width, int height)
    {
        if (control == null || control.IsDisposed) { return; }
        width = Math.Max(1, width);
        height = Math.Max(1, height);
        if (control.Left == left && control.Top == top && control.Width == width && control.Height == height) { return; }
        control.SetBounds(left, top, width, height);
    }

    public static void WireHexVectorTextBox(TextBox box, bool nicMode, int fixedMaxHexDigits)
    {
        if (box == null) { return; }
        HexVectorBoxState state = new HexVectorBoxState { NicMode = nicMode, FixedMaxHexDigits = Math.Max(1, fixedMaxHexDigits) };
        _hexVectorStates.Remove(box);
        _hexVectorStates.Add(box, state);
        box.KeyDown += HexVector_KeyDown;
        box.TextChanged += HexVector_TextChanged;
        box.Click += HexVector_KeepPrefixSelection;
        box.GotFocus += HexVector_KeepPrefixSelection;
    }

    private static void HexVector_KeyDown(object sender, KeyEventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box == null) { return; }
        if (box.SelectionStart < 2 && (e.KeyCode == Keys.Back || e.KeyCode == Keys.Delete))
        {
            e.SuppressKeyPress = true;
            return;
        }
        if (e.KeyCode == Keys.Home)
        {
            box.SelectionStart = Math.Min(2, box.TextLength);
            e.SuppressKeyPress = true;
        }
    }

    private static void HexVector_KeepPrefixSelection(object sender, EventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box != null && box.SelectionStart < 2) { box.SelectionStart = Math.Min(2, box.TextLength); }
    }

    private static void HexVector_TextChanged(object sender, EventArgs e)
    {
        TextBox box = sender as TextBox;
        if (box == null || box.IsDisposed) { return; }
        HexVectorBoxState state;
        if (!_hexVectorStates.TryGetValue(box, out state)) { return; }

        int maxHexDigits = state.FixedMaxHexDigits;
        int maxValueCount = 0;
        object info = UnwrapOrigTag(box.Tag);
        if (state.NicMode)
        {
            int readWidth = GetIntValue(info, "ReadWidth", 32);
            maxHexDigits = (readWidth == 16) ? 4 : ((readWidth == 64) ? 16 : 8);
            maxValueCount = GetIntValue(info, "MaxQueues", 0);
        }
        else
        {
            maxValueCount = GetIntValue(info, "ExpectedCount", 0);
        }

        string normalized = NormalizeHexVectorInputText(box.Text, maxHexDigits, maxValueCount);
        if (!String.Equals(normalized, box.Text, StringComparison.Ordinal))
        {
            box.Text = normalized;
            box.SelectionStart = box.TextLength;
        }
    }

    private static object UnwrapOrigTag(object tag)
    {
        System.Collections.IDictionary dict = tag as System.Collections.IDictionary;
        if (dict != null && dict.Contains("OrigTag")) { return dict["OrigTag"]; }
        return tag;
    }

    private static int GetIntValue(object source, string key, int fallback)
    {
        if (source == null) { return fallback; }
        try
        {
            System.Collections.IDictionary dict = source as System.Collections.IDictionary;
            if (dict != null && dict.Contains(key)) { return Convert.ToInt32(dict[key]); }
            System.Reflection.PropertyInfo prop = source.GetType().GetProperty(key);
            if (prop != null) { return Convert.ToInt32(prop.GetValue(source, null)); }
        }
        catch { }
        return fallback;
    }

    private static string NormalizeHexVectorInputText(string text, int maxHexDigits, int maxValueCount)
    {
        string raw = (text ?? String.Empty).Replace("\r", String.Empty).Replace("\n", String.Empty);
        if (String.IsNullOrWhiteSpace(raw)) { return "0x"; }
        string[] segments = Regex.Split(raw, "([,;|\\s]+)");
        StringBuilder sb = new StringBuilder(raw.Length + 8);
        bool haveToken = false;
        bool pendingDelimiter = false;
        int emittedTokenCount = 0;
        int safeMaxHexDigits = Math.Max(1, maxHexDigits);

        for (int i = 0; i < segments.Length; i++)
        {
            string segment = segments[i];
            if (String.IsNullOrEmpty(segment)) { continue; }
            if (Regex.IsMatch(segment, "^[,;|\\s]+$"))
            {
                if (haveToken && (maxValueCount <= 0 || emittedTokenCount < maxValueCount)) { pendingDelimiter = true; }
                continue;
            }

            string token = Regex.Replace(segment, "^(?i:0x)", String.Empty);
            token = Regex.Replace(token, "[^0-9A-Fa-f]", String.Empty);
            if (token.Length > safeMaxHexDigits) { token = token.Substring(0, safeMaxHexDigits); }
            bool shouldEmit = Regex.IsMatch(segment, "^(?i:0x?)$") || token.Length > 0;
            if (!shouldEmit) { continue; }
            if (maxValueCount > 0 && emittedTokenCount >= maxValueCount) { continue; }
            if (pendingDelimiter && sb.Length > 0 && sb[sb.Length - 1] != ',') { sb.Append(','); }
            sb.Append("0x");
            sb.Append(token.ToUpperInvariant());
            haveToken = true;
            pendingDelimiter = false;
            emittedTokenCount++;
        }

        if (sb.Length == 0) { return "0x"; }
        if (Regex.IsMatch(raw, "[,;|\\s]+$") && sb[sb.Length - 1] != ',' && (maxValueCount <= 0 || emittedTokenCount < maxValueCount)) { sb.Append(','); }
        return sb.ToString();
    }

    public static void WireRegistryPathElement(DeviceEditorTextElement element)
    {
        if (element == null) { return; }
        element.DoubleClick += RegistryPath_DoubleClick;
        element.MouseEnter += RegistryPath_MouseEnter;
        element.MouseLeave += RegistryPath_MouseLeave;
    }

    private static void RegistryPath_MouseEnter(object sender, EventArgs e)
    {
        DeviceEditorTextElement element = sender as DeviceEditorTextElement;
        if (element == null) { return; }
        if (_regPathHoverFont != null) { element.Font = _regPathHoverFont; }
        element.ForeColor = _regPathHoverColor;
    }

    private static void RegistryPath_MouseLeave(object sender, EventArgs e)
    {
        DeviceEditorTextElement element = sender as DeviceEditorTextElement;
        if (element == null) { return; }
        if (_regPathNormalFont != null) { element.Font = _regPathNormalFont; }
        element.ForeColor = _regPathNormalColor;
    }

    private static void RegistryPath_DoubleClick(object sender, EventArgs e)
    {
        DeviceEditorTextElement element = sender as DeviceEditorTextElement;
        if (element == null) { return; }
        OpenRegistryPath(Convert.ToString(element.Tag));
    }

    public static void OpenRegistryPath(string regPath)
    {
        if (String.IsNullOrWhiteSpace(regPath)) { return; }
        try
        {
            string normalizedPath = NormalizeRegistryPathForRegedit(regPath);
            if (String.IsNullOrWhiteSpace(normalizedPath)) { return; }
            using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\Applets\Regedit"))
            {
                if (key != null) { key.SetValue("LastKey", "Computer\\" + normalizedPath, Microsoft.Win32.RegistryValueKind.String); }
            }
            System.Diagnostics.ProcessStartInfo psi = new System.Diagnostics.ProcessStartInfo("regedit.exe");
            psi.UseShellExecute = true;
            System.Diagnostics.Process.Start(psi);
        }
        catch (Exception ex)
        {
            MessageBox.Show("Failed to open registry path: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private static string NormalizeRegistryPathForRegedit(string regPath)
    {
        string path = (regPath ?? String.Empty).Trim().Trim('"').Replace('/', '\\');
        if (String.IsNullOrWhiteSpace(path)) { return String.Empty; }
        path = StripRegistryPathPrefix(path, @"Microsoft.PowerShell.Core\Registry::");
        path = StripRegistryPathPrefix(path, @"Registry::");
        while (path.IndexOf(@"\\", StringComparison.Ordinal) >= 0) { path = path.Replace(@"\\", @"\"); }
        path = CanonicalizeRegistryHiveForRegedit(path, "HKLM", "HKEY_LOCAL_MACHINE");
        path = CanonicalizeRegistryHiveForRegedit(path, "HKCU", "HKEY_CURRENT_USER");
        path = CanonicalizeRegistryHiveForRegedit(path, "HKCR", "HKEY_CLASSES_ROOT");
        path = CanonicalizeRegistryHiveForRegedit(path, "HKU", "HKEY_USERS");
        path = CanonicalizeRegistryHiveForRegedit(path, "HKCC", "HKEY_CURRENT_CONFIG");
        if (path.StartsWith(@"SYSTEM\", StringComparison.OrdinalIgnoreCase)) { path = @"HKEY_LOCAL_MACHINE\" + path; }
        return path.Trim('\\');
    }

    private static string StripRegistryPathPrefix(string path, string prefix)
    {
        if (String.IsNullOrEmpty(path) || String.IsNullOrEmpty(prefix)) { return path; }
        return path.StartsWith(prefix, StringComparison.OrdinalIgnoreCase) ? path.Substring(prefix.Length) : path;
    }

    private static string CanonicalizeRegistryHiveForRegedit(string path, string shortHive, string canonicalHive)
    {
        if (String.IsNullOrWhiteSpace(path)) { return path; }
        string p = path.TrimStart('\\');
        string colonPrefix = shortHive + @":\";
        string slashPrefix = shortHive + @"\";
        string canonicalPrefix = canonicalHive + @"\";
        string underscoredCanonicalPrefix = canonicalHive.Replace("_", String.Empty) + @"\";
        if (p.StartsWith(colonPrefix, StringComparison.OrdinalIgnoreCase)) { return canonicalPrefix + p.Substring(colonPrefix.Length).TrimStart('\\'); }
        if (p.StartsWith(slashPrefix, StringComparison.OrdinalIgnoreCase)) { return canonicalPrefix + p.Substring(slashPrefix.Length).TrimStart('\\'); }
        if (p.StartsWith(canonicalPrefix, StringComparison.OrdinalIgnoreCase)) { return canonicalPrefix + p.Substring(canonicalPrefix.Length).TrimStart('\\'); }
        if (p.StartsWith(underscoredCanonicalPrefix, StringComparison.OrdinalIgnoreCase)) { return canonicalPrefix + p.Substring(underscoredCanonicalPrefix.Length).TrimStart('\\'); }
        return p;
    }

    public static void WireDeviceEditorState(DeviceEditorState state)
    {
        if (state == null) { return; }
        if (state.LogicalCount <= 0) { state.LogicalCount = Environment.ProcessorCount; }
        if (state.RssHtStep <= 0) { state.RssHtStep = 1; }
        if (state.InitialNumQueues <= 0) { state.InitialNumQueues = 1; }
        if (state.Cells == null && state.Grid != null) { state.Cells = state.Grid.Cells; }
        if (state.NumQueues != null)
        {
            state.NumQueues.Tag = state;
            state.NumQueues.ValueChanged += NumQueues_ValueChanged;
        }
        if (state.PolicyCombo != null)
        {
            state.PolicyCombo.Tag = state;
            state.PolicyCombo.SelectedIndexChanged += PolicyCombo_SelectedIndexChanged;
        }
        if (state.NdisIrqToggle != null)
        {
            state.NdisIrqToggle.Tag = state;
            state.NdisIrqToggle.CheckedChanged += NdisIrqToggle_CheckedChanged;
        }
        if (state.Grid != null)
        {
            state.Grid.Tag = state;
            state.Grid.MaskChanged += CpuGrid_MaskChanged;
        }
    }

    private static DeviceEditorState GetState(object sender)
    {
        Control c = sender as Control;
        if (c != null) { return c.Tag as DeviceEditorState; }
        return null;
    }

    private static void NumQueues_ValueChanged(object sender, EventArgs e)
    {
        if (NdisUpdating) { return; }
        DeviceEditorState state = GetState(sender);
        if (state == null || !state.IsNdis || state.Updating) { return; }
        int selectedBase = FindFirstCheckedCore(state);
        if (selectedBase < 0) { return; }
        int queueCount = 1;
        try { queueCount = Convert.ToInt32(state.NumQueues.Value); } catch { queueCount = 1; }
        if (queueCount < 1) { queueCount = 1; }
        state.Updating = true;
        try
        {
            ulong mask = ApplyNdisBaseSelection(state, selectedBase, queueCount);
            SetMaskText(state, mask == 0UL ? "Invalid RSS range - reduce queues" : "0x" + mask.ToString("X"));
        }
        finally { state.Updating = false; }
    }

    private static void PolicyCombo_SelectedIndexChanged(object sender, EventArgs e)
    {
        DeviceEditorState state = GetState(sender);
        if (state == null || state.Cells == null) { return; }
        bool enableAffinity = state.PolicyCombo != null && state.PolicyCombo.SelectedIndex == 4;
        if (state.IsNdis)
        {
            if (state.NdisIrqToggle != null && state.NdisIrqToggle.Checked) { SetCellsAutoCheck(state, enableAffinity, true); }
        }
        else { SetCellsAutoCheck(state, enableAffinity, true); }
        RaiseReservedColoring(sender);
    }

    private static void NdisIrqToggle_CheckedChanged(object sender, EventArgs e)
    {
        DeviceEditorState state = GetState(sender);
        if (state == null || !state.IsNdis || state.Updating) { return; }
        bool irqMode = state.NdisIrqToggle != null && state.NdisIrqToggle.Checked;
        if (state.NumQueues != null) { state.NumQueues.Visible = !irqMode; }
        if (state.NumQueuesLabel != null) { state.NumQueuesLabel.Visible = !irqMode; }
        if (state.PolicyCombo != null) { state.PolicyCombo.Visible = irqMode; }
        if (state.PolicyLabel != null) { state.PolicyLabel.Visible = irqMode; }

        NdisUpdating = true;
        state.Updating = true;
        try
        {
            if (irqMode)
            {
                string affinity = !String.IsNullOrWhiteSpace(state.NdisIrqAffinity) ? state.NdisIrqAffinity : "0x0";
                SetCellsFromAffinity(state, affinity);
                SetMaskText(state, affinity);
                bool enableAffinity = state.PolicyCombo != null && state.PolicyCombo.SelectedIndex == 4;
                SetCellsAutoCheck(state, enableAffinity, true);
            }
            else
            {
                int selectedBase = ParseHexInt(state.InitialValue, -1);
                int queues = Math.Max(1, state.InitialNumQueues);
                if (selectedBase >= 0)
                {
                    ulong mask = ApplyNdisBaseSelection(state, selectedBase, queues);
                    SetMaskText(state, mask == 0UL ? "Invalid RSS range - reduce queues" : "0x" + mask.ToString("X"));
                }
                else
                {
                    ClearCells(state);
                    SetMaskText(state, "0x0");
                }
                if (state.NumQueues != null)
                {
                    decimal newValue = Math.Max((decimal)state.NumQueues.Minimum, Math.Min((decimal)queues, (decimal)state.NumQueues.Maximum));
                    state.NumQueues.Value = newValue;
                }
            }
        }
        finally
        {
            state.Updating = false;
            NdisUpdating = false;
        }
        RaiseReservedColoring(sender);
    }


    private static void CpuGrid_MaskChanged(object sender, CpuAffinityGridMaskChangedEventArgs e)
    {
        if (NdisUpdating) { return; }
        CpuAffinityGrid grid = sender as CpuAffinityGrid;
        DeviceEditorState state = grid != null ? grid.Tag as DeviceEditorState : null;
        if (state == null || state.Updating) { return; }
        if (state.IsNdis)
        {
            bool irqMode = state.NdisIrqToggle != null && state.NdisIrqToggle.Checked;
            if (irqMode)
            {
                SetMaskText(state, CalculateAffinityHex(state));
                return;
            }
            if (e.IsChecked)
            {
                int queues = 1;
                try { queues = state.NumQueues != null ? Convert.ToInt32(state.NumQueues.Value) : 1; } catch { queues = 1; }
                if (queues < 1) { queues = 1; }
                state.Updating = true;
                try
                {
                    ulong mask = ApplyNdisBaseSelection(state, e.CpuIndex, queues);
                    SetMaskText(state, mask == 0UL ? "Invalid RSS range - reduce queues" : "0x" + mask.ToString("X"));
                }
                finally { state.Updating = false; }
            }
            else
            {
                state.Updating = true;
                try
                {
                    ClearCells(state);
                    SetMaskText(state, "0x0");
                }
                finally { state.Updating = false; }
            }
        }
        else
        {
            SetMaskText(state, CalculateAffinityHex(state));
        }
    }

    private static void RaiseReservedColoring(object sender)
    {
        EventHandler callback = ReservedColoringCallback;
        if (callback == null) { return; }
        try { callback(sender, EventArgs.Empty); } catch { }
    }

    private static void SetMaskText(DeviceEditorState state, string text)
    {
        if (state == null) { return; }
        if (state.MaskLabel != null) { state.MaskLabel.Text = "IRQ Affinity Mask: "; }
        if (state.MaskValue != null) { state.MaskValue.Text = String.IsNullOrEmpty(text) ? "0x0" : text; }
    }

    private static int FindFirstCheckedCore(DeviceEditorState state)
    {
        if (state == null || state.Cells == null) { return -1; }
        for (int i = 0; i < state.Cells.Length; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell != null && cell.Checked) { return i; }
        }
        return -1;
    }

    private static ulong ApplyNdisBaseSelection(DeviceEditorState state, int baseCore, int queueCount)
    {
        if (state == null || state.Cells == null) { return 0UL; }
        int logical = Math.Max(1, state.LogicalCount);
        int step = Math.Max(1, state.RssHtStep);
        bool[] selected = new bool[Math.Max(logical, state.Cells.Length)];
        ulong mask = 0UL;
        int[] processors = ExovanceRssTopology.GetProcessors(baseCore, queueCount, logical);
        foreach (int core in processors) { selected[core] = true; mask |= 1UL << core; }
        // Keep the requested base visible on an invalid range so Apply can
        // reject that exact selection before making any registry changes.
        if (processors.Length == 0 && baseCore >= 0 && baseCore < selected.Length) { selected[baseCore] = true; }
        for (int i = 0; i < state.Cells.Length; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell == null) { continue; }
            bool isSelected = i < selected.Length && selected[i];
            cell.Checked = isSelected;
            cell.AutoCheck = !isSelected;
            cell.Enabled = true;
        }
        return mask;
    }

    private static int PositiveModulo(int value, int divisor)
    {
        if (divisor <= 0) { return 0; }
        int result = value % divisor;
        return result < 0 ? result + divisor : result;
    }

    private static void ClearCells(DeviceEditorState state)
    {
        if (state == null || state.Cells == null) { return; }
        for (int i = 0; i < state.Cells.Length; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell == null) { continue; }
            cell.Checked = false;
            cell.AutoCheck = true;
            cell.Enabled = true;
        }
    }

    private static void SetCellsAutoCheck(DeviceEditorState state, bool autoCheck, bool enabled)
    {
        if (state == null || state.Cells == null) { return; }
        for (int i = 0; i < state.Cells.Length; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell == null) { continue; }
            cell.AutoCheck = autoCheck;
            cell.Enabled = enabled;
        }
    }

    private static void SetCellsFromAffinity(DeviceEditorState state, string affinityHex)
    {
        if (state == null) { return; }
        ulong mask = ParseHexUInt64(affinityHex);
        if (state.Grid != null)
        {
            state.Grid.Mask = mask;
            return;
        }
        if (state.Cells == null) { return; }
        for (int i = 0; i < state.Cells.Length; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell == null) { continue; }
            bool isChecked = i < 64 && ((mask & (1UL << i)) != 0UL);
            cell.Checked = isChecked;
        }
    }

    private static string CalculateAffinityHex(DeviceEditorState state)
    {
        if (state == null) { return "0x0"; }
        if (state.Grid != null) { return "0x" + state.Grid.Mask.ToString("X"); }
        if (state.Cells == null) { return "0x0"; }
        ulong mask = 0UL;
        for (int i = 0; i < state.Cells.Length && i < 64; i++)
        {
            CpuAffinityGridCell cell = state.Cells[i];
            if (cell != null && cell.Checked) { mask |= (1UL << i); }
        }
        return "0x" + mask.ToString("X");
    }

    private static ulong ParseHexUInt64(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return 0UL; }
        string hex = text.Trim();
        if (hex.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { hex = hex.Substring(2); }
        if (String.IsNullOrWhiteSpace(hex)) { return 0UL; }
        try { return Convert.ToUInt64(hex, 16); } catch { return 0UL; }
    }

    private static int ParseHexInt(string text, int fallback)
    {
        if (String.IsNullOrWhiteSpace(text)) { return fallback; }
        string hex = text.Trim();
        if (hex.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { hex = hex.Substring(2); }
        try { return Convert.ToInt32(hex, 16); } catch { return fallback; }
    }
}


public sealed class CpuAffinityGridMaskChangedEventArgs : EventArgs
{
    public readonly int CpuIndex;
    public readonly bool IsChecked;
    public readonly ulong Mask;

    public CpuAffinityGridMaskChangedEventArgs(int cpuIndex, bool isChecked, ulong mask)
    {
        CpuIndex = cpuIndex;
        IsChecked = isChecked;
        Mask = mask;
    }
}

public sealed class CpuAffinityGridCell
{
    private readonly CpuAffinityGrid _owner;
    private readonly int _index;
    private bool _autoCheck;
    private bool _enabled;
    private Color _foreColor;
    private Padding _padding;

    internal CpuAffinityGridCell(CpuAffinityGrid owner, int index)
    {
        _owner = owner;
        _index = index;
        _autoCheck = true;
        _enabled = true;
        _foreColor = Color.Empty;
        _padding = Padding.Empty;
    }

    public CpuAffinityGrid Owner { get { return _owner; } }
    public int CpuIndex { get { return _index; } }

    public object Tag
    {
        get { return _index; }
        set { }
    }

    public string Text
    {
        get { return _owner.GetCpuText(_index); }
        set { _owner.SetCpuText(_index, value); }
    }

    public Font Font
    {
        get { return _owner.Font; }
        set { if (value != null) { _owner.Font = value; } }
    }

    public bool Checked
    {
        get { return _owner.GetCpuChecked(_index); }
        set { _owner.SetCpuChecked(_index, value, false); }
    }

    public bool AutoCheck
    {
        get { return _autoCheck; }
        set
        {
            if (_autoCheck == value) { return; }
            _autoCheck = value;
            _owner.InvalidateCpu(_index);
        }
    }

    public bool Enabled
    {
        get { return _enabled; }
        set
        {
            if (_enabled == value) { return; }
            _enabled = value;
            _owner.InvalidateCpu(_index);
        }
    }

    public Color ForeColor
    {
        get { return _foreColor; }
        set
        {
            if (_foreColor.ToArgb() == value.ToArgb()) { return; }
            _foreColor = value;
            _owner.InvalidateCpu(_index);
        }
    }

    public Color BackColor
    {
        get { return _owner.BackColor; }
        set { _owner.BackColor = value; }
    }

    public Padding Padding
    {
        get { return _padding; }
        set
        {
            _padding = value;
            _owner.InvalidateCpu(_index);
        }
    }

    public int Left { get { return _owner.GetCpuBounds(_index).Left; } set { } }
    public int Top { get { return _owner.GetCpuBounds(_index).Top; } set { } }
    public int Width { get { return _owner.GetCpuCellWidth(_index); } set { } }
    public int Height { get { return 20; } set { } }
    public int Right { get { return Left + Width; } }
    public int Bottom { get { return Top + Height; } }

    public event EventHandler CheckedChanged;

    internal void RaiseCheckedChanged()
    {
        EventHandler handler = CheckedChanged;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    public void Invalidate()
    {
        _owner.InvalidateCpu(_index);
    }
}

public sealed class CpuAffinityGridAnnotation
{
    private readonly CpuAffinityGrid _owner;
    private readonly int _index;

    internal CpuAffinityGridAnnotation(CpuAffinityGrid owner, int index)
    {
        _owner = owner;
        _index = index;
    }

    public CpuAffinityGrid Owner { get { return _owner; } }
    public Control Parent { get { return _owner; } }

    public object Tag
    {
        get { return _index; }
        set { }
    }

    public string Text
    {
        get { return _owner.GetAnnotationText(_index); }
        set { _owner.SetAnnotationText(_index, value); }
    }

    public int Left { get { return _owner.GetAnnotationBounds(_index).Left; } set { } }
    public int Top { get { return _owner.GetAnnotationBounds(_index).Top; } set { } }
    public int Width { get { return _owner.CppcLabelWidth; } set { } }
    public int Height { get { return 14; } set { } }
    public int Right { get { return Left + Width; } }
    public int Bottom { get { return Top + Height; } }
}

public sealed class CpuAffinityGrid : Control
{
    private int _logicalCount;
    private ulong _mask;
    private bool[] _checked;
    private string[] _cpuTexts;
    private bool[] _isPCore;
    private string[] _annotations;
    private int[] _checkboxWidths;
    private int[] _cppcLabelOffsets;
    private CpuAffinityGridCell[] _cells;
    private CpuAffinityGridAnnotation[] _annotationCells;
    private int _hoverIndex;
    private int _focusIndex;
    private Rectangle[] _smtRects;
    private string[] _smtLabels;
    private Point[] _smtLabelPoints;
    private Font _annotationFont;
    private Font _overlayFont;
    private int _paintUpdateDepth;
    private bool _hasPendingInvalidation;
    private Rectangle _pendingInvalidation;

    public CpuAffinityGrid()
    {
        _logicalCount = 0;
        _mask = 0UL;
        _checked = new bool[0];
        _cpuTexts = new string[0];
        _isPCore = new bool[0];
        _annotations = new string[0];
        _checkboxWidths = new int[0];
        _cppcLabelOffsets = new int[0];
        _cells = new CpuAffinityGridCell[0];
        _annotationCells = new CpuAffinityGridAnnotation[0];
        _hoverIndex = -1;
        _focusIndex = 0;
        _smtRects = new Rectangle[0];
        _smtLabels = new string[0];
        _smtLabelPoints = new Point[0];
        _paintUpdateDepth = 0;
        _hasPendingInvalidation = false;
        _pendingInvalidation = Rectangle.Empty;
        CppcEnabled = false;
        CppcLabelWidth = 31;
        MaxCoresPerColumn = 8;
        Columns = 4;
        ColumnWidth = 86;
        RowHeight = 32;
        TopPad = 0;
        TextVerticalOffset = 1;
        PCoreColor = Color.FromArgb(219, 219, 219);
        ECoreColor = Color.FromArgb(0, 104, 181);
        OrangeColor = Color.FromArgb(255, 100, 45);
        CheckBorderColor = Color.FromArgb(180, 180, 180);
        CheckHoverBorderColor = Color.FromArgb(220, 220, 220);
        SmtOverlayColor = Color.FromArgb(150, 150, 150);
        this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw | ControlStyles.Selectable, true);
        this.BackColor = Color.Black;
        this.TabStop = true;
        AccessibleName = "CPU affinity selection";
        AccessibleDescription = "Arrow keys choose a CPU. Space changes the selection without applying settings.";
    }

    public new void SuspendLayout()
    {
        _paintUpdateDepth++;
        base.SuspendLayout();
    }

    public new void ResumeLayout(bool performLayout)
    {
        if (_paintUpdateDepth > 0) { _paintUpdateDepth--; }
        base.ResumeLayout(performLayout);
        if (_paintUpdateDepth == 0 && _hasPendingInvalidation)
        {
            Rectangle pending = _pendingInvalidation;
            _hasPendingInvalidation = false;
            _pendingInvalidation = Rectangle.Empty;
            if (pending.Width <= 0 || pending.Height <= 0) { base.Invalidate(); }
            else { base.Invalidate(pending); }
        }
    }

    public new void Invalidate()
    {
        InvalidateGrid(Rectangle.Empty);
    }

    public new void Invalidate(Rectangle rc)
    {
        InvalidateGrid(rc);
    }

    private void InvalidateGrid(Rectangle rc)
    {
        if (IsDisposed) { return; }
        if (_paintUpdateDepth > 0)
        {
            if (rc.Width <= 0 || rc.Height <= 0)
            {
                _pendingInvalidation = Rectangle.Empty;
                _hasPendingInvalidation = true;
                return;
            }
            if (!_hasPendingInvalidation)
            {
                _pendingInvalidation = rc;
                _hasPendingInvalidation = true;
            }
            else if (_pendingInvalidation.Width > 0 && _pendingInvalidation.Height > 0)
            {
                _pendingInvalidation = Rectangle.Union(_pendingInvalidation, rc);
            }
            return;
        }
        if (rc.Width <= 0 || rc.Height <= 0) { base.Invalidate(); }
        else { base.Invalidate(rc); }
    }

    public event EventHandler<CpuAffinityGridMaskChangedEventArgs> MaskChanged;

    public ulong Mask
    {
        get { return _mask; }
        set { SetMaskInternal(value, false, -1); }
    }

    public int LogicalCount
    {
        get { return _logicalCount; }
        set
        {
            int count = value;
            if (count < 0) { count = 0; }
            if (_logicalCount == count && _cells != null && _cells.Length == count) { return; }
            _logicalCount = count;
            _focusIndex = Math.Max(0, Math.Min(Math.Max(0, count - 1), _focusIndex));
            _checked = new bool[count];
            _cells = new CpuAffinityGridCell[count];
            _annotationCells = new CpuAffinityGridAnnotation[count];
            for (int i = 0; i < count; i++)
            {
                _cells[i] = new CpuAffinityGridCell(this, i);
                _annotationCells[i] = new CpuAffinityGridAnnotation(this, i);
            }
            SetMaskInternal(_mask, false, -1);
            Invalidate();
        }
    }

    public bool[] IsPCore
    {
        get { return _isPCore; }
        set { _isPCore = value ?? new bool[0]; Invalidate(); }
    }

    public string[] Annotations
    {
        get { return _annotations; }
        set { _annotations = value ?? new string[0]; Invalidate(); }
    }

    public string[] CpuTexts
    {
        get { return _cpuTexts; }
        set { _cpuTexts = value ?? new string[0]; Invalidate(); }
    }

    public int[] CheckboxWidths
    {
        get { return _checkboxWidths; }
        set { _checkboxWidths = value ?? new int[0]; Invalidate(); }
    }

    public int[] CppcLabelOffsets
    {
        get { return _cppcLabelOffsets; }
        set { _cppcLabelOffsets = value ?? new int[0]; Invalidate(); }
    }

    public CpuAffinityGridCell[] Cells { get { return _cells; } }
    public CpuAffinityGridAnnotation[] AnnotationCells { get { return _annotationCells; } }

    public bool CppcEnabled { get; set; }
    public int CppcLabelWidth { get; set; }
    public int MaxCoresPerColumn { get; set; }
    public int Columns { get; set; }
    public int ColumnWidth { get; set; }
    public int RowHeight { get; set; }
    public int TopPad { get; set; }
    public int TextVerticalOffset { get; set; }
    public Color PCoreColor { get; set; }
    public Color ECoreColor { get; set; }
    public Color OrangeColor { get; set; }
    public Color CheckBorderColor { get; set; }
    public Color CheckHoverBorderColor { get; set; }
    public Color SmtOverlayColor { get; set; }

    public Font AnnotationFont
    {
        get { return _annotationFont; }
        set { _annotationFont = value; Invalidate(); }
    }

    public Font OverlayFont
    {
        get { return _overlayFont; }
        set { _overlayFont = value; Invalidate(); }
    }

    public void SetLayoutMetrics(int maxCoresPerColumn, int columns, int columnWidth, int rowHeight, int topPad)
    {
        MaxCoresPerColumn = Math.Max(1, maxCoresPerColumn);
        Columns = Math.Max(1, columns);
        ColumnWidth = Math.Max(1, columnWidth);
        RowHeight = Math.Max(1, rowHeight);
        TopPad = Math.Max(0, topPad);
        Invalidate();
    }

    public void SetSmtOverlays(Rectangle[] rects, string[] labels, Point[] labelPoints)
    {
        _smtRects = rects ?? new Rectangle[0];
        _smtLabels = labels ?? new string[0];
        _smtLabelPoints = labelPoints ?? new Point[0];
        Invalidate();
    }

    public bool GetCpuChecked(int index)
    {
        if (index < 0 || index >= _checked.Length) { return false; }
        return _checked[index];
    }

    public void SetCheckedFromBoolArray(bool[] values)
    {
        int count = _checked == null ? 0 : _checked.Length;
        ulong newMask = 0UL;
        for (int i = 0; i < count; i++)
        {
            bool isChecked = values != null && i < values.Length && values[i];
            _checked[i] = isChecked;
            if (isChecked && i < 64) { newMask |= (1UL << i); }
        }
        _mask = newMask;
        Invalidate();
    }

    public void SetCheckedFromCoreSet(HashSet<int> cores)
    {
        int count = _checked == null ? 0 : _checked.Length;
        ulong newMask = 0UL;
        for (int i = 0; i < count; i++)
        {
            bool isChecked = cores != null && cores.Contains(i);
            _checked[i] = isChecked;
            if (isChecked && i < 64) { newMask |= (1UL << i); }
        }
        _mask = newMask;
        Invalidate();
    }

    public void SetCheckedFromPcoreLookup(bool[] isPCoreLookup, bool reservePCores)
    {
        int count = _checked == null ? 0 : _checked.Length;
        ulong newMask = 0UL;
        for (int i = 0; i < count; i++)
        {
            bool isPCore = isPCoreLookup == null || i >= isPCoreLookup.Length ? true : isPCoreLookup[i];
            bool isChecked = reservePCores ? isPCore : !isPCore;
            _checked[i] = isChecked;
            if (isChecked && i < 64) { newMask |= (1UL << i); }
        }
        _mask = newMask;
        Invalidate();
    }

    public byte[] BuildCheckedBytes(int logicalCount)
    {
        int count = logicalCount < 1 ? 1 : logicalCount;
        byte[] bytes = new byte[Math.Max(8, (count + 7) / 8)];
        int max = Math.Min(count, _checked == null ? 0 : _checked.Length);
        for (int i = 0; i < max; i++)
        {
            if (!_checked[i]) { continue; }
            int byteIndex = i / 8;
            int bitIndex = i % 8;
            bytes[byteIndex] = (byte)(bytes[byteIndex] | (byte)(1 << bitIndex));
        }
        return bytes;
    }

    public void SetCpuChecked(int index, bool value, bool raiseCellEvent)
    {
        if (index < 0 || index >= _checked.Length) { return; }
        if (_checked[index] == value) { return; }
        _checked[index] = value;
        if (index >= 0 && index < 64)
        {
            ulong bit = 1UL << index;
            if (value) { _mask |= bit; }
            else { _mask &= ~bit; }
        }
        InvalidateCpu(index);
        if (raiseCellEvent && _cells != null && index < _cells.Length && _cells[index] != null)
        {
            _cells[index].RaiseCheckedChanged();
        }
    }

    public string GetCpuText(int index)
    {
        if (_cpuTexts != null && index >= 0 && index < _cpuTexts.Length && _cpuTexts[index] != null) { return _cpuTexts[index]; }
        return "CPU " + index.ToString();
    }

    public void SetCpuText(int index, string value)
    {
        EnsureStringArray(ref _cpuTexts, _logicalCount);
        if (index < 0 || index >= _cpuTexts.Length) { return; }
        _cpuTexts[index] = value ?? String.Empty;
        InvalidateCpu(index);
    }

    public string GetAnnotationText(int index)
    {
        if (_annotations != null && index >= 0 && index < _annotations.Length && _annotations[index] != null) { return _annotations[index]; }
        return String.Empty;
    }

    public void SetAnnotationText(int index, string value)
    {
        EnsureStringArray(ref _annotations, _logicalCount);
        if (index < 0 || index >= _annotations.Length) { return; }
        _annotations[index] = value ?? String.Empty;
        InvalidateCpu(index);
    }

    public int GetCpuCellWidth(int index)
    {
        if (_checkboxWidths != null && index >= 0 && index < _checkboxWidths.Length && _checkboxWidths[index] > 0) { return _checkboxWidths[index]; }
        return TextRenderer.MeasureText(GetCpuText(index), this.Font).Width + 17;
    }

    public Rectangle GetCpuBounds(int index)
    {
        if (index < 0) { return Rectangle.Empty; }
        int maxRows = Math.Max(1, MaxCoresPerColumn);
        int col = index / maxRows;
        int row = index % maxRows;
        int x = 2 + (col * Math.Max(1, ColumnWidth));
        int y = TopPad + (row * Math.Max(1, RowHeight));
        return new Rectangle(x, y, GetCpuCellWidth(index), Math.Max(20, RowHeight - 6));
    }

    public Rectangle GetAnnotationBounds(int index)
    {
        Rectangle cpu = GetCpuBounds(index);
        int offset = GetCpuCellWidth(index) - 3;
        if (_cppcLabelOffsets != null && index >= 0 && index < _cppcLabelOffsets.Length) { offset = _cppcLabelOffsets[index]; }
        return new Rectangle(cpu.Left + offset, cpu.Top + 3, Math.Max(1, CppcLabelWidth), Math.Max(14, cpu.Height - 4));
    }

    public void InvalidateCpu(int index)
    {
        if (index < 0 || index >= _logicalCount || IsDisposed) { return; }
        Rectangle r = GetCpuBounds(index);
        if (CppcEnabled) { r = Rectangle.Union(r, GetAnnotationBounds(index)); }
        r.Inflate(3, 3);
        Invalidate(r);
    }

    protected override void OnMouseMove(MouseEventArgs e)
    {
        base.OnMouseMove(e);
        int idx = HitTest(e.Location);
        Cursor = idx >= 0 ? Cursors.Hand : Cursors.Default;
        if (idx == _hoverIndex) { return; }
        int old = _hoverIndex;
        _hoverIndex = idx;
        if (old >= 0) { InvalidateCpu(old); }
        if (_hoverIndex >= 0) { InvalidateCpu(_hoverIndex); }
    }

    protected override void OnMouseLeave(EventArgs e)
    {
        base.OnMouseLeave(e);
        int old = _hoverIndex;
        _hoverIndex = -1;
        if (old >= 0) { InvalidateCpu(old); }
    }

    protected override void OnMouseDown(MouseEventArgs e)
    {
        base.OnMouseDown(e);
        if (e.Button != MouseButtons.Left) { return; }
        int idx = HitTest(e.Location);
        if (idx < 0 || idx >= _logicalCount) { return; }
        CpuAffinityGridCell cell = _cells[idx];
        if (cell == null || !cell.Enabled || !cell.AutoCheck || !this.Enabled) { return; }
        Focus();
        _focusIndex = idx;
        bool newValue = !GetCpuChecked(idx);
        SetCpuChecked(idx, newValue, true);
        OnMaskChanged(new CpuAffinityGridMaskChangedEventArgs(idx, newValue, _mask));
    }

    protected override bool IsInputKey(Keys keyData)
    {
        Keys key = keyData & Keys.KeyCode;
        if (key == Keys.Up || key == Keys.Down || key == Keys.Left || key == Keys.Right || key == Keys.Home || key == Keys.End) { return true; }
        return base.IsInputKey(keyData);
    }
    protected override void OnKeyDown(KeyEventArgs e)
    {
        base.OnKeyDown(e);
        if (!Enabled || _logicalCount == 0) { return; }
        int next = _focusIndex;
        if (e.KeyCode == Keys.Up) { next--; }
        else if (e.KeyCode == Keys.Down) { next++; }
        else if (e.KeyCode == Keys.Left) { next -= Math.Max(1, MaxCoresPerColumn); }
        else if (e.KeyCode == Keys.Right) { next += Math.Max(1, MaxCoresPerColumn); }
        else if (e.KeyCode == Keys.Home) { next = 0; }
        else if (e.KeyCode == Keys.End) { next = _logicalCount - 1; }
        else if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) {
            CpuAffinityGridCell cell = _cells[_focusIndex];
            if (cell != null && cell.Enabled && cell.AutoCheck) {
                SetCpuChecked(_focusIndex, !GetCpuChecked(_focusIndex), true);
                OnMaskChanged(new CpuAffinityGridMaskChangedEventArgs(_focusIndex, GetCpuChecked(_focusIndex), _mask));
            }
        }
        else { return; }
        _focusIndex = Math.Max(0, Math.Min(_logicalCount - 1, next));
        e.Handled = true; e.SuppressKeyPress = true; Invalidate();
    }
    protected override void OnGotFocus(EventArgs e) { Invalidate(); base.OnGotFocus(e); }
    protected override void OnLostFocus(EventArgs e) { Invalidate(); base.OnLostFocus(e); }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);
        Graphics g = e.Graphics;
        g.Clear(this.BackColor);
        DrawSmtOverlays(g);
        for (int i = 0; i < _logicalCount; i++)
        {
            DrawCpu(g, i);
        }
    }

    private void DrawSmtOverlays(Graphics g)
    {
        if (_smtRects == null || _smtRects.Length == 0) { return; }
        Font f = _overlayFont ?? _annotationFont ?? this.Font;
        using (Pen pen = new Pen(SmtOverlayColor, 1f))
        using (SolidBrush brush = new SolidBrush(SmtOverlayColor))
        {
            for (int i = 0; i < _smtRects.Length; i++)
            {
                g.DrawRectangle(pen, _smtRects[i]);
                if (_smtLabels != null && i < _smtLabels.Length && _smtLabelPoints != null && i < _smtLabelPoints.Length)
                {
                    g.DrawString(_smtLabels[i] ?? String.Empty, f, brush, (float)_smtLabelPoints[i].X, (float)_smtLabelPoints[i].Y);
                }
            }
        }
    }

    private void DrawCpu(Graphics g, int index)
    {
        Rectangle bounds = GetCpuBounds(index);
        CpuAffinityGridCell cell = _cells[index];
        bool selected = GetCpuChecked(index);
        bool hovered = Enabled && cell != null && cell.Enabled && cell.AutoCheck && index == _hoverIndex;
        Color fill = ExovancePalette.CpuFill(selected, hovered);
        Rectangle tile = new Rectangle(bounds.Left, bounds.Top, Math.Max(2, bounds.Width), bounds.Height - 1);
        g.SmoothingMode = SmoothingMode.AntiAlias;
        using (GraphicsPath path = ExovanceVisuals.Round(tile, 5))
        using (SolidBrush brush = new SolidBrush(fill))
        using (Pen edge = new Pen(ExovancePalette.CpuBorder(selected, hovered))) { g.FillPath(brush, path); g.DrawPath(edge, path); }
        int x = tile.Left + 4;
        int y = tile.Top + Math.Max(4, (tile.Height - 9) / 2);
        if (selected)
        {
            using (Pen check = new Pen(ExovancePalette.Accent, 1.7f)) {
                check.StartCap = LineCap.Round; check.EndCap = LineCap.Round;
                g.DrawLines(check, new PointF[] { new PointF(x, y+4), new PointF(x+3, y+7), new PointF(x+8, y+1) });
            }
        }
        else {
            using (Pen box = new Pen(ExovancePalette.Muted)) { g.DrawRectangle(box, x, y, 8, 8); }
        }
        Color textColor = selected ? ExovancePalette.Accent : PCoreColor;
        if (!selected && _isPCore != null && index < _isPCore.Length && !_isPCore[index]) { textColor = ECoreColor; }
        if (!Enabled || cell == null || !cell.Enabled) { textColor = ExovancePalette.Muted; }
        TextRenderer.DrawText(g, GetCpuText(index), Font, new Rectangle(tile.Left + 17, tile.Top, Math.Max(1, tile.Width - 17), tile.Height), textColor, fill,
            TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix);
        if (Focused && ShowFocusCues && index == _focusIndex) { ControlPaint.DrawFocusRectangle(g, Rectangle.Inflate(tile, -2, -2), ExovancePalette.Text, fill); }
        if (CppcEnabled) {
            string annotation = GetAnnotationText(index);
            if (!String.IsNullOrEmpty(annotation)) { TextRenderer.DrawText(g, annotation, _annotationFont ?? Font, GetAnnotationBounds(index), ExovancePalette.Muted, BackColor, TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix); }
        }
    }

    private int HitTest(Point p)
    {
        for (int i = 0; i < _logicalCount; i++)
        {
            if (GetCpuBounds(i).Contains(p)) { return i; }
        }
        return -1;
    }

    private void SetMaskInternal(ulong value, bool raise, int changedIndex)
    {
        _mask = _logicalCount >= 64 ? value : (_logicalCount <= 0 ? 0UL : (value & ((1UL << _logicalCount) - 1UL)));
        for (int i = 0; i < _checked.Length; i++)
        {
            _checked[i] = (i < 64) && ((_mask & (1UL << i)) != 0UL);
        }
        Invalidate();
        if (raise && changedIndex >= 0 && changedIndex < _logicalCount)
        {
            OnMaskChanged(new CpuAffinityGridMaskChangedEventArgs(changedIndex, GetCpuChecked(changedIndex), _mask));
        }
    }

    private void OnMaskChanged(CpuAffinityGridMaskChangedEventArgs e)
    {
        ExovanceInteractionState.MarkChanged();
        EventHandler<CpuAffinityGridMaskChangedEventArgs> handler = MaskChanged;
        if (handler != null) { handler(this, e); }
    }

    private static void EnsureStringArray(ref string[] arr, int length)
    {
        if (length < 0) { length = 0; }
        if (arr == null)
        {
            arr = new string[length];
            return;
        }
        if (arr.Length >= length) { return; }
        string[] resized = new string[length];
        Array.Copy(arr, resized, arr.Length);
        arr = resized;
    }
}


public static class CpuInfo
{
    public const int RelationProcessorCore = 0;
    public const int RelationCache = 2;
    public const int RelationProcessorDie = 5;
    public const int ERROR_INSUFFICIENT_BUFFER = 122;

    [StructLayout(LayoutKind.Sequential)]
    public struct SLPIEX_HEADER
    {
        public int Relationship;
        public int Size;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct GROUP_AFFINITY
    {
        public ulong Mask;
        public ushort Group;
        public ushort Reserved1;
        public uint Reserved2;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESSOR_RELATIONSHIP_FIXED
    {
        public byte Flags;
        public byte EfficiencyClass;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 20)]
        public byte[] Reserved;
        public ushort GroupCount;
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct CACHE_RELATIONSHIP_FIXED
    {
        public byte Level;
        public byte Associativity;
        public ushort LineSize;
        public uint CacheSize;
        public int Type;
        [MarshalAs(UnmanagedType.ByValArray, SizeConst = 18)]
        public byte[] Reserved;
        public ushort GroupCount;
    }

    public sealed class CoreGroupInfo
    {
        public int CoreIndex;
        public byte EfficiencyClass;
        public int[] LogicalProcessors;
    }

    public sealed class CacheGroupInfo
    {
        public byte Level;
        public uint CacheSize;
        public ushort Group;
        public ulong Mask;
        public ushort[] Groups;
        public ulong[] Masks;
        public int[] LogicalProcessors;
    }

    public sealed class DieGroupInfo
    {
        public int DieIndex;
        public ushort Group;
        public ulong Mask;
        public ushort[] Groups;
        public ulong[] Masks;
        public int[] LogicalProcessors;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool GetLogicalProcessorInformationEx(
        int RelationshipType,
        IntPtr Buffer,
        ref int ReturnedLength
    );

    private static int[] ExpandMask(ushort group, ulong mask, int processorCount)
    {
        var result = new List<int>();
        for (int i = 0; i < 64; i++)
        {
            if ((mask & (1UL << i)) == 0)
                continue;

            int globalIndex = (group * 64) + i;
            if (globalIndex >= 0 && globalIndex < processorCount)
            {
                result.Add(globalIndex);
            }
        }
        return result.ToArray();
    }

    private static int[] ExpandMasks(List<GROUP_AFFINITY> masks, int processorCount)
    {
        var result = new SortedSet<int>();
        if (masks != null)
        {
            for (int i = 0; i < masks.Count; i++)
            {
                int[] expanded = ExpandMask(masks[i].Group, masks[i].Mask, processorCount);
                for (int j = 0; j < expanded.Length; j++) { result.Add(expanded[j]); }
            }
        }
        int[] values = new int[result.Count];
        result.CopyTo(values);
        return values;
    }

    private static List<GROUP_AFFINITY> ReadGroupAffinities(IntPtr firstMaskPtr, int groupCount, int groupAffinitySize)
    {
        var masks = new List<GROUP_AFFINITY>();
        if (groupCount <= 0) { return masks; }
        for (int g = 0; g < groupCount; g++)
        {
            IntPtr gaPtr = IntPtr.Add(firstMaskPtr, g * groupAffinitySize);
            var ga = (GROUP_AFFINITY)Marshal.PtrToStructure(gaPtr, typeof(GROUP_AFFINITY));
            if (ga.Mask != 0UL) { masks.Add(ga); }
        }
        return masks;
    }

    private static ushort[] ExtractGroups(List<GROUP_AFFINITY> masks)
    {
        if (masks == null || masks.Count == 0) { return new ushort[0]; }
        ushort[] groups = new ushort[masks.Count];
        for (int i = 0; i < masks.Count; i++) { groups[i] = masks[i].Group; }
        return groups;
    }

    private static ulong[] ExtractMasks(List<GROUP_AFFINITY> masks)
    {
        if (masks == null || masks.Count == 0) { return new ulong[0]; }
        ulong[] values = new ulong[masks.Count];
        for (int i = 0; i < masks.Count; i++) { values[i] = masks[i].Mask; }
        return values;
    }

    private static InvalidOperationException CreateLogicalProcessorInformationException(string relationName, int win32Error, int returnedLength)
    {
        return new InvalidOperationException(String.Format("GetLogicalProcessorInformationEx({0}) failed. Win32Error={1}, ReturnedLength={2}.", relationName, win32Error, returnedLength));
    }

    public static List<CoreGroupInfo> GetProcessorCoreGroups()
    {
        int bufferSize = 0;
        var result = new List<CoreGroupInfo>();
        int processorCount = Environment.ProcessorCount;

        if (!GetLogicalProcessorInformationEx(RelationProcessorCore, IntPtr.Zero, ref bufferSize) &&
            Marshal.GetLastWin32Error() != ERROR_INSUFFICIENT_BUFFER)
        {
            return result;
        }

        IntPtr buffer = Marshal.AllocHGlobal(bufferSize);
        try
        {
            if (!GetLogicalProcessorInformationEx(RelationProcessorCore, buffer, ref bufferSize))
            {
                return result;
            }

            int offset = 0;
            int coreIndex = 0;
            int headerSize = Marshal.SizeOf(typeof(SLPIEX_HEADER));
            int fixedProcSize = Marshal.SizeOf(typeof(PROCESSOR_RELATIONSHIP_FIXED));
            int groupAffinitySize = Marshal.SizeOf(typeof(GROUP_AFFINITY));

            while (offset < bufferSize)
            {
                IntPtr entryPtr = IntPtr.Add(buffer, offset);
                var header = (SLPIEX_HEADER)Marshal.PtrToStructure(entryPtr, typeof(SLPIEX_HEADER));

                if (header.Relationship == RelationProcessorCore)
                {
                    IntPtr procPtr = IntPtr.Add(entryPtr, headerSize);
                    var proc = (PROCESSOR_RELATIONSHIP_FIXED)Marshal.PtrToStructure(procPtr, typeof(PROCESSOR_RELATIONSHIP_FIXED));

                    var logicalProcessors = new List<int>();
                    IntPtr maskPtr = IntPtr.Add(procPtr, fixedProcSize);

                    for (int g = 0; g < proc.GroupCount; g++)
                    {
                        IntPtr gaPtr = IntPtr.Add(maskPtr, g * groupAffinitySize);
                        var ga = (GROUP_AFFINITY)Marshal.PtrToStructure(gaPtr, typeof(GROUP_AFFINITY));
                        logicalProcessors.AddRange(ExpandMask(ga.Group, ga.Mask, processorCount));
                    }

                    result.Add(new CoreGroupInfo
                    {
                        CoreIndex = coreIndex++,
                        EfficiencyClass = proc.EfficiencyClass,
                        LogicalProcessors = logicalProcessors.ToArray()
                    });
                }

                if (header.Size <= 0)
                {
                    break;
                }

                offset += header.Size;
            }
        }
        finally
        {
            Marshal.FreeHGlobal(buffer);
        }

        return result;
    }

    public static Dictionary<int, byte> GetCoreEfficiencyClasses()
    {
        var result = new Dictionary<int, byte>();
        foreach (var core in GetProcessorCoreGroups())
        {
            foreach (int logicalProcessor in core.LogicalProcessors)
            {
                if (!result.ContainsKey(logicalProcessor))
                {
                    result[logicalProcessor] = core.EfficiencyClass;
                }
            }
        }
        return result;
    }

    public static List<DieGroupInfo> GetProcessorDieGroups()
    {
        int bufferSize = 0;
        var result = new List<DieGroupInfo>();
        int processorCount = Environment.ProcessorCount;
        int firstError = 0;

        if (!GetLogicalProcessorInformationEx(RelationProcessorDie, IntPtr.Zero, ref bufferSize))
        {
            firstError = Marshal.GetLastWin32Error();
            if (firstError != ERROR_INSUFFICIENT_BUFFER)
            {
                throw CreateLogicalProcessorInformationException("RelationProcessorDie", firstError, bufferSize);
            }
        }

        if (bufferSize <= 0)
        {
            throw CreateLogicalProcessorInformationException("RelationProcessorDie", firstError, bufferSize);
        }

        IntPtr buffer = Marshal.AllocHGlobal(bufferSize);
        try
        {
            if (!GetLogicalProcessorInformationEx(RelationProcessorDie, buffer, ref bufferSize))
            {
                throw CreateLogicalProcessorInformationException("RelationProcessorDie", Marshal.GetLastWin32Error(), bufferSize);
            }

            int offset = 0;
            int dieIndex = 0;
            int headerSize = Marshal.SizeOf(typeof(SLPIEX_HEADER));
            int fixedProcSize = Marshal.SizeOf(typeof(PROCESSOR_RELATIONSHIP_FIXED));
            int groupAffinitySize = Marshal.SizeOf(typeof(GROUP_AFFINITY));

            while (offset < bufferSize)
            {
                IntPtr entryPtr = IntPtr.Add(buffer, offset);
                var header = (SLPIEX_HEADER)Marshal.PtrToStructure(entryPtr, typeof(SLPIEX_HEADER));

                if (header.Size <= 0)
                {
                    throw new InvalidOperationException(String.Format("GetLogicalProcessorInformationEx(RelationProcessorDie) returned an invalid entry size at offset {0}.", offset));
                }

                if (header.Relationship == RelationProcessorDie)
                {
                    IntPtr procPtr = IntPtr.Add(entryPtr, headerSize);
                    var proc = (PROCESSOR_RELATIONSHIP_FIXED)Marshal.PtrToStructure(procPtr, typeof(PROCESSOR_RELATIONSHIP_FIXED));
                    IntPtr maskPtr = IntPtr.Add(procPtr, fixedProcSize);
                    var masks = ReadGroupAffinities(maskPtr, proc.GroupCount, groupAffinitySize);
                    int[] logicalProcessors = ExpandMasks(masks, processorCount);

                    if (logicalProcessors.Length > 0)
                    {
                        result.Add(new DieGroupInfo
                        {
                            DieIndex = dieIndex++,
                            Group = masks.Count > 0 ? masks[0].Group : (ushort)0,
                            Mask = masks.Count > 0 ? masks[0].Mask : 0UL,
                            Groups = ExtractGroups(masks),
                            Masks = ExtractMasks(masks),
                            LogicalProcessors = logicalProcessors
                        });
                    }
                }

                offset += header.Size;
            }
        }
        finally
        {
            Marshal.FreeHGlobal(buffer);
        }

        if (result.Count == 0)
        {
            throw new InvalidOperationException("GetLogicalProcessorInformationEx(RelationProcessorDie) returned no usable processor-die affinity groups.");
        }

        return result;
    }

    public static List<CacheGroupInfo> GetL3CacheGroups()
    {
        int bufferSize = 0;
        var result = new List<CacheGroupInfo>();
        int processorCount = Environment.ProcessorCount;

        if (!GetLogicalProcessorInformationEx(RelationCache, IntPtr.Zero, ref bufferSize) &&
            Marshal.GetLastWin32Error() != ERROR_INSUFFICIENT_BUFFER)
        {
            return result;
        }

        if (bufferSize <= 0) { return result; }

        IntPtr buffer = Marshal.AllocHGlobal(bufferSize);
        try
        {
            if (!GetLogicalProcessorInformationEx(RelationCache, buffer, ref bufferSize))
            {
                return result;
            }

            int offset = 0;
            int headerSize = Marshal.SizeOf(typeof(SLPIEX_HEADER));
            int fixedCacheSize = Marshal.SizeOf(typeof(CACHE_RELATIONSHIP_FIXED));
            int groupAffinitySize = Marshal.SizeOf(typeof(GROUP_AFFINITY));

            while (offset < bufferSize)
            {
                IntPtr entryPtr = IntPtr.Add(buffer, offset);
                var header = (SLPIEX_HEADER)Marshal.PtrToStructure(entryPtr, typeof(SLPIEX_HEADER));

                if (header.Relationship == RelationCache)
                {
                    IntPtr cachePtr = IntPtr.Add(entryPtr, headerSize);
                    var cache = (CACHE_RELATIONSHIP_FIXED)Marshal.PtrToStructure(cachePtr, typeof(CACHE_RELATIONSHIP_FIXED));

                    if (cache.Level == 3 && cache.CacheSize > 0)
                    {
                        int groupCount = cache.GroupCount > 0 ? cache.GroupCount : 1;
                        IntPtr maskPtr = IntPtr.Add(cachePtr, fixedCacheSize);
                        var masks = ReadGroupAffinities(maskPtr, groupCount, groupAffinitySize);
                        int[] logicalProcessors = ExpandMasks(masks, processorCount);
                        if (logicalProcessors.Length > 0)
                        {
                            result.Add(new CacheGroupInfo
                            {
                                Level = cache.Level,
                                CacheSize = cache.CacheSize,
                                Group = masks.Count > 0 ? masks[0].Group : (ushort)0,
                                Mask = masks.Count > 0 ? masks[0].Mask : 0UL,
                                Groups = ExtractGroups(masks),
                                Masks = ExtractMasks(masks),
                                LogicalProcessors = logicalProcessors
                            });
                        }
                    }
                }

                if (header.Size <= 0)
                {
                    break;
                }

                offset += header.Size;
            }
        }
        finally
        {
            Marshal.FreeHGlobal(buffer);
        }

        return result;
    }
}


public class DarkMode
{
    [DllImport("dwmapi.dll", PreserveSig = true)]
    public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);

    [DllImport("uxtheme.dll", EntryPoint = "#135", CharSet = CharSet.Unicode)]
    public static extern int SetPreferredAppMode(int mode);

    [DllImport("uxtheme.dll", EntryPoint = "#136", CharSet = CharSet.Unicode)]
    public static extern void FlushMenuThemes();

    // DWMWA_USE_IMMERSIVE_DARK_MODE
    public const int DWMWA_USE_IMMERSIVE_DARK_MODE_BEFORE_20H1 = 19;
    public const int DWMWA_USE_IMMERSIVE_DARK_MODE = 20;

    // App mode values
    public const int APPMODE_DEFAULT = 0;
    public const int APPMODE_ALLOWDARK = 1;
    public const int APPMODE_FORCEDARK = 2;
    public const int APPMODE_FORCELIGHT = 3;

    public static bool EnableDarkModeForWindow(IntPtr hwnd)
    {
        int darkMode = 1;
        int attr = DWMWA_USE_IMMERSIVE_DARK_MODE;

        // Try the newer attribute first (Windows 10 20H1+)
        int result = DwmSetWindowAttribute(hwnd, attr, ref darkMode, sizeof(int));

        // Fall back to older attribute for older Windows 10 versions
        if (result != 0)
        {
            attr = DWMWA_USE_IMMERSIVE_DARK_MODE_BEFORE_20H1;
            result = DwmSetWindowAttribute(hwnd, attr, ref darkMode, sizeof(int));
        }

        return result == 0;
    }

    public static void EnableDarkModeForApp()
    {
        SetPreferredAppMode(APPMODE_FORCEDARK);
        FlushMenuThemes();
    }
}


public class WheelMessageFilter : IMessageFilter
{
    private const int WM_MOUSEWHEEL = 0x020A;
    private const int WM_MOUSEHWHEEL = 0x020E;
    private IntPtr _targetHwnd = IntPtr.Zero;
    private Control _targetControl;
    private Control _scopeControl;
    private Control _ownerControl;
    private bool _sending;

    public static bool SuspendRedirect = false;

    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

    [DllImport("user32.dll")]
    private static extern IntPtr WindowFromPoint(Point point);

    public void SetTarget(IntPtr hwnd) { _targetHwnd = hwnd; }

    public void SetTarget(Control target, Control scope, Control owner)
    {
        _targetControl = target;
        _scopeControl = scope;
        _ownerControl = owner;
        _targetHwnd = target != null && !target.IsDisposed && target.IsHandleCreated ? target.Handle : IntPtr.Zero;
    }

    private static int GetWheelDelta(IntPtr wParam)
    {
        long value = wParam.ToInt64();
        return (short)((value >> 16) & 0xFFFF);
    }

    private static Point GetScreenPoint(IntPtr lParam)
    {
        long value = lParam.ToInt64();
        return new Point((short)(value & 0xFFFF), (short)((value >> 16) & 0xFFFF));
    }

    private static bool IsScreenPointInsideControl(Control control, Point screenPoint)
    {
        if (control == null || control.IsDisposed || !control.IsHandleCreated) { return false; }
        Point clientPoint = control.PointToClient(screenPoint);
        return control.ClientRectangle.Contains(clientPoint);
    }

    private static bool IsDescendantOrSame(Control control, Control ancestor)
    {
        if (control == null || ancestor == null) { return false; }
        Control c = control;
        int guard = 0;
        while (c != null && guard++ < 128)
        {
            if (Object.ReferenceEquals(c, ancestor)) { return true; }
            c = c.Parent;
        }
        return false;
    }

    private bool IsInsideRedirectScope(Point screenPoint)
    {
        if (IsScreenPointInsideControl(_scopeControl, screenPoint)) { return true; }
        if (_scopeControl == null && IsScreenPointInsideControl(_ownerControl, screenPoint)) { return true; }
        IntPtr hwnd = WindowFromPoint(screenPoint);
        if (hwnd == IntPtr.Zero) { return false; }
        Control control = Control.FromChildHandle(hwnd);
        if (control == null) { control = Control.FromHandle(hwnd); }
        return IsDescendantOrSame(control, _scopeControl) || (_scopeControl == null && IsDescendantOrSame(control, _ownerControl)) || IsDescendantOrSame(control, _targetControl);
    }

    public bool PreFilterMessage(ref Message m)
    {
        if ((m.Msg != WM_MOUSEWHEEL && m.Msg != WM_MOUSEHWHEEL) || _sending || SuspendRedirect) { return false; }
        Point screenPoint = GetScreenPoint(m.LParam);
        if (m.Msg == WM_MOUSEHWHEEL)
        {
            return DeviceEditorNativeUiSupport.TryHandleMouseHWheelAtScreenPoint(screenPoint, GetWheelDelta(m.WParam));
        }
        if (_targetHwnd == IntPtr.Zero || !IsInsideRedirectScope(screenPoint)) { return false; }
        _sending = true;
        try
        {
            SendMessage(_targetHwnd, m.Msg, m.WParam, m.LParam);
        }
        finally
        {
            _sending = false;
        }
        return true;
    }
}

public sealed class LowLatencyUiTicker : IDisposable
{
    private readonly Control _control;
    private readonly MethodInvoker _tick;
    private readonly IntPtr _timerHandle;
    private readonly IntPtr _stopEventHandle;
    private readonly Thread _thread;
    private readonly object _gate;
    private int _running;
    private int _posted;
    private int _disposed;
    private int _periodMs;

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CreateWaitableTimerExW(IntPtr lpTimerAttributes, string lpTimerName, uint dwFlags, uint dwDesiredAccess);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool SetWaitableTimerEx(IntPtr hTimer, ref long lpDueTime, int lPeriod, IntPtr pfnCompletionRoutine, IntPtr lpArgToCompletionRoutine, IntPtr wakeContext, uint tolerableDelay);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool CancelWaitableTimer(IntPtr hTimer);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint WaitForMultipleObjects(uint nCount, IntPtr[] lpHandles, bool bWaitAll, uint dwMilliseconds);

    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
    private static extern IntPtr CreateEventW(IntPtr lpEventAttributes, bool bManualReset, bool bInitialState, string lpName);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool SetEvent(IntPtr hEvent);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool ResetEvent(IntPtr hEvent);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool CloseHandle(IntPtr hObject);

    private const uint CREATE_WAITABLE_TIMER_HIGH_RESOLUTION = 0x00000002;
    private const uint TIMER_ALL_ACCESS = 0x001F0003;
    private const uint WAIT_OBJECT_0 = 0x00000000;
    private const uint WAIT_FAILED = 0xFFFFFFFF;
    private const uint INFINITE = 0xFFFFFFFF;

    public LowLatencyUiTicker(Control control, MethodInvoker tick, int periodMs)
    {
        if (control == null) throw new ArgumentNullException("control");
        if (tick == null) throw new ArgumentNullException("tick");
        _control = control;
        _tick = tick;
        _periodMs = NormalizePeriod(periodMs);
        _gate = new object();
        _timerHandle = CreateWaitableTimerExW(IntPtr.Zero, null, CREATE_WAITABLE_TIMER_HIGH_RESOLUTION, TIMER_ALL_ACCESS);
        if (_timerHandle == IntPtr.Zero)
        {
            int error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error, "CreateWaitableTimerExW(CREATE_WAITABLE_TIMER_HIGH_RESOLUTION) failed for LowLatencyUiTicker: periodMs=" + _periodMs.ToString(CultureInfo.InvariantCulture) + ", lastError=" + error.ToString(CultureInfo.InvariantCulture));
        }
        _stopEventHandle = CreateEventW(IntPtr.Zero, true, false, null);
        if (_stopEventHandle == IntPtr.Zero)
        {
            int error = Marshal.GetLastWin32Error();
            Win32Exception createEventFailure = new Win32Exception(error, "CreateEventW failed for LowLatencyUiTicker stop gate: lastError=" + error.ToString(CultureInfo.InvariantCulture));
            if (!CloseHandle(_timerHandle))
            {
                int closeError = Marshal.GetLastWin32Error();
                throw new AggregateException(createEventFailure, new Win32Exception(closeError, "CloseHandle(timer) failed after CreateEventW failure: timerHandle=0x" + _timerHandle.ToInt64().ToString("X", CultureInfo.InvariantCulture) + ", lastError=" + closeError.ToString(CultureInfo.InvariantCulture)));
            }
            throw createEventFailure;
        }
        _thread = new Thread(TimerThreadProc);
        _thread.IsBackground = true;
        _thread.Priority = ThreadPriority.Highest;
        _thread.Name = "DeviceTweaker.LowLatencyUiTicker";
        _thread.Start();
    }

    public bool IsRunning { get { return Volatile.Read(ref _running) == 1; } }

    public int PeriodMs
    {
        get { return Volatile.Read(ref _periodMs); }
        set
        {
            int v = NormalizePeriod(value);
            Volatile.Write(ref _periodMs, v);
            if (IsRunning) { ArmTimer(v); }
        }
    }

    public void Start()
    {
        if (Volatile.Read(ref _disposed) == 1) return;
        if (Interlocked.Exchange(ref _running, 1) == 1) return;
        if (!ResetEvent(_stopEventHandle))
        {
            int error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error, "ResetEvent failed while starting LowLatencyUiTicker: lastError=" + error.ToString(CultureInfo.InvariantCulture));
        }
        ArmTimer(PeriodMs);
    }

    public void Stop()
    {
        if (Interlocked.Exchange(ref _running, 0) == 0) return;
        if (!CancelWaitableTimer(_timerHandle))
        {
            int error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error, "CancelWaitableTimer failed while stopping LowLatencyUiTicker: lastError=" + error.ToString(CultureInfo.InvariantCulture));
        }
        Interlocked.Exchange(ref _posted, 0);
        if (!SetEvent(_stopEventHandle))
        {
            int error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error, "SetEvent failed while stopping LowLatencyUiTicker: lastError=" + error.ToString(CultureInfo.InvariantCulture));
        }
    }

    private static int NormalizePeriod(int periodMs)
    {
        if (periodMs < 1) return 1;
        if (periodMs > 8) return 8;
        return periodMs;
    }

    private void ArmTimer(int periodMs)
    {
        lock (_gate)
        {
            if (Volatile.Read(ref _disposed) == 1) return;
            long dueTime = -Math.Max(1L, (long)periodMs) * 10000L;
            if (!SetWaitableTimerEx(_timerHandle, ref dueTime, periodMs, IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, 0))
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(error, "SetWaitableTimerEx failed for LowLatencyUiTicker: periodMs=" + periodMs.ToString(CultureInfo.InvariantCulture) + ", dueTime100ns=" + dueTime.ToString(CultureInfo.InvariantCulture) + ", lastError=" + error.ToString(CultureInfo.InvariantCulture));
            }
        }
    }

    private void TimerThreadProc()
    {
        IntPtr[] handles = new IntPtr[] { _timerHandle, _stopEventHandle };
        while (Volatile.Read(ref _disposed) == 0)
        {
            uint wait = WaitForMultipleObjects(2, handles, false, INFINITE);
            if (wait == WAIT_FAILED)
            {
                int error = Marshal.GetLastWin32Error();
                throw new Win32Exception(error, "WaitForMultipleObjects failed in LowLatencyUiTicker: lastError=" + error.ToString(CultureInfo.InvariantCulture));
            }
            if (Volatile.Read(ref _disposed) == 1) break;
            if (wait == WAIT_OBJECT_0)
            {
                OnTimerSignal();
            }
            else if (wait == WAIT_OBJECT_0 + 1)
            {
                ResetEvent(_stopEventHandle);
            }
            else
            {
                throw new InvalidOperationException("Unexpected wait result in LowLatencyUiTicker: wait=0x" + wait.ToString("X", CultureInfo.InvariantCulture));
            }
        }
    }

    private void OnTimerSignal()
    {
        if (Volatile.Read(ref _running) != 1) return;
        if (Volatile.Read(ref _disposed) == 1) return;
        if (Interlocked.Exchange(ref _posted, 1) == 1) return;
        try
        {
            if (_control.IsDisposed || !_control.IsHandleCreated)
            {
                Interlocked.Exchange(ref _posted, 0);
                return;
            }
            _control.BeginInvoke((MethodInvoker)OnUiTick);
        }
        catch (InvalidOperationException)
        {
            Interlocked.Exchange(ref _posted, 0);
            if (!_control.IsDisposed) { throw; }
        }
        catch (Exception ex)
        {
            Interlocked.Exchange(ref _posted, 0);
            throw new InvalidOperationException("LowLatencyUiTicker failed to marshal a frame to the UI thread.", ex);
        }
    }

    private void OnUiTick()
    {
        Interlocked.Exchange(ref _posted, 0);
        if (Volatile.Read(ref _running) != 1) return;
        if (Volatile.Read(ref _disposed) == 1) return;
        try
        {
            _tick();
        }
        catch (Exception ex)
        {
            throw new InvalidOperationException("LowLatencyUiTicker UI frame callback failed.", ex);
        }
    }

    public void Dispose()
    {
        if (Interlocked.Exchange(ref _disposed, 1) == 1) return;
        List<Exception> failures = new List<Exception>();
        if (Volatile.Read(ref _running) == 1)
        {
            try { Stop(); } catch (Exception ex) { failures.Add(ex); }
        }
        else
        {
            if (!SetEvent(_stopEventHandle))
            {
                int error = Marshal.GetLastWin32Error();
                failures.Add(new Win32Exception(error, "SetEvent failed while disposing LowLatencyUiTicker: lastError=" + error.ToString(CultureInfo.InvariantCulture)));
            }
        }
        if (!_thread.Join(250))
        {
            failures.Add(new TimeoutException("LowLatencyUiTicker timer thread did not exit within 250 ms during Dispose."));
        }
        if (_timerHandle != IntPtr.Zero && !CloseHandle(_timerHandle))
        {
            int error = Marshal.GetLastWin32Error();
            failures.Add(new Win32Exception(error, "CloseHandle(timer) failed while disposing LowLatencyUiTicker: timerHandle=0x" + _timerHandle.ToInt64().ToString("X", CultureInfo.InvariantCulture) + ", lastError=" + error.ToString(CultureInfo.InvariantCulture)));
        }
        if (_stopEventHandle != IntPtr.Zero && !CloseHandle(_stopEventHandle))
        {
            int error = Marshal.GetLastWin32Error();
            failures.Add(new Win32Exception(error, "CloseHandle(stopEvent) failed while disposing LowLatencyUiTicker: stopEventHandle=0x" + _stopEventHandle.ToInt64().ToString("X", CultureInfo.InvariantCulture) + ", lastError=" + error.ToString(CultureInfo.InvariantCulture)));
        }
        if (failures.Count == 1) { throw failures[0]; }
        if (failures.Count > 1) { throw new AggregateException("LowLatencyUiTicker Dispose encountered multiple failures.", failures); }
    }
}

public static class ScrollHelper {
    [StructLayout(LayoutKind.Sequential)]
    private struct RECT {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;

        public RECT(int left, int top, int right, int bottom) {
            Left = left;
            Top = top;
            Right = right;
            Bottom = bottom;
        }
    }

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool RedrawWindow(IntPtr hWnd, IntPtr lprcUpdate, IntPtr hrgnUpdate, uint flags);
    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool RedrawWindow(IntPtr hWnd, ref RECT lprcUpdate, IntPtr hrgnUpdate, uint flags);
    [DllImport("user32.dll", EntryPoint = "GetWindowLong", SetLastError = true)]
    private static extern int GetWindowLong32(IntPtr hWnd, int nIndex);
    [DllImport("user32.dll", EntryPoint = "SetWindowLong", SetLastError = true)]
    private static extern int SetWindowLong32(IntPtr hWnd, int nIndex, int dwNewLong);
    [DllImport("user32.dll", EntryPoint = "GetWindowLongPtr", SetLastError = true)]
    private static extern IntPtr GetWindowLongPtr64(IntPtr hWnd, int nIndex);
    [DllImport("user32.dll", EntryPoint = "SetWindowLongPtr", SetLastError = true)]
    private static extern IntPtr SetWindowLongPtr64(IntPtr hWnd, int nIndex, IntPtr dwNewLong);
    [DllImport("user32.dll", SetLastError = true)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

    private const uint RDW_INVALIDATE   = 0x0001;
    private const uint RDW_ERASE        = 0x0004;
    private const uint RDW_NOERASE      = 0x0020;
    private const uint RDW_ALLCHILDREN  = 0x0080;
    private const uint RDW_UPDATENOW    = 0x0100;
    private const uint RDW_FRAME        = 0x0400;
    private const int  GWL_EXSTYLE      = -20;
    private const int  WS_EX_COMPOSITED = 0x02000000;
    private const int  WM_SETREDRAW     = 0x000B;

    private static IntPtr GetWindowLongPtrSafe(IntPtr hWnd, int nIndex) {
        if (IntPtr.Size == 8) return GetWindowLongPtr64(hWnd, nIndex);
        return new IntPtr(GetWindowLong32(hWnd, nIndex));
    }

    private static IntPtr SetWindowLongPtrSafe(IntPtr hWnd, int nIndex, IntPtr value) {
        if (IntPtr.Size == 8) return SetWindowLongPtr64(hWnd, nIndex, value);
        return new IntPtr(SetWindowLong32(hWnd, nIndex, value.ToInt32()));
    }

    public static void SetRedraw(IntPtr hwnd, bool enabled) {
        if (hwnd == IntPtr.Zero) return;
        SendMessage(hwnd, WM_SETREDRAW, enabled ? new IntPtr(1) : IntPtr.Zero, IntPtr.Zero);
    }

    private static void RedrawConstructionWindow(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return;
        uint flags = RDW_INVALIDATE | RDW_ERASE | RDW_FRAME | RDW_ALLCHILDREN | RDW_UPDATENOW;
        if (!RedrawWindow(hwnd, IntPtr.Zero, IntPtr.Zero, flags)) {
            int error = Marshal.GetLastWin32Error();
            throw new Win32Exception(error, "RedrawWindow failed after WM_SETREDRAW(true): hwnd=0x" + hwnd.ToInt64().ToString("X") + ", flags=0x" + flags.ToString("X") + ", lastError=" + error.ToString(CultureInfo.InvariantCulture));
        }
    }

    public static bool BeginConstructionRedraw(Control control) {
        if (control == null || control.IsDisposed || !control.IsHandleCreated) return false;
        SetRedraw(control.Handle, false);
        return true;
    }

    public static void EndConstructionRedraw(Control control, bool armed) {
        if (!armed) return;
        if (control == null || control.IsDisposed || !control.IsHandleCreated) return;
        IntPtr hwnd = control.Handle;
        SetRedraw(hwnd, true);
        RedrawConstructionWindow(hwnd);
    }

    private static readonly System.Reflection.PropertyInfo DoubleBufferedProperty = typeof(Control).GetProperty(
        "DoubleBuffered",
        System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic
    );

    public static void EnableDoubleBuffer(Control control) {
        if (control == null || control.IsDisposed) return;
        try {
            if (DoubleBufferedProperty != null) DoubleBufferedProperty.SetValue(control, true, null);
        } catch { }
    }

    public static void EnableDoubleBufferRecursive(Control root) {
        if (root == null || root.IsDisposed) return;
        EnableDoubleBuffer(root);
        foreach (Control child in root.Controls) {
            EnableDoubleBufferRecursive(child);
        }
    }

    public static void EnableComposited(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return;
        DisableComposited(hwnd);
    }

    public static void DisableComposited(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return;
        IntPtr exPtr = GetWindowLongPtrSafe(hwnd, GWL_EXSTYLE);
        long ex = exPtr.ToInt64();
        if ((ex & WS_EX_COMPOSITED) != 0) {
            SetWindowLongPtrSafe(hwnd, GWL_EXSTYLE, new IntPtr(ex & ~((long)WS_EX_COMPOSITED)));
        }
    }

    public static void FlushPaint(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return;
        RedrawWindow(hwnd, IntPtr.Zero, IntPtr.Zero, RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
    }

    public static void ScrollPaint(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return;
        RedrawWindow(hwnd, IntPtr.Zero, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
    }

    public static void ScrollPaintAtomic(IntPtr viewportHwnd, IntPtr innerHwnd, IntPtr trackHwnd) {
        // Repaint through the viewport, not the entire oversized inner panel. Redrawing the full
        // inner surface is correct but can traverse thousands of off-screen child HWNDs. The parent
        // viewport clips this to what is actually visible.
        if (viewportHwnd != IntPtr.Zero) {
            RedrawWindow(viewportHwnd, IntPtr.Zero, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
        }
        else if (innerHwnd != IntPtr.Zero) {
            RedrawWindow(innerHwnd, IntPtr.Zero, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
        }
        if (trackHwnd != IntPtr.Zero) {
            RedrawWindow(trackHwnd, IntPtr.Zero, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
        }
    }

    public static void ScrollPaintTrack(IntPtr trackHwnd) {
        if (trackHwnd == IntPtr.Zero) return;
        RedrawWindow(trackHwnd, IntPtr.Zero, IntPtr.Zero, RDW_INVALIDATE | RDW_ALLCHILDREN | RDW_NOERASE);
    }

    public static void ScrollPaintVisible(IntPtr hwnd, int viewportTop, int viewportHeight, int viewportWidth, int overscan) {
        if (hwnd == IntPtr.Zero || viewportHeight <= 0 || viewportWidth <= 0) return;
        int pad = overscan < 0 ? 0 : overscan;
        int top = viewportTop - pad;
        if (top < 0) top = 0;
        int bottom = viewportTop + viewportHeight + pad;
        if (bottom <= top) bottom = top + Math.Max(1, viewportHeight);
        RECT dirty = new RECT(0, top, viewportWidth, bottom);
        RedrawWindow(hwnd, ref dirty, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
    }

    // Band repaint for small deltas; falls back to a full visible repaint on large jumps.
    public static void ScrollPaintSmart(IntPtr hwnd, int previousViewportTop, int viewportTop, int viewportHeight, int viewportWidth, int overscan) {
        if (hwnd == IntPtr.Zero || viewportHeight <= 0 || viewportWidth <= 0) return;

        int newTop = viewportTop;
        int newBottom = viewportTop + viewportHeight;
        int oldTop = previousViewportTop;
        int delta = newTop - oldTop;
        int pad = overscan < 0 ? 0 : overscan;
        RECT dirty;

        if (oldTop < 0 || delta == 0 || Math.Abs(delta) >= viewportHeight) {
            dirty = new RECT(0, newTop, viewportWidth, newBottom);
        }
        else if (delta > 0) {
            dirty = new RECT(0, oldTop + viewportHeight - pad, viewportWidth, newBottom + pad);
        }
        else {
            dirty = new RECT(0, newTop - pad, viewportWidth, oldTop + pad);
        }

        if (dirty.Top < newTop) dirty.Top = newTop;
        if (dirty.Bottom > newBottom) dirty.Bottom = newBottom;
        if (dirty.Bottom <= dirty.Top) dirty = new RECT(0, newTop, viewportWidth, newBottom);

        RedrawWindow(hwnd, ref dirty, IntPtr.Zero, RDW_INVALIDATE | RDW_UPDATENOW | RDW_ALLCHILDREN | RDW_NOERASE);
    }
}

[StructLayout(LayoutKind.Sequential)]
public struct SCROLLINFO {
    public int  cbSize;
    public uint fMask;
    public int  nMin;
    public int  nMax;
    public uint nPage;
    public int  nPos;
    public int  nTrackPos;
}

public static class HScrollHelper {
    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool GetScrollInfo(IntPtr hwnd, int nBar, ref SCROLLINFO lpsi);
    [DllImport("user32.dll", SetLastError = true)]
    private static extern int SetScrollInfo(IntPtr hwnd, int nBar, ref SCROLLINFO lpsi, bool redraw);
    [DllImport("user32.dll", CharSet = CharSet.Auto)]
    private static extern IntPtr SendMessage(IntPtr hWnd, int Msg, IntPtr wParam, IntPtr lParam);

    private const int SB_HORZ = 0;
    private const uint SIF_ALL = 0x17;
    private const uint SIF_POS = 0x4;
    private const int WM_HSCROLL = 0x0114;
    private const int SB_THUMBPOSITION = 4;
    private const int SB_THUMBTRACK = 5;
    private const int SB_ENDSCROLL = 8;

    public static int[] GetHScrollInfo(IntPtr hwnd) {
        if (hwnd == IntPtr.Zero) return new int[] { 0, 0, 0, 0, 0 };
        SCROLLINFO si = new SCROLLINFO();
        si.cbSize = Marshal.SizeOf(typeof(SCROLLINFO));
        si.fMask = SIF_ALL;
        if (!GetScrollInfo(hwnd, SB_HORZ, ref si))
            return new int[] { 0, 0, 0, 0, 0 };
        return new int[] { si.nMin, si.nMax, (int)si.nPage, si.nPos, si.nTrackPos };
    }

    public static void SetHScrollPos(IntPtr hwnd, int pos) {
        SetHScrollPos(hwnd, pos, false);
    }

    public static void SetHScrollPos(IntPtr hwnd, int pos, bool tracking) {
        if (hwnd == IntPtr.Zero) return;
        SCROLLINFO all = new SCROLLINFO();
        all.cbSize = Marshal.SizeOf(typeof(SCROLLINFO));
        all.fMask = SIF_ALL;
        if (GetScrollInfo(hwnd, SB_HORZ, ref all)) {
            int min = all.nMin;
            int max = all.nMax - Math.Max(0, (int)all.nPage - 1);
            if (max < min) max = min;
            if (pos < min) pos = min;
            if (pos > max) pos = max;
        }
        SCROLLINFO si = new SCROLLINFO();
        si.cbSize = Marshal.SizeOf(typeof(SCROLLINFO));
        si.fMask = SIF_POS;
        si.nPos = pos;
        SetScrollInfo(hwnd, SB_HORZ, ref si, true);
        int code = tracking ? SB_THUMBTRACK : SB_THUMBPOSITION;
        int wParam = code | ((pos & 0xFFFF) << 16);
        SendMessage(hwnd, WM_HSCROLL, (IntPtr)wParam, IntPtr.Zero);
        if (!tracking) { SendMessage(hwnd, WM_HSCROLL, (IntPtr)SB_ENDSCROLL, IntPtr.Zero); }
    }
}


