public sealed class DeviceRegistryKeyStateView
{
    private readonly DeviceRegistryState state;
    private readonly string viewKind;

    public DeviceRegistryKeyStateView(DeviceRegistryState state, string viewKind)
    {
        this.state = state;
        this.viewKind = String.IsNullOrEmpty(viewKind) ? String.Empty : viewKind;
    }

    public object GetValue(string name, object defaultValue)
    {
        if (state == null || String.IsNullOrEmpty(name)) { return defaultValue; }

        if (String.Equals(viewKind, "Base", StringComparison.OrdinalIgnoreCase))
        {
            if (String.Equals(name, "*RssBaseProcNumber", StringComparison.OrdinalIgnoreCase)) { return state.HasRssBaseProcNumber ? state.RssBaseProcNumber : defaultValue; }
            if (String.Equals(name, "*NumRssQueues", StringComparison.OrdinalIgnoreCase)) { return state.HasNumRssQueues ? state.NumRssQueues : defaultValue; }
            return defaultValue;
        }

        if (String.Equals(viewKind, "AffinityPolicy", StringComparison.OrdinalIgnoreCase))
        {
            if (String.Equals(name, "AssignmentSetOverride", StringComparison.OrdinalIgnoreCase)) { return state.HasAssignmentSetOverride ? state.AssignmentSetOverride : defaultValue; }
            if (String.Equals(name, "DevicePolicy", StringComparison.OrdinalIgnoreCase)) { return state.HasDevicePolicy ? state.DevicePolicy : defaultValue; }
            if (String.Equals(name, "DevicePriority", StringComparison.OrdinalIgnoreCase)) { return state.HasDevicePriority ? state.DevicePriority : defaultValue; }
            return defaultValue;
        }

        if (String.Equals(viewKind, "Msi", StringComparison.OrdinalIgnoreCase))
        {
            if (String.Equals(name, "MSISupported", StringComparison.OrdinalIgnoreCase)) { return state.HasMsiSupported ? state.MsiSupported : defaultValue; }
            if (String.Equals(name, "MessageNumberLimit", StringComparison.OrdinalIgnoreCase)) { return state.HasMessageNumberLimit ? state.MessageNumberLimit : defaultValue; }
            return defaultValue;
        }

        return defaultValue;
    }

    public void Close()
    {
    }
}

public static class DeviceTweakerRegistrySnapshot
{
    private const string AffinityPolicySubkey = @"Device Parameters\Interrupt Management\Affinity Policy";
    private const string MsiSubkey = @"Device Parameters\Interrupt Management\MessageSignaledInterruptProperties";

    public static Dictionary<string, DeviceRegistryState> ReadDeviceRegistryStates(IEnumerable<string> registryPaths)
    {
        Dictionary<string, DeviceRegistryState> result = new Dictionary<string, DeviceRegistryState>(StringComparer.OrdinalIgnoreCase);
        if (registryPaths == null) { return result; }

        Dictionary<string, string> uniqueRelativePaths = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (string rawPath in registryPaths)
        {
            if (String.IsNullOrWhiteSpace(rawPath)) { continue; }
            string originalPath = NormalizePathSeparators(rawPath);
            string relativePath = ToRelativeRegistryPath(originalPath);
            if (String.IsNullOrWhiteSpace(relativePath)) { continue; }
            if (!uniqueRelativePaths.ContainsKey(relativePath)) { uniqueRelativePaths.Add(relativePath, originalPath); }
        }

        if (uniqueRelativePaths.Count == 0) { return result; }

        Microsoft.Win32.RegistryKey hklm = null;
        Dictionary<string, Microsoft.Win32.RegistryKey> baseKeyCache = new Dictionary<string, Microsoft.Win32.RegistryKey>(StringComparer.OrdinalIgnoreCase);
        List<Microsoft.Win32.RegistryKey> openedKeys = new List<Microsoft.Win32.RegistryKey>();

        try
        {
            hklm = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Default);
            foreach (KeyValuePair<string, string> pair in uniqueRelativePaths)
            {
                DeviceRegistryState state = ReadSingleState(hklm, pair.Key, pair.Value, baseKeyCache, openedKeys);
                AddStateAliases(result, state);
            }
        }
        finally
        {
            for (int i = openedKeys.Count - 1; i >= 0; i--)
            {
                try { if (openedKeys[i] != null) { openedKeys[i].Close(); } } catch { }
            }
            try { if (hklm != null) { hklm.Close(); } } catch { }
        }

        return result;
    }

    private static DeviceRegistryState ReadSingleState(
        Microsoft.Win32.RegistryKey hklm,
        string relativePath,
        string originalPath,
        Dictionary<string, Microsoft.Win32.RegistryKey> baseKeyCache,
        List<Microsoft.Win32.RegistryKey> openedKeys)
    {
        DeviceRegistryState state = new DeviceRegistryState();
        state.RegistryPath = originalPath;
        state.RelativePath = relativePath;

        Microsoft.Win32.RegistryKey baseKey = GetCachedBaseKey(hklm, relativePath, baseKeyCache, openedKeys);
        state.BaseKeyExists = (baseKey != null);
        if (baseKey == null) { return state; }

        object value;
        if (TryReadRegistryValue(baseKey, "*RssBaseProcNumber", out value)) { state.HasRssBaseProcNumber = true; state.RssBaseProcNumber = value; }
        if (TryReadRegistryValue(baseKey, "*NumRssQueues", out value)) { state.HasNumRssQueues = true; state.NumRssQueues = value; }

        Microsoft.Win32.RegistryKey affinityKey = null;
        try
        {
            affinityKey = baseKey.OpenSubKey(AffinityPolicySubkey, false);
            state.AffinityPolicyKeyExists = (affinityKey != null);
            if (affinityKey != null)
            {
                if (TryReadRegistryValue(affinityKey, "AssignmentSetOverride", out value)) { state.HasAssignmentSetOverride = true; state.AssignmentSetOverride = value; }
                if (TryReadRegistryValue(affinityKey, "DevicePolicy", out value)) { state.HasDevicePolicy = true; state.DevicePolicy = value; }
                if (TryReadRegistryValue(affinityKey, "DevicePriority", out value)) { state.HasDevicePriority = true; state.DevicePriority = value; }
            }
        }
        catch (System.Security.SecurityException) { }
        catch (UnauthorizedAccessException) { }
        catch (System.IO.IOException) { }
        finally
        {
            try { if (affinityKey != null) { affinityKey.Close(); } } catch { }
        }

        Microsoft.Win32.RegistryKey msiKey = null;
        try
        {
            msiKey = baseKey.OpenSubKey(MsiSubkey, false);
            state.MsiKeyExists = (msiKey != null);
            if (msiKey != null)
            {
                if (TryReadRegistryValue(msiKey, "MSISupported", out value)) { state.HasMsiSupported = true; state.MsiSupported = value; }
                if (TryReadRegistryValue(msiKey, "MessageNumberLimit", out value)) { state.HasMessageNumberLimit = true; state.MessageNumberLimit = value; }
            }
        }
        catch (System.Security.SecurityException) { }
        catch (UnauthorizedAccessException) { }
        catch (System.IO.IOException) { }
        finally
        {
            try { if (msiKey != null) { msiKey.Close(); } } catch { }
        }

        return state;
    }

    private static Microsoft.Win32.RegistryKey GetCachedBaseKey(
        Microsoft.Win32.RegistryKey hklm,
        string relativePath,
        Dictionary<string, Microsoft.Win32.RegistryKey> baseKeyCache,
        List<Microsoft.Win32.RegistryKey> openedKeys)
    {
        Microsoft.Win32.RegistryKey key;
        if (baseKeyCache.TryGetValue(relativePath, out key)) { return key; }

        key = null;
        if (hklm != null && !String.IsNullOrWhiteSpace(relativePath))
        {
            try { key = hklm.OpenSubKey(relativePath, false); }
            catch (System.Security.SecurityException) { key = null; }
            catch (UnauthorizedAccessException) { key = null; }
            catch (System.IO.IOException) { key = null; }
        }

        baseKeyCache[relativePath] = key;
        if (key != null) { openedKeys.Add(key); }
        return key;
    }

    private static bool TryReadRegistryValue(Microsoft.Win32.RegistryKey key, string valueName, out object value)
    {
        value = null;
        if (key == null) { return false; }
        try
        {
            value = key.GetValue(valueName, null);
            return value != null;
        }
        catch (System.Security.SecurityException) { value = null; return false; }
        catch (UnauthorizedAccessException) { value = null; return false; }
        catch (System.IO.IOException) { value = null; return false; }
    }

    private static void AddStateAliases(Dictionary<string, DeviceRegistryState> result, DeviceRegistryState state)
    {
        if (result == null || state == null || String.IsNullOrWhiteSpace(state.RelativePath)) { return; }
        AddStateAlias(result, state.RegistryPath, state);
        AddStateAlias(result, state.RelativePath, state);
        AddStateAlias(result, @"HKLM:\" + state.RelativePath, state);
        AddStateAlias(result, @"HKLM\" + state.RelativePath, state);
        AddStateAlias(result, @"HKEY_LOCAL_MACHINE\" + state.RelativePath, state);
        AddStateAlias(result, @"Microsoft.PowerShell.Core\Registry::HKEY_LOCAL_MACHINE\" + state.RelativePath, state);
        AddStateAlias(result, @"Registry::HKEY_LOCAL_MACHINE\" + state.RelativePath, state);
    }

    private static void AddStateAlias(Dictionary<string, DeviceRegistryState> result, string alias, DeviceRegistryState state)
    {
        if (String.IsNullOrWhiteSpace(alias)) { return; }
        result[NormalizePathSeparators(alias)] = state;
    }

    private static string ToRelativeRegistryPath(string rawPath)
    {
        if (String.IsNullOrWhiteSpace(rawPath)) { return null; }
        string path = NormalizePathSeparators(rawPath);
        if (String.IsNullOrWhiteSpace(path)) { return null; }

        path = Regex.Replace(path, @"^(?i:Microsoft\.PowerShell\.Core\\Registry::)", String.Empty);
        path = Regex.Replace(path, @"^(?i:Registry::)", String.Empty);

        if (Regex.IsMatch(path, @"^(?i:PNP:)") )
        {
            string pnpInstanceId = Regex.Replace(path, @"^(?i:PNP:)", String.Empty);
            return InstanceIdToRelativeRegistryPath(pnpInstanceId);
        }

        path = Regex.Replace(path, @"^(?i:HKLM:\\|HKLM\\|HKEY[_]?LOCAL[_]?MACHINE\\)", String.Empty);
        path = path.TrimStart('\\');
        return String.IsNullOrWhiteSpace(path) ? null : path;
    }

    private static string InstanceIdToRelativeRegistryPath(string instanceId)
    {
        string id = NormalizePathSeparators(instanceId);
        if (String.IsNullOrWhiteSpace(id)) { return null; }
        id = id.TrimStart('\\');
        id = Regex.Replace(id, @"^(?i:Microsoft\.PowerShell\.Core\\Registry::)", String.Empty);
        id = Regex.Replace(id, @"^(?i:Registry::)", String.Empty);
        id = Regex.Replace(id, @"^(?i:HKLM:\\|HKLM\\|HKEY[_]?LOCAL[_]?MACHINE\\)", String.Empty);
        if (Regex.IsMatch(id, @"^(?i:SYSTEM\\CurrentControlSet\\Enum\\)")) { return id; }
        return @"SYSTEM\CurrentControlSet\Enum\" + id;
    }

    private static string NormalizePathSeparators(string path)
    {
        if (path == null) { return null; }
        string text = path.Trim().Trim('"').Replace('/', '\\');
        while (text.IndexOf(@"\\", StringComparison.Ordinal) >= 0)
        {
            text = text.Replace(@"\\", @"\");
        }
        return text;
    }

    public const string ReservedCpuSetsRegistryPath = @"HKEY_LOCAL_MACHINE\System\CurrentControlSet\Control\Session Manager\kernel";
    public const string ReservedCpuSetsRegistryValueName = "ReservedCpuSets";
    private const string KernelSubkey = @"SYSTEM\CurrentControlSet\Control\Session Manager\kernel";
    private const string ReservedCpuSetsValueName = ReservedCpuSetsRegistryValueName;

    public static byte[] ReadReservedCpuSetsBytes()
    {
        Microsoft.Win32.RegistryKey hklm = null;
        Microsoft.Win32.RegistryKey key = null;
        try
        {
            hklm = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Default);
            key = hklm.OpenSubKey(KernelSubkey, false);
            if (key == null) { return null; }
            object value = key.GetValue(ReservedCpuSetsValueName, null, Microsoft.Win32.RegistryValueOptions.DoNotExpandEnvironmentNames);
            byte[] bytes = value as byte[];
            if (bytes == null) { return null; }
            byte[] clone = new byte[bytes.Length];
            Buffer.BlockCopy(bytes, 0, clone, 0, bytes.Length);
            return clone;
        }
        catch (System.Security.SecurityException) { return null; }
        catch (UnauthorizedAccessException) { return null; }
        catch (System.IO.IOException) { return null; }
        finally
        {
            try { if (key != null) { key.Close(); } } catch { }
            try { if (hklm != null) { hklm.Close(); } } catch { }
        }
    }

    public static bool WriteReservedCpuSetsBytes(byte[] bytes)
    {
        if (bytes == null) { return false; }
        Microsoft.Win32.RegistryKey hklm = null;
        Microsoft.Win32.RegistryKey key = null;
        try
        {
            hklm = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Default);
            key = hklm.CreateSubKey(KernelSubkey, Microsoft.Win32.RegistryKeyPermissionCheck.ReadWriteSubTree);
            if (key == null) { return false; }
            key.SetValue(ReservedCpuSetsValueName, bytes, Microsoft.Win32.RegistryValueKind.Binary);
            return true;
        }
        finally
        {
            try { if (key != null) { key.Close(); } } catch { }
            try { if (hklm != null) { hklm.Close(); } } catch { }
        }
    }

    public static bool DeleteReservedCpuSetsValue()
    {
        Microsoft.Win32.RegistryKey hklm = null;
        Microsoft.Win32.RegistryKey key = null;
        try
        {
            hklm = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, Microsoft.Win32.RegistryView.Default);
            key = hklm.OpenSubKey(KernelSubkey, true);
            if (key == null) { return false; }
            object existing = key.GetValue(ReservedCpuSetsValueName, null, Microsoft.Win32.RegistryValueOptions.DoNotExpandEnvironmentNames);
            if (existing == null) { return false; }
            key.DeleteValue(ReservedCpuSetsValueName, false);
            return true;
        }
        finally
        {
            try { if (key != null) { key.Close(); } } catch { }
            try { if (hklm != null) { hklm.Close(); } } catch { }
        }
    }
}

public static class ReservedCpuSetsUiNative
{
    private static readonly Color ColorDefault = Color.FromArgb(219, 219, 219);
    private static readonly Color ColorDim = Color.FromArgb(150, 150, 150);
    private static readonly Color ColorEffBlue = Color.FromArgb(0, 104, 181);
    private static readonly Color ColorReservedP = Color.Yellow;
    private static readonly Color ColorReservedE = Color.Green;
    private static readonly Color ColorCcd0 = Color.Orange;
    private static readonly Color ColorCcd1 = Color.Purple;
    private static readonly Color ColorCcd0Res = Color.Brown;
    private static readonly Color ColorCcd1Res = Color.Pink;

    public static bool[] GetReservedCoresLocal(int count, DeviceTweakerStartupModel startup)
    {
        if (count < 0) { count = 0; }
        bool[] reserved = new bool[count];
        byte[] bytes = null;

        if (startup != null && startup.ReservedCpuSetsSnapshotLoaded)
        {
            bytes = startup.HasReservedCpuSets ? startup.ReservedCpuSetsBytes : null;
        }
        else
        {
            bytes = DeviceTweakerRegistrySnapshot.ReadReservedCpuSetsBytes();
            if (startup != null)
            {
                startup.ReservedCpuSetsBytes = CloneBytes(bytes);
                startup.HasReservedCpuSets = (bytes != null);
                startup.ReservedCpuSetsSnapshotLoaded = true;
            }
        }

        FillReservedArray(reserved, bytes);
        return reserved;
    }

    public static bool[] DecodeReservedCpuSetsBytes(byte[] bytes, int count)
    {
        if (count < 0) { count = 0; }
        bool[] reserved = new bool[count];
        FillReservedArray(reserved, bytes);
        return reserved;
    }

    public static void SetCellsCheckedFromReservedArray(object cells, bool[] reserved)
    {
        if (reserved == null) { reserved = new bool[0]; }
        CpuAffinityGrid grid = cells as CpuAffinityGrid;
        if (grid != null)
        {
            grid.SetCheckedFromBoolArray(reserved);
            return;
        }
        CpuAffinityGridCell[] gridCells = cells as CpuAffinityGridCell[];
        if (gridCells != null && gridCells.Length > 0 && gridCells[0] != null && gridCells[0].Owner != null)
        {
            gridCells[0].Owner.SetCheckedFromBoolArray(reserved);
            return;
        }
        foreach (object cell in EnumerateObjects(cells))
        {
            int core = GetCellCoreIndex(cell);
            if (core < 0 || core >= reserved.Length) { continue; }
            SetCellChecked(cell, reserved[core]);
        }
    }

    public static byte[] BuildReservedCpuSetsBytesFromCells(object cells, int logicalCount)
    {
        CpuAffinityGrid grid = cells as CpuAffinityGrid;
        if (grid != null) { return grid.BuildCheckedBytes(logicalCount); }
        CpuAffinityGridCell[] gridCells = cells as CpuAffinityGridCell[];
        if (gridCells != null && gridCells.Length > 0 && gridCells[0] != null && gridCells[0].Owner != null)
        {
            return gridCells[0].Owner.BuildCheckedBytes(logicalCount);
        }

        int count = NormalizeLogicalCount(logicalCount);
        byte[] bytes = new byte[Math.Max(8, (count + 7) / 8)];
        foreach (object cell in EnumerateObjects(cells))
        {
            int core = GetCellCoreIndex(cell);
            if (core < 0 || core >= count) { continue; }
            if (!GetCellChecked(cell)) { continue; }
            int byteIndex = core / 8;
            int bitIndex = core % 8;
            bytes[byteIndex] = (byte)(bytes[byteIndex] | (byte)(1 << bitIndex));
        }
        return bytes;
    }

    public static byte[] BuildReservedCpuSetsBytesFromGrid(CpuAffinityGrid grid, int logicalCount)
    {
        if (grid == null) { return BuildReservedCpuSetsBytesFromCells(null, logicalCount); }
        return grid.BuildCheckedBytes(logicalCount);
    }

    public static byte[] BuildReservedCpuSetsBytesFromCores(object cores, int logicalCount)
    {
        int count = NormalizeLogicalCount(logicalCount);
        byte[] bytes = new byte[Math.Max(8, (count + 7) / 8)];
        foreach (object coreObj in EnumerateObjects(cores))
        {
            int core;
            try { core = Convert.ToInt32(coreObj); } catch { continue; }
            if (core < 0 || core >= count) { continue; }
            int byteIndex = core / 8;
            int bitIndex = core % 8;
            bytes[byteIndex] = (byte)(bytes[byteIndex] | (byte)(1 << bitIndex));
        }
        return bytes;
    }

    public static bool WriteReservedCpuSetsBytes(byte[] bytes, DeviceTweakerStartupModel startup)
    {
        if (bytes == null) { return false; }
        byte[] clone = CloneBytes(bytes);
        bool ok = DeviceTweakerRegistrySnapshot.WriteReservedCpuSetsBytes(clone);
        if (ok && startup != null)
        {
            startup.ReservedCpuSetsBytes = CloneBytes(clone);
            startup.HasReservedCpuSets = true;
            startup.ReservedCpuSetsSnapshotLoaded = true;
        }
        return ok;
    }

    public static bool DeleteReservedCpuSetsValue(DeviceTweakerStartupModel startup)
    {
        bool existed = DeviceTweakerRegistrySnapshot.DeleteReservedCpuSetsValue();
        if (startup != null)
        {
            startup.ReservedCpuSetsBytes = null;
            startup.HasReservedCpuSets = false;
            startup.ReservedCpuSetsSnapshotLoaded = true;
        }
        return existed;
    }

    public static void ApplyReservedColoring(object deviceList, object deviceControls, object reservedCells, bool[] reservedArr, bool isDualCcd, object ccd0Cores, object ccd1Cores, bool[] isPCoreLookup)
    {
        if (reservedArr == null) { reservedArr = new bool[0]; }
        System.Collections.IDictionary controlMap = deviceControls as System.Collections.IDictionary;
        HashSet<int> ccd0 = ToIntSet(ccd0Cores);
        HashSet<int> ccd1 = ToIntSet(ccd1Cores);

        if (controlMap != null)
        {
            foreach (object device in EnumerateObjects(deviceList))
            {
                object ctrls = GetDictionaryValue(controlMap, device);
                if (ctrls == null) { continue; }
                object checkBoxes = GetMemberValue(ctrls, "CheckBoxes");
                string category = ToInvariantString(GetMemberValue(device, "Category"));
                string role = ToInvariantString(GetMemberValue(device, "Role"));
                ApplyCellsColoring(checkBoxes, ctrls, category, role, reservedArr, isDualCcd, ccd0, ccd1, isPCoreLookup);
            }
        }

        ApplyCellsColoring(reservedCells, null, String.Empty, String.Empty, reservedArr, isDualCcd, ccd0, ccd1, isPCoreLookup);
    }

    private static void ApplyCellsColoring(object cells, object ctrls, string category, string role, bool[] reservedArr, bool isDualCcd, HashSet<int> ccd0, HashSet<int> ccd1, bool[] isPCoreLookup)
    {
        foreach (object cell in EnumerateObjects(cells))
        {
            int core = GetCellCoreIndex(cell);
            if (core < 0 || core >= reservedArr.Length) { continue; }
            bool isReserved = reservedArr[core];
            bool affinityAllowed = GetCellAutoCheck(cell);

            if (!affinityAllowed && GetCellChecked(cell) && String.Equals(category, "Network", StringComparison.OrdinalIgnoreCase) && String.Equals(role, "NDIS", StringComparison.OrdinalIgnoreCase))
            {
                object ndisToggle = GetMemberValue(ctrls, "NdisIrqToggle");
                if (ndisToggle == null || !GetBoolMemberValue(ndisToggle, "Checked", false)) { affinityAllowed = true; }
            }

            Color color;
            if (isDualCcd)
            {
                if (ccd0.Contains(core)) { color = isReserved ? ColorCcd0Res : ColorCcd0; }
                else if (ccd1.Contains(core)) { color = isReserved ? ColorCcd1Res : ColorCcd1; }
                else { color = affinityAllowed ? ColorDefault : ColorDim; }
            }
            else if (isReserved)
            {
                color = IsPCore(core, isPCoreLookup) ? ColorReservedP : ColorReservedE;
            }
            else if (!affinityAllowed)
            {
                color = ColorDim;
            }
            else
            {
                color = IsPCore(core, isPCoreLookup) ? ColorDefault : ColorEffBlue;
            }

            SetCellForeColor(cell, color);
        }
    }

    private static int NormalizeLogicalCount(int logicalCount)
    {
        return logicalCount < 1 ? 1 : logicalCount;
    }

    private static byte[] CloneBytes(byte[] bytes)
    {
        if (bytes == null) { return null; }
        byte[] clone = new byte[bytes.Length];
        Buffer.BlockCopy(bytes, 0, clone, 0, bytes.Length);
        return clone;
    }

    private static void FillReservedArray(bool[] reserved, byte[] bytes)
    {
        if (reserved == null || bytes == null) { return; }
        int bitIndex = 0;
        for (int i = 0; i < bytes.Length && bitIndex < reserved.Length; i++)
        {
            byte b = bytes[i];
            for (int j = 0; j < 8 && bitIndex < reserved.Length; j++)
            {
                reserved[bitIndex] = ((b & (1 << j)) != 0);
                bitIndex++;
            }
        }
    }

    private static bool IsPCore(int index, bool[] lookup)
    {
        if (lookup != null && index >= 0 && index < lookup.Length) { return lookup[index]; }
        return true;
    }

    private static HashSet<int> ToIntSet(object values)
    {
        HashSet<int> existing = values as HashSet<int>;
        if (existing != null) { return existing; }
        HashSet<int> set = new HashSet<int>();
        foreach (object value in EnumerateObjects(values))
        {
            try { set.Add(Convert.ToInt32(value)); } catch { }
        }
        return set;
    }

    private static System.Collections.IEnumerable EnumerateObjects(object value)
    {
        if (value == null) { yield break; }
        string text = value as string;
        if (text != null) { yield return value; yield break; }
        System.Collections.IEnumerable enumerable = value as System.Collections.IEnumerable;
        if (enumerable == null) { yield return value; yield break; }
        foreach (object item in enumerable) { if (item != null) { yield return item; } }
    }

    private static object GetDictionaryValue(System.Collections.IDictionary dict, object key)
    {
        if (dict == null || key == null) { return null; }
        try { if (dict.Contains(key)) { return dict[key]; } } catch { }
        foreach (System.Collections.DictionaryEntry entry in dict)
        {
            try
            {
                if (Object.ReferenceEquals(entry.Key, key) || Object.Equals(entry.Key, key)) { return entry.Value; }
            }
            catch { }
        }
        return null;
    }

    private static object GetMemberValue(object obj, string name)
    {
        if (obj == null || String.IsNullOrEmpty(name)) { return null; }
        System.Collections.IDictionary dict = obj as System.Collections.IDictionary;
        if (dict != null)
        {
            try { if (dict.Contains(name)) { return dict[name]; } } catch { }
            foreach (System.Collections.DictionaryEntry entry in dict)
            {
                string keyText = Convert.ToString(entry.Key);
                if (String.Equals(keyText, name, StringComparison.OrdinalIgnoreCase)) { return entry.Value; }
            }
        }

        try
        {
            System.Reflection.PropertyInfo prop = obj.GetType().GetProperty(name, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.IgnoreCase);
            if (prop != null) { return prop.GetValue(obj, null); }
        }
        catch { }
        return null;
    }

    private static string ToInvariantString(object value)
    {
        return value == null ? String.Empty : Convert.ToString(value);
    }

    private static int GetCellCoreIndex(object cell)
    {
        if (cell == null) { return -1; }
        CpuAffinityGridCell gridCell = cell as CpuAffinityGridCell;
        if (gridCell != null) { return gridCell.CpuIndex; }
        object tag = GetMemberValue(cell, "Tag");
        try { return Convert.ToInt32(tag); } catch { return -1; }
    }

    private static bool GetCellChecked(object cell)
    {
        if (cell == null) { return false; }
        CpuAffinityGridCell gridCell = cell as CpuAffinityGridCell;
        if (gridCell != null) { return gridCell.Checked; }
        CheckBox box = cell as CheckBox;
        if (box != null) { return box.Checked; }
        return GetBoolMemberValue(cell, "Checked", false);
    }

    private static void SetCellChecked(object cell, bool value)
    {
        if (cell == null) { return; }
        CpuAffinityGridCell gridCell = cell as CpuAffinityGridCell;
        if (gridCell != null) { gridCell.Checked = value; return; }
        CheckBox box = cell as CheckBox;
        if (box != null) { box.Checked = value; return; }
        SetMemberValue(cell, "Checked", value);
    }

    private static bool GetCellAutoCheck(object cell)
    {
        if (cell == null) { return true; }
        CpuAffinityGridCell gridCell = cell as CpuAffinityGridCell;
        if (gridCell != null) { return gridCell.AutoCheck; }
        CheckBox box = cell as CheckBox;
        if (box != null) { return box.AutoCheck; }
        return GetBoolMemberValue(cell, "AutoCheck", true);
    }

    private static void SetCellForeColor(object cell, Color color)
    {
        if (cell == null) { return; }
        CpuAffinityGridCell gridCell = cell as CpuAffinityGridCell;
        if (gridCell != null) { gridCell.ForeColor = color; return; }
        Control ctrl = cell as Control;
        if (ctrl != null) { ctrl.ForeColor = color; return; }
        SetMemberValue(cell, "ForeColor", color);
    }

    private static bool GetBoolMemberValue(object obj, string name, bool defaultValue)
    {
        object value = GetMemberValue(obj, name);
        if (value == null) { return defaultValue; }
        try { return Convert.ToBoolean(value); } catch { return defaultValue; }
    }

    private static void SetMemberValue(object obj, string name, object value)
    {
        if (obj == null || String.IsNullOrEmpty(name)) { return; }
        try
        {
            System.Reflection.PropertyInfo prop = obj.GetType().GetProperty(name, System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.IgnoreCase);
            if (prop != null && prop.CanWrite) { prop.SetValue(obj, value, null); }
        }
        catch { }
    }
}

public static class DeviceTweakerPathHelpers
{
    private static bool IsHex(char c)
    {
        return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
    }

    private static bool IsDigit(char c)
    {
        return c >= '0' && c <= '9';
    }

    private static string UpperHex4(string text, int start)
    {
        if (String.IsNullOrEmpty(text) || start < 0 || start + 4 > text.Length) { return null; }
        for (int i = 0; i < 4; i++) { if (!IsHex(text[start + i])) { return null; } }
        return text.Substring(start, 4).ToUpperInvariant();
    }

    private static string UpperHex8(string text, int start)
    {
        if (String.IsNullOrEmpty(text) || start < 0 || start + 8 > text.Length) { return null; }
        for (int i = 0; i < 8; i++) { if (!IsHex(text[start + i])) { return null; } }
        return text.Substring(start, 8).ToUpperInvariant();
    }

    public static string FindHex4TokenValue(string text, string token)
    {
        if (String.IsNullOrEmpty(text) || String.IsNullOrEmpty(token)) { return null; }
        int index = text.IndexOf(token, StringComparison.OrdinalIgnoreCase);
        while (index >= 0)
        {
            string value = UpperHex4(text, index + token.Length);
            if (value != null) { return value; }
            int nextStart = index + 1;
            if (nextStart >= text.Length) { break; }
            index = text.IndexOf(token, nextStart, StringComparison.OrdinalIgnoreCase);
        }
        return null;
    }

    public static string FindHex8TokenValue(string text, string token)
    {
        if (String.IsNullOrEmpty(text) || String.IsNullOrEmpty(token)) { return null; }
        int index = text.IndexOf(token, StringComparison.OrdinalIgnoreCase);
        while (index >= 0)
        {
            string value = UpperHex8(text, index + token.Length);
            if (value != null) { return value; }
            int nextStart = index + 1;
            if (nextStart >= text.Length) { break; }
            index = text.IndexOf(token, nextStart, StringComparison.OrdinalIgnoreCase);
        }
        return null;
    }

    private static UsbVidPidParseResult MakeUsbVidPidResult(string vid, string pid)
    {
        UsbVidPidParseResult result = new UsbVidPidParseResult();
        if (String.IsNullOrWhiteSpace(vid) || String.IsNullOrWhiteSpace(pid)) { return result; }
        result.Success = true;
        result.Vid = vid.ToUpperInvariant();
        result.Pid = pid.ToUpperInvariant();
        result.ColonKey = result.Vid + ":" + result.Pid;
        result.VidPidKey = "VID_" + result.Vid + "&PID_" + result.Pid;
        return result;
    }

    public static UsbVidPidParseResult ExtractUsbVidPid(string text)
    {
        string vid = FindHex4TokenValue(text, "VID_");
        if (vid == null) { return new UsbVidPidParseResult(); }
        string pid = FindHex4TokenValue(text, "PID_");
        if (pid == null) { return new UsbVidPidParseResult(); }
        return MakeUsbVidPidResult(vid, pid);
    }

    public static string ExtractUsbVidPidColonKey(string text)
    {
        UsbVidPidParseResult result = ExtractUsbVidPid(text);
        return result != null && result.Success ? result.ColonKey : null;
    }

    public static string ExtractUsbVidPidKey(string text)
    {
        UsbVidPidParseResult result = ExtractUsbVidPid(text);
        return result != null && result.Success ? result.VidPidKey : null;
    }

    private static UsbVidPidParseResult ParsePlainVidPidPair(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return new UsbVidPidParseResult(); }
        string s = text.Trim();
        int i = 0;
        while (i < s.Length && Char.IsWhiteSpace(s[i])) { i++; }
        if (i + 4 > s.Length) { return new UsbVidPidParseResult(); }
        string vid = UpperHex4(s, i);
        if (vid == null) { return new UsbVidPidParseResult(); }
        i += 4;
        while (i < s.Length && Char.IsWhiteSpace(s[i])) { i++; }
        if (i >= s.Length || (s[i] != ':' && s[i] != '-')) { return new UsbVidPidParseResult(); }
        i++;
        while (i < s.Length && Char.IsWhiteSpace(s[i])) { i++; }
        if (i + 4 > s.Length) { return new UsbVidPidParseResult(); }
        string pid = UpperHex4(s, i);
        if (pid == null) { return new UsbVidPidParseResult(); }
        i += 4;
        while (i < s.Length && Char.IsWhiteSpace(s[i])) { i++; }
        if (i != s.Length) { return new UsbVidPidParseResult(); }
        return MakeUsbVidPidResult(vid, pid);
    }

    public static UsbVidPidParseResult ExtractUsbVidPidFlexible(string sourceId, string instanceId)
    {
        UsbVidPidParseResult result = ExtractUsbVidPid(sourceId);
        if (result != null && result.Success) { return result; }
        result = ParsePlainVidPidPair(sourceId);
        if (result != null && result.Success) { return result; }
        return ExtractUsbVidPid(instanceId);
    }

    public static int ExtractUsbMiNumber(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return -1; }
        int index = text.IndexOf("MI_", StringComparison.OrdinalIgnoreCase);
        while (index >= 0)
        {
            bool validPrefix = (index == 0) || text[index - 1] == '&';
            int valueStart = index + 3;
            bool validValue = valueStart + 2 <= text.Length && IsHex(text[valueStart]) && IsHex(text[valueStart + 1]);
            int after = valueStart + 2;
            bool validSuffix = after >= text.Length || text[after] == '&' || text[after] == '\\' || text[after] == '#';
            if (validPrefix && validValue && validSuffix)
            {
                int parsed;
                if (Int32.TryParse(text.Substring(valueStart, 2), System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture, out parsed)) { return parsed; }
            }
            int nextStart = index + 1;
            if (nextStart >= text.Length) { break; }
            index = text.IndexOf("MI_", nextStart, StringComparison.OrdinalIgnoreCase);
        }
        return -1;
    }

    public static string[] GetHidUsbPollingLookupKeys(string instanceId)
    {
        List<string> keys = new List<string>();
        UsbVidPidParseResult pair = ExtractUsbVidPid(instanceId);
        if (pair == null || !pair.Success) { return keys.ToArray(); }
        int mi = ExtractUsbMiNumber(instanceId);
        if (mi >= 0) { keys.Add(pair.VidPidKey + ":MI_" + mi.ToString("X2")); }
        keys.Add(pair.VidPidKey);
        return keys.ToArray();
    }

    public static double CalculateUsbEndpointPollingHz(string speed, int bInterval)
    {
        if (bInterval <= 0) { return 0.0; }
        bool highOrSuper = String.Equals(speed, "High", StringComparison.OrdinalIgnoreCase) || String.Equals(speed, "Super", StringComparison.OrdinalIgnoreCase) || String.Equals(speed, "SuperPlus", StringComparison.OrdinalIgnoreCase);
        double intervalUs = highOrSuper ? Math.Pow(2.0, bInterval - 1) * 125.0 : ((double)bInterval) * 1000.0;
        return intervalUs <= 0.0 ? 0.0 : 1000000.0 / intervalUs;
    }

    public static string FormatPollingRateTag(double hz)
    {
        double khz = hz / 1000.0;
        if (khz >= 1.0 && Math.Abs(khz - Math.Round(khz)) < 0.0000001) { return Math.Round(khz).ToString("0") + "K"; }
        return khz.ToString("0.###") + "K";
    }

    public static Dictionary<string, PollingRateLookupRecord> BuildPollingRateLookup(UsbEnumerationResult usbEnumResult)
    {
        Dictionary<string, List<UsbEndpointRecord>> groups = new Dictionary<string, List<UsbEndpointRecord>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, PollingRateLookupRecord> lookup = new Dictionary<string, PollingRateLookupRecord>(StringComparer.OrdinalIgnoreCase);
        if (usbEnumResult == null || usbEnumResult.Endpoints == null) { return lookup; }
        for (int i = 0; i < usbEnumResult.Endpoints.Count; i++)
        {
            UsbEndpointRecord ep = usbEnumResult.Endpoints[i];
            if (ep == null) { continue; }
            string key = Safe(ep.VendorId) + ":" + Safe(ep.ProductId) + ":" + Safe(ep.TopologyPath);
            List<UsbEndpointRecord> list;
            if (!groups.TryGetValue(key, out list)) { list = new List<UsbEndpointRecord>(); groups[key] = list; }
            list.Add(ep);
        }
        foreach (KeyValuePair<string, List<UsbEndpointRecord>> grp in groups)
        {
            List<UsbEndpointRecord> list = grp.Value;
            if (list == null || list.Count == 0) { continue; }
            UsbEndpointRecord first = list[0];
            string vidPid = Safe(first.VendorId) + ":" + Safe(first.ProductId);
            int bestBInterval = Int32.MaxValue;
            UsbEndpointRecord best = null;
            for (int i = 0; i < list.Count; i++)
            {
                UsbEndpointRecord ep = list[i];
                if (ep == null) { continue; }
                if (String.Equals(ep.TransferType, "Interrupt", StringComparison.OrdinalIgnoreCase) && String.Equals(ep.Direction, "IN", StringComparison.OrdinalIgnoreCase) && ep.AlternateSetting == 0)
                {
                    if (ep.bInterval < bestBInterval) { bestBInterval = ep.bInterval; best = ep; }
                }
            }
            if (best == null || best.bInterval <= 0) { continue; }
            double hz = CalculateUsbEndpointPollingHz(best.Speed, best.bInterval);
            if (hz <= 0.0) { continue; }
            PollingRateLookupRecord existing;
            if (!lookup.TryGetValue(vidPid, out existing) || existing.Hz < hz)
            {
                lookup[vidPid] = new PollingRateLookupRecord { Hz = hz, Speed = best.Speed, bInterval = best.bInterval, Tag = FormatPollingRateTag(hz) };
            }
        }
        return lookup;
    }

    public static Dictionary<string, HidUsbPollingInfoRecord> BuildHidUsbPollingInfoLookup(UsbEnumerationResult usbEnumResult)
    {
        Dictionary<string, HidUsbPollingInfoRecord> lookup = new Dictionary<string, HidUsbPollingInfoRecord>(StringComparer.OrdinalIgnoreCase);
        if (usbEnumResult == null || usbEnumResult.Endpoints == null) { return lookup; }
        for (int i = 0; i < usbEnumResult.Endpoints.Count; i++)
        {
            UsbEndpointRecord ep = usbEnumResult.Endpoints[i];
            if (ep == null || ep.DeviceIsHub) { continue; }
            if (!String.Equals(ep.InterfaceClass, "0x03", StringComparison.OrdinalIgnoreCase)) { continue; }
            if (!String.Equals(ep.TransferType, "Interrupt", StringComparison.OrdinalIgnoreCase)) { continue; }
            if (!String.Equals(ep.Direction, "IN", StringComparison.OrdinalIgnoreCase)) { continue; }
            if (ep.AlternateSetting != 0) { continue; }
            if (String.IsNullOrWhiteSpace(ep.VendorId) || String.IsNullOrWhiteSpace(ep.ProductId)) { continue; }
            double hz = CalculateUsbEndpointPollingHz(ep.Speed, ep.bInterval);
            if (hz <= 0.0) { continue; }
            string vidPidKey = "VID_" + ep.VendorId.ToUpperInvariant() + "&PID_" + ep.ProductId.ToUpperInvariant();
            string interfaceLabel = ep.InterfaceNumber >= 0 ? "MI_" + ep.InterfaceNumber.ToString("X2") : null;
            HidUsbPollingInfoRecord info = new HidUsbPollingInfoRecord
            {
                Speed = ep.Speed,
                bInterval = ep.bInterval,
                Hz = hz,
                PollingRate = hz.ToString("0.###") + " Hz (" + FormatPollingRateTag(hz) + ")",
                Interface = interfaceLabel,
                EndpointAddress = ep.EndpointAddress,
                EndpointNumber = ep.EndpointNumber,
                IntervalInterpretation = ep.IntervalInterpretation,
                TopologyPath = ep.TopologyPath
            };
            AddBestHidPollingInfo(lookup, vidPidKey, info);
            if (!String.IsNullOrWhiteSpace(interfaceLabel)) { AddBestHidPollingInfo(lookup, vidPidKey + ":" + interfaceLabel, info); }
        }
        return lookup;
    }

    private static void AddBestHidPollingInfo(Dictionary<string, HidUsbPollingInfoRecord> lookup, string key, HidUsbPollingInfoRecord info)
    {
        HidUsbPollingInfoRecord existing;
        if (!lookup.TryGetValue(key, out existing) || existing.Hz < info.Hz) { lookup[key] = info; }
    }

    private static string Safe(string value) { return value ?? String.Empty; }

    private static string DecodeRegistryEscapes(string text)
    {
        if (String.IsNullOrEmpty(text)) { return String.Empty; }
        StringBuilder sb = null;
        for (int i = 0; i < text.Length; i++)
        {
            char replacement = '\0';
            if (text[i] == '\\' && i + 5 < text.Length && (text[i + 1] == 'u' || text[i + 1] == 'U'))
            {
                string code = text.Substring(i + 2, 4);
                if (String.Equals(code, "005c", StringComparison.OrdinalIgnoreCase)) { replacement = '\\'; }
                else if (String.Equals(code, "0026", StringComparison.OrdinalIgnoreCase)) { replacement = '&'; }
                else if (String.Equals(code, "003c", StringComparison.OrdinalIgnoreCase)) { replacement = '<'; }
                else if (String.Equals(code, "003e", StringComparison.OrdinalIgnoreCase)) { replacement = '>'; }
                else if (String.Equals(code, "0027", StringComparison.OrdinalIgnoreCase)) { replacement = '\''; }
            }
            if (replacement != '\0')
            {
                if (sb == null) { sb = new StringBuilder(text.Length); sb.Append(text, 0, i); }
                sb.Append(replacement);
                i += 5;
            }
            else if (sb != null) { sb.Append(text[i]); }
        }
        return sb == null ? text : sb.ToString();
    }

    private static string CollapseBackslashes(string text)
    {
        if (String.IsNullOrEmpty(text)) { return String.Empty; }
        StringBuilder sb = null;
        bool previousSlash = false;
        for (int i = 0; i < text.Length; i++)
        {
            char c = text[i];
            if (c == '\\')
            {
                if (previousSlash)
                {
                    if (sb == null) { sb = new StringBuilder(text.Length); sb.Append(text, 0, i); }
                    continue;
                }
                previousSlash = true;
            }
            else { previousSlash = false; }
            if (sb != null) { sb.Append(c); }
        }
        return sb == null ? text : sb.ToString();
    }

    private static string StripPrefix(string text, string prefix)
    {
        if (!String.IsNullOrEmpty(text) && text.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) { return text.Substring(prefix.Length); }
        return text;
    }

    private static string StripControlSetEnumPrefix(string text)
    {
        if (String.IsNullOrEmpty(text)) { return String.Empty; }
        const string controlSet = "ControlSet";
        const string enumSuffix = "\\Enum\\";
        if (text.Length >= controlSet.Length + 3 + enumSuffix.Length && text.StartsWith(controlSet, StringComparison.OrdinalIgnoreCase))
        {
            int digitStart = controlSet.Length;
            if (IsDigit(text[digitStart]) && IsDigit(text[digitStart + 1]) && IsDigit(text[digitStart + 2]))
            {
                int suffixStart = digitStart + 3;
                if (text.IndexOf(enumSuffix, suffixStart, enumSuffix.Length, StringComparison.OrdinalIgnoreCase) == suffixStart) { return text.Substring(suffixStart + enumSuffix.Length); }
            }
        }
        return text;
    }

    public static string NormalizeLookupText(string value)
    {
        if (String.IsNullOrWhiteSpace(value)) { return String.Empty; }
        string text = DecodeRegistryEscapes(value.Trim().Trim('"'));
        text = text.Replace('/', '\\');
        text = CollapseBackslashes(text);
        text = StripPrefix(text, @"Microsoft.PowerShell.Core\Registry::");
        text = StripPrefix(text, @"Registry::");
        text = StripPrefix(text, @"HKEY_LOCAL_MACHINE\");
        text = StripPrefix(text, @"HKLM:\");
        text = StripPrefix(text, @"HKLM\");
        text = StripPrefix(text, @"System\CurrentControlSet\Enum\");
        text = StripControlSetEnumPrefix(text);
        return text.Trim('\\');
    }

    private static string ExtractPrefixedSegment(string deviceId, string prefix)
    {
        if (String.IsNullOrWhiteSpace(deviceId) || String.IsNullOrWhiteSpace(prefix)) { return null; }
        string[] parts = deviceId.Split('&');
        for (int i = 0; i < parts.Length; i++)
        {
            string seg = parts[i] == null ? String.Empty : parts[i].Trim();
            if (seg.StartsWith(prefix, StringComparison.OrdinalIgnoreCase)) { return seg.ToUpperInvariant(); }
        }
        return null;
    }

    public static string ToPnpId(string registryPath)
    {
        if (String.IsNullOrWhiteSpace(registryPath)) { return null; }
        string cleanPath = NormalizeLookupText(registryPath);
        string[] rawParts = cleanPath.Split(new char[] { '\\' }, StringSplitOptions.RemoveEmptyEntries);
        if (rawParts.Length < 2) { return cleanPath; }
        string bus = rawParts[0].ToUpperInvariant();
        string deviceId = rawParts[1];
        string vendorPrefix = "VEN_";
        string devicePrefix = "DEV_";
        bool isUsb = String.Equals(bus, "USB", StringComparison.OrdinalIgnoreCase) || FindHex4TokenValue(deviceId, "VID_") != null;
        if (isUsb) { vendorPrefix = "VID_"; devicePrefix = "PID_"; }
        string vendor = ExtractPrefixedSegment(deviceId, vendorPrefix);
        string device = ExtractPrefixedSegment(deviceId, devicePrefix);
        if (vendor != null && device != null) { return bus + "_" + vendor + "_" + device; }
        if (isUsb) { return bus + "_" + (vendor ?? "UNKNOWN_VID") + "_" + (device ?? "UNKNOWN_PID"); }
        return bus + "_" + (vendor ?? "UNKNOWN_VEN") + "_" + (device ?? "UNKNOWN_DEV");
    }

    public static string NormalizeHostControllerPath(string hostControllerPath)
    {
        if (String.IsNullOrWhiteSpace(hostControllerPath)) { return null; }
        string text = hostControllerPath.Trim().ToUpperInvariant();
        if (text.StartsWith(@"\\?\", StringComparison.Ordinal) || text.StartsWith(@"\\.\", StringComparison.Ordinal)) { text = text.Substring(4); }
        int guidStart = text.LastIndexOf("#{", StringComparison.Ordinal);
        if (guidStart >= 0 && text.EndsWith("}", StringComparison.Ordinal)) { text = text.Substring(0, guidStart); }
        text = text.Replace('#', '\\');
        text = CollapseBackslashes(text);
        return String.IsNullOrWhiteSpace(text) ? null : text;
    }

    public static string ConvertUsbHostControllerPathToPnpKey(string hostControllerPath)
    {
        string normalized = NormalizeHostControllerPath(hostControllerPath);
        if (String.IsNullOrWhiteSpace(normalized)) { return null; }
        return ToPnpId(normalized);
    }

    private static string GetVenDevToken(string text)
    {
        string ven = FindHex4TokenValue(text, "VEN_");
        string dev = FindHex4TokenValue(text, "DEV_");
        if (ven == null || dev == null) { return null; }
        return "VEN_" + ven + "&DEV_" + dev;
    }

    private static string GetLeafAfterLastSlash(string text)
    {
        if (String.IsNullOrEmpty(text)) { return String.Empty; }
        int slash = text.LastIndexOf('\\');
        return slash >= 0 && slash + 1 < text.Length ? text.Substring(slash + 1) : text;
    }

    public static bool HostControllerPathsMatch(string hostControllerPath, string controllerPath)
    {
        string hcNorm = NormalizeHostControllerPath(hostControllerPath);
        string ctNorm = NormalizeHostControllerPath(controllerPath);
        if (String.IsNullOrWhiteSpace(hcNorm) || String.IsNullOrWhiteSpace(ctNorm)) { return false; }
        if (String.Equals(hcNorm, ctNorm, StringComparison.OrdinalIgnoreCase)) { return true; }
        string hcVD = GetVenDevToken(hcNorm);
        string ctVD = GetVenDevToken(ctNorm);
        if (hcVD == null || ctVD == null || !String.Equals(hcVD, ctVD, StringComparison.OrdinalIgnoreCase)) { return false; }
        string hcInst = GetLeafAfterLastSlash(hcNorm);
        string ctInst = GetLeafAfterLastSlash(ctNorm);
        return String.IsNullOrWhiteSpace(hcInst) || String.IsNullOrWhiteSpace(ctInst) || String.Equals(hcInst, ctInst, StringComparison.OrdinalIgnoreCase);
    }

    public static string NormalizeUsbBcdVersionLabel(string usbVersion)
    {
        if (String.IsNullOrWhiteSpace(usbVersion)) { return null; }
        string v = usbVersion.Trim();
        int dot = v.IndexOf('.');
        if (dot > 0)
        {
            bool majorOk = true;
            for (int i = 0; i < dot; i++) { if (!IsDigit(v[i])) { majorOk = false; break; } }
            if (majorOk)
            {
                string major = v.Substring(0, dot);
                string tail = v.Substring(dot + 1);
                bool tailDigits = tail.Length > 0;
                for (int i = 0; i < tail.Length; i++) { if (!IsDigit(tail[i])) { tailDigits = false; break; } }
                if (tailDigits)
                {
                    if (tail.Length == 2) { return tail[1] == '0' ? major + "." + tail[0].ToString() : major + "." + tail; }
                    string minor = tail.TrimEnd('0');
                    if (String.IsNullOrWhiteSpace(minor)) { minor = "0"; }
                    return major + "." + minor;
                }
            }
        }
        return v;
    }

    public static string GetUsbSpeedSpecificLabel(string speed)
    {
        if (String.IsNullOrWhiteSpace(speed)) { return null; }
        if (String.Equals(speed, "Low", StringComparison.OrdinalIgnoreCase)) { return "USB 1.0 Low-Speed (1.5 Mbps)"; }
        if (String.Equals(speed, "Full", StringComparison.OrdinalIgnoreCase)) { return "USB 1.1 Full-Speed (12 Mbps)"; }
        if (String.Equals(speed, "High", StringComparison.OrdinalIgnoreCase)) { return "USB 2.0 High-Speed (480 Mbps)"; }
        if (String.Equals(speed, "Super", StringComparison.OrdinalIgnoreCase)) { return "USB 3.2 Gen 1x1 (5 Gbps)"; }
        if (String.Equals(speed, "SuperPlus", StringComparison.OrdinalIgnoreCase)) { return "USB 3.2 Gen 2x1 (10 Gbps)"; }
        return speed;
    }

    public static string GetUsbEndpointSpecDisplayToken(string usbVersion, string speed)
    {
        string speedLabel = GetUsbSpeedSpecificLabel(speed);
        if (!String.IsNullOrWhiteSpace(speedLabel)) { return speedLabel; }
        string versionLabel = NormalizeUsbBcdVersionLabel(usbVersion);
        return !String.IsNullOrWhiteSpace(versionLabel) ? "USB " + versionLabel : null;
    }

    private static bool ContainsIgnoreCase(string text, string value)
    {
        return !String.IsNullOrEmpty(text) && text.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0;
    }

    public static int GetUsbVersionTokenSortRank(string token)
    {
        if (String.IsNullOrWhiteSpace(token)) { return 0; }
        int rank = 0;
        int usbIndex = token.IndexOf("USB", StringComparison.OrdinalIgnoreCase);
        if (usbIndex >= 0)
        {
            int i = usbIndex + 3;
            while (i < token.Length && Char.IsWhiteSpace(token[i])) { i++; }
            int majorStart = i;
            while (i < token.Length && IsDigit(token[i])) { i++; }
            if (i > majorStart)
            {
                int major;
                if (Int32.TryParse(token.Substring(majorStart, i - majorStart), out major))
                {
                    int minor = 0;
                    if (i < token.Length && token[i] == '.')
                    {
                        i++;
                        int minorStart = i;
                        while (i < token.Length && IsDigit(token[i])) { i++; }
                        if (i > minorStart) { Int32.TryParse(token.Substring(minorStart, i - minorStart), out minor); }
                    }
                    rank = (major * 1000) + (minor * 10);
                }
            }
        }
        if ((ContainsIgnoreCase(token, "Gen 2x2") || ContainsIgnoreCase(token, "Gen 2 x 2") || ContainsIgnoreCase(token, "20 Gbps"))) { rank += 8; }
        else if (ContainsIgnoreCase(token, "Gen 2x1") || ContainsIgnoreCase(token, "Gen 2 x 1") || ContainsIgnoreCase(token, "Gen 2") || ContainsIgnoreCase(token, "10 Gbps") || ContainsIgnoreCase(token, "SuperSpeedPlus")) { rank += 7; }
        else if (ContainsIgnoreCase(token, "Gen 1x1") || ContainsIgnoreCase(token, "Gen 1 x 1") || ContainsIgnoreCase(token, "Gen 1") || ContainsIgnoreCase(token, "5 Gbps") || ContainsIgnoreCase(token, "SuperSpeed")) { rank += 6; }
        else if (ContainsIgnoreCase(token, "High-Speed")) { rank += 3; }
        else if (ContainsIgnoreCase(token, "Full-Speed")) { rank += 2; }
        else if (ContainsIgnoreCase(token, "Low-Speed")) { rank += 1; }
        return rank;
    }

    public static int GetUsbSpecificationLabelSortRank(string token)
    {
        if (String.IsNullOrWhiteSpace(token)) { return 0; }
        if ((ContainsIgnoreCase(token, "USB 4") && ContainsIgnoreCase(token, "v 2")) || ContainsIgnoreCase(token, "80 Gbps")) { return 4080; }
        if (ContainsIgnoreCase(token, "USB 4") || ContainsIgnoreCase(token, "40 Gbps")) { return 4040; }
        if (ContainsIgnoreCase(token, "Gen 2x2") || ContainsIgnoreCase(token, "Gen 2 x 2") || ContainsIgnoreCase(token, "20 Gbps")) { return 3220; }
        if (ContainsIgnoreCase(token, "Gen 2x1") || ContainsIgnoreCase(token, "Gen 2 x 1") || ContainsIgnoreCase(token, "Gen 2") || ContainsIgnoreCase(token, "10 Gbps")) { return 3210; }
        if (ContainsIgnoreCase(token, "Gen 1x1") || ContainsIgnoreCase(token, "Gen 1 x 1") || ContainsIgnoreCase(token, "Gen 1") || ContainsIgnoreCase(token, "5 Gbps") || ContainsIgnoreCase(token, "SuperSpeed")) { return 3205; }
        if (ContainsIgnoreCase(token, "High-Speed") || ContainsIgnoreCase(token, "480 Mbps") || ContainsIgnoreCase(token, "USB 2.0")) { return 2000; }
        if (ContainsIgnoreCase(token, "Full-Speed") || ContainsIgnoreCase(token, "12 Mbps") || ContainsIgnoreCase(token, "USB 1.1")) { return 1100; }
        if (ContainsIgnoreCase(token, "Low-Speed") || ContainsIgnoreCase(token, "1.5 Mbps") || ContainsIgnoreCase(token, "USB 1.0")) { return 1000; }
        return 0;
    }

    public static Dictionary<string, string> BuildUsbControllerMaxSpeedLabelLookup(UsbEnumerationResult usbEnumResult)
    {
        Dictionary<string, string> labels = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, int> ranks = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        if (usbEnumResult == null || usbEnumResult.ControllerCapabilities == null) { return labels; }
        for (int i = 0; i < usbEnumResult.ControllerCapabilities.Count; i++)
        {
            UsbControllerCapabilityRecord cap = usbEnumResult.ControllerCapabilities[i];
            if (cap == null || String.IsNullOrWhiteSpace(cap.HostControllerPath) || String.IsNullOrWhiteSpace(cap.MaxSpeed)) { continue; }
            string ctrlKey = ConvertUsbHostControllerPathToPnpKey(cap.HostControllerPath);
            if (String.IsNullOrWhiteSpace(ctrlKey)) { continue; }
            int rank = cap.MaxSpeedRank;
            if (!labels.ContainsKey(ctrlKey) || rank > ranks[ctrlKey]) { labels[ctrlKey] = cap.MaxSpeed.Trim(); ranks[ctrlKey] = rank; }
        }
        return labels;
    }

    public static List<UsbEndpointRoleSpecRecord> BuildUsbEndpointRoleSpecRecords(UsbEnumerationResult usbEnumResult, string controllerKey, string role, string vidPid, string instanceId, string productString)
    {
        List<UsbEndpointRoleSpecRecord> records = new List<UsbEndpointRoleSpecRecord>();
        if (usbEnumResult == null || usbEnumResult.Endpoints == null) { return records; }
        if (String.IsNullOrWhiteSpace(controllerKey) || String.IsNullOrWhiteSpace(role)) { return records; }
        string sourceId = !String.IsNullOrWhiteSpace(vidPid) ? vidPid : instanceId;
        UsbVidPidParseResult pair = ExtractUsbVidPidFlexible(sourceId, instanceId);
        if (pair == null || !pair.Success) { return records; }
        int mi = ExtractUsbMiNumber(instanceId);
        bool hasMi = mi >= 0;
        string productLabel = (!String.IsNullOrWhiteSpace(productString) && !String.Equals(productString, "<none>", StringComparison.OrdinalIgnoreCase)) ? productString.Trim() : "VID_" + pair.Vid + "&PID_" + pair.Pid;
        string trimmedRole = role.Trim();
        string interfaceKey = hasMi ? "MI_" + mi.ToString("X2") : "MI_ANY";
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < usbEnumResult.Endpoints.Count; i++)
        {
            UsbEndpointRecord ep = usbEnumResult.Endpoints[i];
            if (ep == null || ep.DeviceIsHub || String.IsNullOrWhiteSpace(ep.HostControllerPath)) { continue; }
            string epCtrlKey = ConvertUsbHostControllerPathToPnpKey(ep.HostControllerPath);
            if (String.IsNullOrWhiteSpace(epCtrlKey) || !String.Equals(epCtrlKey, controllerKey, StringComparison.OrdinalIgnoreCase)) { continue; }
            if (!String.Equals(Safe(ep.VendorId), pair.Vid, StringComparison.OrdinalIgnoreCase)) { continue; }
            if (!String.Equals(Safe(ep.ProductId), pair.Pid, StringComparison.OrdinalIgnoreCase)) { continue; }
            if (hasMi && ep.InterfaceNumber != mi) { continue; }
            string token = GetUsbEndpointSpecDisplayToken(ep.UsbVersion, ep.Speed);
            if (String.IsNullOrWhiteSpace(token)) { continue; }
            int rank = GetUsbVersionTokenSortRank(token);
            string entryKey = productLabel + "|" + trimmedRole + "|" + token + "|" + pair.ColonKey + "|" + interfaceKey;
            if (!seen.Add(entryKey)) { continue; }
            records.Add(new UsbEndpointRoleSpecRecord
            {
                EntryKey = entryKey,
                ProductString = productLabel,
                Role = trimmedRole,
                SpeedToken = token,
                Rank = rank,
                VidPid = pair.ColonKey,
                InstanceId = instanceId,
                InterfaceNumber = hasMi ? (int?)mi : null
            });
        }
        return records;
    }

    public static string GetPciLookupInstanceId(string value)
    {
        string text = NormalizeLookupText(value);
        if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
        int enumIndex = text.IndexOf(@"\Enum\", StringComparison.OrdinalIgnoreCase);
        if (enumIndex >= 0) { text = text.Substring(enumIndex + @"\Enum\".Length); }
        int pciIndex = text.IndexOf(@"PCI\", StringComparison.OrdinalIgnoreCase);
        if (pciIndex > 0) { text = text.Substring(pciIndex); }
        if (!text.StartsWith(@"PCI\", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
        return text.Trim('\\');
    }

    public static string GetPciLookupHardwareId(string value)
    {
        string text = NormalizeLookupText(value);
        if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
        int startIndex = 0;
        int pciIndex = text.IndexOf(@"PCI\", StringComparison.OrdinalIgnoreCase);
        if (pciIndex >= 0) { startIndex = pciIndex + @"PCI\".Length; }
        if (startIndex >= text.Length) { return String.Empty; }
        int slashIndex = text.IndexOf('\\', startIndex);
        if (slashIndex > startIndex) { return text.Substring(startIndex, slashIndex - startIndex).Trim(); }
        return text.Substring(startIndex).Trim();
    }

    public static string BuildPciPnpId(string hardwareId)
    {
        if (String.IsNullOrWhiteSpace(hardwareId)) { return String.Empty; }
        Match venMatch = Regex.Match(hardwareId, @"VEN_([0-9A-Fa-f]{4})", RegexOptions.IgnoreCase);
        Match devMatch = Regex.Match(hardwareId, @"DEV_([0-9A-Fa-f]{4})", RegexOptions.IgnoreCase);
        string vendor = venMatch.Success ? "VEN_" + venMatch.Groups[1].Value.ToUpperInvariant() : String.Empty;
        string device = devMatch.Success ? "DEV_" + devMatch.Groups[1].Value.ToUpperInvariant() : String.Empty;
        if (vendor.Length > 0 && device.Length > 0) { return "PCI_" + vendor + "_" + device; }
        if (vendor.Length > 0) { return "PCI_" + vendor + "_UNKNOWN_DEV"; }
        if (device.Length > 0) { return "PCI_UNKNOWN_VEN_" + device; }
        return String.Empty;
    }

    public static string ExtractPciPortId(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        int leafStart = instanceId.LastIndexOf('\\') + 1;
        if (leafStart <= 0 || leafStart >= instanceId.Length) { return String.Empty; }
        string leaf = instanceId.Substring(leafStart);
        if (String.IsNullOrWhiteSpace(leaf)) { return String.Empty; }
        int firstAmp = leaf.IndexOf('&');
        if (firstAmp < 0) { return leaf; }
        int secondAmp = leaf.IndexOf('&', firstAmp + 1);
        if (secondAmp < 0) { return leaf; }
        int thirdAmp = leaf.IndexOf('&', secondAmp + 1);
        if (thirdAmp < 0) { return leaf; }
        return leaf.Substring(0, thirdAmp);
    }

    public static PciLookupFields ParsePciLookupFields(string value)
    {
        PciLookupFields fields = new PciLookupFields();
        fields.InstanceId = GetPciLookupInstanceId(value);
        fields.HardwareId = GetPciLookupHardwareId(!String.IsNullOrWhiteSpace(fields.InstanceId) ? fields.InstanceId : value);
        fields.PNPID = BuildPciPnpId(fields.HardwareId);
        fields.PortId = ExtractPciPortId(fields.InstanceId);
        return fields;
    }

    public static string ExtractPciDevId(string text)
    {
        return FindHex4TokenValue(text, "DEV_");
    }

    public static string ExtractPciVenDevToken(string text)
    {
        string ven = FindHex4TokenValue(text, "VEN_");
        string dev = FindHex4TokenValue(text, "DEV_");
        if (ven == null || dev == null) { return null; }
        return "VEN_" + ven + "&DEV_" + dev;
    }

    public static bool ContainsOrdinalIgnoreCase(string text, string value)
    {
        return !String.IsNullOrEmpty(text) && !String.IsNullOrEmpty(value) && text.IndexOf(value, StringComparison.OrdinalIgnoreCase) >= 0;
    }

    public static bool ContainsUsbVidPidColonKey(string text, string colonKey)
    {
        if (String.IsNullOrWhiteSpace(text) || String.IsNullOrWhiteSpace(colonKey)) { return false; }
        UsbVidPidParseResult expected = ParsePlainVidPidPair(colonKey);
        if (expected == null || !expected.Success) { expected = ExtractUsbVidPid(colonKey); }
        if (expected == null || !expected.Success) { return false; }
        UsbVidPidParseResult actual = ExtractUsbVidPid(text);
        if (actual != null && actual.Success)
        {
            return String.Equals(actual.Vid, expected.Vid, StringComparison.OrdinalIgnoreCase) && String.Equals(actual.Pid, expected.Pid, StringComparison.OrdinalIgnoreCase);
        }
        string vidToken = "VID_" + expected.Vid;
        string pidToken = "PID_" + expected.Pid;
        return ContainsOrdinalIgnoreCase(text, vidToken) && ContainsOrdinalIgnoreCase(text, pidToken);
    }

    public static int ExtractUsbRootPortFromLocationPath(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return -1; }
        const string root = "USBROOT(";
        int rootIndex = text.IndexOf(root, StringComparison.OrdinalIgnoreCase);
        if (rootIndex < 0) { return -1; }
        int afterRoot = text.IndexOf(")#USB(", rootIndex + root.Length, StringComparison.OrdinalIgnoreCase);
        if (afterRoot < 0) { return -1; }
        int digitStart = afterRoot + ")#USB(".Length;
        int i = digitStart;
        while (i < text.Length && IsDigit(text[i])) { i++; }
        if (i == digitStart || i >= text.Length || text[i] != ')') { return -1; }
        int value;
        return Int32.TryParse(text.Substring(digitStart, i - digitStart), out value) ? value : -1;
    }

    public static int ExtractUsbRootPortFromLocationInfo(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return -1; }
        const string prefix = "Port_#";
        int start = text.IndexOf(prefix, StringComparison.OrdinalIgnoreCase);
        while (start >= 0)
        {
            int digitStart = start + prefix.Length;
            int i = digitStart;
            while (i < text.Length && IsDigit(text[i])) { i++; }
            if (i > digitStart && i + ".Hub_#0001".Length <= text.Length && String.Compare(text, i, ".Hub_#0001", 0, ".Hub_#0001".Length, true, System.Globalization.CultureInfo.InvariantCulture) == 0)
            {
                int value;
                return Int32.TryParse(text.Substring(digitStart, i - digitStart), out value) ? value : -1;
            }
            int next = start + 1;
            if (next >= text.Length) { break; }
            start = text.IndexOf(prefix, next, StringComparison.OrdinalIgnoreCase);
        }
        return -1;
    }

    public static BdfLocationParseResult ParseBdfLocation(string text)
    {
        BdfLocationParseResult result = new BdfLocationParseResult();
        if (String.IsNullOrWhiteSpace(text)) { return result; }
        string s = text.TrimEnd();
        if (!s.EndsWith(")", StringComparison.Ordinal)) { return result; }
        int open = s.LastIndexOf('(');
        if (open < 0 || open + 1 >= s.Length) { return result; }
        string body = s.Substring(open + 1, s.Length - open - 2);
        string[] parts = body.Split(',');
        if (parts.Length != 3) { return result; }
        int bus, dev, fn;
        if (!Int32.TryParse(parts[0].Trim(), out bus)) { return result; }
        if (!Int32.TryParse(parts[1].Trim(), out dev)) { return result; }
        if (!Int32.TryParse(parts[2].Trim(), out fn)) { return result; }
        result.Success = true;
        result.Bus = bus;
        result.Device = dev;
        result.Function = fn;
        return result;
    }

    public static bool ContainsCpuColocationDescription(string text)
    {
        return ContainsIgnoreCase(text, "Basic Display Adapter") || ContainsIgnoreCase(text, "Encryption/Decryption") || ContainsIgnoreCase(text, @"Encryption\Decryption");
    }

    public static bool ContainsGameControllerText(string text)
    {
        return ContainsIgnoreCase(text, "game controller") || ContainsIgnoreCase(text, "Xbox");
    }

    public static PciIdentityFields ParsePciIdentity(string instanceId, string registryPath)
    {
        string raw = !String.IsNullOrWhiteSpace(instanceId) ? instanceId : registryPath;
        PciIdentityFields result = new PciIdentityFields();
        if (String.IsNullOrWhiteSpace(raw)) { return result; }
        string ven = FindHex4TokenValue(raw, "VEN_");
        string dev = FindHex4TokenValue(raw, "DEV_");
        if (ven == null || dev == null) { return result; }
        result.Success = true;
        result.VendorId = ven;
        result.DeviceId = dev;
        string subsys = FindHex8TokenValue(raw, "SUBSYS_");
        if (subsys != null)
        {
            result.SubDeviceId = subsys.Substring(0, 4);
            result.SubVendorId = subsys.Substring(4, 4);
        }
        string subven = FindHex4TokenValue(raw, "SUBVEN_");
        if (subven != null) { result.SubVendorId = subven; }
        string subdev = FindHex4TokenValue(raw, "SUBDEV_");
        if (subdev != null) { result.SubDeviceId = subdev; }
        return result;
    }
}


