    public static DeviceTweakerStartupModel BuildStartupModel()
    {
        return BuildFullStartupPayload(new DeviceTweakerStartupOptions());
    }

    public static Task<DeviceTweakerStartupPayload> StartFullStartupPayloadTask(DeviceTweakerStartupOptions options)
    {
        DeviceTweakerStartupOptions captured = CloneStartupOptions(options);
        return Task.Factory.StartNew(
            () => BuildFullStartupPayload(captured),
            CancellationToken.None,
            TaskCreationOptions.DenyChildAttach,
            TaskScheduler.Default);
    }

    private static DeviceTweakerStartupOptions CloneStartupOptions(DeviceTweakerStartupOptions options)
    {
        DeviceTweakerStartupOptions clone = new DeviceTweakerStartupOptions();
        if (options == null) { return clone; }
        clone.IncludeLogs = options.IncludeLogs;
        clone.IncludeUiReadyState = options.IncludeUiReadyState;
        clone.PciIdsPath = options.PciIdsPath == null ? String.Empty : options.PciIdsPath;
        if (options.IgnoredAudioNames == null || options.IgnoredAudioNames.Length == 0)
        {
            clone.IgnoredAudioNames = new string[0];
        }
        else
        {
            clone.IgnoredAudioNames = new string[options.IgnoredAudioNames.Length];
            Array.Copy(options.IgnoredAudioNames, clone.IgnoredAudioNames, options.IgnoredAudioNames.Length);
        }
        return clone;
    }

    public static DeviceTweakerStartupPayload CompleteFullStartupPayloadTask(Task<DeviceTweakerStartupPayload> task)
    {
        if (task == null) { return null; }
        return task.GetAwaiter().GetResult();
    }

    public static AudioEndpointInfo[] BuildAudioEndpointParentRows(DeviceDiscoveryModel model, string[] ignoredAudioNames)
    {
        List<AudioEndpointInfo> rows = BuildStartupAudioEndpointParentRows(model, ignoredAudioNames, null);
        return rows == null ? new AudioEndpointInfo[0] : rows.ToArray();
    }

