    private static Task<T> StartStartupWorker<T>(Func<T> work)
    {
        return Task.Factory.StartNew(
            work,
            CancellationToken.None,
            TaskCreationOptions.DenyChildAttach,
            TaskScheduler.Default);
    }

    private static T GetStartupTaskResult<T>(Task<T> task, T fallback)
    {
        if (task == null) { return fallback; }
        try
        {
            T value = task.GetAwaiter().GetResult();
            return ((object)value) == null ? fallback : value;
        }
        catch { return fallback; }
    }

    private static void WaitForStartupWorkers(params Task[] tasks)
    {
        if (tasks == null || tasks.Length == 0) { return; }
        List<Task> waitTasks = new List<Task>();
        for (int i = 0; i < tasks.Length; i++)
        {
            if (tasks[i] != null) { waitTasks.Add(tasks[i]); }
        }
        if (waitTasks.Count == 0) { return; }
        try { Task.WaitAll(waitTasks.ToArray()); } catch { }
    }

    private static StartupReservedCpuSetsSnapshot ReadReservedCpuSetsSnapshot()
    {
        StartupReservedCpuSetsSnapshot snapshot = new StartupReservedCpuSetsSnapshot();
        try
        {
            snapshot.Bytes = DeviceTweakerRegistrySnapshot.ReadReservedCpuSetsBytes();
            snapshot.HasReservedCpuSets = (snapshot.Bytes != null);
        }
        catch
        {
            snapshot.Bytes = null;
            snapshot.HasReservedCpuSets = false;
        }
        snapshot.Loaded = true;
        return snapshot;
    }

