    private static StartupUsbDiscoveryResult BuildStartupUsbDiscoveryPartial(DeviceDiscoveryModel discoveryModel, StartupAudioParentsResult audioParents, DeviceTweakerStartupOptions options, bool includeLogs)
    {
        StartupUsbDiscoveryResult result = new StartupUsbDiscoveryResult();
        try
        {
            DeviceTweakerStartupPayload partialStartup = new DeviceTweakerStartupPayload();
            partialStartup.DiscoveryModel = discoveryModel == null ? new DeviceDiscoveryModel() : discoveryModel;

            if (audioParents != null && audioParents.Rows != null)
            {
                for (int i = 0; i < audioParents.Rows.Count; i++)
                {
                    if (audioParents.Rows[i] != null) { partialStartup.AudioEndpointParentRows.Add(audioParents.Rows[i]); }
                }
                partialStartup.AudioEndpointParentRowsComplete = audioParents.Complete;
            }

            DeviceTweakerStartupOptions localOptions = CloneStartupOptions(options);
            localOptions.IncludeLogs = includeLogs;
            UsbDiscoveryResult usb = BuildUsbDiscovery(partialStartup, localOptions);
            result.Result = usb;
            result.Complete = (usb != null);

            if (partialStartup.HidRows != null)
            {
                for (int i = 0; i < partialStartup.HidRows.Count; i++)
                {
                    if (partialStartup.HidRows[i] != null) { result.HidRows.Add(partialStartup.HidRows[i]); }
                }
            }
            if (partialStartup.UsbEndpointDescriptors != null)
            {
                foreach (KeyValuePair<string, UsbEndpointRecord> kv in partialStartup.UsbEndpointDescriptors)
                {
                    if (!String.IsNullOrWhiteSpace(kv.Key) && kv.Value != null) { result.EndpointDescriptors[kv.Key] = kv.Value; }
                }
            }
            if (partialStartup.AudioEndpointParentRows != null)
            {
                for (int i = 0; i < partialStartup.AudioEndpointParentRows.Count; i++)
                {
                    if (partialStartup.AudioEndpointParentRows[i] != null) { result.AudioParentRows.Add(partialStartup.AudioEndpointParentRows[i]); }
                }
            }
            if (includeLogs && partialStartup.AudioEndpointSourceLogs != null)
            {
                for (int i = 0; i < partialStartup.AudioEndpointSourceLogs.Count; i++)
                {
                    if (!String.IsNullOrWhiteSpace(partialStartup.AudioEndpointSourceLogs[i])) { result.AudioParentLogs.Add(partialStartup.AudioEndpointSourceLogs[i]); }
                }
            }
            result.AudioParentRowsComplete = partialStartup.AudioEndpointParentRowsComplete;
        }
        catch
        {
            result.Result = null;
            result.Complete = false;
        }
        return result;
    }

    private static StartupPciRowsResult BuildStartupPciRowsPartial(DeviceDiscoveryModel model, StartupAudioParentsResult audioParents, StartupUsbDiscoveryResult usbResult, string[] ignoredAudioNames, string pciIdsPath)
    {
        StartupPciRowsResult result = new StartupPciRowsResult();
        result.Result = null;
        result.Complete = false;
        try
        {
            List<AudioEndpointInfo> audioParentRows = new List<AudioEndpointInfo>();
            if (audioParents != null && audioParents.Rows != null)
            {
                for (int i = 0; i < audioParents.Rows.Count; i++) { if (audioParents.Rows[i] != null) { audioParentRows.Add(audioParents.Rows[i]); } }
            }
            if ((audioParents == null || !audioParents.Complete || audioParentRows.Count == 0) && usbResult != null && usbResult.AudioParentRows != null && usbResult.AudioParentRows.Count > 0)
            {
                audioParentRows.Clear();
                for (int i = 0; i < usbResult.AudioParentRows.Count; i++) { if (usbResult.AudioParentRows[i] != null) { audioParentRows.Add(usbResult.AudioParentRows[i]); } }
            }

            List<AudioEndpointInfo> audioForPci = audioParentRows;
            if (usbResult != null && usbResult.Result != null && usbResult.Result.AudioDetails != null && usbResult.Result.AudioDetails.Count > 0)
            {
                audioForPci = usbResult.Result.AudioDetails;
            }

            result.Result = BuildPciDisplayRecords(model, audioForPci, audioParentRows, ignoredAudioNames, pciIdsPath);
            result.Complete = (result.Result != null);
        }
        catch
        {
            result.Result = null;
            result.Complete = false;
        }
        return result;
    }

    private static void MergeStartupAudioParents(DeviceTweakerStartupPayload startup, StartupAudioParentsResult result)
    {
        if (startup == null || result == null) { return; }
        if (result.Rows != null)
        {
            for (int i = 0; i < result.Rows.Count; i++)
            {
                if (result.Rows[i] != null) { startup.AudioEndpointParentRows.Add(result.Rows[i]); }
            }
        }
        if (result.Logs != null)
        {
            for (int i = 0; i < result.Logs.Count; i++)
            {
                if (!String.IsNullOrWhiteSpace(result.Logs[i])) { startup.AudioEndpointSourceLogs.Add(result.Logs[i]); }
            }
        }
        startup.AudioEndpointParentRowsComplete = result.Complete;
    }

    private static void MergeRecoveredStartupAudioParents(DeviceTweakerStartupPayload startup, StartupUsbDiscoveryResult result)
    {
        if (startup == null || result == null || !result.AudioParentRowsComplete) { return; }
        if (startup.AudioEndpointParentRowsComplete && startup.AudioEndpointParentRows.Count > 0) { return; }
        startup.AudioEndpointParentRows.Clear();
        if (result.AudioParentRows != null)
        {
            for (int i = 0; i < result.AudioParentRows.Count; i++)
            {
                if (result.AudioParentRows[i] != null) { startup.AudioEndpointParentRows.Add(result.AudioParentRows[i]); }
            }
        }
        if (result.AudioParentLogs != null)
        {
            for (int i = 0; i < result.AudioParentLogs.Count; i++)
            {
                if (!String.IsNullOrWhiteSpace(result.AudioParentLogs[i])) { startup.AudioEndpointSourceLogs.Add(result.AudioParentLogs[i]); }
            }
        }
        startup.AudioEndpointParentRowsComplete = true;
    }

    private static void MergeStartupUsbDiscovery(DeviceTweakerStartupPayload startup, StartupUsbDiscoveryResult result, bool includeLogs)
    {
        if (startup == null || result == null || result.Result == null)
        {
            if (startup != null) { startup.UsbRowsComplete = false; }
            return;
        }
        UsbDiscoveryResult usb = result.Result;
        if (usb.Devices != null) { for (int i = 0; i < usb.Devices.Count; i++) { if (usb.Devices[i] != null) { startup.UsbControllerRows.Add(usb.Devices[i]); } } }
        if (usb.AudioDetails != null) { for (int i = 0; i < usb.AudioDetails.Count; i++) { if (usb.AudioDetails[i] != null) { startup.UsbAudioEndpointRows.Add(usb.AudioDetails[i]); } } }
        if (usb.UnusedCpuControllers != null) { for (int i = 0; i < usb.UnusedCpuControllers.Count; i++) { if (!String.IsNullOrWhiteSpace(usb.UnusedCpuControllers[i])) { startup.UsbUnusedCpuControllers.Add(usb.UnusedCpuControllers[i]); } } }
        if (includeLogs && usb.Logs != null) { for (int i = 0; i < usb.Logs.Count; i++) { if (!String.IsNullOrWhiteSpace(usb.Logs[i])) { startup.UsbSourceLogs.Add(usb.Logs[i]); } } }
        if (result.HidRows != null) { for (int i = 0; i < result.HidRows.Count; i++) { if (result.HidRows[i] != null) { startup.HidRows.Add(result.HidRows[i]); } } }
        if (result.EndpointDescriptors != null)
        {
            foreach (KeyValuePair<string, UsbEndpointRecord> kv in result.EndpointDescriptors)
            {
                if (!String.IsNullOrWhiteSpace(kv.Key) && kv.Value != null) { startup.UsbEndpointDescriptors[kv.Key] = kv.Value; }
            }
        }
        startup.UsbRowsComplete = result.Complete;
    }

    private static void MergeStartupPciRows(DeviceTweakerStartupPayload startup, StartupPciRowsResult result, bool includeLogs)
    {
        if (startup == null || result == null || result.Result == null)
        {
            if (startup != null) { startup.PciRowsComplete = false; }
            return;
        }
        PciDiscoveryResult pci = result.Result;
        if (pci.GPU != null) { for (int i = 0; i < pci.GPU.Count; i++) { if (pci.GPU[i] != null) { startup.PciGpuRows.Add(pci.GPU[i]); } } }
        if (pci.Audio != null) { for (int i = 0; i < pci.Audio.Count; i++) { if (pci.Audio[i] != null) { startup.PciAudioRows.Add(pci.Audio[i]); } } }
        if (includeLogs && pci.Logs != null) { for (int i = 0; i < pci.Logs.Count; i++) { if (!String.IsNullOrWhiteSpace(pci.Logs[i])) { startup.PciSourceLogs.Add(pci.Logs[i]); } } }
        startup.PciRowsComplete = result.Complete;
    }

    private static void MergeStartupStorageRows(DeviceTweakerStartupPayload startup, StartupStorageRowsResult result)
    {
        if (startup == null || result == null)
        {
            if (startup != null) { startup.StorageRowsComplete = false; }
            return;
        }
        if (result.Rows != null) { for (int i = 0; i < result.Rows.Count; i++) { if (result.Rows[i] != null) { startup.StorageRows.Add(result.Rows[i]); } } }
        if (result.Logs != null) { for (int i = 0; i < result.Logs.Count; i++) { if (!String.IsNullOrWhiteSpace(result.Logs[i])) { startup.StorageSourceLogs.Add(result.Logs[i]); } } }
        startup.StorageRowsComplete = result.Complete;
    }

    private static void MergeStartupNetworkRows(DeviceTweakerStartupPayload startup, StartupNetworkRowsResult result)
    {
        if (startup == null || result == null)
        {
            if (startup != null) { startup.NetworkRowsComplete = false; }
            return;
        }
        if (result.Rows != null) { for (int i = 0; i < result.Rows.Count; i++) { if (result.Rows[i] != null) { startup.NetworkAdapterRows.Add(result.Rows[i]); } } }
        if (result.Logs != null) { for (int i = 0; i < result.Logs.Count; i++) { if (!String.IsNullOrWhiteSpace(result.Logs[i])) { startup.NetworkSourceLogs.Add(result.Logs[i]); } } }
        startup.NetworkRowsComplete = result.Complete;
    }

    private static void MergeStartupResourceRows(DeviceTweakerStartupPayload startup, StartupResourceRowsPartial result)
    {
        if (startup == null || result == null)
        {
            if (startup != null)
            {
                startup.IrqRowsComplete = false;
                startup.DeviceAddressRowsComplete = false;
            }
            return;
        }
        if (result.IrqAllocationRows != null)
        {
            for (int i = 0; i < result.IrqAllocationRows.Count; i++)
            {
                if (result.IrqAllocationRows[i] != null) { startup.IrqAllocationRows.Add(result.IrqAllocationRows[i]); }
            }
        }
        if (result.DeviceAddressByPnpId != null)
        {
            foreach (KeyValuePair<string, ulong> kv in result.DeviceAddressByPnpId)
            {
                if (!String.IsNullOrWhiteSpace(kv.Key) && !startup.DeviceAddressByPnpId.ContainsKey(kv.Key)) { startup.DeviceAddressByPnpId[kv.Key] = kv.Value; }
            }
        }
        startup.IrqRowsComplete = result.Complete;
        startup.DeviceAddressRowsComplete = result.Complete;
    }

    public static DeviceTweakerStartupPayload BuildFullStartupPayload(DeviceTweakerStartupOptions options)
    {
        System.Diagnostics.Stopwatch sw = System.Diagnostics.Stopwatch.StartNew();
        if (options == null) { options = new DeviceTweakerStartupOptions(); }
        bool includeLogs = options.IncludeLogs;
        bool includeUiReadyState = options.IncludeUiReadyState;
        string[] ignoredAudioNames = options.IgnoredAudioNames == null ? new string[0] : (string[])options.IgnoredAudioNames.Clone();
        string pciIdsPath = options.PciIdsPath == null ? String.Empty : options.PciIdsPath;
        DeviceTweakerStartupOptions capturedOptions = CloneStartupOptions(options);

        DeviceTweakerStartupPayload startup = new DeviceTweakerStartupPayload();
        try { startup.StartupSourceLogs.Add("BuildFullStartupPayload: native startup discovery started"); } catch { }

        Task<CpuStartupTopologyModel> cpuTask = StartStartupWorker<CpuStartupTopologyModel>(() =>
        {
            try { return BuildCpuStartupTopologyModel(); }
            catch { return new CpuStartupTopologyModel(); }
        });

        Task<StartupReservedCpuSetsSnapshot> reservedTask = StartStartupWorker<StartupReservedCpuSetsSnapshot>(() => ReadReservedCpuSetsSnapshot());

        Task<DeviceDiscoveryModel> modelTask = StartStartupWorker<DeviceDiscoveryModel>(() =>
        {
            try { return BuildModel(); }
            catch { return new DeviceDiscoveryModel(); }
        });

        Task<StartupNetworkRowsResult> networkTask = StartStartupWorker<StartupNetworkRowsResult>(() => BuildStartupNetworkRowsPartial(pciIdsPath, includeLogs));
        Task<StartupResourceRowsPartial> resourceTask = StartStartupWorker<StartupResourceRowsPartial>(() => BuildStartupResourceRowsPartial());

        DeviceDiscoveryModel discoveryModel = GetStartupTaskResult<DeviceDiscoveryModel>(modelTask, new DeviceDiscoveryModel());
        if (discoveryModel == null) { discoveryModel = new DeviceDiscoveryModel(); }
        startup.DiscoveryModel = discoveryModel;

        try { HydrateStartupDiscoveryMaps(startup); } catch { }

        Task<StartupAudioParentsResult> audioTask = StartStartupWorker<StartupAudioParentsResult>(() => BuildStartupAudioEndpointParentsPartial(discoveryModel, ignoredAudioNames, includeLogs));
        Task<StartupStorageRowsResult> storageTask = StartStartupWorker<StartupStorageRowsResult>(() => BuildStartupStorageRowsPartial(discoveryModel, includeLogs));

        Task<StartupUsbDiscoveryResult> usbTask = audioTask.ContinueWith<StartupUsbDiscoveryResult>(antecedent =>
        {
            StartupAudioParentsResult audioResult = null;
            try { if (antecedent != null && antecedent.Status == TaskStatus.RanToCompletion) { audioResult = antecedent.Result; } } catch { audioResult = null; }
            if (audioResult == null) { audioResult = new StartupAudioParentsResult(); }
            return BuildStartupUsbDiscoveryPartial(discoveryModel, audioResult, capturedOptions, includeLogs);
        }, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default);

        Task<StartupPciRowsResult> pciTask = usbTask.ContinueWith<StartupPciRowsResult>(antecedent =>
        {
            StartupUsbDiscoveryResult usbResult = null;
            try { if (antecedent != null && antecedent.Status == TaskStatus.RanToCompletion) { usbResult = antecedent.Result; } } catch { usbResult = null; }
            StartupAudioParentsResult audioResult = GetStartupTaskResult<StartupAudioParentsResult>(audioTask, new StartupAudioParentsResult());
            return BuildStartupPciRowsPartial(discoveryModel, audioResult, usbResult, ignoredAudioNames, pciIdsPath);
        }, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default);

        WaitForStartupWorkers(cpuTask, reservedTask, audioTask, usbTask, pciTask, storageTask, networkTask, resourceTask);

        startup.CpuTopology = GetStartupTaskResult<CpuStartupTopologyModel>(cpuTask, new CpuStartupTopologyModel());
        if (startup.CpuTopology == null) { startup.CpuTopology = new CpuStartupTopologyModel(); }

        StartupReservedCpuSetsSnapshot reserved = GetStartupTaskResult<StartupReservedCpuSetsSnapshot>(reservedTask, new StartupReservedCpuSetsSnapshot());
        startup.ReservedCpuSetsBytes = reserved.Bytes;
        startup.HasReservedCpuSets = reserved.HasReservedCpuSets;
        startup.ReservedCpuSetsSnapshotLoaded = reserved.Loaded;

        StartupAudioParentsResult audioParents = GetStartupTaskResult<StartupAudioParentsResult>(audioTask, new StartupAudioParentsResult());
        MergeStartupAudioParents(startup, audioParents);

        StartupUsbDiscoveryResult usbDiscovery = GetStartupTaskResult<StartupUsbDiscoveryResult>(usbTask, new StartupUsbDiscoveryResult());
        MergeRecoveredStartupAudioParents(startup, usbDiscovery);
        MergeStartupUsbDiscovery(startup, usbDiscovery, includeLogs);

        StartupPciRowsResult pciRows = GetStartupTaskResult<StartupPciRowsResult>(pciTask, new StartupPciRowsResult());
        MergeStartupPciRows(startup, pciRows, includeLogs);

        StartupStorageRowsResult storageRows = GetStartupTaskResult<StartupStorageRowsResult>(storageTask, new StartupStorageRowsResult());
        MergeStartupStorageRows(startup, storageRows);

        StartupNetworkRowsResult networkRows = GetStartupTaskResult<StartupNetworkRowsResult>(networkTask, new StartupNetworkRowsResult());
        MergeStartupNetworkRows(startup, networkRows);

        StartupResourceRowsPartial resourceRows = GetStartupTaskResult<StartupResourceRowsPartial>(resourceTask, new StartupResourceRowsPartial());
        MergeStartupResourceRows(startup, resourceRows);

        try { HydrateStartupAllDeviceRows(startup); } catch { }
        try { SeedStartupRegistryState(startup); } catch { }
        try
        {
            if (includeUiReadyState)
            {
                BuildStartupUiReadyState(startup);
                startup.UiStateComplete = true;
            }
            else { startup.UiStateComplete = false; }
        }
        catch { startup.UiStateComplete = false; }

        sw.Stop();
        startup.NativeBuildMilliseconds = sw.Elapsed.TotalMilliseconds;
        try { startup.StartupSourceLogs.Add("BuildFullStartupPayload: native startup discovery completed in " + sw.Elapsed.TotalMilliseconds.ToString("0.###") + " ms"); } catch { }
        return startup;
    }

    private static void HydrateStartupDiscoveryMaps(DeviceTweakerStartupModel startup)
    {
        if (startup == null || startup.DiscoveryModel == null) { return; }
        DeviceDiscoveryModel model = startup.DiscoveryModel;

        if (model.EndpointDescriptors != null)
        {
            foreach (KeyValuePair<string, UsbEndpointRecord> kv in model.EndpointDescriptors)
            {
                if (!String.IsNullOrWhiteSpace(kv.Key) && kv.Value != null) { startup.UsbEndpointDescriptors[kv.Key] = kv.Value; }
            }
        }

        if (model.HidInterfaces != null)
        {
            foreach (KeyValuePair<string, HidInterfaceInfo> kv in model.HidInterfaces)
            {
                HidInterfaceInfo hid = kv.Value;
                if (hid == null) { continue; }
                string key = FirstNonEmpty(hid.Instance, kv.Key);
                if (String.IsNullOrWhiteSpace(key)) { continue; }
                string role = ClassifyHidRoleFromInstanceAndProduct(key, hid.Product);
                if (!String.IsNullOrWhiteSpace(role)) { startup.HidRoleByInstanceId[key] = role; }
            }
        }

        if (model.AudioEndpoints != null)
        {
            foreach (KeyValuePair<string, DeviceNode> kv in model.AudioEndpoints)
            {
                DeviceNode node = kv.Value;
                if (node == null || String.IsNullOrWhiteSpace(kv.Key)) { continue; }
                startup.AudioEndpointByInstanceId[kv.Key] = FirstNonEmpty(node.FriendlyName, node.DeviceDesc, node.InstanceId);
            }
        }
    }

    private static List<AudioEndpointInfo> BuildStartupAudioEndpointParentRows(DeviceDiscoveryModel model, string[] ignoredAudioNames, List<string> logs)
    {
        List<AudioEndpointInfo> rows = new List<AudioEndpointInfo>();
        if (model == null || model.AudioEndpoints == null || model.AudioEndpoints.Count == 0) { return rows; }

        HashSet<string> ignoredSet = BuildStringSet(ignoredAudioNames);
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        List<string> endpointIdsForFormFactor = new List<string>(model.AudioEndpoints.Count);
        foreach (KeyValuePair<string, DeviceNode> ffKv in model.AudioEndpoints)
        {
            DeviceNode ffEndpoint = ffKv.Value;
            string ffEndpointId = FirstNonEmpty(ffEndpoint == null ? null : ffEndpoint.InstanceId, ffKv.Key);
            string ffEndpointName = FirstNonEmpty(ffEndpoint == null ? null : ffEndpoint.FriendlyName, ffEndpoint == null ? null : ffEndpoint.DeviceDesc, ffEndpointId);
            if (!String.IsNullOrWhiteSpace(ffEndpointName) && ignoredSet.Contains(ffEndpointName)) { continue; }
            if (!String.IsNullOrWhiteSpace(ffEndpointId)) { endpointIdsForFormFactor.Add(ffEndpointId); }
        }

        Dictionary<string, AudioEndpointFormFactorInfo> formFactorInfoByEndpointId = BuildAudioEndpointFormFactorInfoMap(endpointIdsForFormFactor);

        foreach (KeyValuePair<string, DeviceNode> kv in model.AudioEndpoints)
        {
            DeviceNode endpoint = kv.Value;
            if (endpoint == null) { continue; }

            string endpointId = FirstNonEmpty(endpoint.InstanceId, kv.Key);
            string endpointName = FirstNonEmpty(endpoint.FriendlyName, endpoint.DeviceDesc, endpointId);
            if (String.IsNullOrWhiteSpace(endpointId)) { continue; }

            if (!String.IsNullOrWhiteSpace(endpointName) && ignoredSet.Contains(endpointName))
            {
                if (logs != null) { logs.Add("Optimized-TestAudioDeviceParents: Endpoint ignored by name -> AudioDevice='" + SafeText(endpointName) + "' InstanceId='" + SafeText(endpointId) + "'"); }
                continue;
            }

            AudioEndpointFormFactorInfo formFactorInfo;
            if (formFactorInfoByEndpointId == null || !formFactorInfoByEndpointId.TryGetValue(endpointId, out formFactorInfo) || formFactorInfo == null) { formFactorInfo = CreateUnavailableAudioEndpointFormFactorInfo(); }
            string audioType = !String.IsNullOrWhiteSpace(formFactorInfo.AudioType) ? formFactorInfo.AudioType : "Audio";

            AudioEndpointParentResolution parentResolution = ResolveAudioEndpointParentWithCfgMgr(model, endpointId);
            string controllerId = parentResolution.ControllerId;
            string usbVidPid = !String.IsNullOrWhiteSpace(parentResolution.UsbVidPid) ? parentResolution.UsbVidPid : ExtractVidPidPair(endpointId);

            string key = controllerId + "|" + endpointId + "|" + audioType;
            if (!seen.Add(key)) { continue; }

            AudioEndpointInfo row = new AudioEndpointInfo();
            row.AudioDevice = endpointName;
            row.AudioType = audioType;
            row.ControllerID = controllerId;
            row.UsbVidPid = usbVidPid;
            row.InstanceId = endpointId;
            row.FormFactorName = formFactorInfo.FormFactorName;
            row.FormFactorValue = formFactorInfo.FormFactorValue;
            row.Reason = formFactorInfo.Reason;
            rows.Add(row);

            if (logs != null)
            {
                logs.Add("Optimized-TestAudioDeviceParents: Endpoint mapped -> AudioDevice='" + SafeText(endpointName) + "' AudioType='" + SafeText(audioType) + "' Controller='" + SafeText(controllerId) + "' InstanceId='" + SafeText(endpointId) + "' ParentResolver='" + (parentResolution.UsedNativePath ? "CM_Get_Parent" : "native model fallback") + "' Reason='" + SafeText(formFactorInfo.Reason) + "'");
            }
        }

        return rows;
    }

    private static AudioEndpointParentResolution ResolveAudioEndpointParentWithCfgMgr(DeviceDiscoveryModel model, string endpointId)
    {
        AudioEndpointParentResolution result = new AudioEndpointParentResolution();
        if (String.IsNullOrWhiteSpace(endpointId)) { return result; }

        string usbVidPid = ExtractVidPidPair(endpointId);
        uint currentDevInst;
        if (TryLocateDeviceInstance(endpointId, out currentDevInst))
        {
            HashSet<string> visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string currentId = endpointId;
            for (int depth = 0; depth < 16 && currentDevInst != 0; depth++)
            {
                if (!String.IsNullOrWhiteSpace(currentId) && !visited.Add(currentId)) { break; }

                uint parentDevInst;
                string parentId = GetParentDeviceIdFromDevInst(currentDevInst, out parentDevInst);
                if (String.IsNullOrWhiteSpace(parentId) || parentDevInst == 0) { break; }

                result.UsedNativePath = true;
                string parentVidPid = ExtractVidPidPair(parentId);
                if (String.IsNullOrWhiteSpace(usbVidPid) && !String.IsNullOrWhiteSpace(parentVidPid)) { usbVidPid = parentVidPid; }

                if (StartsWithPnp(parentId, "PCI\\"))
                {
                    result.ControllerId = ToPnpId(parentId);
                    result.UsbVidPid = usbVidPid;
                    return result;
                }

                if (IsUsbControllerId(model, parentId))
                {
                    result.ControllerId = ToPnpId(parentId);
                    result.UsbVidPid = usbVidPid;
                    return result;
                }

                currentId = parentId;
                currentDevInst = parentDevInst;
            }
        }

        string assocController = FindControllerForDevice(model, endpointId);
        if (!String.IsNullOrWhiteSpace(assocController))
        {
            result.ControllerId = assocController;
        }
        else
        {
            string pciParent = FindPciParentForDevice(model, endpointId);
            if (!String.IsNullOrWhiteSpace(pciParent)) { result.ControllerId = pciParent; }
        }

        result.UsbVidPid = !String.IsNullOrWhiteSpace(usbVidPid) ? usbVidPid : ExtractVidPidPair(endpointId);
        return result;
    }

    private static bool TryLocateDeviceInstance(string instanceId, out uint devInst)
    {
        devInst = 0;
        if (String.IsNullOrWhiteSpace(instanceId)) { return false; }
        try
        {
            return CM_Locate_DevNode(out devInst, instanceId, CM_LOCATE_DEVNODE_NORMAL) == CONFIGRET_SUCCESS && devInst != 0;
        }
        catch
        {
            devInst = 0;
            return false;
        }
    }

    private static string GetParentDeviceIdFromDevInst(uint devInst, out uint parentDevInst)
    {
        parentDevInst = 0;
        if (devInst == 0) { return String.Empty; }
        try
        {
            if (CM_Get_Parent(out parentDevInst, devInst, 0) != CONFIGRET_SUCCESS || parentDevInst == 0) { return String.Empty; }
            return GetDeviceIdFromDevInst(parentDevInst);
        }
        catch
        {
            parentDevInst = 0;
            return String.Empty;
        }
    }

    private static string GetDeviceIdFromDevInst(uint devInst)
    {
        if (devInst == 0) { return String.Empty; }

        uint size = 0;
        int cr = CM_Get_Device_ID_Size(out size, devInst, 0);
        int capacity = (cr == CONFIGRET_SUCCESS && size > 0 && size < 32768) ? (int)size + 2 : 1024;
        StringBuilder sb = new StringBuilder(capacity);
        cr = CM_Get_Device_ID(devInst, sb, (uint)sb.Capacity, 0);
        if (cr == CONFIGRET_SUCCESS) { return sb.ToString(); }
        return String.Empty;
    }

    private static string InferAudioEndpointType(string name, string instanceId, DeviceNode node)
    {
        string text = (name ?? String.Empty) + " " + (instanceId ?? String.Empty) + " " + (node == null ? String.Empty : FirstNonEmpty(node.FriendlyName, node.DeviceDesc, node.Service));
        if (text.IndexOf("microphone", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("mic", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("capture", StringComparison.OrdinalIgnoreCase) >= 0) { return "Microphone"; }
        if (text.IndexOf("headphone", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("speaker", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("output", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("render", StringComparison.OrdinalIgnoreCase) >= 0) { return "Speakers"; }
        return "Audio";
    }

    private sealed class AudioEndpointFormFactorInfo
    {
        public string AudioType;
        public string FormFactorName;
        public uint? FormFactorValue;
        public string Reason;
    }

    private sealed class AudioEndpointFormFactorRegistryRecord
    {
        public uint Value;
        public string Source;
    }

    private static readonly string[] AudioEndpointFormFactorRegistryValueNames = new string[]
    {
        "{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},0",
        "{1DA5D803-D492-4EDD-8C23-E0C0FFEE7F0E},0"
    };

    private static readonly string[] AudioEndpointRegistryFlows = new string[] { "Render", "Capture" };

    private static AudioEndpointFormFactorInfo CreateUnavailableAudioEndpointFormFactorInfo()
    {
        AudioEndpointFormFactorInfo fallback = new AudioEndpointFormFactorInfo();
        fallback.AudioType = "Audio";
        fallback.FormFactorName = "Unavailable";
        fallback.FormFactorValue = null;
        fallback.Reason = "PKEY_AudioEndpoint_FormFactor unavailable; display type defaulted to Audio";
        return fallback;
    }

    private static AudioEndpointFormFactorInfo ResolveAudioEndpointFormFactorInfo(string instanceId)
    {
        if (!String.IsNullOrWhiteSpace(instanceId))
        {
            Dictionary<string, AudioEndpointFormFactorInfo> map = BuildAudioEndpointFormFactorInfoMap(new string[] { instanceId });
            AudioEndpointFormFactorInfo info;
            if (map != null && map.TryGetValue(instanceId, out info) && info != null) { return info; }
        }
        return CreateUnavailableAudioEndpointFormFactorInfo();
    }

    private static Dictionary<string, AudioEndpointFormFactorInfo> BuildAudioEndpointFormFactorInfoMap(IEnumerable<string> instanceIds)
    {
        Dictionary<string, AudioEndpointFormFactorInfo> infoById = new Dictionary<string, AudioEndpointFormFactorInfo>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, AudioEndpointFormFactorRegistryRecord> records = ReadAudioEndpointFormFactorRegistryRecords(instanceIds);
        if (records == null || records.Count == 0) { return infoById; }

        foreach (KeyValuePair<string, AudioEndpointFormFactorRegistryRecord> kv in records)
        {
            if (String.IsNullOrWhiteSpace(kv.Key) || kv.Value == null) { continue; }
            infoById[kv.Key] = CreateAudioEndpointFormFactorInfo(kv.Value.Value, kv.Value.Source);
        }
        return infoById;
    }

    private static Dictionary<string, AudioEndpointFormFactorRegistryRecord> ReadAudioEndpointFormFactorRegistryRecords(IEnumerable<string> instanceIds)
    {
        Dictionary<string, AudioEndpointFormFactorRegistryRecord> records = new Dictionary<string, AudioEndpointFormFactorRegistryRecord>(StringComparer.OrdinalIgnoreCase);
        if (instanceIds == null) { return records; }

        Dictionary<string, List<string>> endpointIdsByGuid = new Dictionary<string, List<string>>(StringComparer.OrdinalIgnoreCase);
        HashSet<string> seenIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (string rawId in instanceIds)
        {
            string id = rawId;
            if (String.IsNullOrWhiteSpace(id)) { continue; }
            id = id.Trim();
            if (!seenIds.Add(id)) { continue; }

            string guid = GetAudioEndpointGuidFromInstanceId(id);
            if (String.IsNullOrWhiteSpace(guid)) { continue; }

            List<string> idsForGuid;
            if (!endpointIdsByGuid.TryGetValue(guid, out idsForGuid))
            {
                idsForGuid = new List<string>();
                endpointIdsByGuid[guid] = idsForGuid;
            }
            idsForGuid.Add(id);
        }

        if (endpointIdsByGuid.Count == 0) { return records; }

        List<Microsoft.Win32.RegistryView> views = new List<Microsoft.Win32.RegistryView>();
        try
        {
            if (Environment.Is64BitOperatingSystem) { views.Add(Microsoft.Win32.RegistryView.Registry64); }
            else { views.Add(Microsoft.Win32.RegistryView.Default); }
        }
        catch { views.Add(Microsoft.Win32.RegistryView.Default); }

        if (views.Count == 0) { views.Add(Microsoft.Win32.RegistryView.Default); }
        if (views[views.Count - 1] != Microsoft.Win32.RegistryView.Default) { views.Add(Microsoft.Win32.RegistryView.Default); }

        int resolvableEndpointCount = 0;
        foreach (KeyValuePair<string, List<string>> guidEntry in endpointIdsByGuid)
        {
            if (guidEntry.Value != null) { resolvableEndpointCount += guidEntry.Value.Count; }
        }
        for (int viewIndex = 0; viewIndex < views.Count; viewIndex++)
        {
            if (records.Count >= resolvableEndpointCount) { break; }
            Microsoft.Win32.RegistryKey hklm = null;
            try
            {
                hklm = Microsoft.Win32.RegistryKey.OpenBaseKey(Microsoft.Win32.RegistryHive.LocalMachine, views[viewIndex]);
                for (int flowIndex = 0; flowIndex < AudioEndpointRegistryFlows.Length; flowIndex++)
                {
                    if (records.Count >= resolvableEndpointCount) { break; }
                    string flow = AudioEndpointRegistryFlows[flowIndex];
                    foreach (KeyValuePair<string, List<string>> guidEntry in endpointIdsByGuid)
                    {
                        if (AllEndpointIdsResolved(guidEntry.Value, records)) { continue; }

                        string subPath = @"SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\" + flow + @"\" + guidEntry.Key + @"\Properties";
                        Microsoft.Win32.RegistryKey key = null;
                        try
                        {
                            key = hklm.OpenSubKey(subPath, false);
                            if (key == null) { continue; }

                            for (int valueNameIndex = 0; valueNameIndex < AudioEndpointFormFactorRegistryValueNames.Length; valueNameIndex++)
                            {
                                string valueName = AudioEndpointFormFactorRegistryValueNames[valueNameIndex];
                                object raw = key.GetValue(valueName, null);
                                uint parsed;
                                if (!TryConvertAudioEndpointFormFactorValue(raw, out parsed)) { continue; }

                                string source = @"HKEY_LOCAL_MACHINE\" + subPath + @"\" + valueName;
                                for (int idIndex = 0; idIndex < guidEntry.Value.Count; idIndex++)
                                {
                                    string endpointId = guidEntry.Value[idIndex];
                                    if (String.IsNullOrWhiteSpace(endpointId) || records.ContainsKey(endpointId)) { continue; }
                                    AudioEndpointFormFactorRegistryRecord record = new AudioEndpointFormFactorRegistryRecord();
                                    record.Value = parsed;
                                    record.Source = source;
                                    records[endpointId] = record;
                                }
                                break;
                            }
                        }
                        catch { }
                        finally { if (key != null) { try { key.Close(); } catch { } } }
                    }
                }
            }
            catch { }
            finally { if (hklm != null) { try { hklm.Close(); } catch { } } }
        }

        return records;
    }

    private static bool AllEndpointIdsResolved(List<string> endpointIds, Dictionary<string, AudioEndpointFormFactorRegistryRecord> records)
    {
        if (endpointIds == null || endpointIds.Count == 0) { return true; }
        if (records == null || records.Count == 0) { return false; }
        for (int i = 0; i < endpointIds.Count; i++)
        {
            string id = endpointIds[i];
            if (!String.IsNullOrWhiteSpace(id) && !records.ContainsKey(id)) { return false; }
        }
        return true;
    }

    private static AudioEndpointFormFactorInfo CreateAudioEndpointFormFactorInfo(uint value, string source)
    {
        AudioEndpointFormFactorInfo info = new AudioEndpointFormFactorInfo();
        string name = "UnknownFormFactor";
        string audioType = "Audio";
        switch (value)
        {
            case 0: name = "RemoteNetworkDevice"; audioType = "Remote Network Audio"; break;
            case 1: name = "Speakers"; audioType = "Speakers"; break;
            case 2: name = "LineLevel"; audioType = "Line Level"; break;
            case 3: name = "Headphones"; audioType = "Headphones"; break;
            case 4: name = "Microphone"; audioType = "Microphone"; break;
            case 5: name = "Headset"; audioType = "Headset"; break;
            case 6: name = "Handset"; audioType = "Handset"; break;
            case 7: name = "UnknownDigitalPassthrough"; audioType = "Digital Passthrough"; break;
            case 8: name = "SPDIF"; audioType = "SPDIF"; break;
            case 9: name = "DigitalAudioDisplayDevice"; audioType = "Display Audio"; break;
            case 10: name = "UnknownFormFactor"; audioType = "Audio"; break;
            case 11: name = "EndpointFormFactor_enum_count"; audioType = "Audio"; break;
            default: name = "UnknownFormFactorValue_" + value.ToString(System.Globalization.CultureInfo.InvariantCulture); audioType = "Audio"; break;
        }
        info.AudioType = audioType;
        info.FormFactorName = name;
        info.FormFactorValue = value;
        info.Reason = "PKEY_AudioEndpoint_FormFactor=" + name + " (" + value.ToString(System.Globalization.CultureInfo.InvariantCulture) + ") from " + (String.IsNullOrWhiteSpace(source) ? "unavailable endpoint property" : source);
        return info;
    }

    private static bool TryConvertAudioEndpointFormFactorValue(object raw, out uint value)
    {
        value = 0;
        if (raw == null) { return false; }
        try
        {
            byte[] bytes = raw as byte[];
            if (bytes != null)
            {
                if (bytes.Length >= 4) { value = BitConverter.ToUInt32(bytes, 0); return true; }
                if (bytes.Length > 0) { value = Convert.ToUInt32(bytes[0], System.Globalization.CultureInfo.InvariantCulture); return true; }
                return false;
            }
            value = Convert.ToUInt32(raw, System.Globalization.CultureInfo.InvariantCulture);
            return true;
        }
        catch { }
        try
        {
            string text = Convert.ToString(raw, System.Globalization.CultureInfo.InvariantCulture);
            if (String.IsNullOrWhiteSpace(text)) { return false; }
            switch (text.Trim())
            {
                case "RemoteNetworkDevice": value = 0; return true;
                case "Speakers": value = 1; return true;
                case "LineLevel": value = 2; return true;
                case "Headphones": value = 3; return true;
                case "Microphone": value = 4; return true;
                case "Headset": value = 5; return true;
                case "Handset": value = 6; return true;
                case "UnknownDigitalPassthrough": value = 7; return true;
                case "SPDIF": value = 8; return true;
                case "HDMI": value = 9; return true;
                case "DigitalAudioDisplayDevice": value = 9; return true;
                case "UnknownFormFactor": value = 10; return true;
                case "EndpointFormFactor_enum_count": value = 11; return true;
            }
        }
        catch { }
        return false;
    }

    private static string GetAudioEndpointGuidFromInstanceId(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        int open = instanceId.LastIndexOf('{');
        if (open < 0) { return String.Empty; }
        int close = instanceId.IndexOf('}', open);
        if (close <= open) { return String.Empty; }
        return instanceId.Substring(open, close - open + 1);
    }

    private static List<UsbHidDeviceInfo> BuildStartupHidRows(DeviceDiscoveryModel model)
    {
        List<UsbHidDeviceInfo> rows = new List<UsbHidDeviceInfo>();
        if (model == null || model.HidInterfaces == null) { return rows; }
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (KeyValuePair<string, HidInterfaceInfo> kv in model.HidInterfaces)
        {
            HidInterfaceInfo hid = kv.Value;
            if (hid == null) { continue; }
            string instanceId = FirstNonEmpty(hid.Instance, kv.Key, hid.DevicePath);
            if (String.IsNullOrWhiteSpace(instanceId) || !seen.Add(instanceId)) { continue; }
            string role = ClassifyHidRoleFromInstanceAndProduct(instanceId, hid.Product);
            if (String.IsNullOrWhiteSpace(role)) { continue; }
            UsbHidDeviceInfo row = new UsbHidDeviceInfo();
            row.ProductString = FirstNonEmpty(hid.Product, ResolveDeviceName(model, instanceId), instanceId);
            row.DeviceInstanceID = instanceId;
            row.DeviceType = role;
            row.ClassificationReason = "Native startup HID interface classification";
            string controllerId = FindControllerForDevice(model, instanceId);
            if (!String.IsNullOrWhiteSpace(controllerId)) { row.USBControllerPNPIDs.Add(controllerId); }
            rows.Add(row);
        }
        return rows;
    }

    private static string ResolveDeviceName(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        DeviceNode node = null;
        if (model.DevicesByInstanceId != null && model.DevicesByInstanceId.TryGetValue(instanceId, out node) && node != null) { return FirstNonEmpty(node.FriendlyName, node.DeviceDesc, node.InstanceId); }
        return String.Empty;
    }

    private static string FindControllerForDevice(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        if (model.UsbControllerAssociationList != null)
        {
            string current = instanceId;
            HashSet<string> chain = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int depth = 0; depth < 16 && !String.IsNullOrWhiteSpace(current) && chain.Add(current); depth++)
            {
                string currentVidPid = ExtractVidPidPair(current);
                string currentBase = Regex.Replace(current ?? String.Empty, "&(MI|COL)_[0-9A-Fa-f]+", String.Empty, RegexOptions.IgnoreCase).TrimEnd('&');
                for (int i = 0; i < model.UsbControllerAssociationList.Count; i++)
                {
                    UsbControllerAssociationRecord assoc = model.UsbControllerAssociationList[i];
                    if (assoc == null) { continue; }
                    if (String.Equals(assoc.DevId, current, StringComparison.OrdinalIgnoreCase) || String.Equals(assoc.CtrlId, current, StringComparison.OrdinalIgnoreCase)) { return ToPnpId(assoc.CtrlId); }
                    if (!String.IsNullOrWhiteSpace(currentBase) && String.Equals(assoc.DevId, currentBase, StringComparison.OrdinalIgnoreCase)) { return ToPnpId(assoc.CtrlId); }
                    if (!String.IsNullOrWhiteSpace(currentVidPid) && String.Equals(ExtractVidPidPair(assoc.DevId), currentVidPid, StringComparison.OrdinalIgnoreCase)) { return ToPnpId(assoc.CtrlId); }
                }
                string parent = String.Empty;
                if (model.ParentByInstanceId != null) { model.ParentByInstanceId.TryGetValue(current, out parent); }
                if (String.IsNullOrWhiteSpace(parent)) { parent = GetParentFromDeviceNode(model, current); }
                if (String.IsNullOrWhiteSpace(parent) || String.Equals(parent, current, StringComparison.OrdinalIgnoreCase)) { break; }
                current = parent;
            }
        }
        return String.Empty;
    }

    private static string FindPciParentForDevice(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        string current = instanceId;
        HashSet<string> chain = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (int depth = 0; depth < 16 && !String.IsNullOrWhiteSpace(current) && chain.Add(current); depth++)
        {
            if (StartsWithPnp(current, "PCI\\")) { return ToPnpId(current); }
            string parent = String.Empty;
            if (model.ParentByInstanceId != null) { model.ParentByInstanceId.TryGetValue(current, out parent); }
            if (String.IsNullOrWhiteSpace(parent)) { parent = GetParentFromDeviceNode(model, current); }
            if (String.IsNullOrWhiteSpace(parent) || String.Equals(parent, current, StringComparison.OrdinalIgnoreCase)) { break; }
            current = parent;
        }
        return String.Empty;
    }

    private static string GetParentFromDeviceNode(DeviceDiscoveryModel model, string instanceId)
    {
        DeviceNode node = null;
        if (model != null && model.DevicesByInstanceId != null && model.DevicesByInstanceId.TryGetValue(instanceId, out node) && node != null) { return FirstNonEmpty(node.ParentInstanceId, node.NormalizedParentInstanceId); }
        return String.Empty;
    }

    private static bool StartsWithPnp(string text, string prefix)
    {
        return !String.IsNullOrWhiteSpace(text) && text.TrimStart('\\').StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsUsbControllerId(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return false; }
        if (model.UsbControllers != null && model.UsbControllers.ContainsKey(instanceId)) { return true; }
        DeviceNode node = null;
        if (model.DevicesByInstanceId != null && model.DevicesByInstanceId.TryGetValue(instanceId, out node) && node != null)
        {
            string text = FirstNonEmpty(node.ClassName, node.Service, node.FriendlyName, node.DeviceDesc, node.InstanceId);
            if (text.IndexOf("USB", StringComparison.OrdinalIgnoreCase) >= 0 && text.IndexOf("Controller", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        }
        return false;
    }

    private static List<DeviceTweakerStorageDeviceRow> BuildStartupStorageRows(DeviceDiscoveryModel model, List<string> logs)
    {
        List<DeviceTweakerStorageDeviceRow> rows = new List<DeviceTweakerStorageDeviceRow>();
        HashSet<string> startupUnspecifiedPhysicalDiskDeviceIds;
        Dictionary<string, StartupPhysicalDiskInfo> physicalByDeviceId = QueryStartupPhysicalDisks(out startupUnspecifiedPhysicalDiskDeviceIds);
        int diskCount = 0;
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("SELECT Index, Model, PNPDeviceID, InterfaceType, MediaType FROM Win32_DiskDrive"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        diskCount++;
                        string index = StartupManagementText(mo, "Index");
                        string pnp = StartupManagementText(mo, "PNPDeviceID");
                        if (String.IsNullOrWhiteSpace(pnp)) { continue; }
                        string modelName = FirstNonEmpty(StartupManagementText(mo, "Model"), pnp);
                        StartupPhysicalDiskInfo phys = null;
                        bool ignoredByPhysicalDiskMediaType = !String.IsNullOrWhiteSpace(index) && startupUnspecifiedPhysicalDiskDeviceIds != null && startupUnspecifiedPhysicalDiskDeviceIds.Contains(index);
                        if (ignoredByPhysicalDiskMediaType)
                        {
                            if (logs != null) { logs.Add("Optimized-GetStorageDevices: Ignored disk PNP='" + SafeText(pnp) + "' Win32Model='" + SafeText(modelName) + "' PhysicalDisk DeviceId='" + SafeText(index) + "' because Get-PhysicalDisk.MediaType returned Unspecified"); }
                            continue;
                        }
                        if (!String.IsNullOrWhiteSpace(index)) { physicalByDeviceId.TryGetValue(index, out phys); }
                        string mediaType = phys == null ? StartupManagementText(mo, "MediaType") : phys.MediaType;
                        string busType = phys == null ? StartupManagementText(mo, "InterfaceType") : phys.BusType;
                        string category = StartupNormalizeStorageMediaType(mediaType, modelName);
                        string busDisplay = StartupNormalizeStorageBusType(busType, StartupManagementText(mo, "InterfaceType"));
                        string controllerPath = FindStartupStorageControllerPath(model, pnp);
                        string controllerPnp = ToPnpId(controllerPath);
                        if (String.IsNullOrWhiteSpace(controllerPnp)) { controllerPnp = pnp; }
                        string controllerDesc = FindStartupStorageControllerDescription(model, controllerPath, FirstNonEmpty(phys == null ? String.Empty : phys.FriendlyName, modelName));
                        DeviceTweakerStorageDeviceRow row = new DeviceTweakerStorageDeviceRow();
                        row.Category = "PCI";
                        row.Role = "Storage";
                        row.StorageType = category;
                        row.DisplayName = StartupStorageDisplayName(category, busDisplay, modelName);
                        row.RegistryPath = !String.IsNullOrWhiteSpace(controllerPath) ? controllerPath : InstanceIdToHklmEnumPath(pnp);
                        row.Description = controllerDesc;
                        row.BusType = busDisplay;
                        row.PNPID = controllerPnp;
                        row.DiskPNPID = pnp;
                        int diskIndex;
                        row.DiskIndex = Int32.TryParse(index, NumberStyles.Integer, CultureInfo.InvariantCulture, out diskIndex) ? diskIndex : -1;
                        row.PhysicalDrivePath = row.DiskIndex >= 0 ? "\\\\.\\PhysicalDrive" + row.DiskIndex.ToString(CultureInfo.InvariantCulture) : String.Empty;
                        rows.Add(row);
                        if (logs != null) { logs.Add("Optimized-GetStorageDevices: Matched disk ControllerPNP='" + SafeText(row.PNPID) + "' DiskPNP='" + SafeText(row.DiskPNPID) + "' Win32Model='" + SafeText(modelName) + "' MediaType='" + SafeText(mediaType) + "' BusType='" + SafeText(busType) + "' -> DisplayName='" + SafeText(row.DisplayName) + "' ControllerPath='" + SafeText(row.RegistryPath) + "'"); }
                    }
                }
            }
        }
        catch { }
        if (logs != null) { logs.Insert(0, "Optimized-GetStorageDevices: Win32_DiskDrive returned " + diskCount.ToString() + " disk(s) for native startup correlation"); logs.Add("Optimized-GetStorageDevices: Summary -> StorageDevicesMatched=" + rows.Count.ToString() + " CorrelatedDisks=" + rows.Count.ToString()); }
        return rows;
    }

    private sealed class StartupPhysicalDiskInfo
    {
        public string DeviceId;
        public string FriendlyName;
        public string MediaType;
        public string BusType;
    }

    private static Dictionary<string, StartupPhysicalDiskInfo> QueryStartupPhysicalDisks(out HashSet<string> ignoredUnspecifiedDeviceIds)
    {
        ignoredUnspecifiedDeviceIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, StartupPhysicalDiskInfo> result = new Dictionary<string, StartupPhysicalDiskInfo>(StringComparer.OrdinalIgnoreCase);
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("root\\Microsoft\\Windows\\Storage", "SELECT DeviceId, FriendlyName, MediaType, BusType FROM MSFT_PhysicalDisk"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        StartupPhysicalDiskInfo info = new StartupPhysicalDiskInfo();
                        info.DeviceId = StartupManagementText(mo, "DeviceId");
                        info.FriendlyName = StartupManagementText(mo, "FriendlyName");
                        info.MediaType = StartupNormalizePhysicalDiskMedia(StartupManagementText(mo, "MediaType"));
                        info.BusType = StartupNormalizePhysicalDiskBus(StartupManagementText(mo, "BusType"));
                        if (!String.IsNullOrWhiteSpace(info.DeviceId))
                        {
                            if (StartupIsPhysicalDiskMediaTypeUnspecified(info.MediaType)) { ignoredUnspecifiedDeviceIds.Add(info.DeviceId); }
                            else { result[info.DeviceId] = info; }
                        }
                    }
                }
            }
        }
        catch { }
        return result;
    }

    private static string FindStartupStorageControllerPath(DeviceDiscoveryModel model, string diskPnpId)
    {
        string pci = FindPciParentInstanceForDevice(model, diskPnpId);
        if (!String.IsNullOrWhiteSpace(pci)) { return InstanceIdToHklmEnumPath(pci); }
        return InstanceIdToHklmEnumPath(diskPnpId);
    }

    private static string FindPciParentInstanceForDevice(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        string current = StartupInstanceIdFromRegistryPath(instanceId);
        HashSet<string> chain = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        for (int depth = 0; depth < 16 && !String.IsNullOrWhiteSpace(current) && chain.Add(current); depth++)
        {
            current = StartupInstanceIdFromRegistryPath(current);
            if (StartsWithPnp(current, "PCI\\")) { return current; }
            string parent = String.Empty;
            if (model.ParentByInstanceId != null) { model.ParentByInstanceId.TryGetValue(current, out parent); }
            if (String.IsNullOrWhiteSpace(parent)) { parent = GetParentFromDeviceNode(model, current); }
            parent = StartupInstanceIdFromRegistryPath(parent);
            if (String.IsNullOrWhiteSpace(parent) || String.Equals(parent, current, StringComparison.OrdinalIgnoreCase)) { break; }
            current = parent;
        }
        return String.Empty;
    }

    private static string FindStartupStorageControllerDescription(DeviceDiscoveryModel model, string controllerPath, string fallback)
    {
        string instance = StartupInstanceIdFromRegistryPath(controllerPath);
        DeviceNode node = null;
        if (model != null && model.DevicesByInstanceId != null && model.DevicesByInstanceId.TryGetValue(instance, out node) && node != null) { return FirstNonEmpty(node.FriendlyName, node.DeviceDesc, fallback); }
        string desc = StartupReadHklmString(controllerPath, "DeviceDesc");
        return FirstNonEmpty(desc, fallback);
    }

    private static string StartupStorageDisplayName(string category, string busDisplay, string model)
    {
        string categoryText = String.IsNullOrWhiteSpace(category) ? "Storage" : category.Trim();
        string busText = String.IsNullOrWhiteSpace(busDisplay) ? String.Empty : busDisplay.Trim();
        string prefix = String.IsNullOrWhiteSpace(busText) ? categoryText : categoryText + " [" + busText + "]";
        string modelText = FormatModelName(model);
        if (String.IsNullOrWhiteSpace(modelText)) { return prefix; }
        if (prefix.IndexOf(modelText, StringComparison.OrdinalIgnoreCase) >= 0) { return prefix; }
        return prefix + " - " + modelText;
    }

    private static string StartupNormalizeStorageMediaType(string mediaType, string model)
    {
        string m = StartupNormalizePhysicalDiskMedia(mediaType);
        if (!String.IsNullOrWhiteSpace(m) && !StartupIsPhysicalDiskMediaTypeUnspecified(m)) { return m; }
        string text = model ?? String.Empty;
        if (text.IndexOf("SSD", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("NVMe", StringComparison.OrdinalIgnoreCase) >= 0) { return "SSD"; }
        return "Storage";
    }

    private static bool StartupIsPhysicalDiskMediaTypeUnspecified(string mediaType)
    {
        if (String.IsNullOrWhiteSpace(mediaType)) { return false; }
        string t = mediaType.Trim();
        return String.Equals(t, "0", StringComparison.OrdinalIgnoreCase) || String.Equals(t, "Unspecified", StringComparison.OrdinalIgnoreCase);
    }

    private static string StartupNormalizePhysicalDiskMedia(string mediaType)
    {
        if (String.IsNullOrWhiteSpace(mediaType)) { return String.Empty; }
        string t = mediaType.Trim();
        if (t == "0") { return "Unspecified"; }
        if (t == "3") { return "HDD"; }
        if (t == "4") { return "SSD"; }
        if (t == "5") { return "SCM"; }
        if (t.IndexOf("SSD", StringComparison.OrdinalIgnoreCase) >= 0) { return "SSD"; }
        if (t.IndexOf("HDD", StringComparison.OrdinalIgnoreCase) >= 0 || t.IndexOf("Hard", StringComparison.OrdinalIgnoreCase) >= 0) { return "HDD"; }
        return t;
    }

    private static string StartupNormalizeStorageBusType(string busType, string interfaceType)
    {
        string b = StartupNormalizePhysicalDiskBus(busType);
        if (!String.IsNullOrWhiteSpace(b)) { return b; }
        return interfaceType == null ? String.Empty : interfaceType.Trim();
    }

    private static string StartupNormalizePhysicalDiskBus(string busType)
    {
        if (String.IsNullOrWhiteSpace(busType)) { return String.Empty; }
        string t = busType.Trim();
        if (t == "7") { return "USB"; }
        if (t == "10") { return "SAS"; }
        if (t == "11") { return "SATA"; }
        if (t == "17") { return "NVMe"; }
        if (t.IndexOf("NVMe", StringComparison.OrdinalIgnoreCase) >= 0) { return "NVMe"; }
        if (t.IndexOf("SATA", StringComparison.OrdinalIgnoreCase) >= 0) { return "SATA"; }
        if (t.IndexOf("SAS", StringComparison.OrdinalIgnoreCase) >= 0) { return "SAS"; }
        if (t.IndexOf("USB", StringComparison.OrdinalIgnoreCase) >= 0) { return "USB"; }
        return t;
    }

    private sealed class StartupNetworkPhysicalAdapter
    {
        public string InterfaceDescription = String.Empty;
        public string Name = String.Empty;
        public string PnpDeviceId = String.Empty;
        public string Status = String.Empty;
        public string NdisPhysicalMedium = String.Empty;
        public string NdisMedium = String.Empty;
        public string NdisMediaSource = String.Empty;
        public string Kind = String.Empty;
    }

    private static bool TryParseStartupUInt32(string value, out uint result)
    {
        result = 0;
        if (String.IsNullOrWhiteSpace(value)) { return false; }
        string s = value.Trim();
        if (String.Equals(s, "<none>", StringComparison.OrdinalIgnoreCase) || String.Equals(s, "none", StringComparison.OrdinalIgnoreCase) || String.Equals(s, "<empty>", StringComparison.OrdinalIgnoreCase) || String.Equals(s, "unknown", StringComparison.OrdinalIgnoreCase)) { return false; }
        if (s.IndexOf('/') >= 0) { s = s.Split('/')[0].Trim(); }
        return UInt32.TryParse(s, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out result);
    }

    private static string StartupNormalizeNetworkNdisValue(string value)
    {
        if (String.IsNullOrWhiteSpace(value)) { return String.Empty; }
        string s = value.Trim();
        if (String.Equals(s, "<none>", StringComparison.OrdinalIgnoreCase) ||
            String.Equals(s, "none", StringComparison.OrdinalIgnoreCase) ||
            String.Equals(s, "<empty>", StringComparison.OrdinalIgnoreCase) ||
            String.Equals(s, "unknown", StringComparison.OrdinalIgnoreCase) ||
            String.Equals(s, "OtherOrUnknown", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
        uint n;
        if (TryParseStartupUInt32(s, out n)) { return n.ToString(System.Globalization.CultureInfo.InvariantCulture); }
        if (s.IndexOf("NdisMediumNative802_11", StringComparison.OrdinalIgnoreCase) >= 0) { return "16"; }
        if (s.IndexOf("NdisPhysicalMediumNative802_11", StringComparison.OrdinalIgnoreCase) >= 0) { return "9"; }
        if (s.IndexOf("Native802_11", StringComparison.OrdinalIgnoreCase) >= 0) { return "9"; }
        if (s.IndexOf("WirelessLan", StringComparison.OrdinalIgnoreCase) >= 0) { return "1"; }
        if (s.IndexOf("Bluetooth", StringComparison.OrdinalIgnoreCase) >= 0) { return "10"; }
        if (s.IndexOf("WirelessWan", StringComparison.OrdinalIgnoreCase) >= 0) { return "8"; }
        if (s.IndexOf("WiMax", StringComparison.OrdinalIgnoreCase) >= 0) { return "12"; }
        return s;
    }

    private static bool StartupKindIsWeak(string kind)
    {
        return String.IsNullOrWhiteSpace(kind) ||
               String.Equals(kind, "OtherOrUnknown", StringComparison.OrdinalIgnoreCase) ||
               String.Equals(kind, "EthernetOrUnknown", StringComparison.OrdinalIgnoreCase);
    }

    private static string StartupClassifyNetworkAdapterKindFromMedia(string ndisPhysicalMediumText, string ndisMediumText, string adapterTypeIdText)
    {
        string baseKind = StartupClassifyNetworkAdapterKind(StartupNormalizeNetworkNdisValue(ndisPhysicalMediumText), StartupNormalizeNetworkNdisValue(ndisMediumText));
        if (!StartupKindIsWeak(baseKind)) { return baseKind; }

        uint adapterTypeId;
        if (TryParseStartupUInt32(adapterTypeIdText, out adapterTypeId))
        {
            if (adapterTypeId == 9) { return "WiFi"; }
            if (adapterTypeId == 0) { return "WiredEthernet"; }
            if (adapterTypeId == 3) { return "WirelessWAN"; }
            if (adapterTypeId == 10) { return "Bluetooth"; }
        }

        if (String.Equals(baseKind, "EthernetOrUnknown", StringComparison.OrdinalIgnoreCase)) { return "WiredEthernet"; }
        return "OtherOrUnknown";
    }

    private static void StartupApplyNetworkMediaFallback(StartupNetworkPhysicalAdapter snap, string adapterTypeIdText)
    {
        if (snap == null) { return; }
        snap.NdisPhysicalMedium = StartupNormalizeNetworkNdisValue(snap.NdisPhysicalMedium);
        snap.NdisMedium = StartupNormalizeNetworkNdisValue(snap.NdisMedium);

        string source = String.Empty;
        uint adapterTypeId;
        bool fromAdapterType = TryParseStartupUInt32(adapterTypeIdText, out adapterTypeId);

        if (String.IsNullOrWhiteSpace(snap.NdisPhysicalMedium) || String.IsNullOrWhiteSpace(snap.NdisMedium))
        {
            if (fromAdapterType && adapterTypeId == 9)
            {
                if (String.IsNullOrWhiteSpace(snap.NdisPhysicalMedium)) { snap.NdisPhysicalMedium = "9"; }
                if (String.IsNullOrWhiteSpace(snap.NdisMedium)) { snap.NdisMedium = "16"; }
                source = "Derived:Win32_NetworkAdapter.AdapterTypeID=9";
            }
            else if (fromAdapterType && adapterTypeId == 0)
            {
                if (String.IsNullOrWhiteSpace(snap.NdisPhysicalMedium)) { snap.NdisPhysicalMedium = "14"; }
                if (String.IsNullOrWhiteSpace(snap.NdisMedium)) { snap.NdisMedium = "0"; }
                source = "Derived:Win32_NetworkAdapter.AdapterTypeID=0";
            }
        }

        snap.Kind = StartupClassifyNetworkAdapterKindFromMedia(snap.NdisPhysicalMedium, snap.NdisMedium, adapterTypeIdText);
        if (!String.IsNullOrWhiteSpace(source)) { snap.NdisMediaSource = source; }
        else if (String.IsNullOrWhiteSpace(snap.NdisMediaSource) && (!String.IsNullOrWhiteSpace(snap.NdisPhysicalMedium) || !String.IsNullOrWhiteSpace(snap.NdisMedium))) { snap.NdisMediaSource = "MSFT_NetAdapter"; }
    }

    private static string StartupClassifyNetworkAdapterKind(string ndisPhysicalMediumText, string ndisMediumText)
    {
        uint ndisPhysicalMedium;
        if (TryParseStartupUInt32(ndisPhysicalMediumText, out ndisPhysicalMedium))
        {
            switch (ndisPhysicalMedium)
            {
                case 1: return "WiFi";
                case 9: return "WiFi";
                case 14: return "WiredEthernet";
                case 10: return "Bluetooth";
                case 8: return "WirelessWAN";
                case 12: return "WiMAX";
            }
        }

        uint ndisMedium;
        if (TryParseStartupUInt32(ndisMediumText, out ndisMedium))
        {
            if (ndisMedium == 16) { return "WiFi"; }
            if (ndisMedium == 0) { return "EthernetOrUnknown"; }
        }

        return "OtherOrUnknown";
    }

    private static string StartupNetworkAdapterDisplayBase(string driverType, string adapterKind)
    {
        string driver = String.Equals(driverType, "NetAdapterCx", StringComparison.OrdinalIgnoreCase) ? "NetAdapterCx" : "NDIS";
        string kind = String.IsNullOrWhiteSpace(adapterKind) ? "OtherOrUnknown" : adapterKind.Trim();
        return "Network Interface Card (" + driver + " " + kind + ")";
    }

    private static List<DeviceTweakerNetworkAdapterRow> BuildStartupNetworkRows(string pciIdsPath, List<string> logs)
    {
        List<DeviceTweakerNetworkAdapterRow> rows = new List<DeviceTweakerNetworkAdapterRow>();
        if (logs != null) { try { logs.Add("Get-NetworkAdapters: pci.ids path='" + SafeText(pciIdsPath) + "' Exists=" + System.IO.File.Exists(pciIdsPath).ToString()); } catch { } }
        List<StartupNetworkPhysicalAdapter> physicalAdapters = QueryStartupPhysicalNetworkAdapters(logs);
        Dictionary<string, StartupNetworkPhysicalAdapter> physicalByName = new Dictionary<string, StartupNetworkPhysicalAdapter>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, StartupNetworkPhysicalAdapter> physicalByPnp = new Dictionary<string, StartupNetworkPhysicalAdapter>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < physicalAdapters.Count; i++)
        {
            StartupNetworkPhysicalAdapter pa = physicalAdapters[i];
            if (pa == null) { continue; }
            if (!String.IsNullOrWhiteSpace(pa.InterfaceDescription) && !physicalByName.ContainsKey(pa.InterfaceDescription)) { physicalByName[pa.InterfaceDescription] = pa; }
            if (!String.IsNullOrWhiteSpace(pa.Name) && !physicalByName.ContainsKey(pa.Name)) { physicalByName[pa.Name] = pa; }
            if (!String.IsNullOrWhiteSpace(pa.PnpDeviceId) && !physicalByPnp.ContainsKey(pa.PnpDeviceId)) { physicalByPnp[pa.PnpDeviceId] = pa; }
        }
        int total = 0;
        int skipped = 0;
        if (physicalAdapters.Count == 0)
        {
            if (logs != null) { logs.Add("Get-NetworkAdapters: No physical adapters found via native startup network probes. Returning empty."); }
            return rows;
        }

        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("SELECT Name, PNPDeviceID, AdapterTypeID FROM Win32_NetworkAdapter"))
            {
                searcher.Options.ReturnImmediately = true;
                searcher.Options.Rewindable = false;
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        total++;
                        string name = StartupManagementText(mo, "Name");
                        string pnp = StartupManagementText(mo, "PNPDeviceID");
                        string adapterTypeId = StartupManagementText(mo, "AdapterTypeID");
                        if (String.IsNullOrWhiteSpace(pnp)) { skipped++; if (logs != null) { logs.Add("Get-NetworkAdapters: Adapter IGNORED: Name='" + SafeText(name) + "' | Reason: No PNPDeviceID available (virtual or incomplete device)"); } continue; }
                        StartupNetworkPhysicalAdapter physicalInfo = null;
                        if (!String.IsNullOrWhiteSpace(pnp)) { physicalByPnp.TryGetValue(pnp, out physicalInfo); }
                        if (physicalInfo == null && !String.IsNullOrWhiteSpace(name)) { physicalByName.TryGetValue(name, out physicalInfo); }
                        if (physicalInfo == null) { skipped++; if (logs != null) { logs.Add("Get-NetworkAdapters: Adapter IGNORED: Name='" + SafeText(name) + "' PNPDeviceID='" + SafeText(pnp) + "' | Reason: Not present in MSFT_NetAdapter Virtual=False (virtual/software adapter)"); } continue; }
                        StartupApplyNetworkMediaFallback(physicalInfo, adapterTypeId);
                        string adapterKind = String.IsNullOrWhiteSpace(physicalInfo.Kind) ? StartupClassifyNetworkAdapterKindFromMedia(physicalInfo.NdisPhysicalMedium, physicalInfo.NdisMedium, adapterTypeId) : physicalInfo.Kind;
                        string regPath = InstanceIdToHklmEnumPath(pnp);
                        string driver = StartupReadHklmString(regPath, "Driver");
                        if (String.IsNullOrWhiteSpace(driver)) { skipped++; if (logs != null) { logs.Add("Get-NetworkAdapters: Adapter IGNORED: Name='" + SafeText(name) + "' PNPDeviceID='" + SafeText(pnp) + "' | Reason: No 'Driver' registry value found at '" + SafeText(regPath) + "'"); } continue; }
                        string service = StartupReadHklmString(@"HKLM:\SYSTEM\CurrentControlSet\Control\Class\" + driver + @"\Ndi", "Service");
                        if (!String.IsNullOrWhiteSpace(service)) { service = service.TrimEnd('.').Trim(); }
                        if (String.IsNullOrWhiteSpace(service)) { skipped++; if (logs != null) { logs.Add("Get-NetworkAdapters: Adapter IGNORED: Name='" + SafeText(name) + "' PNPDeviceID='" + SafeText(pnp) + "' Driver='" + SafeText(driver) + "' | Reason: No Ndi\\Service registry value found"); } continue; }
                        string serviceRegPath = @"HKLM:\SYSTEM\CurrentControlSet\Services\" + service;
                        string imagePath = StartupReadHklmString(serviceRegPath, "ImagePath");
                        string resolvedPath = StartupResolveDriverImagePath(imagePath);
                        string driverType = StartupGetDriverTypeFromBinary(resolvedPath);
                        string classRegPath = @"HKLM:\SYSTEM\CurrentControlSet\Control\Class\" + driver;
                        string resolvedName = ResolvePciDisplayName(pnp, regPath, name, "Network", pciIdsPath);
                        if (String.IsNullOrWhiteSpace(resolvedName)) { resolvedName = name; }
                        StartupApplyNetworkMediaFallback(physicalInfo, adapterTypeId);
                        adapterKind = String.IsNullOrWhiteSpace(physicalInfo.Kind) ? StartupClassifyNetworkAdapterKindFromMedia(physicalInfo.NdisPhysicalMedium, physicalInfo.NdisMedium, adapterTypeId) : physicalInfo.Kind;
                        string displayBase = StartupNetworkAdapterDisplayBase(driverType, adapterKind);
                        DeviceTweakerNetworkAdapterRow row = new DeviceTweakerNetworkAdapterRow();
                        row.Category = "Network";
                        row.Role = driverType;
                        row.NetworkAdapterKind = adapterKind;
                        row.Type = adapterKind;
                        row.NdisPhysicalMedium = physicalInfo.NdisPhysicalMedium;
                        row.NdisMedium = physicalInfo.NdisMedium;
                        row.NdisMediaSource = physicalInfo.NdisMediaSource;
                        row.DisplayName = String.IsNullOrWhiteSpace(resolvedName) ? displayBase : displayBase + " - " + resolvedName;
                        row.RegistryPath = classRegPath;
                        row.Description = resolvedName;
                        row.OriginalDescription = name;
                        row.ConfigPath = regPath;
                        row.PNPID = FirstNonEmpty(BuildPciPnpId(pnp), pnp);
                        rows.Add(row);
                        if (logs != null)
                        {
                            logs.Add("Get-NetworkAdapters: '" + SafeText(name) + "' matched adapter candidate (physical identity is checked before writes)");
                            logs.Add("Get-NetworkAdapters: Detected network adapter:");
                            logs.Add("  Name               : '" + SafeText(name) + "'");
                            logs.Add("  ResolvedName       : '" + SafeText(resolvedName) + "'");
                            logs.Add("  Role               : '" + SafeText(driverType) + "'");
                            logs.Add("  DriverType         : '" + SafeText(driverType) + "'");
                            logs.Add("  Type               : '" + SafeText(adapterKind) + "'");
                            logs.Add("  NdisPhysicalMedium : '" + SafeText(row.NdisPhysicalMedium) + "'");
                            logs.Add("  NdisMedium         : '" + SafeText(row.NdisMedium) + "'");
                            logs.Add("  NdisMediaSource    : '" + SafeText(physicalInfo.NdisMediaSource) + "'");
                            logs.Add("  PNPID              : '" + SafeText(row.PNPID) + "'");
                            logs.Add("  ClassPath          : '" + SafeText(row.RegistryPath) + "'");
                            logs.Add("  ConfigPath         : '" + SafeText(regPath) + "'");
                            logs.Add("  Service            : '" + SafeText(serviceRegPath) + "'");
                            logs.Add("  ImagePath          : '" + SafeText(imagePath) + "'");
                            logs.Add("  ResolvedPath       : '" + SafeText(resolvedPath) + "'");
                        }
                    }
                }
            }
        }
        catch { }
        if (logs != null)
        {
            logs.Add("Get-NetworkAdapters: Summary -> NetworkAdaptersDetected=" + rows.Count.ToString() + " Win32NetworkAdapterTotal=" + total.ToString() + " IgnoredSkipped=" + skipped.ToString());
            for (int i = 0; i < rows.Count; i++) { logs.Add("  Detected Adapter: Name='" + SafeText(rows[i].Description) + "' OriginalName='" + SafeText(rows[i].OriginalDescription) + "' Role='" + SafeText(rows[i].Role) + "' Type='" + SafeText(rows[i].NetworkAdapterKind) + "' NdisPhysicalMedium='" + SafeText(rows[i].NdisPhysicalMedium) + "' NdisMedium='" + SafeText(rows[i].NdisMedium) + "' NdisMediaSource='" + SafeText(rows[i].NdisMediaSource) + "' ClassPath='" + SafeText(rows[i].RegistryPath) + "' ConfigPath='" + SafeText(rows[i].ConfigPath) + "'"); }
        }
        return rows;
    }

    private static List<StartupNetworkPhysicalAdapter> QueryStartupPhysicalNetworkAdapters(List<string> logs)
    {
        List<StartupNetworkPhysicalAdapter> result = new List<StartupNetworkPhysicalAdapter>();
        string source = "MSFT_NetAdapter Virtual=False";
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("root\\StandardCimv2", "SELECT InterfaceDescription, Name, Status, InterfaceOperationalStatus, AdminStatus, NdisPhysicalMedium, NdisMedium, InterfaceIndex, PNPDeviceID FROM MSFT_NetAdapter WHERE Virtual=False"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        StartupNetworkPhysicalAdapter snap = new StartupNetworkPhysicalAdapter();
                        snap.InterfaceDescription = FirstNonEmpty(StartupManagementText(mo, "InterfaceDescription"), StartupManagementText(mo, "Name"));
                        snap.Name = FirstNonEmpty(StartupManagementText(mo, "Name"), snap.InterfaceDescription);
                        snap.PnpDeviceId = StartupManagementText(mo, "PNPDeviceID");
                        snap.Status = FirstNonEmpty(StartupManagementText(mo, "Status"), StartupManagementText(mo, "InterfaceOperationalStatus"), StartupManagementText(mo, "AdminStatus"));
                        snap.NdisPhysicalMedium = StartupManagementText(mo, "NdisPhysicalMedium");
                        snap.NdisMedium = StartupManagementText(mo, "NdisMedium");
                        StartupApplyNetworkMediaFallback(snap, String.Empty);
                        if (!String.IsNullOrWhiteSpace(snap.InterfaceDescription) || !String.IsNullOrWhiteSpace(snap.PnpDeviceId)) { result.Add(snap); }
                    }
                }
            }
        }
        catch { }
        if (result.Count == 0)
        {
            source = "Win32_NetworkAdapter PhysicalAdapter=True fallback";
            try
            {
                using (System.Management.ManagementObjectSearcher fallback = new System.Management.ManagementObjectSearcher("SELECT Name, NetConnectionStatus, PNPDeviceID, PhysicalAdapter, AdapterTypeID FROM Win32_NetworkAdapter WHERE PhysicalAdapter=True"))
                {
                    foreach (System.Management.ManagementObject mo in fallback.Get())
                    {
                        using (mo)
                        {
                            StartupNetworkPhysicalAdapter snap = new StartupNetworkPhysicalAdapter();
                            snap.InterfaceDescription = StartupManagementText(mo, "Name");
                            snap.Name = snap.InterfaceDescription;
                            snap.PnpDeviceId = StartupManagementText(mo, "PNPDeviceID");
                            snap.Status = StartupManagementText(mo, "NetConnectionStatus");
                            StartupApplyNetworkMediaFallback(snap, StartupManagementText(mo, "AdapterTypeID"));
                            if (!String.IsNullOrWhiteSpace(snap.InterfaceDescription) || !String.IsNullOrWhiteSpace(snap.PnpDeviceId)) { result.Add(snap); }
                        }
                    }
                }
            }
            catch { }
        }
        if (logs != null)
        {
            logs.Add("Get-NetworkAdapters: " + source + " returned " + result.Count.ToString() + " adapter(s)");
            for (int i = 0; i < result.Count; i++)
            {
                StartupNetworkPhysicalAdapter pa = result[i];
                logs.Add("  Physical adapter: InterfaceDescription='" + SafeText(pa.InterfaceDescription) + "' Name='" + SafeText(pa.Name) + "' PNPDeviceID='" + SafeText(pa.PnpDeviceId) + "' Status=" + SafeText(pa.Status) + " Type='" + SafeText(pa.Kind) + "' NdisPhysicalMedium='" + SafeText(pa.NdisPhysicalMedium) + "' NdisMedium='" + SafeText(pa.NdisMedium) + "' NdisMediaSource='" + SafeText(pa.NdisMediaSource) + "'");
            }
        }
        return result;
    }

    private static StartupResourceRowsPartial BuildStartupResourceRowsPartial()
    {
        StartupResourceRowsPartial result = new StartupResourceRowsPartial();
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("SELECT Antecedent, Dependent FROM Win32_PnPAllocatedResource"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        string dep = StartupManagementText(mo, "Dependent");
                        string ant = StartupManagementText(mo, "Antecedent");
                        string deviceId = StartupExtractWmiQuotedValue(dep, "DeviceID");
                        if (!String.IsNullOrWhiteSpace(deviceId)) { deviceId = deviceId.Replace("\\\\", "\\"); }
                        if (String.IsNullOrWhiteSpace(deviceId)) { continue; }
                        DeviceTweakerIrqAllocationRow row = new DeviceTweakerIrqAllocationRow();
                        row.DependentDeviceId = deviceId;
                        row.PnpId = FirstNonEmpty(BuildPciPnpId(deviceId), deviceId);
                        if (ant.IndexOf("Win32_IRQResource", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            row.ResourceClass = "Win32_IRQResource";
                            long irq;
                            if (Int64.TryParse(StartupExtractWmiQuotedValue(ant, "IRQNumber"), out irq)) { row.IrqNumber = irq; }
                            result.IrqAllocationRows.Add(row);
                        }
                        else if (ant.IndexOf("Win32_DeviceMemoryAddress", StringComparison.OrdinalIgnoreCase) >= 0)
                        {
                            row.ResourceClass = "Win32_DeviceMemoryAddress";
                            ulong address;
                            if (UInt64.TryParse(StartupExtractWmiQuotedValue(ant, "StartingAddress"), out address))
                            {
                                row.PhysicalAddress = address;
                                if (!result.DeviceAddressByPnpId.ContainsKey(deviceId)) { result.DeviceAddressByPnpId[deviceId] = address; }
                            }
                            result.IrqAllocationRows.Add(row);
                        }
                    }
                }
            }
            result.Complete = true;
        }
        catch { result.Complete = false; }
        return result;
    }

    private static bool BuildStartupResourceRows(DeviceTweakerStartupPayload startup)
    {
        if (startup == null) { return false; }
        StartupResourceRowsPartial result = BuildStartupResourceRowsPartial();
        MergeStartupResourceRows(startup, result);
        return result != null && result.Complete;
    }

    private static string StartupExtractWmiQuotedValue(string text, string key)
    {
        if (String.IsNullOrWhiteSpace(text) || String.IsNullOrWhiteSpace(key)) { return String.Empty; }
        try
        {
            Match m = Regex.Match(text, Regex.Escape(key) + "=\"([^\"]*)\"", RegexOptions.IgnoreCase);
            if (m.Success) { return m.Groups[1].Value; }
            m = Regex.Match(text, Regex.Escape(key) + "=([^,]+)", RegexOptions.IgnoreCase);
            if (m.Success) { return m.Groups[1].Value.Trim().Trim('"'); }
        }
        catch { }
        return String.Empty;
    }

    private static string StartupManagementText(System.Management.ManagementBaseObject mo, string propertyName)
    {
        if (mo == null || String.IsNullOrWhiteSpace(propertyName)) { return String.Empty; }
        try
        {
            object value = mo.Properties[propertyName] == null ? null : mo.Properties[propertyName].Value;
            if (value == null) { return String.Empty; }
            Array arr = value as Array;
            if (arr != null)
            {
                List<string> parts = new List<string>();
                foreach (object item in arr) { if (item != null && !String.IsNullOrWhiteSpace(Convert.ToString(item))) { parts.Add(Convert.ToString(item).Trim()); } }
                return parts.Count == 0 ? String.Empty : String.Join("/", parts.ToArray());
            }
            string text = Convert.ToString(value);
            return String.IsNullOrWhiteSpace(text) ? String.Empty : text.Trim();
        }
        catch { return String.Empty; }
    }

    private static string StartupReadHklmString(string displayPath, string valueName)
    {
        if (String.IsNullOrWhiteSpace(displayPath)) { return String.Empty; }
        Microsoft.Win32.RegistryKey rk = null;
        try
        {
            string subKey = StartupHklmSubKey(displayPath);
            if (String.IsNullOrWhiteSpace(subKey)) { return String.Empty; }
            rk = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(subKey, false);
            if (rk == null) { return String.Empty; }
            object value = rk.GetValue(valueName, null);
            return value == null ? String.Empty : Convert.ToString(value);
        }
        catch { return String.Empty; }
        finally { if (rk != null) { try { rk.Close(); } catch { } } }
    }

    private static string StartupHklmSubKey(string displayPath)
    {
        string path = displayPath == null ? String.Empty : displayPath.Trim();
        path = path.Replace('/', '\\');
        string[] prefixes = new string[] { @"Microsoft.PowerShell.Core\Registry::HKEY_LOCAL_MACHINE\", @"Microsoft.PowerShell.Core\Registry::HKLM:\", @"Registry::HKEY_LOCAL_MACHINE\", @"Registry::HKLM:\", @"HKEY_LOCAL_MACHINE\", @"HKLM:\", @"HKLM\" };
        for (int i = 0; i < prefixes.Length; i++)
        {
            if (path.StartsWith(prefixes[i], StringComparison.OrdinalIgnoreCase)) { path = path.Substring(prefixes[i].Length); break; }
        }
        while (path.StartsWith("\\", StringComparison.Ordinal)) { path = path.Substring(1); }
        return path;
    }

    private static string StartupResolveDriverImagePath(string imagePath)
    {
        if (String.IsNullOrWhiteSpace(imagePath)) { return String.Empty; }
        string resolved = imagePath.Trim().Trim('"');
        try
        {
            string systemRoot = Environment.GetEnvironmentVariable("SystemRoot");
            if (String.IsNullOrWhiteSpace(systemRoot)) { systemRoot = @"C:\Windows"; }
            if (resolved.StartsWith(@"\SystemRoot", StringComparison.OrdinalIgnoreCase)) { resolved = systemRoot + resolved.Substring(@"\SystemRoot".Length); }
            else if (resolved.StartsWith("System32", StringComparison.OrdinalIgnoreCase)) { resolved = System.IO.Path.Combine(systemRoot, resolved); }
            else if (resolved.StartsWith(@"\??\", StringComparison.OrdinalIgnoreCase)) { resolved = resolved.Substring(4); }
            resolved = resolved.Replace("%SystemRoot%", systemRoot).Replace("%systemroot%", systemRoot);
        }
        catch { }
        return resolved;
    }

    private static string StartupGetDriverTypeFromBinary(string resolvedPath)
    {
        if (String.IsNullOrWhiteSpace(resolvedPath) || !System.IO.File.Exists(resolvedPath)) { return "NDIS"; }
        try
        {
            using (System.IO.FileStream stream = System.IO.File.Open(resolvedPath, System.IO.FileMode.Open, System.IO.FileAccess.Read, System.IO.FileShare.ReadWrite))
            {
                int bytesToRead = (int)Math.Min(stream.Length, 1048576L);
                byte[] buffer = new byte[bytesToRead];
                int offset = 0;
                while (offset < bytesToRead)
                {
                    int read = stream.Read(buffer, offset, bytesToRead - offset);
                    if (read <= 0) { break; }
                    offset += read;
                }
                string text = Encoding.ASCII.GetString(buffer, 0, offset);
                if (text.IndexOf("NetAdapter", StringComparison.OrdinalIgnoreCase) >= 0) { return "NetAdapterCx"; }
            }
        }
        catch { }
        return "NDIS";
    }

    private static string StartupInstanceIdFromRegistryPath(string path)
    {
        if (String.IsNullOrWhiteSpace(path)) { return String.Empty; }
        string p = path.Replace('/', '\\');
        string marker = @"SYSTEM\CurrentControlSet\Enum\";
        int idx = p.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
        if (idx >= 0) { return p.Substring(idx + marker.Length).Trim('\\'); }
        return p.Trim('\\');
    }

    private static string StartupPnpIdForDisplay(params string[] values)
    {
        if (values == null) { return String.Empty; }
        for (int i = 0; i < values.Length; i++)
        {
            string value = values[i];
            if (String.IsNullOrWhiteSpace(value)) { continue; }
            string formatted = DeviceTweakerPathHelpers.ToPnpId(value);
            if (!String.IsNullOrWhiteSpace(formatted)) { return formatted; }
            return value.Trim();
        }
        return String.Empty;
    }

    private static void HydrateStartupAllDeviceRows(DeviceTweakerStartupPayload startup)
    {
        if (startup == null) { return; }
        AddStartupRows(startup, startup.UsbControllerRows);
        AddStartupRows(startup, startup.PciGpuRows);
        AddStartupRows(startup, startup.PciAudioRows);
        AddStartupRows(startup, startup.StorageRows);
        AddStartupRows(startup, startup.NetworkAdapterRows);
    }

    private static void AddStartupRows(DeviceTweakerStartupPayload startup, System.Collections.IEnumerable rows)
    {
        if (startup == null || rows == null) { return; }
        foreach (object row in rows)
        {
            if (row == null) { continue; }
            startup.AllDeviceRows.Add(row);
            string key = StartupDeviceKey(row);
            string display = FirstNonEmpty(StartupProp(row, "DisplayName"), StartupProp(row, "Description"), key);
            if (!String.IsNullOrWhiteSpace(key)) { startup.DisplayStringsByDeviceKey[key] = display; }
        }
    }

    private static string StartupDeviceKey(object row)
    {
        string path = FirstNonEmpty(StartupProp(row, "RegistryPath"), StartupProp(row, "ConfigPath"), StartupProp(row, "PSPath"));
        if (!String.IsNullOrWhiteSpace(path)) { return path; }
        return FirstNonEmpty(StartupProp(row, "PNPID"), StartupProp(row, "Description"), StartupProp(row, "DisplayName"));
    }

    private static string StartupProp(object row, string name)
    {
        if (row == null || String.IsNullOrWhiteSpace(name)) { return String.Empty; }
        try
        {
            System.Reflection.PropertyInfo prop = row.GetType().GetProperty(name);
            if (prop == null) { return String.Empty; }
            object value = prop.GetValue(row, null);
            return value == null ? String.Empty : Convert.ToString(value);
        }
        catch { return String.Empty; }
    }

    private static void BuildStartupUiReadyState(DeviceTweakerStartupPayload startup)
    {
        if (startup == null || startup.AllDeviceRows == null) { return; }
        foreach (object row in startup.AllDeviceRows)
        {
            string key = StartupDeviceKey(row);
            if (String.IsNullOrWhiteSpace(key) || startup.UiStateByDeviceKey.ContainsKey(key)) { continue; }
            DeviceStartupUiState state = BuildStartupUiStateForRow(startup, row, key);
            startup.UiStateByDeviceKey[key] = state;
        }
    }

    private static DeviceStartupUiState BuildStartupUiStateForRow(DeviceTweakerStartupPayload startup, object row, string key)
    {
        DeviceStartupUiState state = new DeviceStartupUiState();
        state.DeviceKey = key;

        string category = StartupProp(row, "Category");
        string role = StartupProp(row, "Role");
        string registryPath = FirstNonEmpty(StartupProp(row, "RegistryPath"), StartupProp(row, "PSPath"));
        string configPath = StartupProp(row, "ConfigPath");
        bool isNetwork = String.Equals(category, "Network", StringComparison.OrdinalIgnoreCase);
        bool isNDIS = isNetwork && String.Equals(role, "NDIS", StringComparison.OrdinalIgnoreCase);
        bool isNetAdapterCx = isNetwork && String.Equals(role, "NetAdapterCx", StringComparison.OrdinalIgnoreCase);

        string affinityPath = registryPath;
        string msiPath = isNetwork ? FirstNonEmpty(configPath, registryPath) : registryPath;
        string policyPath = isNDIS ? FirstNonEmpty(configPath, registryPath) : (isNetAdapterCx ? affinityPath : registryPath);
        string pnpIdPath = isNDIS ? FirstNonEmpty(configPath, registryPath) : (isNetwork ? msiPath : registryPath);

        state.AffinityPath = affinityPath;
        state.MsiPath = msiPath;
        state.PolicyPath = policyPath;
        if (String.Equals(category, "USB", StringComparison.OrdinalIgnoreCase))
        {
            state.PnpId = StartupPnpIdForDisplay(StartupProp(row, "PNPID"), StartupProp(row, "InstanceId"), StartupInstanceIdFromRegistryPath(pnpIdPath));
        }
        else
        {
            state.PnpId = FirstNonEmpty(StartupProp(row, "PNPID"), StartupProp(row, "InstanceId"), StartupInstanceIdFromRegistryPath(pnpIdPath));
        }
        state.InitialAffinity = "0x0";
        state.NdisIrqAffinity = "0x0";
        state.MsiEnabled = 0;
        state.MessageLimit = String.Empty;
        state.Priority = 2;
        state.Policy = 0;
        state.NumQueues = null;

        Dictionary<string, DeviceRegistryState> registry = startup == null ? null : startup.RegistryStateByPath;
        DeviceRegistryState aff = FindStartupRegistryState(registry, affinityPath);
        DeviceRegistryState msi = FindStartupRegistryState(registry, msiPath);
        DeviceRegistryState pol = FindStartupRegistryState(registry, policyPath);

        bool readPolicy = false;
        bool readPriority = false;
        if (isNDIS)
        {
            if (aff != null)
            {
                if (aff.HasRssBaseProcNumber && aff.RssBaseProcNumber != null)
                {
                    try { state.InitialAffinity = "0x" + Convert.ToInt32(aff.RssBaseProcNumber).ToString("X", CultureInfo.InvariantCulture); } catch { }
                }
                if (aff.HasNumRssQueues && aff.NumRssQueues != null)
                {
                    try { state.NumQueues = Math.Max(1, Convert.ToInt32(aff.NumRssQueues)); } catch { }
                }
            }
            if (pol != null)
            {
                if (pol.HasAssignmentSetOverride)
                {
                    string mask = ConvertStartupRegistryAffinityValueToHex(pol.AssignmentSetOverride);
                    if (!String.IsNullOrWhiteSpace(mask)) { state.NdisIrqAffinity = mask; }
                }
                if (pol.HasDevicePolicy && pol.DevicePolicy != null) { try { state.Policy = Convert.ToInt32(pol.DevicePolicy); } catch { } }
                readPolicy = true;
            }
        }
        else
        {
            if (aff != null)
            {
                if (aff.HasAssignmentSetOverride)
                {
                    string mask = ConvertStartupRegistryAffinityValueToHex(aff.AssignmentSetOverride);
                    if (!String.IsNullOrWhiteSpace(mask)) { state.InitialAffinity = mask; }
                }
                if (String.Equals(policyPath, affinityPath, StringComparison.OrdinalIgnoreCase) && aff.HasDevicePolicy && aff.DevicePolicy != null)
                {
                    try { state.Policy = Convert.ToInt32(aff.DevicePolicy); } catch { }
                    readPolicy = true;
                }
                if (String.Equals(msiPath, affinityPath, StringComparison.OrdinalIgnoreCase) && aff.HasDevicePriority && aff.DevicePriority != null)
                {
                    try { state.Priority = Convert.ToInt32(aff.DevicePriority); } catch { }
                    readPriority = true;
                }
            }
            state.NdisIrqAffinity = state.InitialAffinity;
        }

        if (msi != null)
        {
            if (msi.HasMsiSupported && msi.MsiSupported != null) { try { state.MsiEnabled = Convert.ToInt32(msi.MsiSupported); } catch { } }
            if (msi.HasMessageNumberLimit && msi.MessageNumberLimit != null) { state.MessageLimit = msi.MessageNumberLimit; }
            if (!readPriority && msi.HasDevicePriority && msi.DevicePriority != null)
            {
                try { state.Priority = Convert.ToInt32(msi.DevicePriority); } catch { }
                readPriority = true;
            }
            if (!readPolicy && String.Equals(policyPath, msiPath, StringComparison.OrdinalIgnoreCase) && msi.HasDevicePolicy && msi.DevicePolicy != null)
            {
                try { state.Policy = Convert.ToInt32(msi.DevicePolicy); } catch { }
                readPolicy = true;
            }
        }

        if (!readPolicy && pol != null && pol.HasDevicePolicy && pol.DevicePolicy != null)
        {
            try { state.Policy = Convert.ToInt32(pol.DevicePolicy); } catch { }
        }
        return state;
    }

    private static DeviceRegistryState FindStartupRegistryState(Dictionary<string, DeviceRegistryState> registry, string path)
    {
        if (registry == null || String.IsNullOrWhiteSpace(path)) { return null; }
        DeviceRegistryState state;
        if (registry.TryGetValue(path, out state)) { return state; }
        string normalized = path.Replace('/', '\\').Trim();
        if (registry.TryGetValue(normalized, out state)) { return state; }
        string rel = StartupHklmSubKey(normalized);
        if (!String.IsNullOrWhiteSpace(rel) && registry.TryGetValue(rel, out state)) { return state; }
        return null;
    }

    private static string ConvertStartupRegistryAffinityValueToHex(object value)
    {
        if (value == null) { return null; }
        try
        {
            UInt64 mask = 0UL;
            byte[] bytes = value as byte[];
            if (bytes == null)
            {
                Array arr = value as Array;
                if (arr != null)
                {
                    int max = Math.Min(arr.Length, 8);
                    for (int i = 0; i < max; i++)
                    {
                        object item = arr.GetValue(i);
                        if (item != null) { mask |= ((UInt64)Convert.ToByte(item)) << (8 * i); }
                    }
                    return "0x" + mask.ToString("X", CultureInfo.InvariantCulture);
                }
                string text = Convert.ToString(value).Trim();
                if (String.IsNullOrWhiteSpace(text)) { return null; }
                if (text.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { mask = Convert.ToUInt64(text.Substring(2), 16); }
                else { mask = Convert.ToUInt64(value); }
                return "0x" + mask.ToString("X", CultureInfo.InvariantCulture);
            }
            int maxBytes = Math.Min(bytes.Length, 8);
            for (int i = 0; i < maxBytes; i++) { mask |= ((UInt64)bytes[i]) << (8 * i); }
            return "0x" + mask.ToString("X", CultureInfo.InvariantCulture);
        }
        catch { return null; }
    }

    private static void SeedStartupRegistryState(DeviceTweakerStartupModel startup)
    {
        if (startup == null || startup.DiscoveryModel == null) { return; }
        List<string> paths = new List<string>();
        DeviceDiscoveryModel model = startup.DiscoveryModel;

        if (model.PciDevicesByPath != null)
        {
            foreach (KeyValuePair<string, PciDeviceInfo> kv in model.PciDevicesByPath)
            {
                if (!String.IsNullOrWhiteSpace(kv.Key)) { paths.Add(kv.Key); }
                if (kv.Value != null && !String.IsNullOrWhiteSpace(kv.Value.PSPath)) { paths.Add(kv.Value.PSPath); }
            }
        }

        if (model.UsbControllerAssociationList != null)
        {
            for (int i = 0; i < model.UsbControllerAssociationList.Count; i++)
            {
                UsbControllerAssociationRecord assoc = model.UsbControllerAssociationList[i];
                if (assoc == null || String.IsNullOrWhiteSpace(assoc.CtrlId)) { continue; }
                paths.Add(InstanceIdToHklmEnumPath(assoc.CtrlId));
            }
        }

        if (model.AudioEndpoints != null)
        {
            foreach (KeyValuePair<string, DeviceNode> kv in model.AudioEndpoints)
            {
                if (!String.IsNullOrWhiteSpace(kv.Key)) { paths.Add(InstanceIdToHklmEnumPath(kv.Key)); }
            }
        }

        AddStartupRowRegistryPaths(paths, startup.AllDeviceRows);
        AddStartupRowRegistryPaths(paths, startup.StorageRows);
        AddStartupRowRegistryPaths(paths, startup.NetworkAdapterRows);

        if (paths.Count > 0)
        {
            Dictionary<string, DeviceRegistryState> states = DeviceTweakerRegistrySnapshot.ReadDeviceRegistryStates(paths);
            if (states != null) { startup.RegistryStateByPath = states; }
        }
    }

    private static void AddStartupRowRegistryPaths(List<string> paths, System.Collections.IEnumerable rows)
    {
        if (paths == null || rows == null) { return; }
        foreach (object row in rows)
        {
            if (row == null) { continue; }
            string registryPath = StartupProp(row, "RegistryPath");
            string configPath = StartupProp(row, "ConfigPath");
            string psPath = StartupProp(row, "PSPath");
            if (!String.IsNullOrWhiteSpace(registryPath)) { paths.Add(registryPath); }
            if (!String.IsNullOrWhiteSpace(configPath)) { paths.Add(configPath); }
            if (!String.IsNullOrWhiteSpace(psPath)) { paths.Add(psPath); }
        }
    }

    private static string InstanceIdToHklmEnumPath(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        string text = StartupInstanceIdFromRegistryPath(instanceId);
        if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
        if (text.StartsWith(@"HKEY_LOCAL_MACHINE", StringComparison.OrdinalIgnoreCase)) { return text; }
        if (text.StartsWith(@"HKLM:\", StringComparison.OrdinalIgnoreCase)) { return @"HKEY_LOCAL_MACHINE\" + text.Substring(6).TrimStart('\\'); }
        if (text.StartsWith(@"SYSTEM\CurrentControlSet\Enum", StringComparison.OrdinalIgnoreCase)) { return @"HKEY_LOCAL_MACHINE\" + text.TrimStart('\\'); }
        return @"HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Enum\" + text.Trim('\\');
    }

    private static CpuStartupTopologyModel BuildCpuStartupTopologyModel()
    {
        CpuStartupTopologyModel cpu = new CpuStartupTopologyModel();
        cpu.LogicalProcessorCount = Environment.ProcessorCount;
        try { cpu.CoreGroups = CpuInfo.GetProcessorCoreGroups(); } catch { cpu.CoreGroups = new List<CpuInfo.CoreGroupInfo>(); }
        try { cpu.L3CacheGroups = CpuInfo.GetL3CacheGroups(); } catch { cpu.L3CacheGroups = new List<CpuInfo.CacheGroupInfo>(); }
        try { cpu.EfficiencyClassByLogicalProcessor = CpuInfo.GetCoreEfficiencyClasses(); } catch { cpu.EfficiencyClassByLogicalProcessor = new Dictionary<int, byte>(); }

        cpu.PhysicalCoreCount = (cpu.CoreGroups != null && cpu.CoreGroups.Count > 0) ? cpu.CoreGroups.Count : cpu.LogicalProcessorCount;
        if (cpu.PhysicalCoreCount < 1) { cpu.PhysicalCoreCount = Math.Max(1, cpu.LogicalProcessorCount); }

        try
        {
            int min = Int32.MaxValue;
            int max = Int32.MinValue;
            foreach (KeyValuePair<int, byte> kv in cpu.EfficiencyClassByLogicalProcessor)
            {
                int value = (int)kv.Value;
                if (value < min) { min = value; }
                if (value > max) { max = value; }
            }
            cpu.IsHeterogeneous = (min != Int32.MaxValue && max != Int32.MinValue && min != max);
        }
        catch { cpu.IsHeterogeneous = false; }

        try
        {
            using (Microsoft.Win32.RegistryKey rk = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"HARDWARE\DESCRIPTION\System\CentralProcessor\0", false))
            {
                if (rk != null)
                {
                    object vendor = rk.GetValue("VendorIdentifier", null);
                    object name = rk.GetValue("ProcessorNameString", null);
                    cpu.VendorIdentifier = vendor == null ? String.Empty : Convert.ToString(vendor);
                    cpu.ProcessorName = name == null ? String.Empty : Convert.ToString(name);
                    string combined = (cpu.VendorIdentifier ?? String.Empty) + " " + (cpu.ProcessorName ?? String.Empty);
                    cpu.IsIntelCpu = combined.IndexOf("GenuineIntel", StringComparison.OrdinalIgnoreCase) >= 0 || combined.IndexOf("Intel", StringComparison.OrdinalIgnoreCase) >= 0;
                }
            }
        }
        catch { }

        try
        {
            cpu.IsDualCcdCandidate = cpu.L3CacheGroups != null && cpu.L3CacheGroups.Count >= 2;
            if (cpu.IsDualCcdCandidate)
            {
                if (cpu.L3CacheGroups.Count > 0)
                {
                    cpu.Ccd0LogicalProcessors = SortedUnique(cpu.L3CacheGroups[0].LogicalProcessors);
                    cpu.Ccd0L3Bytes = (ulong)cpu.L3CacheGroups[0].CacheSize;
                }
                if (cpu.L3CacheGroups.Count > 1)
                {
                    cpu.Ccd1LogicalProcessors = SortedUnique(cpu.L3CacheGroups[1].LogicalProcessors);
                    cpu.Ccd1L3Bytes = (ulong)cpu.L3CacheGroups[1].CacheSize;
                }
            }
        }
        catch { }

        return cpu;
    }

    private static int[] SortedUnique(int[] values)
    {
        if (values == null || values.Length == 0) { return new int[0]; }
        SortedSet<int> set = new SortedSet<int>();
        for (int i = 0; i < values.Length; i++) { if (values[i] >= 0) { set.Add(values[i]); } }
        int[] result = new int[set.Count];
        set.CopyTo(result);
        return result;
    }

    private static string ClassifyHidRoleFromInstanceAndProduct(string instanceId, string product)
    {
        string text = ((instanceId ?? String.Empty) + " " + (product ?? String.Empty));
        if (text.IndexOf("keyboard", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("UP:0001_U:0006", StringComparison.OrdinalIgnoreCase) >= 0) { return "Keyboard"; }
        if (text.IndexOf("mouse", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("UP:0001_U:0002", StringComparison.OrdinalIgnoreCase) >= 0) { return "Mouse"; }
        if (text.IndexOf("audio", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("headset", StringComparison.OrdinalIgnoreCase) >= 0 || text.IndexOf("microphone", StringComparison.OrdinalIgnoreCase) >= 0) { return "Audio"; }
        return String.Empty;
    }

    public static DeviceDiscoveryModel BuildModel()
    {
        DeviceTopologySnapshot snapshot = null;
        try { snapshot = UsbBIntervalReader.BuildDeviceTopologySnapshot(); }
        catch { snapshot = new DeviceTopologySnapshot(); }

        DeviceDiscoveryModel model = BuildFromSnapshot(snapshot);
        try { AddPciRegistryDevices(model); } catch { }
        return model;
    }

    private static DeviceDiscoveryModel BuildFromSnapshot(DeviceTopologySnapshot snapshot)
    {
        DeviceDiscoveryModel model = new DeviceDiscoveryModel();
        model.TopologySnapshot = snapshot ?? new DeviceTopologySnapshot();

        if (model.TopologySnapshot.DevicesByInstanceId != null && model.TopologySnapshot.DevicesByInstanceId.Count > 0)
        {
            foreach (KeyValuePair<string, DeviceNode> entry in model.TopologySnapshot.DevicesByInstanceId)
            {
                if (!String.IsNullOrWhiteSpace(entry.Key) && entry.Value != null && !model.DevicesByInstanceId.ContainsKey(entry.Key))
                {
                    model.DevicesByInstanceId[entry.Key] = entry.Value;
                }
            }
        }

        if (model.TopologySnapshot.DeviceNodes != null)
        {
            for (int i = 0; i < model.TopologySnapshot.DeviceNodes.Count; i++)
            {
                DeviceNode node = model.TopologySnapshot.DeviceNodes[i];
                if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }

                model.DevicesByInstanceId[node.InstanceId] = node;
                if (!String.IsNullOrWhiteSpace(node.NormalizedInstanceId)) { model.DevicesByInstanceId[node.NormalizedInstanceId] = node; }

                if (!String.IsNullOrWhiteSpace(node.ParentInstanceId))
                {
                    model.ParentByInstanceId[node.InstanceId] = node.ParentInstanceId;
                }

                if (node.IsPresent && String.Equals(node.ClassName, "AudioEndpoint", StringComparison.OrdinalIgnoreCase))
                {
                    model.AudioEndpoints[node.InstanceId] = node;
                }
            }
        }

        if (model.TopologySnapshot.ParentMap != null)
        {
            foreach (KeyValuePair<string, string> parent in model.TopologySnapshot.ParentMap)
            {
                if (!String.IsNullOrWhiteSpace(parent.Key) && !String.IsNullOrWhiteSpace(parent.Value))
                {
                    model.ParentByInstanceId[parent.Key] = parent.Value;
                }
            }
        }

        if (model.TopologySnapshot.ControllerAssociations != null)
        {
            for (int i = 0; i < model.TopologySnapshot.ControllerAssociations.Count; i++)
            {
                UsbControllerAssociationRecord assoc = model.TopologySnapshot.ControllerAssociations[i];
                if (assoc == null || String.IsNullOrWhiteSpace(assoc.CtrlId)) { continue; }

                model.UsbControllerAssociationList.Add(assoc);

                List<UsbControllerAssociationRecord> list;
                if (!model.UsbControllerAssociations.TryGetValue(assoc.CtrlId, out list))
                {
                    list = new List<UsbControllerAssociationRecord>();
                    model.UsbControllerAssociations[assoc.CtrlId] = list;
                }
                list.Add(assoc);

                DeviceNode controllerNode = null;
                if (!model.DevicesByInstanceId.TryGetValue(assoc.CtrlId, out controllerNode) || controllerNode == null)
                {
                    controllerNode = new DeviceNode { InstanceId = assoc.CtrlId, FriendlyName = assoc.CtrlId, DeviceDesc = assoc.CtrlId, IsPresent = true };
                }
                model.UsbControllers[assoc.CtrlId] = controllerNode;
            }
        }

        if (model.TopologySnapshot.HidInterfaces != null)
        {
            for (int i = 0; i < model.TopologySnapshot.HidInterfaces.Count; i++)
            {
                HidInterfaceInfo hid = model.TopologySnapshot.HidInterfaces[i];
                if (hid == null) { continue; }
                string key = !String.IsNullOrWhiteSpace(hid.Instance) ? hid.Instance : hid.DevicePath;
                if (!String.IsNullOrWhiteSpace(key)) { model.HidInterfaces[key] = hid; }
            }
        }

        if (model.TopologySnapshot.UsbEnumeration != null && model.TopologySnapshot.UsbEnumeration.Endpoints != null)
        {
            for (int i = 0; i < model.TopologySnapshot.UsbEnumeration.Endpoints.Count; i++)
            {
                UsbEndpointRecord endpoint = model.TopologySnapshot.UsbEnumeration.Endpoints[i];
                if (endpoint == null) { continue; }
                string key = BuildEndpointDescriptorKey(endpoint, i);
                model.EndpointDescriptors[key] = endpoint;
            }
        }

        return model;
    }

    private static string BuildEndpointDescriptorKey(UsbEndpointRecord endpoint, int ordinal)
    {
        string controller = endpoint.HostControllerPath ?? String.Empty;
        string hub = endpoint.HubPath ?? String.Empty;
        string topology = endpoint.TopologyPath ?? String.Empty;
        string mi = endpoint.InterfaceNumber >= 0 ? endpoint.InterfaceNumber.ToString("X2") : "NA";
        string ep = !String.IsNullOrWhiteSpace(endpoint.EndpointAddress) ? endpoint.EndpointAddress : "NA";
        return controller + "|" + hub + "|" + topology + "|MI_" + mi + "|EP_" + ep + "|" + ordinal.ToString();
    }

    private static void AddPciRegistryDevices(DeviceDiscoveryModel model)
    {
        if (model == null) { return; }

        Microsoft.Win32.RegistryKey root = null;
        try
        {
            root = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum\PCI");
            if (root == null) { return; }

            string[] venKeyNames = root.GetSubKeyNames();
            for (int v = 0; v < venKeyNames.Length; v++)
            {
                string venKeyName = venKeyNames[v];
                Microsoft.Win32.RegistryKey venKey = null;
                try
                {
                    venKey = root.OpenSubKey(venKeyName);
                    if (venKey == null) { continue; }

                    string[] instNames = venKey.GetSubKeyNames();
                    for (int i = 0; i < instNames.Length; i++)
                    {
                        string instName = instNames[i];
                        Microsoft.Win32.RegistryKey instKey = null;
                        try
                        {
                            instKey = venKey.OpenSubKey(instName);
                            if (instKey == null) { continue; }

                            object descValue = instKey.GetValue("DeviceDesc", null);
                            if (descValue == null) { continue; }

                            string instanceId = "PCI\\" + venKeyName + "\\" + instName;
                            string path = @"HKLM:\SYSTEM\CurrentControlSet\Enum\PCI\" + venKeyName + @"\" + instName;
                            string desc = Convert.ToString(descValue);
                            string location = Convert.ToString(instKey.GetValue("LocationInformation", null));
                            string[] hardwareIds = RegistryValueToStringArray(instKey.GetValue("HardwareID", null));
                            string[] compatibleIds = RegistryValueToStringArray(instKey.GetValue("CompatibleIDs", null));
                            string hardwareId = hardwareIds.Length > 0 && !String.IsNullOrWhiteSpace(hardwareIds[0]) ? hardwareIds[0] : venKeyName;
                            string classCode = ExtractPciClassCode(hardwareIds, compatibleIds, instanceId, hardwareId, venKeyName);
                            bool isHda = IsHdaClassCode(classCode) || ContainsHdaIdentityText(desc, hardwareIds, compatibleIds, instanceId, hardwareId, venKeyName);

                            PciDeviceInfo info = new PciDeviceInfo();
                            info.PSPath = path;
                            info.DeviceDesc = desc;
                            info.LocationInformation = location;
                            info.InstanceId = instanceId;
                            info.HardwareId = hardwareId;
                            info.HardwareIds = hardwareIds;
                            info.CompatibleIds = compatibleIds;
                            info.ClassCode = classCode;
                            info.IsGpuClassCode = IsGpuDisplayClassCode(classCode);
                            info.PNPID = BuildPciPnpId(hardwareId);
                            info.PortId = ExtractPciPortId(instanceId);
                            info.IsGpuDescription = ContainsAny(desc, new string[] { "AMD", "NVIDIA", "Radeon", "GeForce", "Intel", "Arc" });
                            info.IsHdaController = isHda;
                            info.IsAudioController = isHda || (!String.IsNullOrWhiteSpace(desc) && desc.IndexOf("Audio Controller", StringComparison.OrdinalIgnoreCase) >= 0);

                            model.PciDevicesByPath[info.PSPath] = info;
                            model.PciDevicesByInstanceId[info.InstanceId] = info;
                        }
                        catch { }
                        finally { if (instKey != null) { try { instKey.Close(); } catch { } } }
                    }
                }
                catch { }
                finally { if (venKey != null) { try { venKey.Close(); } catch { } } }
            }
        }
        finally { if (root != null) { try { root.Close(); } catch { } } }
    }

    private static bool ContainsAny(string text, string[] tokens)
    {
        if (String.IsNullOrWhiteSpace(text) || tokens == null) { return false; }
        for (int i = 0; i < tokens.Length; i++)
        {
            if (!String.IsNullOrEmpty(tokens[i]) && text.IndexOf(tokens[i], StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        }
        return false;
    }

    private static string[] RegistryValueToStringArray(object value)
    {
        if (value == null) { return new string[0]; }
        string[] arr = value as string[];
        if (arr != null) { return arr; }
        System.Array array = value as System.Array;
        if (array != null)
        {
            List<string> list = new List<string>();
            foreach (object item in array) { if (item != null) { list.Add(Convert.ToString(item)); } }
            return list.ToArray();
        }
        return new string[] { Convert.ToString(value) };
    }

    private static string ExtractPciClassCode(params object[] values)
    {
        if (values == null) { return String.Empty; }
        for (int i = 0; i < values.Length; i++)
        {
            object value = values[i];
            if (value == null) { continue; }
            System.Collections.IEnumerable enumerable = value as System.Collections.IEnumerable;
            if (enumerable != null && !(value is string))
            {
                foreach (object item in enumerable)
                {
                    string nested = ExtractPciClassCode(item);
                    if (!String.IsNullOrWhiteSpace(nested)) { return nested; }
                }
                continue;
            }
            string text = Convert.ToString(value);
            if (String.IsNullOrWhiteSpace(text)) { continue; }
            Match m = Regex.Match(text, "CC_([0-9A-Fa-f]{4,6})", RegexOptions.IgnoreCase);
            if (!m.Success) { continue; }
            string raw = m.Groups[1].Value.ToUpperInvariant();
            return raw.Length >= 4 ? raw.Substring(0, 4) : raw;
        }
        return String.Empty;
    }

    private static bool IsHdaClassCode(string classCode)
    {
        return !String.IsNullOrWhiteSpace(classCode) && classCode.Trim().StartsWith("0403", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsGpuDisplayClassCode(string classCode)
    {
        if (String.IsNullOrWhiteSpace(classCode)) { return false; }
        string normalized = classCode.Trim();
        if (normalized.StartsWith("CC_", StringComparison.OrdinalIgnoreCase)) { normalized = normalized.Substring(3); }
        if (normalized.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { normalized = normalized.Substring(2); }
        return normalized.Length >= 2 && normalized.StartsWith("03", StringComparison.OrdinalIgnoreCase);
    }

    private static bool ContainsHdaIdentityText(params object[] values)
    {
        if (values == null) { return false; }
        for (int i = 0; i < values.Length; i++)
        {
            object value = values[i];
            if (value == null) { continue; }
            System.Collections.IEnumerable enumerable = value as System.Collections.IEnumerable;
            if (enumerable != null && !(value is string))
            {
                foreach (object item in enumerable) { if (ContainsHdaIdentityText(item)) { return true; } }
                continue;
            }
            string text = Convert.ToString(value);
            if (String.IsNullOrWhiteSpace(text)) { continue; }
            if (text.IndexOf("High Definition Audio", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
            if (text.IndexOf("HDAUDIO", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
            if (text.IndexOf("CC_0403", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        }
        return false;
    }

    private static string BuildPciPnpId(string hardwareId)
    {
        if (String.IsNullOrWhiteSpace(hardwareId)) { return String.Empty; }
        Match venMatch = Regex.Match(hardwareId, @"VEN_([0-9A-Fa-f]{4})", RegexOptions.IgnoreCase);
        Match devMatch = Regex.Match(hardwareId, @"DEV_([0-9A-Fa-f]{4})", RegexOptions.IgnoreCase);
        string vendor = venMatch.Success ? "VEN_" + venMatch.Groups[1].Value.ToUpperInvariant() : String.Empty;
        string device = devMatch.Success ? "DEV_" + devMatch.Groups[1].Value.ToUpperInvariant() : String.Empty;
        if (vendor.Length > 0 && device.Length > 0) { return "PCI_" + vendor + "_" + device; }
        if (vendor.Length > 0) { return "PCI_" + vendor + "_UNKNOWN_DEV"; }
        if (device.Length > 0) { return "PCI_UNKNOWN_VEN_" + device; }
        return String.Empty;
    }

    private static string ExtractPciPortId(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }

        int leafStart = instanceId.LastIndexOf('\\') + 1;
        if (leafStart <= 0 || leafStart >= instanceId.Length) { return String.Empty; }

        string leaf = instanceId.Substring(leafStart);
        if (String.IsNullOrWhiteSpace(leaf)) { return String.Empty; }

        int firstAmp = leaf.IndexOf('&');
        if (firstAmp < 0) { return leaf; }
        int secondAmp = leaf.IndexOf('&', firstAmp + 1);
        if (secondAmp < 0) { return leaf; }
        int thirdAmp = leaf.IndexOf('&', secondAmp + 1);
        if (thirdAmp < 0) { return leaf; }

        return leaf.Substring(0, thirdAmp);
    }
