    public static UsbDiscoveryResult BuildUsbDisplayRecords(DeviceDiscoveryModel model, List<UsbHidDeviceInfo> hidDevices, List<AudioEndpointInfo> audioDetails, string[] ignoredAudioNames)
    {
        UsbDiscoveryResult result = new UsbDiscoveryResult();
        if (model == null) { model = BuildModel(); }
        if (hidDevices == null) { hidDevices = new List<UsbHidDeviceInfo>(); }
        if (audioDetails == null) { audioDetails = new List<AudioEndpointInfo>(); }

        Dictionary<string, List<AudioEndpointInfo>> audioDetailsByController = BuildAudioDetailsByController(audioDetails);
        Dictionary<string, HidRoleState> hidRoleMap = new Dictionary<string, HidRoleState>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, Dictionary<string, PollingRateInfo>> pollingRateMap = new Dictionary<string, Dictionary<string, PollingRateInfo>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, List<EndpointSpecEntry>> endpointSpecLookup = new Dictionary<string, List<EndpointSpecEntry>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, PollingRateInfo> pollingLookup = BuildPollingRateLookup(model);
        HashSet<string> ignoredSet = BuildStringSet(ignoredAudioNames);

        for (int i = 0; i < hidDevices.Count; i++)
        {
            UsbHidDeviceInfo hid = hidDevices[i];
            if (hid == null || hid.USBControllerPNPIDs == null || hid.USBControllerPNPIDs.Count == 0) { continue; }

            string devVidPid = ExtractVidPidPair(hid.DeviceInstanceID);
            for (int c = 0; c < hid.USBControllerPNPIDs.Count; c++)
            {
                string controllerId = hid.USBControllerPNPIDs[c];
                string ctrlKey = ToPnpId(controllerId);
                if (String.IsNullOrWhiteSpace(ctrlKey)) { continue; }

                HidRoleState state;
                if (!hidRoleMap.TryGetValue(ctrlKey, out state))
                {
                    state = new HidRoleState();
                    hidRoleMap[ctrlKey] = state;
                }

                string role = CleanText(hid.DeviceType);
                if (!String.IsNullOrWhiteSpace(role) && !String.IsNullOrWhiteSpace(devVidPid))
                {
                    AddEndpointSpecs(endpointSpecLookup, model, ctrlKey, role, devVidPid, hid.DeviceInstanceID, hid.ProductString);
                }

                if (String.Equals(role, "Keyboard", StringComparison.OrdinalIgnoreCase)) { state.Keyboard = true; }
                else if (String.Equals(role, "Mouse", StringComparison.OrdinalIgnoreCase)) { state.Mouse = true; }
                else if (String.Equals(role, "Audio", StringComparison.OrdinalIgnoreCase))
                {
                    state.Audio = true;
                    string audioReason = !String.IsNullOrWhiteSpace(hid.ClassificationReason) ? hid.ClassificationReason : "HID interface classified as Audio";
                    state.AudioReasons.Add("Product='" + SafeText(hid.ProductString) + "' InstanceId='" + SafeText(hid.DeviceInstanceID) + "' | " + audioReason);
                    AddMergedAudioDetail(audioDetailsByController, ctrlKey, new AudioEndpointInfo
                    {
                        AudioDevice = hid.ProductString,
                        AudioType = "Audio",
                        UsbVidPid = devVidPid,
                        InstanceId = hid.DeviceInstanceID,
                        Reason = audioReason,
                        ControllerID = ctrlKey
                    });
                }

                if ((String.Equals(role, "Keyboard", StringComparison.OrdinalIgnoreCase) || String.Equals(role, "Mouse", StringComparison.OrdinalIgnoreCase)) && !String.IsNullOrWhiteSpace(devVidPid))
                {
                    PollingRateInfo pr;
                    if (pollingLookup.TryGetValue(devVidPid, out pr))
                    {
                        SetPollingRateForRole(pollingRateMap, ctrlKey, role, pr);
                    }
                }
            }
        }

        Dictionary<string, UsbControllerBuild> controllerMap = new Dictionary<string, UsbControllerBuild>(StringComparer.OrdinalIgnoreCase);
        HashSet<string> loggedRoleKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        List<UsbControllerAssociationRecord> pairs = model != null ? model.UsbControllerAssociationList : null;
        if ((pairs == null || pairs.Count == 0) && model != null && model.TopologySnapshot != null) { pairs = model.TopologySnapshot.ControllerAssociations; }
        if (pairs == null) { pairs = new List<UsbControllerAssociationRecord>(); }

        for (int i = 0; i < pairs.Count; i++)
        {
            UsbControllerAssociationRecord pair = pairs[i];
            if (pair == null || String.IsNullOrWhiteSpace(pair.CtrlId)) { continue; }

            string ctrlKey = ToPnpId(pair.CtrlId);
            if (String.IsNullOrWhiteSpace(ctrlKey)) { continue; }
            DeviceDisplayInfo ctrlInfo = ResolveDeviceInfo(model, pair.CtrlId);

            UsbControllerBuild build;
            if (!controllerMap.TryGetValue(ctrlKey, out build))
            {
                build = new UsbControllerBuild();
                build.Key = ctrlKey;
                build.RegistryPath = ctrlInfo.RegistryPath;
                build.Description = ctrlInfo.DeviceDesc;
                controllerMap[ctrlKey] = build;
            }

            DeviceDisplayInfo devInfo = ResolveDeviceInfo(model, pair.DevId);
            if (devInfo != null && !String.IsNullOrWhiteSpace(devInfo.DeviceDesc) && DeviceTweakerPathHelpers.ContainsGameControllerText(devInfo.DeviceDesc))
            {
                build.AddRole("Controller");
                string gcVidPid = ExtractVidPidPair(pair.DevId);
                if (!String.IsNullOrWhiteSpace(gcVidPid))
                {
                    AddEndpointSpecs(endpointSpecLookup, model, ctrlKey, "Controller", gcVidPid, pair.DevId, devInfo.DeviceDesc);
                    PollingRateInfo gcPr;
                    if (pollingLookup.TryGetValue(gcVidPid, out gcPr)) { SetPollingRateForRole(pollingRateMap, ctrlKey, "Controller", gcPr); }
                }
            }

            List<AudioEndpointInfo> mappedAudio;
            if (audioDetailsByController.TryGetValue(ctrlKey, out mappedAudio))
            {
                HashSet<string> seenAudioTypes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int a = 0; a < mappedAudio.Count; a++)
                {
                    AudioEndpointInfo detail = mappedAudio[a];
                    if (detail == null) { continue; }
                    string atype = CleanText(detail.AudioType);
                    if (String.IsNullOrWhiteSpace(atype) || !seenAudioTypes.Add(atype)) { continue; }
                    if (build.AddRole(atype))
                    {
                        string logKey = ctrlKey + "|" + atype;
                        if (loggedRoleKeys.Add(logKey))
                        {
                            result.Logs.Add("Get-USBControllers: Assigned audio role -> Role='" + atype + "' Controller='" + ctrlKey + "' Desc='" + SafeText(build.Description) + "'");
                        }
                    }
                }
                for (int a = 0; a < mappedAudio.Count; a++)
                {
                    AudioEndpointInfo detail = mappedAudio[a];
                    if (detail == null) { continue; }
                    string atype = CleanText(detail.AudioType);
                    AddEndpointSpecs(endpointSpecLookup, model, ctrlKey, atype, detail.UsbVidPid, detail.InstanceId, detail.AudioDevice);
                }
            }
        }

        foreach (KeyValuePair<string, HidRoleState> hidEntry in hidRoleMap)
        {
            UsbControllerBuild build;
            if (!controllerMap.TryGetValue(hidEntry.Key, out build)) { continue; }
            HidRoleState state = hidEntry.Value;
            if (state.Keyboard && build.AddRole("Keyboard"))
            {
                string logKey = hidEntry.Key + "|Keyboard";
                if (loggedRoleKeys.Add(logKey)) { result.Logs.Add("Get-USBControllers: Assigned HID role -> Role='Keyboard' Controller='" + hidEntry.Key + "' Desc='" + SafeText(build.Description) + "'"); }
            }
            if (state.Mouse && build.AddRole("Mouse"))
            {
                string logKey = hidEntry.Key + "|Mouse";
                if (loggedRoleKeys.Add(logKey)) { result.Logs.Add("Get-USBControllers: Assigned HID role -> Role='Mouse' Controller='" + hidEntry.Key + "' Desc='" + SafeText(build.Description) + "'"); }
            }
            if (state.Audio && build.AddRole("Audio"))
            {
                string logKey = hidEntry.Key + "|Audio";
                if (loggedRoleKeys.Add(logKey))
                {
                    string reasonText = state.AudioReasons.Count > 0 ? String.Join("; ", state.AudioReasons.ToArray()) : "HID special handling";
                    result.Logs.Add("Get-USBControllers: Assigned audio role -> Role='Audio' Controller='" + hidEntry.Key + "' Source='HID special handling' Desc='" + SafeText(build.Description) + "' | Reason: " + reasonText);
                }
            }
        }

        result.Logs.Add("Get-USBControllers: Final controller map collected for GUI:");
        foreach (KeyValuePair<string, UsbControllerBuild> entry in controllerMap)
        {
            string roles = entry.Value.Roles.Count > 0 ? String.Join("/", SortedUnique(entry.Value.Roles)) : "<none>";
            result.Logs.Add("  - Controller entry: Controller='" + entry.Key + "' Roles='" + roles + "' Path='" + SafeText(entry.Value.RegistryPath) + "' Desc='" + SafeText(entry.Value.Description) + "'");
        }

        Dictionary<string, string> originMap = BuildUsbControllerOriginMap(model, pairs, controllerMap, result.Logs);
        Dictionary<string, string> maxSpeedLookup = BuildUsbControllerMaxSpeedLabelLookupNative(model);

        foreach (KeyValuePair<string, UsbControllerBuild> entry in controllerMap)
        {
            UsbControllerBuild build = entry.Value;
            if (originMap.ContainsKey(entry.Key) && String.Equals(originMap[entry.Key], "CPU", StringComparison.OrdinalIgnoreCase) && build.Roles.Count == 0)
            {
                result.UnusedCpuControllers.Add(entry.Key);
                result.Logs.Add("Get-USBControllers: WARNING - Unused CPU USB Controller detected -> Controller='" + entry.Key + "'");
            }
        }

        foreach (KeyValuePair<string, UsbControllerBuild> entry in controllerMap)
        {
            UsbControllerBuild build = entry.Value;
            List<string> rolesArr = new List<string>();
            for (int r = 0; r < build.Roles.Count; r++)
            {
                string role = build.Roles[r];
                if (String.IsNullOrWhiteSpace(role)) { continue; }
                if (ignoredSet.Contains(role)) { continue; }
                rolesArr.Add(role);
            }
            if (rolesArr.Count == 0) { continue; }

            SortedSet<string> audioTypeDisplaySet = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
            List<AudioEndpointInfo> details;
            if (audioDetailsByController.TryGetValue(entry.Key, out details))
            {
                for (int d = 0; d < details.Count; d++)
                {
                    string audioType = details[d] != null ? CleanText(details[d].AudioType) : String.Empty;
                    if (String.IsNullOrWhiteSpace(audioType)) { continue; }
                    if (String.Equals(audioType, "Audio", StringComparison.OrdinalIgnoreCase)) { continue; }
                    audioTypeDisplaySet.Add(audioType);
                }
            }
            string[] audioTypesForDisplay = ToArray(audioTypeDisplaySet);
            string audioTypeDisplayText = audioTypesForDisplay.Length > 0 ? String.Join("/", audioTypesForDisplay) : null;

            List<string> roleLabels = new List<string>();
            for (int r = 0; r < rolesArr.Count; r++)
            {
                string role = rolesArr[r];
                string roleTextForDisplay = (audioTypeDisplayText != null && String.Equals(role, "Audio", StringComparison.OrdinalIgnoreCase)) ? "Audio (" + audioTypeDisplayText + ")" : role;
                Dictionary<string, PollingRateInfo> byRole;
                PollingRateInfo pr;
                if (pollingRateMap.TryGetValue(entry.Key, out byRole) && byRole.TryGetValue(role, out pr)) { roleLabels.Add(roleTextForDisplay + " " + pr.Tag); }
                else { roleLabels.Add(roleTextForDisplay); }
            }

            string originLabel = originMap.ContainsKey(entry.Key) ? originMap[entry.Key] : "Chipset";
            string maxLabel = maxSpeedLookup.ContainsKey(entry.Key) ? maxSpeedLookup[entry.Key] : null;
            if (String.IsNullOrWhiteSpace(maxLabel)) { maxLabel = "USB capability unknown"; }
            string rolesDisplayText = roleLabels.Count > 0 ? String.Join("/", roleLabels.ToArray()) : "none";
            string endpointUsageLabel = GetUsbEndpointRoleSpecText(endpointSpecLookup, entry.Key, rolesArr);
            if (String.IsNullOrWhiteSpace(endpointUsageLabel)) { endpointUsageLabel = "Endpoint use: not detected"; }

            result.Devices.Add(new UsbDeviceInfo
            {
                Category = "USB",
                Roles = rolesArr.ToArray(),
                AudioTypes = audioTypesForDisplay,
                DisplayName = originLabel + " USB Controller (Max " + maxLabel + "; Roles - " + rolesDisplayText + ")",
                UsbHeaderTitle = originLabel + " USB controller | Max: " + maxLabel + " | Roles: " + rolesDisplayText,
                UsbEndpointUsageLabel = endpointUsageLabel,
                UsbControllerMaxLabel = maxLabel,
                RegistryPath = build.RegistryPath,
                Description = build.Description
            });
        }

        List<AudioEndpointInfo> flatAudio = new List<AudioEndpointInfo>();
        foreach (KeyValuePair<string, List<AudioEndpointInfo>> entry in audioDetailsByController)
        {
            for (int i = 0; i < entry.Value.Count; i++) { flatAudio.Add(entry.Value[i]); }
        }
        result.AudioDetails = flatAudio;
        if (model != null) { model.UsbDisplayRecords = result.Devices; }
        return result;
    }

    public static PciDiscoveryResult BuildPciDisplayRecords(DeviceDiscoveryModel model, List<AudioEndpointInfo> audioDetails, List<AudioEndpointInfo> audioParentsRaw, string[] ignoredAudioNames, string pciIdsPath)
    {
        PciDiscoveryResult result = new PciDiscoveryResult();
        if (model == null) { model = BuildModel(); }
        if (audioDetails == null) { audioDetails = new List<AudioEndpointInfo>(); }
        if (audioParentsRaw == null) { audioParentsRaw = new List<AudioEndpointInfo>(); }
        HashSet<string> ignoredSet = BuildStringSet(ignoredAudioNames);
        Dictionary<string, List<AudioEndpointInfo>> audioDetailsByController = BuildAudioDetailsByController(audioDetails);

        Dictionary<string, List<PciDeviceInfo>> pciByInstanceId = new Dictionary<string, List<PciDeviceInfo>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, List<PciDeviceInfo>> pciByHardwareId = new Dictionary<string, List<PciDeviceInfo>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, PciDeviceInfo> pciByPath = new Dictionary<string, PciDeviceInfo>(StringComparer.OrdinalIgnoreCase);

        if (model != null && model.PciDevicesByPath != null)
        {
            foreach (KeyValuePair<string, PciDeviceInfo> kv in model.PciDevicesByPath)
            {
                PciDeviceInfo record = kv.Value;
                if (record == null) { continue; }
                if (String.IsNullOrWhiteSpace(record.PSPath)) { record.PSPath = kv.Key; }
                if (String.IsNullOrWhiteSpace(record.InstanceId)) { record.InstanceId = GetPciLookupInstanceId(record.PSPath); }
                if (String.IsNullOrWhiteSpace(record.HardwareId)) { record.HardwareId = GetPciLookupHardwareId(record.InstanceId); }
                if (String.IsNullOrWhiteSpace(record.PortId)) { record.PortId = ExtractPciPortId(record.InstanceId); }
                if (String.IsNullOrWhiteSpace(record.PNPID)) { record.PNPID = BuildPciPnpId(record.HardwareId); }
                if (String.IsNullOrWhiteSpace(record.ClassCode)) { record.ClassCode = ExtractPciClassCode(record.HardwareIds, record.CompatibleIds, record.InstanceId, record.HardwareId, record.PSPath); }
                record.IsGpuDescription = ContainsGpuNameToken(record.DeviceDesc);
                record.IsGpuClassCode = IsGpuDisplayClassCode(record.ClassCode);
                record.IsHdaController = record.IsHdaController || IsHdaClassCode(record.ClassCode) || ContainsHdaIdentityText(record.DeviceDesc, record.HardwareIds, record.CompatibleIds, record.InstanceId, record.HardwareId, record.PSPath);
                record.IsAudioController = record.IsHdaController || ContainsAudioControllerText(record.DeviceDesc);
                pciByPath[record.PSPath] = record;
                AddPciLookupRecord(pciByInstanceId, record.InstanceId, record);
                AddPciLookupRecord(pciByHardwareId, record.HardwareId, record);
            }
        }

        HashSet<string> gpuInstanceSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        HashSet<string> gpuHardwareIdSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (model != null && model.DevicesByInstanceId != null)
        {
            foreach (KeyValuePair<string, DeviceNode> kv in model.DevicesByInstanceId)
            {
                DeviceNode dev = kv.Value;
                if (dev == null || !dev.IsPresent) { continue; }
                if (!String.Equals(dev.ClassName, "Display", StringComparison.OrdinalIgnoreCase)) { continue; }
                string name = FirstNonEmpty(dev.FriendlyName, dev.DeviceDesc, dev.InstanceId);
                if (ContainsGpuNameToken(name))
                {
                    string gpuInstanceKey = GetPciLookupInstanceId(dev.InstanceId);
                    if (!String.IsNullOrWhiteSpace(gpuInstanceKey)) { gpuInstanceSet.Add(gpuInstanceKey); }
                    string gpuHardwareKey = GetPciLookupHardwareId(dev.InstanceId);
                    if (!String.IsNullOrWhiteSpace(gpuHardwareKey)) { gpuHardwareIdSet.Add(gpuHardwareKey); }
                    if (dev.HardwareIds != null)
                    {
                        for (int h = 0; h < dev.HardwareIds.Length; h++)
                        {
                            string candidate = GetPciLookupHardwareId(dev.HardwareIds[h]);
                            if (!String.IsNullOrWhiteSpace(candidate)) { gpuHardwareIdSet.Add(candidate); }
                        }
                    }
                    result.Logs.Add("Get-PCIDevices: PnP Display GPU matched: Name='" + SafeText(name) + "' InstanceId='" + SafeText(dev.InstanceId) + "' Status='OK'");
                }
                else
                {
                    result.Logs.Add("Get-PCIDevices: PnP Display device IGNORED (not GPU): Name='" + SafeText(name) + "' InstanceId='" + SafeText(dev.InstanceId) + "' Status='OK' | Reason: FriendlyName does not match AMD/NVIDIA/Radeon/GeForce/Intel/Arc pattern");
                }
            }
        }

        HashSet<string> matchedGpuPciPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (string key in gpuInstanceSet) { AddGpuPciMatchesFromLookup(pciByInstanceId, key, matchedGpuPciPaths, false); }
        foreach (string key in gpuHardwareIdSet) { AddGpuPciMatchesFromLookup(pciByHardwareId, key, matchedGpuPciPaths, true); }
        if (matchedGpuPciPaths.Count == 0) { AddGpuPciMatchesFromDisplayClassCodeFallback(pciByPath, matchedGpuPciPaths, result.Logs); }

        HashSet<string> gpuPorts = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (KeyValuePair<string, PciDeviceInfo> kv in pciByPath)
        {
            string psPath = kv.Key;
            if (!matchedGpuPciPaths.Contains(psPath)) { continue; }
            PciDeviceInfo record = kv.Value;
            string desc = record.DeviceDesc;
            string regInstanceId = record.InstanceId;
            string portId = !String.IsNullOrWhiteSpace(record.PortId) ? record.PortId : ExtractPciPortId(regInstanceId);
            if (!String.IsNullOrWhiteSpace(portId)) { gpuPorts.Add(portId); }
            string gpuInstanceForName = !String.IsNullOrWhiteSpace(regInstanceId) ? regInstanceId : psPath;
            string gpuResolvedName = ResolvePciDisplayName(gpuInstanceForName, psPath, desc, "GPU", pciIdsPath);
            if (String.IsNullOrWhiteSpace(gpuResolvedName)) { gpuResolvedName = desc; }
            PciDeviceInfo gpu = new PciDeviceInfo
            {
                Category = "PCI",
                Role = "GPU",
                DisplayName = NewTypedDisplayName("GPU", gpuResolvedName),
                RegistryPath = psPath,
                Description = gpuResolvedName,
                ChipsetDescription = desc,
                Port = portId,
                PSPath = psPath,
                DeviceDesc = desc,
                InstanceId = regInstanceId,
                HardwareId = record.HardwareId,
                ClassCode = record.ClassCode,
                PNPID = record.PNPID,
                PortId = portId
            };
            result.GPU.Add(gpu);
            result.Logs.Add("Get-PCIDevices: GPU detected: Path='" + SafeText(psPath) + "' Port='" + SafeText(portId) + "' ChipsetDesc='" + SafeText(desc) + "' ResolvedVideoCard='" + SafeText(gpuResolvedName) + "'");
        }

        List<PciDeviceInfo> ignoredAudio = new List<PciDeviceInfo>();
        foreach (KeyValuePair<string, PciDeviceInfo> kv in pciByPath)
        {
            string psPath = kv.Key;
            PciDeviceInfo record = kv.Value;
            if (record == null || !record.IsAudioController) { continue; }
            string desc = record.DeviceDesc;
            string portId = !String.IsNullOrWhiteSpace(record.PortId) ? record.PortId : ExtractPciPortId(record.InstanceId);
            string pnpId = !String.IsNullOrWhiteSpace(record.PNPID) ? record.PNPID : BuildPciPnpId(record.HardwareId);

            List<AudioEndpointInfo> mappedDetails;
            if (audioDetailsByController.TryGetValue(pnpId, out mappedDetails))
            {
                SortedSet<string> typeSet = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
                SortedSet<string> endpointNameSet = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
                SortedSet<string> reasonSet = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
                for (int m = 0; m < mappedDetails.Count; m++)
                {
                    AudioEndpointInfo detail = mappedDetails[m];
                    if (detail == null) { continue; }
                    string mappedType = CleanText(detail.AudioType);
                    if (!String.IsNullOrWhiteSpace(mappedType) && !String.Equals(mappedType, "Unknown Audio Device", StringComparison.OrdinalIgnoreCase)) { typeSet.Add(mappedType); }
                    if (!String.IsNullOrWhiteSpace(detail.AudioDevice)) { endpointNameSet.Add(detail.AudioDevice.Trim()); }
                    if (!String.IsNullOrWhiteSpace(detail.Reason)) { reasonSet.Add(detail.Reason.Trim()); }
                }
                string[] endpointNames = ToArray(endpointNameSet);
                string classificationReason;
                if (reasonSet.Count > 0) { classificationReason = "Mapped from AudioEndpoint classification reason(s): " + String.Join("; ", ToArray(reasonSet)); }
                else if (mappedDetails.Count > 0) { classificationReason = "Mapped from AudioEndpoint device tree traversal"; }
                else { classificationReason = "Mapped from audio endpoint lookup"; }

                if (typeSet.Count > 0)
                {
                    string[] types = ToArray(typeSet);
                    if (IsHdAudioOnlyTypes(types))
                    {
                        string ignoreReason = "Mapped role is HD Audio-only";
                        PciDeviceInfo ignored = new PciDeviceInfo { PSPath = psPath, PNPID = pnpId, DeviceDesc = desc, Description = ignoreReason, EndpointNames = endpointNames, ClassificationReason = ignoreReason, HardwareId = record.HardwareId, HardwareIds = record.HardwareIds, CompatibleIds = record.CompatibleIds, ClassCode = record.ClassCode, IsHdaController = record.IsHdaController };
                        ignoredAudio.Add(ignored);
                        result.Logs.Add("Get-PCIDevices: IGNORED HDA Audio controller (HD Audio-only classification) -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' Desc='" + SafeText(desc) + "' | EndpointNames='" + (endpointNames.Length > 0 ? String.Join("; ", endpointNames) : "<none>") + "' | Reason: " + ignoreReason);
                        continue;
                    }
                    string audioInstanceForName = !String.IsNullOrWhiteSpace(record.InstanceId) ? record.InstanceId : psPath;
                    string audioResolvedName = ResolvePciDisplayName(audioInstanceForName, psPath, desc, "Audio", pciIdsPath);
                    string display = NewAudioControllerDisplayName(types, audioResolvedName);
                    string descriptionForAudio = String.IsNullOrWhiteSpace(audioResolvedName) ? desc : audioResolvedName;
                    PciDeviceInfo audio = new PciDeviceInfo
                    {
                        Category = "PCI",
                        Role = "Audio",
                        DisplayName = display,
                        RegistryPath = psPath,
                        Description = descriptionForAudio,
                        OriginalDescription = desc,
                        ResolvedName = audioResolvedName,
                        Port = portId,
                        AudioTypes = types,
                        PNPID = pnpId,
                        EndpointNames = endpointNames,
                        ClassificationReason = classificationReason,
                        PSPath = psPath,
                        DeviceDesc = desc,
                        InstanceId = record.InstanceId,
                        HardwareId = record.HardwareId,
                        HardwareIds = record.HardwareIds,
                        CompatibleIds = record.CompatibleIds,
                        ClassCode = record.ClassCode,
                        IsHdaController = record.IsHdaController,
                        PortId = portId
                    };
                    result.Audio.Add(audio);
                    result.Logs.Add("Get-PCIDevices: INCLUDED Audio controller -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' Port='" + SafeText(portId) + "' Desc='" + SafeText(desc) + "' ResolvedName='" + (String.IsNullOrWhiteSpace(audioResolvedName) ? "<none>" : audioResolvedName) + "' Display='" + SafeText(display) + "' Types='" + (types.Length > 0 ? String.Join("/", types) : "<none>") + "' | EndpointNames='" + (endpointNames.Length > 0 ? String.Join("; ", endpointNames) : "<none>") + "' | Reason: " + classificationReason);
                }
                else
                {
                    string ignoreReason = reasonSet.Count > 0 ? "Mapped but no usable audio types; AudioEndpoint reason(s): " + String.Join("; ", ToArray(reasonSet)) : "Mapped but no usable audio types";
                    PciDeviceInfo ignored = new PciDeviceInfo { PSPath = psPath, PNPID = pnpId, DeviceDesc = desc, Description = ignoreReason, EndpointNames = endpointNames, ClassificationReason = ignoreReason };
                    ignoredAudio.Add(ignored);
                    result.Logs.Add("Get-PCIDevices: IGNORED Audio controller (mapped but no usable types) -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' Desc='" + SafeText(desc) + "' | EndpointNames='" + (endpointNames.Length > 0 ? String.Join("; ", endpointNames) : "<none>") + "' | Reason: " + ignoreReason);
                }
            }
            else
            {
                List<string> epReasons = new List<string>();
                List<string> epNames = new List<string>();
                for (int a = 0; a < audioParentsRaw.Count; a++)
                {
                    AudioEndpointInfo epRow = audioParentsRaw[a];
                    if (epRow == null) { continue; }
                    string epName = !String.IsNullOrWhiteSpace(epRow.AudioDevice) ? epRow.AudioDevice : "<unknown>";
                    if (!String.IsNullOrWhiteSpace(epRow.ControllerID)) { epReasons.Add("Endpoint '" + epName + "' (InstanceId='" + SafeText(epRow.InstanceId) + "') -> mapped to different controller '" + epRow.ControllerID + "', not '" + pnpId + "'"); }
                    else { epReasons.Add("Endpoint '" + epName + "' (InstanceId='" + SafeText(epRow.InstanceId) + "') -> could not resolve any PCI/USB parent controller in device tree"); }
                    epNames.Add(epName);
                }
                if (model != null && model.AudioEndpoints != null)
                {
                    foreach (KeyValuePair<string, DeviceNode> ep in model.AudioEndpoints)
                    {
                        DeviceNode d = ep.Value;
                        if (d != null && !String.IsNullOrWhiteSpace(d.FriendlyName) && ignoredSet.Contains(d.FriendlyName))
                        {
                            epReasons.Add("Endpoint '" + d.FriendlyName + "' (InstanceId='" + SafeText(d.InstanceId) + "') -> excluded (DualSense controller audio device)");
                            epNames.Add(d.FriendlyName);
                        }
                    }
                }
                string detailedReason = epReasons.Count == 0 ? "No audio endpoint mapping found; no AudioEndpoint devices detected on system" : "No audio endpoint mapping found; " + epReasons.Count.ToString() + " endpoint(s) checked: " + String.Join("; ", epReasons.ToArray());
                string summaryReason = epReasons.Count > 0 ? "No audio endpoint mapping found" : detailedReason;
                if (record.IsHdaController)
                {
                    string[] types = ContainsAny(desc, new string[] { "HDMI", "Display", "GPU", "NVIDIA", "AMD", "Radeon", "GeForce" }) ? new string[] { "Display Audio" } : new string[] { "HD Audio" };
                    if (IsHdAudioOnlyTypes(types))
                    {
                        string ignoreReason = summaryReason + "; HD Audio-only controller has no non-HD-Audio endpoint role";
                        ignoredAudio.Add(new PciDeviceInfo { PSPath = psPath, PNPID = pnpId, DeviceDesc = desc, Description = ignoreReason, ClassificationReason = ignoreReason, EndpointNames = epNames.ToArray(), HardwareId = record.HardwareId, HardwareIds = record.HardwareIds, CompatibleIds = record.CompatibleIds, ClassCode = record.ClassCode, IsHdaController = true });
                        result.Logs.Add("Get-PCIDevices: IGNORED HDA Audio controller (HD Audio-only classification) -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' ClassCode='" + SafeText(record.ClassCode) + "' Desc='" + SafeText(desc) + "' | Reason: " + SafeText(ignoreReason));
                        continue;
                    }
                    string audioInstanceForName = !String.IsNullOrWhiteSpace(record.InstanceId) ? record.InstanceId : psPath;
                    string audioResolvedName = ResolvePciDisplayName(audioInstanceForName, psPath, desc, "Audio", pciIdsPath);
                    string display = NewAudioControllerDisplayName(types, String.IsNullOrWhiteSpace(audioResolvedName) ? desc : audioResolvedName);
                    PciDeviceInfo audio = new PciDeviceInfo
                    {
                        Category = "PCI",
                        Role = "Audio",
                        DisplayName = display,
                        RegistryPath = psPath,
                        Description = String.IsNullOrWhiteSpace(audioResolvedName) ? desc : audioResolvedName,
                        OriginalDescription = desc,
                        ResolvedName = audioResolvedName,
                        Port = portId,
                        AudioTypes = types,
                        PNPID = pnpId,
                        EndpointNames = epNames.ToArray(),
                        ClassificationReason = summaryReason + "; included because PCI class code/identity matches High Definition Audio",
                        PSPath = psPath,
                        DeviceDesc = desc,
                        InstanceId = record.InstanceId,
                        HardwareId = record.HardwareId,
                        HardwareIds = record.HardwareIds,
                        CompatibleIds = record.CompatibleIds,
                        ClassCode = record.ClassCode,
                        IsHdaController = true,
                        PortId = portId
                    };
                    result.Audio.Add(audio);
                    result.Logs.Add("Get-PCIDevices: INCLUDED HDA Audio controller without endpoint mapping -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' ClassCode='" + SafeText(record.ClassCode) + "' Desc='" + SafeText(desc) + "' | Reason: " + SafeText(audio.ClassificationReason));
                    continue;
                }
                ignoredAudio.Add(new PciDeviceInfo { PSPath = psPath, PNPID = pnpId, DeviceDesc = desc, Description = detailedReason, ClassificationReason = summaryReason, EndpointNames = epNames.ToArray(), HardwareId = record.HardwareId, HardwareIds = record.HardwareIds, CompatibleIds = record.CompatibleIds, ClassCode = record.ClassCode, IsHdaController = record.IsHdaController });
                result.Logs.Add("Get-PCIDevices: IGNORED Audio controller (no mapping) -> PNPID='" + SafeText(pnpId) + "' Path='" + SafeText(psPath) + "' Desc='" + SafeText(desc) + "' | Reason: No audio endpoint mapping found");
                if (epReasons.Count > 0)
                {
                    result.Logs.Add("  Checked AudioEndpoint(s): Count=" + epReasons.Count.ToString() + " ControllerPNPID='" + SafeText(pnpId) + "'");
                    for (int e = 0; e < epReasons.Count; e++) { result.Logs.Add("    - " + epReasons[e]); }
                }
                else { result.Logs.Add("  No AudioEndpoint devices (class=AudioEndpoint, status=OK) found on system to match against"); }
            }
        }

        for (int a = 0; a < result.Audio.Count; a++)
        {
            PciDeviceInfo audio = result.Audio[a];
            if (!String.IsNullOrWhiteSpace(audio.Port) && gpuPorts.Contains(audio.Port) && audio.AudioTypes != null && audio.AudioTypes.Length > 0)
            {
                string oldDisplay = audio.DisplayName;
                string audioGpuModel = audio.ResolvedName;
                audio.DisplayName = NewAudioControllerDisplayName(new string[] { "GPU" }, audioGpuModel);
                audio.Role = "AudioGPU";
                result.Logs.Add("Get-PCIDevices: Audio controller upgraded to Audio-GPU -> PNPID='" + SafeText(audio.PNPID) + "' Path='" + SafeText(audio.RegistryPath) + "' Port='" + SafeText(audio.Port) + "' OldDisplay='" + SafeText(oldDisplay) + "' NewDisplay='" + SafeText(audio.DisplayName) + "' ResolvedName='" + (String.IsNullOrWhiteSpace(audioGpuModel) ? "<none>" : audioGpuModel) + "'");
            }
        }

        result.Logs.Add("Get-PCIDevices: Summary -> GPUsFound=" + result.GPU.Count.ToString() + " AudioControllersIncluded=" + result.Audio.Count.ToString() + " AudioControllersIgnored=" + ignoredAudio.Count.ToString());
        if (result.Audio.Count > 0)
        {
            result.Logs.Add("SUMMARY: Audio controller classification results:");
            for (int i = 0; i < result.Audio.Count; i++)
            {
                PciDeviceInfo ad = result.Audio[i];
                string types = (ad.AudioTypes != null && ad.AudioTypes.Length > 0) ? String.Join("/", ad.AudioTypes) : "<none>";
                string endpointNames = (ad.EndpointNames != null && ad.EndpointNames.Length > 0) ? String.Join("; ", ad.EndpointNames) : "<none>";
                string reason = !String.IsNullOrWhiteSpace(ad.ClassificationReason) ? ad.ClassificationReason : "<none>";
                result.Logs.Add("  - Audio controller: PNPID='" + SafeText(ad.PNPID) + "' Path='" + SafeText(ad.RegistryPath) + "' Port='" + SafeText(ad.Port) + "' Desc='" + SafeText(ad.Description) + "' Types='" + types + "' EndpointNames='" + endpointNames + "' | Reason: " + reason);
            }
        }
        if (ignoredAudio.Count > 0)
        {
            result.Logs.Add("SUMMARY: Audio controllers IGNORED: " + ignoredAudio.Count.ToString() + " controller(s)");
            for (int i = 0; i < ignoredAudio.Count; i++)
            {
                PciDeviceInfo ia = ignoredAudio[i];
                string endpointNames = (ia.EndpointNames != null && ia.EndpointNames.Length > 0) ? String.Join("; ", SortedUnique(ia.EndpointNames)) : "<none>";
                result.Logs.Add("  - Ignored audio controller -> PNPID='" + SafeText(ia.PNPID) + "' Path='" + SafeText(ia.PSPath) + "' Desc='" + SafeText(ia.DeviceDesc) + "'");
                if (ia.EndpointNames != null && ia.EndpointNames.Length > 0)
                {
                    result.Logs.Add("    EndpointNames:");
                    string[] names = SortedUnique(ia.EndpointNames);
                    for (int n = 0; n < names.Length; n++) { result.Logs.Add("      - '" + names[n] + "'"); }
                }
                else { result.Logs.Add("    EndpointNames: <none>"); }
                result.Logs.Add("    Reason: " + SafeText(ia.ClassificationReason));
            }
        }

        if (model != null)
        {
            model.PciGpuDisplayRecords = result.GPU;
            model.PciAudioDisplayRecords = result.Audio;
        }
        return result;
    }

    private static Dictionary<string, List<AudioEndpointInfo>> BuildAudioDetailsByController(List<AudioEndpointInfo> audioDetails)
    {
        Dictionary<string, List<AudioEndpointInfo>> map = new Dictionary<string, List<AudioEndpointInfo>>(StringComparer.OrdinalIgnoreCase);
        if (audioDetails == null) { return map; }
        for (int i = 0; i < audioDetails.Count; i++)
        {
            AudioEndpointInfo detail = audioDetails[i];
            if (detail == null || String.IsNullOrWhiteSpace(detail.ControllerID)) { continue; }
            string key = detail.ControllerID.Trim();
            AddMergedAudioDetail(map, key, detail);
        }
        return map;
    }

    private static void AddMergedAudioDetail(Dictionary<string, List<AudioEndpointInfo>> map, string controllerKey, AudioEndpointInfo detail)
    {
        if (map == null || detail == null || String.IsNullOrWhiteSpace(controllerKey)) { return; }
        List<AudioEndpointInfo> list;
        if (!map.TryGetValue(controllerKey, out list))
        {
            list = new List<AudioEndpointInfo>();
            map[controllerKey] = list;
        }
        if (!String.IsNullOrWhiteSpace(detail.InstanceId))
        {
            for (int i = 0; i < list.Count; i++)
            {
                if (list[i] != null && !String.IsNullOrWhiteSpace(list[i].InstanceId) && String.Equals(list[i].InstanceId, detail.InstanceId, StringComparison.OrdinalIgnoreCase)) { return; }
            }
        }
        if (String.IsNullOrWhiteSpace(detail.ControllerID)) { detail.ControllerID = controllerKey; }
        list.Add(detail);
    }

    private static DeviceDisplayInfo ResolveDeviceInfo(DeviceDiscoveryModel model, string instanceId)
    {
        DeviceDisplayInfo info = new DeviceDisplayInfo();
        info.RegistryPath = InstanceIdToRegistryPath(instanceId);
        info.DeviceDesc = instanceId;
        if (String.IsNullOrWhiteSpace(instanceId)) { return info; }

        DeviceNode node = null;
        if (model != null && model.DevicesByInstanceId != null) { model.DevicesByInstanceId.TryGetValue(instanceId, out node); }
        if (node != null)
        {
            info.DeviceDesc = FirstNonEmpty(node.FriendlyName, node.DeviceDesc, node.InstanceId, instanceId);
            info.RegistryPath = InstanceIdToRegistryPath(FirstNonEmpty(node.InstanceId, instanceId));
            return info;
        }

        try
        {
            using (Microsoft.Win32.RegistryKey enumRoot = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum"))
            {
                if (enumRoot != null)
                {
                    using (Microsoft.Win32.RegistryKey subKey = enumRoot.OpenSubKey(instanceId))
                    {
                        if (subKey != null)
                        {
                            object desc = subKey.GetValue("DeviceDesc", null);
                            if (desc != null) { info.DeviceDesc = Convert.ToString(desc); }
                        }
                    }
                }
            }
        }
        catch { }
        return info;
    }

    private static string InstanceIdToRegistryPath(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        return @"HKLM:\SYSTEM\CurrentControlSet\Enum\" + instanceId.Trim().Trim('\\');
    }

