    private static Dictionary<string, PollingRateInfo> BuildPollingRateLookup(DeviceDiscoveryModel model)
    {
        Dictionary<string, PollingRateInfo> lookup = new Dictionary<string, PollingRateInfo>(StringComparer.OrdinalIgnoreCase);
        if (model == null || model.TopologySnapshot == null || model.TopologySnapshot.UsbEnumeration == null) { return lookup; }
        Dictionary<string, PollingRateLookupRecord> records = DeviceTweakerPathHelpers.BuildPollingRateLookup(model.TopologySnapshot.UsbEnumeration);
        if (records == null) { return lookup; }
        foreach (KeyValuePair<string, PollingRateLookupRecord> kv in records)
        {
            PollingRateLookupRecord record = kv.Value;
            if (record == null || String.IsNullOrWhiteSpace(kv.Key) || record.Hz <= 0.0) { continue; }
            lookup[kv.Key] = new PollingRateInfo { Hz = record.Hz, Tag = record.Tag };
        }
        return lookup;
    }

    private static void SetPollingRateForRole(Dictionary<string, Dictionary<string, PollingRateInfo>> map, string ctrlKey, string role, PollingRateInfo info)
    {
        if (map == null || String.IsNullOrWhiteSpace(ctrlKey) || String.IsNullOrWhiteSpace(role) || info == null) { return; }
        Dictionary<string, PollingRateInfo> byRole;
        if (!map.TryGetValue(ctrlKey, out byRole)) { byRole = new Dictionary<string, PollingRateInfo>(StringComparer.OrdinalIgnoreCase); map[ctrlKey] = byRole; }
        PollingRateInfo existing;
        if (!byRole.TryGetValue(role, out existing) || existing.Hz < info.Hz) { byRole[role] = info; }
    }

