    private static void AddEndpointSpecs(Dictionary<string, List<EndpointSpecEntry>> lookup, DeviceDiscoveryModel model, string controllerKey, string role, string vidPid, string instanceId, string productString)
    {
        if (lookup == null || model == null || model.TopologySnapshot == null) { return; }
        if (String.IsNullOrWhiteSpace(controllerKey) || String.IsNullOrWhiteSpace(role)) { return; }
        List<UsbEndpointRoleSpecRecord> records = DeviceTweakerPathHelpers.BuildUsbEndpointRoleSpecRecords(model.TopologySnapshot.UsbEnumeration, controllerKey, role, vidPid, instanceId, productString);
        if (records == null || records.Count == 0) { return; }
        List<EndpointSpecEntry> entryList;
        if (!lookup.TryGetValue(controllerKey, out entryList)) { entryList = new List<EndpointSpecEntry>(); lookup[controllerKey] = entryList; }
        for (int i = 0; i < records.Count; i++)
        {
            UsbEndpointRoleSpecRecord record = records[i];
            if (record == null || String.IsNullOrWhiteSpace(record.EntryKey)) { continue; }
            bool exists = false;
            for (int e = 0; e < entryList.Count; e++)
            {
                if (String.Equals(entryList[e].EntryKey, record.EntryKey, StringComparison.OrdinalIgnoreCase)) { exists = true; break; }
            }
            if (exists) { continue; }
            entryList.Add(new EndpointSpecEntry
            {
                EntryKey = record.EntryKey,
                ProductString = record.ProductString,
                Role = record.Role,
                SpeedToken = record.SpeedToken,
                Rank = record.Rank,
                VidPid = record.VidPid,
                InstanceId = record.InstanceId,
                InterfaceNumber = record.InterfaceNumber
            });
        }
    }

    private static string GetUsbEndpointRoleSpecText(Dictionary<string, List<EndpointSpecEntry>> lookup, string controllerKey, List<string> roles)
    {
        if (lookup == null || String.IsNullOrWhiteSpace(controllerKey) || !lookup.ContainsKey(controllerKey)) { return null; }
        List<EndpointSpecEntry> raw = lookup[controllerKey];
        if (raw == null || raw.Count == 0) { return null; }
        HashSet<string> roleFilter = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (roles != null)
        {
            for (int i = 0; i < roles.Count; i++) { if (!String.IsNullOrWhiteSpace(roles[i])) { roleFilter.Add(roles[i].Trim()); } }
        }
        List<EndpointSpecEntry> entries = new List<EndpointSpecEntry>();
        for (int i = 0; i < raw.Count; i++)
        {
            EndpointSpecEntry e = raw[i];
            if (e == null || String.IsNullOrWhiteSpace(e.Role) || String.IsNullOrWhiteSpace(e.SpeedToken)) { continue; }
            if (roleFilter.Count > 0 && !roleFilter.Contains(e.Role)) { continue; }
            entries.Add(e);
        }
        if (entries.Count == 0) { return null; }
        entries.Sort(CompareEndpointEntry);
        if (entries.Count == 1)
        {
            EndpointSpecEntry e = entries[0];
            return "Endpoint use: " + FormatEndpointProductRoleText(e.ProductString, e.Role) + " - " + e.SpeedToken;
        }
        Dictionary<string, List<EndpointSpecEntry>> bySpeed = new Dictionary<string, List<EndpointSpecEntry>>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, int> maxRank = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < entries.Count; i++)
        {
            EndpointSpecEntry e = entries[i];
            List<EndpointSpecEntry> list;
            if (!bySpeed.TryGetValue(e.SpeedToken, out list)) { list = new List<EndpointSpecEntry>(); bySpeed[e.SpeedToken] = list; maxRank[e.SpeedToken] = 0; }
            list.Add(e);
            if (e.Rank > maxRank[e.SpeedToken]) { maxRank[e.SpeedToken] = e.Rank; }
        }
        List<string> speedNames = new List<string>(bySpeed.Keys);
        speedNames.Sort(delegate(string a, string b) {
            int rankCompare = maxRank[b].CompareTo(maxRank[a]);
            if (rankCompare != 0) { return rankCompare; }
            return String.Compare(a, b, StringComparison.OrdinalIgnoreCase);
        });
        List<string> parts = new List<string>();
        for (int s = 0; s < speedNames.Count; s++)
        {
            string speed = speedNames[s];
            List<EndpointSpecEntry> list = bySpeed[speed];
            list.Sort(CompareEndpointEntryProductRoleOnly);
            List<string> deviceTexts = new List<string>();
            HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < list.Count; i++)
            {
                string txt = FormatEndpointProductRoleText(list[i].ProductString, list[i].Role);
                if (seen.Add(txt)) { deviceTexts.Add(txt); }
            }
            if (deviceTexts.Count > 0) { parts.Add(speed + ": " + String.Join(", ", deviceTexts.ToArray())); }
        }
        if (parts.Count == 0) { return null; }
        return "Endpoint use: " + String.Join(" | ", parts.ToArray());
    }

    private static int CompareEndpointEntry(EndpointSpecEntry a, EndpointSpecEntry b)
    {
        if (a == null && b == null) { return 0; }
        if (a == null) { return 1; }
        if (b == null) { return -1; }
        int rankCompare = b.Rank.CompareTo(a.Rank);
        if (rankCompare != 0) { return rankCompare; }
        int speedCompare = String.Compare(SafeText(a.SpeedToken), SafeText(b.SpeedToken), StringComparison.OrdinalIgnoreCase);
        if (speedCompare != 0) { return speedCompare; }
        return CompareEndpointEntryProductRoleOnly(a, b);
    }

    private static int CompareEndpointEntryProductRoleOnly(EndpointSpecEntry a, EndpointSpecEntry b)
    {
        if (a == null && b == null) { return 0; }
        if (a == null) { return 1; }
        if (b == null) { return -1; }
        int productCompare = String.Compare(SafeText(a.ProductString), SafeText(b.ProductString), StringComparison.OrdinalIgnoreCase);
        if (productCompare != 0) { return productCompare; }
        return String.Compare(SafeText(a.Role), SafeText(b.Role), StringComparison.OrdinalIgnoreCase);
    }

    private static string FormatEndpointProductRoleText(string product, string role)
    {
        string p = String.IsNullOrWhiteSpace(product) ? "Unknown USB device" : product.Trim();
        string r = String.IsNullOrWhiteSpace(role) ? "Unknown" : role.Trim();
        return "\"" + p.Replace('"', '\'') + "\" (" + r.Replace('"', '\'') + ")";
    }

