    private static Dictionary<string, string> BuildUsbControllerOriginMap(DeviceDiscoveryModel model, List<UsbControllerAssociationRecord> pairs, Dictionary<string, UsbControllerBuild> controllerMap, List<string> logs)
    {
        Dictionary<string, string> originMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        HashSet<string> cpuUsbDevIds = new HashSet<string>(new string[] { "5782", "5785", "5787", "57A5", "1138", "1135", "0B27", "15E9", "15EC", "15F0", "15B5", "15B6", "15C1", "15D4", "15DB" }, StringComparer.OrdinalIgnoreCase);
        Dictionary<string, string> ctrlKeyToInstId = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        if (pairs != null)
        {
            for (int i = 0; i < pairs.Count; i++)
            {
                if (pairs[i] == null) { continue; }
                string key = ToPnpId(pairs[i].CtrlId);
                if (!String.IsNullOrWhiteSpace(key) && !ctrlKeyToInstId.ContainsKey(key)) { ctrlKeyToInstId[key] = pairs[i].CtrlId; }
            }
        }
        Dictionary<int, List<string>> busDescMap = new Dictionary<int, List<string>>();
        if (model != null && model.PciDevicesByPath != null)
        {
            foreach (KeyValuePair<string, PciDeviceInfo> kv in model.PciDevicesByPath)
            {
                PciDeviceInfo pci = kv.Value;
                if (pci == null || String.IsNullOrWhiteSpace(pci.LocationInformation) || String.IsNullOrWhiteSpace(pci.DeviceDesc)) { continue; }
                BdfLocationParseResult lm = DeviceTweakerPathHelpers.ParseBdfLocation(pci.LocationInformation);
                if (lm.Success)
                {
                    List<string> list;
                    if (!busDescMap.TryGetValue(lm.Bus, out list)) { list = new List<string>(); busDescMap[lm.Bus] = list; }
                    list.Add(pci.DeviceDesc);
                }
            }
        }
        foreach (KeyValuePair<string, UsbControllerBuild> controller in controllerMap)
        {
            string origin = "Chipset";
            string instId = ctrlKeyToInstId.ContainsKey(controller.Key) ? ctrlKeyToInstId[controller.Key] : null;
            if (!String.IsNullOrWhiteSpace(instId))
            {
                string devId = DeviceTweakerPathHelpers.ExtractPciDevId(instId);
                if (!String.IsNullOrWhiteSpace(devId) && cpuUsbDevIds.Contains(devId)) { origin = "CPU"; }
                else
                {
                    string loc = ReadEnumRegistryString(instId, "LocationInformation");
                    if (!String.IsNullOrWhiteSpace(loc))
                    {
                        BdfLocationParseResult clm = DeviceTweakerPathHelpers.ParseBdfLocation(loc);
                        if (clm.Success)
                        {
                            if (clm.Device == 13) { origin = "CPU"; }
                            else if (clm.Device == 20) { origin = "Chipset"; }
                            else if (busDescMap.ContainsKey(clm.Bus))
                            {
                                List<string> siblings = busDescMap[clm.Bus];
                                for (int i = 0; i < siblings.Count; i++)
                                {
                                    if (DeviceTweakerPathHelpers.ContainsCpuColocationDescription(siblings[i])) { origin = "CPU"; break; }
                                }
                            }
                        }
                    }
                }
            }
            originMap[controller.Key] = origin;
            if (logs != null) { logs.Add("Get-USBControllers: Controller origin -> Controller='" + controller.Key + "' Origin='" + origin + "' InstanceId='" + SafeText(instId) + "'"); }
        }
        return originMap;
    }

    private static string ReadEnumRegistryString(string instanceId, string valueName)
    {
        if (String.IsNullOrWhiteSpace(instanceId) || String.IsNullOrWhiteSpace(valueName)) { return null; }
        try
        {
            using (Microsoft.Win32.RegistryKey enumRoot = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Enum"))
            using (Microsoft.Win32.RegistryKey sub = enumRoot != null ? enumRoot.OpenSubKey(instanceId) : null)
            {
                if (sub == null) { return null; }
                object value = sub.GetValue(valueName, null);
                return value == null ? null : Convert.ToString(value);
            }
        }
        catch { return null; }
    }

