    private static int AddGpuPciMatchesFromDisplayClassCodeFallback(Dictionary<string, PciDeviceInfo> pciByPath, HashSet<string> matchedPaths, List<string> logs)
    {
        if (pciByPath == null || matchedPaths == null || matchedPaths.Count > 0) { return 0; }
        int added = 0;
        foreach (KeyValuePair<string, PciDeviceInfo> kv in pciByPath)
        {
            PciDeviceInfo record = kv.Value;
            if (record == null || !IsGpuDisplayClassCode(record.ClassCode)) { continue; }
            string psPath = !String.IsNullOrWhiteSpace(record.PSPath) ? record.PSPath : kv.Key;
            if (String.IsNullOrWhiteSpace(psPath)) { continue; }
            if (matchedPaths.Add(psPath))
            {
                added++;
                if (logs != null) { logs.Add("Get-PCIDevices: PCI display-class GPU fallback matched: Path='" + SafeText(psPath) + "' ClassCode='" + SafeText(record.ClassCode) + "' Desc='" + SafeText(record.DeviceDesc) + "' | Reason: name-token GPU detection found zero GPUs and PCI class code starts with 03"); }
            }
        }
        if (logs != null) { logs.Add("Get-PCIDevices: PCI display-class GPU fallback summary -> Matched=" + added.ToString() + " | Activation: name-token GPU detection found zero GPUs"); }
        return added;
    }

    private static void AddGpuPciMatchesFromLookup(Dictionary<string, List<PciDeviceInfo>> lookup, string key, HashSet<string> matchedPaths, bool requireGpuDescription)
    {
        if (lookup == null || matchedPaths == null || String.IsNullOrWhiteSpace(key) || !lookup.ContainsKey(key)) { return; }
        List<PciDeviceInfo> records = lookup[key];
        for (int i = 0; i < records.Count; i++)
        {
            PciDeviceInfo record = records[i];
            if (record == null || String.IsNullOrWhiteSpace(record.PSPath)) { continue; }
            if (requireGpuDescription && !record.IsGpuDescription) { continue; }
            matchedPaths.Add(record.PSPath);
        }
    }

    private static bool ContainsGpuNameToken(string value)
    {
        return ContainsAny(value, new string[] { "AMD", "NVIDIA", "Radeon", "GeForce", "Intel", "Arc" });
    }

    private static bool ContainsAudioControllerText(string value)
    {
        return !String.IsNullOrWhiteSpace(value) && value.IndexOf("Audio Controller", StringComparison.OrdinalIgnoreCase) >= 0;
    }

    private static string ResolvePciDisplayName(string instanceId, string registryPath, string windowsName, string role, string pciIdsPath)
    {
        string baseName = CleanPlainDeviceText(windowsName);
        PciIdentity identity = GetPciIdentity(instanceId, registryPath);
        if (identity == null) { return String.Equals(role, "Audio", StringComparison.OrdinalIgnoreCase) ? String.Empty : baseName; }
        PciIdsResolvedParts parts = FindPciIdsResolvedParts(identity, pciIdsPath);
        if (parts == null || !parts.Available) { return String.Equals(role, "Audio", StringComparison.OrdinalIgnoreCase) ? String.Empty : baseName; }
        string vendorName = parts.VendorName;
        string deviceName = parts.DeviceName;
        string subsystemName = parts.SubsystemName;
        string subVendorName = parts.SubVendorName;
        if (String.Equals(role, "Audio", StringComparison.OrdinalIgnoreCase))
        {
            if (!String.IsNullOrWhiteSpace(deviceName))
            {
                string resolved = MergePciResolvedName(vendorName, deviceName, String.Empty, false);
                if (!String.IsNullOrWhiteSpace(resolved)) { return resolved; }
            }
            if (!String.IsNullOrWhiteSpace(subsystemName))
            {
                string resolved = MergePciResolvedName(subVendorName, subsystemName, String.Empty, true);
                if (!String.IsNullOrWhiteSpace(resolved)) { return resolved; }
            }
            return String.Empty;
        }
        if (String.Equals(role, "GPU", StringComparison.OrdinalIgnoreCase))
        {
            if (!String.IsNullOrWhiteSpace(subsystemName))
            {
                string resolved = MergePciResolvedName(subVendorName, subsystemName, baseName, true);
                if (!String.IsNullOrWhiteSpace(resolved)) { return resolved; }
            }
            if (!String.IsNullOrWhiteSpace(subVendorName) && !String.IsNullOrWhiteSpace(baseName))
            {
                string chipVendor = !String.IsNullOrWhiteSpace(vendorName) ? vendorName : subVendorName;
                string chipSuffix = RemoveLeadingVendorFromName(baseName, chipVendor);
                if (!String.IsNullOrWhiteSpace(chipSuffix) && subVendorName.IndexOf(chipVendor, StringComparison.OrdinalIgnoreCase) < 0) { return JoinDisplayNameParts(new string[] { subVendorName, chipSuffix }); }
            }
            return baseName;
        }
        string generic = MergePciResolvedName(vendorName, deviceName, baseName, false);
        return !String.IsNullOrWhiteSpace(generic) ? generic : baseName;
    }

    private static PciIdentity GetPciIdentity(string instanceId, string registryPath)
    {
        PciIdentityFields parsed = DeviceTweakerPathHelpers.ParsePciIdentity(instanceId, registryPath);
        if (parsed == null || !parsed.Success) { return null; }
        PciIdentity id = new PciIdentity();
        id.VendorId = parsed.VendorId;
        id.DeviceId = parsed.DeviceId;
        id.SubVendorId = parsed.SubVendorId;
        id.SubDeviceId = parsed.SubDeviceId;
        return id;
    }

    private static PciIdsResolvedParts FindPciIdsResolvedParts(PciIdentity identity, string pciIdsPath)
    {
        PciIdsResolvedParts result = new PciIdsResolvedParts();
        result.Available = false;
        result.VendorName = String.Empty;
        result.DeviceName = String.Empty;
        result.SubVendorName = String.Empty;
        result.SubsystemName = String.Empty;
        if (identity == null || String.IsNullOrWhiteSpace(pciIdsPath) || !System.IO.File.Exists(pciIdsPath)) { return result; }
        string currentVendor = String.Empty;
        string currentDevice = String.Empty;
        try
        {
            foreach (string rawLine in System.IO.File.ReadLines(pciIdsPath))
            {
                if (String.IsNullOrWhiteSpace(rawLine)) { continue; }
                char firstChar = rawLine[0];
                if (firstChar == '#') { continue; }
                if (firstChar != '\t')
                {
                    if (rawLine.Length >= 5 && Char.IsWhiteSpace(rawLine[4]))
                    {
                        string possibleVendor = rawLine.Substring(0, 4).ToUpperInvariant();
                        if (Regex.IsMatch(possibleVendor, @"^[0-9A-F]{4}$"))
                        {
                            currentVendor = possibleVendor;
                            currentDevice = String.Empty;
                            string name = rawLine.Length > 5 ? rawLine.Substring(5) : String.Empty;
                            if (currentVendor == identity.VendorId && String.IsNullOrWhiteSpace(result.VendorName)) { result.VendorName = NormalizePciIdsDisplayText(name); }
                            if (!String.IsNullOrWhiteSpace(identity.SubVendorId) && currentVendor == identity.SubVendorId && String.IsNullOrWhiteSpace(result.SubVendorName)) { result.SubVendorName = NormalizePciIdsDisplayText(name); }
                        }
                        else { currentVendor = String.Empty; currentDevice = String.Empty; }
                    }
                    else { currentVendor = String.Empty; currentDevice = String.Empty; }
                    continue;
                }
                if (rawLine.Length > 1 && rawLine[1] == '\t')
                {
                    if (currentVendor == identity.VendorId && currentDevice == identity.DeviceId && !String.IsNullOrWhiteSpace(identity.SubVendorId) && !String.IsNullOrWhiteSpace(identity.SubDeviceId))
                    {
                        string subLine = rawLine.Substring(2).TrimStart();
                        string[] parts = Regex.Split(subLine, @"\s+");
                        if (parts.Length >= 3)
                        {
                            string sv = parts[0].ToUpperInvariant();
                            string sd = parts[1].ToUpperInvariant();
                            if (sv == identity.SubVendorId && sd == identity.SubDeviceId)
                            {
                                int nameStart = subLine.IndexOf(parts[1], StringComparison.Ordinal) + parts[1].Length;
                                result.SubsystemName = NormalizePciIdsDisplayText(subLine.Substring(nameStart));
                            }
                        }
                    }
                    continue;
                }
                if (currentVendor == identity.VendorId)
                {
                    string deviceLine = rawLine.Substring(1).TrimStart();
                    if (deviceLine.Length >= 6)
                    {
                        string possibleDevice = deviceLine.Substring(0, 4).ToUpperInvariant();
                        if (Regex.IsMatch(possibleDevice, @"^[0-9A-F]{4}$"))
                        {
                            currentDevice = possibleDevice;
                            if (currentDevice == identity.DeviceId && String.IsNullOrWhiteSpace(result.DeviceName))
                            {
                                int start = 4;
                                while (start < deviceLine.Length && Char.IsWhiteSpace(deviceLine[start])) { start++; }
                                if (start < deviceLine.Length) { result.DeviceName = NormalizePciIdsDisplayText(deviceLine.Substring(start)); }
                            }
                        }
                        else { currentDevice = String.Empty; }
                    }
                }
                if (!String.IsNullOrWhiteSpace(result.VendorName) && !String.IsNullOrWhiteSpace(result.DeviceName) && (String.IsNullOrWhiteSpace(identity.SubVendorId) || !String.IsNullOrWhiteSpace(result.SubVendorName)) && (String.IsNullOrWhiteSpace(identity.SubVendorId) || String.IsNullOrWhiteSpace(identity.SubDeviceId) || !String.IsNullOrWhiteSpace(result.SubsystemName))) { break; }
            }
            result.Available = true;
        }
        catch { result.Available = false; }
        return result;
    }

    private static string MergePciResolvedName(string vendorName, string deviceName, string windowsName, bool preferSubsystem)
    {
        string win = CleanPlainDeviceText(windowsName);
        string vendor = GetPreferredVendorName(vendorName, win);
        string device = NormalizePciIdsDisplayText(deviceName);
        if (preferSubsystem)
        {
            if (String.IsNullOrWhiteSpace(device)) { return win; }
            if (!String.IsNullOrWhiteSpace(vendor) && device.IndexOf(vendor, StringComparison.OrdinalIgnoreCase) < 0)
            {
                string first = FirstToken(vendor);
                if (!String.IsNullOrWhiteSpace(first) && device.IndexOf(first, StringComparison.OrdinalIgnoreCase) < 0) { return JoinDisplayNameParts(new string[] { vendor, device }); }
            }
            return device;
        }
        if (String.IsNullOrWhiteSpace(vendor) && String.IsNullOrWhiteSpace(device)) { return win; }
        string winWithoutVendor = RemoveLeadingVendorFromName(win, vendor);
        string identifierPrefix = GetDistinctIdentifierPrefix(device, winWithoutVendor);
        if (!String.IsNullOrWhiteSpace(winWithoutVendor)) { return JoinDisplayNameParts(new string[] { vendor, identifierPrefix, winWithoutVendor }); }
        return JoinDisplayNameParts(new string[] { vendor, device });
    }

    private static string CleanPlainDeviceText(string text)
    {
        string value = text == null ? String.Empty : text.Trim().Trim('"').Trim('\'');
        if (String.IsNullOrWhiteSpace(value) || String.Equals(value, "Not Found", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
        Match m = Regex.Match(value, @"(?i)^@?[^,;'""`|\r\n]+?\.inf\s*,\s*[^;'""`|\r\n]*\s*;\s*(?<desc>.+)$");
        if (m.Success) { value = m.Groups["desc"].Value.Trim().Trim('"').Trim('\''); }
        else if (value.IndexOf(';') >= 0)
        {
            string[] parts = value.Split(';');
            value = parts[parts.Length - 1].Trim();
        }
        value = Regex.Replace(value, @"^""|""$", String.Empty);
        value = Regex.Replace(value, @"\s+", " ");
        return value.Trim();
    }

    private static string NormalizePciIdsDisplayText(string text)
    {
        string value = CleanPlainDeviceText(text);
        if (String.IsNullOrWhiteSpace(value)) { return String.Empty; }
        value = Regex.Replace(value, @"\s*\[[^\]]*\]\s*$", String.Empty);
        value = Regex.Replace(value, @"\s*,?\s*(Corporation|Corp\.?|Incorporated|Inc\.?|Company|Co\.?,?\s*Ltd\.?|Co\.?,?\s*Limited|Ltd\.?|Limited|GmbH|S\.A\.|S\.p\.A\.|AG|KG|LLC|PLC)\s*$", String.Empty, RegexOptions.IgnoreCase);
        value = Regex.Replace(value, @"\s+", " ");
        return value.Trim(" \t\r\n,.-".ToCharArray());
    }

    private static string GetPreferredVendorName(string vendorName, string windowsName)
    {
        string vendor = NormalizePciIdsDisplayText(vendorName);
        string win = CleanPlainDeviceText(windowsName);
        if (String.IsNullOrWhiteSpace(vendor) || String.IsNullOrWhiteSpace(win)) { return vendor; }
        string first = FirstToken(vendor);
        if (String.IsNullOrWhiteSpace(first)) { return vendor; }
        Match m = Regex.Match(win, @"^(\S+)");
        if (m.Success && String.Equals(m.Groups[1].Value, first, StringComparison.OrdinalIgnoreCase)) { return m.Groups[1].Value + vendor.Substring(first.Length); }
        return vendor;
    }

    private static string RemoveLeadingVendorFromName(string name, string vendorName)
    {
        string nameText = CleanPlainDeviceText(name);
        string vendorText = NormalizePciIdsDisplayText(vendorName);
        if (String.IsNullOrWhiteSpace(nameText) || String.IsNullOrWhiteSpace(vendorText)) { return nameText; }
        List<string> candidates = new List<string>();
        candidates.Add(vendorText);
        string first = FirstToken(vendorText);
        if (!String.IsNullOrWhiteSpace(first)) { candidates.Add(first); }
        for (int i = 0; i < candidates.Count; i++)
        {
            string candidate = candidates[i];
            if (String.IsNullOrWhiteSpace(candidate)) { continue; }
            string pattern = "^" + Regex.Escape(candidate) + @"(\s+|[-:]+\s*)";
            string updated = Regex.Replace(nameText, pattern, String.Empty, RegexOptions.IgnoreCase).Trim();
            if (!String.Equals(updated, nameText, StringComparison.Ordinal)) { return updated; }
        }
        return nameText;
    }

    private static string GetDistinctIdentifierPrefix(string deviceName, string referenceName)
    {
        string deviceText = NormalizePciIdsDisplayText(deviceName);
        string referenceText = CleanPlainDeviceText(referenceName);
        if (String.IsNullOrWhiteSpace(deviceText)) { return String.Empty; }
        string[] tokens = Regex.Split(deviceText, @"[\s\[\]\(\),;/]+");
        for (int i = 0; i < tokens.Length; i++)
        {
            string token = tokens[i] == null ? String.Empty : tokens[i].Trim().Trim(" \t\r\n.,;:-_".ToCharArray());
            if (token.Length < 2) { continue; }
            if (!Regex.IsMatch(token, @"[A-Za-z]") || !Regex.IsMatch(token, @"[0-9]")) { continue; }
            if (!String.IsNullOrWhiteSpace(referenceText) && referenceText.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0) { continue; }
            return token;
        }
        return String.Empty;
    }

    private static string JoinDisplayNameParts(string[] parts)
    {
        List<string> result = new List<string>();
        if (parts != null)
        {
            for (int i = 0; i < parts.Length; i++)
            {
                string text = CleanPlainDeviceText(parts[i]);
                if (String.IsNullOrWhiteSpace(text)) { continue; }
                bool exists = false;
                for (int e = 0; e < result.Count; e++) { if (String.Equals(result[e], text, StringComparison.OrdinalIgnoreCase)) { exists = true; break; } }
                if (!exists) { result.Add(text); }
            }
        }
        return Regex.Replace(String.Join(" ", result.ToArray()), @"\s+", " ").Trim();
    }

    private static string FirstToken(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
        Match m = Regex.Match(text.Trim(), @"^(\S+)");
        return m.Success ? m.Groups[1].Value : String.Empty;
    }

    private static string NewTypedDisplayName(string baseText, string model)
    {
        string b = CleanText(baseText);
        string m = FormatModelName(model);
        if (String.IsNullOrWhiteSpace(b)) { return m; }
        if (String.IsNullOrWhiteSpace(m)) { return b; }
        if (b.IndexOf(m, StringComparison.OrdinalIgnoreCase) >= 0) { return b; }
        return b + " - " + m;
    }

    private static bool IsHdAudioOnlyTypes(string[] roles)
    {
        if (roles == null || roles.Length != 1) { return false; }
        string role = roles[0] == null ? String.Empty : roles[0].Trim();
        return String.Equals(role, "HD Audio", StringComparison.OrdinalIgnoreCase);
    }

    private static string NewAudioControllerDisplayName(string[] roles, string model)
    {
        string[] roleList = SortedUnique(roles);
        string baseText = roleList.Length > 0 ? "Audio controller (" + String.Join("/", roleList) + ")" : "Audio controller";
        string modelText = FormatModelName(model);
        if (String.IsNullOrWhiteSpace(modelText)) { return baseText; }
        if (baseText.IndexOf(modelText, StringComparison.OrdinalIgnoreCase) >= 0) { return baseText; }
        return baseText + " - " + modelText;
    }

    private static string FormatModelName(string model)
    {
        string text = model == null ? String.Empty : model.Trim();
        if (String.IsNullOrWhiteSpace(text) || String.Equals(text, "Not Found", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
        if (text.IndexOf(';') >= 0)
        {
            string[] parts = text.Split(';');
            text = parts[parts.Length - 1].Trim();
        }
        text = Regex.Replace(text, @"^""|""$", String.Empty);
        text = Regex.Replace(text, @"\s+", " ");
        return text.Trim();
    }

    private static HashSet<string> BuildStringSet(string[] values)
    {
        HashSet<string> set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (values == null) { return set; }
        for (int i = 0; i < values.Length; i++)
        {
            if (!String.IsNullOrWhiteSpace(values[i])) { set.Add(values[i].Trim()); }
        }
        return set;
    }

    private static string[] SortedUnique(IEnumerable<string> values)
    {
        SortedSet<string> set = new SortedSet<string>(StringComparer.OrdinalIgnoreCase);
        if (values != null)
        {
            foreach (string value in values)
            {
                if (!String.IsNullOrWhiteSpace(value)) { set.Add(value.Trim()); }
            }
        }
        string[] result = new string[set.Count];
        set.CopyTo(result);
        return result;
    }

    private static string[] ToArray(SortedSet<string> set)
    {
        if (set == null || set.Count == 0) { return new string[0]; }
        string[] result = new string[set.Count];
        set.CopyTo(result);
        return result;
    }

    private static string FirstNonEmpty(params string[] values)
    {
        if (values == null) { return String.Empty; }
        for (int i = 0; i < values.Length; i++) { if (!String.IsNullOrWhiteSpace(values[i])) { return values[i]; } }
        return String.Empty;
    }

    private static string CleanText(string value)
    {
        return value == null ? String.Empty : value.Trim();
    }

    private static string SafeText(string value)
    {
        return value == null ? String.Empty : value;
    }

