    {
        public string ClassName;
        public string Service;
    }

    private sealed class NativeHidClassification
    {
        public string Type;
        public string Reason;
    }

    private sealed class NativeHidWheelProbe
    {
        public bool Ok;
        public bool Wheel;
        public bool MouseTopLevel;
        public bool RelativeX;
        public bool RelativeY;
        public bool ButtonPage;
        public string Detail;
        public string Error;
    }
    private const uint NativeHidFileShareRead = 0x00000001;
    private const uint NativeHidFileShareWrite = 0x00000002;
    private const uint NativeHidOpenExisting = 3;
    private static readonly IntPtr NativeHidInvalidHandleValue = new IntPtr(-1);

    private sealed class NativeAudioIdentity
    {
        public string Name;
        public string Normalized;
        public string UsbVidPid;
        public string ControllerID;
        public string InstanceId;
        public string Source;
    }

    private static string HidHardwareLookupKey(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        string text = instanceId.Trim().Replace("#", "\\").ToUpperInvariant();
        string[] segments = text.Split(new char[] { '\\' }, StringSplitOptions.RemoveEmptyEntries);
        if (segments.Length >= 2)
        {
            string first = segments[0];
            if (String.Equals(first, "HID", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(first, "USB", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(first, "BTHENUM", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(first, "KEYBOARD", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(first, "MOUSE", StringComparison.OrdinalIgnoreCase))
            {
                return segments[1].Trim().ToUpperInvariant();
            }
        }
        return segments.Length > 0 ? segments[0].Trim().ToUpperInvariant() : text;
    }

    private static string LegacyHidAssociationFallbackKey(string key)
    {
        if (String.IsNullOrWhiteSpace(key)) { return String.Empty; }
        string s = Regex.Replace(key.Trim().ToUpperInvariant(), @"(?i)&(MI|COL)_[0-9A-Fa-f]+", String.Empty).TrimEnd('&');
        return s;
    }

    private static string CompositeHidAssociationFallbackKey(string key)
    {
        if (String.IsNullOrWhiteSpace(key)) { return String.Empty; }
        string s = Regex.Replace(key.Trim().ToUpperInvariant(), @"(?i)&(?:MI_[0-9A-F]{2}|COL[0-9A-F]{2}|COL_[0-9A-F]{2})", String.Empty).TrimEnd('&');
        return s;
    }

    private static string NormalizeCrossClassDeviceName(string value)
    {
        if (String.IsNullOrWhiteSpace(value)) { return String.Empty; }
        string trimmed = value.Trim();
        if (String.Equals(trimmed, "<none>", StringComparison.OrdinalIgnoreCase) || String.Equals(trimmed, "none", StringComparison.OrdinalIgnoreCase)) { return String.Empty; }
        string normalized = Regex.Replace(trimmed.ToLowerInvariant(), "[^a-z0-9]+", String.Empty);
        return normalized.Length >= 4 ? normalized : String.Empty;
    }

    private static void AddHidIdentityString(List<string> idList, string value)
    {
        if (idList == null || String.IsNullOrWhiteSpace(value)) { return; }
        idList.Add(value.Trim().ToUpperInvariant());
    }

    private static void AddHidIdentityStrings(List<string> idList, string[] values)
    {
        if (values == null) { return; }
        for (int i = 0; i < values.Length; i++) { AddHidIdentityString(idList, values[i]); }
    }

    private static string InferNativeHidTypeFromIds(List<string> idList, string className)
    {
        if (idList != null)
        {
            for (int i = 0; i < idList.Count; i++)
            {
                string id = idList[i];
                if (String.Equals(id, "HID_DEVICE_SYSTEM_KEYBOARD", StringComparison.OrdinalIgnoreCase) ||
                    String.Equals(id, "HID_DEVICE_UP:0001_U:0006", StringComparison.OrdinalIgnoreCase) ||
                    String.Equals(id, "HID_DEVICE_UP:0001_U:0007", StringComparison.OrdinalIgnoreCase))
                {
                    return "Keyboard";
                }
                if (String.Equals(id, "HID_DEVICE_SYSTEM_MOUSE", StringComparison.OrdinalIgnoreCase) ||
                    String.Equals(id, "HID_DEVICE_UP:0001_U:0002", StringComparison.OrdinalIgnoreCase))
                {
                    return "Mouse";
                }
            }
        }
        if (String.Equals(className, "Keyboard", StringComparison.OrdinalIgnoreCase)) { return "Keyboard"; }
        if (String.Equals(className, "Mouse", StringComparison.OrdinalIgnoreCase)) { return "Mouse"; }
        return String.Empty;
    }

    private static List<DeviceNode> GetUniqueDeviceNodes(DeviceDiscoveryModel model)
    {
        List<DeviceNode> nodes = new List<DeviceNode>();
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (model == null) { return nodes; }
        if (model.TopologySnapshot != null && model.TopologySnapshot.DeviceNodes != null)
        {
            for (int i = 0; i < model.TopologySnapshot.DeviceNodes.Count; i++)
            {
                DeviceNode node = model.TopologySnapshot.DeviceNodes[i];
                if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
                if (seen.Add(node.InstanceId)) { nodes.Add(node); }
            }
        }
        if (model.DevicesByInstanceId != null)
        {
            foreach (KeyValuePair<string, DeviceNode> kv in model.DevicesByInstanceId)
            {
                DeviceNode node = kv.Value;
                if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
                if (seen.Add(node.InstanceId)) { nodes.Add(node); }
            }
        }
        return nodes;
    }

    private static void BuildNativeHidTypeMaps(DeviceDiscoveryModel model, Dictionary<string, NativeHidClassEntry> hidClassLookup, Dictionary<string, string> typeLookup)
    {
        if (hidClassLookup == null || typeLookup == null) { return; }
        List<DeviceNode> nodes = GetUniqueDeviceNodes(model);
        for (int i = 0; i < nodes.Count; i++)
        {
            DeviceNode node = nodes[i];
            if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
            string key = HidHardwareLookupKey(node.InstanceId);
            if (String.IsNullOrWhiteSpace(key)) { continue; }
            if (String.Equals(node.ClassName, "HIDClass", StringComparison.OrdinalIgnoreCase) && !hidClassLookup.ContainsKey(key))
            {
                NativeHidClassEntry entry = new NativeHidClassEntry();
                entry.ClassName = "HIDClass";
                entry.Service = node.Service;
                hidClassLookup[key] = entry;
            }
        }
        for (int i = 0; i < nodes.Count; i++)
        {
            DeviceNode node = nodes[i];
            if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
            if (!String.Equals(node.ClassName, "Keyboard", StringComparison.OrdinalIgnoreCase) &&
                !String.Equals(node.ClassName, "Mouse", StringComparison.OrdinalIgnoreCase) &&
                !String.Equals(node.ClassName, "HIDClass", StringComparison.OrdinalIgnoreCase))
            {
                continue;
            }
            string key = HidHardwareLookupKey(node.InstanceId);
            if (String.IsNullOrWhiteSpace(key) || typeLookup.ContainsKey(key)) { continue; }
            List<string> ids = new List<string>();
            AddHidIdentityStrings(ids, node.HardwareIds);
            AddHidIdentityStrings(ids, node.CompatibleIds);
            string type = InferNativeHidTypeFromIds(ids, node.ClassName);
            if (!String.IsNullOrWhiteSpace(type)) { typeLookup[key] = type; }
        }
    }

    private static NativeHidClassification ClassifyNativeHidDevice(Dictionary<string, NativeHidClassEntry> hidClassLookup, Dictionary<string, string> typeLookup, string instanceId)
    {
        NativeHidClassification result = new NativeHidClassification();
        string key = HidHardwareLookupKey(instanceId);
        string typedAs = null;
        if (!String.IsNullOrWhiteSpace(key) && typeLookup != null) { typeLookup.TryGetValue(key, out typedAs); }
        NativeHidClassEntry hidEntry = null;
        if (!String.IsNullOrWhiteSpace(key) && hidClassLookup != null) { hidClassLookup.TryGetValue(key, out hidEntry); }
        bool hidClass = hidEntry != null && String.Equals(hidEntry.ClassName, "HIDClass", StringComparison.OrdinalIgnoreCase);
        string svcName = (hidEntry != null && !String.IsNullOrWhiteSpace(hidEntry.Service)) ? hidEntry.Service : "<none>";

        if (String.Equals(typedAs, "Mouse", StringComparison.OrdinalIgnoreCase))
        {
            if (hidClass) { result.Type = "Mouse"; result.Reason = "Type=Mouse + HIDClass(Service=" + svcName + ")"; }
            else { result.Type = String.Empty; result.Reason = "Type=Mouse but HIDClass check failed (Class=miss, Service=" + svcName + ")"; }
            return result;
        }
        if (String.Equals(typedAs, "Keyboard", StringComparison.OrdinalIgnoreCase))
        {
            if (hidClass) { result.Type = "Keyboard"; result.Reason = "Type=Keyboard + HIDClass(Service=" + svcName + ")"; }
            else { result.Type = String.Empty; result.Reason = "Type=Keyboard but HIDClass check failed (Class=miss, Service=" + svcName + ")"; }
            return result;
        }
        result.Type = String.Empty;
        result.Reason = "Type lookup did not classify as Mouse/Keyboard";
        return result;
    }

    private static bool IsMi03MouseAudioOverride(string hwId, string deviceType, string reason)
    {
        if (!String.Equals(deviceType, "Mouse", StringComparison.OrdinalIgnoreCase)) { return false; }
        if (String.IsNullOrWhiteSpace(hwId)) { return false; }
        if (!Regex.IsMatch(hwId, @"(?i)(?:^|&)MI_03(?:&|$)")) { return false; }
        if (String.IsNullOrWhiteSpace(reason) || !Regex.IsMatch(reason, @"(?i)Type=Mouse\s*\+\s*HIDClass\(Service=")) { return false; }
        return true;
    }

    private static List<HidInterfaceInfo> GetNativeHidInterfaceRows(DeviceDiscoveryModel model)
    {
        List<HidInterfaceInfo> rows = new List<HidInterfaceInfo>();
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (model != null && model.HidInterfaces != null)
        {
            foreach (KeyValuePair<string, HidInterfaceInfo> kv in model.HidInterfaces)
            {
                HidInterfaceInfo hid = kv.Value;
                if (hid == null) { continue; }
                string instance = FirstNonEmpty(hid.Instance, kv.Key);
                string key = FirstNonEmpty(instance, hid.DevicePath, hid.Product);
                if (String.IsNullOrWhiteSpace(key) || !seen.Add(key)) { continue; }
                HidInterfaceInfo row = new HidInterfaceInfo();
                row.Product = FirstNonEmpty(hid.Product, "<none>");
                row.DevicePath = hid.DevicePath;
                row.Instance = instance;
                rows.Add(row);
            }
        }
        return rows;
    }

    private static void AddNativeAudioIdentity(List<NativeAudioIdentity> identities, HashSet<string> seen, string name, string source, string usbVidPid, string controllerId, string instanceId)
    {
        if (identities == null || seen == null) { return; }
        string normalized = NormalizeCrossClassDeviceName(name);
        string vidPid = !String.IsNullOrWhiteSpace(usbVidPid) ? usbVidPid.Trim().ToUpperInvariant() : ExtractVidPidPair(instanceId);
        if (String.IsNullOrWhiteSpace(normalized) && String.IsNullOrWhiteSpace(vidPid)) { return; }
        string key = (String.IsNullOrWhiteSpace(normalized) ? "<noname>" : normalized) + "|" + (String.IsNullOrWhiteSpace(vidPid) ? "<novidpid>" : vidPid) + "|" + source + "|" + (String.IsNullOrWhiteSpace(controllerId) ? "<noctrl>" : controllerId);
        if (!seen.Add(key)) { return; }
        NativeAudioIdentity id = new NativeAudioIdentity();
        id.Name = name;
        id.Normalized = normalized;
        id.UsbVidPid = vidPid;
        id.ControllerID = controllerId;
        id.InstanceId = instanceId;
        id.Source = source;
        identities.Add(id);
    }

    private static List<NativeAudioIdentity> BuildNativeAudioIdentities(DeviceDiscoveryModel model, List<AudioEndpointInfo> audioRows)
    {
        List<NativeAudioIdentity> identities = new List<NativeAudioIdentity>();
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (audioRows != null)
        {
            for (int i = 0; i < audioRows.Count; i++)
            {
                AudioEndpointInfo row = audioRows[i];
                if (row == null) { continue; }
                AddNativeAudioIdentity(identities, seen, row.AudioDevice, "AudioEndpoint", row.UsbVidPid, row.ControllerID, row.InstanceId);
            }
        }
        if (model != null && model.AudioEndpoints != null)
        {
            foreach (KeyValuePair<string, DeviceNode> kv in model.AudioEndpoints)
            {
                DeviceNode node = kv.Value;
                if (node == null || !node.IsPresent) { continue; }
                string endpointId = FirstNonEmpty(node.InstanceId, kv.Key);
                string endpointName = FirstNonEmpty(node.FriendlyName, node.DeviceDesc, endpointId);
                AddNativeAudioIdentity(identities, seen, endpointName, "PnPDevice", null, null, endpointId);
            }
        }
        return identities;
    }

    private static NativeAudioIdentity FindNativeAudioMatch(List<NativeAudioIdentity> identities, string product, string instanceId)
    {
        string productNorm = NormalizeCrossClassDeviceName(product);
        string hidVidPid = ExtractVidPidPair(instanceId);
        if (String.IsNullOrWhiteSpace(productNorm) && String.IsNullOrWhiteSpace(hidVidPid)) { return null; }
        if (!String.IsNullOrWhiteSpace(hidVidPid) && identities != null)
        {
            for (int i = 0; i < identities.Count; i++)
            {
                NativeAudioIdentity id = identities[i];
                if (id != null && !String.IsNullOrWhiteSpace(id.UsbVidPid) && String.Equals(id.UsbVidPid, hidVidPid, StringComparison.OrdinalIgnoreCase)) { return id; }
            }
        }
        if (!String.IsNullOrWhiteSpace(productNorm) && identities != null)
        {
            for (int i = 0; i < identities.Count; i++)
            {
                NativeAudioIdentity id = identities[i];
                if (id == null || String.IsNullOrWhiteSpace(id.Normalized)) { continue; }
                if (String.Equals(id.Normalized, productNorm, StringComparison.OrdinalIgnoreCase) || id.Normalized.IndexOf(productNorm, StringComparison.OrdinalIgnoreCase) >= 0 || productNorm.IndexOf(id.Normalized, StringComparison.OrdinalIgnoreCase) >= 0) { return id; }
            }
        }
        return null;
    }

    private static bool TryAddControllerId(List<string> list, string controllerId)
    {
        if (list == null || String.IsNullOrWhiteSpace(controllerId)) { return false; }
        for (int i = 0; i < list.Count; i++) { if (String.Equals(list[i], controllerId, StringComparison.OrdinalIgnoreCase)) { return false; } }
        list.Add(controllerId);
        return true;
    }

    private static List<string> FindControllersForNativeHid(DeviceDiscoveryModel model, string instanceId)
    {
        List<string> controllers = new List<string>();
        if (model == null || String.IsNullOrWhiteSpace(instanceId)) { return controllers; }
        string key = HidHardwareLookupKey(instanceId);
        string legacyBase = LegacyHidAssociationFallbackKey(key);
        string compositeBase = CompositeHidAssociationFallbackKey(key);
        List<UsbControllerAssociationRecord> pairs = model.UsbControllerAssociationList;
        if ((pairs == null || pairs.Count == 0) && model.TopologySnapshot != null) { pairs = model.TopologySnapshot.ControllerAssociations; }
        if (pairs != null)
        {
            for (int i = 0; i < pairs.Count; i++)
            {
                UsbControllerAssociationRecord pair = pairs[i];
                if (pair == null || String.IsNullOrWhiteSpace(pair.CtrlId) || String.IsNullOrWhiteSpace(pair.DevId)) { continue; }
                string devKey = HidHardwareLookupKey(pair.DevId);
                if (String.IsNullOrWhiteSpace(devKey)) { continue; }
                bool match = String.Equals(devKey, key, StringComparison.OrdinalIgnoreCase);
                if (!match && !String.IsNullOrWhiteSpace(legacyBase)) { match = String.Equals(devKey, legacyBase, StringComparison.OrdinalIgnoreCase); }
                if (!match && !String.IsNullOrWhiteSpace(compositeBase)) { match = String.Equals(devKey, compositeBase, StringComparison.OrdinalIgnoreCase); }
                if (!match && devKey.IndexOf(key, StringComparison.OrdinalIgnoreCase) >= 0) { match = true; }
                string devVidPidKey = DeviceTweakerPathHelpers.ExtractUsbVidPidKey(devKey);
                if (!match && !String.IsNullOrWhiteSpace(compositeBase) && !String.IsNullOrWhiteSpace(devVidPidKey) && key.IndexOf(devKey, StringComparison.OrdinalIgnoreCase) >= 0 && compositeBase.IndexOf(devVidPidKey, StringComparison.OrdinalIgnoreCase) >= 0) { match = true; }
                if (match) { TryAddControllerId(controllers, pair.CtrlId); }
            }
        }
        if (controllers.Count == 0)
        {
            string controller = FindControllerForDevice(model, instanceId);
            if (!String.IsNullOrWhiteSpace(controller)) { TryAddControllerId(controllers, controller); }
        }
        return controllers;
    }

    private static bool SameProductLowerInterfaceHasHidClassRole(List<HidInterfaceInfo> hidRows, Dictionary<string, NativeHidClassEntry> hidClassLookup, Dictionary<string, string> typeLookup, string product, string instanceId)
    {
        if (String.IsNullOrWhiteSpace(product) || String.Equals(product, "<none>", StringComparison.OrdinalIgnoreCase) || String.IsNullOrWhiteSpace(instanceId)) { return false; }
        int currentMi = DeviceTweakerPathHelpers.ExtractUsbMiNumber(instanceId);
        if (currentMi != 3) { return false; }
        if (hidRows == null) { return false; }
        for (int i = 0; i < hidRows.Count; i++)
        {
            HidInterfaceInfo candidate = hidRows[i];
            if (candidate == null || String.IsNullOrWhiteSpace(candidate.Instance)) { continue; }
            if (String.Equals(candidate.Instance, instanceId, StringComparison.OrdinalIgnoreCase)) { continue; }
            if (!String.Equals(candidate.Product, product, StringComparison.OrdinalIgnoreCase)) { continue; }
            int candidateMi = DeviceTweakerPathHelpers.ExtractUsbMiNumber(candidate.Instance);
            if (candidateMi < 0 || candidateMi >= currentMi) { continue; }
            NativeHidClassification cls = ClassifyNativeHidDevice(hidClassLookup, typeLookup, candidate.Instance);
            if (cls == null || (!String.Equals(cls.Type, "Mouse", StringComparison.OrdinalIgnoreCase) && !String.Equals(cls.Type, "Keyboard", StringComparison.OrdinalIgnoreCase))) { continue; }
            if (Regex.IsMatch(cls.Reason ?? String.Empty, @"(?i)Type=(?:Mouse|Keyboard)\s*\+\s*HIDClass\(Service=")) { return true; }
        }
        return false;
    }

    private static UsbHidDeviceInfo CreateNativeHidRow(string product, string instanceId, string devicePath, string deviceType, string reason, List<string> controllers)
    {
        UsbHidDeviceInfo row = new UsbHidDeviceInfo();
        row.ProductString = FirstNonEmpty(product, "<none>");
        row.DeviceInstanceID = instanceId;
        row.DevicePath = devicePath;
        row.DeviceType = String.IsNullOrWhiteSpace(deviceType) ? null : deviceType;
        row.ClassificationReason = reason;
        if (controllers != null)
        {
            for (int i = 0; i < controllers.Count; i++)
            {
                if (!String.IsNullOrWhiteSpace(controllers[i])) { row.USBControllerPNPIDs.Add(controllers[i]); }
            }
        }
        return row;
    }

    private static bool IsHidClassMouseKeyboardClassification(UsbHidDeviceInfo row, string expectedType)
    {
        if (row == null || !String.Equals(row.DeviceType, expectedType, StringComparison.OrdinalIgnoreCase)) { return false; }
        if (!String.Equals(expectedType, "Mouse", StringComparison.OrdinalIgnoreCase) && !String.Equals(expectedType, "Keyboard", StringComparison.OrdinalIgnoreCase)) { return false; }
        string pattern = "Type=" + Regex.Escape(expectedType) + @"\s*\+\s*HIDClass\(Service=";
        return Regex.IsMatch(row.ClassificationReason ?? String.Empty, pattern, RegexOptions.IgnoreCase);
    }

    private static string FormatLastWin32Error(string api)
    {
        int code = Marshal.GetLastWin32Error();
        string message = String.Empty;
        try { message = new Win32Exception(code).Message; } catch { }
        if (String.IsNullOrWhiteSpace(message)) { message = "unknown Win32 error"; }
        return api + " failed: Win32=" + code.ToString(System.Globalization.CultureInfo.InvariantCulture) + " (" + message + ")";
    }

    private static bool NativeHidValueCapContains(HidInterop.HIDP_VALUE_CAPS cap, int usagePage, int usage, bool relativeOnly)
    {
        if (cap.UsagePage != usagePage) { return false; }
        if (relativeOnly && cap.IsAbsolute) { return false; }
        int min = cap.UsageMin;
        int max = cap.IsRange ? cap.UsageMax : min;
        return usage >= min && usage <= max;
    }

    private static bool NativeHidButtonUsagePage(HidInterop.HIDP_BUTTON_CAPS[] caps, int usagePage)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (caps[i].UsagePage == usagePage) { return true; } }
        return false;
    }

    private static bool NativeHidValueUsage(HidInterop.HIDP_VALUE_CAPS[] caps, int usagePage, int usage, bool relativeOnly)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (NativeHidValueCapContains(caps[i], usagePage, usage, relativeOnly)) { return true; } }
        return false;
    }

    private static HidInterop.HIDP_BUTTON_CAPS[] GetNativeHidButtonCaps(IntPtr preparsed, HidInterop.HIDP_REPORT_TYPE reportType, int count)
    {
        if (preparsed == IntPtr.Zero || count <= 0) { return new HidInterop.HIDP_BUTTON_CAPS[0]; }
        HidInterop.HIDP_BUTTON_CAPS[] caps = new HidInterop.HIDP_BUTTON_CAPS[count];
        ushort len = (ushort)count;
        int status = HidInterop.HidP_GetButtonCaps(reportType, caps, ref len, preparsed);
        if (status != HidInterop.HIDP_STATUS_SUCCESS) { return new HidInterop.HIDP_BUTTON_CAPS[0]; }
        if (len == caps.Length) { return caps; }
        HidInterop.HIDP_BUTTON_CAPS[] trimmed = new HidInterop.HIDP_BUTTON_CAPS[len];
        Array.Copy(caps, trimmed, len);
        return trimmed;
    }

    private static HidInterop.HIDP_VALUE_CAPS[] GetNativeHidValueCaps(IntPtr preparsed, HidInterop.HIDP_REPORT_TYPE reportType, int count)
    {
        if (preparsed == IntPtr.Zero || count <= 0) { return new HidInterop.HIDP_VALUE_CAPS[0]; }
        HidInterop.HIDP_VALUE_CAPS[] caps = new HidInterop.HIDP_VALUE_CAPS[count];
        ushort len = (ushort)count;
        int status = HidInterop.HidP_GetValueCaps(reportType, caps, ref len, preparsed);
        if (status != HidInterop.HIDP_STATUS_SUCCESS) { return new HidInterop.HIDP_VALUE_CAPS[0]; }
        if (len == caps.Length) { return caps; }
        HidInterop.HIDP_VALUE_CAPS[] trimmed = new HidInterop.HIDP_VALUE_CAPS[len];
        Array.Copy(caps, trimmed, len);
        return trimmed;
    }

    private static NativeHidWheelProbe ProbeNativeHidWheelEvidence(string devicePath)
    {
        NativeHidWheelProbe result = new NativeHidWheelProbe();
        if (String.IsNullOrWhiteSpace(devicePath)) { result.Error = "empty HID device path"; return result; }
        IntPtr handle = IntPtr.Zero;
        IntPtr preparsed = IntPtr.Zero;
        try
        {
            handle = HidInterop.CreateFile(devicePath, 0, NativeHidFileShareRead | NativeHidFileShareWrite, IntPtr.Zero, NativeHidOpenExisting, 0, IntPtr.Zero);
            if (handle == IntPtr.Zero || handle == NativeHidInvalidHandleValue) { result.Error = FormatLastWin32Error("CreateFile"); return result; }
            if (!HidInterop.HidD_GetPreparsedData(handle, out preparsed)) { result.Error = FormatLastWin32Error("HidD_GetPreparsedData"); return result; }
            HidInterop.HIDP_CAPS caps = new HidInterop.HIDP_CAPS();
            int capStatus = HidInterop.HidP_GetCaps(preparsed, ref caps);
            if (capStatus != HidInterop.HIDP_STATUS_SUCCESS) { result.Error = "HidP_GetCaps failed: status=" + capStatus.ToString(System.Globalization.CultureInfo.InvariantCulture); return result; }
            HidInterop.HIDP_VALUE_CAPS[] inputValues = GetNativeHidValueCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Input, caps.NumberInputValueCaps);
            HidInterop.HIDP_BUTTON_CAPS[] inputButtons = GetNativeHidButtonCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Input, caps.NumberInputButtonCaps);
            result.MouseTopLevel = caps.UsagePage == 0x01 && caps.Usage == 0x02;
            result.RelativeX = NativeHidValueUsage(inputValues, 0x01, 0x30, true);
            result.RelativeY = NativeHidValueUsage(inputValues, 0x01, 0x31, true);
            result.ButtonPage = NativeHidButtonUsagePage(inputButtons, 0x09);
            result.Wheel = NativeHidValueUsage(inputValues, 0x01, 0x38, true);
            result.Ok = true;
            result.Detail = "TLC=UP=0x" + caps.UsagePage.ToString("X4") + "/U=0x" + caps.Usage.ToString("X4") + "; Wheel=" + result.Wheel.ToString() + "; RelX=" + result.RelativeX.ToString() + "; RelY=" + result.RelativeY.ToString() + "; Buttons=" + result.ButtonPage.ToString() + "; InputValueCaps=" + inputValues.Length.ToString(System.Globalization.CultureInfo.InvariantCulture) + "; InputButtonCaps=" + inputButtons.Length.ToString(System.Globalization.CultureInfo.InvariantCulture);
            return result;
        }
        catch (Exception ex)
        {
            result.Error = ex.GetType().FullName + ": " + ex.Message;
            return result;
        }
        finally
        {
            if (preparsed != IntPtr.Zero) { try { HidInterop.HidD_FreePreparsedData(preparsed); } catch { } }
            if (handle != IntPtr.Zero && handle != NativeHidInvalidHandleValue) { try { HidInterop.CloseHandle(handle); } catch { } }
        }
    }

    private static bool HasNativeMouseRow(List<UsbHidDeviceInfo> rows)
    {
        if (rows == null) { return false; }
        for (int i = 0; i < rows.Count; i++)
        {
            UsbHidDeviceInfo row = rows[i];
            if (row != null && String.Equals(row.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase)) { return true; }
        }
        return false;
    }

    private static HashSet<string> BuildNativeKeyboardProductSet(List<UsbHidDeviceInfo> rows)
    {
        HashSet<string> products = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (rows == null) { return products; }
        for (int i = 0; i < rows.Count; i++)
        {
            UsbHidDeviceInfo row = rows[i];
            if (row == null || !String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase)) { continue; }
            string product = row.ProductString == null ? String.Empty : row.ProductString.Trim();
            if (!String.IsNullOrWhiteSpace(product) && !String.Equals(product, "<none>", StringComparison.OrdinalIgnoreCase)) { products.Add(product); }
        }
        return products;
    }

    private static bool NativeHidWheelFallbackSuppressed(UsbHidDeviceInfo row)
    {
        if (row == null) { return true; }
        if (!String.IsNullOrWhiteSpace(row.DeviceType)) { return true; }
        string reason = row.ClassificationReason ?? String.Empty;
        if (reason.IndexOf("blocked from Mouse/Keyboard classification because audio endpoints take precedence", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        if (reason.IndexOf("explicitly excluded from HID classification", StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        return false;
    }

    private static void AppendNativeHidClassificationReason(UsbHidDeviceInfo row, string addition)
    {
        if (row == null || String.IsNullOrWhiteSpace(addition)) { return; }
        if (String.IsNullOrWhiteSpace(row.ClassificationReason)) { row.ClassificationReason = addition; return; }
        if (row.ClassificationReason.IndexOf(addition, StringComparison.OrdinalIgnoreCase) >= 0) { return; }
        row.ClassificationReason = row.ClassificationReason + "; " + addition;
    }

    private static void ApplyNativeHidWheelMouseFallback(List<UsbHidDeviceInfo> rows)
    {
        if (rows == null || rows.Count == 0) { return; }
        if (HasNativeMouseRow(rows)) { return; }
        HashSet<string> keyboardProducts = BuildNativeKeyboardProductSet(rows);
        for (int i = 0; i < rows.Count; i++)
        {
            UsbHidDeviceInfo row = rows[i];
            if (row == null) { continue; }
            if (NativeHidWheelFallbackSuppressed(row)) { continue; }
            string product = row.ProductString == null ? String.Empty : row.ProductString.Trim();
            if (!String.IsNullOrWhiteSpace(product) && keyboardProducts.Contains(product)) { continue; }
            NativeHidWheelProbe probe = ProbeNativeHidWheelEvidence(row.DevicePath);
            if (probe == null)
            {
                AppendNativeHidClassificationReason(row, "Final HID mouse fallback checked after all primary rules: capability probe returned null");
                continue;
            }
            if (!probe.Ok)
            {
                AppendNativeHidClassificationReason(row, "Final HID mouse fallback checked after all primary rules: capability probe failed: " + (String.IsNullOrWhiteSpace(probe.Error) ? "<no detail>" : probe.Error));
                continue;
            }
            if (!probe.Wheel)
            {
                AppendNativeHidClassificationReason(row, "Final HID mouse fallback checked after all primary rules: Wheel=False; " + (String.IsNullOrWhiteSpace(probe.Detail) ? "<no detail>" : probe.Detail));
                continue;
            }
            row.DeviceType = "Mouse";
            string detail = !String.IsNullOrWhiteSpace(probe.Detail) ? probe.Detail : "Wheel=True";
            row.ClassificationReason = "Final HID mouse fallback: no Mouse remained after native HID type lookup, HIDClass validation, MI_03 audio handling, audio-endpoint precedence, and product deduplication; row was unclassified and its product string was not classified as Keyboard; HID input value capabilities expose Generic Desktop Wheel as a relative value. " + detail;
        }
    }

    private static string HidVidPidKeyFromInstance(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return String.Empty; }
        UsbVidPidParseResult pair = DeviceTweakerPathHelpers.ExtractUsbVidPid(instanceId);
        return pair != null && pair.Success ? pair.VidPidKey : String.Empty;
    }

    private static void ApplyNativeHidProductDedup(List<UsbHidDeviceInfo> rows)
    {
        if (rows == null || rows.Count == 0) { return; }
        Dictionary<string, HashSet<string>> productRoleMap = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < rows.Count; i++)
        {
            UsbHidDeviceInfo row = rows[i];
            if (row == null || String.IsNullOrWhiteSpace(row.ProductString) || String.IsNullOrWhiteSpace(row.DeviceType)) { continue; }
            HashSet<string> roles;
            if (!productRoleMap.TryGetValue(row.ProductString, out roles)) { roles = new HashSet<string>(StringComparer.OrdinalIgnoreCase); productRoleMap[row.ProductString] = roles; }
            roles.Add(row.DeviceType);
        }

        Dictionary<string, UsbHidDeviceInfo> dominantByProduct = new Dictionary<string, UsbHidDeviceInfo>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, int> dominantMiByProduct = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < rows.Count; i++)
        {
            UsbHidDeviceInfo row = rows[i];
            if (row == null || String.IsNullOrWhiteSpace(row.ProductString)) { continue; }
            if (!String.Equals(row.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase) && !String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase)) { continue; }
            int mi = DeviceTweakerPathHelpers.ExtractUsbMiNumber(row.DeviceInstanceID);
            if (mi < 0) { continue; }
            int currentMi;
            UsbHidDeviceInfo current;
            if (!dominantByProduct.TryGetValue(row.ProductString, out current) || !dominantMiByProduct.TryGetValue(row.ProductString, out currentMi) || mi < currentMi || (mi == currentMi && String.Equals(current.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase) && String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase)))
            {
                dominantByProduct[row.ProductString] = row;
                dominantMiByProduct[row.ProductString] = mi;
            }
        }
        HashSet<string> dominantMouseProducts = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (KeyValuePair<string, UsbHidDeviceInfo> kv in dominantByProduct)
        {
            if (kv.Value != null && String.Equals(kv.Value.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase)) { dominantMouseProducts.Add(kv.Key); }
        }

        foreach (KeyValuePair<string, HashSet<string>> kv in productRoleMap)
        {
            string product = kv.Key;
            HashSet<string> roles = kv.Value;
            if (roles == null || !roles.Contains("Mouse") || !roles.Contains("Keyboard")) { continue; }
            string dominantRole = null;
            int dominantInterface = Int32.MaxValue;
            string fallbackRole = "Mouse";
            List<UsbHidDeviceInfo> mi00KeyboardCandidates = new List<UsbHidDeviceInfo>();
            List<UsbHidDeviceInfo> mi01OrMi02MouseCandidates = new List<UsbHidDeviceInfo>();

            for (int i = 0; i < rows.Count; i++)
            {
                UsbHidDeviceInfo row = rows[i];
                if (row == null || !String.Equals(row.ProductString, product, StringComparison.OrdinalIgnoreCase)) { continue; }
                if (!String.Equals(row.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase) && !String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase)) { continue; }
                int mi = DeviceTweakerPathHelpers.ExtractUsbMiNumber(row.DeviceInstanceID);
                if (mi < 0) { continue; }
                if (mi == 0 && IsHidClassMouseKeyboardClassification(row, "Keyboard")) { mi00KeyboardCandidates.Add(row); }
                else if ((mi == 1 || mi == 2) && IsHidClassMouseKeyboardClassification(row, "Mouse")) { mi01OrMi02MouseCandidates.Add(row); }
                if (dominantRole == null || mi < dominantInterface)
                {
                    dominantInterface = mi;
                    dominantRole = row.DeviceType;
                }
                else if (mi == dominantInterface && String.Equals(dominantRole, "Mouse", StringComparison.OrdinalIgnoreCase) && String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase))
                {
                    dominantRole = row.DeviceType;
                }
            }

            mi01OrMi02MouseCandidates.Sort(delegate(UsbHidDeviceInfo a, UsbHidDeviceInfo b)
            {
                return DeviceTweakerPathHelpers.ExtractUsbMiNumber(a == null ? null : a.DeviceInstanceID).CompareTo(DeviceTweakerPathHelpers.ExtractUsbMiNumber(b == null ? null : b.DeviceInstanceID));
            });

            bool specialOverride = false;
            string specialMouseRole = null;
            for (int k = 0; k < mi00KeyboardCandidates.Count && !specialOverride; k++)
            {
                string keyboardKey = HidVidPidKeyFromInstance(mi00KeyboardCandidates[k].DeviceInstanceID);
                if (String.IsNullOrWhiteSpace(keyboardKey)) { continue; }
                for (int m = 0; m < mi01OrMi02MouseCandidates.Count; m++)
                {
                    string mouseKey = HidVidPidKeyFromInstance(mi01OrMi02MouseCandidates[m].DeviceInstanceID);
                    if (!String.Equals(keyboardKey, mouseKey, StringComparison.OrdinalIgnoreCase)) { continue; }
                    specialOverride = true;
                    specialMouseRole = "Mouse";
                    break;
                }
            }
            if (specialOverride)
            {
                bool hasOtherDominantInterfaceMouseProduct = dominantMouseProducts.Count > 0 && (dominantMouseProducts.Count > 1 || !dominantMouseProducts.Contains(product));
                if (!hasOtherDominantInterfaceMouseProduct) { dominantRole = specialMouseRole; }
            }
            if (String.IsNullOrWhiteSpace(dominantRole)) { dominantRole = fallbackRole; }
            for (int i = 0; i < rows.Count; i++)
            {
                UsbHidDeviceInfo row = rows[i];
                if (row == null || !String.Equals(row.ProductString, product, StringComparison.OrdinalIgnoreCase)) { continue; }
                if (String.Equals(row.DeviceType, "Mouse", StringComparison.OrdinalIgnoreCase) || String.Equals(row.DeviceType, "Keyboard", StringComparison.OrdinalIgnoreCase)) { row.DeviceType = dominantRole; }
            }
        }
    }

    private static List<UsbHidDeviceInfo> BuildNativeUsbHidRows(DeviceDiscoveryModel model, List<AudioEndpointInfo> audioRows, bool includeLogs, List<string> logs)
    {
        List<UsbHidDeviceInfo> results = new List<UsbHidDeviceInfo>();
        if (model == null) { return results; }
        Dictionary<string, NativeHidClassEntry> hidClassLookup = new Dictionary<string, NativeHidClassEntry>(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, string> typeLookup = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        BuildNativeHidTypeMaps(model, hidClassLookup, typeLookup);
        List<HidInterfaceInfo> hidRows = GetNativeHidInterfaceRows(model);
        List<NativeAudioIdentity> audioIdentities = BuildNativeAudioIdentities(model, audioRows);
        if (includeLogs && logs != null)
        {
            logs.Add("HID/Audio precedence:");
            logs.Add("  LoadedIdentityRecords : " + audioIdentities.Count.ToString(System.Globalization.CultureInfo.InvariantCulture));
            logs.Add("  SuppressionBasis      : ProductString and USB VID/PID");
        }

        for (int i = 0; i < hidRows.Count; i++)
        {
            HidInterfaceInfo hid = hidRows[i];
            if (hid == null) { continue; }
            string product = FirstNonEmpty(hid.Product, "<none>");
            string instance = hid.Instance;
            List<string> controllers = FindControllersForNativeHid(model, instance);
            string lowerName = product == null ? String.Empty : product.ToLowerInvariant();
            if (lowerName.IndexOf("samson", StringComparison.OrdinalIgnoreCase) >= 0)
            {
                results.Add(CreateNativeHidRow(product, instance, hid.DevicePath, null, "Samson audio device explicitly excluded from HID classification", controllers));
                continue;
            }

            NativeHidClassification cls = ClassifyNativeHidDevice(hidClassLookup, typeLookup, instance);
            string deviceType = cls == null ? null : cls.Type;
            string reason = cls == null ? "Type lookup did not classify as Mouse/Keyboard" : cls.Reason;

            if (IsMi03MouseAudioOverride(instance, deviceType, reason))
            {
                if (SameProductLowerInterfaceHasHidClassRole(hidRows, hidClassLookup, typeLookup, product, instance))
                {
                    reason = reason + "; Special handling skipped: same product string also has lower interface classified as Mouse/Keyboard via HIDClass";
                }
                else
                {
                    deviceType = "Audio";
                    reason = reason + "; Special handling: HID Mouse + HIDClass on MI_03 is treated as Audio instead of Mouse";
                }
            }

            NativeAudioIdentity audioMatch = FindNativeAudioMatch(audioIdentities, product, instance);
            if (audioMatch != null && !String.Equals(deviceType, "Audio", StringComparison.OrdinalIgnoreCase))
            {
                string hidVidPid = ExtractVidPidPair(instance);
                string matchDetail = !String.IsNullOrWhiteSpace(hidVidPid) && !String.IsNullOrWhiteSpace(audioMatch.UsbVidPid) && String.Equals(audioMatch.UsbVidPid, hidVidPid, StringComparison.OrdinalIgnoreCase)
                    ? "USB VID/PID " + hidVidPid + " matches"
                    : "ProductString overlaps";
                string audioBlockReason = matchDetail + " AudioEndpoint '" + SafeText(audioMatch.Name) + "' (Source=" + SafeText(audioMatch.Source) + "); blocked from Mouse/Keyboard classification because audio endpoints take precedence over HID mouse/keyboard for the same USB product";
                results.Add(CreateNativeHidRow(product, instance, hid.DevicePath, null, audioBlockReason, controllers));
                continue;
            }

            results.Add(CreateNativeHidRow(product, instance, hid.DevicePath, deviceType, reason, controllers));
        }

        ApplyNativeHidProductDedup(results);
        ApplyNativeHidWheelMouseFallback(results);
        return results;
    }

    public static UsbDiscoveryResult BuildUsbDiscovery(DeviceTweakerStartupModel model, StartupOptions options)
    {
        DeviceTweakerStartupOptions mapped = new DeviceTweakerStartupOptions();
        if (options != null)
        {
            mapped.IncludeLogs = options.IncludeLogs;
            mapped.IncludeUiReadyState = options.IncludeUiReadyState;
            mapped.IgnoredAudioNames = options.IgnoredAudioNames == null ? new string[0] : options.IgnoredAudioNames;
            mapped.PciIdsPath = options.PciIdsPath == null ? String.Empty : options.PciIdsPath;
        }
        return BuildUsbDiscovery(model, mapped);
    }

    public static UsbDiscoveryResult BuildUsbDiscovery(DeviceTweakerStartupModel model, DeviceTweakerStartupOptions options)
    {
        UsbDiscoveryResult result = new UsbDiscoveryResult();
        if (options == null) { options = new DeviceTweakerStartupOptions(); }
        bool includeLogs = options.IncludeLogs;
        string[] ignoredAudioNames = options.IgnoredAudioNames == null ? new string[0] : options.IgnoredAudioNames;

        DeviceDiscoveryModel discoveryModel = null;
        if (model != null) { discoveryModel = model.DiscoveryModel; }
        if (discoveryModel == null) { discoveryModel = BuildModel(); }
        if (model != null && model.DiscoveryModel == null) { model.DiscoveryModel = discoveryModel; }

        List<AudioEndpointInfo> audioRows = new List<AudioEndpointInfo>();
        if (model != null && model.AudioEndpointParentRows != null && (model.AudioEndpointParentRowsComplete || model.AudioEndpointParentRows.Count > 0))
        {
            for (int i = 0; i < model.AudioEndpointParentRows.Count; i++) { if (model.AudioEndpointParentRows[i] != null) { audioRows.Add(model.AudioEndpointParentRows[i]); } }
        }
        else
        {
            List<string> audioLogs = includeLogs && model != null ? model.AudioEndpointSourceLogs : null;
            try
            {
                audioRows = BuildStartupAudioEndpointParentRows(discoveryModel, ignoredAudioNames, audioLogs);
                if (model != null && model.AudioEndpointParentRows != null)
                {
                    model.AudioEndpointParentRows.Clear();
                    for (int i = 0; i < audioRows.Count; i++) { if (audioRows[i] != null) { model.AudioEndpointParentRows.Add(audioRows[i]); } }
                    model.AudioEndpointParentRowsComplete = true;
                }
            }
            catch
            {
                if (model != null) { model.AudioEndpointParentRowsComplete = false; }
                throw;
            }
        }

        List<string> nativeHidLogs = includeLogs ? new List<string>() : null;
        List<UsbHidDeviceInfo> hidRows = BuildNativeUsbHidRows(discoveryModel, audioRows, includeLogs, nativeHidLogs);
        if (model != null && model.HidRows != null)
        {
            model.HidRows.Clear();
            for (int i = 0; i < hidRows.Count; i++) { if (hidRows[i] != null) { model.HidRows.Add(hidRows[i]); } }
        }

        UsbDiscoveryResult display = BuildUsbDisplayRecords(discoveryModel, hidRows, audioRows, ignoredAudioNames);
        if (display == null) { return result; }
        result.Devices = display.Devices ?? new List<UsbDeviceInfo>();
        result.AudioDetails = display.AudioDetails ?? new List<AudioEndpointInfo>();
        result.UnusedCpuControllers = display.UnusedCpuControllers ?? new List<string>();
        if (includeLogs)
        {
            // HID classification details are reconstructed by DeviceTweakerMechanicalDiscoveryLog from typed HidRows.
            // Keep the source log list limited to the USB controller builder trace to avoid duplicate HID blocks.
            if (display.Logs != null) { for (int i = 0; i < display.Logs.Count; i++) { if (!String.IsNullOrWhiteSpace(display.Logs[i])) { result.Logs.Add(display.Logs[i]); } } }
        }
        if (model != null)
        {
            if (model.UsbEndpointDescriptors != null && discoveryModel.EndpointDescriptors != null)
            {
                foreach (KeyValuePair<string, UsbEndpointRecord> kv in discoveryModel.EndpointDescriptors) { if (!String.IsNullOrWhiteSpace(kv.Key) && kv.Value != null) { model.UsbEndpointDescriptors[kv.Key] = kv.Value; } }
            }
        }
        return result;
    }


}


public static class DeviceTweakerMechanicalDiscoveryLog
{
    private sealed class LogField
    {
        public string Key;
        public string Value;
        public LogField(string key, string value) { Key = key ?? String.Empty; Value = value ?? String.Empty; }
    }

    private sealed class HidAuditRecord
    {
        public string Product;
        public string Type;
        public string Instance;
        public string HwId;
        public string DevicePath;
        public string Reason;
    }

    private sealed class HidClassification
    {
        public string Type;
        public string Reason;
    }

    private sealed class HidCapabilityProbe
    {
        public bool Ok;
        public string Error;
        public HidInterop.HIDP_CAPS Caps;
        public HidInterop.HIDP_BUTTON_CAPS[] InputButtonCaps;
        public HidInterop.HIDP_VALUE_CAPS[] InputValueCaps;
        public HidInterop.HIDP_BUTTON_CAPS[] OutputButtonCaps;
        public HidInterop.HIDP_VALUE_CAPS[] OutputValueCaps;
        public HidInterop.HIDP_BUTTON_CAPS[] FeatureButtonCaps;
        public HidInterop.HIDP_VALUE_CAPS[] FeatureValueCaps;
    }

    private static string Safe(object value)
    {
        if (value == null) { return "<null>"; }
        string s = Convert.ToString(value);
        if (String.IsNullOrWhiteSpace(s)) { return "<empty>"; }
        return s.Trim().Replace("\r", " ").Replace("\n", " ");
    }

    private static string EmptyToNone(string value)
    {
        if (String.IsNullOrWhiteSpace(value)) { return "<none>"; }
        return value.Trim().Replace("\r", " ").Replace("\n", " ");
    }

    private static string Quote(string value)
    {
        return "'" + EmptyToNone(value).Replace("'", "`") + "'";
    }

    private static string PnpKey(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return "<empty>"; }
        try { return DeviceTweakerPathHelpers.ToPnpId(instanceId); }
        catch { return instanceId.Trim(); }
    }

    private static string FirstNonEmpty(params string[] values)
    {
        if (values == null) { return String.Empty; }
        for (int i = 0; i < values.Length; i++)
        {
            if (!String.IsNullOrWhiteSpace(values[i])) { return values[i].Trim(); }
        }
        return String.Empty;
    }

    private static object GetPropertyValue(object source, string name)
    {
        if (source == null || String.IsNullOrWhiteSpace(name)) { return null; }
        try
        {
            System.Collections.IDictionary dict = source as System.Collections.IDictionary;
            if (dict != null)
            {
                if (dict.Contains(name)) { return dict[name]; }
                foreach (System.Collections.DictionaryEntry entry in dict)
                {
                    if (entry.Key != null && String.Equals(Convert.ToString(entry.Key), name, StringComparison.OrdinalIgnoreCase)) { return entry.Value; }
                }
            }
        }
        catch { }
        try
        {
            System.Reflection.PropertyInfo psProps = source.GetType().GetProperty("Properties");
            object psPropCollection = psProps == null ? null : psProps.GetValue(source, null);
            System.Collections.IEnumerable psEnumerable = psPropCollection as System.Collections.IEnumerable;
            if (psEnumerable != null)
            {
                foreach (object psProp in psEnumerable)
                {
                    if (psProp == null) { continue; }
                    System.Reflection.PropertyInfo nameProp = psProp.GetType().GetProperty("Name");
                    object propNameObj = nameProp == null ? null : nameProp.GetValue(psProp, null);
                    if (propNameObj == null || !String.Equals(Convert.ToString(propNameObj), name, StringComparison.OrdinalIgnoreCase)) { continue; }
                    System.Reflection.PropertyInfo valueProp = psProp.GetType().GetProperty("Value");
                    return valueProp == null ? null : valueProp.GetValue(psProp, null);
                }
            }
        }
        catch { }
        try
        {
            System.Reflection.PropertyInfo p = source.GetType().GetProperty(name);
            if (p != null) { return p.GetValue(source, null); }
        }
        catch { }
        return null;
    }

    private static string RawProp(object source, string name)
    {
        object value = GetPropertyValue(source, name);
        if (value == null) { return String.Empty; }
        string s = Convert.ToString(value);
        return String.IsNullOrWhiteSpace(s) ? String.Empty : s.Trim();
    }

    private static string Prop(object source, string name)
    {
        return EmptyToNone(RawProp(source, name));
    }

    private static System.Collections.Generic.IEnumerable<object> Each(object source)
    {
        if (source == null) { yield break; }
        string str = source as string;
        if (str != null) { yield return source; yield break; }
        System.Collections.IEnumerable enumerable = source as System.Collections.IEnumerable;
        if (enumerable == null) { yield return source; yield break; }
        foreach (object item in enumerable)
        {
            if (item != null) { yield return item; }
        }
    }

    private static int CountEach(object source)
    {
        int count = 0;
        foreach (object item in Each(source)) { if (item != null) { count++; } }
        return count;
    }

    private static string JoinValue(object value)
    {
        if (value == null) { return "<none>"; }
        string str = value as string;
        if (str != null) { return EmptyToNone(str); }
        System.Collections.IEnumerable enumerable = value as System.Collections.IEnumerable;
        if (enumerable == null) { return EmptyToNone(Convert.ToString(value)); }
        System.Collections.Generic.List<string> parts = new System.Collections.Generic.List<string>();
        foreach (object item in enumerable)
        {
            if (item == null) { continue; }
            string s = Convert.ToString(item);
            if (!String.IsNullOrWhiteSpace(s) && !parts.Contains(s.Trim())) { parts.Add(s.Trim()); }
        }
        return parts.Count == 0 ? "<none>" : String.Join("/", parts.ToArray());
    }

    private static string JoinProp(object source, string name)
    {
        return JoinValue(GetPropertyValue(source, name));
    }

    private static void AddLine(System.Collections.Generic.List<string> lines, string text)
    {
        if (lines == null || text == null) { return; }
        if (String.IsNullOrWhiteSpace(text)) { return; }
        lines.Add(text);
    }

    private static void AddField(System.Collections.Generic.List<LogField> fields, string key, object value)
    {
        if (fields == null || String.IsNullOrWhiteSpace(key)) { return; }
        fields.Add(new LogField(key, value == null ? "<null>" : Convert.ToString(value)));
    }

    private static void AddBlock(System.Collections.Generic.List<string> lines, string title, System.Collections.Generic.List<LogField> fields, string indent)
    {
        if (String.IsNullOrWhiteSpace(title)) { return; }
        AddLine(lines, indent + title.TrimEnd(':') + ":");
        if (fields == null || fields.Count == 0) { return; }
        int max = 0;
        for (int i = 0; i < fields.Count; i++) { if (fields[i].Key.Length > max) { max = fields[i].Key.Length; } }
        string fieldIndent = indent + "  ";
        for (int i = 0; i < fields.Count; i++)
        {
            AddLine(lines, fieldIndent + fields[i].Key.PadRight(max) + " : " + fields[i].Value);
        }
    }

    private static void AddObjectBlock(System.Collections.Generic.List<string> lines, string title, object source, string indent, string[] properties, string[] displayNames, bool[] quoteValues)
    {
        System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
        for (int i = 0; i < properties.Length; i++)
        {
            string value = String.Equals(properties[i], "Roles", StringComparison.OrdinalIgnoreCase) || String.Equals(properties[i], "AudioTypes", StringComparison.OrdinalIgnoreCase) || String.Equals(properties[i], "EndpointNames", StringComparison.OrdinalIgnoreCase)
                ? JoinProp(source, properties[i])
                : Prop(source, properties[i]);
            if (quoteValues != null && i < quoteValues.Length && quoteValues[i]) { value = Quote(value); }
            AddField(fields, displayNames != null && i < displayNames.Length ? displayNames[i] : properties[i], value);
        }
        AddBlock(lines, title, fields, indent);
    }

    private static DeviceNode FindNode(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || model.DevicesByInstanceId == null || String.IsNullOrWhiteSpace(instanceId)) { return null; }
        DeviceNode node = null;
        if (model.DevicesByInstanceId.TryGetValue(instanceId, out node) && node != null) { return node; }
        string pnp = PnpKey(instanceId);
        if (model.DevicesByInstanceId.TryGetValue(pnp, out node) && node != null) { return node; }
        foreach (System.Collections.Generic.KeyValuePair<string, DeviceNode> kv in model.DevicesByInstanceId)
        {
            if (kv.Value == null) { continue; }
            if (String.Equals(kv.Value.InstanceId, instanceId, StringComparison.OrdinalIgnoreCase)) { return kv.Value; }
            if (!String.IsNullOrWhiteSpace(kv.Value.NormalizedInstanceId) && String.Equals(kv.Value.NormalizedInstanceId, instanceId, StringComparison.OrdinalIgnoreCase)) { return kv.Value; }
            if (String.Equals(PnpKey(kv.Value.InstanceId), pnp, StringComparison.OrdinalIgnoreCase)) { return kv.Value; }
        }
        return null;
    }

    private static string[] NodeEvidenceStrings(DeviceNode node, string instanceId, string product)
    {
        System.Collections.Generic.List<string> values = new System.Collections.Generic.List<string>();
        if (!String.IsNullOrWhiteSpace(instanceId)) { values.Add(instanceId); }
        if (!String.IsNullOrWhiteSpace(product)) { values.Add(product); }
        if (node != null)
        {
            if (!String.IsNullOrWhiteSpace(node.InstanceId)) { values.Add(node.InstanceId); }
            if (!String.IsNullOrWhiteSpace(node.FriendlyName)) { values.Add(node.FriendlyName); }
            if (!String.IsNullOrWhiteSpace(node.DeviceDesc)) { values.Add(node.DeviceDesc); }
            if (node.HardwareIds != null) { for (int i = 0; i < node.HardwareIds.Length; i++) { if (!String.IsNullOrWhiteSpace(node.HardwareIds[i])) { values.Add(node.HardwareIds[i]); } } }
            if (node.CompatibleIds != null) { for (int i = 0; i < node.CompatibleIds.Length; i++) { if (!String.IsNullOrWhiteSpace(node.CompatibleIds[i])) { values.Add(node.CompatibleIds[i]); } } }
        }
        return values.ToArray();
    }

    private static bool EvidenceContains(string[] evidence, string needle)
    {
        if (evidence == null || String.IsNullOrWhiteSpace(needle)) { return false; }
        for (int i = 0; i < evidence.Length; i++)
        {
            if (!String.IsNullOrWhiteSpace(evidence[i]) && evidence[i].IndexOf(needle, StringComparison.OrdinalIgnoreCase) >= 0) { return true; }
        }
        return false;
    }

    private static HidClassification ClassifyHid(DeviceDiscoveryModel model, string instanceId, string product)
    {
        DeviceNode node = FindNode(model, instanceId);
        string[] evidence = NodeEvidenceStrings(node, instanceId, product);
        string typedAs = String.Empty;
        if (EvidenceContains(evidence, "HID_DEVICE_SYSTEM_MOUSE") || EvidenceContains(evidence, "HID_DEVICE_UP:0001_U:0002") || EvidenceContains(evidence, "MI_00") && EvidenceContains(evidence, "mouse")) { typedAs = "Mouse"; }
        else if (EvidenceContains(evidence, "HID_DEVICE_SYSTEM_KEYBOARD") || EvidenceContains(evidence, "HID_DEVICE_UP:0001_U:0006") || EvidenceContains(evidence, "HID_DEVICE_UP:0001_U:0007") || EvidenceContains(evidence, "keyboard")) { typedAs = "Keyboard"; }
        bool hidClass = false;
        string service = "<none>";
        if (node != null)
        {
            if (!String.IsNullOrWhiteSpace(node.Service)) { service = node.Service; }
            hidClass = String.Equals(node.ClassName, "HIDClass", StringComparison.OrdinalIgnoreCase) || String.Equals(node.Service, "HidUsb", StringComparison.OrdinalIgnoreCase);
        }
        HidClassification result = new HidClassification();
        if (String.Equals(typedAs, "Mouse", StringComparison.OrdinalIgnoreCase))
        {
            if (hidClass) { result.Type = "Mouse"; result.Reason = "Type=Mouse + HIDClass(Service=" + service + ")"; }
            else { result.Type = String.Empty; result.Reason = "Type=Mouse but HIDClass check failed (Class=miss, Service=" + service + ")"; }
            return result;
        }
        if (String.Equals(typedAs, "Keyboard", StringComparison.OrdinalIgnoreCase))
        {
            if (hidClass) { result.Type = "Keyboard"; result.Reason = "Type=Keyboard + HIDClass(Service=" + service + ")"; }
            else { result.Type = String.Empty; result.Reason = "Type=Keyboard but HIDClass check failed (Class=miss, Service=" + service + ")"; }
            return result;
        }
        result.Type = String.Empty;
        result.Reason = "Type lookup did not classify as Mouse/Keyboard";
        return result;
    }

    private static int ExtractMi(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return -1; }
        try { return DeviceTweakerPathHelpers.ExtractUsbMiNumber(text); } catch { }
        System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(text, @"(?i)(?:^|&)MI_([0-9A-F]{2})(?:&|$)");
        if (!m.Success) { return -1; }
        try { return Convert.ToInt32(m.Groups[1].Value, 16); } catch { return -1; }
    }

    private static string ExtractVidPidKey(string text)
    {
        if (String.IsNullOrWhiteSpace(text)) { return String.Empty; }
        try { return DeviceTweakerPathHelpers.ExtractUsbVidPidKey(text); } catch { }
        System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(text, @"(?i)VID_([0-9A-F]{4})&PID_([0-9A-F]{4})");
        return m.Success ? ("VID_" + m.Groups[1].Value.ToUpperInvariant() + "&PID_" + m.Groups[2].Value.ToUpperInvariant()) : String.Empty;
    }

    private static UsbEndpointRecord FindEndpointForHid(DeviceDiscoveryModel model, string instanceId)
    {
        if (model == null || model.EndpointDescriptors == null || String.IsNullOrWhiteSpace(instanceId)) { return null; }
        string hidVidPid = ExtractVidPidKey(instanceId);
        int mi = ExtractMi(instanceId);
        UsbEndpointRecord best = null;
        foreach (System.Collections.Generic.KeyValuePair<string, UsbEndpointRecord> kv in model.EndpointDescriptors)
        {
            UsbEndpointRecord ep = kv.Value;
            if (ep == null) { continue; }
            string epVidPid = String.Empty;
            if (!String.IsNullOrWhiteSpace(ep.VendorId) && !String.IsNullOrWhiteSpace(ep.ProductId)) { epVidPid = "VID_" + ep.VendorId.Trim().ToUpperInvariant() + "&PID_" + ep.ProductId.Trim().ToUpperInvariant(); }
            if (!String.IsNullOrWhiteSpace(hidVidPid) && !String.Equals(hidVidPid, epVidPid, StringComparison.OrdinalIgnoreCase)) { continue; }
            if (mi >= 0 && ep.InterfaceNumber >= 0 && ep.InterfaceNumber != mi) { continue; }
            if (!String.IsNullOrWhiteSpace(ep.TransferType) && ep.TransferType.IndexOf("Interrupt", StringComparison.OrdinalIgnoreCase) < 0) { continue; }
            if (best == null) { best = ep; }
            if (!String.IsNullOrWhiteSpace(ep.Direction) && ep.Direction.IndexOf("In", StringComparison.OrdinalIgnoreCase) >= 0) { return ep; }
        }
        return best;
    }

    private static string FormatInterface(int mi)
    {
        return FormatInterface(mi, null);
    }

    private static string FormatInterface(int mi, UsbEndpointRecord ep)
    {
        if (mi >= 0) { return "MI_" + mi.ToString("X2"); }
        if (ep != null && ep.InterfaceNumber >= 0) { return "MI_" + ep.InterfaceNumber.ToString("X2"); }
        return "<unknown>";
    }

    private static string FormatInterval(UsbEndpointRecord ep)
    {
        if (ep == null) { return "<unknown>"; }
        if (!String.IsNullOrWhiteSpace(ep.IntervalInterpretation)) { return ep.IntervalInterpretation; }
        if (ep.bInterval <= 0) { return "<unknown>"; }
        string speed = ep.Speed ?? String.Empty;
        if (speed.IndexOf("High", StringComparison.OrdinalIgnoreCase) >= 0 || speed.IndexOf("Super", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            double us = 125.0 * Math.Pow(2.0, Math.Max(0, ep.bInterval - 1));
            if (Math.Abs(us - Math.Round(us)) < 0.01) { return ((int)Math.Round(us)).ToString() + " us"; }
            return us.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) + " us";
        }
        return ep.bInterval.ToString() + " ms";
    }

    private static string FormatPollingRate(UsbEndpointRecord ep)
    {
        if (ep == null || ep.bInterval <= 0) { return "<unknown>"; }
        string speed = ep.Speed ?? String.Empty;
        double hz;
        if (speed.IndexOf("High", StringComparison.OrdinalIgnoreCase) >= 0 || speed.IndexOf("Super", StringComparison.OrdinalIgnoreCase) >= 0)
        {
            double us = 125.0 * Math.Pow(2.0, Math.Max(0, ep.bInterval - 1));
            hz = 1000000.0 / us;
        }
        else { hz = 1000.0 / Math.Max(1, ep.bInterval); }
        int rounded = (int)Math.Round(hz);
        if (rounded >= 1000 && rounded % 1000 == 0) { return rounded.ToString() + " Hz (" + (rounded / 1000).ToString() + "K)"; }
        return rounded.ToString() + " Hz";
    }

    private static HidAuditRecord BuildHidRecordFromRow(DeviceDiscoveryModel model, object row)
    {
        string product = FirstNonEmpty(RawProp(row, "ProductString"), RawProp(row, "Product"));
        string instance = FirstNonEmpty(RawProp(row, "DeviceInstanceID"), RawProp(row, "Instance"), RawProp(row, "HwId"), RawProp(row, "hwId"));
        string type = FirstNonEmpty(RawProp(row, "DeviceType"), RawProp(row, "Type"));
        string reason = FirstNonEmpty(RawProp(row, "ClassificationReason"), RawProp(row, "Reason"));
        string devicePath = RawProp(row, "DevicePath");
        if (String.IsNullOrWhiteSpace(reason) || String.IsNullOrWhiteSpace(type))
        {
            HidClassification cls = ClassifyHid(model, instance, product);
            if (String.IsNullOrWhiteSpace(type)) { type = cls.Type; }
            if (String.IsNullOrWhiteSpace(reason)) { reason = cls.Reason; }
        }
        return new HidAuditRecord { Product = product, Type = type, Instance = instance, HwId = PnpKey(instance), DevicePath = devicePath, Reason = reason };
    }

    private static System.Collections.Generic.List<HidAuditRecord> BuildHidRecords(DeviceDiscoveryModel model, object hidRows)
    {
        System.Collections.Generic.List<HidAuditRecord> records = new System.Collections.Generic.List<HidAuditRecord>();
        foreach (object row in Each(hidRows))
        {
            if (row == null) { continue; }
            HidAuditRecord rec = BuildHidRecordFromRow(model, row);
            if (!String.IsNullOrWhiteSpace(rec.Instance) || !String.IsNullOrWhiteSpace(rec.Product)) { records.Add(rec); }
        }
        if (records.Count > 0) { return records; }
        if (model != null && model.HidInterfaces != null)
        {
            foreach (System.Collections.Generic.KeyValuePair<string, HidInterfaceInfo> kv in model.HidInterfaces)
            {
                HidInterfaceInfo hid = kv.Value;
                if (hid == null) { continue; }
                string instance = FirstNonEmpty(hid.Instance, kv.Key);
                HidClassification cls = ClassifyHid(model, instance, hid.Product);
                records.Add(new HidAuditRecord { Product = hid.Product, Type = cls.Type, Instance = instance, HwId = PnpKey(instance), DevicePath = hid.DevicePath, Reason = cls.Reason });
            }
        }
        return records;
    }

    private static string ConvertHidUsageLabel(int usagePage, int usage)
    {
        string pageName;
        switch (usagePage)
        {
            case 0x01: pageName = "GenericDesktop"; break;
            case 0x07: pageName = "KeyboardKeypad"; break;
            case 0x08: pageName = "LED"; break;
            case 0x09: pageName = "Button"; break;
            case 0x0C: pageName = "Consumer"; break;
            default: pageName = "UsagePage"; break;
        }
        string usageName = "Usage";
        if (usagePage == 0x01)
        {
            switch (usage)
            {
                case 0x02: usageName = "Mouse"; break;
                case 0x04: usageName = "Joystick"; break;
                case 0x05: usageName = "GamePad"; break;
                case 0x06: usageName = "Keyboard"; break;
                case 0x07: usageName = "Keypad"; break;
                case 0x30: usageName = "X"; break;
                case 0x31: usageName = "Y"; break;
                case 0x32: usageName = "Z"; break;
                case 0x33: usageName = "Rx"; break;
                case 0x34: usageName = "Ry"; break;
                case 0x35: usageName = "Rz"; break;
                case 0x38: usageName = "Wheel"; break;
                case 0x39: usageName = "HatSwitch"; break;
                default: usageName = "Usage"; break;
            }
        }
        else if (usagePage == 0x07) { usageName = "KeyboardKey"; }
        else if (usagePage == 0x08)
        {
            switch (usage)
            {
                case 0x01: usageName = "NumLock"; break;
                case 0x02: usageName = "CapsLock"; break;
                case 0x03: usageName = "ScrollLock"; break;
                default: usageName = "LED"; break;
            }
        }
        else if (usagePage == 0x09) { usageName = "Button" + usage.ToString(); }
        else if (usagePage == 0x0C)
        {
            usageName = usage == 0x0238 ? "ACPan-HorizontalWheel" : "ConsumerUsage";
        }
        return String.Format("UP=0x{0:X4}({1}) U=0x{2:X4}({3})", usagePage, pageName, usage, usageName);
    }

    private static string FormatButtonUsageRange(HidInterop.HIDP_BUTTON_CAPS cap)
    {
        int min = cap.UsageMin;
        int max = cap.IsRange ? cap.UsageMax : min;
        if (cap.IsRange && max != min) { return ConvertHidUsageLabel(cap.UsagePage, min) + ".." + ConvertHidUsageLabel(cap.UsagePage, max); }
        return ConvertHidUsageLabel(cap.UsagePage, min);
    }

    private static string FormatValueUsageRange(HidInterop.HIDP_VALUE_CAPS cap)
    {
        int min = cap.UsageMin;
        int max = cap.IsRange ? cap.UsageMax : min;
        if (cap.IsRange && max != min) { return ConvertHidUsageLabel(cap.UsagePage, min) + ".." + ConvertHidUsageLabel(cap.UsagePage, max); }
        return ConvertHidUsageLabel(cap.UsagePage, min);
    }

    private static HidInterop.HIDP_BUTTON_CAPS[] GetButtonCaps(IntPtr preparsed, HidInterop.HIDP_REPORT_TYPE reportType, int count)
    {
        if (count <= 0) { return new HidInterop.HIDP_BUTTON_CAPS[0]; }
        HidInterop.HIDP_BUTTON_CAPS[] arr = new HidInterop.HIDP_BUTTON_CAPS[count];
        ushort len = (ushort)count;
        int status = HidInterop.HidP_GetButtonCaps(reportType, arr, ref len, preparsed);
        if (status != HidInterop.HIDP_STATUS_SUCCESS) { return new HidInterop.HIDP_BUTTON_CAPS[0]; }
        if (len == arr.Length) { return arr; }
        HidInterop.HIDP_BUTTON_CAPS[] outArr = new HidInterop.HIDP_BUTTON_CAPS[len];
        Array.Copy(arr, outArr, len);
        return outArr;
    }

    private static HidInterop.HIDP_VALUE_CAPS[] GetValueCaps(IntPtr preparsed, HidInterop.HIDP_REPORT_TYPE reportType, int count)
    {
        if (count <= 0) { return new HidInterop.HIDP_VALUE_CAPS[0]; }
        HidInterop.HIDP_VALUE_CAPS[] arr = new HidInterop.HIDP_VALUE_CAPS[count];
        ushort len = (ushort)count;
        int status = HidInterop.HidP_GetValueCaps(reportType, arr, ref len, preparsed);
        if (status != HidInterop.HIDP_STATUS_SUCCESS) { return new HidInterop.HIDP_VALUE_CAPS[0]; }
        if (len == arr.Length) { return arr; }
        HidInterop.HIDP_VALUE_CAPS[] outArr = new HidInterop.HIDP_VALUE_CAPS[len];
        Array.Copy(arr, outArr, len);
        return outArr;
    }

    private static HidCapabilityProbe ProbeHidCaps(string devicePath)
    {
        HidCapabilityProbe result = new HidCapabilityProbe();
        result.InputButtonCaps = new HidInterop.HIDP_BUTTON_CAPS[0];
        result.InputValueCaps = new HidInterop.HIDP_VALUE_CAPS[0];
        result.OutputButtonCaps = new HidInterop.HIDP_BUTTON_CAPS[0];
        result.OutputValueCaps = new HidInterop.HIDP_VALUE_CAPS[0];
        result.FeatureButtonCaps = new HidInterop.HIDP_BUTTON_CAPS[0];
        result.FeatureValueCaps = new HidInterop.HIDP_VALUE_CAPS[0];
        if (String.IsNullOrWhiteSpace(devicePath)) { result.Error = "Capability probe unavailable: empty HID device path"; return result; }
        IntPtr handle = IntPtr.Zero;
        IntPtr preparsed = IntPtr.Zero;
        try
        {
            handle = HidInterop.CreateFile(devicePath, 0, 3, IntPtr.Zero, 3, 0, IntPtr.Zero);
            if (handle == IntPtr.Zero || handle == (IntPtr)(-1)) { result.Error = "Capability probe unavailable: CreateFile failed"; return result; }
            if (!HidInterop.HidD_GetPreparsedData(handle, out preparsed)) { result.Error = "Capability probe unavailable: HidD_GetPreparsedData failed"; return result; }
            HidInterop.HIDP_CAPS caps = new HidInterop.HIDP_CAPS();
            int status = HidInterop.HidP_GetCaps(preparsed, ref caps);
            if (status != HidInterop.HIDP_STATUS_SUCCESS) { result.Error = "Capability probe unavailable: HidP_GetCaps status=" + status.ToString(); return result; }
            result.Caps = caps;
            result.InputButtonCaps = GetButtonCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Input, caps.NumberInputButtonCaps);
            result.InputValueCaps = GetValueCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Input, caps.NumberInputValueCaps);
            result.OutputButtonCaps = GetButtonCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Output, caps.NumberOutputButtonCaps);
            result.OutputValueCaps = GetValueCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Output, caps.NumberOutputValueCaps);
            result.FeatureButtonCaps = GetButtonCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Feature, caps.NumberFeatureButtonCaps);
            result.FeatureValueCaps = GetValueCaps(preparsed, HidInterop.HIDP_REPORT_TYPE.HidP_Feature, caps.NumberFeatureValueCaps);
            result.Ok = true;
            return result;
        }
        catch (Exception ex) { result.Error = "Capability probe failed: " + ex.Message; return result; }
        finally
        {
            if (preparsed != IntPtr.Zero) { try { HidInterop.HidD_FreePreparsedData(preparsed); } catch { } }
            if (handle != IntPtr.Zero && handle != (IntPtr)(-1)) { try { HidInterop.CloseHandle(handle); } catch { } }
        }
    }

    private static bool ButtonCapContains(HidInterop.HIDP_BUTTON_CAPS cap, int usagePage, int usage, string relativeMode)
    {
        if (cap.UsagePage != usagePage) { return false; }
        if (String.Equals(relativeMode, "Relative", StringComparison.OrdinalIgnoreCase) && cap.IsAbsolute) { return false; }
        if (String.Equals(relativeMode, "Absolute", StringComparison.OrdinalIgnoreCase) && !cap.IsAbsolute) { return false; }
        int min = cap.UsageMin;
        int max = cap.IsRange ? cap.UsageMax : min;
        return usage >= min && usage <= max;
    }

    private static bool ValueCapContains(HidInterop.HIDP_VALUE_CAPS cap, int usagePage, int usage, string relativeMode)
    {
        if (cap.UsagePage != usagePage) { return false; }
        if (String.Equals(relativeMode, "Relative", StringComparison.OrdinalIgnoreCase) && cap.IsAbsolute) { return false; }
        if (String.Equals(relativeMode, "Absolute", StringComparison.OrdinalIgnoreCase) && !cap.IsAbsolute) { return false; }
        int min = cap.UsageMin;
        int max = cap.IsRange ? cap.UsageMax : min;
        return usage >= min && usage <= max;
    }

    private static bool AnyButtonUsage(HidInterop.HIDP_BUTTON_CAPS[] caps, int usagePage, int usage)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (ButtonCapContains(caps[i], usagePage, usage, "Any")) { return true; } }
        return false;
    }

    private static bool AnyValueUsage(HidInterop.HIDP_VALUE_CAPS[] caps, int usagePage, int usage, string relativeMode)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (ValueCapContains(caps[i], usagePage, usage, relativeMode)) { return true; } }
        return false;
    }

    private static bool AnyButtonUsagePage(HidInterop.HIDP_BUTTON_CAPS[] caps, int usagePage)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (caps[i].UsagePage == usagePage) { return true; } }
        return false;
    }

    private static bool AnyValueUsagePage(HidInterop.HIDP_VALUE_CAPS[] caps, int usagePage)
    {
        if (caps == null) { return false; }
        for (int i = 0; i < caps.Length; i++) { if (caps[i].UsagePage == usagePage) { return true; } }
        return false;
    }

    private static void AddHidCapabilitySummary(System.Collections.Generic.List<string> lines, HidAuditRecord rec, HidCapabilityProbe probe)
    {
        AddLine(lines, "HID Capability:");
        System.Collections.Generic.List<LogField> header = new System.Collections.Generic.List<LogField>();
        AddField(header, "ProductString", Quote(rec.Product));
        AddField(header, "Type", EmptyToNone(rec.Type));
        AddField(header, "hwId", Quote(rec.HwId));
        int max = 0;
        for (int i = 0; i < header.Count; i++) { if (header[i].Key.Length > max) { max = header[i].Key.Length; } }
        for (int i = 0; i < header.Count; i++) { AddLine(lines, "  " + header[i].Key.PadRight(max) + " : " + header[i].Value); }
        if (!probe.Ok)
        {
            AddLine(lines, "  Detail        : " + EmptyToNone(probe.Error));
            return;
        }

        System.Collections.Generic.List<LogField> tlc = new System.Collections.Generic.List<LogField>();
        AddField(tlc, "UsagePage", String.Format("UP=0x{0:X4}({1})", probe.Caps.UsagePage, UsagePageName(probe.Caps.UsagePage)));
        AddField(tlc, "Usage", String.Format("U=0x{0:X4}({1})", probe.Caps.Usage, UsageName(probe.Caps.UsagePage, probe.Caps.Usage)));
        AddBlock(lines, "TLC", tlc, "  ");

        System.Collections.Generic.List<LogField> reports = new System.Collections.Generic.List<LogField>();
        AddField(reports, "In", probe.Caps.InputReportByteLength.ToString());
        AddField(reports, "Out", probe.Caps.OutputReportByteLength.ToString());
        AddField(reports, "Feature", probe.Caps.FeatureReportByteLength.ToString());
        AddBlock(lines, "Reports", reports, "  ");

        System.Collections.Generic.List<LogField> counts = new System.Collections.Generic.List<LogField>();
        AddField(counts, "LC", probe.Caps.NumberLinkCollectionNodes.ToString());
        AddField(counts, "InBtn", probe.Caps.NumberInputButtonCaps.ToString());
        AddField(counts, "InVal", probe.Caps.NumberInputValueCaps.ToString());
        AddField(counts, "InData", probe.Caps.NumberInputDataIndices.ToString());
        AddField(counts, "OutBtn", probe.Caps.NumberOutputButtonCaps.ToString());
        AddField(counts, "OutVal", probe.Caps.NumberOutputValueCaps.ToString());
        AddField(counts, "OutData", probe.Caps.NumberOutputDataIndices.ToString());
        AddField(counts, "FeatureBtn", probe.Caps.NumberFeatureButtonCaps.ToString());
        AddField(counts, "FeatureVal", probe.Caps.NumberFeatureValueCaps.ToString());
        AddField(counts, "FeatureData", probe.Caps.NumberFeatureDataIndices.ToString());
        AddBlock(lines, "CapCounts", counts, "  ");

        bool mouseTlc = probe.Caps.UsagePage == 0x01 && probe.Caps.Usage == 0x02;
        bool relX = AnyValueUsage(probe.InputValueCaps, 0x01, 0x30, "Relative");
        bool relY = AnyValueUsage(probe.InputValueCaps, 0x01, 0x31, "Relative");
        bool buttons = AnyButtonUsagePage(probe.InputButtonCaps, 0x09);
        bool wheel = AnyValueUsage(probe.InputValueCaps, 0x01, 0x38, "Relative");
        bool hWheel = AnyValueUsage(probe.InputValueCaps, 0x0C, 0x0238, "Relative");
        System.Collections.Generic.List<LogField> mouse = new System.Collections.Generic.List<LogField>();
        AddField(mouse, "MouseTLC", mouseTlc.ToString());
        AddField(mouse, "RelX", relX.ToString());
        AddField(mouse, "RelY", relY.ToString());
        AddField(mouse, "RelXY", (relX && relY).ToString());
        AddField(mouse, "Buttons", buttons.ToString());
        AddField(mouse, "Wheel", wheel.ToString());
        AddField(mouse, "HWheel", hWheel.ToString());
        AddBlock(lines, "MouseEvidence", mouse, "  ");

        bool keyboardTlc = probe.Caps.UsagePage == 0x01 && (probe.Caps.Usage == 0x06 || probe.Caps.Usage == 0x07);
        bool keyArray = AnyButtonUsagePage(probe.InputButtonCaps, 0x07) || AnyValueUsagePage(probe.InputValueCaps, 0x07);
        bool ledNum = AnyButtonUsage(probe.OutputButtonCaps, 0x08, 0x01) || AnyValueUsage(probe.OutputValueCaps, 0x08, 0x01, "Any");
        bool ledCaps = AnyButtonUsage(probe.OutputButtonCaps, 0x08, 0x02) || AnyValueUsage(probe.OutputValueCaps, 0x08, 0x02, "Any");
        bool ledScroll = AnyButtonUsage(probe.OutputButtonCaps, 0x08, 0x03) || AnyValueUsage(probe.OutputValueCaps, 0x08, 0x03, "Any");
        System.Collections.Generic.List<LogField> keyboard = new System.Collections.Generic.List<LogField>();
        AddField(keyboard, "KeyboardTLC", keyboardTlc.ToString());
        AddField(keyboard, "KeyArrayUP07", keyArray.ToString());
        AddField(keyboard, "LED_NumLock", ledNum.ToString());
        AddField(keyboard, "LED_CapsLock", ledCaps.ToString());
        AddField(keyboard, "LED_ScrollLock", ledScroll.ToString());
        AddField(keyboard, "LED_All3", (ledNum && ledCaps && ledScroll).ToString());
        AddBlock(lines, "KeyboardEvidence", keyboard, "  ");
    }

    private static string UsagePageName(int usagePage)
    {
        switch (usagePage)
        {
            case 0x01: return "GenericDesktop";
            case 0x07: return "KeyboardKeypad";
            case 0x08: return "LED";
            case 0x09: return "Button";
            case 0x0C: return "Consumer";
            default: return "UsagePage";
        }
    }

    private static string UsageName(int usagePage, int usage)
    {
        string label = ConvertHidUsageLabel(usagePage, usage);
        int p = label.LastIndexOf('(');
        if (p >= 0 && label.EndsWith(")")) { return label.Substring(p + 1, label.Length - p - 2); }
        return "Usage";
    }

    private static void AddButtonCapSection(System.Collections.Generic.List<string> lines, string sectionName, HidInterop.HIDP_BUTTON_CAPS[] caps)
    {
        if (caps == null || caps.Length == 0) { AddLine(lines, "  " + sectionName + " : <none>"); return; }
        AddLine(lines, "  " + sectionName + ":");
        for (int i = 0; i < caps.Length; i++)
        {
            HidInterop.HIDP_BUTTON_CAPS cap = caps[i];
            AddLine(lines, "    - Cap " + (i + 1).ToString() + ":");
            System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
            AddField(fields, "Usage", FormatButtonUsageRange(cap));
            AddField(fields, "RID", ((int)cap.ReportID).ToString());
            AddField(fields, "LC", ((int)cap.LinkCollection).ToString());
            AddField(fields, "Link", ConvertHidUsageLabel(cap.LinkUsagePage, cap.LinkUsage));
            AddField(fields, "Range", cap.IsRange.ToString());
            AddField(fields, "Abs", cap.IsAbsolute.ToString());
            AddField(fields, "Alias", cap.IsAlias.ToString());
            AddField(fields, "Data", ((int)cap.DataIndexMin).ToString() + "-" + ((int)cap.DataIndexMax).ToString());
            AddCapFields(lines, fields);
        }
    }

    private static void AddValueCapSection(System.Collections.Generic.List<string> lines, string sectionName, HidInterop.HIDP_VALUE_CAPS[] caps)
    {
        if (caps == null || caps.Length == 0) { AddLine(lines, "  " + sectionName + " : <none>"); return; }
        AddLine(lines, "  " + sectionName + ":");
        for (int i = 0; i < caps.Length; i++)
        {
            HidInterop.HIDP_VALUE_CAPS cap = caps[i];
            AddLine(lines, "    - Cap " + (i + 1).ToString() + ":");
            System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
            AddField(fields, "Usage", FormatValueUsageRange(cap));
            AddField(fields, "RID", ((int)cap.ReportID).ToString());
            AddField(fields, "LC", ((int)cap.LinkCollection).ToString());
            AddField(fields, "Link", ConvertHidUsageLabel(cap.LinkUsagePage, cap.LinkUsage));
            AddField(fields, "Range", cap.IsRange.ToString());
            AddField(fields, "Abs", cap.IsAbsolute.ToString());
            AddField(fields, "Alias", cap.IsAlias.ToString());
            AddField(fields, "Null", cap.HasNull.ToString());
            AddField(fields, "Bits", ((int)cap.BitSize).ToString());
            AddField(fields, "Count", ((int)cap.ReportCount).ToString());
            AddField(fields, "Logical", cap.LogicalMin.ToString() + ".." + cap.LogicalMax.ToString());
            AddField(fields, "Physical", cap.PhysicalMin.ToString() + ".." + cap.PhysicalMax.ToString());
            AddField(fields, "Units", "0x" + cap.Units.ToString("X8"));
            AddField(fields, "UnitsExp", "0x" + cap.UnitsExp.ToString("X8"));
            AddField(fields, "Data", ((int)cap.DataIndexMin).ToString() + "-" + ((int)cap.DataIndexMax).ToString());
            AddCapFields(lines, fields);
        }
    }

    private static void AddCapFields(System.Collections.Generic.List<string> lines, System.Collections.Generic.List<LogField> fields)
    {
        int max = 0;
        for (int i = 0; i < fields.Count; i++) { if (fields[i].Key.Length > max) { max = fields[i].Key.Length; } }
        for (int i = 0; i < fields.Count; i++) { AddLine(lines, "        " + fields[i].Key.PadRight(max) + " : " + fields[i].Value); }
    }

    private static void AddHidCapabilityDetails(System.Collections.Generic.List<string> lines, HidAuditRecord rec, HidCapabilityProbe probe)
    {
        AddLine(lines, "HID Capability Details:");
        System.Collections.Generic.List<LogField> header = new System.Collections.Generic.List<LogField>();
        AddField(header, "ProductString", Quote(rec.Product));
        AddField(header, "Type", EmptyToNone(rec.Type));
        AddField(header, "hwId", Quote(rec.HwId));
        int max = 0;
        for (int i = 0; i < header.Count; i++) { if (header[i].Key.Length > max) { max = header[i].Key.Length; } }
        for (int i = 0; i < header.Count; i++) { AddLine(lines, "  " + header[i].Key.PadRight(max) + " : " + header[i].Value); }
        if (!probe.Ok) { AddLine(lines, "  Detail : " + EmptyToNone(probe.Error)); return; }
        AddButtonCapSection(lines, "InputButtonCaps", probe.InputButtonCaps);
        AddValueCapSection(lines, "InputValueCaps", probe.InputValueCaps);
        AddButtonCapSection(lines, "OutputButtonCaps", probe.OutputButtonCaps);
        AddValueCapSection(lines, "OutputValueCaps", probe.OutputValueCaps);
        AddButtonCapSection(lines, "FeatureButtonCaps", probe.FeatureButtonCaps);
        AddValueCapSection(lines, "FeatureValueCaps", probe.FeatureValueCaps);
    }

    private static void AddHidAudit(System.Collections.Generic.List<string> lines, DeviceDiscoveryModel model, object hidRows, object pciAudioRows)
    {
        int identityCount = 0;
        if (model != null && model.AudioEndpoints != null)
        {
            // Match the legacy HID/audio precedence logger: it counted AudioEndpoint parent identities
            // and PnP AudioEndpoint identities, not final PCI audio rows.
            identityCount += model.AudioEndpoints.Count;
            identityCount += model.AudioEndpoints.Count;
        }
        System.Collections.Generic.List<LogField> precedence = new System.Collections.Generic.List<LogField>();
        AddField(precedence, "LoadedIdentityRecords", identityCount.ToString());
        AddField(precedence, "SuppressionBasis", "ProductString and USB VID/PID");
        AddBlock(lines, "HID/Audio precedence", precedence, "");

        System.Collections.Generic.List<HidAuditRecord> records = BuildHidRecords(model, hidRows);
        System.Collections.Generic.Dictionary<string,HidAuditRecord> classified = new System.Collections.Generic.Dictionary<string,HidAuditRecord>(StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.Dictionary<string,HidAuditRecord> ignored = new System.Collections.Generic.Dictionary<string,HidAuditRecord>(StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.HashSet<string> classifiedProducts = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.HashSet<string> classifiedVidPids = new System.Collections.Generic.HashSet<string>(StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.List<HidAuditRecord> ignoredRecords = new System.Collections.Generic.List<HidAuditRecord>();
        for (int i = 0; i < records.Count; i++)
        {
            HidAuditRecord rec = records[i];
            UsbEndpointRecord ep = FindEndpointForHid(model, rec.Instance);
            int mi = ExtractMi(rec.Instance);
            bool hasType = !String.IsNullOrWhiteSpace(rec.Type);
            string title = hasType ? "HID Device" : "HID Device IGNORED (not Mouse/Keyboard/Audio)";
            System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
            AddField(fields, "ProductString", Quote(rec.Product));
            if (hasType) { AddField(fields, "Type", rec.Type); }
            AddField(fields, "hwId", Quote(rec.HwId));
            AddField(fields, "USBSpeed", ep != null ? EmptyToNone(ep.Speed) : "<unavailable>");
            AddField(fields, "bInterval", ep != null ? ep.bInterval.ToString() : "<unavailable>");
            AddField(fields, "DescriptorPollingRate", FormatPollingRate(ep));
            AddField(fields, "USBInterface", FormatInterface(mi, ep));
            AddField(fields, "EndpointAddress", ep != null ? EmptyToNone(ep.EndpointAddress) : "<unknown>");
            AddField(fields, "Interval", FormatInterval(ep));
            AddField(fields, "Reason", EmptyToNone(rec.Reason));
            AddBlock(lines, title, fields, "");

            string summaryKey = !String.IsNullOrWhiteSpace(rec.Product) ? rec.Product : rec.HwId;
            if (hasType)
            {
                if (!classified.ContainsKey(summaryKey)) { classified[summaryKey] = rec; }
                if (!String.IsNullOrWhiteSpace(rec.Product)) { classifiedProducts.Add(rec.Product.Trim()); }
                string classifiedVidPid = ExtractVidPidKey(FirstNonEmpty(rec.Instance, rec.HwId));
                if (!String.IsNullOrWhiteSpace(classifiedVidPid)) { classifiedVidPids.Add(classifiedVidPid); }
                if (String.Equals(rec.Type, "Mouse", StringComparison.OrdinalIgnoreCase) || String.Equals(rec.Type, "Keyboard", StringComparison.OrdinalIgnoreCase))
                {
                    HidCapabilityProbe probe = ProbeHidCaps(rec.DevicePath);
                    AddHidCapabilitySummary(lines, rec, probe);
                    AddHidCapabilityDetails(lines, rec, probe);
                }
            }
            else { ignoredRecords.Add(rec); }
        }

        for (int i = 0; i < ignoredRecords.Count; i++)
        {
            HidAuditRecord rec = ignoredRecords[i];
            string ignoredProduct = String.IsNullOrWhiteSpace(rec.Product) ? String.Empty : rec.Product.Trim();
            string ignoredVidPid = ExtractVidPidKey(FirstNonEmpty(rec.Instance, rec.HwId));
            if (!String.IsNullOrWhiteSpace(ignoredProduct) && classifiedProducts.Contains(ignoredProduct)) { continue; }
            if (!String.IsNullOrWhiteSpace(ignoredVidPid) && classifiedVidPids.Contains(ignoredVidPid)) { continue; }
            string summaryKey = !String.IsNullOrWhiteSpace(rec.Product) ? rec.Product : rec.HwId;
            if (!ignored.ContainsKey(summaryKey)) { ignored[summaryKey] = rec; }
        }

        if (classified.Count > 0)
        {
            AddLine(lines, "SUMMARY: HID device classification results:");
            foreach (System.Collections.Generic.KeyValuePair<string,HidAuditRecord> kv in classified)
            {
                System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
                AddField(fields, "ProductString", Quote(kv.Value.Product));
                AddField(fields, "Type", EmptyToNone(kv.Value.Type));
                AddField(fields, "Reason", EmptyToNone(kv.Value.Reason));
                AddBlock(lines, "- HID classification result", fields, "  ");
            }
        }
        else { AddLine(lines, "SUMMARY: No HID devices classified as Mouse/Keyboard/Audio detected."); }

        if (ignored.Count > 0)
        {
            AddLine(lines, "SUMMARY: HID devices IGNORED (not classified as Mouse/Keyboard/Audio): " + ignored.Count.ToString() + " unique product(s)");
            foreach (System.Collections.Generic.KeyValuePair<string,HidAuditRecord> kv in ignored)
            {
                System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
                AddField(fields, "ProductString", Quote(kv.Value.Product));
                AddField(fields, "hwId", Quote(kv.Value.HwId));
                AddField(fields, "Reason", EmptyToNone(kv.Value.Reason));
                AddBlock(lines, "- HID ignored device", fields, "  ");
            }
        }
    }

    private static void AddRawSourceLogs(System.Collections.Generic.List<string> lines, object sourceLogs)
    {
        foreach (object item in Each(sourceLogs))
        {
            if (item == null) { continue; }
            string s = Convert.ToString(item);
            if (String.IsNullOrWhiteSpace(s)) { continue; }
            string normalized = s.Replace("\r\n", "\n").Replace("\r", "\n");
            string[] parts = normalized.Split(new char[] { '\n' });
            for (int i = 0; i < parts.Length; i++)
            {
                string line = parts[i];
                if (String.IsNullOrWhiteSpace(line)) { continue; }
                AddLine(lines, line.TrimEnd());
            }
        }
    }


    private sealed class SourceLogBlock
    {
        public System.Collections.Generic.List<string> Lines = new System.Collections.Generic.List<string>();
        public string PnpId = String.Empty;
        public string Controller = String.Empty;
        public int OriginalIndex;
    }

    private static System.Collections.Generic.List<string> ToSourceLogList(object sourceLogs)
    {
        System.Collections.Generic.List<string> result = new System.Collections.Generic.List<string>();
        foreach (object item in Each(sourceLogs))
        {
            if (item == null) { continue; }
            string s = Convert.ToString(item);
            if (String.IsNullOrWhiteSpace(s)) { continue; }
            string normalized = s.Replace("\r\n", "\n").Replace("\r", "\n");
            string[] parts = normalized.Split(new char[] { '\n' });
            for (int i = 0; i < parts.Length; i++)
            {
                string line = parts[i];
                if (String.IsNullOrWhiteSpace(line)) { continue; }
                result.Add(line.TrimEnd());
            }
        }
        return result;
    }

    private static bool StartsWithIgnoreCase(string text, string prefix)
    {
        return text != null && prefix != null && text.StartsWith(prefix, StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsIndentedSourceLogLine(string line)
    {
        return !String.IsNullOrEmpty(line) && (line[0] == ' ' || line[0] == '\t');
    }

    private static string ExtractLogFieldValue(string text, string key)
    {
        if (String.IsNullOrWhiteSpace(text) || String.IsNullOrWhiteSpace(key)) { return String.Empty; }
        string keyExpr = System.Text.RegularExpressions.Regex.Escape(key.Trim());
        System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(text, "(?i)(?<![A-Za-z0-9_/\\-])" + keyExpr + "\\s*=\\s*'([^']*)'");
        if (m.Success) { return m.Groups[1].Value.Trim(); }
        m = System.Text.RegularExpressions.Regex.Match(text, "(?i)(?<![A-Za-z0-9_/\\-])" + keyExpr + "\\s*=\\s*\\\"([^\\\"]*)\\\"");
        if (m.Success) { return m.Groups[1].Value.Trim(); }
        m = System.Text.RegularExpressions.Regex.Match(text, "(?i)(?<![A-Za-z0-9_/\\-])" + keyExpr + "\\s*=\\s*([^\\s|;,\\)]+)");
        if (m.Success) { return m.Groups[1].Value.Trim().Trim('\'', '"'); }
        return String.Empty;
    }

    private static int UsbRoleRank(string roleText)
    {
        string s = String.IsNullOrWhiteSpace(roleText) ? String.Empty : roleText.Trim();
        if (s.IndexOf("Keyboard", StringComparison.OrdinalIgnoreCase) >= 0) { return 0; }
        if (s.IndexOf("Mouse", StringComparison.OrdinalIgnoreCase) >= 0) { return 1; }
        if (s.IndexOf("Audio", StringComparison.OrdinalIgnoreCase) >= 0) { return 2; }
        if (s.IndexOf("<none>", StringComparison.OrdinalIgnoreCase) >= 0 || s.Length == 0) { return 3; }
        return 4;
    }

    private static int CompareTextOrdinalIgnoreCase(string a, string b)
    {
        return StringComparer.OrdinalIgnoreCase.Compare(a ?? String.Empty, b ?? String.Empty);
    }

    private static void SortContiguousSourceLogGroup(System.Collections.Generic.List<string> logs, string prefix, System.Comparison<string> comparison)
    {
        if (logs == null || logs.Count < 2 || String.IsNullOrWhiteSpace(prefix) || comparison == null) { return; }
        int i = 0;
        while (i < logs.Count)
        {
            if (!StartsWithIgnoreCase(logs[i], prefix)) { i++; continue; }
            int start = i;
            while (i < logs.Count && StartsWithIgnoreCase(logs[i], prefix)) { i++; }
            int count = i - start;
            if (count < 2) { continue; }
            System.Collections.Generic.List<string> group = logs.GetRange(start, count);
            group.Sort(comparison);
            for (int g = 0; g < group.Count; g++) { logs[start + g] = group[g]; }
        }
    }

    private static string[] NormalizeUsbSourceLogs(object sourceLogs)
    {
        System.Collections.Generic.List<string> logs = ToSourceLogList(sourceLogs);
        if (logs.Count < 2) { return logs.ToArray(); }

        System.Collections.Generic.Dictionary<string,string> roleByController = new System.Collections.Generic.Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < logs.Count; i++)
        {
            string line = logs[i];
            if (StartsWithIgnoreCase(line, "  - Controller entry:"))
            {
                string controller = ExtractLogFieldValue(line, "Controller");
                string roles = ExtractLogFieldValue(line, "Roles");
                if (!String.IsNullOrWhiteSpace(controller) && !roleByController.ContainsKey(controller)) { roleByController[controller] = roles; }
            }
            else if (StartsWithIgnoreCase(line, "Get-USBControllers: Assigned HID role"))
            {
                string controller = ExtractLogFieldValue(line, "Controller");
                string role = ExtractLogFieldValue(line, "Role");
                if (!String.IsNullOrWhiteSpace(controller) && !String.IsNullOrWhiteSpace(role) && !roleByController.ContainsKey(controller)) { roleByController[controller] = role; }
            }
        }

        SortContiguousSourceLogGroup(logs, "Get-USBControllers: Assigned HID role", delegate(string a, string b) {
            int ra = UsbRoleRank(ExtractLogFieldValue(a, "Role"));
            int rb = UsbRoleRank(ExtractLogFieldValue(b, "Role"));
            if (ra != rb) { return ra.CompareTo(rb); }
            return CompareTextOrdinalIgnoreCase(ExtractLogFieldValue(a, "Controller"), ExtractLogFieldValue(b, "Controller"));
        });

        SortContiguousSourceLogGroup(logs, "  - Controller entry:", delegate(string a, string b) {
            string ca = ExtractLogFieldValue(a, "Controller");
            string cb = ExtractLogFieldValue(b, "Controller");
            string raText = ExtractLogFieldValue(a, "Roles");
            string rbText = ExtractLogFieldValue(b, "Roles");
            int ra = UsbRoleRank(raText);
            int rb = UsbRoleRank(rbText);
            if (ra != rb) { return ra.CompareTo(rb); }
            return CompareTextOrdinalIgnoreCase(ca, cb);
        });

        SortContiguousSourceLogGroup(logs, "Get-USBControllers: Controller origin", delegate(string a, string b) {
            string ca = ExtractLogFieldValue(a, "Controller");
            string cb = ExtractLogFieldValue(b, "Controller");
            string roleA = roleByController.ContainsKey(ca) ? roleByController[ca] : String.Empty;
            string roleB = roleByController.ContainsKey(cb) ? roleByController[cb] : String.Empty;
            int ra = UsbRoleRank(roleA);
            int rb = UsbRoleRank(roleB);
            if (ra != rb) { return ra.CompareTo(rb); }
            return CompareTextOrdinalIgnoreCase(ca, cb);
        });

        return logs.ToArray();
    }

    private static bool IsPciAudioDetectionStart(string line)
    {
        return StartsWithIgnoreCase(line, "Get-PCIDevices: IGNORED Audio controller") || StartsWithIgnoreCase(line, "Get-PCIDevices: INCLUDED Audio controller");
    }

    private static int PciVendorDeviceSortValue(string pnpId, bool vendor)
    {
        if (String.IsNullOrWhiteSpace(pnpId)) { return -1; }
        string pattern = vendor ? "(?i)VEN_([0-9A-F]{4})" : "(?i)DEV_([0-9A-F]{4})";
        System.Text.RegularExpressions.Match m = System.Text.RegularExpressions.Regex.Match(pnpId, pattern);
        if (!m.Success) { return -1; }
        try { return Int32.Parse(m.Groups[1].Value, System.Globalization.NumberStyles.HexNumber, System.Globalization.CultureInfo.InvariantCulture); }
        catch { return -1; }
    }

    private static int ComparePciPnpIdDescending(string a, string b)
    {
        int av = PciVendorDeviceSortValue(a, true);
        int bv = PciVendorDeviceSortValue(b, true);
        if (av != bv) { return bv.CompareTo(av); }
        int ad = PciVendorDeviceSortValue(a, false);
        int bd = PciVendorDeviceSortValue(b, false);
        if (ad != bd) { return bd.CompareTo(ad); }
        return CompareTextOrdinalIgnoreCase(b, a);
    }

    private static int ComparePciAudioBlocks(SourceLogBlock a, SourceLogBlock b)
    {
        int cmp = ComparePciPnpIdDescending(a == null ? String.Empty : a.PnpId, b == null ? String.Empty : b.PnpId);
        if (cmp != 0) { return cmp; }
        int ai = a == null ? 0 : a.OriginalIndex;
        int bi = b == null ? 0 : b.OriginalIndex;
        return ai.CompareTo(bi);
    }

    private static System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<string>> BuildIgnoredAudioEndpointDetailsByPnpId(System.Collections.Generic.List<string> logs)
    {
        System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<string>> map = new System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<string>>(StringComparer.OrdinalIgnoreCase);
        if (logs == null) { return map; }
        for (int i = 0; i < logs.Count; i++)
        {
            string line = logs[i];
            if (!StartsWithIgnoreCase(line, "Get-PCIDevices: IGNORED Audio controller")) { continue; }
            string pnp = ExtractLogFieldValue(line, "PNPID");
            if (String.IsNullOrWhiteSpace(pnp) || map.ContainsKey(pnp)) { continue; }
            System.Collections.Generic.List<string> detail = new System.Collections.Generic.List<string>();
            int j = i + 1;
            while (j < logs.Count && IsIndentedSourceLogLine(logs[j]))
            {
                string child = logs[j];
                if (StartsWithIgnoreCase(child, "  Checked AudioEndpoint(s):"))
                {
                    string cleaned = System.Text.RegularExpressions.Regex.Replace(child, "\\s+ControllerPNPID='[^']*'", String.Empty);
                    detail.Add("  " + cleaned.TrimEnd());
                }
                else if (StartsWithIgnoreCase(child, "    - Endpoint "))
                {
                    detail.Add("  " + child.TrimEnd());
                }
                j++;
            }
            if (detail.Count > 0) { map[pnp] = detail; }
        }
        return map;
    }

    private static string[] NormalizePciSourceLogs(object sourceLogs)
    {
        System.Collections.Generic.List<string> original = ToSourceLogList(sourceLogs);
        if (original.Count < 2) { return original.ToArray(); }
        System.Collections.Generic.Dictionary<string,System.Collections.Generic.List<string>> ignoredDetailByPnp = BuildIgnoredAudioEndpointDetailsByPnpId(original);

        System.Collections.Generic.List<string> firstPass = new System.Collections.Generic.List<string>(original.Count + 16);
        int i = 0;
        while (i < original.Count)
        {
            if (!IsPciAudioDetectionStart(original[i]))
            {
                firstPass.Add(original[i]);
                i++;
                continue;
            }

            System.Collections.Generic.List<SourceLogBlock> blocks = new System.Collections.Generic.List<SourceLogBlock>();
            while (i < original.Count && IsPciAudioDetectionStart(original[i]))
            {
                SourceLogBlock block = new SourceLogBlock();
                block.OriginalIndex = i;
                block.PnpId = ExtractLogFieldValue(original[i], "PNPID");
                block.Lines.Add(original[i]);
                i++;
                while (i < original.Count && IsIndentedSourceLogLine(original[i]))
                {
                    block.Lines.Add(original[i]);
                    i++;
                }
                blocks.Add(block);
            }
            blocks.Sort(ComparePciAudioBlocks);
            for (int b = 0; b < blocks.Count; b++) { firstPass.AddRange(blocks[b].Lines); }
        }

        System.Collections.Generic.List<string> secondPass = new System.Collections.Generic.List<string>(firstPass.Count + 32);
        i = 0;
        while (i < firstPass.Count)
        {
            string line = firstPass[i];
            if (!StartsWithIgnoreCase(line, "SUMMARY: Audio controllers IGNORED"))
            {
                secondPass.Add(line);
                i++;
                continue;
            }

            secondPass.Add(line);
            i++;
            System.Collections.Generic.List<SourceLogBlock> blocks = new System.Collections.Generic.List<SourceLogBlock>();
            while (i < firstPass.Count && StartsWithIgnoreCase(firstPass[i], "  - Ignored audio controller"))
            {
                SourceLogBlock block = new SourceLogBlock();
                block.OriginalIndex = i;
                block.PnpId = ExtractLogFieldValue(firstPass[i], "PNPID");
                block.Lines.Add(firstPass[i]);
                i++;
                bool hasChecked = false;
                while (i < firstPass.Count && !StartsWithIgnoreCase(firstPass[i], "  - Ignored audio controller") && IsIndentedSourceLogLine(firstPass[i]))
                {
                    if (firstPass[i].IndexOf("Checked AudioEndpoint(s)", StringComparison.OrdinalIgnoreCase) >= 0) { hasChecked = true; }
                    block.Lines.Add(firstPass[i]);
                    i++;
                }
                if (!hasChecked && !String.IsNullOrWhiteSpace(block.PnpId) && ignoredDetailByPnp.ContainsKey(block.PnpId))
                {
                    block.Lines.AddRange(ignoredDetailByPnp[block.PnpId]);
                }
                blocks.Add(block);
            }
            blocks.Sort(ComparePciAudioBlocks);
            for (int b = 0; b < blocks.Count; b++) { secondPass.AddRange(blocks[b].Lines); }
        }

        return secondPass.ToArray();
    }


    private sealed class NetworkAdapterSnapshot
    {
        public string Name = String.Empty;
        public string PnpDeviceId = String.Empty;
        public string InterfaceDescription = String.Empty;
        public string Status = String.Empty;
        public string NetworkAdapterKind = String.Empty;
        public string NdisPhysicalMedium = String.Empty;
        public string NdisMedium = String.Empty;
    }

    private sealed class NetworkDriverSnapshot
    {
        public string ServiceRegPath = String.Empty;
        public string ImagePath = String.Empty;
        public string ResolvedPath = String.Empty;
        public string FileDescription = String.Empty;
    }

    private static string NormalizeNetworkRegistryDisplayPath(string path)
    {
        if (String.IsNullOrWhiteSpace(path)) { return String.Empty; }
        string s = path.Trim();
        if (s.StartsWith("HKLM:\\", StringComparison.OrdinalIgnoreCase)) { return "HKEY_LOCAL_MACHINE\\" + s.Substring(6); }
        if (s.StartsWith("HKLM\\", StringComparison.OrdinalIgnoreCase)) { return "HKEY_LOCAL_MACHINE\\" + s.Substring(5); }
        return s;
    }

    private static string HklmSubKeyFromDisplayPath(string path)
    {
        if (String.IsNullOrWhiteSpace(path)) { return String.Empty; }
        string s = NormalizeNetworkRegistryDisplayPath(path).Trim();
        const string hklm = "HKEY_LOCAL_MACHINE\\";
        if (s.StartsWith(hklm, StringComparison.OrdinalIgnoreCase)) { return s.Substring(hklm.Length); }
        if (s.StartsWith("HKLM:\\", StringComparison.OrdinalIgnoreCase)) { return s.Substring(6); }
        return s.TrimStart('\\');
    }

    private static string ReadHklmStringValue(string displayPath, string valueName)
    {
        if (String.IsNullOrWhiteSpace(displayPath) || String.IsNullOrWhiteSpace(valueName)) { return String.Empty; }
        try
        {
            string subKey = HklmSubKeyFromDisplayPath(displayPath);
            if (String.IsNullOrWhiteSpace(subKey)) { return String.Empty; }
            using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.LocalMachine.OpenSubKey(subKey, false))
            {
                if (key == null) { return String.Empty; }
                object value = key.GetValue(valueName);
                return value == null ? String.Empty : Convert.ToString(value).Trim();
            }
        }
        catch { return String.Empty; }
    }

    private static string ResolveNetworkDriverImagePath(string imagePath)
    {
        if (String.IsNullOrWhiteSpace(imagePath)) { return String.Empty; }
        try
        {
            string resolved = imagePath.Trim();
            string systemRoot = Environment.GetEnvironmentVariable("SystemRoot");
            if (String.IsNullOrWhiteSpace(systemRoot)) { systemRoot = @"C:\Windows"; }
            if (resolved.StartsWith("\\SystemRoot", StringComparison.OrdinalIgnoreCase))
            {
                resolved = systemRoot + resolved.Substring("\\SystemRoot".Length);
            }
            else if (resolved.StartsWith(@"System32", StringComparison.OrdinalIgnoreCase))
            {
                resolved = System.IO.Path.Combine(systemRoot, resolved);
            }
            else if (resolved.StartsWith("\\??\\", StringComparison.OrdinalIgnoreCase))
            {
                resolved = resolved.Substring(4);
            }
            resolved = resolved.Replace("%SystemRoot%", systemRoot).Replace("%systemroot%", systemRoot);
            return resolved.Trim();
        }
        catch { return imagePath.Trim(); }
    }

    private static string GetNetworkDriverFileDescription(string resolvedPath)
    {
        if (String.IsNullOrWhiteSpace(resolvedPath)) { return String.Empty; }
        try
        {
            if (!System.IO.File.Exists(resolvedPath)) { return String.Empty; }
            string desc = System.Diagnostics.FileVersionInfo.GetVersionInfo(resolvedPath).FileDescription;
            return String.IsNullOrWhiteSpace(desc) ? String.Empty : desc.Trim();
        }
        catch { return String.Empty; }
    }

    private static NetworkDriverSnapshot GetNetworkDriverSnapshot(object row)
    {
        NetworkDriverSnapshot snap = new NetworkDriverSnapshot();
        if (row == null) { return snap; }

        string classPath = RawProp(row, "RegistryPath");
        string configPath = RawProp(row, "ConfigPath");
        string driver = String.Empty;

        if (!String.IsNullOrWhiteSpace(configPath)) { driver = ReadHklmStringValue(configPath, "Driver"); }
        if (String.IsNullOrWhiteSpace(driver) && !String.IsNullOrWhiteSpace(classPath))
        {
            string classSubKey = HklmSubKeyFromDisplayPath(classPath);
            const string marker = @"SYSTEM\CurrentControlSet\Control\Class\";
            int idx = classSubKey.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
            if (idx >= 0) { driver = classSubKey.Substring(idx + marker.Length); }
        }

        string serviceName = String.Empty;
        if (!String.IsNullOrWhiteSpace(classPath)) { serviceName = ReadHklmStringValue(NormalizeNetworkRegistryDisplayPath(classPath) + @"\Ndi", "Service"); }
        if (String.IsNullOrWhiteSpace(serviceName) && !String.IsNullOrWhiteSpace(driver))
        {
            serviceName = ReadHklmStringValue(@"HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Control\Class\" + driver + @"\Ndi", "Service");
        }
        if (!String.IsNullOrWhiteSpace(serviceName)) { serviceName = serviceName.TrimEnd('.').Trim(); }

        if (!String.IsNullOrWhiteSpace(serviceName))
        {
            snap.ServiceRegPath = @"HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Services\" + serviceName;
            snap.ImagePath = ReadHklmStringValue(snap.ServiceRegPath, "ImagePath");
            snap.ResolvedPath = ResolveNetworkDriverImagePath(snap.ImagePath);
            snap.FileDescription = GetNetworkDriverFileDescription(snap.ResolvedPath);
        }
        return snap;
    }

    private static string ManagementPropertyText(System.Management.ManagementBaseObject mo, string propertyName)
    {
        if (mo == null || String.IsNullOrWhiteSpace(propertyName)) { return String.Empty; }
        try
        {
            object value = mo.Properties[propertyName] == null ? null : mo.Properties[propertyName].Value;
            if (value == null) { return String.Empty; }
            System.Array array = value as System.Array;
            if (array != null)
            {
                System.Collections.Generic.List<string> parts = new System.Collections.Generic.List<string>();
                foreach (object item in array)
                {
                    if (item == null) { continue; }
                    string s = Convert.ToString(item).Trim();
                    if (s.Length > 0) { parts.Add(s); }
                }
                return parts.Count == 0 ? String.Empty : String.Join("/", parts.ToArray());
            }
            string text = Convert.ToString(value);
            return String.IsNullOrWhiteSpace(text) ? String.Empty : text.Trim();
        }
        catch { return String.Empty; }
    }

    private static string NormalizeNetworkStatusText(string status)
    {
        if (String.IsNullOrWhiteSpace(status)) { return String.Empty; }
        string s = status.Trim();
        if (String.Equals(s, "1", StringComparison.OrdinalIgnoreCase)) { return "Up"; }
        if (String.Equals(s, "2", StringComparison.OrdinalIgnoreCase)) { return "Down"; }
        if (String.Equals(s, "3", StringComparison.OrdinalIgnoreCase)) { return "Testing"; }
        if (String.Equals(s, "4", StringComparison.OrdinalIgnoreCase)) { return "Unknown"; }
        if (String.Equals(s, "5", StringComparison.OrdinalIgnoreCase)) { return "Dormant"; }
        if (String.Equals(s, "6", StringComparison.OrdinalIgnoreCase)) { return "NotPresent"; }
        if (String.Equals(s, "7", StringComparison.OrdinalIgnoreCase)) { return "LowerLayerDown"; }
        return s;
    }

    private static bool TryParseNetworkAdapterNdisUInt32(string value, out uint result)
    {
        result = 0;
        if (String.IsNullOrWhiteSpace(value)) { return false; }
        string s = value.Trim();
        if (s.IndexOf('/') >= 0) { s = s.Split('/')[0].Trim(); }
        return UInt32.TryParse(s, System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out result);
    }

    private static string ClassifyNetworkAdapterKind(string ndisPhysicalMediumText, string ndisMediumText)
    {
        uint ndisPhysicalMedium;
        if (TryParseNetworkAdapterNdisUInt32(ndisPhysicalMediumText, out ndisPhysicalMedium))
        {
            switch (ndisPhysicalMedium)
            {
                case 1: return "WiFi";
                case 9: return "WiFi";
                case 14: return "WiredEthernet";
                case 10: return "Bluetooth";
                case 8: return "WirelessWAN";
                case 12: return "WiMAX";
            }
        }

        uint ndisMedium;
        if (TryParseNetworkAdapterNdisUInt32(ndisMediumText, out ndisMedium))
        {
            if (ndisMedium == 16) { return "WiFi"; }
            if (ndisMedium == 0) { return "EthernetOrUnknown"; }
        }

        return "OtherOrUnknown";
    }

    private static System.Collections.Generic.List<NetworkAdapterSnapshot> QueryPhysicalNetworkAdapterSnapshots(object networkRows)
    {
        System.Collections.Generic.List<NetworkAdapterSnapshot> result = new System.Collections.Generic.List<NetworkAdapterSnapshot>();
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("root\\StandardCimv2", "SELECT InterfaceDescription, Name, Status, InterfaceOperationalStatus, AdminStatus, NdisPhysicalMedium, NdisMedium, InterfaceIndex, PNPDeviceID FROM MSFT_NetAdapter WHERE Virtual=False"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        NetworkAdapterSnapshot snap = new NetworkAdapterSnapshot();
                        snap.InterfaceDescription = FirstNonEmpty(ManagementPropertyText(mo, "InterfaceDescription"), ManagementPropertyText(mo, "Name"));
                        snap.Name = FirstNonEmpty(ManagementPropertyText(mo, "Name"), snap.InterfaceDescription);
                        snap.PnpDeviceId = ManagementPropertyText(mo, "PNPDeviceID");
                        snap.Status = NormalizeNetworkStatusText(FirstNonEmpty(ManagementPropertyText(mo, "Status"), ManagementPropertyText(mo, "InterfaceOperationalStatus"), ManagementPropertyText(mo, "AdminStatus")));
                        snap.NdisPhysicalMedium = ManagementPropertyText(mo, "NdisPhysicalMedium");
                        snap.NdisMedium = ManagementPropertyText(mo, "NdisMedium");
                        snap.NetworkAdapterKind = ClassifyNetworkAdapterKind(snap.NdisPhysicalMedium, snap.NdisMedium);
                        if (!String.IsNullOrWhiteSpace(snap.InterfaceDescription) || !String.IsNullOrWhiteSpace(snap.PnpDeviceId)) { result.Add(snap); }
                    }
                }
            }
        }
        catch { }

        if (result.Count == 0)
        {
            foreach (object row in Each(networkRows))
            {
                string name = FirstNonEmpty(RawProp(row, "OriginalDescription"), RawProp(row, "Description"));
                if (String.IsNullOrWhiteSpace(name)) { continue; }
                NetworkAdapterSnapshot snap = new NetworkAdapterSnapshot();
                snap.InterfaceDescription = name;
                snap.Name = name;
                snap.PnpDeviceId = FirstNonEmpty(RawProp(row, "ConfigPath"), RawProp(row, "PNPID"));
                snap.Status = FirstNonEmpty(RawProp(row, "Status"), RawProp(row, "InterfaceOperationalStatus"), "Up");
                snap.NdisPhysicalMedium = RawProp(row, "NdisPhysicalMedium");
                snap.NdisMedium = RawProp(row, "NdisMedium");
                snap.NetworkAdapterKind = FirstNonEmpty(RawProp(row, "NetworkAdapterKind"), RawProp(row, "Type"), ClassifyNetworkAdapterKind(snap.NdisPhysicalMedium, snap.NdisMedium));
                result.Add(snap);
            }
        }
        return result;
    }

    private static System.Collections.Generic.List<NetworkAdapterSnapshot> QueryWin32NetworkAdapterSnapshots()
    {
        System.Collections.Generic.List<NetworkAdapterSnapshot> result = new System.Collections.Generic.List<NetworkAdapterSnapshot>();
        try
        {
            using (System.Management.ManagementObjectSearcher searcher = new System.Management.ManagementObjectSearcher("SELECT Name, PNPDeviceID FROM Win32_NetworkAdapter"))
            {
                foreach (System.Management.ManagementObject mo in searcher.Get())
                {
                    using (mo)
                    {
                        NetworkAdapterSnapshot snap = new NetworkAdapterSnapshot();
                        snap.Name = ManagementPropertyText(mo, "Name");
                        snap.PnpDeviceId = ManagementPropertyText(mo, "PNPDeviceID");
                        if (!String.IsNullOrWhiteSpace(snap.Name) || !String.IsNullOrWhiteSpace(snap.PnpDeviceId)) { result.Add(snap); }
                    }
                }
            }
        }
        catch { }
        return result;
    }

    private static object FindNetworkRowByOriginalName(object networkRows, string originalName)
    {
        object first = null;
        foreach (object row in Each(networkRows))
        {
            if (row == null) { continue; }
            if (first == null) { first = row; }
            string rowName = FirstNonEmpty(RawProp(row, "OriginalDescription"), RawProp(row, "Description"));
            if (!String.IsNullOrWhiteSpace(originalName) && String.Equals(rowName, originalName, StringComparison.OrdinalIgnoreCase)) { return row; }
        }
        return first;
    }

    private static void AddLegacyNetworkDetectedBlock(System.Collections.Generic.List<string> lines, object row, string adapterName)
    {
        if (row == null) { return; }
        NetworkDriverSnapshot driver = GetNetworkDriverSnapshot(row);
        string original = FirstNonEmpty(adapterName, RawProp(row, "OriginalDescription"), RawProp(row, "Description"));
        string resolved = FirstNonEmpty(RawProp(row, "Description"), original);
        string role = Prop(row, "Role");
        string adapterKind = FirstNonEmpty(RawProp(row, "NetworkAdapterKind"), RawProp(row, "Type"), ClassifyNetworkAdapterKind(RawProp(row, "NdisPhysicalMedium"), RawProp(row, "NdisMedium")));
        string ndisPhysicalMedium = RawProp(row, "NdisPhysicalMedium");
        string ndisMedium = RawProp(row, "NdisMedium");
        string pnp = Prop(row, "PNPID");
        string classPath = NormalizeNetworkRegistryDisplayPath(RawProp(row, "RegistryPath"));
        string configPath = NormalizeNetworkRegistryDisplayPath(RawProp(row, "ConfigPath"));

        System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
        AddField(fields, "Name", Quote(original));
        AddField(fields, "ResolvedName", Quote(resolved));
        AddField(fields, "Role", Quote(role));
        AddField(fields, "DriverType", Quote(role));
        AddField(fields, "Type", Quote(adapterKind));
        AddField(fields, "NdisPhysicalMedium", Quote(ndisPhysicalMedium));
        AddField(fields, "NdisMedium", Quote(ndisMedium));
        AddField(fields, "PNPID", Quote(pnp));
        AddField(fields, "ClassPath", Quote(classPath));
        AddField(fields, "ConfigPath", Quote(configPath));
        AddField(fields, "Service", Quote(driver.ServiceRegPath));
        AddField(fields, "ImagePath", Quote(driver.ImagePath));
        AddField(fields, "ResolvedPath", Quote(driver.ResolvedPath));
        AddField(fields, "FileDescription", Quote(driver.FileDescription));
        AddBlock(lines, "Get-NetworkAdapters: Detected network adapter", fields, String.Empty);
    }

    private static void AddLegacyNetworkSummary(System.Collections.Generic.List<string> lines, object networkRows, int win32Total, int ignoredSkipped)
    {
        int detectedCount = CountEach(networkRows);
        System.Collections.Generic.List<LogField> summary = new System.Collections.Generic.List<LogField>();
        AddField(summary, "NetworkAdaptersDetected", detectedCount.ToString());
        AddField(summary, "Win32NetworkAdapterTotal", win32Total.ToString());
        AddField(summary, "IgnoredSkipped", ignoredSkipped.ToString());
        AddBlock(lines, "Get-NetworkAdapters: Summary", summary, String.Empty);

        foreach (object row in Each(networkRows))
        {
            string resolved = FirstNonEmpty(RawProp(row, "Description"), RawProp(row, "OriginalDescription"));
            string original = FirstNonEmpty(RawProp(row, "OriginalDescription"), resolved);
            string role = Prop(row, "Role");
            string adapterKind = FirstNonEmpty(RawProp(row, "NetworkAdapterKind"), RawProp(row, "Type"), ClassifyNetworkAdapterKind(RawProp(row, "NdisPhysicalMedium"), RawProp(row, "NdisMedium")));
            string ndisPhysicalMedium = RawProp(row, "NdisPhysicalMedium");
            string ndisMedium = RawProp(row, "NdisMedium");
            string classPath = NormalizeNetworkRegistryDisplayPath(RawProp(row, "RegistryPath"));
            string configPath = NormalizeNetworkRegistryDisplayPath(RawProp(row, "ConfigPath"));

            System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
            AddField(fields, "Name", Quote(resolved));
            AddField(fields, "OriginalName", Quote(original));
            AddField(fields, "Role", Quote(role));
            AddField(fields, "Type", Quote(adapterKind));
            AddField(fields, "NdisPhysicalMedium", Quote(ndisPhysicalMedium));
            AddField(fields, "NdisMedium", Quote(ndisMedium));
            AddField(fields, "ClassPath", Quote(classPath));
            AddField(fields, "ConfigPath", Quote(configPath));
            AddBlock(lines, "Detected Adapter", fields, "  ");
        }
    }

    private static string[] BuildLegacyNetworkSourceLogs(object networkRows)
    {
        System.Collections.Generic.List<string> lines = new System.Collections.Generic.List<string>();
        System.Collections.Generic.List<NetworkAdapterSnapshot> physicalAdapters = QueryPhysicalNetworkAdapterSnapshots(networkRows);
        System.Collections.Generic.Dictionary<string, NetworkAdapterSnapshot> physicalByName = new System.Collections.Generic.Dictionary<string, NetworkAdapterSnapshot>(StringComparer.OrdinalIgnoreCase);
        System.Collections.Generic.Dictionary<string, NetworkAdapterSnapshot> physicalByPnp = new System.Collections.Generic.Dictionary<string, NetworkAdapterSnapshot>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < physicalAdapters.Count; i++)
        {
            NetworkAdapterSnapshot pa = physicalAdapters[i];
            if (pa == null) { continue; }
            if (!String.IsNullOrWhiteSpace(pa.InterfaceDescription) && !physicalByName.ContainsKey(pa.InterfaceDescription)) { physicalByName[pa.InterfaceDescription] = pa; }
            if (!String.IsNullOrWhiteSpace(pa.Name) && !physicalByName.ContainsKey(pa.Name)) { physicalByName[pa.Name] = pa; }
            if (!String.IsNullOrWhiteSpace(pa.PnpDeviceId) && !physicalByPnp.ContainsKey(pa.PnpDeviceId)) { physicalByPnp[pa.PnpDeviceId] = pa; }
        }

        AddLine(lines, "Get-NetworkAdapters: MSFT_NetAdapter Virtual=False returned " + physicalAdapters.Count.ToString() + " adapter(s)");
        for (int i = 0; i < physicalAdapters.Count; i++)
        {
            NetworkAdapterSnapshot pa = physicalAdapters[i];
            if (pa == null) { continue; }
            System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
            AddField(fields, "InterfaceDescription", Quote(pa.InterfaceDescription));
            AddField(fields, "Name", Quote(pa.Name));
            AddField(fields, "PNPDeviceID", Quote(pa.PnpDeviceId));
            AddField(fields, "Status", EmptyToNone(pa.Status));
            AddField(fields, "Type", Quote(pa.NetworkAdapterKind));
            AddField(fields, "NdisPhysicalMedium", Quote(pa.NdisPhysicalMedium));
            AddField(fields, "NdisMedium", Quote(pa.NdisMedium));
            AddBlock(lines, "Physical adapter", fields, "  ");
        }

        System.Collections.Generic.List<NetworkAdapterSnapshot> allAdapters = QueryWin32NetworkAdapterSnapshots();
        if (allAdapters.Count == 0)
        {
            foreach (object row in Each(networkRows))
            {
                NetworkAdapterSnapshot snap = new NetworkAdapterSnapshot();
                snap.Name = FirstNonEmpty(RawProp(row, "OriginalDescription"), RawProp(row, "Description"));
                snap.PnpDeviceId = RawProp(row, "ConfigPath");
                allAdapters.Add(snap);
            }
        }

        int skipped = 0;
        for (int i = 0; i < allAdapters.Count; i++)
        {
            NetworkAdapterSnapshot adapter = allAdapters[i];
            if (adapter == null) { continue; }
            string adapterName = adapter.Name;
            string pnp = adapter.PnpDeviceId;
            if (String.IsNullOrWhiteSpace(pnp))
            {
                System.Collections.Generic.List<LogField> ignoredFields = new System.Collections.Generic.List<LogField>();
                AddField(ignoredFields, "Name", Quote(adapterName));
                AddField(ignoredFields, "Reason", "No PNPDeviceID available (virtual or incomplete device)");
                AddBlock(lines, "Get-NetworkAdapters: Adapter IGNORED", ignoredFields, String.Empty);
                skipped++;
                continue;
            }

            NetworkAdapterSnapshot physicalInfo = null;
            if (!String.IsNullOrWhiteSpace(pnp)) { physicalByPnp.TryGetValue(pnp, out physicalInfo); }
            if (physicalInfo == null && !String.IsNullOrWhiteSpace(adapterName)) { physicalByName.TryGetValue(adapterName, out physicalInfo); }
            bool isPhysical = physicalInfo != null;
            if (!isPhysical)
            {
                System.Collections.Generic.List<LogField> ignoredFields = new System.Collections.Generic.List<LogField>();
                AddField(ignoredFields, "Name", Quote(adapterName));
                AddField(ignoredFields, "PNPDeviceID", Quote(pnp));
                AddField(ignoredFields, "Reason", "Not present in MSFT_NetAdapter Virtual=False (virtual\\software adapter)");
                AddBlock(lines, "Get-NetworkAdapters: Adapter IGNORED", ignoredFields, String.Empty);
                skipped++;
                continue;
            }

            AddLine(lines, "Get-NetworkAdapters: " + Quote(adapterName) + " matched adapter candidate (physical identity is checked before writes)");
            object row = FindNetworkRowByOriginalName(networkRows, adapterName);
            AddLegacyNetworkDetectedBlock(lines, row, adapterName);
        }

        AddLegacyNetworkSummary(lines, networkRows, allAdapters.Count, skipped);
        return lines.ToArray();
    }

    private static bool NetworkSourceLogsAlreadyLegacyComplete(System.Collections.Generic.List<string> logs)
    {
        if (logs == null || logs.Count == 0) { return false; }
        bool hasPhysicalBlock = false;
        bool hasIgnoredBlock = false;
        bool hasServiceField = false;
        bool hasSummaryBlock = false;
        bool hasNdisPhysicalMediumField = false;
        bool hasNdisMediumField = false;
        bool hasTypeField = false;
        for (int i = 0; i < logs.Count; i++)
        {
            string line = logs[i] ?? String.Empty;
            if (StartsWithIgnoreCase(line, "  Physical adapter:")) { hasPhysicalBlock = true; }
            if (StartsWithIgnoreCase(line, "Get-NetworkAdapters: Adapter IGNORED:")) { hasIgnoredBlock = true; }
            if (line.IndexOf("Service", StringComparison.OrdinalIgnoreCase) >= 0 && line.IndexOf("CurrentControlSet", StringComparison.OrdinalIgnoreCase) >= 0) { hasServiceField = true; }
            if (StartsWithIgnoreCase(line, "  NdisPhysicalMedium") || line.IndexOf("NdisPhysicalMedium=", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf("NdisPhysicalMedium='", StringComparison.OrdinalIgnoreCase) >= 0) { hasNdisPhysicalMediumField = true; }
            if (StartsWithIgnoreCase(line, "  NdisMedium") || line.IndexOf("NdisMedium=", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf("NdisMedium='", StringComparison.OrdinalIgnoreCase) >= 0) { hasNdisMediumField = true; }
            if (StartsWithIgnoreCase(line, "  Type") || line.IndexOf(" Type=", StringComparison.OrdinalIgnoreCase) >= 0 || line.IndexOf(" Type='", StringComparison.OrdinalIgnoreCase) >= 0) { hasTypeField = true; }
            if (StartsWithIgnoreCase(line, "Get-NetworkAdapters: Summary:")) { hasSummaryBlock = true; }
        }
        return hasPhysicalBlock && hasIgnoredBlock && hasServiceField && hasSummaryBlock && hasNdisPhysicalMediumField && hasNdisMediumField && hasTypeField;
    }

    private static string[] NormalizeNetworkSourceLogs(object networkSourceLogs, object networkRows)
    {
        System.Collections.Generic.List<string> logs = ToSourceLogList(networkSourceLogs);
        int count = CountEach(networkRows);
        if (count <= 0) { return logs.Count > 0 ? logs.ToArray() : new string[0]; }

        if (NetworkSourceLogsAlreadyLegacyComplete(logs)) { return logs.ToArray(); }

        // Rebuild this section in the legacy/correct shape instead of replaying the newer compact
        // network source logs. This keeps DeviceTweakerMechanicalDiscoveryLog as the only emitted
        // mechanical log surface while preserving the old physical-adapter, ignored-adapter,
        // driver/service detail, and aligned summary blocks.
        try
        {
            string[] rebuilt = BuildLegacyNetworkSourceLogs(networkRows);
            if (rebuilt != null && rebuilt.Length > 0) { return rebuilt; }
        }
        catch { }

        if (logs.Count > 0) { return logs.ToArray(); }
        return new string[0];
    }

    private static void AddMechanicalUsbAudit(System.Collections.Generic.List<string> lines, DeviceDiscoveryModel model, object usbRows)
    {
        AddLine(lines, "USB Mechanical Audit:");
        int usbRowCount = 0;
        foreach (object row in Each(usbRows))
        {
            usbRowCount++;
            AddObjectBlock(lines, "USBDisplayRow", row, "  ",
                new string[] { "DisplayName", "Roles", "AudioTypes", "UsbHeaderTitle", "UsbEndpointUsageLabel", "UsbControllerMaxLabel", "RegistryPath", "Description" },
                new string[] { "DisplayName", "Roles", "AudioTypes", "Header", "EndpointUse", "MaxSpeed", "RegistryPath", "Desc" },
                new bool[] { true, true, true, true, true, true, true, true });
        }
        if (usbRowCount == 0) { AddLine(lines, "  USBDisplayRow : <none> | Reason='no USB controller UI rows reached the final device list'"); }

        if (model != null && model.UsbControllers != null && model.UsbControllers.Count > 0)
        {
            foreach (System.Collections.Generic.KeyValuePair<string, DeviceNode> kv in model.UsbControllers)
            {
                DeviceNode node = kv.Value;
                System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
                AddField(fields, "PNPID", Quote(PnpKey(node != null ? node.InstanceId : kv.Key)));
                AddField(fields, "InstanceId", Quote(node != null ? node.InstanceId : kv.Key));
                AddField(fields, "Class", Quote(node != null ? node.ClassName : String.Empty));
                AddField(fields, "Service", Quote(node != null ? node.Service : String.Empty));
                AddField(fields, "Desc", Quote(node != null ? FirstNonEmpty(node.FriendlyName, node.DeviceDesc, kv.Key) : kv.Key));
                AddField(fields, "Parent", Quote(node != null ? node.ParentInstanceId : String.Empty));
                AddBlock(lines, "USBControllerNode", fields, "  ");
            }
        }
        else { AddLine(lines, "  USBControllerNode : <none> | Reason='native discovery model has zero USB controller nodes'"); }

        if (model != null && model.UsbControllerAssociationList != null && model.UsbControllerAssociationList.Count > 0)
        {
            for (int i = 0; i < model.UsbControllerAssociationList.Count; i++)
            {
                UsbControllerAssociationRecord pair = model.UsbControllerAssociationList[i];
                if (pair == null) { continue; }
                System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
                AddField(fields, "Controller", Quote(PnpKey(pair.CtrlId)));
                AddField(fields, "Device", Quote(PnpKey(pair.DevId)));
                AddField(fields, "RawController", Quote(pair.CtrlId));
                AddField(fields, "RawDevice", Quote(pair.DevId));
                AddField(fields, "Depth", pair.Depth.ToString());
                AddBlock(lines, "USBControllerAssociation", fields, "  ");
            }
        }
        else { AddLine(lines, "  USBControllerAssociation : <none> | Reason='no controller/device parent-chain associations were produced'"); }
    }

    private static void AddMechanicalPciAudit(System.Collections.Generic.List<string> lines, DeviceDiscoveryModel model, object pciGpuRows, object pciAudioRows)
    {
        AddLine(lines, "PCI Mechanical Audit:");
        int gpuCount = 0;
        foreach (object row in Each(pciGpuRows))
        {
            gpuCount++;
            AddObjectBlock(lines, "PCIGpuRow", row, "  ",
                new string[] { "DisplayName", "PNPID", "Port", "RegistryPath", "Description", "OriginalDescription" },
                new string[] { "DisplayName", "PNPID", "Port", "RegistryPath", "Desc", "OriginalDesc" },
                new bool[] { true, true, true, true, true, true });
        }
        if (gpuCount == 0) { AddLine(lines, "  PCIGpuRow : <none>"); }

        int audioCount = 0;
        foreach (object row in Each(pciAudioRows))
        {
            audioCount++;
            AddObjectBlock(lines, "PCIAudioRow", row, "  ",
                new string[] { "DisplayName", "Role", "PNPID", "Port", "AudioTypes", "EndpointNames", "RegistryPath", "Description", "ClassificationReason" },
                new string[] { "DisplayName", "Role", "PNPID", "Port", "AudioTypes", "EndpointNames", "RegistryPath", "Desc", "Reason" },
                new bool[] { true, true, true, true, true, false, true, true, false });
        }
        if (audioCount == 0) { AddLine(lines, "  PCIAudioRow : <none>"); }

        if (model != null && model.PciDevicesByPath != null && model.PciDevicesByPath.Count > 0)
        {
            foreach (System.Collections.Generic.KeyValuePair<string, PciDeviceInfo> kv in model.PciDevicesByPath)
            {
                PciDeviceInfo p = kv.Value;
                if (p == null) { continue; }
                System.Collections.Generic.List<LogField> fields = new System.Collections.Generic.List<LogField>();
                AddField(fields, "PNPID", Quote(FirstNonEmpty(p.PNPID, PnpKey(p.InstanceId))));
                AddField(fields, "InstanceId", Quote(p.InstanceId));
                AddField(fields, "HardwareId", Quote(p.HardwareId));
                AddField(fields, "PortId", Quote(p.PortId));
                AddField(fields, "Location", Quote(p.LocationInformation));
                AddField(fields, "ClassCode", Quote(p.ClassCode));
                AddField(fields, "IsGpu", p.IsGpuDescription.ToString());
                AddField(fields, "IsGpuClassCode", p.IsGpuClassCode.ToString());
                AddField(fields, "IsAudioController", p.IsAudioController.ToString());
                AddField(fields, "Path", Quote(FirstNonEmpty(p.PSPath, kv.Key)));
                AddField(fields, "Desc", Quote(p.DeviceDesc));
                AddBlock(lines, "PCIDeviceNode", fields, "  ");
            }
        }
        else { AddLine(lines, "  PCIDeviceNode : <none> | Reason='native discovery model has zero PCI children'"); }
    }

    private static void AddStorageAudit(System.Collections.Generic.List<string> lines, object storageRows)
    {
        AddLine(lines, "Storage Mechanical Audit:");
        int count = 0;
        foreach (object row in Each(storageRows))
        {
            count++;
            AddObjectBlock(lines, "StorageRow", row, "  ",
                new string[] { "DisplayName", "Role", "StorageType", "RegistryPath", "Description" },
                new string[] { "DisplayName", "Role", "StorageType", "ControllerPath", "Desc" },
                new bool[] { true, true, true, true, true });
        }
        if (count == 0) { AddLine(lines, "  StorageRow : <none>"); }
    }

    private static void AddNetworkAudit(System.Collections.Generic.List<string> lines, object networkRows)
    {
        AddLine(lines, "Network Mechanical Audit:");
        int count = 0;
        foreach (object row in Each(networkRows))
        {
            count++;
            AddObjectBlock(lines, "NetworkAdapterRow", row, "  ",
                new string[] { "DisplayName", "Role", "PNPID", "RegistryPath", "ConfigPath", "Description", "OriginalDescription" },
                new string[] { "DisplayName", "Role", "PNPID", "RegistryPath", "ConfigPath", "Desc", "OriginalDesc" },
                new bool[] { true, true, true, true, true, true, true });
        }
        if (count == 0) { AddLine(lines, "  NetworkAdapterRow : <none> | Reason='no final network adapter rows were produced; check Get-NetAdapter -Physical / Win32_NetworkAdapter correlation and registry Driver/Ndi\\Service values'"); }
    }

    public static string[] BuildDiscoveryAuditLines(DeviceDiscoveryModel model, object usbRows, object pciGpuRows, object pciAudioRows, object networkRows)
    {
        return BuildDiscoveryAuditLines(model, usbRows, pciGpuRows, pciAudioRows, networkRows, null, null, null, null, null, null);
    }

    public static string[] BuildDiscoveryAuditLines(DeviceDiscoveryModel model, object usbRows, object pciGpuRows, object pciAudioRows, object networkRows, object storageRows, object hidRows, object usbSourceLogs, object pciSourceLogs)
    {
        return BuildDiscoveryAuditLines(model, usbRows, pciGpuRows, pciAudioRows, networkRows, storageRows, hidRows, usbSourceLogs, pciSourceLogs, null, null);
    }

    public static string[] BuildDiscoveryAuditLines(DeviceDiscoveryModel model, object usbRows, object pciGpuRows, object pciAudioRows, object networkRows, object storageRows, object hidRows, object usbSourceLogs, object pciSourceLogs, object storageSourceLogs, object networkSourceLogs)
    {
        System.Collections.Generic.List<string> lines = new System.Collections.Generic.List<string>(512);
        if (model == null) { model = new DeviceDiscoveryModel(); }

        // Legacy-compatible output: DeviceTweakerMechanicalDiscoveryLog is now the sole replay surface
        // for the old discovery log sections. Do not emit START/Source/Snapshot wrappers or the
        // newer Mechanical Audit node dumps; those made logs/logging.txt diverge from the known-good log.
        // The source log normalizers below preserve the old/correct deterministic ordering and make
        // sure detailed audio-endpoint and network discovery sections survive async/native collection.
        AddHidAudit(lines, model, hidRows, pciAudioRows);
        AddRawSourceLogs(lines, NormalizeUsbSourceLogs(usbSourceLogs));
        AddRawSourceLogs(lines, NormalizePciSourceLogs(pciSourceLogs));
        AddRawSourceLogs(lines, storageSourceLogs);
        AddRawSourceLogs(lines, NormalizeNetworkSourceLogs(networkSourceLogs, networkRows));
        return lines.ToArray();
    }
}

public static class UsbBIntervalReader
{
    private const uint FILE_DEVICE_USB = 0x22;
    private const uint FILE_ANY_ACCESS = 0;
    private const uint METHOD_BUFFERED = 0;

    private const uint DIGCF_PRESENT = 0x00000002;
    private const uint DIGCF_ALLCLASSES = 0x00000004;
    private const uint DIGCF_DEVICEINTERFACE = 0x00000010;

    private const uint SPDRP_DEVICEDESC = 0x00000000;
    private const uint SPDRP_HARDWAREID = 0x00000001;
    private const uint SPDRP_COMPATIBLEIDS = 0x00000002;
    private const uint SPDRP_SERVICE = 0x00000004;
    private const uint SPDRP_CLASS = 0x00000007;
    private const uint SPDRP_CLASSGUID = 0x00000008;
    private const uint SPDRP_FRIENDLYNAME = 0x0000000C;
    private const uint SPDRP_ENUMERATOR_NAME = 0x00000016;

    private const uint GENERIC_READ = 0x80000000;
    private const uint GENERIC_WRITE = 0x40000000;
    private const uint FILE_SHARE_READ = 0x00000001;
    private const uint FILE_SHARE_WRITE = 0x00000002;
    private const uint OPEN_EXISTING = 3;

    private const int ERROR_INSUFFICIENT_BUFFER = 122;
    private const int ERROR_NO_MORE_ITEMS = 259;

    private const int USB_CONFIGURATION_DESCRIPTOR_TYPE = 2;
    private const int USB_INTERFACE_DESCRIPTOR_TYPE = 4;
    private const int USB_ENDPOINT_DESCRIPTOR_TYPE = 5;

    private const int USB_NODE_INFORMATION_BUFFER_SIZE = 128;
    private const int USB_NODE_CONNECTION_INFORMATION_EX_SIZE = 35;
    private const int USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE = 16;
    private const int USB_HUB_INFORMATION_EX_BUFFER_SIZE = 96;
    private const int USB_DESCRIPTOR_REQUEST_HEADER_SIZE = 12;
    private const int LARGE_NAME_BUFFER = 4096;
    private const int MAX_TOPOLOGY_DEPTH = 32;
    private const int MAX_DEVNODE_ASSOCIATION_DEPTH = 64;
    private const int CR_SUCCESS = 0;
    private const uint DN_PRESENT = 0x00000008;

    private static Guid GUID_DEVINTERFACE_USB_HOST_CONTROLLER =
        new Guid("{3ABF6F2D-71C4-462A-8A92-1E6861E6AF27}");

    private static readonly IntPtr INVALID_HANDLE_VALUE = new IntPtr(-1);

    private static readonly uint IOCTL_USB_GET_ROOT_HUB_NAME =
        CTL_CODE(FILE_DEVICE_USB, 258, METHOD_BUFFERED, FILE_ANY_ACCESS);

