    private static uint CTL_CODE(uint deviceType, uint function, uint method, uint access)
    {
        return (deviceType << 16) | (access << 14) | (function << 2) | method;
    }


    public static DeviceTopologySnapshot BuildDeviceTopologySnapshot()
    {
        DeviceTopologySnapshot snapshot = new DeviceTopologySnapshot();

        snapshot.DeviceNodes = EnumerateDeviceNodesNative();
        BuildDeviceNodeIndexes(snapshot);

        try { snapshot.HostControllerInterfaces = GetHostControllerInterfaces(null); }
        catch { snapshot.HostControllerInterfaces = new List<UsbHostControllerInterfaceInfo>(); }

        snapshot.ControllerByPath = BuildHostControllerMapByPath(snapshot.HostControllerInterfaces);
        if (snapshot.HostControllerInterfaces != null)
        {
            for (int i = 0; i < snapshot.HostControllerInterfaces.Count; i++)
            {
                UsbHostControllerInterfaceInfo hc = snapshot.HostControllerInterfaces[i];
                if (hc == null || String.IsNullOrWhiteSpace(hc.PnpId)) { continue; }
                if (!snapshot.ControllerByPnpId.ContainsKey(hc.PnpId)) { snapshot.ControllerByPnpId.Add(hc.PnpId, hc); }
            }
        }

        try { snapshot.ControllerAssociations = BuildControllerAssociationsFromDeviceNodes(snapshot.DeviceNodes, snapshot.ControllerByPath.Values, snapshot.ChildrenByParent); }
        catch { snapshot.ControllerAssociations = new List<UsbControllerAssociationRecord>(); }

        try { snapshot.HidInterfaces = EnumerateHidInterfacesNative(); }
        catch { snapshot.HidInterfaces = new List<HidInterfaceInfo>(); }

        try { snapshot.UsbEnumeration = Enumerate(false, snapshot.HostControllerInterfaces); }
        catch { snapshot.UsbEnumeration = new UsbEnumerationResult(); }

        BuildUsbEndpointIndexes(snapshot);
        snapshot.UsbEndpoints = BuildUsbEndpointInfos(snapshot.UsbEnumeration, snapshot.ControllerAssociations, snapshot.ControllerByPath);

        return snapshot;
    }

    private static void BuildDeviceNodeIndexes(DeviceTopologySnapshot snapshot)
    {
        if (snapshot == null) { return; }
        if (snapshot.ParentMap == null) { snapshot.ParentMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); }
        if (snapshot.DevicesByInstanceId == null) { snapshot.DevicesByInstanceId = new Dictionary<string, DeviceNode>(StringComparer.OrdinalIgnoreCase); }
        if (snapshot.ChildrenByParent == null) { snapshot.ChildrenByParent = new Dictionary<string, List<DeviceNode>>(StringComparer.OrdinalIgnoreCase); }
        if (snapshot.DeviceNodes == null) { return; }

        for (int i = 0; i < snapshot.DeviceNodes.Count; i++)
        {
            DeviceNode node = snapshot.DeviceNodes[i];
            if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }

            if (String.IsNullOrWhiteSpace(node.NormalizedInstanceId)) { node.NormalizedInstanceId = NormalizeDeviceInstanceId(node.InstanceId); }
            if (String.IsNullOrWhiteSpace(node.NormalizedParentInstanceId)) { node.NormalizedParentInstanceId = NormalizeDeviceInstanceId(node.ParentInstanceId); }
            if (String.IsNullOrWhiteSpace(node.PnpId)) { node.PnpId = DeviceTweakerPathHelpers.ToPnpId(node.InstanceId); }
            if (String.IsNullOrWhiteSpace(node.VidPid)) { node.VidPid = ExtractVidPidPairFromNode(node); }
            if (String.IsNullOrWhiteSpace(node.VenDev)) { node.VenDev = ExtractVenDevFromNode(node); }

            if (!snapshot.DevicesByInstanceId.ContainsKey(node.InstanceId)) { snapshot.DevicesByInstanceId.Add(node.InstanceId, node); }
            if (!String.IsNullOrWhiteSpace(node.NormalizedInstanceId) && !snapshot.DevicesByInstanceId.ContainsKey(node.NormalizedInstanceId)) { snapshot.DevicesByInstanceId.Add(node.NormalizedInstanceId, node); }

            string parent = !String.IsNullOrWhiteSpace(node.ParentInstanceId) ? node.ParentInstanceId : node.NormalizedParentInstanceId;
            if (String.IsNullOrWhiteSpace(parent)) { continue; }

            if (!snapshot.ParentMap.ContainsKey(node.InstanceId)) { snapshot.ParentMap.Add(node.InstanceId, parent); }
            if (!String.IsNullOrWhiteSpace(node.NormalizedInstanceId) && !snapshot.ParentMap.ContainsKey(node.NormalizedInstanceId)) { snapshot.ParentMap.Add(node.NormalizedInstanceId, parent); }

            List<DeviceNode> children;
            if (!snapshot.ChildrenByParent.TryGetValue(parent, out children))
            {
                children = new List<DeviceNode>();
                snapshot.ChildrenByParent[parent] = children;
            }
            children.Add(node);

            if (!String.IsNullOrWhiteSpace(node.NormalizedParentInstanceId) && !String.Equals(parent, node.NormalizedParentInstanceId, StringComparison.OrdinalIgnoreCase))
            {
                if (!snapshot.ChildrenByParent.TryGetValue(node.NormalizedParentInstanceId, out children))
                {
                    children = new List<DeviceNode>();
                    snapshot.ChildrenByParent[node.NormalizedParentInstanceId] = children;
                }
                children.Add(node);
            }
        }
    }

    private static Dictionary<string, string> BuildHostControllerMapByPath(List<UsbHostControllerInterfaceInfo> hostControllers)
    {
        Dictionary<string, string> map = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        if (hostControllers == null) { return map; }
        for (int i = 0; i < hostControllers.Count; i++)
        {
            UsbHostControllerInterfaceInfo hc = hostControllers[i];
            if (hc == null || String.IsNullOrWhiteSpace(hc.HostControllerPath) || String.IsNullOrWhiteSpace(hc.InstanceId)) { continue; }
            if (!map.ContainsKey(hc.HostControllerPath)) { map.Add(hc.HostControllerPath, hc.InstanceId); }
        }
        return map;
    }

    private static void BuildUsbEndpointIndexes(DeviceTopologySnapshot snapshot)
    {
        if (snapshot == null) { return; }
        if (snapshot.EndpointByVidPid == null) { snapshot.EndpointByVidPid = new Dictionary<string, UsbEndpointRecord>(StringComparer.OrdinalIgnoreCase); }
        if (snapshot.UsbEnumeration == null || snapshot.UsbEnumeration.Endpoints == null) { return; }
        for (int i = 0; i < snapshot.UsbEnumeration.Endpoints.Count; i++)
        {
            UsbEndpointRecord ep = snapshot.UsbEnumeration.Endpoints[i];
            if (ep == null) { continue; }
            string vid = NormalizeHex4(ep.VendorId);
            string pid = NormalizeHex4(ep.ProductId);
            if (String.IsNullOrWhiteSpace(vid) || String.IsNullOrWhiteSpace(pid)) { continue; }
            string key = vid + ":" + pid;
            if (!snapshot.EndpointByVidPid.ContainsKey(key)) { snapshot.EndpointByVidPid.Add(key, ep); }
        }
    }

    private static List<DeviceNode> EnumerateDeviceNodesNative()
    {
        List<DeviceNode> nodes = new List<DeviceNode>();
        IntPtr infoSet = SetupDiGetClassDevsAll(IntPtr.Zero, IntPtr.Zero, IntPtr.Zero, DIGCF_ALLCLASSES);
        if (infoSet == INVALID_HANDLE_VALUE || infoSet == IntPtr.Zero) { return nodes; }

        try
        {
            uint index = 0;
            while (true)
            {
                SP_DEVINFO_DATA devInfo = new SP_DEVINFO_DATA();
                devInfo.cbSize = Marshal.SizeOf(typeof(SP_DEVINFO_DATA));

                bool ok = SetupDiEnumDeviceInfo(infoSet, index, ref devInfo);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    if (err == ERROR_NO_MORE_ITEMS) { break; }
                    break;
                }

                string instanceId = GetSetupDiDeviceInstanceId(infoSet, ref devInfo);
                if (String.IsNullOrWhiteSpace(instanceId)) { instanceId = GetDeviceIdFromDevInst(devInfo.DevInst); }
                if (String.IsNullOrWhiteSpace(instanceId)) { index++; continue; }

                DeviceNode node = new DeviceNode();
                node.InstanceId = instanceId;
                node.NormalizedInstanceId = NormalizeDeviceInstanceId(instanceId);
                node.ParentInstanceId = GetParentDeviceIdFromDevInst(devInfo.DevInst);
                node.NormalizedParentInstanceId = NormalizeDeviceInstanceId(node.ParentInstanceId);
                node.ClassGuid = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_CLASSGUID);
                if (String.IsNullOrWhiteSpace(node.ClassGuid) && devInfo.ClassGuid != Guid.Empty)
                {
                    node.ClassGuid = devInfo.ClassGuid.ToString("B").ToUpperInvariant();
                }
                node.ClassName = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_CLASS);
                node.Service = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_SERVICE);
                node.HardwareIds = GetRegistryMultiStringProperty(infoSet, ref devInfo, SPDRP_HARDWAREID);
                node.CompatibleIds = GetRegistryMultiStringProperty(infoSet, ref devInfo, SPDRP_COMPATIBLEIDS);
                node.FriendlyName = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_FRIENDLYNAME);
                node.DeviceDesc = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_DEVICEDESC);
                node.EnumeratorName = GetRegistryStringProperty(infoSet, ref devInfo, SPDRP_ENUMERATOR_NAME);
                node.PnpId = DeviceTweakerPathHelpers.ToPnpId(node.InstanceId);
                node.VidPid = ExtractVidPidPairFromNode(node);
                node.VenDev = ExtractVenDevFromNode(node);
                node.IsPresent = IsDevInstPresent(devInfo.DevInst);
                nodes.Add(node);

                index++;
            }
        }
        finally
        {
            SetupDiDestroyDeviceInfoList(infoSet);
        }

        return nodes;
    }

    private static string NormalizeDeviceInstanceId(string instanceId)
    {
        if (String.IsNullOrWhiteSpace(instanceId)) { return null; }
        string normalized = DeviceTweakerPathHelpers.NormalizeLookupText(instanceId);
        return String.IsNullOrWhiteSpace(normalized) ? instanceId.Trim() : normalized;
    }

    private static string ExtractVidPidPairFromNode(DeviceNode node)
    {
        if (node == null) { return null; }
        string pair = DeviceTweakerPathHelpers.ExtractUsbVidPidColonKey(node.InstanceId);
        if (!String.IsNullOrWhiteSpace(pair)) { return pair; }
        if (node.HardwareIds != null)
        {
            for (int i = 0; i < node.HardwareIds.Length; i++)
            {
                pair = DeviceTweakerPathHelpers.ExtractUsbVidPidColonKey(node.HardwareIds[i]);
                if (!String.IsNullOrWhiteSpace(pair)) { return pair; }
            }
        }
        if (node.CompatibleIds != null)
        {
            for (int i = 0; i < node.CompatibleIds.Length; i++)
            {
                pair = DeviceTweakerPathHelpers.ExtractUsbVidPidColonKey(node.CompatibleIds[i]);
                if (!String.IsNullOrWhiteSpace(pair)) { return pair; }
            }
        }
        return null;
    }

    private static string ExtractVenDevFromNode(DeviceNode node)
    {
        if (node == null) { return null; }
        string venDev = DeviceTweakerPathHelpers.ExtractPciVenDevToken(node.InstanceId);
        if (!String.IsNullOrWhiteSpace(venDev)) { return venDev; }
        if (node.HardwareIds != null)
        {
            for (int i = 0; i < node.HardwareIds.Length; i++)
            {
                venDev = DeviceTweakerPathHelpers.ExtractPciVenDevToken(node.HardwareIds[i]);
                if (!String.IsNullOrWhiteSpace(venDev)) { return venDev; }
            }
        }
        if (node.CompatibleIds != null)
        {
            for (int i = 0; i < node.CompatibleIds.Length; i++)
            {
                venDev = DeviceTweakerPathHelpers.ExtractPciVenDevToken(node.CompatibleIds[i]);
                if (!String.IsNullOrWhiteSpace(venDev)) { return venDev; }
            }
        }
        return null;
    }

    private static string GetRegistryStringProperty(IntPtr infoSet, ref SP_DEVINFO_DATA devInfo, uint property)
    {
        string[] values = GetRegistryMultiStringProperty(infoSet, ref devInfo, property);
        if (values == null || values.Length == 0) { return null; }
        return values[0];
    }

    private static string[] GetRegistryMultiStringProperty(IntPtr infoSet, ref SP_DEVINFO_DATA devInfo, uint property)
    {
        uint propType;
        int required;
        byte[] buffer = new byte[1024];

        bool ok = SetupDiGetDeviceRegistryProperty(infoSet, ref devInfo, property, out propType, buffer, buffer.Length, out required);
        if (!ok && required > buffer.Length && required < 1024 * 1024)
        {
            buffer = new byte[required];
            ok = SetupDiGetDeviceRegistryProperty(infoSet, ref devInfo, property, out propType, buffer, buffer.Length, out required);
        }
        if (!ok) { return new string[0]; }

        int byteCount = required;
        if (byteCount <= 0 || byteCount > buffer.Length) { byteCount = buffer.Length; }
        string raw = Encoding.Unicode.GetString(buffer, 0, byteCount).TrimEnd('\0');
        if (String.IsNullOrWhiteSpace(raw)) { return new string[0]; }

        string[] parts = raw.Split(new char[] { '\0' }, StringSplitOptions.RemoveEmptyEntries);
        List<string> clean = new List<string>();
        for (int i = 0; i < parts.Length; i++)
        {
            string s = parts[i];
            if (!String.IsNullOrWhiteSpace(s)) { clean.Add(s.Trim()); }
        }
        return clean.ToArray();
    }

    private static bool IsDevInstPresent(uint devInst)
    {
        if (devInst == 0) { return false; }
        uint status;
        uint problem;
        int cr = CM_Get_DevNode_Status(out status, out problem, devInst, 0);
        return cr == CR_SUCCESS && (status & DN_PRESENT) != 0;
    }

    private static string GetParentDeviceIdFromDevInst(uint devInst)
    {
        if (devInst == 0) { return null; }
        uint parentDevInst;
        int cr = CM_Get_Parent(out parentDevInst, devInst, 0);
        if (cr != CR_SUCCESS || parentDevInst == 0) { return null; }
        return GetDeviceIdFromDevInst(parentDevInst);
    }

    private static List<UsbControllerAssociationRecord> BuildControllerAssociationsFromDeviceNodes(List<DeviceNode> nodes, ICollection<string> controllerIds)
    {
        return BuildControllerAssociationsFromDeviceNodes(nodes, controllerIds, null);
    }

    private static List<UsbControllerAssociationRecord> BuildControllerAssociationsFromDeviceNodes(List<DeviceNode> nodes, ICollection<string> controllerIds, Dictionary<string, List<DeviceNode>> childrenByParent)
    {
        List<UsbControllerAssociationRecord> records = new List<UsbControllerAssociationRecord>();
        if (nodes == null || controllerIds == null || controllerIds.Count == 0) { return records; }

        Dictionary<string, List<DeviceNode>> childMap = childrenByParent;
        if (childMap == null || childMap.Count == 0)
        {
            childMap = new Dictionary<string, List<DeviceNode>>(StringComparer.OrdinalIgnoreCase);
            for (int i = 0; i < nodes.Count; i++)
            {
                DeviceNode node = nodes[i];
                if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
                string parent = !String.IsNullOrWhiteSpace(node.ParentInstanceId) ? node.ParentInstanceId : node.NormalizedParentInstanceId;
                if (String.IsNullOrWhiteSpace(parent)) { continue; }
                List<DeviceNode> children;
                if (!childMap.TryGetValue(parent, out children)) { children = new List<DeviceNode>(); childMap[parent] = children; }
                children.Add(node);
                if (!String.IsNullOrWhiteSpace(node.NormalizedParentInstanceId) && !String.Equals(parent, node.NormalizedParentInstanceId, StringComparison.OrdinalIgnoreCase))
                {
                    if (!childMap.TryGetValue(node.NormalizedParentInstanceId, out children)) { children = new List<DeviceNode>(); childMap[node.NormalizedParentInstanceId] = children; }
                    children.Add(node);
                }
            }
        }

        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (string controllerId in controllerIds)
        {
            if (String.IsNullOrWhiteSpace(controllerId)) { continue; }
            AddControllerDescendants(controllerId, controllerId, childMap, records, seen, 1);
            string normalized = NormalizeDeviceInstanceId(controllerId);
            if (!String.IsNullOrWhiteSpace(normalized) && !String.Equals(normalized, controllerId, StringComparison.OrdinalIgnoreCase))
            {
                AddControllerDescendants(controllerId, normalized, childMap, records, seen, 1);
            }
        }

        return records;
    }

    private static void AddControllerDescendants(string controllerId, string parentKey, Dictionary<string, List<DeviceNode>> childrenByParent, List<UsbControllerAssociationRecord> records, HashSet<string> seen, int depth)
    {
        if (String.IsNullOrWhiteSpace(controllerId) || String.IsNullOrWhiteSpace(parentKey)) { return; }
        if (childrenByParent == null || records == null || seen == null) { return; }
        if (depth > MAX_DEVNODE_ASSOCIATION_DEPTH) { return; }

        List<DeviceNode> children;
        if (!childrenByParent.TryGetValue(parentKey, out children) || children == null) { return; }
        for (int i = 0; i < children.Count; i++)
        {
            DeviceNode child = children[i];
            if (child == null || String.IsNullOrWhiteSpace(child.InstanceId)) { continue; }
            string key = controllerId + "\u001F" + child.InstanceId;
            if (seen.Add(key))
            {
                records.Add(new UsbControllerAssociationRecord { CtrlId = controllerId, DevId = child.InstanceId, Depth = depth });
            }
            AddControllerDescendants(controllerId, child.InstanceId, childrenByParent, records, seen, depth + 1);
            if (!String.IsNullOrWhiteSpace(child.NormalizedInstanceId) && !String.Equals(child.NormalizedInstanceId, child.InstanceId, StringComparison.OrdinalIgnoreCase))
            {
                AddControllerDescendants(controllerId, child.NormalizedInstanceId, childrenByParent, records, seen, depth + 1);
            }
        }
    }

    private static List<HidInterfaceInfo> EnumerateHidInterfacesNative()
    {
        List<HidInterfaceInfo> results = new List<HidInterfaceInfo>();
        Guid guid = HidInterop.GUID_DEVINTERFACE_HID;
        int flags = HidInterop.DIGCF_PRESENT | HidInterop.DIGCF_DEVICEINTERFACE;
        IntPtr devInfo = HidInterop.SetupDiGetClassDevs(ref guid, IntPtr.Zero, IntPtr.Zero, flags);
        if (devInfo == IntPtr.Zero || devInfo == INVALID_HANDLE_VALUE) { return results; }

        try
        {
            int index = 0;
            while (true)
            {
                HidInterop.SP_DEVICE_INTERFACE_DATA iface = new HidInterop.SP_DEVICE_INTERFACE_DATA();
                iface.cbSize = Marshal.SizeOf(typeof(HidInterop.SP_DEVICE_INTERFACE_DATA));
                if (!HidInterop.SetupDiEnumDeviceInterfaces(devInfo, IntPtr.Zero, ref guid, index, ref iface)) { break; }

                HidInterop.SP_DEVICE_INTERFACE_DETAIL_DATA detail = new HidInterop.SP_DEVICE_INTERFACE_DETAIL_DATA();
                detail.cbSize = IntPtr.Size == 8 ? 8 : 5;
                int required = 0;
                if (!HidInterop.SetupDiGetDeviceInterfaceDetail(devInfo, ref iface, ref detail, Marshal.SizeOf(typeof(HidInterop.SP_DEVICE_INTERFACE_DETAIL_DATA)), out required, IntPtr.Zero))
                {
                    index++;
                    continue;
                }

                string devicePath = detail.DevicePath;
                string product = "<none>";
                IntPtr handle = HidInterop.CreateFile(devicePath, 0, FILE_SHARE_READ | FILE_SHARE_WRITE, IntPtr.Zero, OPEN_EXISTING, 0, IntPtr.Zero);
                if (handle != IntPtr.Zero && handle != INVALID_HANDLE_VALUE)
                {
                    try
                    {
                        byte[] buf = new byte[256];
                        if (HidInterop.HidD_GetProductString(handle, buf, buf.Length))
                        {
                            string productRaw = Encoding.Unicode.GetString(buf).TrimEnd('\0');
                            if (!String.IsNullOrWhiteSpace(productRaw)) { product = productRaw; }
                        }
                    }
                    finally
                    {
                        HidInterop.CloseHandle(handle);
                    }
                }

                results.Add(new HidInterfaceInfo { Product = product, DevicePath = devicePath, Instance = ParseHidInterfaceInstance(devicePath) });
                index++;
            }
        }
        finally
        {
            HidInterop.SetupDiDestroyDeviceInfoList(devInfo);
        }

        return results;
    }

    private static string ParseHidInterfaceInstance(string devicePath)
    {
        if (String.IsNullOrWhiteSpace(devicePath)) { return null; }
        int marker = devicePath.IndexOf("hid#", StringComparison.OrdinalIgnoreCase);
        if (marker < 0) { return null; }
        int start = marker + 4;
        int end = devicePath.IndexOf('#', start);
        if (end <= start) { return null; }
        string instance = devicePath.Substring(start, end - start).Replace('#', '\\');
        return String.IsNullOrWhiteSpace(instance) ? null : instance.ToUpperInvariant();
    }

    private static Dictionary<string, string> GetHostControllerInstanceIdByPath()
    {
        return BuildHostControllerMapByPath(GetHostControllerInterfaces(null));
    }

    private static List<UsbHostControllerInterfaceInfo> GetHostControllerInterfaces(List<UsbErrorRecord> errors)
    {
        List<UsbHostControllerInterfaceInfo> controllers = new List<UsbHostControllerInterfaceInfo>();
        IntPtr infoSet = SetupDiGetClassDevs(ref GUID_DEVINTERFACE_USB_HOST_CONTROLLER, IntPtr.Zero, IntPtr.Zero, DIGCF_PRESENT | DIGCF_DEVICEINTERFACE);
        if (infoSet == INVALID_HANDLE_VALUE || infoSet == IntPtr.Zero)
        {
            if (errors != null) { AddLastError(errors, "SetupAPI", "SetupDiGetClassDevs", "Failed to enumerate USB host controller interfaces."); }
            return controllers;
        }

        try
        {
            uint index = 0;
            while (true)
            {
                SP_DEVICE_INTERFACE_DATA ifData = new SP_DEVICE_INTERFACE_DATA();
                ifData.cbSize = Marshal.SizeOf(typeof(SP_DEVICE_INTERFACE_DATA));
                bool ok = SetupDiEnumDeviceInterfaces(infoSet, IntPtr.Zero, ref GUID_DEVINTERFACE_USB_HOST_CONTROLLER, index, ref ifData);
                if (!ok)
                {
                    int err = Marshal.GetLastWin32Error();
                    if (err == ERROR_NO_MORE_ITEMS) { break; }
                    if (errors != null) { AddError(errors, "SetupAPI", "SetupDiEnumDeviceInterfaces", err, "Failed while enumerating host controller interface index " + index + "."); }
                    break;
                }

                string path = GetDeviceInterfacePath(infoSet, ref ifData);
                SP_DEVINFO_DATA devInfo;
                string instanceId = null;
                if (TryGetInterfaceDevInfo(infoSet, ref ifData, out devInfo))
                {
                    instanceId = GetSetupDiDeviceInstanceId(infoSet, ref devInfo);
                    if (String.IsNullOrWhiteSpace(instanceId)) { instanceId = GetDeviceIdFromDevInst(devInfo.DevInst); }
                }

                if (String.IsNullOrWhiteSpace(path))
                {
                    if (errors != null) { AddError(errors, "SetupAPI", "GetDeviceInterfacePath", -1, "SetupDiGetDeviceInterfaceDetail returned an empty host controller path for index " + index + "."); }
                    index++;
                    continue;
                }

                UsbHostControllerInterfaceInfo controller = new UsbHostControllerInterfaceInfo();
                controller.Index = controllers.Count;
                controller.HostControllerPath = path;
                controller.InstanceId = instanceId;
                controller.NormalizedInstanceId = NormalizeDeviceInstanceId(instanceId);
                controller.PnpId = DeviceTweakerPathHelpers.ToPnpId(instanceId);
                controllers.Add(controller);
                index++;
            }
        }
        finally
        {
            SetupDiDestroyDeviceInfoList(infoSet);
        }

        return controllers;
    }

    private static string GetDeviceInterfacePath(IntPtr infoSet, ref SP_DEVICE_INTERFACE_DATA ifData)
    {
        uint required = 0;
        SetupDiGetDeviceInterfaceDetail(infoSet, ref ifData, IntPtr.Zero, 0, out required, IntPtr.Zero);
        if (required == 0) { return null; }

        IntPtr detailBuffer = Marshal.AllocHGlobal((int)required);
        try
        {
            Marshal.WriteInt32(detailBuffer, IntPtr.Size == 8 ? 8 : 6);
            bool ok = SetupDiGetDeviceInterfaceDetail(infoSet, ref ifData, detailBuffer, required, out required, IntPtr.Zero);
            if (!ok) { return null; }
            IntPtr pDevicePath = IntPtr.Add(detailBuffer, 4);
            return Marshal.PtrToStringUni(pDevicePath);
        }
        finally
        {
            Marshal.FreeHGlobal(detailBuffer);
        }
    }

    private static List<UsbEndpointInfo> BuildUsbEndpointInfos(UsbEnumerationResult usbEnumeration, List<UsbControllerAssociationRecord> associations, Dictionary<string, string> controllerByPath)
    {
        List<UsbEndpointInfo> infos = new List<UsbEndpointInfo>();
        if (usbEnumeration == null || usbEnumeration.Endpoints == null) { return infos; }
        if (associations == null) { associations = new List<UsbControllerAssociationRecord>(); }
        if (controllerByPath == null) { controllerByPath = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase); }

        Dictionary<string, List<UsbControllerAssociationRecord>> associationsByVidPid = BuildAssociationLookupByVidPid(associations);

        for (int i = 0; i < usbEnumeration.Endpoints.Count; i++)
        {
            UsbEndpointRecord ep = usbEnumeration.Endpoints[i];
            if (ep == null) { continue; }

            string controllerId = null;
            if (!String.IsNullOrWhiteSpace(ep.HostControllerPath)) { controllerByPath.TryGetValue(ep.HostControllerPath, out controllerId); }

            UsbEndpointInfo info = new UsbEndpointInfo();
            info.ControllerInstanceId = controllerId;
            info.DeviceInstanceId = ResolveEndpointDeviceInstanceId(controllerId, ep, associationsByVidPid);
            info.Vid = NormalizeHex4(ep.VendorId);
            info.Pid = NormalizeHex4(ep.ProductId);
            info.InterfaceNumber = ep.InterfaceNumber;
            info.EndpointAddress = ParseEndpointAddress(ep.EndpointAddress);
            info.BInterval = ep.bInterval;
            info.Speed = ep.Speed;
            info.TransferType = ep.TransferType;
            info.Direction = ep.Direction;
            infos.Add(info);
        }

        return infos;
    }

    private static Dictionary<string, List<UsbControllerAssociationRecord>> BuildAssociationLookupByVidPid(List<UsbControllerAssociationRecord> associations)
    {
        Dictionary<string, List<UsbControllerAssociationRecord>> lookup = new Dictionary<string, List<UsbControllerAssociationRecord>>(StringComparer.OrdinalIgnoreCase);
        if (associations == null) { return lookup; }
        for (int i = 0; i < associations.Count; i++)
        {
            UsbControllerAssociationRecord assoc = associations[i];
            if (assoc == null || String.IsNullOrWhiteSpace(assoc.DevId)) { continue; }
            string vidPid = DeviceTweakerPathHelpers.ExtractUsbVidPidColonKey(assoc.DevId);
            if (String.IsNullOrWhiteSpace(vidPid)) { continue; }
            List<UsbControllerAssociationRecord> list;
            if (!lookup.TryGetValue(vidPid, out list)) { list = new List<UsbControllerAssociationRecord>(); lookup[vidPid] = list; }
            list.Add(assoc);
        }
        return lookup;
    }

    private static string ResolveEndpointDeviceInstanceId(string controllerId, UsbEndpointRecord ep, Dictionary<string, List<UsbControllerAssociationRecord>> associationsByVidPid)
    {
        if (ep == null || associationsByVidPid == null) { return null; }
        string vid = NormalizeHex4(ep.VendorId);
        string pid = NormalizeHex4(ep.ProductId);
        if (String.IsNullOrWhiteSpace(vid) || String.IsNullOrWhiteSpace(pid)) { return null; }

        string vidPid = vid + ":" + pid;
        List<UsbControllerAssociationRecord> candidates;
        if (!associationsByVidPid.TryGetValue(vidPid, out candidates) || candidates == null || candidates.Count == 0) { return null; }

        string miToken = ep.InterfaceNumber >= 0 ? ("MI_" + ep.InterfaceNumber.ToString("X2")) : null;
        string best = null;
        int bestScore = Int32.MinValue;

        for (int i = 0; i < candidates.Count; i++)
        {
            UsbControllerAssociationRecord assoc = candidates[i];
            if (assoc == null || String.IsNullOrWhiteSpace(assoc.DevId)) { continue; }
            if (!String.IsNullOrWhiteSpace(controllerId) && !String.IsNullOrWhiteSpace(assoc.CtrlId) && !String.Equals(controllerId, assoc.CtrlId, StringComparison.OrdinalIgnoreCase)) { continue; }

            string id = assoc.DevId;
            int score = 10;
            if (!String.IsNullOrWhiteSpace(miToken))
            {
                if (id.IndexOf(miToken, StringComparison.OrdinalIgnoreCase) >= 0) { score += 100; }
                else if (id.IndexOf("MI_", StringComparison.OrdinalIgnoreCase) >= 0) { score -= 5; }
            }
            if (id.StartsWith("USB\\", StringComparison.OrdinalIgnoreCase)) { score += 20; }
            else if (id.StartsWith("HID\\", StringComparison.OrdinalIgnoreCase)) { score += 10; }
            score += Math.Max(0, 64 - assoc.Depth);

            if (score > bestScore) { bestScore = score; best = id; }
        }

        return best;
    }

    private static int ParseEndpointAddress(string endpointAddress)
    {
        if (String.IsNullOrWhiteSpace(endpointAddress)) { return 0; }
        string s = endpointAddress.Trim();
        try
        {
            if (s.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { return Convert.ToInt32(s.Substring(2), 16); }
            return Convert.ToInt32(s, 10);
        }
        catch { return 0; }
    }

    private static string NormalizeHex4(string value)
    {
        if (String.IsNullOrWhiteSpace(value)) { return null; }
        string s = value.Trim();
        if (s.StartsWith("0x", StringComparison.OrdinalIgnoreCase)) { s = s.Substring(2); }
        s = s.ToUpperInvariant();
        if (s.Length > 4) { s = s.Substring(s.Length - 4); }
        while (s.Length < 4) { s = "0" + s; }
        return s;
    }

    public static UsbEnumerationResult Enumerate(bool includeDisconnectedPorts)
    {
        UsbEnumerationResult result = new UsbEnumerationResult();
        List<UsbHostControllerInterfaceInfo> hostControllers = GetHostControllerInterfaces(result.Errors);
        return Enumerate(includeDisconnectedPorts, hostControllers, result.Errors);
    }

    public static UsbEnumerationResult Enumerate(bool includeDisconnectedPorts, List<UsbHostControllerInterfaceInfo> hostControllers)
    {
        return Enumerate(includeDisconnectedPorts, hostControllers, null);
    }

    private static UsbEnumerationResult Enumerate(bool includeDisconnectedPorts, List<UsbHostControllerInterfaceInfo> hostControllers, List<UsbErrorRecord> initialErrors)
    {
        UsbEnumerationResult result = new UsbEnumerationResult();
        if (initialErrors != null) { for (int e = 0; e < initialErrors.Count; e++) { if (initialErrors[e] != null) { result.Errors.Add(initialErrors[e]); } } }
        if (hostControllers == null || hostControllers.Count == 0) { return result; }

        if (hostControllers.Count == 1)
        {
            MergeUsbEnumerationResult(result, EnumerateHostController(hostControllers[0], includeDisconnectedPorts));
            return result;
        }

        Task<UsbEnumerationResult>[] tasks = new Task<UsbEnumerationResult>[hostControllers.Count];
        for (int i = 0; i < hostControllers.Count; i++)
        {
            UsbHostControllerInterfaceInfo controllerForTask = hostControllers[i];
            tasks[i] = Task<UsbEnumerationResult>.Factory.StartNew(
                delegate { return EnumerateHostController(controllerForTask, includeDisconnectedPorts); },
                CancellationToken.None,
                TaskCreationOptions.DenyChildAttach,
                TaskScheduler.Default);
        }

        try { Task.WaitAll(tasks); } catch { }

        for (int i = 0; i < tasks.Length; i++)
        {
            if (tasks[i] == null) { continue; }
            if (tasks[i].Status == TaskStatus.RanToCompletion) { MergeUsbEnumerationResult(result, tasks[i].Result); }
            else if (tasks[i].Exception != null) { AddError(result.Errors, "HC" + i, "Parallel host-controller task", -1, tasks[i].Exception.Flatten().ToString()); }
        }

        return result;
    }

    private static UsbEnumerationResult EnumerateHostController(UsbHostControllerInterfaceInfo controller, bool includeDisconnectedPorts)
    {
        UsbEnumerationResult result = new UsbEnumerationResult();
        if (controller == null || String.IsNullOrWhiteSpace(controller.HostControllerPath)) { return result; }

        int hcIndex = controller.Index >= 0 ? controller.Index : 0;
        string hcPath = controller.HostControllerPath;
        string scope = "HC" + hcIndex;

        try
        {
            using (SafeFileHandle hcHandle = OpenExactPath(hcPath))
            {
                if (hcHandle == null || hcHandle.IsInvalid)
                {
                    AddLastError(result.Errors, scope, "Open host controller", "CreateFile failed for host controller path: " + hcPath);
                    return result;
                }

                string rootHubName = QueryRootHubName(hcHandle, result.Errors, scope);
                if (String.IsNullOrWhiteSpace(rootHubName)) { return result; }

                SafeFileHandle rootHubHandle = null;
                string openedHubPath = null;
                try
                {
                    rootHubHandle = OpenUsbSymbolicName(rootHubName, result.Errors, scope, "Open root hub", out openedHubPath);
                    if (rootHubHandle == null || rootHubHandle.IsInvalid) { return result; }

                    UsbControllerCapabilityRecord controllerCapability = QueryControllerCapability(rootHubHandle, openedHubPath, hcIndex, hcPath, result.Errors, scope);
                    if (controllerCapability != null) { result.ControllerCapabilities.Add(controllerCapability); }

                    EnumerateHub(rootHubHandle, openedHubPath, hcIndex, hcPath, scope, result, includeDisconnectedPorts, 0);
                }
                finally
                {
                    if (rootHubHandle != null) { rootHubHandle.Dispose(); }
                }
            }
        }
        catch (Exception ex)
        {
            AddError(result.Errors, scope, "Unhandled exception", -1, ex.ToString());
        }

        return result;
    }

    private static void MergeUsbEnumerationResult(UsbEnumerationResult target, UsbEnumerationResult source)
    {
        if (target == null || source == null) { return; }
        if (source.Endpoints != null) { for (int i = 0; i < source.Endpoints.Count; i++) { if (source.Endpoints[i] != null) { target.Endpoints.Add(source.Endpoints[i]); } } }
        if (source.Errors != null) { for (int i = 0; i < source.Errors.Count; i++) { if (source.Errors[i] != null) { target.Errors.Add(source.Errors[i]); } } }
        if (source.ControllerCapabilities != null) { for (int i = 0; i < source.ControllerCapabilities.Count; i++) { if (source.ControllerCapabilities[i] != null) { target.ControllerCapabilities.Add(source.ControllerCapabilities[i]); } } }
    }

    public static List<UsbControllerAssociationRecord> EnumerateControllerAssociations()
    {
        List<DeviceNode> nodes = EnumerateDeviceNodesNative();
        Dictionary<string, List<DeviceNode>> childrenByParent = new Dictionary<string, List<DeviceNode>>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < nodes.Count; i++)
        {
            DeviceNode node = nodes[i];
            if (node == null || String.IsNullOrWhiteSpace(node.InstanceId)) { continue; }
            string parent = !String.IsNullOrWhiteSpace(node.ParentInstanceId) ? node.ParentInstanceId : node.NormalizedParentInstanceId;
            if (String.IsNullOrWhiteSpace(parent)) { continue; }
            List<DeviceNode> children;
            if (!childrenByParent.TryGetValue(parent, out children)) { children = new List<DeviceNode>(); childrenByParent[parent] = children; }
            children.Add(node);
            if (!String.IsNullOrWhiteSpace(node.NormalizedParentInstanceId) && !String.Equals(parent, node.NormalizedParentInstanceId, StringComparison.OrdinalIgnoreCase))
            {
                if (!childrenByParent.TryGetValue(node.NormalizedParentInstanceId, out children)) { children = new List<DeviceNode>(); childrenByParent[node.NormalizedParentInstanceId] = children; }
                children.Add(node);
            }
        }
        Dictionary<string, string> controllerByPath = GetHostControllerInstanceIdByPath();
        return BuildControllerAssociationsFromDeviceNodes(nodes, controllerByPath.Values, childrenByParent);
    }

    private static bool TryGetInterfaceDevInfo(IntPtr infoSet, ref SP_DEVICE_INTERFACE_DATA ifData, out SP_DEVINFO_DATA devInfo)
    {
        devInfo = new SP_DEVINFO_DATA();
        devInfo.cbSize = Marshal.SizeOf(typeof(SP_DEVINFO_DATA));

        uint required = 0;
        bool ok = SetupDiGetDeviceInterfaceDetail(
            infoSet,
            ref ifData,
            IntPtr.Zero,
            0,
            out required,
            ref devInfo);

        int err = Marshal.GetLastWin32Error();
        if ((ok || err == ERROR_INSUFFICIENT_BUFFER) && devInfo.DevInst != 0)
        {
            return true;
        }

        if (required == 0)
        {
            return false;
        }

        IntPtr detailBuffer = Marshal.AllocHGlobal((int)required);
        try
        {
            Marshal.WriteInt32(detailBuffer, IntPtr.Size == 8 ? 8 : 6);
            devInfo = new SP_DEVINFO_DATA();
            devInfo.cbSize = Marshal.SizeOf(typeof(SP_DEVINFO_DATA));

            ok = SetupDiGetDeviceInterfaceDetail(
                infoSet,
                ref ifData,
                detailBuffer,
                required,
                out required,
                ref devInfo);

            return ok && devInfo.DevInst != 0;
        }
        finally
        {
            Marshal.FreeHGlobal(detailBuffer);
        }
    }

    private static string GetSetupDiDeviceInstanceId(IntPtr infoSet, ref SP_DEVINFO_DATA devInfo)
    {
        int required = 0;
        StringBuilder sb = new StringBuilder(1024);
        if (SetupDiGetDeviceInstanceId(infoSet, ref devInfo, sb, sb.Capacity, out required))
        {
            return sb.ToString();
        }

        if (required > 0)
        {
            sb = new StringBuilder(required + 2);
            if (SetupDiGetDeviceInstanceId(infoSet, ref devInfo, sb, sb.Capacity, out required))
            {
                return sb.ToString();
            }
        }

        return null;
    }

    private static string GetDeviceIdFromDevInst(uint devInst)
    {
        if (devInst == 0) { return null; }

        uint size = 0;
        int cr = CM_Get_Device_ID_Size(out size, devInst, 0);
        int capacity = (cr == CR_SUCCESS && size > 0 && size < 32768) ? (int)size + 2 : 1024;

        StringBuilder sb = new StringBuilder(capacity);
        cr = CM_Get_Device_ID(devInst, sb, (uint)sb.Capacity, 0);
        if (cr == CR_SUCCESS)
        {
            return sb.ToString();
        }

        return null;
    }

    private static void TraverseDevnodeChildren(
        string controllerId,
        uint parentDevInst,
        List<UsbControllerAssociationRecord> records,
        HashSet<string> seen,
        int depth)
    {
        if (String.IsNullOrWhiteSpace(controllerId)) { return; }
        if (parentDevInst == 0) { return; }
        if (depth > MAX_DEVNODE_ASSOCIATION_DEPTH) { return; }

        uint childDevInst;
        int cr = CM_Get_Child(out childDevInst, parentDevInst, 0);
        if (cr != CR_SUCCESS || childDevInst == 0) { return; }

        while (childDevInst != 0)
        {
            string childId = GetDeviceIdFromDevInst(childDevInst);
            if (!String.IsNullOrWhiteSpace(childId))
            {
                string key = controllerId + "\n" + childId;
                if (seen.Add(key))
                {
                    UsbControllerAssociationRecord rec = new UsbControllerAssociationRecord();
                    rec.CtrlId = controllerId;
                    rec.DevId = childId;
                    rec.Depth = depth;
                    records.Add(rec);
                }
            }

            TraverseDevnodeChildren(controllerId, childDevInst, records, seen, depth + 1);

            uint siblingDevInst;
            cr = CM_Get_Sibling(out siblingDevInst, childDevInst, 0);
            if (cr != CR_SUCCESS || siblingDevInst == 0) { break; }
            childDevInst = siblingDevInst;
        }
    }

    private static List<string> GetHostControllerDevicePaths(List<UsbErrorRecord> errors)
    {
        List<string> paths = new List<string>();
        List<UsbHostControllerInterfaceInfo> controllers = GetHostControllerInterfaces(errors);
        for (int i = 0; i < controllers.Count; i++)
        {
            if (controllers[i] != null && !String.IsNullOrWhiteSpace(controllers[i].HostControllerPath)) { paths.Add(controllers[i].HostControllerPath); }
        }
        return paths;
    }

    private static void EnumerateHub(
        SafeFileHandle hubHandle,
        string hubOpenedPath,
        int hostControllerIndex,
        string hostControllerPath,
        string topologyPrefix,
        UsbEnumerationResult result,
        bool includeDisconnectedPorts,
        int depth)
    {
        if (depth > MAX_TOPOLOGY_DEPTH)
        {
            AddError(result.Errors, topologyPrefix, "Topology depth guard", -1,
                "Stopped recursion because topology depth exceeded " + MAX_TOPOLOGY_DEPTH + ".");
            return;
        }

        int portCount = QueryHubPortCount(hubHandle, result.Errors, topologyPrefix);
        if (portCount <= 0)
        {
            return;
        }

        for (int port = 1; port <= portCount; port++)
        {
            string scope = topologyPrefix + "/Port" + port;
            byte[] conn = QueryConnectionInfo(hubHandle, port, result.Errors, scope);
            if (conn == null)
            {
                continue;
            }

            int status = ToInt32(conn, 31);
            bool connected = status == 1;

            if (!connected && !includeDisconnectedPorts)
            {
                continue;
            }

            bool isHub = conn[24] != 0;
            int deviceAddress = ToUInt16(conn, 25);
            int currentConfigValue = conn[22];
            int maxPacket0 = conn[11];
            string speed = UsbSpeedToString(conn[23]);
            byte[] connV2 = QueryConnectionInfoV2(hubHandle, port);
            if (connV2 != null)
            {
                speed = RefineUsbSpeedWithConnectionInfoV2(speed, connV2);
            }

            string driverKeyName = connected
                ? QueryConnectionDriverKeyName(hubHandle, port, result.Errors, scope)
                : "";

            byte[] deviceDesc = new byte[18];
            Buffer.BlockCopy(conn, 4, deviceDesc, 0, 18);

            string vendorId = ToUInt16(deviceDesc, 8).ToString("X4");
            string productId = ToUInt16(deviceDesc, 10).ToString("X4");
            string usbVersion = BcdToString(ToUInt16(deviceDesc, 2));
            string devClass = "0x" + deviceDesc[4].ToString("X2");
            string devSubClass = "0x" + deviceDesc[5].ToString("X2");
            string devProtocol = "0x" + deviceDesc[6].ToString("X2");
            int numConfigurations = deviceDesc[17];

            if (!connected)
            {
                continue;
            }

            if (numConfigurations > 0)
            {
                int descriptorIndex = -1;
                byte[] config = FindActiveConfigurationDescriptor(
                    hubHandle,
                    port,
                    (byte)currentConfigValue,
                    (byte)numConfigurations,
                    result.Errors,
                    scope,
                    out descriptorIndex);

                if (config != null)
                {
                    ParseConfigurationEndpoints(
                        config,
                        hostControllerIndex,
                        hostControllerPath,
                        hubOpenedPath,
                        scope,
                        port,
                        speed,
                        isHub,
                        deviceAddress,
                        vendorId,
                        productId,
                        usbVersion,
                        devClass,
                        devSubClass,
                        devProtocol,
                        maxPacket0,
                        currentConfigValue,
                        descriptorIndex,
                        driverKeyName,
                        result);
                }
            }

            if (isHub)
            {
                string childHubName = QueryConnectionHubName(hubHandle, port, result.Errors, scope);
                if (String.IsNullOrWhiteSpace(childHubName))
                {
                    continue;
                }

                SafeFileHandle childHubHandle = null;
                string childOpenedPath = null;

                try
                {
                    childHubHandle = OpenUsbSymbolicName(childHubName, result.Errors, scope, "Open downstream hub", out childOpenedPath);
                    if (childHubHandle == null || childHubHandle.IsInvalid)
                    {
                        continue;
                    }

                    EnumerateHub(
                        childHubHandle,
                        childOpenedPath,
                        hostControllerIndex,
                        hostControllerPath,
                        scope,
                        result,
                        includeDisconnectedPorts,
                        depth + 1);
                }
                finally
                {
                    if (childHubHandle != null)
                    {
                        childHubHandle.Dispose();
                    }
                }
            }
        }
    }

    private static void ParseConfigurationEndpoints(
        byte[] config,
        int hostControllerIndex,
        string hostControllerPath,
        string hubOpenedPath,
        string topologyPath,
        int portNumber,
        string speed,
        bool deviceIsHub,
        int deviceAddress,
        string vendorId,
        string productId,
        string usbVersion,
        string devClass,
        string devSubClass,
        string devProtocol,
        int maxPacket0,
        int currentConfigurationValue,
        int configurationDescriptorIndex,
        string driverKeyName,
        UsbEnumerationResult result)
    {
        int currentInterfaceNumber = -1;
        int currentAlternateSetting = -1;
        string currentInterfaceClass = "";
        string currentInterfaceSubClass = "";
        string currentInterfaceProtocol = "";

        int offset = 0;
        while (offset + 2 <= config.Length)
        {
            int bLength = config[offset];
            int bDescriptorType = config[offset + 1];

            if (bLength <= 0) { break; }
            if (offset + bLength > config.Length) { break; }

            if (bDescriptorType == USB_INTERFACE_DESCRIPTOR_TYPE && bLength >= 9)
            {
                currentInterfaceNumber = config[offset + 2];
                currentAlternateSetting = config[offset + 3];
                currentInterfaceClass = "0x" + config[offset + 5].ToString("X2");
                currentInterfaceSubClass = "0x" + config[offset + 6].ToString("X2");
                currentInterfaceProtocol = "0x" + config[offset + 7].ToString("X2");
            }
            else if (bDescriptorType == USB_ENDPOINT_DESCRIPTOR_TYPE && bLength >= 7)
            {
                byte endpointAddressRaw = config[offset + 2];
                byte attributes = config[offset + 3];
                int wMaxPacketSize = ToUInt16(config, offset + 4);
                int interval = config[offset + 6];

                UsbEndpointRecord rec = new UsbEndpointRecord();
                rec.HostControllerIndex = hostControllerIndex;
                rec.HostControllerPath = hostControllerPath;
                rec.HubPath = hubOpenedPath;
                rec.TopologyPath = topologyPath;
                rec.PortNumber = portNumber;
                rec.Speed = speed;
                rec.DeviceIsHub = deviceIsHub;
                rec.DeviceAddress = deviceAddress;
                rec.VendorId = vendorId;
                rec.ProductId = productId;
                rec.UsbVersion = usbVersion;
                rec.DeviceClass = devClass;
                rec.DeviceSubClass = devSubClass;
                rec.DeviceProtocol = devProtocol;
                rec.MaxPacketSize0 = maxPacket0;
                rec.CurrentConfigurationValue = currentConfigurationValue;
                rec.ConfigurationDescriptorIndex = configurationDescriptorIndex;
                rec.DriverKeyName = driverKeyName;
                rec.InterfaceNumber = currentInterfaceNumber;
                rec.AlternateSetting = currentAlternateSetting;
                rec.InterfaceClass = currentInterfaceClass;
                rec.InterfaceSubClass = currentInterfaceSubClass;
                rec.InterfaceProtocol = currentInterfaceProtocol;
                rec.EndpointAddress = "0x" + endpointAddressRaw.ToString("X2");
                rec.Direction = ((endpointAddressRaw & 0x80) != 0) ? "IN" : "OUT";
                rec.EndpointNumber = endpointAddressRaw & 0x0F;
                rec.TransferType = TransferTypeToString(attributes & 0x03);
                rec.MaxPacketSize = wMaxPacketSize;
                rec.bInterval = interval;
                rec.IntervalInterpretation = DescribeInterval(attributes & 0x03, speed, interval);
                rec.Note = "";
                result.Endpoints.Add(rec);
            }

            offset += bLength;
        }
    }

    private static byte[] FindActiveConfigurationDescriptor(
        SafeFileHandle hubHandle,
        int port,
        byte currentConfigurationValue,
        byte numConfigurations,
        List<UsbErrorRecord> errors,
        string scope,
        out int descriptorIndex)
    {
        descriptorIndex = -1;
        if (currentConfigurationValue == 0) { return null; }

        for (int i = 0; i < numConfigurations; i++)
        {
            byte[] cfg = QueryConfigurationDescriptor(hubHandle, port, (byte)i, errors, scope);
            if (cfg == null || cfg.Length < 9) { continue; }
            int bConfigurationValue = cfg[5];
            if (bConfigurationValue == currentConfigurationValue)
            {
                descriptorIndex = i;
                return cfg;
            }
        }
        return null;
    }

    private static byte[] QueryConfigurationDescriptor(
        SafeFileHandle hubHandle,
        int port,
        byte descriptorIndex,
        List<UsbErrorRecord> errors,
        string scope)
    {
        byte[] first = BuildDescriptorRequest(port, USB_CONFIGURATION_DESCRIPTOR_TYPE, descriptorIndex, 9);
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_DESCRIPTOR_FROM_NODE_CONNECTION,
            first, first.Length, first, first.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned != first.Length) { return null; }

        int headerOffset = USB_DESCRIPTOR_REQUEST_HEADER_SIZE;
        int wTotalLength = ToUInt16(first, headerOffset + 2);
        if (wTotalLength < 9) { return null; }

        byte[] full = BuildDescriptorRequest(port, USB_CONFIGURATION_DESCRIPTOR_TYPE, descriptorIndex, wTotalLength);
        ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_DESCRIPTOR_FROM_NODE_CONNECTION,
            full, full.Length, full, full.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned != full.Length) { return null; }

        byte[] data = new byte[wTotalLength];
        Buffer.BlockCopy(full, USB_DESCRIPTOR_REQUEST_HEADER_SIZE, data, 0, wTotalLength);
        return data;
    }

    private static byte[] BuildDescriptorRequest(int port, int descriptorType, byte descriptorIndex, int dataLength)
    {
        byte[] buffer = new byte[USB_DESCRIPTOR_REQUEST_HEADER_SIZE + dataLength];
        WriteUInt32(buffer, 0, (uint)port);
        WriteUInt16(buffer, 6, (ushort)(((descriptorType & 0xFF) << 8) | descriptorIndex));
        WriteUInt16(buffer, 8, 0);
        WriteUInt16(buffer, 10, (ushort)dataLength);
        return buffer;
    }

    private static UsbControllerCapabilityRecord QueryControllerCapability(
        SafeFileHandle rootHubHandle,
        string rootHubPath,
        int hostControllerIndex,
        string hostControllerPath,
        List<UsbErrorRecord> errors,
        string scope)
    {
        int portCount = -1;
        int highestPortNumberFromInfoEx = -1;
        int hubType = 0;

        byte[] hubInfoEx = QueryHubInformationEx(rootHubHandle);
        if (hubInfoEx != null && hubInfoEx.Length >= 6)
        {
            hubType = ToInt32(hubInfoEx, 0);
            highestPortNumberFromInfoEx = ToUInt16(hubInfoEx, 4);
            if (highestPortNumberFromInfoEx > 0) { portCount = highestPortNumberFromInfoEx; }
        }

        if (portCount <= 0)
        {
            portCount = QueryHubPortCount(rootHubHandle, errors, scope + "/ControllerCapability");
        }

        UsbControllerCapabilityRecord rec = new UsbControllerCapabilityRecord();
        rec.HostControllerIndex = hostControllerIndex;
        rec.HostControllerPath = hostControllerPath;
        rec.RootHubPath = rootHubPath;
        rec.HighestPortNumber = (portCount > 0) ? portCount : 0;
        rec.MaxSpeed = "";
        rec.MaxSpeedRank = 0;
        rec.DetectionMethod = "RootHubPortProtocolCapability";
        rec.PortSummary = "";

        List<string> portSummary = new List<string>();

        if (portCount > 0)
        {
            for (int port = 1; port <= portCount; port++)
            {
                byte[] connV2 = QueryConnectionInfoV2(rootHubHandle, port);
                if (connV2 == null || connV2.Length < USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE)
                {
                    continue;
                }

                uint protocols = BitConverter.ToUInt32(connV2, 8);
                uint flags = BitConverter.ToUInt32(connV2, 12);
                UsbSpeedSpec spec = UsbPortProtocolCapabilityToSpec(protocols, flags);
                if (spec == null) { continue; }

                portSummary.Add("P" + port.ToString() + ":" + spec.Label);
                if (spec.Rank > rec.MaxSpeedRank)
                {
                    rec.MaxSpeed = spec.Label;
                    rec.MaxSpeedRank = spec.Rank;
                }
            }
        }

        if (rec.MaxSpeedRank <= 0 && hubType > 0)
        {
            UsbSpeedSpec hubTypeSpec = UsbHubTypeToSpec(hubType);
            if (hubTypeSpec != null)
            {
                rec.MaxSpeed = hubTypeSpec.Label;
                rec.MaxSpeedRank = hubTypeSpec.Rank;
                rec.DetectionMethod = "HubInformationExType";
            }
        }

        rec.PortSummary = String.Join(", ", portSummary.ToArray());
        return rec;
    }

    private sealed class UsbSpeedSpec
    {
        public string Label;
        public int Rank;
        public UsbSpeedSpec(string label, int rank)
        {
            Label = label;
            Rank = rank;
        }
    }

    private static UsbSpeedSpec UsbPortProtocolCapabilityToSpec(uint protocols, uint flags)
    {
        bool supportsUsb300 = (protocols & 0x00000004) != 0;
        bool supportsUsb200 = (protocols & 0x00000002) != 0;
        bool supportsUsb110 = (protocols & 0x00000001) != 0;
        bool superSpeedPlusCapable = (flags & 0x00000008) != 0;
        bool superSpeedPlusOperating = (flags & 0x00000004) != 0;

        if (supportsUsb300 && (superSpeedPlusCapable || superSpeedPlusOperating))
        {
            return new UsbSpeedSpec("USB 3.2 Gen 2x1 (10 Gbps)", 3210);
        }
        if (supportsUsb300)
        {
            return new UsbSpeedSpec("USB 3.2 Gen 1x1 (5 Gbps)", 3205);
        }
        if (supportsUsb200)
        {
            return new UsbSpeedSpec("USB 2.0 High-Speed (480 Mbps)", 2000);
        }
        if (supportsUsb110)
        {
            return new UsbSpeedSpec("USB 1.1 Full-Speed (12 Mbps)", 1100);
        }
        return null;
    }

    private static UsbSpeedSpec UsbHubTypeToSpec(int hubType)
    {
        switch (hubType)
        {
            case 3: return new UsbSpeedSpec("USB 3.2 Gen 1x1 (5 Gbps)", 3205);
            case 2: return new UsbSpeedSpec("USB 2.0 High-Speed (480 Mbps)", 2000);
            default: return null;
        }
    }

    private static byte[] QueryHubInformationEx(SafeFileHandle hubHandle)
    {
        byte[] buffer = new byte[USB_HUB_INFORMATION_EX_BUFFER_SIZE];
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_HUB_INFORMATION_EX,
            buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < 6) { return null; }
        return buffer;
    }

    private static int QueryHubPortCount(SafeFileHandle hubHandle, List<UsbErrorRecord> errors, string scope)
    {
        byte[] buffer = new byte[USB_NODE_INFORMATION_BUFFER_SIZE];
        WriteUInt32(buffer, 0, 0);
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_NODE_INFORMATION,
            buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < 7) { return -1; }
        return buffer[6];
    }

    private static byte[] QueryConnectionInfo(SafeFileHandle hubHandle, int port, List<UsbErrorRecord> errors, string scope)
    {
        byte[] buffer = new byte[USB_NODE_CONNECTION_INFORMATION_EX_SIZE];
        WriteUInt32(buffer, 0, (uint)port);
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_NODE_CONNECTION_INFORMATION_EX,
            buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < USB_NODE_CONNECTION_INFORMATION_EX_SIZE) { return null; }
        return buffer;
    }

    private static byte[] QueryConnectionInfoV2(SafeFileHandle hubHandle, int port)
    {
        byte[] buffer = new byte[USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE];
        WriteUInt32(buffer, 0, (uint)port);
        WriteUInt32(buffer, 4, (uint)USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE);
        WriteUInt32(buffer, 8, 0x00000007);
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, IOCTL_USB_GET_NODE_CONNECTION_INFORMATION_EX_V2,
            buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE) { return null; }
        return buffer;
    }

    private static string RefineUsbSpeedWithConnectionInfoV2(string speed, byte[] connV2)
    {
        if (connV2 == null || connV2.Length < USB_NODE_CONNECTION_INFORMATION_EX_V2_SIZE) { return speed; }
        uint flags = BitConverter.ToUInt32(connV2, 12);
        if ((flags & 0x00000004) != 0) { return "SuperPlus"; }
        if ((flags & 0x00000001) != 0) { return "Super"; }
        return speed;
    }

    private static string QueryRootHubName(SafeFileHandle hostControllerHandle, List<UsbErrorRecord> errors, string scope)
    {
        byte[] buffer = new byte[LARGE_NAME_BUFFER];
        int bytesReturned;
        bool ok = DeviceIoControl(hostControllerHandle, IOCTL_USB_GET_ROOT_HUB_NAME,
            IntPtr.Zero, 0, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < 4) { return null; }
        int actualLength = ToInt32(buffer, 0);
        if (actualLength < 4 || actualLength > buffer.Length) { return null; }
        return DecodeUnicodeString(buffer, 4, actualLength - 4);
    }

    private static string QueryConnectionHubName(SafeFileHandle hubHandle, int port, List<UsbErrorRecord> errors, string scope)
    {
        return QueryConnectionUnicodeField(hubHandle, IOCTL_USB_GET_NODE_CONNECTION_NAME, port, errors, scope, "Get downstream hub name");
    }

    private static string QueryConnectionDriverKeyName(SafeFileHandle hubHandle, int port, List<UsbErrorRecord> errors, string scope)
    {
        return QueryConnectionUnicodeField(hubHandle, IOCTL_USB_GET_NODE_CONNECTION_DRIVERKEY_NAME, port, errors, scope, "Get driver key name");
    }

    private static string QueryConnectionUnicodeField(SafeFileHandle hubHandle, uint ioctl, int port,
        List<UsbErrorRecord> errors, string scope, string step)
    {
        byte[] buffer = new byte[LARGE_NAME_BUFFER];
        WriteUInt32(buffer, 0, (uint)port);
        int bytesReturned;
        bool ok = DeviceIoControl(hubHandle, ioctl, buffer, buffer.Length, buffer, buffer.Length, out bytesReturned, IntPtr.Zero);
        if (!ok || bytesReturned < 8) { return null; }
        int actualLength = ToInt32(buffer, 4);
        if (actualLength < 8 || actualLength > buffer.Length) { return null; }
        return DecodeUnicodeString(buffer, 8, actualLength - 8);
    }

    private static SafeFileHandle OpenUsbSymbolicName(string rawName, List<UsbErrorRecord> errors,
        string scope, string step, out string openedPath)
    {
        openedPath = null;
        if (String.IsNullOrWhiteSpace(rawName)) { return null; }
        List<string> candidates = BuildOpenPathCandidates(rawName);
        foreach (string candidate in candidates)
        {
            SafeFileHandle handle = OpenExactPath(candidate);
            if (handle != null && !handle.IsInvalid) { openedPath = candidate; return handle; }
            if (handle != null) { handle.Dispose(); }
        }
        return null;
    }

    private static List<string> BuildOpenPathCandidates(string rawName)
    {
        List<string> list = new List<string>();
        HashSet<string> seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        Action<string> add = delegate(string s) { if (!String.IsNullOrWhiteSpace(s) && seen.Add(s)) { list.Add(s); } };
        string name = rawName.Trim();
        add(name);
        if (name.StartsWith(@"\??\")) { add(@"\\?\" + name.Substring(4)); }
        if (!(name.StartsWith(@"\\.\") || name.StartsWith(@"\\?\")))
        {
            if (!name.StartsWith(@"\??\")) { add(@"\\.\" + name); }
        }
        return list;
    }

    private static SafeFileHandle OpenExactPath(string path)
    {
        return CreateFile(path, GENERIC_READ | GENERIC_WRITE, FILE_SHARE_READ | FILE_SHARE_WRITE,
            IntPtr.Zero, OPEN_EXISTING, 0, IntPtr.Zero);
    }

    private static void AddLastError(List<UsbErrorRecord> errors, string scope, string step, string details)
    {
        int code = Marshal.GetLastWin32Error();
        AddError(errors, scope, step, code, details);
    }

    private static void AddError(List<UsbErrorRecord> errors, string scope, string step, int win32Code, string details)
    {
        UsbErrorRecord rec = new UsbErrorRecord();
        rec.Scope = scope; rec.Step = step; rec.Win32Code = win32Code;
        rec.Win32Message = (win32Code >= 0) ? new Win32Exception(win32Code).Message : "";
        rec.Details = details;
        errors.Add(rec);
    }

    private static string DecodeUnicodeString(byte[] buffer, int offset, int byteCount)
    {
        if (byteCount <= 0) { return ""; }
        return Encoding.Unicode.GetString(buffer, offset, byteCount).TrimEnd('\0');
    }

    private static int ToInt32(byte[] buffer, int offset) { return BitConverter.ToInt32(buffer, offset); }
    private static ushort ToUInt16(byte[] buffer, int offset) { return BitConverter.ToUInt16(buffer, offset); }
    private static void WriteUInt16(byte[] buffer, int offset, ushort value)
    {
        byte[] tmp = BitConverter.GetBytes(value); buffer[offset] = tmp[0]; buffer[offset + 1] = tmp[1];
    }
    private static void WriteUInt32(byte[] buffer, int offset, uint value)
    {
        byte[] tmp = BitConverter.GetBytes(value);
        buffer[offset] = tmp[0]; buffer[offset + 1] = tmp[1]; buffer[offset + 2] = tmp[2]; buffer[offset + 3] = tmp[3];
    }

    private static string BcdToString(ushort bcd)
    {
        int major = (bcd >> 8) & 0xFF; int minorHigh = (bcd >> 4) & 0x0F; int minorLow = bcd & 0x0F;
        return major.ToString() + "." + minorHigh.ToString() + minorLow.ToString();
    }

    private static string UsbSpeedToString(int speed)
    {
        switch (speed) { case 0: return "Low"; case 1: return "Full"; case 2: return "High"; case 3: return "Super"; default: return "Unknown(" + speed + ")"; }
    }

    private static string TransferTypeToString(int transferType)
    {
        switch (transferType) { case 0: return "Control"; case 1: return "Isochronous"; case 2: return "Bulk"; case 3: return "Interrupt"; default: return "Unknown(" + transferType + ")"; }
    }

    private static string DescribeInterval(int transferType, string speed, int bInterval)
    {
        if (transferType == 0 || transferType == 2) { return "N/A"; }
        if (bInterval <= 0) { return "N/A"; }

        bool highOrSuper = String.Equals(speed, "High", StringComparison.OrdinalIgnoreCase) ||
                           String.Equals(speed, "Super", StringComparison.OrdinalIgnoreCase) ||
                           String.Equals(speed, "SuperPlus", StringComparison.OrdinalIgnoreCase);

        if (transferType == 3)
        {
            if (highOrSuper)
            {
                double microseconds = Math.Pow(2.0, bInterval - 1) * 125.0;
                return FormatDuration(microseconds);
            }
            return bInterval + " ms";
        }
        if (transferType == 1)
        {
            if (highOrSuper)
            {
                double microseconds = Math.Pow(2.0, bInterval - 1) * 125.0;
                return FormatDuration(microseconds);
            }
            return bInterval + " ms";
        }
        return "N/A";
    }

    private static string FormatDuration(double microseconds)
    {
        if (microseconds < 1000.0) { return microseconds.ToString("0.###") + " us"; }
        double milliseconds = microseconds / 1000.0;
        if (milliseconds < 1000.0) { return milliseconds.ToString("0.###") + " ms"; }
        return (milliseconds / 1000.0).ToString("0.###") + " s";
    }
}


