public sealed class HeaderSurfaceItem
{
    private readonly HeaderSurface _owner;
    private string _text;
    private Font _font;
    private Color _foreColor;
    private Color _linkColor;
    private Color _activeLinkColor;
    private bool _isLink;
    private bool _hover;

    internal HeaderSurfaceItem(HeaderSurface owner, string text, Font font, Color foreColor, int left, int top, bool isLink)
    {
        _owner = owner;
        _text = text ?? String.Empty;
        _font = font;
        _foreColor = foreColor;
        _linkColor = foreColor;
        _activeLinkColor = foreColor;
        _isLink = isLink;
        _hover = false;
        Left = left;
        Top = top;
        Size s = HeaderSurface.MeasureTextSize(_text, _font);
        Width = s.Width;
        Height = s.Height;
    }

    public string Text
    {
        get { return _text; }
        set { _text = value ?? String.Empty; RecomputeSize(); _owner.Invalidate(); }
    }

    public Font Font
    {
        get { return _font ?? _owner.Font; }
        set { _font = value; RecomputeSize(); _owner.Invalidate(); }
    }

    public Color ForeColor
    {
        get { return _foreColor; }
        set { _foreColor = value; _owner.Invalidate(Bounds); }
    }

    public Color LinkColor
    {
        get { return _linkColor; }
        set { _linkColor = value; _owner.Invalidate(Bounds); }
    }

    public Color ActiveLinkColor
    {
        get { return _activeLinkColor; }
        set { _activeLinkColor = value; _owner.Invalidate(Bounds); }
    }

    public bool IsLink { get { return _isLink; } set { _isLink = value; _owner.Invalidate(Bounds); } }
    public bool Hover { get { return _hover; } }
    public int Left { get; set; }
    public int Top { get; set; }
    public int Width { get; set; }
    public int Height { get; set; }
    public int Right { get { return _owner.Left + Left + Width; } }
    public int Bottom { get { return _owner.Top + Top + Height; } }
    internal int LocalRight { get { return Left + Width; } }
    internal int LocalBottom { get { return Top + Height; } }
    public Rectangle Bounds { get { return new Rectangle(Left, Top, Width, Height); } }

    public event EventHandler LinkClicked;
    public event EventHandler MouseEnter;
    public event EventHandler MouseLeave;

    internal bool HitTest(Point p)
    {
        return _isLink && Width > 0 && Height > 0 && Bounds.Contains(p);
    }

    internal void SetHover(bool value)
    {
        if (_hover == value) { return; }
        _hover = value;
        if (_hover)
        {
            EventHandler enter = MouseEnter;
            if (enter != null) { enter(this, EventArgs.Empty); }
        }
        else
        {
            EventHandler leave = MouseLeave;
            if (leave != null) { leave(this, EventArgs.Empty); }
        }
        _owner.Invalidate(Bounds);
    }

    internal void RaiseLinkClicked()
    {
        EventHandler handler = LinkClicked;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void Draw(Graphics g)
    {
        if (String.IsNullOrEmpty(_text) || Width <= 0 || Height <= 0) { return; }
        Color color = _isLink ? (_hover ? _activeLinkColor : _linkColor) : _foreColor;
        Font drawFont = Font;
        Font temp = null;
        try
        {
            if (_isLink && (drawFont.Style & FontStyle.Underline) == 0)
            {
                temp = new Font(drawFont, drawFont.Style | FontStyle.Underline);
                drawFont = temp;
            }
            TextRenderer.DrawText(g, _text, drawFont, Bounds, color, _owner.BackColor, TextFormatFlags.NoPadding | TextFormatFlags.Left | TextFormatFlags.Top | TextFormatFlags.NoPrefix);
        }
        finally
        {
            if (temp != null) { temp.Dispose(); }
        }
    }

    private void RecomputeSize()
    {
        Size s = HeaderSurface.MeasureTextSize(_text, Font);
        Width = s.Width;
        Height = s.Height;
    }
}

public sealed class HeaderSurface : Control
{
    public bool Hero { get; set; }
    private readonly List<HeaderSurfaceItem> _items;
    private HeaderSurfaceItem _hoverItem;

    public HeaderSurface()
    {
        _items = new List<HeaderSurfaceItem>();
        _hoverItem = null;
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        BackColor = Color.Black;
        TabStop = false;
        UpdateStyles();
    }

    public HeaderSurfaceItem AddText(string text, Font font, Color foreColor, int left, int top)
    {
        HeaderSurfaceItem item = new HeaderSurfaceItem(this, text, font, foreColor, left, top, false);
        _items.Add(item);
        Invalidate(item.Bounds);
        return item;
    }

    public HeaderSurfaceItem AddLink(string text, Font font, Color linkColor, Color activeLinkColor, int left, int top)
    {
        HeaderSurfaceItem item = new HeaderSurfaceItem(this, text, font, linkColor, left, top, true);
        item.LinkColor = linkColor;
        item.ActiveLinkColor = activeLinkColor;
        _items.Add(item);
        Invalidate(item.Bounds);
        return item;
    }

    public int VirtualBottom
    {
        get
        {
            int bottom = 0;
            foreach (HeaderSurfaceItem item in _items) { if (item.LocalBottom > bottom) { bottom = item.LocalBottom; } }
            return bottom;
        }
    }

    public static Size MeasureTextSize(string text, Font font)
    {
        string measureText = String.IsNullOrEmpty(text) ? " " : text;
        if (font == null) { font = Control.DefaultFont; }
        Size s = TextRenderer.MeasureText(measureText, font, new Size(32767, 32767), TextFormatFlags.NoPadding | TextFormatFlags.NoPrefix);
        if (s.Width < 1) { s.Width = 1; }
        if (s.Height < 1) { s.Height = font.Height + 4; }
        return s;
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);
        e.Graphics.Clear(Hero ? ExovancePalette.Background : BackColor);
        if (Hero) {
            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;
            Rectangle box = new Rectangle(20, 12, Math.Max(2, Width - 42), Math.Max(2, Height - 14));
            using (GraphicsPath path = ExovanceVisuals.Round(box, 14))
            using (SolidBrush fill = new SolidBrush(ExovancePalette.Card))
            using (Pen pen = new Pen(ExovancePalette.Border)) { e.Graphics.FillPath(fill, path); e.Graphics.DrawPath(pen, path); }
            using (Pen mark = new Pen(ExovancePalette.Accent, 4f)) {
                mark.StartCap = LineCap.Round; mark.EndCap = LineCap.Round;
                e.Graphics.DrawLine(mark, 43, 38, 59, 38);
                e.Graphics.DrawLine(mark, 43, 47, 54, 47);
                e.Graphics.DrawLine(mark, 43, 56, 59, 56);
            }
        }
        for (int i = 0; i < _items.Count; i++) { _items[i].Draw(e.Graphics); }
    }

    protected override void OnMouseMove(MouseEventArgs e)
    {
        base.OnMouseMove(e);
        HeaderSurfaceItem hit = HitTestItem(e.Location);
        if (!Object.ReferenceEquals(hit, _hoverItem))
        {
            if (_hoverItem != null) { _hoverItem.SetHover(false); }
            _hoverItem = hit;
            if (_hoverItem != null) { _hoverItem.SetHover(true); }
        }
        Cursor target = hit != null ? Cursors.Hand : DefaultCursor;
        if (!Object.ReferenceEquals(Cursor, target)) { Cursor = target; }
    }

    protected override void OnMouseLeave(EventArgs e)
    {
        if (_hoverItem != null)
        {
            _hoverItem.SetHover(false);
            _hoverItem = null;
        }
        Cursor = DefaultCursor;
        base.OnMouseLeave(e);
    }

    protected override void OnMouseClick(MouseEventArgs e)
    {
        HeaderSurfaceItem hit = HitTestItem(e.Location);
        if (hit != null && e.Button == MouseButtons.Left) { hit.RaiseLinkClicked(); }
        base.OnMouseClick(e);
    }

    private HeaderSurfaceItem HitTestItem(Point p)
    {
        for (int i = _items.Count - 1; i >= 0; i--)
        {
            if (_items[i].HitTest(p)) { return _items[i]; }
        }
        return null;
    }
}

public sealed class RetainedRegistryPathElement
{
    private readonly ReservedCpuSetsSurface _owner;
    private string _title;
    private string _displayPath;
    private string _registryPath;
    private Rectangle _bounds;
    private Rectangle _pathBounds;
    private Rectangle _titleBounds;
    private Rectangle[] _pathLineBounds;
    private string[] _pathLineTexts;
    private int _lineHeight;
    private int _minimumWidth;
    private int _minimumHeight;
    private bool _hover;

    internal RetainedRegistryPathElement(ReservedCpuSetsSurface owner, string title, string displayPath, string registryPath, int left, int top, int width, int height, Font font, Font hoverFont, Color titleColor, Color pathColor, Color hoverColor, Color backColor)
    {
        _owner = owner;
        _title = title ?? String.Empty;
        _displayPath = displayPath ?? String.Empty;
        _registryPath = registryPath ?? String.Empty;
        _minimumWidth = Math.Max(1, width);
        _minimumHeight = Math.Max(1, height);
        _bounds = new Rectangle(left, top, _minimumWidth, _minimumHeight);
        _titleBounds = Rectangle.Empty;
        _pathBounds = Rectangle.Empty;
        _pathLineBounds = new Rectangle[0];
        _pathLineTexts = new string[0];
        _lineHeight = 1;
        Font = font;
        HoverFont = hoverFont;
        TitleColor = titleColor;
        PathColor = pathColor;
        HoverColor = hoverColor;
        BackColor = backColor;
        Cursor = Cursors.Hand;
        _hover = false;
        RecalculatePathBounds();
    }

    public string Title { get { return _title; } set { _title = value ?? String.Empty; RecalculatePathBounds(); _owner.Invalidate(_bounds); } }
    public string DisplayPath { get { return _displayPath; } set { _displayPath = value ?? String.Empty; RecalculatePathBounds(); _owner.Invalidate(_bounds); } }
    public string RegistryPath { get { return _registryPath; } set { _registryPath = value ?? String.Empty; } }
    public Font Font { get; set; }
    public Font HoverFont { get; set; }
    public Color TitleColor { get; set; }
    public Color PathColor { get; set; }
    public Color HoverColor { get; set; }
    public Color BackColor { get; set; }
    public Cursor Cursor { get; set; }
    public int Left { get { return _bounds.Left; } set { SetBounds(value, Top, Width, Height); } }
    public int Top { get { return _bounds.Top; } set { SetBounds(Left, value, Width, Height); } }
    public int Width { get { return _bounds.Width; } set { SetBounds(Left, Top, value, Height); } }
    public int Height { get { return _bounds.Height; } set { SetBounds(Left, Top, Width, value); } }
    public int Right { get { return _bounds.Right; } }
    public int Bottom { get { return _bounds.Bottom; } }
    public Rectangle Bounds { get { return _bounds; } }
    public Rectangle PathBounds { get { return _pathBounds; } }
    public bool Hover { get { return _hover; } }

    public event EventHandler Click;
    public event EventHandler DoubleClick;
    public event EventHandler MouseEnter;
    public event EventHandler MouseLeave;

    public void SetBounds(int left, int top, int width, int height)
    {
        Rectangle old = _bounds;
        _minimumWidth = Math.Max(1, width);
        _minimumHeight = Math.Max(1, height);
        _bounds = new Rectangle(left, top, _minimumWidth, _minimumHeight);
        RecalculatePathBounds();
        _owner.Invalidate(Rectangle.Union(old, _bounds));
    }

    public void Refresh() { _owner.Invalidate(_bounds); }
    public void Invalidate() { _owner.Invalidate(_bounds); }

    internal bool HitTest(Point p)
    {
        for (int i = 0; i < _pathLineBounds.Length; i++)
        {
            if (_pathLineBounds[i].Contains(p)) { return true; }
        }
        return false;
    }

    internal void SetHover(bool value)
    {
        if (_hover == value) { return; }
        _hover = value;
        if (_hover)
        {
            EventHandler enter = MouseEnter;
            if (enter != null) { enter(this, EventArgs.Empty); }
        }
        else
        {
            EventHandler leave = MouseLeave;
            if (leave != null) { leave(this, EventArgs.Empty); }
        }
        _owner.Invalidate(_bounds);
    }

    internal void RaiseClick()
    {
        EventHandler handler = Click;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void RaiseDoubleClick()
    {
        EventHandler handler = DoubleClick;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void Draw(Graphics g)
    {
        using (SolidBrush back = new SolidBrush(BackColor)) { g.FillRectangle(back, _bounds); }
        Font normalFont = Font ?? _owner.Font;
        Font activeFont = (_hover && HoverFont != null) ? HoverFont : normalFont;
        Color activePathColor = _hover ? HoverColor : PathColor;
        TextFormatFlags titleFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        TextFormatFlags pathFlags = TextFormatFlags.Left | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        if (_titleBounds.Width > 0) { TextRenderer.DrawText(g, _title, normalFont, _titleBounds, TitleColor, BackColor, titleFlags); }
        for (int i = 0; i < _pathLineBounds.Length && i < _pathLineTexts.Length; i++)
        {
            TextRenderer.DrawText(g, _pathLineTexts[i], activeFont, _pathLineBounds[i], activePathColor, BackColor, pathFlags);
        }
    }

    private void RecalculatePathBounds()
    {
        Font normalFont = Font ?? _owner.Font;
        Font layoutFont = HoverFont ?? normalFont;
        TextFormatFlags measureFlags = TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
        int normalLineHeight = TextRenderer.MeasureText("Hg", normalFont, new Size(32767, 32767), measureFlags).Height;
        int layoutLineHeight = TextRenderer.MeasureText("Hg", layoutFont, new Size(32767, 32767), measureFlags).Height;
        _lineHeight = Math.Max(1, Math.Max(normalLineHeight, layoutLineHeight));
        Size titleSize = TextRenderer.MeasureText(String.IsNullOrEmpty(_title) ? " " : _title, normalFont, new Size(32767, 32767), measureFlags);
        Size pathSize = TextRenderer.MeasureText(String.IsNullOrEmpty(_displayPath) ? " " : _displayPath, layoutFont, new Size(32767, 32767), measureFlags);
        int titleWidth = Math.Max(1, titleSize.Width + 2);
        int pathWidth = Math.Max(1, pathSize.Width + 2);
        int totalWidth = Math.Max(_minimumWidth, Math.Max(titleWidth, pathWidth));
        int rowGap = 2;
        int totalHeight = (_lineHeight * 2) + rowGap;
        _bounds.Width = Math.Max(1, totalWidth);
        _bounds.Height = Math.Max(_minimumHeight, totalHeight);
        int top = _bounds.Top + Math.Max(0, (_bounds.Height - totalHeight) / 2);
        _titleBounds = new Rectangle(_bounds.Left, top, titleWidth, _lineHeight);
        _pathLineTexts = new string[] { _displayPath };
        _pathLineBounds = new Rectangle[] { new Rectangle(_bounds.Left, top + _lineHeight + rowGap, pathWidth, _lineHeight) };
        _pathBounds = _pathLineBounds[0];
    }

}

public sealed class RetainedButtonElement
{
    private readonly ReservedCpuSetsSurface _owner;
    private string _text;
    private Rectangle _bounds;
    private bool _hover;

    internal RetainedButtonElement(ReservedCpuSetsSurface owner, string text, int left, int top, int width, int height, Font font, Color backColor, Color foreColor, Color borderColor, Color hoverBorderColor)
    {
        _owner = owner;
        _text = text ?? String.Empty;
        _bounds = new Rectangle(left, top, Math.Max(1, width), Math.Max(1, height));
        Font = font;
        BackColor = backColor;
        ForeColor = foreColor;
        BorderColor = borderColor;
        HoverBorderColor = hoverBorderColor;
        Cursor = Cursors.Hand;
        _hover = false;
    }

    public string Text { get { return _text; } set { _text = value ?? String.Empty; _owner.Invalidate(_bounds); } }
    public Font Font { get; set; }
    public Color BackColor { get; set; }
    public Color ForeColor { get; set; }
    public Color BorderColor { get; set; }
    public Color HoverBorderColor { get; set; }
    public Cursor Cursor { get; set; }
    public int Left { get { return _bounds.Left; } set { SetBounds(value, Top, Width, Height); } }
    public int Top { get { return _bounds.Top; } set { SetBounds(Left, value, Width, Height); } }
    public int Width { get { return _bounds.Width; } set { SetBounds(Left, Top, value, Height); } }
    public int Height { get { return _bounds.Height; } set { SetBounds(Left, Top, Width, value); } }
    public int Right { get { return _bounds.Right; } }
    public int Bottom { get { return _bounds.Bottom; } }
    public Rectangle Bounds { get { return _bounds; } }
    public bool Hover { get { return _hover; } }

    public event EventHandler Click;
    public event EventHandler MouseEnter;
    public event EventHandler MouseLeave;

    public void SetBounds(int left, int top, int width, int height)
    {
        Rectangle old = _bounds;
        _bounds = new Rectangle(left, top, Math.Max(1, width), Math.Max(1, height));
        _owner.Invalidate(Rectangle.Union(old, _bounds));
    }

    public void Refresh() { _owner.Invalidate(_bounds); }
    public void Invalidate() { _owner.Invalidate(_bounds); }

    internal bool HitTest(Point p) { return _bounds.Contains(p); }

    internal void SetHover(bool value)
    {
        if (_hover == value) { return; }
        _hover = value;
        if (_hover)
        {
            EventHandler enter = MouseEnter;
            if (enter != null) { enter(this, EventArgs.Empty); }
        }
        else
        {
            EventHandler leave = MouseLeave;
            if (leave != null) { leave(this, EventArgs.Empty); }
        }
        _owner.Invalidate(_bounds);
    }

    internal void RaiseClick()
    {
        EventHandler handler = Click;
        if (handler != null) { handler(this, EventArgs.Empty); }
    }

    internal void Draw(Graphics g)
    {
        using (SolidBrush back = new SolidBrush(BackColor)) { g.FillRectangle(back, _bounds); }
        using (Pen pen = new Pen(_hover ? HoverBorderColor : BorderColor, 1f)) { g.DrawRectangle(pen, _bounds.Left, _bounds.Top, _bounds.Width - 1, _bounds.Height - 1); }
        Font f = Font ?? _owner.Font;
        TextRenderer.DrawText(g, _text, f, _bounds, ForeColor, BackColor, TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);
    }
}

public sealed class ReservedCpuSetsSurface : Control
{
    private readonly List<RetainedButtonElement> _buttons;
    private readonly List<RetainedRegistryPathElement> _registryPathLinks;
    private RetainedButtonElement _hoverButton;
    private RetainedRegistryPathElement _hoverRegistryPathLink;
    private Rectangle _panelBounds;
    private Color _panelBorderColor;

    public ReservedCpuSetsSurface()
    {
        _buttons = new List<RetainedButtonElement>();
        _registryPathLinks = new List<RetainedRegistryPathElement>();
        _hoverButton = null;
        _hoverRegistryPathLink = null;
        _panelBounds = Rectangle.Empty;
        _panelBorderColor = SystemColors.ControlDark;
        SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
        BackColor = Color.Black;
        ForeColor = Color.FromArgb(219,219,219);
        TabStop = false;
        UpdateStyles();
    }

    public void SetPanelBounds(int left, int top, int width, int height)
    {
        Rectangle old = _panelBounds;
        _panelBounds = new Rectangle(left, top, Math.Max(1, width), Math.Max(1, height));
        Invalidate(Rectangle.Union(old, _panelBounds));
    }

    public RetainedButtonElement CreateButton(string text, int left, int top, int width, int height, Font font, Color backColor, Color foreColor, Color borderColor, Color hoverBorderColor)
    {
        RetainedButtonElement button = new RetainedButtonElement(this, text, left, top, width, height, font, backColor, foreColor, borderColor, hoverBorderColor);
        _buttons.Add(button);
        Invalidate(button.Bounds);
        return button;
    }

    public RetainedRegistryPathElement CreateRegistryPathLink(string title, string displayPath, string registryPath, int left, int top, int width, int height, Font font, Font hoverFont, Color titleColor, Color pathColor, Color hoverColor, Color backColor)
    {
        RetainedRegistryPathElement link = new RetainedRegistryPathElement(this, title, displayPath, registryPath, left, top, width, height, font, hoverFont, titleColor, pathColor, hoverColor, backColor);
        _registryPathLinks.Add(link);
        Invalidate(link.Bounds);
        return link;
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        base.OnPaint(e);
        Graphics g = e.Graphics;
        g.Clear(BackColor);
        DrawGroupFrame(g);
        if (_panelBounds.Width > 0 && _panelBounds.Height > 0)
        {
            using (Pen pen = new Pen(_panelBorderColor, 1f)) { g.DrawRectangle(pen, _panelBounds.Left, _panelBounds.Top, _panelBounds.Width - 1, _panelBounds.Height - 1); }
        }
        for (int i = 0; i < _registryPathLinks.Count; i++) { _registryPathLinks[i].Draw(g); }
        for (int i = 0; i < _buttons.Count; i++) { _buttons[i].Draw(g); }
    }

    protected override void OnMouseMove(MouseEventArgs e)
    {
        base.OnMouseMove(e);
        RetainedRegistryPathElement linkHit = HitTestRegistryPathLink(e.Location);
        RetainedButtonElement buttonHit = linkHit == null ? HitTestButton(e.Location) : null;
        if (!Object.ReferenceEquals(linkHit, _hoverRegistryPathLink))
        {
            if (_hoverRegistryPathLink != null) { _hoverRegistryPathLink.SetHover(false); }
            _hoverRegistryPathLink = linkHit;
            if (_hoverRegistryPathLink != null) { _hoverRegistryPathLink.SetHover(true); }
        }
        if (!Object.ReferenceEquals(buttonHit, _hoverButton))
        {
            if (_hoverButton != null) { _hoverButton.SetHover(false); }
            _hoverButton = buttonHit;
            if (_hoverButton != null) { _hoverButton.SetHover(true); }
        }
        Cursor target = linkHit != null ? (linkHit.Cursor ?? Cursors.Hand) : (buttonHit != null ? (buttonHit.Cursor ?? Cursors.Hand) : DefaultCursor);
        if (!Object.ReferenceEquals(Cursor, target)) { Cursor = target; }
    }

    protected override void OnMouseLeave(EventArgs e)
    {
        if (_hoverRegistryPathLink != null)
        {
            _hoverRegistryPathLink.SetHover(false);
            _hoverRegistryPathLink = null;
        }
        if (_hoverButton != null)
        {
            _hoverButton.SetHover(false);
            _hoverButton = null;
        }
        Cursor = DefaultCursor;
        base.OnMouseLeave(e);
    }

    protected override void OnMouseClick(MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left)
        {
            RetainedRegistryPathElement linkHit = HitTestRegistryPathLink(e.Location);
            if (linkHit != null) { linkHit.RaiseClick(); }
            else
            {
                RetainedButtonElement hit = HitTestButton(e.Location);
                if (hit != null) { hit.RaiseClick(); }
            }
        }
        base.OnMouseClick(e);
    }

    protected override void OnMouseDoubleClick(MouseEventArgs e)
    {
        if (e.Button == MouseButtons.Left)
        {
            RetainedRegistryPathElement linkHit = HitTestRegistryPathLink(e.Location);
            if (linkHit != null) { linkHit.RaiseDoubleClick(); }
        }
        base.OnMouseDoubleClick(e);
    }

    private RetainedRegistryPathElement HitTestRegistryPathLink(Point p)
    {
        for (int i = _registryPathLinks.Count - 1; i >= 0; i--)
        {
            if (_registryPathLinks[i].HitTest(p)) { return _registryPathLinks[i]; }
        }
        return null;
    }

    private RetainedButtonElement HitTestButton(Point p)
    {
        for (int i = _buttons.Count - 1; i >= 0; i--)
        {
            if (_buttons[i].HitTest(p)) { return _buttons[i]; }
        }
        return null;
    }

    private void DrawGroupFrame(Graphics g)
    {
        ExovanceVisuals.CardFrame(g, new Rectangle(0, 0, Width, Height), Text, Font);
    }
}

