public static class DeviceTweakerFormFactory
{

    public static DeviceTweakerFontCacheNative CreateFontCache(FontFamily family)
    {
        family = new FontFamily("Segoe UI");
        return new DeviceTweakerFontCacheNative {
            Font9 = new Font(family, 11.0f), Font7_5 = new Font(family, 9.0f),
            Font9Underline = new Font(family, 9.0f, FontStyle.Underline),
            Font10 = new Font(family, 12.0f), Font11 = new Font(family, 12.0f),
            Font12 = new Font(family, 12.0f), Font13 = new Font(family, 13.0f),
            Font22 = new Font(family, 13.0f), Font22Bold = new Font(family, 24.0f, FontStyle.Bold),
            Font26 = new Font(family, 26.0f, FontStyle.Bold), Segoe22 = new Font("Segoe UI Symbol", 20.0f)
        };
    }

    public static Color[] CreateColorCache()
    {
        return new[] { ExovancePalette.Background, ExovancePalette.Text, ExovancePalette.Accent,
            ExovancePalette.Text, ExovancePalette.Violet, Color.FromArgb(153, 255, 225),
            ExovancePalette.Muted, ExovancePalette.Muted, ExovancePalette.Card,
            ExovancePalette.Border, ExovancePalette.Raised, ExovancePalette.Violet, ExovancePalette.Error };
    }

    public static DeviceTweakerMainShellNative CreateMainShell(int width, Font font, Color backColor)
    {
        Form form = new Form();
        form.Text = "EXOVANCE DEVICE TWEAKER v2";
        try
        {
            Rectangle workArea = Screen.FromPoint(Cursor.Position).WorkingArea;
            if (workArea.Width <= 0 || workArea.Height <= 0) { workArea = Screen.PrimaryScreen.WorkingArea; }
            int maxWidth = Math.Max(640, workArea.Width - 24);
            int maxHeight = Math.Max(480, workArea.Height - 24);
            width = Math.Max(1, Math.Min(width, maxWidth));
            form.Size = new Size(width, Math.Min(1000, maxHeight));
            form.MaximumSize = new Size(maxWidth, maxHeight);
        }
        catch
        {
            form.Size = new Size(width, 1000);
        }
        form.BackColor = ExovancePalette.Background;
        form.StartPosition = FormStartPosition.CenterScreen;
        form.AutoScroll = false;
        form.KeyPreview = true;
        form.Font = font;

        Panel panel = new Panel();
        panel.Dock = DockStyle.Fill;
        panel.AutoScroll = false;
        panel.BackColor = backColor;
        panel.Font = font;
        form.Controls.Add(panel);

        return new DeviceTweakerMainShellNative { Form = form, Panel = panel };
    }

    private static Size StablePreferredSize(Control control)
    {
        Size preferred = control.GetPreferredSize(Size.Empty);
        if (preferred.Width <= 0 || preferred.Height <= 0)
        {
            preferred = TextRenderer.MeasureText(control.Text ?? String.Empty, control.Font, new Size(32767, 32767), TextFormatFlags.SingleLine);
        }
        if (preferred.Width < 1) { preferred.Width = 1; }
        if (preferred.Height < 1) { preferred.Height = control.Font.Height + 4; }
        return preferred;
    }

    private static void LockPreferredAutoSize(Control control)
    {
        control.Size = StablePreferredSize(control);
    }

    private static int RightOf(Control control)
    {
        return control.Left + StablePreferredSize(control).Width;
    }

    private static int BottomOf(Control control)
    {
        return control.Top + StablePreferredSize(control).Height;
    }

    private static Label MakeLabel(string text, Font font, Color foreColor, int left, int top)
    {
        Label label = new Label();
        label.Text = text ?? String.Empty;
        label.Font = font;
        label.ForeColor = foreColor;
        label.AutoSize = true;
        label.Left = left;
        label.Top = top;
        LockPreferredAutoSize(label);
        return label;
    }

    private static LinkLabel MakeLink(string text, Font font, Color linkColor, Color activeLinkColor, int left, int top)
    {
        LinkLabel link = new LinkLabel();
        link.Text = text ?? String.Empty;
        link.Font = font;
        link.LinkColor = linkColor;
        link.ActiveLinkColor = activeLinkColor;
        link.AutoSize = true;
        link.Left = left;
        link.Top = top;
        LockPreferredAutoSize(link);
        return link;
    }

    public static DeviceTweakerHeaderControlsNative CreateHeaderControls(Panel panel, Font titleFont, Font linkFont, Color lightGray, Color blue, Color orange)
    {
        DeviceTweakerHeaderControlsNative c = new DeviceTweakerHeaderControlsNative();
        HeaderSurface surface = new HeaderSurface();
        surface.SetBounds(0, 0, panel != null ? Math.Max(360, panel.ClientSize.Width) : 1000, 150);
        surface.BackColor = ExovancePalette.Card;
        surface.Hero = true;
        surface.Font = linkFont ?? Control.DefaultFont;
        surface.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        Font wordmark = new Font("Segoe UI", 24.0f, FontStyle.Bold);
        surface.Disposed += delegate { wordmark.Dispose(); };
        c.Surface = surface;
        c.TitlePrefix = surface.AddText("EXOVANCE", wordmark, ExovancePalette.Text, 78, 25);
        c.Author = surface.AddText("DEVICE TWEAKER  /  V2", linkFont, ExovancePalette.Muted, c.TitlePrefix.LocalRight + 24, 46);
        c.SecretTweakPrefix = surface.AddText("A clearer view of your hardware. Precise control over every change.", linkFont, ExovancePalette.Muted, 42, 80);
        c.SecretTweakBuy = surface.AddText("", linkFont, lightGray, 42, 112);
        c.BeyondServicePrefix = surface.AddText("", linkFont, lightGray, 42, 112);
        c.Service = surface.AddLink("Help", linkFont, ExovancePalette.Accent, ExovancePalette.Text, 42, 112);
        c.BeyondGuidesPrefix = surface.AddText("", linkFont, lightGray, 100, 112);
        c.Guides = surface.AddLink("Credits", linkFont, ExovancePalette.Muted, ExovancePalette.Text, 100, 112);
        c.Gaming = surface.AddText("", linkFont, lightGray, 180, 112);
        c.Logs = surface.AddLink("Логи", linkFont, ExovancePalette.Accent, ExovancePalette.Text, 180, 112);
        c.Feedback = surface.AddText("Ready - no changes applied", linkFont, ExovancePalette.Muted, 400, 112);
        if (panel != null) { panel.Controls.Add(surface); }
        return c;
    }

    private static HeaderSurfaceItem[] GetStatusControlArray(DeviceTweakerStatusControlsNative c)
    {
        return new HeaderSurfaceItem[]
        {
            c.HtTitle, c.HtStatus,
            c.Sep1, c.HeteroTitle, c.HeteroValue,
            c.Sep2, c.CppcTitle, c.CppcValue,
            c.Sep3, c.DualCcdTitle, c.DualCcdValue,
            c.DualCcdPrefPrefix, c.DualCcdPrefValue, c.DualCcdPrefSuffix
        };
    }

    private static int StatusRight(DeviceTweakerStatusControlsNative c)
    {
        int right = 0;
        foreach (HeaderSurfaceItem item in GetStatusControlArray(c))
        {
            if (item == null || String.IsNullOrEmpty(item.Text)) { continue; }
            int itemRight = item.LocalRight;
            if (itemRight > right) { right = itemRight; }
        }
        return right;
    }

    private static void ApplyStatusFont(DeviceTweakerStatusControlsNative c, Font font)
    {
        foreach (HeaderSurfaceItem item in GetStatusControlArray(c))
        {
            if (item == null) { continue; }
            item.Font = font;
        }
    }

    private static int RightOf(HeaderSurfaceItem item)
    {
        return item == null ? 0 : item.LocalRight;
    }

    private static void PositionStatusControls(DeviceTweakerStatusControlsNative c, int left, int top, int sepGap)
    {
        foreach (HeaderSurfaceItem item in GetStatusControlArray(c))
        {
            if (item == null) { continue; }
            item.Top = top;
        }

        c.HtTitle.Left = left;
        c.HtStatus.Left = RightOf(c.HtTitle);

        c.Sep1.Left = RightOf(c.HtStatus) + sepGap;
        c.HeteroTitle.Left = RightOf(c.Sep1) + sepGap;
        c.HeteroValue.Left = RightOf(c.HeteroTitle);

        c.Sep2.Left = RightOf(c.HeteroValue) + sepGap;
        c.CppcTitle.Left = RightOf(c.Sep2) + sepGap;
        c.CppcValue.Left = RightOf(c.CppcTitle);

        c.Sep3.Left = RightOf(c.CppcValue) + sepGap;
        c.DualCcdTitle.Left = RightOf(c.Sep3) + sepGap;
        c.DualCcdValue.Left = RightOf(c.DualCcdTitle);

        c.DualCcdPrefPrefix.Left = RightOf(c.DualCcdValue);
        c.DualCcdPrefValue.Left = RightOf(c.DualCcdPrefPrefix);
        c.DualCcdPrefSuffix.Left = RightOf(c.DualCcdPrefValue);
        if (c.Surface != null) { c.Surface.Invalidate(); }
    }

    private static void FitStatusControls(DeviceTweakerStatusControlsNative c, int left, int top, int maxRight, Font statusFont)
    {
        int[] compactGaps = new int[] { 8, 6, 4, 2, 0 };
        foreach (int gap in compactGaps)
        {
            PositionStatusControls(c, left, top, gap);
            if (maxRight <= 0 || StatusRight(c) <= maxRight) { return; }
        }

        if (maxRight <= 0) { return; }

        float minSize = 10.0f;
        for (float size = statusFont.SizeInPoints - 0.5f; size >= minSize; size -= 0.5f)
        {
            Font fittedFont = new Font(statusFont.FontFamily, size, statusFont.Style, GraphicsUnit.Point);
            ApplyStatusFont(c, fittedFont);
            PositionStatusControls(c, left, top, 0);
            if (StatusRight(c) <= maxRight) { return; }
        }
    }


    public static DeviceTweakerStatusControlsNative CreateStatusControls(Panel panel, int top, int maxRight, string htStatus, Color htColor, bool isHeteroCpu, bool cppcEnabled, bool isDualCcdCpu, bool isDualCcxCpu, string preferredCcd, Font statusFont, Color lightGray, Color orange, Color separatorColor)
    {
        string sep = "\u2502";
        DeviceTweakerStatusControlsNative c = new DeviceTweakerStatusControlsNative();
        HeaderSurface surface = new HeaderSurface();
        surface.Left = 0;
        surface.Top = top;
        surface.Width = panel != null ? Math.Max(360, panel.ClientSize.Width) : 1000;
        surface.Height = Math.Max(1, (statusFont ?? Control.DefaultFont).Height + 8);
        surface.BackColor = panel != null ? panel.BackColor : Color.Black;
        surface.Font = statusFont ?? Control.DefaultFont;
        surface.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        c.Surface = surface;

        c.HtTitle = surface.AddText("SMT  ", statusFont, lightGray, 14, 0);
        c.HtStatus = surface.AddText(htStatus, statusFont, htStatus == "On" ? ExovancePalette.Accent : ExovancePalette.Muted, c.HtTitle.LocalRight, 0);

        c.Sep1 = surface.AddText(sep, statusFont, separatorColor, c.HtStatus.LocalRight, 0);
        c.HeteroTitle = surface.AddText("   Hybrid  ", statusFont, lightGray, c.Sep1.LocalRight, 0);
        c.HeteroValue = surface.AddText(isHeteroCpu ? "On" : "Off", statusFont, isHeteroCpu ? ExovancePalette.Accent : ExovancePalette.Muted, c.HeteroTitle.LocalRight, 0);

        c.Sep2 = surface.AddText(sep, statusFont, separatorColor, c.HeteroValue.LocalRight, 0);
        c.CppcTitle = surface.AddText("   CPPC  ", statusFont, lightGray, c.Sep2.LocalRight, 0);
        c.CppcValue = surface.AddText(cppcEnabled ? "On" : "Off", statusFont, cppcEnabled ? ExovancePalette.Accent : ExovancePalette.Muted, c.CppcTitle.LocalRight, 0);

        c.Sep3 = surface.AddText(sep, statusFont, separatorColor, c.CppcValue.LocalRight, 0);
        c.DualCcdTitle = surface.AddText("   Dual CCD  ", statusFont, lightGray, c.Sep3.LocalRight, 0);
        string dualText = isDualCcdCpu ? "On" : (isDualCcxCpu ? "Double CCX" : "Off");
        c.DualCcdValue = surface.AddText(dualText, statusFont, isDualCcdCpu ? ExovancePalette.Accent : ExovancePalette.Muted, c.DualCcdTitle.LocalRight, 0);

        c.DualCcdPrefPrefix = surface.AddText(isDualCcdCpu ? "(P-CCD - " : String.Empty, statusFont, lightGray, c.DualCcdValue.LocalRight, 0);
        c.DualCcdPrefValue = surface.AddText(isDualCcdCpu ? (preferredCcd ?? String.Empty) : String.Empty, statusFont, orange, c.DualCcdPrefPrefix.LocalRight, 0);
        c.DualCcdPrefSuffix = surface.AddText(isDualCcdCpu ? ")" : String.Empty, statusFont, lightGray, c.DualCcdPrefValue.LocalRight, 0);

        FitStatusControls(c, 14, 0, maxRight, statusFont);
        surface.Height = Math.Max(surface.Height, surface.VirtualBottom + 4);
        if (panel != null) { panel.Controls.Add(surface); }
        return c;
    }


    public static Button CreateActionButton(Panel panel, string text, Font font, Color backColor, Color foreColor, Color borderColor)
    {
        ExovanceActionButton button = new ExovanceActionButton();
        button.Text = text ?? String.Empty;
        button.AccessibleName = button.Text;
        button.Primary = text == "APPLY";
        button.Height = 56;
        button.BackColor = ExovancePalette.Raised;
        button.ForeColor = ExovancePalette.Text;
        button.Font = font;
        button.AutoEllipsis = true;
        button.UseMnemonic = false;
        if (panel != null) { panel.Controls.Add(button); }
        return button;
    }

    public static DeviceTweakerStartupChromeBuildResult BuildStartupChrome(
        Panel panel,
        int formWidth,
        string htStatus,
        Color htColor,
        bool isHeteroCpu,
        bool cppcEnabled,
        bool isDualCcdCpu,
        bool isDualCcxCpu,
        string preferredCcd,
        Font titleFont,
        Font linkFont,
        Font statusFont,
        Font buttonFont,
        Color black,
        Color white,
        Color lightGray,
        Color blue,
        Color orange,
        Color separatorColor)
    {
        DeviceTweakerStartupChromeBuildResult result = new DeviceTweakerStartupChromeBuildResult();
        if (panel == null) { return result; }

        try { panel.SuspendLayout(); } catch { }
        try
        {
            result.Header = CreateHeaderControls(panel, titleFont, linkFont, lightGray, blue, orange);
            int statusTop = 190;
            if (result.Header != null && result.Header.Gaming != null) { statusTop = result.Header.Surface.Bottom + 14; }
            result.Status = CreateStatusControls(
                panel,
                statusTop,
                Math.Max(1, formWidth - 40),
                htStatus,
                htColor,
                isHeteroCpu,
                cppcEnabled,
                isDualCcdCpu,
                isDualCcxCpu,
                preferredCcd,
                statusFont,
                lightGray,
                orange,
                separatorColor);

            Button btnApply = CreateActionButton(panel, "APPLY", buttonFont, black, white, orange);
            Button btnAuto = CreateActionButton(panel, "AUTO OPTIMIZATION", buttonFont, black, white, orange);
            Button btnSecret = CreateActionButton(panel, "ALTERNATE PLAN", buttonFont, black, white, orange);
            Button btnBackup = CreateActionButton(panel, "BACKUP", buttonFont, black, white, orange);
            Button btnReset = CreateActionButton(panel, "RESET", buttonFont, black, white, orange);
            Button[] actionButtons = new Button[] { btnApply, btnAuto, btnSecret, btnBackup, btnReset };

            int btnMarginLeft = 20;
            int btnMarginRight = 20;
            int btnSpacing = 10;
            int scrollBarWidth = 20;
            int totalAvailable = Math.Max(1, formWidth - btnMarginLeft - btnMarginRight - scrollBarWidth - (btnSpacing * (actionButtons.Length - 1)));
            int[] minButtonWidths = new int[actionButtons.Length];
            int totalMinButtonWidth = 0;
            TextFormatFlags buttonMeasureFlags = TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.NoPadding;
            for (int i = 0; i < actionButtons.Length; i++)
            {
                Button b = actionButtons[i];
                Font measureFont = buttonFont ?? (b != null ? b.Font : Control.DefaultFont);
                string measureText = b != null ? (b.Text ?? String.Empty) : String.Empty;
                Size textSize = TextRenderer.MeasureText(measureText, measureFont, new Size(32767, 99), buttonMeasureFlags);
                int minWidth = Math.Max(72, textSize.Width + 34);
                minButtonWidths[i] = minWidth;
                totalMinButtonWidth += minWidth;
            }
            int[] layoutButtonWidths = new int[actionButtons.Length];
            if (totalMinButtonWidth > totalAvailable && totalMinButtonWidth > 0)
            {
                int usedWidth = 0;
                for (int i = 0; i < actionButtons.Length; i++)
                {
                    int remainingButtons = actionButtons.Length - i - 1;
                    int remainingWidth = Math.Max(1, totalAvailable - usedWidth);
                    int scaledWidth = (i == actionButtons.Length - 1) ? remainingWidth : (int)Math.Floor((double)minButtonWidths[i] * (double)totalAvailable / (double)totalMinButtonWidth);
                    scaledWidth = Math.Max(50, Math.Min(remainingWidth - remainingButtons, scaledWidth));
                    layoutButtonWidths[i] = Math.Max(1, scaledWidth);
                    usedWidth += layoutButtonWidths[i];
                }
            }
            else
            {
                int extraButtonWidth = Math.Max(0, totalAvailable - totalMinButtonWidth);
                int extraPerButton = actionButtons.Length > 0 ? (extraButtonWidth / actionButtons.Length) : 0;
                int extraRemainder = actionButtons.Length > 0 ? (extraButtonWidth % actionButtons.Length) : 0;
                for (int i = 0; i < actionButtons.Length; i++)
                {
                    layoutButtonWidths[i] = Math.Max(1, minButtonWidths[i] + extraPerButton + (i < extraRemainder ? 1 : 0));
                }
            }
            int btnTopPos = 230;
            if (result.Status != null && result.Status.Surface != null) { btnTopPos = result.Status.Surface.Bottom + 12; }
            else if (result.Status != null && result.Status.HtStatus != null) { btnTopPos = result.Status.HtStatus.Bottom + 12; }
            int maxBottom = 0;
            int currentButtonLeft = btnMarginLeft;
            for (int i = 0; i < actionButtons.Length; i++)
            {
                Button b = actionButtons[i];
                if (b == null) { continue; }
                b.Width = Math.Max(1, layoutButtonWidths[i]);
                b.Left = currentButtonLeft;
                b.Top = btnTopPos;
                currentButtonLeft += b.Width + btnSpacing;
                if (b.Bottom > maxBottom) { maxBottom = b.Bottom; }
            }

            result.ApplyButton = btnApply;
            result.AutoOptimizeButton = btnAuto;
            result.SecretOptimizeButton = btnSecret;
            result.BackupButton = btnBackup;
            result.ResetButton = btnReset;
            result.ActionButtons = actionButtons;
            result.ActionButtonsBottom = maxBottom;
        }
        finally
        {
            try { panel.ResumeLayout(false); } catch { }
        }
        return result;
    }
}


