                    )
                    Add-Type -TypeDefinition $typeDefinition -ReferencedAssemblies $referencedAssemblies -OutputAssembly ([string]$tmpAssemblyPath) -OutputType Library -ErrorAction Stop
                    $compiledFromSource = $true
                    try {
