    try {
        if (-not [string]::IsNullOrWhiteSpace([string]$script:cachedScriptPath) -and [System.IO.File]::Exists([string]$script:cachedScriptPath)) {
            $scriptFileInfo = [System.IO.FileInfo]::new([string]$script:cachedScriptPath)
            $cacheKey = $cacheKey + '_' + ([string]$scriptFileInfo.Length) + '_' + ([string]$scriptFileInfo.LastWriteTimeUtc.Ticks)
        }
    } catch { }
    $cacheAssemblyPath = Get-DeviceTweakerMergedTypeCacheAssemblyPath -CacheKey $cacheKey
    if (Import-DeviceTweakerCachedMergedTypes -CacheAssemblyPath $cacheAssemblyPath) { return }

    Add-DeviceTweakerMergedTypesFromSource -CacheAssemblyPath $cacheAssemblyPath
