function Get-CachedDeviceTopologySnapshot {
    if ($null -ne $script:cachedDeviceTopologySnapshot) { return $script:cachedDeviceTopologySnapshot }

    $model = Get-DeviceTweakerDiscoveryModel
    if ($model -and $model.TopologySnapshot) {
        $script:cachedDeviceTopologySnapshot = $model.TopologySnapshot
        Set-DeviceTopologyDerivedCaches -Snapshot $script:cachedDeviceTopologySnapshot
        return $script:cachedDeviceTopologySnapshot
    }

    if ($script:deviceTopologyAsyncResult -and $script:deviceTopologyRunspace) {
        try {
            if (-not $script:deviceTopologyAsyncResult.IsCompleted) {
                [void]$script:deviceTopologyAsyncResult.AsyncWaitHandle.WaitOne(15000)
            }
            $raw = @($script:deviceTopologyRunspace.EndInvoke($script:deviceTopologyAsyncResult))
            if ($raw.Count -gt 0 -and $null -ne $raw[0].__DeviceTweakerTopologyNativeError) {
                $script:deviceTopologyPrefetchError = [string]$raw[0].__DeviceTweakerTopologyNativeError
                $script:cachedDeviceTopologySnapshot = $null
            } elseif ($raw.Count -gt 0) {
                $script:cachedDeviceTopologySnapshot = $raw[0]
                Set-DeviceTopologyDerivedCaches -Snapshot $script:cachedDeviceTopologySnapshot
            }
        } catch {
            $script:deviceTopologyPrefetchError = $_.Exception.Message
        } finally {
            try { $script:deviceTopologyRunspace.Dispose() } catch {}
            $script:deviceTopologyRunspace = $null
            $script:deviceTopologyAsyncResult = $null
        }
    }
    if ($null -eq $script:cachedDeviceTopologySnapshot -and ('DeviceTopologyNative' -as [type])) {
        try {
            $script:cachedDeviceTopologySnapshot = [DeviceTopologyNative]::BuildDeviceTopologySnapshot()
            Set-DeviceTopologyDerivedCaches -Snapshot $script:cachedDeviceTopologySnapshot
        } catch {
            $script:deviceTopologyPrefetchError = $_.Exception.Message
            Write-DeviceTweakerPerfFallbackLog "DeviceTopologySnapshot native pass failed | Reason: $($_.Exception.Message)"
        }
    }
    return $script:cachedDeviceTopologySnapshot
}

function Get-DeviceTopologyParentMap {
    if ($script:cachedParentMap -and $script:cachedParentMap.Count -gt 0) { return $script:cachedParentMap }

    $model = Get-DeviceTweakerDiscoveryModel
    if ($model -and $model.ParentByInstanceId -and $model.ParentByInstanceId.Count -gt 0) {
        $script:cachedParentMap = $model.ParentByInstanceId
        return $script:cachedParentMap
    }

    $snap = Get-CachedDeviceTopologySnapshot
    if ($snap) {
        $script:cachedParentMap = Convert-DeviceTopologySnapshotToParentMap -Snapshot $snap
        return $script:cachedParentMap
    }
    return @{}
}


