$script:cppcEventsAsyncResult = $null
$script:isIntelCpuCache = $null
try {
    $script:_cpuRegForCppcStart = Get-ItemProperty -Path 'HKLM:\HARDWARE\DESCRIPTION\System\CentralProcessor\0' -ErrorAction SilentlyContinue
    if ($script:_cpuRegForCppcStart) {
        $script:_cpuVendorForCppcStart = [string]$script:_cpuRegForCppcStart.VendorIdentifier
        $script:_cpuNameForCppcStart   = [string]$script:_cpuRegForCppcStart.ProcessorNameString
        $script:isIntelCpuCache = [bool](
            $script:_cpuVendorForCppcStart -match '(?i)GenuineIntel|Intel' -or
            $script:_cpuNameForCppcStart   -match '(?i)\bIntel\b|Core\(TM\)|Xeon|Celeron|Pentium|Atom'
        )
    }
} catch { $script:isIntelCpuCache = $null }
try { Remove-Variable -Name _cpuRegForCppcStart,_cpuVendorForCppcStart,_cpuNameForCppcStart -Scope Script -ErrorAction SilentlyContinue } catch {}

if (-not ([bool]$script:isIntelCpuCache)) {
    $script:cppcEventsRunspace = New-DeviceTweakerDiscoveryPowerShell
    [void]$script:cppcEventsRunspace.AddScript({
        param([int]$maxEvents)
        try {
            @(Get-WinEvent -FilterHashtable @{
                LogName      = 'System'
                Id           = 55
                ProviderName = 'Microsoft-Windows-Kernel-Processor-Power'
            } -MaxEvents $maxEvents -ErrorAction SilentlyContinue)
        } catch { @() }
    }, $true).AddArgument([Environment]::ProcessorCount * 4)
    $script:cppcEventsAsyncResult = $script:cppcEventsRunspace.BeginInvoke()
}

$script:cachedPhysicalDisks = $null
$script:cachedPhysicalDisksIgnoredUnspecified = @()
function Test-DeviceTweakerPhysicalDiskMediaTypeUnspecified {
    param([AllowNull()][object]$MediaType)
    if ($null -eq $MediaType) { return $false }
    $text = $null
    try { $text = [string]$MediaType } catch { $text = $null }
    if ([string]::IsNullOrWhiteSpace($text)) { return $false }
    $trimmed = $text.Trim()
    return ($trimmed.Equals('Unspecified', [System.StringComparison]::OrdinalIgnoreCase) -or $trimmed -eq '0')
}

function Get-DeviceTweakerPhysicalDiskIdentityText {
    param([AllowNull()][object]$Disk)
    if ($null -eq $Disk) { return '<null>' }
    $parts = [System.Collections.Generic.List[string]]::new()
    foreach ($name in @('DeviceId','FriendlyName','SerialNumber','UniqueId','ObjectId')) {
        try {
            $value = $Disk.$name
            if ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value)) { [void]$parts.Add(($name + '=''' + ([string]$value) + '''')) }
        } catch {}
    }
    if ($parts.Count -eq 0) { return $Disk.ToString() }
    return ($parts -join ' ')
}

function Remove-DeviceTweakerUnspecifiedPhysicalDisks {
    param([AllowNull()][object[]]$PhysicalDisks)
    $filtered = [System.Collections.Generic.List[object]]::new()
    $ignored = [System.Collections.Generic.List[object]]::new()
    foreach ($disk in @($PhysicalDisks)) {
        if ($null -eq $disk) { continue }
        $mediaType = $null
        try { $mediaType = $disk.MediaType } catch { $mediaType = $null }
        if (Test-DeviceTweakerPhysicalDiskMediaTypeUnspecified -MediaType $mediaType) { [void]$ignored.Add($disk); continue }
        [void]$filtered.Add($disk)
    }
    $script:cachedPhysicalDisksIgnoredUnspecified = $ignored.ToArray()
    return $filtered.ToArray()
}

function Get-CachedPhysicalDisks {
    if ($null -eq $script:cachedPhysicalDisks) {
        if ($script:physDiskAsyncResult -and $script:physDiskRunspace) {
            try {
                $script:cachedPhysicalDisks = @(Remove-DeviceTweakerUnspecifiedPhysicalDisks -PhysicalDisks @($script:physDiskRunspace.EndInvoke($script:physDiskAsyncResult)))
            } catch {
                $script:cachedPhysicalDisks = @(Remove-DeviceTweakerUnspecifiedPhysicalDisks -PhysicalDisks @(Get-PhysicalDisk -ErrorAction SilentlyContinue))
            } finally {
                try { $script:physDiskRunspace.Dispose() } catch {}
                $script:physDiskRunspace = $null
                $script:physDiskAsyncResult = $null
            }
        } else {
            $script:cachedPhysicalDisks = @(Remove-DeviceTweakerUnspecifiedPhysicalDisks -PhysicalDisks @(Get-PhysicalDisk -ErrorAction SilentlyContinue))
        }
    }
    return $script:cachedPhysicalDisks
}

$script:cachedWin32DiskDrives = $null
function Get-CachedWin32DiskDrives {
    if ($null -eq $script:cachedWin32DiskDrives) {
        if ($script:win32DiskAsyncResult -and $script:win32DiskRunspace) {
            try {
                $script:cachedWin32DiskDrives = @($script:win32DiskRunspace.EndInvoke($script:win32DiskAsyncResult))
            } catch {
                $script:cachedWin32DiskDrives = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue)
            } finally {
                try { $script:win32DiskRunspace.Dispose() } catch {}
                $script:win32DiskRunspace = $null
                $script:win32DiskAsyncResult = $null
            }
        } else {
            $script:cachedWin32DiskDrives = @(Get-CimInstance Win32_DiskDrive -ErrorAction SilentlyContinue)
        }
    }
    return $script:cachedWin32DiskDrives
}

function Dec-To-Hex($decimal) {
    return "0x$($decimal.ToString('X2'))"
}

function Convert-RWEverythingOutputToUInt64 {
    [CmdletBinding()]
    param(
        [Parameter(Position=0, ValueFromPipeline=$true)][AllowNull()][object]$Stdout,
        [Parameter(Position=1)][AllowNull()][string]$Context
    )

    $raw = if ($null -eq $Stdout) { '' } else { [string]$Stdout }
    $trimmed = $raw.Trim()
    $contextText = if ([string]::IsNullOrWhiteSpace($Context)) { '' } else { (' Context={0}.' -f $Context) }

    if ([string]::IsNullOrWhiteSpace($trimmed)) {
        throw ('RWEverything returned an empty response.{0} RawLength={1}.' -f $contextText, $raw.Length)
    }

    if ($trimmed -match '(?i)(invalid\s+command|unknown\s+command|unrecognized\s+command|bad\s+command|syntax\s+error|command\s+error|unsupported\s+command|not\s+support)') {
        $sample = $trimmed
        if ($sample.Length -gt 1600) { $sample = $sample.Substring(0, 1600) + '...[truncated]' }
        throw ('RWEverything returned a command/parser error.{0} RawOutput={1}' -f $contextText, $sample)
    }

    $matches = [regex]::Matches($trimmed, '(?i)(?:0x[0-9a-f]{1,16}|[0-9a-f]{1,16}h|\b[0-9a-f]{2,16}\b|\b[0-9]{1,20}\b)')
    if ($null -eq $matches -or $matches.Count -eq 0) {
        $sample = $trimmed
        if ($sample.Length -gt 1600) { $sample = $sample.Substring(0, 1600) + '...[truncated]' }
        throw ('RWEverything returned no parseable integer token.{0} RawOutput={1}' -f $contextText, $sample)
    }

    $parseErrors = [System.Collections.Generic.List[string]]::new()
    for ($i = $matches.Count - 1; $i -ge 0; $i--) {
        $token = $matches[$i].Value.Trim()
        try {
            if ($token -match '^(?i)0x[0-9a-f]+$') { return [Convert]::ToUInt64($token.Substring(2), 16) }
            if ($token -match '^(?i)[0-9a-f]+h$') { return [Convert]::ToUInt64($token.Substring(0, $token.Length - 1), 16) }
            if ($token -match '^[0-9]+$') { return [Convert]::ToUInt64($token, 10) }
            return [Convert]::ToUInt64($token, 16)
        } catch {
            [void]$parseErrors.Add(('{0}: {1}' -f $token, $_.Exception.Message))
        }
    }

    $candidateText = (($matches | ForEach-Object { $_.Value }) -join ', ')
    if ($candidateText.Length -gt 800) { $candidateText = $candidateText.Substring(0, 800) + '...[truncated]' }
    $errorText = ($parseErrors.ToArray() -join '; ')
    throw ('RWEverything returned integer-looking token(s), but none fit UInt64.{0} Tokens={1}. ParseErrors={2}' -f $contextText, $candidateText, $errorText)
}

function Get-Value-From-Address($address, $cache = $null) {
    $cacheKey = $null
    if ($null -ne $cache) {
        $cacheKey = ('{0:X16}' -f ([uint64]$address))
        if ($cache.ContainsKey($cacheKey)) { return $cache[$cacheKey] }
    }

    $address = Dec-To-Hex -decimal ([uint64]$address)
    $stdout = Invoke-RWECommand -Command "R32 $($address)"
    $value = Convert-RWEverythingOutputToUInt64 $stdout

    if ($null -ne $cache) { $cache[$cacheKey] = $value }
    return $value
}

function Get-Device-Addresses {
    if ($script:cachedDeviceAddressMapComplete) {
        if ($null -ne $script:cachedDeviceAddressMap) { return $script:cachedDeviceAddressMap }
        return @{}
    }
    $data = @{}
    $resources = Get-WmiObject -Class Win32_PNPAllocatedResource -ComputerName LocalHost -Namespace root\CIMV2
    foreach ($resource in $resources) {
        $deviceId = $resource.Dependent.Split("=")[1].Replace('"', '').Replace("\\", "\")
        $physicalAddress = $resource.Antecedent.Split("=")[1].Replace('"', '')
        if (-not $data.ContainsKey($deviceId) -and $deviceId -and $physicalAddress) {
            $data[$deviceId] = [uint64]$physicalAddress
        }
    }
    $script:cachedDeviceAddressMap = $data
    $script:cachedDeviceAddressMapComplete = $true
    return $data
}

function Is-Admin {
    $currentPrincipal = [Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent())
    return $currentPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

$script:RWEPreflightResult = $null
$script:RWECommandTimeoutMs = 30000
$script:RWEAllowParallelReadCommands = $false
$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))

function Resolve-RWEPath {
    param([AllowNull()][string]$Path)

    $candidates = [System.Collections.Generic.List[string]]::new()
    if (-not [string]::IsNullOrWhiteSpace($Path)) { [void]$candidates.Add([string]$Path) }
    if (-not [string]::IsNullOrWhiteSpace($env:RWE_PATH)) { [void]$candidates.Add([string]$env:RWE_PATH) }

    foreach ($base in @($script:cachedScriptDir, $PSScriptRoot)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$base)) {
            [void]$candidates.Add((Join-Path $base 'Rw.exe'))
            [void]$candidates.Add((Join-Path $base 'RW-Everything\Rw.exe'))
        }
    }

    foreach ($known in @(
        'C:\Program Files (x86)\RW-Everything\Rw.exe',
        'C:\Program Files\RW-Everything\Rw.exe',
        'C:\RW-Everything\Rw.exe'
    )) { [void]$candidates.Add($known) }

    $seen = @{}
    foreach ($candidate in $candidates) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        $expanded = [Environment]::ExpandEnvironmentVariables([string]$candidate)
        if ($seen.ContainsKey($expanded)) { continue }
        $seen[$expanded] = $true
        try {
            if (Test-Path -LiteralPath $expanded -PathType Leaf) {
                return (Get-Item -LiteralPath $expanded -ErrorAction Stop).FullName
            }
        } catch { }
    }

    return $Path
}

function Get-DeviceTweakerDriverBlockDiagnostics {
    param([AllowNull()][string]$ResolvedRWEPath)

    $lines = [System.Collections.Generic.List[string]]::new()

    try {
        $hvciKey = 'HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity'
        $hvci = Get-ItemProperty -Path $hvciKey -Name Enabled -ErrorAction SilentlyContinue
        if ($null -ne $hvci -and [int]$hvci.Enabled -eq 1) {
            [void]$lines.Add('Memory Integrity / HVCI appears enabled. Unsigned or blocked kernel drivers can be refused before RWEverything can open hardware access.')
        }
    } catch { }

    try {
        $ci = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\CI\Config' -Name VulnerableDriverBlocklistEnable -ErrorAction SilentlyContinue
        if ($null -ne $ci -and [int]$ci.VulnerableDriverBlocklistEnable -eq 1) {
            [void]$lines.Add('Microsoft vulnerable-driver blocklist appears enabled. Older hardware-access drivers are commonly blocked by this policy.')
        }
    } catch { }

    try {
        $dg = Get-CimInstance -Namespace root\Microsoft\Windows\DeviceGuard -ClassName Win32_DeviceGuard -ErrorAction SilentlyContinue
        if ($dg) {
            $running = @($dg.SecurityServicesRunning)
            if ($running -contains 2) { [void]$lines.Add('DeviceGuard reports Hypervisor Enforced Code Integrity as running.') }
            if ($running -contains 1) { [void]$lines.Add('DeviceGuard reports Credential Guard / VBS security service as running.') }
        }
    } catch { }

    foreach ($svcName in @('RwDrv','RwDrv64')) {
        try {
            $svc = Get-CimInstance Win32_SystemDriver -Filter "Name='$svcName'" -ErrorAction SilentlyContinue
            if ($svc) {
                [void]$lines.Add(("Driver service {0}: State={1}; Status={2}; Path={3}" -f $svcName, $svc.State, $svc.Status, $svc.PathName))
            }
        } catch { }
        try {
            $svcKey = Get-ItemProperty -Path ("HKLM:\SYSTEM\CurrentControlSet\Services\{0}" -f $svcName) -ErrorAction SilentlyContinue
            if ($svcKey) {
                [void]$lines.Add(("Service registry {0}: Type={1}; Start={2}; ImagePath={3}" -f $svcName, $svcKey.Type, $svcKey.Start, $svcKey.ImagePath))
            }
        } catch { }
    }

    $driverCandidates = [System.Collections.Generic.List[string]]::new()
    try {
        if (-not [string]::IsNullOrWhiteSpace($ResolvedRWEPath) -and (Test-Path -LiteralPath $ResolvedRWEPath -PathType Leaf)) {
            $rweDir = Split-Path -Parent $ResolvedRWEPath
            foreach ($f in @('RwDrv.sys','RwDrv64.sys')) { [void]$driverCandidates.Add((Join-Path $rweDir $f)) }
        }
    } catch { }
    foreach ($f in @(
        "$env:SystemRoot\System32\drivers\RwDrv.sys",
        "$env:SystemRoot\System32\drivers\RwDrv64.sys",
        "$env:SystemRoot\SysWOW64\drivers\RwDrv.sys",
        "$env:SystemRoot\SysWOW64\drivers\RwDrv64.sys"
    )) { [void]$driverCandidates.Add($f) }

    $seen = @{}
    foreach ($driverPath in $driverCandidates) {
        if ([string]::IsNullOrWhiteSpace($driverPath) -or $seen.ContainsKey($driverPath)) { continue }
        $seen[$driverPath] = $true
        try {
            if (Test-Path -LiteralPath $driverPath -PathType Leaf) {
                $sig = Get-AuthenticodeSignature -LiteralPath $driverPath -ErrorAction SilentlyContinue
                $status = if ($sig) { [string]$sig.Status } else { 'Unknown' }
                [void]$lines.Add(("Driver file found: {0}; Authenticode={1}" -f $driverPath, $status))
            }
        } catch { }
    }

    try {
        $start = (Get-Date).AddDays(-14)
        $eventsList = [System.Collections.Generic.List[object]]::new(4)
        foreach ($ev in (Get-WinEvent -FilterHashtable @{ LogName = 'Microsoft-Windows-CodeIntegrity/Operational'; StartTime = $start } -MaxEvents 120 -ErrorAction SilentlyContinue)) {
            if ($ev.Message -match '(?i)rwdrv|rw-everything|rweverything|blocked|vulnerable|unsigned|hash|certificate') {
                [void]$eventsList.Add($ev)
                if ($eventsList.Count -ge 4) { break }
            }
        }
        $events = @($eventsList.ToArray())
        foreach ($ev in $events) {
            $msg = ([string]$ev.Message) -replace "`r?`n", ' '
            if ($msg.Length -gt 260) { $msg = $msg.Substring(0,260) + '...' }
            [void]$lines.Add(("CodeIntegrity event {0}: {1}" -f $ev.Id, $msg))
        }
    } catch { }

    if ($lines.Count -eq 0) { return 'No obvious Windows-side RWEverything driver blocker was detected.' }
    return ($lines.ToArray() -join [Environment]::NewLine)
}

function Initialize-DeviceTweakerRWEverything {
    [CmdletBinding()]
    param(
        [AllowNull()][string]$Path = $rwePath,
        [switch]$Force,
        [switch]$Quiet
    )

    if (Test-DeviceTweakerRWEnNVMeDisabled) {
        $script:RWEPreflightResult = [PSCustomObject]@{ Ready = $false; Path = [string]$Path; Message = 'RWEverything and NVMe feature processing are disabled by $DisableRWEnNVMe.'; Diagnostics = 'DisableRWEnNVMe=True'; LastError = $null; CheckedAt = Get-Date }
        return $script:RWEPreflightResult
    }

    if (-not $Force -and $null -ne $script:RWEPreflightResult) { return $script:RWEPreflightResult }

    $resolvedPath = Resolve-RWEPath -Path $Path
    $problems = [System.Collections.Generic.List[string]]::new()

    try {
        if (-not (Is-Admin)) { [void]$problems.Add('Administrator privileges are required for RWEverything hardware access.') }
    } catch {
        [void]$problems.Add('Could not verify administrator privileges.')
    }

    if ([string]::IsNullOrWhiteSpace($resolvedPath) -or -not (Test-Path -LiteralPath $resolvedPath -PathType Leaf)) {
        [void]$problems.Add(("Rw.exe was not found. Checked the configured path: {0}" -f $Path))
    }

    $diagnostics = Get-DeviceTweakerDriverBlockDiagnostics -ResolvedRWEPath $resolvedPath
    $ready = ($problems.Count -eq 0)
    $message = if ($ready) {
        ("RWEverything preflight passed: {0}" -f $resolvedPath)
    } else {
        ("RWEverything preflight failed: {0}" -f ($problems.ToArray() -join ' '))
    }

    $script:RWEPreflightResult = [PSCustomObject]@{
        Ready       = $ready
        Path        = $resolvedPath
        Message     = $message
        Diagnostics = $diagnostics
        LastError   = $null
        CheckedAt   = Get-Date
    }

    if (-not $Quiet -and -not $ready) {
        Write-Host $message -ForegroundColor Red
        if ($diagnostics) { Write-Host $diagnostics -ForegroundColor Yellow }
    }

    return $script:RWEPreflightResult
}

function Test-RWENotInstalledError {
    param([AllowNull()][object]$ErrorValue)

    $message = if ($null -eq $ErrorValue) { '' } else { [string]$ErrorValue }
    return ($message -match '(?i)(Rw\.exe\s+was\s+not\s+found|Rw\.exe.*not\s+exists|not\s+exists.*Rw\.exe|RWEverything\s+preflight\s+failed:.*Rw\.exe|rweverything.*not\s+installed|rwe\s+not\s+installed)')
}

function Invoke-RWECommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$Command,
        [int]$TimeoutMs = $script:RWECommandTimeoutMs,
        [switch]$AllowEmptyOutput,
        [switch]$ForceSerialized
    )

    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('RWEverything command processing is disabled by $DisableRWEnNVMe.') }

    function ConvertTo-RWECompactText {
        param([AllowNull()][object]$Value, [int]$Limit = 4000)
        $s = if ($null -eq $Value) { '' } else { [string]$Value }
        $s = $s.Replace([string][char]0, '<NUL>').Trim()
        if ($s.Length -gt $Limit) { return ($s.Substring(0, $Limit) + '...[truncated]') }
        return $s
    }

    function Get-RWEProcessSnapshotText {
        param([AllowNull()][string]$ResolvedPath)
        $rows = [System.Collections.Generic.List[string]]::new()
        try {
            foreach ($p in @(Get-CimInstance Win32_Process -Filter "Name='Rw.exe'" -ErrorAction SilentlyContinue)) {
                if ($null -eq $p) { continue }
                $exec = [string]$p.ExecutablePath
                $same = 'unknown'
                if (-not [string]::IsNullOrWhiteSpace($ResolvedPath) -and -not [string]::IsNullOrWhiteSpace($exec)) {
                    $same = [string]([string]::Equals($exec, $ResolvedPath, [System.StringComparison]::OrdinalIgnoreCase))
                }
                if ($same -eq 'False') { continue }
                $startText = ''
                try { if ($p.CreationDate) { $startText = [Management.ManagementDateTimeConverter]::ToDateTime($p.CreationDate).ToString('O') } } catch { }
                [void]$rows.Add(('PID={0}; ParentPID={1}; SameBinary={2}; Start={3}; Executable={4}; CommandLine={5}' -f $p.ProcessId, $p.ParentProcessId, $same, $startText, (ConvertTo-RWECompactText $exec 700), (ConvertTo-RWECompactText ([string]$p.CommandLine) 1200)))
            }
        } catch {
            [void]$rows.Add(('process snapshot failed: {0}' -f $_.Exception.Message))
        }
        if ($rows.Count -eq 0) { return 'none' }
        return ($rows.ToArray() -join ' | ')
    }

    function Clear-RWEInteractiveInstances {
        param([AllowNull()][string]$ResolvedPath)
        $notes = [System.Collections.Generic.List[string]]::new()
        $cmdByPid = @{}
        try {
            foreach ($p in @(Get-CimInstance Win32_Process -Filter "Name='Rw.exe'" -ErrorAction SilentlyContinue)) {
                if ($null -ne $p) { $cmdByPid[[int]$p.ProcessId] = [string]$p.CommandLine }
            }
        } catch {
            [void]$notes.Add(('Could not read Rw.exe command lines: {0}' -f $_.Exception.Message))
        }
        try {
            foreach ($rw in @(Get-Process -Name 'Rw' -ErrorAction SilentlyContinue)) {
                if ($null -eq $rw) { continue }
                $sameBinary = $true
                try {
                    if (-not [string]::IsNullOrWhiteSpace($ResolvedPath)) {
                        $sameBinary = [string]::Equals([string]$rw.MainModule.FileName, $ResolvedPath, [System.StringComparison]::OrdinalIgnoreCase)
                    }
                } catch { $sameBinary = $true }
                if (-not $sameBinary) { continue }
                $pidValue = [int]$rw.Id
                $cmdLine = ''
                if ($cmdByPid.ContainsKey($pidValue)) { $cmdLine = [string]$cmdByPid[$pidValue] }
                if ($cmdLine -match '(?i)(^|[\s"''])/?Command\s*=') {
                    [void]$notes.Add(('Left active command-line Rw.exe PID {0} untouched.' -f $pidValue))
                    continue
                }
                try {
                    if ($rw.MainWindowHandle -ne [IntPtr]::Zero) {
                        [void]$rw.CloseMainWindow()
                        if ($rw.WaitForExit(900)) {
                            [void]$notes.Add(('Closed interactive Rw.exe PID {0} before CLI command.' -f $pidValue))
                            continue
                        }
                    }
                } catch {
                    [void]$notes.Add(('CloseMainWindow failed for Rw.exe PID {0}: {1}' -f $pidValue, $_.Exception.Message))
                }
                try {
                    $rw.Kill()
                    [void]$rw.WaitForExit(900)
                    [void]$notes.Add(('Killed non-command Rw.exe PID {0} before CLI command.' -f $pidValue))
                } catch {
                    [void]$notes.Add(('Could not clear non-command Rw.exe PID {0}: {1}' -f $pidValue, $_.Exception.Message))
                }
            }
        } catch {
            [void]$notes.Add(('Process-lock scan failed: {0}' -f $_.Exception.Message))
        }
        return $notes.ToArray()
    }

    function New-RWECommandFailureMessage {
        param(
            [string]$Reason,
            [AllowNull()][object]$ExitCode,
            [AllowNull()][object]$StdOut,
            [AllowNull()][object]$StdErr,
            [AllowNull()][object]$ExceptionText,
            [AllowNull()][object]$ElapsedMs,
            [AllowNull()][object]$Path,
            [AllowNull()][object]$Arguments,
            [AllowNull()][object]$DriverDiagnostics,
            [AllowNull()][object]$MutexNotes,
            [AllowNull()][object]$ProcessLockNotes,
            [AllowNull()][object]$AttemptHistory
        )
        $lines = [System.Collections.Generic.List[string]]::new()
        [void]$lines.Add(('RWEverything command failed: {0}' -f $Reason))
        [void]$lines.Add(('Command       : {0}' -f $Command))
        [void]$lines.Add(('Path          : {0}' -f $Path))
        [void]$lines.Add(('Arguments     : {0}' -f $Arguments))
        [void]$lines.Add(('TimeoutMs     : {0}' -f ([Math]::Max(1000, $TimeoutMs))))
        if ($null -ne $ElapsedMs) { [void]$lines.Add(('ElapsedMs     : {0:N3}' -f ([double]$ElapsedMs))) }
        if ($null -ne $ExitCode) { [void]$lines.Add(('ExitCode      : {0}' -f $ExitCode)) }
        if ($ExceptionText) { [void]$lines.Add(('Exception     : {0}' -f (ConvertTo-RWECompactText $ExceptionText 2000))) }
        if ($MutexNotes) { [void]$lines.Add(('Mutex         : {0}' -f (ConvertTo-RWECompactText $MutexNotes 3000))) }
        if ($ProcessLockNotes) { [void]$lines.Add(('ProcessLock   : {0}' -f (ConvertTo-RWECompactText $ProcessLockNotes 4000))) }
        if ($AttemptHistory) {
            [void]$lines.Add('AttemptHistory:')
            [void]$lines.Add((ConvertTo-RWECompactText $AttemptHistory 6000))
        }
        $stdOutLength = if ($null -eq $StdOut) { 0 } else { ([string]$StdOut).Length }
        $stdErrLength = if ($null -eq $StdErr) { 0 } else { ([string]$StdErr).Length }
        [void]$lines.Add(('StdOutLength  : {0}' -f $stdOutLength))
        [void]$lines.Add(('StdOut        : {0}' -f (ConvertTo-RWECompactText $StdOut 4000)))
        [void]$lines.Add(('StdErrLength  : {0}' -f $stdErrLength))
        [void]$lines.Add(('StdErr        : {0}' -f (ConvertTo-RWECompactText $StdErr 4000)))
        if ($DriverDiagnostics) {
            [void]$lines.Add('DriverDiagnostics:')
            [void]$lines.Add((ConvertTo-RWECompactText $DriverDiagnostics 6000))
        }
        return ($lines.ToArray() -join [Environment]::NewLine)
    }

    function Invoke-RWECommandOnce {
        param([int]$AttemptNumber, [string]$ResolvedPath)
        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $ResolvedPath
        $escapedCommand = ([string]$Command).Replace('"', '\"')
        $psi.Arguments = ('/Min /NoLogo /Stdout /Stderr /Command="{0}"' -f $escapedCommand)
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        try { $psi.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden } catch { }

        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $psi
        $stdout = ''
        $stderr = ''
        $exitCode = $null
        $exceptionText = $null
        $timedOut = $false
        $sw = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            if (-not $process.Start()) { throw 'Process.Start returned false.' }
            if (-not $process.WaitForExit([Math]::Max(1000, $TimeoutMs))) {
                $timedOut = $true
                try { $process.Kill() } catch { }
                try { [void]$process.WaitForExit(1000) } catch { }
            }
            try { $stdout = $process.StandardOutput.ReadToEnd() } catch { $exceptionText = ('stdout read failed: {0}' -f $_.Exception.Message) }
            try { $stderr = $process.StandardError.ReadToEnd() } catch { if ($exceptionText) { $exceptionText += '; ' }; $exceptionText += ('stderr read failed: {0}' -f $_.Exception.Message) }
            try { $exitCode = $process.ExitCode } catch { if ($exceptionText) { $exceptionText += '; ' }; $exceptionText += ('exit-code read failed: {0}' -f $_.Exception.Message) }
            if ($timedOut) { if ($exceptionText) { $exceptionText += '; ' }; $exceptionText += 'timeout waiting for Rw.exe to exit' }
        } catch {
            $exceptionText = $_.Exception.Message
        } finally {
            $sw.Stop()
            try { $process.Dispose() } catch { }
        }
        return [PSCustomObject]@{
            AttemptNumber = $AttemptNumber
            Arguments = $psi.Arguments
            StdOut = $stdout
            StdErr = $stderr
            ExitCode = $exitCode
            ExceptionText = $exceptionText
            ElapsedMs = $sw.Elapsed.TotalMilliseconds
            TimedOut = $timedOut
        }
    }

    $preflight = Initialize-DeviceTweakerRWEverything -Path $rwePath -Quiet
    if (-not $preflight.Ready) {
        throw ($preflight.Message + [Environment]::NewLine + $preflight.Diagnostics)
    }

    $mutex = $null
    $mutexAcquired = $false
    $mutexNotes = [System.Collections.Generic.List[string]]::new()
    $processLockNotes = [System.Collections.Generic.List[string]]::new()
    $attemptHistory = [System.Collections.Generic.List[string]]::new()
    $last = $null
    $maxAttempts = 4
    $badPattern = '(?i)(driver\s+cannot\s+be\s+loaded|cannot\s+load\s+driver|driver\s+load\s+fail|blocked|unsigned|vulnerable|access\s+denied|invalid\s+command|unknown\s+command|unrecognized\s+command|bad\s+command|syntax\s+error|command\s+error|unsupported\s+command|not\s+support)'

    $parallelReadCandidate = $false
    try {
        $commandModeText = ([string]$Command).Trim()
        $parallelReadCandidate = (-not $ForceSerialized -and $commandModeText -match '^(?i)(R8|R16|R32|R64|R)\s+')
    } catch { $parallelReadCandidate = $false }
    $allowParallelReadCommands = $false
    try {
        $parallelReadFlag = Get-Variable -Name RWEAllowParallelReadCommands -Scope Script -ErrorAction SilentlyContinue
        if ($null -ne $parallelReadFlag) { $allowParallelReadCommands = [bool]$parallelReadFlag.Value }
    } catch { $allowParallelReadCommands = $false }
    $skipGlobalRweMutex = [bool]($parallelReadCandidate -and $allowParallelReadCommands)

    try {
        if (-not $skipGlobalRweMutex) {
        $mutexName = 'Global\DeviceTweaker.RWEverything.CLI.Lock'
        try {
            $mutex = [System.Threading.Mutex]::new($false, $mutexName)
        } catch {
            $mutexName = 'Local\DeviceTweaker.RWEverything.CLI.Lock'
            $mutex = [System.Threading.Mutex]::new($false, $mutexName)
            [void]$mutexNotes.Add(('Global mutex unavailable; using Local mutex. Reason={0}' -f $_.Exception.Message))
        }
        $lockTimeout = [Math]::Max(([Math]::Max(1000, $TimeoutMs) + 15000), 60000)
        $lockWatch = [System.Diagnostics.Stopwatch]::StartNew()
        try {
            $mutexAcquired = $mutex.WaitOne($lockTimeout)
        } catch [System.Threading.AbandonedMutexException] {
            $mutexAcquired = $true
            [void]$mutexNotes.Add('Acquired abandoned RWEverything mutex; previous owner exited while holding it.')
        }
        $lockWatch.Stop()
        [void]$mutexNotes.Add(('Name={0}; Acquired={1}; WaitMs={2:N3}; TimeoutMs={3}' -f $mutexName, $mutexAcquired, $lockWatch.Elapsed.TotalMilliseconds, $lockTimeout))
        if (-not $mutexAcquired) {
            $diagnostics = Get-DeviceTweakerDriverBlockDiagnostics -ResolvedRWEPath ([string]$preflight.Path)
            $msg = New-RWECommandFailureMessage -Reason 'timed out waiting for the RWEverything command mutex' -ExitCode $null -StdOut '' -StdErr '' -ExceptionText $null -ElapsedMs $lockWatch.Elapsed.TotalMilliseconds -Path ([string]$preflight.Path) -Arguments '' -DriverDiagnostics $diagnostics -MutexNotes ($mutexNotes.ToArray() -join '; ') -ProcessLockNotes $null -AttemptHistory $null
            throw $msg
        }

        [void]$processLockNotes.Add(('BeforeCleanup={0}' -f (Get-RWEProcessSnapshotText -ResolvedPath ([string]$preflight.Path))))
        foreach ($n in @(Clear-RWEInteractiveInstances -ResolvedPath ([string]$preflight.Path))) { [void]$processLockNotes.Add($n) }
        [void]$processLockNotes.Add(('AfterCleanup={0}' -f (Get-RWEProcessSnapshotText -ResolvedPath ([string]$preflight.Path))))
        } else {
            [void]$mutexNotes.Add(('ParallelRead=True; Command={0}; Global RWEverything mutex and interactive process cleanup skipped for read-only CLI throughput.' -f (ConvertTo-RWECompactText $Command 700)))
        }

        for ($attempt = 1; $attempt -le $maxAttempts; $attempt++) {
            $last = Invoke-RWECommandOnce -AttemptNumber $attempt -ResolvedPath ([string]$preflight.Path)
            $combined = (([string]$last.StdOut) + [Environment]::NewLine + ([string]$last.StdErr)).Trim()
            $payload = if (-not [string]::IsNullOrWhiteSpace([string]$last.StdOut)) { [string]$last.StdOut } elseif (-not [string]::IsNullOrWhiteSpace([string]$last.StdErr)) { [string]$last.StdErr } else { '' }
            $stdOutLength = if ($null -eq $last.StdOut) { 0 } else { ([string]$last.StdOut).Length }
            $stdErrLength = if ($null -eq $last.StdErr) { 0 } else { ([string]$last.StdErr).Length }
            [void]$attemptHistory.Add(('Attempt {0}/{1}: ExitCode={2}; TimedOut={3}; ElapsedMs={4:N3}; StdOutLength={5}; StdErrLength={6}; Exception={7}' -f $attempt, $maxAttempts, $last.ExitCode, $last.TimedOut, ([double]$last.ElapsedMs), $stdOutLength, $stdErrLength, (ConvertTo-RWECompactText $last.ExceptionText 900)))

            if ($last.ExceptionText -and -not $last.TimedOut) {
                if ($attempt -lt $maxAttempts) {
                    Start-Sleep -Milliseconds ([Math]::Min(600, 40 * [Math]::Pow(2, ($attempt - 1))))
                    continue
                }
                break
            }

            if ($combined -match $badPattern) { break }

            if (-not $AllowEmptyOutput -and -not [string]::IsNullOrWhiteSpace($payload)) {
                return $payload
            }

            if ($AllowEmptyOutput -and $last.ExitCode -eq 0) {
                return $payload
            }

            if ($attempt -lt $maxAttempts) {
                Start-Sleep -Milliseconds ([Math]::Min(600, 40 * [Math]::Pow(2, ($attempt - 1))))
                continue
            }
        }

        $lastStdOut = if ($null -eq $last) { '' } else { [string]$last.StdOut }
        $lastStdErr = if ($null -eq $last) { '' } else { [string]$last.StdErr }
        $lastCombined = ($lastStdOut + [Environment]::NewLine + $lastStdErr).Trim()
        $lastPayload = if (-not [string]::IsNullOrWhiteSpace($lastStdOut)) { $lastStdOut } elseif (-not [string]::IsNullOrWhiteSpace($lastStdErr)) { $lastStdErr } else { '' }
        $lastExitCode = if ($null -eq $last) { $null } else { $last.ExitCode }
        $lastElapsed = if ($null -eq $last) { $null } else { $last.ElapsedMs }
        $lastException = if ($null -eq $last) { $null } else { $last.ExceptionText }
        $diagnostics = Get-DeviceTweakerDriverBlockDiagnostics -ResolvedRWEPath ([string]$preflight.Path)
        if ($null -eq $last) { $reason = 'no RWEverything command attempt was executed' }
        elseif ($last.TimedOut) { $reason = 'timeout waiting for Rw.exe to exit' }
        elseif ($lastException) { $reason = 'process execution exception' }
        elseif ($lastCombined -match $badPattern) { $reason = 'RWEverything reported a driver/command/parser error' }
        elseif ($lastExitCode -ne 0 -and [string]::IsNullOrWhiteSpace($lastPayload)) { $reason = ('non-zero exit code {0} with empty stdout/stderr after retries' -f $lastExitCode) }
        elseif ($lastExitCode -ne 0) { $reason = ('non-zero exit code {0}' -f $lastExitCode) }
        elseif (-not $AllowEmptyOutput -and [string]::IsNullOrWhiteSpace($lastPayload)) { $reason = 'empty RWEverything read payload across stdout and stderr after retries' }
        else { $reason = 'unknown RWEverything command failure' }
        $argsText = if ($null -eq $last) { '' } else { [string]$last.Arguments }
        $msg = New-RWECommandFailureMessage -Reason $reason -ExitCode $lastExitCode -StdOut $lastStdOut -StdErr $lastStdErr -ExceptionText $lastException -ElapsedMs $lastElapsed -Path ([string]$preflight.Path) -Arguments $argsText -DriverDiagnostics $diagnostics -MutexNotes ($mutexNotes.ToArray() -join '; ') -ProcessLockNotes ($processLockNotes.ToArray() -join '; ') -AttemptHistory ($attemptHistory.ToArray() -join [Environment]::NewLine)
        $script:RWEPreflightResult = [PSCustomObject]@{ Ready = $false; Path = [string]$preflight.Path; Message = $msg; Diagnostics = $diagnostics; LastError = $lastCombined; CheckedAt = Get-Date }
        throw $msg
    } finally {
        if ($mutexAcquired -and $null -ne $mutex) { try { $mutex.ReleaseMutex() } catch { } }
        if ($null -ne $mutex) { try { $mutex.Dispose() } catch { } }
    }
}


function Invoke-RWEReadBatch {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][AllowNull()][uint64[]]$Addresses,
        [ValidateSet(8,16,32)][int]$Width = 32,
        [int]$ThrottleLimit = 0,
        [int]$TimeoutMs = $script:RWECommandTimeoutMs
    )

    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('RWEverything batch-read processing is disabled by $DisableRWEnNVMe.') }

    $values = @{}
    if ($null -eq $Addresses -or $Addresses.Count -eq 0) { return $values }

    if ($ThrottleLimit -le 0) {
        try { $ThrottleLimit = [int]$script:RWEReadParallelThrottle } catch { $ThrottleLimit = 0 }
    }
    if ($ThrottleLimit -le 0) { $ThrottleLimit = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount)) }
    $ThrottleLimit = [Math]::Max(1, [Math]::Min(32, $ThrottleLimit))
    $TimeoutMs = [Math]::Max(1000, $TimeoutMs)

    $readOp = switch ($Width) {
        8  { 'R8'; break }
        16 { 'R16'; break }
        default { 'R32'; break }
    }

    $preflight = Initialize-DeviceTweakerRWEverything -Path $rwePath -Quiet
    if (-not $preflight.Ready) {
        throw ($preflight.Message + [Environment]::NewLine + $preflight.Diagnostics)
    }

    $items = [System.Collections.Generic.List[object]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($address in @($Addresses)) {
        try { $addr = [uint64]$address } catch { continue }
        $key = ('{0:X16}' -f $addr)
        if (-not $seen.Add($key)) { continue }
        $hex = Dec-To-Hex -decimal $addr
        [void]$items.Add([PSCustomObject]@{ Address = $addr; Key = $key; Command = ('{0} {1}' -f $readOp, $hex) })
    }
    if ($items.Count -eq 0) { return $values }

    function Invoke-RWEReadBatchSerialized {
        param([Parameter(Mandatory=$true)][object[]]$Items)
        $serializedValues = @{}
        foreach ($item in @($Items)) {
            $stdout = Invoke-RWECommand -Command ([string]$item.Command) -TimeoutMs $TimeoutMs -ForceSerialized
            $serializedValues[[string]$item.Key] = [uint64](Convert-RWEverythingOutputToUInt64 -Stdout $stdout -Context ('SerializedBatchRead {0} Address=0x{1:X}' -f $readOp, ([uint64]$item.Address)))
        }
        return $serializedValues
    }

    $allowNativeParallelRwe = $false
    try {
        $parallelReadFlag = Get-Variable -Name RWEAllowParallelReadCommands -Scope Script -ErrorAction SilentlyContinue
        if ($null -ne $parallelReadFlag) { $allowNativeParallelRwe = [bool]$parallelReadFlag.Value }
    } catch { $allowNativeParallelRwe = $false }

    if (-not $allowNativeParallelRwe -or $ThrottleLimit -le 1 -or $items.Count -le 1) {
        return (Invoke-RWEReadBatchSerialized -Items ([object[]]$items.ToArray()))
    }

    function Start-RWEReadBatchProcess {
        param([Parameter(Mandatory=$true)]$Item, [Parameter(Mandatory=$true)][string]$ResolvedPath)

        $psi = [System.Diagnostics.ProcessStartInfo]::new()
        $psi.FileName = $ResolvedPath
        $escapedCommand = ([string]$Item.Command).Replace('"', '\"')
        $psi.Arguments = ('/Min /NoLogo /Stdout /Stderr /Command="{0}"' -f $escapedCommand)
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        try { $psi.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Hidden } catch { }

        $process = [System.Diagnostics.Process]::new()
        $process.StartInfo = $psi
        $stdoutBuilder = [System.Text.StringBuilder]::new()
        $stderrBuilder = [System.Text.StringBuilder]::new()
        $outHandler = [System.Diagnostics.DataReceivedEventHandler]({
            param($sender, $eventArgs)
            if ($null -ne $eventArgs.Data) { [void]$stdoutBuilder.AppendLine($eventArgs.Data) }
        }.GetNewClosure())
        $errHandler = [System.Diagnostics.DataReceivedEventHandler]({
            param($sender, $eventArgs)
            if ($null -ne $eventArgs.Data) { [void]$stderrBuilder.AppendLine($eventArgs.Data) }
        }.GetNewClosure())
        $process.add_OutputDataReceived($outHandler)
        $process.add_ErrorDataReceived($errHandler)

        if (-not $process.Start()) { throw ('Process.Start returned false for RWEverything command {0}' -f $Item.Command) }
        $process.BeginOutputReadLine()
        $process.BeginErrorReadLine()

        return [PSCustomObject]@{
            Item = $Item
            Process = $process
            StdOut = $stdoutBuilder
            StdErr = $stderrBuilder
            OutHandler = $outHandler
            ErrHandler = $errHandler
            StartedUtc = [DateTime]::UtcNow
            Arguments = $psi.Arguments
        }
    }

    $running = [System.Collections.Generic.List[object]]::new()
    $errors = [System.Collections.Generic.List[string]]::new()
    $queue = [System.Collections.Queue]::new()
    foreach ($item in @($items.ToArray())) { $queue.Enqueue($item) }

    try {
        while ($queue.Count -gt 0 -or $running.Count -gt 0) {
            while ($queue.Count -gt 0 -and $running.Count -lt $ThrottleLimit) {
                $item = $queue.Dequeue()
                try {
                    [void]$running.Add((Start-RWEReadBatchProcess -Item $item -ResolvedPath ([string]$preflight.Path)))
                } catch {
                    [void]$errors.Add(('Start failed for {0} at 0x{1:X}: {2}' -f $item.Command, ([uint64]$item.Address), $_.Exception.Message))
                }
            }

            for ($i = $running.Count - 1; $i -ge 0; $i--) {
                $job = $running[$i]
                $proc = $job.Process
                $timedOut = $false
                $removeJob = $false
                try {
                    if (-not $proc.HasExited) {
                        $elapsedMs = ([DateTime]::UtcNow - [DateTime]$job.StartedUtc).TotalMilliseconds
                        if ($elapsedMs -ge $TimeoutMs) {
                            $timedOut = $true
                            try { $proc.Kill() } catch { }
                            try { [void]$proc.WaitForExit(1000) } catch { }
                        } else {
                            continue
                        }
                    }
                    $removeJob = $true

                    if ($timedOut) { try { [void]$proc.WaitForExit(1000) } catch { } }
                    else { try { $proc.WaitForExit() } catch { } }
                    $stdout = [string]$job.StdOut.ToString()
                    $stderr = [string]$job.StdErr.ToString()
                    $combined = ($stdout + [Environment]::NewLine + $stderr).Trim()
                    $payload = if (-not [string]::IsNullOrWhiteSpace($stdout)) { $stdout } elseif (-not [string]::IsNullOrWhiteSpace($stderr)) { $stderr } else { '' }
                    $exitCode = $null
                    try { $exitCode = $proc.ExitCode } catch { }

                    if ($timedOut) {
                        [void]$errors.Add(('Timeout after {0} ms for {1} at 0x{2:X}' -f $TimeoutMs, $job.Item.Command, ([uint64]$job.Item.Address)))
                    } elseif ($combined -match '(?i)(driver\s+cannot\s+be\s+loaded|cannot\s+load\s+driver|driver\s+load\s+fail|blocked|unsigned|vulnerable|access\s+denied|invalid\s+command|unknown\s+command|unrecognized\s+command|bad\s+command|syntax\s+error|command\s+error|unsupported\s+command|not\s+support)') {
                        [void]$errors.Add(('RWEverything error for {0} at 0x{1:X}: {2}' -f $job.Item.Command, ([uint64]$job.Item.Address), ($combined.Substring(0, [Math]::Min(900, $combined.Length)))))
                    } elseif ($null -ne $exitCode -and $exitCode -ne 0 -and [string]::IsNullOrWhiteSpace($payload)) {
                        [void]$errors.Add(('ExitCode={0} with empty output for {1} at 0x{2:X}' -f $exitCode, $job.Item.Command, ([uint64]$job.Item.Address)))
                    } else {
                        try {
                            $context = ('ExperimentalParallelRead {0} Address=0x{1:X}' -f $readOp, ([uint64]$job.Item.Address))
                            $values[[string]$job.Item.Key] = [uint64](Convert-RWEverythingOutputToUInt64 -Stdout $payload -Context $context)
                        } catch {
                            [void]$errors.Add(('Parse failed for {0} at 0x{1:X}: {2}' -f $job.Item.Command, ([uint64]$job.Item.Address), $_.Exception.Message))
                        }
                    }
                } finally {
                    if ($removeJob) {
                        try { if ($job.OutHandler) { $proc.remove_OutputDataReceived($job.OutHandler) } } catch { }
                        try { if ($job.ErrHandler) { $proc.remove_ErrorDataReceived($job.ErrHandler) } } catch { }
                        try { $proc.Dispose() } catch { }
                        $running.RemoveAt($i)
                    }
                }
            }

            if ($running.Count -gt 0 -or $queue.Count -gt 0) { Start-Sleep -Milliseconds 5 }
        }
    } finally {
        for ($i = $running.Count - 1; $i -ge 0; $i--) {
            try {
                if ($running[$i].Process -and -not $running[$i].Process.HasExited) { $running[$i].Process.Kill() }
            } catch { }
            try { if ($running[$i].Process) { $running[$i].Process.Dispose() } } catch { }
        }
    }

    if ($errors.Count -gt 0 -or $values.Count -ne $seen.Count) {
        if ($errors.Count -gt 0) {
            try { Write-Host (('Experimental parallel RWEverything read failed; retrying with serialized native Rw.exe reads. {0}' -f (($errors.ToArray() -join ' | ')))) -ForegroundColor Yellow } catch { }
        } else {
            try { Write-Host 'Experimental parallel RWEverything read returned incomplete data; retrying with serialized native Rw.exe reads.' -ForegroundColor Yellow } catch { }
        }
        return (Invoke-RWEReadBatchSerialized -Items ([object[]]$items.ToArray()))
    }

    return $values
}

function Read-ControllerIMOD($controller, $deviceMap) {
    try {
        $runtimeInfo = Get-XHCIControllerRuntimeInfo -controller $controller -deviceMap $deviceMap
    } catch {
        Write-Host ("USB IMOD read skipped: RWEverything could not read controller runtime registers. {0}" -f $_.Exception.Message) -ForegroundColor Yellow
        return $null
    }
    if ($null -eq $runtimeInfo) { return $null }

    $imodValues = [System.Collections.Generic.List[object]]::new()
    $interrupterAddresses = [System.Collections.Generic.List[uint64]]::new()
    for ($i = 0; $i -lt $runtimeInfo.MaxIntrs; $i++) {
        [void]$interrupterAddresses.Add([uint64]($runtimeInfo.RuntimeAddress + 0x24 + (0x20 * $i)))
    }

    if ($interrupterAddresses.Count -gt 1 -and (Get-Command Invoke-RWEReadBatch -ErrorAction SilentlyContinue)) {
        try {
            $batchValues = Invoke-RWEReadBatch -Addresses ([uint64[]]$interrupterAddresses.ToArray()) -Width 32
            for ($i = 0; $i -lt $interrupterAddresses.Count; $i++) {
                $key = ('{0:X16}' -f ([uint64]$interrupterAddresses[$i]))
                if (-not $batchValues.ContainsKey($key)) { throw ('missing batch value for address 0x{0:X}' -f ([uint64]$interrupterAddresses[$i])) }
                [void]$imodValues.Add(([uint64]$batchValues[$key] -band 0xFFFF))
            }
            return $imodValues
        } catch {
            Write-Host ("USB IMOD parallel read failed; falling back to serialized reads: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
            $imodValues.Clear()
        }
    }

    for ($i = 0; $i -lt $runtimeInfo.MaxIntrs; $i++) {
        $interrupterAddress = [uint64]$interrupterAddresses[$i]
        try {
            $value = Get-Value-From-Address -address $interrupterAddress
            [void]$imodValues.Add(($value -band 0xFFFF))
        } catch {
            Write-Host ("USB IMOD read stopped at interrupter {0} / address 0x{1:X}: {2}" -f $i, ([uint64]$interrupterAddress), $_.Exception.Message) -ForegroundColor Yellow
            break
        }
    }
    return $imodValues
}

function Write-ControllerIMOD($controller, $deviceMap, $newInterval) {
    $deviceId = $controller.DeviceID
    if (-not $deviceMap.Contains($deviceId)) { return $false }

    $capabilityAddress = $deviceMap[$deviceId]
    $hcsparamsOffset = $globalHCSPARAMSOffset
    $rtsoff = $globalRTSOFF

    foreach ($hwid in $userDefinedData.Keys) {
        if ($deviceId -match $hwid) {
            $userDefinedController = $userDefinedData[$hwid]
            if ($userDefinedController.ContainsKey("HCSPARAMS_OFFSET")) { $hcsparamsOffset = $userDefinedController["HCSPARAMS_OFFSET"] }
            elseif ($userDefinedController.ContainsKey("HCSPARAPS_OFFSET")) { $hcsparamsOffset = $userDefinedController["HCSPARAPS_OFFSET"] }
            if ($userDefinedController.ContainsKey("RTSOFF")) { $rtsoff = $userDefinedController["RTSOFF"] }
        }
    }

    $HCSPARAMSValue = Get-Value-From-Address -address ($capabilityAddress + $hcsparamsOffset)
    $maxIntrs = ($HCSPARAMSValue -shr 8) -band 0x7FF
    $RTSOFFValue = Get-Value-From-Address -address ($capabilityAddress + $rtsoff)
    $runtimeAddress = $capabilityAddress + $RTSOFFValue

    if ($newInterval -is [hashtable]) {
        if ($newInterval.Count -eq 0) { return $false }
        foreach ($idx in $newInterval.Keys) {
            $i = [int]$idx
            if ($i -lt 0 -or $i -ge $maxIntrs) { continue }
            $interrupterAddress = $runtimeAddress + 0x24 + (0x20 * $i)
            $currentValue = Get-Value-From-Address -address $interrupterAddress
            $preservedIMODC = [uint32]($currentValue -band 0xFFFF0000)
            $targetInterval = [uint32]([uint16]$newInterval[$idx])
            $mergedValue = $preservedIMODC -bor ($targetInterval -band 0xFFFF)
            $hexAddress = Dec-To-Hex -decimal ([uint64]$interrupterAddress)
            $hexValue = "0x$($mergedValue.ToString('X8'))"
            Invoke-RWECommand -Command "W32 $($hexAddress) $($hexValue)" -AllowEmptyOutput | Out-Null
        }
        return $true
    }

    $perInterrupterValues = $null
    $uniformInterval = [uint16]0
    if ($newInterval -is [System.Array] -or $newInterval -is [System.Collections.IList]) {
        $perInterrupterList = [System.Collections.Generic.List[uint16]]::new()
        foreach ($_intervalValue in @($newInterval)) { [void]$perInterrupterList.Add([uint16]$_intervalValue) }
        $perInterrupterValues = $perInterrupterList.ToArray()
        if ($perInterrupterValues.Count -ne $maxIntrs) { return $false }
    } else {
        $uniformInterval = [uint16]$newInterval
    }

    for ($i = 0; $i -lt $maxIntrs; $i++) {
        $interrupterAddress = $runtimeAddress + 0x24 + (0x20 * $i)
        $currentValue = Get-Value-From-Address -address $interrupterAddress
        $preservedIMODC = [uint32]($currentValue -band 0xFFFF0000)
        $targetInterval = if ($null -ne $perInterrupterValues) { [uint32]$perInterrupterValues[$i] } else { [uint32]$uniformInterval }
        $mergedValue = $preservedIMODC -bor ($targetInterval -band 0xFFFF)
        $hexAddress = Dec-To-Hex -decimal ([uint64]$interrupterAddress)
        $hexValue = "0x$($mergedValue.ToString('X8'))"
        Invoke-RWECommand -Command "W32 $($hexAddress) $($hexValue)" -AllowEmptyOutput | Out-Null
    }
    return $true
}

function Read-Value64FromAddress([uint64]$address, $cache = $null) {
    $lo = Get-Value-From-Address -address $address -cache $cache
    $hi = Get-Value-From-Address -address ($address + 4) -cache $cache
    return ([uint64]$hi -shl 32) -bor [uint64]$lo
}

function Get-XHCIControllerRuntimeInfo {
    param(
        $controller,
        $deviceMap,
        $readCache = $null
    )

    $deviceId = $controller.DeviceID
    if (-not $deviceMap.Contains($deviceId)) { return $null }

    if ($null -eq $script:xhciControllerRuntimeInfoCache) {
        $script:xhciControllerRuntimeInfoCache = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    }

    $cacheKey = $deviceId -replace '\\\\', '\'
    $capBase = [uint64]$deviceMap[$deviceId]

    if ($script:xhciControllerRuntimeInfoCache.ContainsKey($cacheKey)) {
        $cached = $script:xhciControllerRuntimeInfoCache[$cacheKey]
        if ($cached -and ([uint64]$cached.CapabilityAddress -eq $capBase)) {
            return $cached
        }
    }

    $hcsparamsOffset = $globalHCSPARAMSOffset
    $rtsoff = $globalRTSOFF
    foreach ($hwid in $userDefinedData.Keys) {
        if ($deviceId -match $hwid) {
            $ud = $userDefinedData[$hwid]
            if ($ud.ContainsKey("HCSPARAMS_OFFSET")) { $hcsparamsOffset = $ud["HCSPARAMS_OFFSET"] }
            elseif ($ud.ContainsKey("HCSPARAPS_OFFSET")) { $hcsparamsOffset = $ud["HCSPARAPS_OFFSET"] }
            if ($ud.ContainsKey("RTSOFF")) { $rtsoff = $ud["RTSOFF"] }
        }
    }

    $capLengthDW = [uint32](Get-Value-From-Address -address $capBase -cache $readCache)
    $capLength = $capLengthDW -band 0xFF

    $hcsparams1 = [uint32](Get-Value-From-Address -address ($capBase + $hcsparamsOffset) -cache $readCache)
    $maxSlots = [int]($hcsparams1 -band 0xFF)
    $maxIntrs = [int](($hcsparams1 -shr 8) -band 0x7FF)
    $maxPorts = [int](($hcsparams1 -shr 24) -band 0xFF)

    $hccparams1 = [uint32](Get-Value-From-Address -address ($capBase + 0x10) -cache $readCache)
    $ctxSize = if (($hccparams1 -shr 2) -band 1) { 64 } else { 32 }
    $xecpOffset = [int](($hccparams1 -shr 16) -band 0xFFFF)

    $opBase = $capBase + [uint64]$capLength
    $dcbaap = Read-Value64FromAddress -address ($opBase + 0x30) -cache $readCache

    $rtsoffValue = [uint32](Get-Value-From-Address -address ($capBase + $rtsoff) -cache $readCache)
    $runtimeAddress = $capBase + [uint64]$rtsoffValue

    $info = [PSCustomObject]@{
        DeviceId          = $deviceId
        CapabilityAddress = $capBase
        HCSPARAMSOffset   = $hcsparamsOffset
        RTSOFF            = $rtsoff
        CapLength         = $capLength
        HCSPARAMS1         = $hcsparams1
        HCCPARAMS1         = $hccparams1
        XECPOffset         = $xecpOffset
        MaxSlots          = $maxSlots
        MaxIntrs          = $maxIntrs
        MaxPorts          = $maxPorts
        CtxSize           = $ctxSize
        OpBase            = $opBase
        DCBAAP            = $dcbaap
        RuntimeAddress    = $runtimeAddress
        RTSOFFValue       = $rtsoffValue
    }

    $script:xhciControllerRuntimeInfoCache[$cacheKey] = $info
    return $info
}


function Get-XHCIPortRegisterAddress {
    param(
        [Parameter(Mandatory=$true)]$runtimeInfo,
        [Parameter(Mandatory=$true)][int]$PortNumber,
        [Parameter(Mandatory=$true)][ValidateSet('PORTSC','PORTPMSC','PORTLI','PORTHLPMC')][string]$Register
    )

    if ($null -eq $runtimeInfo) { throw [System.ArgumentNullException]::new('runtimeInfo') }
    $maxPorts = [int]$runtimeInfo.MaxPorts
    if ($maxPorts -le 0) { throw [System.InvalidOperationException]::new(('Invalid MaxPorts for xHCI controller {0}: {1}' -f $runtimeInfo.DeviceId, $maxPorts)) }
    if ($PortNumber -lt 1 -or $PortNumber -gt $maxPorts) { throw [System.ArgumentOutOfRangeException]::new('PortNumber', $PortNumber, ('Port number must be in the range 1..{0}' -f $maxPorts)) }

    [uint64]$registerOffset = 0
    switch ($Register) {
        'PORTSC' { $registerOffset = 0; break }
        'PORTPMSC' { $registerOffset = 4; break }
        'PORTLI' { $registerOffset = 8; break }
        'PORTHLPMC' { $registerOffset = 12; break }
        default { throw [System.ArgumentException]::new(('Unsupported xHCI port register name: {0}' -f $Register), 'Register') }
    }

    return ([uint64]$runtimeInfo.OpBase + [uint64]0x400 + ([uint64]0x10 * [uint64]($PortNumber - 1)) + $registerOffset)
}

function Get-XHCISupportedProtocolPortRanges {
    param(
        [Parameter(Mandatory=$true)]$runtimeInfo,
        $readCache = $null
    )

    if ($null -eq $runtimeInfo) { throw [System.ArgumentNullException]::new('runtimeInfo') }
    $maxPorts = [int]$runtimeInfo.MaxPorts
    if ($maxPorts -le 0) { throw [System.InvalidOperationException]::new(('Invalid MaxPorts for xHCI controller {0}: {1}' -f $runtimeInfo.DeviceId, $maxPorts)) }
    $xecpOffsetDwords = [int]$runtimeInfo.XECPOffset
    if ($xecpOffsetDwords -le 0) { throw [System.InvalidOperationException]::new(('Controller {0} reports no xHCI Extended Capabilities Pointer; refusing to classify root ports heuristically.' -f $runtimeInfo.DeviceId)) }

    $ranges = [System.Collections.Generic.List[object]]::new()
    $seen = [System.Collections.Generic.HashSet[uint64]]::new()
    [uint64]$capabilityAddress = [uint64]$runtimeInfo.CapabilityAddress + ([uint64]$xecpOffsetDwords * [uint64]4)

    for ($guard = 0; $guard -lt 256; $guard++) {
        if (-not $seen.Add($capabilityAddress)) { throw [System.InvalidOperationException]::new(('Loop detected while walking xHCI extended capabilities for {0} at {1}' -f $runtimeInfo.DeviceId, (Dec-To-Hex -decimal $capabilityAddress))) }
        $header = [uint32](Get-Value-From-Address -address $capabilityAddress -cache $readCache)
        $capabilityId = [int]($header -band 0xFF)
        $nextDwords = [int](($header -shr 8) -band 0xFF)

        if ($capabilityId -eq 2) {
            $nameValue = [uint32](Get-Value-From-Address -address ($capabilityAddress + [uint64]4) -cache $readCache)
            $portValue = [uint32](Get-Value-From-Address -address ($capabilityAddress + [uint64]8) -cache $readCache)
            $major = [int](($header -shr 24) -band 0xFF)
            $minor = [int](($header -shr 16) -band 0xFF)
            $startPort = [int]($portValue -band 0xFF)
            $portCount = [int](($portValue -shr 8) -band 0xFF)
            $psic = [int](($portValue -shr 28) -band 0xF)

            if ($nameValue -eq [uint32]0x20425355 -and $startPort -ge 1 -and $portCount -ge 1) {
                $endPort = [int][Math]::Min($maxPorts, $startPort + $portCount - 1)
                if ($endPort -ge $startPort) {
                    $protocolName = if ($major -eq 3) { 'USB3' } elseif ($major -eq 2) { 'USB2' } else { ('USB{0}' -f $major) }
                    $ranges.Add([PSCustomObject]@{
                        CapabilityAddress        = $capabilityAddress
                        Header                   = $header
                        Protocol                 = $protocolName
                        Major                    = $major
                        Minor                    = $minor
                        StartPort                = $startPort
                        PortCount                = $portCount
                        EndPort                  = $endPort
                        PSIC                     = $psic
                        HardwareLpmCapability    = [bool](($portValue -shr 19) -band 1)
                        BeslLpmCapability        = [bool](($portValue -shr 20) -band 1)
                    }) | Out-Null
                }
            }
        }

        if ($nextDwords -eq 0) { break }
        $capabilityAddress = $capabilityAddress + ([uint64]$nextDwords * [uint64]4)
    }

    if ($ranges.Count -eq 0) { throw [System.InvalidOperationException]::new(('No xHCI Supported Protocol Capability entries were found for controller {0}.' -f $runtimeInfo.DeviceId)) }
    return $ranges.ToArray()
}

function Get-XHCIPortProtocolLookup {
    param(
        [Parameter(Mandatory=$true)]$runtimeInfo,
        $readCache = $null
    )

    $lookup = @{}
    $ranges = Get-XHCISupportedProtocolPortRanges -runtimeInfo $runtimeInfo -readCache $readCache
    foreach ($range in @($ranges)) {
        for ($port = [int]$range.StartPort; $port -le [int]$range.EndPort; $port++) {
            if ($lookup.ContainsKey($port)) { throw [System.InvalidOperationException]::new(('Overlapping xHCI protocol capabilities for controller {0}, port {1}.' -f $runtimeInfo.DeviceId, $port)) }
            $lookup[$port] = $range
        }
    }
    return $lookup
}

function Resolve-XHCIUSB3TimeoutByte {
    param(
        [Parameter(Mandatory=$true)][bool]$Enable,
        [Parameter(Mandatory=$true)][int]$Current,
        [Parameter(Mandatory=$true)][ValidateSet('U1','U2')][string]$Kind,
        [Parameter(Mandatory=$true)][ValidateSet('RejectAll','InhibitHostInitiatedOnly')][string]$Mode
    )

    if (-not $Enable) {
        if ($Mode -eq 'InhibitHostInitiatedOnly') { return [byte]0xFF }
        return [byte]0
    }

    if ($Kind -eq 'U1') {
        if ($Current -ge 1 -and $Current -le 0x7F) { return [byte]$Current }
        return [byte]1
    }

    if ($Current -ge 1 -and $Current -le 0xFE) { return [byte]$Current }
    return [byte]1
}

function Set-XHCILinkPowerManagement {
    param(
        [Parameter(Mandatory=$true)]$controller,
        [Parameter(Mandatory=$true)]$deviceMap,
        [Parameter(Mandatory=$true)][bool]$EnableU1,
        [Parameter(Mandatory=$true)][bool]$EnableU2,
        [ValidateSet('RejectAll','InhibitHostInitiatedOnly')][string]$Mode = 'RejectAll',
        [switch]$IncludeUSB2
    )

    $readCache = @{}
    $runtimeInfo = Get-XHCIControllerRuntimeInfo -controller $controller -deviceMap $deviceMap -readCache $readCache
    if ($null -eq $runtimeInfo) { throw [System.InvalidOperationException]::new(('Unable to resolve xHCI runtime information for controller {0}' -f $controller.DeviceID)) }
    $protocolLookup = Get-XHCIPortProtocolLookup -runtimeInfo $runtimeInfo -readCache $readCache
    $records = [System.Collections.Generic.List[object]]::new()
    $changedCount = 0

    for ($port = 1; $port -le [int]$runtimeInfo.MaxPorts; $port++) {
        if (-not $protocolLookup.ContainsKey($port)) { continue }
        $protocol = $protocolLookup[$port]
        $portscAddress = Get-XHCIPortRegisterAddress -runtimeInfo $runtimeInfo -PortNumber $port -Register 'PORTSC'
        $pmscAddress = Get-XHCIPortRegisterAddress -runtimeInfo $runtimeInfo -PortNumber $port -Register 'PORTPMSC'
        $portsc = [uint32](Get-Value-From-Address -address $portscAddress -cache $readCache)
        $oldPmsc = [uint32](Get-Value-From-Address -address $pmscAddress -cache $readCache)
        $newPmsc = $oldPmsc
        $verifyMask = [uint32]0
        $u1Timeout = $null
        $u2Timeout = $null
        $action = 'Skipped'

        if ($protocol.Protocol -eq 'USB3') {
            $u1Timeout = Resolve-XHCIUSB3TimeoutByte -Enable $EnableU1 -Current ([int]($oldPmsc -band 0xFF)) -Kind 'U1' -Mode $Mode
            $u2Timeout = Resolve-XHCIUSB3TimeoutByte -Enable $EnableU2 -Current ([int](($oldPmsc -shr 8) -band 0xFF)) -Kind 'U2' -Mode $Mode
            $newPmsc = [uint32](($oldPmsc -band [uint32]4294901760) -bor ([uint32]$u1Timeout) -bor (([uint32]$u2Timeout) -shl 8))
            $verifyMask = [uint32]0x0000FFFF
            $action = if ($newPmsc -eq $oldPmsc) { 'Unchanged' } else { 'Written' }
        } elseif ($IncludeUSB2 -and $protocol.Protocol -eq 'USB2') {
            if (-not $EnableU1 -and -not $EnableU2) {
                $newPmsc = [uint32]($oldPmsc -band [uint32]4294901751)
                $verifyMask = [uint32]0x00010008
                $action = if ($newPmsc -eq $oldPmsc) { 'Unchanged' } else { 'Written' }
            } elseif ($protocol.HardwareLpmCapability) {
                $newPmsc = [uint32]($oldPmsc -bor [uint32]0x00010000)
                $verifyMask = [uint32]0x00010000
                $action = if ($newPmsc -eq $oldPmsc) { 'Unchanged' } else { 'Written' }
            } else {
                $action = 'SkippedUSB2NoHLC'
            }
        } else {
            $action = ('Skipped{0}' -f $protocol.Protocol)
        }

        if ($newPmsc -ne $oldPmsc) {
            $hexAddress = Dec-To-Hex -decimal $pmscAddress
            $hexValue = ('0x{0:X8}' -f [uint32]$newPmsc)
            Invoke-RWECommand -Command "W32 $hexAddress $hexValue" -AllowEmptyOutput | Out-Null
            $readBack = [uint32](Get-Value-From-Address -address $pmscAddress -cache @{})
            if (($readBack -band $verifyMask) -ne ($newPmsc -band $verifyMask)) {
                throw [System.InvalidOperationException]::new(('xHCI PORTPMSC verification failed for controller {0}, port {1}, protocol {2}, address {3}: wrote {4}, read 0x{5:X8}, expected-mask 0x{6:X8}' -f $runtimeInfo.DeviceId, $port, $protocol.Protocol, $hexAddress, $hexValue, $readBack, $verifyMask))
            }
            $changedCount++
        } else {
            $readBack = $oldPmsc
        }

        $records.Add([PSCustomObject]@{
            Port                 = $port
            Protocol             = $protocol.Protocol
            PORTSCAddress        = $portscAddress
            PORTPMSCAddress      = $pmscAddress
            PORTSC               = $portsc
            OldPORTPMSC          = $oldPmsc
            NewPORTPMSC          = $newPmsc
            ReadBackPORTPMSC     = $readBack
            Connected            = [bool]($portsc -band 1)
            Enabled              = [bool]($portsc -band 2)
            PortPower            = [bool]($portsc -band 0x200)
            PortSpeed            = [int](($portsc -shr 10) -band 0xF)
            LinkState            = [int](($portsc -shr 5) -band 0xF)
            U1Timeout            = $u1Timeout
            U2Timeout            = $u2Timeout
            ForceLinkPMAccept    = [bool]($newPmsc -band 0x00010000)
            Action               = $action
        }) | Out-Null
    }

    return [PSCustomObject]@{
        Success        = $true
        Controller     = $runtimeInfo.DeviceId
        MaxPorts       = [int]$runtimeInfo.MaxPorts
        ChangedCount   = $changedCount
        Mode           = $Mode
        IncludeUSB2    = [bool]$IncludeUSB2
        Records        = $records.ToArray()
    }
}

function Get-XHCIInterrupterDeviceMap {
    param(
        $controller,
        $deviceMap,
        $usbEnumResult,
        $hidDevices,
        $pollingRateLookup
    )

    try {
        $deviceId = $controller.DeviceID
        if (-not $deviceMap.Contains($deviceId)) { return $null }

        if ($null -eq $script:xhciInterrupterDeviceMapCache) {
            $script:xhciInterrupterDeviceMapCache = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
        }

        $ctrlIdNorm = [DeviceTweakerPathHelpers]::NormalizeHostControllerPath([string]$deviceId)
        $ctrlPnpId = Get-PNPId $deviceId

        $usbEndpointCount = if ($usbEnumResult -and $usbEnumResult.Endpoints) { @($usbEnumResult.Endpoints).Count } else { 0 }
        $hidDeviceCount = if ($hidDevices) { @($hidDevices).Count } else { 0 }
        $pollingCount = if ($pollingRateLookup) { $pollingRateLookup.Count } else { 0 }
        $audioCount = 0
        if ($script:audioLookupDetails -and $ctrlPnpId -and $script:audioLookupDetails.ContainsKey($ctrlPnpId)) {
            $audioCount = @($script:audioLookupDetails[$ctrlPnpId]).Count
        }

        $usbRefSig = if ($usbEnumResult) { [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($usbEnumResult) } else { 0 }
        $usbEpRefSig = if ($usbEnumResult -and $usbEnumResult.Endpoints) { [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($usbEnumResult.Endpoints) } else { 0 }
        $hidRefSig = if ($hidDevices) { [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($hidDevices) } else { 0 }
        $pollingRefSig = if ($pollingRateLookup) { [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($pollingRateLookup) } else { 0 }
        $audioRefSig = if ($script:audioLookupDetails -and $ctrlPnpId -and $script:audioLookupDetails.ContainsKey($ctrlPnpId)) { [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($script:audioLookupDetails[$ctrlPnpId]) } else { 0 }

        $cacheKey = $ctrlIdNorm
        $cacheSignature = "$usbRefSig|$usbEpRefSig|$hidRefSig|$pollingRefSig|$audioRefSig|$usbEndpointCount|$hidDeviceCount|$pollingCount|$audioCount"
        if ($script:xhciInterrupterDeviceMapCache.ContainsKey($cacheKey)) {
            $cachedEntry = $script:xhciInterrupterDeviceMapCache[$cacheKey]
            if ($cachedEntry -and
                $cachedEntry.Signature -eq $cacheSignature -and
                ([uint64]$cachedEntry.CapabilityAddress -eq [uint64]$deviceMap[$deviceId])) {
                return $cachedEntry.Value
            }
        }

        $readCache = @{}
        $runtimeInfo = Get-XHCIControllerRuntimeInfo -controller $controller -deviceMap $deviceMap -readCache $readCache
        if ($null -eq $runtimeInfo) { return $null }
        if ($runtimeInfo.DCBAAP -eq 0) { return $null }

        $slotsToProbe = [Math]::Min($runtimeInfo.MaxSlots, 24)

        $activeSlotAddrs = [System.Collections.Generic.List[object]]::new()
        for ($s = 1; $s -le $slotsToProbe; $s++) {
            $entryAddr = $runtimeInfo.DCBAAP + ([uint64]$s * 8)
            $lo = [uint32](Get-Value-From-Address -address $entryAddr -cache $readCache)
            if ($lo -eq 0) { continue }
            $hi = [uint32](Get-Value-From-Address -address ($entryAddr + 4) -cache $readCache)
            $ptr = ([uint64]$hi -shl 32) -bor [uint64]$lo
            if ($ptr -eq 0) { continue }
            $activeSlotAddrs.Add([PSCustomObject]@{ Slot = $s; CtxBase = $ptr })
        }

        if ($activeSlotAddrs.Count -eq 0) { return $null }

        $slotDevices = [System.Collections.Generic.List[object]]::new()
        foreach ($entry in $activeSlotAddrs) {
            $base = $entry.CtxBase
            $dw0 = [uint32](Get-Value-From-Address -address $base -cache $readCache)
            $dw1 = [uint32](Get-Value-From-Address -address ($base + 4) -cache $readCache)
            $dw2 = [uint32](Get-Value-From-Address -address ($base + 8) -cache $readCache)
            $dw3 = [uint32](Get-Value-From-Address -address ($base + 12) -cache $readCache)

            $isHub       = [bool](($dw0 -shr 26) -band 1)
            $rootHubPort = [int](($dw1 -shr 16) -band 0xFF)
            $intrTarget  = [int](($dw2 -shr 22) -band 0x3FF)
            $devAddr     = [int]($dw3 -band 0xFF)
            $slotState   = [int](($dw3 -shr 27) -band 0x1F)

            if ($slotState -lt 2 -or $isHub) { continue }

            $ctxEntries = [int](($dw0 -shr 27) -band 0x1F)
            if ($ctxEntries -ge 3) {
                :epScan for ($ei = 3; $ei -le $ctxEntries; $ei += 2) {
                    $epBase  = $base + ([uint64]$ei * $runtimeInfo.CtxSize)
                    $epDW0   = [uint32](Get-Value-From-Address -address $epBase -cache $readCache)
                    $epDW1   = [uint32](Get-Value-From-Address -address ($epBase + 4) -cache $readCache)
                    $epState = [int]($epDW0 -band 0x7)
                    $epType  = [int](($epDW1 -shr 3) -band 0x7)

                    if (($epType -eq 7 -or $epType -eq 5) -and $epState -gt 0) {
                        $trLo = [uint32](Get-Value-From-Address -address ($epBase + 8) -cache $readCache)
                        $trHi = [uint32](Get-Value-From-Address -address ($epBase + 12) -cache $readCache)
                        $trPtr = (([uint64]$trHi -shl 32) -bor [uint64]$trLo) -band ([uint64]::MaxValue -bxor 0xF)
                        if ($trPtr -ne 0) {
                            $trbDW2 = [uint32](Get-Value-From-Address -address ($trPtr + 8) -cache $readCache)
                            $trbDW3 = [uint32](Get-Value-From-Address -address ($trPtr + 12) -cache $readCache)
                            $trbType = [int](($trbDW3 -shr 10) -band 0x3F)
                            if ($trbType -eq 1 -or $trbType -eq 3 -or $trbType -eq 5) {
                                $intrTarget = [int](($trbDW2 -shr 22) -band 0x3FF)
                                break epScan
                            }
                        }
                    }
                }
            }

            $slotDevices.Add([PSCustomObject]@{
                Slot          = $entry.Slot
                DeviceAddress = $devAddr
                RootHubPort   = $rootHubPort
                Interrupter   = $intrTarget
            })
        }

        if ($slotDevices.Count -eq 0) { return $null }

        $addrInfo = @{}
        if ($usbEnumResult -and $usbEnumResult.Endpoints) {
            $hcMatchCache = [System.Collections.Generic.Dictionary[string,bool]]::new([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($ep in $usbEnumResult.Endpoints) {
                if (-not $ep.HostControllerPath -or $ep.DeviceIsHub) { continue }
                $da = [int]$ep.DeviceAddress

                $hcKey = [string]$ep.HostControllerPath
                if (-not $hcMatchCache.ContainsKey($hcKey)) {
                    $hcMatchCache[$hcKey] = [DeviceTweakerPathHelpers]::HostControllerPathsMatch($hcKey, $ctrlIdNorm)
                }
                if (-not $hcMatchCache[$hcKey]) { continue }

                if (-not $addrInfo.ContainsKey($da)) {
                    $addrInfo[$da] = @{
                        VidPid           = "$($ep.VendorId):$($ep.ProductId)"
                        InterfaceClasses = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                    }
                }
                if ($ep.InterfaceClass) { [void]$addrInfo[$da].InterfaceClasses.Add($ep.InterfaceClass) }
            }
        }

        $vpToType = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        if ($hidDevices) {
            foreach ($hd in $hidDevices) {
                if (-not $hd.DeviceType -or -not $hd.DeviceInstanceID) { continue }
                $vp = [DeviceTweakerPathHelpers]::ExtractUsbVidPidColonKey([string]$hd.DeviceInstanceID)
                if ($vp -and -not $vpToType.ContainsKey($vp)) { $vpToType[$vp] = $hd.DeviceType }
            }
        }

        $map = @{}
        foreach ($sd in $slotDevices) {
            $intrIdx = $sd.Interrupter
            $label   = $null

            if ($addrInfo.ContainsKey($sd.DeviceAddress)) {
                $info = $addrInfo[$sd.DeviceAddress]
                $vp = $info.VidPid

                if ($vpToType.ContainsKey($vp)) {
                    $devType = $vpToType[$vp]
                    $prTag = ''
                    if ($pollingRateLookup -and $pollingRateLookup.ContainsKey($vp)) {
                        $prTag = " $($pollingRateLookup[$vp].Tag)"
                    }
                    $label = "$devType$prTag"
                }
                elseif ($info.InterfaceClasses.Contains('0x03')) {
                    $prTag = ''
                    if ($pollingRateLookup -and $pollingRateLookup.ContainsKey($vp)) {
                        $prTag = " $($pollingRateLookup[$vp].Tag)"
                    }
                    $label = "Controller$prTag"
                }
                elseif ($info.InterfaceClasses.Contains('0x01')) {
                    $label = 'Audio'
                }
            }

            if ($label) {
                if (-not $map.ContainsKey($intrIdx)) {
                    $map[$intrIdx] = [System.Collections.Generic.List[string]]::new()
                }
                if (-not $map[$intrIdx].Contains($label)) {
                    [void]$map[$intrIdx].Add($label)
                }
            }
        }

        if ($script:audioLookupDetails -and $ctrlPnpId -and $script:audioLookupDetails.ContainsKey($ctrlPnpId)) {
            foreach ($sd in $slotDevices) {
                $intrIdx = $sd.Interrupter
                if ($addrInfo.ContainsKey($sd.DeviceAddress)) {
                    $info = $addrInfo[$sd.DeviceAddress]
                    if ($info.InterfaceClasses.Contains('0x01') -and $map.ContainsKey($intrIdx)) {
                        $deviceVidPid = $info.VidPid
                        $specificTypes = [System.Collections.Generic.List[string]]::new()
                        foreach ($ad in $script:audioLookupDetails[$ctrlPnpId]) {
                            if ($ad.UsbVidPid -and $deviceVidPid -and $ad.UsbVidPid -ne $deviceVidPid) { continue }
                            $at = $ad.AudioType
                            if ($at -and $at -ne 'Audio' -and -not $specificTypes.Contains($at)) {
                                [void]$specificTypes.Add($at)
                            }
                        }
                        if ($specificTypes.Count -gt 0) {
                            [void]$map[$intrIdx].Remove('Audio')
                            foreach ($st in $specificTypes) {
                                if (-not $map[$intrIdx].Contains($st)) {
                                    [void]$map[$intrIdx].Add($st)
                                }
                            }
                        }
                    }
                }
            }
        }

        if ($map.Count -eq 0) { return $null }

        $script:xhciInterrupterDeviceMapCache[$cacheKey] = [PSCustomObject]@{
            Signature       = $cacheSignature
            CapabilityAddress = [uint64]$runtimeInfo.CapabilityAddress
            Value           = $map
        }

        return $map
    }
    catch {
        return $null
    }
}

