function Resolve-RealtekQueueModerationLayoutByKey {
    param([AllowNull()][string]$Key)
    if ([string]::IsNullOrWhiteSpace($Key)) { return $null }
    foreach ($layout in @($script:RealtekQueueModerationLayouts)) {
        if ($null -eq $layout) { continue }
        if ($layout.ContainsKey('Key') -and [string]::Equals([string]$layout.Key, [string]$Key, [System.StringComparison]::OrdinalIgnoreCase)) { return $layout }
    }
    return $null
}

function Resolve-RealtekQueueModerationLayout {
    param([AllowNull()][hashtable]$nicInfo)
    if ($null -eq $nicInfo) { return $null }
    if ($nicInfo.ContainsKey('QueueLayoutKey')) {
        $layout = Resolve-RealtekQueueModerationLayoutByKey -Key ([string]$nicInfo.QueueLayoutKey)
        if ($null -ne $layout) { return $layout }
    }
    if ($nicInfo.ContainsKey('DeviceIds')) {
        foreach ($deviceId in @($nicInfo.DeviceIds)) {
            if ($null -eq $deviceId) { continue }
            $d = ([string]$deviceId).ToUpperInvariant()
            foreach ($layout in @($script:RealtekQueueModerationLayouts)) {
                foreach ($id in @($layout.DeviceIds)) {
                    if ([string]::Equals($d, ([string]$id).ToUpperInvariant(), [System.StringComparison]::OrdinalIgnoreCase)) { return $layout }
                }
            }
        }
    }
    return $null
}

function Get-RealtekQueueModerationLayoutText {
    param([AllowNull()][object]$Layout)
    if ($null -eq $Layout) { return 'layout=generic-unverified; verifiedQueues=Q0-Q1; unknownQueues=unverified' }
    $key = if ($Layout.ContainsKey('Key')) { [string]$Layout.Key } else { 'unknown' }
    $chip = if ($Layout.ContainsKey('ChipName')) { [string]$Layout.ChipName } else { 'unknown-chip' }
    $verified = if ($Layout.ContainsKey('VerifiedQueueSlots')) { [int]$Layout.VerifiedQueueSlots } else { 0 }
    $slots = if ($Layout.ContainsKey('QueueSlots')) { [int]$Layout.QueueSlots } else { 0 }
    $policy = if ($Layout.ContainsKey('UnknownQueuePolicy')) { [string]$Layout.UnknownQueuePolicy } else { 'unverified' }
    return ('layout={0}({1}); slots={2}; verifiedQueueSlots={3}; unknown={4}' -f $key, $chip, $slots, $verified, $policy)
}

function Get-RealtekQueueModerationSlot {
    param([AllowNull()][object]$Layout, [int]$Queue, [int]$FallbackBankCount = 64)
    $base = [uint64]0x0A00
    $stride = [uint64]8
    $dwordCount = [Math]::Max(1, [int]$FallbackBankCount)
    $queueSlots = [Math]::Max(1, [int][Math]::Ceiling(([double]$dwordCount) / 2.0))
    $verifiedSlots = 2
    $policy = 'generic-unverified-even-dword-candidate'
    $key = 'GENERIC'
    $chip = 'Generic Realtek IntMITI V2'
    $evidence = 'Q0/Q1 named-register evidence only; Q2+ unverified'
    if ($null -ne $Layout) {
        if ($Layout.ContainsKey('BaseOffset')) { $base = [uint64]$Layout.BaseOffset }
        if ($Layout.ContainsKey('RxTxDwordStride')) { $stride = [uint64]$Layout.RxTxDwordStride }
        if ($Layout.ContainsKey('DwordCount')) { $dwordCount = [Math]::Max(1, [int]$Layout.DwordCount) }
        if ($Layout.ContainsKey('QueueSlots')) { $queueSlots = [Math]::Max(1, [int]$Layout.QueueSlots) }
        if ($Layout.ContainsKey('VerifiedQueueSlots')) { $verifiedSlots = [Math]::Max(0, [int]$Layout.VerifiedQueueSlots) }
        if ($Layout.ContainsKey('UnknownQueuePolicy')) { $policy = [string]$Layout.UnknownQueuePolicy }
        if ($Layout.ContainsKey('Key')) { $key = [string]$Layout.Key }
        if ($Layout.ContainsKey('ChipName')) { $chip = [string]$Layout.ChipName }
        if ($Layout.ContainsKey('Evidence')) { $evidence = [string]$Layout.Evidence }
    }
    $queueValid = ($Queue -ge 0 -and $Queue -lt $queueSlots)
    $idx = [int]($Queue * 2)
    $offset = [uint64]($base + ([uint64]$Queue * $stride))
    $bankValid = ($idx -ge 0 -and $idx -lt $dwordCount)
    $verified = ($queueValid -and $bankValid -and $Queue -lt $verifiedSlots)
    $state = if ($verified) { 'verified' } elseif ($queueValid -and $bankValid) { 'unverified' } else { 'out-of-layout' }
    $verification = if ($verified) { 'verified-named-register' } elseif ($queueValid -and $bankValid) { $policy } else { 'no-layout-bank' }
    return [PSCustomObject]@{
        Queue = [int]$Queue
        IntMitiIndex = [int]$idx
        IntMitiOffset = [uint64]$offset
        QueueValid = [bool]$queueValid
        BankValid = [bool]$bankValid
        QueueVerified = [bool]$verified
        VerificationState = [string]$state
        Verification = [string]$verification
        LayoutKey = [string]$key
        ChipName = [string]$chip
        Evidence = [string]$evidence
    }
}

$script:RealtekIntMitiV2LabelCache = @{}

function Test-RealtekIntMitiV2LabelMaterializationDisabled {
    $flag = Get-Variable -Scope Script -Name DisableRWEnNVMe -ErrorAction SilentlyContinue
    if ($null -eq $flag) { return $false }
    return [bool]$flag.Value
}

function New-RealtekIntMitiV2BankLabelsFast {
    param([int]$Count, [AllowNull()][object]$Layout)
    if ($Count -le 0) { return [string[]]::new(0) }
    $labels = [string[]]::new($Count)
    $base = [uint64]0x0A00
    $verifiedSlots = 2
    $key = 'GENERIC'
    $policy = 'generic-unverified-even-dword-candidate'
    if ($null -ne $Layout) {
        if ($Layout.ContainsKey('BaseOffset')) { $base = [uint64]$Layout.BaseOffset }
        if ($Layout.ContainsKey('VerifiedQueueSlots')) { $verifiedSlots = [Math]::Max(0, [int]$Layout.VerifiedQueueSlots) }
        if ($Layout.ContainsKey('Key')) { $key = [string]$Layout.Key }
        if ($Layout.ContainsKey('UnknownQueuePolicy')) { $policy = [string]$Layout.UnknownQueuePolicy }
    }
    for ($i = 0; $i -lt $Count; $i++) {
        $offset = [uint64]($base + ([uint64]$i * [uint64]4))
        if (($i -band 1) -eq 0) {
            $q = [int]($i / 2)
            if ($q -lt $verifiedSlots) {
                $labels[$i] = 'RXQ{0}/TXQ{0} verified -> vector pending -> IntMITI{1}@0x{2:X4} low=RX high=TX [{3}; verified-named-register]' -f $q, $i, $offset, $key
            } else {
                $labels[$i] = 'Unverified queue candidate Q{0} -> vector pending -> IntMITI{1}@0x{2:X4} low=RX high=TX [{3}; {4}; raw evidence required]' -f $q, $i, $offset, $key, $policy
            }
        } else {
            $labels[$i] = 'No queue claim -> IntMITI{0}@0x{1:X4} adjacent low16/RX-only candidate mask=0x00003F7F' -f $i, $offset
        }
    }
    return $labels
}

function New-RealtekIntMitiV2BankLabels {
    param([int]$Count, [AllowNull()][object]$Layout)
    if (Test-RealtekIntMitiV2LabelMaterializationDisabled) { return [string[]]::new(0) }
    return New-RealtekIntMitiV2BankLabelsFast -Count $Count -Layout $Layout
}

function Get-RealtekIntMitiV2BankLabelsCached {
    param([AllowNull()][string]$Key, [int]$Count)
    if ($Count -le 0) { return [string[]]::new(0) }
    if (Test-RealtekIntMitiV2LabelMaterializationDisabled) { return [string[]]::new(0) }
    $normalizedKey = if ([string]::IsNullOrWhiteSpace($Key)) { 'GENERIC' } else { ([string]$Key).Trim().ToUpperInvariant() }
    $cacheKey = '{0}|{1}' -f $normalizedKey, [int]$Count
    if ($script:RealtekIntMitiV2LabelCache.ContainsKey($cacheKey)) {
        return [string[]]$script:RealtekIntMitiV2LabelCache[$cacheKey]
    }
    $layout = if ($normalizedKey -eq 'GENERIC') { $null } else { Resolve-RealtekQueueModerationLayoutByKey -Key $normalizedKey }
    $labels = [string[]](New-RealtekIntMitiV2BankLabelsFast -Count $Count -Layout $layout)
    $script:RealtekIntMitiV2LabelCache[$cacheKey] = $labels
    return $labels
}

function Ensure-RealtekIntMitiV2VectorLabels {
    param([AllowNull()][hashtable]$nicInfo)
    if ($null -eq $nicInfo) { return }
    if ($nicInfo.ContainsKey('VectorLabels') -and $null -ne $nicInfo.VectorLabels -and $nicInfo.VectorLabels.Count -gt 0) { return }
    $family = if ($nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '' }
    $kind = if ($nicInfo.ContainsKey('VectorLabelKind')) { [string]$nicInfo.VectorLabelKind } else { '' }
    if ($kind -ne 'RealtekIntMitiV2' -and $family -ne 'RealtekIntrMitV2') { return }
    if (Test-RealtekIntMitiV2LabelMaterializationDisabled) { return }
    $key = if ($nicInfo.ContainsKey('RealtekLayoutKey')) { [string]$nicInfo.RealtekLayoutKey } elseif ($nicInfo.ContainsKey('QueueLayoutKey')) { [string]$nicInfo.QueueLayoutKey } else { 'GENERIC' }
    $count = if ($nicInfo.ContainsKey('VectorLabelCount')) { [int]$nicInfo.VectorLabelCount } elseif ($nicInfo.ContainsKey('MaxQueues')) { [int]$nicInfo.MaxQueues } else { 0 }
    if ($count -le 0) { return }
    $labels = [string[]](Get-RealtekIntMitiV2BankLabelsCached -Key $key -Count $count)
    if ($labels.Count -gt 0) { $nicInfo['VectorLabels'] = $labels }
}

function Get-NICIMODDefaultMask {
    param([hashtable]$nicInfo)
    if ($null -eq $nicInfo) { return [uint64]4294967295 }
    if ($nicInfo.ContainsKey('ReadMask')) { return [uint64]$nicInfo.ReadMask }
    if ($nicInfo.ReadWidth -eq 16) { return [uint64]0xFFFF }
    if ($nicInfo.ReadWidth -eq 64) { return [uint64]::MaxValue }
    return [uint64]4294967295
}

function Get-NICIMODValueMask {
    param([hashtable]$nicInfo, [int]$Index = 0)
    $baseMask = Get-NICIMODDefaultMask $nicInfo
    if ($null -ne $nicInfo -and $nicInfo.Family -eq 'RealtekIntrMitV2') {
        $fullMask = [uint64]0x3F7F3F7F
        $low16Mask = [uint64]0x00003F7F
        $mode = if ($nicInfo.ContainsKey('PerIndexMaskMode')) { [string]$nicInfo.PerIndexMaskMode } else { '' }
        if ($mode -eq 'RealtekV2IntMitiFull32' -or $mode -eq 'RealtekV2QueuePairFull32') {
            return $fullMask
        }
        if ($mode -eq 'RealtekV2AlternatingIntMitiLow16' -or $mode -eq 'RealtekV2AlternatingFullLow16') {
            if (($Index % 2) -ne 0) { return $low16Mask }
            return $fullMask
        }
        if ($baseMask -eq [uint64]0x7F7F7F7F -or $baseMask -eq $fullMask) { return $fullMask }
    }
    return $baseMask
}

function Limit-NICIMODValueToHardwareRange {
    param([uint64]$Value, [hashtable]$nicInfo, [int]$Index = 0)

    $mask = Get-NICIMODValueMask -nicInfo $nicInfo -Index $Index
    $v = [uint64]$Value -band [uint64]$mask
    $family = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '' }

    if ($family -eq 'IntelEITRv2' -or $family -eq 'IntelIceGLINT') {
        $lo = [uint64]($v -band [uint64]0xFFFFFFFF)
        $hi = [uint64](($v -shr 32) -band [uint64]0xFFFFFFFF)
        if ($lo -gt [uint64]0x1FE0) { $lo = [uint64]0x1FE0 }
        if ($hi -gt [uint64]0x1FE0) { $hi = [uint64]0x1FE0 }
        return [uint64]($lo -bor ($hi -shl 32))
    }

    return [uint64]$v
}

