function Find-NICIMODInfoByIds {
    param([string]$VendorId, [string]$DeviceId)
    if ([string]::IsNullOrWhiteSpace($VendorId) -or [string]::IsNullOrWhiteSpace($DeviceId)) { return $null }
    foreach ($entry in $script:nicIMODVendorDB) {
        if ($entry.VendorId -eq $VendorId -and $entry.DeviceIds -contains $DeviceId) {
            return $entry
        }
    }
    return $null
}

function Find-RealtekNICIMODInfoByName {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
    $s = $Text.ToUpperInvariant()
    $looksRealtek = $s.Contains('REALTEK') -or $s.Contains('RTL') -or $s.Contains('KILLER')
    if (-not $looksRealtek) { return $null }
    if ($s.Contains('8127') -or $s.Contains('0E10')) { return Find-NICIMODInfoByIds '10EC' '8127' }
    if ($s.Contains('8126') -or $s.Contains('5000') -or $s.Contains('E5000')) { return Find-NICIMODInfoByIds '10EC' '8126' }
    if ($s.Contains('9151')) { return Find-NICIMODInfoByIds '10EC' '9151' }
    if ($s.Contains('8125') -or $s.Contains('8225') -or $s.Contains('8162') -or $s.Contains('3000') -or $s.Contains('E3000') -or $s.Contains('8168KB')) { return Find-NICIMODInfoByIds '10EC' '8125' }
    if ($s.Contains('REALTEK') -and ($s.Contains('10GBE') -or $s.Contains('10G'))) { return Find-NICIMODInfoByIds '10EC' '8127' }
    if ($s.Contains('REALTEK') -and ($s.Contains('5GBE') -or $s.Contains('5G'))) { return Find-NICIMODInfoByIds '10EC' '8126' }
    if ($s.Contains('REALTEK') -and ($s.Contains('2.5GBE') -or $s.Contains('2.5G'))) { return Find-NICIMODInfoByIds '10EC' '8125' }
    if ($s.Contains('E2500') -or $s.Contains('E2600')) { return Find-NICIMODInfoByIds '10EC' '2500' }
    if ($s.Contains('8111') -or $s.Contains('8168') -or $s.Contains('8169') -or $s.Contains('810X') -or $s.Contains('8101') -or $s.Contains('8136') -or $s.Contains('8137') -or $s.Contains('8129') -or $s.Contains('8166') -or $s.Contains('8167')) { return Find-NICIMODInfoByIds '10EC' '8168' }
    if ($s.Contains('REALTEK') -and ($s.Contains('PCIE GBE') -or $s.Contains('GBE FAMILY') -or $s.Contains('GIGABIT'))) { return Find-NICIMODInfoByIds '10EC' '8168' }
    return $null
}

function Get-NICIMODInfo {
    param([string]$pnpId, [string]$DisplayName)
    $pciId = [DeviceTweakerPathHelpers]::ParsePciIdentity($pnpId, $null)
    if ($pciId -and $pciId.Success) {
        $match = Find-NICIMODInfoByIds ([string]$pciId.VendorId) ([string]$pciId.DeviceId)
        if ($match) { return $match }
    }
    return Find-RealtekNICIMODInfoByName $DisplayName
}

function Get-NICDeviceAddress {
    param([PSCustomObject]$device, [hashtable]$deviceMap)
    $configPath = $null
    if ($device.ConfigPath) {
        $configPath = $device.ConfigPath
    }
    if (-not $configPath) { return [uint64]0 }
    $instanceId = $configPath -replace '^(Microsoft\.PowerShell\.Core\\Registry::)?(HKLM:\\|HKEY_LOCAL_MACHINE\\)SYSTEM\\CurrentControlSet\\Enum\\', ''
    $instanceId = $instanceId -replace '\\\\', '\'
    if ($deviceMap.ContainsKey($instanceId)) { return $deviceMap[$instanceId] }
    $escaped = $instanceId -replace '\\', '\\'
    if ($deviceMap.ContainsKey($escaped)) { return $deviceMap[$escaped] }
    foreach ($key in $deviceMap.Keys) {
        $normalizedKey = $key -replace '\\\\', '\'
        if ($normalizedKey -eq $instanceId) { return $deviceMap[$key] }
    }
    $venDevStr = [DeviceTweakerPathHelpers]::ExtractPciVenDevToken($instanceId)
    if ($venDevStr) {
        foreach ($key in $deviceMap.Keys) {
            if ([DeviceTweakerPathHelpers]::ContainsOrdinalIgnoreCase([string]$key, [string]$venDevStr)) { return $deviceMap[$key] }
        }
    }
    return [uint64]0
}


function ConvertTo-DeviceTweakerHexKey {
    param([Parameter(Mandatory=$true)][uint64]$Address)
    return ('{0:X16}' -f [uint64]$Address)
}

function Get-DeviceTweakerBatchValue {
    param([hashtable]$Batch, [uint64]$Address, [string]$Name, [AllowNull()][object]$Mask = $null, [switch]$Optional)
    $key = ConvertTo-DeviceTweakerHexKey -Address $Address
    if ($null -eq $Batch -or -not $Batch.ContainsKey($key)) {
        if ($Optional) { return $null }
        throw ('Missing {0} register read at 0x{1:X}.' -f $Name, [uint64]$Address)
    }

    $mask64 = [uint64]::MaxValue
    if ($PSBoundParameters.ContainsKey('Mask') -and $null -ne $Mask) {
        try {
            if ($Mask -is [uint64]) {
                $mask64 = [uint64]$Mask
            } elseif ($Mask -is [uint32]) {
                $mask64 = [uint64]$Mask
            } elseif ($Mask -is [uint16]) {
                $mask64 = [uint64]$Mask
            } elseif ($Mask -is [byte]) {
                $mask64 = [uint64]$Mask
            } elseif ($Mask -is [int]) {
                if ([int]$Mask -lt 0) { $mask64 = [uint64]([BitConverter]::ToUInt32([BitConverter]::GetBytes([int]$Mask), 0)) }
                else { $mask64 = [uint64]([int]$Mask) }
            } elseif ($Mask -is [long]) {
                if ([long]$Mask -lt 0) { $mask64 = [BitConverter]::ToUInt64([BitConverter]::GetBytes([long]$Mask), 0) }
                else { $mask64 = [uint64]([long]$Mask) }
            } elseif ($Mask -is [int16]) {
                if ([int16]$Mask -lt 0) { $mask64 = [uint64]([BitConverter]::ToUInt16([BitConverter]::GetBytes([int16]$Mask), 0)) }
                else { $mask64 = [uint64]([int16]$Mask) }
            } elseif ($Mask -is [sbyte]) {
                if ([sbyte]$Mask -lt 0) { $mask64 = [uint64](([int]$Mask) -band 0xFF) }
                else { $mask64 = [uint64]([sbyte]$Mask) }
            } else {
                $maskText = ([string]$Mask).Trim()
                if ([string]::IsNullOrWhiteSpace($maskText)) {
                    $mask64 = [uint64]::MaxValue
                } elseif ($maskText.StartsWith('0x', [StringComparison]::OrdinalIgnoreCase)) {
                    $mask64 = [Convert]::ToUInt64($maskText.Substring(2), 16)
                } elseif ($maskText.EndsWith('h', [StringComparison]::OrdinalIgnoreCase)) {
                    $mask64 = [Convert]::ToUInt64($maskText.Substring(0, $maskText.Length - 1), 16)
                } elseif ($maskText.StartsWith('-', [StringComparison]::OrdinalIgnoreCase)) {
                    $signedMask = [Convert]::ToInt64($maskText, 10)
                    $mask64 = [BitConverter]::ToUInt64([BitConverter]::GetBytes([long]$signedMask), 0)
                } else {
                    $mask64 = [Convert]::ToUInt64($maskText, 10)
                }
            }
        } catch {
            $maskType = if ($null -eq $Mask) { '<null>' } else { $Mask.GetType().FullName }
            throw ('Invalid mask for {0} register read at 0x{1:X}. RawMaskType={2}; RawMaskValue={3}; Error={4}' -f $Name, [uint64]$Address, $maskType, [string]$Mask, $_.Exception.Message)
        }
    }

    return (([uint64]$Batch[$key]) -band $mask64)
}

function Write-NICITRDiagnostic {
    param(
        [Parameter(Mandatory=$true)][string]$Message,
        [ValidateSet('Info','Warning','Error')][string]$Level = 'Info',
        [AllowNull()][object]$Exception = $null
    )

    $prefix = '[NIC ITR]'
    $color = switch ($Level) {
        'Error'   { 'Red'; break }
        'Warning' { 'Yellow'; break }
        default   { 'Cyan' }
    }

    $detail = $Message
    if ($null -ne $Exception) {
        try {
            $ex = if ($Exception -is [System.Management.Automation.ErrorRecord]) { $Exception.Exception } elseif ($Exception -is [System.Exception]) { $Exception } else { $null }
            if ($null -ne $ex) {
                $detail = '{0}{1}Exception: {2}: {3}' -f $detail, [Environment]::NewLine, $ex.GetType().FullName, $ex.Message
                if (-not [string]::IsNullOrWhiteSpace($ex.StackTrace)) { $detail = '{0}{1}StackTrace: {2}' -f $detail, [Environment]::NewLine, $ex.StackTrace }
                if ($Exception -is [System.Management.Automation.ErrorRecord]) {
                    try { if ($null -ne $Exception.CategoryInfo) { $detail = '{0}{1}CategoryInfo: {2}' -f $detail, [Environment]::NewLine, [string]$Exception.CategoryInfo } } catch { }
                    try { if (-not [string]::IsNullOrWhiteSpace([string]$Exception.FullyQualifiedErrorId)) { $detail = '{0}{1}FullyQualifiedErrorId: {2}' -f $detail, [Environment]::NewLine, [string]$Exception.FullyQualifiedErrorId } } catch { }
                    try { if ($null -ne $Exception.InvocationInfo -and -not [string]::IsNullOrWhiteSpace([string]$Exception.InvocationInfo.PositionMessage)) { $detail = '{0}{1}PositionMessage: {2}' -f $detail, [Environment]::NewLine, [string]$Exception.InvocationInfo.PositionMessage } } catch { }
                    if ($null -ne $Exception.ScriptStackTrace) { $detail = '{0}{1}ScriptStackTrace: {2}' -f $detail, [Environment]::NewLine, $Exception.ScriptStackTrace }
                }
            } else {
                $detail = '{0}{1}{2}' -f $detail, [Environment]::NewLine, [string]$Exception
            }
        } catch { }
    }

    try { Write-Host (('{0}[{1}] {2}' -f $prefix, $Level.ToUpperInvariant(), $detail)) -ForegroundColor $color } catch { }
    try {
        if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) {
            Write-DeviceTweakerPerfFallbackLog (('{0}[{1}] {2}' -f $prefix, $Level.ToUpperInvariant(), $detail))
        }
    } catch { }
}

function Get-NICITRDeviceDebugName {
    param([AllowNull()][object]$Device)
    if ($null -eq $Device) { return '<null-device>' }
    $parts = [System.Collections.Generic.List[string]]::new()
    foreach ($name in @('DisplayName','Name','FriendlyName')) {
        try {
            $prop = $Device.PSObject.Properties[$name]
            if ($null -ne $prop -and -not [string]::IsNullOrWhiteSpace([string]$prop.Value)) { [void]$parts.Add([string]$prop.Value); break }
        } catch { }
    }
    foreach ($name in @('PNPID','DeviceID','RegistryPath','ConfigPath','DeviceKey')) {
        try {
            $prop = $Device.PSObject.Properties[$name]
            if ($null -ne $prop -and -not [string]::IsNullOrWhiteSpace([string]$prop.Value)) { [void]$parts.Add(('{0}={1}' -f $name, [string]$prop.Value)) }
        } catch { }
    }
    if ($parts.Count -eq 0) { return ([string]$Device) }
    return ($parts.ToArray() -join ' | ')
}

function New-RealtekIntMitiV2TopologyErrorLabels {
    param([int]$Count, [string]$Error)
    $safeCount = [Math]::Max(1, $Count)
    $safeError = if ([string]::IsNullOrWhiteSpace($Error)) { 'unknown topology read error' } else { ($Error -replace '[\r\n]+', ' ') }
    $labels = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $safeCount; $i++) {
        $offset = 0x0A00 + ($i * 4)
        if (($i % 2) -eq 0) {
            $q = [int]($i / 2)
            [void]$labels.Add(('RXQ{0}/TXQ{0} unresolved -> IntMITI{1}@0x{2:X4} low=RX high=TX [topology read failed: {3}]' -f $q, $i, $offset, $safeError))
        } else {
            [void]$labels.Add(('No queue claim -> IntMITI{0}@0x{1:X4} adjacent low16/RX-only candidate [topology read failed: {2}]' -f $i, $offset, $safeError))
        }
    }
    return [string[]]$labels.ToArray()
}

function ConvertFrom-RealtekQueueLog2Code {
    param([int]$Code, [int]$Max = 128)
    $map = [ordered]@{ '0' = 1; '1' = 2; '2' = 4; '3' = 8; '4' = 16; '5' = 32; '6' = 64; '7' = 128 }
    $key = [string]([int]$Code -band 0x7)
    $value = if ($map.Contains($key)) { [int]$map[$key] } else { 1 }
    if ($Max -gt 0 -and $value -gt $Max) { return [int]$Max }
    return [int]$value
}

function Get-RealtekIntMitiV2QueueSlotLimit {
    param([hashtable]$nicInfo)
    $maxBanks = 64
    if ($null -ne $nicInfo -and $nicInfo.ContainsKey('MaxQueues')) {
        try { $maxBanks = [Math]::Max(1, [int]$nicInfo.MaxQueues) } catch { $maxBanks = 64 }
    }
    $derivedSlots = [Math]::Max(1, [Math]::Min(32, [int][Math]::Ceiling(([double]$maxBanks) / 2.0)))
    $layout = Resolve-RealtekQueueModerationLayout -nicInfo $nicInfo
    if ($null -ne $layout -and $layout.ContainsKey('QueueSlots')) {
        try { return [Math]::Max(1, [Math]::Min($derivedSlots, [int]$layout.QueueSlots)) } catch { return $derivedSlots }
    }
    return $derivedSlots
}

function ConvertTo-RealtekU64Pair {
    param([uint64]$Low, [uint64]$High)
    $mask32 = [Convert]::ToUInt64('FFFFFFFF', 16)
    return (([uint64]$High -shl 32) -bor (([uint64]$Low) -band $mask32))
}

function New-RealtekTopologyRegisterPair {
    param([string]$Name, [int]$Queue, [uint64]$LowOffset, [uint64]$HighOffset)
    return [PSCustomObject]@{ Name = $Name; Queue = [int]$Queue; LowOffset = [uint64]$LowOffset; HighOffset = [uint64]$HighOffset }
}

function Read-RealtekMacOcp16 {
    param([uint64]$Bar, [uint16]$OcpAddress)
    $macOcpAddr = [uint64]($Bar + 0x00B0)
    $addrDiv2 = [uint32]([uint16]([uint32]$OcpAddress / 2))
    $commandValue = [uint32]($addrDiv2 -shl 16)
    $hexAddress = Dec-To-Hex -decimal $macOcpAddr
    $timeout = [Math]::Max(30000, [int]$script:RWECommandTimeoutMs)
    try {
        Invoke-RWECommand -Command ('W32 {0} 0x{1:X8}' -f $hexAddress, $commandValue) -AllowEmptyOutput -TimeoutMs $timeout | Out-Null
        $batch = Invoke-RWEReadBatch -Addresses ([uint64[]]@($macOcpAddr)) -Width 32 -TimeoutMs $timeout
        $raw = Get-DeviceTweakerBatchValue -Batch $batch -Address $macOcpAddr -Name ('MACOCP[0x{0:X4}]' -f $OcpAddress) -Mask 0xFFFFFFFF
        return [PSCustomObject]@{ Address = [uint64]$macOcpAddr; OcpAddress = [uint16]$OcpAddress; Raw = [uint64]$raw; Value = [uint16]($raw -band 0xFFFF); Error = $null }
    }
    catch {
        return [PSCustomObject]@{ Address = [uint64]$macOcpAddr; OcpAddress = [uint16]$OcpAddress; Raw = $null; Value = $null; Error = $_.Exception.Message }
    }
}


function Get-RealtekITRPropertyValue {
    param([AllowNull()][object]$Object, [Parameter(Mandatory=$true)][string]$Name)
    if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) { return $null }
    try {
        if ($Object -is [System.Collections.IDictionary]) {
            if ($Object.Contains($Name)) { return $Object[$Name] }
            if ($Object.ContainsKey($Name)) { return $Object[$Name] }
        }
    } catch { }
    try {
        $prop = $Object.PSObject.Properties[$Name]
        if ($null -ne $prop) { return $prop.Value }
    } catch { }
    return $null
}

function Get-RealtekITRStringCandidateList {
    param([AllowNull()][object]$Device)
    $items = [System.Collections.Generic.List[string]]::new()
    foreach ($name in @('Name','InterfaceAlias','InterfaceName','FriendlyName','DisplayName','Description','DeviceName','NetConnectionID')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value)) { [void]$items.Add(([string]$value).Trim()) }
    }
    $unique = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in $items) {
        if ([string]::IsNullOrWhiteSpace($item)) { continue }
        if ($seen.Add($item)) { [void]$unique.Add($item) }
    }
    return [string[]]$unique.ToArray()
}

function Get-RealtekITRFirstIntProperty {
    param([AllowNull()][object]$Object, [string[]]$Names)
    foreach ($name in @($Names)) {
        $value = Get-RealtekITRPropertyValue -Object $Object -Name $name
        if ($null -eq $value) { continue }
        try {
            $text = ([string]$value).Trim()
            if ([string]::IsNullOrWhiteSpace($text)) { continue }
            return [int]([Convert]::ToInt64($text, 0))
        } catch { }
    }
    return $null
}

function Format-RealtekITRNullableText {
    param(
        [AllowNull()][object]$Value,
        [string]$Unavailable = 'n/a'
    )
    if ($null -eq $Value) { return [string]$Unavailable }
    try {
        $text = ([string]$Value).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return [string]$Unavailable }
        return $text
    } catch {
        return [string]$Unavailable
    }
}


function Format-RealtekITRProbeErrorsBrief {
    param([AllowNull()][object]$ProbeErrors)
    $items = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($raw in @($ProbeErrors)) {
        if ($null -eq $raw) { continue }
        $e = ([string]$raw).Trim()
        if ([string]::IsNullOrWhiteSpace($e)) { continue }
        $tag = 'Other'
        if ($e -like 'NetAdapter module import failed*') { $tag = 'Import' }
        elseif ($e -like 'Get-NetAdapterRss command is not available*') { $tag = 'CmdMissing' }
        elseif ($e -like 'Get-NetAdapterRss -Name "*" failed*') { $tag = 'Name' }
        elseif ($e -like 'Get-NetAdapterRss -Name "*" enumeration failed*') { $tag = 'All' }
        elseif ($e -like 'Get-NetAdapterRss matched adapter*') { $tag = 'MatchedName' }
        elseif ($e -like 'Get-NetAdapter enumeration failed*') { $tag = 'GetNetAdapter' }
        elseif ($e -like 'MSFT_NetAdapterRss CIM query failed*') { $tag = 'CIM' }
        if ($seen.Add($tag)) { [void]$items.Add($tag) }
    }
    if ($items.Count -eq 0) { return 'none' }
    return ($items.ToArray() -join '+')
}

function Test-RealtekITRAdapterObjectMatchesDevice {
    param(
        [AllowNull()][object]$Object,
        [AllowNull()][string[]]$Candidates,
        [AllowNull()][object]$Identity
    )
    if ($null -eq $Object) { return $false }

    $objectTexts = [System.Collections.Generic.List[string]]::new()
    foreach ($name in @('Name','InterfaceDescription','InterfaceAlias','Description','InterfaceName','NetConnectionID')) {
        $value = Get-RealtekITRPropertyValue -Object $Object -Name $name
        if ($null -ne $value -and -not [string]::IsNullOrWhiteSpace([string]$value)) { [void]$objectTexts.Add(([string]$value).Trim()) }
    }
    foreach ($candidate in @($Candidates)) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        foreach ($objectText in @($objectTexts.ToArray())) {
            if ([string]::IsNullOrWhiteSpace($objectText)) { continue }
            if ($objectText.IndexOf($candidate, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or $candidate.IndexOf($objectText, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $true }
        }
    }

    if ($null -ne $Identity -and -not [string]::IsNullOrWhiteSpace([string]$Identity.VendorId) -and -not [string]::IsNullOrWhiteSpace([string]$Identity.DeviceId)) {
        $raws = [System.Collections.Generic.List[string]]::new()
        foreach ($name in @('PNPDeviceID','PnpDeviceID','InstanceId','InstanceID','DeviceID','MatchingDeviceId','HardwareID','HardwareIds')) {
            $value = Get-RealtekITRPropertyValue -Object $Object -Name $name
            if ($null -eq $value) { continue }
            foreach ($v in @($value)) { if ($null -ne $v -and -not [string]::IsNullOrWhiteSpace([string]$v)) { [void]$raws.Add([string]$v) } }
        }
        if ($raws.Count -gt 0) {
            $oid = Get-RealtekITRPciIdentityFromText -Text ([string[]]$raws.ToArray())
            if ($null -ne $oid -and [string]$oid.VendorId -eq [string]$Identity.VendorId -and [string]$oid.DeviceId -eq [string]$Identity.DeviceId) { return $true }
        }
    }
    return $false
}

function New-RealtekRssV2RuntimeSnapshotFromObject {
    param(
        [Parameter(Mandatory=$true)][object]$Object,
        [Parameter(Mandatory=$true)][string]$Source,
        [Parameter(Mandatory=$true)][int]$OSBuild,
        [AllowNull()][string]$AdapterName,
        [AllowNull()][string[]]$ProbeErrors
    )
    $enabledRaw = Get-RealtekITRPropertyValue -Object $Object -Name 'Enabled'
    $enabled = $null
    if ($null -ne $enabledRaw) {
        try { $enabled = [bool]$enabledRaw } catch { $enabled = $null }
    }
    $queueCount = Get-RealtekITRFirstIntProperty -Object $Object -Names @('NumberOfReceiveQueues','NumberOfRxQueues','ReceiveQueueCount','QueueCount','NumberOfQueues','MaxReceiveQueues')
    $iteCount = Get-RealtekITRFirstIntProperty -Object $Object -Names @('NumberOfIndirectionTableEntries','IndirectionTableEntryCount','IndirectionTableSize','NumberOfIndirectionTableEntriesRequested')
    if ($null -eq $iteCount) {
        $indirection = Get-RealtekITRPropertyValue -Object $Object -Name 'IndirectionTable'
        if ($null -ne $indirection) {
            try { $iteCount = [int]@($indirection).Count } catch { }
        }
    }
    $profile = Get-RealtekITRPropertyValue -Object $Object -Name 'Profile'
    $hashFunction = Get-RealtekITRPropertyValue -Object $Object -Name 'HashFunction'
    $hashTypes = Get-RealtekITRPropertyValue -Object $Object -Name 'HashTypes'
    $hashKeyLength = $null
    foreach ($keyName in @('HashKey','HashSecretKey','SecretKey')) {
        $keyValue = Get-RealtekITRPropertyValue -Object $Object -Name $keyName
        if ($null -eq $keyValue) { continue }
        try { $hashKeyLength = [int]@($keyValue).Count; break } catch { }
    }
    $runtimeVisible = ($null -ne $queueCount -or $null -ne $iteCount -or $null -ne $enabled)
    $status = if ($OSBuild -ge 17134) { if ($runtimeVisible) { 'OS_build_RSSv2_eligible_adapter_runtime_visible' } else { 'OS_build_RSSv2_eligible_adapter_runtime_fields_absent' } } else { 'OS_pre_RSSv2' }
    $e = if ($null -ne $ProbeErrors) { [string[]]$ProbeErrors } else { [string[]]@() }
    return [PSCustomObject]@{
        Source = [string]$Source
        AdapterName = [string]$AdapterName
        OSBuild = [int]$OSBuild
        OSRssV2Capable = [bool]($OSBuild -ge 17134)
        RssV2RuntimeVisible = [bool]$runtimeVisible
        RssV2Status = [string]$status
        Enabled = $enabled
        NumberOfReceiveQueues = $queueCount
        NumberOfIndirectionTableEntries = $iteCount
        Profile = if ($null -ne $profile) { [string]$profile } else { $null }
        HashFunction = if ($null -ne $hashFunction) { [string]$hashFunction } else { $null }
        HashTypes = if ($null -ne $hashTypes) { [string]$hashTypes } else { $null }
        HashKeyLength = $hashKeyLength
        ProbeErrors = $e
        DirectOidCapability = 'user-mode-unavailable'
        CpuMaskSource = 'not-read-from-registry'
    }
}


function ConvertTo-RealtekITREnumPciInstanceIdFromRegistryPath {
    param([AllowNull()][string]$Path)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $p = ([string]$Path).Trim()
    $p = $p -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
    $p = $p -replace '^HKLM:\\',''
    $p = $p -replace '^HKEY_LOCAL_MACHINE\\',''
    $p = $p.Trim('\')
    if ($p.StartsWith('PCI\', [System.StringComparison]::OrdinalIgnoreCase)) { return $p }
    $enumNeedle = 'SYSTEM\CurrentControlSet\Enum\PCI\'
    $idx = $p.IndexOf($enumNeedle, [System.StringComparison]::OrdinalIgnoreCase)
    if ($idx -ge 0) {
        $tail = $p.Substring($idx + $enumNeedle.Length)
        if (-not [string]::IsNullOrWhiteSpace($tail)) { return ('PCI\' + $tail.Trim('\')) }
    }
    $enumNeedle2 = 'Enum\PCI\'
    $idx = $p.IndexOf($enumNeedle2, [System.StringComparison]::OrdinalIgnoreCase)
    if ($idx -ge 0) {
        $tail = $p.Substring($idx + $enumNeedle2.Length)
        if (-not [string]::IsNullOrWhiteSpace($tail)) { return ('PCI\' + $tail.Trim('\')) }
    }
    return $null
}

function ConvertTo-RealtekITRRegistryPathFromInstanceId {
    param([AllowNull()][string]$InstanceId)
    if ([string]::IsNullOrWhiteSpace($InstanceId)) { return $null }
    $id = ([string]$InstanceId).Trim().Trim('\')
    if ($id.StartsWith('PCI\', [System.StringComparison]::OrdinalIgnoreCase)) { return ('HKLM:\SYSTEM\CurrentControlSet\Enum\' + $id) }
    return $null
}

function Add-RealtekITRUniqueString {
    param([System.Collections.Generic.List[string]]$List, [System.Collections.Generic.HashSet[string]]$Seen, [AllowNull()][object]$Value)
    if ($null -eq $Value) { return }
    foreach ($item in @($Value)) {
        if ($null -eq $item) { continue }
        $text = ([string]$item).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        if ($Seen.Add($text)) { [void]$List.Add($text) }
    }
}

function Test-RealtekITRLooksLikePciHardwareId {
    param([AllowNull()][string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return $false }
    $v = ([string]$Value).Trim().Trim('\')
    return ($v.StartsWith('PCI\', [System.StringComparison]::OrdinalIgnoreCase) -and $v.IndexOf('VEN_', [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $v.IndexOf('DEV_', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Test-RealtekITRLooksLikeFullPciInstanceId {
    param([AllowNull()][string]$Value)
    if (-not (Test-RealtekITRLooksLikePciHardwareId -Value $Value)) { return $false }
    $v = ([string]$Value).Trim().Trim('\')
    $parts = $v -split '\\'
    return ($parts.Count -ge 3 -and -not [string]::IsNullOrWhiteSpace([string]$parts[2]))
}

function Test-RealtekITRHardwareIdMatchesPnpInstance {
    param([AllowNull()][string]$HardwareId, [AllowNull()][string]$InstanceId)
    if (-not (Test-RealtekITRLooksLikePciHardwareId -Value $HardwareId)) { return $false }
    if (-not (Test-RealtekITRLooksLikeFullPciInstanceId -Value $InstanceId)) { return $false }
    $h = ([string]$HardwareId).Trim().Trim('\')
    $i = ([string]$InstanceId).Trim().Trim('\')
    return ($i.Equals($h, [System.StringComparison]::OrdinalIgnoreCase) -or $i.StartsWith(($h + '\'), [System.StringComparison]::OrdinalIgnoreCase) -or $i.StartsWith($h, [System.StringComparison]::OrdinalIgnoreCase))
}

function Add-RealtekITRFullPciInstanceCandidate {
    param(
        [System.Collections.Generic.List[string]]$List,
        [System.Collections.Generic.HashSet[string]]$Seen,
        [AllowNull()][object]$Value
    )
    foreach ($raw in @($Value)) {
        if ($null -eq $raw) { continue }
        $candidate = ([string]$raw).Trim().Trim('\')
        if (Test-RealtekITRLooksLikeFullPciInstanceId -Value $candidate) { Add-RealtekITRUniqueString -List $List -Seen $Seen -Value $candidate }
    }
}

function Test-RealtekITRHardwareIdPresentInArray {
    param([AllowNull()][string]$HardwareId, [AllowNull()][object]$HardwareIds)
    if (-not (Test-RealtekITRLooksLikePciHardwareId -Value $HardwareId)) { return $false }
    $h = ([string]$HardwareId).Trim().Trim('\')
    foreach ($raw in @($HardwareIds)) {
        if ($null -eq $raw) { continue }
        $x = ([string]$raw).Trim().Trim('\')
        if ([string]::IsNullOrWhiteSpace($x)) { continue }
        if ($x.Equals($h, [System.StringComparison]::OrdinalIgnoreCase) -or $x.StartsWith($h, [System.StringComparison]::OrdinalIgnoreCase) -or $h.StartsWith($x, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }
    return $false
}

function Add-RealtekITRResolvedPnpInstances {
    param(
        [System.Collections.Generic.List[string]]$List,
        [System.Collections.Generic.HashSet[string]]$Seen,
        [AllowNull()][object]$Value
    )
    if ($null -eq $List -or $null -eq $Seen -or $null -eq $Value) { return }
    foreach ($raw in @($Value)) {
        if ($null -eq $raw) { continue }
        $candidate = ([string]$raw).Trim().Trim('\')
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        if (-not (Test-RealtekITRLooksLikePciHardwareId -Value $candidate)) { continue }

        if (Test-RealtekITRLooksLikeFullPciInstanceId -Value $candidate) {
            Add-RealtekITRFullPciInstanceCandidate -List $List -Seen $Seen -Value $candidate
            try {
                $exactPnp = @(Get-PnpDevice -InstanceId $candidate -ErrorAction SilentlyContinue)
                foreach ($p in $exactPnp) { Add-RealtekITRFullPciInstanceCandidate -List $List -Seen $Seen -Value (Get-RealtekITRPropertyValue -Object $p -Name 'InstanceId') }
            } catch { }
            continue
        }

        foreach ($className in @('Net',$null)) {
            try {
                $pnpItems = if ([string]::IsNullOrWhiteSpace([string]$className)) { @(Get-PnpDevice -ErrorAction SilentlyContinue) } else { @(Get-PnpDevice -Class $className -ErrorAction SilentlyContinue) }
                foreach ($p in $pnpItems) {
                    $iid = Get-RealtekITRPropertyValue -Object $p -Name 'InstanceId'
                    if (Test-RealtekITRHardwareIdMatchesPnpInstance -HardwareId $candidate -InstanceId ([string]$iid)) { Add-RealtekITRFullPciInstanceCandidate -List $List -Seen $Seen -Value ([string]$iid) }
                }
            } catch { }
        }

        try {
            $adapters = @(Get-CimInstance -ClassName Win32_NetworkAdapter -ErrorAction SilentlyContinue)
            foreach ($adapter in $adapters) {
                $pnp = Get-RealtekITRPropertyValue -Object $adapter -Name 'PNPDeviceID'
                if (Test-RealtekITRHardwareIdMatchesPnpInstance -HardwareId $candidate -InstanceId ([string]$pnp)) { Add-RealtekITRFullPciInstanceCandidate -List $List -Seen $Seen -Value ([string]$pnp) }
            }
        } catch { }

        try {
            $entities = @(Get-CimInstance -ClassName Win32_PnPEntity -ErrorAction SilentlyContinue)
            foreach ($entity in $entities) {
                $hardwareIds = Get-RealtekITRPropertyValue -Object $entity -Name 'HardwareID'
                $byHardwareArray = Test-RealtekITRHardwareIdPresentInArray -HardwareId $candidate -HardwareIds $hardwareIds
                foreach ($propName in @('PNPDeviceID','DeviceID')) {
                    $iid = Get-RealtekITRPropertyValue -Object $entity -Name $propName
                    if ($byHardwareArray -or (Test-RealtekITRHardwareIdMatchesPnpInstance -HardwareId $candidate -InstanceId ([string]$iid))) { Add-RealtekITRFullPciInstanceCandidate -List $List -Seen $Seen -Value ([string]$iid) }
                }
            }
        } catch { }
    }
}

function ConvertTo-RealtekITRWqlStringLiteral {
    param([AllowNull()][string]$Value)
    if ($null -eq $Value) { return "''" }
    return ("'{0}'" -f (([string]$Value).Replace('\','\\').Replace("'","''")))
}

function Get-RealtekITRDeviceInstanceIdCandidates {
    param([AllowNull()][object]$Device)
    $items = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in @('PNPID','PNPDeviceID','DeviceID','InstanceId','InstanceID','DeviceInstanceId')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -ne $value) { Add-RealtekITRUniqueString -List $items -Seen $seen -Value $value }
    }
    foreach ($name in @('RegistryPath','PSPath','DeviceKey')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -eq $value) { continue }
        $instance = ConvertTo-RealtekITREnumPciInstanceIdFromRegistryPath -Path ([string]$value)
        if (-not [string]::IsNullOrWhiteSpace($instance)) { Add-RealtekITRUniqueString -List $items -Seen $seen -Value $instance }
    }
    foreach ($name in @('ConfigPath','AdapterConfigPath','NetClassPath','RegistryPath','PSPath','DeviceKey')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -eq $value -or [string]::IsNullOrWhiteSpace([string]$value)) { continue }
        try {
            $cfgPath = ([string]$value) -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
            if ($cfgPath.StartsWith('HKEY_LOCAL_MACHINE\', [System.StringComparison]::OrdinalIgnoreCase)) { $cfgPath = 'HKLM:\' + $cfgPath.Substring('HKEY_LOCAL_MACHINE\'.Length) }
            elseif (-not $cfgPath.StartsWith('HKLM:\', [System.StringComparison]::OrdinalIgnoreCase)) { $cfgPath = 'HKLM:\' + $cfgPath.Trim('\') }
            $cfg = Get-ItemProperty -LiteralPath $cfgPath -ErrorAction Stop
            foreach ($cfgName in @('MatchingDeviceId','DeviceInstanceID','PNPDeviceID')) {
                $cfgValue = $cfg.PSObject.Properties[$cfgName]
                if ($null -ne $cfgValue -and $null -ne $cfgValue.Value) { Add-RealtekITRUniqueString -List $items -Seen $seen -Value $cfgValue.Value }
            }
            $hw = $cfg.PSObject.Properties['HardwareID']
            if ($null -ne $hw -and $null -ne $hw.Value) { Add-RealtekITRUniqueString -List $items -Seen $seen -Value $hw.Value }
            $netCfg = $cfg.PSObject.Properties['NetCfgInstanceId']
            if ($null -ne $netCfg -and $null -ne $netCfg.Value) {
                $guidText = ([string]$netCfg.Value).Trim('{}')
                if (-not [string]::IsNullOrWhiteSpace($guidText)) {
                    try {
                        $wmi = @()
                        try { $wmi += @(Get-CimInstance -ClassName Win32_NetworkAdapter -Filter ("GUID='{0}'" -f $guidText) -ErrorAction Stop) } catch { }
                        try { $wmi += @(Get-CimInstance -ClassName Win32_NetworkAdapter -Filter ("GUID='{{{0}}}'" -f $guidText) -ErrorAction Stop) } catch { }
                        if ($wmi.Count -eq 0) {
                            foreach ($adapter in @(Get-CimInstance -ClassName Win32_NetworkAdapter -ErrorAction SilentlyContinue)) {
                                $adapterGuid = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'GUID')
                                if (-not [string]::IsNullOrWhiteSpace($adapterGuid) -and $adapterGuid.Trim('{}').Equals($guidText, [System.StringComparison]::OrdinalIgnoreCase)) { $wmi += $adapter }
                            }
                        }
                        foreach ($adapter in $wmi) { Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'PNPDeviceID') }
                    } catch { }
                }
            }
        } catch { }
    }
    $filtered = [System.Collections.Generic.List[string]]::new()
    $filteredSeen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($items.ToArray())) {
        if ([string]::IsNullOrWhiteSpace($item)) { continue }
        if ($item.IndexOf('PCI\', [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or $item.IndexOf('VEN_', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
            Add-RealtekITRResolvedPnpInstances -List $filtered -Seen $filteredSeen -Value $item
        }
    }
    return [string[]]$filtered.ToArray()
}

function Get-RealtekITRPciIdentityFromText {
    param([AllowNull()][object]$Text)
    foreach ($raw in @($Text)) {
        if ($null -eq $raw) { continue }
        $s = [string]$raw
        if ([string]::IsNullOrWhiteSpace($s)) { continue }
        $m = [regex]::Match($s, 'VEN_([0-9A-Fa-f]{4}).*?DEV_([0-9A-Fa-f]{4})')
        if (-not $m.Success) { continue }
        $subVendor = $null
        $subDevice = $null
        $sub = [regex]::Match($s, 'SUBSYS_([0-9A-Fa-f]{8})')
        if ($sub.Success) {
            $subDevice = $sub.Groups[1].Value.Substring(0,4).ToUpperInvariant()
            $subVendor = $sub.Groups[1].Value.Substring(4,4).ToUpperInvariant()
        }
        return [PSCustomObject]@{
            VendorId = $m.Groups[1].Value.ToUpperInvariant()
            DeviceId = $m.Groups[2].Value.ToUpperInvariant()
            SubVendorId = $subVendor
            SubDeviceId = $subDevice
        }
    }
    return $null
}

function Get-RealtekITRDevicePciIdentity {
    param([AllowNull()][object]$Device)
    $raws = [System.Collections.Generic.List[string]]::new()
    foreach ($inst in @(Get-RealtekITRDeviceInstanceIdCandidates -Device $Device)) { if (-not [string]::IsNullOrWhiteSpace($inst)) { [void]$raws.Add([string]$inst) } }
    foreach ($name in @('PNPID','PNPDeviceID','DeviceID','InstanceId','InstanceID','RegistryPath','PSPath','DeviceKey','HardwareID','HardwareIds','MatchingDeviceId')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -ne $value) { foreach ($v in @($value)) { if ($null -ne $v) { [void]$raws.Add([string]$v) } } }
    }
    return Get-RealtekITRPciIdentityFromText -Text ([string[]]$raws.ToArray())
}

function New-RealtekITRBdfObject {
    param([int]$Segment, [int]$Bus, [int]$Device, [int]$Function, [string]$Source)
    if ($Bus -lt 0 -or $Bus -gt 255 -or $Device -lt 0 -or $Device -gt 31 -or $Function -lt 0 -or $Function -gt 7) { return $null }
    return [PSCustomObject]@{ Segment = [int]$Segment; Bus = [int]$Bus; Device = [int]$Device; Function = [int]$Function; Source = [string]$Source; Bdf = [DeviceTweakerPciEcam]::FormatBdf([int]$Segment,[int]$Bus,[int]$Device,[int]$Function) }
}

function ConvertFrom-RealtekITRLocationInfoToBdf {
    param([AllowNull()][string]$LocationInfo, [string]$Source = 'LocationInformation')
    if ([string]::IsNullOrWhiteSpace($LocationInfo)) { return $null }
    $loc = ([string]$LocationInfo).Trim()
    $mSeg = [regex]::Match($loc, 'PCI\s+segment\s+(\d+)\s+bus\s+(\d+)\s*,\s*device\s+(\d+)\s*,\s*function\s+(\d+)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($mSeg.Success) {
        return (New-RealtekITRBdfObject -Segment ([int]$mSeg.Groups[1].Value) -Bus ([int]$mSeg.Groups[2].Value) -Device ([int]$mSeg.Groups[3].Value) -Function ([int]$mSeg.Groups[4].Value) -Source ('{0} "{1}"' -f $Source, $loc))
    }
    $m = [regex]::Match($loc, 'PCI\s+bus\s+(\d+)\s*,\s*device\s+(\d+)\s*,\s*function\s+(\d+)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($m.Success) {
        return (New-RealtekITRBdfObject -Segment 0 -Bus ([int]$m.Groups[1].Value) -Device ([int]$m.Groups[2].Value) -Function ([int]$m.Groups[3].Value) -Source ('{0} "{1}"' -f $Source, $loc))
    }
    try {
        $parsed = [DeviceTweakerPathHelpers]::ParseBdfLocation($loc)
        if ($null -ne $parsed -and $parsed.Success) { return (New-RealtekITRBdfObject -Segment 0 -Bus ([int]$parsed.Bus) -Device ([int]$parsed.Device) -Function ([int]$parsed.Function) -Source ('{0} "{1}"' -f $Source, $loc)) }
    } catch { }
    return $null
}

function ConvertFrom-RealtekITRPciAddressProperty {
    param([AllowNull()][object]$Address)
    $items = [System.Collections.Generic.List[object]]::new()
    if ($null -eq $Address) { return [object[]]@() }
    try { $a = [int64]([Convert]::ToInt64(([string]$Address).Trim(), 0)) } catch { try { $a = [int64]$Address } catch { return [object[]]@() } }
    $candidatePairs = @(
        @{ Device = [int](($a -shr 16) -band 0xFFFF); Function = [int]($a -band 0xFFFF); Mode = 'SPDRP_ADDRESS hiword=device lowword=function' },
        @{ Device = [int](($a -shr 8) -band 0x1F); Function = [int]($a -band 0x7); Mode = 'byte-packed device/function fallback' },
        @{ Device = [int](($a -shr 3) -band 0x1F); Function = [int]($a -band 0x7); Mode = 'PCI devfn fallback' }
    )
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($p in $candidatePairs) {
        $dev = [int]$p.Device
        $fn = [int]$p.Function
        if ($dev -lt 0 -or $dev -gt 31 -or $fn -lt 0 -or $fn -gt 7) { continue }
        $key = ('{0}.{1}' -f $dev,$fn)
        if (-not $seen.Add($key)) { continue }
        [void]$items.Add([PSCustomObject]@{ Device = $dev; Function = $fn; Mode = [string]$p.Mode; RawAddress = [int64]$a })
    }
    return [object[]]$items.ToArray()
}

function Test-RealtekITRBdfMatchesDeviceIdentity {
    param([AllowNull()][object]$Bdf, [AllowNull()][object]$Device, [AllowNull()][object]$Identity)
    if ($null -eq $Bdf) { return $false }
    $id = $Identity
    if ($null -eq $id) { $id = Get-RealtekITRDevicePciIdentity -Device $Device }
    if ($null -eq $id -or [string]::IsNullOrWhiteSpace([string]$id.VendorId) -or [string]::IsNullOrWhiteSpace([string]$id.DeviceId)) { return $true }
    try {
        $raw = [uint32](Read-PciConfigValue -Segment ([int]$Bdf.Segment) -Bus ([int]$Bdf.Bus) -Device ([int]$Bdf.Device) -Function ([int]$Bdf.Function) -Offset 0x00 -Width 32)
        if ($raw -eq [uint32]0xFFFFFFFF -or $raw -eq [uint32]0) { return $false }
        $vendor = ('{0:X4}' -f ([int]($raw -band [uint32]0xFFFF)))
        $deviceId = ('{0:X4}' -f ([int](($raw -shr 16) -band [uint32]0xFFFF)))
        return ($vendor -eq ([string]$id.VendorId).ToUpperInvariant() -and $deviceId -eq ([string]$id.DeviceId).ToUpperInvariant())
    } catch {
        return $true
    }
}

function Get-RealtekITRNetAdapterNameCandidates {
    param([AllowNull()][object]$Device)
    $items = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $instances = [string[]](Get-RealtekITRDeviceInstanceIdCandidates -Device $Device)
    $identity = Get-RealtekITRDevicePciIdentity -Device $Device
    $netCfgGuid = $null
    foreach ($name in @('ConfigPath','AdapterConfigPath','NetClassPath')) {
        $cfgPath = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -eq $cfgPath -or [string]::IsNullOrWhiteSpace([string]$cfgPath)) { continue }
        try {
            $p = ([string]$cfgPath) -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
            if ($p.StartsWith('HKEY_LOCAL_MACHINE\', [System.StringComparison]::OrdinalIgnoreCase)) { $p = 'HKLM:\' + $p.Substring('HKEY_LOCAL_MACHINE\'.Length) }
            elseif (-not $p.StartsWith('HKLM:\', [System.StringComparison]::OrdinalIgnoreCase)) { $p = 'HKLM:\' + $p.Trim('\') }
            $cfg = Get-ItemProperty -LiteralPath $p -ErrorAction Stop
            $g = $cfg.PSObject.Properties['NetCfgInstanceId']
            if ($null -ne $g -and $null -ne $g.Value -and -not [string]::IsNullOrWhiteSpace([string]$g.Value)) { $netCfgGuid = ([string]$g.Value).Trim('{}'); break }
        } catch { }
    }
    try {
        $wmiAdapters = @(Get-CimInstance -ClassName Win32_NetworkAdapter -ErrorAction SilentlyContinue)
        foreach ($adapter in $wmiAdapters) {
            $pnp = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'PNPDeviceID')
            $guid = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'GUID')
            $matched = $false
            foreach ($inst in @($instances)) {
                if (-not [string]::IsNullOrWhiteSpace($inst) -and -not [string]::IsNullOrWhiteSpace($pnp) -and ($pnp.Equals($inst, [System.StringComparison]::OrdinalIgnoreCase) -or $pnp.StartsWith($inst, [System.StringComparison]::OrdinalIgnoreCase) -or $inst.StartsWith($pnp, [System.StringComparison]::OrdinalIgnoreCase))) { $matched = $true; break }
            }
            if (-not $matched -and -not [string]::IsNullOrWhiteSpace($netCfgGuid) -and -not [string]::IsNullOrWhiteSpace($guid)) {
                if ($guid.Trim('{}').Equals($netCfgGuid, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true }
            }
            if (-not $matched -and $null -ne $identity -and -not [string]::IsNullOrWhiteSpace($pnp)) {
                $aid = Get-RealtekITRPciIdentityFromText -Text $pnp
                if ($null -ne $aid -and [string]$aid.VendorId -eq [string]$identity.VendorId -and [string]$aid.DeviceId -eq [string]$identity.DeviceId) { $matched = $true }
            }
            if ($matched) {
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'NetConnectionID')
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'Name')
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'Description')
            }
        }
    } catch { }
    try {
        $adapters = @()
        try { $adapters = @(Get-NetAdapter -IncludeHidden -ErrorAction Stop) } catch { $adapters = @(Get-NetAdapter -ErrorAction Stop) }
        foreach ($adapter in $adapters) {
            $adapterName = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'Name')
            $adapterAlias = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'InterfaceAlias')
            $adapterDesc = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'InterfaceDescription')
            $adapterPnp = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'PnpDeviceID')
            $adapterGuid = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'InterfaceGuid')
            $matched = $false
            foreach ($inst in @($instances)) {
                if ([string]::IsNullOrWhiteSpace($inst) -or [string]::IsNullOrWhiteSpace($adapterPnp)) { continue }
                if ($adapterPnp.Equals($inst, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true; break }
            }
            if (-not $matched -and -not [string]::IsNullOrWhiteSpace($netCfgGuid) -and -not [string]::IsNullOrWhiteSpace($adapterGuid)) {
                if ($adapterGuid.Trim('{}').Equals($netCfgGuid, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true }
            }
            if (-not $matched -and $null -ne $identity -and -not [string]::IsNullOrWhiteSpace([string]$identity.VendorId) -and -not [string]::IsNullOrWhiteSpace([string]$identity.DeviceId) -and -not [string]::IsNullOrWhiteSpace($adapterPnp)) {
                $aid = Get-RealtekITRPciIdentityFromText -Text $adapterPnp
                if ($null -ne $aid -and [string]$aid.VendorId -eq [string]$identity.VendorId -and [string]$aid.DeviceId -eq [string]$identity.DeviceId) { $matched = $true }
            }
            if ($matched) {
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value $adapterName
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value $adapterAlias
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value $adapterDesc
            }
        }
    } catch { }
    try {
        $wmiAdapters = @(Get-CimInstance -ClassName Win32_NetworkAdapter -ErrorAction Stop)
        foreach ($adapter in $wmiAdapters) {
            $pnp = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'PNPDeviceID')
            $guid = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'GUID')
            $matched = $false
            foreach ($inst in @($instances)) {
                if (-not [string]::IsNullOrWhiteSpace($inst) -and -not [string]::IsNullOrWhiteSpace($pnp) -and $pnp.Equals($inst, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true; break }
            }
            if (-not $matched -and -not [string]::IsNullOrWhiteSpace($netCfgGuid) -and -not [string]::IsNullOrWhiteSpace($guid)) {
                if ($guid.Trim('{}').Equals($netCfgGuid, [System.StringComparison]::OrdinalIgnoreCase)) { $matched = $true }
            }
            if (-not $matched -and $null -ne $identity -and -not [string]::IsNullOrWhiteSpace($pnp)) {
                $aid = Get-RealtekITRPciIdentityFromText -Text $pnp
                if ($null -ne $aid -and [string]$aid.VendorId -eq [string]$identity.VendorId -and [string]$aid.DeviceId -eq [string]$identity.DeviceId) { $matched = $true }
            }
            if ($matched) {
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'NetConnectionID')
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'Name')
                Add-RealtekITRUniqueString -List $items -Seen $seen -Value (Get-RealtekITRPropertyValue -Object $adapter -Name 'Description')
            }
        }
    } catch { }
    return [string[]]$items.ToArray()
}


function Get-RealtekRssV2RuntimeSnapshot {
    param([AllowNull()][object]$Device, [int]$QueueSlotLimit = 32)
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $Device
    $osBuild = 0
    try { $osBuild = [int][Environment]::OSVersion.Version.Build } catch { $osBuild = 0 }
    $nameCandidates = [System.Collections.Generic.List[string]]::new()
    $nameSeen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($candidate in @(Get-RealtekITRNetAdapterNameCandidates -Device $Device)) { Add-RealtekITRUniqueString -List $nameCandidates -Seen $nameSeen -Value $candidate }
    foreach ($candidate in @(Get-RealtekITRStringCandidateList -Device $Device)) { Add-RealtekITRUniqueString -List $nameCandidates -Seen $nameSeen -Value $candidate }
    $candidates = [string[]]$nameCandidates.ToArray()
    $identity = Get-RealtekITRDevicePciIdentity -Device $Device
    $errors = [System.Collections.Generic.List[string]]::new()
    Write-NICITRDiagnostic -Level Info -Message ('Realtek RSSv2 runtime probe start: device={0}; OSBuild={1}; candidates={2}' -f $deviceDebugName, $osBuild, ($candidates -join ' | '))
    try { Import-Module NetAdapter -ErrorAction SilentlyContinue } catch { [void]$errors.Add(('NetAdapter module import failed: {0}' -f $_.Exception.Message)) }
    $rssCommand = Get-Command Get-NetAdapterRss -ErrorAction SilentlyContinue
    if ($null -ne $rssCommand) {
        foreach ($candidate in @($candidates)) {
            try {
                $obj = Get-NetAdapterRss -Name $candidate -ErrorAction Stop
                if ($null -ne $obj) {
                    $snapshot = New-RealtekRssV2RuntimeSnapshotFromObject -Object $obj -Source 'Get-NetAdapterRss.Name' -OSBuild $osBuild -AdapterName $candidate -ProbeErrors ([string[]]$errors.ToArray())
                    Write-NICITRDiagnostic -Level Info -Message ('Realtek RSSv2 runtime probe matched by name: device={0}; source={1}; adapter={2}; enabled={3}; queues={4}; ITEs={5}; status={6}' -f $deviceDebugName, [string]$snapshot.Source, [string]$snapshot.AdapterName, [string]$snapshot.Enabled, [string]$snapshot.NumberOfReceiveQueues, [string]$snapshot.NumberOfIndirectionTableEntries, [string]$snapshot.RssV2Status)
                    return $snapshot
                }
            } catch {
                [void]$errors.Add(('Get-NetAdapterRss -Name "{0}" failed: {1}' -f $candidate, $_.Exception.Message))
            }
        }
        try {
            $rssAll = @(Get-NetAdapterRss -Name '*' -ErrorAction Stop)
            foreach ($obj in $rssAll) {
                $matched = Test-RealtekITRAdapterObjectMatchesDevice -Object $obj -Candidates $candidates -Identity $identity
                if (-not $matched -and $rssAll.Count -eq 1) { $matched = $true }
                if (-not $matched) { continue }
                $adapterName = [string](Get-RealtekITRPropertyValue -Object $obj -Name 'Name')
                $snapshot = New-RealtekRssV2RuntimeSnapshotFromObject -Object $obj -Source 'Get-NetAdapterRss.AllMatch' -OSBuild $osBuild -AdapterName $adapterName -ProbeErrors ([string[]]$errors.ToArray())
                Write-NICITRDiagnostic -Level Info -Message ('Realtek RSSv2 runtime probe matched from Get-NetAdapterRss *: device={0}; source={1}; adapter={2}; enabled={3}; queues={4}; ITEs={5}; status={6}' -f $deviceDebugName, [string]$snapshot.Source, [string]$snapshot.AdapterName, [string]$snapshot.Enabled, [string]$snapshot.NumberOfReceiveQueues, [string]$snapshot.NumberOfIndirectionTableEntries, [string]$snapshot.RssV2Status)
                return $snapshot
            }
        } catch {
            [void]$errors.Add(('Get-NetAdapterRss -Name "*" enumeration failed: {0}' -f $_.Exception.Message))
        }
        try {
            $adapters = @(Get-NetAdapter -ErrorAction Stop)
            foreach ($adapter in $adapters) {
                $matched = Test-RealtekITRAdapterObjectMatchesDevice -Object $adapter -Candidates $candidates -Identity $identity
                if (-not $matched) { continue }
                $adapterName = [string](Get-RealtekITRPropertyValue -Object $adapter -Name 'Name')
                if ([string]::IsNullOrWhiteSpace($adapterName)) { continue }
                try {
                    $obj = Get-NetAdapterRss -Name $adapterName -ErrorAction Stop
                    if ($null -ne $obj) {
                        $snapshot = New-RealtekRssV2RuntimeSnapshotFromObject -Object $obj -Source 'Get-NetAdapterRss.Get-NetAdapterMatch' -OSBuild $osBuild -AdapterName $adapterName -ProbeErrors ([string[]]$errors.ToArray())
                        Write-NICITRDiagnostic -Level Info -Message ('Realtek RSSv2 runtime probe matched by adapter text: device={0}; source={1}; adapter={2}; enabled={3}; queues={4}; ITEs={5}; status={6}' -f $deviceDebugName, [string]$snapshot.Source, [string]$snapshot.AdapterName, [string]$snapshot.Enabled, [string]$snapshot.NumberOfReceiveQueues, [string]$snapshot.NumberOfIndirectionTableEntries, [string]$snapshot.RssV2Status)
                        return $snapshot
                    }
                } catch {
                    [void]$errors.Add(('Get-NetAdapterRss matched adapter "{0}" failed: {1}' -f $adapterName, $_.Exception.Message))
                }
            }
        } catch {
            [void]$errors.Add(('Get-NetAdapter enumeration failed: {0}' -f $_.Exception.Message))
        }
    } else {
        [void]$errors.Add('Get-NetAdapterRss command is not available in this PowerShell session.')
    }
    try {
        $cim = @(Get-CimInstance -Namespace 'root/StandardCimv2' -ClassName 'MSFT_NetAdapterRss' -ErrorAction Stop)
        foreach ($obj in $cim) {
            $matched = Test-RealtekITRAdapterObjectMatchesDevice -Object $obj -Candidates $candidates -Identity $identity
            if (-not $matched -and $cim.Count -eq 1) { $matched = $true }
            if (-not $matched) { continue }
            $adapterName = [string](Get-RealtekITRPropertyValue -Object $obj -Name 'Name')
            $snapshot = New-RealtekRssV2RuntimeSnapshotFromObject -Object $obj -Source 'MSFT_NetAdapterRss.CIM' -OSBuild $osBuild -AdapterName $adapterName -ProbeErrors ([string[]]$errors.ToArray())
            Write-NICITRDiagnostic -Level Info -Message ('Realtek RSSv2 runtime probe matched by CIM: device={0}; source={1}; adapter={2}; enabled={3}; queues={4}; ITEs={5}; status={6}' -f $deviceDebugName, [string]$snapshot.Source, [string]$snapshot.AdapterName, [string]$snapshot.Enabled, [string]$snapshot.NumberOfReceiveQueues, [string]$snapshot.NumberOfIndirectionTableEntries, [string]$snapshot.RssV2Status)
            return $snapshot
        }
    } catch {
        [void]$errors.Add(('MSFT_NetAdapterRss CIM query failed: {0}' -f $_.Exception.Message))
    }
    foreach ($err in $errors) { Write-NICITRDiagnostic -Level Warning -Message ('Realtek RSSv2 runtime probe detail: device={0}; {1}' -f $deviceDebugName, $err) }
    return [PSCustomObject]@{
        Source = 'unavailable'
        AdapterName = $null
        OSBuild = [int]$osBuild
        OSRssV2Capable = [bool]($osBuild -ge 17134)
        RssV2RuntimeVisible = $false
        RssV2Status = if ($osBuild -ge 17134) { 'OS_build_RSSv2_eligible_adapter_runtime_unavailable' } else { 'OS_pre_RSSv2' }
        Enabled = $null
        NumberOfReceiveQueues = $null
        NumberOfIndirectionTableEntries = $null
        Profile = $null
        HashFunction = $null
        HashTypes = $null
        HashKeyLength = $null
        ProbeErrors = [string[]]$errors.ToArray()
        DirectOidCapability = 'user-mode-unavailable'
        CpuMaskSource = 'not-read-from-registry'
    }
}

function Resolve-RealtekITRPciBdfForDevice {
    param([AllowNull()][object]$Device)
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $Device
    $attempts = [System.Collections.Generic.List[string]]::new()
    $identity = Get-RealtekITRDevicePciIdentity -Device $Device

    foreach ($segmentName in @('Segment','PciSegment')) {
        foreach ($busName in @('Bus','BusNumber','PciBus')) {
            foreach ($deviceName in @('Device','DeviceNumber','PciDevice')) {
                foreach ($functionName in @('Function','FunctionNumber','PciFunction')) {
                    $segVal = Get-RealtekITRPropertyValue -Object $Device -Name $segmentName
                    $busVal = Get-RealtekITRPropertyValue -Object $Device -Name $busName
                    $devVal = Get-RealtekITRPropertyValue -Object $Device -Name $deviceName
                    $fnVal = Get-RealtekITRPropertyValue -Object $Device -Name $functionName
                    if ($null -eq $busVal -or $null -eq $devVal -or $null -eq $fnVal) { continue }
                    try {
                        $seg = if ($null -ne $segVal) { [int]([Convert]::ToInt64(([string]$segVal).Trim(), 0)) } else { 0 }
                        $bus = [int]([Convert]::ToInt64(([string]$busVal).Trim(), 0))
                        $dev = [int]([Convert]::ToInt64(([string]$devVal).Trim(), 0))
                        $fn = [int]([Convert]::ToInt64(([string]$fnVal).Trim(), 0))
                        $candidate = New-RealtekITRBdfObject -Segment $seg -Bus $bus -Device $dev -Function $fn -Source ('device properties {0}/{1}/{2}/{3}' -f $segmentName,$busName,$deviceName,$functionName)
                        if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
                        if ($null -ne $candidate) { [void]$attempts.Add(('explicit property candidate rejected: {0}' -f [string]$candidate.Bdf)) }
                    } catch { [void]$attempts.Add(('explicit property probe failed: {0}' -f $_.Exception.Message)) }
                }
            }
        }
    }

    foreach ($name in @('LocationInformation','LocationInfo','DEVPKEY_Device_LocationInfo')) {
        $value = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -eq $value -or [string]::IsNullOrWhiteSpace([string]$value)) { continue }
        $candidate = ConvertFrom-RealtekITRLocationInfoToBdf -LocationInfo ([string]$value) -Source $name
        if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
        if ($null -ne $candidate) { [void]$attempts.Add(('location property candidate rejected: {0}' -f [string]$candidate.Bdf)) }
    }

    foreach ($name in @('RegistryPath','PSPath','DeviceKey')) {
        $registryPath = Get-RealtekITRPropertyValue -Object $Device -Name $name
        if ($null -eq $registryPath -or [string]::IsNullOrWhiteSpace([string]$registryPath)) { continue }
        try {
            $p = [string]$registryPath
            $p = $p -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
            if ($p.StartsWith('HKEY_LOCAL_MACHINE\', [System.StringComparison]::OrdinalIgnoreCase)) { $p = 'HKLM:\' + $p.Substring('HKEY_LOCAL_MACHINE\'.Length) }
            elseif (-not $p.StartsWith('HKLM:\', [System.StringComparison]::OrdinalIgnoreCase)) {
                $trimmed = $p.Trim('\')
                if (-not $trimmed.StartsWith('SYSTEM\CurrentControlSet\Enum\', [System.StringComparison]::OrdinalIgnoreCase) -and $trimmed.StartsWith('PCI\', [System.StringComparison]::OrdinalIgnoreCase)) { $trimmed = 'SYSTEM\CurrentControlSet\Enum\' + $trimmed }
                $p = 'HKLM:\' + $trimmed
            }
            $prop = Get-ItemProperty -LiteralPath $p -ErrorAction Stop
            foreach ($locName in @('LocationInformation','LocationInfo')) {
                $locProp = $prop.PSObject.Properties[$locName]
                if ($null -eq $locProp -or $null -eq $locProp.Value -or [string]::IsNullOrWhiteSpace([string]$locProp.Value)) { continue }
                $candidate = ConvertFrom-RealtekITRLocationInfoToBdf -LocationInfo ([string]$locProp.Value) -Source ('registry {0}' -f $locName)
                if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
                if ($null -ne $candidate) { [void]$attempts.Add(('registry location candidate rejected: {0}' -f [string]$candidate.Bdf)) }
            }
        } catch { [void]$attempts.Add(('registry location probe failed for {0}: {1}' -f [string]$registryPath, $_.Exception.Message)) }
    }

    $instanceCandidates = [string[]](Get-RealtekITRDeviceInstanceIdCandidates -Device $Device)
    foreach ($instance in @($instanceCandidates)) {
        if ([string]::IsNullOrWhiteSpace($instance)) { continue }
        try {
            $prop = Get-PnpDeviceProperty -InstanceId $instance -KeyName 'DEVPKEY_Device_LocationInfo' -ErrorAction Stop
            if ($null -ne $prop -and $null -ne $prop.Data -and -not [string]::IsNullOrWhiteSpace([string]$prop.Data)) {
                $candidate = ConvertFrom-RealtekITRLocationInfoToBdf -LocationInfo ([string]$prop.Data) -Source ('Get-PnpDeviceProperty LocationInfo {0}' -f $instance)
                if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
                if ($null -ne $candidate) { [void]$attempts.Add(('PnP location candidate rejected: {0}' -f [string]$candidate.Bdf)) }
            }
        } catch { [void]$attempts.Add(('PnP LocationInfo probe failed for {0}: {1}' -f $instance, $_.Exception.Message)) }

        try {
            $busProp = Get-PnpDeviceProperty -InstanceId $instance -KeyName 'DEVPKEY_Device_BusNumber' -ErrorAction Stop
            $addrProp = Get-PnpDeviceProperty -InstanceId $instance -KeyName 'DEVPKEY_Device_Address' -ErrorAction Stop
            if ($null -ne $busProp -and $null -ne $busProp.Data -and $null -ne $addrProp -and $null -ne $addrProp.Data) {
                $bus = [int]$busProp.Data
                $addrCandidates = @()
                if ($null -ne (Get-Command ConvertFrom-RealtekITRPciAddressProperty -ErrorAction SilentlyContinue)) {
                    $addrCandidates = @(ConvertFrom-RealtekITRPciAddressProperty -Address $addrProp.Data)
                } else {
                    $a = [int64]$addrProp.Data
                    $tmpSeen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($p in @(
                        @{ Device = [int](($a -shr 16) -band 0xFFFF); Function = [int]($a -band 0xFFFF); Mode = 'SPDRP_ADDRESS hiword=device lowword=function inline' },
                        @{ Device = [int](($a -shr 8) -band 0x1F); Function = [int]($a -band 0x7); Mode = 'byte-packed device/function inline fallback' },
                        @{ Device = [int](($a -shr 3) -band 0x1F); Function = [int]($a -band 0x7); Mode = 'PCI devfn inline fallback' }
                    )) {
                        $dev = [int]$p.Device; $fn = [int]$p.Function
                        if ($dev -lt 0 -or $dev -gt 31 -or $fn -lt 0 -or $fn -gt 7) { continue }
                        $key = ('{0}.{1}' -f $dev,$fn)
                        if ($tmpSeen.Add($key)) { $addrCandidates += [PSCustomObject]@{ Device = $dev; Function = $fn; Mode = [string]$p.Mode; RawAddress = [int64]$a } }
                    }
                }
                foreach ($addrCandidate in @($addrCandidates)) {
                    $candidate = New-RealtekITRBdfObject -Segment 0 -Bus $bus -Device ([int]$addrCandidate.Device) -Function ([int]$addrCandidate.Function) -Source ('Get-PnpDeviceProperty BusNumber/Address {0}; address=0x{1:X}; decode={2}' -f $instance, [int64]$addrCandidate.RawAddress, [string]$addrCandidate.Mode)
                    if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
                    if ($null -ne $candidate) { [void]$attempts.Add(('PnP BusNumber/Address candidate rejected: {0}' -f [string]$candidate.Bdf)) }
                }
            }
        } catch { [void]$attempts.Add(('PnP BusNumber/Address probe failed for {0}: {1}' -f $instance, $_.Exception.Message)) }

        try {
            $entities = @()
            foreach ($filterProp in @('PNPDeviceID','DeviceID')) {
                $literal = ConvertTo-RealtekITRWqlStringLiteral -Value $instance
                $entities += @(Get-CimInstance -ClassName Win32_PnPEntity -Filter ("{0}={1}" -f $filterProp, $literal) -ErrorAction SilentlyContinue)
            }
            foreach ($entity in $entities) {
                foreach ($locName in @('LocationInformation','LocationInfo','DEVPKEY_Device_LocationInfo')) {
                    $loc = Get-RealtekITRPropertyValue -Object $entity -Name $locName
                    if ($null -eq $loc -or [string]::IsNullOrWhiteSpace([string]$loc)) { continue }
                    $candidate = ConvertFrom-RealtekITRLocationInfoToBdf -LocationInfo ([string]$loc) -Source ('Win32_PnPEntity {0} {1}' -f $locName, $instance)
                    if ($null -ne $candidate -and (Test-RealtekITRBdfMatchesDeviceIdentity -Bdf $candidate -Device $Device -Identity $identity)) { return $candidate }
                    if ($null -ne $candidate) { [void]$attempts.Add(('Win32_PnPEntity location candidate rejected: {0}' -f [string]$candidate.Bdf)) }
                }
            }
        } catch { [void]$attempts.Add(('Win32_PnPEntity location probe failed for {0}: {1}' -f $instance, $_.Exception.Message)) }
    }

    $attemptText = if ($attempts.Count -gt 0) { '; attempts=' + (($attempts.ToArray() | Select-Object -First 8) -join ' | ') } else { '' }
    throw ('Cannot resolve Realtek NIC BDF for MSI-X correlation: no usable LocationInfo or BusNumber/Address PnP data was available. device={0}; instanceCandidates={1}{2}' -f $deviceDebugName, ($instanceCandidates -join ','), $attemptText)
}

function Get-RealtekMsixVectorTopology {
    param([AllowNull()][object]$Device, [int]$QueueSlotLimit = 32, [int]$ExpectedRxQueues = 1, [int]$ExpectedTxQueues = 1)
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $Device
    $errors = [System.Collections.Generic.List[string]]::new()
    $required = @('Get-PciCapabilityList','Get-PciMsixTableInfo','Read-PciMsixTableRawDwords','Read-PciMsixPbaRawDwords')
    foreach ($cmd in $required) {
        if ($null -eq (Get-Command $cmd -ErrorAction SilentlyContinue)) {
            [void]$errors.Add(('required function {0} is not loaded yet' -f $cmd))
        }
    }
    if ($errors.Count -gt 0) {
        foreach ($err in $errors) { Write-NICITRDiagnostic -Level Warning -Message ('Realtek MSI-X vector topology probe unavailable: device={0}; {1}' -f $deviceDebugName, $err) }
        return [PSCustomObject]@{ Available = $false; Error = ($errors.ToArray() -join '; '); Entries = [object[]]@(); QueueVectorMap = @{}; CpuMaskPolicy = 'not-read'; Source = 'unavailable' }
    }
    try {
        $bdf = Resolve-RealtekITRPciBdfForDevice -Device $Device
        Write-NICITRDiagnostic -Level Info -Message ('Realtek MSI-X vector topology probe start: device={0}; BDF={1}; BDFSource={2}; expectedRx={3}; expectedTx={4}; queueSlotLimit={5}' -f $deviceDebugName, [string]$bdf.Bdf, [string]$bdf.Source, $ExpectedRxQueues, $ExpectedTxQueues, $QueueSlotLimit)
        $caps = @(Get-PciCapabilityList -Segment ([int]$bdf.Segment) -Bus ([int]$bdf.Bus) -Device ([int]$bdf.Device) -Function ([int]$bdf.Function))
        $msixCap = $null
        foreach ($cap in $caps) { if ([int]$cap.Id -eq 0x11) { $msixCap = $cap; break } }
        if ($null -eq $msixCap) { throw ('MSI-X capability 0x11 is absent on {0}; conventional capabilities scanned={1}' -f [string]$bdf.Bdf, ($caps.Count)) }
        $info = Get-PciMsixTableInfo -Segment ([int]$bdf.Segment) -Bus ([int]$bdf.Bus) -Device ([int]$bdf.Device) -Function ([int]$bdf.Function) -Capability $msixCap
        $requestedEntries = [Math]::Max(1, [Math]::Max([int]$QueueSlotLimit, [Math]::Max([int]$ExpectedRxQueues, [int]$ExpectedTxQueues)))
        $readEntries = [Math]::Min([int]$info.TableSize, [int]$requestedEntries)
        $table = [uint32[]](Read-PciMsixTableRawDwords -Segment ([int]$bdf.Segment) -Bus ([int]$bdf.Bus) -Device ([int]$bdf.Device) -Function ([int]$bdf.Function) -Capability $msixCap -StartDwordIndex 0 -MaxDwords ([int]($readEntries * 4)))
        $pba = [uint32[]](Read-PciMsixPbaRawDwords -Segment ([int]$bdf.Segment) -Bus ([int]$bdf.Bus) -Device ([int]$bdf.Device) -Function ([int]$bdf.Function) -Capability $msixCap -StartDwordIndex 0 -MaxDwords 0)
        $entries = [System.Collections.Generic.List[object]]::new()
        $map = @{}
        for ($i = 0; $i -lt $readEntries; $i++) {
            $base = $i * 4
            if (($base + 3) -ge $table.Count) { break }
            $addressLo = [uint32]$table[$base]
            $addressHi = [uint32]$table[$base + 1]
            $messageData = [uint32]$table[$base + 2]
            $vectorControl = [uint32]$table[$base + 3]
            $masked = (($vectorControl -band [uint32]1) -ne 0)
            $vectorNumber = [int]($messageData -band [uint32]0xFF)
            $pending = $false
            $pbaIndex = [int][Math]::Floor([double]($i / 32))
            $pbaBit = [int]($i % 32)
            if ($pbaIndex -ge 0 -and $pbaIndex -lt $pba.Count) { $pending = ((([uint32]$pba[$pbaIndex]) -band ([uint32]1 -shl $pbaBit)) -ne 0) }
            $entry = [PSCustomObject]@{
                TableIndex = [int]$i
                MessageAddressLow = [uint32]$addressLo
                MessageAddressHigh = [uint32]$addressHi
                MessageData = [uint32]$messageData
                VectorControl = [uint32]$vectorControl
                VectorNumber = [int]$vectorNumber
                Masked = [bool]$masked
                Pending = [bool]$pending
                CpuMask = $null
                CpuMaskSource = $null
                QueueCorrelation = 'table-index-correlated-with-queue-index-and-queue-status-bits'
            }
            [void]$entries.Add($entry)
            $map[$i] = $entry
        }
        Write-NICITRDiagnostic -Level Info -Message ('Realtek MSI-X vector topology decoded: device={0}; BDF={1}; cap=0x{2:X2}; tableEntries={3}; readEntries={4}; table=0x{5:X}; pba=0x{6:X}' -f $deviceDebugName, [string]$bdf.Bdf, [int]$info.CapabilityOffset, [int]$info.TableSize, [int]$readEntries, [uint64]$info.TableAddress, [uint64]$info.PbaAddress)
        return [PSCustomObject]@{ Available = $true; Error = $null; Bdf = [string]$bdf.Bdf; BdfSource = [string]$bdf.Source; CapabilityOffset = [int]$info.CapabilityOffset; TableSize = [int]$info.TableSize; ReadEntries = [int]$readEntries; TableAddress = [uint64]$info.TableAddress; PbaAddress = [uint64]$info.PbaAddress; Entries = [object[]]$entries.ToArray(); QueueVectorMap = $map; CpuMaskPolicy = 'not-read'; Source = 'PCI MSI-X table/PBA via RWE MMIO + ECAM capability walk' }
    } catch {
        Write-NICITRDiagnostic -Level Warning -Message ('Realtek MSI-X vector topology probe failed: device={0}' -f $deviceDebugName) -Exception $_
        return [PSCustomObject]@{ Available = $false; Error = $_.Exception.Message; Entries = [object[]]@(); QueueVectorMap = @{}; CpuMaskPolicy = 'not-read'; Source = 'probe-failed' }
    }
}

function New-RealtekIntMitiV2MappedLabels {
    param([int]$Count, [int]$LikelyRxQueues = 1, [int]$LikelyTxQueues = 1, [AllowNull()][object[]]$QueueRecords, [AllowNull()][object]$Layout, [bool]$RssEffectiveDisabled = $false, [AllowNull()][string]$RssDisableReasonText)
    if ($Count -le 0) { return @() }
    $recordByQueue = @{}
    if ($null -ne $QueueRecords) {
        foreach ($record in @($QueueRecords)) {
            if ($null -eq $record) { continue }
            try { $recordByQueue[[int]$record.Queue] = $record } catch { }
        }
    }
    $rxCount = [Math]::Max(1, [int]$LikelyRxQueues)
    $txCount = [Math]::Max(1, [int]$LikelyTxQueues)
    $labels = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $Count; $i++) {
        $offset = 0x0A00 + ($i * 4)
        if (($i % 2) -eq 0) {
            $q = [int]($i / 2)
            if ($recordByQueue.ContainsKey($q)) {
                $r = $recordByQueue[$q]
                $rxState = if ([bool]$r.RxActive) { 'active' } elseif ([bool]$r.RxCandidate) { 'candidate' } else { 'inactive' }
                $txState = if ([bool]$r.TxActive) { 'active' } elseif ([bool]$r.TxCandidate) { 'candidate' } else { 'inactive' }
                $rxProof = [string]$r.RxEvidenceText
                $txProof = [string]$r.TxEvidenceText
                $vectorText = 'pending'
                try {
                    if ($null -ne $r.PSObject.Properties['MsixVectorNumber'] -and $null -ne $r.MsixVectorNumber) {
                        $vectorText = ('{0} entry {1}' -f [int]$r.MsixVectorNumber, [string]$r.MsixVectorIndex)
                    }
                } catch { $vectorText = 'pending' }

                $cpuMaskSegment = ''
                try {
                    $maskSource = if ($null -ne $r.PSObject.Properties['MsixCpuMaskSource']) { [string]$r.MsixCpuMaskSource } else { '' }
                    $maskValue = if ($null -ne $r.PSObject.Properties['MsixCpuMask']) { [string]$r.MsixCpuMask } else { '' }
                    if (-not [string]::IsNullOrWhiteSpace($maskValue) -and $maskSource.IndexOf('registry', [System.StringComparison]::OrdinalIgnoreCase) -lt 0) {
                        $cpuMaskSegment = (' -> CPU mask {0}' -f $maskValue)
                    }
                } catch { $cpuMaskSegment = '' }

                $slot = Get-RealtekQueueModerationSlot -Layout $Layout -Queue $q -FallbackBankCount $Count
                $mappingText = if ([bool]$slot.QueueVerified) { ('verified {0}' -f [string]$slot.Verification) } else { ('UNVERIFIED {0}; evidence-only, not auto-labeled as queue ownership' -f [string]$slot.Verification) }
                $rssPrefix = if ($RssEffectiveDisabled -and $q -eq 0) { ('RSS disabled/RXQ0 effective ({0}); ' -f [string]$RssDisableReasonText) } elseif ($RssEffectiveDisabled) { ('RSS disabled/non-primary RX inactive ({0}); ' -f [string]$RssDisableReasonText) } else { '' }
                $queueName = if ([bool]$slot.QueueVerified) { ('RXQ{0} {1}/TXQ{0} {2}' -f $q, $rxState, $txState) } else { ('Q{0} raw candidate RX={1}/TX={2}' -f $q, $rxState, $txState) }
                [void]$labels.Add(('{0}{1} -> vector {2}{3} -> IntMITI{4}@0x{5:X4} low=RX high=TX [{6}; {7}; {8}]' -f $rssPrefix, $queueName, $vectorText, $cpuMaskSegment, $i, $offset, $mappingText, $rxProof, $txProof))
            } else {
                $slot = Get-RealtekQueueModerationSlot -Layout $Layout -Queue $q -FallbackBankCount $Count
                $mappingText = if ([bool]$slot.QueueVerified) { ('verified {0}' -f [string]$slot.Verification) } else { ('UNVERIFIED {0}; evidence-only, not auto-labeled as queue ownership' -f [string]$slot.Verification) }
                $rxText = if ($RssEffectiveDisabled -and $q -eq 0) { 'RXQ0 effective because RSS disabled' } elseif ($RssEffectiveDisabled) { 'RX non-primary inactive because RSS disabled' } elseif ($q -lt $rxCount -and [bool]$slot.QueueVerified) { 'RXQ{0} active' -f $q } elseif ($q -lt $rxCount) { 'RX raw candidate Q{0}' -f $q } else { 'RX inactive' }
                $txText = if ($q -lt $txCount -and [bool]$slot.QueueVerified) { 'TXQ{0} active' -f $q } elseif ($q -lt $txCount) { 'TX raw candidate Q{0}' -f $q } else { 'TX inactive' }
                [void]$labels.Add(('{0}/{1} -> vector pending -> IntMITI{2}@0x{3:X4} low=RX high=TX [{4}]' -f $rxText, $txText, $i, $offset, $mappingText))
            }
        } else {
            [void]$labels.Add(('No queue claim -> IntMITI{0}@0x{1:X4} adjacent low16/RX-only candidate' -f $i, $offset))
        }
    }
    return @($labels.ToArray())
}

function Get-RealtekIntMitiV2Topology {
    param([PSCustomObject]$device, [hashtable]$deviceMap, [hashtable]$nicInfo)
    if ($null -eq $nicInfo -or $nicInfo.Family -ne 'RealtekIntrMitV2') { return $null }
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $device
    $bar = Get-NICDeviceAddress $device $deviceMap
    if ($bar -eq 0) {
        $mapKeys = if ($null -ne $deviceMap) { @($deviceMap.Keys).Count } else { 0 }
        Write-NICITRDiagnostic -Level Error -Message ('Realtek IntMITI V2 topology cannot start: PCI BAR address unresolved. device={0}; deviceMapKeys={1}' -f $deviceDebugName, $mapKeys)
        throw ('Cannot map Realtek IntMITI V2 topology because the PCI BAR address was not resolved. device={0}; deviceMapKeys={1}' -f $deviceDebugName, $mapKeys)
    }
    $queueSlotLimit = Get-RealtekIntMitiV2QueueSlotLimit -nicInfo $nicInfo
    $moderationLayout = Resolve-RealtekQueueModerationLayout -nicInfo $nicInfo
    $moderationLayoutText = Get-RealtekQueueModerationLayoutText -Layout $moderationLayout
    $rssV2Snapshot = Get-RealtekRssV2RuntimeSnapshot -Device $device -QueueSlotLimit $queueSlotLimit
    $rssV2QueueCount = $null
    $rssV2IteCount = $null
    $rssV2BoundedRxQueues = $null
    $rssV2PrimaryState = 'unavailable'
    try { if ($null -ne $rssV2Snapshot -and $null -ne $rssV2Snapshot.NumberOfReceiveQueues) { $rssV2QueueCount = [int]$rssV2Snapshot.NumberOfReceiveQueues } } catch { $rssV2QueueCount = $null }
    try { if ($null -ne $rssV2Snapshot -and $null -ne $rssV2Snapshot.NumberOfIndirectionTableEntries) { $rssV2IteCount = [int]$rssV2Snapshot.NumberOfIndirectionTableEntries } } catch { $rssV2IteCount = $null }
    if ($null -ne $rssV2Snapshot -and $rssV2Snapshot.RssV2RuntimeVisible) {
        if ($null -ne $rssV2Snapshot.Enabled -and -not [bool]$rssV2Snapshot.Enabled) {
            $rssV2BoundedRxQueues = 1
            $rssV2PrimaryState = 'RSSv2-runtime-disabled-primary-single-rxq'
        } elseif ($null -ne $rssV2QueueCount -and [int]$rssV2QueueCount -gt 0) {
            $rssV2BoundedRxQueues = [Math]::Max(1, [Math]::Min([int]$queueSlotLimit, [int]$rssV2QueueCount))
            $rssV2PrimaryState = 'RSSv2-runtime-primary'
        } else {
            $rssV2PrimaryState = 'RSSv2-runtime-visible-without-queue-count'
        }
    }
    Write-NICITRDiagnostic -Level Info -Message ('Realtek IntMITI V2 topology start: device={0}; BAR=0x{1:X}; queueSlotLimit={2}; maxDwords={3}; {4}; rssv2Source={5}; rssv2Status={6}; rssv2Enabled={7}; rssv2Queues={8}; rssv2ITEs={9}; primary={10}' -f $deviceDebugName, [uint64]$bar, [int]$queueSlotLimit, [int]$nicInfo.MaxQueues, $moderationLayoutText, [string]$rssV2Snapshot.Source, [string]$rssV2Snapshot.RssV2Status, [string]$rssV2Snapshot.Enabled, [string]$rssV2QueueCount, [string]$rssV2IteCount, [string]$rssV2PrimaryState)
    $rssCtrlAddr = [uint64]($bar + 0x4500)
    $qNumCtrlAddr = [uint64]($bar + 0x4800)
    $rssTableBase = [uint64]($bar + 0x4700)
    $rxDescQ0LowAddr = [uint64]($bar + 0x00E4)
    $rxDescQ0HighAddr = [uint64]($bar + 0x00E8)
    $txDescQ0LowAddr = [uint64]($bar + 0x0020)
    $txDescQ0HighAddr = [uint64]($bar + 0x0024)
    $txHDescLowAddr = [uint64]($bar + 0x0028)
    $txHDescHighAddr = [uint64]($bar + 0x002C)
    $rdsarQ1LowBase = [uint64]($bar + 0x4000)
    $tnpdsQ1LowBase = [uint64]($bar + 0x2100)
    $txIdleCredit0Addr = [uint64]($bar + 0x2500)
    $txIdleCredit1Addr = [uint64]($bar + 0x2504)
    $txPointerBase = [uint64]($bar + 0x2800)
    $txPointerBpTailBase = [uint64]($bar + 0x0D30)
    $txPointerBpCloseBase = [uint64]($bar + 0x0D34)
    $imrV2ClearAddr = [uint64]($bar + 0x0D00)
    $imrV2SetAddr = [uint64]($bar + 0x0D0C)
    $isrV2Addr = [uint64]($bar + 0x0D04)
    $rduStaAddr = [uint64]($bar + 0x0D0A)
    $tduStaAddr = [uint64]($bar + 0x0D08)
    $dwordAddresses = [System.Collections.Generic.List[uint64]]::new()
    foreach ($addr in @($rssCtrlAddr,$rxDescQ0LowAddr,$rxDescQ0HighAddr,$txDescQ0LowAddr,$txDescQ0HighAddr,$txHDescLowAddr,$txHDescHighAddr,$txIdleCredit0Addr,$txIdleCredit1Addr,$imrV2ClearAddr,$imrV2SetAddr,$isrV2Addr)) { [void]$dwordAddresses.Add([uint64]$addr) }
    $rxPairs = [System.Collections.Generic.List[object]]::new()
    [void]$rxPairs.Add((New-RealtekTopologyRegisterPair -Name 'RxDescAddr' -Queue 0 -LowOffset 0x00E4 -HighOffset 0x00E8))
    $txPairs = [System.Collections.Generic.List[object]]::new()
    [void]$txPairs.Add((New-RealtekTopologyRegisterPair -Name 'TxDescStartAddr' -Queue 0 -LowOffset 0x0020 -HighOffset 0x0024))
    [void]$txPairs.Add((New-RealtekTopologyRegisterPair -Name 'TxHDescStartAddr' -Queue -1 -LowOffset 0x0028 -HighOffset 0x002C))
    for ($q = 1; $q -lt $queueSlotLimit; $q++) {
        $rxLow = [uint64](0x4000 + (($q - 1) * 8))
        $txLow = [uint64](0x2100 + (($q - 1) * 8))
        [void]$rxPairs.Add((New-RealtekTopologyRegisterPair -Name ('RDSAR_Q{0}' -f $q) -Queue $q -LowOffset $rxLow -HighOffset ([uint64]($rxLow + 4))))
        [void]$txPairs.Add((New-RealtekTopologyRegisterPair -Name ('TNPDS_Q{0}' -f $q) -Queue $q -LowOffset $txLow -HighOffset ([uint64]($txLow + 4))))
    }
    foreach ($pair in @($rxPairs)) {
        [void]$dwordAddresses.Add([uint64]($bar + [uint64]$pair.LowOffset))
        [void]$dwordAddresses.Add([uint64]($bar + [uint64]$pair.HighOffset))
    }
    foreach ($pair in @($txPairs)) {
        [void]$dwordAddresses.Add([uint64]($bar + [uint64]$pair.LowOffset))
        [void]$dwordAddresses.Add([uint64]($bar + [uint64]$pair.HighOffset))
    }
    for ($i = 0; $i -lt 32; $i++) { [void]$dwordAddresses.Add([uint64]($rssTableBase + ($i * 4))) }
    for ($q = 0; $q -lt $queueSlotLimit; $q++) { [void]$dwordAddresses.Add([uint64]($txPointerBase + ($q * 4))) }
    for ($q = 0; $q -lt [Math]::Min(2, $queueSlotLimit); $q++) {
        [void]$dwordAddresses.Add([uint64]($txPointerBpTailBase + ($q * 8)))
        [void]$dwordAddresses.Add([uint64]($txPointerBpCloseBase + ($q * 8)))
    }
    $wordAddresses = [System.Collections.Generic.List[uint64]]::new()
    foreach ($addr in @($qNumCtrlAddr,$rduStaAddr,$tduStaAddr)) { [void]$wordAddresses.Add([uint64]$addr) }
    for ($q = 0; $q -lt $queueSlotLimit; $q++) {
        [void]$wordAddresses.Add([uint64]($txPointerBase + ($q * 4)))
        [void]$wordAddresses.Add([uint64]($txPointerBase + ($q * 4) + 2))
    }
    $timeout = [Math]::Max(30000, [int]$script:RWECommandTimeoutMs)
    Write-NICITRDiagnostic -Level Info -Message ('Realtek IntMITI V2 topology read batch: device={0}; R32count={1}; R16count={2}; timeoutMs={3}; RSS_CTRL=0x{4:X}; Q_NUM=0x{5:X}; RETA=0x{6:X}' -f $deviceDebugName, $dwordAddresses.Count, $wordAddresses.Count, $timeout, [uint64]$rssCtrlAddr, [uint64]$qNumCtrlAddr, [uint64]$rssTableBase)
    $dwordBatch = Invoke-RWEReadBatch -Addresses ([uint64[]]$dwordAddresses.ToArray()) -Width 32 -TimeoutMs $timeout
    $wordBatch = Invoke-RWEReadBatch -Addresses ([uint64[]]$wordAddresses.ToArray()) -Width 16 -TimeoutMs $timeout
    $rssCtrl = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $rssCtrlAddr -Name 'RSS_CTRL_8125' -Mask 0xFFFFFFFF
    $qNumCtrl = Get-DeviceTweakerBatchValue -Batch $wordBatch -Address $qNumCtrlAddr -Name 'Q_NUM_CTRL_8125' -Mask 0xFFFF
    $imrV2Clear = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $imrV2ClearAddr -Name 'IMR_V2_CLEAR_REG_8125' -Mask 0xFFFFFFFF
    $imrV2Set = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $imrV2SetAddr -Name 'IMR_V2_SET_REG_8125' -Mask 0xFFFFFFFF
    $isrV2 = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $isrV2Addr -Name 'ISR_V2_8125' -Mask 0xFFFFFFFF
    $rduSta = Get-DeviceTweakerBatchValue -Batch $wordBatch -Address $rduStaAddr -Name 'RDU_STA_8125' -Mask 0xFFFF
    $tduSta = Get-DeviceTweakerBatchValue -Batch $wordBatch -Address $tduStaAddr -Name 'TDU_STA_8125' -Mask 0xFFFF
    $rssBytes = [System.Collections.Generic.List[int]]::new()
    $rssDwords = [System.Collections.Generic.List[uint64]]::new()
    for ($i = 0; $i -lt 32; $i++) {
        $addr = [uint64]($rssTableBase + ($i * 4))
        $dw = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $addr -Name ('RSS_INDIRECTION_TBL_8125_V2[{0}]' -f $i) -Mask 0xFFFFFFFF
        [void]$rssDwords.Add([uint64]$dw)
        for ($b = 0; $b -lt 4; $b++) { [void]$rssBytes.Add([int](($dw -shr (8 * $b)) -band 0xFF)) }
    }
    $queueHitCounts = @{}
    foreach ($entry in $rssBytes) {
        $qid = [int]($entry -band 0xFF)
        if (-not $queueHitCounts.ContainsKey($qid)) { $queueHitCounts[$qid] = 0 }
        $queueHitCounts[$qid] = [int]$queueHitCounts[$qid] + 1
    }
    $indirQueues = @($queueHitCounts.Keys | ForEach-Object { [int]$_ } | Sort-Object)
    $qNumRxCode = [int](($qNumCtrl -shr 2) -band 0x7)
    $qNumRxQueues = ConvertFrom-RealtekQueueLog2Code -Code $qNumRxCode -Max 128
    $rssCtrlRxCode = [int](($rssCtrl -shr 16) -band 0x7)
    $rssCtrlRxQueues = ConvertFrom-RealtekQueueLog2Code -Code $rssCtrlRxCode -Max 128
    $rssCtrlMaskCode = [int](($rssCtrl -shr 8) -band 0x7)
    $rssCtrlTableEntries = ConvertFrom-RealtekQueueLog2Code -Code $rssCtrlMaskCode -Max 128
    $rssCtrlHashMask = [uint64]($rssCtrl -band 0xFF)
    $rssCtrlHashEnabled = ($rssCtrlHashMask -ne 0)
    $rssCtrlEnabled = ($rssCtrl -ne 0 -and $rssCtrlHashEnabled)
    $osRssDisabled = ($null -ne $rssV2Snapshot -and [bool]$rssV2Snapshot.RssV2RuntimeVisible -and $null -ne $rssV2Snapshot.Enabled -and -not [bool]$rssV2Snapshot.Enabled)
    $rssCtrlDisabled = (-not $rssCtrlHashEnabled)
    $rssEffectiveDisabled = ($osRssDisabled -or $rssCtrlDisabled)
    $rssDisableReasons = [System.Collections.Generic.List[string]]::new()
    if ($osRssDisabled) { [void]$rssDisableReasons.Add('OS-RSS-disabled') }
    if ($rssCtrlDisabled) { [void]$rssDisableReasons.Add(('RSS_CTRL-hash-mask-zero:0x{0:X8}' -f [uint64]$rssCtrl)) }
    $rssDisableReasonText = if ($rssDisableReasons.Count -gt 0) { ($rssDisableReasons.ToArray() -join '+') } else { 'RSS enabled or unavailable' }
    $txOcp = Read-RealtekMacOcp16 -Bar $bar -OcpAddress ([uint16]0xE63E)
    $txOcpCode = $null
    $txOcpQueues = $null
    if ($null -ne $txOcp -and $null -eq $txOcp.Error -and $null -ne $txOcp.Value) {
        $txOcpCode = [int](([uint16]$txOcp.Value -shr 10) -band 0x3)
        $txOcpQueues = ConvertFrom-RealtekQueueLog2Code -Code $txOcpCode -Max 8
    }
    $rxDescRecords = @{}
    foreach ($pair in @($rxPairs)) {
        if ([int]$pair.Queue -lt 0) { continue }
        $lowAddr = [uint64]($bar + [uint64]$pair.LowOffset)
        $highAddr = [uint64]($bar + [uint64]$pair.HighOffset)
        $low = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $lowAddr -Name ([string]$pair.Name + '_LOW') -Mask 0xFFFFFFFF
        $high = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $highAddr -Name ([string]$pair.Name + '_HIGH') -Mask 0xFFFFFFFF
        $baseValue = ConvertTo-RealtekU64Pair -Low $low -High $high
        $rxDescRecords[[int]$pair.Queue] = [PSCustomObject]@{ Queue = [int]$pair.Queue; Name = [string]$pair.Name; LowOffset = [uint64]$pair.LowOffset; HighOffset = [uint64]$pair.HighOffset; Low = [uint64]$low; High = [uint64]$high; Base = [uint64]$baseValue; NonZero = ($baseValue -ne 0) }
    }
    $txDescRecords = @{}
    $txHighPriorityDesc = $null
    foreach ($pair in @($txPairs)) {
        $lowAddr = [uint64]($bar + [uint64]$pair.LowOffset)
        $highAddr = [uint64]($bar + [uint64]$pair.HighOffset)
        $low = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $lowAddr -Name ([string]$pair.Name + '_LOW') -Mask 0xFFFFFFFF
        $high = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $highAddr -Name ([string]$pair.Name + '_HIGH') -Mask 0xFFFFFFFF
        $baseValue = ConvertTo-RealtekU64Pair -Low $low -High $high
        $record = [PSCustomObject]@{ Queue = [int]$pair.Queue; Name = [string]$pair.Name; LowOffset = [uint64]$pair.LowOffset; HighOffset = [uint64]$pair.HighOffset; Low = [uint64]$low; High = [uint64]$high; Base = [uint64]$baseValue; NonZero = ($baseValue -ne 0) }
        if ([int]$pair.Queue -lt 0) { $txHighPriorityDesc = $record } else { $txDescRecords[[int]$pair.Queue] = $record }
    }
    $txPointerRecords = @{}
    for ($q = 0; $q -lt $queueSlotLimit; $q++) {
        $baseAddr = [uint64]($txPointerBase + ($q * 4))
        $tail16 = Get-DeviceTweakerBatchValue -Batch $wordBatch -Address $baseAddr -Name ('SW_TAIL_PTR_Q{0}_8125_16' -f $q) -Mask 0xFFFF
        $close16 = Get-DeviceTweakerBatchValue -Batch $wordBatch -Address ([uint64]($baseAddr + 2)) -Name ('HW_CLO_PTR_Q{0}_8125_16' -f $q) -Mask 0xFFFF
        $packed32 = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $baseAddr -Name ('SW_TAIL_HW_CLO_PTR_Q{0}_8126_32' -f $q) -Mask 0xFFFFFFFF
        $tailFromPacked = [uint16]($packed32 -band 0xFFFF)
        $closeFromPacked = [uint16](($packed32 -shr 16) -band 0xFFFF)
        $bpTail = $null
        $bpClose = $null
        if ($q -lt 2) {
            $bpTail = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address ([uint64]($txPointerBpTailBase + ($q * 8))) -Name ('SW_TAIL_PTR_Q{0}_8125BP_32' -f $q) -Mask 0xFFFFFFFF
            $bpClose = Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address ([uint64]($txPointerBpCloseBase + ($q * 8))) -Name ('HW_CLO_PTR_Q{0}_8125BP_32' -f $q) -Mask 0xFFFFFFFF
        }
        $txPointerRecords[$q] = [PSCustomObject]@{ Queue = [int]$q; Offset = [uint64](0x2800 + ($q * 4)); Tail8125 = [uint16]$tail16; Consumer8125 = [uint16]$close16; Packed8126Or8127 = [uint32]$packed32; Tail8126Or8127 = [uint16]$tailFromPacked; Consumer8126Or8127 = [uint16]$closeFromPacked; BpTail8125 = $bpTail; BpConsumer8125 = $bpClose; NonZero = (($tail16 -ne 0) -or ($close16 -ne 0) -or ($packed32 -ne 0) -or ($null -ne $bpTail -and $bpTail -ne 0) -or ($null -ne $bpClose -and $bpClose -ne 0)) }
    }
    $txIdleCredits = [PSCustomObject]@{
        Q0 = [uint64](Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $txIdleCredit0Addr -Name 'PLA_TXQ0_IDLE_CREDIT' -Mask 0xFFFFFFFF)
        Q1 = [uint64](Get-DeviceTweakerBatchValue -Batch $dwordBatch -Address $txIdleCredit1Addr -Name 'PLA_TXQ1_IDLE_CREDIT' -Mask 0xFFFFFFFF)
    }
    $queueRecords = [System.Collections.Generic.List[object]]::new()
    $activeRxQueues = [System.Collections.Generic.List[int]]::new()
    $activeTxQueues = [System.Collections.Generic.List[int]]::new()
    for ($q = 0; $q -lt $queueSlotLimit; $q++) {
        $rxDesc = if ($rxDescRecords.ContainsKey($q)) { $rxDescRecords[$q] } else { $null }
        $txDesc = if ($txDescRecords.ContainsKey($q)) { $txDescRecords[$q] } else { $null }
        $txPtr = if ($txPointerRecords.ContainsKey($q)) { $txPointerRecords[$q] } else { $null }
        $rssHits = if ($queueHitCounts.ContainsKey($q)) { [int]$queueHitCounts[$q] } else { 0 }
        $layoutSlot = Get-RealtekQueueModerationSlot -Layout $moderationLayout -Queue $q -FallbackBankCount ([int]$nicInfo.MaxQueues)
        $mappingVerified = [bool]$layoutSlot.QueueVerified
        $rxDescOk = ($q -eq 0 -or ($null -ne $rxDesc -and [bool]$rxDesc.NonZero))
        $txDescOk = ($q -eq 0 -or ($null -ne $txDesc -and [bool]$txDesc.NonZero))
        $rxQNumAgree = ((-not $rssEffectiveDisabled) -and $q -lt $qNumRxQueues)
        $rxRssCtrlAgree = ((-not $rssEffectiveDisabled) -and $rssCtrlEnabled -and $q -lt $rssCtrlRxQueues)
        $rxRssV2Agree = ((-not $rssEffectiveDisabled) -and $null -ne $rssV2BoundedRxQueues -and $q -lt [int]$rssV2BoundedRxQueues)
        $rxRssIndirAgree = ((-not $rssEffectiveDisabled) -and $rssHits -gt 0)
        $rxRduBit = ($q -lt 16 -and (($rduSta -band ([uint64]1 -shl $q)) -ne 0))
        $txTduBit = ($q -lt 16 -and (($tduSta -band ([uint64]1 -shl $q)) -ne 0))
        $txOcpAgree = ($null -ne $txOcpQueues -and $q -lt [int]$txOcpQueues)
        $txPointerObserved = ($null -ne $txPtr -and [bool]$txPtr.NonZero)
        $rxEvidenceActive = $false
        $rxEvidenceReason = 'none'
        if ($rssEffectiveDisabled) {
            if ($q -eq 0) { $rxEvidenceActive = $true; $rxEvidenceReason = 'rss-disabled-rxq0-effective' }
            elseif ($rxDescOk -or $rxRduBit) { $rxEvidenceReason = 'rss-disabled-descriptor-or-status-evidence-only' }
            else { $rxEvidenceReason = 'rss-disabled-nonprimary-rxq-inactive' }
        } elseif ($q -eq 0) {
            $rxEvidenceActive = $true
            $rxEvidenceReason = if ($rxRssV2Agree) { 'rssv2-primary-base-q0' } else { 'base-q0' }
        } elseif ($rxRssV2Agree) {
            $rxEvidenceActive = $true
            $rxEvidenceReason = if ($rxDescOk -or $rxRssIndirAgree -or $rxRduBit -or $rxQNumAgree -or $rxRssCtrlAgree) { 'rssv2-primary+mmio-cross-check' } else { 'rssv2-primary' }
        } elseif ($rxDescOk -and $rxRssIndirAgree -and $rxQNumAgree) {
            $rxEvidenceActive = $true
            $rxEvidenceReason = 'desc+rss-table+qnum'
        } elseif ($rxDescOk -and $rxRssCtrlAgree) {
            $rxEvidenceActive = $true
            $rxEvidenceReason = 'desc+rss-ctrl'
        }
        $txEvidenceActive = $false
        $txEvidenceReason = 'none'
        if ($q -eq 0) { $txEvidenceActive = $true; $txEvidenceReason = 'base-q0' }
        elseif ($txDescOk -and $txOcpAgree) { $txEvidenceActive = $true; $txEvidenceReason = 'desc+mac-ocp-txqnum' }
        $rxActive = ($rxEvidenceActive -and ($mappingVerified -or $q -eq 0))
        $txActive = ($txEvidenceActive -and ($mappingVerified -or $q -eq 0))
        $rxReason = if ($rxActive) { $rxEvidenceReason } elseif ($rxEvidenceActive) { ('unverified-layout-evidence-only:{0}' -f $rxEvidenceReason) } else { $rxEvidenceReason }
        $txReason = if ($txActive) { $txEvidenceReason } elseif ($txEvidenceActive) { ('unverified-layout-evidence-only:{0}' -f $txEvidenceReason) } else { $txEvidenceReason }
        $rxCandidate = ($rxActive -or $rxDescOk -or $rxRssIndirAgree -or $rxQNumAgree -or $rxRssCtrlAgree -or $rxRssV2Agree -or $rxRduBit)
        $txCandidate = ($txActive -or $txDescOk -or $txOcpAgree -or $txTduBit -or $txPointerObserved)
        if ($rxActive) { [void]$activeRxQueues.Add($q) }
        if ($txActive) { [void]$activeTxQueues.Add($q) }
        $rxEvidenceParts = [System.Collections.Generic.List[string]]::new()
        [void]$rxEvidenceParts.Add(('layout={0}/{1}/IntMITI{2}' -f [string]$layoutSlot.LayoutKey, [string]$layoutSlot.VerificationState, [int]$layoutSlot.IntMitiIndex))
        if ($rssEffectiveDisabled) { [void]$rxEvidenceParts.Add(('rssDisabled={0}' -f $rssDisableReasonText)) }
        if ($null -ne $rxDesc) { [void]$rxEvidenceParts.Add(('desc=0x{0:X16}' -f [uint64]$rxDesc.Base)) }
        [void]$rxEvidenceParts.Add(('rssHits={0}' -f $rssHits))
        [void]$rxEvidenceParts.Add(('rssv2={0}/q={1}/ite={2}/src={3}' -f [string]$rxRssV2Agree, [string]$rssV2QueueCount, [string]$rssV2IteCount, [string]$rssV2Snapshot.Source))
        [void]$rxEvidenceParts.Add(('qnumWeak={0}/{1}' -f $qNumRxCode, $qNumRxQueues))
        [void]$rxEvidenceParts.Add(('rssCtrl={0}/{1}/hash=0x{2:X2}' -f $rssCtrlRxCode, $rssCtrlRxQueues, [uint64]$rssCtrlHashMask))
        if ($rxRduBit) { [void]$rxEvidenceParts.Add('rdu') }
        [void]$rxEvidenceParts.Add(('rxActive={0}' -f $rxReason))
        $txEvidenceParts = [System.Collections.Generic.List[string]]::new()
        [void]$txEvidenceParts.Add(('layout={0}/{1}/IntMITI{2}' -f [string]$layoutSlot.LayoutKey, [string]$layoutSlot.VerificationState, [int]$layoutSlot.IntMitiIndex))
        if ($null -ne $txDesc) { [void]$txEvidenceParts.Add(('desc=0x{0:X16}' -f [uint64]$txDesc.Base)) }
        if ($null -ne $txOcpQueues) { [void]$txEvidenceParts.Add(('ocpE63E={0}/{1}' -f $txOcpCode, $txOcpQueues)) } else { [void]$txEvidenceParts.Add(('ocpE63E=error:{0}' -f [string]$txOcp.Error)) }
        if ($txTduBit) { [void]$txEvidenceParts.Add('tdu') }
        if ($txPointerObserved) { [void]$txEvidenceParts.Add(('ptr=0x{0:X8}/bp=0x{1:X8}:0x{2:X8}' -f [uint32]$txPtr.Packed8126Or8127, [uint32]($txPtr.BpTail8125 -as [uint32]), [uint32]($txPtr.BpConsumer8125 -as [uint32]))) }
        [void]$txEvidenceParts.Add(('txActive={0}' -f $txReason))
        [void]$queueRecords.Add([PSCustomObject]@{
            Queue = [int]$q
            IntMitiIndex = [int]$layoutSlot.IntMitiIndex
            IntMitiOffset = [uint64]$layoutSlot.IntMitiOffset
            QueueMappingVerified = [bool]$layoutSlot.QueueVerified
            QueueMappingState = [string]$layoutSlot.VerificationState
            QueueMappingVerification = [string]$layoutSlot.Verification
            QueueLayoutKey = [string]$layoutSlot.LayoutKey
            RxActive = [bool]$rxActive
            TxActive = [bool]$txActive
            RxCandidate = [bool]$rxCandidate
            TxCandidate = [bool]$txCandidate
            RxReason = [string]$rxReason
            TxReason = [string]$txReason
            RssHits = [int]$rssHits
            QNumRxAgree = [bool]$rxQNumAgree
            RssCtrlAgree = [bool]$rxRssCtrlAgree
            RssV2Agree = [bool]$rxRssV2Agree
            RssV2QueueCount = $rssV2QueueCount
            RssV2IteCount = $rssV2IteCount
            RxDescriptor = $rxDesc
            TxDescriptor = $txDesc
            TxPointer = $txPtr
            RxEvidenceText = ($rxEvidenceParts.ToArray() -join ',')
            TxEvidenceText = ($txEvidenceParts.ToArray() -join ',')
        })
    }
    $rxQueues = 1
    foreach ($q in $activeRxQueues) { if ($q + 1 -gt $rxQueues) { $rxQueues = [int]($q + 1) } }
    $txQueues = 1
    foreach ($q in $activeTxQueues) { if ($q + 1 -gt $txQueues) { $txQueues = [int]($q + 1) } }
    $msixTopology = Get-RealtekMsixVectorTopology -Device $device -QueueSlotLimit $queueSlotLimit -ExpectedRxQueues $rxQueues -ExpectedTxQueues $txQueues
    foreach ($record in @($queueRecords.ToArray())) {
        $vectorEntry = $null
        try {
            if ($null -ne $msixTopology -and [bool]$msixTopology.Available -and $null -ne $msixTopology.QueueVectorMap -and $msixTopology.QueueVectorMap.ContainsKey([int]$record.Queue)) { $vectorEntry = $msixTopology.QueueVectorMap[[int]$record.Queue] }
        } catch { $vectorEntry = $null }
        if ($null -ne $vectorEntry) {
            $vectorEvidence = ('msixEntry={0}/vector={1}/masked={2}/pending={3}/msg=0x{4:X8}' -f [int]$vectorEntry.TableIndex, [int]$vectorEntry.VectorNumber, [bool]$vectorEntry.Masked, [bool]$vectorEntry.Pending, [uint32]$vectorEntry.MessageData)
            Add-Member -InputObject $record -NotePropertyName MsixVectorIndex -NotePropertyValue ([int]$vectorEntry.TableIndex) -Force
            Add-Member -InputObject $record -NotePropertyName MsixVectorNumber -NotePropertyValue ([int]$vectorEntry.VectorNumber) -Force
            Add-Member -InputObject $record -NotePropertyName MsixMessageData -NotePropertyValue ([uint32]$vectorEntry.MessageData) -Force
            Add-Member -InputObject $record -NotePropertyName MsixMasked -NotePropertyValue ([bool]$vectorEntry.Masked) -Force
            Add-Member -InputObject $record -NotePropertyName MsixPending -NotePropertyValue ([bool]$vectorEntry.Pending) -Force
            Add-Member -InputObject $record -NotePropertyName MsixCpuMask -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixCpuMaskSource -NotePropertyValue ([string]$vectorEntry.CpuMaskSource) -Force
            Add-Member -InputObject $record -NotePropertyName MsixEvidenceText -NotePropertyValue $vectorEvidence -Force
            $record.RxEvidenceText = (([string]$record.RxEvidenceText) + ',' + $vectorEvidence)
        } else {
            if ($null -ne $msixTopology -and -not [string]::IsNullOrWhiteSpace([string]$msixTopology.Error)) {
                $vectorEvidence = ('msix=unavailable: {0}' -f [string]$msixTopology.Error)
            } else {
                $vectorEvidence = 'msix=unresolved: no probe error captured'
            }
            Add-Member -InputObject $record -NotePropertyName MsixVectorIndex -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixVectorNumber -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixMessageData -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixMasked -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixPending -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixCpuMask -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixCpuMaskSource -NotePropertyValue $null -Force
            Add-Member -InputObject $record -NotePropertyName MsixEvidenceText -NotePropertyValue $vectorEvidence -Force
            $record.RxEvidenceText = (([string]$record.RxEvidenceText) + ',' + $vectorEvidence)
        }
    }
    $labels = New-RealtekIntMitiV2MappedLabels -Count ([int]$nicInfo.MaxQueues) -LikelyRxQueues $rxQueues -LikelyTxQueues $txQueues -QueueRecords ([object[]]$queueRecords.ToArray()) -Layout $moderationLayout -RssEffectiveDisabled ([bool]$rssEffectiveDisabled) -RssDisableReasonText $rssDisableReasonText
    $activeBanks = [System.Collections.Generic.List[string]]::new()
    $maxActiveQueue = [Math]::Max($rxQueues, $txQueues)
    for ($q = 0; $q -lt $maxActiveQueue; $q++) {
        $slot = Get-RealtekQueueModerationSlot -Layout $moderationLayout -Queue $q -FallbackBankCount ([int]$nicInfo.MaxQueues)
        $bankText = if ([bool]$slot.QueueVerified) { ('Q{0}->IntMITI{1}' -f $q, [int]$slot.IntMitiIndex) } else { ('Q{0}?unverified->IntMITI{1}' -f $q, [int]$slot.IntMitiIndex) }
        [void]$activeBanks.Add($bankText)
    }
    $hitParts = [System.Collections.Generic.List[string]]::new()
    foreach ($qid in $indirQueues) { [void]$hitParts.Add(('{0}:{1}' -f $qid, [int]$queueHitCounts[$qid])) }
    $hitText = if ($hitParts.Count -gt 0) { ($hitParts.ToArray() -join ',') } else { 'none' }
    $txOcpText = if ($null -ne $txOcp -and $null -eq $txOcp.Error -and $null -ne $txOcp.Value) { ('0x{0:X4}->{1}' -f ([uint16]$txOcp.Value), $txOcpQueues) } else { ('error:{0}' -f [string]$txOcp.Error) }
    $rssPrimaryText = if ($rssEffectiveDisabled) { ('RSS disabled / RXQ0 effective ({0})' -f $rssDisableReasonText) } elseif ($null -ne $rssV2BoundedRxQueues) { ('RSSv2({0})' -f $rssV2PrimaryState) } else { 'MMIO(RETA/QNUM/RSS_CTRL)' }
    $rssV2ProbeErrorCount = 0
    try { if ($null -ne $rssV2Snapshot -and $null -ne $rssV2Snapshot.ProbeErrors) { $rssV2ProbeErrorCount = [int]@($rssV2Snapshot.ProbeErrors).Count } } catch { $rssV2ProbeErrorCount = 0 }
    $rssV2ProbeErrorBrief = try { Format-RealtekITRProbeErrorsBrief -ProbeErrors $rssV2Snapshot.ProbeErrors } catch { 'unavailable' }
    $rssV2Text = ('RSSv2 src={0} status={1} en={2} q={3} bounded={4} ite={5} oid={6} probeErr={7}[{8}]' -f `
        (Format-RealtekITRNullableText -Value $rssV2Snapshot.Source -Unavailable 'unavailable'), `
        (Format-RealtekITRNullableText -Value $rssV2Snapshot.RssV2Status -Unavailable 'unknown'), `
        (Format-RealtekITRNullableText -Value $rssV2Snapshot.Enabled -Unavailable 'unknown'), `
        (Format-RealtekITRNullableText -Value $rssV2QueueCount -Unavailable 'unknown'), `
        (Format-RealtekITRNullableText -Value $rssV2BoundedRxQueues -Unavailable 'unknown'), `
        (Format-RealtekITRNullableText -Value $rssV2IteCount -Unavailable 'unknown'), `
        (Format-RealtekITRNullableText -Value $rssV2Snapshot.DirectOidCapability -Unavailable 'user-mode-unavailable'), `
        $rssV2ProbeErrorCount, `
        $rssV2ProbeErrorBrief)
    if ($null -ne $msixTopology -and -not [string]::IsNullOrWhiteSpace([string]$msixTopology.Error)) {
        $msixErr = [string]$msixTopology.Error
    } else {
        $msixErr = 'no probe error captured'
    }

    $msixText = if ($null -ne $msixTopology -and [bool]$msixTopology.Available) {
        ('MSIX {0} entries={1}/{2} cap=0x{3:X2}' -f [string]$msixTopology.Bdf, [int]$msixTopology.ReadEntries, [int]$msixTopology.TableSize, [int]$msixTopology.CapabilityOffset)
    } else {
        ('MSIX unavailable: {0}' -f $msixErr)
    }
    $summary = 'primaryRx={0}; {1}; {2}; MMIO RSS_CTRL=0x{3:X8} hash=0x{4:X2} rssQcode={5}->{6} retaCode={7}->{8} RETAread=128 QNUM=0x{9:X4} rxQweak={10}->{11} TXOCP_E63E={12} hits={13} RXactive~{14} TXactive~{15} {16}; {17}; IntMITI queue banks are layout-verified only, unknown banks remain unverified raw candidates' -f $rssPrimaryText, $moderationLayoutText, $rssV2Text, $rssCtrl, $rssCtrlHashMask, $rssCtrlRxCode, $rssCtrlRxQueues, $rssCtrlMaskCode, $rssCtrlTableEntries, $qNumCtrl, $qNumRxCode, $qNumRxQueues, $txOcpText, $hitText, $rxQueues, $txQueues, ($activeBanks.ToArray() -join ' '), $msixText
    Write-NICITRDiagnostic -Level Info -Message ('Realtek IntMITI V2 topology decoded: device={0}; {1}' -f $deviceDebugName, $summary)
    return [PSCustomObject]@{
        Labels = [string[]]$labels
        Summary = $summary
        QueueSlotLimit = [int]$queueSlotLimit
        QueueRecords = [object[]]$queueRecords.ToArray()
        RssV2Snapshot = $rssV2Snapshot
        RssV2PrimaryState = [string]$rssV2PrimaryState
        RssV2BoundedRxQueues = $rssV2BoundedRxQueues
        RssV2QueueCount = $rssV2QueueCount
        RssV2IteCount = $rssV2IteCount
        RssEffectiveDisabled = [bool]$rssEffectiveDisabled
        RssDisableReason = [string]$rssDisableReasonText
        RealtekQueueModerationLayout = $moderationLayout
        RealtekQueueModerationLayoutText = [string]$moderationLayoutText
        MsixVectorTopology = $msixTopology
        RssCtrl = [uint64]$rssCtrl
        RssCtrlHashMask = [uint64]$rssCtrlHashMask
        RssCtrlHashEnabled = [bool]$rssCtrlHashEnabled
        RssCtrlRxCode = [int]$rssCtrlRxCode
        RssCtrlDecodedRxQueues = [int]$rssCtrlRxQueues
        RssCtrlTableCode = [int]$rssCtrlMaskCode
        RssCtrlDecodedTableEntries = [int]$rssCtrlTableEntries
        QNumCtrl = [uint64]$qNumCtrl
        QNumRxCode = [int]$qNumRxCode
        QNumDecodedRxQueuesWeak = [int]$qNumRxQueues
        TxQNumOcp = $txOcp
        TxQNumOcpCode = $txOcpCode
        TxQNumOcpDecodedQueues = $txOcpQueues
        RssIndirectionDwords = [uint64[]]$rssDwords.ToArray()
        RssIndirectionBytes = [int[]]$rssBytes.ToArray()
        RssIndirectionHitCounts = $queueHitCounts
        RssIndirectionQueues = [int[]]$indirQueues
        LikelyRxQueues = [int]$rxQueues
        LikelyTxQueues = [int]$txQueues
        RxDescriptorQueues = $rxDescRecords
        TxDescriptorQueues = $txDescRecords
        TxHighPriorityDescriptor = $txHighPriorityDesc
        TxPointerQueues = $txPointerRecords
        TxIdleCredits = $txIdleCredits
        ImrV2Clear = [uint64]$imrV2Clear
        ImrV2Set = [uint64]$imrV2Set
        IsrV2 = [uint64]$isrV2
        RduStatus = [uint64]$rduSta
        TduStatus = [uint64]$tduSta
    }
}

function Apply-RealtekIntMitiV2TopologyToNicInfo {
    param([hashtable]$nicInfo, [object]$Topology)
    if ($null -eq $nicInfo -or $null -eq $Topology) { return }
    $errorText = $null
    $errorProp = $Topology.PSObject.Properties['Error']
    if ($null -ne $errorProp -and $null -ne $errorProp.Value -and -not [string]::IsNullOrWhiteSpace([string]$errorProp.Value)) { $errorText = [string]$errorProp.Value }

    $labelsProp = $Topology.PSObject.Properties['Labels']
    $labelList = @()
    if ($null -ne $labelsProp -and $null -ne $labelsProp.Value) { $labelList = @($labelsProp.Value | ForEach-Object { [string]$_ }) }
    if ($labelList.Count -eq 0 -and -not [string]::IsNullOrWhiteSpace($errorText) -and $nicInfo.ContainsKey('Family') -and $nicInfo.Family -eq 'RealtekIntrMitV2') {
        $count = if ($nicInfo.ContainsKey('MaxQueues')) { [int]$nicInfo.MaxQueues } else { 64 }
        $labelList = @(New-RealtekIntMitiV2TopologyErrorLabels -Count $count -Error $errorText)
    }
    if ($labelList.Count -gt 0) { $nicInfo['VectorLabels'] = [string[]]$labelList }

    $summaryProp = $Topology.PSObject.Properties['Summary']
    if ($null -ne $summaryProp -and $null -ne $summaryProp.Value) { $nicInfo['RuntimeQueueTopology'] = [string]$summaryProp.Value }
    if (-not [string]::IsNullOrWhiteSpace($errorText)) {
        $nicInfo['RealtekTopologyError'] = $errorText
        Write-NICITRDiagnostic -Level Error -Message ('Realtek IntMITI V2 topology applied in error state: {0}' -f $errorText)
    } elseif ($nicInfo.ContainsKey('RealtekTopologyError')) {
        [void]$nicInfo.Remove('RealtekTopologyError')
    }
    $nicInfo['RealtekTopology'] = $Topology
}

function Update-RealtekIntMitiV2TopologyInNicInfo {
    param([PSCustomObject]$device, [hashtable]$deviceMap, [hashtable]$nicInfo)
    if ($null -eq $nicInfo -or $nicInfo.Family -ne 'RealtekIntrMitV2') { return $null }
    $topology = Get-RealtekIntMitiV2Topology -device $device -deviceMap $deviceMap -nicInfo $nicInfo
    Apply-RealtekIntMitiV2TopologyToNicInfo -nicInfo $nicInfo -Topology $topology
    return $topology
}

function Set-RealtekIntMitiV2TopologyOnControls {
    param([hashtable]$ctrls, [hashtable]$nicInfo, [object]$Topology)
    if ($null -eq $ctrls -or $null -eq $nicInfo -or $null -eq $Topology) { return }
    Apply-RealtekIntMitiV2TopologyToNicInfo -nicInfo $nicInfo -Topology $Topology
    if ($ctrls.ContainsKey('NICFamilyLabel') -and $null -ne $ctrls.NICFamilyLabel) {
        $familyName = if ($nicInfo.ContainsKey('FamilyName')) { [string]$nicInfo.FamilyName } else { 'Realtek IntMITI V2' }
        $summary = if ($nicInfo.ContainsKey('RuntimeQueueTopology')) { [string]$nicInfo.RuntimeQueueTopology } else { $null }
        if (-not [string]::IsNullOrWhiteSpace($summary)) {
            $ctrls.NICFamilyLabel.Text = ('[{0}] | {1}' -f $familyName, $summary)
            Sync-ScrollableLabelIfNeeded -label $ctrls.NICFamilyLabel
            try {
                $geo = [DeviceEditorBuilder]::DescribeScrollableLabel($ctrls.NICFamilyLabel)
                Write-NICITRDiagnostic -Level Info -Message ('Realtek IntMITI V2 family/topology label updated. textLen={0}; geometry={1}' -f ([string]$ctrls.NICFamilyLabel.Text).Length, $geo)
            } catch { }
        }
    }
}

function Get-NICIMODIndexedOffset {
    param([hashtable]$nicInfo, [int]$Index, [string]$Direction = 'Rx')
    $idx = [Math]::Max(0, [int]$Index)
    $stride = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('Stride')) { [uint64]$nicInfo.Stride } else { [uint64]0 }
    if ($Direction -eq 'Tx' -and $null -ne $nicInfo -and $nicInfo.ContainsKey('TxBaseOffset')) {
        return ([uint64]$nicInfo.TxBaseOffset + ($stride * [uint64]$idx))
    }
    if ($Direction -eq 'Rx' -and $null -ne $nicInfo -and $nicInfo.ContainsKey('SegmentBreakIndex') -and $nicInfo.ContainsKey('Segment2BaseOffset')) {
        $breakIndex = [int]$nicInfo.SegmentBreakIndex
        if ($breakIndex -gt 0 -and $idx -ge $breakIndex) {
            return ([uint64]$nicInfo.Segment2BaseOffset + ($stride * [uint64]($idx - $breakIndex)))
        }
    }
    return ([uint64]$nicInfo.BaseOffset + ($stride * [uint64]$idx))
}

function Read-NICIMOD {
    param([PSCustomObject]$device, [hashtable]$deviceMap, [hashtable]$nicInfo)
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $device
    $familyName = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('FamilyName')) { [string]$nicInfo.FamilyName } elseif ($null -ne $nicInfo -and $nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '<unknown NIC ITR family>' }
    $bar = Get-NICDeviceAddress $device $deviceMap
    if ($bar -eq 0) {
        $mapKeys = if ($null -ne $deviceMap) { @($deviceMap.Keys).Count } else { 0 }
        Write-NICITRDiagnostic -Level Error -Message ('Read-NICIMOD aborted: PCI BAR address unresolved. device={0}; family={1}; deviceMapKeys={2}' -f $deviceDebugName, $familyName, $mapKeys)
        return $null
    }
    Write-NICITRDiagnostic -Level Info -Message ('Read-NICIMOD start: device={0}; family={1}; BAR=0x{2:X}; baseOffset=0x{3:X}; stride=0x{4:X}; count={5}; width={6}' -f $deviceDebugName, $familyName, [uint64]$bar, [uint64]$nicInfo.BaseOffset, [uint64]$nicInfo.Stride, [int]$nicInfo.MaxQueues, [int]$nicInfo.ReadWidth)
    $values = [System.Collections.Generic.List[object]]::new()
    $readCmd = if ($nicInfo.ReadWidth -eq 16) { "R16" } else { "R32" }
    $readWidth = if ($nicInfo.ReadWidth -eq 16) { 16 } else { 32 }
    $hasTxOffset = $nicInfo.ContainsKey('TxOffset') -and $nicInfo.TxOffset -gt 0
    $hasTxBaseOffset = $nicInfo.ContainsKey('TxBaseOffset')

    if ($nicInfo.MaxQueues -gt 1 -or $hasTxBaseOffset -or $hasTxOffset) {
        try {
            $rxAddresses = [System.Collections.Generic.List[uint64]]::new()
            $txAddresses = [System.Collections.Generic.List[uint64]]::new()
            for ($q = 0; $q -lt $nicInfo.MaxQueues; $q++) {
                $addr = [uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Rx'))
                [void]$rxAddresses.Add($addr)
                if ($hasTxBaseOffset) {
                    [void]$txAddresses.Add([uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Tx')))
                } elseif ($hasTxOffset) {
                    [void]$txAddresses.Add([uint64]($addr + $nicInfo.TxOffset))
                }
            }

            $rxBatch = Invoke-RWEReadBatch -Addresses ([uint64[]]$rxAddresses.ToArray()) -Width $readWidth
            $txBatch = $null
            if ($txAddresses.Count -gt 0) {
                $txWidth = if ($hasTxBaseOffset) { 32 } else { $readWidth }
                $txBatch = Invoke-RWEReadBatch -Addresses ([uint64[]]$txAddresses.ToArray()) -Width $txWidth
            }

            for ($q = 0; $q -lt $nicInfo.MaxQueues; $q++) {
                $rxKey = ('{0:X16}' -f ([uint64]$rxAddresses[$q]))
                if (-not $rxBatch.ContainsKey($rxKey)) { throw ('missing NIC RX batch value for address 0x{0:X}' -f ([uint64]$rxAddresses[$q])) }
                $rxVal = [uint64]$rxBatch[$rxKey]
                if ($hasTxBaseOffset) {
                    $txKey = ('{0:X16}' -f ([uint64]$txAddresses[$q]))
                    if (-not $txBatch.ContainsKey($txKey)) { throw ('missing NIC TX batch value for address 0x{0:X}' -f ([uint64]$txAddresses[$q])) }
                    $txVal = [uint64]$txBatch[$txKey]
                    $combined = (([uint64]($rxVal -band [uint64]4294967295)) -bor (([uint64]($txVal -band [uint64]4294967295)) -shl 32))
                    [void]$values.Add($combined -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
                } elseif ($hasTxOffset) {
                    $txKey = ('{0:X16}' -f ([uint64]$txAddresses[$q]))
                    if (-not $txBatch.ContainsKey($txKey)) { throw ('missing NIC TX batch value for address 0x{0:X}' -f ([uint64]$txAddresses[$q])) }
                    $txVal = [uint64]$txBatch[$txKey]
                    $combined = (($rxVal -band [uint64]0xFFFF) -bor (($txVal -band [uint64]0xFFFF) -shl 16))
                    [void]$values.Add($combined -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
                } else {
                    [void]$values.Add($rxVal -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
                }
            }
            return $values
        } catch {
            Write-NICITRDiagnostic -Level Warning -Message ('Read-NICIMOD batch read failed; falling back to serialized reads. device={0}; family={1}; BAR=0x{2:X}; RXcount={3}; TXcount={4}' -f $deviceDebugName, $familyName, [uint64]$bar, $rxAddresses.Count, $txAddresses.Count) -Exception $_
            $values.Clear()
        }
    }

    for ($q = 0; $q -lt $nicInfo.MaxQueues; $q++) {
        $addr = [uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Rx'))
        $hexAddr = "0x$($addr.ToString('X2'))"
        try {
            $stdout = Invoke-RWECommand -Command "$readCmd $hexAddr"
            $rxVal = (Convert-RWEverythingOutputToUInt64 $stdout)
            if ($hasTxBaseOffset) {
                $txAddr = [uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Tx'))
                $txHexAddr = "0x$($txAddr.ToString('X2'))"
                $txStdout = Invoke-RWECommand -Command "R32 $txHexAddr"
                $txVal = (Convert-RWEverythingOutputToUInt64 $txStdout)
                $combined = (([uint64]($rxVal -band [uint64]4294967295)) -bor (([uint64]($txVal -band [uint64]4294967295)) -shl 32))
                [void]$values.Add($combined -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
            } elseif ($hasTxOffset) {
                $txAddr = $addr + $nicInfo.TxOffset
                $txHexAddr = "0x$($txAddr.ToString('X2'))"
                $txStdout = Invoke-RWECommand -Command "$readCmd $txHexAddr"
                $txVal = (Convert-RWEverythingOutputToUInt64 $txStdout)
                $combined = (($rxVal -band [uint64]0xFFFF) -bor (($txVal -band [uint64]0xFFFF) -shl 16))
                [void]$values.Add($combined -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
            } else {
                [void]$values.Add($rxVal -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $q))
            }
        } catch {
            Write-NICITRDiagnostic -Level Error -Message ('Read-NICIMOD serialized read failed. device={0}; family={1}; index={2}; readCmd={3}; rxAddress=0x{4:X}' -f $deviceDebugName, $familyName, $q, $readCmd, [uint64]$addr) -Exception $_
            [void]$values.Add([uint64]0)
        }
    }
    Write-NICITRDiagnostic -Level Info -Message ('Read-NICIMOD complete: device={0}; values={1}' -f $deviceDebugName, (Format-NICIMODValueListText -values ([uint64[]]@($values.ToArray())) -nicInfo $nicInfo))
    return $values
}

function Write-NICIMOD {
    param([PSCustomObject]$device, [hashtable]$deviceMap, [hashtable]$nicInfo, [uint64]$newValue, [uint64[]]$perQueueValues = $null)
    $deviceDebugName = Get-NICITRDeviceDebugName -Device $device
    $familyName = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('FamilyName')) { [string]$nicInfo.FamilyName } elseif ($null -ne $nicInfo -and $nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '<unknown NIC ITR family>' }
    $bar = Get-NICDeviceAddress $device $deviceMap
    if ($bar -eq 0) {
        $mapKeys = if ($null -ne $deviceMap) { @($deviceMap.Keys).Count } else { 0 }
        Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD aborted: PCI BAR address unresolved. device={0}; family={1}; deviceMapKeys={2}' -f $deviceDebugName, $familyName, $mapKeys)
        return $false
    }
    Write-NICITRDiagnostic -Level Info -Message ('Write-NICIMOD start: device={0}; family={1}; BAR=0x{2:X}; baseOffset=0x{3:X}; stride=0x{4:X}; count={5}; width={6}; uniform=0x{7:X}' -f $deviceDebugName, $familyName, [uint64]$bar, [uint64]$nicInfo.BaseOffset, [uint64]$nicInfo.Stride, [int]$nicInfo.MaxQueues, [int]$nicInfo.ReadWidth, [uint64]$newValue)

    $writeCmd = if ($nicInfo.ReadWidth -eq 16) { "W16" } else { "W32" }
    $orBits = if ($nicInfo.ContainsKey('WriteORBits')) { [uint64]$nicInfo.WriteORBits } else { [uint64]0 }
    $hasTxOffset = $nicInfo.ContainsKey('TxOffset') -and $nicInfo.TxOffset -gt 0
    $hasTxBaseOffset = $nicInfo.ContainsKey('TxBaseOffset')

    for ($q = 0; $q -lt $nicInfo.MaxQueues; $q++) {
        $addr = [uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Rx'))
        $hexAddr = "0x$($addr.ToString('X2'))"
        $qVal = if ($null -ne $perQueueValues -and $q -lt $perQueueValues.Count) {
            [uint64]$perQueueValues[$q]
        } else {
            [uint64]$newValue
        }
        $qMask = Get-NICIMODValueMask -nicInfo $nicInfo -Index $q
        $qMaskedVal = Limit-NICIMODValueToHardwareRange -Value $qVal -nicInfo $nicInfo -Index $q
        if ($hasTxBaseOffset) {
            $rxVal = (($qMaskedVal -band [uint64]4294967295) -bor ($orBits -band [uint64]4294967295))
            $rxHex = "0x$($rxVal.ToString('X'))"
            try {
                Invoke-RWECommand -Command "W32 $hexAddr $rxHex" -AllowEmptyOutput | Out-Null
            } catch {
                Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD RX dword write failed. device={0}; family={1}; index={2}; address=0x{3:X}; value=0x{4:X}' -f $deviceDebugName, $familyName, $q, [uint64]$addr, [uint64]$rxVal) -Exception $_
                return $false
            }
            $txAddr = [uint64]($bar + (Get-NICIMODIndexedOffset -nicInfo $nicInfo -Index $q -Direction 'Tx'))
            $txHexAddr = "0x$($txAddr.ToString('X2'))"
            $txVal = ((($qMaskedVal -shr 32) -band [uint64]4294967295) -bor ($orBits -band [uint64]4294967295))
            $txHex = "0x$($txVal.ToString('X'))"
            try {
                Invoke-RWECommand -Command "W32 $txHexAddr $txHex" -AllowEmptyOutput | Out-Null
            } catch {
                Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD TX dword write failed. device={0}; family={1}; index={2}; address=0x{3:X}; value=0x{4:X}' -f $deviceDebugName, $familyName, $q, [uint64]$txAddr, [uint64]$txVal) -Exception $_
                return $false
            }
        } elseif ($hasTxOffset) {
            $rxVal = (($qMaskedVal -band [uint64]0xFFFF) -bor $orBits)
            $rxHex = "0x$($rxVal.ToString('X'))"
            try {
                Invoke-RWECommand -Command "$writeCmd $hexAddr $rxHex" -AllowEmptyOutput | Out-Null
            } catch {
                Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD RX/combined write failed. device={0}; family={1}; index={2}; cmd={3}; address=0x{4:X}; value=0x{5:X}' -f $deviceDebugName, $familyName, $q, $writeCmd, [uint64]$addr, [uint64]$rxVal) -Exception $_
                return $false
            }
            $txAddr = $addr + $nicInfo.TxOffset
            $txHexAddr = "0x$($txAddr.ToString('X2'))"
            $txVal = ((($qMaskedVal -shr 16) -band [uint64]0xFFFF) -bor $orBits)
            $txHex = "0x$($txVal.ToString('X'))"
            try {
                Invoke-RWECommand -Command "$writeCmd $txHexAddr $txHex" -AllowEmptyOutput | Out-Null
            } catch {
                Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD TX-offset write failed. device={0}; family={1}; index={2}; cmd={3}; address=0x{4:X}; value=0x{5:X}' -f $deviceDebugName, $familyName, $q, $writeCmd, [uint64]$txAddr, [uint64]$txVal) -Exception $_
                return $false
            }
        } else {
            $finalVal = ($qMaskedVal -bor $orBits)
            $hexVal = "0x$($finalVal.ToString('X'))"
            try {
                Invoke-RWECommand -Command "$writeCmd $hexAddr $hexVal" -AllowEmptyOutput | Out-Null
            } catch {
                Write-NICITRDiagnostic -Level Error -Message ('Write-NICIMOD dword/word write failed. device={0}; family={1}; index={2}; cmd={3}; address=0x{4:X}; value=0x{5:X}' -f $deviceDebugName, $familyName, $q, $writeCmd, [uint64]$addr, [uint64]$finalVal) -Exception $_
                return $false
            }
        }
    }
    Write-NICITRDiagnostic -Level Info -Message ('Write-NICIMOD complete: device={0}; family={1}; wrote {2} vector slot(s)' -f $deviceDebugName, $familyName, [int]$nicInfo.MaxQueues)
    return $true
}

function Get-NICIMODVectorLabels {
    param([hashtable]$nicInfo)

    if ($null -eq $nicInfo) { return @() }
    Ensure-RealtekIntMitiV2VectorLabels -nicInfo $nicInfo
    if ($nicInfo.ContainsKey('VectorLabels') -and $null -ne $nicInfo.VectorLabels -and $nicInfo.VectorLabels.Count -gt 0) {
        return @($nicInfo.VectorLabels)
    }

    $labels = [System.Collections.Generic.List[string]]::new()
    for ($i = 0; $i -lt $nicInfo.MaxQueues; $i++) {
        $labels.Add("Q$($i)")
    }
    return $labels
}

function Get-NICIMODCompactVectorLabel {
    param(
        [hashtable]$nicInfo,
        [int]$Index,
        [AllowNull()][string]$Label
    )

    $idx = [Math]::Max(0, [int]$Index)
    $raw = if ([string]::IsNullOrWhiteSpace($Label)) { '' } else { ([string]$Label -replace '[\r\n]+', ' ').Trim() }
    $family = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '' }

    if ($family -eq 'RealtekIntrMitV2') {
        $mode = if ($null -ne $nicInfo -and $nicInfo.ContainsKey('PerIndexMaskMode')) { [string]$nicInfo.PerIndexMaskMode } else { '' }
        $oddRxOnly = ($mode -eq 'RealtekV2AlternatingIntMitiLow16' -or $mode -eq 'RealtekV2AlternatingFullLow16') -and (($idx % 2) -ne 0)
        if ($raw -match 'RXQ(\d+)/TXQ\d+.*?IntMITI(\d+)') { return ('Q{0}/I{1}' -f $matches[1], $matches[2]) }
        if ($raw -match 'Q(\d+).*?IntMITI(\d+)') { return ('Q{0}/I{1}' -f $matches[1], $matches[2]) }
        if ($raw -match 'IntMITI(\d+)') {
            if ($oddRxOnly -or $raw -match 'RX-only|adjacent|No queue claim') { return ('I{0}/RXonly' -f $matches[1]) }
            return ('I{0}' -f $matches[1])
        }
        if (($idx % 2) -eq 0) { return ('Q{0}/I{1}' -f ([int]($idx / 2)), $idx) }
        if ($oddRxOnly) { return ('I{0}/RXonly' -f $idx) }
        return ('I{0}' -f $idx)
    }

    if (-not [string]::IsNullOrWhiteSpace($raw) -and $raw.Length -le 28) { return $raw }
    if ($raw -match '\b(INTPF|GLINT)(\d+)\b') { return ($matches[1] + $matches[2]) }
    if ($raw -match '\b(V|Q|RxQ|TxQ)(\d+)\b') { return ($matches[1] + $matches[2]) }
    return ('Q{0}' -f $idx)
}

function Get-NICIMODMultipleValuesText {
    param([hashtable]$nicInfo)

    if ($null -ne $nicInfo -and $nicInfo.Family -eq 'RealtekIntrMitV2') {
        $lastQueue = [Math]::Max(0, [int]$nicInfo.MaxQueues - 1)
        return "Multiple IntMITI V2 editable 32-bit dword values (IntMITI0-IntMITI$lastQueue; runtime mapping uses RSS_CTRL/Q_NUM/RSS indirection/descriptor/status reads when available; even dwords carry low=RX high=TX, adjacent odd dwords are not queue banks)"
    }
    if ($null -ne $nicInfo -and $nicInfo.Family -eq 'RealtekIntrMit') {
        return 'Single IntrMitigate value (Rx[7:0] + Tx[15:8])'
    }

    $labels = @(Get-NICIMODVectorLabels $nicInfo)
    if ($labels.Count -eq 0) { return "Multiple values" }

    $queueOnly = $true
    for ($i = 0; $i -lt $labels.Count; $i++) {
        if ($labels[$i] -ne "Q$($i)") {
            $queueOnly = $false
            break
        }
    }

    if ($queueOnly -and $labels.Count -gt 1) {
        return "Multiple values (Q0-Q$($labels.Count - 1))"
    }

    if ($labels.Count -gt 8) {
        return "Multiple values ($($labels[0]) ... $($labels[$labels.Count - 1]))"
    }
    return "Multiple values ($($labels -join ', '))"
}

function Format-NICIMODValueHex {
    param([uint64]$value, [hashtable]$nicInfo)

    $hexDigits = if ($nicInfo.ReadWidth -eq 16) { 4 } elseif ($nicInfo.ReadWidth -eq 64) { 16 } else { 8 }
    return "0x$($value.ToString("X$hexDigits"))"
}

function Format-NICIMODValueListText {
    param([uint64[]]$values, [hashtable]$nicInfo)

    if ($null -eq $values -or $values.Count -eq 0) { return "" }
    $formatted = foreach ($value in $values) { Format-NICIMODValueHex -value ([uint64]$value) -nicInfo $nicInfo }
    return ($formatted -join ',')
}


function Get-HexVectorMaxTextLength {
    param(
        [int]$hexDigits,
        [int]$valueCount
    )

    $safeDigits = [Math]::Max(1, $hexDigits)
    $safeCount = [Math]::Max(1, $valueCount)
    return (($safeDigits + 2) * $safeCount) + ($safeCount - 1)
}

function Get-HexVectorDisplayWidth {
    param(
        [System.Drawing.Font]$font,
        [int]$hexDigits,
        [int]$valueCount,
        [int]$minimumWidth = 0
    )

    $safeDigits = [Math]::Max(1, $hexDigits)
    $safeCount = [Math]::Max(1, $valueCount)
    $sampleToken = '0x' + ('F' * $safeDigits)
    $sampleText = ((1..$safeCount | ForEach-Object { $sampleToken }) -join ',')
    $tf = [System.Windows.Forms.TextFormatFlags]::NoPadding
    $measured = [System.Windows.Forms.TextRenderer]::MeasureText($sampleText, $font, [System.Drawing.Size]::new(99999, 99), $tf).Width + 18
    if ($minimumWidth -gt 0) {
        return [Math]::Max($measured, $minimumWidth)
    }
    return $measured
}

function Normalize-HexVectorInputText {
    param(
        [string]$text,
        [int]$maxHexDigits,
        [int]$maxValueCount = 0
    )

    $raw = if ($null -eq $text) { '' } else { [string]$text }
    $raw = $raw -replace '[\r\n]+', ''
    if ([string]::IsNullOrWhiteSpace($raw)) { return '0x' }

    $segments = [regex]::Split($raw, '([,;|\s]+)')
    $sb = [System.Text.StringBuilder]::new()
    $haveToken = $false
    $pendingDelimiter = $false
    $emittedTokenCount = 0

    foreach ($segment in $segments) {
        if ([string]::IsNullOrEmpty($segment)) { continue }

        if ($segment -match '^[,;|\s]+$') {
            if ($haveToken -and ($maxValueCount -le 0 -or $emittedTokenCount -lt $maxValueCount)) {
                $pendingDelimiter = $true
            }
            continue
        }

        $hexOnly = ($segment -replace '^(?i)0x', '') -replace '[^0-9A-Fa-f]', ''
        if ($hexOnly.Length -gt $maxHexDigits) {
            $hexOnly = $hexOnly.Substring(0, $maxHexDigits)
        }

        $shouldEmitToken = ($segment -match '^(?i)0x?$') -or $hexOnly.Length -gt 0
        if (-not $shouldEmitToken) { continue }
        if ($maxValueCount -gt 0 -and $emittedTokenCount -ge $maxValueCount) { continue }

        if ($pendingDelimiter -and $sb.Length -gt 0 -and $sb[$sb.Length - 1] -ne ',') {
            [void]$sb.Append(',')
        }

        [void]$sb.Append('0x')
        [void]$sb.Append($hexOnly.ToUpperInvariant())
        $haveToken = $true
        $pendingDelimiter = $false
        $emittedTokenCount++
    }

    if ($sb.Length -eq 0) { return '0x' }

    if ($raw -match '[,;|\s]+$' -and $sb[$sb.Length - 1] -ne ',' -and ($maxValueCount -le 0 -or $emittedTokenCount -lt $maxValueCount)) {
        [void]$sb.Append(',')
    }

    return $sb.ToString()
}

function New-IMODCustomHScrollBar {
    param(
        [System.Windows.Forms.TextBox]$textBox,
        [System.Windows.Forms.Panel]$parentPanel,
        [int]$trackHeight = 10
    )

    $uiType = $null
    foreach ($asm in [AppDomain]::CurrentDomain.GetAssemblies()) {
        $uiType = $asm.GetType('DeviceEditorNativeUiSupport', $false, $false)
        if ($null -ne $uiType) { break }
    }
    if ($null -eq $uiType) { throw [System.InvalidOperationException]::new('DeviceEditorNativeUiSupport type was not found after native UI Add-Type compilation.') }
    $flags = [System.Reflection.BindingFlags]::Public -bor [System.Reflection.BindingFlags]::Static
    $method = $uiType.GetMethod('CreateTextBoxHScroll', $flags)
    if ($null -eq $method) { throw [System.MissingMethodException]::new('DeviceEditorNativeUiSupport', 'CreateTextBoxHScroll') }
    try {
        return $method.Invoke($null, @($textBox, $parentPanel, $trackHeight, $script:colBlack))
    } catch [System.Reflection.TargetInvocationException] {
        if ($null -ne $_.Exception.InnerException) { throw $_.Exception.InnerException }
        throw
    }
}

function New-ScrollableLabel {
    param(
        [System.Windows.Forms.Control]$parentPanel,
        [int]$left,
        [int]$top,
        [int]$viewWidth,
        [int]$viewHeight = 18,
        [int]$trackHeight = 8,
        [System.Drawing.Font]$font,
        [System.Drawing.Color]$foreColor
    )

    $uiType = $null
    foreach ($asm in [AppDomain]::CurrentDomain.GetAssemblies()) {
        $uiType = $asm.GetType('DeviceEditorNativeUiSupport', $false, $false)
        if ($null -ne $uiType) { break }
    }
    if ($null -eq $uiType) { throw [System.InvalidOperationException]::new('DeviceEditorNativeUiSupport type was not found after native UI Add-Type compilation.') }
    $flags = [System.Reflection.BindingFlags]::Public -bor [System.Reflection.BindingFlags]::Static
    $method = $uiType.GetMethod('CreateScrollableLabel', $flags)
    if ($null -eq $method) { throw [System.MissingMethodException]::new('DeviceEditorNativeUiSupport', 'CreateScrollableLabel') }
    try {
        $native = $method.Invoke($null, @($parentPanel, $left, $top, $viewWidth, $viewHeight, $trackHeight, $font, $foreColor, $script:colBlack))
        return @{
            Container = $native.Container
            Label = $native.Label
            Viewport = $native.Viewport
            Track = $native.Track
            Thumb = $native.Thumb
            State = $native.State
            Sync = $native.Sync
        }
    } catch [System.Reflection.TargetInvocationException] {
        if ($null -ne $_.Exception.InnerException) { throw $_.Exception.InnerException }
        throw
    }
}

function Format-USBIMODValueHex {
    param([uint16]$value)
    return '0x{0:X4}' -f $value
}

function Format-USBIMODValueListText {
    param([uint16[]]$values)

    if ($null -eq $values -or $values.Count -eq 0) { return '' }
    $formatted = foreach ($value in $values) { Format-USBIMODValueHex -value ([uint16]$value) }
    return ($formatted -join ',')
}

function Parse-USBIMODInput {
    param(
        [string]$text,
        [int]$expectedCount = 0
    )

    $raw = if ($null -eq $text) { '' } else { $text.Trim() }
    if ([string]::IsNullOrWhiteSpace($raw) -or $raw -eq '0x') {
        if ($expectedCount -gt 1) {
            throw "Enter either one hex value or exactly $expectedCount per-interrupter hex values separated by commas."
        }
        throw 'Enter a hex value in the form 0x1234.'
    }

    $tokens = @($raw -split '[,;|\s]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    foreach ($token in $tokens) {
        if ($token -notmatch '^0x[0-9A-Fa-f]{1,4}$') {
            throw "Invalid hex value: $token"
        }
    }

    if ($tokens.Count -eq 1) {
        return [PSCustomObject]@{
            UniformValue         = [uint16][Convert]::ToUInt16($tokens[0].Substring(2), 16)
            PerInterrupterValues = $null
        }
    }

    if ($expectedCount -gt 0 -and $tokens.Count -ne $expectedCount) {
        throw "Enter either one hex value or exactly $expectedCount per-interrupter values."
    }

    $values = [System.Collections.Generic.List[uint16]]::new()
    foreach ($token in $tokens) {
        $values.Add([uint16][Convert]::ToUInt16($token.Substring(2), 16))
    }

    return [PSCustomObject]@{
        UniformValue         = $null
        PerInterrupterValues = @($values)
    }
}

function Convert-USBIMODToTimeString {
    param([uint16]$rawValue)

    $ns = [uint64]$rawValue * 250
    if ($ns -ge 1000) {
        return "$($ns / 1000.0) µs"
    }
    return "$ns ns"
}

function Set-USBIMODControlsFromValues {
    param(
        [hashtable]$ctrls,
        [object[]]$imodValues
    )

    if ($null -eq $ctrls) { return }

    if ($imodValues -and $imodValues.Count -gt 0) {
        $typedValues = @($imodValues | ForEach-Object { [uint16]$_ })
        $ctrls.ExpectedUSBInterrupterCount = $typedValues.Count

        if ($null -ne $ctrls.NewIMOD) {
            $tagTarget = $null
            if ($ctrls.NewIMOD.Tag -is [hashtable] -and $ctrls.NewIMOD.Tag.ContainsKey('OrigTag') -and $ctrls.NewIMOD.Tag.OrigTag -is [hashtable]) {
                $tagTarget = $ctrls.NewIMOD.Tag.OrigTag
            } elseif ($ctrls.NewIMOD.Tag -is [hashtable]) {
                $tagTarget = $ctrls.NewIMOD.Tag
            }
            if ($null -ne $tagTarget) {
                $tagTarget.ExpectedCount = $typedValues.Count
            }
        }

        $allText = Format-USBIMODValueListText -values $typedValues
        if ($null -ne $ctrls.CurrentIMOD) { $ctrls.CurrentIMOD.Text = $allText }
        if ($null -ne $ctrls.NewIMOD) { $ctrls.NewIMOD.Text = $allText }

        if ($null -ne $ctrls.NewIMOD -and $null -ne $ctrls.IMODNsLabel) {
            Update-IMOD-NsLabel -textBox $ctrls.NewIMOD -label $ctrls.IMODNsLabel
        }
        return
    }

    $ctrls.ExpectedUSBInterrupterCount = 0
    if ($null -ne $ctrls.NewIMOD) {
        $tagTarget = $null
        if ($ctrls.NewIMOD.Tag -is [hashtable] -and $ctrls.NewIMOD.Tag.ContainsKey('OrigTag') -and $ctrls.NewIMOD.Tag.OrigTag -is [hashtable]) {
            $tagTarget = $ctrls.NewIMOD.Tag.OrigTag
        } elseif ($ctrls.NewIMOD.Tag -is [hashtable]) {
            $tagTarget = $ctrls.NewIMOD.Tag
        }
        if ($null -ne $tagTarget) {
            $tagTarget.ExpectedCount = 0
        }
    }

    if ($null -ne $ctrls.CurrentIMOD) { $ctrls.CurrentIMOD.Text = 'Error reading' }
    if ($null -ne $ctrls.IMODNsLabel) { $ctrls.IMODNsLabel.Text = '' }
}

function Parse-NICIMODInput {
    param([string]$text, [hashtable]$nicInfo)

    $raw = if ($null -eq $text) { '' } else { $text.Trim() }
    if ([string]::IsNullOrWhiteSpace($raw) -or $raw -eq '0x') {
        throw "Enter either one hex value or $($nicInfo.MaxQueues) per-bank/source hex values separated by commas."
    }

    $tokens = @($raw -split '[,;|\s]+' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    $maxHexLen = if ($nicInfo.ReadWidth -eq 16) { 4 } elseif ($nicInfo.ReadWidth -eq 64) { 16 } else { 8 }
    $pattern = "^0x[0-9A-Fa-f]{1,$maxHexLen}$"

    foreach ($token in $tokens) {
        if ($token -notmatch $pattern) { throw "Invalid hex value: $token" }
    }

    $clampWarnings = [System.Collections.Generic.List[string]]::new()

    if ($tokens.Count -eq 1) {
        $mask = Get-NICIMODValueMask -nicInfo $nicInfo -Index 0
        $val = [Convert]::ToUInt64($tokens[0].Substring(2), 16)
        $clamped = Limit-NICIMODValueToHardwareRange -Value $val -nicInfo $nicInfo -Index 0
        if ($mask -ne [uint64]::MaxValue -and $clamped -ne $val) {
            $clampWarnings.Add("$($tokens[0]) exceeds valid hardware range/mask for uniform/first bank 0x$($mask.ToString('X')), clamped to 0x$($clamped.ToString("X$maxHexLen"))")
        }
        if ($null -ne $nicInfo -and $nicInfo.Family -eq 'RealtekIntrMitV2' -and $nicInfo.MaxQueues -gt 1) {
            $mode = if ($nicInfo.ContainsKey('PerIndexMaskMode')) { [string]$nicInfo.PerIndexMaskMode } else { '' }
            if ($mode -eq 'RealtekV2AlternatingIntMitiLow16' -or $mode -eq 'RealtekV2AlternatingFullLow16') {
                $adjacentMask = Get-NICIMODValueMask -nicInfo $nicInfo -Index 1
                $adjacentClamped = $val -band $adjacentMask
                if ($adjacentMask -ne $mask -and $adjacentClamped -ne $val) {
                    $clampWarnings.Add("$($tokens[0]) exceeds valid range for adjacent RX-only IntMITI V2 dwords (odd indexes, mask 0x$($adjacentMask.ToString('X8'))), odd dwords will be written as 0x$($adjacentClamped.ToString("X$maxHexLen"))")
                }
            }
        }
        return [PSCustomObject]@{
            UniformValue   = $clamped
            PerQueueValues = $null
            ClampWarning   = if ($clampWarnings.Count -gt 0) { $clampWarnings -join "`n" } else { $null }
        }
    }

    if ($tokens.Count -ne $nicInfo.MaxQueues) {
        $labels = @(Get-NICIMODVectorLabels $nicInfo)
        $compactLabels = for ($li = 0; $li -lt $labels.Count; $li++) { Get-NICIMODCompactVectorLabel -nicInfo $nicInfo -Index $li -Label ([string]$labels[$li]) }
        throw "Enter either one hex value or exactly $($nicInfo.MaxQueues) values for $($compactLabels -join ', ')."
    }

    $values = [System.Collections.Generic.List[uint64]]::new()
    $labels = @(Get-NICIMODVectorLabels $nicInfo)
    for ($i = 0; $i -lt $tokens.Count; $i++) {
        $mask = Get-NICIMODValueMask -nicInfo $nicInfo -Index $i
        $val = [Convert]::ToUInt64($tokens[$i].Substring(2), 16)
        $clamped = Limit-NICIMODValueToHardwareRange -Value $val -nicInfo $nicInfo -Index $i
        if ($mask -ne [uint64]::MaxValue -and $clamped -ne $val) {
            $rawLabelText = if ($i -lt $labels.Count) { [string]$labels[$i] } else { "index $i" }
            $labelText = Get-NICIMODCompactVectorLabel -nicInfo $nicInfo -Index $i -Label $rawLabelText
            $clampWarnings.Add("$($tokens[$i]) exceeds valid hardware range/mask for $labelText (mask 0x$($mask.ToString('X'))), clamped to 0x$($clamped.ToString("X$maxHexLen"))")
        }
        [void]$values.Add($clamped)
    }

    return [PSCustomObject]@{
        UniformValue   = $null
        PerQueueValues = @($values)
        ClampWarning   = if ($clampWarnings.Count -gt 0) { $clampWarnings -join "`n" } else { $null }
    }
}

function Format-NICIMOD2usValue {
    param([uint32]$regValue)
    $us = [uint64]($regValue -band 0x1FFE)
    if ($us -gt [uint64]0x1FE0) { $us = [uint64]0x1FE0 }
    if ($us -eq 0) { return 'Off' }
    if ($us -ge 1000) { return "$([Math]::Round(([double]$us / 1000), 3))ms" }
    return "${us}µs"
}

function Format-NICIMODRxTx2usPair {
    param([uint64]$rawValue)
    $rxReg = [uint32]($rawValue -band [uint64]4294967295)
    $txReg = [uint32](($rawValue -shr 32) -band [uint64]4294967295)
    if ($rawValue -eq 0) { return 'Rx:Off Tx:Off' }
    return "Rx:$(Format-NICIMOD2usValue $rxReg) Tx:$(Format-NICIMOD2usValue $txReg)"
}

function Format-NICIMODDurationNs {
    param([uint64]$Nanoseconds)
    if ($Nanoseconds -eq 0) { return "0ns" }
    if ($Nanoseconds -lt 1000) { return "${Nanoseconds}ns" }
    $us = [double]$Nanoseconds / 1000.0
    if ($us -lt 1000) {
        if ([Math]::Abs($us - [Math]::Round($us)) -lt 0.000001) { return "$([uint64][Math]::Round($us))µs" }
        return "$($us.ToString('0.###',[System.Globalization.CultureInfo]::InvariantCulture))µs"
    }
    $ms = $us / 1000.0
    if ([Math]::Abs($ms - [Math]::Round($ms)) -lt 0.000001) { return "$([uint64][Math]::Round($ms))ms" }
    return "$($ms.ToString('0.###',[System.Globalization.CultureInfo]::InvariantCulture))ms"
}

function Format-RealtekIntrMitDelayRange {
    param([uint64]$Units)
    if ($Units -eq 0) { return "0ns" }
    $scaleSet = [uint64[]]@(320,2560,40960,20480,327700,5120,655400,10240,1310000,5000,40000,80000,160000,81920,327680,655360,1310720)
    $minNs = [uint64]::MaxValue
    $maxNs = [uint64]0
    foreach ($scale in $scaleSet) {
        $ns = [uint64]$Units * [uint64]$scale
        if ($ns -lt $minNs) { $minNs = $ns }
        if ($ns -gt $maxNs) { $maxNs = $ns }
    }
    $minText = Format-NICIMODDurationNs $minNs
    $maxText = Format-NICIMODDurationNs $maxNs
    if ($minNs -eq $maxNs) { return $minText }
    return "$minText-$maxText"
}

function Format-RealtekIntrMit1GDelay {
    param([uint64]$Units)
    if ($Units -eq 0) { return "0ns" }
    $ns = [uint64]$Units * [uint64]5000
    return Format-NICIMODDurationNs $ns
}

function Format-RealtekIntrMitEndpoint {
    param([string]$Prefix, [uint64]$TimeUnits, [uint64]$FrameUnits)
    $fieldFrames = [uint64]$FrameUnits * [uint64]4
    $framesText = if ($TimeUnits -eq 0) {
        if ($FrameUnits -eq 0) { "1f" } else { "1f(raw${fieldFrames}f)" }
    } else {
        "${fieldFrames}f"
    }
    $lowLatencyOneGigabitText = Format-RealtekIntrMit1GDelay $TimeUnits
    $rangeText = Format-RealtekIntrMitDelayRange $TimeUnits
    if ($rangeText -eq $lowLatencyOneGigabitText) { return "${Prefix}:u${TimeUnits}=${lowLatencyOneGigabitText}/${framesText}" }
    return "${Prefix}:u${TimeUnits}=${lowLatencyOneGigabitText}@1G(${rangeText})/${framesText}"
}

function Format-RealtekIntrMitV2Endpoint {
    param([string]$Prefix, [uint64]$TimeUnits, [uint64]$Frames)
    if ($TimeUnits -eq 0 -and $Frames -eq 0) { return "${Prefix}:0u/0f" }
    return "${Prefix}:u${TimeUnits}≈${TimeUnits}µs/f${Frames}"
}

function Convert-NICIMODToTimeString {
    param([uint64]$rawValue, [hashtable]$nicInfo, [int]$Index = -1)
    switch ($nicInfo.Family) {
        'IntelEITRv2' {
            return Format-NICIMODRxTx2usPair $rawValue
        }
        'IntelIceGLINT' {
            return Format-NICIMODRxTx2usPair $rawValue
        }
        'IntelIxgbeEITR' {
            $interval = ($rawValue -shr 3) -band 0x1FF
            $ns = [uint64]$interval * [uint64]2048
            if ($ns -eq 0) { return "Off (0ns)" }
            return (Format-NICIMODDurationNs $ns)
        }
        'IntelEITR' {
            $reg = [uint64]($rawValue -band [uint64]0x00007FFC)
            $ns = $reg * [uint64]256
            if ($ns -eq 0) { return "Off (0ns)" }
            return (Format-NICIMODDurationNs $ns)
        }
        'IntelITR' {
            $rate = [uint64]($rawValue -band [uint64]0xFFFF)
            if ($rate -eq 0) { return "Off (0 irq/s)" }
            $us = 1000000.0 / [double]$rate
            $timeText = if ($us -ge 1000.0) { ($us / 1000.0).ToString('0.###',[System.Globalization.CultureInfo]::InvariantCulture) + 'ms' } else { $us.ToString('0.###',[System.Globalization.CultureInfo]::InvariantCulture) + 'µs' }
            return "$timeText @ $rate irq/s"
        }
        'AquantiaITR' {
            function Format-AquantiaITRPart([uint32]$regValue, [string]$prefix) {
                if ($regValue -eq 0) { return "${prefix}:Off" }
                $mode = $regValue -band 0x3
                $minUnits = ($regValue -shr 8) -band 0x1FF
                $maxUnits = ($regValue -shr 16) -band 0x1FF
                $minUs = [uint64]$minUnits * 2
                $maxUs = [uint64]$maxUnits * 2
                if ($mode -eq 0) { return "${prefix}:Off raw=0x$($regValue.ToString('X8'))" }
                return "${prefix}:${minUs}-${maxUs}µs raw=0x$($regValue.ToString('X8'))"
            }
            $rxReg = [uint32]($rawValue -band [uint64]4294967295)
            $txReg = [uint32](($rawValue -shr 32) -band [uint64]4294967295)
            if ($rawValue -eq 0) { return "Rx:Off Tx:Off" }
            return "$(Format-AquantiaITRPart $rxReg 'Rx') $(Format-AquantiaITRPart $txReg 'Tx')"
        }
        'RealtekIntrMit' {
            $rxFrameUnits = $rawValue -band 0xF
            $rxTimeUnits = ($rawValue -shr 4) -band 0xF
            $txFrameUnits = ($rawValue -shr 8) -band 0xF
            $txTimeUnits = ($rawValue -shr 12) -band 0xF
            if ($rawValue -eq 0) { return "Off (disabled)" }
            return "$(Format-RealtekIntrMitEndpoint 'Rx' $rxTimeUnits $rxFrameUnits) $(Format-RealtekIntrMitEndpoint 'Tx' $txTimeUnits $txFrameUnits)"
        }
        'RealtekIntrMitV2' {
            $rxTimeUnits = $rawValue -band 0x7F
            $rxFrames = ($rawValue -shr 8) -band 0x3F
            $txTimeUnits = ($rawValue -shr 16) -band 0x7F
            $txFrames = ($rawValue -shr 24) -band 0x3F
            $isAdjacentRxOnly = $false
            if ($Index -ge 0 -and ($Index % 2) -ne 0) {
                $mode = if ($nicInfo.ContainsKey('PerIndexMaskMode')) { [string]$nicInfo.PerIndexMaskMode } else { '' }
                $isAdjacentRxOnly = ($mode -eq 'RealtekV2AlternatingIntMitiLow16' -or $mode -eq 'RealtekV2AlternatingFullLow16')
            }
            if ($rawValue -eq 0) {
                if ($isAdjacentRxOnly) { return "Rx:Off (RX-only)" }
                return "Off (disabled)"
            }
            if ($isAdjacentRxOnly) { return "$(Format-RealtekIntrMitV2Endpoint 'Rx' $rxTimeUnits $rxFrames) RX-only" }
            return "$(Format-RealtekIntrMitV2Endpoint 'Rx' $rxTimeUnits $rxFrames) $(Format-RealtekIntrMitV2Endpoint 'Tx' $txTimeUnits $txFrames)"
        }
    }
    return ""
}

function Update-NIC-IMOD-TimeLabel {
    param(
        [System.Windows.Forms.TextBox]$textBox,
        [System.Windows.Forms.Label]$label,
        [hashtable]$nicInfo
    )
    if ($null -eq $nicInfo -or $null -eq $label) { return }

    $parsed = $null
    $valueCount = 0
    try {
        $parsed = Parse-NICIMODInput -text $textBox.Text -nicInfo $nicInfo
        if ($null -ne $parsed.PerQueueValues -and $parsed.PerQueueValues.Count -gt 0) {
            $labels = @(Get-NICIMODVectorLabels $nicInfo)
            $segments = [System.Collections.Generic.List[string]]::new()
            for ($i = 0; $i -lt $parsed.PerQueueValues.Count; $i++) {
                $rawSourceLabel = if ($i -lt $labels.Count) { [string]$labels[$i] } else { "Q$($i)" }
                $sourceLabel = Get-NICIMODCompactVectorLabel -nicInfo $nicInfo -Index $i -Label $rawSourceLabel
                $displayVal = [uint64]$parsed.PerQueueValues[$i] -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index $i)
                [void]$segments.Add("${sourceLabel}:$(Convert-NICIMODToTimeString $displayVal $nicInfo -Index $i)")
            }
            $valueCount = [int]$parsed.PerQueueValues.Count
            $label.Text = ($segments -join " | ")
        } elseif ($null -ne $parsed.UniformValue) {
            $displayVal = [uint64]$parsed.UniformValue -band (Get-NICIMODValueMask -nicInfo $nicInfo -Index 0)
            $label.Text = Convert-NICIMODToTimeString $displayVal $nicInfo
            $valueCount = 1
        } else {
            $label.Text = ""
        }
    } catch {
        $rawText = if ($null -ne $textBox) { [string]$textBox.Text } else { '' }
        if (-not [string]::IsNullOrWhiteSpace($rawText) -and $rawText -ne '0x') {
            $familyName = if ($nicInfo.ContainsKey('FamilyName')) { [string]$nicInfo.FamilyName } elseif ($nicInfo.ContainsKey('Family')) { [string]$nicInfo.Family } else { '<unknown>' }
            Write-NICITRDiagnostic -Level Error -Message ('NIC ITR time-label parse/render failed. family={0}; inputLen={1}; inputPreview={2}' -f $familyName, $rawText.Length, ($rawText.Substring(0, [Math]::Min(160, $rawText.Length)))) -Exception $_
            $label.Text = 'ERR: NIC ITR time label failed - see console'
        } else {
            $label.Text = ''
        }
    }

    try {
        Sync-ScrollableLabelIfNeeded -label $label
    } catch {
        try {
            $geo = [DeviceEditorBuilder]::DescribeScrollableLabel($label)
            Write-NICITRDiagnostic -Level Error -Message ('NIC ITR time-label scroll sync failed. values={0}; labelTextLen={1}; geometry={2}' -f $valueCount, ([string]$label.Text).Length, $geo) -Exception $_
        } catch {
            Write-NICITRDiagnostic -Level Error -Message ('NIC ITR time-label scroll sync failed and geometry collection also failed.') -Exception $_
        }
    }

    try {
        $labelTextLen = ([string]$label.Text).Length
        if ($valueCount -gt 8 -or $labelTextLen -gt 2048) {
            $geo = [DeviceEditorBuilder]::DescribeScrollableLabel($label)
            Write-NICITRDiagnostic -Level Info -Message ('NIC ITR time-label updated. values={0}; labelTextLen={1}; geometry={2}' -f $valueCount, $labelTextLen, $geo)
        }
    } catch { }
}


$_dtScriptBootstrapSw = [System.Diagnostics.Stopwatch]::StartNew()

$script:DisableLogs        = $false
$script:DisableRWEnNVMe    = [bool]$script:DisableRWEnNVMe
$script:randomCPPCRatings = $false
$script:doubleccddebug   = $false
$script:ecoresdebug      = $false
$script:debugECoreIndices = @()
$script:simulate32cores   = $false
$script:simulate32logical16physical = $false
$script:SwitchRealHyperThreadStatus = $false
$script:forceNDIS         = $false
$script:forceNetAdapterCx = $false
$script:CLINdisAffinityMode = $null
$script:autoNdisAffinityMode = 'RSS'
$script:secretNdisAffinityMode = 'RSS'

$script:cachedCmdLineFlagSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach ($_deviceTweakerArg in [Environment]::GetCommandLineArgs()) {
    if ($null -eq $_deviceTweakerArg) { continue }
    $_deviceTweakerArgText = [string]$_deviceTweakerArg
    $_deviceTweakerArgTextLength = $_deviceTweakerArgText.Length
    if ($_deviceTweakerArgTextLength -le 0) { continue }

    $_deviceTweakerArgHadPrefix = $false
    $_deviceTweakerArgScanStart = 0
    if ($_deviceTweakerArgTextLength -gt 1 -and ($_deviceTweakerArgText[0] -eq '-' -or $_deviceTweakerArgText[0] -eq '/')) {
        $_deviceTweakerArgHadPrefix = $true
        $_deviceTweakerArgScanStart = 1
    }

    $_deviceTweakerArgEqualsIndex = if ($_deviceTweakerArgScanStart -lt $_deviceTweakerArgTextLength) { $_deviceTweakerArgText.IndexOf('=', $_deviceTweakerArgScanStart) } else { -1 }
    if ($_deviceTweakerArgEqualsIndex -ge 0) {
        $_deviceTweakerArgNameLength = $_deviceTweakerArgEqualsIndex - $_deviceTweakerArgScanStart
        if ($_deviceTweakerArgNameLength -gt 0 -and [string]::Equals($_deviceTweakerArgText.Substring($_deviceTweakerArgEqualsIndex + 1), 'true', [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$script:cachedCmdLineFlagSet.Add($_deviceTweakerArgText.Substring($_deviceTweakerArgScanStart, $_deviceTweakerArgNameLength))
        }
