function Get-DeviceIRQCounts {
    if ($script:cachedIrqAllocationsComplete) {
        $allocations = @($script:cachedIrqAllocations)
    } elseif ($script:cachedIrqAllocations) {
        $allocations = @($script:cachedIrqAllocations)
    } else {
        $allocations = @(Get-CimInstance -ClassName Win32_PnPAllocatedResource -ErrorAction SilentlyContinue)
        $script:cachedIrqAllocations = @($allocations)
        $script:cachedIrqAllocationsComplete = $true
    }
    $irqInfo = @{}

    foreach ($allocation in $allocations) {
        try {
            if ($null -ne $allocation -and $null -ne $allocation.PSObject.Properties['DependentDeviceId']) {
                if (-not [string]::Equals([string]$allocation.ResourceClass, 'Win32_IRQResource', [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                $deviceId = [string]$allocation.DependentDeviceId
                if ([string]::IsNullOrWhiteSpace($deviceId) -or $deviceId -match 'ACPI') { continue }
                $formattedId = Get-PNPId $deviceId
                if ([string]::IsNullOrWhiteSpace([string]$formattedId)) { continue }
                if (-not $irqInfo.ContainsKey($formattedId)) {
                    $irqInfo[$formattedId] = @{
                        Count = 0
                        IrqNumbers = [System.Collections.Generic.List[long]]::new()
                        MsiStatus = "Unknown"
                    }
                }
                $irqNumber = [long]$allocation.IrqNumber
                $entry = $irqInfo[$formattedId]
                $entry.Count++
                $entry.IrqNumbers.Add($irqNumber)
                if ($irqNumber -gt 999) { $entry.MsiStatus = "Enabled" }
                elseif ($entry.MsiStatus -eq "Unknown") { $entry.MsiStatus = "Disabled" }
                continue
            }

            $device = $allocation.Dependent
            if ($null -eq $device) { continue }

            $deviceId = $null
            if ($null -ne $device.DeviceID) {
                $deviceId = $device.DeviceID
            }
            if (-not $deviceId -and $device -is [string]) {
                if ($device -match 'DeviceID="([^"]+)"') {
                    $deviceId = $matches[1] -replace '\\\\', '\'
                }
            }
            if (-not $deviceId) { continue }
            if ($deviceId -match 'ACPI') { continue }

            $formattedId = Get-PNPId $deviceId
            if ([string]::IsNullOrWhiteSpace([string]$formattedId)) { continue }

            if (-not $irqInfo.ContainsKey($formattedId)) {
                $irqInfo[$formattedId] = @{
                    Count = 0
                    IrqNumbers = [System.Collections.Generic.List[long]]::new()
                    MsiStatus = "Unknown"
                }
            }

            $resource = $allocation.Antecedent
            if ($null -ne $resource -and $resource.CimClass.CimClassName -eq 'Win32_IRQResource') {
                $irqNumber = $resource.IRQNumber
                $entry = $irqInfo[$formattedId]
                $entry.Count++
                $entry.IrqNumbers.Add($irqNumber)

                if ($irqNumber -gt 999) {
                    $entry.MsiStatus = "Enabled"
                }
                elseif ($entry.MsiStatus -eq "Unknown") {
                    $entry.MsiStatus = "Disabled"
                }
            }
        }
        catch {
            Write-Warning "Error processing allocation: $_"
        }
    }

    return $irqInfo
}

function Create-ReservedCpuSetsUI {
    param(
        [int]$topPos
    )

    $script:reservedCheckboxes = @()
    $script:reservedCppcLabels = @()
    $script:reservedCpuGrid = $null

    Ensure-DeviceEditorNativeBuildContext

    $reservedState = [ReservedCpuSetsInitialState]::new()
    $reservedState.Metrics = $script:_deviceEditorNativeMetrics
    $reservedState.StartupModel = $script:StartupModel
    $reservedState.IsHeteroCpu = [bool]$script:isHeteroCpu
    $reservedState.IsDualCcdCpu = [bool]$script:IsDualCCDCpu

    $reservedBuild = [DeviceEditorBuilder]::BuildReservedCpuSetsSection(
        [int]$topPos,
        [int]$script:cachedLogicalCount,
        [int]$script:affGroupBoxWidth,
        [int]$script:affPanelWidth,
        $script:_deviceEditorNativeTheme,
        $reservedState
    )

    if ($null -eq $reservedBuild -or $null -eq $reservedBuild.Root) {
        return $topPos
    }

    $panel.Controls.Add($reservedBuild.Root)
    $script:reservedCpuGrid = $reservedBuild.Grid
    $script:reservedCheckboxes = if ($null -ne $reservedBuild.Cells) { $reservedBuild.Cells } else { @() }
    $script:reservedCppcLabels = if ($script:cppcEnabled -and $null -ne $script:reservedCpuGrid) { $script:reservedCpuGrid.AnnotationCells } else { @() }

    $reservedButtons = if ($null -ne $reservedBuild.Buttons) { $reservedBuild.Buttons } else { @() }
    $reservedButtonIndex = 0
    $btnSetReserved = if ($reservedButtons.Count -gt $reservedButtonIndex) { $reservedButtons[$reservedButtonIndex] } else { $null }
    $reservedButtonIndex++

    if ($null -ne $btnSetReserved) {
        $btnSetReserved.Add_Click({
            try {
                $logicalCount = [int]$script:cachedLogicalCount
                $bytes = if ($null -ne $script:reservedCpuGrid) {
                    [ReservedCpuSetsUiNative]::BuildReservedCpuSetsBytesFromGrid($script:reservedCpuGrid, $logicalCount)
                } else {
                    [ReservedCpuSetsUiNative]::BuildReservedCpuSetsBytesFromCells($script:reservedCheckboxes, $logicalCount)
                }
                if (-not [ReservedCpuSetsUiNative]::WriteReservedCpuSetsBytes($bytes, $script:StartupModel)) {
                    throw "Native ReservedCpuSets registry write returned false."
                }

                try {
                    $newReserved = [ReservedCpuSetsUiNative]::GetReservedCoresLocal($logicalCount, $script:StartupModel)
                } catch {
                    $newReserved = [bool[]]::new([Math]::Max(0, $logicalCount))
                }
                if ($null -ne $script:reservedCpuGrid) {
                    $script:reservedCpuGrid.SetCheckedFromBoolArray($newReserved)
                } else {
                    [ReservedCpuSetsUiNative]::SetCellsCheckedFromReservedArray($script:reservedCheckboxes, $newReserved)
                }
                [ReservedCpuSetsUiNative]::ApplyReservedColoring($deviceList, $deviceControls, $script:reservedCheckboxes, $newReserved, [bool]$script:IsDualCCDCpu, $script:Ccd0CoreSet, $script:Ccd1CoreSet, $script:_isPCoreLookup)

                Show-DarkMessageBox -Message "ReservedCpuSets updated successfully!" -Title "Success" -Icon Information
            }
            catch {
                Show-DarkMessageBox -Message "Failed to update ReservedCpuSets: $_" -Title "Error" -Icon Error
            }
        })
    }

    if ($script:isHeteroCpu) {
        $btnResECores = if ($reservedButtons.Count -gt $reservedButtonIndex) { $reservedButtons[$reservedButtonIndex] } else { $null }
        $reservedButtonIndex++
        $btnResPCores = if ($reservedButtons.Count -gt $reservedButtonIndex) { $reservedButtons[$reservedButtonIndex] } else { $null }
        $reservedButtonIndex++

        if ($null -ne $btnResECores) {
            $btnResECores.Add_Click({
                $grid = $script:reservedCpuGrid
                try {
                    try { if ($grid) { $grid.SuspendLayout() } } catch { }
                    if ($grid -is [CpuAffinityGrid]) {
                        $grid.SetCheckedFromPcoreLookup([bool[]]$script:_isPCoreLookup, $false)
                    } else {
                        foreach ($chk in $script:reservedCheckboxes) {
                            $coreNum = [int]$chk.Tag
                            $chk.Checked = (-not $script:_isPCoreLookup[$coreNum])
                        }
                    }
                }
                finally {
                    try { if ($grid) { $grid.ResumeLayout($false) } } catch { }
                }
            })
        }

        if ($null -ne $btnResPCores) {
            $btnResPCores.Add_Click({
                $grid = $script:reservedCpuGrid
                try {
                    try { if ($grid) { $grid.SuspendLayout() } } catch { }
                    if ($grid -is [CpuAffinityGrid]) {
                        $grid.SetCheckedFromPcoreLookup([bool[]]$script:_isPCoreLookup, $true)
                    } else {
                        foreach ($chk in $script:reservedCheckboxes) {
                            $coreNum = [int]$chk.Tag
                            $chk.Checked = $script:_isPCoreLookup[$coreNum]
                        }
                    }
                }
                finally {
                    try { if ($grid) { $grid.ResumeLayout($false) } } catch { }
                }
            })
        }
    }

    if ($script:IsDualCCDCpu) {
        $btnResCCD0 = if ($reservedButtons.Count -gt $reservedButtonIndex) { $reservedButtons[$reservedButtonIndex] } else { $null }
        $reservedButtonIndex++
        $btnResCCD1 = if ($reservedButtons.Count -gt $reservedButtonIndex) { $reservedButtons[$reservedButtonIndex] } else { $null }
        $reservedButtonIndex++

        if ($null -ne $btnResCCD0) {
            $btnResCCD0.Add_Click({
                $grid = $script:reservedCpuGrid
                $ccdSet = $script:Ccd0CoreSet
                try {
                    try { if ($grid) { $grid.SuspendLayout() } } catch { }
                    if ($grid -is [CpuAffinityGrid]) {
                        $grid.SetCheckedFromCoreSet($ccdSet)
                    } else {
                        foreach ($chk in $script:reservedCheckboxes) {
                            $coreNum = [int]$chk.Tag
                            $chk.Checked = $ccdSet.Contains($coreNum)
                        }
                    }
                }
                finally {
                    try { if ($grid) { $grid.ResumeLayout($false) } } catch { }
                }
            })
        }

        if ($null -ne $btnResCCD1) {
            $btnResCCD1.Add_Click({
                $grid = $script:reservedCpuGrid
                $ccdSet = $script:Ccd1CoreSet
                try {
                    try { if ($grid) { $grid.SuspendLayout() } } catch { }
                    if ($grid -is [CpuAffinityGrid]) {
                        $grid.SetCheckedFromCoreSet($ccdSet)
                    } else {
                        foreach ($chk in $script:reservedCheckboxes) {
                            $coreNum = [int]$chk.Tag
                            $chk.Checked = $ccdSet.Contains($coreNum)
                        }
                    }
                }
                finally {
                    try { if ($grid) { $grid.ResumeLayout($false) } } catch { }
                }
            })
        }
    }

    return [int]$reservedBuild.FinalBottom
}

