function Get-CPPCCheckboxText {
    param([int]$cpuNumber)
    return "CPU $cpuNumber"
}

function Get-CPPCAnnotationText {
    param([int]$cpuNumber, [bool]$showRatings = $false)
    if (-not $script:cppcEnabled) { return "" }
    if ($showRatings -and $script:cppcRatings.ContainsKey($cpuNumber)) {
        return "R$($script:cppcRatings[$cpuNumber])"
    } elseif ($script:cppcRanks.ContainsKey($cpuNumber)) {
        return "#$($script:cppcRanks[$cpuNumber])"
    }
    return ""
}

function Get-PNPId($registryPath) {
    if ($null -eq $script:pnpIdCache) { $script:pnpIdCache = @{} }
    if ($null -eq $registryPath) { return $null }

    $cacheKey = [string]$registryPath
    if ([string]::IsNullOrWhiteSpace($cacheKey)) { return $null }

    if (-not $script:pnpIdCache.ContainsKey($cacheKey)) {
        $formattedId = $null
        try {
            if ('DeviceTweakerPathHelpers' -as [type]) {
                $formattedId = [DeviceTweakerPathHelpers]::ToPnpId($cacheKey)
            }
        } catch { $formattedId = $null }
        if ([string]::IsNullOrWhiteSpace([string]$formattedId)) { $formattedId = $cacheKey.Trim() }
        $script:pnpIdCache[$cacheKey] = [string]$formattedId
    }

    return $script:pnpIdCache[$cacheKey]
}

function Format-RegistryPathForDisplay($registryPath) {
    if ([string]::IsNullOrWhiteSpace([string]$registryPath)) { return "(N/A)" }
    $cacheKey = [string]$registryPath
    if (-not $script:formatPathCache.ContainsKey($cacheKey)) {
        $path = ConvertTo-DeviceTweakerCanonicalRegistryDisplayPath $cacheKey
        if ([string]::IsNullOrWhiteSpace([string]$path)) { $path = "(N/A)" }
        $script:formatPathCache[$cacheKey] = $path
    }
    return $script:formatPathCache[$cacheKey]
}

function Test-DeviceTweakerStorageDevice {
    param([AllowNull()][object]$Device)

    if ($null -eq $Device) { return $false }
    $category = if ($null -ne $Device.Category) { [string]$Device.Category } else { '' }
    $role = if ($null -ne $Device.Role) { [string]$Device.Role } else { '' }

    return (
        $role.Equals('Storage', [System.StringComparison]::OrdinalIgnoreCase) -or
        $category.Equals('SSD', [System.StringComparison]::OrdinalIgnoreCase) -or
        $category.Equals('HDD', [System.StringComparison]::OrdinalIgnoreCase)
    )
}

function Test-DeviceTweakerBackupCategoryMatch {
    param(
        [AllowNull()][object]$Device,
        [AllowNull()][object]$BackupDevice
    )

    if ($null -eq $Device -or $null -eq $BackupDevice) { return $false }
    $deviceCategory = if ($null -ne $Device.Category) { [string]$Device.Category } else { '' }
    $backupCategory = [string](Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('Category') -Default '')
    $backupRole = [string](Get-DeviceTweakerBackupValue -Object $BackupDevice -Names @('Role') -Default '')

    if ($deviceCategory.Equals($backupCategory, [System.StringComparison]::OrdinalIgnoreCase)) { return $true }

    if (Test-DeviceTweakerStorageDevice $Device) {
        if ($backupRole.Equals('Storage', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        if ($backupCategory.Equals('SSD', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
        if ($backupCategory.Equals('HDD', [System.StringComparison]::OrdinalIgnoreCase)) { return $true }
    }

    return $false
}

$script:ignoredDualSenseAudioNames = @(
    'Headset Microphone (Dualsense Wireless Controller)',
