$script:audioEndpointFormFactorPnpKey = '{1DA5D803-D492-4EDD-8C23-E0C0FFEE7F0E} 0'

function ConvertTo-DeviceTweakerAudioEndpointFormFactorValue {
    param([AllowNull()][object]$Value)

    if ($null -eq $Value) { return $null }

    if ($Value -is [byte[]]) {
        if ($Value.Count -ge 4) {
            try { return [uint32][System.BitConverter]::ToUInt32([byte[]]$Value, 0) } catch { return $null }
        }
        if ($Value.Count -gt 0) {
            try { return [uint32]$Value[0] } catch { return $null }
        }
        return $null
    }

    try { return [uint32]$Value } catch {}

    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return $null }

    switch -Exact ($text) {
        'RemoteNetworkDevice'           { return [uint32]0 }
        'Speakers'                      { return [uint32]1 }
        'LineLevel'                     { return [uint32]2 }
        'Headphones'                    { return [uint32]3 }
        'Microphone'                    { return [uint32]4 }
        'Headset'                       { return [uint32]5 }
        'Handset'                       { return [uint32]6 }
        'UnknownDigitalPassthrough'     { return [uint32]7 }
        'SPDIF'                         { return [uint32]8 }
        'HDMI'                          { return [uint32]9 }
        'DigitalAudioDisplayDevice'     { return [uint32]9 }
        'UnknownFormFactor'             { return [uint32]10 }
        'EndpointFormFactor_enum_count' { return [uint32]11 }
    }

    return $null
}

function Resolve-DeviceTweakerAudioEndpointFormFactorInfo {
    param(
        [AllowNull()][object]$Value,
        [AllowNull()][string]$Source
    )

    $num = ConvertTo-DeviceTweakerAudioEndpointFormFactorValue $Value
    $sourceText = if ([string]::IsNullOrWhiteSpace($Source)) { 'unavailable endpoint property' } else { ([string]$Source).Trim() }

    if ($null -eq $num) {
        $info = [DeviceTweakerAudioEndpointFormFactorInfo]::new()
        $info.AudioType = 'Audio'
        $info.FormFactorName = 'Unavailable'
        $info.FormFactorValue = $null
        $info.Source = $sourceText
        $info.Reason = 'PKEY_AudioEndpoint_FormFactor unavailable; display type defaulted to Audio'
        return $info
    }

    $ffName = 'UnknownFormFactor'
    $audioType = 'Audio'
    switch ([uint32]$num) {
        0  { $ffName = 'RemoteNetworkDevice';       $audioType = 'Remote Network Audio'; break }
        1  { $ffName = 'Speakers';                  $audioType = 'Speakers';             break }
        2  { $ffName = 'LineLevel';                 $audioType = 'Line Level';            break }
        3  { $ffName = 'Headphones';                $audioType = 'Headphones';            break }
        4  { $ffName = 'Microphone';                $audioType = 'Microphone';            break }
        5  { $ffName = 'Headset';                   $audioType = 'Headset';               break }
        6  { $ffName = 'Handset';                   $audioType = 'Handset';               break }
        7  { $ffName = 'UnknownDigitalPassthrough'; $audioType = 'Digital Passthrough';   break }
        8  { $ffName = 'SPDIF';                     $audioType = 'SPDIF';                 break }
        9  { $ffName = 'DigitalAudioDisplayDevice'; $audioType = 'Display Audio';         break }
        10 { $ffName = 'UnknownFormFactor';         $audioType = 'Audio';                 break }
        11 { $ffName = 'EndpointFormFactor_enum_count'; $audioType = 'Audio';             break }
        default { $ffName = "UnknownFormFactorValue_$num"; $audioType = 'Audio';          break }
    }

    $info = [DeviceTweakerAudioEndpointFormFactorInfo]::new()
    $info.AudioType = $audioType
    $info.FormFactorName = $ffName
    $info.FormFactorValue = [uint32]$num
    $info.Source = $sourceText
    $info.Reason = "PKEY_AudioEndpoint_FormFactor=$ffName ($num) from $sourceText"
    return $info
}


function Get-DeviceTweakerAudioEndpointGuidFromInstanceId {
    param([AllowNull()][string]$InstanceId)

    if ([string]::IsNullOrWhiteSpace($InstanceId)) { return $null }
    $open = $InstanceId.LastIndexOf('{')
    if ($open -lt 0) { return $null }
    $close = $InstanceId.IndexOf('}', $open)
    if ($close -le $open) { return $null }
    return $InstanceId.Substring($open, ($close - $open + 1))
}

function New-DeviceTweakerAudioEndpointFormFactorRecord {
    param(
        [uint32]$Value,
        [AllowNull()][string]$Source
    )

    return [DeviceTweakerAudioEndpointFormFactorRecord]::new([uint32]$Value, [string]$Source)
}

function Read-DeviceTweakerAudioEndpointFormFactorRegistryMap {
    param([AllowNull()][string[]]$EndpointIds)

    $map = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $missing = [System.Collections.Generic.List[string]]::new()
    if (-not $EndpointIds -or $EndpointIds.Count -eq 0) {
        return [DeviceTweakerAudioEndpointFormFactorRegistryMapResult]::new($map, [string[]]@())
    }

    $valueNames = @(
        '{1da5d803-d492-4edd-8c23-e0c0ffee7f0e},0',
        '{1DA5D803-D492-4EDD-8C23-E0C0FFEE7F0E},0'
    )

    $views = [System.Collections.Generic.List[Microsoft.Win32.RegistryView]]::new()
    if ([Environment]::Is64BitOperatingSystem) {
        [void]$views.Add([Microsoft.Win32.RegistryView]::Registry64)
    }
    [void]$views.Add([Microsoft.Win32.RegistryView]::Default)

    foreach ($view in $views) {
        $hklm = $null
        try {
            $hklm = [Microsoft.Win32.RegistryKey]::OpenBaseKey([Microsoft.Win32.RegistryHive]::LocalMachine, $view)
        } catch {
            continue
        }

        try {
            foreach ($iid in $EndpointIds) {
                if ([string]::IsNullOrWhiteSpace($iid) -or $map.ContainsKey($iid)) { continue }

                $guid = Get-DeviceTweakerAudioEndpointGuidFromInstanceId $iid
                if ([string]::IsNullOrWhiteSpace($guid)) { continue }

                foreach ($flow in @('Render','Capture')) {
                    $subPath = "SOFTWARE\Microsoft\Windows\CurrentVersion\MMDevices\Audio\$flow\$guid\Properties"
                    $key = $null
                    try {
                        $key = $hklm.OpenSubKey($subPath)
                        if ($null -eq $key) { continue }

                        foreach ($vn in $valueNames) {
                            $raw = $key.GetValue($vn, $null)
                            $value = ConvertTo-DeviceTweakerAudioEndpointFormFactorValue $raw
                            if ($null -ne $value) {
                                $map[$iid] = New-DeviceTweakerAudioEndpointFormFactorRecord -Value ([uint32]$value) -Source "HKLM:\$subPath\$vn"
                                break
                            }
                        }
                    } catch {
                    } finally {
                        if ($key) { try { $key.Close() } catch {} }
                    }

                    if ($map.ContainsKey($iid)) { break }
                }
            }
        } finally {
            if ($hklm) { try { $hklm.Close() } catch {} }
        }
    }

    foreach ($iid in $EndpointIds) {
        if ([string]::IsNullOrWhiteSpace($iid)) { continue }
        if (-not $map.ContainsKey($iid)) { $missing.Add($iid) }
    }

    return [DeviceTweakerAudioEndpointFormFactorRegistryMapResult]::new($map, [string[]]$missing.ToArray())
}

function Get-DeviceTweakerAudioEndpointFormFactorMapForEndpoints {
    param([AllowNull()][object[]]$AudioEndpoints)

    $ids = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($ep in @($AudioEndpoints)) {
        if ($null -eq $ep) { continue }
        $id = if ($null -ne $ep.InstanceId) { [string]$ep.InstanceId } else { $null }
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        if ($seen.Add($id)) { $ids.Add($id) }
    }
    if ($ids.Count -eq 0) { return @{} }

    if ($null -eq $script:audioEndpointFormFactorCache) { $script:audioEndpointFormFactorCache = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase) }

    $map = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $uncachedIds = [System.Collections.Generic.List[string]]::new()
    foreach ($id in $ids) {
        if ($script:audioEndpointFormFactorCache.ContainsKey($id)) {
            $map[$id] = $script:audioEndpointFormFactorCache[$id]
        } else {
            $uncachedIds.Add($id)
        }
    }

    if ($uncachedIds.Count -gt 0) {
        $registryResult = Read-DeviceTweakerAudioEndpointFormFactorRegistryMap -EndpointIds $uncachedIds.ToArray()
        if ($registryResult -and $registryResult.Map) {
            foreach ($key in @($registryResult.Map.Keys)) {
                $record = $registryResult.Map[$key]
                $map[$key] = $record
                $script:audioEndpointFormFactorCache[$key] = $record
            }
        }
    }

    return $map
}

function Start-DeviceTweakerAudioEndpointFormFactorQuery {
    param([AllowNull()][object[]]$AudioEndpoints)

    $ids = [System.Collections.Generic.List[string]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($ep in @($AudioEndpoints)) {
        if ($null -eq $ep) { continue }
        $id = if ($null -ne $ep.InstanceId) { [string]$ep.InstanceId } else { $null }
        if ([string]::IsNullOrWhiteSpace($id)) { continue }
        if ($seen.Add($id)) { $ids.Add($id) }
    }
    if ($ids.Count -eq 0) { return $null }

    if ($null -eq $script:audioEndpointFormFactorCache) { $script:audioEndpointFormFactorCache = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase) }

    $map = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $uncachedIds = [System.Collections.Generic.List[string]]::new()
    foreach ($id in $ids) {
        if ($script:audioEndpointFormFactorCache.ContainsKey($id)) {
            $map[$id] = $script:audioEndpointFormFactorCache[$id]
        } else {
            $uncachedIds.Add($id)
        }
    }

    if ($uncachedIds.Count -gt 0) {
        $registryResult = Read-DeviceTweakerAudioEndpointFormFactorRegistryMap -EndpointIds $uncachedIds.ToArray()
        if ($registryResult -and $registryResult.Map) {
            foreach ($key in @($registryResult.Map.Keys)) {
                $record = $registryResult.Map[$key]
                $map[$key] = $record
                $script:audioEndpointFormFactorCache[$key] = $record
            }
        }

        $remainingIds = [System.Collections.Generic.List[string]]::new()
        if ($registryResult -and $registryResult.Missing) {
            foreach ($id in @($registryResult.Missing)) {
                if (-not [string]::IsNullOrWhiteSpace($id) -and -not $map.ContainsKey($id)) { $remainingIds.Add($id) }
            }
        }
    } else {
        $remainingIds = [System.Collections.Generic.List[string]]::new()
    }

    $query = [DeviceTweakerAudioEndpointFormFactorQuery]::new()
    $query.PS = $null
    $query.Result = $null
    $query.EndpointCount = [int]$ids.Count
    $query.Map = $map
    $query.MissingCount = [int]$remainingIds.Count
    $query.Completed = $true
    return $query
}

function Receive-DeviceTweakerAudioEndpointFormFactorQuery {
    param(
        [AllowNull()][object]$Query,
        [int]$WaitMilliseconds = 8000
    )

    $map = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $Query) { return $map }

    if ($null -ne $Query.Map -and $Query.Map) {
        foreach ($key in @($Query.Map.Keys)) { $map[$key] = $Query.Map[$key] }
    }

    if ($null -ne $Query.Completed -and $Query.Completed) { return $map }
    if ($null -eq $Query.PS -or $null -eq $Query.Result) { return $map }

    $effectiveWait = $WaitMilliseconds
    if ($null -ne $Query.MissingCount -and $Query.MissingCount -gt 0) {
        if ($map.Count -gt 0) {
            $effectiveWait = [Math]::Min($WaitMilliseconds, 150)
        } else {
            $effectiveWait = [Math]::Min($WaitMilliseconds, 500)
        }
    }

    try {
        if (-not $Query.Result.IsCompleted -and $effectiveWait -gt 0) {
            [void]$Query.Result.AsyncWaitHandle.WaitOne($effectiveWait)
        }
        if ($Query.Result.IsCompleted) {
            $results = @($Query.PS.EndInvoke($Query.Result))
            if ($results.Count -gt 0 -and $results[0] -is [hashtable]) {
                foreach ($key in @($results[0].Keys)) {
                    $record = $results[0][$key]
                    $map[$key] = $record
                    try {
                        if ($null -eq $script:audioEndpointFormFactorCache) { $script:audioEndpointFormFactorCache = [System.Collections.Generic.Dictionary[string,DeviceTweakerAudioEndpointFormFactorRecord]]::new([System.StringComparer]::OrdinalIgnoreCase) }
                        $script:audioEndpointFormFactorCache[$key] = $record
                    } catch {}
                }
            }
        } else {
            try { $Query.PS.Stop() } catch {}
        }
    } catch {
    } finally {
        try { $Query.PS.Dispose() } catch {}
    }

    return $map
}

function Optimized-TestAudioDeviceParents {
    $startupPayload = Get-DeviceTweakerStartupModel
    if ($startupPayload -and $startupPayload.AudioEndpointParentRowsComplete) {
        return [AudioEndpointInfo[]]@($startupPayload.AudioEndpointParentRows)
    }

    if ($startupPayload -and $startupPayload.DiscoveryModel -and ('DeviceTweakerDiscovery' -as [type])) {
        try {
            $rows = [DeviceTweakerDiscovery]::BuildAudioEndpointParentRows($startupPayload.DiscoveryModel, [string[]]@($script:ignoredDualSenseAudioNames))
            if ($null -eq $rows) { return [AudioEndpointInfo[]]@() }

            try {
                if ($startupPayload.AudioEndpointParentRows) { $startupPayload.AudioEndpointParentRows.Clear() }
                foreach ($_row in @($rows)) { if ($_row) { [void]$startupPayload.AudioEndpointParentRows.Add($_row) } }
                $startupPayload.AudioEndpointParentRowsComplete = $true
                Set-DeviceTweakerStartupModelDerivedCaches -Model $startupPayload
            } catch {}

            return [AudioEndpointInfo[]]@($rows)
        } catch {
            try { Write-DeviceTweakerPerfFallbackLog "AudioEndpoint parent native fallback failed | Reason: $($_.Exception.Message)" } catch {}
        }
    }

    return [AudioEndpointInfo[]]@()
}

$audioParentsRaw = Measure-Function 'Optimized-TestAudioDeviceParents' { Optimized-TestAudioDeviceParents }
$script:audioParentsRaw = @($audioParentsRaw)

$_sw_audio_lookup = [System.Diagnostics.Stopwatch]::StartNew()
$audioLookup = @{}
$script:audioLookupDetails = [System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[DeviceTweakerAudioLookupDetail]]]::new([System.StringComparer]::OrdinalIgnoreCase)

foreach ($row in $audioParentsRaw) {
    if ($row.ControllerID) {
        if (-not $audioLookup.ContainsKey($row.ControllerID)) {
            $audioLookup[$row.ControllerID] = [System.Collections.Generic.List[string]]::new()
        }
        $audioLookup[$row.ControllerID].Add('Audio')

        if (-not $script:audioLookupDetails.ContainsKey($row.ControllerID)) {
            $script:audioLookupDetails[$row.ControllerID] = [System.Collections.Generic.List[DeviceTweakerAudioLookupDetail]]::new()
        }
        $rowFormFactorName = if ($null -ne $row.FormFactorName) { $row.FormFactorName } else { $null }
        $rowFormFactorValue = if ($null -ne $row.FormFactorValue) { $row.FormFactorValue } else { $null }
        $detail = [DeviceTweakerAudioLookupDetail]::new()
        $detail.AudioDevice = [string]$row.AudioDevice
        $detail.AudioType = [string]$row.AudioType
        $detail.UsbVidPid = [string]$row.UsbVidPid
        $detail.InstanceId = [string]$row.InstanceId
        $detail.FormFactorName = [string]$rowFormFactorName
        $detail.FormFactorValue = $rowFormFactorValue
        $detail.Reason = [string]$row.Reason
        $detail.ControllerID = [string]$row.ControllerID
        [void]$script:audioLookupDetails[$row.ControllerID].Add($detail)
    }
}
$_sw_audio_lookup.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'Audio-Lookup-Build' -Milliseconds $_sw_audio_lookup.Elapsed.TotalMilliseconds }

function Convert-DeviceTweakerInstanceIdToRegistryPath {
    param(
        [AllowNull()][object]$InstanceId,
        [switch]$Relative
    )

    if ([string]::IsNullOrWhiteSpace([string]$InstanceId)) { return $null }

    $id = Normalize-DeviceTweakerPathSeparators ([string]$InstanceId)
    $id = $id.Trim().TrimStart('\')
    if ([string]::IsNullOrWhiteSpace($id)) { return $null }

    $id = $id -replace "^(?i:Microsoft\.PowerShell\.Core\\Registry::)", ""
    $id = $id -replace "^(?i:Registry::)", ""
    $id = $id -replace "^(?i:HKLM:\\|HKLM\\|HKEY[_]?LOCAL[_]?MACHINE\\)", ""

    if ($id -match '^(?i:SYSTEM\\CurrentControlSet\\Enum\\)') {
        if ($Relative) { return $id }
        return "HKLM:\$id"
    }

    $relativePath = "SYSTEM\CurrentControlSet\Enum\$id"
    if ($Relative) { return $relativePath }
    return "HKLM:\$relativePath"
}

function Get-RelativeRegistryPath($fullPath) {
    if ([string]::IsNullOrWhiteSpace([string]$fullPath)) { return $null }
    $path = Normalize-DeviceTweakerPathSeparators $fullPath
    $path = $path -replace "^(?i:Microsoft\.PowerShell\.Core\\Registry::)", ""
    $path = $path -replace "^(?i:Registry::)", ""

    if ($path -match '^(?i:PNP:)') {
        $pnpInstanceId = $path -replace '^(?i:PNP:)',''
        return Convert-DeviceTweakerInstanceIdToRegistryPath -InstanceId $pnpInstanceId -Relative
    }

    $path = $path -replace "^(?i:HKLM:\\|HKLM\\|HKEY[_]?LOCAL[_]?MACHINE\\)", ""
    $path = $path.TrimStart('\')
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    return $path
}

function Get-RegistryInfo($deviceId) {
    $paths = @("HKLM:\SYSTEM\CurrentControlSet\Enum\$deviceId", "HKLM:\SYSTEM\ControlSet001\Enum\$deviceId")
    foreach ($path in $paths) {
        if (Test-Path $path) {
            try {
                $info = Get-ItemProperty -Path $path -ErrorAction Stop
                return @{ RegistryPath = $path; DeviceDesc = $info.DeviceDesc }
            }
            catch { continue }
        }
    }
    return @{ RegistryPath = "Not Found"; DeviceDesc = "Not Found" }
}

function Format-DeviceTweakerModelName {
    param([AllowNull()][object]$Name)

    $text = if ($null -eq $Name) { '' } else { [string]$Name }
    $text = $text.Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { return '' }
    if ($text -eq 'Not Found') { return '' }

    if ($text.IndexOf(';') -ge 0) {
        $parts = $text -split ';'
        $text = ([string]$parts[$parts.Count - 1]).Trim()
    }

    $text = $text -replace '^"|"$', ''
    $text = $text -replace '\s+', ' '
    return $text.Trim()
}

function New-DeviceTweakerTypedDisplayName {
    param(
        [string]$Base,
        [AllowNull()][object]$Model
    )

    $baseText = if ($null -eq $Base) { '' } else { ([string]$Base).Trim() }
    $modelText = Format-DeviceTweakerModelName $Model
    if ([string]::IsNullOrWhiteSpace($baseText)) { return $modelText }
    if ([string]::IsNullOrWhiteSpace($modelText)) { return $baseText }
    if ($baseText.IndexOf($modelText, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $baseText }

    return "$baseText - $modelText"
}

function Test-DeviceTweakerHdAudioOnly {
    param([AllowNull()][object[]]$Types)
    $clean = [System.Collections.Generic.List[string]]::new()
    foreach ($type in @($Types)) {
        if ($null -eq $type) { continue }
        $text = ([string]$type).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        $clean.Add($text)
    }
    return ($clean.Count -eq 1 -and [string]::Equals($clean[0], 'HD Audio', [System.StringComparison]::OrdinalIgnoreCase))
}

function New-DeviceTweakerAudioControllerDisplayName {
    param(
        [AllowNull()][object[]]$Roles,
        [AllowNull()][object]$Model
    )

    $roleSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($role in @($Roles)) {
        $roleText = if ($null -eq $role) { '' } else { ([string]$role).Trim() }
        if ([string]::IsNullOrWhiteSpace($roleText)) { continue }
        [void]$roleSet.Add($roleText)
    }

    $roleList = if ($roleSet.Count -gt 0) { @(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $roleSet) } else { @() }
    $baseText = if ($roleList.Count -gt 0) { 'Audio controller (' + ($roleList -join '/') + ')' } else { 'Audio controller' }
    $modelText = Format-DeviceTweakerModelName $Model

    if ([string]::IsNullOrWhiteSpace($modelText)) { return $baseText }
    if ($baseText.IndexOf($modelText, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $baseText }

    return "$baseText - $modelText"
}

function New-DeviceTweakerStorageDisplayName {
    param(
        [AllowNull()][string]$Category,
        [AllowNull()][string]$BusDisplay,
        [AllowNull()][object]$Model
    )

    $categoryText = if ([string]::IsNullOrWhiteSpace($Category)) { 'Storage' } else { ([string]$Category).Trim() }
    $busText      = if ([string]::IsNullOrWhiteSpace($BusDisplay)) { '' } else { ([string]$BusDisplay).Trim() }
    $modelText    = Format-DeviceTweakerModelName $Model

    $prefix = if ([string]::IsNullOrWhiteSpace($busText)) {
        $categoryText
    } else {
        "$categoryText [$busText]"
    }

    if ([string]::IsNullOrWhiteSpace($modelText)) { return $prefix }
    if ($prefix.IndexOf($modelText, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $prefix }

    return "$prefix - $modelText"
}

function Get-PciPortId($devicePath) {
    $parts = $devicePath -split '\\'
    if ($parts.Count -lt 3) { return $null }
    $lastPart = $parts[-1]
    $segments = $lastPart -split '&'
    if ($segments.Count -ge 3) {
        return "$($segments[0])&$($segments[1])&$($segments[2])"
    }
    return $null
}

function Is-GPU($deviceDesc) {
    return ($deviceDesc -match '(?i)(AMD|NVIDIA|Radeon|GeForce|Intel|Arc)')
}

function Optimized-GetStorageDevices {
    $doLog = -not $script:DisableLogs
    $logSb = $null
    $logFile = $null
    if ($doLog) {
        $logSb = [System.Text.StringBuilder]::new(2048)
        $logFile = $script:cachedLogFile
    }
    $ts = if ($doLog) { Get-Date } else { $null }

    $allPnp = Get-CachedPnpDevices

    $pnpToPhysDisk  = @{}
    $pnpToWin32Disk = @{}
    try {
        $physicalDisks = Get-CachedPhysicalDisks
        $physicalDiskList = @($physicalDisks)
        if ($doLog) {
            $ignoredUnspecifiedPhysicalDisks = @($script:cachedPhysicalDisksIgnoredUnspecified)
            Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Get-PhysicalDisk accepted $($physicalDiskList.Count) disk(s); ignored $($ignoredUnspecifiedPhysicalDisks.Count) disk(s) because MediaType returned Unspecified"
            foreach ($ignoredPd in $ignoredUnspecifiedPhysicalDisks) {
                Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "  PhysicalDisk IGNORED: $(Get-DeviceTweakerPhysicalDiskIdentityText -Disk $ignoredPd) MediaType='$($ignoredPd.MediaType)' BusType='$($ignoredPd.BusType)' Reason='Get-PhysicalDisk.MediaType returned Unspecified'"
            }
            foreach ($pd in $physicalDiskList) {
                Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "  PhysicalDisk: DeviceId='$($pd.DeviceId)' FriendlyName='$($pd.FriendlyName)' MediaType='$($pd.MediaType)' BusType='$($pd.BusType)'"
            }
        }

        $physDiskByNumber = @{}
        foreach ($pd in $physicalDiskList) {
            if (Test-DeviceTweakerPhysicalDiskMediaTypeUnspecified -MediaType $pd.MediaType) {
                if ($doLog) { Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "  PhysicalDisk IGNORED: $(Get-DeviceTweakerPhysicalDiskIdentityText -Disk $pd) MediaType='$($pd.MediaType)' BusType='$($pd.BusType)' Reason='Get-PhysicalDisk.MediaType returned Unspecified'" }
                continue
            }
            $physDiskByNumber[$pd.DeviceId] = $pd
        }

        $win32Disks = Get-CachedWin32DiskDrives
        $win32DiskList = @($win32Disks)
        if ($doLog) {
            Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Win32_DiskDrive returned $($win32DiskList.Count) disk(s) for correlation"
        }
        foreach ($wd in $win32DiskList) {
            $diskNum = $wd.Index.ToString()
            if ($physDiskByNumber.ContainsKey($diskNum) -and $wd.PNPDeviceID) {
                $pnpToPhysDisk[$wd.PNPDeviceID]  = $physDiskByNumber[$diskNum]
                $pnpToWin32Disk[$wd.PNPDeviceID] = $wd
                if ($doLog) {
                    Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "  Correlated: PNPDeviceID='$($wd.PNPDeviceID)' -> PhysicalDisk DeviceId='$diskNum' Win32Model='$($wd.Model)' MediaType='$($physDiskByNumber[$diskNum].MediaType)' BusType='$($physDiskByNumber[$diskNum].BusType)'"
                }
            }
        }
    } catch {
        if ($doLog) { try { Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: WARNING - Failed to build PhysicalDisk lookup: $_" } catch {} }
    }

    $parentMap = Get-DeviceTopologyParentMap
    if (-not $parentMap -or $parentMap.Count -eq 0) {
        $parentMap = @{}
        if ($doLog) {
            Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Native topology parent map is empty; cmdlet parent fallback skipped to keep topology discovery single-pass"
        }
    }

    $pciItems = Get-CachedPciDeviceProps
    $pciLookup = @{}
    foreach ($item in $pciItems) {
        $pciInstanceId = ($item.PSPath -split '\\Enum\\')[1]
        if ($pciInstanceId) { $pciLookup[$pciInstanceId] = $item }
    }

    $_storageMatchedCount = 0
    foreach ($diskPnpId in $pnpToPhysDisk.Keys) {
        $physDisk = $pnpToPhysDisk[$diskPnpId]
        $mediaType = $physDisk.MediaType.ToString()
        if (Test-DeviceTweakerPhysicalDiskMediaTypeUnspecified -MediaType $mediaType) {
            if ($doLog) { Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Ignored correlated disk PNPDeviceID='$diskPnpId' because Get-PhysicalDisk.MediaType returned Unspecified" }
            continue
        }
        $busType   = $physDisk.BusType.ToString()

        $category = switch ($mediaType) {
            'SSD'   { 'SSD' }
            'HDD'   { 'HDD' }
            default { $mediaType }
        }

        $busDisplay = switch ($busType) {
            'NVMe'  { 'NVMe' }
            'SATA'  { 'SATA' }
            'SAS'   { 'SAS' }
            'RAID'  { 'RAID' }
            'USB'   { 'USB' }
            'SCM'   { 'SCM' }
            default { $busType }
        }

        $win32Disk = if ($pnpToWin32Disk.ContainsKey($diskPnpId)) { $pnpToWin32Disk[$diskPnpId] } else { $null }
        $modelSource = if ($win32Disk -and -not [string]::IsNullOrWhiteSpace([string]$win32Disk.Model)) { $win32Disk.Model } else { $physDisk.FriendlyName }
        $displayName = New-DeviceTweakerStorageDisplayName -Category $category -BusDisplay $busDisplay -Model $modelSource

        $controllerPsPath = $null
        $controllerDesc   = $null
        $currentId = $diskPnpId
        for ($depth = 0; $depth -lt 8 -and $currentId; $depth++) {
            $parentId = $parentMap[$currentId]
            if (-not $parentId) {
                break
            }
            if (-not $parentId) { break }
            if ($parentId -like 'PCI\*') {
                $pciItem = $pciLookup[$parentId]
                if ($pciItem) {
                    $controllerPsPath = "HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Enum\$parentId"
                    $controllerDesc   = $pciItem.DeviceDesc
                } else {
                    $controllerQueryPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$parentId"
                    $controllerPsPath = "HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Enum\$parentId"
                    try {
                        $controllerProps = Get-ItemProperty -Path $controllerQueryPath -ErrorAction SilentlyContinue
                        if ($controllerProps -and $controllerProps.DeviceDesc) { $controllerDesc = $controllerProps.DeviceDesc }
                    } catch {}
                }
                break
            }
            $currentId = $parentId
        }

        if (-not $controllerPsPath) {
            $controllerPsPath = "HKEY_LOCAL_MACHINE\SYSTEM\CurrentControlSet\Enum\$diskPnpId"
            $controllerDesc   = $physDisk.FriendlyName
            if ($doLog) {
                Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: No PCI parent found for '$diskPnpId', using disk PNP path as fallback"
            }
        }

        $controllerPnpId = $null
        try { if (-not [string]::IsNullOrWhiteSpace([string]$controllerPsPath)) { $controllerPnpId = Get-PNPId $controllerPsPath } } catch { $controllerPnpId = $null }
        if ([string]::IsNullOrWhiteSpace([string]$controllerPnpId)) { $controllerPnpId = $diskPnpId }

        $diskNumForRow = -1
        try { if ($win32Disk -and $null -ne $win32Disk.Index) { $diskNumForRow = [int]$win32Disk.Index } } catch { $diskNumForRow = -1 }
        $physicalDrivePathForRow = if ($diskNumForRow -ge 0) { ('\\.\PhysicalDrive{0}' -f $diskNumForRow) } else { $null }

        if ($doLog) {
            Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Matched disk ControllerPNP='$controllerPnpId' DiskPNP='$diskPnpId' -> Win32Model='$($win32Disk.Model)' PhysicalDisk FriendlyName='$($physDisk.FriendlyName)' ModelSource='$modelSource' MediaType='$mediaType' BusType='$busType' -> DisplayName='$displayName' ControllerPath='$controllerPsPath'"
        }
        $_storageMatchedCount++

        [PSCustomObject]@{
            Category     = 'PCI'
            Role         = 'Storage'
            StorageType  = $category
            DisplayName  = $displayName
            RegistryPath       = $controllerPsPath
            Description        = $controllerDesc
            BusType            = $busDisplay
            PNPID              = $controllerPnpId
            DiskPNPID          = $diskPnpId
            DiskIndex          = [int]$diskNumForRow
            PhysicalDrivePath  = $physicalDrivePathForRow
        }
    }

    if ($doLog) {
        Append-DeviceTweakerFormattedLogEntry -StringBuilder $logSb -Timestamp $ts -Text "Optimized-GetStorageDevices: Summary -> StorageDevicesMatched=$_storageMatchedCount CorrelatedDisks=$($pnpToPhysDisk.Count)"
    }

    if ($doLog -and $logSb.Length -gt 0) {
        try { $script:_cachedStorageNativeDiscoveryLogText = $logSb.ToString() } catch {}
    }
}

if (-not (Test-Path Variable:script:cachedPciDeviceProps)) { $script:cachedPciDeviceProps = $null }
function Get-CachedPciDeviceProps {
    if ($null -eq $script:cachedPciDeviceProps) {
        try {
            $model = Get-DeviceTweakerDiscoveryModel
            if ($model -and $model.PciDevicesByPath) {
                $script:cachedPciDeviceProps = @(Convert-DeviceTweakerDiscoveryModelToPciDeviceProps -Model $model)
                try { if ($script:pciPropsRunspace) { $script:pciPropsRunspace.Dispose() } } catch {}
                $script:pciPropsRunspace = $null
                $script:pciPropsAsyncResult = $null
            }
        } catch {}

        if ($null -eq $script:cachedPciDeviceProps -and $script:pciPropsAsyncResult -and $script:pciPropsRunspace) {
            try {
                $asyncResults = @($script:pciPropsRunspace.EndInvoke($script:pciPropsAsyncResult))
                $script:cachedPciDeviceProps = $asyncResults
            } catch {
                $script:cachedPciDeviceProps = $null
            } finally {
                try { $script:pciPropsRunspace.Dispose() } catch {}
                $script:pciPropsRunspace = $null
                $script:pciPropsAsyncResult = $null
            }
        }
        if ($null -eq $script:cachedPciDeviceProps) {
            try {
                $script:cachedPciDeviceProps = @(Get-PciEnumPropsFast)
            } catch {
                $script:cachedPciDeviceProps = @()
            }
        }
    }
    return $script:cachedPciDeviceProps
}

$script:networkAdapterPciPathCache = @{}
function Find-NetworkAdapterPCI($device) {
    $devDesc = if ($device -and $null -ne $device.Description) { [string]$device.Description } else { '' }
    $configPath = if ($device -and $null -ne $device.ConfigPath) { [string]$device.ConfigPath } else { '' }
    $pnpIdProp = if ($device -and $null -ne $device.PNPID) { [string]$device.PNPID } else { '' }

    $cacheKeyParts = @($pnpIdProp, $configPath, $devDesc) | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) }
    $cacheKey = if ($cacheKeyParts.Count -gt 0) { $cacheKeyParts -join '|' } else { '<empty>' }
    if ($script:networkAdapterPciPathCache.ContainsKey($cacheKey)) {
        return $script:networkAdapterPciPathCache[$cacheKey]
    }

    $candidateIds = [System.Collections.Generic.List[string]]::new()
    foreach ($candidate in @($pnpIdProp, $configPath)) {
        if ([string]::IsNullOrWhiteSpace([string]$candidate)) { continue }
        $candidateText = [string]$candidate
        if ($candidateText -match '(?i)(PCI\\VEN_[^\s]+)') { $candidateText = $Matches[1] }
        elseif ($candidateText -match '(?i)Enum\\(.+)$') { $candidateText = $Matches[1] }
        $candidateText = $candidateText -replace '^Microsoft\.PowerShell\.Core\\Registry::', ''
        $candidateText = $candidateText -replace '^(HKLM:\\|HKEY_LOCAL_MACHINE\\)', ''
        $candidateText = $candidateText -replace '^SYSTEM\\CurrentControlSet\\Enum\\', ''
        $candidateText = $candidateText.Trim([char]'\')
        if (-not [string]::IsNullOrWhiteSpace($candidateText)) { $candidateIds.Add($candidateText) }
    }

    foreach ($candidateId in $candidateIds) {
        $candidateRegPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$candidateId"
        if (Test-Path $candidateRegPath) {
            $script:networkAdapterPciPathCache[$cacheKey] = $candidateRegPath
            return $candidateRegPath
        }
    }

    $found = $null
    $pciItems = Get-CachedPciDeviceProps
    foreach ($item in $pciItems) {
        $itemPath = [string]$item.PSPath
        foreach ($candidateId in $candidateIds) {
            if ([string]::IsNullOrWhiteSpace($candidateId)) { continue }
            if ($itemPath -match [regex]::Escape($candidateId)) {
                $found = $item.PSPath
                break
            }
        }
        if ($found) { break }
    }

    if (-not $found -and -not [string]::IsNullOrWhiteSpace($devDesc)) {
        foreach ($item in $pciItems) {
            $pciDesc = [string]$item.DeviceDesc
            if (($pciDesc -like "*$devDesc*") -or ($devDesc -like "*$pciDesc*")) {
                $found = $item.PSPath
                break
            }
        }
    }

    $script:networkAdapterPciPathCache[$cacheKey] = $found
    return $found
}

$script:deviceUiBuildState = $null
$script:RegistryStateByPath = $null
$script:DeviceUiBuildResolvedPathByKey = $null
$script:UiBuildRegistryBaseKeyCache = $null
$script:UiBuildRegistryChildKeyCache = $null
$script:UiBuildRegistryOpenedKeys = $null
function Get-DeviceUiBuildCacheKey {
    param([AllowNull()][object]$Device)

    if ($null -eq $Device) { return '<null-device>' }

    $category = if ($null -ne $Device.Category) { [string]$Device.Category } else { '' }
    $role = if ($null -ne $Device.Role) { [string]$Device.Role } else { '' }
    $registryPath = if ($null -ne $Device.RegistryPath) { [string]$Device.RegistryPath } else { '' }
    $configPath = if ($null -ne $Device.ConfigPath) { [string]$Device.ConfigPath } else { '' }
    $displayName = if ($null -ne $Device.DisplayName) { [string]$Device.DisplayName } else { '' }
    $usbHeader = if ($null -ne $Device.UsbHeaderTitle) { [string]$Device.UsbHeaderTitle } else { '' }

    return (($category, $role, $registryPath, $configPath, $displayName, $usbHeader) -join '|')
}

function Open-DeviceUiBuildRegistryBaseKey {
    param(
        [AllowNull()][string]$RelativePath,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][hashtable]$BaseKeyCache,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][System.Collections.IList]$OpenedKeys
    )

    if ([string]::IsNullOrWhiteSpace([string]$RelativePath)) { return $null }
    $cacheKey = [string]$RelativePath

    if ($BaseKeyCache.ContainsKey($cacheKey)) { return $BaseKeyCache[$cacheKey] }

    $snapshotState = Get-DeviceUiBuildRegistrySnapshotState -Path $null -RelativePath $cacheKey
    if ($null -ne $snapshotState) {
        if ($snapshotState.BaseKeyExists) {
            $key = [DeviceRegistryKeyStateView]::new($snapshotState, 'Base')
            $BaseKeyCache[$cacheKey] = $key
            return $key
        }
        $BaseKeyCache[$cacheKey] = $null
        return $null
    }

    $key = $null
    try {
        $key = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($cacheKey, $false)
    } catch {
        $key = $null
    }

    $BaseKeyCache[$cacheKey] = $key
    if ($null -ne $key) { [void]$OpenedKeys.Add($key) }
    return $key
}

function Open-DeviceUiBuildRegistryChildKey {
    param(
        [AllowNull()][string]$RelativePath,
        [Parameter(Mandatory=$true)][string]$SubkeySuffix,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][hashtable]$BaseKeyCache,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][hashtable]$ChildKeyCache,
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][System.Collections.IList]$OpenedKeys
    )

    if ([string]::IsNullOrWhiteSpace([string]$RelativePath)) { return $null }
    if ([string]::IsNullOrWhiteSpace([string]$SubkeySuffix)) { return $null }

    $relativePathText = [string]$RelativePath
    $suffixText = ([string]$SubkeySuffix).TrimStart('\')
    $cacheKey = "$relativePathText`n$suffixText"

    if ($ChildKeyCache.ContainsKey($cacheKey)) { return $ChildKeyCache[$cacheKey] }

    $snapshotState = Get-DeviceUiBuildRegistrySnapshotState -Path $null -RelativePath $relativePathText
    if ($null -ne $snapshotState) {
        $viewKind = $null
        $keyExists = $false
        if ($suffixText.Equals('Device Parameters\Interrupt Management\Affinity Policy', [System.StringComparison]::OrdinalIgnoreCase)) {
            $viewKind = 'AffinityPolicy'
            $keyExists = [bool]$snapshotState.AffinityPolicyKeyExists
        } elseif ($suffixText.Equals('Device Parameters\Interrupt Management\MessageSignaledInterruptProperties', [System.StringComparison]::OrdinalIgnoreCase)) {
            $viewKind = 'Msi'
            $keyExists = [bool]$snapshotState.MsiKeyExists
        }

        if ($viewKind) {
            if ($keyExists) {
                $key = [DeviceRegistryKeyStateView]::new($snapshotState, $viewKind)
                $ChildKeyCache[$cacheKey] = $key
                return $key
            }
            $ChildKeyCache[$cacheKey] = $null
            return $null
        }
    }

    $key = $null
    $baseKey = Open-DeviceUiBuildRegistryBaseKey -RelativePath $relativePathText -BaseKeyCache $BaseKeyCache -OpenedKeys $OpenedKeys
    if ($null -ne $baseKey) {
        try {
            $key = $baseKey.OpenSubKey($suffixText, $false)
        } catch {
            $key = $null
        }
    }

    $ChildKeyCache[$cacheKey] = $key
    if ($null -ne $key) { [void]$OpenedKeys.Add($key) }
    return $key
}

function Close-DeviceUiBuildRegistryKeys {
    param([AllowNull()][System.Collections.IList]$OpenedKeys)

    if ($null -eq $OpenedKeys) { return }
    for ($i = ($OpenedKeys.Count - 1); $i -ge 0; $i--) {
        $key = $OpenedKeys[$i]
        if ($null -ne $key) {
            try { $key.Close() } catch { }
        }
    }
}

function Get-DeviceUiBuildResolvedPaths {
    param([object]$Device)

    $deviceKey = Get-DeviceUiBuildCacheKey $Device
    if ($null -ne $script:DeviceUiBuildResolvedPathByKey -and $script:DeviceUiBuildResolvedPathByKey.ContainsKey($deviceKey)) {
        return $script:DeviceUiBuildResolvedPathByKey[$deviceKey]
    }

    $isNetwork = ($Device.Category -eq "Network")
    $isNDIS = ($isNetwork -and $Device.Role -eq "NDIS")
    $isNetAdapterCx = ($isNetwork -and $Device.Role -eq "NetAdapterCx")

    $affinityPath = if ($isNDIS) {
        $Device.RegistryPath
    } elseif ($isNetAdapterCx) {
        Get-NetworkAdapterAffinityRegistryPath $Device
    } else {
        $Device.RegistryPath
    }

    $msiPath = if ($isNetwork) { Get-NetworkAdapterMSIRegistryPath $Device } else { $Device.RegistryPath }

    $policyPath = if ($isNDIS) {
        if ($Device.ConfigPath) { $Device.ConfigPath } else { $Device.RegistryPath }
    } elseif ($isNetAdapterCx) {
        $affinityPath
    } else {
        $Device.RegistryPath
    }

    $pnpIdPath = if ($isNDIS -and $null -ne $Device.ConfigPath -and $Device.ConfigPath) {
        $Device.ConfigPath
    } elseif ($isNetwork) {
        $msiPath
    } else {
        $Device.RegistryPath
    }

    $resolved = [DeviceUiBuildResolvedPaths]::new()
    $resolved.IsNetwork = [bool]$isNetwork
    $resolved.IsNDIS = [bool]$isNDIS
    $resolved.IsNetAdapterCx = [bool]$isNetAdapterCx
    $resolved.AffinityPath = [string]$affinityPath
    $resolved.MsiPath = [string]$msiPath
    $resolved.PolicyPath = [string]$policyPath
    $resolved.PnpIdPath = [string]$pnpIdPath

    if ($null -ne $script:DeviceUiBuildResolvedPathByKey) { $script:DeviceUiBuildResolvedPathByKey[$deviceKey] = $resolved }
    return $resolved
}

function Add-DeviceUiBuildRegistryPathForSnapshot {
    param(
        [Parameter(Mandatory=$true)][AllowEmptyCollection()][System.Collections.Generic.List[string]]$RegistryPaths,
        [AllowNull()][string]$Path
    )

    if ([string]::IsNullOrWhiteSpace([string]$Path)) { return }
    [void]$RegistryPaths.Add([string]$Path)

    try {
        $relativePath = Get-RelativeRegistryPath $Path
        if (-not [string]::IsNullOrWhiteSpace([string]$relativePath)) { [void]$RegistryPaths.Add([string]$relativePath) }
    } catch { }
}

function Get-DeviceUiBuildRegistrySnapshotState {
    param(
        [AllowNull()][string]$Path,
        [AllowNull()][string]$RelativePath
    )

    $map = $script:RegistryStateByPath
    if ($null -eq $map) { return $null }

    foreach ($candidate in @($Path, $RelativePath)) {
        if ([string]::IsNullOrWhiteSpace([string]$candidate)) { continue }
        try {
            $candidateText = [string]$candidate
            if ($map.ContainsKey($candidateText)) { return $map[$candidateText] }
        } catch { }
    }

    return $null
}

function Get-DeviceUiBuildState {
    param([object]$device)

    if ($null -eq $script:deviceUiBuildState) { $script:deviceUiBuildState = [System.Collections.Generic.Dictionary[string,DeviceStartupUiState]]::new([System.StringComparer]::OrdinalIgnoreCase) }
    $deviceKey = Get-DeviceUiBuildCacheKey $device
    if ($script:deviceUiBuildState.ContainsKey($deviceKey)) {
        return $script:deviceUiBuildState[$deviceKey]
    }

    $resolvedPaths = Get-DeviceUiBuildResolvedPaths $device
    $isNetwork = [bool]$resolvedPaths.IsNetwork
    $isNDIS = [bool]$resolvedPaths.IsNDIS
    $isNetAdapterCx = [bool]$resolvedPaths.IsNetAdapterCx
    $affinityPath = $resolvedPaths.AffinityPath
    $msiPath = $resolvedPaths.MsiPath
    $policyPath = $resolvedPaths.PolicyPath
    $pnpIdPath = $resolvedPaths.PnpIdPath

    $pnpId = Get-PNPId $pnpIdPath

    $initialAffinity = '0x0'
    $ndisIrqAffinity = '0x0'
    $numQueues = $null
    $msiEnabled = 0
    $messageLimit = ''
    $priorityValue = 2
    $policyValue = 0

    $_readPolicy = $false
    $_readPriority = $false

    $affinityPolicySubkey = 'Device Parameters\Interrupt Management\Affinity Policy'
    $msiSubkey = 'Device Parameters\Interrupt Management\MessageSignaledInterruptProperties'

    $relAff = Get-RelativeRegistryPath $affinityPath
    $relMsi = Get-RelativeRegistryPath $msiPath
    $relPol = Get-RelativeRegistryPath $policyPath

    $baseKeyCache = $script:UiBuildRegistryBaseKeyCache
    $childKeyCache = $script:UiBuildRegistryChildKeyCache
    $openedKeys = $script:UiBuildRegistryOpenedKeys
    $useSharedRegistryCache = ($null -ne $baseKeyCache -and $null -ne $childKeyCache -and $null -ne $openedKeys)

    if ($null -eq $baseKeyCache) { $baseKeyCache = @{} }
    if ($null -eq $childKeyCache) { $childKeyCache = @{} }
    if ($null -eq $openedKeys) { $openedKeys = [System.Collections.ArrayList]::new() }

    try {
        if ($isNDIS) {
            if (-not [string]::IsNullOrWhiteSpace([string]$relAff)) {
                $rk = Open-DeviceUiBuildRegistryBaseKey -RelativePath $relAff -BaseKeyCache $baseKeyCache -OpenedKeys $openedKeys
                if ($rk) {
                    try {
                        $v = $rk.GetValue("*RssBaseProcNumber", $null)
                        if ($v -ne $null) { $initialAffinity = "0x" + ([int]$v).ToString("X") }
                        $qVal = $rk.GetValue("*NumRssQueues", $null)
                        if ($qVal -ne $null) { $numQueues = [Math]::Max(1, [int]$qVal) }
                    } catch { }
                }
            }

            if (-not [string]::IsNullOrWhiteSpace([string]$relPol)) {
                $rk = Open-DeviceUiBuildRegistryChildKey -RelativePath $relPol -SubkeySuffix $affinityPolicySubkey -BaseKeyCache $baseKeyCache -ChildKeyCache $childKeyCache -OpenedKeys $openedKeys
                if ($rk) {
                    try {
                        $asoVal = $rk.GetValue("AssignmentSetOverride", $null)
                        if ($asoVal -ne $null) {
                            $maskHex = Convert-DeviceTweakerRegistryAffinityValueToHex $asoVal
                            if (-not [string]::IsNullOrWhiteSpace([string]$maskHex)) { $ndisIrqAffinity = $maskHex }
                        }
                        $dpVal = $rk.GetValue("DevicePolicy", $null)
                        if ($dpVal -ne $null) { $policyValue = [int]$dpVal }
                    } catch { }
                }
                $_readPolicy = $true
            }
        } else {
            if (-not [string]::IsNullOrWhiteSpace([string]$relAff)) {
                $rk = Open-DeviceUiBuildRegistryChildKey -RelativePath $relAff -SubkeySuffix $affinityPolicySubkey -BaseKeyCache $baseKeyCache -ChildKeyCache $childKeyCache -OpenedKeys $openedKeys
                if ($rk) {
                    try {
                        $asoVal = $rk.GetValue("AssignmentSetOverride", $null)
                        if ($asoVal -ne $null) {
                            $maskHex = Convert-DeviceTweakerRegistryAffinityValueToHex $asoVal
                            if (-not [string]::IsNullOrWhiteSpace([string]$maskHex)) {
                                $initialAffinity = $maskHex
                            }
                        }
                        if ($policyPath -eq $affinityPath) {
                            $dpVal = $rk.GetValue("DevicePolicy", $null)
                            if ($dpVal -ne $null) { $policyValue = [int]$dpVal }
                            $_readPolicy = $true
                        }
                        if ($msiPath -eq $affinityPath) {
                            $priVal = $rk.GetValue("DevicePriority", $null)
                            if ($priVal -ne $null) { $priorityValue = [int]$priVal }
                            $_readPriority = $true
                        }
                    } catch { }
                }
            }
            $ndisIrqAffinity = $initialAffinity
        }

        if (-not [string]::IsNullOrWhiteSpace([string]$relMsi)) {
            $rk = Open-DeviceUiBuildRegistryChildKey -RelativePath $relMsi -SubkeySuffix $msiSubkey -BaseKeyCache $baseKeyCache -ChildKeyCache $childKeyCache -OpenedKeys $openedKeys
            if ($rk) {
                try {
                    $msiVal = $rk.GetValue("MSISupported", $null)
                    $mlVal = $rk.GetValue("MessageNumberLimit", $null)
                    if ($msiVal -ne $null) { $msiEnabled = [int]$msiVal }
                    if ($mlVal) { $messageLimit = $mlVal }
                } catch { }
            }

            if (-not $_readPriority) {
                $rk = Open-DeviceUiBuildRegistryChildKey -RelativePath $relMsi -SubkeySuffix $affinityPolicySubkey -BaseKeyCache $baseKeyCache -ChildKeyCache $childKeyCache -OpenedKeys $openedKeys
                if ($rk) {
                    try {
                        $priVal = $rk.GetValue("DevicePriority", $null)
                        if ($priVal -ne $null) { $priorityValue = [int]$priVal }
                        if (-not $_readPolicy -and $policyPath -eq $msiPath) {
                            $dpVal = $rk.GetValue("DevicePolicy", $null)
                            if ($dpVal -ne $null) { $policyValue = [int]$dpVal }
                            $_readPolicy = $true
                        }
                    } catch { }
                }
                $_readPriority = $true
            }
        }

        if (-not $_readPolicy) {
            if (-not [string]::IsNullOrWhiteSpace([string]$relPol)) {
                $rk = Open-DeviceUiBuildRegistryChildKey -RelativePath $relPol -SubkeySuffix $affinityPolicySubkey -BaseKeyCache $baseKeyCache -ChildKeyCache $childKeyCache -OpenedKeys $openedKeys
                if ($rk) {
                    try {
                        $dpVal = $rk.GetValue("DevicePolicy", $null)
                        if ($dpVal -ne $null) { $policyValue = [int]$dpVal }
                    } catch { }
                }
            }
        }
    } finally {
        if (-not $useSharedRegistryCache) {
            Close-DeviceUiBuildRegistryKeys -OpenedKeys $openedKeys
        }
    }

    $state = [DeviceStartupUiState]::new()
    $state.DeviceKey = [string]$deviceKey
    $state.AffinityPath = [string]$affinityPath
    $state.MsiPath = [string]$msiPath
    $state.PolicyPath = [string]$policyPath
    $state.PnpId = [string]$pnpId
    $state.InitialAffinity = [string]$initialAffinity
    $state.MsiEnabled = [int]$msiEnabled
    $state.MessageLimit = $messageLimit
    $state.Priority = [int]$priorityValue
    $state.Policy = [int]$policyValue
    $state.NumQueues = $numQueues
    $state.NdisIrqAffinity = [string]$ndisIrqAffinity

    $script:deviceUiBuildState[$deviceKey] = $state
    return $state
}


function Complete-DeviceTweakerStartupModel {
    param(
        [AllowNull()][object]$Model,
        [AllowNull()][object]$Devices,
        [AllowNull()][object]$StorageRows,
        [AllowNull()][object]$NetworkRows,
        [AllowNull()][object]$DeviceAddressMap,
        [AllowNull()][object]$IrqAllocations
    )

    if ($null -eq $Model) { return }
    $_completeSw = [System.Diagnostics.Stopwatch]::StartNew()

    try {
        if ($Model.CpuTopology) {
            try { $Model.CpuTopology.CppcRatings.Clear() } catch { }
            try { $Model.CpuTopology.CppcRanks.Clear() } catch { }
            try {
                foreach ($k in @($script:cppcRatings.Keys)) {
                    $ki = [int]$k
                    $Model.CpuTopology.CppcRatings[$ki] = [int]$script:cppcRatings[$k]
                }
            } catch { }
            try {
                foreach ($k in @($script:cppcRanks.Keys)) {
                    $ki = [int]$k
                    $Model.CpuTopology.CppcRanks[$ki] = [int]$script:cppcRanks[$k]
                }
            } catch { }
            try { $Model.CpuTopology.CppcEnabled = [bool]$script:cppcEnabled } catch { }
        }
    } catch { }

    try { $Model.AllDeviceRows.Clear() } catch { }
    try { $Model.StorageRows.Clear() } catch { }
    try { $Model.NetworkAdapterRows.Clear() } catch { }
    try { $Model.UsbControllerRows.Clear() } catch { }
    try { $Model.PciGpuRows.Clear() } catch { }
    try { $Model.PciAudioRows.Clear() } catch { }
    try { $Model.DisplayStringsByDeviceKey.Clear() } catch { }

    foreach ($dev in @($Devices)) {
        if ($null -eq $dev) { continue }
        try { [void]$Model.AllDeviceRows.Add($dev) } catch { }
        try {
            $key = Get-DeviceUiBuildCacheKey $dev
            $display = if ($null -ne $dev.DisplayName) { [string]$dev.DisplayName } elseif ($null -ne $dev.Description) { [string]$dev.Description } else { [string]$key }
            if (-not [string]::IsNullOrWhiteSpace([string]$key)) { $Model.DisplayStringsByDeviceKey[$key] = $display }
        } catch { }
        try {
            if ($dev -is [UsbDeviceInfo]) { [void]$Model.UsbControllerRows.Add($dev) }
            elseif ($dev -is [PciDeviceInfo] -and $dev.Role -eq 'GPU') { [void]$Model.PciGpuRows.Add($dev) }
            elseif ($dev -is [PciDeviceInfo] -and ($dev.Role -eq 'Audio' -or $dev.Role -eq 'AudioGPU')) { [void]$Model.PciAudioRows.Add($dev) }
        } catch { }
    }

    foreach ($row in @($StorageRows)) {
        if ($null -eq $row) { continue }
        try { [void]$Model.StorageRows.Add($row) } catch { }
    }

    foreach ($row in @($NetworkRows)) {
        if ($null -eq $row) { continue }
        try { [void]$Model.NetworkAdapterRows.Add($row) } catch { }
    }

    try { $Model.DeviceAddressByPnpId.Clear() } catch { }
    if ($DeviceAddressMap -is [hashtable]) {
        foreach ($k in @($DeviceAddressMap.Keys)) {
            try {
                if ($null -eq $k) { continue }
                $Model.DeviceAddressByPnpId[[string]$k] = [uint64]$DeviceAddressMap[$k]
            } catch { }
        }
    }

    try { $Model.IrqAllocationRows.Clear() } catch { }
    foreach ($row in @($IrqAllocations)) {
        if ($null -eq $row) { continue }
        try { [void]$Model.IrqAllocationRows.Add($row) } catch { }
    }

    $_completeSw.Stop()
    try { $Model.CompletedBuildMilliseconds = $_completeSw.Elapsed.TotalMilliseconds } catch { }
}

function Prepare-DeviceUiBuildCache {
    param([object[]]$Devices)

    $script:deviceUiBuildState = [System.Collections.Generic.Dictionary[string,DeviceStartupUiState]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $script:RegistryStateByPath = $null
    $script:DeviceUiBuildResolvedPathByKey = [System.Collections.Generic.Dictionary[string,DeviceUiBuildResolvedPaths]]::new([System.StringComparer]::OrdinalIgnoreCase)

    $registryPaths = [System.Collections.Generic.List[string]]::new()
    foreach ($dev in @($Devices)) {
        if ($null -eq $dev) { continue }
        $resolvedPaths = Get-DeviceUiBuildResolvedPaths $dev
        Add-DeviceUiBuildRegistryPathForSnapshot -RegistryPaths $registryPaths -Path $resolvedPaths.AffinityPath
        Add-DeviceUiBuildRegistryPathForSnapshot -RegistryPaths $registryPaths -Path $resolvedPaths.MsiPath
        Add-DeviceUiBuildRegistryPathForSnapshot -RegistryPaths $registryPaths -Path $resolvedPaths.PolicyPath
    }

    try {
        if ($script:StartupModel -and $script:StartupModel.RegistryStateByPath -and $script:StartupModel.RegistryStateByPath.Count -gt 0) {
            $script:RegistryStateByPath = $script:StartupModel.RegistryStateByPath
        } elseif ($registryPaths.Count -gt 0 -and ('DeviceTweakerRegistrySnapshot' -as [type])) {
            $script:RegistryStateByPath = [DeviceTweakerRegistrySnapshot]::ReadDeviceRegistryStates($registryPaths)
        }
    } catch {
        $script:RegistryStateByPath = $null
    }

    $script:UiBuildRegistryBaseKeyCache = @{}
    $script:UiBuildRegistryChildKeyCache = @{}
    $script:UiBuildRegistryOpenedKeys = [System.Collections.ArrayList]::new()

    try {
        foreach ($dev in @($Devices)) {
            if ($null -ne $dev) { [void](Get-DeviceUiBuildState $dev) }
        }
        try {
            if ($null -ne $script:StartupModel) {
                if ($null -ne $script:RegistryStateByPath) { $script:StartupModel.RegistryStateByPath = $script:RegistryStateByPath }
                if ($null -ne $script:deviceUiBuildState) {
                    try { $script:StartupModel.UiStateByDeviceKey.Clear() } catch { }
                    foreach ($k in @($script:deviceUiBuildState.Keys)) {
                        try { $script:StartupModel.UiStateByDeviceKey[[string]$k] = $script:deviceUiBuildState[$k] } catch { }
                    }
                }
            }
        } catch { }
    } finally {
        Close-DeviceUiBuildRegistryKeys -OpenedKeys $script:UiBuildRegistryOpenedKeys
        $script:UiBuildRegistryBaseKeyCache = $null
        $script:UiBuildRegistryChildKeyCache = $null
        $script:UiBuildRegistryOpenedKeys = $null
        $script:RegistryStateByPath = $null
        $script:DeviceUiBuildResolvedPathByKey = $null
    }
}

function Get-NetworkAdapterMSIRegistryPath($device) {
    if ($device.Category -eq "Network") {
         $pciKey = Find-NetworkAdapterPCI $device
         if ($pciKey -ne $null) { return $pciKey }
         if ($device.Role -eq "NDIS" -and
             $null -ne $device.ConfigPath -and
             $device.ConfigPath) {
             return $device.ConfigPath
         }
    }
    return $device.RegistryPath
}

function Get-NetworkAdapterAffinityRegistryPath($device) {
    if ($device.Category -eq "Network" -and $device.Role -eq "NDIS") {
        return $device.RegistryPath
    }
    elseif ($device.Category -eq "Network" -and $device.Role -eq "NetAdapterCx") {
        if ($device.ConfigPath) {
            return $device.ConfigPath
        } else {
            return $device.RegistryPath
        }
    }
    else {
        return $device.RegistryPath
    }
}

function Get-AffinityHexForCore($assignmentCore, $logicalCores) {
    return ('{0:X16}' -f (ConvertTo-ExovanceAffinityMask @([int]$assignmentCore)))
}

function ConvertTo-DeviceTweakerAffinityUInt64([AllowNull()][object]$affinityHex) {
    $hex = ([string]$affinityHex).Trim()
    if ([string]::IsNullOrWhiteSpace($hex)) { return [uint64]0 }
    if ($hex.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) { $hex = $hex.Substring(2) }
    if ([string]::IsNullOrWhiteSpace($hex)) { return [uint64]0 }
    try { return [Convert]::ToUInt64($hex, 16) } catch { return [uint64]0 }
}

function Calculate-AffinityHex($checkboxes) {
    if ($checkboxes -and $checkboxes.Count -gt 0 -and $checkboxes[0] -is [CpuAffinityGridCell]) {
        return "0x" + $checkboxes[0].Owner.Mask.ToString("X")
    }

    $mask = [uint64]0
    foreach ($chk in $checkboxes) {
        if ($chk.Checked) {
            $coreNum = [int]$chk.Tag
            if ($coreNum -ge 0 -and $coreNum -lt 64) { $mask = $mask -bor ([uint64]1 -shl $coreNum) }
        }
    }
    return "0x" + $mask.ToString("X")
}

function Set-CheckboxesFromAffinity($checkboxes, $affinityHex) {
    $maskInt = ConvertTo-DeviceTweakerAffinityUInt64 $affinityHex
    if ($checkboxes -and $checkboxes.Count -gt 0 -and $checkboxes[0] -is [CpuAffinityGridCell]) {
        $checkboxes[0].Owner.Mask = $maskInt
        return
    }

    foreach ($chk in $checkboxes) {
        $core = [int]$chk.Tag
        if ($core -ge 0 -and $core -lt 64 -and (($maskInt -band ([uint64]1 -shl $core)) -ne 0)) { $chk.Checked = $true } else { $chk.Checked = $false }
    }
}

function Get-CurrentAffinity {
    param(
        [AllowNull()][string]$registryPath,
        [bool]$isNDIS,
        [switch]$PreserveAbsence
    )

    $fallback = if ($PreserveAbsence) { $null } else { "0x0" }
    if ([string]::IsNullOrWhiteSpace([string]$registryPath)) { return $fallback }
    if ($isNDIS) {
        $state = Get-DeviceTweakerRegistryValueState -RegistryPath $registryPath -SubkeySuffix $null -ValueName '*RssBaseProcNumber'
        if ($state.Present) { return "0x" + ([int]$state.Value).ToString("X") }
        return $fallback
    } else {
        $state = Get-DeviceTweakerRegistryValueState -RegistryPath $registryPath -SubkeySuffix 'Device Parameters\Interrupt Management\Affinity Policy' -ValueName 'AssignmentSetOverride'
        if ($state.Present) {
            $maskHex = Convert-DeviceTweakerRegistryAffinityValueToHex $state.Value
            if (-not [string]::IsNullOrWhiteSpace([string]$maskHex)) { return $maskHex }
        }
        return $fallback
    }
}

function Convert-AffinityMaskToCores {
    param([string]$AffinityMask)

    if ([string]::IsNullOrWhiteSpace($AffinityMask)) { return @() }

    $maskText = $AffinityMask.Trim()
    if ($maskText.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
        $maskText = $maskText.Substring(2)
    }

    [uint64]$maskInt64 = 0
    try { $maskInt64 = [Convert]::ToUInt64($maskText, 16) } catch { return @() }

    $cores = [System.Collections.Generic.List[int]]::new()
    for ($b = 0; $b -lt 64; $b++) {
        if ($maskInt64 -band ([uint64]1 -shl $b)) { $cores.Add($b) }
    }
    return @($cores)
}

function Merge-AssignedGpuCoresIntoOccupiedList {
    param(
        [array]$GpuDevices,
        [hashtable]$AssignedMap,
        [object[]]$CurrentOccupiedCores
    )

    $merged = [System.Collections.Generic.List[int]]::new()
    foreach ($core in @($CurrentOccupiedCores)) {
        if ($null -ne $core -and "$core" -ne '') { $merged.Add([int]$core) }
    }

    foreach ($gpu in @($GpuDevices)) {
        if ($null -eq $gpu) { continue }

        $gpuCores = @()

        if ($AssignedMap -and $AssignedMap.ContainsKey($gpu)) {
            $gpuCores = @($AssignedMap[$gpu])
        }

        if ($gpuCores.Count -eq 0 -and $gpu.RegistryPath) {
            $gpuCores = Convert-AffinityMaskToCores (Get-CurrentAffinity $gpu.RegistryPath $false)
        }

        foreach ($core in @($gpuCores)) {
            if ($null -ne $core -and "$core" -ne '') { [void]$merged.Add([int]$core) }
        }
    }

    return @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $merged)
}


function Get-CurrentNumRssQueues {
    param([string]$registryPath)

    $relativePath = Get-RelativeRegistryPath $registryPath
    if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { return $null }
    try {
        $regKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($relativePath, $false)
        if ($regKey -ne $null) {
            $val = $regKey.GetValue("*NumRssQueues", $null)
            if ($null -ne $val) {
                return [int]$val
            }
        }
        return $null
    }
    catch {
        return $null
    }
}

function Get-CurrentPriority {
    param(
        [AllowNull()][string]$registryPath,
        [switch]$PreserveAbsence
    )

    $state = Get-DeviceTweakerRegistryValueState -RegistryPath $registryPath -SubkeySuffix 'Device Parameters\Interrupt Management\Affinity Policy' -ValueName 'DevicePriority'
    if ($state.Present) { return [int]$state.Value }
    if ($PreserveAbsence) { return $null }
    return 2
}

function Set-DevicePriority($registryPath, $priority) {
    $failureDetail = 'registry operation failed (no writable key returned).'
    try {
        $relativePath = Get-RelativeRegistryPath $registryPath
        if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Set-DevicePriority' 'Set-DevicePriority: registry operation failed.'; return $false }
        $targetSubkey = "$relativePath\Device Parameters\Interrupt Management\Affinity Policy"
        $regKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($targetSubkey, [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
        if ($regKey -ne $null) {
            $regKey.SetValue("DevicePriority", [int]$priority, [Microsoft.Win32.RegistryValueKind]::DWord)
            $regKey.Close()
            try { Write-ExovanceSettingAccepted -DevicePath $registryPath -Setting 'DevicePriority' -Value $priority } catch { }; return $true
        }
    } catch { $failureDetail = $_.Exception.Message }
    Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Set-DevicePriority' ('Set-DevicePriority: '+$failureDetail); return $false
}

function Get-CurrentMSI {
    param(
        [AllowNull()][string]$registryPath,
        [switch]$PreserveAbsence
    )

    $msiSubkey = 'Device Parameters\Interrupt Management\MessageSignaledInterruptProperties'
    $msiState = Get-DeviceTweakerRegistryValueState -RegistryPath $registryPath -SubkeySuffix $msiSubkey -ValueName 'MSISupported'
    $limitState = Get-DeviceTweakerRegistryValueState -RegistryPath $registryPath -SubkeySuffix $msiSubkey -ValueName 'MessageNumberLimit'

    $msi = if ($msiState.Present) { $msiState.Value } elseif ($PreserveAbsence) { $null } else { 0 }
    $msgLimit = if ($limitState.Present) { $limitState.Value } elseif ($PreserveAbsence) { $null } else { "" }
    return @{ MSIEnabled = $msi; MessageLimit = $msgLimit }
}

function Set-DeviceMSI($registryPath, $msiEnabled, $msgLimit) {
    $failureDetail = 'registry operation failed (no writable key returned).'
    $relativePath = Get-RelativeRegistryPath $registryPath
    if ([string]::IsNullOrWhiteSpace([string]$relativePath)) { Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Set-DeviceMSI' 'Set-DeviceMSI: registry operation failed.'; return $false }
    $subkeySuffix = 'Device Parameters\Interrupt Management\MessageSignaledInterruptProperties'
    $subkeyPath = "$relativePath\$subkeySuffix"
    try {
        if (Test-DeviceTweakerNullLike $msiEnabled) {
            Remove-DeviceTweakerRegistryValue -RegistryPath $registryPath -SubkeySuffix $subkeySuffix -ValueName 'MSISupported' | Out-Null
            if (Test-DeviceTweakerNullLike $msgLimit) {
                Remove-DeviceTweakerRegistryValue -RegistryPath $registryPath -SubkeySuffix $subkeySuffix -ValueName 'MessageNumberLimit' | Out-Null
            }
            try { Write-ExovanceSettingAccepted -DevicePath $registryPath -Setting 'MSI / MessageNumberLimit' -Value ([string]$msiEnabled+'; limit='+$(if(Test-DeviceTweakerNullLike $msgLimit){'<удалить / не задано>'}else{[string]$msgLimit})) } catch { }; return $true
        }

        $regKey = [Microsoft.Win32.Registry]::LocalMachine.CreateSubKey($subkeyPath, [Microsoft.Win32.RegistryKeyPermissionCheck]::ReadWriteSubTree)
        if ($regKey -ne $null) {
            $regKey.SetValue("MSISupported", [int]$msiEnabled, [Microsoft.Win32.RegistryValueKind]::DWord)
            if ((Test-DeviceTweakerNullLike $msgLimit) -or $msgLimit -eq "" -or $msgLimit -eq "Unlimited" -or ([int]$msgLimit) -eq 0) {
                if ($regKey.GetValue("MessageNumberLimit", $null) -ne $null) {
                    $regKey.DeleteValue("MessageNumberLimit", $false)
                }
            }
            else {
                $regKey.SetValue("MessageNumberLimit", [int]$msgLimit, [Microsoft.Win32.RegistryValueKind]::DWord)
            }
            $regKey.Close()
            try { Write-ExovanceSettingAccepted -DevicePath $registryPath -Setting 'MSI / MessageNumberLimit' -Value ([string]$msiEnabled+'; limit='+$(if(Test-DeviceTweakerNullLike $msgLimit){'<удалить / не задано>'}else{[string]$msgLimit})) } catch { }; return $true
        }
    } catch { $failureDetail = $_.Exception.Message }
    Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Set-DeviceMSI' ('Set-DeviceMSI: '+$failureDetail); return $false
}

function Set-DeviceAffinity($registryPath, $affinityHex) {
    try {
        [uint64]$mask = Convert-DeviceTweakerAffinityMaskToUInt64 $affinityHex
        if ($mask -eq 0) { return (Clear-DeviceAffinity $registryPath) }
        Assert-ExovanceAffinityMask -Mask $mask -LogicalCount $script:cachedLogicalCount
        $path = $registryPath.TrimEnd('\') + '\Device Parameters\Interrupt Management\Affinity Policy'
        $bytes = [BitConverter]::GetBytes($mask)
        if (-not [BitConverter]::IsLittleEndian) { [array]::Reverse($bytes) }
        Set-ExovanceRegistryValue -RegistryPath $path -Name 'AssignmentSetOverride' -Value $bytes -Kind Binary
        Set-ExovanceRegistryValue -RegistryPath $path -Name 'DevicePolicy' -Value 4 -Kind DWord
        try { Write-ExovanceSettingAccepted -DevicePath $registryPath -Setting 'AssignmentSetOverride / DevicePolicy=4' -Value ('0x'+$mask.ToString('X')) } catch { }; return $true
    } catch { Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Set-DeviceAffinity' ('IRQ affinity: ' + $_.Exception.Message); return $false }
}

function Clear-DeviceAffinity($registryPath) {
    try {
        $path = $registryPath.TrimEnd('\') + '\Device Parameters\Interrupt Management\Affinity Policy'
        Set-ExovanceRegistryState -RegistryPath $path -State ([pscustomobject]@{Name='AssignmentSetOverride'; Present=$false})
        Set-ExovanceRegistryValue -RegistryPath $path -Name 'DevicePolicy' -Value 0 -Kind DWord
        try { Write-ExovanceSettingAccepted -DevicePath $registryPath -Setting 'AssignmentSetOverride удалён / DevicePolicy=0' -Value $null } catch { }; return $true
    } catch { Add-ExovanceWriteFailure -DevicePath $registryPath -Setting 'Clear-DeviceAffinity' ('IRQ affinity reset: ' + $_.Exception.Message); return $false }
}

function Get-HIDDevicesWithUSBControllers {
    $startupPayload = Get-DeviceTweakerStartupModel
    if ($null -eq $startupPayload) {
        $startupPayload = [DeviceTweakerStartupPayload]::new()
    }

    try {
        if ($null -eq $startupPayload.DiscoveryModel) {
            $startupPayload.DiscoveryModel = Get-DeviceTweakerDiscoveryModel
        }
    } catch {}

    $opts = [DeviceTweakerStartupOptions]::new()
    try { $opts.IncludeLogs = (-not [bool]$script:DisableLogs) } catch {}
    try { $opts.IgnoredAudioNames = [string[]]@($script:ignoredDualSenseAudioNames) } catch {}

    try {
        $nativeResult = [DeviceTweakerDiscovery]::BuildUsbDiscovery($startupPayload, $opts)

        try { $script:_cachedUsbNativeDiscoveryLogs = @($nativeResult.Logs) } catch { $script:_cachedUsbNativeDiscoveryLogs = @() }
        try { $script:_cachedUsbNativeUnusedCpuControllers = @($nativeResult.UnusedCpuControllers) } catch { $script:_cachedUsbNativeUnusedCpuControllers = @() }
        try {
            if ($nativeResult.AudioDetails) {
                Set-DeviceTweakerAudioLookupFromDetails -AudioDetails $nativeResult.AudioDetails
            }
        } catch {}

        $rows = @()
        try {
            if ($startupPayload.HidRows) { $rows = @($startupPayload.HidRows) }
        } catch { $rows = @() }
        $script:_cachedHidDevices = $rows
        return $rows
    } catch {
        Write-DeviceTweakerPerfFallbackLog "Get-HIDDevicesWithUSBControllers: native BuildUsbDiscovery failed | Reason: $($_.Exception.Message)"
        $script:_cachedHidDevices = @()
        return @()
    }
}

function Get-CachedBIntervalData {
    if ($null -ne $script:cachedBIntervalResult) { return $script:cachedBIntervalResult }
    try {
        $snap = Get-CachedDeviceTopologySnapshot
        if ($snap -and $snap.UsbEnumeration) {
            $script:cachedBIntervalResult = $snap.UsbEnumeration
            return $script:cachedBIntervalResult
        }
    } catch {
        Write-Host "[bInterval] WARNING: Native topology USB enumeration failed: $_" -ForegroundColor Yellow
        Write-DeviceTweakerPerfFallbackLog "Get-USBControllers: native topology bInterval enumeration failed; polling-rate labels unavailable | Reason: $($_.Exception.Message)"
    }
    if ($script:bIntervalAsyncResult -and $script:bIntervalRunspace) {
        try {
            $results = @($script:bIntervalRunspace.EndInvoke($script:bIntervalAsyncResult))
            $script:cachedBIntervalResult = if ($results.Count -gt 0) { $results[0] } else { $null }
        } catch {
            Write-Host "[bInterval] WARNING: Background USB enumeration failed: $_" -ForegroundColor Yellow
            Write-DeviceTweakerPerfFallbackLog "Get-USBControllers: bInterval background USB enumeration failed; polling-rate labels unavailable | Reason: $($_.Exception.Message)"
            $script:cachedBIntervalResult = $null
        } finally {
            try { $script:bIntervalRunspace.Dispose() } catch {}
            $script:bIntervalRunspace = $null
            $script:bIntervalAsyncResult = $null
        }
    }
    return $script:cachedBIntervalResult
}

