function Build-HidUsbPollingInfoLookup {
    param([object]$UsbEnumResult)
    try { return [DeviceTweakerPathHelpers]::BuildHidUsbPollingInfoLookup($UsbEnumResult) } catch {
        return [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    }
}

function ConvertTo-DeviceTweakerUsbHidInfoList {
    param([AllowNull()][object]$HidDevices)

    $list = [System.Collections.Generic.List[UsbHidDeviceInfo]]::new()
    foreach ($device in @($HidDevices)) {
        if ($null -eq $device) { continue }
        $info = [UsbHidDeviceInfo]::new()
        $info.ProductString = Get-DeviceTweakerFastStringPropertyValue $device 'ProductString'
        $info.DeviceInstanceID = Get-DeviceTweakerFastStringPropertyValue $device 'DeviceInstanceID'
        $info.DeviceType = Get-DeviceTweakerFastStringPropertyValue $device 'DeviceType'
        $info.ClassificationReason = Get-DeviceTweakerFastStringPropertyValue $device 'ClassificationReason'
        try {
            foreach ($controller in @($device.USBControllers)) {
                if ($null -eq $controller) { continue }
                $ctrlId = Get-DeviceTweakerFastStringPropertyValue $controller 'ControllerPNPID'
                if (-not [string]::IsNullOrWhiteSpace($ctrlId)) { [void]$info.USBControllerPNPIDs.Add($ctrlId) }
            }
        } catch {}
        [void]$list.Add($info)
    }
    return $list
}

function ConvertTo-DeviceTweakerAudioEndpointInfoList {
    param([AllowNull()][object]$AudioRowsOrMap)

    $list = [System.Collections.Generic.List[AudioEndpointInfo]]::new()
    $addRow = {
        param([AllowNull()][object]$Row, [AllowNull()][string]$ControllerKey)
        if ($null -eq $Row) { return }
        $info = [AudioEndpointInfo]::new()
        $info.AudioDevice = Get-DeviceTweakerFastStringPropertyValue $Row 'AudioDevice'
        $info.AudioType = Get-DeviceTweakerFastStringPropertyValue $Row 'AudioType'
        $info.ControllerID = Get-DeviceTweakerFastStringPropertyValue $Row 'ControllerID'
        if ([string]::IsNullOrWhiteSpace($info.ControllerID) -and -not [string]::IsNullOrWhiteSpace($ControllerKey)) { $info.ControllerID = $ControllerKey }
        $info.UsbVidPid = Get-DeviceTweakerFastStringPropertyValue $Row 'UsbVidPid'
        $info.InstanceId = Get-DeviceTweakerFastStringPropertyValue $Row 'InstanceId'
        $info.FormFactorName = Get-DeviceTweakerFastStringPropertyValue $Row 'FormFactorName'
        try {
            $ffv = $null
            if ($Row.PSObject.Properties['FormFactorValue']) { $ffv = $Row.FormFactorValue }
            if ($null -ne $ffv) { $info.FormFactorValue = [uint32]$ffv }
        } catch {}
        $info.Reason = Get-DeviceTweakerFastStringPropertyValue $Row 'Reason'
        [void]$list.Add($info)
    }

    if ($AudioRowsOrMap -is [System.Collections.IDictionary]) {
        foreach ($entry in $AudioRowsOrMap.GetEnumerator()) {
            $key = if ($null -ne $entry.Key) { [string]$entry.Key } else { $null }
            foreach ($row in @($entry.Value)) { & $addRow $row $key }
        }
    } else {
        foreach ($row in @($AudioRowsOrMap)) { & $addRow $row $null }
    }

    return $list
}

function ConvertFrom-DeviceTweakerAudioEndpointInfoListToMap {
    param([AllowNull()][object]$AudioDetails)

    $map = [System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[DeviceTweakerAudioLookupDetail]]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($detail in @($AudioDetails)) {
        if ($null -eq $detail -or [string]::IsNullOrWhiteSpace([string]$detail.ControllerID)) { continue }
        $key = [string]$detail.ControllerID
        if (-not $map.ContainsKey($key)) { $map[$key] = [System.Collections.Generic.List[DeviceTweakerAudioLookupDetail]]::new() }
        $row = [DeviceTweakerAudioLookupDetail]::new()
        $row.AudioDevice = [string]$detail.AudioDevice
        $row.AudioType = [string]$detail.AudioType
        $row.UsbVidPid = [string]$detail.UsbVidPid
        $row.InstanceId = [string]$detail.InstanceId
        $row.FormFactorName = [string]$detail.FormFactorName
        $row.FormFactorValue = $detail.FormFactorValue
        $row.Reason = [string]$detail.Reason
        $row.ControllerID = [string]$detail.ControllerID
        [void]$map[$key].Add($row)
    }
    return $map
}

function Set-DeviceTweakerAudioLookupFromDetails {
    param([AllowNull()][object]$AudioDetails)

    $script:audioLookupDetails = ConvertFrom-DeviceTweakerAudioEndpointInfoListToMap -AudioDetails $AudioDetails
    $script:audioLookup = @{}
    foreach ($detail in @($AudioDetails)) {
        if ($null -eq $detail -or [string]::IsNullOrWhiteSpace([string]$detail.ControllerID)) { continue }
        $atype = if ($null -ne $detail.AudioType) { ([string]$detail.AudioType).Trim() } else { '' }
        if ([string]::IsNullOrWhiteSpace($atype)) { continue }
        $key = [string]$detail.ControllerID
        if (-not $script:audioLookup.ContainsKey($key)) { $script:audioLookup[$key] = [System.Collections.Generic.List[string]]::new() }
        [void]$script:audioLookup[$key].Add($atype)
    }
}

function ConvertFrom-DeviceTweakerUsbDeviceInfoList {
    param([AllowNull()][object]$Records)

    if ($null -eq $Records) { return @() }
    try { return $Records.ToArray() } catch { return @($Records) }
}

function ConvertFrom-DeviceTweakerPciDeviceInfoList {
    param([AllowNull()][object]$Records)

    if ($null -eq $Records) { return @() }
    try { return $Records.ToArray() } catch { return @($Records) }
}

function Add-DeviceTweakerNativeDiscoveryLogs {
    param(
        [AllowNull()][object]$Lines,
        [AllowNull()][object]$Buffer,
        [AllowNull()][object]$Timestamp
    )

    if ($script:DisableLogs -or $null -eq $Buffer) { return }

    if ($null -eq $Timestamp) {
        $Timestamp = Get-Date
    } elseif (-not ($Timestamp -is [datetime])) {
        try { $Timestamp = [datetime]$Timestamp } catch { $Timestamp = Get-Date }
    }

    foreach ($line in @($Lines)) {
        if ($null -eq $line) { continue }
        Add-DeviceTweakerFormattedLogEntry -Buffer $Buffer -Timestamp ([datetime]$Timestamp) -Text ([string]$line)
    }
}


function Write-DeviceTweakerUnusedCpuUsbControllerWarnings {
    param([AllowNull()][object]$Controllers)

    foreach ($cEntry in @($Controllers)) {
        if ([string]::IsNullOrWhiteSpace([string]$cEntry)) { continue }
        Write-Host "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] Unused CPU USB Controller detected -> $cEntry" -ForegroundColor Yellow
    }
}

function Get-USBControllersNative {

    $startupPayload = Get-DeviceTweakerStartupModel
    if ($startupPayload -and $startupPayload.UsbRowsComplete) {
        try { if ($startupPayload.HidRows) { $script:_cachedHidDevices = @($startupPayload.HidRows) } else { $script:_cachedHidDevices = @() } } catch { $script:_cachedHidDevices = @() }
        try { if ($startupPayload.UsbSourceLogs) { $script:_cachedUsbNativeDiscoveryLogs = @($startupPayload.UsbSourceLogs) } else { $script:_cachedUsbNativeDiscoveryLogs = @() } } catch { $script:_cachedUsbNativeDiscoveryLogs = @() }
        try { if ($startupPayload.UsbUnusedCpuControllers) { $script:_cachedUsbNativeUnusedCpuControllers = @($startupPayload.UsbUnusedCpuControllers) } else { $script:_cachedUsbNativeUnusedCpuControllers = @() } } catch { $script:_cachedUsbNativeUnusedCpuControllers = @() }
        if (-not $script:_cachedUsbNativeUnusedCpuControllers -or @($script:_cachedUsbNativeUnusedCpuControllers).Count -eq 0) {
            try {
                $unusedControllers = [System.Collections.Generic.List[string]]::new()
                foreach ($_startupLogLine in @($startupPayload.UsbSourceLogs)) {
                    if ([string]$_startupLogLine -match "Unused CPU USB Controller detected.*Controller='([^']+)'") { [void]$unusedControllers.Add([string]$Matches[1]) }
                }
                $script:_cachedUsbNativeUnusedCpuControllers = $unusedControllers.ToArray()
            } catch { $script:_cachedUsbNativeUnusedCpuControllers = @() }
        }
        Write-DeviceTweakerUnusedCpuUsbControllerWarnings -Controllers $script:_cachedUsbNativeUnusedCpuControllers
        try { if ($startupPayload.UsbAudioEndpointRows -and $startupPayload.UsbAudioEndpointRows.Count -gt 0) { Set-DeviceTweakerAudioLookupFromDetails -AudioDetails @($startupPayload.UsbAudioEndpointRows) } } catch {}
        return @($startupPayload.UsbControllerRows)
    }

    $discoveryModel = Get-DeviceTweakerDiscoveryModel
    if ($null -eq $startupPayload) {
        $startupPayload = [DeviceTweakerStartupPayload]::new()
    }
    try { if ($null -eq $startupPayload.DiscoveryModel) { $startupPayload.DiscoveryModel = $discoveryModel } } catch {}

    $opts = [DeviceTweakerStartupOptions]::new()
    try { $opts.IncludeLogs = (-not [bool]$script:DisableLogs) } catch {}
    try { $opts.IgnoredAudioNames = [string[]]@($script:ignoredDualSenseAudioNames) } catch {}

    try {
        $nativeResult = [DeviceTweakerDiscovery]::BuildUsbDiscovery($startupPayload, $opts)
    } catch {
        throw "DeviceTweakerDiscovery.BuildUsbDiscovery failed: $($_.Exception.Message)"
    }

    try { if ($startupPayload.HidRows) { $script:_cachedHidDevices = @($startupPayload.HidRows) } else { $script:_cachedHidDevices = @() } } catch { $script:_cachedHidDevices = @() }
    try { $script:_cachedUsbNativeDiscoveryLogs = @($nativeResult.Logs) } catch { $script:_cachedUsbNativeDiscoveryLogs = @() }
    try { $script:_cachedUsbNativeUnusedCpuControllers = @($nativeResult.UnusedCpuControllers) } catch { $script:_cachedUsbNativeUnusedCpuControllers = @() }

    Set-DeviceTweakerAudioLookupFromDetails -AudioDetails $nativeResult.AudioDetails

    Write-DeviceTweakerUnusedCpuUsbControllerWarnings -Controllers $nativeResult.UnusedCpuControllers

    if ($null -eq $nativeResult -or $null -eq $nativeResult.Devices) { return @() }
    return $nativeResult.Devices.ToArray()
}

function Get-USBControllers {
    $discoveryModel = Get-DeviceTweakerDiscoveryModel
    $assocData = Get-CachedUSBControllerAssocData
    $parsedPairs = $assocData.Pairs
    if ($null -eq $parsedPairs) { $parsedPairs = [System.Collections.Generic.List[object]]::new() }
    $instanceIdSet = $assocData.InstanceIds
    if ($null -eq $instanceIdSet) { $instanceIdSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase) }

    $pnpCache = @{}
    $allCachedDevices = Get-CachedPnpDevices
    $deviceLookup = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($d in $allCachedDevices) {
        if ($d.InstanceId) { $deviceLookup[$d.InstanceId] = $d }
    }

    $regEnumRoot = $null
    try { $regEnumRoot = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey('SYSTEM\CurrentControlSet\Enum') } catch {}
    foreach ($id in $instanceIdSet) {
        if ($deviceLookup.ContainsKey($id)) {
            $device = $deviceLookup[$id]
            $friendly = $null
            foreach ($_nameProp in @('FriendlyName','Name','Caption','Description')) {
                if ($null -ne $device.PSObject.Properties[$_nameProp]) {
                    $_nameVal = [string]$device.$_nameProp
                    if (-not [string]::IsNullOrWhiteSpace($_nameVal)) { $friendly = $_nameVal; break }
                }
            }
            if (-not $friendly) { $friendly = $device.InstanceId }
            $pnpCache[$id] = @{
                RegistryPath = Convert-DeviceTweakerInstanceIdToRegistryPath -InstanceId $device.InstanceId
                DeviceDesc = $friendly
            }
        } else {
            $desc = $null
            if ($regEnumRoot) {
                try {
                    $subKey = $regEnumRoot.OpenSubKey($id)
                    if ($subKey) {
                        $desc = $subKey.GetValue('DeviceDesc')
                        $subKey.Close()
                    }
                } catch {}
            }
            if ($desc) {
                $pnpCache[$id] = @{ RegistryPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$id"; DeviceDesc = $desc }
            } else {
                $pnpCache[$id] = @{ RegistryPath = Convert-DeviceTweakerInstanceIdToRegistryPath -InstanceId $id; DeviceDesc = $id }
            }
        }
    }

    function Resolve-DeviceInfo {
        param($instanceId)
        if (-not $pnpCache.ContainsKey($instanceId)) {
            if ($deviceLookup.ContainsKey($instanceId)) {
                $dev = $deviceLookup[$instanceId]
                $friendly = $null
                foreach ($_nameProp in @('FriendlyName','Name','Caption','Description')) {
                    if ($null -ne $dev.PSObject.Properties[$_nameProp]) {
                        $_nameVal = [string]$dev.$_nameProp
                        if (-not [string]::IsNullOrWhiteSpace($_nameVal)) { $friendly = $_nameVal; break }
                    }
                }
                if (-not $friendly) { $friendly = $instanceId }
                $pnpCache[$instanceId] = @{ RegistryPath = Convert-DeviceTweakerInstanceIdToRegistryPath -InstanceId $dev.InstanceId; DeviceDesc = $friendly }
            } else {
                $desc = $null
                if ($regEnumRoot) {
                    try {
                        $subKey = $regEnumRoot.OpenSubKey($instanceId)
                        if ($subKey) {
                            $desc = $subKey.GetValue('DeviceDesc')
                            $subKey.Close()
                        }
                    } catch {}
                }
                if ($desc) {
                    $pnpCache[$instanceId] = @{ RegistryPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$instanceId"; DeviceDesc = $desc }
                } else {
                    $pnpCache[$instanceId] = @{ RegistryPath = Convert-DeviceTweakerInstanceIdToRegistryPath -InstanceId $instanceId; DeviceDesc = $instanceId }
                }
            }
        }
        return $pnpCache[$instanceId]
    }

    try {
        $scriptDir = $script:cachedScriptDir
    } catch { $scriptDir = Get-Location }

    $logFile = if (-not $script:DisableLogs) { $script:cachedLogFile } else { $null }

    $logBuffer = if (-not $script:DisableLogs) { [System.Collections.Generic.List[string]]::new() } else { $null }
    $_usbLogTs = if (-not $script:DisableLogs) { Get-Date } else { $null }
    $writeLogLocal = {
        param($txt)
        if ($script:DisableLogs -or $null -eq $logBuffer) { return }
        Add-DeviceTweakerFormattedLogEntry -Buffer $logBuffer -Timestamp $_usbLogTs -Text $txt
    }.GetNewClosure()

    $hidDevices = Get-HIDDevicesWithUSBControllers
    $script:_cachedHidDevices = $hidDevices

    $pollingRateState = @{ Loaded = $false; Lookup = $null }
    $ensurePollingRateLookup = {
        if (-not $pollingRateState.Loaded) {
            $bIntervalResult = Get-CachedBIntervalData
            $pollingRateState.Lookup = Build-PollingRateLookup -UsbEnumResult $bIntervalResult
            $pollingRateState.Loaded = $true
        }
        return $pollingRateState.Lookup
    }.GetNewClosure()

    $hidRoleMap = @{}
    $hidAudioReasonMap = @{}
    $pollingRateMap = @{}
    $endpointSpecLookup = @{}
    $controllerMaxSpeedLookup = [System.Collections.Generic.Dictionary[string,string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $usbEndpointSpecState = @{ Loaded = $false; Result = $null }
    $ensureUsbEndpointSpecData = {
        if (-not $usbEndpointSpecState.Loaded) {
            try { $usbEndpointSpecState.Result = Get-CachedBIntervalData } catch { $usbEndpointSpecState.Result = $null }
            $usbEndpointSpecState.Loaded = $true
        }
        return $usbEndpointSpecState.Result
    }.GetNewClosure()
    $addEndpointSpecs = {
        param(
            [AllowNull()][string]$ControllerKey,
            [AllowNull()][string]$Role,
            [AllowNull()][string]$VidPid,
            [AllowNull()][string]$InstanceId,
            [AllowNull()][string]$ProductString
        )
        $usbSpecData = & $ensureUsbEndpointSpecData
        Add-UsbEndpointRoleSpecToken -Lookup $endpointSpecLookup -UsbEnumResult $usbSpecData -ControllerKey $ControllerKey -Role $Role -VidPid $VidPid -InstanceId $InstanceId -ProductString $ProductString
    }.GetNewClosure()

    foreach ($device in $hidDevices) {
        if (-not $device.USBControllers) { continue }

        $devVidPid = $null
        if ($device.DeviceInstanceID) {
            try { $devVidPid = [DeviceTweakerPathHelpers]::ExtractUsbVidPidColonKey([string]$device.DeviceInstanceID) } catch { $devVidPid = $null }
        }

        foreach ($controller in $device.USBControllers) {
            $pnpId = Get-PNPId $controller.ControllerPNPID
            if (-not $hidRoleMap.ContainsKey($pnpId)) {
                $hidRoleMap[$pnpId] = @{ Keyboard = $false; Mouse = $false; Audio = $false }
            }
            if (-not $pollingRateMap.ContainsKey($pnpId)) {
                $pollingRateMap[$pnpId] = @{}
            }

            $roleForDevice = $device.DeviceType
            if ($roleForDevice -and $devVidPid) {
                & $addEndpointSpecs -ControllerKey $pnpId -Role $roleForDevice -VidPid $devVidPid -InstanceId ([string]$device.DeviceInstanceID) -ProductString ([string]$device.ProductString)
            }
            if ($roleForDevice -eq 'Keyboard') {
                $hidRoleMap[$pnpId].Keyboard = $true
            } elseif ($roleForDevice -eq 'Mouse') {
                $hidRoleMap[$pnpId].Mouse = $true
            } elseif ($roleForDevice -eq 'Audio') {
                $hidRoleMap[$pnpId].Audio = $true

                if (-not $hidAudioReasonMap.ContainsKey($pnpId)) {
                    $hidAudioReasonMap[$pnpId] = [System.Collections.Generic.List[string]]::new()
                }
                $audioReason = if ($device.ClassificationReason) { [string]$device.ClassificationReason } else { 'HID interface classified as Audio' }
                $hidAudioReasonMap[$pnpId].Add("Product='$($device.ProductString)' InstanceId='$($device.DeviceInstanceID)' | $audioReason")

                if ($null -ne $script:audioLookupDetails) {
                    if (-not $script:audioLookupDetails.ContainsKey($pnpId)) {
                        $script:audioLookupDetails[$pnpId] = [System.Collections.Generic.List[DeviceTweakerAudioLookupDetail]]::new()
                    }
                    $alreadyTrackedHidAudio = $false
                    foreach ($_audDetail in $script:audioLookupDetails[$pnpId]) {
                        if ($_audDetail.InstanceId -and $device.DeviceInstanceID -and ([string]$_audDetail.InstanceId).Equals([string]$device.DeviceInstanceID, [System.StringComparison]::OrdinalIgnoreCase)) {
                            $alreadyTrackedHidAudio = $true
                            break
                        }
                    }
                    if (-not $alreadyTrackedHidAudio) {
                        $detail = [DeviceTweakerAudioLookupDetail]::new()
                        $detail.AudioDevice = [string]$device.ProductString
                        $detail.AudioType = 'Audio'
                        $detail.UsbVidPid = [string]$devVidPid
                        $detail.InstanceId = [string]$device.DeviceInstanceID
                        $detail.Reason = [string]$audioReason
                        $detail.ControllerID = [string]$pnpId
                        [void]$script:audioLookupDetails[$pnpId].Add($detail)
                    }
                }
            }

            if (($roleForDevice -eq 'Keyboard' -or $roleForDevice -eq 'Mouse') -and $devVidPid) {
                $_pollingLookup = & $ensurePollingRateLookup
                if ($_pollingLookup.ContainsKey($devVidPid)) {
                    $prEntry = $_pollingLookup[$devVidPid]
                    $tag = Format-PollingRateTag -Hz $prEntry.Hz
                    if (-not $pollingRateMap[$pnpId].ContainsKey($roleForDevice)) {
                        $pollingRateMap[$pnpId][$roleForDevice] = @{ Tag = $tag; Hz = $prEntry.Hz }
                    } elseif ($prEntry.Hz -gt $pollingRateMap[$pnpId][$roleForDevice].Hz) {
                        $pollingRateMap[$pnpId][$roleForDevice] = @{ Tag = $tag; Hz = $prEntry.Hz }
                    }
                }
            }
        }
    }

    $controllerMap = @{}
    $loggedRoleKeys = @{}
    $gameControllerRegex = $null

    foreach ($pair in $parsedPairs) {
        $ctrlId = $pair.CtrlId
        $devId  = $pair.DevId

        $ctrlKey = Get-PNPId $ctrlId
        $ctrlInfo = Resolve-DeviceInfo $ctrlId

        if (-not $controllerMap.ContainsKey($ctrlKey)) {
            $controllerMap[$ctrlKey] = @{
                RegistryPath = $ctrlInfo.RegistryPath
                Description  = $ctrlInfo.DeviceDesc
                Roles        = [System.Collections.Generic.HashSet[string]]::new()
            }
        }

        $devInfo = Resolve-DeviceInfo $devId
        if ([DeviceTweakerPathHelpers]::ContainsGameControllerText([string]$devInfo.DeviceDesc)) {
            [void]$controllerMap[$ctrlKey].Roles.Add('Controller')
            $gcVidPid = [DeviceTweakerPathHelpers]::ExtractUsbVidPidColonKey([string]$devId)
            if ($gcVidPid) {
                & $addEndpointSpecs -ControllerKey $ctrlKey -Role 'Controller' -VidPid $gcVidPid -InstanceId ([string]$devId) -ProductString ([string]$devInfo.DeviceDesc)
                $_pollingLookup = & $ensurePollingRateLookup
                if ($_pollingLookup.ContainsKey($gcVidPid)) {
                    if (-not $pollingRateMap.ContainsKey($ctrlKey)) { $pollingRateMap[$ctrlKey] = @{} }
                    $gcPr = $_pollingLookup[$gcVidPid]
                    $gcTag = Format-PollingRateTag -Hz $gcPr.Hz
                    if (-not $pollingRateMap[$ctrlKey].ContainsKey('Controller')) {
                        $pollingRateMap[$ctrlKey]['Controller'] = @{ Tag = $gcTag; Hz = $gcPr.Hz }
                    } elseif ($gcPr.Hz -gt $pollingRateMap[$ctrlKey]['Controller'].Hz) {
                        $pollingRateMap[$ctrlKey]['Controller'] = @{ Tag = $gcTag; Hz = $gcPr.Hz }
                    }
                }
            }
        }

        if ($audioLookup -and $audioLookup.ContainsKey($ctrlKey)) {
            $seenAudioTypes = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
            foreach ($atype in $audioLookup[$ctrlKey]) {
                if (-not $atype -or -not $seenAudioTypes.Add([string]$atype)) { continue }
                if ($controllerMap[$ctrlKey].Roles.Add($atype)) {
                    $logKey = "$ctrlKey|$atype"
                    if (-not $loggedRoleKeys.ContainsKey($logKey)) {
                        $loggedRoleKeys[$logKey] = $true
                        & $writeLogLocal "Get-USBControllers: Assigned audio role -> Role='$atype' Controller='$ctrlKey' Desc='$($controllerMap[$ctrlKey].Description)'"
                    }
                }
                if ($script:audioLookupDetails -and $script:audioLookupDetails.ContainsKey($ctrlKey)) {
                    foreach ($_audDetail in @($script:audioLookupDetails[$ctrlKey])) {
                        if (-not $_audDetail) { continue }
                        $_detailType = if ($_audDetail.PSObject -and ($null -ne $_audDetail.AudioType)) { [string]$_audDetail.AudioType } else { $null }
                        if ($_detailType -and -not ([string]::Equals($_detailType, [string]$atype, [System.StringComparison]::OrdinalIgnoreCase))) { continue }
                        $_audVidPid = if ($_audDetail.PSObject -and ($null -ne $_audDetail.UsbVidPid)) { [string]$_audDetail.UsbVidPid } else { $null }
                        $_audInst   = if ($_audDetail.PSObject -and ($null -ne $_audDetail.InstanceId)) { [string]$_audDetail.InstanceId } else { $null }
                        & $addEndpointSpecs -ControllerKey $ctrlKey -Role ([string]$atype) -VidPid $_audVidPid -InstanceId $_audInst -ProductString ([string]$_audDetail.AudioDevice)
                    }
                }
            }
        }
    }

    foreach ($ctrlKey in $hidRoleMap.Keys) {
        if (-not $controllerMap.ContainsKey($ctrlKey)) { continue }

        if ($hidRoleMap[$ctrlKey].Keyboard -and $controllerMap[$ctrlKey].Roles.Add('Keyboard')) {
            $logKey = "$ctrlKey|Keyboard"
            if (-not $loggedRoleKeys.ContainsKey($logKey)) {
                $loggedRoleKeys[$logKey] = $true
                & $writeLogLocal "Get-USBControllers: Assigned HID role -> Role='Keyboard' Controller='$ctrlKey' Desc='$($controllerMap[$ctrlKey].Description)'"
            }
        }

        if ($hidRoleMap[$ctrlKey].Mouse -and $controllerMap[$ctrlKey].Roles.Add('Mouse')) {
            $logKey = "$ctrlKey|Mouse"
            if (-not $loggedRoleKeys.ContainsKey($logKey)) {
                $loggedRoleKeys[$logKey] = $true
                & $writeLogLocal "Get-USBControllers: Assigned HID role -> Role='Mouse' Controller='$ctrlKey' Desc='$($controllerMap[$ctrlKey].Description)'"
            }
        }

        if ($hidRoleMap[$ctrlKey].Audio -and $controllerMap[$ctrlKey].Roles.Add('Audio')) {
            $logKey = "$ctrlKey|Audio"
            if (-not $loggedRoleKeys.ContainsKey($logKey)) {
                $loggedRoleKeys[$logKey] = $true
                $audioReasonText = if ($hidAudioReasonMap.ContainsKey($ctrlKey)) { ($hidAudioReasonMap[$ctrlKey] -join '; ') } else { 'HID special handling' }
                & $writeLogLocal "Get-USBControllers: Assigned audio role -> Role='Audio' Controller='$ctrlKey' Source='HID special handling' Desc='$($controllerMap[$ctrlKey].Description)' | Reason: $audioReasonText"
            }
        }

    }

    & $writeLogLocal "Get-USBControllers: Final controller map collected for GUI:"
    foreach ($entry in $controllerMap.GetEnumerator()) {
        $key = $entry.Key
        $desc = $entry.Value.Description
        $roles = if ($entry.Value.Roles.Count -gt 0) {
            (@(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $entry.Value.Roles) -join '/')
        } else {
            '<none>'
        }
        & $writeLogLocal "  - Controller entry: Controller='$key' Roles='$roles' Path='$($entry.Value.RegistryPath)' Desc='$desc'"
    }

    $cpuUsbDevIds = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($did in @('5782','5785','5787','57A5','1138','1135','0B27','15E9','15EC','15F0','15B5','15B6','15C1','15D4','15DB')) {
        [void]$cpuUsbDevIds.Add($did)
    }
    $ctrlKeyToInstId = @{}
    foreach ($pair in $parsedPairs) {
        $k = Get-PNPId $pair.CtrlId
        if (-not $ctrlKeyToInstId.ContainsKey($k)) { $ctrlKeyToInstId[$k] = $pair.CtrlId }
    }

    $busDescMap = @{}
    $cachedPciItems = Get-CachedPciDeviceProps
    foreach ($pciItem in $cachedPciItems) {
        $locRaw = $pciItem.LocationInformation
        $descRaw = $pciItem.DeviceDesc
        if ($locRaw -and $descRaw) {
            $lm = [DeviceTweakerPathHelpers]::ParseBdfLocation([string]$locRaw)
            if ($lm.Success) {
                $busNum = [int]$lm.Bus
                if (-not $busDescMap.ContainsKey($busNum)) {
                    $busDescMap[$busNum] = [System.Collections.Generic.List[string]]::new()
                }
                $busDescMap[$busNum].Add([string]$descRaw)
            }
        }
    }

    $ctrlLocCache = @{}
    if ($regEnumRoot) {
        foreach ($cEntry in $controllerMap.Keys) {
            $instId = $ctrlKeyToInstId[$cEntry]
            if (-not $instId) { continue }
            $devHex = [DeviceTweakerPathHelpers]::ExtractPciDevId([string]$instId)
            if ($devHex -and $cpuUsbDevIds.Contains($devHex)) { continue }
            try {
                $ctrlSk = $regEnumRoot.OpenSubKey($instId)
                if ($ctrlSk) {
                    $ctrlLocCache[$cEntry] = $ctrlSk.GetValue('LocationInformation')
                    $ctrlSk.Close()
                }
            } catch {}
        }
    }

    $controllerOriginMap = @{}
    foreach ($cEntry in $controllerMap.Keys) {
        $origin = 'Chipset'
        $instId = $ctrlKeyToInstId[$cEntry]
        if ($instId) {
            $devHex = [DeviceTweakerPathHelpers]::ExtractPciDevId([string]$instId)
            if ($devHex -and $cpuUsbDevIds.Contains($devHex)) {
                $origin = 'CPU'
            } else {
                $ctrlLocRaw = $ctrlLocCache[$cEntry]
                if ($ctrlLocRaw) {
                    $clm = [DeviceTweakerPathHelpers]::ParseBdfLocation([string]$ctrlLocRaw)
                    if ($clm.Success) {
                        $ctrlBus = [int]$clm.Bus
                        $ctrlDev = [int]$clm.Device
                        if ($ctrlDev -eq 13) {
                            $origin = 'CPU'
                        } elseif ($ctrlDev -eq 20) {
                            $origin = 'Chipset'
                        } else {
                            if ($busDescMap.ContainsKey($ctrlBus)) {
                                foreach ($sibDesc in $busDescMap[$ctrlBus]) {
                                    if ([DeviceTweakerPathHelpers]::ContainsCpuColocationDescription([string]$sibDesc)) {
                                        $origin = 'CPU'
                                        break
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        $controllerOriginMap[$cEntry] = $origin
        & $writeLogLocal "Get-USBControllers: Controller origin -> Controller='$cEntry' Origin='$origin' InstanceId='$instId'"
    }

    foreach ($cEntry in $controllerMap.Keys) {
        if ($controllerOriginMap[$cEntry] -eq 'CPU' -and $controllerMap[$cEntry].Roles.Count -eq 0) {
            Write-DeviceTweakerUnusedCpuUsbControllerWarnings -Controllers @($cEntry)
            & $writeLogLocal "Get-USBControllers: WARNING - Unused CPU USB Controller detected -> Controller='$cEntry'"
        }
    }

    $controllerCapabilityData = & $ensureUsbEndpointSpecData
    $controllerMaxSpeedLookup = Build-UsbControllerMaxSpeedLabelLookup -UsbEnumResult $controllerCapabilityData

    $usbDevices = [System.Collections.Generic.List[object]]::new()
    foreach ($entry in $controllerMap.GetEnumerator()) {
        $rolesArr = [System.Collections.Generic.List[string]]::new()
        foreach ($r in $entry.Value.Roles) { if (-not ($script:ignoredDualSenseAudioNames -contains $r)) { $rolesArr.Add($r) } }
        if ($rolesArr.Count -eq 0) { continue }

        $ctrlKey = $entry.Key
        $audioTypeDisplaySet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
        if ($script:audioLookupDetails -and $script:audioLookupDetails.ContainsKey($ctrlKey)) {
            foreach ($_audDetail in @($script:audioLookupDetails[$ctrlKey])) {
                if (-not $_audDetail) { continue }
                $_audioTypeForDisplay = if ($null -ne $_audDetail.AudioType) { ([string]$_audDetail.AudioType).Trim() } else { '' }
                if ([string]::IsNullOrWhiteSpace($_audioTypeForDisplay)) { continue }
                if ($_audioTypeForDisplay.Equals('Audio', [System.StringComparison]::OrdinalIgnoreCase)) { continue }
                [void]$audioTypeDisplaySet.Add($_audioTypeForDisplay)
            }
        }
        $audioTypesForDisplay = if ($audioTypeDisplaySet.Count -gt 0) { @(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $audioTypeDisplaySet) } else { @() }
        $audioTypeDisplayText = if ($audioTypesForDisplay.Count -gt 0) { ($audioTypesForDisplay -join '/') } else { $null }

        $roleLabels = [System.Collections.Generic.List[string]]::new()
        foreach ($role in $rolesArr) {
            $roleTextForDisplay = if ($audioTypeDisplayText -and ([string]$role).Equals('Audio', [System.StringComparison]::OrdinalIgnoreCase)) { "Audio ($audioTypeDisplayText)" } else { [string]$role }
            if ($pollingRateMap.ContainsKey($ctrlKey) -and $pollingRateMap[$ctrlKey].ContainsKey($role)) {
                $prTag = $pollingRateMap[$ctrlKey][$role].Tag
                $roleLabels.Add("$roleTextForDisplay $prTag")
            } else {
                $roleLabels.Add($roleTextForDisplay)
            }
        }

        $originLabel = if ($controllerOriginMap.ContainsKey($ctrlKey)) { $controllerOriginMap[$ctrlKey] } else { 'Chipset' }
        $usbControllerMaxLabel = if ($controllerMaxSpeedLookup.ContainsKey($ctrlKey)) { [string]$controllerMaxSpeedLookup[$ctrlKey] } else { $null }
        if (-not $usbControllerMaxLabel) { $usbControllerMaxLabel = 'USB capability unknown' }

        $rolesDisplayText = if ($roleLabels.Count -gt 0) { ($roleLabels -join '/') } else { 'none' }
        $endpointUsageLabel = Get-UsbEndpointRoleSpecText -Lookup $endpointSpecLookup -ControllerKey $ctrlKey -Roles @($rolesArr)
        if (-not $endpointUsageLabel) { $endpointUsageLabel = 'Endpoint use: not detected' }

        $usbHeaderTitle = "$originLabel USB controller | Max: $usbControllerMaxLabel | Roles: $rolesDisplayText"
        $usbDisplayName = "$originLabel USB Controller (Max $usbControllerMaxLabel; Roles - $rolesDisplayText)"

        $usbDevices.Add([PSCustomObject]@{
            Category              = 'USB'
            Roles                 = @($rolesArr)
            AudioTypes            = @($audioTypesForDisplay)
            DisplayName           = $usbDisplayName
            UsbHeaderTitle        = $usbHeaderTitle
            UsbEndpointUsageLabel = $endpointUsageLabel
            UsbControllerMaxLabel = $usbControllerMaxLabel
            RegistryPath          = $entry.Value.RegistryPath
            Description           = $entry.Value.Description
        })
    }

    if (-not $script:DisableLogs -and $logBuffer.Count -gt 0 -and $logFile) {
        try { Queue-DeviceTweakerLogText -Path $logFile -Text (($logBuffer -join [Environment]::NewLine) + [Environment]::NewLine) } catch {}
    }

    if ($regEnumRoot) { try { $regEnumRoot.Close() } catch {} }

    return $usbDevices
}

function Get-AudioEndpointMappings {
    $startupPayload = Get-DeviceTweakerStartupModel
    if ($startupPayload -and $startupPayload.AudioEndpointParentRowsComplete -and $startupPayload.AudioEndpointParentRows -and $startupPayload.AudioEndpointParentRows.Count -gt 0) {
        $controllerMap = @{}
        foreach ($row in @($startupPayload.AudioEndpointParentRows)) {
            if ($null -eq $row -or [string]::IsNullOrWhiteSpace([string]$row.ControllerID)) { continue }
            $pnpId = Get-PNPId $row.ControllerID
            if ([string]::IsNullOrWhiteSpace([string]$pnpId)) { continue }
            if (-not $controllerMap.ContainsKey($pnpId)) {
                $controllerMap[$pnpId] = @{
                    Types = @()
                    Descriptions = @()
                }
            }
            $type = if ($null -ne $row.AudioType -and -not [string]::IsNullOrWhiteSpace([string]$row.AudioType)) { [string]$row.AudioType } else { 'Audio' }
            $desc = if ($null -ne $row.AudioDevice) { [string]$row.AudioDevice } else { [string]$row.InstanceId }
            $controllerMap[$pnpId].Types += $type
            $controllerMap[$pnpId].Descriptions += $desc
        }
        return $controllerMap
    }

    $allDevices = Get-CachedPnpDevices
    $controllerLookup = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $endpoints = [System.Collections.Generic.List[object]]::new()
    foreach ($d in $allDevices) {
        if ($d.FriendlyName -like '*Audio Controller*' -and $d.Status -eq 'OK' -and $d.InstanceId) {
            $controllerLookup[$d.InstanceId] = $d
        }
        if ($d.Class -eq 'AudioEndpoint' -and $d.Status -eq 'OK') {
            $endpoints.Add($d)
        }
    }
    $audioFormFactorMap = Get-DeviceTweakerAudioEndpointFormFactorMapForEndpoints -AudioEndpoints $endpoints

    $logFile = if (-not $script:DisableLogs) { $script:cachedLogFile } else { $null }
    $_aemLogBuffer = if (-not $script:DisableLogs) { [System.Collections.Generic.List[string]]::new() } else { $null }
    $_aemLogTs = if (-not $script:DisableLogs) { Get-Date } else { $null }
    function Write-Log {
        param($text)
        if ($script:DisableLogs) { return }
        Add-DeviceTweakerFormattedLogEntry -Buffer $_aemLogBuffer -Timestamp $_aemLogTs -Text $text
    }

    $controllerMap = @{}
    $parentMap = Get-DeviceTopologyParentMap
    foreach ($ep in $endpoints) {
        if ($ep.FriendlyName -and $script:ignoredDualSenseAudioNames -contains $ep.FriendlyName) { continue }
        $parent1Data = if ($parentMap -and $parentMap.ContainsKey($ep.InstanceId)) { [string]$parentMap[$ep.InstanceId] } else { $null }
        if (-not $parent1Data) { continue }

        $parent2Data = if ($parentMap -and $parentMap.ContainsKey($parent1Data)) { [string]$parentMap[$parent1Data] } else { $null }
        if (-not $parent2Data) { continue }

        $controller = if ($parent2Data -and $controllerLookup.ContainsKey($parent2Data)) { $controllerLookup[$parent2Data] } else { $null }
        if (-not $controller) { continue }

        $formFactorRecord = $null
        if ($ep.InstanceId -and $audioFormFactorMap -and $audioFormFactorMap.ContainsKey($ep.InstanceId)) {
            $formFactorRecord = $audioFormFactorMap[$ep.InstanceId]
        }
        $formFactorValue = if ($formFactorRecord -and ($null -ne $formFactorRecord.Value)) { $formFactorRecord.Value } else { $null }
        $formFactorSource = if ($formFactorRecord -and ($null -ne $formFactorRecord.Source)) { [string]$formFactorRecord.Source } else { $null }
        $formFactorInfo = Resolve-DeviceTweakerAudioEndpointFormFactorInfo -Value $formFactorValue -Source $formFactorSource
        $type = [string]$formFactorInfo.AudioType

        $pnpId = Get-PNPId $controller.InstanceId
        if (-not $controllerMap.ContainsKey($pnpId)) {
            $controllerMap[$pnpId] = @{
                Types = @()
                Descriptions = @()
            }
        }
        $controllerMap[$pnpId].Types += $type
        $controllerMap[$pnpId].Descriptions += $ep.FriendlyName
        try {
            $fn = if ($ep.FriendlyName) { $ep.FriendlyName } else { "<unknown>" }
            Write-Log "Audio mapping: ControllerPNP='$pnpId' EndpointName='$fn' MatchedType='$type' | Reason: $($formFactorInfo.Reason)"
        } catch {}
    }

    if (-not $script:DisableLogs -and $_aemLogBuffer -and $_aemLogBuffer.Count -gt 0 -and $logFile) {
        try { Queue-DeviceTweakerLogText -Path $logFile -Text (($_aemLogBuffer -join [Environment]::NewLine) + [Environment]::NewLine) } catch {}
    }

    return $controllerMap
}

function Get-PCIDevicesNative {

    $startupPayload = Get-DeviceTweakerStartupModel
    if ($startupPayload -and $startupPayload.PciRowsComplete) {
        try { if ($startupPayload.PciSourceLogs) { $script:_cachedPciNativeDiscoveryLogs = @($startupPayload.PciSourceLogs) } else { $script:_cachedPciNativeDiscoveryLogs = @() } } catch { $script:_cachedPciNativeDiscoveryLogs = @() }
        return @{
            GPU   = @($startupPayload.PciGpuRows)
            Audio = @($startupPayload.PciAudioRows)
        }
    }

    $discoveryModel = Get-DeviceTweakerDiscoveryModel
    $typedAudioDetails = ConvertTo-DeviceTweakerAudioEndpointInfoList -AudioRowsOrMap $script:audioLookupDetails
    $typedAudioParents = ConvertTo-DeviceTweakerAudioEndpointInfoList -AudioRowsOrMap $script:audioParentsRaw
    $ignoredAudioNames = [string[]]@($script:ignoredDualSenseAudioNames)
    $pciIdsPath = Get-DeviceTweakerPciIdsPath

    try {
        $nativeResult = [DeviceTweakerDiscovery]::BuildPciDisplayRecords($discoveryModel, $typedAudioDetails, $typedAudioParents, $ignoredAudioNames, $pciIdsPath)
    } catch {
        throw "DeviceTweakerDiscovery.BuildPciDisplayRecords failed: $($_.Exception.Message)"
    }

    try { $script:_cachedPciNativeDiscoveryLogs = @($nativeResult.Logs) } catch { $script:_cachedPciNativeDiscoveryLogs = @() }

    $gpuRecords = if ($null -ne $nativeResult -and $null -ne $nativeResult.GPU) { $nativeResult.GPU.ToArray() } else { @() }
    $audioRecords = if ($null -ne $nativeResult -and $null -ne $nativeResult.Audio) { $nativeResult.Audio.ToArray() } else { @() }
    return @{
        GPU   = $gpuRecords
        Audio = $audioRecords
    }
}

function Get-PCIDevices {
    $discoveryModel = Get-DeviceTweakerDiscoveryModel
    $allPciItems = if ($discoveryModel -and $discoveryModel.PciDevicesByPath -and $discoveryModel.PciDevicesByPath.Count -gt 0) {
        @(Convert-DeviceTweakerDiscoveryModelToPciDeviceProps -Model $discoveryModel)
    } else {
        Get-CachedPciDeviceProps
    }
    $allModelDevices = Get-CachedPnpDevices

    $pciDescMap = @{}
    foreach ($item in $allPciItems) {
        $pciDescMap[$item.PSPath] = $item.DeviceDesc
    }

    try {
        $scriptDir = $script:cachedScriptDir
    } catch { $scriptDir = Get-Location }
    $logFile = if (-not $script:DisableLogs) { $script:cachedLogFile } else { $null }

    $logBuffer = if (-not $script:DisableLogs) { [System.Collections.Generic.List[string]]::new() } else { $null }
    $_pciLogTs = if (-not $script:DisableLogs) { Get-Date } else { $null }
    $writeLogLocal = {
        param($txt)
        if ($script:DisableLogs -or $null -eq $logBuffer) { return }
        Add-DeviceTweakerFormattedLogEntry -Buffer $logBuffer -Timestamp $_pciLogTs -Text $txt
    }.GetNewClosure()

    function Normalize-DeviceTweakerPciLookupText {
        param([AllowNull()][object]$Value)
        try { return [DeviceTweakerPathHelpers]::NormalizeLookupText([string]$Value) } catch { return '' }
    }

    function Get-DeviceTweakerPciLookupInstanceId {
        param([AllowNull()][object]$Value)
        try { return [DeviceTweakerPathHelpers]::GetPciLookupInstanceId([string]$Value) } catch { return '' }
    }

    function Get-DeviceTweakerPciLookupHardwareId {
        param([AllowNull()][object]$Value)
        try { return [DeviceTweakerPathHelpers]::GetPciLookupHardwareId([string]$Value) } catch { return '' }
    }

    function Get-DeviceTweakerPciLookupPnpId {
        param([AllowNull()][string]$HardwareId)
        try { return [DeviceTweakerPathHelpers]::BuildPciPnpId($HardwareId) } catch { return '' }
    }

    function Get-DeviceTweakerPciLookupPortId {
        param([AllowNull()][string]$InstanceId)
        try { return [DeviceTweakerPathHelpers]::ExtractPciPortId($InstanceId) } catch { return '' }
    }

    function Get-DeviceTweakerPciClassCode {
        param([AllowNull()][object[]]$Values)

        if ($null -eq $Values) { return '' }
        foreach ($value in $Values) {
            if ($null -eq $value) { continue }
            if (($value -is [System.Collections.IEnumerable]) -and -not ($value -is [string])) {
                foreach ($nestedValue in $value) {
                    $nested = Get-DeviceTweakerPciClassCode -Values @($nestedValue)
                    if (-not [string]::IsNullOrWhiteSpace([string]$nested)) { return [string]$nested }
                }
                continue
            }

            $text = [string]$value
            if ([string]::IsNullOrWhiteSpace($text)) { continue }

            $rawMatch = [System.Text.RegularExpressions.Regex]::Match($text.Trim(), '^(?:CC_)?(?:0x)?([0-9A-Fa-f]{4,6})$')
            if ($rawMatch.Success) {
                $raw = $rawMatch.Groups[1].Value.ToUpperInvariant()
                if ($raw.Length -ge 4) { return $raw.Substring(0, 4) }
                return $raw
            }

            $match = [System.Text.RegularExpressions.Regex]::Match($text, 'CC_([0-9A-Fa-f]{4,6})', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
            if ($match.Success) {
                $raw = $match.Groups[1].Value.ToUpperInvariant()
                if ($raw.Length -ge 4) { return $raw.Substring(0, 4) }
                return $raw
            }
        }

        return ''
    }

    function Test-DeviceTweakerPciDisplayControllerClassCode {
        param([AllowNull()][object]$ClassCode)

        if ($null -eq $ClassCode) { return $false }
        $text = ([string]$ClassCode).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return $false }
        if ($text.StartsWith('CC_', [System.StringComparison]::OrdinalIgnoreCase)) { $text = $text.Substring(3) }
        if ($text.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) { $text = $text.Substring(2) }
        return ($text.Length -ge 2 -and $text.StartsWith('03', [System.StringComparison]::OrdinalIgnoreCase))
    }

    function Test-DeviceTweakerPciGpuNameToken {
        param([AllowNull()][object]$Value)

        if ($null -eq $Value) { return $false }
        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) { return $false }

        foreach ($token in @('AMD', 'NVIDIA', 'Radeon', 'GeForce', 'Intel', 'Arc')) {
            if ($text.IndexOf($token, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return $true }
        }

        return $false
    }

    function Test-DeviceTweakerPciAudioControllerText {
        param([AllowNull()][object]$Value)

        if ($null -eq $Value) { return $false }
        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) { return $false }

        return ($text.IndexOf('Audio Controller', [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
    }

    function Add-DeviceTweakerPciLookupRecord {
        param(
            [AllowNull()][object]$Lookup,
            [AllowNull()][string]$Key,
            [AllowNull()][object]$Record
        )

        if ($null -eq $Lookup -or $null -eq $Record -or [string]::IsNullOrWhiteSpace($Key)) { return }

        if (-not $Lookup.ContainsKey($Key)) {
            $Lookup[$Key] = [System.Collections.Generic.List[object]]::new()
        }

        [void]$Lookup[$Key].Add($Record)
    }

    function Add-DeviceTweakerGpuPciMatchesFromDisplayClassCodeFallback {
        param(
            [AllowNull()][object]$PciByPath,
            [AllowNull()][System.Collections.Generic.HashSet[string]]$MatchedPaths
        )

        if ($null -eq $PciByPath -or $null -eq $MatchedPaths -or $MatchedPaths.Count -gt 0) { return 0 }

        $added = 0
        foreach ($entry in $PciByPath.GetEnumerator()) {
            $record = $entry.Value
            if ($null -eq $record) { continue }
            if (-not (Test-DeviceTweakerPciDisplayControllerClassCode $record.ClassCode)) { continue }

            $psPath = if (-not [string]::IsNullOrWhiteSpace([string]$record.PSPath)) { [string]$record.PSPath } else { [string]$entry.Key }
            if ([string]::IsNullOrWhiteSpace($psPath)) { continue }

            if ($MatchedPaths.Add($psPath)) {
                $added++
                try { & $writeLogLocal "Get-PCIDevices: PCI display-class GPU fallback matched: Path='$psPath' ClassCode='$($record.ClassCode)' Desc='$($record.DeviceDesc)' | Reason: name-token GPU detection found zero GPUs and PCI class code starts with 03" } catch {}
            }
        }

        try { & $writeLogLocal "Get-PCIDevices: PCI display-class GPU fallback summary -> Matched=$added | Activation: name-token GPU detection found zero GPUs" } catch {}
        return $added
    }

    function Add-DeviceTweakerGpuPciMatchesFromLookup {
        param(
            [AllowNull()][object]$Lookup,
            [AllowNull()][string]$Key,
            [AllowNull()][System.Collections.Generic.HashSet[string]]$MatchedPaths,
            [switch]$RequireGpuDescription
        )

        if ($null -eq $Lookup -or $null -eq $MatchedPaths -or [string]::IsNullOrWhiteSpace($Key)) { return }
        if (-not $Lookup.ContainsKey($Key)) { return }

        foreach ($record in $Lookup[$Key]) {
            if ($null -eq $record -or [string]::IsNullOrWhiteSpace([string]$record.PSPath)) { continue }
            if ($RequireGpuDescription -and -not [bool]$record.IsGpuDescription) { continue }
            [void]$MatchedPaths.Add([string]$record.PSPath)
        }
    }

    $gpuPorts   = [System.Collections.Generic.HashSet[string]]::new()
    $gpuDevices = [System.Collections.Generic.List[object]]::new()

    $gpuInstanceSet  = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $gpuHardwareIdSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)

    $pciByInstanceId = [System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $pciByHardwareId = [System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[object]]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $pciByPath       = [System.Collections.Generic.Dictionary[string,object]]::new([System.StringComparer]::OrdinalIgnoreCase)

    foreach ($psPath in $pciDescMap.Keys) {
        $desc = $pciDescMap[$psPath]
        $pciFields = [DeviceTweakerPathHelpers]::ParsePciLookupFields([string]$psPath)
        $instanceId = [string]$pciFields.InstanceId
        $hardwareId = [string]$pciFields.HardwareId
        $portId = [string]$pciFields.PortId
        $pnpId = [string]$pciFields.PNPID

        $itemClassCodeProperty = $item.PSObject.Properties['ClassCode']
        $itemClassCode = if ($itemClassCodeProperty -and $null -ne $itemClassCodeProperty.Value) { [string]$itemClassCodeProperty.Value } else { '' }
        if ([string]::IsNullOrWhiteSpace($itemClassCode)) {
            $itemHardwareIdsProperty = $item.PSObject.Properties['HardwareIds']
            $itemCompatibleIdsProperty = $item.PSObject.Properties['CompatibleIds']
            $itemHardwareIdProperty = $item.PSObject.Properties['HardwareId']
            $itemInstanceIdProperty = $item.PSObject.Properties['InstanceId']
            $itemHardwareIds = if ($itemHardwareIdsProperty -and $null -ne $itemHardwareIdsProperty.Value) { @($itemHardwareIdsProperty.Value) } else { @() }
            $itemCompatibleIds = if ($itemCompatibleIdsProperty -and $null -ne $itemCompatibleIdsProperty.Value) { @($itemCompatibleIdsProperty.Value) } else { @() }
            $itemHardwareId = if ($itemHardwareIdProperty -and $null -ne $itemHardwareIdProperty.Value) { [string]$itemHardwareIdProperty.Value } else { $hardwareId }
            $itemInstanceId = if ($itemInstanceIdProperty -and $null -ne $itemInstanceIdProperty.Value) { [string]$itemInstanceIdProperty.Value } else { $instanceId }
            $itemClassCode = Get-DeviceTweakerPciClassCode -Values @($itemHardwareIds, $itemCompatibleIds, $itemInstanceId, $itemHardwareId, $psPath)
        }

        $pciRecord = [PSCustomObject]@{
            PSPath            = [string]$psPath
            DeviceDesc        = $desc
            InstanceId        = $instanceId
            HardwareId        = $hardwareId
            PNPID             = $pnpId
            PortId            = $portId
            ClassCode         = $itemClassCode
            IsGpuDescription  = (Test-DeviceTweakerPciGpuNameToken $desc)
            IsGpuClassCode    = (Test-DeviceTweakerPciDisplayControllerClassCode $itemClassCode)
            IsAudioController = (Test-DeviceTweakerPciAudioControllerText $desc)
        }

        $pciByPath[[string]$psPath] = $pciRecord
        Add-DeviceTweakerPciLookupRecord -Lookup $pciByInstanceId -Key $instanceId -Record $pciRecord
        Add-DeviceTweakerPciLookupRecord -Lookup $pciByHardwareId -Key $hardwareId -Record $pciRecord
    }

    try {
        $pnpDisplayDevices = [System.Collections.Generic.List[object]]::new()
        foreach ($d in $allModelDevices) {
            if ($d.Class -eq 'Display' -and $d.Status -eq 'OK') { $pnpDisplayDevices.Add($d) }
        }
        foreach ($pnpDev in $pnpDisplayDevices) {
            if (Test-DeviceTweakerPciGpuNameToken $pnpDev.FriendlyName) {
                if ($pnpDev.InstanceId) {
                    $gpuInstanceKey = Get-DeviceTweakerPciLookupInstanceId $pnpDev.InstanceId
                    if (-not [string]::IsNullOrWhiteSpace($gpuInstanceKey)) { [void]$gpuInstanceSet.Add($gpuInstanceKey) }

                    $gpuHardwareKey = Get-DeviceTweakerPciLookupHardwareId $pnpDev.InstanceId
                    if (-not [string]::IsNullOrWhiteSpace($gpuHardwareKey)) { [void]$gpuHardwareIdSet.Add($gpuHardwareKey) }
                }

                foreach ($hardwarePropertyName in @('HardwareID', 'HardwareIds', 'HardwareId')) {
                    $hardwareProperty = $pnpDev.PSObject.Properties[$hardwarePropertyName]
                    if ($null -eq $hardwareProperty -or $null -eq $hardwareProperty.Value) { continue }
                    foreach ($candidateHardwareId in @($hardwareProperty.Value)) {
                        $gpuHardwareKey = Get-DeviceTweakerPciLookupHardwareId $candidateHardwareId
                        if (-not [string]::IsNullOrWhiteSpace($gpuHardwareKey)) { [void]$gpuHardwareIdSet.Add($gpuHardwareKey) }
                    }
                }

                try { & $writeLogLocal "Get-PCIDevices: PnP Display GPU matched: Name='$($pnpDev.FriendlyName)' InstanceId='$($pnpDev.InstanceId)' Status='$($pnpDev.Status)'" } catch {}
            } else {
                try { & $writeLogLocal "Get-PCIDevices: PnP Display device IGNORED (not GPU): Name='$($pnpDev.FriendlyName)' InstanceId='$($pnpDev.InstanceId)' Status='$($pnpDev.Status)' | Reason: FriendlyName does not match AMD/NVIDIA/Radeon/GeForce/Intel/Arc pattern" } catch {}
            }
        }
    } catch {
        try { & $writeLogLocal "Get-PCIDevices: cached display device lookup failed: $_" } catch {}
    }

    $matchedGpuPciPaths = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($gpuInstanceKey in $gpuInstanceSet) {
        Add-DeviceTweakerGpuPciMatchesFromLookup -Lookup $pciByInstanceId -Key $gpuInstanceKey -MatchedPaths $matchedGpuPciPaths
    }
    foreach ($gpuHardwareKey in $gpuHardwareIdSet) {
        Add-DeviceTweakerGpuPciMatchesFromLookup -Lookup $pciByHardwareId -Key $gpuHardwareKey -MatchedPaths $matchedGpuPciPaths -RequireGpuDescription
    }
    if ($matchedGpuPciPaths.Count -eq 0) {
        [void](Add-DeviceTweakerGpuPciMatchesFromDisplayClassCodeFallback -PciByPath $pciByPath -MatchedPaths $matchedGpuPciPaths)
    }

    foreach ($psPath in $pciDescMap.Keys) {
        if (-not $matchedGpuPciPaths.Contains([string]$psPath)) { continue }

        $pciRecord = $pciByPath[[string]$psPath]
        $desc = $pciRecord.DeviceDesc
        $regInstanceId = $pciRecord.InstanceId
        $portId = $pciRecord.PortId
        if ([string]::IsNullOrWhiteSpace([string]$portId)) { $portId = Get-DeviceTweakerPciLookupPortId $regInstanceId }
        $gpuPorts.Add($portId) | Out-Null

        $gpuInstanceForName = if ($regInstanceId) { $regInstanceId } else { $psPath }
        $gpuResolvedName = Resolve-DeviceTweakerPciDisplayName -InstanceId $gpuInstanceForName -RegistryPath $psPath -WindowsName $desc -Role 'GPU'
        if ([string]::IsNullOrWhiteSpace([string]$gpuResolvedName)) { $gpuResolvedName = $desc }

        $gpuDevices.Add([PSCustomObject]@{
            Category           = 'PCI'
            Role               = 'GPU'
            DisplayName        = (New-DeviceTweakerTypedDisplayName -Base 'GPU' -Model $gpuResolvedName)
            RegistryPath       = $psPath
            Description        = $gpuResolvedName
            ChipsetDescription = $desc
            Port               = $portId
            InstanceId         = $regInstanceId
            HardwareId         = $pciRecord.HardwareId
            PNPID              = $pciRecord.PNPID
            PortId             = $portId
            ClassCode          = $pciRecord.ClassCode
        })
        try { & $writeLogLocal "Get-PCIDevices: GPU detected: Path='$psPath' Port='$portId' ChipsetDesc='$desc' ResolvedVideoCard='$gpuResolvedName'" } catch {}
    }

    $audioMappings = $audioLookup
    $audioMappingDetails = if ($script:audioLookupDetails) { $script:audioLookupDetails } else { @{} }
    $audioDevices  = [System.Collections.Generic.List[object]]::new()
    $ignoredAudio  = [System.Collections.Generic.List[object]]::new()

    foreach ($psPath in $pciDescMap.Keys) {
        $pciRecord = $pciByPath[[string]$psPath]
        if ($null -eq $pciRecord -or -not [bool]$pciRecord.IsAudioController) { continue }

        $desc = $pciRecord.DeviceDesc
        $portId = $pciRecord.PortId
        if ([string]::IsNullOrWhiteSpace([string]$portId)) { $portId = Get-DeviceTweakerPciLookupPortId $pciRecord.InstanceId }
        $pnpId = $pciRecord.PNPID
        if ([string]::IsNullOrWhiteSpace([string]$pnpId)) { $pnpId = Get-DeviceTweakerPciLookupPnpId $pciRecord.HardwareId }

        if ($audioMappings -and $audioMappings.ContainsKey($pnpId)) {
                $typeSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                $mappedDetails = if ($audioMappingDetails -and $audioMappingDetails.ContainsKey($pnpId)) { @($audioMappingDetails[$pnpId]) } else { @() }
                foreach ($detail in $mappedDetails) {
                    if (-not $detail) { continue }
                    $mappedType = if ($null -ne $detail.AudioType) { ([string]$detail.AudioType).Trim() } else { '' }
                    if ([string]::IsNullOrWhiteSpace($mappedType)) { continue }
                    if ($mappedType -ne 'Unknown Audio Device') { [void]$typeSet.Add($mappedType) }
                }
                if ($typeSet.Count -eq 0) {
                    foreach ($mappedType in $audioMappings[$pnpId]) {
                        if ($mappedType -and $mappedType -ne 'Unknown Audio Device') { [void]$typeSet.Add([string]$mappedType) }
                    }
                }

                $endpointNameSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                $reasonSet = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
                foreach ($detail in $mappedDetails) {
                    if ($detail.AudioDevice) { [void]$endpointNameSet.Add([string]$detail.AudioDevice) }
                    if ($detail.Reason)      { [void]$reasonSet.Add([string]$detail.Reason) }
                }
                $endpointNames = if ($endpointNameSet.Count -gt 0) { @(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $endpointNameSet) } else { @() }
                $classificationReason = if ($reasonSet.Count -gt 0) {
                    "Mapped from AudioEndpoint classification reason(s): " + ((@(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $reasonSet)) -join '; ')
                } elseif ($mappedDetails.Count -gt 0) {
                    "Mapped from AudioEndpoint device tree traversal"
                } else {
                    "Mapped from audio endpoint lookup"
                }

                if ($typeSet.Count -gt 0) {
                    $types = @(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $typeSet)
                    if (Test-DeviceTweakerHdAudioOnly -Types $types) {
                        $ignoreReason = 'Mapped role is HD Audio-only'
                        $ignoredAudio.Add(@{
                            Path            = $psPath
                            PNPID           = $pnpId
                            Desc            = $desc
                            Reason          = $ignoreReason
                            BaseReason      = $ignoreReason
                            EndpointNames   = $endpointNames
                            EndpointReasons = @()
                        })
                        try { & $writeLogLocal "Get-PCIDevices: IGNORED HDA Audio controller (HD Audio-only classification) -> PNPID='$pnpId' Path='$psPath' Desc='$desc' | EndpointNames='$(if ($endpointNames.Count -gt 0) { $endpointNames -join '; ' } else { '<none>' })' | Reason: $ignoreReason" } catch {}
                        continue
                    }
                    $audioInstanceForName = if ($pciRecord.InstanceId) { $pciRecord.InstanceId } else { $psPath }
                    $audioResolvedName = Resolve-DeviceTweakerPciDisplayName -InstanceId $audioInstanceForName -RegistryPath $psPath -WindowsName $desc -Role 'Audio'
                    $display = New-DeviceTweakerAudioControllerDisplayName -Roles $types -Model $audioResolvedName
                    $descriptionForAudio = if ([string]::IsNullOrWhiteSpace([string]$audioResolvedName)) { $desc } else { $audioResolvedName }
                    $audioDevices.Add([PSCustomObject]@{
                        Category             = 'PCI'
                        Role                 = 'Audio'
                        DisplayName          = $display
                        RegistryPath         = $psPath
                        Description          = $descriptionForAudio
                        OriginalDescription  = $desc
                        ResolvedName         = $audioResolvedName
                        Port                 = $portId
                        AudioTypes           = $types
                        PNPID                = $pnpId
                        EndpointNames        = $endpointNames
                        ClassificationReason = $classificationReason
                    })
                    try { & $writeLogLocal "Get-PCIDevices: INCLUDED Audio controller -> PNPID='$pnpId' Path='$psPath' Port='$portId' Desc='$desc' ResolvedName='$(if ([string]::IsNullOrWhiteSpace([string]$audioResolvedName)) { '<none>' } else { $audioResolvedName })' Display='$display' Types='$(if ($types) { $types -join '/' } else { '<none>' })' | EndpointNames='$(if ($endpointNames.Count -gt 0) { $endpointNames -join '; ' } else { '<none>' })' | Reason: $classificationReason" } catch {}
                } else {
                    $ignoreReason = if ($reasonSet.Count -gt 0) {
                        "Mapped but no usable audio types; AudioEndpoint reason(s): " + ((@(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $reasonSet)) -join '; ')
                    } else {
                        "Mapped but no usable audio types"
                    }
                    $ignoredAudio.Add(@{
                        Path            = $psPath
                        PNPID           = $pnpId
                        Desc            = $desc
                        Reason          = $ignoreReason
                        BaseReason      = $ignoreReason
                        EndpointNames   = $endpointNames
                        EndpointReasons = @()
                    })
                    try { & $writeLogLocal "Get-PCIDevices: IGNORED Audio controller (mapped but no usable types) -> PNPID='$pnpId' Path='$psPath' Desc='$desc' | EndpointNames='$(if ($endpointNames.Count -gt 0) { $endpointNames -join '; ' } else { '<none>' })' | Reason: $ignoreReason" } catch {}
                }
            } else {
                $epReasons = [System.Collections.Generic.List[string]]::new()
                $epNames   = [System.Collections.Generic.List[string]]::new()
                if ($audioParentsRaw -and $audioParentsRaw.Count -gt 0) {
                    foreach ($epRow in $audioParentsRaw) {
                        $epName = if ($epRow.AudioDevice) { $epRow.AudioDevice } else { '<unknown>' }
                        if ($epRow.ControllerID) {
                            $epReasons.Add("Endpoint '$epName' (InstanceId='$($epRow.InstanceId)') -> mapped to different controller '$($epRow.ControllerID)', not '$pnpId'")
                        } else {
                            $epReasons.Add("Endpoint '$epName' (InstanceId='$($epRow.InstanceId)') -> could not resolve any PCI/USB parent controller in device tree")
                        }
                        $epNames.Add($epName)
                    }
                }
                foreach ($d in $allModelDevices) {
                    if ($d.Class -eq 'AudioEndpoint' -and $d.Status -eq 'OK' -and $d.FriendlyName -and ($script:ignoredDualSenseAudioNames -contains $d.FriendlyName)) {
                        $epReasons.Add("Endpoint '$($d.FriendlyName)' (InstanceId='$($d.InstanceId)') -> excluded (DualSense controller audio device)")
                        $epNames.Add($d.FriendlyName)
                    }
                }
                if ($epReasons.Count -eq 0) {
                    $detailedReason = "No audio endpoint mapping found; no AudioEndpoint devices detected on system"
                } else {
                    $detailedReason = "No audio endpoint mapping found; $($epReasons.Count) endpoint(s) checked: " + ($epReasons -join '; ')
                }
                $summaryReason = if ($epReasons.Count -gt 0) { "No audio endpoint mapping found" } else { $detailedReason }
                $ignoredAudio.Add(@{
                    Path            = $psPath
                    PNPID           = $pnpId
                    Desc            = $desc
                    Reason          = $detailedReason
                    BaseReason      = $summaryReason
                    EndpointNames   = @($epNames)
                    EndpointReasons = @($epReasons)
                })
                try {
                    & $writeLogLocal "Get-PCIDevices: IGNORED Audio controller (no mapping) -> PNPID='$pnpId' Path='$psPath' Desc='$desc' | Reason: No audio endpoint mapping found"
                    if ($epReasons.Count -gt 0) {
                        & $writeLogLocal "  Checked AudioEndpoint(s): Count=$($epReasons.Count) ControllerPNPID='$pnpId'"
                        foreach ($epR in $epReasons) {
                            & $writeLogLocal "    - $epR"
                        }
                    } else {
                        & $writeLogLocal "  No AudioEndpoint devices (class=AudioEndpoint, status=OK) found on system to match against"
                    }
                } catch {}
            }
        }

    foreach ($a in $audioDevices) {
        if ($a.Port -and $gpuPorts.Contains($a.Port) -and $a.AudioTypes -and $a.AudioTypes.Count -gt 0) {
            $oldDisplay = $a.DisplayName
            $audioGpuModel = if ($null -ne $a.ResolvedName) { $a.ResolvedName } else { $null }
            $a.DisplayName = New-DeviceTweakerAudioControllerDisplayName -Roles @('GPU') -Model $audioGpuModel
            $a.Role        = 'AudioGPU'
            try { & $writeLogLocal "Get-PCIDevices: Audio controller upgraded to Audio-GPU -> PNPID='$($a.PNPID)' Path='$($a.RegistryPath)' Port='$($a.Port)' OldDisplay='$oldDisplay' NewDisplay='$($a.DisplayName)' ResolvedName='$(if ([string]::IsNullOrWhiteSpace([string]$audioGpuModel)) { '<none>' } else { $audioGpuModel })'" } catch {}
        }
    }

    try {
        & $writeLogLocal "Get-PCIDevices: Summary -> GPUsFound=$($gpuDevices.Count) AudioControllersIncluded=$($audioDevices.Count) AudioControllersIgnored=$($ignoredAudio.Count)"
        if ($audioDevices.Count -gt 0) {
            & $writeLogLocal "SUMMARY: Audio controller classification results:"
            foreach ($ad in $audioDevices) {
                $types = if ($ad.AudioTypes -and $ad.AudioTypes.Count -gt 0) { ($ad.AudioTypes -join '/') } else { '<none>' }
                $endpointNames = if ($ad.EndpointNames -and $ad.EndpointNames.Count -gt 0) { ($ad.EndpointNames -join '; ') } else { '<none>' }
                $reason = if ($ad.ClassificationReason) { $ad.ClassificationReason } else { '<none>' }
                & $writeLogLocal "  - Audio controller: PNPID='$($ad.PNPID)' Path='$($ad.RegistryPath)' Port='$($ad.Port)' Desc='$($ad.Description)' Types='$types' EndpointNames='$endpointNames' | Reason: $reason"
            }
        }
        if ($ignoredAudio.Count -gt 0) {
            & $writeLogLocal "SUMMARY: Audio controllers IGNORED: $($ignoredAudio.Count) controller(s)"
            foreach ($ia in $ignoredAudio) {
                $endpointNameList = if ($ia.EndpointNames -and $ia.EndpointNames.Count -gt 0) { @(ConvertTo-DeviceTweakerFastSortedUniqueStringArray $ia.EndpointNames) } else { @() }
                $endpointReasons = if (($ia -is [hashtable]) -and $ia.ContainsKey('EndpointReasons') -and $ia.EndpointReasons) { @($ia.EndpointReasons) } else { @() }
                $summaryReason = if (($ia -is [hashtable]) -and $ia.ContainsKey('BaseReason') -and $ia.BaseReason) { $ia.BaseReason } else { $ia.Reason }

                & $writeLogLocal "  - Ignored audio controller -> PNPID='$($ia.PNPID)' Path='$($ia.Path)' Desc='$($ia.Desc)'"
                if ($endpointNameList.Count -gt 0) {
                    & $writeLogLocal "    EndpointNames:"
                    foreach ($epName in $endpointNameList) {
                        & $writeLogLocal "      - '$epName'"
                    }
                } else {
                    & $writeLogLocal "    EndpointNames: <none>"
                }
                & $writeLogLocal "    Reason: $summaryReason"
                if ($endpointReasons.Count -gt 0) {
                    & $writeLogLocal "    Checked AudioEndpoint(s): Count=$($endpointReasons.Count)"
                    foreach ($epR in $endpointReasons) {
                        & $writeLogLocal "      - $epR"
                    }
                }
            }
        }
    } catch {}

    if (-not $script:DisableLogs -and $logBuffer.Count -gt 0 -and $logFile) {
        try { Queue-DeviceTweakerLogText -Path $logFile -Text (($logBuffer -join [Environment]::NewLine) + [Environment]::NewLine) } catch {}
    }

    return @{
        GPU   = $gpuDevices.ToArray()
        Audio = $audioDevices.ToArray()
    }
}
function Get-NetworkAdapters {
    param([switch]$ReturnLogEnvelope)

    $startupPayload = Get-DeviceTweakerStartupModel
    if ($startupPayload -and $startupPayload.NetworkAdapterRows -and $startupPayload.NetworkAdapterRows.Count -gt 0) {
        $rows = @($startupPayload.NetworkAdapterRows)
        $logs = @()
        try { if ($startupPayload.NetworkSourceLogs) { $logs = @($startupPayload.NetworkSourceLogs); $script:_cachedNetworkNativeDiscoveryLogs = $logs } } catch { $logs = @() }
        if ($ReturnLogEnvelope) {
            return [PSCustomObject]@{
                __DeviceTweakerNetworkAdapterEnvelope = $true
                Devices = $rows
                Logs    = $logs
            }
        }
        if (-not $script:DisableLogs -and $logs.Count -gt 0 -and $script:cachedLogFile) {
            try {
                $_netStartupBuffer = [System.Collections.Generic.List[string]]::new()
                $_netStartupTs = Get-Date
                foreach ($_line in $logs) { if ($null -ne $_line -and -not [string]::IsNullOrWhiteSpace([string]$_line)) { Add-DeviceTweakerFormattedLogEntry -Buffer $_netStartupBuffer -Timestamp $_netStartupTs -Text ([string]$_line) } }
                if ($_netStartupBuffer.Count -gt 0) { Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($_netStartupBuffer -join [Environment]::NewLine) + [Environment]::NewLine) }
            } catch {}
        }
        return $rows
    }

    $logFile = if (-not $script:DisableLogs) { $script:cachedLogFile } else { $null }

    $logBuffer = if (-not $script:DisableLogs) { [System.Collections.Generic.List[string]]::new() } else { $null }
    $_netLogTs = if (-not $script:DisableLogs) { Get-Date } else { $null }
    $writeLogLocal = {
        param($txt)
        if ($script:DisableLogs -or $null -eq $logBuffer) { return }
        Add-DeviceTweakerFormattedLogEntry -Buffer $logBuffer -Timestamp $_netLogTs -Text $txt
    }.GetNewClosure()

    function Complete-NetworkAdapterResult {
        param([AllowNull()][object[]]$Devices)

        $deviceArray = if ($null -eq $Devices) { @() } else { @($Devices) }

        if ($ReturnLogEnvelope) {
            $logArray = if ($script:DisableLogs -or $null -eq $logBuffer) { @() } else { @($logBuffer.ToArray()) }
            return [PSCustomObject]@{
                __DeviceTweakerNetworkAdapterEnvelope = $true
                Devices = $deviceArray
                Logs    = $logArray
            }
        }

        if (-not $script:DisableLogs -and $null -ne $logBuffer -and $logBuffer.Count -gt 0 -and $logFile) {
            try { Queue-DeviceTweakerLogText -Path $logFile -Text (($logBuffer -join [Environment]::NewLine) + [Environment]::NewLine) } catch {}
        }

        return $deviceArray
    }

    function Format-NetworkLogValue {
        param(
            [AllowNull()][object]$Value,
            [switch]$Quote
        )

        $text = if ($null -eq $Value) { '' } else { [string]$Value }
        $text = $text.Trim()

        if ([string]::IsNullOrWhiteSpace($text)) { return '<empty>' }
        if ($Quote) { return "'$text'" }

        return $text
    }

    function Get-NetworkAdapterStatusText {
        param([AllowNull()][object]$Adapter)

        if ($null -eq $Adapter) { return '<empty>' }

        foreach ($propertyName in @('Status', 'InterfaceOperationalStatus', 'OperationalStatus', 'AdminStatus', 'MediaConnectionState')) {
            try {
                $property = $Adapter.PSObject.Properties[$propertyName]
                if ($null -eq $property -or $null -eq $property.Value) { continue }

                $values = @($property.Value) | Where-Object {
                    $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_)
                }

                if ($values.Count -gt 0) {
                    return (($values | ForEach-Object { ([string]$_).Trim() }) -join '/')
                }
            } catch {}
        }

        return '<empty>'
    }

    function ConvertTo-NetworkAdapterNdisUInt32 {
        param([AllowNull()][object]$Value)

        if ($null -eq $Value) { return $null }

        $candidate = $Value
        if ($candidate -is [array]) {
            $candidate = @($candidate | Where-Object { $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -First 1)
            if ($candidate -is [array]) { $candidate = $candidate[0] }
        }

        if ($null -eq $candidate) { return $null }

        try { return [uint32]$candidate } catch {}

        $text = ([string]$candidate).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return $null }
        if ($text -match '^(?i:<none>|none|<empty>|unknown|otherorunknown)$') { return $null }
        if ($text -match '^\d+$') { try { return [uint32]$text } catch {} }
        if ($text -match '(?i)NdisMediumNative802_11') { return [uint32]16 }
        if ($text -match '(?i)NdisPhysicalMediumNative802_11') { return [uint32]9 }
        if ($text -match '(?i)Native802_11') { return [uint32]9 }
        if ($text -match '(?i)WirelessLan') { return [uint32]1 }
        if ($text -match '(?i)Bluetooth') { return [uint32]10 }
        if ($text -match '(?i)WirelessWan') { return [uint32]8 }
        if ($text -match '(?i)WiMax') { return [uint32]12 }

        return $null
    }

    function Format-NetworkAdapterNdisValue {
        param([AllowNull()][object]$Value)

        $number = ConvertTo-NetworkAdapterNdisUInt32 -Value $Value
        if ($null -ne $number) { return ([string]$number) }

        if ($null -eq $Value) { return '' }
        $text = ([string]$Value).Trim()
        if ([string]::IsNullOrWhiteSpace($text)) { return '' }
        if ($text -match '^(?i:<none>|none|<empty>|unknown|otherorunknown)$') { return '' }

        return $text
    }

    function Get-NetworkAdapterPhysicalMediaKind {
        param(
            [AllowNull()][object]$NdisPhysicalMedium,
            [AllowNull()][object]$NdisMedium
        )

        $physical = ConvertTo-NetworkAdapterNdisUInt32 -Value $NdisPhysicalMedium
        if ($null -ne $physical) {
            switch ([uint32]$physical) {
                1  { return 'WiFi' }
                9  { return 'WiFi' }
                14 { return 'WiredEthernet' }
                10 { return 'Bluetooth' }
                8  { return 'WirelessWAN' }
                12 { return 'WiMAX' }
            }
        }

        $medium = ConvertTo-NetworkAdapterNdisUInt32 -Value $NdisMedium
        if ($null -ne $medium) {
            if ([uint32]$medium -eq 16) { return 'WiFi' }
            if ([uint32]$medium -eq 0) { return 'EthernetOrUnknown' }
        }

        return 'OtherOrUnknown'
    }

    function Test-NetworkAdapterWeakMediaKind {
        param([AllowNull()][string]$Kind)
        return ([string]::IsNullOrWhiteSpace([string]$Kind) -or [string]::Equals([string]$Kind, 'OtherOrUnknown', [System.StringComparison]::OrdinalIgnoreCase) -or [string]::Equals([string]$Kind, 'EthernetOrUnknown', [System.StringComparison]::OrdinalIgnoreCase))
    }

    function Get-NetworkAdapterKindFromAdapterTypeId {
        param([AllowNull()][object]$AdapterTypeId)

        $typeId = ConvertTo-NetworkAdapterNdisUInt32 -Value $AdapterTypeId
        if ($null -ne $typeId) {
            switch ([uint32]$typeId) {
                9  { return 'WiFi' }
                0  { return 'WiredEthernet' }
                3  { return 'WirelessWAN' }
                10 { return 'Bluetooth' }
            }
        }

        return ''
    }

    function Get-NetworkAdapterResolvedMediaKind {
        param(
            [AllowNull()][object]$NdisPhysicalMedium,
            [AllowNull()][object]$NdisMedium,
            [AllowNull()][object]$AdapterTypeId
        )

        $kind = Get-NetworkAdapterPhysicalMediaKind -NdisPhysicalMedium $NdisPhysicalMedium -NdisMedium $NdisMedium
        if (-not (Test-NetworkAdapterWeakMediaKind -Kind $kind)) { return $kind }

        $adapterTypeKind = Get-NetworkAdapterKindFromAdapterTypeId -AdapterTypeId $AdapterTypeId
        if (-not [string]::IsNullOrWhiteSpace($adapterTypeKind)) { return $adapterTypeKind }

        if ([string]::Equals($kind, 'EthernetOrUnknown', [System.StringComparison]::OrdinalIgnoreCase)) { return 'WiredEthernet' }
        return 'OtherOrUnknown'
    }

    function Resolve-NetworkAdapterMediaValues {
        param(
            [AllowNull()][object]$NdisPhysicalMedium,
            [AllowNull()][object]$NdisMedium,
            [AllowNull()][object]$AdapterTypeId
        )

        $physical = Format-NetworkAdapterNdisValue -Value $NdisPhysicalMedium
        $medium = Format-NetworkAdapterNdisValue -Value $NdisMedium
        $source = if (-not [string]::IsNullOrWhiteSpace($physical) -or -not [string]::IsNullOrWhiteSpace($medium)) { 'MSFT_NetAdapter' } else { '' }

        $typeId = ConvertTo-NetworkAdapterNdisUInt32 -Value $AdapterTypeId
        if ([string]::IsNullOrWhiteSpace($physical) -or [string]::IsNullOrWhiteSpace($medium)) {
            if ($null -ne $typeId -and [uint32]$typeId -eq 9) {
                if ([string]::IsNullOrWhiteSpace($physical)) { $physical = '9' }
                if ([string]::IsNullOrWhiteSpace($medium)) { $medium = '16' }
                $source = 'Derived:Win32_NetworkAdapter.AdapterTypeID=9'
            } elseif ($null -ne $typeId -and [uint32]$typeId -eq 0) {
                if ([string]::IsNullOrWhiteSpace($physical)) { $physical = '14' }
                if ([string]::IsNullOrWhiteSpace($medium)) { $medium = '0' }
                $source = 'Derived:Win32_NetworkAdapter.AdapterTypeID=0'
            }
        }

        $kind = Get-NetworkAdapterResolvedMediaKind -NdisPhysicalMedium $physical -NdisMedium $medium -AdapterTypeId $AdapterTypeId
        if ([string]::IsNullOrWhiteSpace($source) -and (-not [string]::IsNullOrWhiteSpace($physical) -or -not [string]::IsNullOrWhiteSpace($medium))) { $source = 'MSFT_NetAdapter' }

        return [PSCustomObject]@{
            Kind               = $kind
            NdisPhysicalMedium = $physical
            NdisMedium         = $medium
            Source             = $source
        }
    }

    function New-NetworkAdapterDisplayBase {
        param(
            [AllowNull()][object]$DriverType,
            [AllowNull()][object]$AdapterKind
        )

        $driver = if ([string]::Equals([string]$DriverType, 'NetAdapterCx', [System.StringComparison]::OrdinalIgnoreCase)) { 'NetAdapterCx' } else { 'NDIS' }
        $kind = if ([string]::IsNullOrWhiteSpace([string]$AdapterKind)) { 'OtherOrUnknown' } else { ([string]$AdapterKind).Trim() }

        return "Network Interface Card ($driver $kind)"
    }

    function Get-NetworkAdapterObjectProperty {
        param(
            [AllowNull()][object]$InputObject,
            [Parameter(Mandatory=$true)][string]$PropertyName
        )

        if ($null -eq $InputObject) { return $null }
        try {
            $property = $InputObject.PSObject.Properties[$PropertyName]
            if ($null -eq $property) { return $null }
            return $property.Value
        } catch {
            return $null
        }
    }

    function Write-NetworkKeyValueLogBlock {
        param(
            [string]$Title,
            [System.Collections.IDictionary]$Fields
        )

        if ($script:DisableLogs) { return }
        if ([string]::IsNullOrWhiteSpace($Title)) { return }

        & $writeLogLocal ("${Title}:")
        if (-not $Fields -or $Fields.Count -eq 0) { return }

        $maxKeyLength = 0
        foreach ($key in $Fields.Keys) {
            $keyText = [string]$key
            if ($keyText.Length -gt $maxKeyLength) { $maxKeyLength = $keyText.Length }
        }

        foreach ($key in $Fields.Keys) {
            $keyText = [string]$key
            $valueText = [string]$Fields[$key]
            if ([string]::IsNullOrWhiteSpace($valueText)) { $valueText = '<empty>' }
            & $writeLogLocal ("  {0,-$maxKeyLength} : {1}" -f $keyText, $valueText)
        }
    }

    function Resolve-DriverImagePath {
        param([string]$ImagePath)
        if ([string]::IsNullOrWhiteSpace($ImagePath)) { return $null }
        $resolvedPath = $ImagePath
        if ($resolvedPath -like '\SystemRoot*') {
            $resolvedPath = $resolvedPath -replace '^\\SystemRoot', $env:SystemRoot
        } elseif ($resolvedPath -like 'System32*') {
            $resolvedPath = Join-Path $env:SystemRoot $resolvedPath
        } elseif ($resolvedPath -match '^\\??\\') {
            $resolvedPath = $resolvedPath -replace '^\\??\\', ''
        }
        $resolvedPath = $resolvedPath -replace '%SystemRoot%', $env:SystemRoot
        return $resolvedPath
    }

    function Get-DriverTypeFromBinary {
        param([string]$ResolvedPath)

        if ([string]::IsNullOrWhiteSpace($ResolvedPath) -or -not [System.IO.File]::Exists($ResolvedPath)) {
            return 'NDIS'
        }

        try {
            $fileLen = ([System.IO.FileInfo]::new($ResolvedPath)).Length
            $bytesToRead = [Math]::Min($fileLen, 1048576)
            $bytes = [byte[]]::new($bytesToRead)
            $stream = [System.IO.File]::Open($ResolvedPath, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            try {
                $offset = 0
                while ($offset -lt $bytesToRead) {
                    $read = $stream.Read($bytes, $offset, $bytesToRead - $offset)
                    if ($read -le 0) { break }
                    $offset += $read
                }
            } finally { $stream.Dispose() }
            $text = [System.Text.Encoding]::ASCII.GetString($bytes, 0, $offset)
            if ($text.IndexOf('NetAdapter', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return 'NetAdapterCx' }
            if ($text.IndexOf('NDIS.SYS', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { return 'NDIS' }
        } catch {
            & $writeLogLocal "Get-NetworkAdapters: Error reading driver file '$ResolvedPath' : $_"
        }

        return 'NDIS'
    }

    $out = [System.Collections.Generic.List[object]]::new()

    $physicalAdapters = @()
    $physicalAdapterSource = 'Get-NetAdapter -Physical'

    try {
        $physicalAdapters = @(Get-NetAdapter -Physical -ErrorAction Stop)
    } catch {
        & $writeLogLocal "Get-NetworkAdapters: Get-NetAdapter -Physical failed: $_"
        $physicalAdapterSource = 'MSFT_NetAdapter Virtual=False fallback'
        try {
            $physicalAdapters = @(Get-CimInstance -Namespace root/StandardCimv2 -Query "SELECT InterfaceDescription, Name, Status, InterfaceOperationalStatus, AdminStatus, NdisPhysicalMedium, NdisMedium, InterfaceIndex, PNPDeviceID FROM MSFT_NetAdapter WHERE Virtual=False" -ErrorAction SilentlyContinue)
        } catch {
            & $writeLogLocal "Get-NetworkAdapters: MSFT_NetAdapter fallback failed: $_"
            $physicalAdapters = @()
        }
    }

    if ($physicalAdapters.Count -eq 0 -and $physicalAdapterSource -eq 'Get-NetAdapter -Physical') {
        $physicalAdapterSource = 'MSFT_NetAdapter Virtual=False fallback'
        try {
            $physicalAdapters = @(Get-CimInstance -Namespace root/StandardCimv2 -Query "SELECT InterfaceDescription, Name, Status, InterfaceOperationalStatus, AdminStatus, NdisPhysicalMedium, NdisMedium, InterfaceIndex, PNPDeviceID FROM MSFT_NetAdapter WHERE Virtual=False" -ErrorAction SilentlyContinue)
        } catch {
            & $writeLogLocal "Get-NetworkAdapters: MSFT_NetAdapter fallback failed: $_"
            $physicalAdapters = @()
        }
    }

    $cimPhysicalAdapters = @()
    $cimPhysicalByName = @{}
    $cimPhysicalByPnpId = @{}
    try {
        $cimPhysicalAdapters = @(Get-CimInstance -Namespace root/StandardCimv2 -Query "SELECT InterfaceDescription, Name, Status, InterfaceOperationalStatus, AdminStatus, NdisPhysicalMedium, NdisMedium, InterfaceIndex, PNPDeviceID FROM MSFT_NetAdapter WHERE Virtual=False" -ErrorAction Stop)
        foreach ($_cimPa in $cimPhysicalAdapters) {
            $_cimInterface = [string](Get-NetworkAdapterObjectProperty -InputObject $_cimPa -PropertyName 'InterfaceDescription')
            $_cimName = [string](Get-NetworkAdapterObjectProperty -InputObject $_cimPa -PropertyName 'Name')
            $_cimPnp = [string](Get-NetworkAdapterObjectProperty -InputObject $_cimPa -PropertyName 'PNPDeviceID')
            if (-not [string]::IsNullOrWhiteSpace($_cimInterface) -and -not $cimPhysicalByName.ContainsKey($_cimInterface)) { $cimPhysicalByName[$_cimInterface] = $_cimPa }
            if (-not [string]::IsNullOrWhiteSpace($_cimName) -and -not $cimPhysicalByName.ContainsKey($_cimName)) { $cimPhysicalByName[$_cimName] = $_cimPa }
            if (-not [string]::IsNullOrWhiteSpace($_cimPnp) -and -not $cimPhysicalByPnpId.ContainsKey($_cimPnp)) { $cimPhysicalByPnpId[$_cimPnp] = $_cimPa }
        }
    } catch {
        & $writeLogLocal "Get-NetworkAdapters: MSFT_NetAdapter NDIS media overlay failed: $_"
    }

    & $writeLogLocal "Get-NetworkAdapters: $physicalAdapterSource returned $($physicalAdapters.Count) adapter(s)"

    if ($physicalAdapters.Count -eq 0) {
        & $writeLogLocal "Get-NetworkAdapters: No physical adapters found via MSFT_NetAdapter Virtual=False or Get-NetAdapter -Physical. Returning empty."
        return (Complete-NetworkAdapterResult -Devices @())
    }

    $win32NetAdapterRows = [System.Collections.Generic.List[object]]::new()
    $win32NetAdapterByName = @{}
    $win32NetAdapterByPnpId = @{}
    try {
        $_wmiSearcherFull = [System.Management.ManagementObjectSearcher]::new("SELECT Name, PNPDeviceID, AdapterTypeID, NetConnectionID, Description FROM Win32_NetworkAdapter")
        $_wmiSearcherFull.Options.ReturnImmediately = $true
        $_wmiSearcherFull.Options.Rewindable = $false
        foreach ($_mo in $_wmiSearcherFull.Get()) {
            $_row = [PSCustomObject]@{
                Name            = [string]$_mo['Name']
                PNPDeviceID     = [string]$_mo['PNPDeviceID']
                AdapterTypeID   = [string]$_mo['AdapterTypeID']
                NetConnectionID = [string]$_mo['NetConnectionID']
                Description     = [string]$_mo['Description']
            }
            [void]$win32NetAdapterRows.Add($_row)
            if (-not [string]::IsNullOrWhiteSpace($_row.PNPDeviceID) -and -not $win32NetAdapterByPnpId.ContainsKey($_row.PNPDeviceID)) { $win32NetAdapterByPnpId[$_row.PNPDeviceID] = $_row }
            foreach ($_n in @($_row.Name, $_row.Description, $_row.NetConnectionID)) {
                if (-not [string]::IsNullOrWhiteSpace([string]$_n) -and -not $win32NetAdapterByName.ContainsKey([string]$_n)) { $win32NetAdapterByName[[string]$_n] = $_row }
            }
        }
        $_wmiSearcherFull.Dispose()
    } catch {
        & $writeLogLocal "Get-NetworkAdapters: Win32_NetworkAdapter media fallback query failed: $_"
    }

    $physicalDescSet = @{}
    $physicalInfoByName = @{}
    $physicalInfoByPnpId = @{}
    foreach ($pa in $physicalAdapters) {
        $paInterfaceDescriptionRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'InterfaceDescription'
        $paNameRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'Name'
        $paPnpRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'PNPDeviceID'
        if ([string]::IsNullOrWhiteSpace([string]$paPnpRaw)) { $paPnpRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'PnPDeviceID' }

        $paInterfaceDescription = if ([string]::IsNullOrWhiteSpace([string]$paInterfaceDescriptionRaw)) { ([string]$paNameRaw).Trim() } else { ([string]$paInterfaceDescriptionRaw).Trim() }
        $paName = if ([string]::IsNullOrWhiteSpace([string]$paNameRaw)) { $paInterfaceDescription } else { ([string]$paNameRaw).Trim() }
        $paPnpDeviceId = if ($null -eq $paPnpRaw) { '' } else { ([string]$paPnpRaw).Trim() }

        $overlay = $null
        if (-not [string]::IsNullOrWhiteSpace($paPnpDeviceId) -and $cimPhysicalByPnpId.ContainsKey($paPnpDeviceId)) { $overlay = $cimPhysicalByPnpId[$paPnpDeviceId] }
        if ($null -eq $overlay -and -not [string]::IsNullOrWhiteSpace($paInterfaceDescription) -and $cimPhysicalByName.ContainsKey($paInterfaceDescription)) { $overlay = $cimPhysicalByName[$paInterfaceDescription] }
        if ($null -eq $overlay -and -not [string]::IsNullOrWhiteSpace($paName) -and $cimPhysicalByName.ContainsKey($paName)) { $overlay = $cimPhysicalByName[$paName] }

        $ndisPhysicalMediumRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'NdisPhysicalMedium'
        $ndisMediumRaw = Get-NetworkAdapterObjectProperty -InputObject $pa -PropertyName 'NdisMedium'
        if ($null -ne $overlay) {
            if ($null -eq (ConvertTo-NetworkAdapterNdisUInt32 -Value $ndisPhysicalMediumRaw)) { $ndisPhysicalMediumRaw = Get-NetworkAdapterObjectProperty -InputObject $overlay -PropertyName 'NdisPhysicalMedium' }
            if ($null -eq (ConvertTo-NetworkAdapterNdisUInt32 -Value $ndisMediumRaw)) { $ndisMediumRaw = Get-NetworkAdapterObjectProperty -InputObject $overlay -PropertyName 'NdisMedium' }
            if ([string]::IsNullOrWhiteSpace($paPnpDeviceId)) {
                $overlayPnp = Get-NetworkAdapterObjectProperty -InputObject $overlay -PropertyName 'PNPDeviceID'
                if (-not [string]::IsNullOrWhiteSpace([string]$overlayPnp)) { $paPnpDeviceId = ([string]$overlayPnp).Trim() }
            }
        }

        $win32Overlay = $null
        if (-not [string]::IsNullOrWhiteSpace($paPnpDeviceId) -and $win32NetAdapterByPnpId.ContainsKey($paPnpDeviceId)) { $win32Overlay = $win32NetAdapterByPnpId[$paPnpDeviceId] }
        if ($null -eq $win32Overlay -and -not [string]::IsNullOrWhiteSpace($paInterfaceDescription) -and $win32NetAdapterByName.ContainsKey($paInterfaceDescription)) { $win32Overlay = $win32NetAdapterByName[$paInterfaceDescription] }
        if ($null -eq $win32Overlay -and -not [string]::IsNullOrWhiteSpace($paName) -and $win32NetAdapterByName.ContainsKey($paName)) { $win32Overlay = $win32NetAdapterByName[$paName] }

        $mediaResolution = Resolve-NetworkAdapterMediaValues -NdisPhysicalMedium $ndisPhysicalMediumRaw -NdisMedium $ndisMediumRaw -AdapterTypeId (Get-NetworkAdapterObjectProperty -InputObject $win32Overlay -PropertyName 'AdapterTypeID')
        $ndisPhysicalMedium = $mediaResolution.NdisPhysicalMedium
        $ndisMedium = $mediaResolution.NdisMedium
        $adapterKind = $mediaResolution.Kind
        $ndisMediaSource = $mediaResolution.Source
        $paStatus = Get-NetworkAdapterStatusText -Adapter $pa
        if (($paStatus -eq '<empty>') -and $null -ne $overlay) { $paStatus = Get-NetworkAdapterStatusText -Adapter $overlay }

        $physicalInfo = [PSCustomObject]@{
            InterfaceDescription = $paInterfaceDescription
            Name                 = $paName
            PNPDeviceID          = $paPnpDeviceId
            Status               = $paStatus
            NetworkAdapterKind   = $adapterKind
            NdisPhysicalMedium   = $ndisPhysicalMedium
            NdisMedium           = $ndisMedium
            NdisMediaSource      = $ndisMediaSource
        }

        if (-not [string]::IsNullOrWhiteSpace($paInterfaceDescription)) {
            $physicalDescSet[$paInterfaceDescription] = $true
            if (-not $physicalInfoByName.ContainsKey($paInterfaceDescription)) { $physicalInfoByName[$paInterfaceDescription] = $physicalInfo }
        }
        if (-not [string]::IsNullOrWhiteSpace($paName)) {
            $physicalDescSet[$paName] = $true
            if (-not $physicalInfoByName.ContainsKey($paName)) { $physicalInfoByName[$paName] = $physicalInfo }
        }
        if (-not [string]::IsNullOrWhiteSpace($paPnpDeviceId) -and -not $physicalInfoByPnpId.ContainsKey($paPnpDeviceId)) { $physicalInfoByPnpId[$paPnpDeviceId] = $physicalInfo }

        $paInterfaceLog = Format-NetworkLogValue -Value $paInterfaceDescription -Quote
        $paNameLog = Format-NetworkLogValue -Value $paName -Quote
        $paPnpLog = Format-NetworkLogValue -Value $paPnpDeviceId -Quote
        $paStatusLog = Format-NetworkLogValue -Value $paStatus
        $paKindLog = Format-NetworkLogValue -Value $adapterKind -Quote
        $paNdisPhysicalLog = Format-NetworkLogValue -Value $ndisPhysicalMedium -Quote
        $paNdisMediumLog = Format-NetworkLogValue -Value $ndisMedium -Quote
        $paNdisSourceLog = Format-NetworkLogValue -Value $ndisMediaSource -Quote
        & $writeLogLocal "  Physical adapter: InterfaceDescription=$paInterfaceLog Name=$paNameLog PNPDeviceID=$paPnpLog Status=$paStatusLog Type=$paKindLog NdisPhysicalMedium=$paNdisPhysicalLog NdisMedium=$paNdisMediumLog NdisMediaSource=$paNdisSourceLog"
    }

    $driverByRegPath = @{}
    $serviceByDriver = @{}
    $driverFileInfoCache = @{}
    $allNetAdapters = [System.Collections.Generic.List[object]]::new()
    foreach ($_row in $win32NetAdapterRows) { [void]$allNetAdapters.Add($_row) }
    $_netSkippedCount = 0
    foreach ($adapter in $allNetAdapters) {
        if (-not $adapter.PNPDeviceID) {
            & $writeLogLocal "Get-NetworkAdapters: Adapter IGNORED: Name='$($adapter.Name)' | Reason: No PNPDeviceID available (virtual or incomplete device)"
            $_netSkippedCount++
            continue
        }

        $adapterName = if ($null -ne $adapter.Name) { ([string]$adapter.Name).Trim() } else { $null }
        $pnpDeviceId = if ($null -ne $adapter.PNPDeviceID) { ([string]$adapter.PNPDeviceID).Trim() } else { $null }

        $physicalInfo = $null
        if (-not [string]::IsNullOrWhiteSpace($pnpDeviceId) -and $physicalInfoByPnpId.ContainsKey($pnpDeviceId)) { $physicalInfo = $physicalInfoByPnpId[$pnpDeviceId] }
        if ($null -eq $physicalInfo -and -not [string]::IsNullOrWhiteSpace($adapterName) -and $physicalInfoByName.ContainsKey($adapterName)) { $physicalInfo = $physicalInfoByName[$adapterName] }
        if ($null -eq $physicalInfo) {
            & $writeLogLocal "Get-NetworkAdapters: Adapter IGNORED: Name='$adapterName' PNPDeviceID='$pnpDeviceId' | Reason: Not present in MSFT_NetAdapter Virtual=False (virtual/software adapter)"
            $_netSkippedCount++
            continue
        }

        $win32Info = $null
        if (-not [string]::IsNullOrWhiteSpace($pnpDeviceId) -and $win32NetAdapterByPnpId.ContainsKey($pnpDeviceId)) { $win32Info = $win32NetAdapterByPnpId[$pnpDeviceId] }
        if ($null -eq $win32Info -and -not [string]::IsNullOrWhiteSpace($adapterName) -and $win32NetAdapterByName.ContainsKey($adapterName)) { $win32Info = $win32NetAdapterByName[$adapterName] }
        $mediaResolution = Resolve-NetworkAdapterMediaValues -NdisPhysicalMedium $physicalInfo.NdisPhysicalMedium -NdisMedium $physicalInfo.NdisMedium -AdapterTypeId (Get-NetworkAdapterObjectProperty -InputObject $win32Info -PropertyName 'AdapterTypeID')
        $adapterKind = $mediaResolution.Kind
        $ndisPhysicalMedium = $mediaResolution.NdisPhysicalMedium
        $ndisMedium = $mediaResolution.NdisMedium
        $ndisMediaSource = $mediaResolution.Source

        & $writeLogLocal "Get-NetworkAdapters: '$adapterName' matched adapter candidate (physical identity is checked before writes)"

        $regPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$pnpDeviceId"
        $driver = $driverByRegPath[$regPath]
        if ($null -eq $driver) {
            $_rk = $null
            try {
                $_rk = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SYSTEM\CurrentControlSet\Enum\$pnpDeviceId", $false)
                if ($_rk) { $driver = $_rk.GetValue("Driver") }
            } catch {} finally { if ($_rk) { $_rk.Dispose() } }
            $driverByRegPath[$regPath] = $driver
        }
        if (-not $driver) {
            & $writeLogLocal "Get-NetworkAdapters: Adapter IGNORED: Name='$adapterName' PNPDeviceID='$pnpDeviceId' | Reason: No 'Driver' registry value found at '$regPath'"
            $_netSkippedCount++
            continue
        }

        $serviceName = $serviceByDriver[$driver]
        if ($null -eq $serviceName) {
            $_rk2 = $null
            try {
                $_rk2 = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SYSTEM\CurrentControlSet\Control\Class\$driver\Ndi", $false)
                if ($_rk2) { $serviceName = $_rk2.GetValue("Service") }
            } catch {} finally { if ($_rk2) { $_rk2.Dispose() } }
            if ($serviceName) { $serviceName = $serviceName.TrimEnd('.') }
            $serviceByDriver[$driver] = $serviceName
        }
        if (-not $serviceName) {
            & $writeLogLocal "Get-NetworkAdapters: Adapter IGNORED: Name='$adapterName' PNPDeviceID='$pnpDeviceId' Driver='$driver' | Reason: No Ndi\\Service registry value found"
            $_netSkippedCount++
            continue
        }

        $serviceRegPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$serviceName"

        $imagePath = $null
        $resolvedPath = $null
        $driverType = "NDIS"
        $fileDescription = $null

        if ($driverFileInfoCache.ContainsKey($serviceRegPath)) {
            $cachedInfo = $driverFileInfoCache[$serviceRegPath]
            $imagePath = $cachedInfo.ImagePath
            $resolvedPath = $cachedInfo.ResolvedPath
            $driverType = $cachedInfo.DriverType
            $fileDescription = $cachedInfo.FileDescription
        } else {
            $_rk3 = $null
            try {
                $_rk3 = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SYSTEM\CurrentControlSet\Services\$serviceName", $false)
                if ($_rk3) { $imagePath = $_rk3.GetValue("ImagePath") }
            } catch {} finally { if ($_rk3) { $_rk3.Dispose() } }
            $resolvedPath = Resolve-DriverImagePath $imagePath

            if ($resolvedPath -and [System.IO.File]::Exists($resolvedPath)) {
                try {
                    $fileDescription = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($resolvedPath).FileDescription
                    if ($null -ne $fileDescription) { $fileDescription = ([string]$fileDescription).Trim() }
                } catch {
                    $fileDescription = $null
                }
                $driverType = Get-DriverTypeFromBinary $resolvedPath
            } else {
                & $writeLogLocal "Get-NetworkAdapters: Could not resolve driver path for $adapterName, defaulting to NDIS"
            }

            $driverFileInfoCache[$serviceRegPath] = @{
                ImagePath       = $imagePath
                ResolvedPath    = $resolvedPath
                DriverType      = $driverType
                FileDescription = $fileDescription
            }
        }

        if ($null -ne $imagePath) { $imagePath = ([string]$imagePath).Trim() }
        if ($null -ne $resolvedPath) { $resolvedPath = ([string]$resolvedPath).Trim() }
        if ($null -ne $driverType) { $driverType = ([string]$driverType).Trim() }
        if ($null -ne $fileDescription) { $fileDescription = ([string]$fileDescription).Trim() }

        $classPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\$driver"

        $mediaResolution = Resolve-NetworkAdapterMediaValues -NdisPhysicalMedium $ndisPhysicalMedium -NdisMedium $ndisMedium -AdapterTypeId (Get-NetworkAdapterObjectProperty -InputObject $win32Info -PropertyName 'AdapterTypeID')
        $adapterKind = $mediaResolution.Kind
        $ndisPhysicalMedium = $mediaResolution.NdisPhysicalMedium
        $ndisMedium = $mediaResolution.NdisMedium
        if (-not [string]::IsNullOrWhiteSpace([string]$mediaResolution.Source)) { $ndisMediaSource = $mediaResolution.Source }

        $displayBase = New-NetworkAdapterDisplayBase -DriverType $driverType -AdapterKind $adapterKind


        $pnpId = $null
        try { $pnpId = Get-PNPId $regPath } catch { $pnpId = $pnpDeviceId }
        if ([string]::IsNullOrWhiteSpace([string]$pnpId)) { $pnpId = $pnpDeviceId }

        $resolvedAdapterName = Resolve-DeviceTweakerPciDisplayName -InstanceId $pnpDeviceId -RegistryPath $regPath -WindowsName $adapterName -Role 'Network'
        if ([string]::IsNullOrWhiteSpace([string]$resolvedAdapterName)) { $resolvedAdapterName = $adapterName }

        $display = if ([string]::IsNullOrWhiteSpace([string]$resolvedAdapterName)) { $displayBase } else { "$displayBase - $resolvedAdapterName" }

        $out.Add([PSCustomObject]@{
            Category            = 'Network'
            Role                = $driverType
            NetworkAdapterKind  = $adapterKind
            Type                = $adapterKind
            NdisPhysicalMedium  = $ndisPhysicalMedium
            NdisMedium          = $ndisMedium
            NdisMediaSource     = $ndisMediaSource
            DisplayName         = $display
            RegistryPath        = $classPath
            Description         = $resolvedAdapterName
            OriginalDescription = $adapterName
            ConfigPath          = $regPath
            PNPID               = $pnpId
        })

        try {
            $networkFields = [ordered]@{
                Name               = (Format-NetworkLogValue -Value $adapterName -Quote)
                ResolvedName       = (Format-NetworkLogValue -Value $resolvedAdapterName -Quote)
                Role               = (Format-NetworkLogValue -Value $driverType -Quote)
                DriverType         = (Format-NetworkLogValue -Value $driverType -Quote)
                Type               = (Format-NetworkLogValue -Value $adapterKind -Quote)
                NdisPhysicalMedium = (Format-NetworkLogValue -Value $ndisPhysicalMedium -Quote)
                NdisMedium         = (Format-NetworkLogValue -Value $ndisMedium -Quote)
                NdisMediaSource    = (Format-NetworkLogValue -Value $ndisMediaSource -Quote)
                PNPID              = (Format-NetworkLogValue -Value $pnpId -Quote)
                ClassPath          = (Format-NetworkLogValue -Value $classPath -Quote)
                ConfigPath         = (Format-NetworkLogValue -Value $regPath -Quote)
                Service            = (Format-NetworkLogValue -Value $serviceRegPath -Quote)
                ImagePath          = (Format-NetworkLogValue -Value $imagePath -Quote)
                ResolvedPath       = (Format-NetworkLogValue -Value $resolvedPath -Quote)
                FileDescription    = (Format-NetworkLogValue -Value $fileDescription -Quote)
            }

            Write-NetworkKeyValueLogBlock -Title 'Get-NetworkAdapters: Detected network adapter' -Fields $networkFields
        } catch {}
    }

    try {
        & $writeLogLocal "Get-NetworkAdapters: Summary -> NetworkAdaptersDetected=$($out.Count) Win32NetworkAdapterTotal=$($allNetAdapters.Count) IgnoredSkipped=$_netSkippedCount"
        foreach ($a in $out) {
            & $writeLogLocal "  Detected Adapter: Name='$($a.Description)' OriginalName='$($a.OriginalDescription)' Role='$($a.Role)' Type='$($a.NetworkAdapterKind)' NdisPhysicalMedium='$($a.NdisPhysicalMedium)' NdisMedium='$($a.NdisMedium)' NdisMediaSource='$($a.NdisMediaSource)' ClassPath='$($a.RegistryPath)' ConfigPath='$($a.ConfigPath)'"
        }
    } catch {}

    return (Complete-NetworkAdapterResult -Devices ($out.ToArray()))
}


function Write-DeviceTweakerMechanicalDiscoveryAuditLog {
    param(
        [AllowNull()][object]$StartupModel,
        [AllowNull()][object]$UsbRows,
        [AllowNull()][object]$PciDevices,
        [AllowNull()][object]$NetworkRows
    )

    if ($script:DisableLogs) { return }
    if ([string]::IsNullOrWhiteSpace([string]$script:cachedLogFile)) { return }
    if (-not ('DeviceTweakerMechanicalDiscoveryLog' -as [type])) { return }

    try {
        $model = $null
        if ($StartupModel -and $StartupModel.PSObject.Properties['DiscoveryModel'] -and $StartupModel.DiscoveryModel) {
            $model = $StartupModel.DiscoveryModel
        }
        if ($null -eq $model) { $model = Get-DeviceTweakerDiscoveryModel }

        $gpuRows = @()
        $audioRows = @()
        if ($PciDevices) {
            try { if ($PciDevices.GPU) { $gpuRows = @($PciDevices.GPU) } } catch {}
            try { if ($PciDevices.Audio) { $audioRows = @($PciDevices.Audio) } } catch {}
        }

        $networkAuditRows = [System.Collections.Generic.List[object]]::new()
        foreach ($nr in @($NetworkRows)) {
            if ($null -eq $nr) { continue }
            $nrKind = if ($null -ne $nr.PSObject.Properties['NetworkAdapterKind']) { [string]$nr.NetworkAdapterKind } else { '' }
            $nrType = if ($null -ne $nr.PSObject.Properties['Type']) { [string]$nr.Type } elseif (-not [string]::IsNullOrWhiteSpace($nrKind)) { $nrKind } else { '' }
            $nrNdisPhysicalMedium = if ($null -ne $nr.PSObject.Properties['NdisPhysicalMedium']) { [string]$nr.NdisPhysicalMedium } else { '' }
            $nrNdisMedium = if ($null -ne $nr.PSObject.Properties['NdisMedium']) { [string]$nr.NdisMedium } else { '' }
            [void]$networkAuditRows.Add(@{
                DisplayName         = [string]$nr.DisplayName
                Role                = [string]$nr.Role
                NetworkAdapterKind  = $nrKind
                Type                = $nrType
                NdisPhysicalMedium  = $nrNdisPhysicalMedium
                NdisMedium          = $nrNdisMedium
                PNPID               = [string]$nr.PNPID
                RegistryPath        = [string]$nr.RegistryPath
                ConfigPath          = [string]$nr.ConfigPath
                Description         = [string]$nr.Description
                OriginalDescription = [string]$nr.OriginalDescription
            })
        }

        $storageAuditRows = [System.Collections.Generic.List[object]]::new()
        try {
            if ($StartupModel -and $StartupModel.PSObject.Properties['StorageRows'] -and $StartupModel.StorageRows) {
                foreach ($sr in @($StartupModel.StorageRows)) { if ($null -ne $sr) { [void]$storageAuditRows.Add($sr) } }
            }
        } catch {}

        $hidAuditRows = @()
        try { if ($script:_cachedHidDevices) { $hidAuditRows = @($script:_cachedHidDevices) } } catch { $hidAuditRows = @() }

        $usbSourceLogs = @()
        try { if ($script:_cachedUsbNativeDiscoveryLogs) { $usbSourceLogs = @($script:_cachedUsbNativeDiscoveryLogs) } } catch { $usbSourceLogs = @() }

        $pciSourceLogs = @()
        try { if ($script:_cachedPciNativeDiscoveryLogs) { $pciSourceLogs = @($script:_cachedPciNativeDiscoveryLogs) } } catch { $pciSourceLogs = @() }

        $storageSourceLogs = @()
        try {
            if ($script:_cachedStorageNativeDiscoveryLogText) {
                $storageSourceLogs = @(([string]$script:_cachedStorageNativeDiscoveryLogText).Replace("`r`n", "`n").Replace("`r", "`n") -split "`n" | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
            } elseif ($script:_cachedStorageNativeDiscoveryLogs) {
                $storageSourceLogs = @($script:_cachedStorageNativeDiscoveryLogs)
            }
        } catch { $storageSourceLogs = @() }

        $networkSourceLogs = @()
        try { if ($script:_cachedNetworkNativeDiscoveryLogs) { $networkSourceLogs = @($script:_cachedNetworkNativeDiscoveryLogs) } } catch { $networkSourceLogs = @() }

        $lines = [DeviceTweakerMechanicalDiscoveryLog]::BuildDiscoveryAuditLines($model, @($UsbRows), $gpuRows, $audioRows, $networkAuditRows.ToArray(), $storageAuditRows.ToArray(), $hidAuditRows, $usbSourceLogs, $pciSourceLogs, $storageSourceLogs, $networkSourceLogs)
        if ($null -eq $lines -or $lines.Count -eq 0) { return }

        $buffer = [System.Collections.Generic.List[string]]::new([Math]::Max(16, [int]$lines.Count))
        $ts = Get-Date
        foreach ($line in $lines) {
            if ($null -eq $line) { continue }
            $_lineText = [string]$line
            if ($_lineText.StartsWith('__DEVICE_TWEAKER_RAW_LOG_ENTRY_V1__|', [System.StringComparison]::Ordinal)) {
                [void]$buffer.Add($_lineText)
            } else {
                Add-DeviceTweakerFormattedLogEntry -Buffer $buffer -Timestamp $ts -Text $_lineText
            }
        }

        if ($buffer.Count -gt 0) {
            Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($buffer -join [Environment]::NewLine) + [Environment]::NewLine)
        }
    } catch {
        try {
            $fallback = [System.Collections.Generic.List[string]]::new()
            $ts = Get-Date
            Add-DeviceTweakerFormattedLogEntry -Buffer $fallback -Timestamp $ts -Text 'DeviceTweakerMechanicalDiscoveryLog: ERROR while producing mechanical discovery audit'
            Add-DeviceTweakerFormattedLogEntry -Buffer $fallback -Timestamp $ts -Text ("  Error : '{0}'" -f $_.Exception.Message)
            Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($fallback -join [Environment]::NewLine) + [Environment]::NewLine)
        } catch {}
    }
}

function Invoke-DeviceTweakerDeferredMechanicalDiscoveryAuditLog {
    if ($script:DeviceTweakerMechanicalStartupAuditQueued) { return }
    $script:DeviceTweakerMechanicalStartupAuditQueued = $true
    $script:DeviceTweakerMechanicalStartupAuditError = $null

    if ($script:DisableLogs -or -not $script:EnableMechanicalStartupAudit) { return }

    try {
        Write-DeviceTweakerMechanicalDiscoveryAuditLog -StartupModel $script:StartupModel -UsbRows $script:_startupUsbRows -PciDevices $script:_startupPciDevices -NetworkRows $script:_startupNetworkRows
        $script:DeviceTweakerMechanicalStartupAuditCompleted = $true
    } catch {
        $script:DeviceTweakerMechanicalStartupAuditCompleted = $false
        $script:DeviceTweakerMechanicalStartupAuditError = if ($_.Exception) { $_.Exception.ToString() } else { [string]$_ }
        try {
            if (-not $script:DisableLogs -and -not [string]::IsNullOrWhiteSpace([string]$script:cachedLogFile)) {
                $_auditFailureBuffer = [System.Collections.Generic.List[string]]::new()
                $_auditFailureTimestamp = Get-Date
                Add-DeviceTweakerFormattedLogEntry -Buffer $_auditFailureBuffer -Timestamp $_auditFailureTimestamp -Text 'DeviceTweakerMechanicalDiscoveryLog: deferred post-first-paint audit failed'
                Add-DeviceTweakerFormattedLogEntry -Buffer $_auditFailureBuffer -Timestamp $_auditFailureTimestamp -Text ("  Error : '{0}'" -f $script:DeviceTweakerMechanicalStartupAuditError)
                Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($_auditFailureBuffer -join [Environment]::NewLine) + [Environment]::NewLine)
            }
        } catch {}
    }
}


$_asyncNet = $null
$_asyncNetHandle = $null
$_asyncIrqCim = $null
$_asyncIrqCimHandle = $null
$_asyncDevAddr = $null
$_asyncDevAddrHandle = $null

$_sw_device_list = [System.Diagnostics.Stopwatch]::StartNew()
$startupModel = Measure-Function 'BuildStartupModel' { Get-DeviceTweakerStartupModel }

$deviceList = [System.Collections.Generic.List[object]]::new()
$_usbResult = Measure-Function 'Get-USBControllersNative' { Get-USBControllersNative }
if ($_usbResult) { foreach ($d in @($_usbResult)) { $deviceList.Add($d) } }

$pciDevices = Measure-Function 'Get-PCIDevicesNative' { Get-PCIDevicesNative }
if ($pciDevices.GPU) { foreach ($d in @($pciDevices.GPU)) { $deviceList.Add($d) } }
if ($pciDevices.Audio) {
    foreach ($d in @($pciDevices.Audio)) {
        if (-not ($d.AudioTypes -and ($d.AudioTypes.Count -gt 0))) { continue }


        $deviceList.Add($d)
    }
}

if ($startupModel -and $startupModel.StorageRowsComplete) {
    $_storageResult = @($startupModel.StorageRows)
    try { if ($startupModel.StorageSourceLogs) { $script:_cachedStorageNativeDiscoveryLogs = @($startupModel.StorageSourceLogs) } } catch { $script:_cachedStorageNativeDiscoveryLogs = @() }
} else {
    Get-CachedPhysicalDisks  | Out-Null
    Get-CachedWin32DiskDrives | Out-Null
    $_storageResult = Measure-Function 'Optimized-GetStorageDevices' { Optimized-GetStorageDevices }
}
$_storageRowsForStartupModel = @($_storageResult)
if ($_storageRowsForStartupModel) { foreach ($d in $_storageRowsForStartupModel) { if ($d) { $deviceList.Add($d) } } }

$_networkRowsForStartupModel = @()
$_swNetCollect = [System.Diagnostics.Stopwatch]::StartNew()
try {
    if ($startupModel -and $startupModel.NetworkRowsComplete) {
        $_networkRowsForStartupModel = @($startupModel.NetworkAdapterRows)
        try { if ($startupModel.NetworkSourceLogs) { $script:_cachedNetworkNativeDiscoveryLogs = @($startupModel.NetworkSourceLogs) } else { $script:_cachedNetworkNativeDiscoveryLogs = @() } } catch { $script:_cachedNetworkNativeDiscoveryLogs = @() }
    } elseif ($_asyncNet -and $_asyncNetHandle) {
        $_netRawResult = @($_asyncNet.EndInvoke($_asyncNetHandle))
        $_netResult = @()

        $_netEnvelope = $null
        foreach ($_netItem in $_netRawResult) {
            if ($null -ne $_netItem -and $null -ne $_netItem.PSObject.Properties['__DeviceTweakerNetworkAdapterEnvelope']) {
                $_netEnvelope = $_netItem
                break
            }
        }

        if ($null -ne $_netEnvelope) {
            try {
                $script:_cachedNetworkNativeDiscoveryLogs = @($_netEnvelope.Logs) | Where-Object {
                    $null -ne $_ -and -not [string]::IsNullOrWhiteSpace([string]$_)
                }
            } catch { $script:_cachedNetworkNativeDiscoveryLogs = @() }

            $_netResult = @($_netEnvelope.Devices)
        } else {
            $_netResult = @($_netRawResult)
        }

        $_networkRowsForStartupModel = @($_netResult)
    } else {
        $_netFallbackEnvelope = @(Get-NetworkAdapters -ReturnLogEnvelope)
        $_netFallback = $null
        foreach ($_netFallbackItem in $_netFallbackEnvelope) {
            if ($null -ne $_netFallbackItem -and $null -ne $_netFallbackItem.PSObject.Properties['__DeviceTweakerNetworkAdapterEnvelope']) { $_netFallback = $_netFallbackItem; break }
        }
        if ($null -ne $_netFallback) {
            try { $script:_cachedNetworkNativeDiscoveryLogs = @($_netFallback.Logs) } catch { $script:_cachedNetworkNativeDiscoveryLogs = @() }
            $_networkRowsForStartupModel = @($_netFallback.Devices)
        } else {
            $_networkRowsForStartupModel = @($_netFallbackEnvelope)
        }
    }

    foreach ($d in $_networkRowsForStartupModel) { if ($d) { $deviceList.Add($d) } }

    if (-not $script:DisableLogs -and ($null -eq $_networkRowsForStartupModel -or $_networkRowsForStartupModel.Count -eq 0)) {
        try {
            $_noNetLogBuffer = [System.Collections.Generic.List[string]]::new()
            $_noNetLogTs = Get-Date
            Add-DeviceTweakerFormattedLogEntry -Buffer $_noNetLogBuffer -Timestamp $_noNetLogTs -Text "Get-NetworkAdapters: Parent collection result"
            Add-DeviceTweakerFormattedLogEntry -Buffer $_noNetLogBuffer -Timestamp $_noNetLogTs -Text "  NetworkAdaptersReturned : 0"
            Add-DeviceTweakerFormattedLogEntry -Buffer $_noNetLogBuffer -Timestamp $_noNetLogTs -Text "  Reason                  : no network adapter device objects returned to GUI"
            Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($_noNetLogBuffer -join [Environment]::NewLine) + [Environment]::NewLine)
        } catch {}
    }
} catch {
    try {
        $_asyncNetError = $_
        if (-not $script:DisableLogs -and $script:cachedLogFile) {
            $_netErrorLogBuffer = [System.Collections.Generic.List[string]]::new()
            $_netErrorLogTs = Get-Date
            Add-DeviceTweakerFormattedLogEntry -Buffer $_netErrorLogBuffer -Timestamp $_netErrorLogTs -Text "Get-NetworkAdapters: collection failed; using synchronous fallback"
            Add-DeviceTweakerFormattedLogEntry -Buffer $_netErrorLogBuffer -Timestamp $_netErrorLogTs -Text ("  Error : '{0}'" -f $_asyncNetError.Exception.Message)
            Queue-DeviceTweakerLogText -Path $script:cachedLogFile -Text (($_netErrorLogBuffer -join [Environment]::NewLine) + [Environment]::NewLine)
        }
    } catch {}

    $_netFallbackEnvelope = @(Get-NetworkAdapters -ReturnLogEnvelope)
    $_netFallback = $null
    foreach ($_netFallbackItem in $_netFallbackEnvelope) {
        if ($null -ne $_netFallbackItem -and $null -ne $_netFallbackItem.PSObject.Properties['__DeviceTweakerNetworkAdapterEnvelope']) { $_netFallback = $_netFallbackItem; break }
    }
    if ($null -ne $_netFallback) {
        try { $script:_cachedNetworkNativeDiscoveryLogs = @($_netFallback.Logs) } catch { $script:_cachedNetworkNativeDiscoveryLogs = @() }
        $_networkRowsForStartupModel = @($_netFallback.Devices)
    } else {
        $_networkRowsForStartupModel = @($_netFallbackEnvelope)
    }
    foreach ($d in $_networkRowsForStartupModel) { if ($d) { $deviceList.Add($d) } }
} finally {
    try { if ($_asyncNet) { $_asyncNet.Dispose() } } catch {}
}

if ($script:forceNDIS -or $script:forceNetAdapterCx) {
    $forcedRole    = if ($script:forceNDIS) { 'NDIS' } else { 'NetAdapterCx' }
    foreach ($d in $deviceList) {
        if ($d.Category -eq 'Network') {
            $d.Role        = $forcedRole
            $forcedKind = if ($null -ne $d.PSObject.Properties['NetworkAdapterKind'] -and -not [string]::IsNullOrWhiteSpace([string]$d.NetworkAdapterKind)) { ([string]$d.NetworkAdapterKind).Trim() } else { 'OtherOrUnknown' }
            $forcedDriverLabel = if ($forcedRole -eq 'NetAdapterCx') { 'NetAdapterCx' } else { 'NDIS' }
            $forcedDisplayBase = "Network Interface Card ($forcedDriverLabel $forcedKind)"
            $modelName = if ($null -ne $d.Description) { $d.Description } else { $null }
            $d.DisplayName = New-DeviceTweakerTypedDisplayName -Base $forcedDisplayBase -Model $modelName
        }
    }
    $forcedFlagName = if ($script:forceNDIS) { 'forceNDIS' } else { 'forceNetAdapterCx' }
    Write-Host "[NIC][DEBUG] $forcedFlagName : all Network adapters overridden to Role='$forcedRole'" -ForegroundColor Magenta
}
$_swNetCollect.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'Get-NetworkAdapters' -Milliseconds $_swNetCollect.Elapsed.TotalMilliseconds }

$deviceControls = @{}
$script:_allSecretSaveCheckboxes = [System.Collections.Generic.List[System.Windows.Forms.CheckBox]]::new()
$script:deviceCppcLabels = [System.Collections.Generic.List[System.Windows.Forms.Label]]::new()
$script:deviceCpuAffinityGrids = [System.Collections.Generic.List[CpuAffinityGrid]]::new()

$_swAddrCollect = [System.Diagnostics.Stopwatch]::StartNew()
try {
    if ($startupModel -and $startupModel.DeviceAddressRowsComplete) {
        $globalDeviceAddressMap = @{}
        if ($startupModel.DeviceAddressByPnpId) {
            foreach ($_addrKey in @($startupModel.DeviceAddressByPnpId.Keys)) {
                try { $globalDeviceAddressMap[[string]$_addrKey] = [uint64]$startupModel.DeviceAddressByPnpId[$_addrKey] } catch {}
            }
        }
        $script:cachedDeviceAddressMap = $globalDeviceAddressMap
        $script:cachedDeviceAddressMapComplete = $true
    } elseif ($_asyncDevAddr -and $_asyncDevAddrHandle) {
        $_addrResults = @($_asyncDevAddr.EndInvoke($_asyncDevAddrHandle))
        $globalDeviceAddressMap = if ($_addrResults.Count -gt 0 -and $_addrResults[0] -is [hashtable]) { $_addrResults[0] } else { @{} }
    } else {
        $globalDeviceAddressMap = Get-Device-Addresses
    }
} catch {
    $globalDeviceAddressMap = Get-Device-Addresses
} finally {
    try { if ($_asyncDevAddr) { $_asyncDevAddr.Dispose() } } catch {}
}
$_swAddrCollect.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'Get-Device-Addresses' -Milliseconds $_swAddrCollect.Elapsed.TotalMilliseconds }

try {
    if ($startupModel -and $startupModel.IrqRowsComplete) {
        $script:cachedIrqAllocations = @($startupModel.IrqAllocationRows)
        $script:cachedIrqAllocationsComplete = $true
    } elseif ($_asyncIrqCim -and $_asyncIrqCimHandle) {
        $script:cachedIrqAllocations = @($_asyncIrqCim.EndInvoke($_asyncIrqCimHandle))
        $script:cachedIrqAllocationsComplete = $true
    } else {
        $script:cachedIrqAllocations = $null
        $script:cachedIrqAllocationsComplete = $false
    }
} catch {
    $script:cachedIrqAllocations = $null
    $script:cachedIrqAllocationsComplete = $false
} finally {
    try { if ($_asyncIrqCim) { $_asyncIrqCim.Dispose() } } catch {}
}

Complete-DeviceTweakerStartupModel -Model $startupModel -Devices $deviceList -StorageRows $_storageRowsForStartupModel -NetworkRows $_networkRowsForStartupModel -DeviceAddressMap $globalDeviceAddressMap -IrqAllocations $script:cachedIrqAllocations
$script:StartupModel = $startupModel
$script:_startupUsbRows = @($_usbResult)
$script:_startupPciDevices = $pciDevices
$script:_startupNetworkRows = @($_networkRowsForStartupModel)

$_sw_device_list.Stop()

function Set-ExovanceReadOnlyAdapterUI {
    foreach ($device in $deviceList) {
        if ($device.Category -ne 'Network' -or (Test-ExovanceNetworkWritable $device)) { continue }
        $controls = $deviceControls[$device]
        if ($null -eq $controls) { continue }
        if ($null -ne $controls.NativeState -and $null -ne $controls.NativeState.GroupBox) {
            $controls.NativeState.GroupBox.Enabled = $false
        }
        if ($null -ne $controls.MaskLabel) { $controls.MaskLabel.Text = 'Exovance: ' }
        if ($null -ne $controls.MaskValue) { $controls.MaskValue.Text = 'Read only - unsupported network adapter' }
    }
}

function Refresh-DeviceUI {
    foreach ($device in $deviceList) {
        $ctrls = $deviceControls[$device]

        $ndisIrqMode = $false
        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS") {
            if ($ctrls.ContainsKey('NdisIrqToggle') -and $ctrls.NdisIrqToggle -ne $null) {
                $ndisIrqMode = $ctrls.NdisIrqToggle.Checked
            }
        }

        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and (-not $ndisIrqMode)) {
            $affinityPath = $device.RegistryPath
        }
        elseif ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and $ndisIrqMode) {
            $affinityPath = if ($device.ConfigPath) { $device.ConfigPath } else { $device.RegistryPath }
        }
        elseif ($device.Category -eq "Network" -and $device.Role -eq "NetAdapterCx") {
            $affinityPath = Get-NetworkAdapterAffinityRegistryPath $device
        }
        else {
            $affinityPath = $device.RegistryPath
        }

        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and $ndisIrqMode) {
            $newVal = Get-CurrentAffinity $affinityPath $false
        } else {
            $newVal = Get-CurrentAffinity $affinityPath ($device.Category -eq "Network" -and $device.Role -eq "NDIS")
        }
        $ctrls.InitialValue = $newVal
        if ($ctrls.ContainsKey('NativeState') -and $null -ne $ctrls.NativeState) {
            try { $ctrls.NativeState.InitialValue = [string]$newVal } catch { }
            if ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and $ndisIrqMode) {
                try { $ctrls.NativeState.NdisIrqAffinity = [string]$newVal } catch { }
            }
        }

        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and (-not $ndisIrqMode)) {
            try {
                $selectedBase = [Convert]::ToInt32($newVal,16)
            } catch {
                $selectedBase = -1
            }
            $numQueues = 1
            try { $numQueues = Get-CurrentNumRssQueues $affinityPath } catch { $numQueues = 1 }

            if ($numQueues -lt 1) { $numQueues = 1 }
            if ($ctrls.ContainsKey('NativeState') -and $null -ne $ctrls.NativeState) {
                try { $ctrls.NativeState.InitialNumQueues = [int]$numQueues } catch { }
            }

            $logicalCount = $script:cachedLogicalCount

            $selectedSet = [System.Collections.ArrayList]::new()
            $rssRangeInvalid = $false
            if ($selectedBase -ge 0) {
                try {
                    $rssPlan = Get-ExovanceRssPlan -BaseProcessor $selectedBase -QueueCount $numQueues -LogicalCount $logicalCount -PhysicalCoreMap $script:PhysicalCoreIdByLogicalProcessor
                    foreach ($c in $rssPlan.Processors) { $selectedSet.Add($c) | Out-Null }
                } catch {
                    # Retain the invalid requested base; never fabricate a wrapped plan.
                    $selectedSet.Add($selectedBase) | Out-Null
                    $rssRangeInvalid = $true
                }
            }

            $script:NDISUpdating = $true; [DeviceTweakerUiHandlers]::SetNdisUpdating($true)
            foreach ($chk in $ctrls.CheckBoxes) {
                $core = [int]$chk.Tag
                if ($selectedSet.Contains($core)) {
                    $chk.Checked = $true
                    $chk.AutoCheck = $false
                } else {
                    $chk.Checked = $false
                    $chk.AutoCheck = $true
                }
            }
            $script:NDISUpdating = $false; [DeviceTweakerUiHandlers]::SetNdisUpdating($false)

            if ($selectedBase -ge 0) {
                $maskInt = [uint64]0
                foreach ($c in $selectedSet) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                $displayVal = if ($rssRangeInvalid) { 'Invalid RSS range - reduce queues' } else { "0x" + $maskInt.ToString('X') }
            } else {
                $displayVal = "0x0"
            }

            if ($ctrls.ContainsKey('NumQueues') -and $ctrls.NumQueues -ne $null) {
                try { $ctrls.NumQueues.Value = $numQueues } catch {}
                $ctrls.NumQueues.Visible = $true
            }
            if ($ctrls.ContainsKey('NumQueuesLabel') -and $ctrls.NumQueuesLabel -ne $null) { $ctrls.NumQueuesLabel.Visible = $true }
            if ($ctrls.ContainsKey('PolicyCombo') -and $ctrls.PolicyCombo -ne $null) { $ctrls.PolicyCombo.Visible = $false }
            if ($ctrls.ContainsKey('PolicyLabel') -and $ctrls.PolicyLabel -ne $null) { $ctrls.PolicyLabel.Visible = $false }
        } elseif ($device.Category -eq "Network" -and $device.Role -eq "NDIS" -and $ndisIrqMode) {
            Set-CheckboxesFromAffinity $ctrls.CheckBoxes $newVal
            $displayVal = $newVal

            if ($ctrls.ContainsKey('NumQueues') -and $ctrls.NumQueues -ne $null) { $ctrls.NumQueues.Visible = $false }
            if ($ctrls.ContainsKey('NumQueuesLabel') -and $ctrls.NumQueuesLabel -ne $null) { $ctrls.NumQueuesLabel.Visible = $false }
            if ($ctrls.ContainsKey('PolicyCombo') -and $ctrls.PolicyCombo -ne $null) { $ctrls.PolicyCombo.Visible = $true }
            if ($ctrls.ContainsKey('PolicyLabel') -and $ctrls.PolicyLabel -ne $null) { $ctrls.PolicyLabel.Visible = $true }

            $policyReadPath = $affinityPath
            $policy = Get-CurrentDevicePolicy $policyReadPath
            $ctrls.PolicyCombo.SelectedIndex = if ($policy -ge 0 -and $policy -lt $ctrls.PolicyCombo.Items.Count) { $policy } else { 0 }

            $enableAffinity = ($policy -eq 4)
            foreach ($chk in $ctrls.CheckBoxes) {
                $chk.AutoCheck = $enableAffinity
                $chk.Enabled   = $true
            }
        } else {
            Set-CheckboxesFromAffinity $ctrls.CheckBoxes $newVal
            $displayVal = $newVal
            if ($ctrls.ContainsKey('NumQueues') -and $ctrls.NumQueues -ne $null) {
                $ctrls.NumQueues.Visible = $false
            }
        }
        $ctrls.MaskLabel.Text = "IRQ Affinity Mask: "
        $maskValue = $ctrls.MaskValue
        $maskValue.Text = $displayVal
        $maskValue.ForeColor = [System.Drawing.Color]::FromArgb(255,100,45)

        if ($device.Category -eq "Network") {
            $msiPath = Get-NetworkAdapterMSIRegistryPath $device
        } else {
            $msiPath = $device.RegistryPath
        }
        $msi = Get-CurrentMSI $msiPath
        if ($msi.MSIEnabled -eq 1) {
            $ctrls.MSICombo.SelectedIndex = 1
        } else {
            $ctrls.MSICombo.SelectedIndex = 0
        }
        if ($msi.MessageLimit -eq "") {
            $ctrls.MsgLimitBox.Text = "Unlimited"
        }
        else {
            $ctrls.MsgLimitBox.Text = $msi.MessageLimit.ToString()
        }
        if ($device.Category -eq "Network") {
            $priPath = Get-NetworkAdapterMSIRegistryPath $device
        } else {
            $priPath = $device.RegistryPath
        }
        $priority = Get-CurrentPriority $priPath
        switch ($priority) {
            1 { $ctrls.PriorityCombo.SelectedIndex = 0 }
            2 { $ctrls.PriorityCombo.SelectedIndex = 1 }
            3 { $ctrls.PriorityCombo.SelectedIndex = 2 }
            default { $ctrls.PriorityCombo.SelectedIndex = 1 }
        }

        if (-not ($device.Category -eq "Network" -and $device.Role -eq "NDIS")) {
            $policyReadPath = if ($device.Category -eq "Network" -and $device.Role -eq "NetAdapterCx") { Get-NetworkAdapterAffinityRegistryPath $device } else { $device.RegistryPath }
            $policy = Get-CurrentDevicePolicy $policyReadPath
            $ctrls.PolicyCombo.SelectedIndex = $policy

        $enableAffinity = ($policy -eq 4)
        foreach ($chk in $ctrls.CheckBoxes) {
            $chk.AutoCheck = $enableAffinity
            $chk.Enabled   = $true
        }
        }

    }

    try {
        $reservedArr = [ReservedCpuSetsUiNative]::GetReservedCoresLocal([int]$script:cachedLogicalCount, $script:StartupModel)
        [ReservedCpuSetsUiNative]::ApplyReservedColoring($deviceList, $deviceControls, $script:reservedCheckboxes, $reservedArr, [bool]$script:IsDualCCDCpu, $script:Ccd0CoreSet, $script:Ccd1CoreSet, $script:_isPCoreLookup)
    } catch { }
    Set-ExovanceReadOnlyAdapterUI

}

function Get-FreeCore {
    param(
        [int[]]$occupiedCores,
        [int]  $logicalCount
    )
    $occupied = @{}
    foreach ($c in $occupiedCores) { $occupied[$c] = $true }
    for ($i = 1; $i -lt $logicalCount; $i++) {
        if (-not $occupied.ContainsKey($i)) { return $i }
    }
    return (if (-not $occupied.ContainsKey(0)) { 0 } else { -1 })
}

function Update-ConfigFile {
    param (
        [string]$filePath,
        [string]$coresString,
        [int]   $mouseCore = -1,
        [int]   $dwmCore   = -1
    )
    $content = if (Test-Path $filePath) {
        Get-Content $filePath -Raw -Encoding UTF8
    } else {
        ""
    }

    if ($dwmCore -ge 0 -and $filePath -like '*system_priorities.cfg') {
        $content = $content -replace 'threaddesc=DWM Kernel Sensor Thread, \(.*?\)',
                                     "threaddesc=DWM Kernel Sensor Thread, ($dwmCore)"
        $content = $content -replace 'threaddesc=DWM Master Input Thread, \(.*?\)',
                                     "threaddesc=DWM Master Input Thread, ($mouseCore)"
    }

    $content = $content -replace '(?m)^occupied_affinity_cores=.*$',
                                 "occupied_affinity_cores=$coresString"
    $content = $content -replace '(?m)^occupied_ideal_processor_cores=.*$',
                                 "occupied_ideal_processor_cores=$coresString"

    if ($content -notmatch 'occupied_affinity_cores=') {
        $content += "`r`noccupied_affinity_cores=$coresString"
    }
    if ($content -notmatch 'occupied_ideal_processor_cores=') {
        $content += "`r`noccupied_ideal_processor_cores=$coresString"
    }

    Set-Content -Path $filePath -Value $content.Trim() -Encoding UTF8
}

function Backup-DeviceSettings {
    $backupData = [ordered]@{
        ReservedCpuSets = $null
        Timestamp       = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
        Devices         = @()
    }

    try {
        $rsBytes = $null
        if ($script:StartupModel -and $script:StartupModel.ReservedCpuSetsSnapshotLoaded) {
            if ($script:StartupModel.HasReservedCpuSets) { $rsBytes = [byte[]]$script:StartupModel.ReservedCpuSetsBytes }
        } else {
            $rsBytes = [DeviceTweakerRegistrySnapshot]::ReadReservedCpuSetsBytes()
            if ($script:StartupModel) {
                $script:StartupModel.ReservedCpuSetsBytes = $rsBytes
                $script:StartupModel.HasReservedCpuSets = ($null -ne $rsBytes)
                $script:StartupModel.ReservedCpuSetsSnapshotLoaded = $true
            }
        }
        if ($null -ne $rsBytes) { $backupData.ReservedCpuSets = [Convert]::ToBase64String($rsBytes) }
    } catch {
        Write-Host "Failed to backup ReservedCpuSets: $_"
    }

    foreach ($device in $deviceList) {
        $isNetworkDevice = ($device.Category -eq "Network")
        $isNdisDevice = ($isNetworkDevice -and $device.Role -eq "NDIS")
        $isNetAdapterCxDevice = ($isNetworkDevice -and $device.Role -eq "NetAdapterCx")

        $deviceData = [ordered]@{
            DisplayName  = $device.DisplayName
            Category     = $device.Category
            Role         = if ($device.Category -eq "USB" -and $null -ne $device.Roles -and $device.Roles) {
                               $device.Roles -join "/"
                           } else {
                               $device.Role
                           }
            PNPID        = $null
        }

        if ($null -ne $device.StorageType -and $device.StorageType) {
            $deviceData['StorageType'] = [string]$device.StorageType
        }

        if ($isNetworkDevice) {
            $deviceData['ClassPath'] = Format-RegistryPathForDisplay $device.RegistryPath
            $deviceData['ConfigPath'] = if ($device.ConfigPath) { Format-RegistryPathForDisplay $device.ConfigPath } else { $null }
            $deviceData['NumRssQueues'] = $null
            $deviceData['RssBaseProcNumber'] = $null
            $deviceData['ExovanceRss'] = @(Get-ExovanceRssSnapshot -RegistryPath $device.RegistryPath)
        } else {
            $deviceData['RegistryPath'] = Format-RegistryPathForDisplay $device.RegistryPath
        }

        $deviceData['IRQ affinity mask'] = $null
        $deviceData['MSIEnabled'] = $null
        $deviceData['MessageLimit'] = $null
        $deviceData['IRQ priority'] = $null
        $deviceData['IRQ device policy'] = $null

        if ($isNdisDevice -and $null -ne $device.ConfigPath -and $device.ConfigPath) {
            $pnpIdPath = $device.ConfigPath
        } elseif ($isNetworkDevice) {
            $pnpIdPath = Get-NetworkAdapterMSIRegistryPath $device
        } else {
            $pnpIdPath = $device.RegistryPath
        }
        $pnpID = Get-PNPId $pnpIdPath
        $deviceData['PNPID'] = $pnpID

        if ($isNdisDevice) {
            $rssClassPath = $device.RegistryPath
            try {
                $deviceData['NumRssQueues'] = Get-CurrentNumRssQueues -registryPath $rssClassPath
                $relativePath = Get-RelativeRegistryPath $rssClassPath
                $regKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($relativePath, $false)
                if ($regKey -ne $null) {
                    $value = $regKey.GetValue("*RssBaseProcNumber", $null)
                    if ($value -ne $null) { $deviceData['RssBaseProcNumber'] = $value }
                    $regKey.Close()
                }
            } catch { }

            $irqBackupPath = if ($device.ConfigPath) { $device.ConfigPath } else { $device.RegistryPath }
            $deviceData['IRQ affinity mask'] = Get-CurrentAffinity $irqBackupPath $false -PreserveAbsence
            $deviceData['IRQ device policy'] = Get-CurrentDevicePolicy $irqBackupPath -PreserveAbsence
        } elseif ($isNetAdapterCxDevice) {
            $rssClassPath = $device.RegistryPath
            try {
                $deviceData['NumRssQueues'] = Get-CurrentNumRssQueues -registryPath $rssClassPath
                $rssRelPath = Get-RelativeRegistryPath $rssClassPath
                $rssRegKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($rssRelPath, $false)
                if ($rssRegKey -ne $null) {
                    $rssVal = $rssRegKey.GetValue("*RssBaseProcNumber", $null)
                    if ($rssVal -ne $null) { $deviceData['RssBaseProcNumber'] = $rssVal }
                    $rssRegKey.Close()
                }
            } catch { }

            $irqBackupPathCx = if ($device.ConfigPath) { $device.ConfigPath } else { $device.RegistryPath }
            $deviceData['IRQ affinity mask'] = Get-CurrentAffinity $irqBackupPathCx $false -PreserveAbsence
            $deviceData['IRQ device policy'] = Get-CurrentDevicePolicy $irqBackupPathCx -PreserveAbsence
        } else {
            $deviceData['IRQ affinity mask'] = Get-CurrentAffinity $device.RegistryPath $false -PreserveAbsence
            $deviceData['IRQ device policy'] = Get-CurrentDevicePolicy $device.RegistryPath -PreserveAbsence
        }

        if ($isNetworkDevice) {
            $msiPath = Get-NetworkAdapterMSIRegistryPath $device
        } else {
            $msiPath = $device.RegistryPath
        }

        $msiSettings = Get-CurrentMSI $msiPath -PreserveAbsence
        $deviceData['MSIEnabled'] = $msiSettings.MSIEnabled
        $deviceData['MessageLimit'] = $msiSettings.MessageLimit
        $deviceData['IRQ priority'] = Get-CurrentPriority $msiPath -PreserveAbsence

        $backupData.Devices += [PSCustomObject]$deviceData
    }

    $backupFile = Get-DeviceTweakerBackupPath -ForWrite

    $jsonContent = ConvertTo-DeviceTweakerBackupJson -InputObject $backupData -Depth 10
    $backupDirectory = Split-Path -Parent $backupFile
    if (-not [System.IO.Directory]::Exists($backupDirectory)) { [void][System.IO.Directory]::CreateDirectory($backupDirectory) }
    $jsonContent | Out-File -LiteralPath $backupFile -Encoding UTF8 -Force

    return $backupFile
}

function Restore-DeviceSettings {
    param(
        [string]$backupFile
    )

    if ([string]::IsNullOrWhiteSpace($backupFile)) {
        $backupFile = Get-DeviceTweakerBackupPath -ForRead
    }

    if ([string]::IsNullOrWhiteSpace($backupFile) -or -not [System.IO.File]::Exists($backupFile)) {
        $searchReport = Get-DeviceTweakerBackupSearchReport
        Show-DarkMessageBox -Message "Backup file not found.`n`nFile:`n$backupFile`n`n$searchReport" -Title "Error" -Icon Error
        return $false
    }

    if (-not (Test-DeviceTweakerBackupJson -Path $backupFile)) {
        Show-DarkMessageBox -Message "Backup file is not a valid device settings backup: $backupFile" -Title "Error" -Icon Error
        return $false
    }

    try {
        $jsonContent = Get-Content -LiteralPath $backupFile -Encoding UTF8 -Raw -ErrorAction Stop
        $backupData = ConvertFrom-DeviceTweakerBackupJson -JsonContent $jsonContent

        $pad1 = 22
        $restoreResults = [System.Collections.ArrayList]::new()

        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Write-Host "    RESTORE STARTED" -ForegroundColor Yellow
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Write-Host ""

        Write-Host "  RESERVED CPU SETS" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray

        if ($backupData.ReservedCpuSets) {
            $bytes = [Convert]::FromBase64String($backupData.ReservedCpuSets)
            $rsCores = @()
            for ($bi = 0; $bi -lt $bytes.Count; $bi++) {
                for ($bit = 0; $bit -lt 8; $bit++) {
                    if ($bytes[$bi] -band (1 -shl $bit)) { $rsCores += ($bi * 8 + $bit) }
                }
            }
            $rsStr = if ($rsCores.Count -gt 0) { $rsCores -join ', ' } else { "(empty mask)" }

            try {
                if (-not [ReservedCpuSetsUiNative]::WriteReservedCpuSetsBytes($bytes, $script:StartupModel)) {
                    throw "Native ReservedCpuSets registry write returned false."
                }
                Write-Host ("  {0} : {1}" -f "Action".PadRight($pad1), "Restored from backup") -ForegroundColor Green
                Write-Host ("  {0} : {1}" -f "Reserved Cores".PadRight($pad1), $rsStr)
            } catch {
                Write-Host ("  {0} : {1}" -f "Action".PadRight($pad1), "FAILED") -ForegroundColor Red
                Write-Host ("  {0} : {1}" -f "Error".PadRight($pad1), $_) -ForegroundColor Red
            }
        } else {
            try {
                $wasCleared = [ReservedCpuSetsUiNative]::DeleteReservedCpuSetsValue($script:StartupModel)
                if ($wasCleared) {
                    Write-Host ("  {0} : {1}" -f "Action".PadRight($pad1), "Cleared (backup had none)") -ForegroundColor Yellow
                } else {
                    Write-Host ("  {0} : {1}" -f "Action".PadRight($pad1), "Already empty, no change")
                }
            } catch {
                Write-Host ("  {0} : {1}" -f "Action".PadRight($pad1), "FAILED to clear") -ForegroundColor Red
                Write-Host ("  {0} : {1}" -f "Error".PadRight($pad1), $_) -ForegroundColor Red
            }
        }
        Write-Host ""

        Write-Host "  DEVICE RESTORATIONS" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray

        $devIndex = 0
        foreach ($deviceBackup in $backupData.Devices) {
            $devIndex++
            $matchingDevice = $null
            foreach ($device in $deviceList) {
                $backupPNPID = $deviceBackup.PNPID
                if ($device.Category -eq "Network") {
                    $deviceMsiPath = Get-NetworkAdapterMSIRegistryPath $device
                } else {
                    $deviceMsiPath = $device.RegistryPath
                }
                $devicePNPID = Get-PNPId $deviceMsiPath
                if ($backupPNPID -and $devicePNPID -and $backupPNPID -eq $devicePNPID) {
                    $matchingDevice = $device
                    break
                }
            }

            if (-not $matchingDevice) {
                $backupPathDisplays = @(Get-DeviceTweakerBackupPathDisplayValues -BackupDevice $deviceBackup)
                foreach ($device in $deviceList) {
                    if (-not (Test-DeviceTweakerBackupCategoryMatch -Device $device -BackupDevice $deviceBackup)) { continue }

                    $devicePathDisplays = @(Get-DeviceTweakerDevicePathDisplayValues -Device $device)
                    $pathMatched = $false
                    foreach ($devicePathDisplay in $devicePathDisplays) {
                        foreach ($backupPathDisplay in $backupPathDisplays) {
                            if ($devicePathDisplay -eq $backupPathDisplay) {
                                $pathMatched = $true
                                break
                            }
                        }
                        if ($pathMatched) { break }
                    }

                    if ($pathMatched) {
                        $matchingDevice = $device
                        break
                    }
                }
            }

            if (-not $matchingDevice) {
                foreach ($device in $deviceList) {
                    if ($device.DisplayName -eq $deviceBackup.DisplayName -and
                        (Test-DeviceTweakerBackupCategoryMatch -Device $device -BackupDevice $deviceBackup)) {
                        $matchingDevice = $device
                        break
                    }
                }
            }

            $roleTag = if ($deviceBackup.Role) { " [$($deviceBackup.Category)/$($deviceBackup.Role)]" } else { " [$($deviceBackup.Category)]" }
            $displayLabel = "$($deviceBackup.DisplayName)$roleTag"

            if (-not $matchingDevice) {
                Write-Host ""
                Write-Host ("  {0}. {1}" -f $devIndex, $displayLabel) -ForegroundColor Red
                Write-Host ("  {0}{1}" -f ("".PadRight(4)), ("".PadRight(60, '-'))) -ForegroundColor DarkGray
                Write-Host ("      {0} : {1}" -f "Status".PadRight($pad1), "SKIPPED - device not found on system") -ForegroundColor Red
                continue
            }

            Write-Host ""
            Write-Host ("  {0}. {1}" -f $devIndex, $displayLabel) -ForegroundColor Yellow
            Write-Host ("  {0}{1}" -f ("".PadRight(4)), ("".PadRight(60, '-'))) -ForegroundColor DarkGray

            if ($matchingDevice.Category -eq "Network" -and $matchingDevice.Role -eq "NDIS") {
                $rssClassPath = $matchingDevice.RegistryPath
                $fmtRssClassPath = Format-RegistryPathForDisplay $rssClassPath
                if ($deviceBackup.PSObject.Properties['ExovanceRss']) {
                    Restore-ExovanceRssSnapshot -RegistryPath $matchingDevice.RegistryPath -Snapshot @($deviceBackup.ExovanceRss)
                } else {
                    Add-ExovanceWriteFailure 'Legacy backup has no complete RSS snapshot. Only available RSS values can be restored.'
                    if ($deviceBackup.RssBaseProcNumber -ne $null) {
                        try {
                            Set-ItemProperty -Path $rssClassPath -Name "*RssBaseProcNumber" -Value $deviceBackup.RssBaseProcNumber -Type String -ErrorAction Stop
                            Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "$($deviceBackup.RssBaseProcNumber)") -ForegroundColor Green
                        } catch {
                            Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "FAILED - $_") -ForegroundColor Red
                        }
                    } else {
                        try {
                            $rssRelTmp = Get-RelativeRegistryPath $rssClassPath
                            $rssKeyTmp = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($rssRelTmp, $true)
                            if ($rssKeyTmp -ne $null -and $rssKeyTmp.GetValue("*RssBaseProcNumber", $null) -ne $null) {
                                $rssKeyTmp.DeleteValue("*RssBaseProcNumber", $false)
                                Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "Deleted (backup had none)") -ForegroundColor Yellow
                            } else {
                                Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "(not set in backup, already absent)")
                            }
                            if ($rssKeyTmp) { $rssKeyTmp.Close() }
                        } catch { }
                    }
                    if ($deviceBackup.NumRssQueues -ne $null) {
                        try {
                            Set-ItemProperty -Path $rssClassPath -Name "*NumRssQueues" -Value ("$($deviceBackup.NumRssQueues)") -Type String -ErrorAction Stop
                            Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "$($deviceBackup.NumRssQueues)") -ForegroundColor Green
                        } catch {
                            Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "FAILED - $_") -ForegroundColor Red
                        }
                    } else {
                        try {
                            $rssRelTmp2 = Get-RelativeRegistryPath $rssClassPath
                            $rssKeyTmp2 = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($rssRelTmp2, $true)
                            if ($rssKeyTmp2 -ne $null -and $rssKeyTmp2.GetValue("*NumRssQueues", $null) -ne $null) {
                                $rssKeyTmp2.DeleteValue("*NumRssQueues", $false)
                                Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "Deleted (backup had none)") -ForegroundColor Yellow
                            } else {
                                Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "(not set in backup, already absent)")
                            }
                            if ($rssKeyTmp2) { $rssKeyTmp2.Close() }
                        } catch { }
                    }
                    Write-Host ("        {0} : {1}" -f "RSS Reg".PadRight($pad1 - 2), $fmtRssClassPath) -ForegroundColor DarkGray

                }

                $irqRestorePath = if ($matchingDevice.ConfigPath) { $matchingDevice.ConfigPath } else { $matchingDevice.RegistryPath }
                $irqRestoreRelPath = Get-RelativeRegistryPath $irqRestorePath
                $irqRestoreSubkey = "$irqRestoreRelPath\Device Parameters\Interrupt Management\Affinity Policy"
                $fmtIrqPath = (Format-RegistryPathForDisplay $irqRestorePath) + "\Device Parameters\Interrupt Management\Affinity Policy"
                Restore-DeviceTweakerIrqAffinityFromBackup -RegistryPath $irqRestorePath -BackupDevice $deviceBackup -LogLabel "IRQ Affinity" -PadWidth $pad1
                Write-Host ("        {0} : {1}" -f "IRQ Reg".PadRight($pad1 - 2), $fmtIrqPath) -ForegroundColor DarkGray
            } elseif ($matchingDevice.Category -eq "Network" -and $matchingDevice.Role -eq "NetAdapterCx") {
                $rssClassPathCx = $matchingDevice.RegistryPath
                $fmtRssClassPathCx = Format-RegistryPathForDisplay $rssClassPathCx
                if ($deviceBackup.PSObject.Properties['ExovanceRss']) {
                    Restore-ExovanceRssSnapshot -RegistryPath $matchingDevice.RegistryPath -Snapshot @($deviceBackup.ExovanceRss)
                } else {
                    Add-ExovanceWriteFailure 'Legacy backup has no complete RSS snapshot. Only available RSS values can be restored.'
                    if ($deviceBackup.RssBaseProcNumber -ne $null) {
                        try {
                            Set-ItemProperty -Path $rssClassPathCx -Name "*RssBaseProcNumber" -Value $deviceBackup.RssBaseProcNumber -Type String -ErrorAction Stop
                            Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "$($deviceBackup.RssBaseProcNumber)") -ForegroundColor Green
                        } catch {
                            Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "FAILED - $_") -ForegroundColor Red
                        }
                    } else {
                        try {
                            $rssRelCx = Get-RelativeRegistryPath $rssClassPathCx
                            $rssKeyCx = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($rssRelCx, $true)
                            if ($rssKeyCx -ne $null -and $rssKeyCx.GetValue("*RssBaseProcNumber", $null) -ne $null) {
                                $rssKeyCx.DeleteValue("*RssBaseProcNumber", $false)
                                Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "Deleted (backup had none)") -ForegroundColor Yellow
                            } else {
                                Write-Host ("      {0} : {1}" -f "RSS Base Proc".PadRight($pad1), "(not set in backup, already absent)")
                            }
                            if ($rssKeyCx) { $rssKeyCx.Close() }
                        } catch { }
                    }
                    if ($deviceBackup.NumRssQueues -ne $null) {
                        try {
                            Set-ItemProperty -Path $rssClassPathCx -Name "*NumRssQueues" -Value ("$($deviceBackup.NumRssQueues)") -Type String -ErrorAction Stop
                            Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "$($deviceBackup.NumRssQueues)") -ForegroundColor Green
                        } catch {
                            Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "FAILED - $_") -ForegroundColor Red
                        }
                    } else {
                        try {
                            $rssRelCx2 = Get-RelativeRegistryPath $rssClassPathCx
                            $rssKeyCx2 = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($rssRelCx2, $true)
                            if ($rssKeyCx2 -ne $null -and $rssKeyCx2.GetValue("*NumRssQueues", $null) -ne $null) {
                                $rssKeyCx2.DeleteValue("*NumRssQueues", $false)
                                Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "Deleted (backup had none)") -ForegroundColor Yellow
                            } else {
                                Write-Host ("      {0} : {1}" -f "RSS Queues".PadRight($pad1), "(not set in backup, already absent)")
                            }
                            if ($rssKeyCx2) { $rssKeyCx2.Close() }
                        } catch { }
                    }
                    Write-Host ("        {0} : {1}" -f "RSS Reg".PadRight($pad1 - 2), $fmtRssClassPathCx) -ForegroundColor DarkGray

                }

                $irqRestorePathCx = if ($matchingDevice.ConfigPath) { $matchingDevice.ConfigPath } else { $matchingDevice.RegistryPath }
                $irqRestoreRelPathCx = Get-RelativeRegistryPath $irqRestorePathCx
                $irqRestoreSubkeyCx = "$irqRestoreRelPathCx\Device Parameters\Interrupt Management\Affinity Policy"
                $fmtIrqPathCx = (Format-RegistryPathForDisplay $irqRestorePathCx) + "\Device Parameters\Interrupt Management\Affinity Policy"
                Restore-DeviceTweakerIrqAffinityFromBackup -RegistryPath $irqRestorePathCx -BackupDevice $deviceBackup -LogLabel "IRQ Affinity" -PadWidth $pad1
                Write-Host ("        {0} : {1}" -f "IRQ Reg".PadRight($pad1 - 2), $fmtIrqPathCx) -ForegroundColor DarkGray
            } else {
                $hasIrqBackupData = (Test-DeviceTweakerBackupHasProperty -Object $deviceBackup -Names @('IRQ affinity mask','IrqAffinityMask','Affinity','IrqAssignmentSetOverride','IRQ assignment set override','IRQ device policy','IRQDevicePolicy','IrqDevicePolicy','Policy'))
                if ($hasIrqBackupData) {
                    $fmtAffinityPath = (Format-RegistryPathForDisplay $matchingDevice.RegistryPath) + "\Device Parameters\Interrupt Management\Affinity Policy"
                    Restore-DeviceTweakerIrqAffinityFromBackup -RegistryPath $matchingDevice.RegistryPath -BackupDevice $deviceBackup -LogLabel "IRQ Affinity" -PadWidth $pad1
                    Write-Host ("        {0} : {1}" -f "IRQ Reg".PadRight($pad1 - 2), $fmtAffinityPath) -ForegroundColor DarkGray
                }
            }

            if ($matchingDevice.Category -eq "Network") {
                $msiPath = Get-NetworkAdapterMSIRegistryPath $matchingDevice
            } else {
                $msiPath = $matchingDevice.RegistryPath
            }

            $msiSubkey = 'Device Parameters\Interrupt Management\MessageSignaledInterruptProperties'
            $hasMsiEnabled = Test-DeviceTweakerBackupHasProperty -Object $deviceBackup -Names @('MSIEnabled','MSISupported')
            $hasMessageLimit = Test-DeviceTweakerBackupHasProperty -Object $deviceBackup -Names @('MessageLimit','MessageNumberLimit')
            $msgLimit = Get-DeviceTweakerBackupValue -Object $deviceBackup -Names @('MessageLimit','MessageNumberLimit') -Default $null
            $msiBackupValue = Get-DeviceTweakerBackupValue -Object $deviceBackup -Names @('MSIEnabled','MSISupported') -Default $null
            $msiLabel = 'not in backup'
            $msgLimitLabel = 'not in backup'

            if ($hasMsiEnabled) {
                if (Test-DeviceTweakerNullLike $msiBackupValue) {
                    Remove-DeviceTweakerRegistryValue -RegistryPath $msiPath -SubkeySuffix $msiSubkey -ValueName 'MSISupported' | Out-Null
                    $msiLabel = 'null - deleted/absent'
                } else {
                    Set-DeviceTweakerRegistryDWordValue -RegistryPath $msiPath -SubkeySuffix $msiSubkey -ValueName 'MSISupported' -Value $msiBackupValue | Out-Null
                    $msiLabel = if ([int]$msiBackupValue -eq 1) { 'Enabled' } else { 'Disabled' }
                }
            }

            if ($hasMessageLimit) {
                if ((Test-DeviceTweakerNullLike $msgLimit) -or $msgLimit -eq "" -or $msgLimit -eq "Unlimited" -or ([string]$msgLimit) -eq "0") {
                    Remove-DeviceTweakerRegistryValue -RegistryPath $msiPath -SubkeySuffix $msiSubkey -ValueName 'MessageNumberLimit' | Out-Null
                    $msgLimitLabel = if (Test-DeviceTweakerNullLike $msgLimit) { 'null - deleted/absent' } else { 'Unlimited' }
                } else {
                    Set-DeviceTweakerRegistryDWordValue -RegistryPath $msiPath -SubkeySuffix $msiSubkey -ValueName 'MessageNumberLimit' -Value $msgLimit | Out-Null
                    $msgLimitLabel = "$msgLimit"
                }
            }

            $formattedMsiPath = (Format-RegistryPathForDisplay $msiPath) + "\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
            Write-Host ("      {0} : {1}" -f "MSI Mode".PadRight($pad1), "$msiLabel, Limit=$msgLimitLabel")
            Write-Host ("        {0} : {1}" -f "MSI Reg".PadRight($pad1 - 2), $formattedMsiPath) -ForegroundColor DarkGray

            $hasIrqPriority = Test-DeviceTweakerBackupHasProperty -Object $deviceBackup -Names @('IRQ priority','IRQPriority','IrqPriority','Priority','DevicePriority')
            $backupIrqPriority = Get-DeviceTweakerBackupIrqPriority $deviceBackup
            if ($hasIrqPriority) {
                if ($backupIrqPriority -ne $null) {
                    Set-DevicePriority $msiPath $backupIrqPriority | Out-Null
                    $priorityStr = "$backupIrqPriority"
                } else {
                    Remove-DeviceTweakerRegistryValue -RegistryPath $msiPath -SubkeySuffix 'Device Parameters\Interrupt Management\Affinity Policy' -ValueName 'DevicePriority' | Out-Null
                    $priorityStr = 'null - deleted/absent'
                }
            } else {
                $priorityStr = 'not in backup'
            }
            Write-Host ("      {0} : {1}" -f "IRQ priority".PadRight($pad1), $priorityStr)

            if ($matchingDevice.Category -eq "Network") {
                $fmtClassPath = Format-RegistryPathForDisplay $matchingDevice.RegistryPath
                $fmtConfigPath = if ($matchingDevice.ConfigPath) { Format-RegistryPathForDisplay $matchingDevice.ConfigPath } else { $null }
                if ($fmtConfigPath) {
                    Write-Host ("        {0} : {1}" -f "Class Path".PadRight($pad1 - 2), $fmtClassPath) -ForegroundColor DarkGray
                    Write-Host ("        {0} : {1}" -f "Config Path".PadRight($pad1 - 2), $fmtConfigPath) -ForegroundColor DarkGray
                }
            }
        }

        $guiRefreshOk = $false
        try { Refresh-DeviceUI; $guiRefreshOk = $true } catch { }

        $rsRefreshOk = $false
        try {
            $reservedArr = [ReservedCpuSetsUiNative]::GetReservedCoresLocal([int][Environment]::ProcessorCount, $script:StartupModel)
            [ReservedCpuSetsUiNative]::SetCellsCheckedFromReservedArray($script:reservedCheckboxes, $reservedArr)
            [ReservedCpuSetsUiNative]::ApplyReservedColoring($deviceList, $deviceControls, $script:reservedCheckboxes, $reservedArr, [bool]$script:IsDualCCDCpu, $script:Ccd0CoreSet, $script:Ccd1CoreSet, $script:_isPCoreLookup)
            $rsRefreshOk = $true
        } catch { }

        Write-Host ""
        Write-Host "  FINAL STATE" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        Write-Host ("  Devices Restored     : {0}" -f $backupData.Devices.Count) -ForegroundColor Green
        Write-Host ("  Backup Timestamp     : {0}" -f $backupData.Timestamp)
        $guiStatus = if ($guiRefreshOk) { "Refreshed" } else { "FAILED" }
        $guiColor  = if ($guiRefreshOk) { "Cyan" } else { "Red" }
        Write-Host ("  GUI                  : {0}" -f $guiStatus) -ForegroundColor $guiColor
        $rsStatus = if ($rsRefreshOk) { "Refreshed" } else { "FAILED" }
        $rsColor  = if ($rsRefreshOk) { "Cyan" } else { "Red" }
        Write-Host ("  ReservedCpuSets UI   : {0}" -f $rsStatus) -ForegroundColor $rsColor

        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Assert-ExovanceWritesSucceeded
        Set-ExovanceUiFeedback -State Applied -Text 'Backup restored - review results'
        Write-Host "    RESTORE COMPLETED SUCCESSFULLY" -ForegroundColor Green
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Write-Host ""

        return $true
    } catch {
        Set-ExovanceUiFeedback -State Error -Text 'Action incomplete - review error details'
        Show-DarkMessageBox -Message "Failed to restore settings: $_" -Title "Error" -Icon Error
        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Write-Host "    RESTORE FAILED" -ForegroundColor Red
        Write-Host "  ================================================================" -ForegroundColor DarkYellow
        Write-Host ("  Error: {0}" -f $_) -ForegroundColor Red
        Write-Host ""
        return $false
    }
}

