        $_wFamilyVisible = [Math]::Min([Math]::Max($_wFamily, 180), 340)
        $_wTimeVisible = [Math]::Min([Math]::Max($_wTimeMax, 160), 340)
        $_rowWidthTop = $_wLabel + 4 + $_wFamilyVisible + 5
