        $_rowWidth = [Math]::Max($_rowWidthTop, $_rowWidthBottom)
        $_neededGBWidth = $_rowWidth + 12
        $script:nicIMODMinGroupBoxWidth = [Math]::Max($script:nicIMODMinGroupBoxWidth, $_neededGBWidth)
    }
}
