    $_wHdaReg = [Math]::Max([System.Windows.Forms.TextRenderer]::MeasureText('[MMIO+5Ah]', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width, [Math]::Max([System.Windows.Forms.TextRenderer]::MeasureText('[MMIO+4Eh]', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width, [System.Windows.Forms.TextRenderer]::MeasureText('[MMIO+5Eh]', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width))
    $_hdaValueW = 58
