    $_hdaSetW = [Math]::Max(60, [System.Windows.Forms.TextRenderer]::MeasureText('SET', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width + 22)
    $_hdaRingSetW = [Math]::Max(84, [Math]::Max([System.Windows.Forms.TextRenderer]::MeasureText('SET CORB', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width, [System.Windows.Forms.TextRenderer]::MeasureText('SET RIRB', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width) + 22)
    $_hdaGap = 6
