    $_hdaStatusMeasure = [System.Windows.Forms.TextRenderer]::MeasureText('RINTCNT=0x00 | 256 codec responses/IRQ | rate=codec responses/s÷256', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width + 4
    $_hdaStatusW = [Math]::Max(340, [Math]::Min(520, $_hdaStatusMeasure))
    $_hdaRingStatusW = [Math]::Max(390, [System.Windows.Forms.TextRenderer]::MeasureText('RIRBSIZE=2 | 256 entries / 2048 B | cap: 0,1,2 | RIRB DMA RUN', $_extMeasureFont, [System.Drawing.Size]::new(9999,99), $_extMeasureFlags).Width + 4)
    $_hdaMinRight = [Math]::Max($_hdaX + $_hdaStatusW + $_hdaGap + $_hdaRefreshW + $_hdaGap + $_hdaSetW + $_hdaPadR, $_hdaRingX + $_hdaRingStatusW + $_hdaGap + $_hdaRingSetW + $_hdaPadR)
    $script:hdaRintcntMinGroupBoxWidth = $_hdaMinRight + 12
