}
$_buttonMeasuredMinFormWidth = $_buttonMinTotalWidth + 110
$_statusMinFormWidth = [Math]::Max([Math]::Max($_legacyStatusMinFormWidth, $_statusMeasuredMinFormWidth), $_buttonMeasuredMinFormWidth)
$script:affFormWidth = [Math]::Max(1180, [Math]::Max($script:affGroupBoxWidth + 45, $_statusMinFormWidth))
function Limit-DeviceTweakerFormWidthToWorkingArea {
    param([Parameter(Mandatory=$true)][int]$Width, [System.Windows.Forms.Form]$Form)
    try {
        $workArea = if ($Form -and -not $Form.IsDisposed) { [System.Windows.Forms.Screen]::FromControl($Form).WorkingArea } else { [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea }
        if ($workArea.Width -le 0) { $workArea = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea }
        $maxWidth = [Math]::Max(640, [int]$workArea.Width - 24)
        return [Math]::Min([Math]::Max(1, $Width), $maxWidth)
    } catch { return $Width }
}
$script:affFormDesiredWidth = [int]$script:affFormWidth
$script:affFormWidth = Limit-DeviceTweakerFormWidthToWorkingArea -Width ([int]$script:affFormWidth) -Form $form
