function Get-PropValue {
    param(
        [AllowNull()][object]$Object,
        [Parameter(Mandatory=$true)][string]$Name
    )
    if ($null -eq $Object -or [string]::IsNullOrWhiteSpace($Name)) { return $null }
    try {
        if ($Object -is [System.Collections.IDictionary]) {
            if ($Object.Contains($Name)) { return $Object[$Name] }
            if ($Object.ContainsKey($Name)) { return $Object[$Name] }
        }
    } catch { }
    try {
        $prop = $Object.PSObject.Properties[$Name]
        if ($null -ne $prop) { return $prop.Value }
    } catch { }
    return $null
}

function Get-DeviceTweakerActiveControlMap {
    try {
        if ($script:deviceControlMap -is [System.Collections.IDictionary]) { return $script:deviceControlMap }
    } catch { }
    try {
        $m = Get-Variable -Name deviceControls -Scope Script -ValueOnly -ErrorAction Stop
        if ($m -is [System.Collections.IDictionary]) {
            $script:deviceControlMap = $m
            return $m
        }
    } catch { }
    return $null
}

function Get-DeviceTweakerControlMapForDevice {
    param([Parameter(Mandatory=$true)][object]$Device)
    $mapTable = Get-DeviceTweakerActiveControlMap
    if ($null -eq $mapTable -or $null -eq $Device) { return $null }

    try { if ($mapTable.ContainsKey($Device)) { return $mapTable[$Device] } } catch { }
    try {
        $src = Get-PropValue $Device 'Source'
        if ($null -ne $src -and $mapTable.ContainsKey($src)) { return $mapTable[$src] }
    } catch { }

    $deviceRegistryPath = [string](Get-PropValue $Device 'RegistryPath')
    $deviceKey = [string](Get-PropValue $Device 'DeviceKey')
    foreach ($k in @($mapTable.Keys)) {
        $ctrls = $null
        try { $ctrls = $mapTable[$k] } catch { continue }
        if ($null -eq $ctrls) { continue }
        try {
            if (-not [string]::IsNullOrWhiteSpace($deviceRegistryPath)) {
                if ($ctrls -is [System.Collections.IDictionary] -and $ctrls.ContainsKey('PciAspmRegistryPath') -and [string]::Equals([string]$ctrls['PciAspmRegistryPath'], $deviceRegistryPath, [System.StringComparison]::OrdinalIgnoreCase)) { return $ctrls }
                if ([string]::Equals([string](Get-PropValue $k 'RegistryPath'), $deviceRegistryPath, [System.StringComparison]::OrdinalIgnoreCase)) { return $ctrls }
            }
            if (-not [string]::IsNullOrWhiteSpace($deviceKey) -and [string]::Equals([string](Get-PropValue $k 'DeviceKey'), $deviceKey, [System.StringComparison]::OrdinalIgnoreCase)) { return $ctrls }
        } catch { }
    }
    return $null
}


function Set-DeviceTweakerControlInputEnabled {
    param(
        [AllowNull()][object]$Control,
        [Parameter(Mandatory=$true)][bool]$Enabled
    )
    if ($Control -is [System.Windows.Forms.Control]) {
        try { $Control.Enabled = $Enabled } catch { }
        try { $Control.Invalidate() } catch { }
    }
}

function Set-DeviceTweakerControlsEnabledByKey {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)][string[]]$Keys,
        [Parameter(Mandatory=$true)][bool]$Enabled
    )
    foreach ($key in @($Keys)) {
        if ([string]::IsNullOrWhiteSpace($key)) { continue }
        try {
            if ($Controls.ContainsKey($key)) { Set-DeviceTweakerControlInputEnabled -Control $Controls[$key] -Enabled $Enabled }
        } catch { }
    }
}

