    if ($Controls.ContainsKey('PciMsixEnableCheck') -and $Controls['PciMsixEnableCheck'] -is [System.Windows.Forms.CheckBox]) { $Controls['PciMsixEnableCheck'].Text = 'MSI-X .../...'; try { $Controls['PciMsixEnableCheck'].Invalidate() } catch { } }
}

$script:DeviceTweakerPciAspmRefreshClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAspmCombo')) { return }
    try {
        $button.Enabled = $false
        $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe ASPM read key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function }
        $label = $ctrls['PciAspmStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        Set-DeviceTweakerPciAspmReadPending -Controls $ctrls
        Start-PolledRunspaceTask -TaskName 'PciAspmRead' -ScriptText (Get-AsyncPciAspmWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciAspmResultsToUI -Results @($Result) } finally { try { $button.Enabled = $true } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { $button.Enabled = $true } catch { }
            $label = $ctrls['PciAspmStatusLabel']
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        try { $button.Enabled = $true } catch { }
        $label = $ctrls['PciAspmStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $_.Exception.Message); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

