$script:DeviceTweakerPciDeviceControlSetClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLinkStatusLabel')) { return }
    try {
        $relaxed = $false
        $relaxedCheck = $ctrls['PciRelaxedOrderingCheck']
        if ($relaxedCheck -is [System.Windows.Forms.CheckBox]) { $relaxed = [bool]$relaxedCheck.Checked }
        $extTag = $false
        $extTagCheck = $ctrls['PciExtendedTagCheck']
        if ($extTagCheck -is [System.Windows.Forms.CheckBox]) { $extTag = [bool]$extTagCheck.Checked }
        $tenBitTag = $false
        $tenBitTagCheck = $ctrls['PciTenBitTagRequesterCheck']
        if ($tenBitTagCheck -is [System.Windows.Forms.CheckBox]) { $tenBitTag = [bool]$tenBitTagCheck.Checked }
        $noSnoop = $false
