$script:DeviceTweakerPciLtrObffSetClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLtrObffStatusLabel')) { return }
    try {
        $ltr = $false
        $check = $ctrls['PciLtrEnableCheck']
        if ($check -is [System.Windows.Forms.CheckBox]) { $ltr = [bool]$check.Checked }
        $obffMode = 0
        $combo = $ctrls['PciObffCombo']
        if ($combo -is [System.Windows.Forms.ComboBox]) {
            $selectedObffText = [string]$combo.SelectedItem
            if ([string]::IsNullOrWhiteSpace($selectedObffText)) { $selectedObffText = [string]$combo.Text }
            if ($selectedObffText -like '*MsgA*') { $obffMode = 1 }
            elseif ($selectedObffText -like '*MsgB*') { $obffMode = 2 }
            elseif ($selectedObffText -like '*WAKE#*') { $obffMode = 3 }
            else { $obffMode = 0 }
        }
        $maxSnoopLatencyNs = $null
        $nudSnoop = $ctrls['PciLtrMaxSnoopLatencyNsValue']
        if ($nudSnoop -is [System.Windows.Forms.NumericUpDown] -and $nudSnoop.Enabled) { $maxSnoopLatencyNs = [uint64]$nudSnoop.Value }
        $maxNoSnoopLatencyNs = $null
        $nudNoSnoop = $ctrls['PciLtrMaxNoSnoopLatencyNsValue']
        if ($nudNoSnoop -is [System.Windows.Forms.NumericUpDown] -and $nudNoSnoop.Enabled) { $maxNoSnoopLatencyNs = [uint64]$nudNoSnoop.Value }
        $button.Enabled = $false
        $button.Text = 'SET...'
        Start-AsyncPciLtrObffApply -Device $device -Controls $ctrls -EnableLtr $ltr -ObffMode $obffMode -MaxSnoopLatencyNs $maxSnoopLatencyNs -MaxNoSnoopLatencyNs $maxNoSnoopLatencyNs -Button $button
    } catch {
        try { $button.Enabled = $true; $button.Text = 'SET LTR/OBFF'; $button.Invalidate() } catch { }
        $label = $ctrls['PciLtrObffStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $_.Exception.Message); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}


