    try {
        $barIndex = 0
        $targetSizeEncoded = $null
        $enable = $true
        if (($ctrls.ContainsKey('PciRebarEnableCheck')) -and ($ctrls['PciRebarEnableCheck'] -is [System.Windows.Forms.CheckBox])) { $enable = [bool]$ctrls['PciRebarEnableCheck'].Checked }
        if (($ctrls.ContainsKey('PciRebarBarCombo')) -and ($ctrls['PciRebarBarCombo'] -is [System.Windows.Forms.ComboBox])) {
            $barText = [string]$ctrls['PciRebarBarCombo'].SelectedItem
            if ($barText -match 'BAR([0-5])') { $barIndex = [int]$Matches[1] }
        }
        if (($ctrls.ContainsKey('PciRebarSizeCombo')) -and ($ctrls['PciRebarSizeCombo'] -is [System.Windows.Forms.ComboBox])) {
            $sizeText = [string]$ctrls['PciRebarSizeCombo'].SelectedItem
