        }
        $button.Enabled = $false
        Start-AsyncPciRebarApply -Device $device -Controls $ctrls -BarIndex $barIndex -Enable:$enable -TargetSizeEncoded $targetSizeEncoded -Button $button
    } catch {
        try { $button.Enabled = $true; $button.Invalidate() } catch { }
