        if (($ctrls.ContainsKey('PciDpcInterruptEnableCheck')) -and ($ctrls['PciDpcInterruptEnableCheck'] -is [System.Windows.Forms.CheckBox])) { $dpcIrq = [bool]$ctrls['PciDpcInterruptEnableCheck'].Checked }
        if (($ctrls.ContainsKey('PciMsiEnableCheck')) -and ($ctrls['PciMsiEnableCheck'] -is [System.Windows.Forms.CheckBox])) { $msiEnable = [bool]$ctrls['PciMsiEnableCheck'].Checked }
