        if (($ctrls.ContainsKey('PciAtsEnableCheck')) -and ($ctrls['PciAtsEnableCheck'] -is [System.Windows.Forms.CheckBox])) { $atsEnable = [bool]$ctrls['PciAtsEnableCheck'].Checked }
