        }

        $lmrApply = $false
        if (($ctrls.ContainsKey('PciLmrApplyCheck')) -and ($ctrls['PciLmrApplyCheck'] -is [System.Windows.Forms.CheckBox])) { $lmrApply = [bool]$ctrls['PciLmrApplyCheck'].Checked }
        if ($lmrApply) {
            $lmrCommand = 'NoCommand'
            if (($ctrls.ContainsKey('PciLmrCommandCombo')) -and ($ctrls['PciLmrCommandCombo'] -is [System.Windows.Forms.ComboBox]) -and $null -ne $ctrls['PciLmrCommandCombo'].SelectedItem) { $lmrCommand = [string]$ctrls['PciLmrCommandCombo'].SelectedItem }
            $lmrReceiver = 0
            if (($ctrls.ContainsKey('PciLmrReceiverValue')) -and ($ctrls['PciLmrReceiverValue'] -is [System.Windows.Forms.NumericUpDown])) { $lmrReceiver = [int]$ctrls['PciLmrReceiverValue'].Value }
            $lmrTiming = 0
            if (($ctrls.ContainsKey('PciLmrTimingStepsValue')) -and ($ctrls['PciLmrTimingStepsValue'] -is [System.Windows.Forms.NumericUpDown])) { $lmrTiming = [int]$ctrls['PciLmrTimingStepsValue'].Value }
            $lmrVoltage = 0
            if (($ctrls.ContainsKey('PciLmrVoltageStepsValue')) -and ($ctrls['PciLmrVoltageStepsValue'] -is [System.Windows.Forms.NumericUpDown])) { $lmrVoltage = [int]$ctrls['PciLmrVoltageStepsValue'].Value }
            $lmrErrorLimit = 0
            if (($ctrls.ContainsKey('PciLmrErrorLimitValue')) -and ($ctrls['PciLmrErrorLimitValue'] -is [System.Windows.Forms.NumericUpDown])) { $lmrErrorLimit = [int]$ctrls['PciLmrErrorLimitValue'].Value }
            $lmrGoLeft = $false
            if (($ctrls.ContainsKey('PciLmrGoLeftCheck')) -and ($ctrls['PciLmrGoLeftCheck'] -is [System.Windows.Forms.CheckBox])) { $lmrGoLeft = [bool]$ctrls['PciLmrGoLeftCheck'].Checked }
            $lmrGoDown = $false
            if (($ctrls.ContainsKey('PciLmrGoDownCheck')) -and ($ctrls['PciLmrGoDownCheck'] -is [System.Windows.Forms.CheckBox])) { $lmrGoDown = [bool]$ctrls['PciLmrGoDownCheck'].Checked }
            $lmrVerifyEcho = $false
            if (($ctrls.ContainsKey('PciLmrVerifyEchoCheck')) -and ($ctrls['PciLmrVerifyEchoCheck'] -is [System.Windows.Forms.CheckBox])) { $lmrVerifyEcho = [bool]$ctrls['PciLmrVerifyEchoCheck'].Checked }

            $applyParams['LmrCommand'] = $lmrCommand
            $applyParams['LmrReceiverNumber'] = $lmrReceiver
            $applyParams['LmrTimingSteps'] = $lmrTiming
            $applyParams['LmrVoltageSteps'] = $lmrVoltage
            $applyParams['LmrErrorLimit'] = $lmrErrorLimit
            $applyParams['LmrGoLeft'] = $lmrGoLeft
            $applyParams['LmrGoDown'] = $lmrGoDown
            $applyParams['LmrVerifyEcho'] = $lmrVerifyEcho
            $applyParams['LmrResetToNoCommand'] = $true

            if (($ctrls.ContainsKey('PciLmrLanesText')) -and ($ctrls['PciLmrLanesText'] -is [System.Windows.Forms.TextBox])) {
                $laneText = [string]$ctrls['PciLmrLanesText'].Text
                if (-not [string]::IsNullOrWhiteSpace($laneText)) { $applyParams['LmrLanes'] = $laneText }
            }
            if (($ctrls.ContainsKey('PciLmrRawCommandText')) -and ($ctrls['PciLmrRawCommandText'] -is [System.Windows.Forms.TextBox])) {
                $rawText = ([string]$ctrls['PciLmrRawCommandText'].Text).Trim()
                if (-not [string]::IsNullOrWhiteSpace($rawText) -and $lmrCommand -eq 'Raw') {
                    if ($rawText -match '^0x') { $applyParams['LmrRawCommand'] = [Convert]::ToInt32($rawText.Substring(2), 16) }
                    else { $applyParams['LmrRawCommand'] = [Convert]::ToInt32($rawText, 10) }
                }
            }
        }

        $phyPresetApply = $false
        if (($ctrls.ContainsKey('PciPhyPresetApplyCheck')) -and ($ctrls['PciPhyPresetApplyCheck'] -is [System.Windows.Forms.CheckBox])) { $phyPresetApply = [bool]$ctrls['PciPhyPresetApplyCheck'].Checked }
        if ($phyPresetApply) {
            $phyPresetRate = '32GT'
            if (($ctrls.ContainsKey('PciPhyPresetRateCombo')) -and ($ctrls['PciPhyPresetRateCombo'] -is [System.Windows.Forms.ComboBox])) {
                $selectedRate = [string]$ctrls['PciPhyPresetRateCombo'].SelectedItem
                if ([string]::IsNullOrWhiteSpace($selectedRate)) { $selectedRate = [string]$ctrls['PciPhyPresetRateCombo'].Text }
                if (-not [string]::IsNullOrWhiteSpace($selectedRate)) { $phyPresetRate = $selectedRate }
            }
            $phyStartLane = 0
            if (($ctrls.ContainsKey('PciPhyPresetStartLaneValue')) -and ($ctrls['PciPhyPresetStartLaneValue'] -is [System.Windows.Forms.NumericUpDown])) { $phyStartLane = [int]$ctrls['PciPhyPresetStartLaneValue'].Value }
            $phyPresetBytes = ''
            if (($ctrls.ContainsKey('PciPhyPresetBytesText')) -and ($ctrls['PciPhyPresetBytesText'] -is [System.Windows.Forms.TextBox])) { $phyPresetBytes = ([string]$ctrls['PciPhyPresetBytesText'].Text).Trim() }
            if ([string]::IsNullOrWhiteSpace($phyPresetBytes)) { throw 'PHY-LE is checked, but no per-lane preset byte values were entered. Use raw bytes like 0x75,0x97 or named pairs like D7/U5 D9/U7; low nibble=DPTx preset, high nibble=UPTx preset.' }
            $applyParams['PhysicalLayerRawCapability'] = $phyPresetRate
            $applyParams['PhysicalLayerLaneEqualizationPresetStartLane'] = $phyStartLane
            $applyParams['PhysicalLayerLaneEqualizationPresetBytes'] = $phyPresetBytes
        }

        $button.Enabled = $false
        $button.Text = 'SET...'
        Start-AsyncPciAerDpcAcsApply @applyParams
    } catch {
        try { $button.Enabled = $true; $button.Text = 'SET PCIe EXT'; $button.Invalidate() } catch { }
        $label = $ctrls['PciAerDpcAcsStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $_.Exception.Message); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

function Register-DeviceTweakerPciRebarUiHandlers {
    param([AllowNull()][object]$ControlMap)
    if ($null -eq $ControlMap) { return }
    if ($null -eq $script:DeviceTweakerPciRebarWiredButtonIds) { $script:DeviceTweakerPciRebarWiredButtonIds = [System.Collections.Generic.HashSet[int]]::new() }
    foreach ($entry in @($ControlMap.GetEnumerator())) {
        $ctrls = $entry.Value
        if ($null -eq $ctrls) { continue }
        foreach ($pair in @(@('PciRebarRefreshButton',$script:DeviceTweakerPciRebarRefreshClickHandler), @('PciRebarSetButton',$script:DeviceTweakerPciRebarSetClickHandler))) {
            try {
                $key = [string]$pair[0]
                if (-not $ctrls.ContainsKey($key)) { continue }
                $button = $ctrls[$key] -as [System.Windows.Forms.Button]
                if ($null -eq $button) { continue }
                $id = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($button)
                if ($script:DeviceTweakerPciRebarWiredButtonIds.Add($id)) { $button.Add_Click([System.EventHandler]$pair[1]) }
            } catch { }
        }
        try {
            if ($ctrls.ContainsKey('PciRebarBarCombo')) {
                $combo = $ctrls['PciRebarBarCombo'] -as [System.Windows.Forms.ComboBox]
                if ($null -ne $combo) {
                    $comboId = [System.Runtime.CompilerServices.RuntimeHelpers]::GetHashCode($combo)
                    if ($script:DeviceTweakerPciRebarWiredButtonIds.Add($comboId)) {
                        $localCtrls = $ctrls
                        $combo.Add_SelectedIndexChanged({ param($sender,$eventArgs) Update-PciRebarSizeComboForSelectedBar -Controls $localCtrls }.GetNewClosure())
                    }
                }
            }
        } catch { }
    }
}

$script:DeviceTweakerNvmeRefreshClickHandler = {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $btn = [System.Windows.Forms.Button]$this
    $device = $btn.Tag
    if ($null -eq $device -or -not $deviceControls.ContainsKey($device)) { return }
    $ctrls = $deviceControls[$device]
    $path = Resolve-NVMePhysicalDrivePathForDevice -device $device -ctrls $ctrls
    if ([string]::IsNullOrWhiteSpace($path)) {
        Show-DarkMessageBox -Message 'Cannot resolve a PhysicalDrive path for this NVMe device.' -Title 'Error' -Icon Error
        return
    }
    $isPowerRead = ($ctrls.ContainsKey('NVMePowerRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMePowerRefreshButton']))
    $isVwcRead = ($ctrls.ContainsKey('NVMeVwcRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeVwcRefreshButton']))
    $isTempRead = ($ctrls.ContainsKey('NVMeTempRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeTempRefreshButton']))
    $isWanRead = ($ctrls.ContainsKey('NVMeWanRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeWanRefreshButton']))
    $isHmbRead = ($ctrls.ContainsKey('NVMeHmbRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeHmbRefreshButton']))
    $isErrRead = ($ctrls.ContainsKey('NVMeErrRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeErrRefreshButton']))
    $isHctmRead = ($ctrls.ContainsKey('NVMeHctmRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeHctmRefreshButton']))
    $isArbRead = ($ctrls.ContainsKey('NVMeArbRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeArbRefreshButton']))
    $isNoqRead = ($ctrls.ContainsKey('NVMeNoqRefreshButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeNoqRefreshButton']))
    $readKind = if ($isPowerRead) { 'Power' } elseif ($isVwcRead) { 'Vwc' } elseif ($isTempRead) { 'Temp' } elseif ($isWanRead) { 'Wan' } elseif ($isHmbRead) { 'Hmb' } elseif ($isErrRead) { 'Err' } elseif ($isHctmRead) { 'Hctm' } elseif ($isArbRead) { 'Arb' } elseif ($isNoqRead) { 'Noq' } else { 'Interrupt' }
    $restoreText = if ($isPowerRead) { 'READ PWR' } elseif ($isVwcRead) { 'READ VWC' } elseif ($isTempRead) { 'READ TEMP' } elseif ($isWanRead) { 'READ WAN' } elseif ($isHmbRead) { 'READ HMB' } elseif ($isErrRead) { 'READ ERR' } elseif ($isHctmRead) { 'READ HCTM' } elseif ($isArbRead) { 'READ ARB' } elseif ($isNoqRead) { 'READ NOQ' } else { 'READ' }
    try {
        $btn.Text = 'READ...'
        $btn.Enabled = $false
        if ($ctrls.ContainsKey('NVMeDrivePath')) { $ctrls.NVMeDrivePath = [string]$path }
        if ($readKind -eq 'Interrupt' -and $ctrls.ContainsKey('NVMeTimeLabel') -and $ctrls.NVMeTimeLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeTimeLabel.Text = 'Reading IC...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTimeLabel }
        if ($readKind -eq 'Power' -and $ctrls.ContainsKey('NVMeApstPowerStatusLabel') -and $ctrls.NVMeApstPowerStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeApstPowerStatusLabel.Text = 'Reading APST/PS...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeApstPowerStatusLabel }
        if ($readKind -eq 'Vwc' -and $ctrls.ContainsKey('NVMeVwcStatusLabel') -and $ctrls.NVMeVwcStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeVwcStatusLabel.Text = 'Reading VWC...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeVwcStatusLabel }
        if ($readKind -eq 'Temp' -and $ctrls.ContainsKey('NVMeTempStatusLabel') -and $ctrls.NVMeTempStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeTempStatusLabel.Text = 'Reading TEMP...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTempStatusLabel }
        if ($readKind -eq 'Wan' -and $ctrls.ContainsKey('NVMeWanStatusLabel') -and $ctrls.NVMeWanStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeWanStatusLabel.Text = 'Reading WAN...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeWanStatusLabel }
        if ($readKind -eq 'Hmb' -and $ctrls.ContainsKey('NVMeHmbStatusLabel') -and $ctrls.NVMeHmbStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeHmbStatusLabel.Text = 'Reading HMB...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHmbStatusLabel }
        if ($readKind -eq 'Err' -and $ctrls.ContainsKey('NVMeErrStatusLabel') -and $ctrls.NVMeErrStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeErrStatusLabel.Text = 'Reading Error Recovery...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeErrStatusLabel }
        if ($readKind -eq 'Hctm' -and $ctrls.ContainsKey('NVMeHctmStatusLabel') -and $ctrls.NVMeHctmStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeHctmStatusLabel.Text = 'Reading HCTM...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHctmStatusLabel }
        if ($readKind -eq 'Arb' -and $ctrls.ContainsKey('NVMeArbStatusLabel') -and $ctrls.NVMeArbStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeArbStatusLabel.Text = 'Reading ARB...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel }
        if ($readKind -eq 'Noq' -and $ctrls.ContainsKey('NVMeNoqStatusLabel') -and $ctrls.NVMeNoqStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeNoqStatusLabel.Text = 'Reading NOQ...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeNoqStatusLabel }
        $tempSelection = Get-NVMeTemperatureSelectionFromControls -ctrls $ctrls
        $errSelection = Get-NVMeErrorRecoverySelectionFromControls -ctrls $ctrls
        $script:nvmeSingleReadTask = Start-PolledRunspaceTask -TaskName ('NVMe{0}Read' -f $readKind) -ScriptText (Get-AsyncNVMeInterruptCoalescingWorkerScript) -Arguments @(@([PSCustomObject]@{ Key = [string]$device.RegistryPath; DrivePath = [string]$path; ReadKind = [string]$readKind; TempSensorSelect = [int]$tempSelection.SensorSelect; TempThresholdType = [int]$tempSelection.ThresholdType; ErrNamespaceId = [uint32]$errSelection.NamespaceId })) -OnCompleted {
            param($results)
            try { Apply-AsyncNVMeInterruptCoalescingResultsToUI -resultItems $results }
            finally {
                $btn.Text = $restoreText
                $btn.Enabled = $true
                try { $btn.Invalidate() } catch { }
            }
        }.GetNewClosure() -OnFailed {
            param($err)
            try {
                $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
                if ($isNoqRead -and -not (Test-NVMeNumberOfQueuesUnsupportedError -Message $detail)) { Write-NVMeNumberOfQueuesDetailedErrorToConsole -Message $detail -Operation Read }
                Show-DarkMessageBox -Message ("Failed to read NVMe feature state.`n`n$detail") -Title 'Error' -Icon Error
            } finally {
                $btn.Text = $restoreText
                $btn.Enabled = $true
                try { $btn.Invalidate() } catch { }
            }
        }.GetNewClosure()
    } catch {
        $btn.Text = $restoreText
        $btn.Enabled = $true
        Show-DarkMessageBox -Message ("Failed to start NVMe feature read.`n`n$($_.Exception.Message)") -Title 'Error' -Icon Error
    }
}

$script:DeviceTweakerNvmeSetClickHandler = {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $btn = [System.Windows.Forms.Button]$this
    $device = $btn.Tag
    if ($null -eq $device -or -not $deviceControls.ContainsKey($device)) { return }
    $ctrls = $deviceControls[$device]
    $path = Resolve-NVMePhysicalDrivePathForDevice -device $device -ctrls $ctrls
    if ([string]::IsNullOrWhiteSpace($path)) {
        Show-DarkMessageBox -Message 'Cannot resolve a PhysicalDrive path for this NVMe device.' -Title 'Error' -Icon Error
        return
    }
    $isApstDisable = ($ctrls.ContainsKey('NVMeApstDisableButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeApstDisableButton']))
    $isForcePs0 = ($ctrls.ContainsKey('NVMeForcePs0Button') -and [object]::ReferenceEquals($btn, $ctrls['NVMeForcePs0Button']))
    $isVwcSet = ($ctrls.ContainsKey('NVMeVwcSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeVwcSetButton']))
    $isTempSet = ($ctrls.ContainsKey('NVMeTempSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeTempSetButton']))
    $isWanSet = ($ctrls.ContainsKey('NVMeWanSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeWanSetButton']))
    $isHmbSet = ($ctrls.ContainsKey('NVMeHmbSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeHmbSetButton']))
    $isErrSet = ($ctrls.ContainsKey('NVMeErrSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeErrSetButton']))
    $isHctmSet = ($ctrls.ContainsKey('NVMeHctmSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeHctmSetButton']))
    $isArbSet = ($ctrls.ContainsKey('NVMeArbSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeArbSetButton']))
    $isNoqSet = ($ctrls.ContainsKey('NVMeNoqSetButton') -and [object]::ReferenceEquals($btn, $ctrls['NVMeNoqSetButton']))
    $restoreText = if ($isApstDisable) { 'DIS APST' } elseif ($isForcePs0) { 'PS0' } elseif ($isVwcSet) { 'SET VWC' } elseif ($isTempSet) { 'SET TEMP' } elseif ($isWanSet) { 'SET WAN' } elseif ($isHmbSet) { 'SET HMB' } elseif ($isErrSet) { 'SET ERR' } elseif ($isHctmSet) { 'SET HCTM' } elseif ($isArbSet) { 'SET ARB' } elseif ($isNoqSet) { 'SET NOQ' } else { 'SET' }
    try {
        if ($ctrls.ContainsKey('NVMeDrivePath')) { $ctrls.NVMeDrivePath = [string]$path }
        if ($isApstDisable) {
            $btn.Text = 'DIS...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeApstPowerStatusLabel') -and $ctrls.NVMeApstPowerStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeApstPowerStatusLabel.Text = 'Disabling APST...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeApstPowerStatusLabel }
            Start-AsyncNVMeApstDisableApply -button $btn -ctrls $ctrls -drivePath $path
            return
        }
        if ($isForcePs0) {
            $btn.Text = 'PS0...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeApstPowerStatusLabel') -and $ctrls.NVMeApstPowerStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeApstPowerStatusLabel.Text = 'Forcing PS0...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeApstPowerStatusLabel }
            Start-AsyncNVMeForcePs0Apply -button $btn -ctrls $ctrls -drivePath $path
            return
        }
        if ($isVwcSet) {
            $enabled = $true
            try { if ($ctrls.ContainsKey('NVMeVwcCombo') -and $ctrls.NVMeVwcCombo -is [System.Windows.Forms.ComboBox]) { $enabled = ([int]$ctrls.NVMeVwcCombo.SelectedIndex -eq 1) } } catch { $enabled = $true }
            $btn.Text = 'VWC...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeVwcStatusLabel') -and $ctrls.NVMeVwcStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeVwcStatusLabel.Text = 'Setting VWC...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeVwcStatusLabel }
            Start-AsyncNVMeVolatileWriteCacheApply -button $btn -ctrls $ctrls -drivePath $path -enabled ([bool]$enabled)
            return
        }
        if ($isTempSet) {
            $tempSelection = Get-NVMeTemperatureSelectionFromControls -ctrls $ctrls
            $btn.Text = 'TEMP...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeTempStatusLabel') -and $ctrls.NVMeTempStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeTempStatusLabel.Text = 'Setting TEMP...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTempStatusLabel }
            Start-AsyncNVMeTemperatureThresholdApply -button $btn -ctrls $ctrls -drivePath $path -sensorSelect ([int]$tempSelection.SensorSelect) -thresholdType ([int]$tempSelection.ThresholdType) -thresholdCelsius ([int]$tempSelection.ThresholdCelsius)
            return
        }
        if ($isWanSet) {
            $disableNormal = $false
            try { if ($ctrls.ContainsKey('NVMeWanCombo') -and $ctrls.NVMeWanCombo -is [System.Windows.Forms.ComboBox]) { $disableNormal = ([int]$ctrls.NVMeWanCombo.SelectedIndex -eq 1) } } catch { $disableNormal = $false }
            $btn.Text = 'WAN...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeWanStatusLabel') -and $ctrls.NVMeWanStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeWanStatusLabel.Text = 'Setting WAN...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeWanStatusLabel }
            Start-AsyncNVMeWriteAtomicityNormalApply -button $btn -ctrls $ctrls -drivePath $path -disableNormal ([bool]$disableNormal)
            return
        }
        if ($isHmbSet) {
            $hmbSelection = Get-NVMeHostMemoryBufferSelectionFromControls -ctrls $ctrls
            $btn.Text = 'HMB...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeHmbStatusLabel') -and $ctrls.NVMeHmbStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeHmbStatusLabel.Text = 'Setting HMB...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHmbStatusLabel }
            Start-AsyncNVMeHostMemoryBufferApply -button $btn -ctrls $ctrls -drivePath $path -enabled ([bool]$hmbSelection.Enabled) -memoryReturn ([bool]$hmbSelection.MemoryReturn) -sizeMps ([uint32]$hmbSelection.SizeMps) -descriptorListLower ([uint32]$hmbSelection.DescriptorListLower) -descriptorListUpper ([uint32]$hmbSelection.DescriptorListUpper) -descriptorEntryCount ([uint32]$hmbSelection.DescriptorEntryCount)
            return
        }
        if ($isErrSet) {
            $errSelection = Get-NVMeErrorRecoverySelectionFromControls -ctrls $ctrls
            $btn.Text = 'ERR...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeErrStatusLabel') -and $ctrls.NVMeErrStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeErrStatusLabel.Text = 'Setting Error Recovery...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeErrStatusLabel }
            Start-AsyncNVMeErrorRecoveryApply -button $btn -ctrls $ctrls -drivePath $path -namespaceId ([uint32]$errSelection.NamespaceId) -timeLimitedErrorRecovery ([int]$errSelection.TimeLimitedErrorRecovery) -deallocatedOrUnwrittenLogicalBlockErrorEnabled ([bool]$errSelection.DeallocatedOrUnwrittenLogicalBlockErrorEnabled)
            return
        }
        if ($isHctmSet) {
            $hctmSelection = Get-NVMeHostControlledThermalManagementSelectionFromControls -ctrls $ctrls
            $btn.Text = 'HCTM...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeHctmStatusLabel') -and $ctrls.NVMeHctmStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeHctmStatusLabel.Text = 'Setting HCTM...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHctmStatusLabel }
            Start-AsyncNVMeHostControlledThermalManagementApply -button $btn -ctrls $ctrls -drivePath $path -thermalManagementTemperature1Celsius ([int]$hctmSelection.ThermalManagementTemperature1Celsius) -thermalManagementTemperature2Celsius ([int]$hctmSelection.ThermalManagementTemperature2Celsius)
            return
        }
        if ($isArbSet) {
            $arbSelection = Get-NVMeArbitrationSelectionFromControls -ctrls $ctrls
            $btn.Text = 'ARB...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeArbStatusLabel') -and $ctrls.NVMeArbStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeArbStatusLabel.Text = 'Setting ARB...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel }
            Start-AsyncNVMeArbitrationApply -button $btn -ctrls $ctrls -drivePath $path -arbitrationBurst ([int]$arbSelection.ArbitrationBurst) -lowPriorityWeight ([int]$arbSelection.LowPriorityWeight) -mediumPriorityWeight ([int]$arbSelection.MediumPriorityWeight) -highPriorityWeight ([int]$arbSelection.HighPriorityWeight)
            return
        }
        if ($isNoqSet) {
            $noqSelection = Get-NVMeNumberOfQueuesSelectionFromControls -ctrls $ctrls
            $btn.Text = 'NOQ...'
            $btn.Enabled = $false
            if ($ctrls.ContainsKey('NVMeNoqStatusLabel') -and $ctrls.NVMeNoqStatusLabel -is [System.Windows.Forms.Label]) { $ctrls.NVMeNoqStatusLabel.Text = 'Setting NOQ...'; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeNoqStatusLabel }
            Start-AsyncNVMeNumberOfQueuesApply -button $btn -ctrls $ctrls -drivePath $path -submissionQueues ([int]$noqSelection.SubmissionQueues) -completionQueues ([int]$noqSelection.CompletionQueues)
            return
        }
        $thr = [int]$ctrls.NVMeThreshold.Value
        $time = [int]$ctrls.NVMeTime.Value
        $btn.Text = 'SET...'
        $btn.Enabled = $false
        Start-AsyncNVMeInterruptCoalescingApply -button $btn -ctrls $ctrls -drivePath $path -threshold $thr -timeUnits $time
    } catch {
        $btn.Text = $restoreText
        $btn.Enabled = $true
        Show-DarkMessageBox -Message ("Failed to start NVMe feature set.`n`n$($_.Exception.Message)") -Title 'Error' -Icon Error
    }
}

$script:DeviceTweakerHdaRintcntRefreshClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls -or -not $ctrls.ContainsKey('HDARintcntValue')) { return }
    $label = $ctrls['HDARintcntStatusLabel']
    try {
        $button.Text = 'READ...'
        $button.Enabled = $false
        Set-HdaStatusLabelsToText -Controls $ctrls -Text 'Reading...'
        $base = Resolve-HdaMmioBaseForDevice -Device $device -Controls $ctrls -DeviceMap $globalDeviceAddressMap
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build HDA RINTCNT read key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; HdaBar0 = [uint64]$base; DeviceName = [string](Get-PropValue $device 'DisplayName') }
        Start-PolledRunspaceTask -TaskName 'HdaRintcntRead' -ScriptText (Get-AsyncHdaRintcntWorkerScript) -Arguments @(@($spec), $rwePath) -OnCompleted {
            param($Result)
            try { Apply-AsyncHdaRintcntResultsToUI -Results @($Result) } finally { try { $button.Text = 'READ'; $button.Enabled = $true; $button.Invalidate() } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { $button.Text = 'READ'; $button.Enabled = $true; $button.Invalidate() } catch { }
            $errText = if ($err -and $err.Exception) { [string]$err.Exception.Message } else { [string]$err }
            Set-HdaStatusLabelsToText -Controls $ctrls -Text ('ERR: {0}' -f $errText)
        }.GetNewClosure()
    } catch {
        try { $button.Text = 'READ'; $button.Enabled = $true; $button.Invalidate() } catch { }
        Set-HdaStatusLabelsToText -Controls $ctrls -Text ('ERR: {0}' -f $_.Exception.Message)
    }
}

$script:DeviceTweakerHdaRintcntSetClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls -or -not $ctrls.ContainsKey('HDARintcntValue')) { return }
    $nud = $ctrls['HDARintcntValue']
    if (-not ($nud -is [System.Windows.Forms.NumericUpDown])) { return }
    try {
        $value = [int]$nud.Value
        $button.Text = 'SET...'
        $button.Enabled = $false
        Start-AsyncHdaRintcntApply -Device $device -Controls $ctrls -Value $value -Button $button
    } catch {
        try { $button.Text = 'SET'; $button.Enabled = $true; $button.Invalidate() } catch { }
        $label = $ctrls['HDARintcntStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $_.Exception.Message); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

$script:DeviceTweakerHdaRingSizeSetClickHandler = {
    param($sender, $eventArgs)
    $button = $sender -as [System.Windows.Forms.Button]
    if ($null -eq $button) { return }
    $device = $button.Tag
    if ($null -eq $device) { return }
    $ctrls = Get-DeviceTweakerControlMapForDevice -Device $device
    if ($null -eq $ctrls) { return }
    $kind = $null
    $combo = $null
    $restoreText = 'SET'
    if ($ctrls.ContainsKey('HDACorbSizeSetButton') -and [object]::ReferenceEquals($button, $ctrls['HDACorbSizeSetButton'])) {
        $kind = 'CORB'
        if ($ctrls.ContainsKey('HDACorbSizeCombo')) { $combo = $ctrls['HDACorbSizeCombo'] }
        $restoreText = 'SET CORB'
    } elseif ($ctrls.ContainsKey('HDARirbSizeSetButton') -and [object]::ReferenceEquals($button, $ctrls['HDARirbSizeSetButton'])) {
        $kind = 'RIRB'
        if ($ctrls.ContainsKey('HDARirbSizeCombo')) { $combo = $ctrls['HDARirbSizeCombo'] }
        $restoreText = 'SET RIRB'
    } else {
        return
    }
    try {
        $value = Get-HdaRingSizeComboSelection -Combo $combo -Kind $kind
        $button.Text = if ($kind -eq 'CORB') { 'CORB...' } else { 'RIRB...' }
        $button.Enabled = $false
        Start-AsyncHdaRingSizeApply -Device $device -Controls $ctrls -Kind $kind -Value $value -Button $button
    } catch {
        try { $button.Text = $restoreText; $button.Enabled = $true; $button.Invalidate() } catch { }
        $statusKey = if ($kind -eq 'RIRB') { 'HDARirbSizeStatusLabel' } else { 'HDACorbSizeStatusLabel' }
        if ($ctrls.ContainsKey($statusKey) -and $ctrls[$statusKey] -is [System.Windows.Forms.Label]) {
            $ctrls[$statusKey].Text = ('ERR: {0}' -f $_.Exception.Message)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($ctrls[$statusKey]) } catch { }
        }
    }
}

$script:StartupUiBuildUsedNativeScroll = $false
Measure-Function 'Build-StartupUI' {
    $__dtButtonsBottom = [Math]::Max([Math]::Max([Math]::Max([Math]::Max([int]$btnApply.Bottom, [int]$btnAutoOpt.Bottom), [int]$btnSecretOpt.Bottom), [int]$btnBackup.Bottom), [int]$btnReset.Bottom)
    $script:_topPosUIBuild = $__dtButtonsBottom + 18
    Ensure-DeviceEditorNativeBuildContext
    $script:_deviceEditorNativeMetrics.StartTop = [int]$script:_topPosUIBuild
    $script:_deviceEditorNativeMetrics.DeviceBoxSpacing = [int]$deviceBoxSpacing

    $_startupUiOptions = [StartupUiOptions]::new()
    $_startupUiOptions.ExistingForm = $form
    $_startupUiOptions.ExistingPanel = $panel
    $_startupUiOptions.Devices = $deviceList
    $_startupUiOptions.UiStateSource = $script:deviceUiBuildState
    $_startupUiOptions.PreserveExistingControls = $true
    $_startupUiOptions.IncludeReservedCpuSets = $true
    $_startupUiOptions.BuildScrollContainer = $true
    $_startupUiOptions.DeviceStartTop = [int]$script:_topPosUIBuild
    $_startupUiOptions.DeviceBoxSpacing = [int]$deviceBoxSpacing
    $_startupUiOptions.ScrollTrackWidth = 14
    $_startupUiOptions.ScrollPaddingBottom = 20
    $_startupUiOptions.IsHeteroCpu = [bool]$script:isHeteroCpu
    $_startupUiOptions.IsDualCcdCpu = [bool]$script:IsDualCCDCpu
    $_startupUiOptions.EnableDoubleBuffer = $true

    $_startupUiBuild = [DeviceEditorBuilder]::BuildStartupUi(
        $script:StartupModel,
        $script:_deviceEditorNativeTheme,
        $script:_deviceEditorNativeMetrics,
        $_startupUiOptions
    )

    if ($null -ne $_startupUiBuild) {
        if ($null -ne $_startupUiBuild.DeviceControls) { $script:__DeviceEditorBuiltControlsMap = $_startupUiBuild.DeviceControls }
        if ($null -ne $script:deviceCpuAffinityGrids -and $null -ne $_startupUiBuild.CpuAffinityGrids -and $_startupUiBuild.CpuAffinityGrids.Length -gt 0) {
            $script:deviceCpuAffinityGrids.AddRange([CpuAffinityGrid[]]$_startupUiBuild.CpuAffinityGrids)
        }
        if ($null -ne $script:_allSecretSaveCheckboxes -and $null -ne $_startupUiBuild.SecretSaveCheckboxes -and $_startupUiBuild.SecretSaveCheckboxes.Length -gt 0) {
            $script:_allSecretSaveCheckboxes.AddRange([System.Windows.Forms.CheckBox[]]$_startupUiBuild.SecretSaveCheckboxes)
        }
        if ($null -ne $_startupUiBuild.DeviceUi) {
            [DeviceEditorBuilder]::WireDeviceButtonHandlers(
                $_startupUiBuild.DeviceUi,
                [System.EventHandler]$script:DeviceTweakerUsbSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerUsbSaveClickHandler,
                [System.EventHandler]$script:DeviceTweakerNicSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerNicSaveClickHandler,
                [System.EventHandler]$script:DeviceTweakerNvmeRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerNvmeSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerHdaRintcntRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerHdaRintcntSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciAspmRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciAspmSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciLinkRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciMrrsSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciL1ssRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciL1ssSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciL1ssThresholdSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciLtrObffRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciLtrObffSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerHdaRingSizeSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciMpsSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciDeviceControlSetClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciAerDpcAcsRefreshClickHandler,
                [System.EventHandler]$script:DeviceTweakerPciAerDpcAcsSetClickHandler
            )
            Register-DeviceTweakerPciRebarUiHandlers -ControlMap $_startupUiBuild.DeviceControls
        }
        Register-ReservedCpuSetsUiHandlers -ReservedBuild $_startupUiBuild.ReservedCpuSets
        $script:scrollInnerPanel = $_startupUiBuild.ScrollInnerPanel
        $script:scrollTrack = $_startupUiBuild.ScrollTrack
        $script:scrollThumb = $_startupUiBuild.ScrollThumb
        $script:scrollState = $_startupUiBuild.ScrollState
        $script:scrollTrackWidth = 14
        $script:scrollContentHeight = [int]$_startupUiBuild.ScrollContentHeight
        $script:StartupUiBuildUsedNativeScroll = ($null -ne $script:scrollState -and $null -ne $script:scrollInnerPanel -and $null -ne $script:scrollTrack -and $null -ne $script:scrollThumb)
        $script:_topPosUIBuild = [int]$_startupUiBuild.FinalTop
    }
    return $script:_topPosUIBuild
} | Out-Null
if ($null -ne $script:__DeviceEditorBuiltControlsMap) {
    $deviceControls = $script:__DeviceEditorBuiltControlsMap
    Remove-Variable -Name __DeviceEditorBuiltControlsMap -Scope Script -ErrorAction SilentlyContinue
}
$topPos = $script:_topPosUIBuild
try { $script:deviceList = $deviceList; $script:deviceControlMap = $deviceControls } catch { }
Set-ExovanceReadOnlyAdapterUI

try {
    $reservedArr = [ReservedCpuSetsUiNative]::GetReservedCoresLocal([int]$script:cachedLogicalCount, $script:StartupModel)
    [ReservedCpuSetsUiNative]::ApplyReservedColoring($deviceList, $deviceControls, $script:reservedCheckboxes, $reservedArr, [bool]$script:IsDualCCDCpu, $script:Ccd0CoreSet, $script:Ccd1CoreSet, $script:_isPCoreLookup)
} catch { }

$script:deviceUiBuildState = $null

$_sw_event_wiring = [System.Diagnostics.Stopwatch]::StartNew()
$btnApply.Add_Click({
    if (-not (Enter-DeviceTweakerUiAction -Name 'Apply' -Button $this)) { return }
    try {
    $confirmApply = Show-DarkMessageBox -Message "Apply all current settings to the registry?" -Title "Confirm Apply" -Buttons YesNo -Icon Question
    if ($confirmApply -ne [System.Windows.Forms.DialogResult]::Yes) { return }

    $writableDevices = @(Get-ExovanceWritableDevices -Devices $deviceList)
    foreach ($device in $writableDevices) {
        if ($device.Category -ne 'Network' -or $device.Role -ne 'NDIS') { continue }
        $controls = $deviceControls[$device]
        if ($controls.NdisIrqToggle.Checked) { continue }
        $baseProcessor = -1
        foreach ($cell in $controls.CheckBoxes) { if ($cell.Checked) { $baseProcessor = [int]$cell.Tag; break } }
        $null = Get-ExovanceRssPlan -BaseProcessor $baseProcessor -QueueCount ([int]$controls.NumQueues.Value) -LogicalCount $script:cachedLogicalCount -PhysicalCoreMap $script:PhysicalCoreIdByLogicalProcessor
    }
    $occupiedCores = [System.Collections.ArrayList]::new()
    $weakOccupiedCores = [System.Collections.ArrayList]::new()
    $logicalCount = $script:cachedLogicalCount

    foreach ($device in $writableDevices) {
        $normRoles = [System.Collections.ArrayList]::new()
        foreach ($rr in $device.Roles) {
            if (-not $rr) { continue }
            $parts = $rr -split '[\/,;]+'
            foreach ($pp in $parts) {
                $tokRaw = $pp.Trim()
                if ($tokRaw -eq '') { continue }
                $l = $tokRaw.ToLower()
                switch -Exact ($l) {
                    'audio'      { $tok = 'Audio'; break }
                    'mic'        { $tok = 'Audio'; break }
                    'microphone' { $tok = 'Audio'; break }
                    'headphone'  { $tok = 'Audio'; break }
                    'headphones' { $tok = 'Audio'; break }
                    'headset'    { $tok = 'Audio'; break }
                    'earphone'   { $tok = 'Audio'; break }
                    'earphones'  { $tok = 'Audio'; break }
                    'iem'        { $tok = 'Audio'; break }
                    'speaker'    { $tok = 'Audio'; break }
                    'speakers'   { $tok = 'Audio'; break }
                    'keyboard'   { $tok = 'Keyboard'; break }
                    'kbd'        { $tok = 'Keyboard'; break }
                    'mouse'      { $tok = 'Mouse'; break }
                    'ms'         { $tok = 'Mouse'; break }
                    default      { $tok = $tokRaw; break }
                }
                if (-not $normRoles.Contains($tok)) { $normRoles.Add($tok) | Out-Null }
            }
        }
        $ctrls = $deviceControls[$device]

        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS") {
            $ndisIrqMode = $false
            if ($ctrls.ContainsKey('NdisIrqToggle') -and $ctrls.NdisIrqToggle -ne $null) {
                $ndisIrqMode = $ctrls.NdisIrqToggle.Checked
            }

            if ($ndisIrqMode) {
                $targetRegistryPath = if ($device.ConfigPath) { $device.ConfigPath } else { $device.RegistryPath }
                $computed = Calculate-AffinityHex $ctrls.CheckBoxes
                if ($computed -eq '0x0') { $ctrls.PolicyCombo.SelectedIndex = 0 }
                $result = Set-DeviceAffinity $targetRegistryPath $computed

                $policyValue = $ctrls.PolicyCombo.SelectedIndex
                Set-DevicePolicy $targetRegistryPath $policyValue | Out-Null

                $maskText = $ctrls.MaskValue.Text -replace "0x",""
                $assignedCores = [System.Collections.ArrayList]::new()
                if ($maskText -and ([uint64]::TryParse($maskText, [System.Globalization.NumberStyles]::HexNumber, $null, [ref]$null))) {
                    $maskInt = [Convert]::ToUInt64($maskText, 16)
                    for ($i = 0; $i -lt $logicalCount; $i++) {
                        if (($maskInt -band ([uint64]1 -shl $i)) -ne 0) {
                            $assignedCores.Add($i) | Out-Null
                        }
                    }
                }
            } else {
                $selectedBase = $null
                foreach ($chk in $ctrls.CheckBoxes) { if ($chk.Checked) { $selectedBase = [int]$chk.Tag; break } }
                if ($selectedBase -eq $null) { throw 'Select an RSS base processor, or restore your backup to undo the previous selection.' }
                else {
                    $numQueuesToWrite = 1
                    try { $numQueuesToWrite = [int]$ctrls.NumQueues.Value } catch { $numQueuesToWrite = 1 }
                    if ($numQueuesToWrite -lt 1) { $numQueuesToWrite = 1 }

                    $plan = Set-ExovanceRssConfiguration -RegistryPath $device.RegistryPath -BaseProcessor $selectedBase -QueueCount $numQueuesToWrite
                    $assignedCores = [System.Collections.ArrayList]::new([System.Collections.ICollection]$plan.Processors)

                }
            }
        }
        elseif ($device.Category -eq "Network" -and $device.Role -eq "NetAdapterCx") {
            $targetRegistryPath = Get-NetworkAdapterAffinityRegistryPath $device
            $computed = Calculate-AffinityHex $ctrls.CheckBoxes
                if ($computed -eq '0x0') { $ctrls.PolicyCombo.SelectedIndex = 0 }

            $result = Set-DeviceAffinity $targetRegistryPath $computed
            if ($result) { }
            $maskText = $ctrls.MaskValue.Text -replace "0x",""
            $assignedCores = [System.Collections.ArrayList]::new()
            if ($maskText -and ([uint64]::TryParse($maskText, [System.Globalization.NumberStyles]::HexNumber, $null, [ref]$null))) {
                $maskInt = [Convert]::ToUInt64($maskText, 16)
                for ($i = 0; $i -lt $logicalCount; $i++) {
                    if (($maskInt -band ([uint64]1 -shl $i)) -ne 0) {
                        $assignedCores.Add($i) | Out-Null
                    }
                }
            }
        }
        else {
            $computed = Calculate-AffinityHex $ctrls.CheckBoxes
                if ($computed -eq '0x0') { $ctrls.PolicyCombo.SelectedIndex = 0 }

            $result = Set-DeviceAffinity $device.RegistryPath $computed
            if ($result) { }
            $maskText = $ctrls.MaskValue.Text -replace "0x",""
            $assignedCores = [System.Collections.ArrayList]::new()
            if ($maskText -and ([uint64]::TryParse($maskText, [System.Globalization.NumberStyles]::HexNumber, $null, [ref]$null))) {
                $maskInt = [Convert]::ToUInt64($maskText, 16)
                for ($i = 0; $i -lt $logicalCount; $i++) {
                    if (($maskInt -band ([uint64]1 -shl $i)) -ne 0) {
                        $assignedCores.Add($i) | Out-Null
                    }
                }
            }
        }

        if ($device.Category -eq "Network") {
            $targetRegistryPath = Get-NetworkAdapterMSIRegistryPath $device
        } else {
            $targetRegistryPath = $device.RegistryPath
        }
        $msiEnabled = 0
        if ($ctrls.MSICombo.SelectedItem -eq "Enabled") { $msiEnabled = 1 } else { $msiEnabled = 0 }
        $msgLimit = $ctrls.MsgLimitBox.Text
        if ($msgLimit -eq "Unlimited" -or $msgLimit -eq "0") {
            $msgLimit = ""
        }
        if ($msgLimit -eq "") { $displayMsgLimit = "Unlimited" } else { $displayMsgLimit = $msgLimit }
        $msiResult = Set-DeviceMSI $targetRegistryPath $msiEnabled $msgLimit
        if (-not $msiResult) { }
        $priorityVal = 2
        switch ($ctrls.PriorityCombo.SelectedItem) {
            "Low" { $priorityVal = 1 }
            "Normal" { $priorityVal = 2 }
            "High" { $priorityVal = 3 }
        }
        $priResult = Set-DevicePriority $targetRegistryPath $priorityVal
        if (-not $priResult) { }

        if (-not ($device.Category -eq "Network" -and $device.Role -eq "NDIS")) {
            $policyValue = $ctrls.PolicyCombo.SelectedIndex

            if ($device.Category -eq "Network" -and $device.Role -eq "NetAdapterCx") {
                $policyPath = Get-NetworkAdapterAffinityRegistryPath $device
            } else {
                $policyPath = $device.RegistryPath
            }

           $policyResult = Set-DevicePolicy $policyPath $policyValue
        }

        $shouldConsiderCores = $false
        if ($device.Category -eq "Network" -and $device.Role -eq "NDIS") {
            $ndisIrqModeCheck = $false
            if ($ctrls.ContainsKey('NdisIrqToggle') -and $ctrls.NdisIrqToggle -ne $null) { $ndisIrqModeCheck = $ctrls.NdisIrqToggle.Checked }
            if ($ndisIrqModeCheck) {
                $policyValue = $ctrls.PolicyCombo.SelectedIndex
                $shouldConsiderCores = ($policyValue -eq 4)
            } else {
                $shouldConsiderCores = $true
            }
        } else {
            if ($deviceControls[$device].ContainsKey('PolicyCombo')) {
                $policyValue = $deviceControls[$device].PolicyCombo.SelectedIndex
                if ($policyValue -eq 4) {
                    $shouldConsiderCores = $true
                }
            }
        }

        if ($shouldConsiderCores) {
            if (-not $assignedCores -or $assignedCores.Count -eq 0) {
                $ctrls = $deviceControls[$device]
                $assignedCores = [System.Collections.ArrayList]::new()
                $maskText = ($ctrls.MaskValue.Text -replace "0x","").Trim()
                if ($maskText -and ([uint64]::TryParse($maskText, [System.Globalization.NumberStyles]::HexNumber, $null, [ref]$null))) {
                    $maskInt = [Convert]::ToUInt64($maskText, 16)
                    for ($i = 0; $i -lt $logicalCount; $i++) {
                        if (($maskInt -band ([uint64]1 -shl $i)) -ne 0) { $assignedCores.Add($i) | Out-Null }
                    }
                } else {
                    foreach ($chk in $ctrls.CheckBoxes) {
                        if ($chk.Checked) { $assignedCores.Add([int]$chk.Tag) | Out-Null }
                    }
                    $assignedCores = [System.Collections.ArrayList]::new([System.Collections.ICollection](ConvertTo-DeviceTweakerFastSortedUniqueIntArray $assignedCores.ToArray()))
                }
            }
            if ($device.Category -eq "PCI" -and $device.Role -eq "GPU") {
                $occupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($device.Category -eq "USB" -and ($normRoles.Contains("Mouse") -or $normRoles.Contains("Controller"))) {
                $occupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($device.Category -eq "USB" -and $normRoles.Contains("Audio") -and ($normRoles.Count -eq 1)) {
                $weakOccupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($device.Category -eq "PCI" -and $device.Role -eq "Audio") {
                $weakOccupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($device.Category -eq "Network") {
                $weakOccupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($normRoles.Contains("Keyboard") -and $normRoles.Contains("Audio")) {
                $weakOccupiedCores.AddRange($assignedCores) | Out-Null
            }
            elseif ($device.Category -eq "USB" -and $normRoles.Contains("Keyboard") -and ($normRoles.Count -eq 1)) {
                $weakOccupiedCores.AddRange($assignedCores) | Out-Null
            }
            else {
                if ($assignedCores) {
                    $weakOccupiedCores.AddRange($assignedCores) | Out-Null
                }
            }
        }
    }

    $occupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $occupiedCores.ToArray())
    $occupiedCoresString = $occupiedCores -join ','

    $weakOccupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $weakOccupiedCores.ToArray())
    $weakOccupiedCoresString = $weakOccupiedCores -join ','

    $mouseCore = $null
    foreach ($dev in $deviceList) {
        if ($dev.Category -eq "USB" -and $dev.Roles -contains "Mouse") {
            $ctrls = $deviceControls[$dev]
            $maskValue = $ctrls.MaskValue.Text -replace "0x",""

            if ([uint64]::TryParse($maskValue, [System.Globalization.NumberStyles]::HexNumber, $null, [ref]$null)) {
                $maskInt = [Convert]::ToUInt64($maskValue, 16)
                if ($maskInt -gt 0) {
                    for ($i = 0; $i -lt $logicalCount; $i++) {
                        if (($maskInt -band ([uint64]1 -shl $i)) -ne 0) {
                            $mouseCore = $i
                            break
                        }
                    }
                }
            }
            break
        }
    }

    Refresh-DeviceUI

    $gamesCfgPath = Join-Path $script:cachedScriptDir "games_priorities.cfg"
    $systemCfgPath = Join-Path $script:cachedScriptDir "system_priorities.cfg"

    function Update-ConfigFile {
        param (
            [string]$filePath,
            [string]$coresString,
            [string]$weakCoresString = "",
            [int]   $mouseCore = -1,
            [int]   $dwmCore   = -1
        )
        $content = if (Test-Path $filePath) {
            [System.IO.File]::ReadAllText($filePath, [System.Text.Encoding]::UTF8)
        } else {
            ""
        }

        if ($dwmCore -ge 0 -and $filePath.EndsWith("system_priorities.cfg")) {
            $pattern = 'threaddesc=DWM Kernel Sensor Thread, \(.*?\)'
            $replacement = "threaddesc=DWM Kernel Sensor Thread, ($dwmCore)"
            $content = $content -replace $pattern, $replacement
        }

        if ($mouseCore -ge 0 -and $filePath.EndsWith("system_priorities.cfg")) {
            $pattern = 'threaddesc=DWM Master Input Thread, \(.*?\)'
            $replacement = "threaddesc=DWM Master Input Thread, ($mouseCore)"
            $content = $content -replace $pattern, $replacement
        }

        $content = $content -replace '(?m)^occupied_affinity_cores=.*$', "occupied_affinity_cores=$coresString"
        $content = $content -replace '(?m)^occupied_ideal_processor_cores=.*$', "occupied_ideal_processor_cores=$coresString"

        $content = $content -replace '(?m)^occupied_weak_affinity_cores=.*$', "occupied_weak_affinity_cores=$weakCoresString"
        $content = $content -replace '(?m)^occupied_weak_ideal_processor_cores=.*$', "occupied_weak_ideal_processor_cores=$weakCoresString"

        if (-not ($content -match "occupied_affinity_cores=")) {
            $content += "`r`noccupied_affinity_cores=$coresString"
        }
        if (-not ($content -match "occupied_ideal_processor_cores=")) {
            $content += "`r`noccupied_ideal_processor_cores=$coresString"
        }

        if (-not ($content -match "occupied_weak_affinity_cores=")) {
            $content += "`r`noccupied_weak_affinity_cores=$weakCoresString"
        }
        if (-not ($content -match "occupied_weak_ideal_processor_cores=")) {
            $content += "`r`noccupied_weak_ideal_processor_cores=$weakCoresString"
        }

        $content = Set-PreferredCCDConfigLine -Content $content -PreferredCcd (Get-PreferredCCDForConfig)

        [System.IO.File]::WriteAllText($filePath, $content.Trim(), [System.Text.UTF8Encoding]::new($false))
    }

    $secretTweakPath = Join-Path $script:cachedScriptDir "SecretTweak.exe"
    if (Test-Path $secretTweakPath) {
        Update-ConfigFile -filePath $gamesCfgPath -coresString $occupiedCoresString -weakCoresString $weakOccupiedCoresString
        Update-ConfigFile -filePath $systemCfgPath -coresString $occupiedCoresString -weakCoresString $weakOccupiedCoresString -mouseCore $mouseCore -dwmCore $dwmCore
    } else {
        Write-Host "[Config] Optional legacy CFG export unavailable - skipped" -ForegroundColor DarkYellow
    }

    Assert-ExovanceWritesSucceeded
    Set-ExovanceUiFeedback -State Applied -Text 'Settings applied - restart may be needed'
    Show-DarkMessageBox -Message "Settings applied. A system restart may be required." -Title "Done" -Icon Information

    } catch {
        Set-ExovanceUiFeedback -State Error -Text 'Action incomplete - review error details'
        Show-DarkMessageBox -Message ("Apply failed: " + $_.Exception.Message) -Title 'Apply - incomplete' -Icon Error
    } finally {
        Exit-DeviceTweakerUiAction
    }
})

function Get-AutoOptRoles($device) {

    function Normalize-RawRoles($rawRoles) {
        $norm = @()
        foreach ($r in $rawRoles) {
            if (-not $r) { continue }
            $parts = $r -split '[\/,;]+'
            foreach ($p in $parts) {
                $t = $p.Trim()
                if ($t -eq '') { continue }
                $lt = $t.ToLower()
                switch -Exact ($lt) {
                    'audio'      { $tok = 'Audio'; break }
                    'mic'        { $tok = 'Audio'; break }
                    'microphone' { $tok = 'Audio'; break }
                    'headphone'  { $tok = 'Audio'; break }
                    'headphones' { $tok = 'Audio'; break }
                    'headset'    { $tok = 'Audio'; break }
                    'earphone'   { $tok = 'Audio'; break }
                    'earphones'  { $tok = 'Audio'; break }
                    'iem'        { $tok = 'Audio'; break }
                    'speaker'    { $tok = 'Audio'; break }
                    'speakers'   { $tok = 'Audio'; break }
                    'keyboard'   { $tok = 'Keyboard'; break }
                    'kbd'        { $tok = 'Keyboard'; break }
                    'mouse'      { $tok = 'Mouse'; break }
                    'ms'         { $tok = 'Mouse'; break }
                    default      { $tok = $t; break }
                }
                if (-not ($norm -contains $tok)) { $norm += $tok }
            }
        }
        return $norm
    }

    if ($device.Category -eq 'USB') {
        $normRoles = Normalize-RawRoles $device.Roles
        $nonAudio = $normRoles | Where-Object { $_ -ne 'Audio' }
        if (-not $nonAudio -and $normRoles.Count -gt 0) { return @('Audio') }

        $result = @()
        if ($normRoles -contains 'Audio') { $result += 'Audio' }
        foreach ($t in $normRoles) { if ($t -ne 'Audio' -and -not ($result -contains $t)) { $result += $t } }
        return $result
    }

    return Normalize-RawRoles $device.Roles
}

function Get-PCoreIndices {
    $pCoreIndices = @()
    $logicalCount = $script:cachedLogicalCount
    for ($i = 0; $i -lt $logicalCount; $i++) {
        if (Is-PCore $i) {
            $pCoreIndices += $i
        }
    }
    return $pCoreIndices
}

function Get-SmtSets($logicalCount, $pCores) {
    $smtSets = @()
    foreach ($core in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $script:PhysicalCoreTopology 'Id')) {
        $members = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $core.LogicalProcessors 0 ([Math]::Max(0, $logicalCount - 1)))
        if ($members.Count -lt 2) { continue }

        $allMembersArePCores = $true
        foreach ($member in $members) {
            if (-not ($pCores -contains $member)) {
                $allMembersArePCores = $false
                break
            }
        }

        if ($allMembersArePCores) {
            $smtSets += @{ Id = [int]$core.Id; Cores = $members }
        }
    }
    return $smtSets
}

function CoreMaskFromIndex($coreIndex) {
    return ('{0:X16}' -f (ConvertTo-ExovanceAffinityMask @([int]$coreIndex)))
}

function Reserve-Core($core, [ref]$usedCores, [ref]$usedSmtSets, $smtSetId) {
    $usedCores.Value[$core] = $true
    if ($smtSetId -ne $null) { $usedSmtSets.Value[$smtSetId] = $true }
}

function Get-SmtSetIdForCore($core, $smtSets) {
    if ($null -eq $smtSets -or $smtSets.Count -eq 0) { return $null }

    $coreIndex = [int]$core
    if ($script:PhysicalCoreIdByLogicalProcessor.ContainsKey($coreIndex)) {
        $setId = [int]$script:PhysicalCoreIdByLogicalProcessor[$coreIndex]
        foreach ($s in $smtSets) {
            if ($s.Id -eq $setId) { return $setId }
        }
    }

    foreach ($s in $smtSets) {
        if ($s.Cores -contains $coreIndex) { return [int]$s.Id }
    }

    return $null
}

function Get-PhysicalUnitIdForLogicalCore {
    param(
        [int]$Core,
        $SmtSets
    )

    if ($script:PhysicalCoreIdByLogicalProcessor.ContainsKey($Core)) {
        return [int]$script:PhysicalCoreIdByLogicalProcessor[$Core]
    }

    if ($null -ne $SmtSets) {
        foreach ($s in @($SmtSets)) {
            if (@($s.Cores) -contains $Core) { return [int]$s.Id }
        }
    }

    return $Core
}

function Test-AdjacentLogicalCorePair {
    param(
        [int[]]$Cores,
        $SmtSets,
        [bool]$HtEnabled = $false
    )

    if ($null -eq $Cores -or @($Cores).Count -ne 2) { return $false }
    $c0 = [int]$Cores[0]
    $c1 = [int]$Cores[1]
    if ($c0 -eq 0 -or $c1 -eq 0 -or $c0 -eq $c1) { return $false }

    $u0 = Get-PhysicalUnitIdForLogicalCore -Core $c0 -SmtSets $SmtSets
    $u1 = Get-PhysicalUnitIdForLogicalCore -Core $c1 -SmtSets $SmtSets
    if ($null -ne $u0 -and $null -ne $u1 -and [Math]::Abs([int]$u1 - [int]$u0) -eq 1) { return $true }

    $gap = [Math]::Abs($c1 - $c0)
    if ($gap -eq 1) { return $true }
    if ($HtEnabled -and $gap -eq 2) { return $true }

    return $false
}




function Get-WeakestCoreByCPPC($coreList) {
    if ($null -eq $coreList -or $coreList.Count -eq 0) { return $null }
    if ($script:cppcEnabled) {
        $weakest = Get-DeviceTweakerCppcExtremaCore -CoreList $coreList
        if ($null -ne $weakest) { return $weakest }
    }
    return (@(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $coreList)[0])
}

function Get-BestCoreByCPPC($coreList) {
    if ($null -eq $coreList -or $coreList.Count -eq 0) { return $null }
    if ($script:cppcEnabled) {
        $best = Get-DeviceTweakerCppcExtremaCore -CoreList $coreList -Best
        if ($null -ne $best) { return $best }
    }
    return (@(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $coreList)[0])
}

function Find-FreeSmtSetCore([ref]$usedCoresRef, [ref]$usedSmtRef, $smtSets) {
    $freeSets = $smtSets | Where-Object { -not $usedSmtRef.Value.ContainsKey($_.Id) }
    if (-not $freeSets -or $freeSets.Count -eq 0) { return $null }
    if ($script:cppcEnabled) {
        $candidates = @()
        foreach ($s in $freeSets) {
            foreach ($c in $s.Cores) {
                if (-not $usedCoresRef.Value.ContainsKey($c)) {
                    $rating = if ($script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { [int]::MaxValue }
                    $candidates += @{ Core = $c; SmtId = $s.Id; Rating = $rating }
                    break
                }
            }
        }
        if ($candidates.Count -gt 0) {
            $best = Get-DeviceTweakerFastBestByIntProperty $candidates 'Rating'
            return @{ Core = $best.Core; SmtId = $best.SmtId }
        }
    }
    $choice = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $freeSets 'Id')[0]
    foreach ($c in $choice.Cores) {
        if (-not $usedCoresRef.Value.ContainsKey($c)) {
            return @{ Core = $c; SmtId = $choice.Id }
        }
    }
    return $null
}

function Find-FreePCore([ref]$usedCoresRef, [ref]$usedSmtRef, $pCoreIndices, $smtSets) {
    $res = Find-FreeSmtSetCore -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtRef -smtSets $smtSets
    if ($res) { return $res }
    $free = $pCoreIndices | Where-Object { -not $usedCoresRef.Value.ContainsKey($_) }
    if ($free.Count -gt 0) {
        $core = Get-WeakestCoreByCPPC $free
        $smtId = Get-SmtSetIdForCore -core $core -smtSets $smtSets
        return @{ Core = $core; SmtId = $smtId }
    }
    return $null
}

function Find-FreeECore([ref]$usedCoresRef, $eCoreIndices) {
    if ($eCoreIndices.Count -eq 0) { return $null }
    $free = $eCoreIndices | Where-Object { -not $usedCoresRef.Value.ContainsKey($_) }
    if ($free.Count -gt 0) {
        if ($script:cppcEnabled) { return (Get-BestCoreByCPPC $free) }
        return [int](@(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $free)[0])
    }
    return $null
}

function Find-ShareableCore($preferredSharingPartners, [ref]$usedCoresRef, [ref]$usedSmtRef, $smtSets, [bool]$preferSmt, $assignedMap) {
    foreach ($kv in $assignedMap.GetEnumerator()) {
        $dev = $kv.Key
        $coresAssigned = $kv.Value
        $occupantRoles = Get-AutoOptRoles($dev)
        $ok = $false
        foreach ($r in $occupantRoles) { if ($preferredSharingPartners -contains $r) { $ok = $true; break } }
        if (-not $ok) { continue }

        foreach ($c in $coresAssigned) {
            $smtId = Get-SmtSetIdForCore -core $c -smtSets $smtSets
            if ($preferSmt -and $smtId -ne $null) {
                $set = Get-DeviceTweakerFastFirstWhere $smtSets { param($x) $x.Id -eq $smtId }
                if ($set) {
                    $sib = Get-DeviceTweakerFastFirstWhere $set.Cores { param($x) $x -ne $c }
                    if ($sib -ne $null -and -not $usedCoresRef.Value.ContainsKey([int]$sib)) {
                        return @{ Core = [int]$sib; SmtId = $smtId; ShareMode = 'SMT' }
                    }
                }
                return @{ Core = [int]$c; SmtId = $smtId; ShareMode = 'Core' }
            }
            return @{ Core = [int]$c; SmtId = $smtId; ShareMode = 'Core' }
        }
    }
    return $null
}

function Test-ShouldShowNdisAffinityModeDialog {
    param([System.Collections.IEnumerable]$Devices)

    if ($script:CLIMode) { return $false }
    if ($script:forceNetAdapterCx) { return $false }

    $networkDevices = @($Devices | Where-Object { Test-ExovanceNetworkWritable $_ })
    if ($networkDevices.Count -eq 0) { return $false }
    if ($script:forceNDIS) { return $true }

    return (@($networkDevices | Where-Object { $_.Role -eq 'NDIS' }).Count -gt 0)
}

function Show-NdisAffinityModeDialog {
    param(
        [string]$Title,
        [string]$Prompt,
        [string]$InitialMode = 'RSS',
        [System.Windows.Forms.IWin32Window]$Owner = $null
    )
    $dialog = [System.Windows.Forms.Form]::new()
    try {
        $dialog.Text = 'Exovance - ' + $Title
        $dialog.StartPosition = if ($Owner) { 'CenterParent' } else { 'CenterScreen' }
        $dialog.FormBorderStyle = 'FixedDialog'
        $dialog.MaximizeBox = $false
        $dialog.MinimizeBox = $false
        $dialog.BackColor = $script:colBlack
        $dialog.Font = $script:fontCache11
        $dialog.ClientSize = [System.Drawing.Size]::new(730, 310)
        $dialog.Add_HandleCreated({ try { [DarkMode]::EnableDarkModeForWindow($this.Handle) } catch {} })
        $label = [System.Windows.Forms.Label]::new()
        $label.Text = $Prompt
        $label.ForeColor = $script:colOrange
        $label.SetBounds(26, 24, 678, 56)
        $dialog.Controls.Add($label)
        $description = [System.Windows.Forms.Label]::new()
        $description.Text = "RSS: choose processors for receive processing.`nIRQ Policy: choose processors for hardware interrupts.`nBoth: apply both settings. Performance depends on the driver and workload."
        $description.ForeColor = $script:colLightGray
        $description.SetBounds(26, 86, 678, 95)
        $dialog.Controls.Add($description)
        $modes = @('RSS','IRQ','BOTH')
        $captions = @('RSS','IRQ Policy','Both')
        for ($index = 0; $index -lt $modes.Count; $index++) {
            $button = [System.Windows.Forms.Button]::new()
            $button.Text = $captions[$index]
            $button.Tag = $modes[$index]
            $button.SetBounds((26 + $index * 230), 195, 218, 48)
            $button.FlatStyle = 'Flat'
            $button.FlatAppearance.BorderColor = $script:colOrange
            $button.ForeColor = $script:colWhite
            $button.Add_Click({
                $form = $this.FindForm()
                $form.Tag = [string]$this.Tag
                $form.DialogResult = [System.Windows.Forms.DialogResult]::OK
                $form.Close()
            })
            $dialog.Controls.Add($button)
            if ($modes[$index] -eq $InitialMode) { $dialog.ActiveControl = $button }
        }
        $cancel = [System.Windows.Forms.Button]::new()
        $cancel.Text = 'Cancel'
        $cancel.ForeColor = $script:colWhite
        $cancel.SetBounds(554, 260, 150, 34)
        $cancel.DialogResult = [System.Windows.Forms.DialogResult]::Cancel
        $dialog.CancelButton = $cancel
        $dialog.Controls.Add($cancel)
        $dialog.Tag = $null
        $result = if ($Owner) { $dialog.ShowDialog($Owner) } else { $dialog.ShowDialog() }
        return (Resolve-ExovanceNdisMode -DialogResult ([string]$result) -SelectedMode ([string]$dialog.Tag))
    } finally { $dialog.Dispose() }
}

$btnAutoOpt.Add_Click({
    if (-not (Enter-DeviceTweakerUiAction -Name 'Auto-Optimization' -Button $this)) { return }
    try {
    try {
        $backupResult = Show-DarkMessageBox `
            -Message "Do you want to backup your current device settings before auto-optimization?" `
            -Title   "Auto-Optimization" `
            -Buttons YesNoCancel `
            -Icon    Question
        if ($backupResult -eq [System.Windows.Forms.DialogResult]::Cancel) { return }
        if ($backupResult -eq [System.Windows.Forms.DialogResult]::Yes) {
            try {
                $backupFile = Backup-DeviceSettings
                Show-DarkMessageBox -Message "Settings backed up to:`n$backupFile" -Title "Backup Complete" -Icon Information
            } catch {
                Set-ExovanceUiFeedback -State Error -Text 'Backup failed - automatic changes stopped'
                Show-DarkMessageBox -Message "Backup failed: $_`n`nNo automatic optimization was started." -Title "Backup Error" -Icon Error
                return
            }
        }

        # Keep the complete list for backup/restore; writes use verified physical adapters only.
        $deviceList = @(Get-ExovanceWritableDevices -Devices $deviceList)

        $applyNdisMsi = $false
        $ndisMsiResult = Show-DarkMessageBox `
            -Message "Do you want to configure MSI settings for your network adapter?" `
            -Title   "Auto-Optimization" `
            -Buttons YesNoCancel `
            -Icon    Question
        if ($ndisMsiResult -eq [System.Windows.Forms.DialogResult]::Cancel) { return }
        if ($ndisMsiResult -eq [System.Windows.Forms.DialogResult]::Yes) {
            $applyNdisMsi = $true
        }

        $script:autoNdisAffinityMode = if ($script:CLIMode -and $script:CLINdisAffinityMode) { $script:CLINdisAffinityMode } else { 'RSS' }
        if (Test-ShouldShowNdisAffinityModeDialog $deviceList) {
            $ownerForm = $this.FindForm()
            $script:autoNdisAffinityMode = Show-NdisAffinityModeDialog -Title 'Auto-Optimization - NDIS Affinity Mode' -Prompt 'How should affinity be set for the NDIS network adapter?' -InitialMode $script:autoNdisAffinityMode -Owner $ownerForm
            if ([string]::IsNullOrWhiteSpace($script:autoNdisAffinityMode)) {
                Set-ExovanceUiFeedback -State Ready -Text 'Cancelled - no automatic changes applied'
                return
            }
        } elseif ($script:CLIMode -and $script:CLINdisAffinityMode) {
            Write-Host "[CLI] Auto-Optimization NDIS affinity mode: $($script:autoNdisAffinityMode)" -ForegroundColor DarkGray
        }

        function AutoLog {
            param(
                [string]$Message,
                [string]$Color = 'DarkGray'
            )
            if ($verbose) {
                try { Write-Host $Message -ForegroundColor $Color } catch { }
            }
        }
        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkCyan
        Write-Host "    AUTO-OPTIMIZATION STARTED" -ForegroundColor Cyan
        Write-Host "  ================================================================" -ForegroundColor DarkCyan
        Write-Host ""

        $logicalCount = $script:cachedLogicalCount
        $cpu = $null
        $physicalCount = Get-PhysicalCoreCount
        $htEnabled = ($logicalCount -gt $physicalCount)
        if ($script:SwitchRealHyperThreadStatus) { $htEnabled = -not $htEnabled }
        $pCoreIndices = Get-PCoreIndices
        $pCoreIndicesAll = @($pCoreIndices)
        $eCoreIndices = @()
        for ($i = 0; $i -lt $logicalCount; $i++) {
            if (-not ($pCoreIndices -contains $i)) { $eCoreIndices += $i }
        }

        $targetCores = @(0..($logicalCount - 1))
        $ccdSelection = Resolve-CCDSelectionForDevices
        if ($script:IsDualCCDCpu) {
            $targetCores = @(Get-DeviceSelectionCoresForDualCCD -Context 'Auto')
            $pCoreIndices = $pCoreIndices | Where-Object { $targetCores -contains $_ }
            $eCoreIndices = $eCoreIndices | Where-Object { $targetCores -contains $_ }
        }

        if ($htEnabled) {
            $smtSets = Get-SmtSets -logicalCount $logicalCount -pCores $pCoreIndices
        } else {
            $smtSets = @()
        }
        $smtCount = if ($smtSets) { $smtSets.Count } else { 0 }

        Write-Host "  SYSTEM TOPOLOGY" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        $htStr = if ($htEnabled) { "Enabled" } else { "Disabled" }
        Write-Host ("  Hyperthreading       : {0} ({1} logical / {2} physical)" -f $htStr, $logicalCount, $physicalCount)
        Write-Host ("  P-Cores              : {0}" -f $(if ($pCoreIndices.Count -gt 0) { $pCoreIndices -join ', ' } else { "(none)" }))
        Write-Host ("  E-Cores              : {0}" -f $(if ($eCoreIndices.Count -gt 0) { $eCoreIndices -join ', ' } else { "(none)" }))
        $ccdStr = if ($script:IsDualCCDCpu) { "Dual-CCD" } elseif ($script:IsDualCCXCpu) { "Double-CCX (no CCD special handling)" } else { "Single-CCD" }
        Write-Host ("  CCD Topology         : {0}" -f $ccdStr)
        if ($script:IsDualCCDCpu) {
            Write-Host ("  CCD0 Cores           : {0}" -f ($script:Ccd0Cores -join ', '))
            Write-Host ("  CCD1 Cores           : {0}" -f ($script:Ccd1Cores -join ', '))
            Write-Host ("  Preferred CCD        : CCD{0}" -f [int]$ccdSelection.PreferredCCD)
            Write-Host ("  Device CCD (active)  : CCD{0} ({1})" -f [int]$ccdSelection.DeviceCCD, [string]$ccdSelection.Reason)
        }
        $cppcStr = if ($script:cppcEnabled) { "Enabled" } else { "Disabled" }
        Write-Host ("  CPPC                 : {0}" -f $cppcStr)
        if ($script:cppcEnabled) {
            $ratingStrs = @()
            foreach ($k in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $script:cppcRatings.Keys)) {
                $ratingStrs += "Core$k=$($script:cppcRatings[$k])"
            }
            Write-Host ("  CPPC Ratings         : {0}" -f ($ratingStrs -join '  '))
        }
        Write-Host ""

        Write-Host "  SMT SETS (used for auto-optimization)" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        if ($smtCount -gt 0) {
            foreach ($s in $smtSets) {
                $coreLabels = @()
                foreach ($c in $s.Cores) {
                    $tag = if (Is-PCore $c) { "P" } else { "E" }
                    $cppcTag = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { " r$($script:cppcRatings[[int]$c])" } else { "" }
                    $coreLabels += "$c($tag$cppcTag)"
                }
                Write-Host ("  Set #{0,-3} : cores {1}" -f $s.Id, ($coreLabels -join ', '))
            }
            if ($script:IsDualCCDCpu) {
                Write-Host ("  (Dual-CCD: only CCD{0} SMT sets are used for assignments)" -f [int]$ccdSelection.DeviceCCD) -ForegroundColor DarkYellow
            }
        } else {
            Write-Host "  (none - HT disabled or no P-core pairs found)"
        }
        Write-Host ""

        $usedCores = @{}
        $usedSmtSets = @{}
        $assignedMap = @{}
        $gpuPreReserved = @{}
        $occupiedCores = @()
        $weakOccupiedCores = @()
        $gpus = $deviceList | Where-Object { $_.Category -eq 'PCI' -and $_.Role -eq 'GPU' }
        $nics = $deviceList | Where-Object { $_.Category -eq 'Network' }
        $usbs = $deviceList | Where-Object { $_.Category -eq 'USB' }
        $usbs = @(ConvertTo-DeviceTweakerFastSortedUsbDevices $usbs)
        $ssds = $deviceList | Where-Object { Test-DeviceTweakerStorageDevice $_ }
        $audioPCI = $deviceList | Where-Object { $_.Category -eq 'PCI' -and $_.Role -eq 'Audio' }
        $usbSingleAudio = $usbs | Where-Object {
            $norm = Get-AutoOptRoles $_
            ($norm.Count -eq 1) -and ($norm -contains 'Audio')
        }
        $hasAudioDevices = ($audioPCI.Count -gt 0) -or ($usbSingleAudio.Count -gt 0)






        if ($script:IsDualCCDCpu -and $hasAudioDevices) {
        }

        function Find-FreePCoreLocal([ref]$usedCoresRef, [ref]$usedSmtRef, $pCoreIndicesParam, $smtSetsParam, [bool]$preferBestCPPC = $false) {
            if ($script:cppcEnabled -and $smtSetsParam) {
                $candidates = @()
                foreach ($s in $smtSetsParam) {
                    if (-not $usedSmtRef.Value.ContainsKey($s.Id)) {
                        foreach ($c in $s.Cores) {
                            if (-not $usedCoresRef.Value.ContainsKey($c)) {
                                $rating = if ($script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { [int]::MaxValue }
                                $candidates += @{ Core = $c; SmtId = $s.Id; Rating = $rating }
                                break
                            }
                        }
                    }
                }
                if ($candidates.Count -gt 0) {
                    if ($preferBestCPPC) {
                        $best = Get-DeviceTweakerFastBestByIntProperty $candidates 'Rating' -Descending
                    } else {
                        $best = Get-DeviceTweakerFastBestByIntProperty $candidates 'Rating'
                    }
                    return @{ Core = $best.Core; SmtId = $best.SmtId }
                }
            } elseif ($smtSetsParam) {
                foreach ($s in $smtSetsParam) {
                    if (-not $usedSmtRef.Value.ContainsKey($s.Id)) {
                        foreach ($c in $s.Cores) {
                            if (-not $usedCoresRef.Value.ContainsKey($c)) {
                                return @{ Core = $c; SmtId = $s.Id }
                            }
                        }
                    }
                }
            }
            $freeAll = $pCoreIndicesParam | Where-Object { -not $usedCoresRef.Value.ContainsKey($_) }
            if ($freeAll.Count -gt 0) {
                $core = if ($preferBestCPPC) { Get-BestCoreByCPPC $freeAll } else { Get-WeakestCoreByCPPC $freeAll }
                $smtId = Get-SmtSetIdForCore -core $core -smtSets $smtSetsParam
                return @{ Core = $core; SmtId = $smtId }
            }
            return $null
        }

        function Find-GPUCores($pCoreIndicesParam, $smtSetsParam, $htEnabledParam, [ref]$usedCoresRef, [ref]$usedSmtSetsRef) {


            $units = [System.Collections.ArrayList]::new()
            if ($htEnabledParam -and $smtSetsParam -and @($smtSetsParam).Count -ge 2) {
                foreach ($s in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $smtSetsParam 'Id')) {
                    $rating = 0
                    foreach ($c in @($s.Cores)) {
                        $r = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { [int]$script:cppcRatings[[int]$c] } else { [int]$c }
                        if ($r -gt $rating) { $rating = $r }
                    }
                    [void]$units.Add(@{
                        Id          = [int]$s.Id
                        Cores       = @($s.Cores | ForEach-Object { [int]$_ })
                        PrimaryCore = [int]$s.Cores[0]
                        Rating      = [int]$rating
                    })
                }
            } else {
                foreach ($c in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $pCoreIndicesParam)) {
                    $rating = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { [int]$script:cppcRatings[[int]$c] } else { [int]$c }
                    [void]$units.Add(@{
                        Id          = [int]$c
                        Cores       = @([int]$c)
                        PrimaryCore = [int]$c
                        Rating      = [int]$rating
                    })
                }
            }

            $eligible = [System.Collections.ArrayList]::new()
            foreach ($u in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $units 'Id')) {
                if (@($u.Cores | Where-Object { [int]$_ -eq 0 }).Count -gt 0) { continue }
                if ($usedSmtSetsRef.Value.ContainsKey([int]$u.Id)) { continue }

                $blocked = $false
                foreach ($c in @($u.Cores)) {
                    if ($usedCoresRef.Value.ContainsKey([int]$c)) { $blocked = $true; break }
                }
                if (-not $blocked) { [void]$eligible.Add($u) }
            }

            $eligible = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $eligible 'Id')
            $pairs = [System.Collections.ArrayList]::new()
            for ($i = 0; $i -lt ($eligible.Count - 1); $i++) {
                $u1 = $eligible[$i]
                $u2 = $eligible[$i + 1]
                if (([int]$u2.Id - [int]$u1.Id) -ne 1) { continue }

                $sum = [int]$u1.Rating + [int]$u2.Rating
                [void]$pairs.Add(@{ Unit1 = $u1; Unit2 = $u2; CombinedRating = [int]$sum })
            }

            if ($pairs.Count -eq 0) { return $null }

            if ($script:cppcEnabled) {
                $rankedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $pairs -Cppc)
            } else {
                $rankedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $pairs)
            }

            $selected = $rankedPairs[0]
            return @{
                Cores  = @([int]$selected.Unit1.PrimaryCore, [int]$selected.Unit2.PrimaryCore)
                SmtIds = @([int]$selected.Unit1.Id, [int]$selected.Unit2.Id)
            }
        }

        function Assign-GPUDevice($gpu, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $smtSetsParam, $htEnabledParam, [ref]$assignedMapRef, [ref]$occupiedCoresRef) {
            AutoLog "[AutoOpt][GPU] Picking for GPU: $($gpu.DisplayName)" 'DarkGray'
            $gpuResult = $null
            if ($gpuPreReserved.ContainsKey($gpu)) {
                $gpuResult = $gpuPreReserved[$gpu]
            } else {
                $gpuResult = Find-GPUCores -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -htEnabledParam $htEnabledParam -usedCoresRef $usedCoresRef -usedSmtSetsRef $usedSmtSetsRef
            }
            if ($gpuResult) {
                $assigned = $gpuResult.Cores
                if (-not $gpuPreReserved.ContainsKey($gpu)) {
                    foreach ($i in 0..($assigned.Count - 1)) {
                        $c = $assigned[$i]
                        $sid = if ($gpuResult.SmtIds.Count -gt $i) { $gpuResult.SmtIds[$i] } else { Get-SmtSetIdForCore -core $c -smtSets $smtSetsParam }
                        Reserve-Core $c $usedCoresRef $usedSmtSetsRef $sid
                    }
                }
                $assignedMapRef.Value[$gpu] = $assigned
                $maskInt = [uint64]0
                foreach ($c in $assigned) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                $hexMask = "{0:X16}" -f ([uint64]$maskInt)
                $formattedGpuPath = Format-RegistryPathForDisplay $gpu.RegistryPath
                AutoLog "[AutoOpt][GPU] Setting GPU affinity: $formattedGpuPath -> cores [$($assigned -join ', ')] mask 0x$hexMask" 'DarkGray'
                $res = Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask)
                AutoLog "[AutoOpt][GPU] Set-DeviceAffinity returned: $res" 'DarkGray'
                $occupiedCoresRef.Value += $assigned
            } else {
                $assigned = @()
                $tries = 0
                $gpuFallbackPCores = @($pCoreIndicesParam | Where-Object { [int]$_ -ne 0 })
                while ($assigned.Count -lt 2 -and $tries -lt 200) {
                    $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $gpuFallbackPCores -smtSetsParam $smtSetsParam -preferBestCPPC ([bool]$script:cppcEnabled)
                    if ($f -ne $null) {
                        if (-not ($assigned -contains $f.Core)) {
                            $assigned += $f.Core
                            Reserve-Core $f.Core $usedCoresRef $usedSmtSetsRef $f.SmtId
                        }
                    } else { break }
                    $tries++
                }
                if ($assigned.Count -eq 0) {
                    Write-Host "[AutoOpt][GPU] WARNING - couldn't assign GPU cores" -ForegroundColor Yellow
                    $assignedMapRef.Value[$gpu] = @()
                } else {
                    $assignedMapRef.Value[$gpu] = $assigned
                    $maskInt = [uint64]0
                    foreach ($c in $assigned) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                    $hexMask = "{0:X16}" -f ([uint64]$maskInt)
                    $formattedGpuPath = Format-RegistryPathForDisplay $gpu.RegistryPath
                    AutoLog "[AutoOpt][GPU] Setting GPU affinity (fallback): $formattedGpuPath -> cores [$($assigned -join ', ')] mask 0x$hexMask" 'DarkGray'
                    $res = Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask)
                    AutoLog "[AutoOpt][GPU] Set-DeviceAffinity returned: $res" 'DarkGray'
                    $occupiedCoresRef.Value += $assigned
                }
            }
        }

        function Assign-NICDevice($nic, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            AutoLog "[AutoOpt][NIC] Assigning NIC: $($nic.DisplayName)" 'DarkGray'
            $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
            $shared = $false
            if ($f -eq $null) {
                $preferred = @('Audio','Mouse','Controller')
                $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                if ($share) {
                    $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true }
                    $shared = $true
                    AutoLog "[AutoOpt][NIC] No free P-core; allowing sharing on core $($f.Core) (mode $($share.ShareMode))" 'DarkGray'
                }
            }
            if ($f -ne $null) {
                $core = $f.Core
                $smtid = $f.SmtId
                if ($f.Shared) {
                    $usedCoresRef.Value[[int]$core] = $true
                } else {
                    Reserve-Core $core $usedCoresRef $usedSmtSetsRef $smtid
                }
                $assignedMapRef.Value[$nic] = @($core)
                if ($nic.Role -eq 'NDIS') {
                    try {
                        $ndisMode = $script:autoNdisAffinityMode
                        $valueToSet = "$core"
                        $formattedNicPath = Format-RegistryPathForDisplay $nic.RegistryPath
                        AutoLog "[AutoOpt][NIC] NDIS affinity mode: $ndisMode  (adapter: $formattedNicPath)" 'DarkGray'
                        if ($ndisMode -eq 'RSS' -or $ndisMode -eq 'BOTH') {
                            $null = Set-ExovanceRssConfiguration -RegistryPath $nic.RegistryPath -BaseProcessor $core -QueueCount 1
                        }
                        if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                            $irqTargetPath = if ($nic.ConfigPath) { $nic.ConfigPath } else { $nic.RegistryPath }
                            $formattedIrqPath = Format-RegistryPathForDisplay $irqTargetPath
                            $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                            Set-DeviceAffinity $irqTargetPath ("0x" + $mask) | Out-Null
                            AutoLog "[AutoOpt][NIC] NDIS IRQ Policy: Set AssignmentSetOverride=0x$mask + DevicePolicy=4 at $formattedIrqPath -> core $core" 'DarkGray'
                        }
                    } catch {
                        Write-Host "[AutoOpt][NIC] Failed to write NDIS settings to $($nic.RegistryPath): $_" -ForegroundColor Yellow
                    }
                } else {
                    $targetRegistryPath = Get-NetworkAdapterAffinityRegistryPath $nic
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    $formattedTargetPath = Format-RegistryPathForDisplay $targetRegistryPath
                    AutoLog "[AutoOpt][NIC] Setting affinity via Set-DeviceAffinity at $formattedTargetPath -> core $core mask 0x$mask" 'DarkGray'
                    $res = Set-DeviceAffinity $targetRegistryPath ("0x" + $mask)
                    AutoLog "[AutoOpt][NIC] Set-DeviceAffinity returned: $res" 'DarkGray'
                }
                $weakOccupiedCoresRef.Value += @($core)
            } else {
                Write-Host "[AutoOpt][NIC] WARNING - could not allocate NIC a P-core" -ForegroundColor Yellow
                $assignedMapRef.Value[$nic] = @()
            }
        }

        function Assign-USBDevice($usb, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $eCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$occupiedCoresRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            $roles = Get-AutoOptRoles $usb
            $isControllerRole = ($roles -contains 'Controller')
            $hasMouse = ($roles -contains 'Mouse')
            $singleAudio = ($roles.Count -eq 1 -and $roles -contains 'Audio')
            $singleKeyboard = ($roles.Count -eq 1 -and $roles -contains 'Keyboard')
            $hasOnlyAudioRole = ($roles.Count -eq 1 -and $roles -contains 'Audio')
            $hasAudio = ($roles -contains 'Audio')
            $isMixedAudioRole = ($hasAudio -and $roles.Count -gt 1)
            AutoLog "[AutoOpt][USB] $($usb.DisplayName)" 'DarkGray'
            if ($singleAudio -or $hasOnlyAudioRole) {
                $audioPreferBest = $preferBest
                $ecore = Find-FreeECore -usedCoresRef $usedCoresRef -eCoreIndices $eCoreIndicesParam
                if ($ecore -ne $null) {
                    Reserve-Core $ecore $usedCoresRef $usedSmtSetsRef $null
                    $assignedMapRef.Value[$usb] = @($ecore)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $ecore))
                    AutoLog "[AutoOpt][USB] Single-audio USB assigned E-core $ecore mask 0x$mask" 'DarkGray'
                    $res = Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask)
                    AutoLog "[AutoOpt][USB] Set-DeviceAffinity returned: $res" 'DarkGray'
                    $weakOccupiedCoresRef.Value += @($ecore)
                    return
                } else {
                    if (-not $script:IsDualCCDCpu) {
                        $smtId0 = Get-SmtSetIdForCore -core 0 -smtSets $smtSetsParam
                        Reserve-Core 0 $usedCoresRef $usedSmtSetsRef $smtId0
                        $assignedMapRef.Value[$usb] = @(0)
                        $mask = "{0:X16}" -f ([uint64](1 -shl 0))
                        AutoLog "[AutoOpt][USB] No E-core; force-assigned core 0 (reserved for audio) mask 0x$mask" 'DarkGray'
                        $res = Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask)
                        AutoLog "[AutoOpt][USB] Set-DeviceAffinity returned: $res" 'DarkGray'
                        $weakOccupiedCoresRef.Value += @([int]0)
                        return
                    }
                    AutoLog "[AutoOpt][USB] No E-core and dual-CCD; falling back to P-core with best remaining CPPC" 'DarkGray'
                }
                $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $audioPreferBest
                if ($f -eq $null) {
                    $preferred = @('Audio','Mouse')
                    $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                    if ($share) {
                        $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true }
                        AutoLog "[AutoOpt][USB] No free P-core; allowing sharing on core $($f.Core) (mode $($share.ShareMode))" 'DarkGray'
                    }
                }
                if ($f -ne $null) {
                    $core = $f.Core
                    $smtid = $f.SmtId
                    if ($f.Shared) {
                        $usedCoresRef.Value[[int]$core] = $true
                    } else {
                        Reserve-Core $core $usedCoresRef $usedSmtSetsRef $smtid
                    }
                    $assignedMapRef.Value[$usb] = @($core)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    $formattedUsbPath = Format-RegistryPathForDisplay $usb.RegistryPath
                    AutoLog "[AutoOpt][USB] Single-audio USB P-core fallback: $formattedUsbPath -> core $core mask 0x$mask" 'DarkGray'
                    $res = Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask)
                    AutoLog "[AutoOpt][USB] Set-DeviceAffinity returned: $res" 'DarkGray'
                    $weakOccupiedCoresRef.Value += @($core)
                } else {
                    Write-Host "[AutoOpt][USB] WARNING - could not allocate core for single-audio USB $($usb.DisplayName)" -ForegroundColor Yellow
                    $assignedMapRef.Value[$usb] = @()
                }
                return
            }
            $filteredPCoreIndices = $pCoreIndicesParam
            if ($isMixedAudioRole -and -not $script:IsDualCCDCpu) {
                $filteredPCoreIndices = @($pCoreIndicesParam | Where-Object { $_ -ne 0 })
                AutoLog "[AutoOpt][USB] Mixed audio role: excluding core 0 and e-cores from candidates" 'DarkGray'
            }
            $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $filteredPCoreIndices -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
            if ($f -eq $null) {
                if (-not $hasMouse -and -not $isControllerRole) {
                    $preferred = @('Audio','Mouse')
                    $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                    if ($share) {
                        $rejectShare = $false
                        if ($isMixedAudioRole -and -not $script:IsDualCCDCpu) {
                            if ($share.Core -eq 0 -or -not (Is-PCore $share.Core)) { $rejectShare = $true }
                        }
                        if (-not $rejectShare) {
                            $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true }
                            AutoLog "[AutoOpt][USB] No free P-core; allowing sharing on core $($f.Core) (mode $($share.ShareMode))" 'DarkGray'
                        }
                    }
                }
            }
            if ($f -ne $null) {
                $core = $f.Core
                $smtid = $f.SmtId
                if ($f.Shared) {
                    $usedCoresRef.Value[[int]$core] = $true
                } else {
                    Reserve-Core $core $usedCoresRef $usedSmtSetsRef $smtid
                }
                $assignedMapRef.Value[$usb] = @($core)
                $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                $formattedUsbPath = Format-RegistryPathForDisplay $usb.RegistryPath
                AutoLog "[AutoOpt][USB] Setting USB affinity: $formattedUsbPath -> core $core mask 0x$mask" 'DarkGray'
                $res = Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask)
                AutoLog "[AutoOpt][USB] Set-DeviceAffinity returned: $res" 'DarkGray'
                if ($isControllerRole) { $occupiedCoresRef.Value += @($core) }
                if ($hasMouse) { $occupiedCoresRef.Value += @($core) }
                if ($singleKeyboard) { $weakOccupiedCoresRef.Value += @($core) }
            } else {
                Write-Host "[AutoOpt][USB] WARNING - could not allocate P-core for USB $($usb.DisplayName)" -ForegroundColor Yellow
                $assignedMapRef.Value[$usb] = @()
            }
        }

        function Assign-AudioPCIDevice($aud, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $eCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            AutoLog "[AutoOpt][AudioPCI] Assigning: $($aud.DisplayName)" 'DarkGray'
            $ecore = Find-FreeECore -usedCoresRef $usedCoresRef -eCoreIndices $eCoreIndicesParam
            if ($ecore -ne $null) {
                Reserve-Core $ecore $usedCoresRef $usedSmtSetsRef $null
                $assignedMapRef.Value[$aud] = @($ecore)
                $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $ecore))
                AutoLog "[AutoOpt][AudioPCI] Assigned E-core $ecore mask 0x$mask" 'DarkGray'
                $res = Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask)
                AutoLog "[AutoOpt][AudioPCI] Set-DeviceAffinity returned: $res" 'DarkGray'
                $weakOccupiedCoresRef.Value += @($ecore)
            } else {
                if (-not $script:IsDualCCDCpu) {
                    $smtId0 = Get-SmtSetIdForCore -core 0 -smtSets $smtSetsParam
                    Reserve-Core 0 $usedCoresRef $usedSmtSetsRef $smtId0
                    $assignedMapRef.Value[$aud] = @(0)
                    $mask = "{0:X16}" -f ([uint64](1 -shl 0))
                    AutoLog "[AutoOpt][AudioPCI] No E-core; force-assigned core 0 (reserved for audio) mask 0x$mask" 'DarkGray'
                    $res = Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask)
                    AutoLog "[AutoOpt][AudioPCI] Set-DeviceAffinity returned: $res" 'DarkGray'
                    $weakOccupiedCoresRef.Value += @([int]0)
                    return
                }
                $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
                if ($f -ne $null) {
                    $core = $f.Core
                    Reserve-Core $core $usedCoresRef $usedSmtSetsRef $f.SmtId
                    $assignedMapRef.Value[$aud] = @($core)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    AutoLog "[AutoOpt][AudioPCI] No E-core; assigned P-core $core mask 0x$mask" 'DarkGray'
                    $res = Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask)
                    AutoLog "[AutoOpt][AudioPCI] Set-DeviceAffinity returned: $res" 'DarkGray'
                    $weakOccupiedCoresRef.Value += @($core)
                } else {
                    Write-Host "[AutoOpt][AudioPCI] WARNING - could not assign Audio PCI" -ForegroundColor Yellow
                    $assignedMapRef.Value[$aud] = @()
                }
            }
        }

        if ($script:IsDualCCDCpu) {
            foreach ($gpu in $gpus) {
                $pre = Find-GPUCores -pCoreIndicesParam $pCoreIndices -smtSetsParam $smtSets -htEnabledParam $htEnabled -usedCoresRef ([ref]$usedCores) -usedSmtSetsRef ([ref]$usedSmtSets)
                if ($pre) {
                    $gpuPreReserved[$gpu] = $pre
                    for ($i = 0; $i -lt $pre.Cores.Count; $i++) {
                        $c = [int]$pre.Cores[$i]
                        $sid = if ($pre.SmtIds.Count -gt $i) { $pre.SmtIds[$i] } else { Get-SmtSetIdForCore -core $c -smtSets $smtSets }
                        Reserve-Core $c ([ref]$usedCores) ([ref]$usedSmtSets) $sid
                    }
                }
            }
        }

        if ($script:IsDualCCDCpu) {

            $dualControllerUsb = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 1 })
            $dualMouseUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 2 })
            $dualKeyboardUsb   = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 3 })
            $dualAudioUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 5 })
            $dualOtherUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 6 })
            $dualAudioDevices  = [System.Collections.ArrayList]::new()
            foreach ($usb in $dualAudioUsb) { [void]$dualAudioDevices.Add($usb) }
            foreach ($aud in $audioPCI) { [void]$dualAudioDevices.Add($aud) }

            foreach ($gpu in $gpus) {
                Assign-GPUDevice $gpu ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $smtSets $htEnabled ([ref]$assignedMap) ([ref]$occupiedCores)
            }
            foreach ($usb in $dualControllerUsb) {
                Assign-USBDevice $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($usb in $dualMouseUsb) {
                Assign-USBDevice $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($usb in $dualKeyboardUsb) {
                Assign-USBDevice $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($nic in $nics) {
                Assign-NICDevice $nic ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $smtSets ([ref]$assignedMap) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($dev in $dualAudioDevices) {
                if ($dev.Category -eq 'USB') {
                    Assign-USBDevice $dev ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
                } else {
                    Assign-AudioPCIDevice $dev ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$weakOccupiedCores) -preferBest $true
                }
            }
            foreach ($usb in $dualOtherUsb) {
                Assign-USBDevice $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }

        } else {

            $physUnits = [System.Collections.ArrayList]::new()
            if ($htEnabled -and $smtSets.Count -gt 0) {
                foreach ($s in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $smtSets 'Id')) {
                    $rating = 0
                    if ($script:cppcEnabled) {
                        foreach ($c in $s.Cores) {
                            $r = if ($script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { 0 }
                            if ($r -gt $rating) { $rating = $r }
                        }
                    }
                    [void]$physUnits.Add(@{
                        Id          = $s.Id
                        Cores       = @($s.Cores)
                        Rating      = $rating
                        PrimaryCore = [int]$s.Cores[0]
                        SiblingCore = if ($s.Cores.Count -gt 1) { [int]$s.Cores[1] } else { $null }
                    })
                }
            } else {
                foreach ($c in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $pCoreIndices)) {
                    $rating = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { 0 }
                    [void]$physUnits.Add(@{
                        Id          = [int]$c
                        Cores       = @([int]$c)
                        Rating      = $rating
                        PrimaryCore = [int]$c
                        SiblingCore = $null
                    })
                }
            }
            $totalPhysUnits = $physUnits.Count

            AutoLog "[Plan] Phase 1: $totalPhysUnits physical units built (HT=$htEnabled)" 'DarkGray'

            $deviceSlots = [System.Collections.ArrayList]::new()

            foreach ($aud in $audioPCI) {
                [void]$deviceSlots.Add(@{
                    Device   = $aud
                    Role     = 'Audio'
                    Priority = 0
                    CanShare = $true
                    MustIsolate = $false
                    IsECoreEligible = $true
                })
            }

            foreach ($usba in $usbSingleAudio) {
                [void]$deviceSlots.Add(@{
                    Device   = $usba
                    Role     = 'Audio'
                    Priority = 0
                    CanShare = $true
                    MustIsolate = $false
                    IsECoreEligible = $true
                })
            }

            foreach ($nic in $nics) {
                [void]$deviceSlots.Add(@{
                    Device   = $nic
                    Role     = 'NIC'
                    Priority = 1
                    CanShare = $true
                    MustIsolate = $false
                    IsECoreEligible = $false
                })
            }

            $usbNonAudio = $usbs | Where-Object {
                $norm = Get-AutoOptRoles $_
                -not (($norm.Count -eq 1) -and ($norm -contains 'Audio'))
            }
            foreach ($usb in $usbNonAudio) {
                $roles = Get-AutoOptRoles $usb
                $hasMouse = ($roles -contains 'Mouse')
                $hasController = ($roles -contains 'Controller')
                $hasKeyboard = ($roles -contains 'Keyboard')

                if ($hasController) {
                    [void]$deviceSlots.Add(@{
                        Device   = $usb
                        Role     = 'Controller'
                        Priority = 4
                        CanShare = $false
                        MustIsolate = $true
                        IsECoreEligible = $false
                    })
                } elseif ($hasMouse) {
                    [void]$deviceSlots.Add(@{
                        Device   = $usb
                        Role     = 'Mouse'
                        Priority = 3
                        CanShare = $false
                        MustIsolate = $true
                        IsECoreEligible = $false
                    })
                } elseif ($hasKeyboard) {
                    [void]$deviceSlots.Add(@{
                        Device   = $usb
                        Role     = 'Keyboard'
                        Priority = 2
                        CanShare = $true
                        MustIsolate = $false
                        IsECoreEligible = $false
                    })
                } else {
                    [void]$deviceSlots.Add(@{
                        Device   = $usb
                        Role     = 'Other'
                        Priority = 1
                        CanShare = $true
                        MustIsolate = $false
                        IsECoreEligible = $false
                    })
                }
            }

            $gpuSlots   = @($gpus)
            $mouseSlots = @($deviceSlots | Where-Object { $_.Role -eq 'Mouse' })
            $ctrlSlots  = @($deviceSlots | Where-Object { $_.Role -eq 'Controller' })
            $kbSlots    = @($deviceSlots | Where-Object { $_.Role -eq 'Keyboard' })
            $nicSlots   = @($deviceSlots | Where-Object { $_.Role -eq 'NIC' })
            $audioSlots = @($deviceSlots | Where-Object { $_.Role -eq 'Audio' })
            $otherSlots = @($deviceSlots | Where-Object { $_.Role -eq 'Other' })

            $hasControllerDevice = ($ctrlSlots.Count -gt 0)
            $hasMouseDevice      = ($mouseSlots.Count -gt 0)

            $plan = @{}

            function Get-AutoOptECorePriorityForSlot($slot) {
                switch ([string]$slot.Role) {
                    'Controller' { return 0 }
                    'Mouse'      { return 1 }
                    'Keyboard'   { return 2 }
                    'NIC'        { return 3 }
                    'Audio'      { return 4 }
                    default      { return 5 }
                }
            }

            $availableECoresForPlan = @($eCoreIndices)
            $availableECoresForPlan = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $availableECoresForPlan)
            if ($availableECoresForPlan.Count -gt 0) {
                $ecoreCandidateSlots = [System.Collections.ArrayList]::new()
                foreach ($s in $ctrlSlots)  { [void]$ecoreCandidateSlots.Add($s) }
                foreach ($s in $mouseSlots) { [void]$ecoreCandidateSlots.Add($s) }
                foreach ($s in $kbSlots)    { [void]$ecoreCandidateSlots.Add($s) }
                foreach ($s in $nicSlots)   { [void]$ecoreCandidateSlots.Add($s) }
                foreach ($s in $audioSlots) { [void]$ecoreCandidateSlots.Add($s) }
                foreach ($s in $otherSlots) { [void]$ecoreCandidateSlots.Add($s) }

                $orderedECoreSlots = @(ConvertTo-DeviceTweakerFastSortedECoreSlots $ecoreCandidateSlots)
                foreach ($slot in $orderedECoreSlots) {
                    if ($availableECoresForPlan.Count -le 0) { break }
                    $ecore = if ($script:cppcEnabled) { Get-BestCoreByCPPC $availableECoresForPlan } else { [int]$availableECoresForPlan[0] }
                    if ($null -eq $ecore) { break }
                    $plan[$slot.Device] = @([int]$ecore)
                    $availableECoresForPlan = @($availableECoresForPlan | Where-Object { [int]$_ -ne [int]$ecore })
                    AutoLog "[Plan][ECore] $($slot.Role) '$($slot.Device.DisplayName)' -> E-core $ecore" 'DarkGray'
                }
            }

            $mouseSlots = @($mouseSlots | Where-Object { -not $plan.ContainsKey($_.Device) })
            $ctrlSlots  = @($ctrlSlots  | Where-Object { -not $plan.ContainsKey($_.Device) })
            $kbSlots    = @($kbSlots    | Where-Object { -not $plan.ContainsKey($_.Device) })
            $nicSlots   = @($nicSlots   | Where-Object { -not $plan.ContainsKey($_.Device) })
            $audioSlots = @($audioSlots | Where-Object { -not $plan.ContainsKey($_.Device) })
            $otherSlots = @($otherSlots | Where-Object { -not $plan.ContainsKey($_.Device) })

            $core0RolePriorityConsumedUnitId = $null
            if ((-not $script:cppcEnabled) -and ($eCoreIndices.Count -eq 0) -and (-not $script:IsDualCCDCpu)) {
                $core0PrioritySlots = [System.Collections.ArrayList]::new()
                foreach ($s in $ctrlSlots)  { [void]$core0PrioritySlots.Add($s) }
                foreach ($s in $mouseSlots) { [void]$core0PrioritySlots.Add($s) }
                foreach ($s in $kbSlots)    { [void]$core0PrioritySlots.Add($s) }
                foreach ($s in $nicSlots)   { [void]$core0PrioritySlots.Add($s) }
                foreach ($s in $audioSlots) { [void]$core0PrioritySlots.Add($s) }
                foreach ($s in $otherSlots) { [void]$core0PrioritySlots.Add($s) }
                foreach ($slot in $core0PrioritySlots) {
                    if ($null -eq $slot -or $null -eq $slot.Device) { continue }
                    $plan[$slot.Device] = @(0)
                    $core0RolePriorityConsumedUnitId = Get-PhysicalUnitIdForLogicalCore -Core 0 -SmtSets $smtSets
                    AutoLog "[Plan][Core0] $($slot.Role) '$($slot.Device.DisplayName)' -> core 0 (non-CPPC/non-E-core/single-CCD role priority)" 'DarkGray'
                    break
                }
                $mouseSlots = @($mouseSlots | Where-Object { -not $plan.ContainsKey($_.Device) })
                $ctrlSlots  = @($ctrlSlots  | Where-Object { -not $plan.ContainsKey($_.Device) })
                $kbSlots    = @($kbSlots    | Where-Object { -not $plan.ContainsKey($_.Device) })
                $nicSlots   = @($nicSlots   | Where-Object { -not $plan.ContainsKey($_.Device) })
                $audioSlots = @($audioSlots | Where-Object { -not $plan.ContainsKey($_.Device) })
                $otherSlots = @($otherSlots | Where-Object { -not $plan.ContainsKey($_.Device) })
            }

            $isolatedCount = $mouseSlots.Count + $ctrlSlots.Count
            $shareableCount = $audioSlots.Count + $nicSlots.Count + $kbSlots.Count

            $nonGpuDeviceCount = $isolatedCount + $shareableCount
            $gpuUnitsNeeded    = if ($gpuSlots.Count -gt 0) { 2 } else { 0 }

            AutoLog "[Plan] Phase 2: GPU=$($gpuSlots.Count) Mouse=$($mouseSlots.Count) Ctrl=$($ctrlSlots.Count) KB=$($kbSlots.Count) NIC=$($nicSlots.Count) Audio=$($audioSlots.Count) ECorePre=$($plan.Count)" 'DarkGray'

            $unitsAfterGPU     = $totalPhysUnits - $gpuUnitsNeeded
            $unitsForIsolated  = [math]::Min($isolatedCount, $unitsAfterGPU)
            $unitsForShareable = [math]::Max(0, $unitsAfterGPU - $unitsForIsolated)
            $needsSharing      = ($shareableCount -gt $unitsForShareable)
            $hasSurplus        = ($nonGpuDeviceCount -lt $unitsAfterGPU)
            $surplusCount      = if ($hasSurplus) { $unitsAfterGPU - $nonGpuDeviceCount } else { 0 }

            $excludeCore0ForGPU = $true

            AutoLog "[Plan] Phase 3: unitsAfterGPU=$unitsAfterGPU iso=$isolatedCount share=$shareableCount forShare=$unitsForShareable needsSharing=$needsSharing surplus=$hasSurplus($surplusCount) excl0=$excludeCore0ForGPU" 'DarkGray'

            $sortedUnits = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $physUnits 'Id')
            $adjacentPairs = [System.Collections.ArrayList]::new()
            for ($i = 0; $i -lt $sortedUnits.Count - 1; $i++) {
                $u1 = $sortedUnits[$i]
                $u2 = $sortedUnits[$i + 1]
                if (([int]$u2.Id - [int]$u1.Id) -ne 1) { continue }
                $skipPair = $false
                if ($excludeCore0ForGPU) {
                    foreach ($c in $u1.Cores) { if ([int]$c -eq 0) { $skipPair = $true; break } }
                    if (-not $skipPair) { foreach ($c in $u2.Cores) { if ([int]$c -eq 0) { $skipPair = $true; break } } }
                }
                if ($skipPair) { continue }
                $combinedRating = [int]$u1.Rating + [int]$u2.Rating
                [void]$adjacentPairs.Add(@{ Unit1 = $u1; Unit2 = $u2; CombinedRating = $combinedRating })
            }

            $gpuPlan = $null
            if ($gpuSlots.Count -gt 0 -and $adjacentPairs.Count -gt 0) {
                if ($hasSurplus -and $script:cppcEnabled) {
                    $unitsByRatingDesc = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $physUnits 'Rating' -Descending)
                    $freeUnitIds = @{}
                    $reserved = 0
                    foreach ($u in $unitsByRatingDesc) {
                        if ($reserved -ge $surplusCount) { break }
                        $freeUnitIds[[int]$u.Id] = $true
                        $reserved++
                    }
                    $eligiblePairs = @($adjacentPairs | Where-Object {
                        (-not $freeUnitIds.ContainsKey([int]$_.Unit1.Id)) -and
                        (-not $freeUnitIds.ContainsKey([int]$_.Unit2.Id))
                    })
                    if ($eligiblePairs.Count -gt 0) {
                        $gpuPlan = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $eligiblePairs -Cppc)[0]
                    } else {
                        $gpuPlan = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $adjacentPairs -Cppc)[0]
                    }
                } elseif ($script:cppcEnabled) {
                    $gpuPlan = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $adjacentPairs -Cppc)[0]
                } else {
                    $gpuPlan = @(ConvertTo-DeviceTweakerFastSortedGpuPairs (Get-DeviceTweakerFastFirstEligibleGpuPairList $adjacentPairs) )[0]
                    if (-not $gpuPlan) { $gpuPlan = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $adjacentPairs)[0] }
                }
            }

            $gpuCoreAssignment = @()
            $gpuConsumedUnitIds = @{}
            if ($gpuPlan) {
                $gpuCoreAssignment = @($gpuPlan.Unit1.PrimaryCore, $gpuPlan.Unit2.PrimaryCore)
                $gpuConsumedUnitIds[[int]$gpuPlan.Unit1.Id] = $true
                $gpuConsumedUnitIds[[int]$gpuPlan.Unit2.Id] = $true
                AutoLog "[Plan] Phase 4: GPU → units $($gpuPlan.Unit1.Id),$($gpuPlan.Unit2.Id) → cores [$($gpuCoreAssignment -join ', ')] (CPPC=$($gpuPlan.CombinedRating))" 'DarkGray'
            }

            $remainingUnits = @($physUnits | Where-Object { -not $gpuConsumedUnitIds.ContainsKey([int]$_.Id) })

            $audioDevicesToPlan = [System.Collections.ArrayList]::new()
            foreach ($slot in $audioSlots) { [void]$audioDevicesToPlan.Add($slot) }

            $shareablePCoreSlots = [System.Collections.ArrayList]::new()
            foreach ($slot in $audioDevicesToPlan) { [void]$shareablePCoreSlots.Add($slot) }
            foreach ($slot in $nicSlots) { [void]$shareablePCoreSlots.Add($slot) }
            foreach ($slot in $kbSlots) { [void]$shareablePCoreSlots.Add($slot) }

            $shareablePCoreCount = $shareablePCoreSlots.Count
            $unitsForShareableRecalc = [math]::Max(0, $remainingUnits.Count - $isolatedCount)
            $needsSharingRecalc = ($shareablePCoreCount -gt $unitsForShareableRecalc)
            $hasSurplusRecalc = (($isolatedCount + $shareablePCoreCount) -lt $remainingUnits.Count)
            $surplusRecalc = if ($hasSurplusRecalc) { $remainingUnits.Count - $isolatedCount - $shareablePCoreCount } else { 0 }

            AutoLog "[Plan] Phase 5: remaining=$($remainingUnits.Count) iso=$isolatedCount sharePCore=$shareablePCoreCount sharing=$needsSharingRecalc surplus=$hasSurplusRecalc($surplusRecalc)" 'DarkGray'

            if ($script:cppcEnabled) {
                $unitsByWorst = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remainingUnits 'Rating')
                $unitsByBest  = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remainingUnits 'Rating' -Descending)
            } else {
                $unitsByWorst = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remainingUnits 'Id')
                $unitsByBest  = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remainingUnits 'Id' -Descending)
            }

            $avoidCore0ForNonCppcSurplus = $false
            if ((-not $script:cppcEnabled) -and (-not $needsSharingRecalc) -and $hasSurplusRecalc) {
                $unitsWithoutCore0 = @($remainingUnits | Where-Object { -not ($_.Cores -contains 0) })
                $requiredNonCore0Units = $isolatedCount + $shareablePCoreCount
                if ($unitsWithoutCore0.Count -ge $requiredNonCore0Units) {
                    $avoidCore0ForNonCppcSurplus = $true
                    $unitsByWorst = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $unitsWithoutCore0 'Id') + @(ConvertTo-DeviceTweakerFastSortedByIntProperty (Get-DeviceTweakerFastUnitsContainingCore $remainingUnits 0) 'Id')
                    AutoLog "[Plan] Non-CPPC surplus: core 0 avoided because non-core0 units cover all remaining devices" 'DarkGray'
                }
            }

            $consumedUnitIds = @{}
            function Consume-Unit($unitId) { $consumedUnitIds[[int]$unitId] = $true }
            if ($null -ne $core0RolePriorityConsumedUnitId) { Consume-Unit $core0RolePriorityConsumedUnitId }
            function Get-FirstAvailableUnit($sortedList) {
                foreach ($u in $sortedList) {
                    if (-not $consumedUnitIds.ContainsKey([int]$u.Id)) { return $u }
                }
                return $null
            }

            if (-not $needsSharingRecalc) {
                if ($hasSurplusRecalc -and $script:cppcEnabled) {
                    $orderedSlots = [System.Collections.ArrayList]::new()
                    foreach ($s in $audioDevicesToPlan) { [void]$orderedSlots.Add($s) }
                    foreach ($s in $nicSlots)           { [void]$orderedSlots.Add($s) }
                    foreach ($s in $kbSlots)            { [void]$orderedSlots.Add($s) }
                    foreach ($s in $mouseSlots)         { [void]$orderedSlots.Add($s) }
                    foreach ($s in $ctrlSlots)          { [void]$orderedSlots.Add($s) }
                    foreach ($slot in $orderedSlots) {
                        $unit = Get-FirstAvailableUnit $unitsByWorst
                        if ($unit) {
                            Consume-Unit $unit.Id
                            $plan[$slot.Device] = @([int]$unit.PrimaryCore)
                            AutoLog "[Plan] $($slot.Role) → unit $($unit.Id) core $($unit.PrimaryCore) (CPPC=$($unit.Rating))" 'DarkGray'
                        }
                    }
                } elseif ($script:cppcEnabled) {
                    $orderedSlots = [System.Collections.ArrayList]::new()
                    foreach ($s in $ctrlSlots)          { [void]$orderedSlots.Add($s) }
                    foreach ($s in $mouseSlots)         { [void]$orderedSlots.Add($s) }
                    foreach ($s in $kbSlots)            { [void]$orderedSlots.Add($s) }
                    foreach ($s in $nicSlots)           { [void]$orderedSlots.Add($s) }
                    foreach ($s in $audioDevicesToPlan) { [void]$orderedSlots.Add($s) }
                    foreach ($slot in $orderedSlots) {
                        $unit = Get-FirstAvailableUnit $unitsByBest
                        if ($unit) {
                            Consume-Unit $unit.Id
                            $plan[$slot.Device] = @([int]$unit.PrimaryCore)
                            AutoLog "[Plan] $($slot.Role) → unit $($unit.Id) core $($unit.PrimaryCore) (CPPC=$($unit.Rating))" 'DarkGray'
                        }
                    }
                } else {
                    $orderedSlots = [System.Collections.ArrayList]::new()
                    foreach ($s in $audioDevicesToPlan) {
                        $core0Unit = Get-DeviceTweakerFastFirstWhere $remainingUnits { param($x) @($x.Cores) -contains 0 }
                        if ((-not $avoidCore0ForNonCppcSurplus) -and $core0Unit -and -not $consumedUnitIds.ContainsKey([int]$core0Unit.Id)) {
                            Consume-Unit $core0Unit.Id
                            $plan[$s.Device] = @(0)
                            AutoLog "[Plan] Audio → core 0 (non-CPPC reserve)" 'DarkGray'
                        } else { [void]$orderedSlots.Add($s) }
                    }
                    foreach ($s in $mouseSlots)  { [void]$orderedSlots.Add($s) }
                    foreach ($s in $ctrlSlots)   { [void]$orderedSlots.Add($s) }
                    foreach ($s in $nicSlots)    { [void]$orderedSlots.Add($s) }
                    foreach ($s in $kbSlots)     { [void]$orderedSlots.Add($s) }
                    foreach ($slot in $orderedSlots) {
                        $unit = Get-FirstAvailableUnit $unitsByWorst
                        if ($unit) {
                            Consume-Unit $unit.Id
                            $plan[$slot.Device] = @([int]$unit.PrimaryCore)
                            AutoLog "[Plan] $($slot.Role) → unit $($unit.Id) core $($unit.PrimaryCore)" 'DarkGray'
                        }
                    }
                }
            } else {
                if ($script:cppcEnabled) {
                    $isoSlots = [System.Collections.ArrayList]::new()
                    foreach ($s in $ctrlSlots)  { [void]$isoSlots.Add($s) }
                    foreach ($s in $mouseSlots) { [void]$isoSlots.Add($s) }
                    foreach ($slot in $isoSlots) {
                        $unit = Get-FirstAvailableUnit $unitsByBest
                        if ($unit) {
                            Consume-Unit $unit.Id
                            $plan[$slot.Device] = @([int]$unit.PrimaryCore)
                            AutoLog "[Plan][share] $($slot.Role) → unit $($unit.Id) core $($unit.PrimaryCore) (CPPC=$($unit.Rating)) [isolated]" 'DarkGray'
                        }
                    }
                } else {

                    $sortedAscUnits = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remainingUnits 'Id')
                    $nUnits         = $sortedAscUnits.Count
                    $predictedShareableUnits = $nUnits - $isolatedCount
                    $hasOverflowIso          = ($predictedShareableUnits -le 0)

                    if ($htEnabled -and $hasOverflowIso) {
                        if ($mouseSlots.Count -gt 0) {
                            $mUnit = $sortedAscUnits[$nUnits - 1]
                            Consume-Unit $mUnit.Id
                            $plan[$mouseSlots[0].Device] = @([int]$mUnit.PrimaryCore)
                            AutoLog "[Plan][share] Mouse → unit $($mUnit.Id) core $($mUnit.PrimaryCore) [HT-ON overflow, highest set]" 'DarkGray'
                        }
                        if ($ctrlSlots.Count -gt 0) {
                            $cUnit = Get-DeviceTweakerFastFirstWhere $sortedAscUnits { param($x) -not $consumedUnitIds.ContainsKey([int]$x.Id) }
                            if ($cUnit) {
                                Consume-Unit $cUnit.Id
                                $ctrlCore = if ($cUnit.SiblingCore -ne $null) { [int]$cUnit.SiblingCore } else { [int]$cUnit.PrimaryCore }
                                $plan[$ctrlSlots[0].Device] = @($ctrlCore)
                                AutoLog "[Plan][share] Controller → unit $($cUnit.Id) core $ctrlCore [HT-ON overflow, lowest set sibling]" 'DarkGray'
                            }
                        }
                    } else {
                        $startIdx = if ($hasOverflowIso) { 0 } else { 1 }
                        $isoIdx   = $startIdx
                        foreach ($isoRole in @('Mouse', 'Controller')) {
                            $isoSlotList = if ($isoRole -eq 'Mouse') { $mouseSlots } else { $ctrlSlots }
                            if ($isoSlotList.Count -gt 0 -and $isoSlotList[0].Device -ne $null -and $isoIdx -lt $nUnits) {
                                $u = $sortedAscUnits[$isoIdx]
                                Consume-Unit $u.Id
                                $plan[$isoSlotList[0].Device] = @([int]$u.PrimaryCore)
                                AutoLog "[Plan][share] $isoRole → unit $($u.Id) core $($u.PrimaryCore) [non-CPPC isolated, idx=$isoIdx]" 'DarkGray'
                                $isoIdx++
                            }
                        }
                    }
                }

                $availUnits = @($remainingUnits | Where-Object { -not $consumedUnitIds.ContainsKey([int]$_.Id) })
                $actualAvail = $availUnits.Count

                if ($actualAvail -le 0) {
                    $mouseUnit = $null
                    if ($mouseSlots.Count -gt 0 -and $plan.ContainsKey($mouseSlots[0].Device)) {
                        $mouseCore = $plan[$mouseSlots[0].Device][0]
                        $mouseUnit = Get-DeviceTweakerFastFirstWhere $physUnits { param($x) @($x.Cores) -contains $mouseCore }
                    }
                    if ($mouseUnit) {
                        $shareCore = if ($htEnabled -and $mouseUnit.SiblingCore -ne $null) { [int]$mouseUnit.SiblingCore } else { [int]$mouseUnit.PrimaryCore }
                        $allShareSlots = [System.Collections.ArrayList]::new()
                        foreach ($s in $audioDevicesToPlan) { [void]$allShareSlots.Add($s) }
                        foreach ($s in $nicSlots)           { [void]$allShareSlots.Add($s) }
                        foreach ($s in $kbSlots)            { [void]$allShareSlots.Add($s) }
                        foreach ($slot in $allShareSlots) {
                            $plan[$slot.Device] = @($shareCore)
                            AutoLog "[Plan][share] $($slot.Role) → core $shareCore [Mouse unit sibling/same]" 'DarkGray'
                        }
                    } else {
                        $fb = if ($remainingUnits.Count -gt 0) { [int]$remainingUnits[0].PrimaryCore } else { 0 }
                        foreach ($slot in $shareablePCoreSlots) { $plan[$slot.Device] = @($fb) }
                    }
                } elseif ($actualAvail -ge $shareablePCoreCount) {
                    if ($script:cppcEnabled) {
                        $shareSlots = [System.Collections.ArrayList]::new()
                        foreach ($s in $kbSlots)            { [void]$shareSlots.Add($s) }
                        foreach ($s in $nicSlots)           { [void]$shareSlots.Add($s) }
                        foreach ($s in $audioDevicesToPlan) { [void]$shareSlots.Add($s) }
                        $sortedA = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $availUnits 'Rating' -Descending)
                        $idx = 0
                        foreach ($slot in $shareSlots) {
                            while ($idx -lt $sortedA.Count -and $consumedUnitIds.ContainsKey([int]$sortedA[$idx].Id)) { $idx++ }
                            if ($idx -lt $sortedA.Count) {
                                Consume-Unit $sortedA[$idx].Id
                                $plan[$slot.Device] = @([int]$sortedA[$idx].PrimaryCore)
                                $idx++
                            }
                        }
                    } else {
                        $sortedA = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $availUnits 'Id')
                        foreach ($s in $audioDevicesToPlan) {
                            $c0u = Get-DeviceTweakerFastFirstWhere $sortedA { param($x) @($x.Cores) -contains 0 }
                            if ($c0u -and -not $consumedUnitIds.ContainsKey([int]$c0u.Id)) {
                                Consume-Unit $c0u.Id; $plan[$s.Device] = @(0)
                            } else {
                                $u = Get-DeviceTweakerFastFirstWhere $sortedA { param($x) -not $consumedUnitIds.ContainsKey([int]$x.Id) }
                                if ($u) { Consume-Unit $u.Id; $plan[$s.Device] = @([int]$u.PrimaryCore) }
                            }
                        }
                        foreach ($s in $nicSlots) {
                            $u = Get-DeviceTweakerFastFirstWhere $sortedA { param($x) -not $consumedUnitIds.ContainsKey([int]$x.Id) }
                            if ($u) { Consume-Unit $u.Id; $plan[$s.Device] = @([int]$u.PrimaryCore) }
                        }
                        foreach ($s in $kbSlots) {
                            $u = Get-DeviceTweakerFastFirstWhere $sortedA { param($x) -not $consumedUnitIds.ContainsKey([int]$x.Id) }
                            if ($u) { Consume-Unit $u.Id; $plan[$s.Device] = @([int]$u.PrimaryCore) }
                        }
                    }
                } else {
                    if ($script:cppcEnabled) {
                        $sortedA = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $availUnits 'Rating' -Descending)
                    } else {
                        $sortedA = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $availUnits 'Id')
                        $c0a = $sortedA | Where-Object { $_.Cores -contains 0 }
                        if ($c0a) { $sortedA = @($c0a) + @($sortedA | Where-Object { -not ($_.Cores -contains 0) }) }
                    }

                    if ($actualAvail -eq 1) {
                        $su = $sortedA[0]; Consume-Unit $su.Id
                        if ($htEnabled -and $su.SiblingCore -ne $null) {
                            foreach ($s in $audioDevicesToPlan) { $plan[$s.Device] = @([int]$su.PrimaryCore) }
                            foreach ($s in $nicSlots)           { $plan[$s.Device] = @([int]$su.PrimaryCore) }
                            foreach ($s in $kbSlots)            { $plan[$s.Device] = @([int]$su.SiblingCore) }
                        } else {
                            foreach ($slot in $shareablePCoreSlots) { $plan[$slot.Device] = @([int]$su.PrimaryCore) }
                        }
                    } elseif ($actualAvail -eq 2) {
                        $audioNicUnit = $null; $kbUnit = $null
                        if ($script:cppcEnabled) {
                            $audioNicUnit = $sortedA[$sortedA.Count - 1]
                            $kbUnit = $sortedA[0]
                        } else {
                            $audioNicUnit = $sortedA[0]
                            $kbUnit = $sortedA[1]
                        }
                        Consume-Unit $audioNicUnit.Id; Consume-Unit $kbUnit.Id
                        if ($htEnabled -and $audioNicUnit.SiblingCore -ne $null) {
                            foreach ($s in $audioDevicesToPlan) { $plan[$s.Device] = @([int]$audioNicUnit.PrimaryCore) }
                            foreach ($s in $nicSlots)           { $plan[$s.Device] = @([int]$audioNicUnit.SiblingCore) }
                        } else {
                            foreach ($s in $audioDevicesToPlan) { $plan[$s.Device] = @([int]$audioNicUnit.PrimaryCore) }
                            foreach ($s in $nicSlots)           { $plan[$s.Device] = @([int]$audioNicUnit.PrimaryCore) }
                        }
                        foreach ($s in $kbSlots) { $plan[$s.Device] = @([int]$kbUnit.PrimaryCore) }
                    } else {
                        $shareSlots = [System.Collections.ArrayList]::new()
                        if ($script:cppcEnabled) {
                            foreach ($s in $kbSlots)            { [void]$shareSlots.Add($s) }
                            foreach ($s in $nicSlots)           { [void]$shareSlots.Add($s) }
                            foreach ($s in $audioDevicesToPlan) { [void]$shareSlots.Add($s) }
                        } else {
                            foreach ($s in $audioDevicesToPlan) { [void]$shareSlots.Add($s) }
                            foreach ($s in $nicSlots)           { [void]$shareSlots.Add($s) }
                            foreach ($s in $kbSlots)            { [void]$shareSlots.Add($s) }
                        }
                        $idx = 0
                        foreach ($slot in $shareSlots) {
                            while ($idx -lt $sortedA.Count -and $consumedUnitIds.ContainsKey([int]$sortedA[$idx].Id)) { $idx++ }
                            if ($idx -lt $sortedA.Count) {
                                Consume-Unit $sortedA[$idx].Id
                                $plan[$slot.Device] = @([int]$sortedA[$idx].PrimaryCore)
                                $idx++
                            }
                        }
                    }
                }
            }

            AutoLog "[Plan] Phase 5 complete: $($plan.Count) planned assignments" 'DarkGray'

            foreach ($gpu in $gpus) {
                if ($gpuCoreAssignment.Count -ge 2) {
                    $assignedMap[$gpu] = $gpuCoreAssignment
                    $maskInt = [uint64]0
                    foreach ($c in $gpuCoreAssignment) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                    $hexMask = "{0:X16}" -f $maskInt
                    AutoLog "[Exec][GPU] cores [$($gpuCoreAssignment -join ', ')] mask 0x$hexMask" 'DarkGray'
                    Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask) | Out-Null
                    $occupiedCores += $gpuCoreAssignment
                    foreach ($c in $gpuCoreAssignment) {
                        $usedCores[[int]$c] = $true
                        $sid = Get-SmtSetIdForCore -core $c -smtSets $smtSets
                        if ($sid -ne $null) { $usedSmtSets[[int]$sid] = $true }
                    }
                } else {
                    Write-Host "[Exec][GPU] WARNING - no GPU cores planned" -ForegroundColor Yellow
                    $assignedMap[$gpu] = @()
                }
            }

            foreach ($kv in $plan.GetEnumerator()) {
                $dev = $kv.Key
                $cores = $kv.Value
                if ($cores.Count -eq 0) { continue }
                $core = [int]$cores[0]
                $assignedMap[$dev] = $cores
                $usedCores[[int]$core] = $true
                $sid = Get-SmtSetIdForCore -core $core -smtSets $smtSets
                if ($sid -ne $null) { $usedSmtSets[[int]$sid] = $true }

                if ($dev.Category -eq 'Network') {
                    if ($dev.Role -eq 'NDIS') {
                        try {
                            $ndisMode = $script:autoNdisAffinityMode
                            AutoLog "[Exec][NIC] NDIS affinity mode: $ndisMode" 'DarkGray'
                            if ($ndisMode -eq 'RSS' -or $ndisMode -eq 'BOTH') {
                                $null = Set-ExovanceRssConfiguration -RegistryPath $dev.RegistryPath -BaseProcessor $core -QueueCount 1
                            }
                            if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                                $irqTp = if ($dev.ConfigPath) { $dev.ConfigPath } else { $dev.RegistryPath }
                                $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                                Set-DeviceAffinity $irqTp ("0x" + $mask) | Out-Null
                                AutoLog "[Exec][NIC] NDIS IRQ Policy: AssignmentSetOverride=0x$mask + DevicePolicy=4 at $(Format-RegistryPathForDisplay $irqTp) -> core $core" 'DarkGray'
                            }
                        } catch { Write-Host "[Exec][NIC] NDIS fail: $_" -ForegroundColor Yellow }
                    } else {
                        $tp = Get-NetworkAdapterAffinityRegistryPath $dev
                        $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                        Set-DeviceAffinity $tp ("0x" + $mask) | Out-Null
                        AutoLog "[Exec][NIC] NetAdapterCx core $core" 'DarkGray'
                    }
                    $weakOccupiedCores += @($core)
                } else {
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    Set-DeviceAffinity $dev.RegistryPath ("0x" + $mask) | Out-Null
                    AutoLog "[Exec] $($dev.DisplayName) → core $core" 'DarkGray'
                    if ($dev.Category -eq 'USB') {
                        $roles = Get-AutoOptRoles $dev
                        if ($roles -contains 'Mouse' -or $roles -contains 'Controller') {
                            $occupiedCores += @($core)
                        } elseif (($roles.Count -eq 1) -and ($roles -contains 'Audio')) {
                            $weakOccupiedCores += @($core)
                        } elseif (($roles.Count -eq 1) -and ($roles -contains 'Keyboard')) {
                            $weakOccupiedCores += @($core)
                        } elseif (($roles -contains 'Audio') -and ($roles -contains 'Keyboard') -and
                                  (($roles | Where-Object { $_ -ne 'Audio' -and $_ -ne 'Keyboard' }).Count -eq 0)) {
                            $weakOccupiedCores += @($core)
                        } else { $occupiedCores += @($core) }
                    } elseif ($dev.Category -eq 'PCI' -and $dev.Role -eq 'Audio') {
                        $weakOccupiedCores += @($core)
                    }
                }
            }
        }


        $policyNames = @{
            0 = "MachineDefault"
            1 = "AllCloseProcessors"
            2 = "OneCloseProcessor"
            3 = "AllProcessorsInMachine"
            4 = "SpecifiedProcessors"
            5 = "SpreadMessagesAcrossAllProcessors"
        }

        $deviceResults = [System.Collections.ArrayList]::new()

        foreach ($dev in $deviceList) {
            $msiPath = if ($dev.Category -eq "Network") { Get-NetworkAdapterMSIRegistryPath $dev } else { $dev.RegistryPath }
            if ($dev.Category -eq "Network") {

                if ($dev.Role -eq "NDIS") {
                    $ndisMode = $script:autoNdisAffinityMode
                    if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                        $irqPolicyPath = if ($dev.ConfigPath) { $dev.ConfigPath } else { $dev.RegistryPath }
                        Set-DevicePolicy $irqPolicyPath 4 | Out-Null
                        AutoLog "[AutoOpt][NIC] NDIS IRQ Policy: DevicePolicy=4 at $(Format-RegistryPathForDisplay $irqPolicyPath)" 'DarkGray'
                    }
                    if ($applyNdisMsi) {
                        $ndisMsiPath = Get-NetworkAdapterMSIRegistryPath $dev
                        Set-DeviceMSI $ndisMsiPath 1 "" | Out-Null
                        Set-DevicePriority $ndisMsiPath 3 | Out-Null
                        AutoLog "[AutoOpt][NIC] NDIS MSI enabled, MessageNumberLimit=Unlimited at $(Format-RegistryPathForDisplay $ndisMsiPath)" 'DarkGray'
                    }
                }
                elseif ($dev.Role -eq "NetAdapterCx") {
                    $policyPath = Get-NetworkAdapterAffinityRegistryPath $dev
                    Set-DevicePolicy $policyPath 4 | Out-Null
                    if ($applyNdisMsi) {
                        $netCxMsiPath = Get-NetworkAdapterMSIRegistryPath $dev
                        Set-DeviceMSI $netCxMsiPath 1 "" | Out-Null
                        Set-DevicePriority $netCxMsiPath 3 | Out-Null
                        AutoLog "[AutoOpt][NIC] NetAdapterCx MSI enabled, MessageNumberLimit=Unlimited at $(Format-RegistryPathForDisplay $netCxMsiPath)" 'DarkGray'
                    }
                }

                continue
            }
            if (Test-DeviceTweakerStorageDevice $dev) {
                $chosenMsgLimit = ""
                Set-DeviceMSI $msiPath 1 $chosenMsgLimit | Out-Null
                Set-DevicePriority $msiPath 3 | Out-Null
                continue
            }
            $chosenMsgLimit = ""
            Set-DeviceMSI $msiPath 1 $chosenMsgLimit | Out-Null
            Set-DevicePriority $msiPath 3 | Out-Null
        }

        $devIndex = 0
        foreach ($dev in $deviceList) {
            $devIndex++
            $assigned = $assignedMap[$dev]
            $assignedCores = if ($assigned -and $assigned.Count -gt 0) { $assigned } else { @() }

            $msiPath = if ($dev.Category -eq "Network") { Get-NetworkAdapterMSIRegistryPath $dev } else { $dev.RegistryPath }
            $msiInfo = Get-CurrentMSI $msiPath

            $affinityPath  = $null
            $policyPath    = $null
            $policyValue   = $null
            $isNDIS        = ($dev.Category -eq "Network" -and $dev.Role -eq "NDIS")

            if ($isNDIS) {
                $ndisLogMode = $script:autoNdisAffinityMode
                $affinityPath = $dev.RegistryPath
                $ndisIrqLogPath = if ($dev.ConfigPath) { $dev.ConfigPath } else { $dev.RegistryPath }
                if ($ndisLogMode -eq 'IRQ' -or $ndisLogMode -eq 'BOTH') {
                    $policyPath  = $ndisIrqLogPath
                    $policyValue = Get-CurrentDevicePolicy $policyPath
                } else {
                    $policyValue = $null
                }
            } elseif ($dev.Category -eq "Network" -and $dev.Role -eq "NetAdapterCx") {
                $affinityPath = Get-NetworkAdapterAffinityRegistryPath $dev
                $policyPath   = $affinityPath
                $policyValue  = Get-CurrentDevicePolicy $policyPath
            } else {
                $affinityPath = $dev.RegistryPath
                $policyPath   = $dev.RegistryPath
                $policyValue  = Get-CurrentDevicePolicy $policyPath
            }

            $fmtAffinityPath = if ($affinityPath) { Format-RegistryPathForDisplay $affinityPath } else { "(N/A)" }
            $fmtMsiPath      = Format-RegistryPathForDisplay $msiPath
            $fmtPolicyPath   = if ($policyPath) { Format-RegistryPathForDisplay $policyPath } else { "(N/A)" }

            $affinityRegFull = if ($isNDIS) {
                $ndisLogMode = $script:autoNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') {
                    "$fmtAffinityPath  [*RssBaseProcNumber]"
                } elseif ($ndisLogMode -eq 'IRQ') {
                    $fmtIrqPath = Format-RegistryPathForDisplay $ndisIrqLogPath
                    "$fmtIrqPath\Device Parameters\Interrupt Management\Affinity Policy  [AssignmentSetOverride]"
                } else {
                    $fmtIrqPath = Format-RegistryPathForDisplay $ndisIrqLogPath
                    "$fmtAffinityPath  [*RssBaseProcNumber]  +  $fmtIrqPath\Device Parameters\Interrupt Management\Affinity Policy  [AssignmentSetOverride]"
                }
            } else {
                "$fmtAffinityPath\Device Parameters\Interrupt Management\Affinity Policy"
            }
            $msiRegFull    = "$fmtMsiPath\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
            $policyRegFull = if ($isNDIS) {
                $ndisLogMode = $script:autoNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') {
                    "(NDIS RSS-only: uses *RssBaseProcNumber, no IRQ policy)"
                } elseif ($ndisLogMode -eq 'IRQ') {
                    "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy  [DevicePolicy=4]"
                } else {
                    "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy  [DevicePolicy=4]  (BOTH: RSS + IRQ)"
                }
            } elseif ($policyPath) {
                "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy"
            } else {
                "(N/A)"
            }

            $policyStr = if ($isNDIS) {
                $ndisLogMode = $script:autoNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') {
                    "N/A (NDIS RSS-only: *RssBaseProcNumber)"
                } elseif ($ndisLogMode -eq 'IRQ') {
                    if ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) { "SpecifiedProcessors ($policyValue)  [NDIS IRQ Policy mode]" } else { "SpecifiedProcessors (4)  [NDIS IRQ Policy mode - pending restart]" }
                } else {
                    $irqPart = if ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) { "$($policyNames[[int]$policyValue]) ($policyValue)" } else { "SpecifiedProcessors (4) [pending restart]" }
                    "$irqPart  [NDIS BOTH: RSS + IRQ Policy]"
                }
            } elseif ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) {
                "$($policyNames[[int]$policyValue]) ($policyValue)"
            } elseif ($null -ne $policyValue) {
                "Unknown ($policyValue)"
            } else {
                "Not Set"
            }

            $affinityStr = if ($isNDIS) {
                $ndisLogMode = $script:autoNdisAffinityMode
                $rssVal = $null
                try { $rssVal = (Get-ItemProperty -Path $dev.RegistryPath -Name "*RssBaseProcNumber" -ErrorAction SilentlyContinue).'*RssBaseProcNumber' } catch {}
                $irqAffStr = $null
                if ($ndisLogMode -eq 'IRQ' -or $ndisLogMode -eq 'BOTH') {
                    $rawAff = Get-CurrentAffinity $ndisIrqLogPath $false
                    $maskInt64 = [uint64]0
                    try { $maskInt64 = [Convert]::ToUInt64($rawAff.TrimStart('0x'), 16) } catch {}
                    if ($maskInt64 -gt 0) {
                        $coresFromMask = @(); for ($b = 0; $b -lt 64; $b++) { if ($maskInt64 -band ([uint64]1 -shl $b)) { $coresFromMask += $b } }
                        $irqAffStr = "IRQ: Cores $($coresFromMask -join ', ')  (AssignmentSetOverride=0x$("{0:X16}" -f $maskInt64))"
                    }
                }
                if ($ndisLogMode -eq 'RSS') {
                    if ($null -ne $rssVal) { "Core $rssVal  (*RssBaseProcNumber=$rssVal)" } else { "(not set)" }
                } elseif ($ndisLogMode -eq 'IRQ') {
                    if ($irqAffStr) { $irqAffStr } else { "(IRQ not yet applied - restart required)" }
                } else {
                    $rssPart = if ($null -ne $rssVal) { "RSS: Core $rssVal (*RssBaseProcNumber=$rssVal)" } else { "RSS: (not set)" }
                    $irqPart = if ($irqAffStr) { $irqAffStr } else { "IRQ: (pending restart)" }
                    "$rssPart  +  $irqPart"
                }
            } else {
                $rawAff = Get-CurrentAffinity $affinityPath $false
                $maskInt64 = [uint64]0
                try { $maskInt64 = [Convert]::ToUInt64($rawAff.TrimStart('0x'), 16) } catch {}
                if ($maskInt64 -gt 0) {
                    $coresFromMask = @()
                    for ($b = 0; $b -lt 64; $b++) {
                        if ($maskInt64 -band ([uint64]1 -shl $b)) { $coresFromMask += $b }
                    }
                    "Cores $($coresFromMask -join ', ')  (mask 0x$("{0:X16}" -f $maskInt64))"
                } else {
                    "(not assigned)"
                }
            }

            $msiStr = if ([int]$msiInfo.MSIEnabled -eq 1) { "Enabled" } else { "Disabled" }

            $msgLimitStr = if ($msiInfo.MessageLimit -eq "" -or $msiInfo.MessageLimit -eq $null -or ([string]$msiInfo.MessageLimit -eq "0")) {
                "Unlimited"
            } else {
                "$($msiInfo.MessageLimit)"
            }

            $displayLabel = $dev.DisplayName

            [void]$deviceResults.Add([PSCustomObject]@{
                Index          = $devIndex
                DisplayLabel   = $displayLabel
                Category       = $dev.Category
                Role           = $dev.Role
                AffinityStr    = $affinityStr
                PolicyStr      = $policyStr
                MsiStr         = $msiStr
                MsgLimitStr    = $msgLimitStr
                AffinityReg    = $affinityRegFull
                MsiReg         = $msiRegFull
                PolicyReg      = $policyRegFull
            })
        }

        foreach ($usb in $usbs) {
            $assigned = $assignedMap[$usb]
            if (-not $assigned) { continue }
            if ($usb.Roles -contains 'Controller' -or $usb.Roles -contains 'Mouse') {
                $occupiedCores += $assigned
            }
            $norm = Get-AutoOptRoles $usb
            if (($norm.Count -eq 1) -and ($norm -contains 'Audio')) {
                $weakOccupiedCores += $assigned
            }
        }

        foreach ($usb in $usbs) {
            $assigned = $assignedMap[$usb]
            if (-not $assigned) { continue }
            $normRoles = Get-AutoOptRoles $usb
            $hasAudio = ($normRoles -contains 'Audio')
            $hasKeyboard = ($normRoles -contains 'Keyboard')
            $otherRoles = $normRoles | Where-Object { $_ -ne 'Audio' -and $_ -ne 'Keyboard' }
            if ($hasAudio -and $hasKeyboard -and ($otherRoles.Count -eq 0)) {
                $weakOccupiedCores += $assigned
            }
        }

        foreach ($gpu in $gpus) {
            $assigned = $assignedMap[$gpu]
            if ($assigned) { $occupiedCores += $assigned }
        }
        $occupiedCores = Merge-AssignedGpuCoresIntoOccupiedList -GpuDevices $gpus -AssignedMap $assignedMap -CurrentOccupiedCores $occupiedCores

        foreach ($nic in $nics) {
            $assigned = $assignedMap[$nic]
            if ($assigned) { $weakOccupiedCores += $assigned }
        }

        $occupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $occupiedCores)
        $weakOccupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $weakOccupiedCores)
        $weakOccupiedCores = @($weakOccupiedCores | Where-Object { $occupiedCores -notcontains [int]$_ })

        $scriptDir = $script:cachedScriptDir
        $gamesCfgPath = Join-Path $scriptDir "games_priorities.cfg"
        $systemCfgPath = Join-Path $scriptDir "system_priorities.cfg"

        function Write-ConfigFileEntriesLocal {
            param($path, $coresArr, $weakArr)
            $coresString = ($coresArr -join ',')
            $weakString = ($weakArr -join ',')
            if (-not (Test-Path $path)) { New-Item -Path $path -ItemType File -Force | Out-Null }
            $content = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
            if ($content -match '(?m)^occupied_affinity_cores=.*$') { $content = $content -replace '(?m)^occupied_affinity_cores=.*$', "occupied_affinity_cores=$coresString" } else { $content += "`r`noccupied_affinity_cores=$coresString" }
            if ($content -match '(?m)^occupied_ideal_processor_cores=.*$') { $content = $content -replace '(?m)^occupied_ideal_processor_cores=.*$', "occupied_ideal_processor_cores=$coresString" } else { $content += "`r`noccupied_ideal_processor_cores=$coresString" }
            if ($content -match '(?m)^occupied_weak_affinity_cores=.*$') { $content = $content -replace '(?m)^occupied_weak_affinity_cores=.*$', "occupied_weak_affinity_cores=$weakString" } else { $content += "`r`noccupied_weak_affinity_cores=$weakString" }
            if ($content -match '(?m)^occupied_weak_ideal_processor_cores=.*$') { $content = $content -replace '(?m)^occupied_weak_ideal_processor_cores=.*$', "occupied_weak_ideal_processor_cores=$weakString" } else { $content += "`r`noccupied_weak_ideal_processor_cores=$weakString" }
            $content = Set-PreferredCCDConfigLine -Content $content -PreferredCcd (Get-PreferredCCDForConfig)
            [System.IO.File]::WriteAllText($path, $content.Trim(), [System.Text.UTF8Encoding]::new($false))
        }

        $cfgWriteOk1 = $false; $cfgWriteOk2 = $false
        $cfgSkipped = $false
        $autoOptSecretPath = Join-Path $scriptDir "SecretTweak.exe"
        if (-not (Test-Path $autoOptSecretPath)) {
            $cfgSkipped = $true
            Write-Host "[AutoOpt] Optional legacy CFG export unavailable - skipped" -ForegroundColor DarkYellow
        } else {
            try { Write-ConfigFileEntriesLocal -path $gamesCfgPath -coresArr $occupiedCores -weakArr $weakOccupiedCores; $cfgWriteOk1 = $true } catch { }
            try { Write-ConfigFileEntriesLocal -path $systemCfgPath -coresArr $occupiedCores -weakArr $weakOccupiedCores; $cfgWriteOk2 = $true } catch { }
        }

        $guiRefreshOk = $false
        try { Refresh-DeviceUI; $guiRefreshOk = $true } catch { }

        Write-Host ""
        Write-Host "  DEVICE ASSIGNMENTS" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray

        $pad1 = 22

        foreach ($r in $deviceResults) {
            Write-Host ""
            Write-Host ("  {0}. {1}" -f $r.Index, $r.DisplayLabel) -ForegroundColor Yellow
            Write-Host ("  {0}{1}" -f ("".PadRight(4)), ("".PadRight(60, '-'))) -ForegroundColor DarkGray
            Write-Host ("      {0} : {1}" -f "Affinity".PadRight($pad1),       $r.AffinityStr)
            Write-Host ("      {0} : {1}" -f "IRQ Policy".PadRight($pad1),     $r.PolicyStr)
            Write-Host ("      {0} : {1}" -f "MSI Mode".PadRight($pad1),       $r.MsiStr)
            Write-Host ("      {0} : {1}" -f "Message Limit".PadRight($pad1),  $r.MsgLimitStr)
            Write-Host ("      {0} :" -f "Registry Paths".PadRight($pad1)) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "Affinity".PadRight($pad1 - 2),   $r.AffinityReg) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "MSI".PadRight($pad1 - 2),        $r.MsiReg) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "IRQ Policy".PadRight($pad1 - 2), $r.PolicyReg) -ForegroundColor DarkGray
        }

        Write-Host ""
        Write-Host "  FINAL STATE" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        $occStr  = if ($occupiedCores.Count -gt 0) { $occupiedCores -join ', ' } else { "(none)" }
        $weakStr = if ($weakOccupiedCores.Count -gt 0) { $weakOccupiedCores -join ', ' } else { "(none)" }
        Write-Host ("  Occupied Cores       : {0}" -f $occStr) -ForegroundColor Green
        Write-Host ("  Occupied Weak Cores  : {0}" -f $weakStr) -ForegroundColor Green

        $cfg1Status = if ($cfgSkipped) { "Skipped (optional legacy export)" } elseif ($cfgWriteOk1) { "Written" } else { "FAILED" }
        $cfg2Status = if ($cfgSkipped) { "Skipped (optional legacy export)" } elseif ($cfgWriteOk2) { "Written" } else { "FAILED" }
        $cfg1Color  = if ($cfgSkipped) { "DarkYellow" } elseif ($cfgWriteOk1) { "Green" } else { "Red" }
        $cfg2Color  = if ($cfgSkipped) { "DarkYellow" } elseif ($cfgWriteOk2) { "Green" } else { "Red" }
        Write-Host ("  Config: games_priorities.cfg    : {0}" -f $cfg1Status) -ForegroundColor $cfg1Color
        Write-Host ("  Config: system_priorities.cfg   : {0}" -f $cfg2Status) -ForegroundColor $cfg2Color

        $guiStatus = if ($guiRefreshOk) { "Refreshed" } else { "FAILED" }
        $guiColor  = if ($guiRefreshOk) { "Cyan" } else { "Red" }
        Write-Host ("  GUI                  : {0}" -f $guiStatus) -ForegroundColor $guiColor

        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkCyan
        Assert-ExovanceWritesSucceeded
        Set-ExovanceUiFeedback -State Applied -Text 'Auto plan applied - review results'
        Write-Host "    AUTO-OPTIMIZATION COMPLETED SUCCESSFULLY" -ForegroundColor Green
        Write-Host "  ================================================================" -ForegroundColor DarkCyan
        Write-Host ""

        Show-DarkMessageBox -Message "Auto-optimization finished. A system restart may be required." -Title "Auto-Optimization" -Icon Information
    }
    catch {
        $autoOptErrMsg = "Auto-optimization failed: $($_.Exception.Message)"
        if ($_.InvocationInfo) {
            if ($_.InvocationInfo.ScriptLineNumber) {
                $autoOptErrMsg += "`n`nLine: $($_.InvocationInfo.ScriptLineNumber)"
            }
            if ($_.InvocationInfo.Line) {
                $autoOptErrMsg += "`nCode: $($_.InvocationInfo.Line.Trim())"
            }
        }
        Write-Host "[AutoOpt] Error: $autoOptErrMsg" -ForegroundColor Red
        Set-ExovanceUiFeedback -State Error -Text 'Action incomplete - review error details'
        Show-DarkMessageBox -Message $autoOptErrMsg -Title "Error" -Icon Error
    }

    } finally {
        Exit-DeviceTweakerUiAction
    }
})

$btnSecretOpt.Add_Click({
    if (-not (Enter-DeviceTweakerUiAction -Name 'Alternate Plan' -Button $this)) { return }
    try {
    try {
        $alternateConfirm = Show-DarkMessageBox -Message "Alternate Plan groups selected USB/audio/network devices on a shared CPU and assigns GPU CPUs separately. It can change ReservedCpuSets. HAGS is not changed. Compare results with Auto; faster performance is not guaranteed. Continue?" -Title 'Alternate Plan' -Buttons YesNo -Icon Question
        if ($alternateConfirm -ne [System.Windows.Forms.DialogResult]::Yes) { return }

        $backupResult = Show-DarkMessageBox `
            -Message "Do you want to backup your current device settings before alternate plan?" `
            -Title   "Alternate Plan" `
            -Buttons YesNoCancel `
            -Icon    Question
        if ($backupResult -eq [System.Windows.Forms.DialogResult]::Cancel) { return }
        if ($backupResult -eq [System.Windows.Forms.DialogResult]::Yes) {
            try {
                $backupFile = Backup-DeviceSettings
                Show-DarkMessageBox -Message "Settings backed up to:`n$backupFile" -Title "Backup Complete" -Icon Information
            } catch {
                Set-ExovanceUiFeedback -State Error -Text 'Backup failed - automatic changes stopped'
                Show-DarkMessageBox -Message "Backup failed: $_`n`nNo alternate plan was started." -Title "Backup Error" -Icon Error
                return
            }
        }

        # Keep the complete list for backup/restore; writes use verified physical adapters only.
        $deviceList = @(Get-ExovanceWritableDevices -Devices $deviceList)

        $applyNdisMsi = $false
