        }



        function Format-SecretDebugList {
            param($Items)
            if ($null -eq $Items) { return '(none)' }
            $arr = @($Items)
            if ($arr.Count -eq 0) { return '(none)' }
            return (($arr | ForEach-Object { [string]$_ }) -join ', ')
        }

        function Format-SecretUsedState {
            param([hashtable]$UsedCores, [hashtable]$UsedSmtSets)
            $cores = @()
            $sets = @()
            if ($UsedCores) { $cores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $UsedCores.Keys) }
            if ($UsedSmtSets) { $sets = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $UsedSmtSets.Keys) }
            return ('UsedCores=[{0}] UsedSMT=[{1}]' -f (Format-SecretDebugList $cores), (Format-SecretDebugList $sets))
        }

        function Get-SecretCoreRatingText {
            param($Core)
            if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$Core)) {
                return [string]$script:cppcRatings[[int]$Core]
            }
            return 'n/a'
        }

        function Get-SecretUnitRatingText {
            param($Unit)
            if ($null -eq $Unit) { return 'n/a' }
            try {
                if ($Unit -is [hashtable] -and $Unit.ContainsKey('Rating')) { return [string]$Unit.Rating }
                if ($null -ne $Unit.Rating) { return [string]$Unit.Rating }
            } catch { }
            return 'n/a'
        }

        function Format-SecretUnit {
            param($Unit)
            if ($null -eq $Unit) { return '<null-unit>' }
            $coreLabels = @()
            foreach ($c in @($Unit.Cores)) {
                $coreLabels += ('{0}:r{1}' -f [int]$c, (Get-SecretCoreRatingText $c))
            }
            $sib = if ($null -ne $Unit.SiblingCore) { [string]$Unit.SiblingCore } else { 'none' }
            return ('Unit#{0} Primary={1} Sibling={2} Cores=[{3}] UnitRating={4}' -f [int]$Unit.Id, [int]$Unit.PrimaryCore, $sib, (Format-SecretDebugList $coreLabels), (Get-SecretUnitRatingText $Unit))
        }

        function Add-SecretReason {
            param([System.Collections.ArrayList]$Reasons, [string]$Reason)
            if ($null -ne $Reasons -and -not [string]::IsNullOrWhiteSpace($Reason)) { [void]$Reasons.Add($Reason) }
        }

        function Format-SecretReasons {
            param($Reasons)
            $arr = @($Reasons)
            if ($arr.Count -eq 0) { return 'OK' }
            return ($arr -join '; ')
        }
        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkMagenta
        Write-Host "    ALTERNATE PLAN STARTED" -ForegroundColor Magenta
        Write-Host "  ================================================================" -ForegroundColor DarkMagenta
        Write-Host ""

        $logicalCount = $script:cachedLogicalCount
        $cpu = $null
        $physicalCount = Get-PhysicalCoreCount
        $htEnabled = ($logicalCount -gt $physicalCount)
