        $eCoreIndices = @($eCoreIndicesAll)
        $hasECores = ($eCoreIndices.Count -gt 0)

        $targetCores = @(0..($logicalCount - 1))
        $ccdSelection = Resolve-CCDSelectionForDevices
        $reservedCpuSetsPlan = Get-SecretOptimizationReservedCpuSetsPlan -LogicalCount $logicalCount -AllPCores $pCoreIndicesAll -AllECores $eCoreIndicesAll -CcdSelection $ccdSelection
        $reservedCpuSetsResult = $null
        if ($reservedCpuSetsPlan.ShouldApply) {
            $reservedCpuSetsResult = Set-ReservedCpuSetsFromCoreList -Cores $reservedCpuSetsPlan.ReservedCores -LogicalCount $logicalCount -Reason $reservedCpuSetsPlan.Reason
        }

        if ($script:IsDualCCDCpu) {
            $targetCores = @(Get-DeviceSelectionCoresForDualCCD -Context 'Secret')
            $pCoreIndices = @($pCoreIndices | Where-Object { $targetCores -contains $_ })
            $eCoreIndices = @($eCoreIndices | Where-Object { $targetCores -contains $_ })
        }
        $hasECores = ($eCoreIndices.Count -gt 0)

        if ($htEnabled) {
            $smtSets = Get-SmtSets -logicalCount $logicalCount -pCores $pCoreIndices
        } else {
            $smtSets = @()
        }
        $smtCount = if ($smtSets) { $smtSets.Count } else { 0 }

        Write-Host "  SYSTEM TOPOLOGY (Secret)" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        $htStr = if ($htEnabled) { "Enabled" } else { "Disabled" }
        Write-Host ("  Hyperthreading       : {0} ({1} logical / {2} physical)" -f $htStr, $logicalCount, $physicalCount)
        Write-Host ("  P-Cores              : {0}" -f $(if ($pCoreIndices.Count -gt 0) { $pCoreIndices -join ', ' } else { "(none)" }))
        Write-Host ("  E-Cores              : {0}" -f $(if ($eCoreIndices.Count -gt 0) { $eCoreIndices -join ', ' } else { "(none)" }))
        $ccdStr = if ($script:IsDualCCDCpu) { "Dual-CCD" } elseif ($script:IsDualCCXCpu) { "Double-CCX (no CCD special handling)" } else { "Single-CCD" }
        Write-Host ("  CCD Topology         : {0}" -f $ccdStr)
        if ($script:IsDualCCDCpu) {
            Write-Host ("  CCD0 Cores           : {0}" -f ($script:Ccd0Cores -join ', '))
            Write-Host ("  CCD1 Cores           : {0}" -f ($script:Ccd1Cores -join ', '))
            Write-Host ("  Preferred CCD        : CCD{0}" -f [int]$ccdSelection.PreferredCCD)
            Write-Host ("  Device CCD (active)  : CCD{0} ({1})" -f [int]$ccdSelection.DeviceCCD, [string]$ccdSelection.Reason)
        }
        $cppcStr = if ($script:cppcEnabled) { "Enabled" } else { "Disabled" }
        Write-Host ("  CPPC                 : {0}" -f $cppcStr)
        if ($script:cppcEnabled) {
            $ratingStrs = @()
            foreach ($k in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $script:cppcRatings.Keys)) {
                $ratingStrs += "Core$k=$($script:cppcRatings[$k])"
            }
            Write-Host ("  CPPC Ratings         : {0}" -f ($ratingStrs -join '  '))
        }
        if ($reservedCpuSetsPlan.ShouldApply) {
            $rsCoreText = if ($reservedCpuSetsPlan.ReservedCores.Count -gt 0) { $reservedCpuSetsPlan.ReservedCores -join ', ' } else { '(none)' }
            if ($reservedCpuSetsResult -and $reservedCpuSetsResult.Success) {
                Write-Host ("  ReservedCpuSets      : {0}" -f $rsCoreText) -ForegroundColor Green
                Write-Host ("  Reserved Rule        : {0}" -f $reservedCpuSetsPlan.Reason) -ForegroundColor DarkGreen
            } elseif ($reservedCpuSetsResult) {
                Write-Host ("  ReservedCpuSets      : FAILED - {0}" -f $reservedCpuSetsResult.Error) -ForegroundColor Red
                Write-Host ("  Reserved Rule        : {0}" -f $reservedCpuSetsPlan.Reason) -ForegroundColor DarkYellow
            }
        } else {
            Write-Host ("  ReservedCpuSets      : Unchanged ({0})" -f $reservedCpuSetsPlan.Reason) -ForegroundColor DarkGray
        }
        Write-Host ""

        if ($smtCount -gt 0) {
            Write-Host "  SMT SETS (used for alternate plan)" -ForegroundColor White
            Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
            foreach ($s in $smtSets) {
                $coreLabels = @()
                foreach ($c in $s.Cores) {
                    $tag = if (Is-PCore $c) { "P" } else { "E" }
                    $cppcTag = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { " r$($script:cppcRatings[[int]$c])" } else { "" }
                    $coreLabels += "$c($tag$cppcTag)"
                }
                Write-Host ("  Set #{0,-3} : cores {1}" -f $s.Id, ($coreLabels -join ', '))
            }
            if ($script:IsDualCCDCpu) {
                Write-Host ("  (Dual-CCD: only CCD{0} SMT sets are used for assignments)" -f [int]$ccdSelection.DeviceCCD) -ForegroundColor DarkYellow
            }
            Write-Host ""
        }

        $usedCores = @{}
        $usedSmtSets = @{}
        $assignedMap = @{}
        $gpuPreReserved = @{}
        $occupiedCores = @()
        $weakOccupiedCores = @()
        $gpus = @($deviceList | Where-Object {
            $cat  = [string]$_.Category
            $role = [string]$_.Role
            $name = [string]$_.DisplayName
            $devd = [string]$_.DeviceDesc
            ($role -eq 'GPU') -or
            ($cat -eq 'GPU') -or
            ($name -match '^(?i:GPU)$') -or
            ($cat -eq 'PCI' -and (($name -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)') -or ($devd -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)')))
        })
        foreach ($gd in @($gpus)) {
        }
        $gpuLikeButUnmatched = @($deviceList | Where-Object {
            $n = [string]$_.DisplayName; $d = [string]$_.DeviceDesc
            (($n -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)') -or ($d -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)')) -and (-not (@($gpus) -contains $_))
        })
        foreach ($gdMiss in @($gpuLikeButUnmatched)) {
        }




        $nics = $deviceList | Where-Object { $_.Category -eq 'Network' }
        $usbs = $deviceList | Where-Object { $_.Category -eq 'USB' }
        $usbs = @(ConvertTo-DeviceTweakerFastSortedUsbDevices $usbs)
        $ssds = $deviceList | Where-Object { Test-DeviceTweakerStorageDevice $_ }
        $audioPCI = $deviceList | Where-Object { $_.Category -eq 'PCI' -and $_.Role -eq 'Audio' }
        $usbSingleAudio = $usbs | Where-Object {
            $norm = Get-AutoOptRoles $_
            ($norm.Count -eq 1) -and ($norm -contains 'Audio')
        }
        $hasAudioDevices = ($audioPCI.Count -gt 0) -or ($usbSingleAudio.Count -gt 0)

        function Find-FreePCoreLocal([ref]$usedCoresRef, [ref]$usedSmtRef, $pCoreIndicesParam, $smtSetsParam, [bool]$preferBestCPPC = $false) {
            if ($script:cppcEnabled -and $smtSetsParam) {
                $candidates = @()
                foreach ($s in $smtSetsParam) {
                    if (-not $usedSmtRef.Value.ContainsKey($s.Id)) {
                        foreach ($c in $s.Cores) {
                            if (-not $usedCoresRef.Value.ContainsKey($c)) {
                                $rating = if ($script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { [int]::MaxValue }
                                $candidates += @{ Core = $c; SmtId = $s.Id; Rating = $rating }
                                break
                            }
                        }
                    }
                }
                if ($candidates.Count -gt 0) {
                    if ($preferBestCPPC) {
                        $best = Get-DeviceTweakerFastBestByIntProperty $candidates 'Rating' -Descending
                    } else {
                        $best = Get-DeviceTweakerFastBestByIntProperty $candidates 'Rating'
                    }
                    return @{ Core = $best.Core; SmtId = $best.SmtId }
                }
            } elseif ($smtSetsParam) {
                foreach ($s in $smtSetsParam) {
                    if (-not $usedSmtRef.Value.ContainsKey($s.Id)) {
                        foreach ($c in $s.Cores) {
                            if (-not $usedCoresRef.Value.ContainsKey($c)) {
                                return @{ Core = $c; SmtId = $s.Id }
                            }
                        }
                    }
                }
            }
            $freeAll = $pCoreIndicesParam | Where-Object { -not $usedCoresRef.Value.ContainsKey($_) }
            if ($freeAll.Count -gt 0) {
                $core = if ($preferBestCPPC) { Get-BestCoreByCPPC $freeAll } else { Get-WeakestCoreByCPPC $freeAll }
                $smtId = Get-SmtSetIdForCore -core $core -smtSets $smtSetsParam
                return @{ Core = $core; SmtId = $smtId }
            }
            return $null
        }

        function Find-GPUCoresSecret($pCoreIndicesParam, $smtSetsParam, $htEnabledParam, [ref]$usedCoresRef, [ref]$usedSmtSetsRef) {


            $units = [System.Collections.ArrayList]::new()
            if ($htEnabledParam -and $smtSetsParam -and @($smtSetsParam).Count -ge 2) {
                foreach ($s in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $smtSetsParam 'Id')) {
                    $rating = 0
                    foreach ($c in @($s.Cores)) {
                        $r = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { [int]$script:cppcRatings[[int]$c] } else { [int]$c }
                        if ($r -gt $rating) { $rating = $r }
                    }
                    [void]$units.Add(@{
                        Id          = [int]$s.Id
                        Cores       = @($s.Cores | ForEach-Object { [int]$_ })
                        PrimaryCore = [int]$s.Cores[0]
                        Rating      = [int]$rating
                    })
                }
            } else {
                foreach ($c in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $pCoreIndicesParam)) {
                    $rating = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { [int]$script:cppcRatings[[int]$c] } else { [int]$c }
                    [void]$units.Add(@{
                        Id          = [int]$c
                        Cores       = @([int]$c)
                        PrimaryCore = [int]$c
                        Rating      = [int]$rating
                    })
                }
            }

            foreach ($u in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $units 'Id')) {
            }

            $eligible = [System.Collections.ArrayList]::new()
            foreach ($u in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $units 'Id')) {
                $reasons = [System.Collections.ArrayList]::new()
                if (@($u.Cores | Where-Object { [int]$_ -eq 0 }).Count -gt 0) { Add-SecretReason $reasons 'contains logical core 0' }
                if ($usedSmtSetsRef.Value.ContainsKey([int]$u.Id)) { Add-SecretReason $reasons ("SMT/physical unit {0} already reserved" -f [int]$u.Id) }
                foreach ($c in @($u.Cores)) {
                    if ($usedCoresRef.Value.ContainsKey([int]$c)) { Add-SecretReason $reasons ("logical core {0} already reserved" -f [int]$c) }
                }

                if ($reasons.Count -eq 0) {
                    [void]$eligible.Add($u)
                } else {
                }
            }

            $eligible = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $eligible 'Id')
            $pairs = [System.Collections.ArrayList]::new()
            for ($i = 0; $i -lt ($eligible.Count - 1); $i++) {
                $u1 = $eligible[$i]
                $u2 = $eligible[$i + 1]
                $gap = [int]$u2.Id - [int]$u1.Id
                if ($gap -ne 1) {
                    continue
                }
                $sum = [int]$u1.Rating + [int]$u2.Rating
                [void]$pairs.Add(@{ Unit1 = $u1; Unit2 = $u2; CombinedRating = [int]$sum })
            }

            if ($pairs.Count -eq 0) {
                return $null
            }

            if ($script:cppcEnabled) {
                $rankedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $pairs -Cppc)
            } else {
                $rankedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $pairs)
            }

            $selected = $rankedPairs[0]
            $coresChosen = @([int]$selected.Unit1.PrimaryCore, [int]$selected.Unit2.PrimaryCore)
            return @{
                Cores  = $coresChosen
                SmtIds = @([int]$selected.Unit1.Id, [int]$selected.Unit2.Id)
            }
        }

        function Assign-GPUDeviceSecret($gpu, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $smtSetsParam, $htEnabledParam, [ref]$assignedMapRef, [ref]$occupiedCoresRef) {
            $gpuResult = $null
            if ($gpuPreReserved.ContainsKey($gpu)) {
                $gpuResult = $gpuPreReserved[$gpu]
            } else {
                $gpuResult = Find-GPUCoresSecret -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -htEnabledParam $htEnabledParam -usedCoresRef $usedCoresRef -usedSmtSetsRef $usedSmtSetsRef
            }
            if ($gpuResult) {
                $assigned = $gpuResult.Cores
                if (-not $gpuPreReserved.ContainsKey($gpu)) {
                    foreach ($i in 0..($assigned.Count - 1)) {
                        $c = $assigned[$i]
                        $sid = if ($gpuResult.SmtIds.Count -gt $i) { $gpuResult.SmtIds[$i] } else { Get-SmtSetIdForCore -core $c -smtSets $smtSetsParam }
                        Reserve-Core $c $usedCoresRef $usedSmtSetsRef $sid
                    }
                }
                $assignedMapRef.Value[$gpu] = $assigned
                $maskInt = [uint64]0
                foreach ($c in $assigned) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                $hexMask = "{0:X16}" -f ([uint64]$maskInt)
                Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask) | Out-Null
                $occupiedCoresRef.Value += $assigned
            } else {
                $assigned = @()
                $tries = 0
                $gpuFallbackPCores = @($pCoreIndicesParam | Where-Object { [int]$_ -ne 0 })
                while ($assigned.Count -lt 2 -and $tries -lt 200) {
                    $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $gpuFallbackPCores -smtSetsParam $smtSetsParam -preferBestCPPC ([bool]$script:cppcEnabled)
                    if ($f -ne $null) {
                        if (-not ($assigned -contains $f.Core)) {
                            $assigned += $f.Core
                            Reserve-Core $f.Core $usedCoresRef $usedSmtSetsRef $f.SmtId
                        }
                    } else { break }
                    $tries++
                }
                if ($assigned.Count -eq 0) {
                    Write-Host "[Exovance/Alternate][GPU] WARNING - couldn't assign GPU cores" -ForegroundColor Yellow
                    $assignedMapRef.Value[$gpu] = @()
                } else {
                    $assignedMapRef.Value[$gpu] = $assigned
                    $maskInt = [uint64]0
                    foreach ($c in $assigned) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                    $hexMask = "{0:X16}" -f ([uint64]$maskInt)
                    Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask) | Out-Null
                    $occupiedCoresRef.Value += $assigned
                }
            }
        }

        function Assign-NICDeviceSecret($nic, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
            $shared = $false
            if ($f -eq $null) {
                $preferred = @('Audio','Mouse','Controller')
                $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                if ($share) {
                    $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true }
                    $shared = $true
                }
            }
            if ($f -ne $null) {
                $core = $f.Core
                $smtid = $f.SmtId
                if ($f.Shared) { $usedCoresRef.Value[[int]$core] = $true }
                else { Reserve-Core $core $usedCoresRef $usedSmtSetsRef $smtid }
                $assignedMapRef.Value[$nic] = @($core)
                if ($nic.Role -eq 'NDIS') {
                    try {
                        $ndisMode = $script:secretNdisAffinityMode
                        $formattedNicPath = Format-RegistryPathForDisplay $nic.RegistryPath
                        if ($ndisMode -eq 'RSS' -or $ndisMode -eq 'BOTH') {
                            $null = Set-ExovanceRssConfiguration -RegistryPath $nic.RegistryPath -BaseProcessor $core -QueueCount 1
                        }
                        if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                            $irqTp = if ($nic.ConfigPath) { $nic.ConfigPath } else { $nic.RegistryPath }
                            $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                            Set-DeviceAffinity $irqTp ("0x" + $mask) | Out-Null
                        }
                    } catch { Write-Host "[Exovance/Alternate][NIC] NDIS write fail: $_" -ForegroundColor Yellow }
                } else {
                    $targetRegistryPath = Get-NetworkAdapterAffinityRegistryPath $nic
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    Set-DeviceAffinity $targetRegistryPath ("0x" + $mask) | Out-Null
                }
                $weakOccupiedCoresRef.Value += @($core)
            } else {
                Write-Host "[Exovance/Alternate][NIC] WARNING - could not allocate NIC a P-core" -ForegroundColor Yellow
                $assignedMapRef.Value[$nic] = @()
            }
        }

        function Assign-USBDeviceSecret($usb, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $eCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$occupiedCoresRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            $roles = Get-AutoOptRoles $usb
            $isControllerRole = ($roles -contains 'Controller')
            $hasMouse = ($roles -contains 'Mouse')
            $singleAudio = ($roles.Count -eq 1 -and $roles -contains 'Audio')
            $singleKeyboard = ($roles.Count -eq 1 -and $roles -contains 'Keyboard')
            $hasOnlyAudioRole = ($roles.Count -eq 1 -and $roles -contains 'Audio')
            $hasAudio = ($roles -contains 'Audio')
            $isMixedAudioRole = ($hasAudio -and $roles.Count -gt 1)
            if ($singleAudio -or $hasOnlyAudioRole) {
                $audioPreferBest = $preferBest
                $ecore = Find-FreeECore -usedCoresRef $usedCoresRef -eCoreIndices $eCoreIndicesParam
                if ($ecore -ne $null) {
                    Reserve-Core $ecore $usedCoresRef $usedSmtSetsRef $null
                    $assignedMapRef.Value[$usb] = @($ecore)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $ecore))
                    Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask) | Out-Null
                    $weakOccupiedCoresRef.Value += @($ecore)
                    return
                } else {
                    if (-not $script:IsDualCCDCpu) {
                        $smtId0 = Get-SmtSetIdForCore -core 0 -smtSets $smtSetsParam
                        Reserve-Core 0 $usedCoresRef $usedSmtSetsRef $smtId0
                        $assignedMapRef.Value[$usb] = @(0)
                        $mask = "{0:X16}" -f ([uint64](1 -shl 0))
                        Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask) | Out-Null
                        $weakOccupiedCoresRef.Value += @([int]0)
                        return
                    }
                }
                $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $audioPreferBest
                if ($f -eq $null) {
                    $preferred = @('Audio','Mouse')
                    $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                    if ($share) { $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true } }
                }
                if ($f -ne $null) {
                    $core = $f.Core
                    if ($f.Shared) { $usedCoresRef.Value[[int]$core] = $true }
                    else { Reserve-Core $core $usedCoresRef $usedSmtSetsRef $f.SmtId }
                    $assignedMapRef.Value[$usb] = @($core)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                    Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask) | Out-Null
                    $weakOccupiedCoresRef.Value += @($core)
                } else {
                    Write-Host "[Exovance/Alternate][USB] WARNING - could not allocate core for single-audio USB $($usb.DisplayName)" -ForegroundColor Yellow
                    $assignedMapRef.Value[$usb] = @()
                }
                return
            }
            $filteredPCoreIndices = $pCoreIndicesParam
            if ($isMixedAudioRole -and -not $script:IsDualCCDCpu) {
                $filteredPCoreIndices = @($pCoreIndicesParam | Where-Object { $_ -ne 0 })
            }
            $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $filteredPCoreIndices -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
            if ($f -eq $null) {
                if (-not $hasMouse -and -not $isControllerRole) {
                    $preferred = @('Audio','Mouse')
                    $share = Find-ShareableCore -preferredSharingPartners $preferred -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -smtSets $smtSetsParam -preferSmt $true -assignedMap $assignedMapRef.Value
                    if ($share) {
                        $rejectShare = $false
                        if ($isMixedAudioRole -and -not $script:IsDualCCDCpu) {
                            if ($share.Core -eq 0 -or -not (Is-PCore $share.Core)) { $rejectShare = $true }
                        }
                        if (-not $rejectShare) { $f = @{ Core = $share.Core; SmtId = $share.SmtId; Shared = $true } }
                    }
                }
            }
            if ($f -ne $null) {
                $core = $f.Core
                if ($f.Shared) { $usedCoresRef.Value[[int]$core] = $true }
                else { Reserve-Core $core $usedCoresRef $usedSmtSetsRef $f.SmtId }
                $assignedMapRef.Value[$usb] = @($core)
                $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $core))
                Set-DeviceAffinity $usb.RegistryPath ("0x" + $mask) | Out-Null
                if ($isControllerRole) { $occupiedCoresRef.Value += @($core) }
                if ($hasMouse) { $occupiedCoresRef.Value += @($core) }
                if ($singleKeyboard) { $weakOccupiedCoresRef.Value += @($core) }
            } else {
                Write-Host "[Exovance/Alternate][USB] WARNING - could not allocate P-core for USB $($usb.DisplayName)" -ForegroundColor Yellow
                $assignedMapRef.Value[$usb] = @()
            }
        }

        function Assign-AudioPCIDeviceSecret($aud, [ref]$usedCoresRef, [ref]$usedSmtSetsRef, $pCoreIndicesParam, $eCoreIndicesParam, $smtSetsParam, [ref]$assignedMapRef, [ref]$weakOccupiedCoresRef, [bool]$preferBest) {
            $ecore = Find-FreeECore -usedCoresRef $usedCoresRef -eCoreIndices $eCoreIndicesParam
            if ($ecore -ne $null) {
                Reserve-Core $ecore $usedCoresRef $usedSmtSetsRef $null
                $assignedMapRef.Value[$aud] = @($ecore)
                $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $ecore))
                Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask) | Out-Null
                $weakOccupiedCoresRef.Value += @($ecore)
            } else {
                if (-not $script:IsDualCCDCpu) {
                    $smtId0 = Get-SmtSetIdForCore -core 0 -smtSets $smtSetsParam
                    Reserve-Core 0 $usedCoresRef $usedSmtSetsRef $smtId0
                    $assignedMapRef.Value[$aud] = @(0)
                    $mask = "{0:X16}" -f ([uint64](1 -shl 0))
                    Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask) | Out-Null
                    $weakOccupiedCoresRef.Value += @([int]0)
                    return
                }
                $f = Find-FreePCoreLocal -usedCoresRef $usedCoresRef -usedSmtRef $usedSmtSetsRef -pCoreIndicesParam $pCoreIndicesParam -smtSetsParam $smtSetsParam -preferBestCPPC $preferBest
                if ($f -ne $null) {
                    Reserve-Core $f.Core $usedCoresRef $usedSmtSetsRef $f.SmtId
                    $assignedMapRef.Value[$aud] = @($f.Core)
                    $mask = "{0:X16}" -f ([uint64]([uint64]1 -shl $f.Core))
                    Set-DeviceAffinity $aud.RegistryPath ("0x" + $mask) | Out-Null
                    $weakOccupiedCoresRef.Value += @($f.Core)
                } else {
                    Write-Host "[Exovance/Alternate][AudioPCI] WARNING - could not assign Audio PCI" -ForegroundColor Yellow
                    $assignedMapRef.Value[$aud] = @()
                }
            }
        }

        if ($script:IsDualCCDCpu) {

            foreach ($gpu in @($gpus)) {
                $pre = Find-GPUCoresSecret -pCoreIndicesParam $pCoreIndices -smtSetsParam $smtSets -htEnabledParam $htEnabled -usedCoresRef ([ref]$usedCores) -usedSmtSetsRef ([ref]$usedSmtSets)
                if ($pre) {
                    $gpuPreReserved[$gpu] = $pre
                    for ($i = 0; $i -lt $pre.Cores.Count; $i++) {
                        $c = [int]$pre.Cores[$i]
                        $sid = if ($pre.SmtIds.Count -gt $i) { $pre.SmtIds[$i] } else { Get-SmtSetIdForCore -core $c -smtSets $smtSets }
                        Reserve-Core $c ([ref]$usedCores) ([ref]$usedSmtSets) $sid
                    }
                }
            }

            $secretDualControllerUsb = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 1 })
            $secretDualMouseUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 2 })
            $secretDualKeyboardUsb   = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 3 })
            $secretDualAudioUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 5 })
            $secretDualOtherUsb      = @($usbs | Where-Object { (Get-DeviceTweakerAutoOptRolePriority $_) -eq 6 })
            $secretDualAudioDevices  = [System.Collections.ArrayList]::new()
            foreach ($usb in $secretDualAudioUsb) { [void]$secretDualAudioDevices.Add($usb) }
            foreach ($aud in $audioPCI) { [void]$secretDualAudioDevices.Add($aud) }

            foreach ($gpu in @($gpus)) {
                Assign-GPUDeviceSecret $gpu ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $smtSets $htEnabled ([ref]$assignedMap) ([ref]$occupiedCores)
            }
            foreach ($usb in $secretDualControllerUsb) {
                Assign-USBDeviceSecret $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($usb in $secretDualMouseUsb) {
                Assign-USBDeviceSecret $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($usb in $secretDualKeyboardUsb) {
                Assign-USBDeviceSecret $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($nic in $nics) {
                Assign-NICDeviceSecret $nic ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $smtSets ([ref]$assignedMap) ([ref]$weakOccupiedCores) -preferBest $true
            }
            foreach ($dev in $secretDualAudioDevices) {
                if ($dev.Category -eq 'USB') {
                    Assign-USBDeviceSecret $dev ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
                } else {
                    Assign-AudioPCIDeviceSecret $dev ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$weakOccupiedCores) -preferBest $true
                }
            }
            foreach ($usb in $secretDualOtherUsb) {
                Assign-USBDeviceSecret $usb ([ref]$usedCores) ([ref]$usedSmtSets) $pCoreIndices $eCoreIndices $smtSets ([ref]$assignedMap) ([ref]$occupiedCores) ([ref]$weakOccupiedCores) -preferBest $true
            }

        }
        else {

            $secretECoreIndices = @($eCoreIndices)
            $secretECoreIndices = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $secretECoreIndices)

            $secretGroupDeviceCandidates = [System.Collections.ArrayList]::new()
            foreach ($usb in $usbs) {
                if ($assignedMap.ContainsKey($usb)) { continue }
                [void]$secretGroupDeviceCandidates.Add($usb)
            }
            foreach ($nic in $nics) { [void]$secretGroupDeviceCandidates.Add($nic) }
            foreach ($aud in $audioPCI) {
                if (-not $assignedMap.ContainsKey($aud)) { [void]$secretGroupDeviceCandidates.Add($aud) }
            }
            $secretGroupDevices = @(ConvertTo-DeviceTweakerFastSortedAutoOptDevices $secretGroupDeviceCandidates)

            Write-Host "  SECRET-GROUP DEVICES" -ForegroundColor White
            Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
            foreach ($sd in $secretGroupDevices) {
                Write-Host ("  - {0}" -f $sd.DisplayName)
            }
            Write-Host ""

            $secretGroupCore = $null
            $secretGroupSmtId = $null

            $physUnits = [System.Collections.ArrayList]::new()
            if ($htEnabled -and $smtSets.Count -gt 0) {
                foreach ($s in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $smtSets 'Id')) {
                    $rating = 0
                    if ($script:cppcEnabled) {
                        foreach ($c in $s.Cores) {
                            $r = if ($script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { 0 }
                            if ($r -gt $rating) { $rating = $r }
                        }
                    }
                    [void]$physUnits.Add(@{
                        Id          = $s.Id
                        Cores       = @($s.Cores)
                        Rating      = $rating
                        PrimaryCore = [int]$s.Cores[0]
                        SiblingCore = if ($s.Cores.Count -gt 1) { [int]$s.Cores[1] } else { $null }
                    })
                }
            } else {
                foreach ($c in @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $pCoreIndices)) {
                    $rating = if ($script:cppcEnabled -and $script:cppcRatings.ContainsKey([int]$c)) { $script:cppcRatings[[int]$c] } else { 0 }
                    [void]$physUnits.Add(@{
                        Id          = [int]$c
                        Cores       = @([int]$c)
                        Rating      = $rating
                        PrimaryCore = [int]$c
                        SiblingCore = $null
                    })
                }
            }

            foreach ($unit in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $physUnits 'Id')) {
            }

            $gpuCoreAssignment = @()
            $gpuPreselectedUnitIds = @{}
            $gpuSelectedBeforeSecret = $false
            if ($script:cppcEnabled -and @($gpus).Count -gt 0) {
                $gpuEligibleBeforeSecret = [System.Collections.ArrayList]::new()
                foreach ($unit in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $physUnits 'Id')) {
                    if (@($unit.Cores | Where-Object { [int]$_ -eq 0 }).Count -gt 0) { continue }
                    if ($usedSmtSets.ContainsKey([int]$unit.Id)) { continue }
                    $blocked = $false
                    foreach ($c in @($unit.Cores)) {
                        if ($usedCores.ContainsKey([int]$c)) { $blocked = $true; break }
                    }
                    if (-not $blocked) { [void]$gpuEligibleBeforeSecret.Add($unit) }
                }
                $gpuEligibleBeforeSecret = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $gpuEligibleBeforeSecret 'Id')
                $gpuPairsBeforeSecret = [System.Collections.ArrayList]::new()
                for ($i = 0; $i -lt ($gpuEligibleBeforeSecret.Count - 1); $i++) {
                    $u1 = $gpuEligibleBeforeSecret[$i]
                    $u2 = $gpuEligibleBeforeSecret[$i + 1]
                    if (([int]$u2.Id - [int]$u1.Id) -ne 1) { continue }
                    [void]$gpuPairsBeforeSecret.Add(@{ Unit1 = $u1; Unit2 = $u2; CombinedRating = ([int]$u1.Rating + [int]$u2.Rating) })
                }
                if ($gpuPairsBeforeSecret.Count -gt 0) {
                    $gpuPairBeforeSecret = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $gpuPairsBeforeSecret -Cppc)[0]
                    $gpuCoreAssignment = @([int]$gpuPairBeforeSecret.Unit1.PrimaryCore, [int]$gpuPairBeforeSecret.Unit2.PrimaryCore)
                    $gpuPreselectedUnitIds[[int]$gpuPairBeforeSecret.Unit1.Id] = $true
                    $gpuPreselectedUnitIds[[int]$gpuPairBeforeSecret.Unit2.Id] = $true
                    $gpuSelectedBeforeSecret = $true
                    Write-Host ("[Exovance/Alternate][GPU] CPPC preselected best adjacent GPU cores before Secret-group selection: {0}" -f (Format-SecretDebugList $gpuCoreAssignment)) -ForegroundColor DarkGray
                }
            }





            $secretGroupCoreIsECore = $false
            $secretUnit = $null
            $secretGroupECoreCandidates = @($secretECoreIndices | Where-Object { (-not $usedCores.ContainsKey([int]$_)) -and (-not ($gpuCoreAssignment -contains [int]$_)) })
            if ($hasECores -and $secretGroupECoreCandidates.Count -gt 0) {
                $secretGroupCore = if ($script:cppcEnabled) { [int](Get-BestCoreByCPPC $secretGroupECoreCandidates) } else { [int](@(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $secretGroupECoreCandidates)[0]) }
                $secretGroupSmtId = $null
                $secretGroupCoreIsECore = $true
                Write-Host ("[Exovance/Alternate][ECore] Secret-group core -> best eligible E-core {0}" -f $secretGroupCore) -ForegroundColor DarkGray
            } else {
                $gpuCount = @($gpus).Count
                $TestSecretCandidate = {
                    param($candidate)
                    if ($gpuCount -eq 0 -or $gpuSelectedBeforeSecret) {
                        return $true
                    }


                    $remaining = @($physUnits | Where-Object {
                        ([int]$_.Id -ne [int]$candidate.Id) -and
                        (-not ($_.Cores | Where-Object { [int]$_ -eq 0 }))
                    })
                    $remaining = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $remaining 'Id')

                    if ($remaining.Count -lt 2) {
                        return $false
                    }

                    for ($i = 0; $i -lt $remaining.Count - 1; $i++) {
                        $left = $remaining[$i]
                        $right = $remaining[$i + 1]
                        $gap = [int]$right.Id - [int]$left.Id
                        if ($gap -eq 1) {
                            return $true
                        }
                    }

                    return $false
                }

                $secretCandidateUnits = @($physUnits)
                if ($gpuPreselectedUnitIds.Count -gt 0) {
                    $secretCandidateUnits = @($secretCandidateUnits | Where-Object { -not $gpuPreselectedUnitIds.ContainsKey([int]$_.Id) })
                }
                $secretCandidateUnits = @($secretCandidateUnits | Where-Object {
                    $candidateBlocked = $false
                    if ($usedSmtSets.ContainsKey([int]$_.Id)) { $candidateBlocked = $true }
                    foreach ($candidateCore in @($_.Cores)) {
                        if ($usedCores.ContainsKey([int]$candidateCore) -or ($gpuCoreAssignment -contains [int]$candidateCore)) { $candidateBlocked = $true; break }
                    }
                    -not $candidateBlocked
                })
                if ($secretCandidateUnits.Count -eq 0) {
                    $secretCandidateUnits = if ($gpuPreselectedUnitIds.Count -gt 0) { @($physUnits | Where-Object { -not $gpuPreselectedUnitIds.ContainsKey([int]$_.Id) }) } else { @($physUnits) }
                }

                if ($script:cppcEnabled) {
                    $sortedBest = @(ConvertTo-DeviceTweakerFastSortedByIntProperty (ConvertTo-DeviceTweakerFastSortedByIntProperty $secretCandidateUnits 'Id') 'Rating' -Descending)
                    foreach ($candidate in $sortedBest) {
                        $candidateOk = (& $TestSecretCandidate $candidate)
                        if ($candidateOk) { $secretUnit = $candidate; break }
                    }
                    if (-not $secretUnit -and $sortedBest.Count -gt 0) {
                        $secretUnit = $sortedBest[0]
                    }
                } else {
                    $core0Unit = Get-DeviceTweakerFastFirstWhere $secretCandidateUnits { param($x) @($x.Cores) -contains 0 }
                    if ((-not $script:IsDualCCDCpu) -and (-not $hasECores) -and (-not $script:cppcEnabled) -and $core0Unit) {
                        $secretUnit = $core0Unit
                    } elseif ($core0Unit -and (& $TestSecretCandidate $core0Unit)) {
                        $secretUnit = $core0Unit
                    } else {
                        foreach ($candidate in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $secretCandidateUnits 'Id')) {
                            if (& $TestSecretCandidate $candidate) { $secretUnit = $candidate; break }
                        }
                        if (-not $secretUnit) {
                            $secretUnit = if ($core0Unit) { $core0Unit } elseif ($secretCandidateUnits.Count -gt 0) { $secretCandidateUnits[0] } else { $physUnits[0] }
                        }
                    }
                }

                if ($secretUnit) {
                    $secretGroupCore = [int]$secretUnit.PrimaryCore
                    $secretGroupSmtId = if ($htEnabled) { Get-SmtSetIdForCore -core $secretGroupCore -smtSets $smtSets } else { $null }
                }
            }

            if ($null -ne $secretGroupCore) {
                Reserve-Core $secretGroupCore ([ref]$usedCores) ([ref]$usedSmtSets) $secretGroupSmtId

                $secretMask = "{0:X16}" -f ([uint64]([uint64]1 -shl $secretGroupCore))
                foreach ($sd in $secretGroupDevices) {
                    if (Test-DeviceTweakerStorageDevice $sd) {
                        $assignedMap[$sd] = @()
                        continue
                    }
                    $assignedMap[$sd] = @($secretGroupCore)
                    if ($sd.Category -eq 'Network') {
                        if ($sd.Role -eq 'NDIS') {
                            try {
                                $ndisMode = $script:secretNdisAffinityMode
                                if ($ndisMode -eq 'RSS' -or $ndisMode -eq 'BOTH') {
                                    $null = Set-ExovanceRssConfiguration -RegistryPath $sd.RegistryPath -BaseProcessor $secretGroupCore -QueueCount 1
                                }
                                if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                                    $irqTp = if ($sd.ConfigPath) { $sd.ConfigPath } else { $sd.RegistryPath }
                                    Set-DeviceAffinity $irqTp ("0x" + $secretMask) | Out-Null
                                }
                            } catch { Write-Host "[Exovance/Alternate][NIC] NDIS write fail: $_" -ForegroundColor Yellow }
                        } else {
                            $targetRegistryPath = Get-NetworkAdapterAffinityRegistryPath $sd
                            Set-DeviceAffinity $targetRegistryPath ("0x" + $secretMask) | Out-Null
                        }
                    } else {
                        Set-DeviceAffinity $sd.RegistryPath ("0x" + $secretMask) | Out-Null
                    }
                }
                $occupiedCores += @($secretGroupCore)
                if (-not $usedCores.ContainsKey([int]$secretGroupCore)) {
                    Write-Host ("[Exovance/Alternate][ASSERT] Secret-group core {0} was not present in usedCores immediately after Reserve-Core; forcing reservation." -f [int]$secretGroupCore) -ForegroundColor Red
                    $usedCores[[int]$secretGroupCore] = $true
                }
                if ($null -ne $secretGroupSmtId -and -not $usedSmtSets.ContainsKey([int]$secretGroupSmtId)) {
                    Write-Host ("[Exovance/Alternate][ASSERT] Secret-group SMT set {0} was not present in usedSmtSets immediately after Reserve-Core; forcing reservation." -f [int]$secretGroupSmtId) -ForegroundColor Red
                    $usedSmtSets[[int]$secretGroupSmtId] = $true
                }
            }


            $eligibleGpuUnits = [System.Collections.ArrayList]::new()
            foreach ($unit in @(ConvertTo-DeviceTweakerFastSortedByIntProperty $physUnits 'Id')) {
                $reasons = [System.Collections.ArrayList]::new()
                if (@($unit.Cores | Where-Object { [int]$_ -eq 0 }).Count -gt 0) {
                    Add-SecretReason $reasons 'contains logical core 0, which is excluded from GPU Secret planning'
                }
                if ($null -ne $secretGroupCore -and @($unit.Cores | Where-Object { [int]$_ -eq [int]$secretGroupCore }).Count -gt 0) {
                    Add-SecretReason $reasons ("contains Secret-group logical core {0}" -f [int]$secretGroupCore)
                }
                if ($null -ne $secretGroupSmtId -and [int]$unit.Id -eq [int]$secretGroupSmtId) {
                    Add-SecretReason $reasons ("is the Secret-group SMT set #{0}" -f [int]$secretGroupSmtId)
                }
                if ($usedSmtSets.ContainsKey([int]$unit.Id)) {
                    Add-SecretReason $reasons ("SMT set #{0} already reserved" -f [int]$unit.Id)
                }
                foreach ($c in @($unit.Cores)) {
                    if ($usedCores.ContainsKey([int]$c)) {
                        Add-SecretReason $reasons ("logical core {0} already reserved" -f [int]$c)
                    }
                }
                if ($script:cppcEnabled -and $secretUnit -and [int]$unit.Rating -le [int]$secretUnit.Rating) {
                    Add-SecretReason $reasons ("CPPC rating {0} is not better than Secret-group rating {1}" -f [int]$unit.Rating, [int]$secretUnit.Rating)
                }

                if ($reasons.Count -eq 0) {
                    [void]$eligibleGpuUnits.Add($unit)
                } else {
                }
            }

            $sortedRemaining = @(ConvertTo-DeviceTweakerFastSortedByIntProperty $eligibleGpuUnits 'Id')

            $adjacentPairs = [System.Collections.ArrayList]::new()
            if ($sortedRemaining.Count -lt 2) {
            }
            for ($i = 0; $i -lt $sortedRemaining.Count - 1; $i++) {
                $u1 = $sortedRemaining[$i]
                $u2 = $sortedRemaining[$i + 1]
                $pairReasons = [System.Collections.ArrayList]::new()
                $gap = [int]$u2.Id - [int]$u1.Id
                if ($gap -ne 1) { Add-SecretReason $pairReasons ("not adjacent physical units; id gap={0}" -f $gap) }

                foreach ($u in @($u1, $u2)) {
                    if ($usedSmtSets.ContainsKey([int]$u.Id)) { Add-SecretReason $pairReasons ("Unit#{0} SMT set already reserved" -f [int]$u.Id) }
                    foreach ($c in @($u.Cores)) {
                        if ([int]$c -eq 0) { Add-SecretReason $pairReasons ("Unit#{0} includes core0" -f [int]$u.Id) }
                        if ($null -ne $secretGroupCore -and [int]$c -eq [int]$secretGroupCore) { Add-SecretReason $pairReasons ("Unit#{0} includes Secret-group core {1}" -f [int]$u.Id, [int]$secretGroupCore) }
                        if ($usedCores.ContainsKey([int]$c)) { Add-SecretReason $pairReasons ("Unit#{0} includes reserved logical core {1}" -f [int]$u.Id, [int]$c) }
                    }
                    if ($script:cppcEnabled -and $secretUnit -and [int]$u.Rating -le [int]$secretUnit.Rating) {
                        Add-SecretReason $pairReasons ("Unit#{0} rating {1} is not better than Secret-group rating {2}" -f [int]$u.Id, [int]$u.Rating, [int]$secretUnit.Rating)
                    }
                }

                $combinedRating = [int]$u1.Rating + [int]$u2.Rating
                if ($pairReasons.Count -eq 0) {
                    [void]$adjacentPairs.Add(@{ Unit1 = $u1; Unit2 = $u2; CombinedRating = $combinedRating })
                } else {
                }
            }

            if ($null -eq $gpuCoreAssignment) { $gpuCoreAssignment = @() }
            if ($gpuCoreAssignment.Count -lt 2 -and @($gpus).Count -gt 0 -and $adjacentPairs.Count -gt 0) {
                $gpuPlan = $null
                if ($script:cppcEnabled) {
                    $sortedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $adjacentPairs -Cppc)
                } else {
                    $sortedPairs = @(ConvertTo-DeviceTweakerFastSortedGpuPairs $adjacentPairs)
                }

                foreach ($pair in $sortedPairs) {
                    $pairCores = @([int]$pair.Unit1.PrimaryCore, [int]$pair.Unit2.PrimaryCore)
                    $validationReasons = [System.Collections.ArrayList]::new()
                    foreach ($pc in $pairCores) {
                        if ([int]$pc -eq 0) { Add-SecretReason $validationReasons 'contains logical core 0' }
                        if ($null -ne $secretGroupCore -and [int]$pc -eq [int]$secretGroupCore) { Add-SecretReason $validationReasons ("contains Secret-group core {0}" -f [int]$secretGroupCore) }
                        if ($usedCores.ContainsKey([int]$pc)) { Add-SecretReason $validationReasons ("contains already reserved core {0}" -f [int]$pc) }
                    }
                    foreach ($sid in @([int]$pair.Unit1.Id, [int]$pair.Unit2.Id)) {
                        if ($null -ne $secretGroupSmtId -and [int]$sid -eq [int]$secretGroupSmtId) { Add-SecretReason $validationReasons ("contains Secret-group SMT set {0}" -f [int]$secretGroupSmtId) }
                        if ($usedSmtSets.ContainsKey([int]$sid)) { Add-SecretReason $validationReasons ("contains already reserved SMT set {0}" -f [int]$sid) }
                    }
                    if ($validationReasons.Count -eq 0) {
                        $gpuPlan = $pair
                        break
                    } else {
                    }
                }
                if ($gpuPlan) {
                    $gpuCoreAssignment = @([int]$gpuPlan.Unit1.PrimaryCore, [int]$gpuPlan.Unit2.PrimaryCore)
                }
            } elseif (@($gpus).Count -gt 0) {
            }

            if ($gpuCoreAssignment.Count -ge 2) {
                $finalGpuProblems = [System.Collections.ArrayList]::new()
                foreach ($gc in $gpuCoreAssignment) {
                    if ([int]$gc -eq 0) { Add-SecretReason $finalGpuProblems 'final GPU assignment contains logical core 0' }
                    if ($null -ne $secretGroupCore -and [int]$gc -eq [int]$secretGroupCore) { Add-SecretReason $finalGpuProblems ("final GPU assignment collides with Secret-group core {0}" -f [int]$secretGroupCore) }
                    if ($usedCores.ContainsKey([int]$gc)) { Add-SecretReason $finalGpuProblems ("final GPU assignment collides with already reserved core {0}" -f [int]$gc) }
                    $gcSmt = Get-SmtSetIdForCore -core $gc -smtSets $smtSets
                    if ($null -ne $secretGroupSmtId -and $null -ne $gcSmt -and [int]$gcSmt -eq [int]$secretGroupSmtId) { Add-SecretReason $finalGpuProblems ("final GPU assignment shares Secret-group SMT set {0}" -f [int]$secretGroupSmtId) }
                    if ($null -ne $gcSmt -and $usedSmtSets.ContainsKey([int]$gcSmt)) { Add-SecretReason $finalGpuProblems ("final GPU assignment collides with reserved SMT set {0}" -f [int]$gcSmt) }
                }
                if ($finalGpuProblems.Count -gt 0) {
                    Write-Host ("[Exovance/Alternate][GPU] BLOCKED invalid GPU assignment [{0}]: {1}" -f (Format-SecretDebugList $gpuCoreAssignment), (Format-SecretReasons $finalGpuProblems)) -ForegroundColor Red
                    $gpuCoreAssignment = @()
                } else {
                }
            }

            if (@($gpus).Count -gt 0) {
                if ($gpuCoreAssignment.Count -ge 2) {
                    $preWriteProblems = [System.Collections.ArrayList]::new()
                    foreach ($gc in @($gpuCoreAssignment)) {
                        if ($null -ne $secretGroupCore -and [int]$gc -eq [int]$secretGroupCore) { Add-SecretReason $preWriteProblems ("pre-write collision with Secret-group core {0}" -f [int]$secretGroupCore) }
                        $gcSmtCheck = Get-SmtSetIdForCore -core $gc -smtSets $smtSets
                        if ($null -ne $secretGroupSmtId -and $null -ne $gcSmtCheck -and [int]$gcSmtCheck -eq [int]$secretGroupSmtId) { Add-SecretReason $preWriteProblems ("pre-write collision with Secret-group SMT set {0}" -f [int]$secretGroupSmtId) }
                    }
                    if ($preWriteProblems.Count -gt 0) {
                        Write-Host ("[Exovance/Alternate][GPU][FATAL-BLOCK] Refusing to write invalid GPU cores [{0}]: {1}" -f (Format-SecretDebugList $gpuCoreAssignment), (Format-SecretReasons $preWriteProblems)) -ForegroundColor Red
                        foreach ($gpu in @($gpus)) {
                            $assignedMap[$gpu] = @()
                            $clearGpuOk = Clear-DeviceAffinity $gpu.RegistryPath
                            Write-Host ("[Exovance/Alternate][GPU][CLEAR-AFTER-FATAL] RegistryPath={0} result={1}" -f (Format-RegistryPathForDisplay $gpu.RegistryPath), $clearGpuOk) -ForegroundColor Red
                        }
                    } else {
                    foreach ($gpu in @($gpus)) {
                        $assignedMap[$gpu] = $gpuCoreAssignment
                        $maskInt = [uint64]0
                        foreach ($c in $gpuCoreAssignment) { $maskInt = $maskInt -bor ([uint64]1 -shl $c) }
                        $hexMask = "{0:X16}" -f $maskInt
                        $setGpuOk = Set-DeviceAffinity $gpu.RegistryPath ("0x" + $hexMask)
                        if (-not $setGpuOk) { Write-Host "[Exovance/Alternate][GPU][WRITE] ERROR: Set-DeviceAffinity returned false; registry may still show an old/stale GPU affinity." -ForegroundColor Red }
                        $occupiedCores += $gpuCoreAssignment
                        foreach ($c in $gpuCoreAssignment) {
                            $usedCores[[int]$c] = $true
                            $sid = Get-SmtSetIdForCore -core $c -smtSets $smtSets
                            if ($sid -ne $null) { $usedSmtSets[[int]$sid] = $true }
                        }
                    }
                    }
                } else {
                    Write-Host "[Exovance/Alternate][GPU] WARNING - no valid adjacent GPU pair found; clearing stale GPU affinity so old masks cannot masquerade as new Secret-Opt output." -ForegroundColor Yellow
                    foreach ($gpu in @($gpus)) {
                        $assignedMap[$gpu] = @()
                        $clearGpuOk = Clear-DeviceAffinity $gpu.RegistryPath
                        Write-Host ("[Exovance/Alternate][GPU][CLEAR] RegistryPath={0} result={1}" -f (Format-RegistryPathForDisplay $gpu.RegistryPath), $clearGpuOk) -ForegroundColor Yellow
                    }
                }
            }

        }

        $policyNames = @{
            0 = "MachineDefault"
            1 = "AllCloseProcessors"
            2 = "OneCloseProcessor"
            3 = "AllProcessorsInMachine"
            4 = "SpecifiedProcessors"
            5 = "SpreadMessagesAcrossAllProcessors"
        }

        foreach ($dev in $deviceList) {
            $msiPath = if ($dev.Category -eq "Network") { Get-NetworkAdapterMSIRegistryPath $dev } else { $dev.RegistryPath }
            if ($dev.Category -eq "Network") {
                if ($dev.Role -eq "NDIS") {
                    $ndisMode = $script:secretNdisAffinityMode
                    if ($ndisMode -eq 'IRQ' -or $ndisMode -eq 'BOTH') {
                        $irqPolicyPath = if ($dev.ConfigPath) { $dev.ConfigPath } else { $dev.RegistryPath }
                        Set-DevicePolicy $irqPolicyPath 4 | Out-Null
                    }
                    if ($applyNdisMsi) {
                        Set-DeviceMSI $msiPath 1 "" | Out-Null
                        Set-DevicePriority $msiPath 3 | Out-Null
                    }
                } elseif ($dev.Role -eq "NetAdapterCx") {
                    $policyPath = Get-NetworkAdapterAffinityRegistryPath $dev
                    Set-DevicePolicy $policyPath 4 | Out-Null
                    if ($applyNdisMsi) {
                        $netCxMsiPath = Get-NetworkAdapterMSIRegistryPath $dev
                        Set-DeviceMSI $netCxMsiPath 1 "" | Out-Null
                        Set-DevicePriority $netCxMsiPath 3 | Out-Null
                    }
                }
                continue
            }
            if (Test-DeviceTweakerStorageDevice $dev) {
                Set-DeviceMSI $msiPath 1 "" | Out-Null
                Set-DevicePriority $msiPath 3 | Out-Null
                continue
            }
            Set-DeviceMSI $msiPath 1 "" | Out-Null
            Set-DevicePriority $msiPath 3 | Out-Null
        }

        if (@($gpus).Count -eq 0) {
            $gpuVisibleInDeviceList = @($deviceList | Where-Object { ([string]$_.DisplayName -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)') -or ([string]$_.DeviceDesc -match '(?i)(GPU|NVIDIA|GeForce|RTX|GTX|Radeon|Arc)') })
            if (@($gpuVisibleInDeviceList).Count -gt 0) {
                Write-Host ("[Exovance/Alternate][GPU][FATAL-DISCOVERY] Device-assignment list contains GPU-like device(s), but `$gpus is empty. GPU affinity write would be skipped and stale registry affinity may be printed." ) -ForegroundColor Red
            }
        }

        $deviceResults = [System.Collections.ArrayList]::new()
        $devIndex = 0
        foreach ($dev in $deviceList) {
            $devIndex++
            $assigned = $assignedMap[$dev]
            $assignedCores = if ($assigned -and $assigned.Count -gt 0) { $assigned } else { @() }
            $msiPath = if ($dev.Category -eq "Network") { Get-NetworkAdapterMSIRegistryPath $dev } else { $dev.RegistryPath }
            $msiInfo = Get-CurrentMSI $msiPath
            $affinityPath = $null; $policyPath = $null; $policyValue = $null
            $isNDIS = ($dev.Category -eq "Network" -and $dev.Role -eq "NDIS")
            if ($isNDIS) {
                $ndisLogMode = $script:secretNdisAffinityMode
                $affinityPath = $dev.RegistryPath
                $ndisIrqLogPath = if ($dev.ConfigPath) { $dev.ConfigPath } else { $dev.RegistryPath }
                if ($ndisLogMode -eq 'IRQ' -or $ndisLogMode -eq 'BOTH') {
                    $policyPath = $ndisIrqLogPath; $policyValue = Get-CurrentDevicePolicy $policyPath
                } else { $policyValue = $null }
            } elseif ($dev.Category -eq "Network" -and $dev.Role -eq "NetAdapterCx") {
                $affinityPath = Get-NetworkAdapterAffinityRegistryPath $dev
                $policyPath = $affinityPath; $policyValue = Get-CurrentDevicePolicy $policyPath
            } else {
                $affinityPath = $dev.RegistryPath; $policyPath = $dev.RegistryPath
                $policyValue = Get-CurrentDevicePolicy $policyPath
            }
            $fmtAffinityPath = if ($affinityPath) { Format-RegistryPathForDisplay $affinityPath } else { "(N/A)" }
            $fmtMsiPath = Format-RegistryPathForDisplay $msiPath
            $fmtPolicyPath = if ($policyPath) { Format-RegistryPathForDisplay $policyPath } else { "(N/A)" }
            $affinityRegFull = if ($isNDIS) {
                $ndisLogMode = $script:secretNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') { "$fmtAffinityPath  [*RssBaseProcNumber]" }
                elseif ($ndisLogMode -eq 'IRQ') { $fmtIrqP = Format-RegistryPathForDisplay $ndisIrqLogPath; "$fmtIrqP\Device Parameters\Interrupt Management\Affinity Policy  [AssignmentSetOverride]" }
                else { $fmtIrqP = Format-RegistryPathForDisplay $ndisIrqLogPath; "$fmtAffinityPath  [*RssBaseProcNumber]  +  $fmtIrqP\Device Parameters\Interrupt Management\Affinity Policy  [AssignmentSetOverride]" }
            } else { "$fmtAffinityPath\Device Parameters\Interrupt Management\Affinity Policy" }
            $msiRegFull = "$fmtMsiPath\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
            $policyRegFull = if ($isNDIS) {
                $ndisLogMode = $script:secretNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') { "(NDIS RSS-only: uses *RssBaseProcNumber, no IRQ policy)" }
                elseif ($ndisLogMode -eq 'IRQ') { "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy  [DevicePolicy=4]" }
                else { "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy  [DevicePolicy=4]  (BOTH: RSS + IRQ)" }
            } elseif ($policyPath) { "$fmtPolicyPath\Device Parameters\Interrupt Management\Affinity Policy" } else { "(N/A)" }
            $policyStr = if ($isNDIS) {
                $ndisLogMode = $script:secretNdisAffinityMode
                if ($ndisLogMode -eq 'RSS') { "N/A (NDIS RSS-only: *RssBaseProcNumber)" }
                elseif ($ndisLogMode -eq 'IRQ') { if ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) { "SpecifiedProcessors ($policyValue)  [NDIS IRQ Policy mode]" } else { "SpecifiedProcessors (4)  [NDIS IRQ Policy mode - pending restart]" } }
                else { $irqPart = if ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) { "$($policyNames[[int]$policyValue]) ($policyValue)" } else { "SpecifiedProcessors (4) [pending restart]" }; "$irqPart  [NDIS BOTH: RSS + IRQ Policy]" }
            } elseif ($null -ne $policyValue -and $policyNames.ContainsKey([int]$policyValue)) { "$($policyNames[[int]$policyValue]) ($policyValue)" } elseif ($null -ne $policyValue) { "Unknown ($policyValue)" } else { "Not Set" }
            $affinityStr = if ($isNDIS) {
                $ndisLogMode = $script:secretNdisAffinityMode
                $rssVal = $null
                try { $rssVal = (Get-ItemProperty -Path $dev.RegistryPath -Name "*RssBaseProcNumber" -ErrorAction SilentlyContinue).'*RssBaseProcNumber' } catch {}
                $irqAffStr = $null
                if ($ndisLogMode -eq 'IRQ' -or $ndisLogMode -eq 'BOTH') {
                    $rawAff = Get-CurrentAffinity $ndisIrqLogPath $false; $maskInt64 = [uint64]0
                    try { $maskInt64 = [Convert]::ToUInt64($rawAff.TrimStart('0x'), 16) } catch {}
                    if ($maskInt64 -gt 0) { $coresFromMask = @(); for ($b = 0; $b -lt 64; $b++) { if ($maskInt64 -band ([uint64]1 -shl $b)) { $coresFromMask += $b } }; $irqAffStr = "IRQ: Cores $($coresFromMask -join ', ')  (AssignmentSetOverride=0x$("{0:X16}" -f $maskInt64))" }
                }
                if ($ndisLogMode -eq 'RSS') { if ($null -ne $rssVal) { "Core $rssVal  (*RssBaseProcNumber=$rssVal)" } else { "(not set)" } }
                elseif ($ndisLogMode -eq 'IRQ') { if ($irqAffStr) { $irqAffStr } else { "(IRQ not yet applied - restart required)" } }
                else { $rssPart = if ($null -ne $rssVal) { "RSS: Core $rssVal (*RssBaseProcNumber=$rssVal)" } else { "RSS: (not set)" }; $irqPart = if ($irqAffStr) { $irqAffStr } else { "IRQ: (pending restart)" }; "$rssPart  +  $irqPart" }
            } else {
                $rawAff = Get-CurrentAffinity $affinityPath $false
                $maskInt64 = [uint64]0
                try { $maskInt64 = [Convert]::ToUInt64($rawAff.TrimStart('0x'), 16) } catch {}
                if ($maskInt64 -gt 0) {
                    $coresFromMask = @(); for ($b = 0; $b -lt 64; $b++) { if ($maskInt64 -band ([uint64]1 -shl $b)) { $coresFromMask += $b } }
                    "Cores $($coresFromMask -join ', ')  (mask 0x$("{0:X16}" -f $maskInt64))"
                } else { "(not assigned)" }
            }
            $msiStr = if ([int]$msiInfo.MSIEnabled -eq 1) { "Enabled" } else { "Disabled" }
            $msgLimitStr = if ($msiInfo.MessageLimit -eq "" -or $msiInfo.MessageLimit -eq $null -or ([string]$msiInfo.MessageLimit -eq "0")) { "Unlimited" } else { "$($msiInfo.MessageLimit)" }
            [void]$deviceResults.Add([PSCustomObject]@{
                Index = $devIndex; DisplayLabel = $dev.DisplayName; Category = $dev.Category; Role = $dev.Role
                AffinityStr = $affinityStr; PolicyStr = $policyStr; MsiStr = $msiStr; MsgLimitStr = $msgLimitStr
                AffinityReg = $affinityRegFull; MsiReg = $msiRegFull; PolicyReg = $policyRegFull
            })
        }

        foreach ($usb in $usbs) {
            $assigned = $assignedMap[$usb]
            if (-not $assigned) { continue }
            if ($usb.Roles -contains 'Controller' -or $usb.Roles -contains 'Mouse') {
                $occupiedCores += $assigned
            }
            $norm = Get-AutoOptRoles $usb
            if (($norm.Count -eq 1) -and ($norm -contains 'Audio')) {
                $weakOccupiedCores += $assigned
            }
        }
        foreach ($usb in $usbs) {
            $assigned = $assignedMap[$usb]
            if (-not $assigned) { continue }
            $normRoles = Get-AutoOptRoles $usb
            $hasAudioR = ($normRoles -contains 'Audio')
            $hasKeyboardR = ($normRoles -contains 'Keyboard')
            $otherRoles = $normRoles | Where-Object { $_ -ne 'Audio' -and $_ -ne 'Keyboard' }
            if ($hasAudioR -and $hasKeyboardR -and ($otherRoles.Count -eq 0)) {
                $weakOccupiedCores += $assigned
            }
        }
        foreach ($gpu in @($gpus)) {
            $assigned = $assignedMap[$gpu]
            if ($assigned) { $occupiedCores += $assigned }
        }
        $occupiedCores = Merge-AssignedGpuCoresIntoOccupiedList -GpuDevices $gpus -AssignedMap $assignedMap -CurrentOccupiedCores $occupiedCores
        foreach ($nic in $nics) {
            $assigned = $assignedMap[$nic]
            if ($assigned) { $weakOccupiedCores += $assigned }
        }

        $occupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $occupiedCores)
        $weakOccupiedCores = @(ConvertTo-DeviceTweakerFastSortedUniqueIntArray $weakOccupiedCores)
        $weakOccupiedCores = @($weakOccupiedCores | Where-Object { $occupiedCores -notcontains [int]$_ })

        $scriptDir = $script:cachedScriptDir
        $gamesCfgPath = Join-Path $scriptDir "games_priorities.cfg"
        $systemCfgPath = Join-Path $scriptDir "system_priorities.cfg"

        function Write-ConfigFileEntriesLocal {
            param($path, $coresArr, $weakArr)
            $coresString = ($coresArr -join ',')
            $weakString = ($weakArr -join ',')
            if (-not (Test-Path $path)) { New-Item -Path $path -ItemType File -Force | Out-Null }
            $content = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
            if ($content -match '(?m)^occupied_affinity_cores=.*$') { $content = $content -replace '(?m)^occupied_affinity_cores=.*$', "occupied_affinity_cores=$coresString" } else { $content += "`r`noccupied_affinity_cores=$coresString" }
            if ($content -match '(?m)^occupied_ideal_processor_cores=.*$') { $content = $content -replace '(?m)^occupied_ideal_processor_cores=.*$', "occupied_ideal_processor_cores=$coresString" } else { $content += "`r`noccupied_ideal_processor_cores=$coresString" }
            if ($content -match '(?m)^occupied_weak_affinity_cores=.*$') { $content = $content -replace '(?m)^occupied_weak_affinity_cores=.*$', "occupied_weak_affinity_cores=$weakString" } else { $content += "`r`noccupied_weak_affinity_cores=$weakString" }
            if ($content -match '(?m)^occupied_weak_ideal_processor_cores=.*$') { $content = $content -replace '(?m)^occupied_weak_ideal_processor_cores=.*$', "occupied_weak_ideal_processor_cores=$weakString" } else { $content += "`r`noccupied_weak_ideal_processor_cores=$weakString" }
            $content = Set-PreferredCCDConfigLine -Content $content -PreferredCcd (Get-PreferredCCDForConfig)
            [System.IO.File]::WriteAllText($path, $content.Trim(), [System.Text.UTF8Encoding]::new($false))
        }

        $cfgWriteOk1 = $false; $cfgWriteOk2 = $false
        $cfgSkipped = $false
        $secretExePath = Join-Path $scriptDir "SecretTweak.exe"
        if (-not (Test-Path $secretExePath)) {
            $cfgSkipped = $true
            Write-Host "[Exovance/Alternate] Optional legacy CFG export unavailable - skipped" -ForegroundColor DarkYellow
        } else {
            try { Write-ConfigFileEntriesLocal -path $gamesCfgPath -coresArr $occupiedCores -weakArr $weakOccupiedCores; $cfgWriteOk1 = $true } catch { }
            try { Write-ConfigFileEntriesLocal -path $systemCfgPath -coresArr $occupiedCores -weakArr $weakOccupiedCores; $cfgWriteOk2 = $true } catch { }
        }

        $guiRefreshOk = $false
        try { Refresh-DeviceUI; $guiRefreshOk = $true } catch { }

        Write-Host ""
        Write-Host "  DEVICE ASSIGNMENTS (Secret)" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        $pad1 = 22
        foreach ($r in $deviceResults) {
            Write-Host ""
            Write-Host ("  {0}. {1}" -f $r.Index, $r.DisplayLabel) -ForegroundColor Yellow
            Write-Host ("  {0}{1}" -f ("".PadRight(4)), ("".PadRight(60, '-'))) -ForegroundColor DarkGray
            Write-Host ("      {0} : {1}" -f "Affinity".PadRight($pad1),       $r.AffinityStr)
            Write-Host ("      {0} : {1}" -f "IRQ Policy".PadRight($pad1),     $r.PolicyStr)
            Write-Host ("      {0} : {1}" -f "MSI Mode".PadRight($pad1),       $r.MsiStr)
            Write-Host ("      {0} : {1}" -f "Message Limit".PadRight($pad1),  $r.MsgLimitStr)
            Write-Host ("      {0} :" -f "Registry Paths".PadRight($pad1)) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "Affinity".PadRight($pad1 - 2),   $r.AffinityReg) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "MSI".PadRight($pad1 - 2),        $r.MsiReg) -ForegroundColor DarkGray
            Write-Host ("        {0} : {1}" -f "IRQ Policy".PadRight($pad1 - 2), $r.PolicyReg) -ForegroundColor DarkGray
        }

        Write-Host ""
        Write-Host "  FINAL STATE (Secret)" -ForegroundColor White
        Write-Host ("  " + ('-' * 64)) -ForegroundColor DarkGray
        $occStr  = if ($occupiedCores.Count -gt 0) { $occupiedCores -join ', ' } else { "(none)" }
        $weakStr = if ($weakOccupiedCores.Count -gt 0) { $weakOccupiedCores -join ', ' } else { "(none)" }
        Write-Host ("  Occupied Cores       : {0}" -f $occStr) -ForegroundColor Green
        Write-Host ("  Occupied Weak Cores  : {0}" -f $weakStr) -ForegroundColor Green
        if ($reservedCpuSetsPlan.ShouldApply) {
            $rsFinalCores = if ($reservedCpuSetsPlan.ReservedCores.Count -gt 0) { $reservedCpuSetsPlan.ReservedCores -join ', ' } else { '(none)' }
            if ($reservedCpuSetsResult -and $reservedCpuSetsResult.Success) {
                Write-Host ("  ReservedCpuSets      : Applied [{0}]" -f $rsFinalCores) -ForegroundColor Green
            } elseif ($reservedCpuSetsResult) {
                Write-Host ("  ReservedCpuSets      : FAILED - {0}" -f $reservedCpuSetsResult.Error) -ForegroundColor Red
            }
        } else {
            Write-Host ("  ReservedCpuSets      : Unchanged") -ForegroundColor DarkGray
        }

        $cfg1Status = if ($cfgSkipped) { "Skipped (optional legacy export)" } elseif ($cfgWriteOk1) { "Written" } else { "FAILED" }
        $cfg2Status = if ($cfgSkipped) { "Skipped (optional legacy export)" } elseif ($cfgWriteOk2) { "Written" } else { "FAILED" }
        $cfg1Color  = if ($cfgSkipped) { "DarkYellow" } elseif ($cfgWriteOk1) { "Green" } else { "Red" }
        $cfg2Color  = if ($cfgSkipped) { "DarkYellow" } elseif ($cfgWriteOk2) { "Green" } else { "Red" }
        Write-Host ("  Config: games_priorities.cfg    : {0}" -f $cfg1Status) -ForegroundColor $cfg1Color
        Write-Host ("  Config: system_priorities.cfg   : {0}" -f $cfg2Status) -ForegroundColor $cfg2Color
        $guiStatus = if ($guiRefreshOk) { "Refreshed" } else { "FAILED" }
        $guiColor  = if ($guiRefreshOk) { "Cyan" } else { "Red" }
        Write-Host ("  GUI                  : {0}" -f $guiStatus) -ForegroundColor $guiColor
        Write-Host ""
        Write-Host "  ================================================================" -ForegroundColor DarkMagenta
        Assert-ExovanceWritesSucceeded
        Set-ExovanceUiFeedback -State Applied -Text 'Alternate plan applied - review results'
        Write-Host "    ALTERNATE PLAN COMPLETED SUCCESSFULLY" -ForegroundColor Green
        Write-Host "  ================================================================" -ForegroundColor DarkMagenta
        Write-Host ""

        Show-DarkMessageBox -Message "Alternate plan finished. A system restart may be required." -Title "Alternate Plan" -Icon Information
    }
    catch {
        Write-Host "[Exovance/Alternate] Error: $_" -ForegroundColor Red
        Set-ExovanceUiFeedback -State Error -Text 'Action incomplete - review error details'
        Show-DarkMessageBox -Message "Alternate plan failed: $_" -Title "Error" -Icon Error
    }

    } finally {
        Exit-DeviceTweakerUiAction
    }
})

$_sw_event_wiring.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'Wire-EventHandlers' -Milliseconds $_sw_event_wiring.Elapsed.TotalMilliseconds }

$_sw_scroll_panel = [System.Diagnostics.Stopwatch]::StartNew()
if (-not $script:StartupUiBuildUsedNativeScroll -or $null -eq $script:scrollState) {
    throw [System.InvalidOperationException]::new('Native startup scroll container was not produced by DeviceEditorBuilder.BuildStartupUi; startup reparenting is disabled to avoid handle/layout churn.')
}
try {
    [ScrollHelper]::DisableComposited($panel.Handle)
    $script:scrollState.UpdateLayout()
} catch {
    throw [System.InvalidOperationException]::new(('Native startup scroll activation failed: ' + $_.Exception.Message), $_.Exception)
}
$_sw_scroll_panel.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'Scroll-Panel-Setup' -Milliseconds $_sw_scroll_panel.Elapsed.TotalMilliseconds }

$_sw_cppc_display = [System.Diagnostics.Stopwatch]::StartNew()
$script:cppcTextRank   = $null
$script:cppcTextRating = $null
$script:allCppcAnnotationLabels = $null
$script:allCpuAffinityGrids = $null
$script:allCppcParents    = $null
$script:cppcRefreshPending = $false
$script:cppcRefreshInProgress = $false
$script:cppcLastAppliedShowRatings = $null
$script:cppcAltPollTimer = $null
$script:altMenuFilter = $null

if ($script:cppcEnabled) {
    $logicalCount = $script:cachedLogicalCount
    $script:cppcTextRank   = [string[]]::new($logicalCount)
    $script:cppcTextRating = [string[]]::new($logicalCount)
    for ($i = 0; $i -lt $logicalCount; $i++) {
        if ($script:cppcRanks.ContainsKey($i)) {
            $script:cppcTextRank[$i] = "#$($script:cppcRanks[$i])"
        } else {
            $script:cppcTextRank[$i] = ""
        }
        if ($script:cppcRatings.ContainsKey($i)) {
            $script:cppcTextRating[$i] = "R$($script:cppcRatings[$i])"
        } else {
            $script:cppcTextRating[$i] = ""
        }
    }

    $allLbls = [System.Collections.Generic.List[object]]::new()
    $parentSet = [System.Collections.Generic.HashSet[System.Windows.Forms.Control]]::new()

    foreach ($lbl in $script:deviceCppcLabels) {
        $allLbls.Add($lbl)
        if ($lbl.Parent) { [void]$parentSet.Add($lbl.Parent) }
    }

    if ($script:reservedCppcLabels) {
        foreach ($lbl in $script:reservedCppcLabels) {
            $allLbls.Add($lbl)
            if ($lbl.Parent) { [void]$parentSet.Add($lbl.Parent) }
        }
    }

    $script:allCppcAnnotationLabels = $allLbls.ToArray()
    $script:allCpuAffinityGrids = if ($null -ne $script:deviceCpuAffinityGrids) { $script:deviceCpuAffinityGrids.ToArray() } else { @() }
    $script:allCppcParents    = [System.Windows.Forms.Control[]]@($parentSet)
}

function Refresh-CPPCCheckboxTexts {
    if (-not $script:cppcEnabled -or $null -eq $script:allCppcAnnotationLabels -or $script:cppcRefreshInProgress) { return }

    $script:cppcRefreshInProgress = $true
    try {
        $lookup = if ($script:cppcShowRatings) { $script:cppcTextRating } else { $script:cppcTextRank }
        $changedParents = [System.Collections.Generic.HashSet[System.Windows.Forms.Control]]::new()

        foreach ($p in $script:allCppcParents) {
            if ($p) { $p.SuspendLayout() }
        }

        try {
            foreach ($lbl in $script:allCppcAnnotationLabels) {
                $cpuIndex = [int]$lbl.Tag
                $newText = $lookup[$cpuIndex]
                if ($lbl.Text -ceq $newText) { continue }
                $lbl.Text = $newText
                if ($lbl.Parent) { [void]$changedParents.Add($lbl.Parent) }
            }
            if ($null -ne $script:allCpuAffinityGrids) {
                foreach ($grid in $script:allCpuAffinityGrids) {
                    if ($null -eq $grid -or $grid.IsDisposed) { continue }
                    $grid.Annotations = $lookup
                    [void]$changedParents.Add($grid)
                }
            }
        } finally {
            foreach ($p in $script:allCppcParents) {
                if ($p) { $p.ResumeLayout($false) }
            }
        }

        foreach ($p in $changedParents) {
            $p.Invalidate()
            $p.Update()
        }

        $script:cppcLastAppliedShowRatings = $script:cppcShowRatings
    } finally {
        $script:cppcRefreshInProgress = $false
    }

    if ($script:cppcLastAppliedShowRatings -ne $script:cppcShowRatings) {
        Request-CPPCCheckboxTextRefresh
    }
}

function Request-CPPCCheckboxTextRefresh {
    if (-not $script:cppcEnabled -or $null -eq $script:allCppcAnnotationLabels) { return }
    if ($script:cppcRefreshPending) { return }

    $script:cppcRefreshPending = $true
    try {
        if ($form -and -not $form.IsDisposed -and $form.IsHandleCreated) {
            [void]$form.BeginInvoke([System.Action]{
                $script:cppcRefreshPending = $false
                Refresh-CPPCCheckboxTexts
            })
        } else {
            $script:cppcRefreshPending = $false
            Refresh-CPPCCheckboxTexts
        }
    } catch {
        $script:cppcRefreshPending = $false
        Refresh-CPPCCheckboxTexts
    }
}

function Set-CPPCDisplayMode([bool]$ShowRatings) {
    if (-not $script:cppcEnabled) { return }
    if ($script:cppcShowRatings -eq $ShowRatings -and $script:cppcLastAppliedShowRatings -eq $ShowRatings -and -not $script:cppcRefreshPending) { return }

    $script:cppcShowRatings = $ShowRatings
    Request-CPPCCheckboxTextRefresh
}

if ($script:cppcEnabled) {
    try {
        $script:altMenuFilter = [AltMenuMessageFilter]::new()
        $script:altMenuFilter.TargetHandle = $form.Handle
        [System.Windows.Forms.Application]::AddMessageFilter($script:altMenuFilter)
    } catch {}

    $script:cppcAltPollTimer = [System.Windows.Forms.Timer]::new()
    $script:cppcAltPollTimer.Interval = 1
    $script:cppcAltWasDown = $false
    $script:cppcAltPollTimer.Add_Tick({
        if ($script:uiShuttingDown -or ($form -and $form.IsDisposed)) {
            try { $this.Stop() } catch {}
            try { $this.Dispose() } catch {}
            return
        }

        try {
            $altDown = [UiFastPath]::IsAltDown()
            if ($altDown -ne $script:cppcAltWasDown) {
                $script:cppcAltWasDown = $altDown
                if ($altDown) {
                    Set-CPPCDisplayMode (-not $script:cppcShowRatings)
                }
            }
        } catch [System.Management.Automation.PipelineStoppedException] {
            try { $this.Stop() } catch {}
            try { $this.Dispose() } catch {}
        } catch {}
    })
    $script:cppcAltPollTimer.Start()
}


$form.Add_FormClosing({
    $script:uiShuttingDown = $true
    Stop-DeviceTweakerBackgroundTimers
    try { if ($script:scrollState) { $script:scrollState.StopSmooth(); $script:scrollState.StopDrag() } } catch { throw [System.InvalidOperationException]::new(('Native scroll shutdown failed during FormClosing: ' + $_.Exception.Message), $_.Exception) }
})

$form.Add_FormClosed({
    $script:uiShuttingDown = $true
    Stop-DeviceTweakerBackgroundTimers
    if ($script:scrollState) {
        try { $script:scrollState.Dispose() } catch { throw [System.InvalidOperationException]::new(('Native scroll disposal failed during FormClosed: ' + $_.Exception.Message), $_.Exception) }
        $script:scrollState = $null
    }
    if ($script:cppcAltPollTimer) {
        try { $script:cppcAltPollTimer.Stop() } catch {}
        try { $script:cppcAltPollTimer.Dispose() } catch {}
        $script:cppcAltPollTimer = $null
    }
    if ($script:altMenuFilter) {
        try { [System.Windows.Forms.Application]::RemoveMessageFilter($script:altMenuFilter) } catch {}
        $script:altMenuFilter = $null
    }
})
$_sw_cppc_display.Stop()
if ($script:DebugFunctions) { Add-DeviceTweakerFunctionTiming -Name 'CPPC-Display-Setup' -Milliseconds $_sw_cppc_display.Elapsed.TotalMilliseconds }


function Get-EffectiveUSBInterrupterReadCount {
    param(
        [int]$maxIntrs,
        $interrupterDeviceMap = $null,
        [int]$preferredCount = 0
    )

    if ($maxIntrs -le 0) { return 0 }
    if ($preferredCount -gt 0) { return [Math]::Min($maxIntrs, $preferredCount) }
    if ($null -eq $interrupterDeviceMap -or $interrupterDeviceMap.Count -eq 0) { return $maxIntrs }

    $highestMappedIndex = -1
    foreach ($key in $interrupterDeviceMap.Keys) {
        try {
            $idx = [int]$key
            if ($idx -gt $highestMappedIndex) { $highestMappedIndex = $idx }
        } catch {}
    }

    if ($highestMappedIndex -lt 0) { return $maxIntrs }
    if ($highestMappedIndex -lt 10) { return [Math]::Min($maxIntrs, 10) }
    return [Math]::Min($maxIntrs, ($highestMappedIndex + 1))
}

function Read-ControllerIMOD {
    param(
        $controller,
        $deviceMap,
        $interrupterDeviceMap = $null,
        [int]$preferredCount = 0
    )

    try {
        $runtimeInfo = Get-XHCIControllerRuntimeInfo -controller $controller -deviceMap $deviceMap
    } catch {
        Write-Host ("USB IMOD read skipped: RWEverything could not read controller runtime registers. {0}" -f $_.Exception.Message) -ForegroundColor Yellow
        return $null
    }
    if ($null -eq $runtimeInfo) { return $null }

    $readCount = Get-EffectiveUSBInterrupterReadCount -maxIntrs $runtimeInfo.MaxIntrs -interrupterDeviceMap $interrupterDeviceMap -preferredCount $preferredCount

    $imodValues = [System.Collections.Generic.List[object]]::new()
    $interrupterAddresses = [System.Collections.Generic.List[uint64]]::new()
    for ($i = 0; $i -lt $readCount; $i++) {
        [void]$interrupterAddresses.Add([uint64]($runtimeInfo.RuntimeAddress + 0x24 + (0x20 * $i)))
    }

    if ($interrupterAddresses.Count -gt 1 -and (Get-Command Invoke-RWEReadBatch -ErrorAction SilentlyContinue)) {
        try {
            $batchValues = Invoke-RWEReadBatch -Addresses ([uint64[]]$interrupterAddresses.ToArray()) -Width 32
            for ($i = 0; $i -lt $interrupterAddresses.Count; $i++) {
                $key = ('{0:X16}' -f ([uint64]$interrupterAddresses[$i]))
                if (-not $batchValues.ContainsKey($key)) { throw ('missing batch value for address 0x{0:X}' -f ([uint64]$interrupterAddresses[$i])) }
                [void]$imodValues.Add(([uint64]$batchValues[$key] -band 0xFFFF))
            }
            return $imodValues
        } catch {
            Write-Host ("USB IMOD parallel read failed; falling back to serialized reads: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
            $imodValues.Clear()
        }
    }

    for ($i = 0; $i -lt $readCount; $i++) {
        $interrupterAddress = [uint64]$interrupterAddresses[$i]
        try {
            $value = Get-Value-From-Address -address $interrupterAddress
            [void]$imodValues.Add(($value -band 0xFFFF))
        } catch {
            Write-Host ("USB IMOD read stopped at interrupter {0} / address 0x{1:X}: {2}" -f $i, ([uint64]$interrupterAddress), $_.Exception.Message) -ForegroundColor Yellow
            break
        }
    }
    return $imodValues
}

function Write-ControllerIMOD {
    param($controller, $deviceMap, $newInterval)

    $deviceId = $controller.DeviceID
    if (-not $deviceMap.Contains($deviceId)) { return $false }
    $capabilityAddress = $deviceMap[$deviceId]
    $hcsparamsOffset = $globalHCSPARAMSOffset
    $rtsoff = $globalRTSOFF
    foreach ($hwid in $userDefinedData.Keys) {
        if ($deviceId -match $hwid) {
            $userDefinedController = $userDefinedData[$hwid]
            if ($userDefinedController.ContainsKey("HCSPARAMS_OFFSET")) { $hcsparamsOffset = $userDefinedController["HCSPARAMS_OFFSET"] }
            elseif ($userDefinedController.ContainsKey("HCSPARAPS_OFFSET")) { $hcsparamsOffset = $userDefinedController["HCSPARAPS_OFFSET"] }
            if ($userDefinedController.ContainsKey("RTSOFF")) { $rtsoff = $userDefinedController["RTSOFF"] }
        }
    }

    $HCSPARAMSValue = Get-Value-From-Address -address ($capabilityAddress + $hcsparamsOffset)
    $maxIntrs = ($HCSPARAMSValue -shr 8) -band 0x7FF
    $RTSOFFValue = Get-Value-From-Address -address ($capabilityAddress + $rtsoff)
    $runtimeAddress = $capabilityAddress + $RTSOFFValue

    if ($newInterval -is [hashtable]) {
        if ($newInterval.Count -eq 0) { return $false }
        foreach ($idx in $newInterval.Keys) {
            $i = [int]$idx
            if ($i -lt 0 -or $i -ge $maxIntrs) { continue }
            $interrupterAddress = $runtimeAddress + 0x24 + (0x20 * $i)
            $currentValue = Get-Value-From-Address -address $interrupterAddress
            $preservedIMODC = [uint32]($currentValue -band 0xFFFF0000)
            $targetInterval = [uint32]([uint16]$newInterval[$idx])
            $mergedValue = $preservedIMODC -bor ($targetInterval -band 0xFFFF)
            $hexAddress = Dec-To-Hex -decimal ([uint64]$interrupterAddress)
            $hexValue = "0x$($mergedValue.ToString('X8'))"
            Invoke-RWECommand -Command "W32 $($hexAddress) $($hexValue)" -AllowEmptyOutput | Out-Null
        }
        return $true
    }

    $perInterrupterValues = $null
    $uniformInterval = [uint16]0
    $writeCount = $maxIntrs

    if ($newInterval -is [System.Array] -and -not ($newInterval -is [string])) {
        $perInterrupterValues = @($newInterval | ForEach-Object { [uint16]$_ })
        if ($perInterrupterValues.Count -eq 0 -or $perInterrupterValues.Count -gt $maxIntrs) { return $false }
        $writeCount = $perInterrupterValues.Count
    } else {
        $uniformInterval = [uint16]$newInterval
    }

    for ($i = 0; $i -lt $writeCount; $i++) {
        $interrupterAddress = $runtimeAddress + 0x24 + (0x20 * $i)
        $currentValue = Get-Value-From-Address -address $interrupterAddress
        $preservedIMODC = [uint32]($currentValue -band 0xFFFF0000)
        $targetInterval = if ($null -ne $perInterrupterValues) { [uint32]$perInterrupterValues[$i] } else { [uint32]$uniformInterval }
        $mergedValue = $preservedIMODC -bor ($targetInterval -band 0xFFFF)
        $hexAddress = Dec-To-Hex -decimal ([uint64]$interrupterAddress)
        $hexValue = "0x$($mergedValue.ToString('X8'))"
        Invoke-RWECommand -Command "W32 $($hexAddress) $($hexValue)" -AllowEmptyOutput | Out-Null
    }
    return $true
}

function Get-FunctionDefinitionText {
    param([string]$Name)
    $fn = Get-Item -Path ("function:{0}" -f $Name) -ErrorAction Stop
    return "function {0} {{`r`n{1}`r`n}}" -f $Name, $fn.ScriptBlock.ToString()
}

function New-USBIMODStartupScriptContent {
    param([hashtable]$ImodSettings)

    $sb = [System.Text.StringBuilder]::new()
    $sb.Append(@'
$globalInterval = 0x0
$globalHCSPARAMSOffset = 0x4
$globalRTSOFF = 0x18
$userDefinedData = @{
'@) | Out-Null

    foreach ($key in $ImodSettings.Keys) {
        $parsedUsbSetting = $ImodSettings[$key]
        $sb.Append("    `"$key`" = @{`r`n") | Out-Null
        if ($null -ne $parsedUsbSetting.PerInterrupterValues -and $parsedUsbSetting.PerInterrupterValues.Count -gt 0) {
            $vectorValues = [System.Collections.Generic.List[string]]::new()
            foreach ($_intervalValue in @($parsedUsbSetting.PerInterrupterValues)) { [void]$vectorValues.Add((Format-USBIMODValueHex -value ([uint16]$_intervalValue))) }
            $vectorText = ($vectorValues.ToArray() -join ', ')
            $sb.Append("        `"INTERVALS`" = @($vectorText)`r`n") | Out-Null
        } else {
            $sb.Append("        `"INTERVAL`" = $(Format-USBIMODValueHex -value ([uint16]$parsedUsbSetting.UniformValue))`r`n") | Out-Null
        }
        $sb.Append("    }`r`n") | Out-Null
    }

    $sb.AppendLine('}') | Out-Null
    $sb.AppendLine('$rwePath = "C:\Program Files (x86)\RW-Everything\Rw.exe"') | Out-Null
    $sb.AppendLine('$script:RWEPreflightResult = $null') | Out-Null
    $sb.AppendLine('$script:RWECommandTimeoutMs = 30000') | Out-Null
    $sb.AppendLine() | Out-Null

    foreach ($fnName in @(
        'Dec-To-Hex',
        'Convert-RWEverythingOutputToUInt64',
        'Resolve-RWEPath',
        'Get-DeviceTweakerDriverBlockDiagnostics',
        'Test-DeviceTweakerRWEnNVMeDisabled',
        'Initialize-DeviceTweakerRWEverything',
        'Invoke-RWECommand',
        'Get-Value-From-Address',
        'Read-Value64FromAddress',
        'Get-XHCIControllerRuntimeInfo',
        'Get-XHCIPortRegisterAddress',
        'Get-XHCISupportedProtocolPortRanges',
        'Get-XHCIPortProtocolLookup',
        'Resolve-XHCIUSB3TimeoutByte',
        'Set-XHCILinkPowerManagement',
        'Get-Device-Addresses',
        'Is-Admin',
        'Write-ControllerIMOD'
    )) {
        $sb.AppendLine((Get-FunctionDefinitionText $fnName)) | Out-Null
        $sb.AppendLine() | Out-Null
    }

    $sb.Append(@'
function main {
    if (-not (Is-Admin)) {
        Write-Host "error: administrator privileges required"
        return 1
    }
    $rwePath = Resolve-RWEPath -Path $rwePath
    if (-not (Test-Path -LiteralPath $rwePath -PathType Leaf)) {
        Write-Host "error: $($rwePath) not exists, edit the script to change the path to Rw.exe"
        Write-Host "http://rweverything.com/download"
        return 1
    }
    Stop-Process -Name "Rw" -ErrorAction SilentlyContinue
    $rweReady = Initialize-DeviceTweakerRWEverything -Path $rwePath
    if (-not $rweReady.Ready) {
        Write-Host "error: $($rweReady.Message)"
        if ($rweReady.Diagnostics) { Write-Host $rweReady.Diagnostics }
        return 1
    }
    $deviceMap = Get-Device-Addresses
    foreach ($xhciController in Get-WmiObject Win32_USBController) {
        $isDisabled = $xhciController.ConfigManagerErrorCode -eq 22
        if ($isDisabled) { continue }
        $deviceId = $xhciController.DeviceID
        Write-Host "$($xhciController.Caption) - $($deviceId)"
        if (-not $deviceMap.Contains($deviceId)) {
            Write-Host "error: could not obtain base address`n"
            continue
        }

        $newIntervalArg = $globalInterval
        foreach ($hwid in $userDefinedData.Keys) {
            if ($deviceId -match $hwid) {
                $userDefinedController = $userDefinedData[$hwid]
                if ($userDefinedController.ContainsKey("INTERVAL")) {
                    $newIntervalArg = $userDefinedController["INTERVAL"]
                }
                if ($userDefinedController.ContainsKey("INTERVALS")) {
                    $newIntervalArg = @($userDefinedController["INTERVALS"])
                }
            }
        }

        if (-not (Write-ControllerIMOD -controller $xhciController -deviceMap $deviceMap -newInterval $newIntervalArg)) {
            if ($newIntervalArg -is [System.Array] -and -not ($newIntervalArg -is [string])) {
                Write-Host "error: failed to apply saved INTERVALS for $deviceId`n"
            } else {
                Write-Host "error: failed to apply saved INTERVAL for $deviceId`n"
            }
            continue
        }
        try {
            $lpmResult = Set-XHCILinkPowerManagement -controller $xhciController -deviceMap $deviceMap -EnableU1:$false -EnableU2:$false -Mode 'RejectAll'
            Write-Host ("  USB3 U1/U2 LPM: Changed={0}; Ports={1}" -f $lpmResult.ChangedCount, $lpmResult.Records.Count)
        } catch {
            Write-Host ("error: failed to apply USB3 U1/U2 LPM for ${deviceId}: {0}`n" -f $_.Exception.Message)
            continue
        }

        Write-Host
    }
    return 0
}
$_exitCode = main
exit $_exitCode
'@) | Out-Null

    return $sb.ToString()
}

