function Get-Hex4AfterToken {
    param([string]$Text, [string]$Token)
    if ([string]::IsNullOrWhiteSpace($Text) -or [string]::IsNullOrWhiteSpace($Token)) { return $null }
    $upper = $Text.ToUpperInvariant()
    $tokenUpper = $Token.ToUpperInvariant()
    $idx = $upper.IndexOf($tokenUpper, [System.StringComparison]::Ordinal)
    while ($idx -ge 0) {
        $start = $idx + $tokenUpper.Length
        if ($start + 4 -le $upper.Length) {
            $candidate = $upper.Substring($start, 4)
            $ok = $true
            for ($i = 0; $i -lt 4; $i++) {
                $c = $candidate[$i]
                if (-not (($c -ge '0' -and $c -le '9') -or ($c -ge 'A' -and $c -le 'F'))) { $ok = $false; break }
            }
            if ($ok) { return $candidate }
        }
        $next = $idx + 1
        if ($next -ge $upper.Length) { break }
        $idx = $upper.IndexOf($tokenUpper, $next, [System.StringComparison]::Ordinal)
    }
    return $null
}

function Get-UsbVidPidColonKey {
    param([string]$Text)
    $vid = Get-Hex4AfterToken -Text $Text -Token 'VID_'
    if (-not $vid) { return $null }
    $pid = Get-Hex4AfterToken -Text $Text -Token 'PID_'
    if (-not $pid) { return $null }
    return "$vid`:$pid"
}

function Test-UsbVidPidColonKeyInText {
    param([string]$Text, [string]$ColonKey)
    if ([string]::IsNullOrWhiteSpace($Text) -or [string]::IsNullOrWhiteSpace($ColonKey)) { return $false }
    $actual = Get-UsbVidPidColonKey -Text $Text
    if ($actual) { return [string]::Equals($actual, $ColonKey, [System.StringComparison]::OrdinalIgnoreCase) }
    $parts = $ColonKey.Split(':')
    if ($parts.Count -ne 2) { return $false }
    return ($Text.IndexOf("VID_$($parts[0])", [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $Text.IndexOf("PID_$($parts[1])", [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Get-UsbRootPortFromLocationPath {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return -1 }
    $root = $Text.IndexOf('USBROOT(', [System.StringComparison]::OrdinalIgnoreCase)
    if ($root -lt 0) { return -1 }
    $marker = $Text.IndexOf(')#USB(', $root + 8, [System.StringComparison]::OrdinalIgnoreCase)
    if ($marker -lt 0) { return -1 }
    $start = $marker + 6
    $i = $start
    while ($i -lt $Text.Length -and [char]::IsDigit($Text[$i])) { $i++ }
    if ($i -eq $start -or $i -ge $Text.Length -or $Text[$i] -ne ')') { return -1 }
    $value = 0
    if ([int]::TryParse($Text.Substring($start, $i - $start), [ref]$value)) { return $value }
    return -1
}

function Get-UsbRootPortFromLocationInfo {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return -1 }
    $prefix = 'Port_#'
    $start = $Text.IndexOf($prefix, [System.StringComparison]::OrdinalIgnoreCase)
    while ($start -ge 0) {
        $digitStart = $start + $prefix.Length
        $i = $digitStart
        while ($i -lt $Text.Length -and [char]::IsDigit($Text[$i])) { $i++ }
        if ($i -gt $digitStart -and $i + 10 -le $Text.Length -and [string]::Compare($Text, $i, '.Hub_#0001', 0, 10, $true) -eq 0) {
            $value = 0
            if ([int]::TryParse($Text.Substring($digitStart, $i - $digitStart), [ref]$value)) { return $value }
        }
        $next = $start + 1
        if ($next -ge $Text.Length) { break }
        $start = $Text.IndexOf($prefix, $next, [System.StringComparison]::OrdinalIgnoreCase)
    }
    return -1
}

'@) | Out-Null

    $sb.AppendLine('$secretModeData = @{') | Out-Null
