function Format-DeviceTweakerErrorRecordForUi {
    param([AllowNull()][object]$ErrorRecord)
    if ($null -eq $ErrorRecord) { return '' }
    $parts = [System.Collections.Generic.List[string]]::new()
    try {
        $ex = $ErrorRecord.Exception
        $depth = 0
        while ($null -ne $ex -and $depth -lt 8) {
            $msg = ([string]$ex.Message).Trim()
            if ($msg.Length -gt 0) { [void]$parts.Add(('{0}: {1}' -f $ex.GetType().FullName, $msg)) }
            else { [void]$parts.Add($ex.GetType().FullName) }
            $ex = $ex.InnerException
            $depth++
        }
    } catch { }
    try {
        if ($ErrorRecord.InvocationInfo -and -not [string]::IsNullOrWhiteSpace([string]$ErrorRecord.InvocationInfo.PositionMessage)) {
            [void]$parts.Add(('At: {0}' -f ([string]$ErrorRecord.InvocationInfo.PositionMessage).Trim()))
        }
    } catch { }
    if ($parts.Count -eq 0) {
        try { return ([string]$ErrorRecord).Trim() } catch { return '' }
    }
    return ($parts.ToArray() -join ' <- ')
}

function Expand-DeviceTweakerResultItems {
    param([AllowNull()][object]$ResultItems)
    $flat = [System.Collections.Generic.List[object]]::new()
    foreach ($item in @($ResultItems)) {
        if ($null -eq $item) { continue }
        $hasKey = $false
        try { $hasKey = ($null -ne $item.PSObject.Properties['Key']) } catch { $hasKey = $false }
        if (-not $hasKey -and -not ($item -is [string]) -and ($item -is [System.Collections.IEnumerable])) {
            foreach ($sub in $item) { if ($null -ne $sub) { [void]$flat.Add($sub) } }
        } else {
            [void]$flat.Add($item)
        }
    }
    return $flat.ToArray()
}

