function Test-NVMeVolatileWriteCacheUnsupportedError {
    param([AllowNull()][string]$Message)
    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }
    $notUnsupportedPatterns = @(
        '(?i)No\s+PhysicalDrive\s+path',
        '(?i)drive\s+path\s+is\s+empty',
        '(?i)Access\s+is\s+denied',
        '(?i)UnauthorizedAccess',
        '(?i)system\s+cannot\s+find\s+the\s+file',
        '(?i)win32=5\s*\('
    )
    foreach ($pattern in $notUnsupportedPatterns) {
        if ($Message -match $pattern) { return $false }
    }

    $vwcContext = ($Message -match '(?i)(NVMe\s+VWC|Volatile\s+Write\s+Cache|VWC\.Present|NVME_FEATURE_VOLATILE_WRITE_CACHE|Feature\s+ID\s+0x06|feature=0x06|FID=0x06)')
    if (-not $vwcContext) { return $false }
    if (Test-NVMeInterruptCoalescingSetUnsupportedError -Message $Message) { return $true }

    $storagePropertyAttemptPatterns = @(
        '(?i)NVMe\s+volatile\s+write\s+cache\s+read\s+failed',
        '(?i)NVMe\s+volatile\s+write\s+cache\s+set\s+failed',
        '(?i)NVMe\s+VWC\s+Get\s+Features\s+failed',
        '(?i)NVMe\s+VWC\s+Set\s+Features\s+failed',
        '(?i)NVMe\s+Get\s+Features\s+failed.*Feature\s+ID\s+0x06',
        '(?i)NVMe\s+Set\s+Features\s+failed.*Feature\s+ID\s+0x06',
        '(?i)ioctl=Get',
        '(?i)ioctl=Set',
        '(?i)IOCTL_STORAGE_QUERY_PROPERTY',
        '(?i)IOCTL_STORAGE_SET_PROPERTY'
    )
    $rejectedAsUnsupportedPatterns = @(
        '(?i)VWC\.Present=0',
        '(?i)returnStatus=0x00000002\s*\(ERROR\)',
        '(?i)returnStatus=0x00000003\s*\(INVALID_REQUEST\)',
        '(?i)returnStatus=0x000000FF\s*\(NOT_SUPPORTED\)',
        '(?i)protocolError=0x[0-9A-F]+',
        '(?i)Invalid\s+Field\s+in\s+Command',
        '(?i)INVALID_FIELD_IN_COMMAND',
        '(?i)Incorrect\s+function',
        '(?i)ERROR_INVALID_FUNCTION',
        '(?i)The\s+request\s+is\s+not\s+supported',
        '(?i)not\s+supported',
        '(?i)unsupported',
        '(?i)invalid\s+request',
        '(?i)win32=1\s*\(',
        '(?i)win32=50\s*\('
    )
    $storagePropertyAttempt = $false
    foreach ($pattern in $storagePropertyAttemptPatterns) {
        if ($Message -match $pattern) { $storagePropertyAttempt = $true; break }
    }
    if (-not $storagePropertyAttempt -and ($Message -match '(?i)VWC\.Present=0')) { $storagePropertyAttempt = $true }
    if (-not $storagePropertyAttempt) { return $false }
    foreach ($pattern in $rejectedAsUnsupportedPatterns) {
        if ($Message -match $pattern) { return $true }
    }
    return $false
}

