function Format-NVMeTemperatureThresholdUnsupportedLabel {
    param([int]$SensorSelect = -1, [int]$ThresholdType = -1)
    $suffix = ''
    if ($SensorSelect -ge 0) { $suffix += (' | TMPSEL={0}' -f [int]$SensorSelect) }
    if ($ThresholdType -ge 0) { $suffix += (' | THSEL={0}' -f [int]$ThresholdType) }
    return ('TEMP Unsupported | FID=0x04{0}' -f $suffix)
}

function New-NVMeTemperatureThresholdUnsupportedObject {
