        [Parameter(Mandatory=$true)][string]$DrivePath,
        [int]$SensorSelect = 0,
        [int]$ThresholdType = 0
    )
    $sensorText = if ([int]$SensorSelect -eq 0) { 'Composite' } else { ('Sensor {0}' -f [int]$SensorSelect) }
    $thresholdTypeText = if ([int]$ThresholdType -eq 0) { 'Over' } else { 'Under' }
    [PSCustomObject]@{
        DrivePath           = [string]$DrivePath
        Supported           = $false
        RawValue            = [uint32]0
        SensorSelect        = [int]$SensorSelect
        ThresholdType       = [int]$ThresholdType
        ThresholdKelvin     = 0
        ThresholdCelsius    = -273
        SensorText          = [string]$sensorText
        ThresholdTypeText   = [string]$thresholdTypeText
        Scope               = 'Unsupported'
        DisplayText         = (Format-NVMeTemperatureThresholdUnsupportedLabel -SensorSelect $SensorSelect -ThresholdType $ThresholdType)
    }
}

