    $notUnsupportedPatterns = @(
        '(?i)No\s+PhysicalDrive\s+path',
        '(?i)drive\s+path\s+is\s+empty',
        '(?i)Access\s+is\s+denied',
        '(?i)UnauthorizedAccess',
        '(?i)system\s+cannot\s+find\s+the\s+file',
        '(?i)win32=5\s*\('
    )
    foreach ($pattern in $notUnsupportedPatterns) {
        if ($Message -match $pattern) { return $false }
    }
    $hctmContext = ($Message -match '(?i)(HCTM|Host[-\s]+Controlled[-\s]+Thermal[-\s]+Management|Feature\s+ID\s+0x10|feature=0x10|FID=0x10)')
    if (-not $hctmContext) { return $false }
    if (Test-NVMeInterruptCoalescingSetUnsupportedError -Message $Message) { return $true }

    $unsupportedPatterns = @(
        '(?i)NVMe\s+HCTM\s+read\s+failed',
        '(?i)NVMe\s+HCTM\s+set\s+failed',
        '(?i)NVMe\s+Get\s+Features\s+failed.*Feature\s+ID\s+0x10',
        '(?i)NVMe\s+Set\s+Features\s+failed.*Feature\s+ID\s+0x10',
        '(?i)ioctl=Get',
        '(?i)ioctl=Set',
        '(?i)IOCTL_STORAGE_QUERY_PROPERTY',
        '(?i)IOCTL_STORAGE_SET_PROPERTY',
        '(?i)returnStatus=0x00000003\s*\(INVALID_REQUEST\)',
        '(?i)returnStatus=0x000000FF\s*\(NOT_SUPPORTED\)',
        '(?i)Incorrect\s+function',
        '(?i)ERROR_INVALID_FUNCTION',
        '(?i)The\s+request\s+is\s+not\s+supported',
        '(?i)not\s+supported',
        '(?i)win32=1\s*\(',
        '(?i)win32=50\s*\('
    )
    foreach ($pattern in $unsupportedPatterns) {
        if ($Message -match $pattern) { return $true }
    }
    return $false
}

function Format-NVMeHostControlledThermalManagementUnsupportedLabel {
    param(
        [int]$MinimumTemperatureKelvin = 0,
        [int]$MaximumTemperatureKelvin = 0,
        [uint16]$Attributes = [uint16]0
    )
    return ('HCTM Unsupported | FID=0x10 | HCTMA=0x{0:X4} | MNTMT={1}K | MXTMT={2}K' -f [uint16]$Attributes, [int]$MinimumTemperatureKelvin, [int]$MaximumTemperatureKelvin)
}


function Test-NVMeArbitrationUnsupportedError {
    param([AllowNull()][string]$Message)
    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }
    $notUnsupportedPatterns = @(
        '(?i)No\s+PhysicalDrive\s+path',
        '(?i)drive\s+path\s+is\s+empty',
        '(?i)Access\s+is\s+denied',
        '(?i)UnauthorizedAccess',
        '(?i)system\s+cannot\s+find\s+the\s+file',
        '(?i)win32=5\s*\('
    )
    foreach ($pattern in $notUnsupportedPatterns) { if ($Message -match $pattern) { return $false } }
    $context = ($Message -match '(?i)(NVMe\s+ARB|NVMe\s+Arbitration|Arbitration|Feature\s+ID\s+0x01|feature=0x01|FID=0x01)')
    if (-not $context) { return $false }
    if (Test-NVMeInterruptCoalescingSetUnsupportedError -Message $Message) { return $true }
    $unsupportedPatterns = @(
        '(?i)NVMe\s+Arbitration\s+read\s+failed',
        '(?i)NVMe\s+Arbitration\s+set\s+failed',
        '(?i)NVMe\s+Get\s+Features\s+failed.*Feature\s+ID\s+0x01',
        '(?i)NVMe\s+Set\s+Features\s+failed.*Feature\s+ID\s+0x01',
        '(?i)IOCTL_STORAGE_QUERY_PROPERTY',
        '(?i)IOCTL_STORAGE_SET_PROPERTY',
        '(?i)returnStatus=0x00000003\s*\(INVALID_REQUEST\)',
        '(?i)returnStatus=0x000000FF\s*\(NOT_SUPPORTED\)',
        '(?i)Incorrect\s+function',
        '(?i)ERROR_INVALID_FUNCTION',
        '(?i)The\s+request\s+is\s+not\s+supported',
        '(?i)not\s+supported',
        '(?i)unsupported',
        '(?i)win32=1\s*\(',
        '(?i)win32=50\s*\('
    )
    foreach ($pattern in $unsupportedPatterns) { if ($Message -match $pattern) { return $true } }
    return $false
}

function Format-NVMeArbitrationUnsupportedLabel { return 'ARB Unsupported | FID=0x01' }

