function Get-NVMeArbitration {
    param([Parameter(Mandatory=$true)][string]$DrivePath)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        return (ConvertTo-NVMeArbitrationObject -State ([DeviceTweakerNvmeProtocol]::GetArbitration($DrivePath)))
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeArbitrationUnsupportedError -Message $detail) { return (New-NVMeArbitrationUnsupportedObject -DrivePath $DrivePath) }
        throw [System.InvalidOperationException]::new(('NVMe Arbitration read failed for {0}: {1}' -f $DrivePath, $_.Exception.Message), $_.Exception)
    }
}

function Set-NVMeArbitration {
    param(
        [Parameter(Mandatory=$true)][string]$DrivePath,
        [Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$ArbitrationBurst,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$LowPriorityWeight,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$MediumPriorityWeight,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$HighPriorityWeight
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        return (ConvertTo-NVMeArbitrationObject -State ([DeviceTweakerNvmeProtocol]::SetArbitration($DrivePath, [int]$ArbitrationBurst, [int]$LowPriorityWeight, [int]$MediumPriorityWeight, [int]$HighPriorityWeight)))
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeArbitrationUnsupportedError -Message $detail) { throw [System.NotSupportedException]::new(('NVMe Arbitration unsupported for {0}; Set Features FID=0x01 was rejected by Windows StorNVMe/firmware. {1}' -f $DrivePath, $detail), $_.Exception) }
        throw [System.InvalidOperationException]::new(('NVMe Arbitration set failed for {0} AB={1} LPW={2} MPW={3} HPW={4}: {5}' -f $DrivePath, $ArbitrationBurst, $LowPriorityWeight, $MediumPriorityWeight, $HighPriorityWeight, $_.Exception.Message), $_.Exception)
    }
}

function Test-NVMeNumberOfQueuesLifecycleError {
    param([AllowNull()][string]$Message)
    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }
    $context = ($Message -match '(?i)(NVMe\s+NOQ|Number\s+of\s+Queues|Feature\s+ID\s+0x07|feature=0x07|FID=0x07)')
    if (-not $context) { return $false }
    return ($Message -match '(?i)Command\s+Sequence\s+Error|CommandSequenceError|Feature\s+Not\s+Changeable|FeatureNotChangeable|nvmeStatusFlat=Generic:0x0C|nvmeStatusShifted=Generic:0x0C|nvmeStatusFlat=CommandSpecific:0x0E|nvmeStatusShifted=CommandSpecific:0x0E')
}

function Test-NVMeNumberOfQueuesUnsupportedError {
    param([AllowNull()][string]$Message)
    if ([string]::IsNullOrWhiteSpace($Message)) { return $false }

    $context = ($Message -match '(?i)(NVMe\s+NOQ|Number\s+of\s+Queues|num-queues|Feature\s+ID\s+0x07|feature=0x07|FID=0x07)')
    if (-not $context) { return $false }
    if (Test-NVMeNumberOfQueuesLifecycleError -Message $Message) { return $false }

    $explicitUnsupportedPatterns = @(
        '(?i)returnStatus=0x000000FF\s*\(NOT_SUPPORTED\)',
        '(?i)returnStatus=0x00000003\s*\(INVALID_REQUEST\)',
        '(?i)\(NOT_SUPPORTED\)',
        '(?i)\bNOT_SUPPORTED\b',
        '(?i)\(INVALID_REQUEST\)',
        '(?i)\bINVALID_REQUEST\b',
        '(?i)Incorrect\s+function',
        '(?i)ERROR_INVALID_FUNCTION',
        '(?i)INVALID_FUNCTION',
        '(?i)The\s+request\s+is\s+not\s+supported',
        '(?i)\brequest\s+is\s+not\s+supported\b',
        '(?i)win32=1\s*\(',
        '(?i)win32=50\s*\('
    )
    foreach ($pattern in $explicitUnsupportedPatterns) { if ($Message -match $pattern) { return $true } }

    $notUnsupportedPatterns = @(
        '(?i)No\s+PhysicalDrive\s+path',
        '(?i)drive\s+path\s+is\s+empty',
        '(?i)Access\s+is\s+denied',
        '(?i)UnauthorizedAccess',
        '(?i)system\s+cannot\s+find\s+the\s+file',
        '(?i)win32=5\s*\('
    )
    foreach ($pattern in $notUnsupportedPatterns) { if ($Message -match $pattern) { return $false } }

    $genuineUnsupportedPatterns = @(
        '(?i)System\.NotSupportedException',
        '(?i)\bNotSupportedException\b',
        '(?i)returnStatus=0x000000FF\s*\(NOT_SUPPORTED\)',
        '(?i)returnStatus=0x00000003\s*\(INVALID_REQUEST\)',
        '(?i)\(NOT_SUPPORTED\)',
        '(?i)\bNOT_SUPPORTED\b',
        '(?i)\(INVALID_REQUEST\)',
        '(?i)\bINVALID_REQUEST\b',
        '(?i)Incorrect\s+function',
        '(?i)ERROR_INVALID_FUNCTION',
        '(?i)INVALID_FUNCTION',
        '(?i)The\s+request\s+is\s+not\s+supported',
        '(?i)\brequest\s+is\s+not\s+supported\b',
        '(?i)\bnot\s+supported\b',
        '(?i)\bunsupported\b',
        '(?i)win32=1\s*\(',
        '(?i)win32=50\s*\('
    )
    foreach ($pattern in $genuineUnsupportedPatterns) { if ($Message -match $pattern) { return $true } }
    return $false
}

function Write-NVMeNumberOfQueuesDetailedErrorToConsole {
    param(
        [AllowNull()][string]$Message,
        [ValidateSet('Read','Set','Unknown')][string]$Operation = 'Unknown'
    )
    if ([string]::IsNullOrWhiteSpace($Message)) { return }
    try { if (Test-NVMeNumberOfQueuesUnsupportedError -Message $Message) { return } } catch { }
    $stamp = try { Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff' } catch { '' }
    $opText = if ([string]::IsNullOrWhiteSpace($Operation) -or $Operation -eq 'Unknown') { 'NVMe NOQ' } else { "NVMe NOQ $Operation" }
    try { Write-Host ("[$stamp] [$opText][ERROR] Detailed non-unsupported Number of Queues failure follows:") -ForegroundColor Red } catch { }
    try { Write-Host ([string]$Message) -ForegroundColor Yellow } catch { }
}

function Format-NVMeNumberOfQueuesUnsupportedLabel { return 'NOQ Unsupported | FID=0x07' }

