function Get-NVMeNumberOfQueues {
    param([Parameter(Mandatory=$true)][string]$DrivePath)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        return (ConvertTo-NVMeNumberOfQueuesObject -State ([DeviceTweakerNvmeProtocol]::GetNumberOfQueues($DrivePath)))
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeNumberOfQueuesUnsupportedError -Message $detail) { return (New-NVMeNumberOfQueuesUnsupportedObject -DrivePath $DrivePath) }
        throw [System.InvalidOperationException]::new(('NVMe Number of Queues read failed for {0}: {1}' -f $DrivePath, $_.Exception.Message), $_.Exception)
    }
}

function Set-NVMeNumberOfQueues {
    param(
        [Parameter(Mandatory=$true)][string]$DrivePath,
        [Parameter(Mandatory=$true)][ValidateRange(1,65535)][int]$SubmissionQueues,
        [Parameter(Mandatory=$true)][ValidateRange(1,65535)][int]$CompletionQueues
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        return (ConvertTo-NVMeNumberOfQueuesObject -State ([DeviceTweakerNvmeProtocol]::SetNumberOfQueues($DrivePath, [int]$SubmissionQueues, [int]$CompletionQueues)))
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeNumberOfQueuesLifecycleError -Message $detail) { throw [System.InvalidOperationException]::new(('NVMe Number of Queues FID=0x07 is only changeable during controller initialization before I/O queue creation; the current Windows StorNVMe path has already passed that lifecycle point. {0}' -f $detail), $_.Exception) }
        if (Test-NVMeNumberOfQueuesUnsupportedError -Message $detail) { throw [System.NotSupportedException]::new(('NVMe Number of Queues unsupported for {0}; Set Features FID=0x07 was rejected by Windows StorNVMe/firmware. {1}' -f $DrivePath, $detail), $_.Exception) }
        throw [System.InvalidOperationException]::new(('NVMe Number of Queues set failed for {0} SQ={1} CQ={2}: {3}' -f $DrivePath, $SubmissionQueues, $CompletionQueues, $_.Exception.Message), $_.Exception)
    }
}

function Format-NVMeArbitrationReadbackLabel {
    param($ArbState, [AllowNull()][string]$ArbError)
    if ($null -ne $ArbState) {
        if ($ArbState.DisplayText) { return [string]$ArbState.DisplayText }
        return [DeviceTweakerNvmeProtocol]::FormatArbitrationDisplay([int]$ArbState.ArbitrationBurst, [int]$ArbState.LowPriorityWeight, [int]$ArbState.MediumPriorityWeight, [int]$ArbState.HighPriorityWeight, [uint32]$ArbState.RawValue)
    }
    if (-not [string]::IsNullOrWhiteSpace($ArbError)) {
        if (Test-NVMeArbitrationUnsupportedError -Message $ArbError) { return (Format-NVMeArbitrationUnsupportedLabel) }
        return ('ARB ERR: {0}' -f $ArbError)
    }
    return 'Arbitration read failed: worker returned no state and no captured exception details'
}

function Format-NVMeNumberOfQueuesReadbackLabel {
    param($NoqState, [AllowNull()][string]$NoqError)
    if ($null -ne $NoqState) {
        if ($NoqState.DisplayText) { return [string]$NoqState.DisplayText }
        return [DeviceTweakerNvmeProtocol]::FormatNumberOfQueuesDisplay([int]$NoqState.SubmissionQueuesRequested, [int]$NoqState.CompletionQueuesRequested, [int]$NoqState.SubmissionQueuesAllocated, [int]$NoqState.CompletionQueuesAllocated, [uint32]$NoqState.RawValue)
    }
    if (-not [string]::IsNullOrWhiteSpace($NoqError)) {
        if (Test-NVMeNumberOfQueuesUnsupportedError -Message $NoqError) { return (Format-NVMeNumberOfQueuesUnsupportedLabel) }
        Write-NVMeNumberOfQueuesDetailedErrorToConsole -Message $NoqError -Operation Read
        return 'NOQ ERR: see PowerShell console for detailed error'
    }
    return 'Number of Queues read failed: worker returned no state and no captured exception details'
}

function Get-NVMeInterruptCoalescingSetUserMessage {
    param([AllowNull()][string]$Message)
    if ((Test-NVMeInterruptCoalescingUnsupportedError -Message $Message) -or (Test-NVMeInterruptCoalescingSetUnsupportedError -Message $Message)) {
        return (Format-NVMeInterruptCoalescingUnsupportedLabel)
    }
    if ([string]::IsNullOrWhiteSpace($Message)) { return 'Set failed' }
    $text = [string]$Message
    if ($text.Length -gt 420) { $text = $text.Substring(0, 420) + '...' }
    return ('Set failed: {0}' -f $text)
}

function Get-NVMeInterruptCoalescing {
    param([Parameter(Mandatory=$true)][string]$DrivePath)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        $state = [DeviceTweakerNvmeProtocol]::GetInterruptCoalescing($DrivePath)
        [PSCustomObject]@{
            DrivePath            = [string]$state.DrivePath
            Supported            = [bool]$state.Supported
            RawValue             = [uint32]$state.RawValue
            Threshold            = [int]$state.ThresholdRaw
            ThresholdRaw         = [int]$state.ThresholdRaw
            CompletionThreshold  = [int]$state.CompletionThreshold
            TimeUnits            = [int]$state.TimeUnits
            Time100us            = [int]$state.TimeUnits
            TimeUs               = [int]$state.TimeMicroseconds
            ImplicitlyDisabled   = [bool]$state.ImplicitlyDisabled
            Scope                = [string]$state.Scope
            DisplayText          = [string]$state.DisplayText
        }
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeInterruptCoalescingUnsupportedError -Message $detail) {
            return [PSCustomObject]@{
                DrivePath            = [string]$DrivePath
                Supported            = $false
                RawValue             = [uint32]0
                Threshold            = 0
                ThresholdRaw         = 0
                CompletionThreshold  = 0
                TimeUnits            = 0
                Time100us            = 0
                TimeUs               = 0
                ImplicitlyDisabled   = $true
                Scope                = 'Unsupported'
                DisplayText          = (Format-NVMeInterruptCoalescingUnsupportedLabel)
            }
        }
        throw [System.InvalidOperationException]::new(('NVMe interrupt coalescing read failed for {0}: {1}' -f $DrivePath, $_.Exception.Message), $_.Exception)
    }
}

function Set-NVMeInterruptCoalescing {
    param(
        [Parameter(Mandatory=$true)][string]$DrivePath,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Threshold,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Time100us
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { throw [System.InvalidOperationException]::new('NVMe feature processing is disabled by $DisableRWEnNVMe.') }
    try {
        $state = [DeviceTweakerNvmeProtocol]::SetInterruptCoalescing($DrivePath, [int]$Threshold, [int]$Time100us)
        [PSCustomObject]@{
            DrivePath            = [string]$state.DrivePath
            Supported            = [bool]$state.Supported
            RawValue             = [uint32]$state.RawValue
            Threshold            = [int]$state.ThresholdRaw
            ThresholdRaw         = [int]$state.ThresholdRaw
            CompletionThreshold  = [int]$state.CompletionThreshold
            TimeUnits            = [int]$state.TimeUnits
            Time100us            = [int]$state.TimeUnits
            TimeUs               = [int]$state.TimeMicroseconds
            ImplicitlyDisabled   = [bool]$state.ImplicitlyDisabled
            Scope                = [string]$state.Scope
            DisplayText          = [string]$state.DisplayText
        }
    } catch {
        $detail = ''
        try { $detail = Format-DeviceTweakerErrorRecordForUi $_ } catch { $detail = [string]$_.Exception.Message }
        if (Test-NVMeInterruptCoalescingUnsupportedError -Message $detail) {
            throw [System.NotSupportedException]::new(('NVMe Interrupt Coalescing unsupported for {0}; Set Features FID=0x08 was rejected by Windows StorNVMe/firmware. {1}' -f $DrivePath, $detail), $_.Exception)
        }
        throw [System.InvalidOperationException]::new(('NVMe interrupt coalescing set failed for {0} THR={1} TIME={2}: {3}' -f $DrivePath, $Threshold, $Time100us, $_.Exception.Message), $_.Exception)
    }
}

