function ConvertTo-NVMeErrorRecoveryObject {
    param($state)
    if ($null -eq $state) { return $null }
    $supported = $true
    try { if ($state.PSObject.Properties['Supported']) { $supported = [bool]$state.Supported } } catch { $supported = $true }
    [PSCustomObject]@{
        DrivePath = [string]$state.DrivePath
        Supported = [bool]$supported
        RawValue = [uint32]$state.RawValue
        NamespaceId = [uint32]$state.NamespaceId
        TimeLimitedErrorRecovery = [int]$state.TimeLimitedErrorRecovery
        TimeoutMilliseconds = [int]$state.TimeoutMilliseconds
        DeallocatedOrUnwrittenLogicalBlockErrorEnabled = [bool]$state.DeallocatedOrUnwrittenLogicalBlockErrorEnabled
        Scope = [string]$state.Scope
        DisplayText = [string]$state.DisplayText
    }
}

