function Format-NVMeApstPowerReadbackLabel {
    param($ApstState, $PowerState, [AllowNull()][string]$ApstError, [AllowNull()][string]$PowerError)
    $parts = [System.Collections.Generic.List[string]]::new()
    if ($null -ne $ApstState) {
        if ($ApstState.DisplayText) { [void]$parts.Add([string]$ApstState.DisplayText) }
        else {
            $apstText = if ($ApstState.Enabled) { 'Enabled' } else { 'Disabled' }
            [void]$parts.Add(('APST {0} | {1} active entries' -f $apstText, [int]$ApstState.ActiveEntryCount))
        }
    } elseif (-not [string]::IsNullOrWhiteSpace($ApstError)) {
        [void]$parts.Add(('APST ERR: {0}' -f $ApstError))
    }
    if ($null -ne $PowerState) {
        $powerSupported = $true
        try { if ($PowerState.PSObject.Properties['Supported']) { $powerSupported = [bool]$PowerState.Supported } } catch { $powerSupported = $true }
        if (-not $powerSupported) { [void]$parts.Add((Format-NVMePowerManagementUnsupportedLabel)) }
        elseif ($PowerState.DisplayText) { [void]$parts.Add([string]$PowerState.DisplayText) }
        else { [void]$parts.Add(('PS{0}' -f [int]$PowerState.PowerState)) }
    } elseif (-not [string]::IsNullOrWhiteSpace($PowerError)) {
        if (Test-NVMePowerManagementUnsupportedError -Message $PowerError) { [void]$parts.Add((Format-NVMePowerManagementUnsupportedLabel)) }
        else { [void]$parts.Add(('PS ERR: {0}' -f $PowerError)) }
    }
    if ($parts.Count -eq 0) { return 'APST/PS read failed: worker returned no APST state, no Power Management state, and no captured APST/PS exception details' }
    return ($parts.ToArray() -join ' | ')
}

function Format-NVMeVolatileWriteCacheReadbackLabel {
    param($VwcState, [AllowNull()][string]$VwcError)
