                if ($VwcState.DisplayText) { return [string]$VwcState.DisplayText }
                return (Format-NVMeVolatileWriteCacheUnsupportedLabel)
            }
        } catch { }
        if ($VwcState.DisplayText) { return [string]$VwcState.DisplayText }
        $stateText = if ($VwcState.Enabled) { 'Enabled' } else { 'Disabled' }
        $wce = if ($VwcState.Enabled) { 1 } else { 0 }
        return ('VWC {0} | WCE={1} | raw=0x{2:X8}' -f $stateText, $wce, [uint32]$VwcState.RawValue)
    }
    if (-not [string]::IsNullOrWhiteSpace($VwcError)) {
        if (Test-NVMeVolatileWriteCacheUnsupportedError -Message $VwcError) { return (Format-NVMeVolatileWriteCacheUnsupportedLabel) }
        return ('VWC ERR: {0}' -f $VwcError)
