        try {
            if ($HmbState.PSObject.Properties['Supported'] -and -not [bool]$HmbState.Supported) {
                if ($HmbState.DisplayText) { return [string]$HmbState.DisplayText }
                $hmmin = 0
                try { if ($HmbState.PSObject.Properties['MinimumSize4KiB']) { $hmmin = [uint32]$HmbState.MinimumSize4KiB } } catch { $hmmin = 0 }
                return ('HMB unsupported | HMPRE=0 | HMMIN={0} x4KiB' -f [uint32]$hmmin)
            }
        } catch { }
        if ($HmbState.DisplayText) { return [string]$HmbState.DisplayText }
        $stateText = if ($HmbState.Enabled) { 'Enabled' } else { 'Disabled' }
        $ehm = if ($HmbState.Enabled) { 1 } else { 0 }
        $mr = if ($HmbState.MemoryReturn) { 1 } else { 0 }
        return ('HMB {0} | EHM={1} MR={2} | HSIZE={3} MPS | HMDL=0x{4:X16} | EC={5} | raw=0x{6:X8}' -f $stateText, $ehm, $mr, [uint32]$HmbState.SizeMps, [uint64]$HmbState.DescriptorListAddress, [uint32]$HmbState.DescriptorEntryCount, [uint32]$HmbState.RawValue)
    }
    if (-not [string]::IsNullOrWhiteSpace($HmbError)) { return ('HMB ERR: {0}' -f $HmbError) }
    return 'HMB read failed: worker returned no state and no captured exception details'
}


