        $ctrls.NVMeWanStatusLabel.Text = Format-NVMeWriteAtomicityNormalReadbackLabel -WanState $wanState -WanError $wanError
        Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeWanStatusLabel
    }
}

