        if ($ctrls.ContainsKey('NVMeHmbDescriptorEntryCount') -and $ctrls.NVMeHmbDescriptorEntryCount -is [System.Windows.Forms.NumericUpDown]) { $ctrls.NVMeHmbDescriptorEntryCount.Value = [decimal][uint32]$hmbState.DescriptorEntryCount }
