    foreach ($name in @('NVMeHmbModeCombo','NVMeHmbSizeMps','NVMeHmbDescriptorLower','NVMeHmbDescriptorUpper','NVMeHmbDescriptorEntryCount','NVMeHmbSetButton')) {
        try { if ($ctrls.ContainsKey($name) -and $null -ne $ctrls[$name]) { $ctrls[$name].Enabled = [bool]$hmbSupported } } catch { }
    }
    if ($ctrls.ContainsKey('NVMeHmbStatusLabel') -and $null -ne $ctrls.NVMeHmbStatusLabel) {
