        try { if ($ctrls.ContainsKey($name) -and $null -ne $ctrls[$name]) { $ctrls[$name].Enabled = [bool]$arbSupported } } catch { }
    }
    if ($ctrls.ContainsKey('NVMeArbStatusLabel') -and $null -ne $ctrls.NVMeArbStatusLabel) {
        $ctrls.NVMeArbStatusLabel.Text = Format-NVMeArbitrationReadbackLabel -ArbState $arbState -ArbError $arbError
        Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel
    }
}

function Get-NVMeArbitrationSelectionFromControls {
    param([hashtable]$ctrls)
    $ab = 7
    $lpw = 0
    $mpw = 0
    $hpw = 0
    try { if ($ctrls.ContainsKey('NVMeArbBurstCombo') -and $ctrls.NVMeArbBurstCombo -is [System.Windows.Forms.ComboBox] -and $ctrls.NVMeArbBurstCombo.SelectedIndex -ge 0) { $ab = [int]$ctrls.NVMeArbBurstCombo.SelectedIndex } } catch { $ab = 7 }
    try { if ($ctrls.ContainsKey('NVMeArbLowWeight') -and $ctrls.NVMeArbLowWeight -is [System.Windows.Forms.NumericUpDown]) { $lpw = [int]$ctrls.NVMeArbLowWeight.Value } } catch { $lpw = 0 }
    try { if ($ctrls.ContainsKey('NVMeArbMediumWeight') -and $ctrls.NVMeArbMediumWeight -is [System.Windows.Forms.NumericUpDown]) { $mpw = [int]$ctrls.NVMeArbMediumWeight.Value } } catch { $mpw = 0 }
    try { if ($ctrls.ContainsKey('NVMeArbHighWeight') -and $ctrls.NVMeArbHighWeight -is [System.Windows.Forms.NumericUpDown]) { $hpw = [int]$ctrls.NVMeArbHighWeight.Value } } catch { $hpw = 0 }
    [PSCustomObject]@{ ArbitrationBurst = $ab; LowPriorityWeight = $lpw; MediumPriorityWeight = $mpw; HighPriorityWeight = $hpw }
}

function Set-NVMeNumberOfQueuesControlsFromState {
    param([hashtable]$ctrls, $noqState, [AllowNull()][string]$noqError)
    if ($null -eq $ctrls) { return }
    $noqSupported = $true
    if ($null -ne $noqState) {
        try { if ($noqState.PSObject.Properties['Supported'] -and -not [bool]$noqState.Supported) { $noqSupported = $false } } catch { $noqSupported = $true }
        if ($noqSupported) {
            if ($ctrls.ContainsKey('NVMeNoqSubmissionQueues') -and $ctrls.NVMeNoqSubmissionQueues -is [System.Windows.Forms.NumericUpDown]) { $ctrls.NVMeNoqSubmissionQueues.Value = [decimal]([Math]::Max(1, [Math]::Min(65535, [int]$noqState.SubmissionQueuesAllocated))) }
            if ($ctrls.ContainsKey('NVMeNoqCompletionQueues') -and $ctrls.NVMeNoqCompletionQueues -is [System.Windows.Forms.NumericUpDown]) { $ctrls.NVMeNoqCompletionQueues.Value = [decimal]([Math]::Max(1, [Math]::Min(65535, [int]$noqState.CompletionQueuesAllocated))) }
        }
    } elseif (Test-NVMeNumberOfQueuesUnsupportedError -Message $noqError) {
        $noqSupported = $false
    }
    foreach ($name in @('NVMeNoqSubmissionQueues','NVMeNoqCompletionQueues','NVMeNoqSetButton')) {
        try { if ($ctrls.ContainsKey($name) -and $null -ne $ctrls[$name]) { $ctrls[$name].Enabled = [bool]$noqSupported } } catch { }
    }
    if ($ctrls.ContainsKey('NVMeNoqStatusLabel') -and $null -ne $ctrls.NVMeNoqStatusLabel) {
        $ctrls.NVMeNoqStatusLabel.Text = Format-NVMeNumberOfQueuesReadbackLabel -NoqState $noqState -NoqError $noqError
        Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeNoqStatusLabel
    }
}

function Get-NVMeNumberOfQueuesSelectionFromControls {
    param([hashtable]$ctrls)
    $sq = 1
    $cq = 1
    try { if ($ctrls.ContainsKey('NVMeNoqSubmissionQueues') -and $ctrls.NVMeNoqSubmissionQueues -is [System.Windows.Forms.NumericUpDown]) { $sq = [int]$ctrls.NVMeNoqSubmissionQueues.Value } } catch { $sq = 1 }
    try { if ($ctrls.ContainsKey('NVMeNoqCompletionQueues') -and $ctrls.NVMeNoqCompletionQueues -is [System.Windows.Forms.NumericUpDown]) { $cq = [int]$ctrls.NVMeNoqCompletionQueues.Value } } catch { $cq = 1 }
    [PSCustomObject]@{ SubmissionQueues = $sq; CompletionQueues = $cq }
}

function Set-NVMeInterruptCoalescingControlsFromState {
    param([hashtable]$ctrls, $state)
    if ($null -eq $ctrls -or $null -eq $state) { return }
    $supported = $true
    try { if ($state.PSObject.Properties['Supported']) { $supported = [bool]$state.Supported } } catch { $supported = $true }
    if (-not $supported) {
        if ($ctrls.ContainsKey('NVMeTimeLabel') -and $null -ne $ctrls.NVMeTimeLabel) {
            $ctrls.NVMeTimeLabel.Text = if ($state.DisplayText) { [string]$state.DisplayText } else { Format-NVMeInterruptCoalescingUnsupportedLabel }
            Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTimeLabel
        }
        return
    }
    if ($ctrls.ContainsKey('NVMeThreshold') -and $null -ne $ctrls.NVMeThreshold) {
        $ctrls.NVMeThreshold.Value = [decimal]([Math]::Max(0, [Math]::Min(255, [int]$state.Threshold)))
    }
    if ($ctrls.ContainsKey('NVMeTime') -and $null -ne $ctrls.NVMeTime) {
        $ctrls.NVMeTime.Value = [decimal]([Math]::Max(0, [Math]::Min(255, [int]$state.TimeUnits)))
    }
    if ($ctrls.ContainsKey('NVMeTimeLabel') -and $null -ne $ctrls.NVMeTimeLabel) {
        $text = if ($state.DisplayText) { [string]$state.DisplayText } else { Format-NVMeInterruptCoalescingLabel -Threshold ([int]$state.Threshold) -TimeUnits ([int]$state.TimeUnits) }
        $ctrls.NVMeTimeLabel.Text = $text
        Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTimeLabel
    }
}

function Set-NVMeApstPowerControlsFromState {
    param([hashtable]$ctrls, $apstState, $powerState, [AllowNull()][string]$apstError, [AllowNull()][string]$powerError)
    if ($null -eq $ctrls) { return }
    if ($ctrls.ContainsKey('NVMeApstPowerStatusLabel') -and $null -ne $ctrls.NVMeApstPowerStatusLabel) {
        $ctrls.NVMeApstPowerStatusLabel.Text = Format-NVMeApstPowerReadbackLabel -ApstState $apstState -PowerState $powerState -ApstError $apstError -PowerError $powerError
        Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeApstPowerStatusLabel
    }
}

function Resolve-NVMePhysicalDrivePathForDevice {
    param($device, [hashtable]$ctrls)
    if ($null -ne $ctrls -and $ctrls.ContainsKey('NVMeDrivePath') -and -not [string]::IsNullOrWhiteSpace([string]$ctrls.NVMeDrivePath)) { return [string]$ctrls.NVMeDrivePath }
    if ($null -ne $device) {
        if ($device.PSObject.Properties['PhysicalDrivePath'] -and -not [string]::IsNullOrWhiteSpace([string]$device.PhysicalDrivePath)) { return [string]$device.PhysicalDrivePath }
        if ($device.PSObject.Properties['DiskIndex'] -and $null -ne $device.DiskIndex -and [int]$device.DiskIndex -ge 0) { return ('\\.\PhysicalDrive{0}' -f [int]$device.DiskIndex) }
        $pnp = if ($device.PSObject.Properties['DiskPNPID'] -and -not [string]::IsNullOrWhiteSpace([string]$device.DiskPNPID)) { [string]$device.DiskPNPID } elseif ($device.PSObject.Properties['PNPID']) { [string]$device.PNPID } elseif ($null -ne $ctrls -and $ctrls.ContainsKey('StoragePNPID')) { [string]$ctrls.StoragePNPID } else { $null }
        if (-not [string]::IsNullOrWhiteSpace($pnp)) {
            try {
                $disk = Get-CachedWin32DiskDrives | Where-Object { $_.PNPDeviceID -eq $pnp } | Select-Object -First 1
                if ($disk -and $null -ne $disk.Index) { return ('\\.\PhysicalDrive{0}' -f [int]$disk.Index) }
            } catch { }
        }
    }
    return $null
}

function Get-AsyncNVMeInterruptCoalescingWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Format-DeviceTweakerErrorRecordForUi')
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled')
        (Get-FunctionDefinitionText 'Get-NVMeInterruptCoalescing')
        (Get-FunctionDefinitionText 'Test-NVMeArbitrationUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeArbitrationUnsupportedLabel')
        (Get-FunctionDefinitionText 'ConvertTo-NVMeArbitrationObject')
        (Get-FunctionDefinitionText 'New-NVMeArbitrationUnsupportedObject')
        (Get-FunctionDefinitionText 'Get-NVMeArbitration')
        (Get-FunctionDefinitionText 'Test-NVMeNumberOfQueuesLifecycleError')
        (Get-FunctionDefinitionText 'Test-NVMeNumberOfQueuesUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeNumberOfQueuesUnsupportedLabel')
        (Get-FunctionDefinitionText 'ConvertTo-NVMeNumberOfQueuesObject')
        (Get-FunctionDefinitionText 'New-NVMeNumberOfQueuesUnsupportedObject')
        (Get-FunctionDefinitionText 'Get-NVMeNumberOfQueues')
        (Get-FunctionDefinitionText 'Get-NVMeAutonomousPowerStateTransition')
        (Get-FunctionDefinitionText 'Test-NVMePowerManagementUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMePowerManagementUnsupportedLabel')
        (Get-FunctionDefinitionText 'Get-NVMePowerState')
        (Get-FunctionDefinitionText 'Test-NVMeVolatileWriteCacheUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeVolatileWriteCacheUnsupportedLabel')
        (Get-FunctionDefinitionText 'New-NVMeVolatileWriteCacheUnsupportedObject')
        (Get-FunctionDefinitionText 'Get-NVMeVolatileWriteCache')
        (Get-FunctionDefinitionText 'Test-NVMeTemperatureThresholdUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeTemperatureThresholdUnsupportedLabel')
        (Get-FunctionDefinitionText 'New-NVMeTemperatureThresholdUnsupportedObject')
        (Get-FunctionDefinitionText 'Get-NVMeTemperatureThreshold')
        (Get-FunctionDefinitionText 'Test-NVMeWriteAtomicityNormalUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeWriteAtomicityNormalUnsupportedLabel')
        (Get-FunctionDefinitionText 'New-NVMeWriteAtomicityNormalUnsupportedObject')
        (Get-FunctionDefinitionText 'Get-NVMeWriteAtomicityNormal')
        (Get-FunctionDefinitionText 'Get-NVMeHostMemoryBuffer')
        (Get-FunctionDefinitionText 'Test-NVMeInterruptCoalescingSetUnsupportedError')
        (Get-FunctionDefinitionText 'Test-NVMeInterruptCoalescingUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeInterruptCoalescingUnsupportedLabel')
        (Get-FunctionDefinitionText 'Test-NVMeErrorRecoveryUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeErrorRecoveryUnsupportedLabel')
        (Get-FunctionDefinitionText 'Test-NVMeHostControlledThermalManagementUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeHostControlledThermalManagementUnsupportedLabel')
        (Get-FunctionDefinitionText 'ConvertTo-NVMeErrorRecoveryObject')
        (Get-FunctionDefinitionText 'ConvertTo-NVMeHostControlledThermalManagementObject')
        (Get-FunctionDefinitionText 'Get-NVMeErrorRecovery')
        (Get-FunctionDefinitionText 'Get-NVMeHostControlledThermalManagement')
    ) -join "`r`n`r`n"
    return @"
param(`$specs)
$defs
`$results = [System.Collections.Generic.List[object]]::new()
foreach (`$spec in @(`$specs)) {
    if (`$null -eq `$spec) { continue }
    `$icState = `$null
    `$icError = `$null
    `$icSuccess = `$false
    `$arbState = `$null
    `$arbError = `$null
    `$arbSuccess = `$false
    `$noqState = `$null
    `$noqError = `$null
    `$noqSuccess = `$false
    `$apstState = `$null
    `$apstError = `$null
    `$apstSuccess = `$false
    `$powerState = `$null
    `$powerError = `$null
    `$powerSuccess = `$false
    `$vwcState = `$null
    `$vwcError = `$null
    `$vwcSuccess = `$false
    `$tempState = `$null
    `$tempError = `$null
    `$tempSuccess = `$false
    `$wanState = `$null
    `$wanError = `$null
    `$wanSuccess = `$false
    `$hmbState = `$null
    `$hmbError = `$null
    `$hmbSuccess = `$false
    `$errState = `$null
    `$errError = `$null
    `$errSuccess = `$false
    `$hctmState = `$null
    `$hctmError = `$null
    `$hctmSuccess = `$false
    `$tempSensor = 0
    `$tempType = 0
    `$errNamespaceId = [uint32]1
    `$readKind = 'All'
    try { if (`$spec.PSObject.Properties['ReadKind'] -and -not [string]::IsNullOrWhiteSpace([string]`$spec.ReadKind)) { `$readKind = [string]`$spec.ReadKind } } catch { `$readKind = 'All' }
    `$rk = `$readKind.Trim().ToUpperInvariant()
    `$readAll = ([string]::IsNullOrWhiteSpace(`$rk) -or `$rk -eq 'ALL')
    `$readIc = (`$readAll -or `$rk -eq 'IC' -or `$rk -eq 'INTERRUPT' -or `$rk -eq 'INTERRUPTCOALESCING' -or `$rk -eq 'INTERRUPT_COALESCING')
    `$readArb = (`$readAll -or `$rk -eq 'ARB' -or `$rk -eq 'ARBITRATION')
    `$readNoq = (`$readAll -or `$rk -eq 'NOQ' -or `$rk -eq 'NUMBEROFQUEUES' -or `$rk -eq 'NUMBER_OF_QUEUES' -or `$rk -eq 'NUMQUEUES' -or `$rk -eq 'NUM_QUEUES')
    `$readApstPower = (`$readAll -or `$rk -eq 'POWER' -or `$rk -eq 'PWR' -or `$rk -eq 'APST' -or `$rk -eq 'APSTPOWER' -or `$rk -eq 'APST_POWER')
    `$readVwc = (`$readAll -or `$rk -eq 'VWC' -or `$rk -eq 'VOLATILEWRITECACHE' -or `$rk -eq 'VOLATILE_WRITE_CACHE')
    `$readTemp = (`$readAll -or `$rk -eq 'TEMP' -or `$rk -eq 'TEMPERATURE' -or `$rk -eq 'TEMPERATURETHRESHOLD' -or `$rk -eq 'TEMPERATURE_THRESHOLD')
    `$readWan = (`$readAll -or `$rk -eq 'WAN' -or `$rk -eq 'WRITEATOMICITYNORMAL' -or `$rk -eq 'WRITE_ATOMICITY_NORMAL')
    `$readHmb = (`$readAll -or `$rk -eq 'HMB' -or `$rk -eq 'HOSTMEMORYBUFFER' -or `$rk -eq 'HOST_MEMORY_BUFFER')
    `$readErr = (`$readAll -or `$rk -eq 'ERR' -or `$rk -eq 'ERROR' -or `$rk -eq 'ERRORRECOVERY' -or `$rk -eq 'ERROR_RECOVERY')
    `$readHctm = (`$readAll -or `$rk -eq 'HCTM' -or `$rk -eq 'HOSTCONTROLLEDTHERMALMANAGEMENT' -or `$rk -eq 'HOST_CONTROLLED_THERMAL_MANAGEMENT')
    if (-not (`$readIc -or `$readArb -or `$readNoq -or `$readApstPower -or `$readVwc -or `$readTemp -or `$readWan -or `$readHmb -or `$readErr -or `$readHctm)) { `$readAll = `$true; `$readIc = `$true; `$readArb = `$true; `$readNoq = `$true; `$readApstPower = `$true; `$readVwc = `$true; `$readTemp = `$true; `$readWan = `$true; `$readHmb = `$true; `$readErr = `$true; `$readHctm = `$true }
    try { if (`$spec.PSObject.Properties['TempSensorSelect']) { `$tempSensor = [int]`$spec.TempSensorSelect } } catch { `$tempSensor = 0 }
    try { if (`$spec.PSObject.Properties['TempThresholdType']) { `$tempType = [int]`$spec.TempThresholdType } } catch { `$tempType = 0 }
    try { if (`$spec.PSObject.Properties['ErrNamespaceId']) { `$errNamespaceId = [uint32]`$spec.ErrNamespaceId } } catch { `$errNamespaceId = [uint32]1 }
    if (`$readIc) { try { `$icState = Get-NVMeInterruptCoalescing -DrivePath ([string]`$spec.DrivePath); `$icSuccess = `$true } catch { `$icError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readArb) { try { `$arbState = Get-NVMeArbitration -DrivePath ([string]`$spec.DrivePath); `$arbSuccess = `$true } catch { `$arbError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readNoq) { try { `$noqState = Get-NVMeNumberOfQueues -DrivePath ([string]`$spec.DrivePath); `$noqSuccess = `$true } catch { `$noqError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readApstPower) { try { `$apstState = Get-NVMeAutonomousPowerStateTransition -DrivePath ([string]`$spec.DrivePath); `$apstSuccess = `$true } catch { `$apstError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readApstPower) { try { `$powerState = Get-NVMePowerState -DrivePath ([string]`$spec.DrivePath); `$powerSuccess = `$true } catch { `$powerError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readVwc) { try { `$vwcState = Get-NVMeVolatileWriteCache -DrivePath ([string]`$spec.DrivePath); `$vwcSuccess = `$true } catch { `$vwcError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readTemp) { try { `$tempState = Get-NVMeTemperatureThreshold -DrivePath ([string]`$spec.DrivePath) -SensorSelect `$tempSensor -ThresholdType `$tempType; `$tempSuccess = `$true } catch { `$tempError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readWan) { try { `$wanState = Get-NVMeWriteAtomicityNormal -DrivePath ([string]`$spec.DrivePath); `$wanSuccess = `$true } catch { `$wanError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readHmb) { try { `$hmbState = Get-NVMeHostMemoryBuffer -DrivePath ([string]`$spec.DrivePath); `$hmbSuccess = `$true } catch { `$hmbError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readErr) { try { `$errState = Get-NVMeErrorRecovery -DrivePath ([string]`$spec.DrivePath) -NamespaceId `$errNamespaceId; `$errSuccess = `$true } catch { `$errError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    if (`$readHctm) { try { `$hctmState = Get-NVMeHostControlledThermalManagement -DrivePath ([string]`$spec.DrivePath); `$hctmSuccess = `$true } catch { `$hctmError = Format-DeviceTweakerErrorRecordForUi `$_ } }
    [void]`$results.Add([PSCustomObject]@{
        Key = [string]`$spec.Key
        DrivePath = [string]`$spec.DrivePath
        ReadKind = [string]`$readKind
        IcRequested = [bool]`$readIc
        ArbRequested = [bool]`$readArb
        NoqRequested = [bool]`$readNoq
        ApstRequested = [bool]`$readApstPower
        PowerRequested = [bool]`$readApstPower
        VwcRequested = [bool]`$readVwc
        TempRequested = [bool]`$readTemp
        WanRequested = [bool]`$readWan
        HmbRequested = [bool]`$readHmb
        ErrRequested = [bool]`$readErr
        HctmRequested = [bool]`$readHctm
        Success = (`$icSuccess -or `$arbSuccess -or `$noqSuccess -or `$apstSuccess -or `$powerSuccess -or `$vwcSuccess -or `$tempSuccess -or `$wanSuccess -or `$hmbSuccess -or `$errSuccess -or `$hctmSuccess)
        ReadBack = `$icState
        Error = `$icError
        ArbSuccess = `$arbSuccess
        ArbReadBack = `$arbState
        ArbError = `$arbError
        NoqSuccess = `$noqSuccess
        NoqReadBack = `$noqState
        NoqError = `$noqError
        ApstSuccess = `$apstSuccess
        ApstReadBack = `$apstState
        ApstError = `$apstError
        PowerSuccess = `$powerSuccess
        PowerReadBack = `$powerState
        PowerError = `$powerError
        VwcSuccess = `$vwcSuccess
        VwcReadBack = `$vwcState
        VwcError = `$vwcError
        TempSuccess = `$tempSuccess
        TempReadBack = `$tempState
        TempError = `$tempError
        WanSuccess = `$wanSuccess
        WanReadBack = `$wanState
        WanError = `$wanError
        HmbSuccess = `$hmbSuccess
        HmbReadBack = `$hmbState
        HmbError = `$hmbError
        ErrSuccess = `$errSuccess
        ErrReadBack = `$errState
        ErrError = `$errError
        HctmSuccess = `$hctmSuccess
        HctmReadBack = `$hctmState
        HctmError = `$hctmError
    })
}
return ,`$results
"@
}



function Get-AsyncNVMeArbitrationApplyWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Format-DeviceTweakerErrorRecordForUi')
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled')
        (Get-FunctionDefinitionText 'Test-NVMeInterruptCoalescingSetUnsupportedError')
        (Get-FunctionDefinitionText 'Test-NVMeArbitrationUnsupportedError')
        (Get-FunctionDefinitionText 'Format-NVMeArbitrationUnsupportedLabel')
        (Get-FunctionDefinitionText 'ConvertTo-NVMeArbitrationObject')
        (Get-FunctionDefinitionText 'Set-NVMeArbitration')
    ) -join "`r`n`r`n"
    return @"
param(`$drivePath, `$arbitrationBurst, `$lowPriorityWeight, `$mediumPriorityWeight, `$highPriorityWeight)
$defs
try {
    `$state = Set-NVMeArbitration -DrivePath ([string]`$drivePath) -ArbitrationBurst ([int]`$arbitrationBurst) -LowPriorityWeight ([int]`$lowPriorityWeight) -MediumPriorityWeight ([int]`$mediumPriorityWeight) -HighPriorityWeight ([int]`$highPriorityWeight)
    [PSCustomObject]@{
        Success = `$true
        ArbReadBack = `$state
        Error = `$null
        Unsupported = `$false
    }
} catch {
    `$detail = Format-DeviceTweakerErrorRecordForUi `$_
    [PSCustomObject]@{
        Success = `$false
        ArbReadBack = `$null
        Error = `$detail
        Unsupported = (Test-NVMeArbitrationUnsupportedError -Message `$detail)
    }
}
"@
}

