function Get-AsyncNVMeVolatileWriteCacheApplyWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Format-DeviceTweakerErrorRecordForUi')
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled')
        (Get-FunctionDefinitionText 'Test-NVMeInterruptCoalescingSetUnsupportedError')
        (Get-FunctionDefinitionText 'Test-NVMeVolatileWriteCacheUnsupportedError')
        (Get-FunctionDefinitionText 'Set-NVMeVolatileWriteCache')
    ) -join "`r`n`r`n"
    return @"
param(`$drivePath, `$enabled)
$defs
try {
    `$state = Set-NVMeVolatileWriteCache -DrivePath ([string]`$drivePath) -Enabled ([bool]`$enabled)
    [PSCustomObject]@{
        Success = `$true
        VwcReadBack = `$state
        Error = `$null
        Unsupported = `$false
    }
} catch {
    `$detail = Format-DeviceTweakerErrorRecordForUi `$_
    [PSCustomObject]@{
