function Apply-AsyncNVMeInterruptCoalescingResultsToUI {
    param($resultItems)
    $items = @(Expand-DeviceTweakerResultItems -ResultItems $resultItems)
    foreach ($item in $items) {
        if ($null -eq $item) { continue }
        foreach ($device in $deviceList) {
            if (-not $deviceControls.ContainsKey($device)) { continue }
            $ctrls = $deviceControls[$device]
            if (-not $ctrls.ContainsKey('NVMeThreshold')) { continue }
            $key = [string]$device.RegistryPath
            if ($key -ne [string]$item.Key) { continue }
            $icRequested = $true
            $arbRequested = $true
            $noqRequested = $true
            $apstRequested = $true
            $powerRequested = $true
            $vwcRequested = $true
            $tempRequested = $true
            $wanRequested = $true
            $hmbRequested = $true
            $errRequested = $true
            $hctmRequested = $true
            try { if ($item.PSObject.Properties['IcRequested']) { $icRequested = [bool]$item.IcRequested } } catch { }
            try { if ($item.PSObject.Properties['ArbRequested']) { $arbRequested = [bool]$item.ArbRequested } } catch { }
            try { if ($item.PSObject.Properties['NoqRequested']) { $noqRequested = [bool]$item.NoqRequested } } catch { }
            try { if ($item.PSObject.Properties['ApstRequested']) { $apstRequested = [bool]$item.ApstRequested } } catch { }
            try { if ($item.PSObject.Properties['PowerRequested']) { $powerRequested = [bool]$item.PowerRequested } } catch { }
            try { if ($item.PSObject.Properties['VwcRequested']) { $vwcRequested = [bool]$item.VwcRequested } } catch { }
            try { if ($item.PSObject.Properties['TempRequested']) { $tempRequested = [bool]$item.TempRequested } } catch { }
            try { if ($item.PSObject.Properties['WanRequested']) { $wanRequested = [bool]$item.WanRequested } } catch { }
            try { if ($item.PSObject.Properties['HmbRequested']) { $hmbRequested = [bool]$item.HmbRequested } } catch { }
            try { if ($item.PSObject.Properties['ErrRequested']) { $errRequested = [bool]$item.ErrRequested } } catch { }
            try { if ($item.PSObject.Properties['HctmRequested']) { $hctmRequested = [bool]$item.HctmRequested } } catch { }
            if ($icRequested) {
                if ($item.Success -and $null -ne $item.ReadBack) {
                    Set-NVMeInterruptCoalescingControlsFromState -ctrls $ctrls -state $item.ReadBack
                } elseif ($ctrls.ContainsKey('NVMeTimeLabel') -and $null -ne $ctrls.NVMeTimeLabel) {
                    $icErrorText = if ($item.Error) { [string]$item.Error } else { 'IC read failed' }
                    $ctrls.NVMeTimeLabel.Text = if (Test-NVMeInterruptCoalescingUnsupportedError -Message $icErrorText) { Format-NVMeInterruptCoalescingUnsupportedLabel } else { $icErrorText }
                    Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTimeLabel
                }
            }
            if ($arbRequested) {
                $arbState = $null
                $arbError = $null
                try { if ($item.PSObject.Properties['ArbReadBack']) { $arbState = $item.ArbReadBack } } catch { }
                try { if ($item.PSObject.Properties['ArbError']) { $arbError = [string]$item.ArbError } } catch { }
                Set-NVMeArbitrationControlsFromState -ctrls $ctrls -arbState $arbState -arbError $arbError
            }
            if ($noqRequested) {
                $noqState = $null
                $noqError = $null
                try { if ($item.PSObject.Properties['NoqReadBack']) { $noqState = $item.NoqReadBack } } catch { }
                try { if ($item.PSObject.Properties['NoqError']) { $noqError = [string]$item.NoqError } } catch { }
                Set-NVMeNumberOfQueuesControlsFromState -ctrls $ctrls -noqState $noqState -noqError $noqError
            }
            if ($apstRequested -or $powerRequested) {
                $apstState = $null
                $powerState = $null
                $apstError = $null
                $powerError = $null
                try { if ($item.PSObject.Properties['ApstReadBack']) { $apstState = $item.ApstReadBack } } catch { }
                try { if ($item.PSObject.Properties['PowerReadBack']) { $powerState = $item.PowerReadBack } } catch { }
                try { if ($item.PSObject.Properties['ApstError']) { $apstError = [string]$item.ApstError } } catch { }
                try { if ($item.PSObject.Properties['PowerError']) { $powerError = [string]$item.PowerError } } catch { }
                Set-NVMeApstPowerControlsFromState -ctrls $ctrls -apstState $apstState -powerState $powerState -apstError $apstError -powerError $powerError
            }
            if ($vwcRequested) {
                $vwcState = $null
                $vwcError = $null
                try { if ($item.PSObject.Properties['VwcReadBack']) { $vwcState = $item.VwcReadBack } } catch { }
                try { if ($item.PSObject.Properties['VwcError']) { $vwcError = [string]$item.VwcError } } catch { }
                Set-NVMeVolatileWriteCacheControlsFromState -ctrls $ctrls -vwcState $vwcState -vwcError $vwcError
            }
            if ($tempRequested) {
                $tempState = $null
                $tempError = $null
                try { if ($item.PSObject.Properties['TempReadBack']) { $tempState = $item.TempReadBack } } catch { }
                try { if ($item.PSObject.Properties['TempError']) { $tempError = [string]$item.TempError } } catch { }
                Set-NVMeTemperatureThresholdControlsFromState -ctrls $ctrls -tempState $tempState -tempError $tempError
            }
            if ($wanRequested) {
                $wanState = $null
                $wanError = $null
                try { if ($item.PSObject.Properties['WanReadBack']) { $wanState = $item.WanReadBack } } catch { }
                try { if ($item.PSObject.Properties['WanError']) { $wanError = [string]$item.WanError } } catch { }
                Set-NVMeWriteAtomicityNormalControlsFromState -ctrls $ctrls -wanState $wanState -wanError $wanError
            }
            if ($hmbRequested) {
                $hmbState = $null
                $hmbError = $null
                try { if ($item.PSObject.Properties['HmbReadBack']) { $hmbState = $item.HmbReadBack } } catch { }
                try { if ($item.PSObject.Properties['HmbError']) { $hmbError = [string]$item.HmbError } } catch { }
                Set-NVMeHostMemoryBufferControlsFromState -ctrls $ctrls -hmbState $hmbState -hmbError $hmbError
            }
            if ($errRequested) {
                $errState = $null
                $errError = $null
                try { if ($item.PSObject.Properties['ErrReadBack']) { $errState = $item.ErrReadBack } } catch { }
                try { if ($item.PSObject.Properties['ErrError']) { $errError = [string]$item.ErrError } } catch { }
                Set-NVMeErrorRecoveryControlsFromState -ctrls $ctrls -errState $errState -errError $errError
            }
            if ($hctmRequested) {
                $hctmState = $null
                $hctmError = $null
                try { if ($item.PSObject.Properties['HctmReadBack']) { $hctmState = $item.HctmReadBack } } catch { }
                try { if ($item.PSObject.Properties['HctmError']) { $hctmError = [string]$item.HctmError } } catch { }
                Set-NVMeHostControlledThermalManagementControlsFromState -ctrls $ctrls -hctmState $hctmState -hctmError $hctmError
            }
            break
        }
    }
}


function Start-AsyncNVMeInterruptCoalescingHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $specs = [System.Collections.Generic.List[object]]::new()
    foreach ($device in $deviceList) {
        if (-not $deviceControls.ContainsKey($device)) { continue }
        $ctrls = $deviceControls[$device]
        if (-not $ctrls.ContainsKey('NVMeThreshold')) { continue }
        $path = Resolve-NVMePhysicalDrivePathForDevice -device $device -ctrls $ctrls
        if ([string]::IsNullOrWhiteSpace($path)) {
            if ($ctrls.ContainsKey('NVMeTimeLabel') -and $null -ne $ctrls.NVMeTimeLabel) {
                $ctrls.NVMeTimeLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTimeLabel
            }
            if ($ctrls.ContainsKey('NVMeApstPowerStatusLabel') -and $null -ne $ctrls.NVMeApstPowerStatusLabel) {
                $ctrls.NVMeApstPowerStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeApstPowerStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeVwcStatusLabel') -and $null -ne $ctrls.NVMeVwcStatusLabel) {
                $ctrls.NVMeVwcStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeVwcStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeTempStatusLabel') -and $null -ne $ctrls.NVMeTempStatusLabel) {
                $ctrls.NVMeTempStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTempStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeWanStatusLabel') -and $null -ne $ctrls.NVMeWanStatusLabel) {
                $ctrls.NVMeWanStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeWanStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeHmbStatusLabel') -and $null -ne $ctrls.NVMeHmbStatusLabel) {
                $ctrls.NVMeHmbStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHmbStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeErrStatusLabel') -and $null -ne $ctrls.NVMeErrStatusLabel) {
                $ctrls.NVMeErrStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeErrStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeHctmStatusLabel') -and $null -ne $ctrls.NVMeHctmStatusLabel) {
                $ctrls.NVMeHctmStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeHctmStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeArbStatusLabel') -and $null -ne $ctrls.NVMeArbStatusLabel) {
                $ctrls.NVMeArbStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel
            }
            if ($ctrls.ContainsKey('NVMeNoqStatusLabel') -and $null -ne $ctrls.NVMeNoqStatusLabel) {
                $ctrls.NVMeNoqStatusLabel.Text = 'No PhysicalDrive path'
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeNoqStatusLabel
            }
            continue
        }
        if ($ctrls.ContainsKey('NVMeDrivePath')) { $ctrls.NVMeDrivePath = [string]$path }
        $tempSelection = Get-NVMeTemperatureSelectionFromControls -ctrls $ctrls
        $errSelection = Get-NVMeErrorRecoverySelectionFromControls -ctrls $ctrls
        [void]$specs.Add([PSCustomObject]@{ Key = [string]$device.RegistryPath; DrivePath = [string]$path; ReadKind = 'All'; TempSensorSelect = [int]$tempSelection.SensorSelect; TempThresholdType = [int]$tempSelection.ThresholdType; ErrNamespaceId = [uint32]$errSelection.NamespaceId })
    }
    if ($specs.Count -eq 0) { return }
    $script:nvmeHydrationTask = Start-PolledRunspaceTask -TaskName 'NVMeICHydration' -ScriptText (Get-AsyncNVMeInterruptCoalescingWorkerScript) -Arguments @(@($specs)) -OnCompleted {
        param($results)
        Apply-AsyncNVMeInterruptCoalescingResultsToUI -resultItems $results
    } -OnFailed {
        param($err)
        Write-Host "Deferred NVMe interrupt coalescing hydration failed: $err" -ForegroundColor Red
    }
}


function Start-AsyncNVMeArbitrationApply {
    param(
        [System.Windows.Forms.Button]$button,
        [hashtable]$ctrls,
        [string]$drivePath,
        [int]$arbitrationBurst,
        [int]$lowPriorityWeight,
        [int]$mediumPriorityWeight,
        [int]$highPriorityWeight
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $onCompleted = {
        param($results)
        try {
            $items = @($results)
            if ($items.Count -gt 0 -and $items[0].Success) {
                Set-NVMeArbitrationControlsFromState -ctrls $ctrls -arbState $items[0].ArbReadBack -arbError $null
            } elseif ($items.Count -gt 0) {
                $detail = if ($items[0].Error) { [string]$items[0].Error } else { 'Set failed' }
                $isUnsupported = $false
                try { if ($items[0].PSObject.Properties['Unsupported']) { $isUnsupported = [bool]$items[0].Unsupported } } catch { }
                if ($isUnsupported -and $ctrls.ContainsKey('NVMeArbStatusLabel') -and $null -ne $ctrls.NVMeArbStatusLabel) { $ctrls.NVMeArbStatusLabel.Text = Format-NVMeArbitrationUnsupportedLabel; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel }
                elseif ($ctrls.ContainsKey('NVMeArbStatusLabel') -and $null -ne $ctrls.NVMeArbStatusLabel) { $ctrls.NVMeArbStatusLabel.Text = ('Set failed: {0}' -f $detail); Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel }
                if (-not $isUnsupported) { Show-DarkMessageBox -Message ("Failed to apply NVMe Arbitration.`n`n$detail") -Title 'Error' -Icon Error }
            }
        } finally {
            if ($null -ne $button) { $button.Text = 'SET ARB' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()
    $onFailed = {
        param($err)
        try {
            $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
            $isUnsupported = Test-NVMeArbitrationUnsupportedError -Message $detail
            if ($ctrls.ContainsKey('NVMeArbStatusLabel') -and $null -ne $ctrls.NVMeArbStatusLabel) { $ctrls.NVMeArbStatusLabel.Text = if ($isUnsupported) { Format-NVMeArbitrationUnsupportedLabel } else { ('ERR: {0}' -f $detail) }; Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeArbStatusLabel }
            if (-not $isUnsupported) { Show-DarkMessageBox -Message ("Failed to apply NVMe Arbitration.`n`n$detail") -Title 'Error' -Icon Error }
        } finally {
            if ($null -ne $button) { $button.Text = 'SET ARB' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()
    Start-PolledRunspaceTask -TaskName 'NVMeArbitrationApply' -ScriptText (Get-AsyncNVMeArbitrationApplyWorkerScript) -Arguments @($drivePath, $arbitrationBurst, $lowPriorityWeight, $mediumPriorityWeight, $highPriorityWeight) -OnCompleted $onCompleted -OnFailed $onFailed | Out-Null
}

