                if (-not $isUnsupported) { Show-DarkMessageBox -Message ("Failed to set NVMe temperature threshold.`n`n$detail") -Title 'Error' -Icon Error }
            }
        } finally {
            if ($null -ne $button) { $button.Text = 'SET TEMP' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()
    $onFailed = {
        param($err)
        try {
            $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
            $isUnsupported = (Test-NVMeTemperatureThresholdUnsupportedError -Message $detail)
            if (-not $isUnsupported) { $isUnsupported = Test-NVMeInterruptCoalescingSetUnsupportedError -Message $detail }
            if ($ctrls.ContainsKey('NVMeTempStatusLabel') -and $null -ne $ctrls.NVMeTempStatusLabel) {
                $ctrls.NVMeTempStatusLabel.Text = if ($isUnsupported) { (Format-NVMeTemperatureThresholdUnsupportedLabel -SensorSelect $sensorSelect -ThresholdType $thresholdType) } else { ('TEMP set failed: {0}' -f $detail) }
                Sync-ScrollableLabelIfNeeded -label $ctrls.NVMeTempStatusLabel
            }
