        }
    }.GetNewClosure()
    $script:nvmeTempApplyTask = Start-PolledRunspaceTask -TaskName 'NVMeTempThresholdApply' -ScriptText (Get-AsyncNVMeTemperatureThresholdApplyWorkerScript) -Arguments @($drivePath, $sensorSelect, $thresholdType, $thresholdCelsius) -OnCompleted $onCompleted -OnFailed $onFailed
}

