function ConvertTo-HdaMmioHexAddress {
    param([Parameter(Mandatory=$true)][uint64]$Address)
    return ('0x{0:X}' -f $Address)
}

function Read-HdaMmio16 {
    param([Parameter(Mandatory=$true)][uint64]$Address,[AllowNull()][string]$Context)
    $addrText = ConvertTo-HdaMmioHexAddress -Address $Address
    $stdout = Invoke-RWECommand -Command ('R16 {0}' -f $addrText)
    return [uint16]((Convert-RWEverythingOutputToUInt64 $stdout $Context) -band 0xFFFF)
}

function Read-HdaMmio8 {
    param([Parameter(Mandatory=$true)][uint64]$Address,[AllowNull()][string]$Context)
    $alignedAddress = [uint64]($Address - ([uint64]($Address % 2)))
    $shift = [int](($Address - $alignedAddress) * 8)
    $raw = Read-HdaMmio16 -Address $alignedAddress -Context $Context
    return [byte]((([int]$raw) -shr $shift) -band 0xFF)
}

function Write-HdaMmio16 {
    param([Parameter(Mandatory=$true)][uint64]$Address,[Parameter(Mandatory=$true)][uint16]$Value,[AllowNull()][string]$Context)
    $addrText = ConvertTo-HdaMmioHexAddress -Address $Address
    $valueText = ('0x{0:X4}' -f ([uint16]$Value))
    [void](Invoke-RWECommand -Command ('W16 {0} {1}' -f $addrText, $valueText) -AllowEmptyOutput)
}

function Write-HdaMmio8 {
    param([Parameter(Mandatory=$true)][uint64]$Address,[Parameter(Mandatory=$true)][byte]$Value,[AllowNull()][string]$Context)
    $alignedAddress = [uint64]($Address - ([uint64]($Address % 2)))
    $shift = [int](($Address - $alignedAddress) * 8)
    if ($shift -eq 0 -and $Context -match '(?i)\b(CORBCTL|RIRBCTL)\b|\b(CORB|RIRB) DMA\b') {
        Write-HdaMmio16 -Address $alignedAddress -Value ([uint16]([int]$Value -band 0xFF)) -Context $Context
        return
    }
    $before = Read-HdaMmio16 -Address $alignedAddress -Context ('{0} byte-write pre-read aligned=0x{1:X}' -f $Context, $alignedAddress)
    $mask = [int](0xFF -shl $shift)
    $merged = [uint16]((([int]$before) -band ((-bnot $mask) -band 0xFFFF)) -bor ((([int]$Value) -band 0xFF) -shl $shift))
    Write-HdaMmio16 -Address $alignedAddress -Value $merged -Context $Context
}

function Get-HdaRintcntEffectiveResponses {
    param([Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Value)
    if ($Value -eq 0) { return 256 }
    return $Value
}

function Format-HdaRintcntLabel {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Value,
        [AllowNull()][object]$RirbDmaRunning,
        [AllowNull()][object]$RintInterruptEnabled,
        [AllowNull()][uint64]$Bar0
    )
    $responses = Get-HdaRintcntEffectiveResponses -Value $Value
    $parts = [System.Collections.Generic.List[string]]::new()
    [void]$parts.Add(('RINTCNT=0x{0:X2}' -f $Value))
    [void]$parts.Add(('{0} codec responses/IRQ' -f $responses))
    [void]$parts.Add(('rate=codec responses/s÷{0}' -f $responses))
    if ($null -ne $RirbDmaRunning) { [void]$parts.Add(('RIRB DMA {0}' -f $(if ([bool]$RirbDmaRunning) { 'RUN' } else { 'STOP' }))) }
    if ($null -ne $RintInterruptEnabled) { [void]$parts.Add(('RINT IRQ {0}' -f $(if ([bool]$RintInterruptEnabled) { 'on' } else { 'off' }))) }
    if ($Bar0 -gt 0) { [void]$parts.Add(('BAR0=0x{0:X}' -f $Bar0)) }
    return ($parts.ToArray() -join ' | ')
}

function Get-HdaRingSizeEntryCount {
    param([Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Value)
    switch ($Value) {
        0 { return 2 }
        1 { return 16 }
        2 { return 256 }
        default { return 0 }
    }
}

function Get-HdaRingSizeBytes {
    param([Parameter(Mandatory=$true)][ValidateSet('CORB','RIRB')][string]$Kind,[Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Value)
    if ($Kind -eq 'CORB') {
        switch ($Value) {
            0 { return 8 }
            1 { return 64 }
            2 { return 1024 }
            default { return 0 }
        }
    }
    switch ($Value) {
        0 { return 16 }
        1 { return 128 }
        2 { return 2048 }
        default { return 0 }
    }
}

function Get-HdaSupportedRingSizeValues {
    param([Parameter(Mandatory=$true)][ValidateRange(0,15)][int]$CapabilityMask)
    $values = New-Object System.Collections.Generic.List[int]
    for ($i = 0; $i -le 2; $i++) {
        if (($CapabilityMask -band ([uint64]1 -shl $i)) -ne 0) { [void]$values.Add([int]$i) }
    }
    return [int[]]$values.ToArray()
}

function Format-HdaSupportedRingSizesText {
    param([Parameter(Mandatory=$true)][ValidateRange(0,15)][int]$CapabilityMask)
    $values = New-Object System.Collections.Generic.List[int]
    foreach ($value in @(Get-HdaSupportedRingSizeValues -CapabilityMask $CapabilityMask)) {
        if ($null -eq $value) { continue }
        if ($value -is [System.Array]) {
            foreach ($nested in @($value)) {
                try { [void]$values.Add([int]$nested) } catch { }
            }
            continue
        }
        try { [void]$values.Add([int]$value) } catch { }
    }
    if ($values.Count -eq 0) { return 'none' }
    return (($values.ToArray() | ForEach-Object { [string][int]$_ }) -join ',')
}

function Format-HdaRingSizeLabel {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('CORB','RIRB')][string]$Kind,
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Value,
        [Parameter(Mandatory=$true)][ValidateRange(0,15)][int]$CapabilityMask,
        [AllowNull()][object]$DmaRunning,
        [AllowNull()][uint64]$Bar0
    )
    $entries = Get-HdaRingSizeEntryCount -Value $Value
    $bytes = Get-HdaRingSizeBytes -Kind $Kind -Value $Value
    $parts = [System.Collections.Generic.List[string]]::new()
    [void]$parts.Add(('{0}SIZE={1}' -f $Kind, $Value))
    if ($Value -le 2) { [void]$parts.Add(('{0} entries / {1} B' -f $entries, $bytes)) } else { [void]$parts.Add('reserved selection') }
    [void]$parts.Add(('cap: {0}' -f (Format-HdaSupportedRingSizesText -CapabilityMask $CapabilityMask)))
    if ($null -ne $DmaRunning) { [void]$parts.Add(('{0} DMA {1}' -f $Kind, $(if ([bool]$DmaRunning) { 'RUN' } else { 'STOP' }))) }
    if ($Bar0 -gt 0) { [void]$parts.Add(('BAR0=0x{0:X}' -f $Bar0)) }
    return ($parts.ToArray() -join ' | ')
}

function Get-HdaRintcnt {
    param(
        [Parameter(Mandatory=$true)][uint64]$HdaBar0,
        [AllowNull()][string]$Key,
        [AllowNull()][string]$DeviceName
    )
    if ($HdaBar0 -eq 0) { throw ('HDA MMIO BAR0 is zero for {0}.' -f $Key) }
    $corbctlAddress = [uint64]($HdaBar0 + 0x4C)
    $corbsizeAddress = [uint64]($HdaBar0 + 0x4E)
    $rintcntAddress = [uint64]($HdaBar0 + 0x5A)
    $rirbctlAddress = [uint64]($HdaBar0 + 0x5C)
    $rirbsizeAddress = [uint64]($HdaBar0 + 0x5E)
    try {
        $raw = Read-HdaMmio16 -Address $rintcntAddress -Context ('HDA RINTCNT read Key={0} BAR0=0x{1:X} Address=0x{2:X}' -f $Key, $HdaBar0, $rintcntAddress)
        $value = [int]($raw -band 0xFF)
        $corbCtl = Read-HdaMmio8 -Address $corbctlAddress -Context ('HDA CORBCTL read Key={0} BAR0=0x{1:X} Address=0x{2:X}' -f $Key, $HdaBar0, $corbctlAddress)
        $ctl = Read-HdaMmio8 -Address $rirbctlAddress -Context ('HDA RIRBCTL read Key={0} BAR0=0x{1:X} Address=0x{2:X}' -f $Key, $HdaBar0, $rirbctlAddress)
        $corbRaw = Read-HdaMmio8 -Address $corbsizeAddress -Context ('HDA CORBSIZE read Key={0} BAR0=0x{1:X} Address=0x{2:X}' -f $Key, $HdaBar0, $corbsizeAddress)
        $rirbRaw = Read-HdaMmio8 -Address $rirbsizeAddress -Context ('HDA RIRBSIZE read Key={0} BAR0=0x{1:X} Address=0x{2:X}' -f $Key, $HdaBar0, $rirbsizeAddress)
        $running = (($ctl -band 0x02) -ne 0)
        $irq = (($ctl -band 0x01) -ne 0)
        $corbRunning = (($corbCtl -band 0x02) -ne 0)
        $corbSize = [int]($corbRaw -band 0x03)
        $rirbSize = [int]($rirbRaw -band 0x03)
        $corbCap = [int]((([int]$corbRaw) -shr 4) -band 0x0F)
        $rirbCap = [int]((([int]$rirbRaw) -shr 4) -band 0x0F)
        [pscustomobject]@{
            Key = [string]$Key
            DeviceName = [string]$DeviceName
            HdaBar0 = [uint64]$HdaBar0
            CorbctlAddress = [uint64]$corbctlAddress
            CorbSizeAddress = [uint64]$corbsizeAddress
            RintcntAddress = [uint64]$rintcntAddress
            RirbctlAddress = [uint64]$rirbctlAddress
            RirbSizeAddress = [uint64]$rirbsizeAddress
            RawRegister = [uint16]$raw
            Rintcnt = [int]$value
            ResponsesPerInterrupt = [int](Get-HdaRintcntEffectiveResponses -Value $value)
            CorbCtl = [byte]$corbCtl
            RirbCtl = [byte]$ctl
            CorbDmaRunning = [bool]$corbRunning
            RirbDmaRunning = [bool]$running
            RintInterruptEnabled = [bool]$irq
            CorbSizeRaw = [byte]$corbRaw
            RirbSizeRaw = [byte]$rirbRaw
            CorbSize = [int]$corbSize
            RirbSize = [int]$rirbSize
            CorbSupportedMask = [int]$corbCap
            RirbSupportedMask = [int]$rirbCap
            CorbSupportedSizes = [int[]]@(Get-HdaSupportedRingSizeValues -CapabilityMask $corbCap)
            RirbSupportedSizes = [int[]]@(Get-HdaSupportedRingSizeValues -CapabilityMask $rirbCap)
            DisplayText = (Format-HdaRintcntLabel -Value $value -RirbDmaRunning $running -RintInterruptEnabled $irq -Bar0 $HdaBar0)
            CorbSizeDisplayText = (Format-HdaRingSizeLabel -Kind 'CORB' -Value $corbSize -CapabilityMask $corbCap -DmaRunning $corbRunning -Bar0 $HdaBar0)
            RirbSizeDisplayText = (Format-HdaRingSizeLabel -Kind 'RIRB' -Value $rirbSize -CapabilityMask $rirbCap -DmaRunning $running -Bar0 $HdaBar0)
        }
    } catch {
        throw [System.InvalidOperationException]::new(('HDA state read failed for Key={0}, Device="{1}", BAR0=0x{2:X}: {3}' -f $Key, $DeviceName, $HdaBar0, $_.Exception.Message), $_.Exception)
    }
}

function Wait-HdaRirbDmaState {
    param(
        [Parameter(Mandatory=$true)][uint64]$RirbCtlAddress,
        [Parameter(Mandatory=$true)][bool]$Running,
        [int]$TimeoutMs = 125,
        [AllowNull()][string]$Context
    )
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $last = [byte]0
    do {
        $last = Read-HdaMmio8 -Address $RirbCtlAddress -Context ('HDA RIRBCTL wait {0}' -f $Context)
        if (((($last -band 0x02) -ne 0) -eq $Running)) { return $last }
        Start-Sleep -Milliseconds 1
    } while ($sw.ElapsedMilliseconds -lt $TimeoutMs)
    throw ('Timed out after {0} ms waiting for RIRB DMA {1}. Address=0x{2:X}; LastRIRBCTL=0x{3:X2}; Context={4}' -f $TimeoutMs, $(if ($Running) { 'RUN' } else { 'STOP' }), $RirbCtlAddress, [int]$last, $Context)
}

function Wait-HdaCorbDmaState {
    param(
        [Parameter(Mandatory=$true)][uint64]$CorbCtlAddress,
        [Parameter(Mandatory=$true)][bool]$Running,
        [int]$TimeoutMs = 125,
        [AllowNull()][string]$Context
    )
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $last = [byte]0
    do {
        $last = Read-HdaMmio8 -Address $CorbCtlAddress -Context ('HDA CORBCTL wait {0}' -f $Context)
        if (((($last -band 0x02) -ne 0) -eq $Running)) { return $last }
        Start-Sleep -Milliseconds 1
    } while ($sw.ElapsedMilliseconds -lt $TimeoutMs)
    throw ('Timed out after {0} ms waiting for CORB DMA {1}. Address=0x{2:X}; LastCORBCTL=0x{3:X2}; Context={4}' -f $TimeoutMs, $(if ($Running) { 'RUN' } else { 'STOP' }), $CorbCtlAddress, [int]$last, $Context)
}

function Set-HdaRingSize {
    param(
        [Parameter(Mandatory=$true)][uint64]$HdaBar0,
        [Parameter(Mandatory=$true)][ValidateSet('CORB','RIRB')][string]$Kind,
        [Parameter(Mandatory=$true)][ValidateRange(0,2)][int]$Value,
        [AllowNull()][string]$Key,
        [AllowNull()][string]$DeviceName
    )
    if ($HdaBar0 -eq 0) { throw ('HDA MMIO BAR0 is zero for {0}.' -f $Key) }
    $sizeOffset = if ($Kind -eq 'CORB') { 0x4E } else { 0x5E }
    $ctlOffset = if ($Kind -eq 'CORB') { 0x4C } else { 0x5C }
    $sizeAddress = [uint64]($HdaBar0 + $sizeOffset)
    $ctlAddress = [uint64]($HdaBar0 + $ctlOffset)
    $originalCtl = [byte]0
    $stoppedForWrite = $false
    try {
        $beforeSize = Read-HdaMmio8 -Address $sizeAddress -Context ('HDA {0}SIZE pre-write Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
        $capabilityMask = [int]((([int]$beforeSize) -shr 4) -band 0x0F)
        $requestedMask = [int](1 -shl $Value)
        if (($capabilityMask -band $requestedMask) -eq 0) {
            throw ('HDA {0}SIZE unsupported selection for Key={1}. Requested={2}; CapabilityMask=0x{3:X}; Supported={4}; RawBefore=0x{5:X2}; BAR0=0x{6:X}; Address=0x{7:X}' -f $Kind, $Key, $Value, $capabilityMask, (Format-HdaSupportedRingSizesText -CapabilityMask $capabilityMask), [int]$beforeSize, $HdaBar0, $sizeAddress)
        }
        $originalCtl = Read-HdaMmio8 -Address $ctlAddress -Context ('HDA {0}CTL pre-write Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
        $wasRunning = (($originalCtl -band 0x02) -ne 0)
        if ($wasRunning) {
            Write-HdaMmio8 -Address $ctlAddress -Value ([byte]($originalCtl -band 0xFD)) -Context ('HDA {0} DMA stop Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
            if ($Kind -eq 'CORB') { [void](Wait-HdaCorbDmaState -CorbCtlAddress $ctlAddress -Running $false -Context ('before {0}SIZE write Key={1}' -f $Kind, $Key)) } else { [void](Wait-HdaRirbDmaState -RirbCtlAddress $ctlAddress -Running $false -Context ('before {0}SIZE write Key={1}' -f $Kind, $Key)) }
            $stoppedForWrite = $true
        }
        $newSize = [byte]((([int]$beforeSize) -band 0xFC) -bor ([int]$Value -band 0x03))
        Write-HdaMmio8 -Address $sizeAddress -Value $newSize -Context ('HDA {0}SIZE write Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
        $afterSize = Read-HdaMmio8 -Address $sizeAddress -Context ('HDA {0}SIZE verify Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
        if ((([int]$afterSize) -band 0x03) -ne ([int]$Value -band 0x03)) {
            throw ('HDA {0}SIZE verify failed for Key={1}. Requested={2}; BeforeRaw=0x{3:X2}; WriteRaw=0x{4:X2}; ReadBackRaw=0x{5:X2}; CapabilityMask=0x{6:X}; BAR0=0x{7:X}; Address=0x{8:X}' -f $Kind, $Key, $Value, [int]$beforeSize, [int]$newSize, [int]$afterSize, $capabilityMask, $HdaBar0, $sizeAddress)
        }
        if ($stoppedForWrite) {
            Write-HdaMmio8 -Address $ctlAddress -Value $originalCtl -Context ('HDA {0} DMA restore Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0)
            if ($Kind -eq 'CORB') { [void](Wait-HdaCorbDmaState -CorbCtlAddress $ctlAddress -Running $true -Context ('after {0}SIZE write Key={1}' -f $Kind, $Key)) } else { [void](Wait-HdaRirbDmaState -RirbCtlAddress $ctlAddress -Running $true -Context ('after {0}SIZE write Key={1}' -f $Kind, $Key)) }
        }
        return Get-HdaRintcnt -HdaBar0 $HdaBar0 -Key $Key -DeviceName $DeviceName
    } catch {
        if ($stoppedForWrite) {
            try { Write-HdaMmio8 -Address $ctlAddress -Value $originalCtl -Context ('HDA {0} DMA restore after failure Key={1} BAR0=0x{2:X}' -f $Kind, $Key, $HdaBar0) } catch { }
        }
        throw [System.InvalidOperationException]::new(('HDA {0}SIZE write failed for Key={1}, Device="{2}", BAR0=0x{3:X}, Value={4}: {5}' -f $Kind, $Key, $DeviceName, $HdaBar0, $Value, $_.Exception.Message), $_.Exception)
    }
}

function Set-HdaRintcnt {
    param(
        [Parameter(Mandatory=$true)][uint64]$HdaBar0,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Value,
        [AllowNull()][string]$Key,
        [AllowNull()][string]$DeviceName
    )
    if ($HdaBar0 -eq 0) { throw ('HDA MMIO BAR0 is zero for {0}.' -f $Key) }
    $rintcntAddress = [uint64]($HdaBar0 + 0x5A)
    $rirbctlAddress = [uint64]($HdaBar0 + 0x5C)
    $originalCtl = [byte]0
    $stoppedForWrite = $false
    try {
        $originalCtl = Read-HdaMmio8 -Address $rirbctlAddress -Context ('HDA RIRBCTL pre-write Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
        $wasRunning = (($originalCtl -band 0x02) -ne 0)
        if ($wasRunning) {
            Write-HdaMmio8 -Address $rirbctlAddress -Value ([byte]($originalCtl -band 0xFD)) -Context ('HDA RIRB DMA stop Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
            [void](Wait-HdaRirbDmaState -RirbCtlAddress $rirbctlAddress -Running $false -Context ('before RINTCNT write Key={0}' -f $Key))
            $stoppedForWrite = $true
        }
        $before = Read-HdaMmio16 -Address $rintcntAddress -Context ('HDA RINTCNT pre-write Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
        $newRaw = [uint16]((([int]$before) -band 0xFF00) -bor ([int]$Value -band 0xFF))
        Write-HdaMmio16 -Address $rintcntAddress -Value $newRaw -Context ('HDA RINTCNT write Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
        $after = Read-HdaMmio16 -Address $rintcntAddress -Context ('HDA RINTCNT verify Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
        if ((([int]$after) -band 0xFF) -ne ([int]$Value -band 0xFF)) {
            throw ('HDA RINTCNT verify failed for Key={0}. Requested=0x{1:X2}; BeforeRaw=0x{2:X4}; WriteRaw=0x{3:X4}; ReadBackRaw=0x{4:X4}; BAR0=0x{5:X}; Address=0x{6:X}' -f $Key, $Value, [int]$before, [int]$newRaw, [int]$after, $HdaBar0, $rintcntAddress)
        }
        if ($stoppedForWrite) {
            Write-HdaMmio8 -Address $rirbctlAddress -Value $originalCtl -Context ('HDA RIRB DMA restore Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0)
            [void](Wait-HdaRirbDmaState -RirbCtlAddress $rirbctlAddress -Running $true -Context ('after RINTCNT write Key={0}' -f $Key))
        }
        return Get-HdaRintcnt -HdaBar0 $HdaBar0 -Key $Key -DeviceName $DeviceName
    } catch {
        if ($stoppedForWrite) {
            try { Write-HdaMmio8 -Address $rirbctlAddress -Value $originalCtl -Context ('HDA RIRB DMA restore after failure Key={0} BAR0=0x{1:X}' -f $Key, $HdaBar0) } catch { }
        }
        throw [System.InvalidOperationException]::new(('HDA RINTCNT write failed for Key={0}, Device="{1}", BAR0=0x{2:X}, Value=0x{3:X2}: {4}' -f $Key, $DeviceName, $HdaBar0, $Value, $_.Exception.Message), $_.Exception)
    }
}

function ConvertTo-HdaEnumRelativePath {
    param([AllowNull()][object]$Path)
    if ($null -eq $Path) { return $null }
    $p = [string]$Path
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $p = $p -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
    $p = $p -replace '^HKLM:\\',''
    $p = $p -replace '^HKEY_LOCAL_MACHINE\\',''
    $p = $p.Trim('\')
    $prefix = 'SYSTEM\CurrentControlSet\Enum\'
    if ($p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) { return $p.Substring($prefix.Length) }
    return $p
}

function Resolve-HdaMmioBaseForDevice {
    param([Parameter(Mandatory=$true)][object]$Device,[hashtable]$Controls,[hashtable]$DeviceMap)
    if ($Controls -and $Controls.ContainsKey('HDAMmioBase')) {
        try { if ([uint64]$Controls['HDAMmioBase'] -gt 0) { return [uint64]$Controls['HDAMmioBase'] } } catch { }
    }
    if ($null -eq $DeviceMap) { $DeviceMap = $globalDeviceAddressMap }
    if ($null -eq $DeviceMap) { $DeviceMap = Get-Device-Addresses }
    $candidates = [System.Collections.Generic.List[string]]::new()
    foreach ($v in @(
        $(if ($Controls -and $Controls.ContainsKey('HDAPNPID')) { $Controls['HDAPNPID'] } else { $null }),
        $(if ($Controls -and $Controls.ContainsKey('HDARegistryPath')) { $Controls['HDARegistryPath'] } else { $null }),
        (Get-PropValue $Device 'PNPID'),
        (Get-PropValue $Device 'InstanceId'),
        (Get-PropValue $Device 'RegistryPath'),
        (Get-PropValue $Device 'PSPath'),
        (Get-PropValue $Device 'DeviceKey')
    )) {
        if ($null -eq $v) { continue }
        $text = [string]$v
        if ([string]::IsNullOrWhiteSpace($text)) { continue }
        [void]$candidates.Add($text)
        $rel = ConvertTo-HdaEnumRelativePath -Path $text
        if (-not [string]::IsNullOrWhiteSpace($rel)) { [void]$candidates.Add($rel) }
    }
    foreach ($candidate in @($candidates.ToArray())) {
        foreach ($variant in @($candidate, ($candidate -replace '\\','\\'), ($candidate -replace '\\','\'))) {
            if ([string]::IsNullOrWhiteSpace($variant)) { continue }
            try {
                if ($DeviceMap.ContainsKey($variant) -and [uint64]$DeviceMap[$variant] -gt 0) {
                    $base = [uint64]$DeviceMap[$variant]
                    if ($Controls) { $Controls['HDAMmioBase'] = $base }
                    return $base
                }
            } catch { }
        }
    }
    $token = $null
    try {
        foreach ($candidate in @($candidates.ToArray())) {
            $token = [DeviceTweakerPathHelpers]::ExtractPciVenDevToken([string]$candidate)
            if (-not [string]::IsNullOrWhiteSpace($token)) { break }
        }
    } catch { $token = $null }
    if (-not [string]::IsNullOrWhiteSpace($token)) {
        foreach ($k in @($DeviceMap.Keys)) {
            try {
                if ([string]$k -like ('*{0}*' -f $token) -and [uint64]$DeviceMap[$k] -gt 0) {
                    $base = [uint64]$DeviceMap[$k]
                    if ($Controls) { $Controls['HDAMmioBase'] = $base }
                    return $base
                }
            } catch { }
        }
    }
    $known = ($candidates.ToArray() | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) } | Select-Object -Unique) -join ' | '
    throw ('Cannot resolve HDA MMIO BAR0. No Win32_PNPAllocatedResource memory address matched device keys: {0}' -f $known)
}

function Format-HdaRingSizeComboItemText {
    param([Parameter(Mandatory=$true)][ValidateRange(0,2)][int]$Value)
    return ('{0} | {1} entries' -f $Value, (Get-HdaRingSizeEntryCount -Value $Value))
}

function Set-HdaRingSizeComboItems {
    param(
        [AllowNull()][object]$Combo,
        [Parameter(Mandatory=$true)][ValidateRange(0,2)][int]$Value,
        [AllowNull()][object]$SupportedSizes
    )
    if (-not ($Combo -is [System.Windows.Forms.ComboBox])) { return }
    $items = New-Object System.Collections.Generic.List[int]
    foreach ($v in @($SupportedSizes)) {
        try {
            $iv = [int]$v
            if ($iv -ge 0 -and $iv -le 2 -and -not $items.Contains($iv)) { [void]$items.Add($iv) }
        } catch { }
    }
    if (-not $items.Contains([int]$Value)) { [void]$items.Add([int]$Value) }
    if ($items.Count -eq 0) { for ($i = 0; $i -le 2; $i++) { [void]$items.Add($i) } }
    $sorted = @($items.ToArray() | Sort-Object)
    $targetText = Format-HdaRingSizeComboItemText -Value $Value
    try { $Combo.BeginUpdate() } catch { }
    try {
        $Combo.Items.Clear()
        foreach ($iv in $sorted) { [void]$Combo.Items.Add((Format-HdaRingSizeComboItemText -Value ([int]$iv))) }
        $selected = -1
        for ($i = 0; $i -lt $Combo.Items.Count; $i++) {
            if ([string]$Combo.Items[$i] -eq $targetText) { $selected = $i; break }
        }
        if ($selected -ge 0) { $Combo.SelectedIndex = $selected }
    } finally {
        try { $Combo.EndUpdate() } catch { }
    }
}

function Get-HdaRingSizeComboSelection {
    param([AllowNull()][object]$Combo,[Parameter(Mandatory=$true)][ValidateSet('CORB','RIRB')][string]$Kind)
    if (-not ($Combo -is [System.Windows.Forms.ComboBox])) { throw ('HDA {0}SIZE combo box is not available.' -f $Kind) }
    $text = [string]$Combo.SelectedItem
    if ($text -match '^\s*([0-2])\b') { return [int]$Matches[1] }
    if ($Combo.SelectedIndex -ge 0 -and $Combo.SelectedIndex -le 2) { return [int]$Combo.SelectedIndex }
    throw ('HDA {0}SIZE selection is invalid: "{1}".' -f $Kind, $text)
}

function Set-HdaRingSizeControlsFromState {
    param([hashtable]$Controls,[AllowNull()][object]$State)
    if ($null -eq $Controls -or $null -eq $State) { return }
    if ($Controls.ContainsKey('HDACorbSizeCombo')) {
        Set-HdaRingSizeComboItems -Combo $Controls['HDACorbSizeCombo'] -Value ([Math]::Max(0, [Math]::Min(2, [int]$State.CorbSize))) -SupportedSizes $State.CorbSupportedSizes
    }
    if ($Controls.ContainsKey('HDARirbSizeCombo')) {
        Set-HdaRingSizeComboItems -Combo $Controls['HDARirbSizeCombo'] -Value ([Math]::Max(0, [Math]::Min(2, [int]$State.RirbSize))) -SupportedSizes $State.RirbSupportedSizes
    }
    if ($Controls.ContainsKey('HDACorbSizeStatusLabel') -and $Controls['HDACorbSizeStatusLabel'] -is [System.Windows.Forms.Label]) {
        $Controls['HDACorbSizeStatusLabel'].Text = [string]$State.CorbSizeDisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($Controls['HDACorbSizeStatusLabel']) } catch { }
    }
    if ($Controls.ContainsKey('HDARirbSizeStatusLabel') -and $Controls['HDARirbSizeStatusLabel'] -is [System.Windows.Forms.Label]) {
        $Controls['HDARirbSizeStatusLabel'].Text = [string]$State.RirbSizeDisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($Controls['HDARirbSizeStatusLabel']) } catch { }
    }
}

function Set-HdaRintcntControlsFromState {
    param([hashtable]$Controls,[AllowNull()][object]$State)
    if ($null -eq $Controls -or $null -eq $State) { return }
    if ($Controls.ContainsKey('HDARintcntValue') -and $Controls['HDARintcntValue'] -is [System.Windows.Forms.NumericUpDown]) {
        $Controls['HDARintcntValue'].Value = [decimal]([Math]::Max(0, [Math]::Min(255, [int]$State.Rintcnt)))
    }
    if ($Controls.ContainsKey('HDARintcntStatusLabel') -and $Controls['HDARintcntStatusLabel'] -is [System.Windows.Forms.Label]) {
        $Controls['HDARintcntStatusLabel'].Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($Controls['HDARintcntStatusLabel']) } catch { }
    }
    Set-HdaRingSizeControlsFromState -Controls $Controls -State $State
    if ($Controls.ContainsKey('HDAMmioBase')) { $Controls['HDAMmioBase'] = [uint64]$State.HdaBar0 }
}

function Get-AsyncHdaRintcntWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'ConvertTo-HdaMmioHexAddress'),
        (Get-FunctionDefinitionText 'Read-HdaMmio8'),
        (Get-FunctionDefinitionText 'Read-HdaMmio16'),
        (Get-FunctionDefinitionText 'Get-HdaRintcntEffectiveResponses'),
        (Get-FunctionDefinitionText 'Format-HdaRintcntLabel'),
        (Get-FunctionDefinitionText 'Get-HdaRingSizeEntryCount'),
        (Get-FunctionDefinitionText 'Get-HdaRingSizeBytes'),
        (Get-FunctionDefinitionText 'Get-HdaSupportedRingSizeValues'),
        (Get-FunctionDefinitionText 'Format-HdaSupportedRingSizesText'),
        (Get-FunctionDefinitionText 'Format-HdaRingSizeLabel'),
        (Get-FunctionDefinitionText 'Get-HdaRintcnt')
    ) -join "`n`n"
    return @"
param(`$Specs, `$RWEPathArg)
`$ErrorActionPreference = 'Stop'
`$rwePath = if ([string]::IsNullOrWhiteSpace([string]`$RWEPathArg)) { 'C:\Program Files (x86)\RW-Everything\Rw.exe' } else { [string]`$RWEPathArg }
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$state = Get-HdaRintcnt -HdaBar0 ([uint64]`$spec.HdaBar0) -Key ([string]`$spec.Key) -DeviceName ([string]`$spec.DeviceName)
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = `$_.Exception.Message })
    }
}
return ,`$results.ToArray()
"@
}

