function Add-DeviceTweakerHdaFlatResult {
    param([System.Collections.Generic.List[object]]$Target,[AllowNull()][object]$Value)
    if ($null -eq $Target -or $null -eq $Value) { return }
    $base = $Value
    try { if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject } } catch { $base = $Value }
    if ($base -is [System.Array]) {
        foreach ($child in @($base)) { Add-DeviceTweakerHdaFlatResult -Target $Target -Value $child }
        return
    }
    [void]$Target.Add($Value)
}

function Set-HdaStatusLabelsToText {
    param([hashtable]$Controls,[AllowNull()][string]$Text)
    if ($null -eq $Controls) { return }
    foreach ($key in @('HDARintcntStatusLabel','HDACorbSizeStatusLabel','HDARirbSizeStatusLabel')) {
        if ($Controls.ContainsKey($key) -and $Controls[$key] -is [System.Windows.Forms.Label]) {
            $Controls[$key].Text = [string]$Text
            try { [DeviceEditorBuilder]::SyncScrollableLabel($Controls[$key]) } catch { }
        }
    }
}

function Apply-AsyncHdaRintcntResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerHdaFlatResult -Target $flatResults -Value $raw }
    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('HDARintcntValue')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        if ($result.Success -and $null -ne $result.State) {
            Set-HdaRintcntControlsFromState -Controls $ctrls -State $result.State
        } else {
            $errText = if ($null -eq $result.Error) { 'Unknown HDA RINTCNT error.' } else { [string]$result.Error }
            try {
                Write-Host ('[HDA RINTCNT] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[HDA RINTCNT] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            Set-HdaStatusLabelsToText -Controls $ctrls -Text ('ERR: {0}' -f $errText)
        }
    }
}

function Start-AsyncHdaRintcntHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('HDARintcntValue')) { continue }
        $label = $ctrls['HDARintcntStatusLabel']
        try {
            Set-HdaStatusLabelsToText -Controls $ctrls -Text 'Reading...'
            $base = Resolve-HdaMmioBaseForDevice -Device $device -Controls $ctrls -DeviceMap $globalDeviceAddressMap
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build HDA RINTCNT read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; HdaBar0 = [uint64]$base; DeviceName = [string](Get-PropValue $device 'DisplayName') })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[HDA RINTCNT] Read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[HDA RINTCNT] Read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                if ($errText -match 'Extended Capability ID 0x0015 was not found') { $label.Text = 'ReBAR not supported: ExtCap15 missing on this PCIe function.' }
                else { $label.Text = ('ERR: {0}' -f $errText) }
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
    if ($specs.Count -eq 0) { return }
    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'HdaRintcntHydration' -ScriptText (Get-AsyncHdaRintcntWorkerScript) -Arguments @(@($localSpec), $rwePath) -OnCompleted {
            param($Result)
            Apply-AsyncHdaRintcntResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred HDA RINTCNT hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred HDA RINTCNT hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
        }.GetNewClosure()
    }
}

function Start-AsyncHdaRintcntApply {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Value,[System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['HDARintcntStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $base = Resolve-HdaMmioBaseForDevice -Device $Device -Controls $Controls -DeviceMap $globalDeviceAddressMap
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build HDA RINTCNT apply key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; HdaBar0 = [uint64]$base; Value = [int]$Value; DeviceName = [string](Get-PropValue $Device 'DisplayName') }
        Start-PolledRunspaceTask -TaskName 'HdaRintcntApply' -ScriptText (Get-AsyncHdaRintcntApplyWorkerScript) -Arguments @($spec, $rwePath) -OnCompleted {
            param($Result)
            try { Apply-AsyncHdaRintcntResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Text = 'SET'; $Button.Enabled = $true; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Text = 'SET'; $Button.Enabled = $true; $Button.Invalidate() } } catch { }
            $errText = if ($err -and $err.Exception) { [string]$err.Exception.Message } else { [string]$err }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[HDA RINTCNT] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[HDA RINTCNT] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Text = 'SET'; $Button.Enabled = $true; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

function Start-AsyncHdaRingSizeApply {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][ValidateSet('CORB','RIRB')][string]$Kind,[Parameter(Mandatory=$true)][ValidateRange(0,2)][int]$Value,[System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $statusKey = if ($Kind -eq 'CORB') { 'HDACorbSizeStatusLabel' } else { 'HDARirbSizeStatusLabel' }
    $restoreText = if ($Kind -eq 'CORB') { 'SET CORB' } else { 'SET RIRB' }
    $label = if ($Controls.ContainsKey($statusKey)) { $Controls[$statusKey] } else { $null }
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('Writing {0}SIZE...' -f $Kind); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $base = Resolve-HdaMmioBaseForDevice -Device $Device -Controls $Controls -DeviceMap $globalDeviceAddressMap
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw ('Cannot build HDA {0}SIZE apply key: RegistryPath and DeviceKey are empty.' -f $Kind) }
        $spec = [pscustomobject]@{ Key = $key; HdaBar0 = [uint64]$base; Kind = [string]$Kind; Value = [int]$Value; DeviceName = [string](Get-PropValue $Device 'DisplayName') }
        Start-PolledRunspaceTask -TaskName ('Hda{0}SizeApply' -f $Kind) -ScriptText (Get-AsyncHdaRingSizeApplyWorkerScript) -Arguments @($spec, $rwePath) -OnCompleted {
            param($Result)
            try { Apply-AsyncHdaRintcntResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Text = $restoreText; $Button.Enabled = $true; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Text = $restoreText; $Button.Enabled = $true; $Button.Invalidate() } } catch { }
            $errText = if ($err -and $err.Exception) { [string]$err.Exception.Message } else { [string]$err }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host ('[HDA {0}SIZE] Apply preparation failed' -f $Kind) -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[HDA {0}SIZE] Apply preparation failed{1}{2}' -f $Kind, [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Text = $restoreText; $Button.Enabled = $true; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

