        (Get-FunctionDefinitionText 'Update-RealtekIntMitiV2TopologyInNicInfo')
        (Get-FunctionDefinitionText 'Read-NICIMOD')
        (Get-FunctionDefinitionText 'Get-XHCIInterrupterDeviceMap')
        (Get-FunctionDefinitionText 'Get-EffectiveUSBInterrupterReadCount')
        (Get-FunctionDefinitionText 'Read-ControllerIMOD')
    ) -join "`r`n`r`n"

    return @"
param(`$deviceSpecs, `$controllers, `$deviceMap, `$usbEnumResult, `$hidDevices, `$pollingRateLookup, `$audioLookupDetails, `$userDefinedDataArg, `$rwePathArg, `$globalIntervalArg, `$globalHCSPARAMSOffsetArg, `$globalRTSOFFArg)
`$script:pnpIdCache = @{}
`$script:audioLookupDetails = if (`$audioLookupDetails) { `$audioLookupDetails } else { @{} }
`$script:userDefinedData = if (`$userDefinedDataArg) { `$userDefinedDataArg } else { @{} }
`$globalInterval = `$globalIntervalArg
`$globalHCSPARAMSOffset = `$globalHCSPARAMSOffsetArg
`$globalRTSOFF = `$globalRTSOFFArg
`$rwePath = `$rwePathArg
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))

$defs

`$controllerLookup = [System.Collections.Generic.List[DeviceTweakerControllerLookupEntry]]::new()
foreach (`$c in @(`$controllers)) {
    if (`$null -eq `$c) { continue }
    if (`$c.ConfigManagerErrorCode -eq 22) { continue }
    `$normalizedId = `$c.DeviceID -replace '\\\\', '\\'
    `$entry = [DeviceTweakerControllerLookupEntry]::new()
    `$entry.Controller = `$c
    `$entry.NormalizedId = [string]`$normalizedId
    [void]`$controllerLookup.Add(`$entry)
}

function New-DeviceTweakerImodHydrationResultItem {
    param(`$Key, `$Category, `$Status, `$Error = `$null, `$IMODValues = `$null, `$InterrupterDeviceMap = `$null, `$InterrupterDeviceMapError = `$null, `$NICValues = `$null, `$NICTopology = `$null)
    `$result = [DeviceTweakerImodHydrationResult]::new()
    `$result.Key = [string]`$Key
    `$result.Category = [string]`$Category
    `$result.Status = [string]`$Status
    if (`$null -ne `$Error) { `$result.Error = [string]`$Error }
    if (`$null -ne `$IMODValues) { `$result.IMODValues = [object[]]@(`$IMODValues) }
    `$result.InterrupterDeviceMap = `$InterrupterDeviceMap
    if (`$null -ne `$InterrupterDeviceMapError) { `$result.InterrupterDeviceMapError = [string]`$InterrupterDeviceMapError }
    if (`$null -ne `$NICValues) { `$result.NICValues = [object[]]@(`$NICValues) }
    if (`$null -ne `$NICTopology) { `$result.NICTopology = `$NICTopology }
    return `$result
}

`$results = [System.Collections.Generic.List[DeviceTweakerImodHydrationResult]]::new()
`$rwePreflight = Initialize-DeviceTweakerRWEverything -Path `$rwePath -Quiet
`$rweMissing = (-not `$rwePreflight.Ready -and (Test-RWENotInstalledError `$rwePreflight.Message))
foreach (`$spec in @(`$deviceSpecs)) {
    if (`$null -eq `$spec) { continue }

    if (`$spec.Category -eq 'USB') {
        `$instanceId = Split-Path -Leaf `$spec.RegistryPath
        `$matchedController = `$null
        foreach (`$entry in `$controllerLookup) {
            if (`$entry.NormalizedId.Contains(`$instanceId)) {
                `$matchedController = `$entry.Controller
                break
            }
        }
        if (-not `$matchedController) {
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'USB' -Status 'NoMatch'))
            continue
        }
        if (`$rweMissing) {
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'USB' -Status 'RWENotInstalled' -Error `$rwePreflight.Message))
            continue
        }

        `$intrDevMap = `$null
        `$intrDevMapError = `$null
        try {
            `$intrDevMap = Get-XHCIInterrupterDeviceMap -controller `$matchedController -deviceMap `$deviceMap -usbEnumResult `$usbEnumResult -hidDevices `$hidDevices -pollingRateLookup `$pollingRateLookup
        } catch {
            `$intrDevMap = `$null
            `$intrDevMapError = `$_.Exception.Message
        }

        try {
            `$imodValues = Read-ControllerIMOD -controller `$matchedController -deviceMap `$deviceMap -interrupterDeviceMap `$intrDevMap
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'USB' -Status 'OK' -IMODValues @(`$imodValues) -InterrupterDeviceMap `$intrDevMap -InterrupterDeviceMapError `$intrDevMapError))
        } catch {
            `$readStatus = if (Test-RWENotInstalledError `$_.Exception.Message) { 'RWENotInstalled' } else { 'Error' }
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'USB' -Status `$readStatus -Error `$_.Exception.Message -InterrupterDeviceMap `$intrDevMap -InterrupterDeviceMapError `$intrDevMapError))
        }
        continue
    }

    if (`$spec.Category -eq 'Network' -and `$spec.NICIMODInfo) {
        if (`$rweMissing) {
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'Network' -Status 'RWENotInstalled' -Error `$rwePreflight.Message))
            continue
        }
        try {
            `$nicValues = Read-NICIMOD -device `$spec -deviceMap `$deviceMap -nicInfo `$spec.NICIMODInfo
            `$nicTopology = `$null
            try { `$nicTopology = Update-RealtekIntMitiV2TopologyInNicInfo -device `$spec -deviceMap `$deviceMap -nicInfo `$spec.NICIMODInfo } catch { `$topologyError = `$_.Exception.Message; Write-NICITRDiagnostic -Level Error -Message ('Async NIC ITR hydration topology read failed. device={0}' -f (Get-NICITRDeviceDebugName -Device `$spec)) -Exception `$_; `$labelCount = if (`$spec.NICIMODInfo -and `$spec.NICIMODInfo.ContainsKey('MaxQueues')) { [int]`$spec.NICIMODInfo.MaxQueues } else { 64 }; `$nicTopology = [PSCustomObject]@{ Summary = ('Realtek topology read failed: {0}' -f `$topologyError); Labels = (New-RealtekIntMitiV2TopologyErrorLabels -Count `$labelCount -Error `$topologyError); Error = `$topologyError } }
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'Network' -Status 'OK' -NICValues @(`$nicValues) -NICTopology `$nicTopology))
        } catch {
            `$readStatus = if (Test-RWENotInstalledError `$_.Exception.Message) { 'RWENotInstalled' } else { 'Error' }
            [void]`$results.Add((New-DeviceTweakerImodHydrationResultItem -Key `$spec.Key -Category 'Network' -Status `$readStatus -Error `$_.Exception.Message))
        }
    }
}
return `$results
"@
}

function Get-AsyncUSBIMODApplyWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Dec-To-Hex')
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64')
        (Get-FunctionDefinitionText 'Is-Admin')
        (Get-FunctionDefinitionText 'Resolve-RWEPath')
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics')
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled')
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything')
        (Get-FunctionDefinitionText 'Invoke-RWECommand')
        (Get-FunctionDefinitionText 'Invoke-RWEReadBatch')
        (Get-FunctionDefinitionText 'Get-Value-From-Address')
        (Get-FunctionDefinitionText 'Read-Value64FromAddress')
        (Get-FunctionDefinitionText 'Get-XHCIControllerRuntimeInfo')
        (Get-FunctionDefinitionText 'Get-XHCIPortRegisterAddress')
        (Get-FunctionDefinitionText 'Get-XHCISupportedProtocolPortRanges')
        (Get-FunctionDefinitionText 'Get-XHCIPortProtocolLookup')
        (Get-FunctionDefinitionText 'Resolve-XHCIUSB3TimeoutByte')
        (Get-FunctionDefinitionText 'Set-XHCILinkPowerManagement')
        (Get-FunctionDefinitionText 'Get-EffectiveUSBInterrupterReadCount')
        (Get-FunctionDefinitionText 'Read-ControllerIMOD')
        (Get-FunctionDefinitionText 'Write-ControllerIMOD')
    ) -join "`r`n`r`n"

    return @"
param(`$controller, `$deviceMap, `$newIntervalArg, `$interrupterDeviceMap, `$preferredCountArg, `$userDefinedDataArg, `$rwePathArg, `$globalIntervalArg, `$globalHCSPARAMSOffsetArg, `$globalRTSOFFArg)
`$script:userDefinedData = if (`$userDefinedDataArg) { `$userDefinedDataArg } else { @{} }
`$globalInterval = `$globalIntervalArg
`$globalHCSPARAMSOffset = `$globalHCSPARAMSOffsetArg
`$globalRTSOFF = `$globalRTSOFFArg
`$rwePath = `$rwePathArg
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))

$defs

`$result = Write-ControllerIMOD -controller `$controller -deviceMap `$deviceMap -newInterval `$newIntervalArg
if (-not `$result) { throw 'Failed to apply IMOD settings' }
`$lpmResult = Set-XHCILinkPowerManagement -controller `$controller -deviceMap `$deviceMap -EnableU1:`$false -EnableU2:`$false -Mode 'RejectAll'
`$readBack = Read-ControllerIMOD -controller `$controller -deviceMap `$deviceMap -interrupterDeviceMap `$interrupterDeviceMap -preferredCount ([int]`$preferredCountArg)
`$applyResult = [DeviceTweakerAsyncApplyResult]::new()
`$applyResult.Success = `$true
`$applyResult.ReadBack = [object[]]@(`$readBack)
`$applyResult
"@
}

