function ConvertTo-PciAspmModeName {
    param([Parameter(Mandatory=$true)][int]$Mode)
    switch ($Mode -band 0x3) {
        0 { 'OFF'; break }
        1 { 'L0s'; break }
        2 { 'L1'; break }
        3 { 'L0s+L1'; break }
        default { 'Unknown' }
    }
}

function ConvertTo-PciAspmSupportedNames {
    param([Parameter(Mandatory=$true)][int]$Mask)
    $names = New-Object System.Collections.Generic.List[string]
    if (($Mask -band 0x1) -ne 0) { [void]$names.Add('L0s') }
    if (($Mask -band 0x2) -ne 0) { [void]$names.Add('L1') }
    if ($names.Count -eq 0) { return 'none' }
    return ($names -join '+')
}

function Read-PciConfigValue {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,4095)][int]$Offset,
        [Parameter(Mandatory=$true)][ValidateSet(8,16,32)][int]$Width
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $alignedOffset = [int]($Offset - ($Offset % 4))
    $lane = [int]($Offset - $alignedOffset)
    if ($Width -eq 32 -and $lane -ne 0) {
        throw ('PCIe config read request is not DWORD-aligned. BDF={0}; Offset=0x{1:X3}; Width={2}; Lane={3}.' -f $bdf, $Offset, $Width, $lane)
    }
    if ($Width -eq 16 -and $lane -gt 2) {
        throw ('PCIe config read request crosses a DWORD boundary. BDF={0}; Offset=0x{1:X3}; Width={2}; Lane={3}.' -f $bdf, $Offset, $Width, $lane)
    }

    $address = $null
    $cmd = $null
    try {
        $address = [DeviceTweakerPciEcam]::ResolveAddress($Segment, $Bus, $Device, $Function, $alignedOffset)
        $cmd = 'R32 ' + (Dec-To-Hex -decimal ([uint64]$address))
        $stdout = Invoke-RWECommand -Command $cmd
        $context = ('PCIeConfigRead BDF={0} Offset=0x{1:X3} Width={2} AlignedOffset=0x{3:X3} Lane={4} ECAM=0x{5:X}' -f $bdf, $Offset, $Width, $alignedOffset, $lane, [uint64]$address)
        $dword = [uint64](Convert-RWEverythingOutputToUInt64 -Stdout $stdout -Context $context)
        $shift = [int]($lane * 8)
        if ($Width -eq 8) { return [uint32](($dword -shr $shift) -band 0xFF) }
        if ($Width -eq 16) { return [uint32](($dword -shr $shift) -band 0xFFFF) }
        return [uint32]($dword -band 0xFFFFFFFF)
    } catch {
        $causeText = $_.Exception.Message
        $addrText = if ($null -eq $address) { 'unresolved' } else { ('0x{0:X}' -f ([uint64]$address)) }
        $mcfgText = 'unavailable'
        try { $mcfgText = [DeviceTweakerPciEcam]::FormatSegments([DeviceTweakerPciEcam]::GetMcfgSegments()) } catch { $mcfgText = 'unavailable: ' + $_.Exception.Message }
        throw ('PCIe config read failed. BDF={0}; Segment={1}; Bus={2}; Device={3}; Function={4}; RequestedOffset=0x{5:X3}; Width={6}; AlignedOffset=0x{7:X3}; Lane={8}; ECAM={9}; Command={10}; MCFG={11}{12}{13}' -f $bdf, $Segment, $Bus, $Device, $Function, $Offset, $Width, $alignedOffset, $lane, $addrText, $cmd, $mcfgText, [Environment]::NewLine, $causeText)
    }
}


function Write-PciConfigValue {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,4095)][int]$Offset,
        [Parameter(Mandatory=$true)][ValidateSet(8,16,32)][int]$Width,
        [Parameter(Mandatory=$true)][uint32]$Value
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    if ($Width -eq 32 -and (($Offset -band 0x3) -ne 0)) {
        throw ('PCIe config write request is not DWORD-aligned. BDF={0}; Offset=0x{1:X3}; Width={2}.' -f $bdf, $Offset, $Width)
    }
    if ($Width -eq 16 -and ((($Offset -band 0x1) -ne 0) -or $Offset -gt 4094)) {
        throw ('PCIe config write request is not WORD-aligned or crosses config space. BDF={0}; Offset=0x{1:X3}; Width={2}.' -f $bdf, $Offset, $Width)
    }

    $address = $null
    $cmd = $null
    try {
        $address = [DeviceTweakerPciEcam]::ResolveAddress($Segment, $Bus, $Device, $Function, $Offset)
        if ($Width -eq 8) {
            $op = 'W8'
            $hexValue = ('0x{0:X2}' -f ($Value -band 0xFF))
        }
        elseif ($Width -eq 16) {
            $op = 'W16'
            $hexValue = ('0x{0:X4}' -f ($Value -band 0xFFFF))
        }
        else {
            $op = 'W32'
            $hexValue = ('0x{0:X8}' -f ($Value -band 0xFFFFFFFF))
        }
        $cmd = $op + ' ' + (Dec-To-Hex -decimal ([uint64]$address)) + ' ' + $hexValue
        [void](Invoke-RWECommand -Command $cmd -AllowEmptyOutput)
    } catch {
        $causeText = $_.Exception.Message
        $addrText = if ($null -eq $address) { 'unresolved' } else { ('0x{0:X}' -f ([uint64]$address)) }
        $mcfgText = 'unavailable'
        try { $mcfgText = [DeviceTweakerPciEcam]::FormatSegments([DeviceTweakerPciEcam]::GetMcfgSegments()) } catch { $mcfgText = 'unavailable: ' + $_.Exception.Message }
        throw ('PCIe config write failed. BDF={0}; Segment={1}; Bus={2}; Device={3}; Function={4}; Offset=0x{5:X3}; Width={6}; ECAM={7}; Command={8}; Value=0x{9:X8}; MCFG={10}{11}{12}' -f $bdf, $Segment, $Bus, $Device, $Function, $Offset, $Width, $addrText, $cmd, [uint32]$Value, $mcfgText, [Environment]::NewLine, $causeText)
    }
}



function Get-PciExpressCapabilityContext {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $status = Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x06 -Width 16
    if (($status -band 0x10) -eq 0) {
        throw ('PCI status register CapabilitiesList bit is clear for {0}; this function does not expose the conventional capability list needed to find PCIe Capability ID 0x10.' -f $bdf)
    }
    $ptr = [int]((Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x34 -Width 8) -band 0xFC)
    $seen = @{}
    for ($i = 0; $i -lt 64 -and $ptr -ge 0x40 -and $ptr -lt 0x100; $i++) {
        if ($seen.ContainsKey($ptr)) {
            throw ('Loop detected while traversing PCI capability list for {0}; repeated offset 0x{1:X2}.' -f $bdf, $ptr)
        }
        $seen[$ptr] = $true
        $capId = Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ptr -Width 8
        $next = Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($ptr + 1) -Width 8
        if ($capId -eq 0x10) {
            $pcieCap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($ptr + 0x02) -Width 16)
            $capVersion = [int]($pcieCap -band 0xF)
            $portType = [int](($pcieCap -shr 4) -band 0xF)
            $hasDevice2 = ($capVersion -ge 2)
            return [pscustomobject]@{
                Bdf = $bdf
                CapabilityOffset = $ptr
                CapabilityFlagsOffset = $ptr + 0x02
                CapabilityRegisterRaw = [uint16]$pcieCap
                CapabilityVersion = [int]$capVersion
                DevicePortType = [int]$portType
                HasDevice2Registers = [bool]$hasDevice2
                HasLink2Registers = [bool]$hasDevice2
                DeviceCapabilitiesOffset = $ptr + 0x04
                DeviceControlOffset = $ptr + 0x08
                LinkCapabilitiesOffset = $ptr + 0x0C
                LinkControlOffset = $ptr + 0x10
                LinkStatusOffset = $ptr + 0x12
                DeviceCapabilities2Offset = $ptr + 0x24
                DeviceControl2Offset = $ptr + 0x28
                LinkCapabilities2Offset = $ptr + 0x2C
                LinkControl2Offset = $ptr + 0x30
                LinkStatus2Offset = $ptr + 0x32
            }
        }
        $ptr = [int]($next -band 0xFC)
        if ($ptr -eq 0) { break }
    }
    throw ('PCI Express Capability ID 0x10 was not found for {0}; cannot read PCIe Link Control/ASPM bits.' -f $bdf)
}


function Resolve-PciAspmLinkContext {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $portType = -1
    try { $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch { }
    if ($portType -eq 4 -or $portType -eq 6) {
        $child = Find-PciDownstreamChildFunction -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        return [pscustomobject]@{
            Parent = [pscustomobject]@{ Segment = $Segment; Bus = $Bus; Device = $Device; Function = $Function; Bdf = $bdf }
            Child = $child
            RequestedRole = 'Parent'
            RequestedPortType = [int]$portType
            RequestedPortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
        }
    }
    $parent = Find-PciParentBridge -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    return [pscustomobject]@{
        Parent = $parent
        Child = [pscustomobject]@{ Segment = $Segment; Bus = $Bus; Device = $Device; Function = $Function; Bdf = $bdf }
        RequestedRole = 'Child'
        RequestedPortType = [int]$portType
        RequestedPortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
    }
}

function Get-PciAspmLinkChildFunctions {
    param(
        [Parameter(Mandatory=$true)]$Child
    )
    $children = New-Object System.Collections.Generic.List[object]
    if ($null -eq $Child) { return ,$children.ToArray() }
    $segment = [int]$Child.Segment
    $bus = [int]$Child.Bus
    $device = [int]$Child.Device
    $function = [int]$Child.Function
    $header0 = 0
    $maxFunction = 0
    try {
        $header0 = Get-PciHeaderType -Segment $segment -Bus $bus -Device $device -Function 0
        $maxFunction = if (($header0 -band 0x80) -ne 0) { 7 } else { 0 }
    } catch {
        $maxFunction = $function
    }
    for ($fn = 0; $fn -le $maxFunction; $fn++) {
        if ($fn -ne $function -and -not (Test-PciFunctionPresent -Segment $segment -Bus $bus -Device $device -Function $fn)) { continue }
        try {
            [void](Get-PciExpressCapabilityContext -Segment $segment -Bus $bus -Device $device -Function $fn)
            [void]$children.Add([pscustomobject]@{ Segment = $segment; Bus = $bus; Device = $device; Function = $fn; Bdf = [DeviceTweakerPciEcam]::FormatBdf($segment,$bus,$device,$fn) })
        } catch { }
    }
    if ($children.Count -eq 0) { [void]$children.Add($Child) }
    return ,$children.ToArray()
}

function Get-PciAspmPortState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [string]$Role = 'Requested'
    )
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $lnkcap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkCapabilitiesOffset) -Width 32)
    $lnkctl = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkControlOffset) -Width 16)
    $mode = [int]($lnkctl -band 0x3)
    $support = [int](($lnkcap -band 0x00000C00) -shr 10)
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkControlOffset)
    $portType = -1
    try { $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch { $portType = [int]$ctx.DevicePortType }
    [pscustomobject]@{
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = $bdf
        Role = $Role
        PcieCapabilityVersion = [int]$ctx.CapabilityVersion
        PciePortType = [int]$portType
        PciePortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
        CapabilityOffset = [int]$ctx.CapabilityOffset
        LinkCapabilitiesOffset = [int]$ctx.LinkCapabilitiesOffset
        LinkControlOffset = [int]$ctx.LinkControlOffset
        LinkCapabilitiesRaw = [uint32]$lnkcap
        LinkControlRaw = [uint16]$lnkctl
        Mode = [int]$mode
        ModeName = (ConvertTo-PciAspmModeName -Mode $mode)
        SupportedMask = [int]$support
        SupportedNames = (ConvertTo-PciAspmSupportedNames -Mask $support)
        EcamAddress = [uint64]$ecam
    }
}

function Get-PciAspm {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $requested = Get-PciAspmPortState -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Role 'Requested'
    $link = $null
    try { $link = Resolve-PciAspmLinkContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch {
        $requested | Add-Member -NotePropertyName LinkResolved -NotePropertyValue $false -Force
        $requested | Add-Member -NotePropertyName LinkError -NotePropertyValue ($_.Exception.Message) -Force
        $requested | Add-Member -NotePropertyName DisplayText -NotePropertyValue ('{0}; device-cap {1}; BDF {2}; cap 0x{3:X2}; LNKCTL 0x{4:X4}; ECAM 0x{5:X}; LINK unresolved: {6}' -f $requested.ModeName, $requested.SupportedNames, $requested.Bdf, [int]$requested.CapabilityOffset, [int]$requested.LinkControlRaw, [uint64]$requested.EcamAddress, $_.Exception.Message) -Force
        return $requested
    }

    $parent = Get-PciAspmPortState -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Role 'Parent/Downstream'
    $childFunctions = Get-PciAspmLinkChildFunctions -Child $link.Child
    $childPorts = New-Object System.Collections.Generic.List[object]
    foreach ($child in @($childFunctions)) {
        try { [void]$childPorts.Add((Get-PciAspmPortState -Segment ([int]$child.Segment) -Bus ([int]$child.Bus) -Device ([int]$child.Device) -Function ([int]$child.Function) -Role 'Child/Upstream')) } catch { }
    }
    if ($childPorts.Count -eq 0) { throw ('PCIe ASPM link read failed: no readable child/upstream PCIe function found behind {0}.' -f [string]$parent.Bdf) }

    $commonSupport = [int]$parent.SupportedMask
    $effectiveMode = [int]$parent.Mode
    $childModeText = New-Object System.Collections.Generic.List[string]
    $childBdfs = New-Object System.Collections.Generic.List[string]
    $childCaps = New-Object System.Collections.Generic.List[string]
    foreach ($childPort in @($childPorts.ToArray())) {
        $commonSupport = [int]($commonSupport -band [int]$childPort.SupportedMask)
        $effectiveMode = [int]($effectiveMode -band [int]$childPort.Mode)
        [void]$childModeText.Add(('{0}:{1}' -f [string]$childPort.Bdf, [string]$childPort.ModeName))
        [void]$childBdfs.Add([string]$childPort.Bdf)
        [void]$childCaps.Add(('{0}:{1}' -f [string]$childPort.Bdf, [string]$childPort.SupportedNames))
    }
    $anyChildL0s = $false
    $allChildL0s = $true
    foreach ($childPort in @($childPorts.ToArray())) {
        if (([int]$childPort.Mode -band 0x1) -ne 0) { $anyChildL0s = $true } else { $allChildL0s = $false }
    }
    $childL0sText = if ($childPorts.Count -le 1) { [string]$anyChildL0s } else { ('all={0}, any={1}' -f $allChildL0s, $anyChildL0s) }
    $l0sText = ('L0s parent/down={0}, child/up={1}' -f (([int]$parent.Mode -band 0x1) -ne 0), $childL0sText)
    $linkModeName = ConvertTo-PciAspmModeName -Mode $effectiveMode
    $commonSupportNames = ConvertTo-PciAspmSupportedNames -Mask $commonSupport
    $display = ('{0}; common-cap {1}; requested {2} as {3}; parent {4}={5}; child {6}; {7}; cap 0x{8:X2}; LNKCTL 0x{9:X4}; ECAM 0x{10:X}' -f $linkModeName, $commonSupportNames, [string]$requested.Bdf, [string]$link.RequestedRole, [string]$parent.Bdf, [string]$parent.ModeName, ([string]::Join(', ', $childModeText.ToArray())), $l0sText, [int]$requested.CapabilityOffset, [int]$requested.LinkControlRaw, [uint64]$requested.EcamAddress)

    $requested | Add-Member -NotePropertyName LinkResolved -NotePropertyValue $true -Force
    $requested | Add-Member -NotePropertyName RequestedRole -NotePropertyValue ([string]$link.RequestedRole) -Force
    $requested | Add-Member -NotePropertyName RequestedPortTypeName -NotePropertyValue ([string]$link.RequestedPortTypeName) -Force
    $requested | Add-Member -NotePropertyName ParentPort -NotePropertyValue $parent -Force
    $requested | Add-Member -NotePropertyName ChildPorts -NotePropertyValue @($childPorts.ToArray()) -Force
    $requested | Add-Member -NotePropertyName ChildFunctionCount -NotePropertyValue ([int]$childPorts.Count) -Force
    $requested | Add-Member -NotePropertyName ParentBdf -NotePropertyValue ([string]$parent.Bdf) -Force
    $requested | Add-Member -NotePropertyName ChildBdfs -NotePropertyValue ([string]::Join(', ', $childBdfs.ToArray())) -Force
    $requested | Add-Member -NotePropertyName ParentMode -NotePropertyValue ([int]$parent.Mode) -Force
    $requested | Add-Member -NotePropertyName ChildModes -NotePropertyValue ([string]::Join(', ', $childModeText.ToArray())) -Force
    $requested | Add-Member -NotePropertyName ChildCapabilities -NotePropertyValue ([string]::Join(', ', $childCaps.ToArray())) -Force
    $requested | Add-Member -NotePropertyName Mode -NotePropertyValue ([int]$effectiveMode) -Force
    $requested | Add-Member -NotePropertyName ModeName -NotePropertyValue $linkModeName -Force
    $requested | Add-Member -NotePropertyName SupportedMask -NotePropertyValue ([int]$commonSupport) -Force
    $requested | Add-Member -NotePropertyName SupportedNames -NotePropertyValue $commonSupportNames -Force
    $requested | Add-Member -NotePropertyName CommonSupportedMask -NotePropertyValue ([int]$commonSupport) -Force
    $requested | Add-Member -NotePropertyName CommonSupportedNames -NotePropertyValue $commonSupportNames -Force
    $requested | Add-Member -NotePropertyName L0sDirectionalText -NotePropertyValue $l0sText -Force
    $requested | Add-Member -NotePropertyName DisplayText -NotePropertyValue $display -Force
    return $requested
}

function Set-PciAspmPortMode {
    param(
        [Parameter(Mandatory=$true)]$Port,
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Mode
    )
    $newRaw = [uint32]((([uint32]$Port.LinkControlRaw) -band 0xFFFC) -bor ($Mode -band 0x3))
    if ([uint16]$newRaw -ne [uint16]$Port.LinkControlRaw) {
        Write-PciConfigValue -Segment ([int]$Port.Segment) -Bus ([int]$Port.Bus) -Device ([int]$Port.Device) -Function ([int]$Port.Function) -Offset ([int]$Port.LinkControlOffset) -Width 16 -Value $newRaw
    }
}

function Set-PciAspm {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Mode
    )
    $before = Get-PciAspm -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if (-not [bool]$before.LinkResolved) {
        throw ('PCIe ASPM write refused for {0}: link topology could not be resolved. A single-function write can desynchronize the upstream/downstream Link Control state. {1}' -f $before.Bdf, [string]$before.LinkError)
    }
    $commonSupport = [int]$before.CommonSupportedMask
    if ($Mode -ne 0 -and (($Mode -band (-bnot $commonSupport)) -ne 0)) {
        throw ('Requested ASPM {0} for link {1}<->{2}, but the common Link Capabilities only advertise {3}. Refusing to set unsupported Link Control bits.' -f (ConvertTo-PciAspmModeName -Mode $Mode), [string]$before.ParentBdf, [string]$before.ChildBdfs, [string]$before.CommonSupportedNames)
    }

    $parent = $before.ParentPort
    $children = @($before.ChildPorts)
    $anyBeforeL1 = ((([int]$parent.Mode -band 0x2) -ne 0))
    foreach ($child in @($children)) { if ((([int]$child.Mode -band 0x2) -ne 0)) { $anyBeforeL1 = $true } }
    $clearL1 = ($anyBeforeL1 -and (($Mode -band 0x2) -eq 0))
    if ($clearL1) {
        foreach ($child in @($children)) { Set-PciAspmPortMode -Port $child -Mode $Mode }
        Set-PciAspmPortMode -Port $parent -Mode $Mode
    } else {
        Set-PciAspmPortMode -Port $parent -Mode $Mode
        foreach ($child in @($children)) { Set-PciAspmPortMode -Port $child -Mode $Mode }
    }

    $after = Get-PciAspm -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $failed = New-Object System.Collections.Generic.List[string]
    if (-not [bool]$after.LinkResolved) { [void]$failed.Add('link unresolved after write') }
    else {
        if ((([int]$after.ParentPort.Mode) -band 0x3) -ne ($Mode -band 0x3)) { [void]$failed.Add(('{0} read {1}' -f [string]$after.ParentPort.Bdf, [string]$after.ParentPort.ModeName)) }
        foreach ($child in @($after.ChildPorts)) {
            if ((([int]$child.Mode) -band 0x3) -ne ($Mode -band 0x3)) { [void]$failed.Add(('{0} read {1}' -f [string]$child.Bdf, [string]$child.ModeName)) }
        }
    }
    if ($failed.Count -gt 0) {
        throw ('ASPM link-wide write verification failed for requested {0}. Requested {1}. Failures: {2}. Before: parent {3}=0x{4:X4}, children [{5}]. After: {6}' -f $before.Bdf, (ConvertTo-PciAspmModeName -Mode $Mode), ([string]::Join(', ', $failed.ToArray())), [string]$before.ParentPort.Bdf, [int]$before.ParentPort.LinkControlRaw, [string]$before.ChildModes, [string]$after.DisplayText)
    }
    return $after
}

function ConvertTo-PciObffModeName {
    param([Parameter(Mandatory=$true)][int]$Mode)
    switch ($Mode -band 0x3) {
        0 { 'OFF'; break }
        1 { 'MsgA'; break }
        2 { 'MsgB'; break }
        3 { 'WAKE#'; break }
        default { 'Unknown' }
    }
}

function ConvertTo-PciObffSupportName {
    param([Parameter(Mandatory=$true)][int]$Support)
    switch ($Support -band 0x3) {
        0 { 'none'; break }
        1 { 'message'; break }
        2 { 'WAKE#'; break }
        3 { 'message+WAKE#'; break }
        default { 'unknown' }
    }
}

function Test-PciObffModeSupported {
    param(
        [Parameter(Mandatory=$true)][int]$Support,
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Mode
    )
    $m = $Mode -band 0x3
    if ($m -eq 0) { return $true }
    $s = $Support -band 0x3
    if ($s -eq 1) { return ($m -eq 1 -or $m -eq 2) }
    if ($s -eq 2) { return ($m -eq 3) }
    if ($s -eq 3) { return ($m -ge 1 -and $m -le 3) }
    return $false
}

function Get-PciLtrLatencyMultiplier {
    param([Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$Scale)
    $multipliers = [uint64[]](1,32,1024,32768,1048576,33554432,1073741824,34359738368)
    return [uint64]$multipliers[$Scale]
}

function ConvertTo-PciLtrLatencyNs {
    param([Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$Raw)
    $value = [uint64]($Raw -band 0x03FF)
    $scale = [int](($Raw -shr 10) -band 0x7)
    return [uint64]($value * (Get-PciLtrLatencyMultiplier -Scale $scale))
}

function ConvertFrom-PciLtrLatencyNs {
    param([Parameter(Mandatory=$true)][uint64]$Ns)
    for ($scale = 0; $scale -le 7; $scale++) {
        $mul = Get-PciLtrLatencyMultiplier -Scale $scale
        $value = [uint64](($Ns + $mul - 1) / $mul)
        if ($value -le 1023) {
            return [pscustomobject]@{
                Scale = [int]$scale
                Value = [int]$value
                ActualNs = [uint64]($value * $mul)
                Raw = [uint16]((($scale -band 0x7) -shl 10) -bor ([int]$value -band 0x03FF))
            }
        }
    }
    throw ('PCIe LTR latency {0} ns is too large. Maximum encodable value is 35150012350464 ns.' -f [uint64]$Ns)
}

function Format-PciLtrLatencyNs {
    param([Parameter(Mandatory=$true)][uint64]$Ns)
    if ($Ns -eq 0) { return '0 ns' }
    if ($Ns -ge 1000000000 -and ($Ns % 1000000000) -eq 0) { return ('{0} s' -f [uint64]($Ns / 1000000000)) }
    if ($Ns -ge 1000000 -and ($Ns % 1000000) -eq 0) { return ('{0} ms' -f [uint64]($Ns / 1000000)) }
    if ($Ns -ge 1000 -and ($Ns % 1000) -eq 0) { return ('{0} us' -f [uint64]($Ns / 1000)) }
    return ('{0} ns' -f [uint64]$Ns)
}

function Get-PciLtrExtendedCapabilityState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    try {
        $ltrCtx = Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId 0x0018
        $snoopRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ltrCtx.CapabilityOffset + 0x04) -Width 16)
        $noSnoopRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ltrCtx.CapabilityOffset + 0x06) -Width 16)
        $snoopNs = ConvertTo-PciLtrLatencyNs -Raw ([int]$snoopRaw)
        $noSnoopNs = ConvertTo-PciLtrLatencyNs -Raw ([int]$noSnoopRaw)
        $snoopReserved = (($snoopRaw -band 0xE000) -ne 0)
        $noSnoopReserved = (($noSnoopRaw -band 0xE000) -ne 0)
        return [pscustomobject]@{
            Present = $true
            Error = $null
            CapabilityOffset = [int]$ltrCtx.CapabilityOffset
            Version = [int]$ltrCtx.Version
            HeaderRaw = [uint32]$ltrCtx.HeaderRaw
            MaxSnoopLatencyRaw = [uint16]$snoopRaw
            MaxSnoopLatencyScale = [int](($snoopRaw -shr 10) -band 0x7)
            MaxSnoopLatencyValue = [int]($snoopRaw -band 0x03FF)
            MaxSnoopLatencyNs = [uint64]$snoopNs
            MaxSnoopLatencyText = (Format-PciLtrLatencyNs -Ns $snoopNs)
            MaxSnoopLatencyReservedBitsSet = [bool]$snoopReserved
            MaxNoSnoopLatencyRaw = [uint16]$noSnoopRaw
            MaxNoSnoopLatencyScale = [int](($noSnoopRaw -shr 10) -band 0x7)
            MaxNoSnoopLatencyValue = [int]($noSnoopRaw -band 0x03FF)
            MaxNoSnoopLatencyNs = [uint64]$noSnoopNs
            MaxNoSnoopLatencyText = (Format-PciLtrLatencyNs -Ns $noSnoopNs)
            MaxNoSnoopLatencyReservedBitsSet = [bool]$noSnoopReserved
        }
    } catch {
        return [pscustomobject]@{
            Present = $false
            Error = ('{0}: {1}' -f $bdf, $_.Exception.Message)
            CapabilityOffset = -1
            Version = 0
            HeaderRaw = [uint32]0
            MaxSnoopLatencyRaw = [uint16]0
            MaxSnoopLatencyScale = 0
            MaxSnoopLatencyValue = 0
            MaxSnoopLatencyNs = [uint64]0
            MaxSnoopLatencyText = 'n/a'
            MaxSnoopLatencyReservedBitsSet = $false
            MaxNoSnoopLatencyRaw = [uint16]0
            MaxNoSnoopLatencyScale = 0
            MaxNoSnoopLatencyValue = 0
            MaxNoSnoopLatencyNs = [uint64]0
            MaxNoSnoopLatencyText = 'n/a'
            MaxNoSnoopLatencyReservedBitsSet = $false
        }
    }
}

function Test-DeviceTweakerNullableValueSpecified {
    param([AllowNull()][object]$Value)
    if ($null -eq $Value) { return $false }
    if ($Value -is [string] -and [string]::IsNullOrWhiteSpace([string]$Value)) { return $false }
    return $true
}


function Get-PciLtrObffState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    if (-not [bool]$ctx.HasDevice2Registers) {
        return [pscustomobject]@{
            Segment = $Segment
            Bus = $Bus
            Device = $Device
            Function = $Function
            Bdf = $bdf
            CapabilityOffset = [int]$ctx.CapabilityOffset
            PcieCapabilityVersion = [int]$ctx.CapabilityVersion
            DeviceCapabilities2Offset = [int]$ctx.DeviceCapabilities2Offset
            DeviceControl2Offset = [int]$ctx.DeviceControl2Offset
            DeviceCapabilities2Raw = [uint32]0
            DeviceControl2Raw = [uint16]0
            LtrSupported = $false
            LtrEnabled = $false
            LtrExtendedCapabilityPresent = $false
            LtrExtendedCapabilityError = ('PCIe Capability version {0} has no Device Capabilities 2 / Device Control 2 registers.' -f [int]$ctx.CapabilityVersion)
            LtrExtendedCapabilityOffset = -1
            LtrExtendedCapabilityVersion = 0
            LtrExtendedCapabilityHeaderRaw = [uint32]0
            LtrMaxSnoopLatencyRaw = [uint16]0
            LtrMaxSnoopLatencyScale = 0
            LtrMaxSnoopLatencyValue = 0
            LtrMaxSnoopLatencyNs = [uint64]0
            LtrMaxSnoopLatencyText = 'n/a'
            LtrMaxSnoopLatencyReservedBitsSet = $false
            LtrMaxNoSnoopLatencyRaw = [uint16]0
            LtrMaxNoSnoopLatencyScale = 0
            LtrMaxNoSnoopLatencyValue = 0
            LtrMaxNoSnoopLatencyNs = [uint64]0
            LtrMaxNoSnoopLatencyText = 'n/a'
            LtrMaxNoSnoopLatencyReservedBitsSet = $false
            ObffSupportedMask = 0
            ObffSupportedNames = 'none'
            ObffMode = 0
            ObffModeName = 'OFF'
            EcamAddress = [uint64]0
            DisplayText = ('LTR/OBFF n/a; PCIe Capability v{0} has no DEVCAP2/DEVCTL2; BDF {1}; cap 0x{2:X2}' -f [int]$ctx.CapabilityVersion, $bdf, [int]$ctx.CapabilityOffset)
        }
    }
    $devcap2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceCapabilities2Offset) -Width 32)
    $devctl2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControl2Offset) -Width 16)
    $ltrExt = Get-PciLtrExtendedCapabilityState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $ltrSupported = (($devcap2 -band 0x00000800) -ne 0)
    $obffSupport = [int](($devcap2 -band 0x000C0000) -shr 18)
    $ltrEnabled = (($devctl2 -band 0x0400) -ne 0)
    $obffMode = [int](($devctl2 -band 0x6000) -shr 13)
    $ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceControl2Offset)
    $ltrCapText = if ($ltrSupported) { 'yes' } else { 'no' }
    $ltrStateText = if ($ltrEnabled) { 'on' } else { 'off' }
    $obffModeName = ConvertTo-PciObffModeName -Mode $obffMode
    $obffSupportName = ConvertTo-PciObffSupportName -Support $obffSupport
    $ltrExtText = if ([bool]$ltrExt.Present) { ('ExtCap 0x{0:X3}; Snp {1}; NoSnp {2}' -f [int]$ltrExt.CapabilityOffset, [string]$ltrExt.MaxSnoopLatencyText, [string]$ltrExt.MaxNoSnoopLatencyText) } else { 'ExtCap 0x18 n/a' }
    $reservedWarning = ''
    if ([bool]$ltrExt.Present -and ([bool]$ltrExt.MaxSnoopLatencyReservedBitsSet -or [bool]$ltrExt.MaxNoSnoopLatencyReservedBitsSet)) {
        $reservedWarning = '; WARN LTR reserved bits set'
    }
    [pscustomobject]@{
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = $bdf
        CapabilityOffset = [int]$ctx.CapabilityOffset
        PcieCapabilityVersion = [int]$ctx.CapabilityVersion
        DeviceCapabilities2Offset = [int]$ctx.DeviceCapabilities2Offset
        DeviceControl2Offset = [int]$ctx.DeviceControl2Offset
        DeviceCapabilities2Raw = [uint32]$devcap2
        DeviceControl2Raw = [uint16]$devctl2
        LtrSupported = [bool]$ltrSupported
        LtrEnabled = [bool]$ltrEnabled
        LtrExtendedCapabilityPresent = [bool]$ltrExt.Present
        LtrExtendedCapabilityError = [string]$ltrExt.Error
        LtrExtendedCapabilityOffset = [int]$ltrExt.CapabilityOffset
        LtrExtendedCapabilityVersion = [int]$ltrExt.Version
        LtrExtendedCapabilityHeaderRaw = [uint32]$ltrExt.HeaderRaw
        LtrMaxSnoopLatencyRaw = [uint16]$ltrExt.MaxSnoopLatencyRaw
        LtrMaxSnoopLatencyScale = [int]$ltrExt.MaxSnoopLatencyScale
        LtrMaxSnoopLatencyValue = [int]$ltrExt.MaxSnoopLatencyValue
        LtrMaxSnoopLatencyNs = [uint64]$ltrExt.MaxSnoopLatencyNs
        LtrMaxSnoopLatencyText = [string]$ltrExt.MaxSnoopLatencyText
        LtrMaxSnoopLatencyReservedBitsSet = [bool]$ltrExt.MaxSnoopLatencyReservedBitsSet
        LtrMaxNoSnoopLatencyRaw = [uint16]$ltrExt.MaxNoSnoopLatencyRaw
        LtrMaxNoSnoopLatencyScale = [int]$ltrExt.MaxNoSnoopLatencyScale
        LtrMaxNoSnoopLatencyValue = [int]$ltrExt.MaxNoSnoopLatencyValue
        LtrMaxNoSnoopLatencyNs = [uint64]$ltrExt.MaxNoSnoopLatencyNs
        LtrMaxNoSnoopLatencyText = [string]$ltrExt.MaxNoSnoopLatencyText
        LtrMaxNoSnoopLatencyReservedBitsSet = [bool]$ltrExt.MaxNoSnoopLatencyReservedBitsSet
        ObffSupportedMask = [int]$obffSupport
        ObffSupportedNames = $obffSupportName
        ObffMode = [int]$obffMode
        ObffModeName = $obffModeName
        EcamAddress = [uint64]$ecam
        DisplayText = ('LTR {0} (cap {1}); OBFF {2} (cap {3}); {4}{5}; BDF {6}; cap 0x{7:X2}; PCIeCap v{8}; DEVCAP2 0x{9:X8}; DEVCTL2 0x{10:X4}; ECAM 0x{11:X}' -f $ltrStateText, $ltrCapText, $obffModeName, $obffSupportName, $ltrExtText, $reservedWarning, $bdf, [int]$ctx.CapabilityOffset, [int]$ctx.CapabilityVersion, [uint32]$devcap2, [int]$devctl2, [uint64]$ecam)
    }
}

function Set-PciLtrObffState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][bool]$EnableLtr,
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$ObffMode,
        [AllowNull()][object]$MaxSnoopLatencyNs = $null,
        [AllowNull()][object]$MaxNoSnoopLatencyNs = $null
    )
    $before = Get-PciLtrObffState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ($EnableLtr -and -not [bool]$before.LtrSupported) {
        throw ('LTR write refused for {0}: DevCap2 does not advertise LTR support. DEVCAP2=0x{1:X8}; DEVCTL2=0x{2:X4}.' -f $before.Bdf, [uint32]$before.DeviceCapabilities2Raw, [int]$before.DeviceControl2Raw)
    }
    if (-not (Test-PciObffModeSupported -Support ([int]$before.ObffSupportedMask) -Mode $ObffMode)) {
        throw ('OBFF write refused for {0}: requested {1}, but DevCap2 advertises {2}. DEVCAP2=0x{3:X8}; DEVCTL2=0x{4:X4}.' -f $before.Bdf, (ConvertTo-PciObffModeName -Mode $ObffMode), $before.ObffSupportedNames, [uint32]$before.DeviceCapabilities2Raw, [int]$before.DeviceControl2Raw)
    }

    $writeSnoop = Test-DeviceTweakerNullableValueSpecified -Value $MaxSnoopLatencyNs
    $writeNoSnoop = Test-DeviceTweakerNullableValueSpecified -Value $MaxNoSnoopLatencyNs
    $snoopEncoded = $null
    $noSnoopEncoded = $null
    if ($writeSnoop -or $writeNoSnoop) {
        if (-not [bool]$before.LtrExtendedCapabilityPresent) {
            throw ('LTR latency write refused for {0}: Latency Tolerance Reporting Extended Capability ID 0x18 is not present. DEVCTL2 LTR enable can still be toggled, but Max Snoop/No-Snoop latency registers are unavailable.' -f $before.Bdf)
        }
        if ($writeSnoop) { $snoopEncoded = ConvertFrom-PciLtrLatencyNs -Ns ([uint64]$MaxSnoopLatencyNs) }
        if ($writeNoSnoop) { $noSnoopEncoded = ConvertFrom-PciLtrLatencyNs -Ns ([uint64]$MaxNoSnoopLatencyNs) }
    }

    $newRaw = [uint32](([uint32]$before.DeviceControl2Raw) -band 0x9BFF)
    if ($EnableLtr) { $newRaw = [uint32]($newRaw -bor 0x0400) }
    $newRaw = [uint32]($newRaw -bor (($ObffMode -band 0x3) -shl 13))
    if ([uint16]$newRaw -ne [uint16]$before.DeviceControl2Raw) {
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.DeviceControl2Offset) -Width 16 -Value $newRaw
    }

    if ($writeSnoop -or $writeNoSnoop) {
        $latencyDword = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.LtrExtendedCapabilityOffset + 0x04) -Width 32)
        if ($writeSnoop) { $latencyDword = [uint32](($latencyDword -band 0xFFFF0000) -bor ([uint32]$snoopEncoded.Raw -band 0xFFFF)) }
        if ($writeNoSnoop) { $latencyDword = [uint32](($latencyDword -band 0x0000FFFF) -bor ((([uint32]$noSnoopEncoded.Raw) -band 0xFFFF) -shl 16)) }
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.LtrExtendedCapabilityOffset + 0x04) -Width 32 -Value $latencyDword
    }

    $after = Get-PciLtrObffState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ([bool]$after.LtrEnabled -ne [bool]$EnableLtr -or ([int]$after.ObffMode -ne ($ObffMode -band 0x3))) {
        throw ('LTR/OBFF write verification failed for {0}. Requested LTR={1} OBFF={2}; read LTR={3} OBFF={4}. Before DEVCTL2=0x{5:X4}; after DEVCTL2=0x{6:X4}; DEVCTL2 ECAM=0x{7:X}.' -f $before.Bdf, [bool]$EnableLtr, (ConvertTo-PciObffModeName -Mode $ObffMode), [bool]$after.LtrEnabled, $after.ObffModeName, [int]$before.DeviceControl2Raw, [int]$after.DeviceControl2Raw, [uint64]$before.EcamAddress)
    }
    if ($writeSnoop -and [int]$after.LtrMaxSnoopLatencyRaw -ne [int]$snoopEncoded.Raw) {
        throw ('LTR Max Snoop Latency write verification failed for {0}. Requested {1} ns encoded raw 0x{2:X4} (actual {3} ns); read raw 0x{4:X4} ({5}).' -f $before.Bdf, [uint64]$MaxSnoopLatencyNs, [int]$snoopEncoded.Raw, [uint64]$snoopEncoded.ActualNs, [int]$after.LtrMaxSnoopLatencyRaw, [string]$after.LtrMaxSnoopLatencyText)
    }
    if ($writeNoSnoop -and [int]$after.LtrMaxNoSnoopLatencyRaw -ne [int]$noSnoopEncoded.Raw) {
        throw ('LTR Max No-Snoop Latency write verification failed for {0}. Requested {1} ns encoded raw 0x{2:X4} (actual {3} ns); read raw 0x{4:X4} ({5}).' -f $before.Bdf, [uint64]$MaxNoSnoopLatencyNs, [int]$noSnoopEncoded.Raw, [uint64]$noSnoopEncoded.ActualNs, [int]$after.LtrMaxNoSnoopLatencyRaw, [string]$after.LtrMaxNoSnoopLatencyText)
    }
    return $after
}


function ConvertTo-PciL1ssMaskName {
    param([Parameter(Mandatory=$true)][int]$Mask)
    $names = New-Object System.Collections.Generic.List[string]
    if (($Mask -band 0x8) -ne 0) { [void]$names.Add('ASPM L1.1') }
    if (($Mask -band 0x4) -ne 0) { [void]$names.Add('ASPM L1.2') }
    if (($Mask -band 0x2) -ne 0) { [void]$names.Add('PCI-PM L1.1') }
    if (($Mask -band 0x1) -ne 0) { [void]$names.Add('PCI-PM L1.2') }
    if ($names.Count -eq 0) { return 'OFF' }
    return ($names -join '+')
}

function ConvertTo-PciL1ssThresholdNs {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$Scale,
        [Parameter(Mandatory=$true)][ValidateRange(0,1023)][int]$Value
    )
    $multipliers = [uint64[]](1,32,1024,32768,1048576,33554432)
    if ($Scale -lt 0 -or $Scale -ge $multipliers.Length) { return [uint64]0 }
    return [uint64]([uint64]$Value * [uint64]$multipliers[$Scale])
}

function ConvertFrom-PciL1ssThresholdNs {
    param([Parameter(Mandatory=$true)][uint64]$Ns)
    $multipliers = [uint64[]](1,32,1024,32768,1048576,33554432)
    if ($Ns -eq 0) {
        return [pscustomobject]@{ Scale = 0; Value = 0; ActualNs = [uint64]0 }
    }
    for ($scale = 0; $scale -lt $multipliers.Length; $scale++) {
        $mul = [uint64]$multipliers[$scale]
        $value = [uint64](($Ns + $mul - 1) / $mul)
        if ($value -le 1023) {
            return [pscustomobject]@{ Scale = [int]$scale; Value = [int]$value; ActualNs = [uint64]($value * $mul) }
        }
    }
    return [pscustomobject]@{ Scale = 5; Value = 1023; ActualNs = [uint64]34326183936 }
}


function Format-PciL1ssThresholdNs {
    param([Parameter(Mandatory=$true)][uint64]$Ns)
    if ($Ns -ge 1000000000 -and ($Ns % 1000000000) -eq 0) { return ('{0} s' -f [uint64]($Ns / 1000000000)) }
    if ($Ns -ge 1000000 -and ($Ns % 1000000) -eq 0) { return ('{0} ms' -f [uint64]($Ns / 1000000)) }
    if ($Ns -ge 1000 -and ($Ns % 1000) -eq 0) { return ('{0} us' -f [uint64]($Ns / 1000)) }
    return ('{0} ns' -f [uint64]$Ns)
}

function ConvertTo-PciL1ssPowerOnUs {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Scale,
        [Parameter(Mandatory=$true)][ValidateRange(0,31)][int]$Value
    )
    switch ($Scale) {
        0 { return [uint64]([uint64]$Value * [uint64]2) }
        1 { return [uint64]([uint64]$Value * [uint64]10) }
        2 { return [uint64]([uint64]$Value * [uint64]100) }
        default { return [uint64]0 }
    }
}

function ConvertFrom-PciL1ssPowerOnUs {
    param([Parameter(Mandatory=$true)][uint64]$Us)
    $multipliers = [uint64[]](2,10,100)
    if ($Us -eq 0) { return [pscustomobject]@{ Scale = 0; Value = 0; ActualUs = [uint64]0; Raw = [uint32]0 } }
    for ($scale = 0; $scale -lt $multipliers.Length; $scale++) {
        $mul = [uint64]$multipliers[$scale]
        $value = [uint64](($Us + $mul - 1) / $mul)
        if ($value -le 31) {
            return [pscustomobject]@{ Scale = [int]$scale; Value = [int]$value; ActualUs = [uint64]($value * $mul); Raw = [uint32]((([uint32][int]$scale) -band 0x3) -bor ((([uint32][int]$value) -band 0x1F) -shl 3)) }
        }
    }
    return [pscustomobject]@{ Scale = 2; Value = 31; ActualUs = [uint64]3100; Raw = [uint32]((2 -band 0x3) -bor ((31 -band 0x1F) -shl 3)) }
}

function Format-PciL1ssPowerOnUs {
    param([Parameter(Mandatory=$true)][uint64]$Us)
    if ($Us -ge 1000 -and ($Us % 1000) -eq 0) { return ('{0} ms' -f [uint64]($Us / 1000)) }
    return ('{0} us' -f [uint64]$Us)
}

function Get-PciL1ssPowerOnRaw {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Scale,
        [Parameter(Mandatory=$true)][ValidateRange(0,31)][int]$Value
    )
    return [uint32]((([uint32]$Scale) -band 0x3) -bor ((([uint32]$Value) -band 0x1F) -shl 3))
}


function Get-PciExtendedCapabilityContext {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$CapabilityId
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ptr = 0x100
    $seen = @{}
    for ($i = 0; $i -lt 256 -and $ptr -ge 0x100 -and $ptr -le 0xFFC; $i++) {
        if (($ptr -band 0x3) -ne 0) {
            throw ('Unaligned PCIe extended capability pointer while searching for ExtCap 0x{0:X4} on {1}: offset 0x{2:X3}.' -f $CapabilityId, $bdf, $ptr)
        }
        if ($seen.ContainsKey($ptr)) {
            throw ('Loop detected while traversing PCIe extended capability list for {0}; repeated offset 0x{1:X3} while searching for ExtCap 0x{2:X4}.' -f $bdf, $ptr, $CapabilityId)
        }
        $seen[$ptr] = $true
        $header = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ptr -Width 32)
        if ($header -eq 0 -or $header -eq [uint32]::MaxValue) { break }
        $capId = [int]($header -band 0xFFFF)
        $version = [int](($header -shr 16) -band 0xF)
        $next = [int](($header -shr 20) -band 0xFFC)
        if ($capId -eq $CapabilityId) {
            return [pscustomobject]@{
                CapabilityOffset = [int]$ptr
                CapabilityId = [int]$capId
                Version = [int]$version
                HeaderRaw = [uint32]$header
                NextOffset = [int]$next
            }
        }
        if ($next -eq 0) { break }
        if ($next -lt 0x100 -or $next -gt 0xFFC) {
            throw ('Invalid PCIe extended capability next pointer while searching for ExtCap 0x{0:X4} on {1}: current 0x{2:X3}, next 0x{3:X3}, header 0x{4:X8}.' -f $CapabilityId, $bdf, $ptr, $next, [uint32]$header)
        }
        $ptr = $next
    }
    throw ('PCIe Extended Capability ID 0x{0:X4} was not found for {1}.' -f $CapabilityId, $bdf)
}

function ConvertTo-PciLaneMarginReceiverName {
    param([Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$ReceiverNumber)
    switch ($ReceiverNumber) {
        0 { 'No receiver' }
        1 { 'Downstream port receiver' }
        2 { 'First retimer upstream receiver' }
        3 { 'First retimer downstream receiver' }
        4 { 'Second retimer upstream receiver' }
        5 { 'Second retimer downstream receiver' }
        6 { 'Upstream port receiver' }
        default { ('Reserved receiver {0}' -f $ReceiverNumber) }
    }
}

function ConvertTo-PciLaneMarginCommandTypeName {
    param([Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$CommandType)
    switch ($CommandType) {
        1 { 'Report' }
        2 { 'Set' }
        3 { 'Step timing' }
        4 { 'Step voltage' }
        5 { 'Vendor defined' }
        7 { 'No command' }
        default { ('Reserved type {0}' -f $CommandType) }
    }
}

function ConvertTo-PciLaneMarginStatusName {
    param([Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Status)
    switch ($Status) {
        0 { 'Normal' }
        1 { 'Margining active' }
        2 { 'Nak or error limit' }
        3 { 'Unsupported or aborted' }
    }
}

function Get-PciLaneMarginCommandFields {
    param([Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$Value)
    $raw = [uint16]$Value
    $receiver = [int]($raw -band 0x0007)
    $type = [int](($raw -shr 3) -band 0x0007)
    $payload = [int](($raw -shr 8) -band 0x00FF)
    $errorCount = [int](($raw -shr 8) -band 0x003F)
    $status = [int](($raw -shr 14) -band 0x0003)
    [pscustomobject]@{
        Raw = [uint16]$raw
        ReceiverNumber = [int]$receiver
        ReceiverName = (ConvertTo-PciLaneMarginReceiverName -ReceiverNumber $receiver)
        CommandType = [int]$type
        CommandTypeName = (ConvertTo-PciLaneMarginCommandTypeName -CommandType $type)
        Payload = [byte]$payload
        PayloadHex = ('0x{0:X2}' -f $payload)
        ErrorCount = [int]$errorCount
        MarginStatusCode = [int]$status
        MarginStatusName = (ConvertTo-PciLaneMarginStatusName -Status $status)
        TimingStep = [int]($payload -band 0x3F)
        TimingGoLeft = [bool](($payload -band 0x40) -ne 0)
        VoltageStep = [int]($payload -band 0x7F)
        VoltageGoDown = [bool](($payload -band 0x80) -ne 0)
    }
}

function New-PciLaneMarginCommandWord {
    param(
        [Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$ReceiverNumber,
        [Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$CommandType,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$Payload
    )
    return [uint16]((([uint16]$ReceiverNumber) -band [uint16]0x0007) -bor ((([uint16]$CommandType) -band [uint16]0x0007) -shl 3) -bor ((([uint16]$Payload) -band [uint16]0x00FF) -shl 8))
}

function New-PciLaneMarginNamedCommandWord {
    param(
        [Parameter(Mandatory=$true)][ValidateSet('NoCommand','ReportCapabilities','ReportVoltageSteps','ReportTimingSteps','ReportTimingOffset','ReportVoltageOffset','ReportVoltageSampleRate','ReportTimingSampleRate','ReportSampleCount','ReportMaxLanes','SetErrorLimit','GoToNormalSettings','ClearErrorLog','StepTiming','StepVoltage','Raw')][string]$Command,
        [ValidateRange(0,6)][int]$ReceiverNumber = 0,
        [ValidateRange(0,255)][int]$Payload = 0,
        [ValidateRange(0,63)][int]$TimingSteps = 0,
        [ValidateRange(0,127)][int]$VoltageSteps = 0,
        [ValidateRange(0,63)][int]$ErrorLimit = 0,
        [switch]$GoLeft,
        [switch]$GoDown,
        [ValidateRange(0,65535)][int]$RawValue = 0
    )
    switch ($Command) {
        'NoCommand' { return (New-PciLaneMarginCommandWord -ReceiverNumber 0 -CommandType 7 -Payload 0x9C) }
        'ReportCapabilities' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x88) }
        'ReportVoltageSteps' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x89) }
        'ReportTimingSteps' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8A) }
        'ReportTimingOffset' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8B) }
        'ReportVoltageOffset' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8C) }
        'ReportVoltageSampleRate' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8D) }
        'ReportTimingSampleRate' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8E) }
        'ReportSampleCount' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x8F) }
        'ReportMaxLanes' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 1 -Payload 0x90) }
        'SetErrorLimit' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 2 -Payload (0xC0 -bor ($ErrorLimit -band 0x3F))) }
        'GoToNormalSettings' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 2 -Payload 0x0F) }
        'ClearErrorLog' { return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 2 -Payload 0x55) }
        'StepTiming' { $direction = if ($GoLeft) { 0x40 } else { 0 }; $p = (($TimingSteps -band 0x3F) -bor $direction); return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 3 -Payload $p) }
        'StepVoltage' { $direction = if ($GoDown) { 0x80 } else { 0 }; $p = (($VoltageSteps -band 0x7F) -bor $direction); return (New-PciLaneMarginCommandWord -ReceiverNumber $ReceiverNumber -CommandType 4 -Payload $p) }
        'Raw' { return [uint16]$RawValue }
    }
}

function Get-PciLaneMarginLinkInfo {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $lnkcap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkCapabilitiesOffset) -Width 32)
    $lnkctl = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkControlOffset) -Width 16)
    $lnksta = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkStatusOffset) -Width 16)
    $lnkctl2 = [uint16]0
    $lnksta2 = [uint16]0
    $link2Readable = $false
    try {
        if ([bool]$ctx.HasLink2Registers) {
            $lnkctl2 = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkControl2Offset) -Width 16)
            $lnksta2 = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkStatus2Offset) -Width 16)
            $link2Readable = $true
        }
    } catch { $link2Readable = $false }
    $speedCode = [int]($lnksta -band 0x000F)
    $width = [int](($lnksta -shr 4) -band 0x003F)
    $maxSpeedCode = [int]($lnkcap -band 0x0000000F)
    $maxWidth = [int](($lnkcap -shr 4) -band 0x003F)
    [pscustomobject]@{
        CapabilityOffset = [int]$ctx.CapabilityOffset
        LinkCapabilitiesRaw = [uint32]$lnkcap
        LinkControlRaw = [uint16]$lnkctl
        LinkStatusRaw = [uint16]$lnksta
        LinkControl2Raw = [uint16]$lnkctl2
        LinkStatus2Raw = [uint16]$lnksta2
        Link2Readable = [bool]$link2Readable
        CurrentSpeedCode = [int]$speedCode
        CurrentSpeedName = (ConvertTo-PciLinkSpeedName -Code $speedCode)
        CurrentWidth = [int]$width
        CurrentWidthName = (ConvertTo-PciLinkWidthName -Width $width)
        MaxSpeedCode = [int]$maxSpeedCode
        MaxSpeedName = (ConvertTo-PciLinkSpeedName -Code $maxSpeedCode)
        MaxWidth = [int]$maxWidth
        MaxWidthName = (ConvertTo-PciLinkWidthName -Width $maxWidth)
        HardwareAutonomousWidthDisable = [bool](($lnkctl -band [uint16]0x0200) -ne 0)
        HardwareAutonomousSpeedDisable = [bool](($lnkctl2 -band [uint16]0x0020) -ne 0)
        AspmControl = [int]($lnkctl -band [uint16]0x0003)
        SupportedAtCurrentSpeed = [bool]($speedCode -ge 4)
    }
}

function Invoke-PciLaneMarginCommand {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,4095)][int]$CapabilityOffset,
        [Parameter(Mandatory=$true)][ValidateRange(0,31)][int]$Lane,
        [Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$CommandWord,
        [ValidateRange(0,1000)][int]$DelayMilliseconds = 10,
        [switch]$ResetToNoCommand,
        [switch]$VerifyEcho
    )
    $ctrlOffset = $CapabilityOffset + 0x08 + ($Lane * 4)
    $statOffset = $CapabilityOffset + 0x0A + ($Lane * 4)
    if ($ctrlOffset -lt 0x100 -or $statOffset -gt 0xFFF) { throw ('Lane Margining lane register offset out of PCIe config-space bounds: Cap=0x{0:X3}, Lane={1}, Ctrl=0x{2:X3}, Status=0x{3:X3}.' -f $CapabilityOffset,$Lane,$ctrlOffset,$statOffset) }
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $word = [uint16]$CommandWord
    Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ctrlOffset -Width 16 -Value $word
    if ($DelayMilliseconds -gt 0) { Start-Sleep -Milliseconds $DelayMilliseconds }
    $statusWord = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $statOffset -Width 16)
    $controlReadback = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ctrlOffset -Width 16)
    if ($VerifyEcho -and $statusWord -ne $word) { throw ('Lane Margining command echo mismatch on {0}, Cap=0x{1:X3}, Lane={2}, Ctrl=0x{3:X3}, Status=0x{4:X3}: wrote 0x{5:X4}, status 0x{6:X4}, control readback 0x{7:X4}.' -f $bdf,$CapabilityOffset,$Lane,$ctrlOffset,$statOffset,$word,$statusWord,$controlReadback) }
    if ($ResetToNoCommand) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ctrlOffset -Width 16 -Value (New-PciLaneMarginNamedCommandWord -Command NoCommand) }
    [pscustomobject]@{
        Bdf = $bdf
        CapabilityOffset = [int]$CapabilityOffset
        Lane = [int]$Lane
        ControlOffset = [int]$ctrlOffset
        StatusOffset = [int]$statOffset
        CommandRaw = [uint16]$word
        Command = (Get-PciLaneMarginCommandFields -Value $word)
        ControlReadbackRaw = [uint16]$controlReadback
        ControlReadback = (Get-PciLaneMarginCommandFields -Value $controlReadback)
        StatusRaw = [uint16]$statusWord
        Status = (Get-PciLaneMarginCommandFields -Value $statusWord)
    }
}

function Get-PciLaneMarginReportValue {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,4095)][int]$CapabilityOffset,
        [Parameter(Mandatory=$true)][ValidateRange(0,31)][int]$Lane,
        [Parameter(Mandatory=$true)][ValidateRange(0,6)][int]$ReceiverNumber,
        [Parameter(Mandatory=$true)][ValidateSet('ReportCapabilities','ReportVoltageSteps','ReportTimingSteps','ReportTimingOffset','ReportVoltageOffset','ReportVoltageSampleRate','ReportTimingSampleRate','ReportSampleCount','ReportMaxLanes')][string]$Command
    )
    $word = New-PciLaneMarginNamedCommandWord -Command $Command -ReceiverNumber $ReceiverNumber
    $result = Invoke-PciLaneMarginCommand -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityOffset $CapabilityOffset -Lane $Lane -CommandWord $word -ResetToNoCommand
    $status = $result.Status
    $ok = ([int]$status.CommandType -eq 1 -and [int]$status.ReceiverNumber -eq $ReceiverNumber)
    [pscustomobject]@{
        Command = [string]$Command
        ReceiverNumber = [int]$ReceiverNumber
        ReceiverName = (ConvertTo-PciLaneMarginReceiverName -ReceiverNumber $ReceiverNumber)
        Lane = [int]$Lane
        Supported = [bool]$ok
        Raw = [uint16]$result.StatusRaw
        Payload = [byte]$status.Payload
        ErrorCount = [int]$status.ErrorCount
        MarginStatusCode = [int]$status.MarginStatusCode
        MarginStatusName = [string]$status.MarginStatusName
        Result = $result
    }
}

function Get-PciLaneMarginingState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [int[]]$Receivers = $null,
        [int[]]$Lanes = $null,
        [switch]$ProbeReportCapabilities
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ctx = Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId 0x0027
    $capOffset = [int]$ctx.CapabilityOffset
    if (($capOffset + 0x0B) -gt 0xFFF) { throw ('Lane Margining capability on {0} is truncated/out of PCIe config-space bounds. ExtCap27=0x{1:X3}.' -f $bdf,$capOffset) }
    $capabilityRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOffset + 0x04) -Width 16)
    $portStatusRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOffset + 0x06) -Width 16)
    $ready = (($portStatusRaw -band [uint16]0x0001) -ne 0)
    $softwareReady = (($portStatusRaw -band [uint16]0x0002) -ne 0)
    $link = Get-PciLaneMarginLinkInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $laneCount = [int]$link.CurrentWidth
    if ($laneCount -le 0) { $laneCount = [int]$link.MaxWidth }
    if ($laneCount -le 0) { $laneCount = 1 }
    $laneCount = [Math]::Min(32, [Math]::Max(1, $laneCount))
    if ($null -eq $Lanes -or $Lanes.Count -eq 0) { $Lanes = 0..($laneCount - 1) }
    $laneStates = New-Object System.Collections.Generic.List[object]
    foreach ($laneValue in @($Lanes)) {
        $lane = [int]$laneValue
        if ($lane -lt 0 -or $lane -ge 32) { throw ('Invalid Lane Margining lane {0} for {1}; valid decoded range is 0..31.' -f $lane,$bdf) }
        $ctrlOffset = $capOffset + 0x08 + ($lane * 4)
        $statOffset = $capOffset + 0x0A + ($lane * 4)
        if ($statOffset -gt 0xFFF) { throw ('Lane Margining per-lane register for {0}, lane {1}, exceeds PCIe config-space bounds: status offset 0x{2:X3}.' -f $bdf,$lane,$statOffset) }
        $ctrlRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ctrlOffset -Width 16)
        $statRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $statOffset -Width 16)
        $ctrl = Get-PciLaneMarginCommandFields -Value $ctrlRaw
        $stat = Get-PciLaneMarginCommandFields -Value $statRaw
        [void]$laneStates.Add([pscustomobject]@{
            Lane = [int]$lane
            ControlOffset = [int]$ctrlOffset
            StatusOffset = [int]$statOffset
            ControlRaw = [uint16]$ctrlRaw
            StatusRaw = [uint16]$statRaw
            Control = $ctrl
            Status = $stat
            ReceiverNumber = [int]$stat.ReceiverNumber
            ReceiverName = [string]$stat.ReceiverName
            CommandType = [int]$stat.CommandType
            CommandTypeName = [string]$stat.CommandTypeName
            Payload = [byte]$stat.Payload
            ErrorCount = [int]$stat.ErrorCount
            MarginStatusCode = [int]$stat.MarginStatusCode
            MarginStatusName = [string]$stat.MarginStatusName
            TimingStep = [int]$stat.TimingStep
            TimingGoLeft = [bool]$stat.TimingGoLeft
            VoltageStep = [int]$stat.VoltageStep
            VoltageGoDown = [bool]$stat.VoltageGoDown
        })
    }
    $receiverReports = New-Object System.Collections.Generic.List[object]
    if ($ProbeReportCapabilities -and $ready -and [bool]$link.SupportedAtCurrentSpeed) {
        if ($null -eq $Receivers -or $Receivers.Count -eq 0) { $Receivers = 1,2,3,4,5,6 }
        foreach ($receiverValue in @($Receivers)) {
            $receiver = [int]$receiverValue
            if ($receiver -lt 1 -or $receiver -gt 6) { throw ('Invalid Lane Margining receiver {0} for {1}; report receiver range is 1..6.' -f $receiver,$bdf) }
            $reports = @{}
            $errors = New-Object System.Collections.Generic.List[string]
            foreach ($cmd in @('ReportCapabilities','ReportVoltageSteps','ReportTimingSteps','ReportTimingOffset','ReportVoltageOffset','ReportVoltageSampleRate','ReportTimingSampleRate','ReportSampleCount','ReportMaxLanes')) {
                try { $reports[$cmd] = Get-PciLaneMarginReportValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityOffset $capOffset -Lane 0 -ReceiverNumber $receiver -Command $cmd }
                catch { [void]$errors.Add(('{0}: {1}' -f $cmd,$_.Exception.Message)) }
            }
            $capsPayload = if ($reports.ContainsKey('ReportCapabilities')) { [int]$reports['ReportCapabilities'].Payload } else { 0 }
            $voltageSupported = (($capsPayload -band 0x01) -ne 0)
            $independentVoltage = (($capsPayload -band 0x02) -ne 0)
            $independentTiming = (($capsPayload -band 0x04) -ne 0)
            $sampleReporting = (($capsPayload -band 0x08) -ne 0)
            $independentErrorSampler = (($capsPayload -band 0x10) -ne 0)
            [void]$receiverReports.Add([pscustomobject]@{
                ReceiverNumber = [int]$receiver
                ReceiverName = (ConvertTo-PciLaneMarginReceiverName -ReceiverNumber $receiver)
                ReportsSupported = [bool]($reports.ContainsKey('ReportCapabilities') -and [bool]$reports['ReportCapabilities'].Supported)
                VoltageMarginSupported = [bool]$voltageSupported
                IndependentVoltageMarginSupported = [bool]$independentVoltage
                IndependentTimingMarginSupported = [bool]$independentTiming
                SampleReportingMethodSupported = [bool]$sampleReporting
                IndependentErrorSamplerSupported = [bool]$independentErrorSampler
                MaxVoltageSteps = if ($reports.ContainsKey('ReportVoltageSteps')) { [int]($reports['ReportVoltageSteps'].Payload -band 0x7F) } else { 0 }
                MaxTimingSteps = if ($reports.ContainsKey('ReportTimingSteps')) { [int]($reports['ReportTimingSteps'].Payload -band 0x3F) } else { 0 }
                MaxTimingOffset = if ($reports.ContainsKey('ReportTimingOffset')) { [int]($reports['ReportTimingOffset'].Payload -band 0x7F) } else { 0 }
                MaxVoltageOffset = if ($reports.ContainsKey('ReportVoltageOffset')) { [int]($reports['ReportVoltageOffset'].Payload -band 0x7F) } else { 0 }
                VoltageSampleRate = if ($reports.ContainsKey('ReportVoltageSampleRate')) { [int]($reports['ReportVoltageSampleRate'].Payload -band 0x3F) } else { 0 }
                TimingSampleRate = if ($reports.ContainsKey('ReportTimingSampleRate')) { [int]($reports['ReportTimingSampleRate'].Payload -band 0x3F) } else { 0 }
                SampleCount = if ($reports.ContainsKey('ReportSampleCount')) { [int]$reports['ReportSampleCount'].Payload } else { 0 }
                MaxLanes = if ($reports.ContainsKey('ReportMaxLanes')) { [int]($reports['ReportMaxLanes'].Payload -band 0x1F) } else { 0 }
                RawReports = [hashtable]$reports
                Errors = [string[]]$errors.ToArray()
            })
        }
    }
    $usesDriverSoftware = (($capabilityRaw -band [uint16]0x0001) -ne 0)
    $marginErrors = 0
    foreach ($lane in @($laneStates.ToArray())) { if ([int]$lane.MarginStatusCode -ge 2) { $marginErrors++ } }
    $display = 'LMR@0x{0:X3} ready={1}/{2} usesDrv={3} speed={4} supportedNow={5} width=x{6} lanes={7} errors={8} HAWD/HASD={9}/{10} cap=0x{11:X4} portSts=0x{12:X4}' -f $capOffset,$ready,$softwareReady,$usesDriverSoftware,[string]$link.CurrentSpeedName,[bool]$link.SupportedAtCurrentSpeed,[int]$link.CurrentWidth,[int]$laneStates.Count,$marginErrors,[bool]$link.HardwareAutonomousWidthDisable,[bool]$link.HardwareAutonomousSpeedDisable,[uint16]$capabilityRaw,[uint16]$portStatusRaw
    [pscustomobject]@{
        Bdf = $bdf
        Segment = [int]$Segment
        Bus = [int]$Bus
        Device = [int]$Device
        Function = [int]$Function
        Present = $true
        CapabilityOffset = [int]$capOffset
        CapabilityVersion = [int]$ctx.Version
        HeaderRaw = [uint32]$ctx.HeaderRaw
        CapabilityRaw = [uint16]$capabilityRaw
        PortStatusRaw = [uint16]$portStatusRaw
        UsesDriverSoftware = [bool]$usesDriverSoftware
        Ready = [bool]$ready
        SoftwareReady = [bool]$softwareReady
        SupportedAtCurrentSpeed = [bool]$link.SupportedAtCurrentSpeed
        CurrentSpeedCode = [int]$link.CurrentSpeedCode
        CurrentSpeedName = [string]$link.CurrentSpeedName
        CurrentWidth = [int]$link.CurrentWidth
        MaxWidth = [int]$link.MaxWidth
        HardwareAutonomousWidthDisable = [bool]$link.HardwareAutonomousWidthDisable
        HardwareAutonomousSpeedDisable = [bool]$link.HardwareAutonomousSpeedDisable
        LaneCountDecoded = [int]$laneStates.Count
        Lanes = [object[]]$laneStates.ToArray()
        ReceiverReports = [object[]]$receiverReports.ToArray()
        ProbeReportCapabilities = [bool]$ProbeReportCapabilities
        MarginErrorLaneCount = [int]$marginErrors
        DisplayText = [string]$display
    }
}

function Set-PciLaneMarginingState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [ValidateSet('NoCommand','ReportCapabilities','ReportVoltageSteps','ReportTimingSteps','ReportTimingOffset','ReportVoltageOffset','ReportVoltageSampleRate','ReportTimingSampleRate','ReportSampleCount','ReportMaxLanes','SetErrorLimit','GoToNormalSettings','ClearErrorLog','StepTiming','StepVoltage','Raw')][string]$Command = 'NoCommand',
        [int[]]$Lanes = $null,
        [ValidateRange(0,6)][int]$ReceiverNumber = 0,
        [ValidateRange(0,63)][int]$TimingSteps = 0,
        [ValidateRange(0,127)][int]$VoltageSteps = 0,
        [ValidateRange(0,63)][int]$ErrorLimit = 0,
        [switch]$GoLeft,
        [switch]$GoDown,
        [ValidateRange(0,65535)][int]$RawCommand = 0,
        [switch]$VerifyEcho,
        [switch]$ReadBack,
        [switch]$ResetToNoCommand
    )
    $ctx = Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId 0x0027
    $capOffset = [int]$ctx.CapabilityOffset
    $link = Get-PciLaneMarginLinkInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $portStatusRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOffset + 0x06) -Width 16)
    $ready = (($portStatusRaw -band [uint16]0x0001) -ne 0)
    $receiverCommand = ($Command -notin @('NoCommand','Raw'))
    if ($receiverCommand -and ($ReceiverNumber -lt 1 -or $ReceiverNumber -gt 6)) { throw ('Lane Margining command {0} requires a receiver number in 1..6; got {1}.' -f $Command,$ReceiverNumber) }
    if ($receiverCommand -and -not [bool]$link.SupportedAtCurrentSpeed) { throw ('Lane Margining command {0} refused on {1}: current link speed is {2}; LMR is defined for 16.0 GT/s and faster links.' -f $Command,([DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)),[string]$link.CurrentSpeedName) }
    if ($receiverCommand -and -not $ready) { throw ('Lane Margining command {0} refused on {1}: Port Status Margining Ready bit is clear. PortStatus=0x{2:X4}.' -f $Command,([DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)),[uint16]$portStatusRaw) }
    $laneCount = [int]$link.CurrentWidth
    if ($laneCount -le 0) { $laneCount = [int]$link.MaxWidth }
    if ($laneCount -le 0) { $laneCount = 1 }
    $laneCount = [Math]::Min(32, [Math]::Max(1, $laneCount))
    if ($null -eq $Lanes -or $Lanes.Count -eq 0) { $Lanes = 0..($laneCount - 1) }
    $word = New-PciLaneMarginNamedCommandWord -Command $Command -ReceiverNumber $ReceiverNumber -TimingSteps $TimingSteps -VoltageSteps $VoltageSteps -ErrorLimit $ErrorLimit -GoLeft:$GoLeft -GoDown:$GoDown -RawValue $RawCommand
    $effectiveResetToNoCommand = ($ResetToNoCommand -or ([string]$Command -ne 'Raw'))
    $results = New-Object System.Collections.Generic.List[object]
    foreach ($laneValue in @($Lanes)) {
        $lane = [int]$laneValue
        if ($lane -lt 0 -or $lane -ge 32) { throw ('Invalid Lane Margining lane {0}; valid decoded range is 0..31.' -f $lane) }
        [void]$results.Add((Invoke-PciLaneMarginCommand -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityOffset $capOffset -Lane $lane -CommandWord $word -VerifyEcho:$VerifyEcho -ResetToNoCommand:$effectiveResetToNoCommand))
    }
    $state = if ($ReadBack) { Get-PciLaneMarginingState -Segment $Segment -Bus $Bus -Device $Device -Function $Function } else { $null }
    [pscustomobject]@{
        Bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
        CapabilityOffset = [int]$capOffset
        Command = [string]$Command
        CommandRaw = [uint16]$word
        LanesWritten = [int[]]$Lanes
        WriteResults = [object[]]$results.ToArray()
        State = $state
    }
}


function Test-PciFunctionPresent {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    try {
        $vendor = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x00 -Width 16)
        return ($vendor -ne 0xFFFF -and $vendor -ne 0x0000)
    } catch { return $false }
}

function Get-PciHeaderType {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    return [int](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x0E -Width 8)
}

function Test-PciBridgeFunction {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    try { return (((Get-PciHeaderType -Segment $Segment -Bus $Bus -Device $Device -Function $Function) -band 0x7F) -eq 0x01) }
    catch { return $false }
}

function Get-PciBridgeBusNumbers {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $raw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x18 -Width 32)
    [pscustomobject]@{
        Primary = [int]($raw -band 0xFF)
        Secondary = [int](($raw -shr 8) -band 0xFF)
        Subordinate = [int](($raw -shr 16) -band 0xFF)
        Raw = [uint32]$raw
    }
}

function Get-PciExpressPortType {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $cap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.CapabilityOffset + 0x02) -Width 16)
    return [int](($cap -shr 4) -band 0xF)
}

function ConvertTo-PciExpressPortTypeName {
    param([Parameter(Mandatory=$true)][int]$PortType)
    switch ($PortType) {
        0 { 'Endpoint'; break }
        1 { 'Legacy Endpoint'; break }
        4 { 'Root Port'; break }
        5 { 'Upstream Port'; break }
        6 { 'Downstream Port'; break }
        7 { 'PCIe-to-PCI/PCI-X Bridge'; break }
        8 { 'PCI/PCI-X-to-PCIe Bridge'; break }
        9 { 'Root Complex Integrated Endpoint'; break }
        10 { 'Root Complex Event Collector'; break }
        default { ('Type {0}' -f $PortType) }
    }
}

function Test-PciExtendedCapabilityPresent {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,65535)][int]$CapabilityId
    )
    try { [void](Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId $CapabilityId); return $true }
    catch { return $false }
}

function ConvertTo-PciRebarSizeBytes {
    param([Parameter(Mandatory=$true)][ValidateRange(0,43)][int]$Encoded)
    return [uint64](([uint64]1) -shl ($Encoded + 20))
}

function ConvertTo-PciRebarSizeText {
    param([Parameter(Mandatory=$true)][uint64]$Bytes)
    $eb = [uint64]1152921504606846976
    $pb = [uint64]1125899906842624
    $tb = [uint64]1099511627776
    $gb = [uint64]1073741824
    $mb = [uint64]1048576
    if ($Bytes -ge $eb -and ($Bytes % $eb) -eq 0) { return ('{0} EB' -f [uint64]($Bytes / $eb)) }
    if ($Bytes -ge $pb -and ($Bytes % $pb) -eq 0) { return ('{0} PB' -f [uint64]($Bytes / $pb)) }
    if ($Bytes -ge $tb -and ($Bytes % $tb) -eq 0) { return ('{0} TB' -f [uint64]($Bytes / $tb)) }
    if ($Bytes -ge $gb -and ($Bytes % $gb) -eq 0) { return ('{0} GB' -f [uint64]($Bytes / $gb)) }
    if ($Bytes -ge $mb -and ($Bytes % $mb) -eq 0) { return ('{0} MB' -f [uint64]($Bytes / $mb)) }
    return ('{0} bytes' -f [uint64]$Bytes)
}

function ConvertTo-PciRebarSupportedSizeSummary {
    param([Parameter(Mandatory=$true)][uint64]$NormalizedMask)
    $names = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -le 43; $i++) {
        if (($NormalizedMask -band (([uint64]1) -shl $i)) -ne 0) { [void]$names.Add((ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded $i))) }
    }
    if ($names.Count -eq 0) { return 'none' }
    return ($names -join ', ')
}

function Get-PciRebarBarDescriptor {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,5)][int]$BarIndex
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    if ($BarIndex -gt 0) {
        $previousLowOffset = 0x10 + (($BarIndex - 1) * 4)
        $previousLow = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $previousLowOffset -Width 32)
        $previousIsIo = (($previousLow -band [uint32]0x1) -ne 0)
        $previousIs64 = (-not $previousIsIo) -and (($previousLow -band [uint32]0x6) -eq 0x4)
        if ($previousIs64) { throw ('BAR{0} on {1} is the upper DWORD of 64-bit BAR{2}; it is not a separately decodable BAR. LowRaw(BAR{2})=0x{3:X8}.' -f $BarIndex,$bdf,($BarIndex - 1),[uint32]$previousLow) }
    }
    $lowOffset = 0x10 + ($BarIndex * 4)
    $low = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $lowOffset -Width 32)
    $isIo = (($low -band 0x1) -ne 0)
    $is64 = (-not $isIo) -and (($low -band 0x6) -eq 0x4)
    if ($is64 -and $BarIndex -eq 5) { throw ('Invalid 64-bit BAR descriptor: {0} BAR5 reports a high DWORD beyond config-space BAR array. LowRaw=0x{1:X8}.' -f $bdf, [uint32]$low) }
    $high = [uint32]0
    if ($is64) { $high = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($lowOffset + 4) -Width 32) }
    $base = [uint64]0
    if ($isIo) { $base = [uint64]($low -band 0xFFFFFFFC) }
    elseif ($is64) { $base = (([uint64]$high) -shl 32) -bor ([uint64]($low -band 0xFFFFFFF0)) }
    else { $base = [uint64]($low -band 0xFFFFFFF0) }
    [pscustomobject]@{
        BarIndex = [int]$BarIndex
        LowOffset = [int]$lowOffset
        HighOffset = if ($is64) { [int]($lowOffset + 4) } else { [int]-1 }
        LowRaw = [uint32]$low
        HighRaw = [uint32]$high
        IsIo = [bool]$isIo
        Is64Bit = [bool]$is64
        IsPrefetchable = [bool]((-not $isIo) -and (($low -band 0x8) -ne 0))
        BaseAddress = [uint64]$base
    }
}

function Get-PciRebarNormalizedMask {
    param(
        [Parameter(Mandatory=$true)][uint32]$CapabilityRaw,
        [Parameter(Mandatory=$true)][uint32]$ControlRaw,
        [Parameter(Mandatory=$true)][uint32]$VendorId,
        [Parameter(Mandatory=$true)][uint32]$DeviceId,
        [Parameter(Mandatory=$true)][int]$BarIndex
    )
    $lowMask = [uint64]((([uint64]$CapabilityRaw) -band 0xFFFFFFF0) -shr 4)
    $highMask = [uint64]((((([uint64]$ControlRaw) -band 0xFFFF0000) -shr 16) -band 0xFFFF) -shl 28)
    $mask = [uint64]($lowMask -bor $highMask)
    if ($VendorId -eq 0x1002 -and $DeviceId -eq 0x731F -and $BarIndex -eq 0 -and $lowMask -eq 0x700) { $mask = [uint64]0x3F00 }
    return [uint64]$mask
}

function Get-PciRebarState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [ValidateRange(0,5)][int]$SelectedBarIndex = 0
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $id = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x00 -Width 32)
    $vendorId = [uint32]($id -band 0xFFFF)
    $deviceId = [uint32](($id -shr 16) -band 0xFFFF)
    if ($vendorId -eq 0xFFFF -or $vendorId -eq 0x0000) { throw ('Cannot read valid PCI vendor ID for ReBAR on {0}; raw ID=0x{1:X8}.' -f $bdf, [uint32]$id) }
    $ctx = Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId 0x0015
    $firstCtrlOffset = [int]$ctx.CapabilityOffset + 0x08
    $firstCtrl = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $firstCtrlOffset -Width 32)
    $nbar = [int](($firstCtrl -band 0xE0) -shr 5)
    if ($nbar -lt 1 -or $nbar -gt 6) { throw ('Invalid ReBAR Number-of-BARs field on {0}; ExtCap15=0x{1:X3}; Ctrl0Offset=0x{2:X3}; Ctrl0=0x{3:X8}; NBAR={4}.' -f $bdf, [int]$ctx.CapabilityOffset, $firstCtrlOffset, [uint32]$firstCtrl, $nbar) }
    $entries = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $nbar; $i++) {
        $capOffset = [int]$ctx.CapabilityOffset + 0x04 + ($i * 8)
        $ctrlOffset = [int]$ctx.CapabilityOffset + 0x08 + ($i * 8)
        if ($ctrlOffset -gt 0xFFF) { throw ('ReBAR structure extends beyond PCIe config space on {0}; ExtCap15=0x{1:X3}; Entry={2}; ControlOffset=0x{3:X3}.' -f $bdf, [int]$ctx.CapabilityOffset, $i, $ctrlOffset) }
        $capRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $capOffset -Width 32)
        $ctrlRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ctrlOffset -Width 32)
        $barIndex = [int]($ctrlRaw -band 0x7)
        $sizeEncoded = [int](($ctrlRaw -band 0x3F00) -shr 8)
        $mask = Get-PciRebarNormalizedMask -CapabilityRaw $capRaw -ControlRaw $ctrlRaw -VendorId $vendorId -DeviceId $deviceId -BarIndex $barIndex
        if ($mask -eq 0) { throw ('ReBAR entry has zero supported-size mask on {0}; Entry={1}; BAR={2}; CapOffset=0x{3:X3}; CapRaw=0x{4:X8}; CtrlRaw=0x{5:X8}.' -f $bdf, $i, $barIndex, $capOffset, [uint32]$capRaw, [uint32]$ctrlRaw) }
        $supported = New-Object System.Collections.Generic.List[int]
        for ($enc = 0; $enc -le 43; $enc++) { if (($mask -band (([uint64]1) -shl $enc)) -ne 0) { [void]$supported.Add([int]$enc) } }
        if ($supported.Count -eq 0) { throw ('ReBAR entry supports no decoded sizes on {0}; Entry={1}; BAR={2}; Mask=0x{3:X}.' -f $bdf, $i, $barIndex, [uint64]$mask) }
        $minEnc = [int]$supported[0]
        $maxEnc = [int]$supported[$supported.Count - 1]
        $barDesc = Get-PciRebarBarDescriptor -Segment $Segment -Bus $Bus -Device $Device -Function $Function -BarIndex $barIndex
        $capAddr = [DeviceTweakerPciEcam]::ResolveAddress($Segment, $Bus, $Device, $Function, $capOffset)
        $ctrlAddr = [DeviceTweakerPciEcam]::ResolveAddress($Segment, $Bus, $Device, $Function, $ctrlOffset)
        [void]$entries.Add([pscustomobject]@{
            EntryIndex = [int]$i; BarIndex = [int]$barIndex; CapabilityOffset = [int]$capOffset; ControlOffset = [int]$ctrlOffset
            CapabilityEcamAddress = [uint64]$capAddr; ControlEcamAddress = [uint64]$ctrlAddr; CapabilityRaw = [uint32]$capRaw; ControlRaw = [uint32]$ctrlRaw
            SupportedMask = [uint64]$mask; SupportedEncodedSizes = [int[]]$supported.ToArray(); SupportedText = (ConvertTo-PciRebarSupportedSizeSummary -NormalizedMask $mask)
            CurrentSizeEncoded = [int]$sizeEncoded; CurrentSizeBytes = [uint64](ConvertTo-PciRebarSizeBytes -Encoded $sizeEncoded); CurrentSizeText = (ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded $sizeEncoded))
            MinSupportedEncoded = [int]$minEnc; MaxSupportedEncoded = [int]$maxEnc; MinSupportedText = (ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded $minEnc)); MaxSupportedText = (ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded $maxEnc))
            BarBaseAddress = [uint64]$barDesc.BaseAddress; BarLowOffset = [int]$barDesc.LowOffset; BarHighOffset = [int]$barDesc.HighOffset; BarLowRaw = [uint32]$barDesc.LowRaw; BarHighRaw = [uint32]$barDesc.HighRaw; BarIs64Bit = [bool]$barDesc.Is64Bit; BarIsIo = [bool]$barDesc.IsIo; BarIsPrefetchable = [bool]$barDesc.IsPrefetchable
        })
    }
    $selected = $null
    foreach ($e in @($entries.ToArray())) { if ([int]$e.BarIndex -eq $SelectedBarIndex) { $selected = $e; break } }
    if ($null -eq $selected) { $selected = $entries[0] }
    $effectiveEnabled = ([int]$selected.CurrentSizeEncoded -gt 8)
    $entryParts = New-Object System.Collections.Generic.List[string]
    foreach ($e in @($entries.ToArray())) { [void]$entryParts.Add(('BAR{0}:cur {1};max {2};cap 0x{3:X3};ctl 0x{4:X3};ECAM 0x{5:X}' -f [int]$e.BarIndex, [string]$e.CurrentSizeText, [string]$e.MaxSupportedText, [int]$e.CapabilityOffset, [int]$e.ControlOffset, [uint64]$e.ControlEcamAddress)) }
    $enabledText = if ($effectiveEnabled) { 'on' } else { 'off/legacy' }
    $display = ('ReBAR {0}; {1}; ExtCap15 0x{2:X3} v{3}; selected BAR{4} current {5} enc {6}; supported {7}; entries {8}' -f $enabledText, $bdf, [int]$ctx.CapabilityOffset, [int]$ctx.Version, [int]$selected.BarIndex, [string]$selected.CurrentSizeText, [int]$selected.CurrentSizeEncoded, [string]$selected.SupportedText, ($entryParts -join ' | '))
    [pscustomobject]@{
        Bdf = [string]$bdf; Segment = [int]$Segment; Bus = [int]$Bus; Device = [int]$Device; Function = [int]$Function; VendorId = [uint32]$vendorId; DeviceId = [uint32]$deviceId
        CapabilityOffset = [int]$ctx.CapabilityOffset; CapabilityVersion = [int]$ctx.Version; CapabilityHeaderRaw = [uint32]$ctx.HeaderRaw; NumberOfResizableBars = [int]$nbar
        SelectedBarIndex = [int]$selected.BarIndex; EffectiveEnabled = [bool]$effectiveEnabled; Entries = [object[]]$entries.ToArray(); SelectedEntry = $selected; DisplayText = [string]$display
    }
}

function Set-PciRebarState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,5)][int]$BarIndex,
        [Parameter(Mandatory=$true)][bool]$Enable,
        [AllowNull()][object]$TargetSizeEncoded = $null
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $state = Get-PciRebarState -Segment $Segment -Bus $Bus -Device $Device -Function $Function -SelectedBarIndex $BarIndex
    $entry = $null
    foreach ($e in @($state.Entries)) { if ([int]$e.BarIndex -eq $BarIndex) { $entry = $e; break } }
    if ($null -eq $entry) { throw ('ReBAR BAR{0} is not implemented by {1}. Implemented BARs: {2}.' -f $BarIndex, $bdf, (($state.Entries | ForEach-Object { 'BAR' + [int]$_.BarIndex }) -join ', ')) }
    $targetEnc = -1
    if ($null -ne $TargetSizeEncoded -and [string]$TargetSizeEncoded -ne '') { $targetEnc = [int]$TargetSizeEncoded }
    elseif ($Enable) { $targetEnc = [int]$entry.MaxSupportedEncoded }
    else { $targetEnc = if ((([uint64]$entry.SupportedMask) -band (([uint64]1) -shl 8)) -ne 0) { 8 } else { [int]$entry.MinSupportedEncoded } }
    if ($targetEnc -lt 0 -or $targetEnc -gt 43) { throw ('Invalid ReBAR target size encoding for {0} BAR{1}: {2}; valid PCIe ReBAR encodings are 0..43 (1 MB..8 EB).' -f $bdf, $BarIndex, $targetEnc) }
    if ((([uint64]$entry.SupportedMask) -band (([uint64]1) -shl $targetEnc)) -eq 0) { throw ('Unsupported ReBAR size for {0} BAR{1}: encoding {2} ({3}). Supported encodings: {4}; supported sizes: {5}.' -f $bdf, $BarIndex, $targetEnc, (ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded $targetEnc)), (([int[]]$entry.SupportedEncodedSizes) -join ','), [string]$entry.SupportedText) }
    if ([int]$entry.CurrentSizeEncoded -eq $targetEnc) { return (Get-PciRebarState -Segment $Segment -Bus $Bus -Device $Device -Function $Function -SelectedBarIndex $BarIndex) }
    $targetBytes = [uint64](ConvertTo-PciRebarSizeBytes -Encoded $targetEnc)
    $currentBytes = [uint64]$entry.CurrentSizeBytes
    $bar = Get-PciRebarBarDescriptor -Segment $Segment -Bus $Bus -Device $Device -Function $Function -BarIndex $BarIndex
    if ($bar.IsIo) { throw ('Cannot program ReBAR on {0} BAR{1}: BAR is I/O space, LowRaw=0x{2:X8}.' -f $bdf, $BarIndex, [uint32]$bar.LowRaw) }
    if ($targetBytes -ge [uint64]4294967296 -and -not $bar.Is64Bit) { throw ('Cannot program ReBAR target {0} on {1} BAR{2}: target is 4GB or larger but BAR is not 64-bit. LowRaw=0x{3:X8}.' -f (ConvertTo-PciRebarSizeText -Bytes $targetBytes), $bdf, $BarIndex, [uint32]$bar.LowRaw) }
    if ($targetBytes -gt $currentBytes) {
        if ([uint64]$bar.BaseAddress -eq 0) { throw ('Cannot enlarge ReBAR live on {0} BAR{1}: BAR base address is zero/unassigned. Requested {2}; Current {3}; LowRaw=0x{4:X8}; HighRaw=0x{5:X8}.' -f $bdf, $BarIndex, (ConvertTo-PciRebarSizeText -Bytes $targetBytes), (ConvertTo-PciRebarSizeText -Bytes $currentBytes), [uint32]$bar.LowRaw, [uint32]$bar.HighRaw) }
        if ((([uint64]$bar.BaseAddress) % $targetBytes) -ne 0) { throw ('Cannot enlarge ReBAR live on {0} BAR{1}: existing BAR base 0x{2:X} is not aligned to requested aperture {3}. Firmware/OS resource reallocation is required before this size can be made safe.' -f $bdf, $BarIndex, [uint64]$bar.BaseAddress, (ConvertTo-PciRebarSizeText -Bytes $targetBytes)) }
    }
    $cmdOffset = 0x04
    $commandOriginal = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $cmdOffset -Width 16)
    $memoryEnabled = (($commandOriginal -band 0x2) -ne 0)
    $ctrlOriginal = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$entry.ControlOffset) -Width 32)
    $ctrlNew = [uint32](($ctrlOriginal -band ([uint32]4294951167)) -bor ([uint32]($targetEnc -shl 8)))
    try {
        if ($memoryEnabled) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $cmdOffset -Width 16 -Value ([uint32]($commandOriginal -band ([uint32]0xFFFD))) }
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$entry.ControlOffset) -Width 32 -Value $ctrlNew
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$bar.LowOffset) -Width 32 -Value ([uint32]$bar.LowRaw)
        if ($bar.Is64Bit) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$bar.HighOffset) -Width 32 -Value ([uint32]$bar.HighRaw) }
    } finally {
        try { if ($memoryEnabled) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $cmdOffset -Width 16 -Value ([uint32]$commandOriginal) } } catch { }
    }
    $verify = Get-PciRebarState -Segment $Segment -Bus $Bus -Device $Device -Function $Function -SelectedBarIndex $BarIndex
    $verifyEntry = $null
    foreach ($e in @($verify.Entries)) { if ([int]$e.BarIndex -eq $BarIndex) { $verifyEntry = $e; break } }
    if ($null -eq $verifyEntry -or [int]$verifyEntry.CurrentSizeEncoded -ne $targetEnc) {
        $readBackText = if ($null -eq $verifyEntry) { 'missing' } else { [string]$verifyEntry.CurrentSizeEncoded + ' (' + [string]$verifyEntry.CurrentSizeText + ')' }
        throw ('ReBAR verify failed on {0} BAR{1}: requested encoding {2} ({3}), read back {4}; ControlOffset=0x{5:X3}; WroteControl=0x{6:X8}.' -f $bdf, $BarIndex, $targetEnc, (ConvertTo-PciRebarSizeText -Bytes $targetBytes), $readBackText, [int]$entry.ControlOffset, [uint32]$ctrlNew)
    }
    return $verify
}



function ConvertTo-PciFeatureMaskNames {
    param(
        [Parameter(Mandatory=$true)][uint32]$Mask,
        [Parameter(Mandatory=$true)][object[]]$Definitions,
        [string]$NoneText = 'none'
    )
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($def in @($Definitions)) {
        if ($null -eq $def) { continue }
        $bit = [uint32]$def.Bit
        if (($Mask -band $bit) -ne 0) { [void]$names.Add([string]$def.Name) }
    }
    if ($names.Count -eq 0) { return $NoneText }
    return ($names -join ',')
}

function Get-PciAcsBaseFeatureDefinitions {
    return @(
        [pscustomobject]@{ Bit = [uint32]0x0001; Name = 'SV' },
        [pscustomobject]@{ Bit = [uint32]0x0002; Name = 'TB' },
        [pscustomobject]@{ Bit = [uint32]0x0004; Name = 'RR' },
        [pscustomobject]@{ Bit = [uint32]0x0008; Name = 'CR' },
        [pscustomobject]@{ Bit = [uint32]0x0010; Name = 'UF' },
        [pscustomobject]@{ Bit = [uint32]0x0020; Name = 'EC' },
        [pscustomobject]@{ Bit = [uint32]0x0040; Name = 'DT' }
    )
}

function Get-PciAcsEgressVectorDwordCount {
    param([Parameter(Mandatory=$true)][uint16]$AcsCapabilityRaw)
    if (([uint32]$AcsCapabilityRaw -band [uint32]0x0020) -eq 0) { return 0 }
    $bits = [int]((([uint32]$AcsCapabilityRaw) -shr 8) -band 0xFF)
    if ($bits -le 0) { return 0 }
    return [int][Math]::Ceiling(([double]$bits) / 32.0)
}

function Format-PciDwordArrayText {
    param([AllowNull()][object]$Values)
    if ($null -eq $Values) { return '' }
    $items = New-Object System.Collections.Generic.List[string]
    foreach ($value in @($Values)) { [void]$items.Add(('0x{0:X8}' -f [uint32]$value)) }
    return ($items -join ',')
}

function ConvertTo-PciUInt32Array {
    param([AllowNull()][object]$Value)
    $items = New-Object System.Collections.Generic.List[uint32]
    if ($null -eq $Value) { return [uint32[]]$items.ToArray() }
    $rawItems = @()
    if ($Value -is [string]) {
        $rawItems = @(([string]$Value) -split '[,;\s]+')
    } else {
        $rawItems = @($Value)
    }
    foreach ($raw in $rawItems) {
        if ($null -eq $raw) { continue }
        $token = ([string]$raw).Trim()
        if ([string]::IsNullOrWhiteSpace($token)) { continue }
        if ($token.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$items.Add([Convert]::ToUInt32($token.Substring(2), 16))
        } else {
            [void]$items.Add([Convert]::ToUInt32($token, 0))
        }
    }
    return [uint32[]]$items.ToArray()
}

function ConvertTo-PciUInt8Array {
    param([AllowNull()][object]$Value)
    $items = New-Object System.Collections.Generic.List[byte]
    if ($null -eq $Value) { return [byte[]]$items.ToArray() }
    foreach ($rawItem in @($Value)) {
        if ($null -eq $rawItem) { continue }
        $tokens = @($rawItem)
        if ($rawItem -is [string]) { $tokens = @(([string]$rawItem) -split '[,;\s]+') }
        foreach ($raw in $tokens) {
            if ($null -eq $raw) { continue }
            $token = ([string]$raw).Trim()
            if ([string]::IsNullOrWhiteSpace($token)) { continue }
            $parsed = [uint32]0
            if ($token.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
                $parsed = [Convert]::ToUInt32($token.Substring(2), 16)
            } else {
                $parsed = [Convert]::ToUInt32($token, 10)
            }
            if ($parsed -gt 255) { throw ('PCIe byte value out of range: {0}' -f $token) }
            [void]$items.Add([byte]$parsed)
        }
    }
    return [byte[]]$items.ToArray()
}


function Get-PciCapabilityList {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $items = New-Object System.Collections.Generic.List[object]
    $status = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x06 -Width 16)
    if (($status -band [uint16]0x0010) -eq 0) { return [object[]]@() }
    $ptr = [int]((Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset 0x34 -Width 8) -band [uint32]0xFC)
    $seen = @{}
    for ($i = 0; $i -lt 64 -and $ptr -ge 0x40 -and $ptr -le 0xFC; $i++) {
        if (($ptr -band 0x3) -ne 0) { throw ('Unaligned PCI conventional capability pointer on {0}: offset 0x{1:X2}.' -f $bdf,$ptr) }
        if ($seen.ContainsKey($ptr)) { throw ('Loop detected while traversing PCI conventional capability list for {0}; repeated offset 0x{1:X2}.' -f $bdf,$ptr) }
        $seen[$ptr] = $true
        $capId = [int](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ptr -Width 8)
        if ($capId -eq 0 -or $capId -eq 0xFF) { break }
        $next = [int]((Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($ptr + 1) -Width 8) -band [uint32]0xFC)
        $headerRaw = [uint32]0
        if ($ptr -le 0xFC) { $headerRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ptr -Width 32) }
        [void]$items.Add([pscustomobject]@{
            Offset = [int]$ptr
            Id = [int]$capId
            HeaderRaw = [uint32]$headerRaw
            NextOffset = [int]$next
            IsConventional = $true
        })
        if ($next -eq 0) { break }
        if ($next -lt 0x40 -or $next -gt 0xFC) { throw ('Invalid PCI conventional capability next pointer on {0}: current 0x{1:X2}, next 0x{2:X2}, header 0x{3:X8}.' -f $bdf,$ptr,$next,[uint32]$headerRaw) }
        $ptr = $next
    }
    foreach ($item in $items.ToArray()) { $item }
}

function Get-PciCapabilityByIdIndex {
    param(
        [Parameter(Mandatory=$true)][object[]]$Capabilities,
        [Parameter(Mandatory=$true)][int]$CapabilityId,
        [ValidateRange(0,255)][int]$Index = 0
    )
    $seen = 0
    foreach ($cap in @($Capabilities)) {
        if ([int]$cap.Id -ne [int]$CapabilityId) { continue }
        if ($seen -eq $Index) { return $cap }
        $seen++
    }
    throw ('PCI conventional capability 0x{0:X2} index {1} not present; present count is {2}.' -f $CapabilityId,$Index,$seen)
}

function Get-PciConventionalCapabilityEndOffset {
    param([Parameter(Mandatory=$true)]$Capability)
    $offset = [int]$Capability.Offset
    $next = [int]$Capability.NextOffset
    if ($offset -lt 0x40 -or $offset -gt 0xFC -or (($offset -band 0x3) -ne 0)) { throw ('Invalid PCI conventional capability offset 0x{0:X2}.' -f $offset) }
    if ($next -gt $offset -and $next -le 0x100 -and (($next -band 0x3) -eq 0)) { return [int]($next - 1) }
    return 0xFF
}

function Get-PciConventionalCapabilityByteLength {
    param([Parameter(Mandatory=$true)]$Capability)
    $offset = [int]$Capability.Offset
    $end = Get-PciConventionalCapabilityEndOffset -Capability $Capability
    return [int]($end - $offset + 1)
}

function Read-PciConventionalCapabilityRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,63)][int]$StartDwordIndex = 0,
        [ValidateRange(0,63)][int]$MaxDwords = 0
    )
    $offset = [int]$Capability.Offset
    $lengthBytes = Get-PciConventionalCapabilityByteLength -Capability $Capability
    $capacity = [int][Math]::Floor($lengthBytes / 4)
    if ($capacity -lt 1) { return [uint32[]]@() }
    if ($StartDwordIndex -ge $capacity) { throw ('PCI conventional capability 0x{0:X2} at 0x{1:X2} start DWORD {2} exceeds capacity {3}.' -f [int]$Capability.Id,$offset,$StartDwordIndex,$capacity) }
    $count = if ($MaxDwords -gt 0) { [Math]::Min($MaxDwords, $capacity - $StartDwordIndex) } else { $capacity - $StartDwordIndex }
    $items = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt $count; $i++) {
        $readOffset = $offset + (($StartDwordIndex + $i) * 4)
        [void]$items.Add([uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $readOffset -Width 32))
    }
    return [uint32[]]$items.ToArray()
}

function Set-PciConventionalCapabilityRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Values,
        [ValidateRange(0,63)][int]$StartDwordIndex = 1,
        [bool]$AllowHeaderWrite = $false
    )
    $valueArray = [uint32[]](ConvertTo-PciUInt32Array -Value $Values)
    if ($valueArray.Count -eq 0) { return [object[]]@() }
    if ($StartDwordIndex -eq 0 -and -not $AllowHeaderWrite) { throw ('Refusing raw write to PCI conventional capability header at 0x{0:X2}; set AllowPciConventionalCapabilityHeaderWrite only when intentionally replacing the capability header.' -f [int]$Capability.Offset) }
    $offset = [int]$Capability.Offset
    $capacity = [int][Math]::Floor((Get-PciConventionalCapabilityByteLength -Capability $Capability) / 4)
    if (($StartDwordIndex + $valueArray.Count) -gt $capacity) { throw ('PCI conventional capability 0x{0:X2} raw write at 0x{1:X2} overruns capability: start DWORD {2}, count {3}, capacity {4}.' -f [int]$Capability.Id,$offset,$StartDwordIndex,$valueArray.Count,$capacity) }
    $written = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $valueArray.Count; $i++) {
        $dwordIndex = $StartDwordIndex + $i
        $writeOffset = $offset + ($dwordIndex * 4)
        $expected = [uint32]$valueArray[$i]
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 32 -Value $expected
        $actual = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 32)
        if ($actual -ne $expected) { throw ('PCI conventional capability 0x{0:X2} raw DWORD write verify failed at 0x{1:X2}: expected 0x{2:X8}, readback 0x{3:X8}.' -f [int]$Capability.Id,$writeOffset,$expected,$actual) }
        [void]$written.Add([pscustomobject]@{ CapabilityId = [int]$Capability.Id; Offset = $writeOffset; DwordIndex = $dwordIndex; Value = $actual; IsConventional = $true })
    }
    return [object[]]$written.ToArray()
}

function Get-PciIdeReadableByteLength {
    param(
        [Parameter(Mandatory=$true)]$Capability,
        [Parameter(Mandatory=$true)][uint32]$CapabilityDword,
        [ValidateRange(12,4096)][int]$MaximumAutoReadBytes = 256
    )
    $boundedLength = Get-PciExtendedCapabilityByteLength -Capability $Capability
    if ($boundedLength -lt 12) { return [int]$boundedLength }
    return [int]([Math]::Min($boundedLength, $MaximumAutoReadBytes))
}


function Get-PciExtendedCapabilityEndOffset {
    param([Parameter(Mandatory=$true)]$Capability)
    $offset = [int]$Capability.Offset
    $next = [int]$Capability.NextOffset
    if ($offset -lt 0x100 -or $offset -gt 0xFFC -or (($offset -band 0x3) -ne 0)) { throw ('Invalid PCIe extended capability offset 0x{0:X3}.' -f $offset) }
    if ($next -gt $offset -and $next -le 0x1000 -and (($next -band 0x3) -eq 0)) { return [int]($next - 1) }
    return 0xFFF
}

function Get-PciExtendedCapabilityByteLength {
    param([Parameter(Mandatory=$true)]$Capability)
    $offset = [int]$Capability.Offset
    $end = Get-PciExtendedCapabilityEndOffset -Capability $Capability
    return [int]($end - $offset + 1)
}

function ConvertTo-PciPhysicalLayerCapabilityShortName {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0026 { '16GT'; return }
        0x002A { '32GT'; return }
        0x0031 { '64GT'; return }
        default { ('0x{0:X4}' -f [int]$CapabilityId); return }
    }
}

function ConvertTo-PciPhysicalLayerRateName {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0026 { '16.0 GT/s'; return }
        0x002A { '32.0 GT/s'; return }
        0x0031 { '64.0 GT/s'; return }
        default { ('ExtCap 0x{0:X4}' -f [int]$CapabilityId); return }
    }
}

function ConvertFrom-PciPhysicalLayerCapabilitySelector {
    param([AllowNull()][object]$Capability)
    if ($null -eq $Capability) { throw 'PhysicalLayerRawCapability is null; expected 16GT, 32GT, 64GT, 0x0026, 0x002A, or 0x0031.' }
    if ($Capability -is [string]) {
        $s = ([string]$Capability).Trim()
        switch -Regex ($s.ToUpperInvariant()) {
            '^(16|16GT|16\.0|GEN4|PCIE4|0X26|0X0026|38)$' { return 0x0026 }
            '^(32|32GT|32\.0|GEN5|PCIE5|0X2A|0X002A|42)$' { return 0x002A }
            '^(64|64GT|64\.0|GEN6|PCIE6|0X31|0X0031|49)$' { return 0x0031 }
        }
        $parsed = 0
        if ($s.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) {
            if ([int]::TryParse($s.Substring(2), [System.Globalization.NumberStyles]::HexNumber, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$parsed)) {
                if ($parsed -in 0x0026,0x002A,0x0031) { return $parsed }
            }
        }
        if ([int]::TryParse($s, [ref]$parsed)) {
            if ($parsed -in 0x0026,0x002A,0x0031) { return $parsed }
        }
        throw ('Unsupported PhysicalLayerRawCapability selector "{0}"; expected 16GT, 32GT, 64GT, 0x0026, 0x002A, or 0x0031.' -f $s)
    }
    $id = [int]$Capability
    if ($id -in 0x0026,0x002A,0x0031) { return $id }
    throw ('Unsupported PhysicalLayerRawCapability selector 0x{0:X4}; expected 0x0026, 0x002A, or 0x0031.' -f $id)
}

function Get-PciPhysicalLayerCapabilityReadDwordCount {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0026 { return 7 }
        0x002A { return 8 }
        0x0031 { return 4 }
        default { throw ('Unsupported PCIe Physical Layer extended capability 0x{0:X4}.' -f [int]$CapabilityId) }
    }
}

function Get-PciPhysicalLayerCapabilityStatusDwordIndex {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0026 { return 3 }
        0x002A { return 3 }
        0x0031 { return 3 }
        default { throw ('Unsupported PCIe Physical Layer extended capability 0x{0:X4}.' -f [int]$CapabilityId) }
    }
}

function ConvertTo-PciPhysicalLayerModifiedTsModeName {
    param([Parameter(Mandatory=$true)][int]$Mode)
    switch ([int]$Mode) {
        0 { 'PCI Express'; return }
        1 { 'Training Set Messages'; return }
        2 { 'Alternate Protocol Negotiation'; return }
        default { ('Reserved({0})' -f [int]$Mode); return }
    }
}

function ConvertTo-PciPhysicalLayerEnhancedLinkBehaviorName {
    param([Parameter(Mandatory=$true)][int]$Code)
    switch ([int]$Code) {
        0 { 'Full equalization required'; return }
        1 { 'Equalization bypass to highest rate support'; return }
        2 { 'No equalization needed'; return }
        3 { 'Modified TS1/TS2 ordered sets supported'; return }
        default { ('Reserved({0})' -f [int]$Code); return }
    }
}


function ConvertTo-PciPhysicalLayerPresetCodeName {
    param([Parameter(Mandatory=$true)][int]$Code)
    $n = [int]($Code -band 0x0F)
    if ($n -ge 0 -and $n -le 10) { return ('P{0}' -f $n) }
    return ('ReservedPreset({0})' -f $n)
}

function ConvertTo-PciPhysicalLayerReceiverPresetHintName {
    param([Parameter(Mandatory=$true)][int]$Code)
    $n = [int]($Code -band 0x07)
    return ('Hint{0}' -f $n)
}

function ConvertTo-PciPhysicalLayerEqualizationSummary {
    param(
        [bool]$Complete,
        [bool]$Phase1,
        [bool]$Phase2,
        [bool]$Phase3,
        [bool]$Request
    )
    $missing = New-Object System.Collections.Generic.List[string]
    if (-not $Phase1) { [void]$missing.Add('P1') }
    if (-not $Phase2) { [void]$missing.Add('P2') }
    if (-not $Phase3) { [void]$missing.Add('P3') }
    if ($Complete -and -not $Request) { return 'complete' }
    if ($Complete -and $Request) { return 'complete/requested' }
    if ($Request -and $missing.Count -eq 0) { return 'request-pending' }
    if ($missing.Count -gt 0) {
        if ($Request) { return ('request-pending incomplete:{0}' -f ($missing -join ',')) }
        return ('incomplete:{0}' -f ($missing -join ','))
    }
    return 'not-complete'
}

function ConvertTo-PciPhysicalLayerLanePresetByteText {
    param([Parameter(Mandatory=$true)][byte]$Value)
    $dp = [int]([uint32]$Value -band 0x0F)
    $up = [int](([uint32]$Value -shr 4) -band 0x0F)
    return ('DPTx={0}/UPTx={1}/raw0x{2:X2}' -f (ConvertTo-PciPhysicalLayerPresetCodeName -Code $dp),(ConvertTo-PciPhysicalLayerPresetCodeName -Code $up),[byte]$Value)
}

function ConvertTo-PciPhysicalLayerLaneEqualizationPresetByteArray {
    param([AllowNull()][object]$Value)
    $items = New-Object System.Collections.Generic.List[byte]
    if ($null -eq $Value) { return [byte[]]$items.ToArray() }
    foreach ($rawItem in @($Value)) {
        if ($null -eq $rawItem) { continue }
        $tokens = @($rawItem)
        if ($rawItem -is [string]) { $tokens = @(([string]$rawItem) -split '[,;\s]+') }
        foreach ($rawToken in $tokens) {
            if ($null -eq $rawToken) { continue }
            $token = ([string]$rawToken).Trim()
            if ([string]::IsNullOrWhiteSpace($token)) { continue }
            $normalized = ($token.ToUpperInvariant() -replace '\s+', '')
            $pairMatch = [regex]::Match($normalized, '^(?:D|DP|DPTX|DOWN|DOWNSTREAM|TXD)?[:=]?([0-9]{1,2})(?:/|\|)(?:U|UP|UPTX|UPSTREAM|TXU)?[:=]?([0-9]{1,2})$')
            if (-not $pairMatch.Success) { $pairMatch = [regex]::Match($normalized, '^(?:D|DP|DPTX)([0-9]{1,2})(?:U|UP|UPTX)([0-9]{1,2})$') }
            if ($pairMatch.Success) {
                $dp = [int]$pairMatch.Groups[1].Value
                $up = [int]$pairMatch.Groups[2].Value
                if ($dp -lt 0 -or $dp -gt 15 -or $up -lt 0 -or $up -gt 15) { throw ('PCIe Physical Layer lane preset pair "{0}" must encode DPTx and UPTx nibbles in 0..15.' -f $token) }
                [void]$items.Add([byte]((($up -band 0x0F) -shl 4) -bor ($dp -band 0x0F)))
                continue
            }
            $valueText = $normalized
            $parsed = 0
            if ($valueText.StartsWith('0X')) { $parsed = [Convert]::ToInt32($valueText.Substring(2),16) }
            else { $parsed = [Convert]::ToInt32($valueText,10) }
            if ($parsed -lt 0 -or $parsed -gt 255) { throw ('PCIe Physical Layer lane preset byte "{0}" is outside 0..255.' -f $token) }
            [void]$items.Add([byte]$parsed)
        }
    }
    return [byte[]]$items.ToArray()
}

function Assert-PciPhysicalLayerRawWriteBounds {
    param(
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Values,
        [ValidateRange(0,255)][int]$StartDwordIndex,
        [bool]$AllowHeaderWrite,
        [Parameter(Mandatory=$true)][string]$Bdf
    )
    $valueArray = [uint32[]](ConvertTo-PciUInt32Array -Value $Values)
    if ($valueArray.Count -eq 0) { return }
    if ($StartDwordIndex -eq 0 -and -not $AllowHeaderWrite) { throw ('Refusing PCIe Physical Layer raw write to ExtCap header on {0}: capability 0x{1:X4} at 0x{2:X3}. Set AllowPciExtendedCapabilityHeaderWrite only when intentionally replacing the header.' -f $Bdf,[int]$Capability.Id,[int]$Capability.Offset) }
    $coreDwords = Get-PciPhysicalLayerCapabilityReadDwordCount -CapabilityId ([int]$Capability.Id)
    $boundedDwords = [int][Math]::Floor((Get-PciExtendedCapabilityByteLength -Capability $Capability) / 4)
    $maxDwords = [Math]::Min($boundedDwords, 16)
    if (($StartDwordIndex + $valueArray.Count) -gt $maxDwords) { throw ('PCIe Physical Layer raw write on {0} overruns bounded {1} register block including Lane Equalization Control: start DWORD {2}, count {3}, max DWORD count {4}, capability offset 0x{5:X3}, bounded DWORD count {6}, core DWORD count {7}.' -f $Bdf,(ConvertTo-PciPhysicalLayerRateName -CapabilityId ([int]$Capability.Id)),$StartDwordIndex,$valueArray.Count,$maxDwords,[int]$Capability.Offset,$boundedDwords,$coreDwords) }
}

function Get-PciPhysicalLayerStatusFields {
    param(
        [Parameter(Mandatory=$true)][uint32]$Status,
        [Parameter(Mandatory=$true)][int]$CapabilityId
    )
    $equComplete = (($Status -band [uint32]0x00000001) -ne 0)
    $phase1 = (($Status -band [uint32]0x00000002) -ne 0)
    $phase2 = (($Status -band [uint32]0x00000004) -ne 0)
    $phase3 = (($Status -band [uint32]0x00000008) -ne 0)
    $equRequest = (($Status -band [uint32]0x00000010) -ne 0)
    $incomplete = 0
    if (-not $phase1) { $incomplete++ }
    if (-not $phase2) { $incomplete++ }
    if (-not $phase3) { $incomplete++ }
    if ($equComplete) { $incomplete = 0 }
    $enhancedCode = -1
    $enhancedName = 'n/a'
    $modifiedTsReceived = $false
    $txPrecodeOn = $false
    $txPrecodeRequest = $false
    $noEqualizationNeededReceived = $false
    $equalizationStatusText = ConvertTo-PciPhysicalLayerEqualizationSummary -Complete $equComplete -Phase1 $phase1 -Phase2 $phase2 -Phase3 $phase3 -Request $equRequest
    if ([int]$CapabilityId -eq 0x002A) {
        $enhancedCode = [int](($Status -shr 6) -band [uint32]0x00000003)
        $enhancedName = ConvertTo-PciPhysicalLayerEnhancedLinkBehaviorName -Code $enhancedCode
        $modifiedTsReceived = (($Status -band [uint32]0x00000100) -ne 0)
        $txPrecodeOn = (($Status -band [uint32]0x00000200) -ne 0)
        $txPrecodeRequest = (($Status -band [uint32]0x00000400) -ne 0)
        $noEqualizationNeededReceived = (($Status -band [uint32]0x00000800) -ne 0)
    } elseif ([int]$CapabilityId -eq 0x0031) {
        $txPrecodeOn = (($Status -band [uint32]0x00000020) -ne 0)
        $txPrecodeRequest = (($Status -band [uint32]0x00000040) -ne 0)
        $noEqualizationNeededReceived = (($Status -band [uint32]0x00000080) -ne 0)
    }
    [pscustomobject]@{
        Raw = [uint32]$Status
        EqualizationComplete = [bool]$equComplete
        EqualizationPhase1Successful = [bool]$phase1
        EqualizationPhase2Successful = [bool]$phase2
        EqualizationPhase3Successful = [bool]$phase3
        LinkEqualizationRequest = [bool]$equRequest
        EqualizationIncompletePhaseCount = [int]$incomplete
        EqualizationFailureStatus = [bool]((-not $equComplete) -or $equRequest -or ($incomplete -gt 0))
        EqualizationStatusText = [string]$equalizationStatusText
        ReceivedEnhancedLinkBehaviorControlCode = [int]$enhancedCode
        ReceivedEnhancedLinkBehaviorControlName = [string]$enhancedName
        ModifiedTsReceived = [bool]$modifiedTsReceived
        TransmitterPrecodingOn = [bool]$txPrecodeOn
        TransmitterPrecodingRequest = [bool]$txPrecodeRequest
        NoEqualizationNeededReceived = [bool]$noEqualizationNeededReceived
    }
}

function ConvertTo-PciLaneMaskList {
    param(
        [Parameter(Mandatory=$true)][uint32]$Mask,
        [ValidateRange(0,64)][int]$MaxLanes = 32
    )
    $lanes = New-Object System.Collections.Generic.List[int]
    $limit = [Math]::Min(32, [Math]::Max(0, $MaxLanes))
    for ($lane = 0; $lane -lt $limit; $lane++) {
        $bit = [uint32]([uint64]1 -shl $lane)
        if (($Mask -band $bit) -ne 0) { [void]$lanes.Add([int]$lane) }
    }
    return [int[]]$lanes.ToArray()
}

function Get-PciPhysicalLayerLaneEqualizationControlState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,64)][int]$PreferredLaneCount = 0
    )
    $capabilityId = [int]$Capability.Id
    $offset = [int]$Capability.Offset
    $laneControlOffset = 0x20
    $byteLength = Get-PciExtendedCapabilityByteLength -Capability $Capability
    if ($byteLength -le $laneControlOffset) {
        return [pscustomobject]@{
            Present = $false
            CapabilityId = [int]$capabilityId
            Offset = [int]($offset + $laneControlOffset)
            RegisterOffsetWithinCapability = [int]$laneControlOffset
            LaneRegisterSizeBytes = [int]1
            AvailableLaneBytes = [int]0
            DecodedLaneCount = [int]0
            RawBytes = [byte[]]@()
            RawDwords = [uint32[]]@()
            LaneEqualizationPresets = [object[]]@()
            DisplayText = 'LECtrl=n/a'
        }
    }
    $available = [Math]::Min(32, [Math]::Max(0, $byteLength - $laneControlOffset))
    $decodeCount = if ($PreferredLaneCount -gt 0) { [Math]::Min($available, $PreferredLaneCount) } else { $available }
    $rawBytes = New-Object System.Collections.Generic.List[byte]
    $laneEntries = New-Object System.Collections.Generic.List[object]
    for ($lane = 0; $lane -lt $decodeCount; $lane++) {
        $readOffset = $offset + $laneControlOffset + $lane
        $raw = [byte](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $readOffset -Width 8)
        [void]$rawBytes.Add($raw)
        $downstreamPreset = [int]([uint32]$raw -band 0x0F)
        $upstreamPreset = [int](([uint32]$raw -shr 4) -band 0x0F)
        [void]$laneEntries.Add([pscustomobject]@{
            Lane = [int]$lane
            Offset = [int]$readOffset
            Raw = [byte]$raw
            DownstreamPortTransmitterPreset = [int]$downstreamPreset
            DownstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code $downstreamPreset)
            UpstreamPortTransmitterPreset = [int]$upstreamPreset
            UpstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code $upstreamPreset)
            LowPresetNibble = [int]$downstreamPreset
            HighPresetNibble = [int]$upstreamPreset
            PresetByteText = [string](ConvertTo-PciPhysicalLayerLanePresetByteText -Value $raw)
        })
    }
    $rawDwords = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt $rawBytes.Count; $i += 4) {
        $dw = [uint32]0
        for ($j = 0; $j -lt 4 -and ($i + $j) -lt $rawBytes.Count; $j++) { $dw = [uint32]($dw -bor ([uint32]$rawBytes[$i + $j] -shl (8 * $j))) }
        [void]$rawDwords.Add($dw)
    }
    $items = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @($laneEntries.ToArray())) { [void]$items.Add(('L{0}:{1}' -f [int]$entry.Lane,[string]$entry.PresetByteText)) }
    $text = if ($items.Count -gt 0) { [string]::Join(' ', $items.ToArray()) } else { 'none decoded' }
    [pscustomobject]@{
        Present = $true
        CapabilityId = [int]$capabilityId
        Offset = [int]($offset + $laneControlOffset)
        RegisterOffsetWithinCapability = [int]$laneControlOffset
        LaneRegisterSizeBytes = [int]1
        AvailableLaneBytes = [int]$available
        DecodedLaneCount = [int]$laneEntries.Count
        RawBytes = [byte[]]$rawBytes.ToArray()
        RawDwords = [uint32[]]$rawDwords.ToArray()
        LaneEqualizationPresets = [object[]]$laneEntries.ToArray()
        DecodedPresetText = [string]$text
        DisplayText = ('LECtrl@+0x20 bytes={0}/{1} {2}' -f [int]$laneEntries.Count,[int]$available,$text)
    }
}

function Get-PciPhysicalLayerState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,255)][int]$Index = 0
    )
    $capabilityId = [int]$Capability.Id
    $offset = [int]$Capability.Offset
    $dwordCount = Get-PciPhysicalLayerCapabilityReadDwordCount -CapabilityId $capabilityId
    $boundedCount = [int][Math]::Floor((Get-PciExtendedCapabilityByteLength -Capability $Capability) / 4)
    if ($boundedCount -lt $dwordCount) { throw ('PCIe Physical Layer {0} at 0x{1:X3} is truncated: discovered {2} DWORDs, required {3} DWORDs.' -f (ConvertTo-PciPhysicalLayerRateName -CapabilityId $capabilityId),$offset,$boundedCount,$dwordCount) }
    $raw = New-Object System.Collections.Generic.List[uint32]
    foreach ($value in @(Read-PciExtendedCapabilityRawDwords -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability -StartDwordIndex 0 -MaxDwords $dwordCount)) { [void]$raw.Add([uint32]$value) }
    $capabilityRaw = if ($raw.Count -gt 1) { [uint32]$raw[1] } else { [uint32]0 }
    $controlRaw = if ($raw.Count -gt 2) { [uint32]$raw[2] } else { [uint32]0 }
    $statusIndex = Get-PciPhysicalLayerCapabilityStatusDwordIndex -CapabilityId $capabilityId
    $statusRaw = if ($raw.Count -gt $statusIndex) { [uint32]$raw[$statusIndex] } else { [uint32]0 }
    $statusFields = Get-PciPhysicalLayerStatusFields -Status $statusRaw -CapabilityId $capabilityId
    $localParityRaw = if ($capabilityId -eq 0x0026 -and $raw.Count -gt 4) { [uint32]$raw[4] } else { [uint32]0 }
    $firstRetimerParityRaw = if ($capabilityId -eq 0x0026 -and $raw.Count -gt 5) { [uint32]$raw[5] } else { [uint32]0 }
    $secondRetimerParityRaw = if ($capabilityId -eq 0x0026 -and $raw.Count -gt 6) { [uint32]$raw[6] } else { [uint32]0 }
    $localParityLanes = [int[]](ConvertTo-PciLaneMaskList -Mask $localParityRaw -MaxLanes 32)
    $firstRetimerParityLanes = [int[]](ConvertTo-PciLaneMaskList -Mask $firstRetimerParityRaw -MaxLanes 32)
    $secondRetimerParityLanes = [int[]](ConvertTo-PciLaneMaskList -Mask $secondRetimerParityRaw -MaxLanes 32)
    $localParityLaneCount = [int]$localParityLanes.Count
    $firstRetimerParityLaneCount = [int]$firstRetimerParityLanes.Count
    $secondRetimerParityLaneCount = [int]$secondRetimerParityLanes.Count
    $receivedModifiedTsData1Raw = if ($capabilityId -eq 0x002A -and $raw.Count -gt 4) { [uint32]$raw[4] } else { [uint32]0 }
    $receivedModifiedTsData2Raw = if ($capabilityId -eq 0x002A -and $raw.Count -gt 5) { [uint32]$raw[5] } else { [uint32]0 }
    $transmitModifiedTsData1Raw = if ($capabilityId -eq 0x002A -and $raw.Count -gt 6) { [uint32]$raw[6] } else { [uint32]0 }
    $transmitModifiedTsData2Raw = if ($capabilityId -eq 0x002A -and $raw.Count -gt 7) { [uint32]$raw[7] } else { [uint32]0 }
    $laneEqControl = Get-PciPhysicalLayerLaneEqualizationControlState -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability
    $capEqBypass = $false
    $capNoEqualizationNeeded = $false
    $capModifiedTsMode0 = $false
    $capModifiedTsMode1 = $false
    $capModifiedTsMode2 = $false
    $ctlEqBypassDisable = $false
    $ctlNoEqualizationNeededDisable = $false
    $ctlModifiedTsMode = -1
    $ctlModifiedTsModeName = 'n/a'
    if ($capabilityId -eq 0x002A) {
        $capEqBypass = (($capabilityRaw -band [uint32]0x00000001) -ne 0)
        $capNoEqualizationNeeded = (($capabilityRaw -band [uint32]0x00000002) -ne 0)
        $capModifiedTsMode0 = (($capabilityRaw -band [uint32]0x00000004) -ne 0)
        $capModifiedTsMode1 = (($capabilityRaw -band [uint32]0x00000008) -ne 0)
        $capModifiedTsMode2 = (($capabilityRaw -band [uint32]0x00000010) -ne 0)
        $ctlEqBypassDisable = (($controlRaw -band [uint32]0x00000001) -ne 0)
        $ctlNoEqualizationNeededDisable = (($controlRaw -band [uint32]0x00000002) -ne 0)
        $ctlModifiedTsMode = [int](($controlRaw -shr 8) -band [uint32]0x00000007)
        $ctlModifiedTsModeName = ConvertTo-PciPhysicalLayerModifiedTsModeName -Mode $ctlModifiedTsMode
    }
    $rateName = ConvertTo-PciPhysicalLayerRateName -CapabilityId $capabilityId
    $shortName = ConvertTo-PciPhysicalLayerCapabilityShortName -CapabilityId $capabilityId
    $extraText = ''
    if ($capabilityId -eq 0x0026) {
        $extraText = (' parity local=0x{0:X8}/L[{1}]/cnt={2} r1=0x{3:X8}/L[{4}]/cnt={5} r2=0x{6:X8}/L[{7}]/cnt={8}' -f $localParityRaw,(ConvertTo-PciLaneListText -LaneNumbers $localParityLanes),$localParityLaneCount,$firstRetimerParityRaw,(ConvertTo-PciLaneListText -LaneNumbers $firstRetimerParityLanes),$firstRetimerParityLaneCount,$secondRetimerParityRaw,(ConvertTo-PciLaneListText -LaneNumbers $secondRetimerParityLanes),$secondRetimerParityLaneCount)
    } elseif ($capabilityId -eq 0x002A) {
        $extraText = (' capEqBypass={0} capNoEqNeeded={1} modTsCaps={2}/{3}/{4} ctlEqBypassDis={5} ctlNoEqDis={6} ctlModTs={7} rcvEnh="{8}" modTsRecv={9} txPre={10}/{11} noEqRecv={12} tsRx=0x{13:X8}/0x{14:X8} tsTx=0x{15:X8}/0x{16:X8}' -f $capEqBypass,$capNoEqualizationNeeded,$capModifiedTsMode0,$capModifiedTsMode1,$capModifiedTsMode2,$ctlEqBypassDisable,$ctlNoEqualizationNeededDisable,$ctlModifiedTsModeName,[string]$statusFields.ReceivedEnhancedLinkBehaviorControlName,[bool]$statusFields.ModifiedTsReceived,[bool]$statusFields.TransmitterPrecodingOn,[bool]$statusFields.TransmitterPrecodingRequest,[bool]$statusFields.NoEqualizationNeededReceived,$receivedModifiedTsData1Raw,$receivedModifiedTsData2Raw,$transmitModifiedTsData1Raw,$transmitModifiedTsData2Raw)
    } elseif ($capabilityId -eq 0x0031) {
        $extraText = (' txPre={0}/{1} noEqRecv={2}' -f [bool]$statusFields.TransmitterPrecodingOn,[bool]$statusFields.TransmitterPrecodingRequest,[bool]$statusFields.NoEqualizationNeededReceived)
    }
    if ($laneEqControl.Present) { $extraText = ('{0} {1}' -f $extraText,[string]$laneEqControl.DisplayText) }
    [pscustomobject]@{
        Index = [int]$Index
        CapabilityId = [int]$capabilityId
        CapabilityName = [string]$shortName
        RateName = [string]$rateName
        Offset = [int]$offset
        Version = [int]$Capability.Version
        HeaderRaw = [uint32]$Capability.HeaderRaw
        CapabilityRaw = [uint32]$capabilityRaw
        ControlRaw = [uint32]$controlRaw
        StatusRaw = [uint32]$statusRaw
        RawDwords = [uint32[]]$raw.ToArray()
        RawReadDwordCount = [int]$raw.Count
        RawReadLengthBytes = [int]($raw.Count * 4)
        EqualizationComplete = [bool]$statusFields.EqualizationComplete
        EqualizationPhase1Successful = [bool]$statusFields.EqualizationPhase1Successful
        EqualizationPhase2Successful = [bool]$statusFields.EqualizationPhase2Successful
        EqualizationPhase3Successful = [bool]$statusFields.EqualizationPhase3Successful
        LinkEqualizationRequest = [bool]$statusFields.LinkEqualizationRequest
        EqualizationIncompletePhaseCount = [int]$statusFields.EqualizationIncompletePhaseCount
        EqualizationFailureStatus = [bool]$statusFields.EqualizationFailureStatus
        EqualizationStatusText = [string]$statusFields.EqualizationStatusText
        EqualizationBypassCapable = [bool]$capEqBypass
        NoEqualizationNeededCapable = [bool]$capNoEqualizationNeeded
        ModifiedTsMode0Capable = [bool]$capModifiedTsMode0
        ModifiedTsMode1Capable = [bool]$capModifiedTsMode1
        ModifiedTsMode2Capable = [bool]$capModifiedTsMode2
        EqualizationBypassDisabled = [bool]$ctlEqBypassDisable
        NoEqualizationNeededDisabled = [bool]$ctlNoEqualizationNeededDisable
        ModifiedTsUsageModeCode = [int]$ctlModifiedTsMode
        ModifiedTsUsageModeName = [string]$ctlModifiedTsModeName
        ReceivedEnhancedLinkBehaviorControlCode = [int]$statusFields.ReceivedEnhancedLinkBehaviorControlCode
        ReceivedEnhancedLinkBehaviorControlName = [string]$statusFields.ReceivedEnhancedLinkBehaviorControlName
        ModifiedTsReceived = [bool]$statusFields.ModifiedTsReceived
        TransmitterPrecodingOn = [bool]$statusFields.TransmitterPrecodingOn
        TransmitterPrecodingRequest = [bool]$statusFields.TransmitterPrecodingRequest
        NoEqualizationNeededReceived = [bool]$statusFields.NoEqualizationNeededReceived
        LocalDataParityMismatchStatusRaw = [uint32]$localParityRaw
        FirstRetimerDataParityMismatchStatusRaw = [uint32]$firstRetimerParityRaw
        SecondRetimerDataParityMismatchStatusRaw = [uint32]$secondRetimerParityRaw
        LocalDataParityMismatchLanes = [int[]]$localParityLanes
        FirstRetimerDataParityMismatchLanes = [int[]]$firstRetimerParityLanes
        SecondRetimerDataParityMismatchLanes = [int[]]$secondRetimerParityLanes
        LocalDataParityMismatchLaneCount = [int]$localParityLaneCount
        FirstRetimerDataParityMismatchLaneCount = [int]$firstRetimerParityLaneCount
        SecondRetimerDataParityMismatchLaneCount = [int]$secondRetimerParityLaneCount
        AnyLocalDataParityMismatch = [bool]($localParityRaw -ne 0)
        RetimerParityMismatchIndicator = [bool](($firstRetimerParityRaw -ne 0) -or ($secondRetimerParityRaw -ne 0))
        AnyPhysicalLayerLaneStatusError = [bool](([bool]$statusFields.EqualizationFailureStatus) -or ($localParityRaw -ne 0) -or ($firstRetimerParityRaw -ne 0) -or ($secondRetimerParityRaw -ne 0))
        ReceivedModifiedTsData1Raw = [uint32]$receivedModifiedTsData1Raw
        ReceivedModifiedTsData2Raw = [uint32]$receivedModifiedTsData2Raw
        TransmitModifiedTsData1Raw = [uint32]$transmitModifiedTsData1Raw
        TransmitModifiedTsData2Raw = [uint32]$transmitModifiedTsData2Raw
        LaneEqualizationControlPresent = [bool]$laneEqControl.Present
        LaneEqualizationControlOffset = [int]$laneEqControl.Offset
        LaneEqualizationControlAvailableLaneBytes = [int]$laneEqControl.AvailableLaneBytes
        LaneEqualizationControlDecodedLaneCount = [int]$laneEqControl.DecodedLaneCount
        LaneEqualizationControlRawBytes = [byte[]]$laneEqControl.RawBytes
        LaneEqualizationControlRawDwords = [uint32[]]$laneEqControl.RawDwords
        LaneEqualizationPresetBytes = [byte[]]$laneEqControl.RawBytes
        LaneEqualizationPresets = [object[]]$laneEqControl.LaneEqualizationPresets
        LaneEqualizationPresetText = [string]$laneEqControl.DisplayText
        DisplayText = ('PHY{0}@0x{1:X3} EQ {13} comp={2} p1={3} p2={4} p3={5} req={6} incomplete={7} stat=0x{8:X8} cap=0x{9:X8} ctl=0x{10:X8}{11} raw=[{12}]' -f $shortName,$offset,[bool]$statusFields.EqualizationComplete,[bool]$statusFields.EqualizationPhase1Successful,[bool]$statusFields.EqualizationPhase2Successful,[bool]$statusFields.EqualizationPhase3Successful,[bool]$statusFields.LinkEqualizationRequest,[int]$statusFields.EqualizationIncompletePhaseCount,[uint32]$statusRaw,[uint32]$capabilityRaw,[uint32]$controlRaw,$extraText,(Format-PciDwordArrayText -Values $raw.ToArray()),[string]$statusFields.EqualizationStatusText)
    }
}

function ConvertTo-PciFlitExtendedCapabilityName {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0032 { 'FLIT_LOG'; return }
        0x0033 { 'FLIT_PM'; return }
        0x0034 { 'FLIT_EI'; return }
        0x0037 { 'NOP_FLIT'; return }
        default { ('0x{0:X4}' -f [int]$CapabilityId); return }
    }
}

function ConvertTo-PciLaneListText {
    param([AllowNull()][object]$LaneNumbers)
    $items = New-Object System.Collections.Generic.List[string]
    foreach ($lane in @($LaneNumbers)) { [void]$items.Add([string][int]$lane) }
    if ($items.Count -eq 0) { return 'none' }
    return [string]::Join(',', $items.ToArray())
}

function Get-PciSecondaryExpressState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,64)][int]$PreferredLaneCount = 0
    )
    $offset = [int]$Capability.Offset
    $byteLength = Get-PciExtendedCapabilityByteLength -Capability $Capability
    if ($byteLength -lt 12) { throw ('Secondary PCI Express capability at 0x{0:X3} is truncated: {1} bytes.' -f $offset,$byteLength) }
    $linkControl3 = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x04) -Width 16)
    $laneErrorStatus = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x08) -Width 32)
    $failedLanes = New-Object System.Collections.Generic.List[int]
    for ($lane = 0; $lane -lt 32; $lane++) { if (($laneErrorStatus -band ([uint32]([uint64]1 -shl $lane))) -ne 0) { [void]$failedLanes.Add([int]$lane) } }
    $availableLaneEntries = 0
    if ($byteLength -gt 12) { $availableLaneEntries = [int][Math]::Floor(($byteLength - 12) / 2) }
    $requestedLaneEntries = if ($PreferredLaneCount -gt 0) { [int]$PreferredLaneCount } elseif ($availableLaneEntries -gt 0) { [int]$availableLaneEntries } else { 0 }
    if ($requestedLaneEntries -gt 32) { $requestedLaneEntries = 32 }
    if ($availableLaneEntries -gt 0 -and $requestedLaneEntries -gt $availableLaneEntries) { $requestedLaneEntries = $availableLaneEntries }
    $laneControls = New-Object System.Collections.Generic.List[object]
    for ($lane = 0; $lane -lt $requestedLaneEntries; $lane++) {
        $raw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x0C + ($lane * 2)) -Width 16)
        $dpTx = [int]($raw -band 0x000F)
        $dpRxHint = [int](($raw -shr 4) -band 0x0007)
        $upTx = [int](($raw -shr 8) -band 0x000F)
        $upRxHint = [int](($raw -shr 12) -band 0x0007)
        [void]$laneControls.Add([pscustomobject]@{
            Lane = [int]$lane
            Raw = [uint16]$raw
            DownstreamPortTransmitterPreset = [int]$dpTx
            DownstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code $dpTx)
            DownstreamPortReceiverPresetHint = [int]$dpRxHint
            DownstreamPortReceiverPresetHintName = [string](ConvertTo-PciPhysicalLayerReceiverPresetHintName -Code $dpRxHint)
            UpstreamPortTransmitterPreset = [int]$upTx
            UpstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code $upTx)
            UpstreamPortReceiverPresetHint = [int]$upRxHint
            UpstreamPortReceiverPresetHintName = [string](ConvertTo-PciPhysicalLayerReceiverPresetHintName -Code $upRxHint)
            LaneError = [bool](($lane -lt 32) -and (($laneErrorStatus -band ([uint32]([uint64]1 -shl $lane))) -ne 0))
        })
    }
    $laneTextItems = New-Object System.Collections.Generic.List[string]
    foreach ($entry in @($laneControls.ToArray())) { [void]$laneTextItems.Add(('L{0}:DPTx={1}/DPRx={2}/UPTx={3}/UPRx={4}/Err{5}' -f [int]$entry.Lane,[string]$entry.DownstreamPortTransmitterPresetName,[string]$entry.DownstreamPortReceiverPresetHintName,[string]$entry.UpstreamPortTransmitterPresetName,[string]$entry.UpstreamPortReceiverPresetHintName,[bool]$entry.LaneError)) }
    $laneText = if ($laneTextItems.Count -gt 0) { [string]::Join(' ', $laneTextItems.ToArray()) } else { 'no lane equalization control entries decoded' }
    $laneFailureSummary = if ($failedLanes.Count -gt 0) { ('failed:{0}' -f (ConvertTo-PciLaneListText -LaneNumbers $failedLanes.ToArray())) } else { 'none' }
    [pscustomobject]@{
        Present = $true
        Offset = [int]$offset
        Version = [int]$Capability.Version
        HeaderRaw = [uint32]$Capability.HeaderRaw
        LinkControl3Raw = [uint16]$linkControl3
        LinkEqualizationRequestInterruptEnable = [bool](($linkControl3 -band 0x0002) -ne 0)
        PerformLinkEqualization = [bool](($linkControl3 -band 0x0001) -ne 0)
        LowerSkpOrderedSetGenerationVector = [int](($linkControl3 -shr 8) -band 0x007F)
        LaneErrorStatusRaw = [uint32]$laneErrorStatus
        LaneEqualizationFailureStatus = [bool]($failedLanes.Count -gt 0)
        LaneEqualizationFailureCount = [int]$failedLanes.Count
        LaneEqualizationFailedLanes = [int[]]$failedLanes.ToArray()
        LaneEqualizationFailedLanesText = [string](ConvertTo-PciLaneListText -LaneNumbers $failedLanes.ToArray())
        LaneEqualizationFailureSummary = [string]$laneFailureSummary
        LaneEqualizationControls = [object[]]$laneControls.ToArray()
        LaneEqualizationControlCount = [int]$laneControls.Count
        DisplayText = ('SecPCI@0x{0:X3} LnkCtl3 IRQ={1} perform={2} lowerSKP=0x{3:X2}; LaneErr=0x{4:X8} failedCnt={5} failed={6}; presets {7}' -f $offset,(($linkControl3 -band 0x0002) -ne 0),(($linkControl3 -band 0x0001) -ne 0),[int](($linkControl3 -shr 8) -band 0x007F),[uint32]$laneErrorStatus,[int]$failedLanes.Count,(ConvertTo-PciLaneListText -LaneNumbers $failedLanes.ToArray()),$laneText)
    }
}


function Read-PciExtendedCapabilityRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,255)][int]$StartDwordIndex = 0,
        [ValidateRange(0,255)][int]$MaxDwords = 0
    )
    $offset = [int]$Capability.Offset
    $lengthBytes = Get-PciExtendedCapabilityByteLength -Capability $Capability
    $capacity = [int][Math]::Floor($lengthBytes / 4)
    if ($capacity -lt 1) { return [uint32[]]@() }
    if ($StartDwordIndex -ge $capacity) { throw ('PCIe extended capability 0x{0:X4} at 0x{1:X3} start DWORD {2} exceeds capacity {3}.' -f [int]$Capability.Id,$offset,$StartDwordIndex,$capacity) }
    $count = if ($MaxDwords -gt 0) { [Math]::Min($MaxDwords, $capacity - $StartDwordIndex) } else { $capacity - $StartDwordIndex }
    $items = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt $count; $i++) {
        $readOffset = $offset + (($StartDwordIndex + $i) * 4)
        [void]$items.Add([uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $readOffset -Width 32))
    }
    return [uint32[]]$items.ToArray()
}

function Get-PciExtendedCapabilityByIdIndex {
    param(
        [Parameter(Mandatory=$true)][object[]]$Capabilities,
        [Parameter(Mandatory=$true)][int]$CapabilityId,
        [ValidateRange(0,255)][int]$Index = 0
    )
    $seen = 0
    foreach ($cap in @($Capabilities)) {
        if ([int]$cap.Id -ne [int]$CapabilityId) { continue }
        if ($seen -eq $Index) { return $cap }
        $seen++
    }
    throw ('PCIe extended capability 0x{0:X4} index {1} not present; present count is {2}.' -f $CapabilityId,$Index,$seen)
}

function Get-PciVendorExtendedCapabilityLengthBytes {
    param(
        [Parameter(Mandatory=$true)]$Capability,
        [Parameter(Mandatory=$true)][uint32]$HeaderDword,
        [ValidateRange(4,4096)][int]$MinimumLength = 8
    )
    $boundedLength = Get-PciExtendedCapabilityByteLength -Capability $Capability
    $declaredLength = [int](($HeaderDword -shr 20) -band [uint32]0x00000FFF)
    if ($declaredLength -ge $MinimumLength -and $declaredLength -le $boundedLength) { return $declaredLength }
    return [int]$boundedLength
}

function Set-PciPhysicalLayerLaneEqualizationPresetBytes {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Values,
        [ValidateRange(0,31)][int]$StartLane = 0
    )
    $valueArray = [byte[]](ConvertTo-PciPhysicalLayerLaneEqualizationPresetByteArray -Value $Values)
    if ($valueArray.Count -eq 0) { return [object[]]@() }
    $capabilityId = [int]$Capability.Id
    if ($capabilityId -notin 0x0026,0x002A,0x0031) { throw ('Capability 0x{0:X4} is not a PCIe Physical Layer 16/32/64 GT/s extended capability.' -f $capabilityId) }
    if (($StartLane + $valueArray.Count) -gt 32) { throw ('PCIe Physical Layer {0} Lane Equalization Control write exceeds 32-lane architectural bound: start lane {1}, byte count {2}.' -f (ConvertTo-PciPhysicalLayerRateName -CapabilityId $capabilityId),$StartLane,$valueArray.Count) }
    $laneControlOffset = 0x20
    $byteLength = Get-PciExtendedCapabilityByteLength -Capability $Capability
    if (($laneControlOffset + $StartLane + $valueArray.Count) -gt $byteLength) { throw ('PCIe Physical Layer {0} Lane Equalization Control write overruns discovered capability bounds: offset +0x{1:X2}, start lane {2}, byte count {3}, capability length {4} bytes.' -f (ConvertTo-PciPhysicalLayerRateName -CapabilityId $capabilityId),$laneControlOffset,$StartLane,$valueArray.Count,$byteLength) }
    $baseOffset = [int]$Capability.Offset + $laneControlOffset + $StartLane
    $written = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $valueArray.Count; $i++) {
        $writeOffset = $baseOffset + $i
        $lane = $StartLane + $i
        $expected = [byte]$valueArray[$i]
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 8 -Value $expected
        $actual = [byte](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 8)
        if ($actual -ne $expected) { throw ('PCIe Physical Layer {0} Lane Equalization byte write verify failed at offset 0x{1:X3} lane {2}: expected 0x{3:X2}, readback 0x{4:X2}.' -f (ConvertTo-PciPhysicalLayerRateName -CapabilityId $capabilityId),$writeOffset,$lane,$expected,$actual) }
        [void]$written.Add([pscustomobject]@{
            CapabilityId = [int]$capabilityId
            CapabilityName = [string](ConvertTo-PciPhysicalLayerCapabilityShortName -CapabilityId $capabilityId)
            Offset = [int]$writeOffset
            RegisterOffsetWithinCapability = [int]($laneControlOffset + $lane)
            Lane = [int]$lane
            Value = [byte]$actual
            DownstreamPortTransmitterPreset = [int]([uint32]$actual -band 0x0F)
            DownstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code ([int]([uint32]$actual -band 0x0F)))
            UpstreamPortTransmitterPreset = [int](([uint32]$actual -shr 4) -band 0x0F)
            UpstreamPortTransmitterPresetName = [string](ConvertTo-PciPhysicalLayerPresetCodeName -Code ([int](([uint32]$actual -shr 4) -band 0x0F)))
            PresetByteText = [string](ConvertTo-PciPhysicalLayerLanePresetByteText -Value $actual)
        })
    }
    return [object[]]$written.ToArray()
}

function Set-PciExtendedCapabilityRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Values,
        [ValidateRange(0,255)][int]$StartDwordIndex = 1,
        [bool]$AllowHeaderWrite = $false,
        [ValidateRange(1,255)][int]$ProtectedDwordCount = 1,
        [AllowEmptyString()][string]$ProtectedRegionName = 'PCIe extended capability header'
    )
    $valueArray = [uint32[]](ConvertTo-PciUInt32Array -Value $Values)
    if ($valueArray.Count -eq 0) { return [object[]]@() }
    if ($StartDwordIndex -eq 0 -and -not $AllowHeaderWrite) { throw ('Refusing raw write to PCIe extended capability header at 0x{0:X3}; set AllowPciExtendedCapabilityHeaderWrite only when intentionally replacing the ExtCap header.' -f [int]$Capability.Offset) }
    if ($StartDwordIndex -lt $ProtectedDwordCount -and -not $AllowHeaderWrite) { throw ('Refusing raw write into protected {0} for PCIe extended capability 0x{1:X4} at 0x{2:X3}; start DWORD {3}, protected DWORDs 0..{4}. Use the typed/masked knobs or explicitly allow header writes only when you know the target device layout.' -f $ProtectedRegionName,[int]$Capability.Id,[int]$Capability.Offset,$StartDwordIndex,($ProtectedDwordCount - 1)) }
    $offset = [int]$Capability.Offset
    $capacity = [int][Math]::Floor((Get-PciExtendedCapabilityByteLength -Capability $Capability) / 4)
    if (($StartDwordIndex + $valueArray.Count) -gt $capacity) { throw ('PCIe extended capability 0x{0:X4} raw write at 0x{1:X3} overruns capability: start DWORD {2}, count {3}, capacity {4}.' -f [int]$Capability.Id,$offset,$StartDwordIndex,$valueArray.Count,$capacity) }
    $written = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $valueArray.Count; $i++) {
        $dwordIndex = $StartDwordIndex + $i
        $writeOffset = $offset + ($dwordIndex * 4)
        $expected = [uint32]$valueArray[$i]
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 32 -Value $expected
        $actual = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $writeOffset -Width 32)
        if ($actual -ne $expected) { throw ('PCIe extended capability 0x{0:X4} raw DWORD write verify failed at 0x{1:X3}: expected 0x{2:X8}, readback 0x{3:X8}.' -f [int]$Capability.Id,$writeOffset,$expected,$actual) }
        [void]$written.Add([pscustomobject]@{ CapabilityId = [int]$Capability.Id; Offset = $writeOffset; DwordIndex = $dwordIndex; Value = $actual })
    }
    return [object[]]$written.ToArray()
}

function Get-PciExtendedCapabilityList {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $items = New-Object System.Collections.Generic.List[object]
    $ptr = 0x100
    $seen = @{}
    for ($i = 0; $i -lt 256 -and $ptr -ge 0x100 -and $ptr -le 0xFFC; $i++) {
        if (($ptr -band 0x3) -ne 0) { throw ('Unaligned PCIe extended capability pointer on {0}: offset 0x{1:X3}.' -f $bdf,$ptr) }
        if ($seen.ContainsKey($ptr)) { throw ('Loop detected while traversing PCIe extended capability list for {0}; repeated offset 0x{1:X3}.' -f $bdf,$ptr) }
        $seen[$ptr] = $true
        $header = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $ptr -Width 32)
        if ($header -eq 0 -or $header -eq [uint32]::MaxValue) { break }
        $capId = [int]($header -band 0xFFFF)
        $version = [int](($header -shr 16) -band 0xF)
        $next = [int](($header -shr 20) -band 0xFFC)
        [void]$items.Add([pscustomobject]@{
            Offset = [int]$ptr
            Id = [int]$capId
            Version = [int]$version
            HeaderRaw = [uint32]$header
            NextOffset = [int]$next
        })
        if ($next -eq 0) { break }
        if ($next -lt 0x100 -or $next -gt 0xFFC) { throw ('Invalid PCIe extended capability next pointer on {0}: current 0x{1:X3}, next 0x{2:X3}, header 0x{3:X8}.' -f $bdf,$ptr,$next,[uint32]$header) }
        $ptr = $next
    }
    foreach ($item in $items.ToArray()) { $item }
}


function ConvertTo-PciTphModeName {
    param([Parameter(Mandatory=$true)][int]$Mode)
    switch ($Mode -band 0x7) {
        0 { 'No-ST'; break }
        1 { 'InterruptVector'; break }
        2 { 'DeviceSpecific'; break }
        default { 'Reserved{0}' -f ($Mode -band 0x7) }
    }
}

function ConvertTo-PciTphModeValue {
    param([Parameter(Mandatory=$true)][object]$Value)
    if ($Value -is [string]) {
        $token = ([string]$Value).Trim()
        switch -Regex ($token) {
            '^(0|no[-_ ]?st|none)$' { return 0 }
            '^(1|iv|int|interrupt[-_ ]?vector)$' { return 1 }
            '^(2|ds|dev|device[-_ ]?specific)$' { return 2 }
        }
        if ($token.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) { return [int]([Convert]::ToUInt32($token.Substring(2), 16)) }
        return [int]([Convert]::ToUInt32($token, 0))
    }
    return [int]$Value
}

function ConvertTo-PciTphRequesterEnableName {
    param([Parameter(Mandatory=$true)][int]$Value)
    switch ($Value -band 0x3) {
        0 { 'Disabled'; break }
        1 { 'TPH8'; break }
        3 { 'Extended16'; break }
        default { 'Reserved{0}' -f ($Value -band 0x3) }
    }
}

function ConvertTo-PciTphRequesterEnableValue {
    param([Parameter(Mandatory=$true)][object]$Value)
    if ($Value -is [string]) {
        $token = ([string]$Value).Trim()
        switch -Regex ($token) {
            '^(0|off|disabled|disable|none)$' { return 0 }
            '^(1|on|enable|enabled|tph|tph8|8|8bit|8-bit|tph[-_ ]?only)$' { return 1 }
            '^(3|ext|extended|extended16|16|16bit|16-bit|ext[-_ ]?tph)$' { return 3 }
        }
        if ($token.StartsWith('0x', [System.StringComparison]::OrdinalIgnoreCase)) { return [int]([Convert]::ToUInt32($token.Substring(2), 16)) }
        return [int]([Convert]::ToUInt32($token, 0))
    }
    return [int]$Value
}

function ConvertTo-PciTphCompleterCapabilityName {
    param([Parameter(Mandatory=$true)][int]$Value)
    switch ($Value -band 0x3) {
        0 { 'None'; break }
        1 { 'TPH8'; break }
        3 { 'Extended16'; break }
        default { 'Reserved{0}' -f ($Value -band 0x3) }
    }
}

function Get-PciTphCompleterCapability {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if (-not [bool]$ctx.HasDevice2Registers) {
        return [pscustomobject]@{ Known = $true; Bdf = $bdf; Raw = [uint32]0; Value = 0; Name = 'None'; Reason = 'PCIe Capability version is less than 2; Device Capabilities 2 is not present.' }
    }
    $devCap2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceCapabilities2Offset) -Width 32)
    $value = [int](($devCap2 -band [uint32]0x00003000) -shr 12)
    return [pscustomobject]@{ Known = $true; Bdf = $bdf; Raw = [uint32]$devCap2; Value = [int]$value; Name = (ConvertTo-PciTphCompleterCapabilityName -Value $value); Reason = $null }
}

function Get-PciTphRequesterPathCompleterCapability {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    try {
        $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        if ($portType -eq 9) {
            return [pscustomobject]@{ Known = $false; Bdf = $bdf; CompleterBdf = $null; Value = 3; Name = 'NotChecked-RCiEP'; Raw = [uint32]0; Reason = 'Root Complex Integrated Endpoint; no upstream Root Port completer check is required.' }
        }
        $parent = Find-PciParentBridge -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        $cap = Get-PciTphCompleterCapability -Segment ([int]$parent.Segment) -Bus ([int]$parent.Bus) -Device ([int]$parent.Device) -Function ([int]$parent.Function)
        return [pscustomobject]@{ Known = [bool]$cap.Known; Bdf = $bdf; CompleterBdf = [string]$cap.Bdf; Value = [int]$cap.Value; Name = [string]$cap.Name; Raw = [uint32]$cap.Raw; Reason = $cap.Reason }
    } catch {
        return [pscustomobject]@{ Known = $false; Bdf = $bdf; CompleterBdf = $null; Value = 3; Name = 'Unknown'; Raw = [uint32]0; Reason = $_.Exception.Message }
    }
}

function Resolve-PciTphRequesterEnableForPath {
    param(
        [Parameter(Mandatory=$true)]$Before,
        [Parameter(Mandatory=$true)][int]$Requested,
        [Parameter(Mandatory=$true)][bool]$ExplicitRequester,
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [string]$Before.Bdf
    if ($Requested -ne 0 -and $Requested -ne 1 -and $Requested -ne 3) { throw ('TPH requester-enable on {0} must be 0/Disabled, 1/TPH8, or 3/Extended16. Requested={1}.' -f $bdf,$Requested) }
    if ($Requested -eq 0) { return 0 }
    if ($Requested -eq 3 -and -not [bool]$Before.TphExtendedRequesterSupported) { throw ('TPH Extended16 requester enable is not capability-supported on {0}.' -f $bdf) }
    $pathCap = Get-PciTphRequesterPathCompleterCapability -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ([bool]$pathCap.Known) {
        if ([int]$pathCap.Value -eq 0) { throw ('TPH requester enable refused on {0}: upstream/root completer {1} advertises no TPH completer support.' -f $bdf,[string]$pathCap.CompleterBdf) }
        if ($Requested -eq 3 -and [int]$pathCap.Value -ne 3) {
            if ($ExplicitRequester) { throw ('TPH Extended16 requester enable refused on {0}: upstream/root completer {1} supports {2}, not Extended16.' -f $bdf,[string]$pathCap.CompleterBdf,[string]$pathCap.Name) }
            return 1
        }
    }
    return $Requested
}

function ConvertTo-PciTphStTableLocationName {
    param([Parameter(Mandatory=$true)][int]$Location)
    switch ($Location -band 0x3) {
        0 { 'None'; break }
        1 { 'Capability'; break }
        2 { 'MSI-X'; break }
        default { 'Reserved' }
    }
}

function ConvertTo-PciVcCapabilityKindName {
    param([Parameter(Mandatory=$true)][int]$CapabilityId)
    switch ([int]$CapabilityId) {
        0x0002 { 'VC'; break }
        0x0008 { 'MFVC'; break }
        0x0009 { 'VC9'; break }
        default { 'VC{0:X4}' -f ([int]$CapabilityId -band 0xFFFF) }
    }
}

function ConvertTo-PciTrafficClassNames {
    param([Parameter(Mandatory=$true)][int]$Mask)
    $names = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt 8; $i++) { if ((($Mask -shr $i) -band 0x1) -ne 0) { [void]$names.Add(('TC{0}' -f $i)) } }
    if ($names.Count -eq 0) { return 'none' }
    return ($names -join '+')
}


function ConvertTo-PciMsiMessageCount {
    param([Parameter(Mandatory=$true)][ValidateRange(0,7)][int]$Encoded)
    return [int](([int]1) -shl ($Encoded -band 0x7))
}

function Get-PciMsiReadableByteLength {
    param([Parameter(Mandatory=$true)][uint16]$MessageControl)
    $has64 = (([uint32]$MessageControl -band [uint32]0x0080) -ne 0)
    $hasMask = (([uint32]$MessageControl -band [uint32]0x0100) -ne 0)
    if ($has64) {
        if ($hasMask) { return 24 }
        return 14
    }
    if ($hasMask) { return 20 }
    return 10
}

function Get-PciMsiRawDwordCount {
    param([Parameter(Mandatory=$true)][uint16]$MessageControl)
    return [int][Math]::Floor(([double](Get-PciMsiReadableByteLength -MessageControl $MessageControl)) / 4.0)
}

function Get-PciMsiTrailingWordOffset {
    param(
        [Parameter(Mandatory=$true)][int]$CapabilityOffset,
        [Parameter(Mandatory=$true)][uint16]$MessageControl
    )
    $length = [int](Get-PciMsiReadableByteLength -MessageControl $MessageControl)
    if (($length % 4) -eq 2) { return [int]($CapabilityOffset + $length - 2) }
    return [int]-1
}

function ConvertTo-PciUInt64Scalar {
    param([AllowNull()][object]$Value)
    if ($null -eq $Value) { throw 'A UInt64 value is required.' }
    if ($Value -is [System.Array]) {
        $items = @($Value)
        if ($items.Count -ne 1) { throw ('A single UInt64 value is required; got {0} values.' -f $items.Count) }
        return [uint64](ConvertTo-PciUInt64Scalar -Value $items[0])
    }
    $text = ([string]$Value).Trim()
    if ([string]::IsNullOrWhiteSpace($text)) { throw 'A UInt64 value cannot be empty.' }
    if ($text.StartsWith('0x',[StringComparison]::OrdinalIgnoreCase)) { return [uint64]([Convert]::ToUInt64($text.Substring(2), 16)) }
    return [uint64]([Convert]::ToUInt64($text, 10))
}

function Assert-PciKnownInterruptRawDwordWriteBounds {
    param(
        [Parameter(Mandatory=$true)]$Capability,
        [Parameter(Mandatory=$true)][ValidateSet('MSI','MSIX')][string]$Kind,
        [Parameter(Mandatory=$true)][object]$Values,
        [Parameter(Mandatory=$true)][ValidateRange(0,255)][int]$StartDwordIndex,
        [Parameter(Mandatory=$true)][bool]$AllowHeaderWrite,
        [Parameter(Mandatory=$true)][string]$Bdf
    )
    $valueArray = [uint32[]](ConvertTo-PciUInt32Array -Value $Values)
    if ($valueArray.Count -eq 0) { return }
    if ($StartDwordIndex -eq 0 -and -not $AllowHeaderWrite) { throw ('{0} raw DWORD write on {1} starts at header DWORD 0. Set AllowPciConventionalCapabilityHeaderWrite only when you intentionally want to modify Capability ID / Next Pointer / control header bits.' -f $Kind,$Bdf) }
    $maxSafeDwords = 0
    if ($Kind -eq 'MSI') {
        $control = [uint16](Read-PciConfigValue -Segment $Capability.Segment -Bus $Capability.Bus -Device $Capability.Device -Function $Capability.Function -Offset ([int]$Capability.Offset + 0x02) -Width 16)
        $maxSafeDwords = [int][Math]::Floor(([double](Get-PciMsiReadableByteLength -MessageControl $control)) / 4.0)
    } else {
        $maxSafeDwords = 3
    }
    if (($StartDwordIndex + $valueArray.Count) -gt $maxSafeDwords) { throw ('{0} raw DWORD write on {1} overruns the known {0} capability body: start DWORD {2}, count {3}, safe DWORD capacity {4}, CapabilityOffset=0x{5:X2}. Use typed fields for partial registers such as MSI MessageData.' -f $Kind,$Bdf,$StartDwordIndex,$valueArray.Count,$maxSafeDwords,[int]$Capability.Offset) }
}

function Get-PciInterruptCapabilityControlRawByIndex {
    param(
        [Parameter(Mandatory=$true)]$State,
        [Parameter(Mandatory=$true)][ValidateSet('MSI','MSIX')][string]$Kind,
        [ValidateRange(0,255)][int]$Index = 0
    )
    $list = if ($Kind -eq 'MSI') { @($State.MsiStructuresRaw) } else { @($State.MsixStructuresRaw) }
    if ($Index -lt 0 -or $Index -ge $list.Count) { throw ('{0} capability index {1} is missing in readback state for {2}; present count is {3}.' -f $Kind,$Index,[string]$State.Bdf,$list.Count) }
    return [uint16]$list[$Index].ControlRaw
}

function Get-PciInterruptCapabilityEntryByIndex {
    param(
        [Parameter(Mandatory=$true)]$State,
        [Parameter(Mandatory=$true)][ValidateSet('MSI','MSIX')][string]$Kind,
        [ValidateRange(0,255)][int]$Index = 0
    )
    $list = if ($Kind -eq 'MSI') { @($State.MsiStructuresRaw) } else { @($State.MsixStructuresRaw) }
    if ($Index -lt 0 -or $Index -ge $list.Count) { throw ('{0} capability index {1} is missing in readback state for {2}; present count is {3}.' -f $Kind,$Index,[string]$State.Bdf,$list.Count) }
    return $list[$Index]
}

function Get-PciMaskedControlRequestedBit {
    param(
        [AllowNull()][object]$Mask,
        [AllowNull()][object]$Value,
        [Parameter(Mandatory=$true)][uint16]$Bit
    )
    if (-not ((Test-DeviceTweakerNullableValueSpecified $Mask) -and (Test-DeviceTweakerNullableValueSpecified $Value))) { return $null }
    $maskValues = [uint32[]](ConvertTo-PciUInt32Array -Value $Mask)
    $valueValues = [uint32[]](ConvertTo-PciUInt32Array -Value $Value)
    if ($maskValues.Count -eq 0 -or $valueValues.Count -eq 0) { return $null }
    if ((([uint16]($maskValues[0] -band 0xFFFF)) -band $Bit) -eq 0) { return $null }
    return [bool]((([uint16]($valueValues[0] -band 0xFFFF)) -band $Bit) -ne 0)
}

function Set-PciMsiMaskBits {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$MsiEntry,
        [AllowNull()][object]$MaskBits,
        [AllowNull()][object]$MaskBitsSet,
        [AllowNull()][object]$MaskBitsClear
    )
    if (-not [bool]$MsiEntry.PerVectorMaskingCapable) { throw ('MSI per-vector mask write refused on {0}: MSI capability at 0x{1:X2} does not advertise Per-Vector Masking Capable.' -f [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function),[int]$MsiEntry.Offset) }
    $target = [uint32]$MsiEntry.MaskBitsRaw
    if (Test-DeviceTweakerNullableValueSpecified $MaskBits) {
        $values = [uint32[]](ConvertTo-PciUInt32Array -Value $MaskBits)
        if ($values.Count -eq 0) { throw 'MSI MaskBits requires a non-empty DWORD value.' }
        $target = [uint32]$values[0]
    }
    if (Test-DeviceTweakerNullableValueSpecified $MaskBitsSet) {
        $values = [uint32[]](ConvertTo-PciUInt32Array -Value $MaskBitsSet)
        if ($values.Count -eq 0) { throw 'MSI MaskBitsSet requires a non-empty DWORD value.' }
        $target = [uint32]($target -bor [uint32]$values[0])
    }
    if (Test-DeviceTweakerNullableValueSpecified $MaskBitsClear) {
        $values = [uint32[]](ConvertTo-PciUInt32Array -Value $MaskBitsClear)
        if ($values.Count -eq 0) { throw 'MSI MaskBitsClear requires a non-empty DWORD value.' }
        $target = [uint32]($target -band ([uint32]::MaxValue -bxor [uint32]$values[0]))
    }
    Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$MsiEntry.MaskBitsOffset) -Width 32 -Value $target
    $actual = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$MsiEntry.MaskBitsOffset) -Width 32)
    if ($actual -ne $target) { throw ('MSI Mask Bits write verify failed on {0} at 0x{1:X2}: expected 0x{2:X8}, readback 0x{3:X8}.' -f [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function),[int]$MsiEntry.MaskBitsOffset,[uint32]$target,[uint32]$actual) }
    return [pscustomobject]@{ CapabilityIndex = [int]$MsiEntry.Index; Offset = [int]$MsiEntry.MaskBitsOffset; Value = [uint32]$actual }
}

function Set-PciMsiMessageRoute {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$MsiEntry,
        [AllowNull()][object]$MessageAddress,
        [AllowNull()][object]$MessageAddressLo,
        [AllowNull()][object]$MessageAddressHi,
        [AllowNull()][object]$MessageData,
        [bool]$DisableWhileWriting = $true
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $routeRequested = (Test-DeviceTweakerNullableValueSpecified $MessageAddress) -or (Test-DeviceTweakerNullableValueSpecified $MessageAddressLo) -or (Test-DeviceTweakerNullableValueSpecified $MessageAddressHi) -or (Test-DeviceTweakerNullableValueSpecified $MessageData)
    if (-not $routeRequested) { return $null }
    $targetLo = [uint32]$MsiEntry.MessageAddressLo
    $targetHi = [uint32]$MsiEntry.MessageAddressHi
    $targetData = [uint16]$MsiEntry.MessageData
    if (Test-DeviceTweakerNullableValueSpecified $MessageAddress) {
        if ((Test-DeviceTweakerNullableValueSpecified $MessageAddressLo) -or (Test-DeviceTweakerNullableValueSpecified $MessageAddressHi)) { throw ('MSI route write on {0} cannot combine MsiMessageAddress with MsiMessageAddressLo/MsiMessageAddressHi.' -f $bdf) }
        $addr64 = [uint64](ConvertTo-PciUInt64Scalar -Value $MessageAddress)
        if (($addr64 -band [uint64]0x3) -ne 0) { throw ('MSI Message Address on {0} must be DWORD aligned; requested 0x{1:X}.' -f $bdf,[uint64]$addr64) }
        $mask32 = [Convert]::ToUInt64('FFFFFFFF', 16)
        $targetLo = [uint32]($addr64 -band $mask32)
        $targetHi = [uint32](($addr64 -shr 32) -band $mask32)
    }
    if (Test-DeviceTweakerNullableValueSpecified $MessageAddressLo) {
        $loValues = [uint32[]](ConvertTo-PciUInt32Array -Value $MessageAddressLo)
        if ($loValues.Count -eq 0) { throw ('MSI MessageAddressLo on {0} requires one DWORD.' -f $bdf) }
        $targetLo = [uint32]$loValues[0]
        if (($targetLo -band [uint32]0x00000003) -ne 0) { throw ('MSI MessageAddressLo on {0} must be DWORD aligned; requested 0x{1:X8}.' -f $bdf,[uint32]$targetLo) }
    }
    if (Test-DeviceTweakerNullableValueSpecified $MessageAddressHi) {
        if (-not [bool]$MsiEntry.Is64BitCapable) { throw ('MSI MessageAddressHi write refused on {0}: MSI capability at 0x{1:X2} is not 64-bit address capable.' -f $bdf,[int]$MsiEntry.Offset) }
        $hiValues = [uint32[]](ConvertTo-PciUInt32Array -Value $MessageAddressHi)
        if ($hiValues.Count -eq 0) { throw ('MSI MessageAddressHi on {0} requires one DWORD.' -f $bdf) }
        $targetHi = [uint32]$hiValues[0]
    }
    if (-not [bool]$MsiEntry.Is64BitCapable -and $targetHi -ne 0) { throw ('MSI 64-bit MessageAddress value on {0} is not writable because the MSI capability is 32-bit only. Requested upper DWORD=0x{1:X8}.' -f $bdf,[uint32]$targetHi) }
    if (Test-DeviceTweakerNullableValueSpecified $MessageData) {
        $dataValues = [uint32[]](ConvertTo-PciUInt32Array -Value $MessageData)
        if ($dataValues.Count -eq 0) { throw ('MSI MessageData on {0} requires one WORD-sized value.' -f $bdf) }
        if ([uint32]$dataValues[0] -gt [uint32]0xFFFF) { throw ('MSI MessageData on {0} must fit in 16 bits; requested 0x{1:X}.' -f $bdf,[uint32]$dataValues[0]) }
        $targetData = [uint16]([uint32]$dataValues[0] -band [uint32]0xFFFF)
    }

    $controlOffset = [int]$MsiEntry.Offset + 0x02
    $addressLoOffset = [int]$MsiEntry.Offset + 0x04
    $addressHiOffset = [int]$MsiEntry.Offset + 0x08
    $dataOffset = [int]$MsiEntry.MessageDataOffset
    $originalControl = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $controlOffset -Width 16)
    $wasEnabled = (($originalControl -band [uint16]0x0001) -ne 0)
    if ($DisableWhileWriting -and $wasEnabled) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $controlOffset -Width 16 -Value ([uint16]([uint32]$originalControl -band ([uint32]0xFFFF -bxor [uint32]0x0001))) }
    try {
        if ((Test-DeviceTweakerNullableValueSpecified $MessageAddress) -or (Test-DeviceTweakerNullableValueSpecified $MessageAddressLo)) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $addressLoOffset -Width 32 -Value $targetLo }
        if ([bool]$MsiEntry.Is64BitCapable -and ((Test-DeviceTweakerNullableValueSpecified $MessageAddress) -or (Test-DeviceTweakerNullableValueSpecified $MessageAddressHi))) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $addressHiOffset -Width 32 -Value $targetHi }
        if (Test-DeviceTweakerNullableValueSpecified $MessageData) { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $dataOffset -Width 16 -Value $targetData }
    } finally {
        if ($DisableWhileWriting -and $wasEnabled) {
            try { Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $controlOffset -Width 16 -Value $originalControl } catch { }
        }
    }

    $actualLo = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $addressLoOffset -Width 32)
    $actualHi = [uint32]0
    if ([bool]$MsiEntry.Is64BitCapable) { $actualHi = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $addressHiOffset -Width 32) }
    $actualData = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $dataOffset -Width 16)
    if ($actualLo -ne $targetLo) { throw ('MSI MessageAddressLo write verify failed on {0}: expected 0x{1:X8}, readback 0x{2:X8}.' -f $bdf,[uint32]$targetLo,[uint32]$actualLo) }
    if ([bool]$MsiEntry.Is64BitCapable -and $actualHi -ne $targetHi) { throw ('MSI MessageAddressHi write verify failed on {0}: expected 0x{1:X8}, readback 0x{2:X8}.' -f $bdf,[uint32]$targetHi,[uint32]$actualHi) }
    if ($actualData -ne $targetData) { throw ('MSI MessageData write verify failed on {0}: expected 0x{1:X4}, readback 0x{2:X4}.' -f $bdf,[uint16]$targetData,[uint16]$actualData) }
    return [pscustomobject]@{ CapabilityIndex = [int]$MsiEntry.Index; Offset = [int]$MsiEntry.Offset; MessageAddressLo = [uint32]$actualLo; MessageAddressHi = [uint32]$actualHi; MessageAddress = [uint64]((([uint64]$actualHi) -shl 32) -bor [uint64]$actualLo); MessageData = [uint16]$actualData }
}

function Set-PciMsixTableVectorMasks {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Masks,
        [ValidateRange(0,2047)][int]$StartVectorIndex = 0
    )
    $maskValues = [uint32[]](ConvertTo-PciUInt32Array -Value $Masks)
    if ($maskValues.Count -eq 0) { return [object[]]@() }
    $info = Get-PciMsixTableInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability
    if (($StartVectorIndex + $maskValues.Count) -gt [int]$info.TableSize) { throw ('MSI-X vector-mask write overruns table on {0}: start vector {1}, count {2}, table size {3}, CapabilityOffset=0x{4:X2}.' -f [string]$info.Bdf,$StartVectorIndex,$maskValues.Count,[int]$info.TableSize,[int]$info.CapabilityOffset) }
    $written = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $maskValues.Count; $i++) {
        $vectorIndex = $StartVectorIndex + $i
        $dwordIndex = ($vectorIndex * 4) + 3
        $address = [uint64]([uint64]$info.TableAddress + ([uint64]$dwordIndex * [uint64]4))
        $before = [uint32](Read-PciMmio32 -Address $address -Context ('MSI-X vector mask pre-read BDF={0} Cap=0x{1:X2} Vector={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$vectorIndex,[uint64]$address))
        $expected = [uint32]($before -band ([uint32]::MaxValue -bxor [uint32]0x00000001))
        if (([uint32]$maskValues[$i] -band [uint32]0x00000001) -ne 0) { $expected = [uint32]($expected -bor [uint32]0x00000001) }
        Write-PciMmio32 -Address $address -Value $expected -Context ('MSI-X vector mask write BDF={0} Cap=0x{1:X2} Vector={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$vectorIndex,[uint64]$address)
        $actual = [uint32](Read-PciMmio32 -Address $address -Context ('MSI-X vector mask write verify BDF={0} Cap=0x{1:X2} Vector={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$vectorIndex,[uint64]$address))
        if ($actual -ne $expected) { throw ('MSI-X vector mask write verify failed on {0} vector {1} at address 0x{2:X}: expected 0x{3:X8}, readback 0x{4:X8}.' -f [string]$info.Bdf,$vectorIndex,[uint64]$address,[uint32]$expected,[uint32]$actual) }
        [void]$written.Add([pscustomobject]@{ CapabilityOffset = [int]$info.CapabilityOffset; VectorIndex = [int]$vectorIndex; DwordIndex = [int]$dwordIndex; Address = [uint64]$address; VectorControl = [uint32]$actual; Masked = [bool](($actual -band [uint32]0x00000001) -ne 0) })
    }
    return [object[]]$written.ToArray()
}

function Read-PciMmio32 {
    param(
        [Parameter(Mandatory=$true)][uint64]$Address,
        [AllowNull()][string]$Context
    )
    $cmd = 'R32 ' + (Dec-To-Hex -decimal ([uint64]$Address))
    try {
        $stdout = Invoke-RWECommand -Command $cmd
        return [uint32]((Convert-RWEverythingOutputToUInt64 -Stdout $stdout -Context $Context) -band 0xFFFFFFFF)
    } catch {
        throw ('PCI MMIO read failed. Address=0x{0:X}; Command={1}; Context={2}{3}{4}' -f [uint64]$Address,$cmd,[string]$Context,[Environment]::NewLine,$_.Exception.Message)
    }
}

function Write-PciMmio32 {
    param(
        [Parameter(Mandatory=$true)][uint64]$Address,
        [Parameter(Mandatory=$true)][uint32]$Value,
        [AllowNull()][string]$Context
    )
    $cmd = 'W32 ' + (Dec-To-Hex -decimal ([uint64]$Address)) + (' 0x{0:X8}' -f [uint32]$Value)
    try {
        [void](Invoke-RWECommand -Command $cmd -AllowEmptyOutput)
    } catch {
        throw ('PCI MMIO write failed. Address=0x{0:X}; Value=0x{1:X8}; Command={2}; Context={3}{4}{5}' -f [uint64]$Address,[uint32]$Value,$cmd,[string]$Context,[Environment]::NewLine,$_.Exception.Message)
    }
}

function Get-PciMsixTableInfo {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $offset = [int]$Capability.Offset
    $flags = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x02) -Width 16)
    $tableRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x04) -Width 32)
    $pbaRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($offset + 0x08) -Width 32)
    $tableSize = [int](($flags -band [uint16]0x07FF) + 1)
    $tableBir = [int]($tableRaw -band [uint32]0x00000007)
    $pbaBir = [int]($pbaRaw -band [uint32]0x00000007)
    if ($tableBir -lt 0 -or $tableBir -gt 5) { throw ('MSI-X table BIR {0} is invalid for {1}; CapabilityOffset=0x{2:X2}; TableRaw=0x{3:X8}.' -f $tableBir,$bdf,$offset,[uint32]$tableRaw) }
    if ($pbaBir -lt 0 -or $pbaBir -gt 5) { throw ('MSI-X PBA BIR {0} is invalid for {1}; CapabilityOffset=0x{2:X2}; PbaRaw=0x{3:X8}.' -f $pbaBir,$bdf,$offset,[uint32]$pbaRaw) }
    $tableBar = Get-PciRebarBarDescriptor -Segment $Segment -Bus $Bus -Device $Device -Function $Function -BarIndex $tableBir
    $pbaBar = Get-PciRebarBarDescriptor -Segment $Segment -Bus $Bus -Device $Device -Function $Function -BarIndex $pbaBir
    if ([bool]$tableBar.IsIo) { throw ('MSI-X table BAR{0} is I/O space on {1}; RWEverything R32/W32 MMIO table access requires a memory BAR.' -f $tableBir,$bdf) }
    if ([bool]$pbaBar.IsIo) { throw ('MSI-X PBA BAR{0} is I/O space on {1}; RWEverything R32 MMIO PBA access requires a memory BAR.' -f $pbaBir,$bdf) }
    $tableBase = [uint64]$tableBar.BaseAddress
    $pbaBase = [uint64]$pbaBar.BaseAddress
    $tableOffset = [uint64]($tableRaw -band [uint32]4294967288)
    $pbaOffset = [uint64]($pbaRaw -band [uint32]4294967288)
    if ($tableBase -eq 0) { throw ('MSI-X table BAR{0} base is zero on {1}; CapabilityOffset=0x{2:X2}; TableRaw=0x{3:X8}.' -f $tableBir,$bdf,$offset,[uint32]$tableRaw) }
    if ($pbaBase -eq 0) { throw ('MSI-X PBA BAR{0} base is zero on {1}; CapabilityOffset=0x{2:X2}; PbaRaw=0x{3:X8}.' -f $pbaBir,$bdf,$offset,[uint32]$pbaRaw) }
    if (($tableOffset -band [uint64]0x7) -ne 0) { throw ('MSI-X table offset is not QWORD aligned on {0}; CapabilityOffset=0x{1:X2}; TableRaw=0x{2:X8}; Offset=0x{3:X}.' -f $bdf,$offset,[uint32]$tableRaw,[uint64]$tableOffset) }
    if (($pbaOffset -band [uint64]0x7) -ne 0) { throw ('MSI-X PBA offset is not QWORD aligned on {0}; CapabilityOffset=0x{1:X2}; PbaRaw=0x{2:X8}; Offset=0x{3:X}.' -f $bdf,$offset,[uint32]$pbaRaw,[uint64]$pbaOffset) }
    if (([uint64]::MaxValue - [uint64]$tableBase) -lt [uint64]$tableOffset) { throw ('MSI-X table address overflows UInt64 on {0}; BAR{1}=0x{2:X}; Offset=0x{3:X}.' -f $bdf,$tableBir,[uint64]$tableBase,[uint64]$tableOffset) }
    if (([uint64]::MaxValue - [uint64]$pbaBase) -lt [uint64]$pbaOffset) { throw ('MSI-X PBA address overflows UInt64 on {0}; BAR{1}=0x{2:X}; Offset=0x{3:X}.' -f $bdf,$pbaBir,[uint64]$pbaBase,[uint64]$pbaOffset) }
    $tableAddress = [uint64]($tableBase + $tableOffset)
    $pbaAddress = [uint64]($pbaBase + $pbaOffset)
    $tableBytes = [uint64]([uint64]$tableSize * [uint64]16)
    $pbaQwords = [uint64]([Math]::Ceiling(([double]$tableSize) / 64.0))
    $pbaBytes = [uint64]($pbaQwords * [uint64]8)
    if (([uint64]::MaxValue - [uint64]$tableAddress) -lt ([uint64]$tableBytes - [uint64]1)) { throw ('MSI-X table byte range overflows UInt64 on {0}; Address=0x{1:X}; Bytes={2}.' -f $bdf,[uint64]$tableAddress,[uint64]$tableBytes) }
    if (([uint64]::MaxValue - [uint64]$pbaAddress) -lt ([uint64]$pbaBytes - [uint64]1)) { throw ('MSI-X PBA byte range overflows UInt64 on {0}; Address=0x{1:X}; Bytes={2}.' -f $bdf,[uint64]$pbaAddress,[uint64]$pbaBytes) }
    [pscustomobject]@{
        Bdf = $bdf
        CapabilityOffset = [int]$offset
        FlagsRaw = [uint16]$flags
        TableSize = [int]$tableSize
        TableRaw = [uint32]$tableRaw
        PbaRaw = [uint32]$pbaRaw
        TableBir = [int]$tableBir
        PbaBir = [int]$pbaBir
        TableOffset = [uint64]$tableOffset
        PbaOffset = [uint64]$pbaOffset
        TableBarBaseAddress = [uint64]$tableBase
        PbaBarBaseAddress = [uint64]$pbaBase
        TableAddress = [uint64]$tableAddress
        PbaAddress = [uint64]$pbaAddress
        TableByteLength = [uint64]$tableBytes
        PbaByteLength = [uint64]$pbaBytes
        PbaQwordCount = [int]$pbaQwords
        TableEndAddress = [uint64]($tableAddress + $tableBytes - [uint64]1)
        PbaEndAddress = [uint64]($pbaAddress + $pbaBytes - [uint64]1)
        TotalTableDwords = [int]($tableSize * 4)
        TotalPbaDwords = [int]($pbaQwords * [uint64]2)
    }
}

function Read-PciMsixTableRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,1048575)][int]$StartDwordIndex = 0,
        [ValidateRange(0,1048575)][int]$MaxDwords = 0
    )
    $info = Get-PciMsixTableInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability
    if ($StartDwordIndex -ge [int]$info.TotalTableDwords) { throw ('MSI-X table start DWORD {0} exceeds table capacity {1} on {2}; CapabilityOffset=0x{3:X2}.' -f $StartDwordIndex,[int]$info.TotalTableDwords,[string]$info.Bdf,[int]$info.CapabilityOffset) }
    $count = if ($MaxDwords -gt 0) { [Math]::Min($MaxDwords, [int]$info.TotalTableDwords - $StartDwordIndex) } else { [int]$info.TotalTableDwords - $StartDwordIndex }
    $items = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt $count; $i++) {
        $dwordIndex = $StartDwordIndex + $i
        $address = [uint64]([uint64]$info.TableAddress + ([uint64]$dwordIndex * [uint64]4))
        [void]$items.Add([uint32](Read-PciMmio32 -Address $address -Context ('MSI-X table read BDF={0} Cap=0x{1:X2} Dword={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$dwordIndex,[uint64]$address)))
    }
    return [uint32[]]$items.ToArray()
}

function Read-PciMsixPbaRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [ValidateRange(0,1048575)][int]$StartDwordIndex = 0,
        [ValidateRange(0,1048575)][int]$MaxDwords = 0
    )
    $info = Get-PciMsixTableInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability
    if ([int]$info.TotalPbaDwords -le 0) { return [uint32[]]@() }
    if ($StartDwordIndex -ge [int]$info.TotalPbaDwords) { throw ('MSI-X PBA start DWORD {0} exceeds PBA capacity {1} on {2}; CapabilityOffset=0x{3:X2}.' -f $StartDwordIndex,[int]$info.TotalPbaDwords,[string]$info.Bdf,[int]$info.CapabilityOffset) }
    $count = if ($MaxDwords -gt 0) { [Math]::Min($MaxDwords, [int]$info.TotalPbaDwords - $StartDwordIndex) } else { [int]$info.TotalPbaDwords - $StartDwordIndex }
    $items = New-Object System.Collections.Generic.List[uint32]
    for ($i = 0; $i -lt $count; $i++) {
        $dwordIndex = $StartDwordIndex + $i
        $address = [uint64]([uint64]$info.PbaAddress + ([uint64]$dwordIndex * [uint64]4))
        [void]$items.Add([uint32](Read-PciMmio32 -Address $address -Context ('MSI-X PBA read BDF={0} Cap=0x{1:X2} Dword={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$dwordIndex,[uint64]$address)))
    }
    return [uint32[]]$items.ToArray()
}

function Set-PciMsixTableRawDwords {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)]$Capability,
        [AllowNull()][object]$Values,
        [ValidateRange(0,1048575)][int]$StartDwordIndex = 0
    )
    $valueArray = [uint32[]](ConvertTo-PciUInt32Array -Value $Values)
    if ($valueArray.Count -eq 0) { return [object[]]@() }
    $info = Get-PciMsixTableInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $Capability
    if (($StartDwordIndex + $valueArray.Count) -gt [int]$info.TotalTableDwords) { throw ('MSI-X table raw write overruns table on {0}: start DWORD {1}, count {2}, capacity {3}, CapabilityOffset=0x{4:X2}.' -f [string]$info.Bdf,$StartDwordIndex,$valueArray.Count,[int]$info.TotalTableDwords,[int]$info.CapabilityOffset) }
    $written = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $valueArray.Count; $i++) {
        $dwordIndex = $StartDwordIndex + $i
        $address = [uint64]([uint64]$info.TableAddress + ([uint64]$dwordIndex * [uint64]4))
        $expected = [uint32]$valueArray[$i]
        Write-PciMmio32 -Address $address -Value $expected -Context ('MSI-X table write BDF={0} Cap=0x{1:X2} Dword={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$dwordIndex,[uint64]$address)
        $actual = [uint32](Read-PciMmio32 -Address $address -Context ('MSI-X table write verify BDF={0} Cap=0x{1:X2} Dword={2} Address=0x{3:X}' -f [string]$info.Bdf,[int]$info.CapabilityOffset,$dwordIndex,[uint64]$address))
        if ($actual -ne $expected) { throw ('MSI-X table raw DWORD write verify failed on {0} at address 0x{1:X}: DWORD {2}, expected 0x{3:X8}, readback 0x{4:X8}.' -f [string]$info.Bdf,[uint64]$address,$dwordIndex,$expected,$actual) }
        [void]$written.Add([pscustomobject]@{ CapabilityOffset = [int]$info.CapabilityOffset; DwordIndex = [int]$dwordIndex; Address = [uint64]$address; Value = [uint32]$actual })
    }
    return [object[]]$written.ToArray()
}

function Get-PciAerDpcAcsState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $caps = @(Get-PciExtendedCapabilityList -Segment $Segment -Bus $Bus -Device $Device -Function $Function)
    $pciCaps = @(Get-PciCapabilityList -Segment $Segment -Bus $Bus -Device $Device -Function $Function)
    $bdf = ('{0:X4}:{1:X2}:{2:X2}.{3}' -f $Segment,$Bus,$Device,$Function)

    $aer = $null
    $dpc = $null
    $msiCaps = New-Object System.Collections.Generic.List[object]
    $msixCaps = New-Object System.Collections.Generic.List[object]
    $acs = $null
    $ats = $null
    $pri = $null
    $pasid = $null
    $tph = $null
    $ptm = $null
    $ide = $null
    $lmr = $null
    $secondaryPci = $null
    $physicalLayerCaps = New-Object System.Collections.Generic.List[object]
    $flitExtendedCaps = New-Object System.Collections.Generic.List[object]
    $vcCaps = New-Object System.Collections.Generic.List[object]
    $vsecCaps = New-Object System.Collections.Generic.List[object]
    $dvsecCaps = New-Object System.Collections.Generic.List[object]
    $doeCaps = New-Object System.Collections.Generic.List[object]
    $vndrCaps = New-Object System.Collections.Generic.List[object]
    foreach ($pciCap in $pciCaps) {
        if ([int]$pciCap.Id -eq 0x05) { [void]$msiCaps.Add($pciCap) }
        elseif ([int]$pciCap.Id -eq 0x11) { [void]$msixCaps.Add($pciCap) }
        elseif ([int]$pciCap.Id -eq 0x09) { [void]$vndrCaps.Add($pciCap) }
    }
    foreach ($cap in $caps) {
        switch ([uint16]$cap.Id) {
            0x0001 { if ($null -eq $aer) { $aer = $cap } }
            0x0002 { [void]$vcCaps.Add($cap) }
            0x0008 { [void]$vcCaps.Add($cap) }
            0x0009 { [void]$vcCaps.Add($cap) }
            0x000B { [void]$vsecCaps.Add($cap) }
            0x001D { if ($null -eq $dpc) { $dpc = $cap } }
            0x000D { if ($null -eq $acs) { $acs = $cap } }
            0x000F { if ($null -eq $ats) { $ats = $cap } }
            0x0013 { if ($null -eq $pri) { $pri = $cap } }
            0x0017 { if ($null -eq $tph) { $tph = $cap } }
            0x0019 { if ($null -eq $secondaryPci) { $secondaryPci = $cap } }
            0x001B { if ($null -eq $pasid) { $pasid = $cap } }
            0x001F { if ($null -eq $ptm) { $ptm = $cap } }
            0x0023 { [void]$dvsecCaps.Add($cap) }
            0x0026 { [void]$physicalLayerCaps.Add($cap) }
            0x0027 { if ($null -eq $lmr) { $lmr = $cap } }
            0x002A { [void]$physicalLayerCaps.Add($cap) }
            0x002E { [void]$doeCaps.Add($cap) }
            0x0030 { if ($null -eq $ide) { $ide = $cap } }
            0x0031 { [void]$physicalLayerCaps.Add($cap) }
            0x0032 { [void]$flitExtendedCaps.Add($cap) }
            0x0033 { [void]$flitExtendedCaps.Add($cap) }
            0x0034 { [void]$flitExtendedCaps.Add($cap) }
            0x0037 { [void]$flitExtendedCaps.Add($cap) }
        }
    }


    $msiPresent = ($msiCaps.Count -gt 0)
    $msixPresent = ($msixCaps.Count -gt 0)
    $msiStructures = New-Object System.Collections.Generic.List[object]
    $msixStructures = New-Object System.Collections.Generic.List[object]
    $msiEnabled = $false
    $msixEnabled = $false
    $msixFunctionMasked = $false
    $msiVectorUsedTotal = 0
    $msiVectorPossibleTotal = 0
    $msixVectorUsedTotal = 0
    $msixVectorPossibleTotal = 0
    $msixVectorCountsKnown = $true
    $msixVectorCountErrors = New-Object System.Collections.Generic.List[string]
    foreach ($msiCap in @($msiCaps.ToArray())) {
        $msiIndex = [int]$msiStructures.Count
        $msiOffset = [int]$msiCap.Offset
        $msiControl = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msiOffset + 0x02) -Width 16)
        $msiCapableEncoded = [int](($msiControl -band [uint16]0x000E) -shr 1)
        $msiEnabledEncoded = [int](($msiControl -band [uint16]0x0070) -shr 4)
        $msiVectorPossibleCount = [int](ConvertTo-PciMsiMessageCount -Encoded $msiCapableEncoded)
        $msiVectorEnabledCount = [int](ConvertTo-PciMsiMessageCount -Encoded $msiEnabledEncoded)
        $msiHas64 = (($msiControl -band [uint16]0x0080) -ne 0)
        $msiMaskCapable = (($msiControl -band [uint16]0x0100) -ne 0)
        $msiAddressLo = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msiOffset + 0x04) -Width 32)
        $msiAddressHi = [uint32]0
        $msiDataOffset = if ($msiHas64) { $msiOffset + 0x0C } else { $msiOffset + 0x08 }
        if ($msiHas64) { $msiAddressHi = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msiOffset + 0x08) -Width 32) }
        $msiData = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $msiDataOffset -Width 16)
        $msiMaskOffset = if ($msiHas64) { $msiOffset + 0x10 } else { $msiOffset + 0x0C }
        $msiPendingOffset = if ($msiHas64) { $msiOffset + 0x14 } else { $msiOffset + 0x10 }
        $msiMaskBits = [uint32]0
        $msiPendingBits = [uint32]0
        if ($msiMaskCapable) {
            $msiMaskBits = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $msiMaskOffset -Width 32)
            $msiPendingBits = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $msiPendingOffset -Width 32)
        }
        $msiRawDwords = New-Object System.Collections.Generic.List[uint32]
        $msiRawDwordCount = Get-PciMsiRawDwordCount -MessageControl $msiControl
        $msiTrailingWordOffset = Get-PciMsiTrailingWordOffset -CapabilityOffset $msiOffset -MessageControl $msiControl
        $msiTrailingWordRaw = [uint16]0
        if ($msiTrailingWordOffset -ge 0) { $msiTrailingWordRaw = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $msiTrailingWordOffset -Width 16) }
        foreach ($value in @(Read-PciConventionalCapabilityRawDwords -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $msiCap -StartDwordIndex 0 -MaxDwords $msiRawDwordCount)) { [void]$msiRawDwords.Add([uint32]$value) }
        $msiEntryEnabled = (($msiControl -band [uint16]0x0001) -ne 0)
        $msiVectorUsedCount = if ($msiEntryEnabled) { [int]$msiVectorEnabledCount } else { [int]0 }
        $msiVectorPossibleTotal += [int]$msiVectorPossibleCount
        $msiVectorUsedTotal += [int]$msiVectorUsedCount
        if ($msiEntryEnabled) { $msiEnabled = $true }
        [void]$msiStructures.Add([pscustomobject]@{
            Index = [int]$msiIndex
            Offset = [int]$msiOffset
            HeaderRaw = [uint32]$msiCap.HeaderRaw
            ControlRaw = [uint16]$msiControl
            Enabled = [bool]$msiEntryEnabled
            MultipleMessageCapableEncoded = [int]$msiCapableEncoded
            MultipleMessageCapableCount = [int]$msiVectorPossibleCount
            MultipleMessageEnableEncoded = [int]$msiEnabledEncoded
            MultipleMessageEnableCount = [int]$msiVectorEnabledCount
            VectorUsedCount = [int]$msiVectorUsedCount
            VectorPossibleCount = [int]$msiVectorPossibleCount
            Is64BitCapable = [bool]$msiHas64
            PerVectorMaskingCapable = [bool]$msiMaskCapable
            MessageAddressLo = [uint32]$msiAddressLo
            MessageAddressHi = [uint32]$msiAddressHi
            MessageAddress = [uint64]((([uint64]$msiAddressHi) -shl 32) -bor [uint64]$msiAddressLo)
            MessageDataOffset = [int]$msiDataOffset
            MessageData = [uint16]$msiData
            MaskBitsOffset = if ($msiMaskCapable) { [int]$msiMaskOffset } else { [int]-1 }
            PendingBitsOffset = if ($msiMaskCapable) { [int]$msiPendingOffset } else { [int]-1 }
            MaskBitsRaw = [uint32]$msiMaskBits
            PendingBitsRaw = [uint32]$msiPendingBits
            RawDwords = [uint32[]]$msiRawDwords.ToArray()
            RawCompleteDwordCount = [int]$msiRawDwordCount
            RawTrailingWordOffset = [int]$msiTrailingWordOffset
            RawTrailingWord = [uint16]$msiTrailingWordRaw
            RawReadLengthBytes = [int](Get-PciMsiReadableByteLength -MessageControl $msiControl)
        })
    }
    foreach ($msixCap in @($msixCaps.ToArray())) {
        $msixIndex = [int]$msixStructures.Count
        $msixOffset = [int]$msixCap.Offset
        $msixFlags = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msixOffset + 0x02) -Width 16)
        $msixTableRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msixOffset + 0x04) -Width 32)
        $msixPbaRaw = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($msixOffset + 0x08) -Width 32)
        $msixTableSize = [int](($msixFlags -band [uint16]0x07FF) + 1)
        $msixEntryEnabled = (($msixFlags -band [uint16]0x8000) -ne 0)
        $msixMasked = (($msixFlags -band [uint16]0x4000) -ne 0)
        if ($msixEntryEnabled) { $msixEnabled = $true }
        if ($msixMasked) { $msixFunctionMasked = $true }
        $msixRawDwords = New-Object System.Collections.Generic.List[uint32]
        foreach ($value in @(Read-PciConventionalCapabilityRawDwords -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $msixCap -StartDwordIndex 0 -MaxDwords 3)) { [void]$msixRawDwords.Add([uint32]$value) }
        $msixTableDwords = New-Object System.Collections.Generic.List[uint32]
        $msixPbaDwords = New-Object System.Collections.Generic.List[uint32]
        $msixTableEntries = New-Object System.Collections.Generic.List[object]
        $msixTableInfo = $null
        $msixTableReadError = $null
        $msixPbaReadError = $null
        $msixAnyReadVectorMasked = $false
        $msixAllReadVectorsMasked = $false
        $msixVectorUsedCount = 0
        $msixVectorMaskedCount = 0
        $msixVectorControlReadCount = 0
        $msixVectorCountKnown = $false
        $msixVectorCountReadError = $null
        $msixAnyPending = $false
        $msixPendingVectorCount = 0
        try {
            $msixTableInfo = Get-PciMsixTableInfo -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $msixCap
            $autoTableDwords = [Math]::Min([int]$msixTableInfo.TotalTableDwords, 16)
            if ($autoTableDwords -gt 0) { foreach ($value in @(Read-PciMsixTableRawDwords -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $msixCap -StartDwordIndex 0 -MaxDwords $autoTableDwords)) { [void]$msixTableDwords.Add([uint32]$value) } }
            $entryReadCount = [int][Math]::Floor($msixTableDwords.Count / 4)
            if ($entryReadCount -gt 0) { $msixAllReadVectorsMasked = $true }
            for ($entryIndex = 0; $entryIndex -lt $entryReadCount; $entryIndex++) {
                $baseDword = $entryIndex * 4
                $addrLo = [uint32]$msixTableDwords[$baseDword]
                $addrHi = [uint32]$msixTableDwords[$baseDword + 1]
                $msgData = [uint32]$msixTableDwords[$baseDword + 2]
                $vectorControl = [uint32]$msixTableDwords[$baseDword + 3]
                $vectorMasked = (($vectorControl -band [uint32]0x00000001) -ne 0)
                if ($vectorMasked) { $msixAnyReadVectorMasked = $true } else { $msixAllReadVectorsMasked = $false }
                [void]$msixTableEntries.Add([pscustomobject]@{
                    VectorIndex = [int]$entryIndex
                    MessageAddressLo = [uint32]$addrLo
                    MessageAddressHi = [uint32]$addrHi
                    MessageAddress = [uint64]((([uint64]$addrHi) -shl 32) -bor [uint64]$addrLo)
                    MessageData = [uint32]$msgData
                    VectorControlRaw = [uint32]$vectorControl
                    Masked = [bool]$vectorMasked
                })
            }
        } catch {
            $msixTableReadError = $_.Exception.Message
        }
        if (-not $msixEntryEnabled -or $msixMasked) {
            $msixVectorUsedCount = 0
            $msixVectorMaskedCount = if ($msixMasked) { [int]$msixTableSize } else { [int]0 }
            $msixVectorControlReadCount = 0
            $msixVectorCountKnown = $true
        } elseif ($null -ne $msixTableInfo) {
            try {
                for ($vectorIndex = 0; $vectorIndex -lt $msixTableSize; $vectorIndex++) {
                    $dwordIndex = ($vectorIndex * 4) + 3
                    if ($dwordIndex -lt $msixTableDwords.Count) {
                        $vectorControl = [uint32]$msixTableDwords[$dwordIndex]
                    } else {
                        $address = [uint64]([uint64]$msixTableInfo.TableAddress + ([uint64]$dwordIndex * [uint64]4))
                        $vectorControl = [uint32](Read-PciMmio32 -Address $address -Context ('MSI-X vector count BDF={0} Cap=0x{1:X2} Vector={2} ControlDword={3} Address=0x{4:X}' -f [string]$msixTableInfo.Bdf,[int]$msixTableInfo.CapabilityOffset,$vectorIndex,$dwordIndex,[uint64]$address))
                    }
                    $msixVectorControlReadCount++
                    if (($vectorControl -band [uint32]0x00000001) -ne 0) { $msixVectorMaskedCount++ } else { $msixVectorUsedCount++ }
                }
                $msixVectorCountKnown = ($msixVectorControlReadCount -eq $msixTableSize)
            } catch {
                $msixVectorCountReadError = $_.Exception.Message
                $msixVectorCountKnown = $false
            }
        } else {
            $msixVectorCountReadError = $msixTableReadError
            $msixVectorCountKnown = $false
        }
        if (-not $msixVectorCountKnown) { $msixVectorCountsKnown = $false; if (-not [string]::IsNullOrWhiteSpace([string]$msixVectorCountReadError)) { [void]$msixVectorCountErrors.Add([string]$msixVectorCountReadError) } }
        $msixVectorPossibleTotal += [int]$msixTableSize
        $msixVectorUsedTotal += [int]$msixVectorUsedCount
        if ($null -ne $msixTableInfo) {
            try {
                if ([int]$msixTableInfo.TotalPbaDwords -gt 0) { foreach ($value in @(Read-PciMsixPbaRawDwords -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Capability $msixCap -StartDwordIndex 0 -MaxDwords ([int]$msixTableInfo.TotalPbaDwords))) { [void]$msixPbaDwords.Add([uint32]$value) } }
                for ($vectorIndex = 0; $vectorIndex -lt $msixTableSize; $vectorIndex++) {
                    $pbaDwordIndex = [int][Math]::Floor(([double]$vectorIndex) / 32.0)
                    if ($pbaDwordIndex -ge $msixPbaDwords.Count) { break }
                    $pbaMask = [uint32](([uint64]1) -shl ($vectorIndex % 32))
                    if ((([uint32]$msixPbaDwords[$pbaDwordIndex]) -band $pbaMask) -ne 0) { $msixAnyPending = $true; $msixPendingVectorCount++ }
                }
            } catch {
                $msixPbaReadError = $_.Exception.Message
            }
        }
        [void]$msixStructures.Add([pscustomobject]@{
            Index = [int]$msixIndex
            Offset = [int]$msixOffset
            HeaderRaw = [uint32]$msixCap.HeaderRaw
            ControlRaw = [uint16]$msixFlags
            Enabled = [bool]$msixEntryEnabled
            FunctionMasked = [bool]$msixMasked
            TableSize = [int]$msixTableSize
            TableRaw = [uint32]$msixTableRaw
            TableBir = [int]($msixTableRaw -band [uint32]0x00000007)
            TableOffset = [uint64]($msixTableRaw -band [uint32]4294967288)
            PbaRaw = [uint32]$msixPbaRaw
            PbaBir = [int]($msixPbaRaw -band [uint32]0x00000007)
            PbaOffset = [uint64]($msixPbaRaw -band [uint32]4294967288)
            TableAddress = if ($null -ne $msixTableInfo) { [uint64]$msixTableInfo.TableAddress } else { [uint64]0 }
            PbaAddress = if ($null -ne $msixTableInfo) { [uint64]$msixTableInfo.PbaAddress } else { [uint64]0 }
            TableBarBaseAddress = if ($null -ne $msixTableInfo) { [uint64]$msixTableInfo.TableBarBaseAddress } else { [uint64]0 }
            PbaBarBaseAddress = if ($null -ne $msixTableInfo) { [uint64]$msixTableInfo.PbaBarBaseAddress } else { [uint64]0 }
            PbaByteLength = if ($null -ne $msixTableInfo) { [uint64]$msixTableInfo.PbaByteLength } else { [uint64]0 }
            PbaQwordCount = if ($null -ne $msixTableInfo) { [int]$msixTableInfo.PbaQwordCount } else { [int]0 }
            TableRawDwords = [uint32[]]$msixTableDwords.ToArray()
            TableRawDwordReadCount = [int]$msixTableDwords.Count
            TableEntriesRaw = [object[]]$msixTableEntries.ToArray()
            TableEntryReadCount = [int]$msixTableEntries.Count
            VectorUsedCount = [int]$msixVectorUsedCount
            VectorPossibleCount = [int]$msixTableSize
            VectorCountKnown = [bool]$msixVectorCountKnown
            VectorControlReadCount = [int]$msixVectorControlReadCount
            VectorMaskedCount = [int]$msixVectorMaskedCount
            VectorUnmaskedCount = [int]$msixVectorUsedCount
            VectorCountReadError = $msixVectorCountReadError
            AnyReadVectorMasked = [bool]$msixAnyReadVectorMasked
            AllReadVectorsMasked = [bool]$msixAllReadVectorsMasked
            TableReadError = $msixTableReadError
            PbaRawDwords = [uint32[]]$msixPbaDwords.ToArray()
            PbaRawDwordReadCount = [int]$msixPbaDwords.Count
            PbaReadError = $msixPbaReadError
            PbaAnyPending = [bool]$msixAnyPending
            PbaPendingVectorCount = [int]$msixPendingVectorCount
            RawDwords = [uint32[]]$msixRawDwords.ToArray()
        })
    }

    $aerPresent = ($null -ne $aer)
    $aerOffset = if ($aerPresent) { [int]$aer.Offset } else { -1 }
    $aerUncorrStatus = [uint32]0
    $aerUncorrMask = [uint32]0
    $aerUncorrSeverity = [uint32]0
    $aerCorrStatus = [uint32]0
    $aerCorrMask = [uint32]0
    $aerCapControl = [uint32]0
    $aerRootCommand = [uint32]0
    $aerRootStatus = [uint32]0
    $aerRootErrorSource = [uint32]0
    $aerRootFieldsAvailable = $false
    $aerHeaderLog = New-Object System.Collections.Generic.List[uint32]
    $aerPrefixLog = New-Object System.Collections.Generic.List[uint32]
    $aerEcrcGenCap = $false
    $aerEcrcGenEn = $false
    $aerEcrcChkCap = $false
    $aerEcrcChkEn = $false
    $aerPrefixLogPresent = $false
    if ($aerPresent) {
        $aerUncorrStatus = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x04) -Width 32)
        $aerUncorrMask = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x08) -Width 32)
        $aerUncorrSeverity = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x0C) -Width 32)
        $aerCorrStatus = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x10) -Width 32)
        $aerCorrMask = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x14) -Width 32)
        $aerCapControl = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x18) -Width 32)
        $aerEcrcGenCap = (($aerCapControl -band [uint32]0x00000020) -ne 0)
        $aerEcrcGenEn = (($aerCapControl -band [uint32]0x00000040) -ne 0)
        $aerEcrcChkCap = (($aerCapControl -band [uint32]0x00000080) -ne 0)
        $aerEcrcChkEn = (($aerCapControl -band [uint32]0x00000100) -ne 0)
        $aerPrefixLogPresent = (($aerCapControl -band [uint32]0x00000800) -ne 0)
        if (($aerOffset + 0x28) -le 0xFFC) {
            for ($i = 0; $i -lt 4; $i++) { [void]$aerHeaderLog.Add([uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($aerOffset + 0x1C + ($i * 4)) -Width 32)) }
        }
        if (($aerOffset + 0x34) -le 0xFFC) {
            $aerRootFieldsAvailable = $true
