    if ([string]::IsNullOrWhiteSpace($pcieLinkEqualizationStatusText)) { $pcieLinkEqualizationStatusText = 'n/a' }
    if ([string]::IsNullOrWhiteSpace($pciePhyIndicatorError)) {
        [void]$parts.Add(('LinkPhy FLIT {0}; retimer {1}; LNKSTA2-EQ {2} comp={3} p1={4} p2={5} p3={6} req={7} incomplete={8}; preset margin={9} compliance={10} deemph={11}; flags=0x{12:X4} LNKCAP2=0x{13:X8} LNKCTL2=0x{14:X4} LNKSTA2=0x{15:X4}' -f $pcieFlitModeSummary,$pcieRetimerSummary,$pcieLinkEqualizationStatusText,$pcieLinkEqualizationComplete,$pcieLinkEqualizationPhase1,$pcieLinkEqualizationPhase2,$pcieLinkEqualizationPhase3,$pcieLinkEqualizationRequest,$pcieLinkEqualizationIncompletePhaseCount,$pcieLinkTransmitMarginCode,$pcieLinkCompliancePresetDeemphasis,$pcieLinkCurrentDeemphasis,[uint16]$pcieCapabilityFlagsRaw,[uint32]$pcieLinkCapabilities2Raw,[uint16]$pcieLinkControl2Raw,[uint16]$pcieLinkStatus2Raw))
    } else {
        [void]$parts.Add(('LinkPhy decode-error={0}; extCaps={1}' -f $pciePhyIndicatorError,$flitExtText))
    }
    if ($physicalLayerDecodeErrors.Count -gt 0 -and $physicalLayerStates.Count -gt 0) { [void]$parts.Add(('PHYExtPartialErrors={0}' -f ($physicalLayerDecodeErrors -join ','))) }
    if ($tphPresent) { [void]$parts.Add(('TPH@0x{0:X3} en={1} req={2} mode={3} modes=no:{4}/iv:{5}/ds:{6} ext={7} stLoc={8} stEntries={9} ctrl=0x{10:X8} cap=0x{11:X8}' -f $tphOffset,$tphEnabled,$tphRequesterEnableName,$tphModeName,$tphNoStModeSupported,$tphInterruptVectorModeSupported,$tphDeviceSpecificModeSupported,$tphExtendedRequesterSupported,$tphStTableLocationName,$tphStTableEntryCount,$tphControl,$tphCapability)) } else { [void]$parts.Add('TPH=n/a') }
    if ($doePresent) { [void]$parts.Add(('DOE count={0} irqCap={1} irqAny={2} irqAll={3} ready={4} busy={5} err={6}' -f $doeStructures.Count,$doeInterruptCapable,$doeAnyInterruptEnabled,$doeAllInterruptsEnabled,$doeReadyCount,$doeBusyCount,$doeErrorCount)) } else { [void]$parts.Add('DOE=n/a') }
    if ($idePresent) { [void]$parts.Add(('IDE@0x{0:X3} len={1} readLen={2} truncated={3} cap=0x{4:X8} ctrl=0x{5:X8} link={6} sel={7}/streams={8} flowCap={9} flowEn={10} phe={11} pcrc={12} raw=[{13}]' -f $ideOffset,$ideLengthBytes,$ideRawReadLengthBytes,$ideRawReadTruncated,$ideCapability,$ideControl,$ideLinkSupported,$ideSelectiveSupported,$ideSelectiveStreamCount,$ideFlowThroughSupported,$ideFlowThroughEnabled,$idePartialHeaderEncryptionSupported,$idePcrcSupported,(Format-PciDwordArrayText -Values $ideRawDwords.ToArray()))) } else { [void]$parts.Add('IDE=n/a') }
    if ($dvsecPresent) {
        $dvsecNames = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($dvsecStructures.ToArray())) { [void]$dvsecNames.Add(('@0x{0:X3}:VID=0x{1:X4}:ID=0x{2:X4}:REV={3}:LEN={4}' -f [int]$entry.Offset,[uint16]$entry.VendorId,[uint16]$entry.DvsecId,[int]$entry.Revision,[int]$entry.LengthBytes)) }
        [void]$parts.Add(('DVSEC count={0} {1}' -f $dvsecStructures.Count,($dvsecNames -join ',')))
    } else { [void]$parts.Add('DVSEC=n/a') }
    if ($vsecPresent) {
        $vsecNames = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($vsecStructures.ToArray())) { [void]$vsecNames.Add(('@0x{0:X3}:ID=0x{1:X4}:REV={2}:LEN={3}' -f [int]$entry.Offset,[uint16]$entry.VendorSpecificId,[int]$entry.Revision,[int]$entry.LengthBytes)) }
        [void]$parts.Add(('VSEC count={0} {1}' -f $vsecStructures.Count,($vsecNames -join ',')))
    } else { [void]$parts.Add('VSEC=n/a') }
    if ($vndrPresent) {
        $vndrNames = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($vndrStructures.ToArray())) { [void]$vndrNames.Add(('@0x{0:X2}:LEN={1}:NEXT=0x{2:X2}' -f [int]$entry.Offset,[int]$entry.LengthBytes,[int]$entry.NextOffset)) }
        [void]$parts.Add(('VNDR(conv) count={0} {1}' -f $vndrStructures.Count,($vndrNames -join ',')))
    } else { [void]$parts.Add('VNDR(conv)=n/a') }
    if ($vcPresent) { [void]$parts.Add(('VC/TC structures={0} resources={1} enabled={2} allEnabled={3} TC=0x{4:X2}({5}) TCext={6}' -f $vcStructures.Count,$vcResources.Count,$vcEnabled,$vcAllResourcesEnabled,$vcTrafficClassMap,$tcNames,$tcExtendedClassesEnabled)) } else { [void]$parts.Add('VC/TC=n/a') }

    return [pscustomobject]@{
        Bdf = $bdf
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        MsiPresent = $msiPresent
        MsiCount = [int]$msiStructures.Count
        MsiStructuresRaw = [object[]]$msiStructures.ToArray()
        MsiEnabled = [bool]$msiEnabled
        MsiVectorUsedCount = [int]$msiVectorUsedTotal
        MsiVectorPossibleCount = [int]$msiVectorPossibleTotal
        MsiVectorCountText = ('{0}/{1}' -f [int]$msiVectorUsedTotal,[int]$msiVectorPossibleTotal)
        MsiFirstControlRaw = if ($msiStructures.Count -gt 0) { [uint16]$msiStructures[0].ControlRaw } else { [uint16]0 }
        MsixPresent = $msixPresent
        MsixCount = [int]$msixStructures.Count
        MsixStructuresRaw = [object[]]$msixStructures.ToArray()
        MsixEnabled = [bool]$msixEnabled
        MsixFunctionMasked = [bool]$msixFunctionMasked
        MsixVectorUsedCount = [int]$msixVectorUsedTotal
        MsixVectorPossibleCount = [int]$msixVectorPossibleTotal
        MsixVectorCountKnown = [bool]$msixVectorCountsKnown
        MsixVectorCountText = if ($msixVectorCountsKnown) { ('{0}/{1}' -f [int]$msixVectorUsedTotal,[int]$msixVectorPossibleTotal) } else { ('?/{0}' -f [int]$msixVectorPossibleTotal) }
        MsixVectorCountErrors = [string[]]$msixVectorCountErrors.ToArray()
        MsixFirstControlRaw = if ($msixStructures.Count -gt 0) { [uint16]$msixStructures[0].ControlRaw } else { [uint16]0 }
        AerPresent = $aerPresent
        AerOffset = $aerOffset
        AerVersion = if ($aerPresent) { [int]$aer.Version } else { 0 }
        AerUncorrectableStatusRaw = $aerUncorrStatus
        AerUncorrectableMaskRaw = $aerUncorrMask
        AerUncorrectableSeverityRaw = $aerUncorrSeverity
        AerCorrectableStatusRaw = $aerCorrStatus
        AerCorrectableMaskRaw = $aerCorrMask
        AerCapabilityControlRaw = $aerCapControl
        AerRootFieldsAvailable = $aerRootFieldsAvailable
        AerRootCommandRaw = $aerRootCommand
        AerRootStatusRaw = $aerRootStatus
        AerRootErrorSourceRaw = $aerRootErrorSource
        AerHeaderLogRaw = [uint32[]]$aerHeaderLog.ToArray()
        AerPrefixLogPresent = $aerPrefixLogPresent
        AerPrefixLogRaw = [uint32[]]$aerPrefixLog.ToArray()
        AerEcrcGenerationCapable = $aerEcrcGenCap
        AerEcrcGenerationEnabled = $aerEcrcGenEn
        AerEcrcCheckCapable = $aerEcrcChkCap
        AerEcrcCheckEnabled = $aerEcrcChkEn
        DpcPresent = $dpcPresent
        DpcOffset = $dpcOffset
        DpcVersion = if ($dpcPresent) { [int]$dpc.Version } else { 0 }
        DpcCapabilityRaw = $dpcCapability
        DpcControlRaw = $dpcControl
        DpcStatusRaw = $dpcStatus
        DpcSourceIdRaw = $dpcSourceId
        DpcInterruptMessageNumber = if ($dpcPresent) { [int]([uint32]$dpcCapability -band [uint32]0x001F) } else { 0 }
        DpcRootPortExtensions = $dpcRootPortExtensions
        DpcPoisonedTlpEgressBlockingCapable = $dpcPoisonedTlpEgressBlockingCapable
        DpcSoftwareTriggerCapable = $dpcSwTriggerCapable
        DpcDlActiveErrCorCapable = $dpcDlActiveCapable
        DpcRpPioLogSize = $dpcPioLogSize
        DpcFatalEnable = if ($dpcPresent) { (($dpcControl -band [uint16]0x0001) -ne 0) } else { $false }
        DpcNonFatalEnable = if ($dpcPresent) { (($dpcControl -band [uint16]0x0002) -ne 0) } else { $false }
        DpcInterruptEnable = if ($dpcPresent) { (($dpcControl -band [uint16]0x0008) -ne 0) } else { $false }
        DpcPioStatusRaw = $dpcPioStatus
        DpcPioMaskRaw = $dpcPioMask
        DpcPioSeverityRaw = $dpcPioSeverity
        DpcPioSysErrorRaw = $dpcPioSysError
        DpcPioExceptionRaw = $dpcPioException
        AcsPresent = $acsPresent
        AcsOffset = $acsOffset
        AcsVersion = if ($acsPresent) { [int]$acs.Version } else { 0 }
        AcsCapabilityRaw = $acsCapability
        AcsControlRaw = $acsControl
        AcsSupportedMask = $acsSupported
        AcsEnabledMask = $acsEnabled
        AcsSupportedNames = (ConvertTo-PciFeatureMaskNames -Mask $acsSupported -Definitions $acsDefinitions)
        AcsEnabledNames = (ConvertTo-PciFeatureMaskNames -Mask $acsEnabled -Definitions $acsDefinitions)
        AcsEgressControlVectorSizeBits = $acsEgressVectorSize
        AcsEgressControlDwordCount = $acsEgressDwordCount
        AcsEgressControlVectorRaw = [uint32[]]$acsEgressVector.ToArray()
        AcsAllSupportedEnabled = ($acsPresent -and ([uint16]$acsSupported -ne 0) -and ([uint16]$acsEnabled -eq [uint16]$acsSupported))
        AtsPresent = $atsPresent
        AtsOffset = $atsOffset
        AtsVersion = if ($atsPresent) { [int]$ats.Version } else { 0 }
        AtsCapabilityRaw = $atsCapability
        AtsControlRaw = $atsControl
        AtsEnabled = $atsEnabled
        AtsQueueDepth = $atsQueueDepth
        AtsPageAlignedRequest = $atsPageAlignedRequest
        AtsSmallestTranslationUnitEncoded = $atsStuEncoded
        AtsSmallestTranslationUnitShift = $atsStuShift
        PriPresent = $priPresent
        PriOffset = $priOffset
        PriVersion = if ($priPresent) { [int]$pri.Version } else { 0 }
        PriControlRaw = $priControl
        PriStatusRaw = $priStatus
        PriEnabled = $priEnabled
        PriReset = $priReset
        PriResponseFailure = $priResponseFailure
        PriUnexpectedPrgIndex = $priUnexpectedPrgIndex
        PriStopped = $priStopped
        PriPasidRequired = $priPasidRequired
        PriMaxRequests = $priMaxRequests
        PriAllocatedRequests = $priAllocatedRequests
        PasidPresent = $pasidPresent
        PasidOffset = $pasidOffset
        PasidVersion = if ($pasidPresent) { [int]$pasid.Version } else { 0 }
        PasidCapabilityRaw = $pasidCapability
        PasidControlRaw = $pasidControl
        PasidEnabled = $pasidEnabled
        PasidExecSupported = $pasidExecSupported
        PasidPrivSupported = $pasidPrivSupported
        PasidExecEnabled = $pasidExecEnabled
        PasidPrivEnabled = $pasidPrivEnabled
        PasidWidth = $pasidWidth
        PasidMaxPasids = $pasidMaxPasids
        PtmPresent = $ptmPresent
        PtmOffset = $ptmOffset
        PtmVersion = if ($ptmPresent) { [int]$ptm.Version } else { 0 }
        PtmCapabilityRaw = $ptmCapability
        PtmControlRaw = $ptmControl
        PtmRequesterCapable = $ptmRequesterCapable
        PtmResponderCapable = $ptmResponderCapable
        PtmRootCapable = $ptmRootCapable
        PtmClockGranularityRaw = $ptmClockGranularityRaw
        PtmEnabled = $ptmEnabled
        PtmRootSelected = $ptmRootSelected
        LmrPresent = $lmrPresent
        LmrOffset = $lmrOffset
        LmrDecodeError = $lmrDecodeError
        LaneMarginingState = $lmrState
        LmrReady = if ($null -ne $lmrState) { [bool]$lmrState.Ready } else { $false }
        LmrSoftwareReady = if ($null -ne $lmrState) { [bool]$lmrState.SoftwareReady } else { $false }
        LmrSupportedAtCurrentSpeed = if ($null -ne $lmrState) { [bool]$lmrState.SupportedAtCurrentSpeed } else { $false }
        LmrPortStatusRaw = if ($null -ne $lmrState) { [uint16]$lmrState.PortStatusRaw } else { [uint16]0 }
        LmrCapabilityRaw = if ($null -ne $lmrState) { [uint16]$lmrState.CapabilityRaw } else { [uint16]0 }
        LmrUsesDriverSoftware = if ($null -ne $lmrState) { [bool]$lmrState.UsesDriverSoftware } else { $false }
        LmrLaneCountDecoded = if ($null -ne $lmrState) { [int]$lmrState.LaneCountDecoded } else { 0 }
        LmrMarginErrorLaneCount = if ($null -ne $lmrState) { [int]$lmrState.MarginErrorLaneCount } else { 0 }
        LmrHardwareAutonomousWidthDisable = if ($null -ne $lmrState) { [bool]$lmrState.HardwareAutonomousWidthDisable } else { $false }
        LmrHardwareAutonomousSpeedDisable = if ($null -ne $lmrState) { [bool]$lmrState.HardwareAutonomousSpeedDisable } else { $false }
        PciSecondaryExpressPresent = [bool]($null -ne $secondaryPci)
        PciSecondaryExpressState = $secondaryPciState
        PciSecondaryExpressDecodeError = $secondaryPciDecodeError
        PciSecondaryLaneEqualizationFailureCount = if ($null -ne $secondaryPciState) { [int]$secondaryPciState.LaneEqualizationFailureCount } else { 0 }
        PciSecondaryLaneEqualizationFailedLanes = if ($null -ne $secondaryPciState) { [int[]]$secondaryPciState.LaneEqualizationFailedLanes } else { [int[]]@() }
        PciSecondaryLaneEqualizationControls = if ($null -ne $secondaryPciState) { [object[]]$secondaryPciState.LaneEqualizationControls } else { [object[]]@() }
        PciPhysicalLayerPresent = [bool]$physicalLayerPresent
        PciPhysicalLayerCount = [int]$physicalLayerStates.Count
        PciPhysicalLayerStates = [object[]]$physicalLayerStates.ToArray()
        PciPhysicalLayerDecodeErrors = [string[]]$physicalLayerDecodeErrors.ToArray()
        PciPhysicalLayer16Present = [bool](@($physicalLayerStates.ToArray()) | Where-Object { [int]$_.CapabilityId -eq 0x0026 } | Select-Object -First 1)
        PciPhysicalLayer32Present = [bool](@($physicalLayerStates.ToArray()) | Where-Object { [int]$_.CapabilityId -eq 0x002A } | Select-Object -First 1)
        PciPhysicalLayer64Present = [bool](@($physicalLayerStates.ToArray()) | Where-Object { [int]$_.CapabilityId -eq 0x0031 } | Select-Object -First 1)
        PciFlitExtendedCapabilityCount = [int]$flitExtendedCaps.Count
        PciFlitExtendedCapabilityNames = [string[]]$flitExtendedCapabilityNames.ToArray()
        PciExpressCapabilityFlagsRaw = [uint16]$pcieCapabilityFlagsRaw
        PciFlitModeSupported = [bool]$pcieFlitModeSupported
        PciFlitModeDisabled = [bool]$pcieFlitModeDisabled
        PciFlitModeActive = [bool]$pcieFlitModeActive
        PciFlitModeSummary = [string]$pcieFlitModeSummary
        PciLink2PhysicalIndicatorsAvailable = [bool]$pcieLink2Available
        PciLinkPhyDecodeError = $pciePhyIndicatorError
        PciLinkRetimerSupported = [bool]$pcieRetimerSupported
        PciLinkTwoRetimersSupported = [bool]$pcieTwoRetimersSupported
        PciLinkRetimerDetected = [bool]$pcieRetimerDetected
        PciLinkTwoRetimersDetected = [bool]$pcieTwoRetimersDetected
        PciLinkRetimerSummary = [string]$pcieRetimerSummary
        PciLinkEqualizationComplete = [bool]$pcieLinkEqualizationComplete
        PciLinkEqualizationPhase1Successful = [bool]$pcieLinkEqualizationPhase1
        PciLinkEqualizationPhase2Successful = [bool]$pcieLinkEqualizationPhase2
        PciLinkEqualizationPhase3Successful = [bool]$pcieLinkEqualizationPhase3
        PciLinkEqualizationRequest = [bool]$pcieLinkEqualizationRequest
        PciLinkEqualizationIncompletePhaseCount = [int]$pcieLinkEqualizationIncompletePhaseCount
        PciLinkEqualizationStatusText = [string]$pcieLinkEqualizationStatusText
        PciLinkTransmitMarginCode = [int]$pcieLinkTransmitMarginCode
        PciLinkCompliancePresetDeemphasis = [int]$pcieLinkCompliancePresetDeemphasis
        PciLinkCurrentDeemphasis = [int]$pcieLinkCurrentDeemphasis
        PciLinkCapabilities2RawForPhysicalLayer = [uint32]$pcieLinkCapabilities2Raw
        PciLinkControl2RawForPhysicalLayer = [uint16]$pcieLinkControl2Raw
        PciLinkStatus2RawForPhysicalLayer = [uint16]$pcieLinkStatus2Raw
        TphPresent = $tphPresent
        TphOffset = $tphOffset
        TphVersion = if ($tphPresent) { [int]$tph.Version } else { 0 }
        TphRequesterCapabilityRaw = $tphCapability
        TphRequesterControlRaw = $tphControl
        TphNoStModeSupported = $tphNoStModeSupported
        TphInterruptVectorModeSupported = $tphInterruptVectorModeSupported
        TphDeviceSpecificModeSupported = $tphDeviceSpecificModeSupported
        TphExtendedRequesterSupported = $tphExtendedRequesterSupported
        TphStTableLocation = $tphStTableLocation
        TphStTableLocationName = $tphStTableLocationName
        TphStTableSizeEncoded = $tphStTableSizeEncoded
        TphStTableEntryCount = $tphStTableEntryCount
        TphModeSelect = $tphModeSelect
        TphModeName = $tphModeName
        TphRequesterEnableRaw = $tphRequesterEnableRaw
        TphRequesterEnableName = $tphRequesterEnableName
        TphEnabled = $tphEnabled
        TphSteeringTagsRaw = [uint32[]]$tphSteeringTags.ToArray()
        TphSteeringTagsFullyRead = $tphSteeringTagsFullyRead
        DoePresent = $doePresent
        DoeCount = [int]$doeStructures.Count
        DoeStructuresRaw = [object[]]$doeStructures.ToArray()
        DoeInterruptCapable = $doeInterruptCapable
        DoeAnyInterruptEnabled = $doeAnyInterruptEnabled
        DoeAllInterruptsEnabled = $doeAllInterruptsEnabled
        DoeReadyCount = [int]$doeReadyCount
        DoeBusyCount = [int]$doeBusyCount
        DoeErrorCount = [int]$doeErrorCount
        IdePresent = $idePresent
        IdeOffset = $ideOffset
        IdeVersion = if ($idePresent) { [int]$ide.Version } else { 0 }
        IdeLengthBytes = [int]$ideLengthBytes
        IdeCapabilityRaw = [uint32]$ideCapability
        IdeControlRaw = [uint32]$ideControl
        IdeRawDwords = [uint32[]]$ideRawDwords.ToArray()
        IdeRawReadLengthBytes = [int]$ideRawReadLengthBytes
        IdeRawReadTruncated = [bool]$ideRawReadTruncated
        IdeLinkSupported = $ideLinkSupported
        IdeSelectiveSupported = $ideSelectiveSupported
        IdeSelectiveStreamCountEncoded = [int]$ideSelectiveStreamCountEncoded
        IdeSelectiveStreamCount = [int]$ideSelectiveStreamCount
        IdeFlowThroughSupported = $ideFlowThroughSupported
        IdeFlowThroughEnabled = $ideFlowThroughEnabled
        IdePartialHeaderEncryptionSupported = $idePartialHeaderEncryptionSupported
        IdePcrcSupported = $idePcrcSupported
        DvsecPresent = $dvsecPresent
        DvsecCount = [int]$dvsecStructures.Count
        DvsecStructuresRaw = [object[]]$dvsecStructures.ToArray()
        VsecPresent = $vsecPresent
        VsecCount = [int]$vsecStructures.Count
        VsecStructuresRaw = [object[]]$vsecStructures.ToArray()
        VndrPresent = $vndrPresent
        VndrCount = [int]$vndrStructures.Count
        VndrStructuresRaw = [object[]]$vndrStructures.ToArray()
        VcPresent = $vcPresent
        VcStructureCount = $vcStructures.Count
        VcResourceCount = $vcResources.Count
        VcStructuresRaw = [object[]]$vcStructures.ToArray()
        VcResourcesRaw = [object[]]$vcResources.ToArray()
        VcEnabled = $vcEnabled
        VcAllResourcesEnabled = $vcAllResourcesEnabled
        TcTrafficClassMask = [uint16]$vcTrafficClassMap
        TcTrafficClassNames = $tcNames
        TcExtendedClassesEnabled = $tcExtendedClassesEnabled
        DisplayText = ($parts -join ' | ')
    }
}

