    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [AllowNull()][object]$AerEcrcGenerationEnable = $null,
        [AllowNull()][object]$AerEcrcCheckEnable = $null,
        [AllowNull()][object]$DpcFatalEnable = $null,
        [AllowNull()][object]$DpcNonFatalEnable = $null,
        [AllowNull()][object]$DpcInterruptEnable = $null,
        [AllowNull()][object]$MsiEnable = $null,
