        [AllowNull()][object]$MsixEnable = $null,
        [AllowNull()][object]$MsixFunctionMask = $null,
        [AllowNull()][object]$MsixControlMask = $null,
        [AllowNull()][object]$MsixControlValue = $null,
        [AllowNull()][object]$MsixRawDwords = $null,
        [ValidateRange(0,63)][int]$MsixRawDwordStartIndex = 1,
        [ValidateRange(0,255)][int]$MsixCapabilityIndex = 0,
        [AllowNull()][object]$MsixTableRawDwords = $null,
        [ValidateRange(0,1048575)][int]$MsixTableRawDwordStartIndex = 0,
        [ValidateRange(0,255)][int]$MsixTableCapabilityIndex = 0,
        [AllowNull()][object]$MsixTableVectorMask = $null,
        [ValidateRange(0,2047)][int]$MsixTableVectorMaskStartIndex = 0,
        [AllowNull()][object]$AcsEnable = $null,
        [AllowNull()][object]$AtsEnable = $null,
        [AllowNull()][object]$PriEnable = $null,
        [AllowNull()][object]$PasidEnable = $null,
        [AllowNull()][object]$PasidExecEnable = $null,
        [AllowNull()][object]$PasidPrivEnable = $null,
        [AllowNull()][object]$AtsSmallestTranslationUnitShift = $null,
