        [AllowNull()][object]$AerCorrectableMask = $null,
        [AllowNull()][object]$AerRootCommand = $null,
        [AllowNull()][object]$AerUncorrectableStatusClearMask = $null,
        [AllowNull()][object]$AerCorrectableStatusClearMask = $null,
        [AllowNull()][object]$AerRootStatusClearMask = $null,
        [AllowNull()][object]$DpcControlMask = $null,
        [AllowNull()][object]$DpcStatusClearMask = $null,
        [AllowNull()][object]$DpcPioStatusClearMask = $null,
        [AllowNull()][object]$DpcPioMask = $null,
        [AllowNull()][object]$DpcPioSeverity = $null,
        [AllowNull()][object]$DpcPioSysError = $null,
        [AllowNull()][object]$DpcPioException = $null,
        [AllowNull()][object]$AcsControlMask = $null,
        [AllowNull()][object]$AcsControlEnableMask = $null,
        [AllowNull()][object]$AcsControlDisableMask = $null,
        [AllowNull()][object]$AcsEgressControlVector = $null,
        [AllowNull()][object]$PtmEnable = $null,
        [AllowNull()][object]$PtmRootSelect = $null,
        [AllowNull()][object]$TphEnable = $null,
        [AllowNull()][object]$TphMode = $null,
        [AllowNull()][object]$TphRequesterEnable = $null,
        [AllowNull()][object]$TphSteeringTagVector = $null,
        [AllowNull()][object]$VcEnable = $null,
        [AllowNull()][object]$TcEnable = $null,
        [AllowNull()][object]$VcTrafficClassMap = $null,
        [AllowNull()][object]$VcStructureIndex = $null,
        [AllowNull()][object]$VcResourceIndex = $null,
        [AllowNull()][object]$VcLoadTable = $null,
        [AllowNull()][object]$VcControlEnableMask = $null,
        [AllowNull()][object]$VcControlDisableMask = $null,
        [AllowNull()][object]$DoeInterruptEnable = $null,
        [AllowNull()][object]$DoeControlMask = $null,
        [AllowNull()][object]$DoeControlValue = $null,
        [AllowNull()][object]$DoeRawDwords = $null,
        [ValidateRange(0,255)][int]$DoeRawDwordStartIndex = 4,
        [ValidateRange(0,255)][int]$DoeCapabilityIndex = 0,
        [AllowNull()][object]$IdeRawDwords = $null,
        [ValidateRange(0,255)][int]$IdeRawDwordStartIndex = 2,
        [ValidateRange(0,255)][int]$IdeCapabilityIndex = 0,
        [AllowNull()][object]$PhysicalLayerRawDwords = $null,
        [ValidateRange(0,255)][int]$PhysicalLayerRawDwordStartIndex = 1,
        [AllowNull()][object]$PhysicalLayerRawCapability = '32GT',
        [ValidateRange(0,255)][int]$PhysicalLayerCapabilityIndex = 0,
        [AllowNull()][object]$PhysicalLayerLaneEqualizationPresetBytes = $null,
        [ValidateRange(0,31)][int]$PhysicalLayerLaneEqualizationPresetStartLane = 0,
        [AllowNull()][object]$DvsecRawDwords = $null,
        [ValidateRange(0,255)][int]$DvsecRawDwordStartIndex = 3,
