    if (Test-DeviceTweakerNullableValueSpecified $DpcNonFatalEnable) { if ([bool]$after.DpcNonFatalEnable -ne [bool]$DpcNonFatalEnable) { [void]$fail.Add(('DPC nonfatal expected {0}, readback {1}' -f [bool]$DpcNonFatalEnable,[bool]$after.DpcNonFatalEnable)) } }
    if (Test-DeviceTweakerNullableValueSpecified $DpcInterruptEnable) { if ([bool]$after.DpcInterruptEnable -ne [bool]$DpcInterruptEnable) { [void]$fail.Add(('DPC interrupt expected {0}, readback {1}' -f [bool]$DpcInterruptEnable,[bool]$after.DpcInterruptEnable)) } }
    if ($null -ne $requestedDpcSafeCompare) { if (([uint16]$after.DpcControlRaw -band [uint16]0x000B) -ne [uint16]$requestedDpcSafeCompare) { [void]$fail.Add(('DPC control safe bits expected 0x{0:X4}, readback 0x{1:X4}' -f [uint16]$requestedDpcSafeCompare,([uint16]$after.DpcControlRaw -band [uint16]0x000B))) } }
    if (Test-DeviceTweakerNullableValueSpecified $DpcPioMask) { if ([uint32]$after.DpcPioMaskRaw -ne [uint32]$DpcPioMask) { [void]$fail.Add(('DPC PIO mask expected 0x{0:X8}, readback 0x{1:X8}' -f [uint32]$DpcPioMask,[uint32]$after.DpcPioMaskRaw)) } }
    if (Test-DeviceTweakerNullableValueSpecified $DpcPioSeverity) { if ([uint32]$after.DpcPioSeverityRaw -ne [uint32]$DpcPioSeverity) { [void]$fail.Add(('DPC PIO severity expected 0x{0:X8}, readback 0x{1:X8}' -f [uint32]$DpcPioSeverity,[uint32]$after.DpcPioSeverityRaw)) } }
    if (Test-DeviceTweakerNullableValueSpecified $DpcPioSysError) { if ([uint32]$after.DpcPioSysErrorRaw -ne [uint32]$DpcPioSysError) { [void]$fail.Add(('DPC PIO syserror expected 0x{0:X8}, readback 0x{1:X8}' -f [uint32]$DpcPioSysError,[uint32]$after.DpcPioSysErrorRaw)) } }
    if (Test-DeviceTweakerNullableValueSpecified $DpcPioException) { if ([uint32]$after.DpcPioExceptionRaw -ne [uint32]$DpcPioException) { [void]$fail.Add(('DPC PIO exception expected 0x{0:X8}, readback 0x{1:X8}' -f [uint32]$DpcPioException,[uint32]$after.DpcPioExceptionRaw)) } }
    if ($null -ne $requestedAcsSupportedCompare) { if ([uint16]$after.AcsEnabledMask -ne [uint16]$requestedAcsSupportedCompare) { [void]$fail.Add(('ACS supported control expected 0x{0:X4}, readback 0x{1:X4}, supported=0x{2:X4}' -f [uint16]$requestedAcsSupportedCompare,[uint16]$after.AcsEnabledMask,[uint16]$after.AcsSupportedMask)) } }
    if ($null -ne $requestedAcsEgress) {
        $readback = [uint32[]]$after.AcsEgressControlVectorRaw
        for ($i = 0; $i -lt $requestedAcsEgress.Count; $i++) {
            $actualAcsEgressText = '<missing>'
            if ($i -lt $readback.Count) { $actualAcsEgressText = ('0x{0:X8}' -f [uint32]$readback[$i]) }
            if ($i -ge $readback.Count -or [uint32]$readback[$i] -ne [uint32]$requestedAcsEgress[$i]) { [void]$fail.Add(('ACS egress vector[{0}] expected 0x{1:X8}, readback {2}' -f $i,[uint32]$requestedAcsEgress[$i],$actualAcsEgressText)) }
        }
    }
    if ($null -ne $requestedAtsControlCompare) { if (([uint16]$after.AtsControlRaw -band [uint16]0x801F) -ne [uint16]$requestedAtsControlCompare) { [void]$fail.Add(('ATS control expected 0x{0:X4}, readback 0x{1:X4}' -f [uint16]$requestedAtsControlCompare,([uint16]$after.AtsControlRaw -band [uint16]0x801F))) } }
    if ($null -ne $requestedPriEnableCompare) { if ([bool]$after.PriEnabled -ne [bool]$requestedPriEnableCompare) { [void]$fail.Add(('PRI enable expected {0}, readback {1}' -f [bool]$requestedPriEnableCompare,[bool]$after.PriEnabled)) } }
    if ($null -ne $requestedPriAllocatedCompare) { if ([uint32]$after.PriAllocatedRequests -ne [uint32]$requestedPriAllocatedCompare) { [void]$fail.Add(('PRI allocated requests expected {0}, readback {1}' -f [uint32]$requestedPriAllocatedCompare,[uint32]$after.PriAllocatedRequests)) } }
    if ($null -ne $requestedPasidControlCompare) { if (([uint16]$after.PasidControlRaw -band [uint16]0x0007) -ne [uint16]$requestedPasidControlCompare) { [void]$fail.Add(('PASID control expected 0x{0:X4}, readback 0x{1:X4}' -f [uint16]$requestedPasidControlCompare,([uint16]$after.PasidControlRaw -band [uint16]0x0007))) } }
    if ($null -ne $requestedPtmControlCompare) { if (([uint32]$after.PtmControlRaw -band [uint32]$requestedPtmControlCompare.Mask) -ne [uint32]$requestedPtmControlCompare.Value) { [void]$fail.Add(('PTM control expected masked 0x{0:X8}/0x{1:X8}, readback 0x{2:X8}' -f [uint32]$requestedPtmControlCompare.Value,[uint32]$requestedPtmControlCompare.Mask,([uint32]$after.PtmControlRaw -band [uint32]$requestedPtmControlCompare.Mask))) } }
    if ($null -ne $requestedTphControlCompare) { if (([uint32]$after.TphRequesterControlRaw -band [uint32]$requestedTphControlCompare.Mask) -ne [uint32]$requestedTphControlCompare.Value) { [void]$fail.Add(('TPH control expected masked 0x{0:X8}/0x{1:X8}, readback 0x{2:X8}' -f [uint32]$requestedTphControlCompare.Value,[uint32]$requestedTphControlCompare.Mask,([uint32]$after.TphRequesterControlRaw -band [uint32]$requestedTphControlCompare.Mask))) } }
    if ($null -ne $requestedTphSteeringTags) {
        $readbackTphTags = [uint32[]]$after.TphSteeringTagsRaw
        for ($i = 0; $i -lt $requestedTphSteeringTags.Count; $i++) {
            $actualTphTagText = '<missing>'
            if ($i -lt $readbackTphTags.Count) { $actualTphTagText = ('0x{0:X4}' -f [uint32]$readbackTphTags[$i]) }
            if ($i -ge $readbackTphTags.Count -or [uint32]$readbackTphTags[$i] -ne [uint32]$requestedTphSteeringTags[$i]) { [void]$fail.Add(('TPH ST[{0}] expected 0x{1:X4}, readback {2}' -f $i,[uint32]$requestedTphSteeringTags[$i],$actualTphTagText)) }
        }
    }

    if ($null -ne $requestedDoeInterruptEnable) {
        foreach ($doeEntry in @($after.DoeStructuresRaw)) {
            if ([bool]$doeEntry.InterruptSupported -and [bool]$doeEntry.InterruptEnabled -ne [bool]$requestedDoeInterruptEnable) { [void]$fail.Add(('DOE interrupt enable index {0} expected {1}, readback {2}' -f [int]$doeEntry.Index,[bool]$requestedDoeInterruptEnable,[bool]$doeEntry.InterruptEnabled)) }
        }
    }
    if ($null -ne $requestedDoeControlCompare) {
        $actualDoeControl = $null
        foreach ($candidateDoe in @($after.DoeStructuresRaw)) { if ([int]$candidateDoe.Index -eq [int]$requestedDoeControlCompare.Index) { $actualDoeControl = $candidateDoe; break } }
        if ($null -eq $actualDoeControl) { [void]$fail.Add(('DOE capability index {0} missing after control write' -f [int]$requestedDoeControlCompare.Index)) }
        elseif (([uint32]$actualDoeControl.ControlRaw -band [uint32]$requestedDoeControlCompare.Mask) -ne [uint32]$requestedDoeControlCompare.Value) { [void]$fail.Add(('DOE control index {0} expected masked 0x{1:X8}/0x{2:X8}, readback 0x{3:X8}' -f [int]$requestedDoeControlCompare.Index,[uint32]$requestedDoeControlCompare.Value,[uint32]$requestedDoeControlCompare.Mask,([uint32]$actualDoeControl.ControlRaw -band [uint32]$requestedDoeControlCompare.Mask))) }
    }
    if ($requestedVcControls.Count -gt 0) {
        foreach ($expectedVc in @($requestedVcControls.ToArray())) {
            $actualVc = $null
            foreach ($candidateVc in @($after.VcResourcesRaw)) { if ([int]$candidateVc.StructureIndex -eq [int]$expectedVc.StructureIndex -and [int]$candidateVc.ResourceIndex -eq [int]$expectedVc.ResourceIndex) { $actualVc = $candidateVc; break } }
            if ($null -eq $actualVc) { [void]$fail.Add(('VC resource S{0}/R{1} missing after write' -f [int]$expectedVc.StructureIndex,[int]$expectedVc.ResourceIndex)); continue }
            if (([uint32]$actualVc.ControlRaw -band [uint32]$expectedVc.Mask) -ne [uint32]$expectedVc.Value) { [void]$fail.Add(('VC resource S{0}/R{1} control expected masked 0x{2:X8}/0x{3:X8}, readback 0x{4:X8}' -f [int]$expectedVc.StructureIndex,[int]$expectedVc.ResourceIndex,[uint32]$expectedVc.Value,[uint32]$expectedVc.Mask,([uint32]$actualVc.ControlRaw -band [uint32]$expectedVc.Mask))) }
        }
    }
    if ($requestedVcPortControls.Count -gt 0) {
        foreach ($expectedVcPort in @($requestedVcPortControls.ToArray())) {
            $actualVcPort = $null
            foreach ($candidateVcPort in @($after.VcStructuresRaw)) { if ([int]$candidateVcPort.StructureIndex -eq [int]$expectedVcPort.StructureIndex) { $actualVcPort = $candidateVcPort; break } }
            if ($null -eq $actualVcPort) { [void]$fail.Add(('VC structure S{0} missing after port-control write' -f [int]$expectedVcPort.StructureIndex)); continue }
            if (([uint16]$actualVcPort.PortControlRaw -band [uint16]$expectedVcPort.Mask) -ne [uint16]$expectedVcPort.Value) { [void]$fail.Add(('VC structure S{0} port control expected masked 0x{1:X4}/0x{2:X4}, readback 0x{3:X4}' -f [int]$expectedVcPort.StructureIndex,[uint16]$expectedVcPort.Value,[uint16]$expectedVcPort.Mask,([uint16]$actualVcPort.PortControlRaw -band [uint16]$expectedVcPort.Mask))) }
        }
    }
    if ($fail.Count -gt 0) { throw ('MSI/MSI-X/AER/DPC/ACS/ATS/PRI/PASID/PTM/LMR/TPH/DOE/IDE/DVSEC/VSEC/VNDR/VC/TC verify failed on {0}: {1}. Before: {2}. After: {3}' -f $bdf, ($fail -join '; '), [string]$before.DisplayText, [string]$after.DisplayText) }
    return $after
}


function Find-PciDownstreamChildFunction {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    if (-not (Test-PciBridgeFunction -Segment $Segment -Bus $Bus -Device $Device -Function $Function)) {
        throw ('PCIe link resolve failed: {0} is not a PCI-to-PCI bridge/downstream port.' -f ([DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)))
    }
    $bridge = Get-PciBridgeBusNumbers -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ($bridge.Secondary -lt 0 -or $bridge.Secondary -gt 255 -or $bridge.Subordinate -lt $bridge.Secondary) {
        throw ('PCIe link resolve failed: bridge {0} has invalid bus numbers primary={1} secondary={2} subordinate={3}.' -f ([DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function), [int]$bridge.Primary, [int]$bridge.Secondary, [int]$bridge.Subordinate))
    }

    $firstPcie = $null
    for ($dev = 0; $dev -le 31; $dev++) {
        if (-not (Test-PciFunctionPresent -Segment $Segment -Bus ([int]$bridge.Secondary) -Device $dev -Function 0)) { continue }
        $header0 = 0
        try { $header0 = Get-PciHeaderType -Segment $Segment -Bus ([int]$bridge.Secondary) -Device $dev -Function 0 } catch { continue }
        $maxFunction = if (($header0 -band 0x80) -ne 0) { 7 } else { 0 }
        for ($fn = 0; $fn -le $maxFunction; $fn++) {
            if ($fn -ne 0 -and -not (Test-PciFunctionPresent -Segment $Segment -Bus ([int]$bridge.Secondary) -Device $dev -Function $fn)) { continue }
            try { [void](Get-PciExpressCapabilityContext -Segment $Segment -Bus ([int]$bridge.Secondary) -Device $dev -Function $fn) } catch { continue }
            $candidate = [pscustomobject]@{ Segment = $Segment; Bus = [int]$bridge.Secondary; Device = $dev; Function = $fn; Bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,[int]$bridge.Secondary,$dev,$fn) }
            if ($null -eq $firstPcie) { $firstPcie = $candidate }
            if (Test-PciExtendedCapabilityPresent -Segment $Segment -Bus ([int]$bridge.Secondary) -Device $dev -Function $fn -CapabilityId 0x001E) { return $candidate }
        }
    }
    if ($null -ne $firstPcie) { return $firstPcie }
    throw ('PCIe link resolve failed: no PCIe child function found on secondary bus {0} behind bridge {1}.' -f [int]$bridge.Secondary, ([DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)))
}

function Find-PciParentBridge {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $targetBdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $best = $null
    $bestSpan = [int]::MaxValue
    $segments = [DeviceTweakerPciEcam]::GetMcfgSegments()
    foreach ($seg in @($segments)) {
        if ($null -eq $seg -or [int]$seg.SegmentGroup -ne $Segment) { continue }
        $startBus = [Math]::Max([int]$seg.StartBus, 0)
        $endBus = [Math]::Min([int]$seg.EndBus, [int]$Bus)
        for ($scanBus = $startBus; $scanBus -le $endBus; $scanBus++) {
            for ($dev = 0; $dev -le 31; $dev++) {
                if (-not (Test-PciFunctionPresent -Segment $Segment -Bus $scanBus -Device $dev -Function 0)) { continue }
                $header0 = 0
                try { $header0 = Get-PciHeaderType -Segment $Segment -Bus $scanBus -Device $dev -Function 0 } catch { continue }
                $maxFunction = if (($header0 -band 0x80) -ne 0) { 7 } else { 0 }
                for ($fn = 0; $fn -le $maxFunction; $fn++) {
                    if ($fn -ne 0 -and -not (Test-PciFunctionPresent -Segment $Segment -Bus $scanBus -Device $dev -Function $fn)) { continue }
                    if ($scanBus -eq $Bus -and $dev -eq $Device -and $fn -eq $Function) { continue }
                    if (-not (Test-PciBridgeFunction -Segment $Segment -Bus $scanBus -Device $dev -Function $fn)) { continue }
                    try { $busNums = Get-PciBridgeBusNumbers -Segment $Segment -Bus $scanBus -Device $dev -Function $fn } catch { continue }
                    if ([int]$busNums.Secondary -le $Bus -and $Bus -le [int]$busNums.Subordinate) {
                        $span = [int]$busNums.Subordinate - [int]$busNums.Secondary
                        if ($null -eq $best -or [int]$busNums.Secondary -eq $Bus -or $span -lt $bestSpan) {
                            $bestSpan = $span
                            $best = [pscustomobject]@{ Segment = $Segment; Bus = $scanBus; Device = $dev; Function = $fn; Bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$scanBus,$dev,$fn); Secondary = [int]$busNums.Secondary; Subordinate = [int]$busNums.Subordinate }
                            if ([int]$busNums.Secondary -eq $Bus) { return $best }
                        }
                    }
                }
            }
        }
    }
    if ($null -ne $best) { return $best }
    throw ('PCIe link resolve failed: no parent bridge found for {0}.' -f $targetBdf)
}

function Resolve-PciL1SubstateLinkContext {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $portType = -1
    try { $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch { }
    if ($portType -eq 4 -or $portType -eq 6) {
        $child = Find-PciDownstreamChildFunction -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        return [pscustomobject]@{
            Parent = [pscustomobject]@{ Segment = $Segment; Bus = $Bus; Device = $Device; Function = $Function; Bdf = $bdf }
            Child = $child
            RequestedRole = 'Parent'
            RequestedPortType = $portType
            RequestedPortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
        }
    }
    $parent = Find-PciParentBridge -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    return [pscustomobject]@{
        Parent = $parent
        Child = [pscustomobject]@{ Segment = $Segment; Bus = $Bus; Device = $Device; Function = $Function; Bdf = $bdf }
        RequestedRole = 'Child'
        RequestedPortType = $portType
        RequestedPortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
    }
}


function Get-PciL1SubstatePort {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $ctx = Get-PciExtendedCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function -CapabilityId 0x001E
    $capOff = [int]$ctx.CapabilityOffset
    $cap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOff + 0x04) -Width 32)
    $ctl1 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOff + 0x08) -Width 32)
    $ctl2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ($capOff + 0x0C) -Width 32)
    $implemented = (($cap -band 0x10) -ne 0)
    $rawSupported = [int]($cap -band 0xF)
    $supported = if ($implemented) { $rawSupported } else { 0 }
    $enabled = [int]($ctl1 -band 0xF)

    $capCommonMode = [int](($cap -shr 8) -band 0xFF)
    $capPowerScale = [int](($cap -shr 16) -band 0x3)
    $capPowerValue = [int](($cap -shr 19) -band 0x1F)
    $capPowerUs = ConvertTo-PciL1ssPowerOnUs -Scale $capPowerScale -Value $capPowerValue
    $capPowerScaleReserved = ($capPowerScale -gt 2)

    $commonMode = [int](($ctl1 -shr 8) -band 0xFF)
    $thresholdValue = [int](($ctl1 -shr 16) -band 0x3FF)
    $thresholdScale = [int](($ctl1 -shr 29) -band 0x7)
    $thresholdNs = ConvertTo-PciL1ssThresholdNs -Scale $thresholdScale -Value $thresholdValue
    $scaleReserved = ($thresholdScale -gt 5)
    $thresholdText = if ($scaleReserved) { ('reserved-scale({0}) value {1}' -f $thresholdScale, $thresholdValue) } else { Format-PciL1ssThresholdNs -Ns $thresholdNs }

    $powerScale = [int]($ctl2 -band 0x3)
    $powerValue = [int](($ctl2 -shr 3) -band 0x1F)
    $powerUs = ConvertTo-PciL1ssPowerOnUs -Scale $powerScale -Value $powerValue
    $powerScaleReserved = ($powerScale -gt 2)
    $powerText = if ($powerScaleReserved) { ('reserved-scale({0}) value {1}' -f $powerScale, $powerValue) } else { Format-PciL1ssPowerOnUs -Us $powerUs }
    $capPowerText = if ($capPowerScaleReserved) { ('reserved-scale({0}) value {1}' -f $capPowerScale, $capPowerValue) } else { Format-PciL1ssPowerOnUs -Us $capPowerUs }
    $ctl2ReservedBitsSet = (($ctl2 -band 0xFFFFFF04) -ne 0)

    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ctl1Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,($capOff + 0x08))
    $ctl2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,($capOff + 0x0C))
    $portType = -1
    try { $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch { }
    $reservedWarn = if ($ctl2ReservedBitsSet) { '; WARN CTL2 reserved bits set' } else { '' }
    [pscustomobject]@{
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = $bdf
        PciePortType = [int]$portType
        PciePortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
        CapabilityOffset = [int]$capOff
        CapabilityVersion = [int]$ctx.Version
        HeaderRaw = [uint32]$ctx.HeaderRaw
        CapabilityRaw = [uint32]$cap
        Control1Raw = [uint32]$ctl1
        Control2Raw = [uint32]$ctl2
        Control1Offset = [int]($capOff + 0x08)
        Control2Offset = [int]($capOff + 0x0C)
        L1ssImplemented = [bool]$implemented
        RawSupportedMask = [int]$rawSupported
        SupportedMask = [int]$supported
        SupportedNames = (ConvertTo-PciL1ssMaskName -Mask $supported)
        EnabledMask = [int]$enabled
        EnabledNames = (ConvertTo-PciL1ssMaskName -Mask $enabled)
        PortCommonModeRestoreTimeUs = [int]$capCommonMode
        PortPowerOnScale = [int]$capPowerScale
        PortPowerOnValue = [int]$capPowerValue
        PortPowerOnUs = [uint64]$capPowerUs
        PortPowerOnScaleReserved = [bool]$capPowerScaleReserved
        CommonModeRestoreTimeUs = [int]$commonMode
        CommonModeRestoreTimeCapUs = [int]$capCommonMode
        LtrL12ThresholdScale = [int]$thresholdScale
        LtrL12ThresholdValue = [int]$thresholdValue
        LtrL12ThresholdNs = [uint64]$thresholdNs
        LtrL12ThresholdScaleReserved = [bool]$scaleReserved
        TPowerOnScale = [int]$powerScale
        TPowerOnValue = [int]$powerValue
        TPowerOnUs = [uint64]$powerUs
        TPowerOnScaleReserved = [bool]$powerScaleReserved
        TPowerOnCapScale = [int]$capPowerScale
        TPowerOnCapValue = [int]$capPowerValue
        TPowerOnCapUs = [uint64]$capPowerUs
        Control2ReservedBitsSet = [bool]$ctl2ReservedBitsSet
        Control1EcamAddress = [uint64]$ctl1Ecam
        Control2EcamAddress = [uint64]$ctl2Ecam
        DisplayText = ('Port enabled {0}; supported {1}; LTR1.2 {2}; CMRT ctl {3} us cap {4} us; T_PWR_ON ctl {5} cap {6}; {7}; BDF {8}; ext 0x{9:X3}; CTL1 0x{10:X8}; CTL2 0x{11:X8}; CAP 0x{12:X8}{13}' -f (ConvertTo-PciL1ssMaskName -Mask $enabled), (ConvertTo-PciL1ssMaskName -Mask $supported), $thresholdText, $commonMode, $capCommonMode, $powerText, $capPowerText, (ConvertTo-PciExpressPortTypeName -PortType $portType), $bdf, [int]$capOff, [uint32]$ctl1, [uint32]$ctl2, [uint32]$cap, $reservedWarn)
    }
}


function Get-PciL1Substate {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    return Get-PciL1SubstatePort -Segment $Segment -Bus $Bus -Device $Device -Function $Function
}

function Set-PciL1SubstateEnableMask {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(0,15)][int]$Mask
    )
    $requestedBdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $link = Resolve-PciL1SubstateLinkContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $parentBefore = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
    $childBefore = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
    if (-not [bool]$parentBefore.L1ssImplemented -or -not [bool]$childBefore.L1ssImplemented) {
        throw ('L1SS write refused for link parent {0} <-> child {1}: L1 PM Substates capability must be implemented on both ports. Parent implemented={2}; child implemented={3}.' -f $parentBefore.Bdf, $childBefore.Bdf, [bool]$parentBefore.L1ssImplemented, [bool]$childBefore.L1ssImplemented)
    }
    $linkSupported = [int](([int]$parentBefore.SupportedMask) -band ([int]$childBefore.SupportedMask) -band 0xF)
    $unsupported = [int](($Mask -band (-bnot $linkSupported)) -band 0xF)
    if ($Mask -ne 0 -and $unsupported -ne 0) {
        throw ('Requested L1SS mask {0} for link parent {1} <-> child {2}, but common link support is only {3}. Parent supports {4}; child supports {5}; unsupported requested bits: {6}.' -f (ConvertTo-PciL1ssMaskName -Mask $Mask), $parentBefore.Bdf, $childBefore.Bdf, (ConvertTo-PciL1ssMaskName -Mask $linkSupported), $parentBefore.SupportedNames, $childBefore.SupportedNames, (ConvertTo-PciL1ssMaskName -Mask $unsupported))
    }

    $parentAspmBefore = $null
    $childAspmBefore = $null
    $writeError = $null
    try {
        $parentAspmBefore = Get-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        $childAspmBefore = Get-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)

        if (([int]$childAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Mode 0) }
        if (([int]$parentAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Mode 0) }

        $childCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
        $childCtl1Disabled = [uint32](([uint32]$childCurrent.Control1Raw) -band 0xFFFFFFF0)
        Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childCurrent.Control1Offset) -Width 32 -Value $childCtl1Disabled

        $parentCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        $parentCtl1Disabled = [uint32](([uint32]$parentCurrent.Control1Raw) -band 0xFFFFFFF0)
        Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentCurrent.Control1Offset) -Width 32 -Value $parentCtl1Disabled

        $maskBits = [uint32]($Mask -band 0xF)
        $parentCtl1New = [uint32]($parentCtl1Disabled -bor $maskBits)
        Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentCurrent.Control1Offset) -Width 32 -Value $parentCtl1New
        $childCtl1New = [uint32]($childCtl1Disabled -bor $maskBits)
        Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childCurrent.Control1Offset) -Width 32 -Value $childCtl1New
    } catch {
        $writeError = $_.Exception.Message
    }

    if ($null -ne $parentAspmBefore -and $null -ne $childAspmBefore) {
        try {
            if (([int]$parentAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Mode ([int]$parentAspmBefore.Mode)) }
            if (([int]$childAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Mode ([int]$childAspmBefore.Mode)) }
        } catch {
            if ($writeError) { throw ('L1SS write failed for link parent {0} <-> child {1}; ASPM restore also failed. L1SS error: {2}; ASPM restore error: {3}' -f $parentBefore.Bdf, $childBefore.Bdf, $writeError, $_.Exception.Message) }
            throw ('L1SS write completed for link parent {0} <-> child {1}, but ASPM restore failed: {2}' -f $parentBefore.Bdf, $childBefore.Bdf, $_.Exception.Message)
        }
    }
    if ($writeError) { throw $writeError }

    $parentAfter = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
    $childAfter = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
    if ((([int]$parentAfter.EnabledMask -band 0xF) -ne ($Mask -band 0xF)) -or (([int]$childAfter.EnabledMask -band 0xF) -ne ($Mask -band 0xF))) {
        throw ('L1SS link write verification failed for request {0}. Requested {1}; parent {2} read {3} CTL1 0x{4:X8}; child {5} read {6} CTL1 0x{7:X8}. Before parent CTL1=0x{8:X8}; before child CTL1=0x{9:X8}.' -f $requestedBdf, (ConvertTo-PciL1ssMaskName -Mask $Mask), $parentAfter.Bdf, $parentAfter.EnabledNames, [uint32]$parentAfter.Control1Raw, $childAfter.Bdf, $childAfter.EnabledNames, [uint32]$childAfter.Control1Raw, [uint32]$parentBefore.Control1Raw, [uint32]$childBefore.Control1Raw)
    }
    return (Get-PciL1SubstatePort -Segment $Segment -Bus $Bus -Device $Device -Function $Function)
}


function Set-PciL1SubstateThreshold {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][uint64]$ThresholdNs
    )
    return Set-PciL1SubstateTiming -Segment $Segment -Bus $Bus -Device $Device -Function $Function -ThresholdNs ([int64]$ThresholdNs)
}

function Set-PciL1SubstateTiming {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [int64]$ThresholdNs = -1,
        [int]$CommonModeRestoreTimeUs = -1,
        [int]$PowerOnUs = -1
    )
    $writeThreshold = ($ThresholdNs -ge 0)
    $writeCmrt = ($CommonModeRestoreTimeUs -ge 0)
    $writePower = ($PowerOnUs -ge 0)
    if (-not ($writeThreshold -or $writeCmrt -or $writePower)) { throw 'L1SS timing write refused: no timing field was selected.' }
    if ($writeThreshold -and $ThresholdNs -gt [int64]34326183936) { throw ('L1SS LTR_L1.2_THRESHOLD write refused: {0} ns exceeds max encodable 34326183936 ns.' -f $ThresholdNs) }
    if ($writeCmrt -and ($CommonModeRestoreTimeUs -lt 0 -or $CommonModeRestoreTimeUs -gt 255)) { throw ('L1SS Common_Mode_Restore_Time write refused: {0} us is outside 0..255.' -f $CommonModeRestoreTimeUs) }
    if ($writePower -and ($PowerOnUs -lt 0 -or $PowerOnUs -gt 3100)) { throw ('L1SS T_POWER_ON write refused: {0} us is outside 0..3100.' -f $PowerOnUs) }

    $encodedThreshold = $null
    $encodedPower = $null
    if ($writeThreshold) { $encodedThreshold = ConvertFrom-PciL1ssThresholdNs -Ns ([uint64]$ThresholdNs) }
    if ($writePower) { $encodedPower = ConvertFrom-PciL1ssPowerOnUs -Us ([uint64]$PowerOnUs) }

    $requestedBdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $link = Resolve-PciL1SubstateLinkContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $parentBefore = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
    $childBefore = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
    if (-not [bool]$parentBefore.L1ssImplemented -or -not [bool]$childBefore.L1ssImplemented) {
        throw ('L1SS timing write refused for link parent {0} <-> child {1}: L1 PM Substates capability must be implemented on both ports. Parent implemented={2}; child implemented={3}.' -f $parentBefore.Bdf, $childBefore.Bdf, [bool]$parentBefore.L1ssImplemented, [bool]$childBefore.L1ssImplemented)
    }
    $linkSupported = [int](([int]$parentBefore.SupportedMask) -band ([int]$childBefore.SupportedMask) -band 0xF)
    if (($writeThreshold -or $writePower -or $writeCmrt) -and (($linkSupported -band 0x5) -eq 0)) {
        throw ('L1SS timing write refused for link parent {0} <-> child {1}: common link support has no L1.2 mode. Parent supports {2}; child supports {3}.' -f $parentBefore.Bdf, $childBefore.Bdf, $parentBefore.SupportedNames, $childBefore.SupportedNames)
    }

    $parentAspmBefore = $null
    $childAspmBefore = $null
    $writeError = $null
    try {
        $parentAspmBefore = Get-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        $childAspmBefore = Get-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)

        if (([int]$childAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Mode 0) }
        if (([int]$parentAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Mode 0) }

        $childCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
        $parentCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        $childL12EnabledMask = [int]([int]$childCurrent.EnabledMask -band 0x5)
        $parentL12EnabledMask = [int]([int]$parentCurrent.EnabledMask -band 0x5)

        if ($childL12EnabledMask -ne 0) {
            $childNoL12 = [uint32](([uint32]$childCurrent.Control1Raw) -band 0xFFFFFFFA)
            Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childCurrent.Control1Offset) -Width 32 -Value $childNoL12
            $childCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
        }
        if ($parentL12EnabledMask -ne 0) {
            $parentNoL12 = [uint32](([uint32]$parentCurrent.Control1Raw) -band 0xFFFFFFFA)
            Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentCurrent.Control1Offset) -Width 32 -Value $parentNoL12
            $parentCurrent = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        }

        $parentNewCtl1 = [uint32]$parentCurrent.Control1Raw
        $childNewCtl1 = [uint32]$childCurrent.Control1Raw
        if ($writeCmrt) {
            $cmrtBits = [uint32]((([uint32]$CommonModeRestoreTimeUs) -band 0xFF) -shl 8)
            $parentNewCtl1 = [uint32](($parentNewCtl1 -band 0xFFFF00FF) -bor $cmrtBits)
            $childNewCtl1 = [uint32](($childNewCtl1 -band 0xFFFF00FF) -bor $cmrtBits)
        }
        if ($writeThreshold) {
            $thresholdBits = [uint32]((((([uint32][int]$encodedThreshold.Scale) -band 0x7) -shl 29) -bor ((([uint32][int]$encodedThreshold.Value) -band 0x3FF) -shl 16)))
            $parentNewCtl1 = [uint32](($parentNewCtl1 -band 0x1C00FFFF) -bor $thresholdBits)
            $childNewCtl1 = [uint32](($childNewCtl1 -band 0x1C00FFFF) -bor $thresholdBits)
        }
        if ($parentNewCtl1 -ne [uint32]$parentCurrent.Control1Raw) {
            Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentCurrent.Control1Offset) -Width 32 -Value $parentNewCtl1
        }
        if ($childNewCtl1 -ne [uint32]$childCurrent.Control1Raw) {
            Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childCurrent.Control1Offset) -Width 32 -Value $childNewCtl1
        }

        if ($writePower) {
            $parentCtl2New = [uint32]((([uint32]$parentCurrent.Control2Raw) -band 0xFFFFFF04) -bor ([uint32]$encodedPower.Raw))
            $childCtl2New = [uint32]((([uint32]$childCurrent.Control2Raw) -band 0xFFFFFF04) -bor ([uint32]$encodedPower.Raw))
            if ($parentCtl2New -ne [uint32]$parentCurrent.Control2Raw) {
                Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentCurrent.Control2Offset) -Width 32 -Value $parentCtl2New
            }
            if ($childCtl2New -ne [uint32]$childCurrent.Control2Raw) {
                Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childCurrent.Control2Offset) -Width 32 -Value $childCtl2New
            }
        }

        if ($parentL12EnabledMask -ne 0) {
            $parentPost = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
            $parentRestore = [uint32](([uint32]$parentPost.Control1Raw) -bor ([uint32]$parentL12EnabledMask))
            Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentPost.Control1Offset) -Width 32 -Value $parentRestore
        }
        if ($childL12EnabledMask -ne 0) {
            $childPost = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
            $childRestore = [uint32](([uint32]$childPost.Control1Raw) -bor ([uint32]$childL12EnabledMask))
            Write-PciConfigValue -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Offset ([int]$childPost.Control1Offset) -Width 32 -Value $childRestore
        }
    } catch {
        $writeError = $_.Exception.Message
    }

    if ($null -ne $parentAspmBefore -and $null -ne $childAspmBefore) {
        try {
            if (([int]$parentAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Mode ([int]$parentAspmBefore.Mode)) }
            if (([int]$childAspmBefore.Mode -band 0x3) -ne 0) { [void](Set-PciAspm -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function) -Mode ([int]$childAspmBefore.Mode)) }
        } catch {
            if ($writeError) { throw ('L1SS timing write failed for link parent {0} <-> child {1}; ASPM restore also failed. Timing error: {2}; ASPM restore error: {3}' -f $parentBefore.Bdf, $childBefore.Bdf, $writeError, $_.Exception.Message) }
            throw ('L1SS timing write completed for link parent {0} <-> child {1}, but ASPM restore failed: {2}' -f $parentBefore.Bdf, $childBefore.Bdf, $_.Exception.Message)
        }
    }
    if ($writeError) { throw $writeError }

    $parentAfter = Get-PciL1SubstatePort -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
    $childAfter = Get-PciL1SubstatePort -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
    if ($writeThreshold -and ([int]$parentAfter.LtrL12ThresholdScale -ne [int]$encodedThreshold.Scale -or [int]$parentAfter.LtrL12ThresholdValue -ne [int]$encodedThreshold.Value -or [int]$childAfter.LtrL12ThresholdScale -ne [int]$encodedThreshold.Scale -or [int]$childAfter.LtrL12ThresholdValue -ne [int]$encodedThreshold.Value)) {
        throw ('L1SS LTR threshold verification failed for request {0}. Requested {1} ns encoded scale {2}, value {3}. Parent {4}: scale {5}, value {6}, CTL1=0x{7:X8}; child {8}: scale {9}, value {10}, CTL1=0x{11:X8}.' -f $requestedBdf, [uint64]$ThresholdNs, [int]$encodedThreshold.Scale, [int]$encodedThreshold.Value, $parentAfter.Bdf, [int]$parentAfter.LtrL12ThresholdScale, [int]$parentAfter.LtrL12ThresholdValue, [uint32]$parentAfter.Control1Raw, $childAfter.Bdf, [int]$childAfter.LtrL12ThresholdScale, [int]$childAfter.LtrL12ThresholdValue, [uint32]$childAfter.Control1Raw)
    }
    if ($writeCmrt -and ([int]$parentAfter.CommonModeRestoreTimeUs -ne $CommonModeRestoreTimeUs -or [int]$childAfter.CommonModeRestoreTimeUs -ne $CommonModeRestoreTimeUs)) {
        throw ('L1SS Common_Mode_Restore_Time verification failed for request {0}. Requested {1} us. Parent {2}: {3} us CTL1=0x{4:X8}; child {5}: {6} us CTL1=0x{7:X8}.' -f $requestedBdf, $CommonModeRestoreTimeUs, $parentAfter.Bdf, [int]$parentAfter.CommonModeRestoreTimeUs, [uint32]$parentAfter.Control1Raw, $childAfter.Bdf, [int]$childAfter.CommonModeRestoreTimeUs, [uint32]$childAfter.Control1Raw)
    }
    if ($writePower -and ([int]$parentAfter.TPowerOnScale -ne [int]$encodedPower.Scale -or [int]$parentAfter.TPowerOnValue -ne [int]$encodedPower.Value -or [int]$childAfter.TPowerOnScale -ne [int]$encodedPower.Scale -or [int]$childAfter.TPowerOnValue -ne [int]$encodedPower.Value)) {
        throw ('L1SS T_POWER_ON verification failed for request {0}. Requested {1} us encoded scale {2}, value {3} (actual {4} us). Parent {5}: scale {6}, value {7}, CTL2=0x{8:X8}; child {9}: scale {10}, value {11}, CTL2=0x{12:X8}.' -f $requestedBdf, $PowerOnUs, [int]$encodedPower.Scale, [int]$encodedPower.Value, [uint64]$encodedPower.ActualUs, $parentAfter.Bdf, [int]$parentAfter.TPowerOnScale, [int]$parentAfter.TPowerOnValue, [uint32]$parentAfter.Control2Raw, $childAfter.Bdf, [int]$childAfter.TPowerOnScale, [int]$childAfter.TPowerOnValue, [uint32]$childAfter.Control2Raw)
    }
    return (Get-PciL1SubstatePort -Segment $Segment -Bus $Bus -Device $Device -Function $Function)
}


function ConvertTo-PciPacketSizeBytes {
    param([Parameter(Mandatory=$true)][int]$Encoding)
    if ($Encoding -lt 0 -or $Encoding -gt 5) { return 0 }
    return [int](128 * [Math]::Pow(2, $Encoding))
}

function ConvertTo-PciPacketSizeName {
    param([Parameter(Mandatory=$true)][int]$Encoding)
    $bytes = ConvertTo-PciPacketSizeBytes -Encoding $Encoding
    if ($bytes -le 0) { return ('reserved({0})' -f $Encoding) }
    if ($bytes -ge 1024) { return ('{0} KB' -f [int]($bytes / 1024)) }
    return ('{0} B' -f $bytes)
}

function ConvertFrom-PciPacketSizeBytes {
    param([Parameter(Mandatory=$true)][int]$Bytes)
    switch ($Bytes) {
        128 { 0; break }
        256 { 1; break }
        512 { 2; break }
        1024 { 3; break }
        2048 { 4; break }
        4096 { 5; break }
        default { throw ('Unsupported PCIe packet size {0}; expected one of 128, 256, 512, 1024, 2048, 4096 bytes.' -f $Bytes) }
    }
}

function ConvertTo-PciLinkSpeedName {
    param([Parameter(Mandatory=$true)][int]$Code)
    switch ($Code -band 0xF) {
        1 { 'Gen1 2.5 GT/s'; break }
        2 { 'Gen2 5.0 GT/s'; break }
        3 { 'Gen3 8.0 GT/s'; break }
        4 { 'Gen4 16.0 GT/s'; break }
        5 { 'Gen5 32.0 GT/s'; break }
        6 { 'Gen6 64.0 GT/s'; break }
        7 { 'Gen7 128.0 GT/s'; break }
        default { 'reserved({0})' -f ($Code -band 0xF) }
    }
}


function ConvertTo-PciSupportedLinkSpeedCodes {
    param(
        [Parameter(Mandatory=$true)][uint32]$Vector,
        [ValidateRange(0,7)][int]$FallbackMaxCode = 0
    )
    $codes = [System.Collections.Generic.List[int]]::new()
    if ($Vector -ne 0) {
        for ($code = 1; $code -le 7; $code++) {
            if (($Vector -band ([uint32]1 -shl $code)) -ne 0) { [void]$codes.Add([int]$code) }
        }
    }
    if ($codes.Count -eq 0 -and $FallbackMaxCode -gt 0) {
        for ($code = 1; $code -le $FallbackMaxCode; $code++) { [void]$codes.Add([int]$code) }
    }

    foreach ($code in $codes.ToArray()) { [int]$code }
}

function ConvertTo-PciSupportedLinkSpeedNames {
    param(
        [Parameter(Mandatory=$true)][uint32]$Vector,
        [ValidateRange(0,7)][int]$FallbackMaxCode = 0
    )
    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($code in @(ConvertTo-PciSupportedLinkSpeedCodes -Vector $Vector -FallbackMaxCode $FallbackMaxCode)) {
        [void]$names.Add((ConvertTo-PciLinkSpeedName -Code ([int]$code)))
    }
    if ($names.Count -eq 0) { return 'unknown' }
    return [string]::Join(', ', $names.ToArray())
}

function Test-PciLinkSpeedCodeSupported {
    param(
        [Parameter(Mandatory=$true)][uint32]$Vector,
        [Parameter(Mandatory=$true)][ValidateRange(1,7)][int]$Code,
        [ValidateRange(0,7)][int]$FallbackMaxCode = 0
    )
    foreach ($supported in @(ConvertTo-PciSupportedLinkSpeedCodes -Vector $Vector -FallbackMaxCode $FallbackMaxCode)) {
        if ([int]$supported -eq [int]$Code) { return $true }
    }
    return $false
}

function ConvertTo-PciLinkWidthName {
    param([Parameter(Mandatory=$true)][int]$Width)
    if ($Width -gt 0) { return ('x{0}' -f $Width) }
    return 'link-down/unknown'
}


function Get-PciDevice2TenBitTagState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $hasDevice2 = $false
    try { $hasDevice2 = [bool]$ctx.HasDevice2Registers } catch { $hasDevice2 = ([int]$ctx.CapabilityVersion -ge 2) }
    $devcap2 = [uint32]0
    $devctl2 = [uint32]0
    $devsta = [uint32]0
    $devcap2Ecam = [uint64]0
    $devctl2Ecam = [uint64]0
    $devstaEcam = [uint64]0
    $device2Error = $null
    if ($hasDevice2) {
        try {
            $devcap2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceCapabilities2Offset) -Width 32)
            $devctl2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControl2Offset) -Width 16)
            $devsta = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControlOffset + 2) -Width 16)
            $devcap2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceCapabilities2Offset)
            $devctl2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceControl2Offset)
            $devstaEcam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,([int]$ctx.DeviceControlOffset + 2))
        } catch { $device2Error = $_.Exception.Message }
    }
    $usableDevice2 = [bool]($hasDevice2 -and [string]::IsNullOrWhiteSpace($device2Error))
    [pscustomobject]@{
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = $bdf
        CapabilityOffset = [int]$ctx.CapabilityOffset
        PcieCapabilityVersion = [int]$ctx.CapabilityVersion
        PciePortType = [int]$ctx.DevicePortType
        PciePortTypeName = (ConvertTo-PciExpressPortTypeName -PortType ([int]$ctx.DevicePortType))
        DeviceCapabilities2Offset = if ($hasDevice2) { [int]$ctx.DeviceCapabilities2Offset } else { -1 }
        DeviceControl2Offset = if ($hasDevice2) { [int]$ctx.DeviceControl2Offset } else { -1 }
        DeviceStatusOffset = [int]([int]$ctx.DeviceControlOffset + 2)
        DeviceCapabilities2Raw = [uint32]$devcap2
        DeviceControl2Raw = [uint16]$devctl2
        DeviceStatusRaw = [uint16]$devsta
        HasDevice2Registers = [bool]$usableDevice2
        Device2Error = $device2Error
        TenBitTagCompleterSupported = [bool](($devcap2 -band 0x00010000) -ne 0)
        TenBitTagRequesterSupported = [bool](($devcap2 -band 0x00020000) -ne 0)
        TenBitTagRequesterEnabled = [bool](($devctl2 -band 0x1000) -ne 0)
        TransactionsPending = [bool](($devsta -band 0x0020) -ne 0)
        DeviceCapabilities2EcamAddress = [uint64]$devcap2Ecam
        DeviceControl2EcamAddress = [uint64]$devctl2Ecam
        DeviceStatusEcamAddress = [uint64]$devstaEcam
    }
}

function Wait-PciDeviceTransactionsIdle {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [ValidateRange(25,5000)][int]$TimeoutMs = 1000
    )
    $deadline = [DateTime]::UtcNow.AddMilliseconds($TimeoutMs)
    $state = $null
    do {
        $state = Get-PciDevice2TenBitTagState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        if (-not [bool]$state.TransactionsPending) { return $state }
        Start-Sleep -Milliseconds 25
    } while ([DateTime]::UtcNow -lt $deadline)
    if ($null -eq $state) { $state = Get-PciDevice2TenBitTagState -Segment $Segment -Bus $Bus -Device $Device -Function $Function }
    throw ('10-Bit Tag Requester write refused for {0}: Device Status bit 5 (Transactions Pending) stayed set; changing DEVCTL2[12] while Non-Posted Requests are outstanding is unsafe. DEVSTA=0x{1:X4}; DEVSTA ECAM=0x{2:X}.' -f [string]$state.Bdf, [int]$state.DeviceStatusRaw, [uint64]$state.DeviceStatusEcamAddress)
}

function Get-PciTenBitTagLinkPolicy {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $local = Get-PciDevice2TenBitTagState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $peer = $null
    $link = $null
    $peerRole = 'Peer'
    $linkError = $null
    try {
        $link = Resolve-PciAspmLinkContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        if ([string]::Equals([string]$link.RequestedRole, 'Parent', [System.StringComparison]::OrdinalIgnoreCase)) {
            $peerRole = 'Child/Endpoint Completer'
            $peer = Get-PciDevice2TenBitTagState -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
        } else {
            $peerRole = 'Upstream/Root Completer'
            $peer = Get-PciDevice2TenBitTagState -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        }
    } catch { $linkError = $_.Exception.Message }

    $reasons = [System.Collections.Generic.List[string]]::new()
    if (-not [bool]$local.HasDevice2Registers) { [void]$reasons.Add(('local Device Control 2 unavailable ({0})' -f [string]$local.Device2Error)) }
    if (-not [bool]$local.TenBitTagRequesterSupported) { [void]$reasons.Add(('local DEVCAP2[17] requester-cap=0 (DEVCAP2=0x{0:X8})' -f [uint32]$local.DeviceCapabilities2Raw)) }
    if (-not [bool]$local.TenBitTagCompleterSupported) { [void]$reasons.Add(('local DEVCAP2[16] completer-cap=0 (requester-cap requires matching completer capability)')) }
    if (-not [string]::IsNullOrWhiteSpace($linkError)) { [void]$reasons.Add(('link peer unresolved: {0}' -f $linkError)) }
    elseif ($null -eq $peer) { [void]$reasons.Add('link peer unresolved') }
    else {
        if (-not [bool]$peer.HasDevice2Registers) { [void]$reasons.Add(('{0} Device Control 2 unavailable ({1})' -f $peerRole, [string]$peer.Device2Error)) }
        if (-not [bool]$peer.TenBitTagCompleterSupported) { [void]$reasons.Add(('{0} DEVCAP2[16] completer-cap=0 (DEVCAP2=0x{1:X8})' -f $peerRole, [uint32]$peer.DeviceCapabilities2Raw)) }
    }
    $safe = ($reasons.Count -eq 0)
    $peerRequesterCanBeAligned = $false
    if ($safe -and $null -ne $peer) {
        $peerRequesterCanBeAligned = ([bool]$peer.HasDevice2Registers -and [bool]$peer.TenBitTagRequesterSupported -and [bool]$peer.TenBitTagCompleterSupported -and [bool]$local.TenBitTagCompleterSupported)
    }
    $summary = if ($safe) {
        if ($null -ne $peer) { ('safe: local req/cpl-cap yes; {0} {1} cpl-cap yes; DEVCTL2[12] may be set after transactions drain' -f $peerRole, [string]$peer.Bdf) }
        else { 'safe: local req/cpl-cap yes; peer not applicable' }
    } else { ('blocked: {0}' -f ([string]::Join('; ', $reasons.ToArray()))) }

    [pscustomobject]@{
        Local = $local
        Peer = $peer
        PeerRole = $peerRole
        LinkResolved = [bool]($null -ne $link -and [string]::IsNullOrWhiteSpace($linkError))
        LinkError = $linkError
        RequestedRole = if ($null -ne $link) { [string]$link.RequestedRole } else { 'Unknown' }
        SafeToEnable = [bool]$safe
        PeerRequesterCanBeAligned = [bool]$peerRequesterCanBeAligned
        Reason = $summary
    }
}

function Get-PciLinkState {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $ctx = Get-PciExpressCapabilityContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $capabilityFlagsOffset = if ($ctx.PSObject.Properties.Match('CapabilityFlagsOffset').Count -gt 0) { [int]$ctx.CapabilityFlagsOffset } else { [int]$ctx.CapabilityOffset + 0x02 }
    $pcieFlags = [uint16](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset $capabilityFlagsOffset -Width 16)
    $devcap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceCapabilitiesOffset) -Width 32)
    $devctl = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControlOffset) -Width 16)
    $devsta = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControlOffset + 2) -Width 16)
    $lnkcap = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkCapabilitiesOffset) -Width 32)
    $lnkctl = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkControlOffset) -Width 16)
    $lnksta = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkStatusOffset) -Width 16)
    $hasDevice2 = $false
    try { $hasDevice2 = [bool]$ctx.HasDevice2Registers } catch { $hasDevice2 = ([int]$ctx.CapabilityVersion -ge 2) }
    $devcap2 = [uint32]0
    $devctl2 = [uint32]0
    $devcap2Ecam = [uint64]0
    $devctl2Ecam = [uint64]0
    $device2Error = $null
    if ($hasDevice2) {
        try {
            $devcap2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceCapabilities2Offset) -Width 32)
            $devctl2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.DeviceControl2Offset) -Width 16)
            $devcap2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceCapabilities2Offset)
            $devctl2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceControl2Offset)
        } catch { $device2Error = $_.Exception.Message }
    }

    $currentSpeedCode = [int]($lnksta -band 0x000F)
    $currentWidth = [int](($lnksta -band 0x03F0) -shr 4)
    $maxSpeedCode = [int]($lnkcap -band 0x0000000F)
    $maxWidth = [int](($lnkcap -band 0x000003F0) -shr 4)
    $aspmSupport = [int](($lnkcap -band 0x00000C00) -shr 10)
    $aspmMode = [int]($lnkctl -band 0x0003)
    $mpsCode = [int](($devctl -band 0x00E0) -shr 5)
    $mrrsCode = [int](($devctl -band 0x7000) -shr 12)
    $relaxedOrderingEnabled = (($devctl -band 0x0010) -ne 0)
    $extendedTagSupported = (($devcap -band 0x00000020) -ne 0)
    $extendedTagEnabled = (($devctl -band 0x0100) -ne 0)
    $noSnoopEnabled = (($devctl -band 0x0800) -ne 0)
    $clockPowerManagementSupported = (($lnkcap -band 0x00040000) -ne 0)
    $clockPowerManagementEnabled = (($lnkctl -band 0x0100) -ne 0)
    $commonClockConfigurationEnabled = (($lnkctl -band 0x0040) -ne 0)
    $extendedSyncEnabled = (($lnkctl -band 0x0080) -ne 0)
    $maxPayloadCode = [int]($devcap -band 0x7)
    $mpsBytes = ConvertTo-PciPacketSizeBytes -Encoding $mpsCode
    $mrrsBytes = ConvertTo-PciPacketSizeBytes -Encoding $mrrsCode
    $maxPayloadBytes = ConvertTo-PciPacketSizeBytes -Encoding $maxPayloadCode
    $bdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $devctlEcam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.DeviceControlOffset)
    $lnkctlEcam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkControlOffset)
    $lnkstaEcam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkStatusOffset)
    $speedName = ConvertTo-PciLinkSpeedName -Code $currentSpeedCode
    $widthName = ConvertTo-PciLinkWidthName -Width $currentWidth
    $maxSpeedName = ConvertTo-PciLinkSpeedName -Code $maxSpeedCode
    $maxWidthName = ConvertTo-PciLinkWidthName -Width $maxWidth
    $mpsName = ConvertTo-PciPacketSizeName -Encoding $mpsCode
    $mrrsName = ConvertTo-PciPacketSizeName -Encoding $mrrsCode
    $relaxedOrderingName = if ($relaxedOrderingEnabled) { 'on' } else { 'off' }
    $extendedTagStateName = if ($extendedTagEnabled) { 'on' } else { 'off' }
    $extendedTagCapName = if ($extendedTagSupported) { 'yes' } else { 'no' }
    $noSnoopName = if ($noSnoopEnabled) { 'on' } else { 'off' }
    $clockPowerManagementStateName = if ($clockPowerManagementEnabled) { 'on' } else { 'off' }
    $clockPowerManagementCapName = if ($clockPowerManagementSupported) { 'yes' } else { 'no' }
    $commonClockConfigurationName = if ($commonClockConfigurationEnabled) { 'on' } else { 'off' }
    $extendedSyncName = if ($extendedSyncEnabled) { 'on' } else { 'off' }
    $idoRequestEnabled = (($devctl2 -band 0x0100) -ne 0)
    $idoCompletionEnabled = (($devctl2 -band 0x0200) -ne 0)
    $tenBitTagCompleterSupported = (($devcap2 -band 0x00010000) -ne 0)
    $tenBitTagRequesterSupported = (($devcap2 -band 0x00020000) -ne 0)
    $tenBitTagRequesterEnabled = (($devctl2 -band 0x1000) -ne 0)
    $idoRequestName = if ($idoRequestEnabled) { 'on' } else { 'off' }
    $idoCompletionName = if ($idoCompletionEnabled) { 'on' } else { 'off' }
    $tenBitTagRequesterName = if ($tenBitTagRequesterEnabled) { 'on' } else { 'off' }
    $tenBitTagRequesterCapName = if ($tenBitTagRequesterSupported) { 'yes' } else { 'no' }
    $tenBitTagCompleterCapName = if ($tenBitTagCompleterSupported) { 'yes' } else { 'no' }
    $device2StateName = if ($hasDevice2 -and [string]::IsNullOrWhiteSpace($device2Error)) { 'yes' } elseif ($hasDevice2) { 'error' } else { 'no' }
    $transactionsPending = (($devsta -band 0x0020) -ne 0)
    $tenBitTagPolicy = $null
    $tenBitTagPolicyText = 'unresolved'
    $tenBitTagSafeToEnable = $false
    $tenBitTagPeerBdf = 'n/a'
    $tenBitTagPeerCompleterCapName = 'n/a'
    $tenBitTagPeerRequesterCapName = 'n/a'
    $tenBitTagPeerRequesterEnabledName = 'n/a'
    try {
        $tenBitTagPolicy = Get-PciTenBitTagLinkPolicy -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        $tenBitTagSafeToEnable = [bool]$tenBitTagPolicy.SafeToEnable
        $tenBitTagPolicyText = [string]$tenBitTagPolicy.Reason
        if ($null -ne $tenBitTagPolicy.Peer) {
            $tenBitTagPeerBdf = [string]$tenBitTagPolicy.Peer.Bdf
            $tenBitTagPeerCompleterCapName = if ([bool]$tenBitTagPolicy.Peer.TenBitTagCompleterSupported) { 'yes' } else { 'no' }
            $tenBitTagPeerRequesterCapName = if ([bool]$tenBitTagPolicy.Peer.TenBitTagRequesterSupported) { 'yes' } else { 'no' }
            $tenBitTagPeerRequesterEnabledName = if ([bool]$tenBitTagPolicy.Peer.TenBitTagRequesterEnabled) { 'on' } else { 'off' }
        }
    } catch { $tenBitTagPolicyText = ('unresolved: {0}' -f $_.Exception.Message) }
    $hawdEnabled = (($lnkctl -band 0x0200) -ne 0)
    $hawdName = if ($hawdEnabled) { 'dis' } else { 'auto' }
    $maxPayloadName = ConvertTo-PciPacketSizeName -Encoding $maxPayloadCode

    $hasLink2 = $false
    try { $hasLink2 = [bool]$ctx.HasLink2Registers } catch { $hasLink2 = ([int]$ctx.CapabilityVersion -ge 2) }
    $lnkcap2 = [uint32]0
    $lnkctl2 = [uint32]0
    $lnksta2 = [uint32]0
    $lnkcap2Ecam = [uint64]0
    $lnkctl2Ecam = [uint64]0
    $lnksta2Ecam = [uint64]0
    $targetSpeedCode = 0
    $targetSpeedName = 'n/a'
    $supportedVector = [uint32]0
    $supportedSpeedNames = ConvertTo-PciSupportedLinkSpeedNames -Vector 0 -FallbackMaxCode $maxSpeedCode
    $link2Error = $null
    if ($hasLink2) {
        try {
            $lnkcap2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkCapabilities2Offset) -Width 32)
            $lnkctl2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkControl2Offset) -Width 16)
            $lnksta2 = [uint32](Read-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$ctx.LinkStatus2Offset) -Width 16)
            $lnkcap2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkCapabilities2Offset)
            $lnkctl2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkControl2Offset)
            $lnksta2Ecam = [DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,[int]$ctx.LinkStatus2Offset)
            $targetSpeedCode = [int]($lnkctl2 -band 0x000F)
            $targetSpeedName = ConvertTo-PciLinkSpeedName -Code $targetSpeedCode
            $supportedVector = [uint32]($lnkcap2 -band 0x000000FE)
            $supportedSpeedNames = ConvertTo-PciSupportedLinkSpeedNames -Vector $supportedVector -FallbackMaxCode $maxSpeedCode
        } catch {
            $link2Error = $_.Exception.Message
        }
    }
    $hasdEnabled = (($lnkctl2 -band 0x0020) -ne 0)
    $hasdName = if ($hasdEnabled) { 'dis' } else { 'auto' }
    $flitSupported = (($pcieFlags -band [uint16]0x8000) -ne 0)
    $flitDisabled = (($lnkctl -band [uint32]0x2000) -ne 0)
    $flitActive = (($lnksta2 -band [uint32]0x0400) -ne 0)
    $retimerSupported = (($lnkcap2 -band [uint32]0x00800000) -ne 0)
    $twoRetimersSupported = (($lnkcap2 -band [uint32]0x01000000) -ne 0)
    $retimerDetected = (($lnksta2 -band [uint32]0x0040) -ne 0)
    $twoRetimersDetected = (($lnksta2 -band [uint32]0x0080) -ne 0)
    $linkEqualizationComplete = (($lnksta2 -band [uint32]0x0002) -ne 0)
    $linkEqualizationPhase1 = (($lnksta2 -band [uint32]0x0004) -ne 0)
    $linkEqualizationPhase2 = (($lnksta2 -band [uint32]0x0008) -ne 0)
    $linkEqualizationPhase3 = (($lnksta2 -band [uint32]0x0010) -ne 0)
    $linkEqualizationRequest = (($lnksta2 -band [uint32]0x0020) -ne 0)
    $linkEqualizationIncompletePhaseCount = 0
    if (-not $linkEqualizationPhase1) { $linkEqualizationIncompletePhaseCount++ }
    if (-not $linkEqualizationPhase2) { $linkEqualizationIncompletePhaseCount++ }
    if (-not $linkEqualizationPhase3) { $linkEqualizationIncompletePhaseCount++ }
    if ($linkEqualizationComplete) { $linkEqualizationIncompletePhaseCount = 0 }
    $transmitMarginCode = [int](($lnkctl2 -band [uint32]0x0380) -shr 7)
    $compliancePresetDeemphasis = [int](($lnkctl2 -band [uint32]0xF000) -shr 12)
    $currentDeemphasis = [int]($lnksta2 -band [uint32]0x0001)

    $targetText = if ($hasLink2 -and [string]::IsNullOrWhiteSpace($link2Error)) { ('target {0}; supported {1}; LNKCTL2 0x{2:X4}' -f $targetSpeedName, $supportedSpeedNames, [int]$lnkctl2) } elseif ($hasLink2) { ('Link2 read error: {0}' -f $link2Error) } else { ('supported {0}; no Link Cap/Control 2' -f $supportedSpeedNames) }
    [pscustomobject]@{
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = $bdf
        CapabilityOffset = [int]$ctx.CapabilityOffset
        PcieCapabilityVersion = [int]$ctx.CapabilityVersion
        PciePortType = [int]$ctx.DevicePortType
        PciePortTypeName = (ConvertTo-PciExpressPortTypeName -PortType ([int]$ctx.DevicePortType))
        PcieCapabilityFlagsRaw = [uint16]$pcieFlags
        DeviceCapabilitiesOffset = [int]$ctx.DeviceCapabilitiesOffset
        DeviceControlOffset = [int]$ctx.DeviceControlOffset
        LinkCapabilitiesOffset = [int]$ctx.LinkCapabilitiesOffset
        LinkControlOffset = [int]$ctx.LinkControlOffset
        LinkStatusOffset = [int]$ctx.LinkStatusOffset
        DeviceCapabilitiesRaw = [uint32]$devcap
        DeviceControlRaw = [uint16]$devctl
        DeviceCapabilities2Offset = if ($hasDevice2) { [int]$ctx.DeviceCapabilities2Offset } else { -1 }
        DeviceControl2Offset = if ($hasDevice2) { [int]$ctx.DeviceControl2Offset } else { -1 }
        DeviceCapabilities2Raw = [uint32]$devcap2
        DeviceControl2Raw = [uint16]$devctl2
        DeviceStatusRaw = [uint16]$devsta
        TransactionsPending = [bool]$transactionsPending
        HasDevice2Registers = [bool]($hasDevice2 -and [string]::IsNullOrWhiteSpace($device2Error))
        Device2Error = $device2Error
        IdoRequestEnabled = [bool]$idoRequestEnabled
        IdoCompletionEnabled = [bool]$idoCompletionEnabled
        TenBitTagCompleterSupported = [bool]$tenBitTagCompleterSupported
        TenBitTagRequesterSupported = [bool]$tenBitTagRequesterSupported
        TenBitTagRequesterEnabled = [bool]$tenBitTagRequesterEnabled
        TenBitTagSafeToEnable = [bool]$tenBitTagSafeToEnable
        TenBitTagPolicyReason = [string]$tenBitTagPolicyText
        TenBitTagPeerBdf = [string]$tenBitTagPeerBdf
        TenBitTagPeerCompleterSupported = [bool]([string]::Equals($tenBitTagPeerCompleterCapName, 'yes', [System.StringComparison]::OrdinalIgnoreCase))
        TenBitTagPeerRequesterSupported = [bool]([string]::Equals($tenBitTagPeerRequesterCapName, 'yes', [System.StringComparison]::OrdinalIgnoreCase))
        TenBitTagPeerRequesterEnabled = [bool]([string]::Equals($tenBitTagPeerRequesterEnabledName, 'on', [System.StringComparison]::OrdinalIgnoreCase))
        LinkCapabilitiesRaw = [uint32]$lnkcap
        LinkControlRaw = [uint16]$lnkctl
        LinkStatusRaw = [uint16]$lnksta
        CurrentLinkSpeedCode = $currentSpeedCode
        CurrentLinkSpeedName = $speedName
        CurrentLinkWidth = $currentWidth
        CurrentLinkWidthName = $widthName
        MaxLinkSpeedCode = $maxSpeedCode
        MaxLinkSpeedName = $maxSpeedName
        MaxLinkWidth = $maxWidth
        MaxLinkWidthName = $maxWidthName
        SupportedLinkSpeedVector = [uint32]$supportedVector
        SupportedLinkSpeedNames = [string]$supportedSpeedNames
        TargetLinkSpeedCode = [int]$targetSpeedCode
        TargetLinkSpeedName = [string]$targetSpeedName
        MpsCode = $mpsCode
        MpsBytes = $mpsBytes
        MpsName = $mpsName
        MrrsCode = $mrrsCode
        MrrsBytes = $mrrsBytes
        MrrsName = $mrrsName
        RelaxedOrderingEnabled = [bool]$relaxedOrderingEnabled
        ExtendedTagSupported = [bool]$extendedTagSupported
        ExtendedTagEnabled = [bool]$extendedTagEnabled
        NoSnoopEnabled = [bool]$noSnoopEnabled
        ClockPowerManagementSupported = [bool]$clockPowerManagementSupported
        ClockPowerManagementEnabled = [bool]$clockPowerManagementEnabled
        MaxPayloadCode = $maxPayloadCode
        MaxPayloadBytes = $maxPayloadBytes
        MaxPayloadName = $maxPayloadName
        AspmSupportCode = [int]$aspmSupport
        AspmMode = [int]$aspmMode
        LinkDisabled = (($lnkctl -band 0x0010) -ne 0)
        LinkRetrainBit = (($lnkctl -band 0x0020) -ne 0)
        CommonClockConfiguration = [bool]$commonClockConfigurationEnabled
        ExtendedSync = [bool]$extendedSyncEnabled
        HardwareAutonomousWidthDisable = [bool]$hawdEnabled
        LinkTraining = (($lnksta -band 0x0800) -ne 0)
        SlotClockConfig = (($lnksta -band 0x1000) -ne 0)
        DataLinkLayerActive = (($lnksta -band 0x2000) -ne 0)
        HasLink2Registers = [bool]($hasLink2 -and [string]::IsNullOrWhiteSpace($link2Error))
        Link2Error = $link2Error
        LinkCapabilities2Offset = if ($hasLink2) { [int]$ctx.LinkCapabilities2Offset } else { -1 }
        LinkControl2Offset = if ($hasLink2) { [int]$ctx.LinkControl2Offset } else { -1 }
        LinkStatus2Offset = if ($hasLink2) { [int]$ctx.LinkStatus2Offset } else { -1 }
        LinkCapabilities2Raw = [uint32]$lnkcap2
        LinkControl2Raw = [uint16]$lnkctl2
        LinkStatus2Raw = [uint16]$lnksta2
        HardwareAutonomousSpeedDisable = [bool]$hasdEnabled
        TransmitMarginCode = [int]$transmitMarginCode
        ComplianceDeemphasis = (($lnkctl2 -band 0x0040) -ne 0)
        CompliancePresetDeemphasis = [int]$compliancePresetDeemphasis
        CurrentDeemphasis = [int]$currentDeemphasis
        FlitModeSupported = [bool]$flitSupported
        FlitModeDisabled = [bool]$flitDisabled
        FlitModeActive = [bool]$flitActive
        RetimerSupported = [bool]$retimerSupported
        TwoRetimersSupported = [bool]$twoRetimersSupported
        RetimerDetected = [bool]$retimerDetected
        TwoRetimersDetected = [bool]$twoRetimersDetected
        LinkEqualizationComplete = [bool]$linkEqualizationComplete
        LinkEqualizationPhase1Successful = [bool]$linkEqualizationPhase1
        LinkEqualizationPhase2Successful = [bool]$linkEqualizationPhase2
        LinkEqualizationPhase3Successful = [bool]$linkEqualizationPhase3
        LinkEqualizationRequest = [bool]$linkEqualizationRequest
        LinkEqualizationIncompletePhaseCount = [int]$linkEqualizationIncompletePhaseCount
        LinkControlEcamAddress = [uint64]$lnkctlEcam
        DevControlEcamAddress = [uint64]$devctlEcam
        LinkStatusEcamAddress = [uint64]$lnkstaEcam
        DeviceStatusEcamAddress = [uint64]([DeviceTweakerPciEcam]::ResolveAddress($Segment,$Bus,$Device,$Function,([int]$ctx.DeviceControlOffset + 2)))
        DeviceCapabilities2EcamAddress = [uint64]$devcap2Ecam
        DeviceControl2EcamAddress = [uint64]$devctl2Ecam
        LinkCapabilities2EcamAddress = [uint64]$lnkcap2Ecam
        LinkControl2EcamAddress = [uint64]$lnkctl2Ecam
        LinkStatus2EcamAddress = [uint64]$lnksta2Ecam
        DisplayText = ('Link {0} {1}; max {2} {3}; {4}; MRRS {5}; MPS {6} (cap {7}); Relaxed {8}; ExtTag {9} (cap {10}); 10Tag req {11} (req-cap {12}) cpl-cap {13}; peer {31} cpl-cap {32} req-cap {33} req {34}; NoSnoop {14}; CLKREQ {15} (cap {16}); CCC {17}; ExtSync {18}; IDO req {19} cpl {20} (DEVCTL2 {21}); HAW {22}; HAS {23}; FLIT cap {37} active {38} dis {39}; Retimer sup {40}/{41} det {42}/{43}; EQ2 comp {44} p1 {45} p2 {46} p3 {47} req {48} inc {49}; preset margin {50} compliance {51} deemph {52}; BDF {24}; LNKCTL 0x{25:X4}; LNKSTA 0x{26:X4}; DEVSTA 0x{35:X4}; DEVCTL 0x{27:X4}; DEVCAP2 0x{28:X8}; DEVCTL2 0x{29:X4}; LNKCTL2 0x{30:X4}; LNKSTA2 0x{53:X4}; 10TagPolicy {36}' -f $speedName, $widthName, $maxSpeedName, $maxWidthName, $targetText, $mrrsName, $mpsName, $maxPayloadName, $relaxedOrderingName, $extendedTagStateName, $extendedTagCapName, $tenBitTagRequesterName, $tenBitTagRequesterCapName, $tenBitTagCompleterCapName, $noSnoopName, $clockPowerManagementStateName, $clockPowerManagementCapName, $commonClockConfigurationName, $extendedSyncName, $idoRequestName, $idoCompletionName, $device2StateName, $hawdName, $hasdName, $bdf, [int]$lnkctl, [int]$lnksta, [int]$devctl, [uint32]$devcap2, [int]$devctl2, [int]$lnkctl2, $tenBitTagPeerBdf, $tenBitTagPeerCompleterCapName, $tenBitTagPeerRequesterCapName, $tenBitTagPeerRequesterEnabledName, [int]$devsta, $tenBitTagPolicyText, $flitSupported, $flitActive, $flitDisabled, $retimerSupported, $twoRetimersSupported, $retimerDetected, $twoRetimersDetected, $linkEqualizationComplete, $linkEqualizationPhase1, $linkEqualizationPhase2, $linkEqualizationPhase3, $linkEqualizationRequest, $linkEqualizationIncompletePhaseCount, $transmitMarginCode, $compliancePresetDeemphasis, $currentDeemphasis, [int]$lnksta2)
    }
}

function Get-PciLinkCommonSupportedSpeedCodes {
    param(
        [Parameter(Mandatory=$true)]$ParentState,
        [Parameter(Mandatory=$true)]$ChildState
    )
    $set = [System.Collections.Generic.HashSet[int]]::new()
    foreach ($code in @(ConvertTo-PciSupportedLinkSpeedCodes -Vector ([uint32]$ParentState.SupportedLinkSpeedVector) -FallbackMaxCode ([int]$ParentState.MaxLinkSpeedCode))) {
        [void]$set.Add([int]$code)
    }
    $common = [System.Collections.Generic.List[int]]::new()
    foreach ($code in @(ConvertTo-PciSupportedLinkSpeedCodes -Vector ([uint32]$ChildState.SupportedLinkSpeedVector) -FallbackMaxCode ([int]$ChildState.MaxLinkSpeedCode))) {
        if ($set.Contains([int]$code)) { [void]$common.Add([int]$code) }
    }

    foreach ($code in $common.ToArray()) { [int]$code }
}

function Set-PciTargetLinkSpeedAndRetrain {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateRange(1,7)][int]$TargetSpeedCode,
        [ValidateRange(250,30000)][int]$TimeoutMs = 5000
    )
    $requestedBdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $link = Resolve-PciAspmLinkContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $parentBefore = Get-PciLinkState -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
    $childBefore = Get-PciLinkState -Segment ([int]$link.Child.Segment) -Bus ([int]$link.Child.Bus) -Device ([int]$link.Child.Device) -Function ([int]$link.Child.Function)
    if (-not [bool]$parentBefore.HasLink2Registers) {
        throw ('PCIe target link speed write refused for {0}: downstream/root port {1} does not expose usable Link Control 2. Error={2}' -f $requestedBdf, [string]$parentBefore.Bdf, [string]$parentBefore.Link2Error)
    }
    $common = @(Get-PciLinkCommonSupportedSpeedCodes -ParentState $parentBefore -ChildState $childBefore)
    $supported = $false
    foreach ($code in @($common)) { if ([int]$code -eq [int]$TargetSpeedCode) { $supported = $true; break } }
    if (-not $supported) {
        $commonNames = [System.Collections.Generic.List[string]]::new()
        foreach ($code in @($common)) { [void]$commonNames.Add((ConvertTo-PciLinkSpeedName -Code ([int]$code))) }
        if ($commonNames.Count -eq 0) { [void]$commonNames.Add('none') }
        throw ('PCIe target speed write refused for {0}: requested {1}, but common parent/child supported speeds are {2}. Parent {3}: {4}; child {5}: {6}.' -f $requestedBdf, (ConvertTo-PciLinkSpeedName -Code $TargetSpeedCode), ([string]::Join(', ', $commonNames.ToArray())), [string]$parentBefore.Bdf, [string]$parentBefore.SupportedLinkSpeedNames, [string]$childBefore.Bdf, [string]$childBefore.SupportedLinkSpeedNames)
    }

    $newLnkctl2 = [uint32]((([uint32]$parentBefore.LinkControl2Raw) -band 0xFFF0) -bor ([uint32]($TargetSpeedCode -band 0xF)))
    if ([uint16]$newLnkctl2 -ne [uint16]$parentBefore.LinkControl2Raw) {
        Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentBefore.LinkControl2Offset) -Width 16 -Value $newLnkctl2
    }

    $retrainRaw = [uint32](([uint32]$parentBefore.LinkControlRaw) -bor 0x0020)
    Write-PciConfigValue -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) -Offset ([int]$parentBefore.LinkControlOffset) -Width 16 -Value $retrainRaw

    $deadline = [DateTime]::UtcNow.AddMilliseconds($TimeoutMs)
    $after = $null
    do {
        Start-Sleep -Milliseconds 100
        $after = Get-PciLinkState -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function)
        if (-not [bool]$after.LinkTraining -and [int]$after.CurrentLinkSpeedCode -eq [int]$TargetSpeedCode) { break }
    } while ([DateTime]::UtcNow -lt $deadline)

    if ($null -eq $after) { $after = Get-PciLinkState -Segment ([int]$link.Parent.Segment) -Bus ([int]$link.Parent.Bus) -Device ([int]$link.Parent.Device) -Function ([int]$link.Parent.Function) }
    if ([int]$after.TargetLinkSpeedCode -ne [int]$TargetSpeedCode -or [int]$after.CurrentLinkSpeedCode -ne [int]$TargetSpeedCode -or [bool]$after.LinkTraining) {
        throw ('PCIe target speed/retrain verification failed for {0}. Requested {1}; parent {2} target/read {3}, current/read {4}, training={5}. Before LNKCTL2=0x{6:X4}, LNKCTL=0x{7:X4}; after LNKCTL2=0x{8:X4}, LNKCTL=0x{9:X4}, LNKSTA=0x{10:X4}.' -f $requestedBdf, (ConvertTo-PciLinkSpeedName -Code $TargetSpeedCode), [string]$after.Bdf, [string]$after.TargetLinkSpeedName, [string]$after.CurrentLinkSpeedName, [bool]$after.LinkTraining, [int]$parentBefore.LinkControl2Raw, [int]$parentBefore.LinkControlRaw, [int]$after.LinkControl2Raw, [int]$after.LinkControlRaw, [int]$after.LinkStatusRaw)
    }
    try { $after | Add-Member -NotePropertyName RetainedRequestedBdf -NotePropertyValue $requestedBdf -Force } catch { }
    try { $after | Add-Member -NotePropertyName RetainedChildBdf -NotePropertyValue ([string]$childBefore.Bdf) -Force } catch { }
    try { $after | Add-Member -NotePropertyName DisplayText -NotePropertyValue (('{0}; retrain verified for requested {1} via downstream/root port {2}' -f [string]$after.DisplayText, $requestedBdf, [string]$parentBefore.Bdf)) -Force } catch { }
    return $after
}


function Set-PciMaxReadRequestSize {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateSet(128,256,512,1024,2048,4096)][int]$Bytes
    )
    $targetCode = ConvertFrom-PciPacketSizeBytes -Bytes $Bytes
    $before = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $newRaw = [uint32]((([uint32]$before.DeviceControlRaw) -band 0x8FFF) -bor (($targetCode -band 0x7) -shl 12))
    Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.DeviceControlOffset) -Width 16 -Value $newRaw
    $after = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ([int]$after.MrrsBytes -ne [int]$Bytes) {
        throw ('MRRS write verification failed for {0}. Requested {1} B, read back {2}. Before DEVCTL=0x{3:X4}; after DEVCTL=0x{4:X4}; DEVCTL ECAM=0x{5:X}.' -f $before.Bdf, $Bytes, $after.MrrsName, [int]$before.DeviceControlRaw, [int]$after.DeviceControlRaw, [uint64]$before.DevControlEcamAddress)
    }
    return $after
}


function Set-PciDeviceControlOrderingFeatures {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][bool]$EnableRelaxedOrdering,
        [Parameter(Mandatory=$true)][bool]$EnableExtendedTag,
        [Parameter(Mandatory=$true)][bool]$EnableTenBitTagRequester,
        [Parameter(Mandatory=$true)][bool]$EnableNoSnoop,
        [Parameter(Mandatory=$true)][bool]$EnableClockPowerManagement,
        [Parameter(Mandatory=$true)][bool]$EnableCommonClockConfiguration,
        [Parameter(Mandatory=$true)][bool]$EnableExtendedSync,
        [Parameter(Mandatory=$true)][bool]$EnableIdoRequest,
        [Parameter(Mandatory=$true)][bool]$EnableIdoCompletion,
        [Parameter(Mandatory=$true)][bool]$DisableHardwareAutonomousWidth,
        [Parameter(Mandatory=$true)][bool]$DisableHardwareAutonomousSpeed
    )
    $before = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if ($EnableExtendedTag -and -not [bool]$before.ExtendedTagSupported) {
        throw ('Extended Tag write refused for {0}: Device Capabilities bit 5 does not advertise Extended Tag Field Supported. DEVCAP=0x{1:X8}; DEVCTL=0x{2:X4}; cap 0x{3:X2}.' -f $before.Bdf, [uint32]$before.DeviceCapabilitiesRaw, [int]$before.DeviceControlRaw, [int]$before.CapabilityOffset)
    }
    if ($EnableClockPowerManagement -and -not [bool]$before.ClockPowerManagementSupported) {
        throw ('CLKREQ#/Clock Power Management write refused for {0}: Link Capabilities bit 18 does not advertise Clock Power Management support. LNKCAP=0x{1:X8}; LNKCTL=0x{2:X4}; cap 0x{3:X2}.' -f $before.Bdf, [uint32]$before.LinkCapabilitiesRaw, [int]$before.LinkControlRaw, [int]$before.CapabilityOffset)
    }
    $tenBitPolicy = $null
    if ($EnableTenBitTagRequester -or ([bool]$before.TenBitTagRequesterEnabled -ne [bool]$EnableTenBitTagRequester)) {
        $tenBitPolicy = Get-PciTenBitTagLinkPolicy -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    }
    if ($EnableTenBitTagRequester -and $null -ne $tenBitPolicy -and -not [bool]$tenBitPolicy.SafeToEnable) {
        throw ('10-Bit Tag Requester write refused for {0}: {1}' -f $before.Bdf, [string]$tenBitPolicy.Reason)
    }
    if ($EnableTenBitTagRequester -and $null -ne $tenBitPolicy -and [bool]$tenBitPolicy.PeerRequesterCanBeAligned -and $null -ne $tenBitPolicy.Peer -and -not [bool]$tenBitPolicy.Peer.TenBitTagRequesterEnabled) {
        $peerIdle = Wait-PciDeviceTransactionsIdle -Segment ([int]$tenBitPolicy.Peer.Segment) -Bus ([int]$tenBitPolicy.Peer.Bus) -Device ([int]$tenBitPolicy.Peer.Device) -Function ([int]$tenBitPolicy.Peer.Function) -TimeoutMs 1000
        $peerDevctl2 = [uint32](([uint32]$peerIdle.DeviceControl2Raw) -bor 0x1000)
        Write-PciConfigValue -Segment ([int]$peerIdle.Segment) -Bus ([int]$peerIdle.Bus) -Device ([int]$peerIdle.Device) -Function ([int]$peerIdle.Function) -Offset ([int]$peerIdle.DeviceControl2Offset) -Width 16 -Value $peerDevctl2
    }
    if ($null -ne $tenBitPolicy -and [bool]$before.TenBitTagRequesterEnabled -ne [bool]$EnableTenBitTagRequester) {
        [void](Wait-PciDeviceTransactionsIdle -Segment $Segment -Bus $Bus -Device $Device -Function $Function -TimeoutMs 1000)
    }
    if (($EnableIdoRequest -or $EnableIdoCompletion) -and -not [bool]$before.HasDevice2Registers) {
        throw ('IDO write refused for {0}: Device Control 2 is unavailable. PCIe capability version={1}; Device2Error={2}; cap 0x{3:X2}.' -f $before.Bdf, [int]$before.PcieCapabilityVersion, [string]$before.Device2Error, [int]$before.CapabilityOffset)
    }
    if ($DisableHardwareAutonomousSpeed -and -not [bool]$before.HasLink2Registers) {
        throw ('Hardware Autonomous Speed Disable write refused for {0}: Link Control 2 is unavailable. PCIe capability version={1}; Link2Error={2}; cap 0x{3:X2}.' -f $before.Bdf, [int]$before.PcieCapabilityVersion, [string]$before.Link2Error, [int]$before.CapabilityOffset)
    }
    $newRaw = [uint32]$before.DeviceControlRaw
    if ($EnableRelaxedOrdering) { $newRaw = [uint32]($newRaw -bor 0x0010) } else { $newRaw = [uint32]($newRaw -band 0xFFEF) }
    if ($EnableExtendedTag) { $newRaw = [uint32]($newRaw -bor 0x0100) } else { $newRaw = [uint32]($newRaw -band 0xFEFF) }
    if ($EnableNoSnoop) { $newRaw = [uint32]($newRaw -bor 0x0800) } else { $newRaw = [uint32]($newRaw -band 0xF7FF) }
    if ([uint16]$newRaw -ne [uint16]$before.DeviceControlRaw) {
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.DeviceControlOffset) -Width 16 -Value $newRaw
    }
    $newLinkRaw = [uint32](([uint32]$before.LinkControlRaw) -band 0xFFDF)
    if ($EnableCommonClockConfiguration) { $newLinkRaw = [uint32]($newLinkRaw -bor 0x0040) } else { $newLinkRaw = [uint32]($newLinkRaw -band 0xFFBF) }
    if ($EnableExtendedSync) { $newLinkRaw = [uint32]($newLinkRaw -bor 0x0080) } else { $newLinkRaw = [uint32]($newLinkRaw -band 0xFF7F) }
    if ($EnableClockPowerManagement) { $newLinkRaw = [uint32]($newLinkRaw -bor 0x0100) } else { $newLinkRaw = [uint32]($newLinkRaw -band 0xFEFF) }
    if ($DisableHardwareAutonomousWidth) { $newLinkRaw = [uint32]($newLinkRaw -bor 0x0200) } else { $newLinkRaw = [uint32]($newLinkRaw -band 0xFDFF) }
    if ([uint16]$newLinkRaw -ne [uint16](([uint32]$before.LinkControlRaw) -band 0xFFDF)) {
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.LinkControlOffset) -Width 16 -Value $newLinkRaw
    }
    $newDevCtl2Raw = [uint32]$before.DeviceControl2Raw
    if ($EnableIdoRequest) { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -bor 0x0100) } else { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -band 0xFEFF) }
    if ($EnableIdoCompletion) { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -bor 0x0200) } else { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -band 0xFDFF) }
    if ($EnableTenBitTagRequester) { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -bor 0x1000) } else { $newDevCtl2Raw = [uint32]($newDevCtl2Raw -band 0xEFFF) }
    if ([bool]$before.HasDevice2Registers -and [uint16]$newDevCtl2Raw -ne [uint16]$before.DeviceControl2Raw) {
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.DeviceControl2Offset) -Width 16 -Value $newDevCtl2Raw
    }
    $newLinkCtl2Raw = [uint32]$before.LinkControl2Raw
    if ($DisableHardwareAutonomousSpeed) { $newLinkCtl2Raw = [uint32]($newLinkCtl2Raw -bor 0x0020) } else { $newLinkCtl2Raw = [uint32]($newLinkCtl2Raw -band 0xFFDF) }
    if ([bool]$before.HasLink2Registers -and [uint16]$newLinkCtl2Raw -ne [uint16]$before.LinkControl2Raw) {
        Write-PciConfigValue -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Offset ([int]$before.LinkControl2Offset) -Width 16 -Value $newLinkCtl2Raw
    }
    $after = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $failures = [System.Collections.Generic.List[string]]::new()
    if ($EnableTenBitTagRequester -and $null -ne $tenBitPolicy -and [bool]$tenBitPolicy.PeerRequesterCanBeAligned -and $null -ne $tenBitPolicy.Peer) {
        try {
            $peerAfter = Get-PciDevice2TenBitTagState -Segment ([int]$tenBitPolicy.Peer.Segment) -Bus ([int]$tenBitPolicy.Peer.Bus) -Device ([int]$tenBitPolicy.Peer.Device) -Function ([int]$tenBitPolicy.Peer.Function)
            if ([bool]$peerAfter.TenBitTagRequesterSupported -and -not [bool]$peerAfter.TenBitTagRequesterEnabled) { [void]$failures.Add(('10-Bit Tag peer {0} Requester Enable did not stay set' -f [string]$peerAfter.Bdf)) }
        } catch { [void]$failures.Add(('10-Bit Tag peer verification failed: {0}' -f $_.Exception.Message)) }
    }
    if ([bool]$after.RelaxedOrderingEnabled -ne [bool]$EnableRelaxedOrdering) { [void]$failures.Add(('Relaxed requested {0}, read {1}' -f [bool]$EnableRelaxedOrdering, [bool]$after.RelaxedOrderingEnabled)) }
    if ([bool]$after.ExtendedTagEnabled -ne [bool]$EnableExtendedTag) { [void]$failures.Add(('ExtTag requested {0}, read {1}' -f [bool]$EnableExtendedTag, [bool]$after.ExtendedTagEnabled)) }
    if ([bool]$after.NoSnoopEnabled -ne [bool]$EnableNoSnoop) { [void]$failures.Add(('NoSnoop requested {0}, read {1}' -f [bool]$EnableNoSnoop, [bool]$after.NoSnoopEnabled)) }
    if ([bool]$after.ClockPowerManagementEnabled -ne [bool]$EnableClockPowerManagement) { [void]$failures.Add(('CLKREQ requested {0}, read {1}' -f [bool]$EnableClockPowerManagement, [bool]$after.ClockPowerManagementEnabled)) }
    if ([bool]$after.CommonClockConfiguration -ne [bool]$EnableCommonClockConfiguration) { [void]$failures.Add(('Common Clock requested {0}, read {1}' -f [bool]$EnableCommonClockConfiguration, [bool]$after.CommonClockConfiguration)) }
    if ([bool]$after.ExtendedSync -ne [bool]$EnableExtendedSync) { [void]$failures.Add(('Extended Sync requested {0}, read {1}' -f [bool]$EnableExtendedSync, [bool]$after.ExtendedSync)) }
    if ([bool]$after.IdoRequestEnabled -ne [bool]$EnableIdoRequest) { [void]$failures.Add(('IDO Request requested {0}, read {1}' -f [bool]$EnableIdoRequest, [bool]$after.IdoRequestEnabled)) }
    if ([bool]$after.IdoCompletionEnabled -ne [bool]$EnableIdoCompletion) { [void]$failures.Add(('IDO Completion requested {0}, read {1}' -f [bool]$EnableIdoCompletion, [bool]$after.IdoCompletionEnabled)) }
    if ([bool]$after.TenBitTagRequesterEnabled -ne [bool]$EnableTenBitTagRequester) { [void]$failures.Add(('10-Bit Tag Requester requested {0}, read {1}' -f [bool]$EnableTenBitTagRequester, [bool]$after.TenBitTagRequesterEnabled)) }
    if ([bool]$after.HardwareAutonomousWidthDisable -ne [bool]$DisableHardwareAutonomousWidth) { [void]$failures.Add(('Hardware Autonomous Width Disable requested {0}, read {1}' -f [bool]$DisableHardwareAutonomousWidth, [bool]$after.HardwareAutonomousWidthDisable)) }
    if ([bool]$before.HasLink2Registers -and [bool]$after.HardwareAutonomousSpeedDisable -ne [bool]$DisableHardwareAutonomousSpeed) { [void]$failures.Add(('Hardware Autonomous Speed Disable requested {0}, read {1}' -f [bool]$DisableHardwareAutonomousSpeed, [bool]$after.HardwareAutonomousSpeedDisable)) }
    if ($failures.Count -gt 0) {
        throw ('PCIe Device/Link Control write verification failed for {0}. {1}. Before DEVCTL=0x{2:X4} DEVCTL2=0x{3:X4} LNKCTL=0x{4:X4} LNKCTL2=0x{5:X4}; attempted DEVCTL=0x{6:X4} DEVCTL2=0x{7:X4} LNKCTL=0x{8:X4} LNKCTL2=0x{9:X4}; after DEVCTL=0x{10:X4} DEVCTL2=0x{11:X4} LNKCTL=0x{12:X4} LNKCTL2=0x{13:X4}; DEVCAP=0x{14:X8}; DEVCAP2=0x{15:X8}; LNKCAP=0x{16:X8}; LNKCAP2=0x{17:X8}; DEVCTL ECAM=0x{18:X}; DEVCTL2 ECAM=0x{19:X}; LNKCTL ECAM=0x{20:X}; LNKCTL2 ECAM=0x{21:X}.' -f $before.Bdf, ([string]::Join('; ', $failures.ToArray())), [int]$before.DeviceControlRaw, [int]$before.DeviceControl2Raw, [int]$before.LinkControlRaw, [int]$before.LinkControl2Raw, [int]$newRaw, [int]$newDevCtl2Raw, [int]$newLinkRaw, [int]$newLinkCtl2Raw, [int]$after.DeviceControlRaw, [int]$after.DeviceControl2Raw, [int]$after.LinkControlRaw, [int]$after.LinkControl2Raw, [uint32]$before.DeviceCapabilitiesRaw, [uint32]$before.DeviceCapabilities2Raw, [uint32]$before.LinkCapabilitiesRaw, [uint32]$before.LinkCapabilities2Raw, [uint64]$before.DevControlEcamAddress, [uint64]$before.DeviceControl2EcamAddress, [uint64]$before.LinkControlEcamAddress, [uint64]$before.LinkControl2EcamAddress)
    }
    $tenBitPeerText = ''
    if ($EnableTenBitTagRequester -and $null -ne $tenBitPolicy -and $null -ne $tenBitPolicy.Peer) { $tenBitPeerText = (' Peer10TagReqAligned={0}:{1}' -f [string]$tenBitPolicy.Peer.Bdf, [bool]$tenBitPolicy.PeerRequesterCanBeAligned) }
    try { $after | Add-Member -NotePropertyName DisplayText -NotePropertyValue (('{0}; DEV/LNK verified Relaxed={1} ExtTag={2} TenBitTagReq={3}{12} NoSnoop={4} CLKREQ={5} CCC={6} ExtSync={7} IDOReq={8} IDOCpl={9} HAWDis={10} HASDis={11}' -f [string]$after.DisplayText, [bool]$EnableRelaxedOrdering, [bool]$EnableExtendedTag, [bool]$EnableTenBitTagRequester, [bool]$EnableNoSnoop, [bool]$EnableClockPowerManagement, [bool]$EnableCommonClockConfiguration, [bool]$EnableExtendedSync, [bool]$EnableIdoRequest, [bool]$EnableIdoCompletion, [bool]$DisableHardwareAutonomousWidth, [bool]$DisableHardwareAutonomousSpeed, $tenBitPeerText)) -Force } catch { }
    return $after
}

function Get-PciMpsPathNodeKey {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    return ('{0}:{1:X2}:{2:X2}.{3}' -f $Segment, $Bus, $Device, $Function)
}

function Add-PciMpsPathNode {
    param(
        [Parameter(Mandatory=$true)][System.Collections.Generic.List[object]]$Nodes,
        [Parameter(Mandatory=$true)][System.Collections.Generic.HashSet[string]]$Seen,
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][int]$Depth,
        [Parameter(Mandatory=$true)][string]$Role
    )
    $key = Get-PciMpsPathNodeKey -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    if (-not $Seen.Add($key)) { return }
    $state = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    [void]$Nodes.Add([pscustomobject]@{
        Key = $key
        Segment = $Segment
        Bus = $Bus
        Device = $Device
        Function = $Function
        Bdf = [string]$state.Bdf
        Depth = $Depth
        Role = $Role
        State = $state
    })
}

function Get-PciMpsPathContext {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function
    )
    $nodes = [System.Collections.Generic.List[object]]::new()
    $seen = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    $requestedKey = Get-PciMpsPathNodeKey -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $requestedBdf = [DeviceTweakerPciEcam]::FormatBdf($Segment,$Bus,$Device,$Function)
    $portType = -1
    try { $portType = Get-PciExpressPortType -Segment $Segment -Bus $Bus -Device $Device -Function $Function } catch { }
    Add-PciMpsPathNode -Nodes $nodes -Seen $seen -Segment $Segment -Bus $Bus -Device $Device -Function $Function -Depth 0 -Role 'Requested'
    if ($portType -eq 4 -or $portType -eq 6) {
        $child = Find-PciDownstreamChildFunction -Segment $Segment -Bus $Bus -Device $Device -Function $Function
        Add-PciMpsPathNode -Nodes $nodes -Seen $seen -Segment ([int]$child.Segment) -Bus ([int]$child.Bus) -Device ([int]$child.Device) -Function ([int]$child.Function) -Depth -1 -Role 'DownstreamChild'
    }
    $currentSegment = $Segment
    $currentBus = $Bus
    $currentDevice = $Device
    $currentFunction = $Function
    $depth = 1
    while ($true) {
        $parent = $null
        try { $parent = Find-PciParentBridge -Segment $currentSegment -Bus $currentBus -Device $currentDevice -Function $currentFunction } catch { break }
        if ($null -eq $parent) { break }
        $parentKey = Get-PciMpsPathNodeKey -Segment ([int]$parent.Segment) -Bus ([int]$parent.Bus) -Device ([int]$parent.Device) -Function ([int]$parent.Function)
        if ($seen.Contains($parentKey)) { break }
        Add-PciMpsPathNode -Nodes $nodes -Seen $seen -Segment ([int]$parent.Segment) -Bus ([int]$parent.Bus) -Device ([int]$parent.Device) -Function ([int]$parent.Function) -Depth $depth -Role 'UpstreamBridge'
        $currentSegment = [int]$parent.Segment
        $currentBus = [int]$parent.Bus
        $currentDevice = [int]$parent.Device
        $currentFunction = [int]$parent.Function
        $depth++
        if ($depth -gt 64) { throw ('PCIe MPS path resolve exceeded 64 upstream hops for requested BDF {0}; aborting to avoid a malformed bridge-loop traversal.' -f $requestedBdf) }
    }
    if ($nodes.Count -eq 0) { throw ('PCIe MPS path resolve failed for {0}: no PCIe Device Control nodes were collected.' -f $requestedBdf) }
    [pscustomobject]@{
        RequestedKey = $requestedKey
        RequestedBdf = $requestedBdf
        RequestedPortType = $portType
        RequestedPortTypeName = (ConvertTo-PciExpressPortTypeName -PortType $portType)
        Nodes = $nodes.ToArray()
    }
}

function Set-PciMaxPayloadSize {
    param(
        [Parameter(Mandatory=$true)][int]$Segment,
        [Parameter(Mandatory=$true)][int]$Bus,
        [Parameter(Mandatory=$true)][int]$Device,
        [Parameter(Mandatory=$true)][int]$Function,
        [Parameter(Mandatory=$true)][ValidateSet(128,256,512,1024,2048,4096)][int]$Bytes
    )
    $targetCode = ConvertFrom-PciPacketSizeBytes -Bytes $Bytes
    $path = Get-PciMpsPathContext -Segment $Segment -Bus $Bus -Device $Device -Function $Function
    $nodes = @($path.Nodes)
    $minCapCode = 5
    $minCapBdf = $null
    $beforeText = [System.Collections.Generic.List[string]]::new()
    foreach ($node in $nodes) {
        $capCode = [int]$node.State.MaxPayloadCode
        if ($capCode -lt $minCapCode) { $minCapCode = $capCode; $minCapBdf = [string]$node.Bdf }
        [void]$beforeText.Add(('{0}/{1}: MPS {2}, cap {3}, DEVCTL 0x{4:X4}' -f [string]$node.Bdf, [string]$node.Role, [string]$node.State.MpsName, [string]$node.State.MaxPayloadName, [int]$node.State.DeviceControlRaw))
    }
    $minCapBytes = ConvertTo-PciPacketSizeBytes -Encoding $minCapCode
    if ($targetCode -gt $minCapCode) {
        throw ('PCIe MPS write refused for {0}. Requested {1} B exceeds path-wide Max Payload Size Supported {2} B at {3}. Path: {4}' -f [string]$path.RequestedBdf, $Bytes, $minCapBytes, $minCapBdf, ([string]::Join(' | ', $beforeText.ToArray())))
    }
    $upstreamFirst = @($nodes | Sort-Object -Property @{ Expression = { $_.Depth }; Descending = $true })
    $downstreamFirst = @($nodes | Sort-Object -Property @{ Expression = { $_.Depth }; Descending = $false })
    foreach ($node in $upstreamFirst) {
        $current = Get-PciLinkState -Segment ([int]$node.Segment) -Bus ([int]$node.Bus) -Device ([int]$node.Device) -Function ([int]$node.Function)
        if ([int]$current.MpsCode -ge $targetCode) { continue }
        $newRaw = [uint32]((([uint32]$current.DeviceControlRaw) -band 0xFF1F) -bor (([uint32]($targetCode -band 0x7)) -shl 5))
        Write-PciConfigValue -Segment ([int]$node.Segment) -Bus ([int]$node.Bus) -Device ([int]$node.Device) -Function ([int]$node.Function) -Offset ([int]$current.DeviceControlOffset) -Width 16 -Value $newRaw
    }
    foreach ($node in $downstreamFirst) {
        $current = Get-PciLinkState -Segment ([int]$node.Segment) -Bus ([int]$node.Bus) -Device ([int]$node.Device) -Function ([int]$node.Function)
        if ([int]$current.MpsCode -le $targetCode) { continue }
        $newRaw = [uint32]((([uint32]$current.DeviceControlRaw) -band 0xFF1F) -bor (([uint32]($targetCode -band 0x7)) -shl 5))
        Write-PciConfigValue -Segment ([int]$node.Segment) -Bus ([int]$node.Bus) -Device ([int]$node.Device) -Function ([int]$node.Function) -Offset ([int]$current.DeviceControlOffset) -Width 16 -Value $newRaw
    }
    $afterNodes = [System.Collections.Generic.List[object]]::new()
    $failed = [System.Collections.Generic.List[string]]::new()
    $pathSummary = [System.Collections.Generic.List[string]]::new()
    $requestedAfter = $null
    foreach ($node in $nodes) {
        $after = Get-PciLinkState -Segment ([int]$node.Segment) -Bus ([int]$node.Bus) -Device ([int]$node.Device) -Function ([int]$node.Function)
        [void]$afterNodes.Add($after)
        [void]$pathSummary.Add(('{0}/{1}: MPS {2}, cap {3}, DEVCTL 0x{4:X4}' -f [string]$after.Bdf, [string]$node.Role, [string]$after.MpsName, [string]$after.MaxPayloadName, [int]$after.DeviceControlRaw))
        if ([int]$after.MpsBytes -ne [int]$Bytes) { [void]$failed.Add(('{0} read {1}' -f [string]$after.Bdf, [string]$after.MpsName)) }
        if ([string]::Equals([string]$node.Key, [string]$path.RequestedKey, [System.StringComparison]::OrdinalIgnoreCase)) { $requestedAfter = $after }
    }
    if ($failed.Count -gt 0) {
        throw ('PCIe MPS path-wide write verification failed for {0}. Requested {1} B. Failed nodes: {2}. Before: {3}. After: {4}' -f [string]$path.RequestedBdf, $Bytes, ([string]::Join(', ', $failed.ToArray())), ([string]::Join(' | ', $beforeText.ToArray())), ([string]::Join(' | ', $pathSummary.ToArray())))
    }
    if ($null -eq $requestedAfter) { $requestedAfter = Get-PciLinkState -Segment $Segment -Bus $Bus -Device $Device -Function $Function }
    $pathText = [string]::Join(' | ', $pathSummary.ToArray())
    try { $requestedAfter | Add-Member -NotePropertyName MpsPathMinimumBytes -NotePropertyValue ([int]$minCapBytes) -Force } catch { }
    try { $requestedAfter | Add-Member -NotePropertyName MpsPathSummary -NotePropertyValue $pathText -Force } catch { }
    try { $requestedAfter | Add-Member -NotePropertyName DisplayText -NotePropertyValue (('{0}; path MPS {1} B verified [{2}]' -f [string]$requestedAfter.DisplayText, $Bytes, $pathText)) -Force } catch { }
    return $requestedAfter
}

function ConvertTo-DeviceTweakerEnumRelativePath {
    param([object]$Path)
    if ($null -eq $Path) { return $null }
    $p = [string]$Path
    if ([string]::IsNullOrWhiteSpace($p)) { return $null }
    $p = $p -replace '^Microsoft\.PowerShell\.Core\\Registry::',''
    $p = $p -replace '^HKLM:\\',''
    $p = $p -replace '^HKEY_LOCAL_MACHINE\\',''
    $p = $p.Trim('\')
    $prefix = 'SYSTEM\CurrentControlSet\Enum\'
    if ($p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) { return $p.Substring($prefix.Length) }
    return $p
}

function Resolve-PciAspmBdfForDevice {
    param(
        [Parameter(Mandatory=$true)][object]$Device,
        [hashtable]$Controls
    )
    $registryPath = $null
    if ($Controls -and $Controls.ContainsKey('PciAspmRegistryPath')) { $registryPath = [string]$Controls['PciAspmRegistryPath'] }
    if ([string]::IsNullOrWhiteSpace($registryPath)) { $registryPath = Get-PropValue $Device 'RegistryPath' }
    if ([string]::IsNullOrWhiteSpace($registryPath)) { $registryPath = Get-PropValue $Device 'PSPath' }
    $rel = ConvertTo-DeviceTweakerEnumRelativePath -Path $registryPath
    if ([string]::IsNullOrWhiteSpace($rel)) { throw 'Cannot resolve PCI ASPM BDF: device registry path is empty.' }
    $regKey = 'HKLM:\SYSTEM\CurrentControlSet\Enum\' + $rel
    $loc = $null
    try { $loc = [string](Get-ItemProperty -LiteralPath $regKey -Name 'LocationInformation' -ErrorAction Stop).LocationInformation } catch { }
    if ([string]::IsNullOrWhiteSpace($loc)) {
        $inst = $rel
        try {
            $prop = Get-PnpDeviceProperty -InstanceId $inst -KeyName 'DEVPKEY_Device_LocationInfo' -ErrorAction Stop
            if ($null -ne $prop -and $null -ne $prop.Data) { $loc = [string]$prop.Data }
        } catch { }
    }
    if ([string]::IsNullOrWhiteSpace($loc)) { throw ('Cannot resolve PCI ASPM BDF for registry path {0}: LocationInformation is empty or unavailable.' -f $regKey) }
    $parsed = [DeviceTweakerPathHelpers]::ParseBdfLocation($loc)
    if ($null -eq $parsed -or -not $parsed.Success) { throw ('Cannot parse PCI BDF from LocationInformation "{0}" for {1}.' -f $loc, $regKey) }
    [pscustomobject]@{
        Segment = 0
        Bus = [int]$parsed.Bus
        Device = [int]$parsed.Device
        Function = [int]$parsed.Function
        RegistryPath = $regKey
        LocationInformation = $loc
        Bdf = [DeviceTweakerPciEcam]::FormatBdf(0, [int]$parsed.Bus, [int]$parsed.Device, [int]$parsed.Function)
    }
}

function Set-PciAspmControlsFromState {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)]$State
    )
    $combo = $Controls['PciAspmCombo']
    $label = $Controls['PciAspmStatusLabel']
    if ($combo -is [System.Windows.Forms.ComboBox]) {
        $idx = [Math]::Max(0, [Math]::Min(3, [int]$State.Mode))
        $combo.SelectedIndex = $idx
        $combo.Enabled = $true
    }
    if ($label -is [System.Windows.Forms.Label]) {
        $label.Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
    }
    $button = $Controls['PciAspmSetButton']
    if ($button -is [System.Windows.Forms.Button]) {
        $button.Enabled = $true
        try { $button.Invalidate() } catch { }
    }
}

function Get-AsyncPciAspmWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'ConvertTo-PciAspmModeName'),
        (Get-FunctionDefinitionText 'ConvertTo-PciAspmSupportedNames'),
        (Get-FunctionDefinitionText 'Read-PciConfigValue'),
        (Get-FunctionDefinitionText 'Get-PciExpressCapabilityContext'),
        (Get-FunctionDefinitionText 'Get-PciExtendedCapabilityContext'),
        (Get-FunctionDefinitionText 'Test-PciFunctionPresent'),
        (Get-FunctionDefinitionText 'Get-PciHeaderType'),
        (Get-FunctionDefinitionText 'Test-PciBridgeFunction'),
        (Get-FunctionDefinitionText 'Get-PciBridgeBusNumbers'),
        (Get-FunctionDefinitionText 'Get-PciExpressPortType'),
        (Get-FunctionDefinitionText 'ConvertTo-PciExpressPortTypeName'),
        (Get-FunctionDefinitionText 'Test-PciExtendedCapabilityPresent'),
        (Get-FunctionDefinitionText 'Find-PciDownstreamChildFunction'),
        (Get-FunctionDefinitionText 'Find-PciParentBridge'),
        (Get-FunctionDefinitionText 'Resolve-PciAspmLinkContext'),
        (Get-FunctionDefinitionText 'Get-PciAspmLinkChildFunctions'),
        (Get-FunctionDefinitionText 'Get-PciAspmPortState'),
        (Get-FunctionDefinitionText 'Get-PciAspm')
    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$state = Get-PciAspm -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function)
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

