    }
}
return ,`$results.ToArray()
"@
}

function Add-DeviceTweakerPciAspmFlatResult {
    param(
        [System.Collections.Generic.List[object]]$Target,
        [AllowNull()][object]$Value
    )
    if ($null -eq $Target -or $null -eq $Value) { return }

    $base = $Value
    try {
        if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject }
    } catch { $base = $Value }

    if ($base -is [System.Array]) {
        foreach ($child in @($base)) { Add-DeviceTweakerPciAspmFlatResult -Target $Target -Value $child }
        return
    }

    [void]$Target.Add($Value)
}

function Apply-AsyncPciAspmResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }

    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciAspmFlatResult -Target $flatResults -Value $raw }

    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAspmCombo')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciAspmStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciAspmControlsFromState -Controls $ctrls -State $result.State
        }
        else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe ASPM error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe ASPM] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ASPM] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                $label.Text = ('ERR: {0}' -f $errText)
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
}

function Set-PciAspmHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    if ([string]::IsNullOrWhiteSpace($errText)) { $errText = 'Unknown PCIe ASPM hydration error.' }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAspmStatusLabel')) { return }
        $label = $ctrls['PciAspmStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) {
            $label.Text = ('ERR: {0}' -f $errText)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
        }
        return
    }
}

function Start-AsyncPciAspmHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAspmCombo')) { continue }
        $label = $ctrls['PciAspmStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciAspmReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe ASPM read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe ASPM] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ASPM] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }

    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciAspmHydration' -ScriptText (Get-AsyncPciAspmWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciAspmResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred PCIe ASPM hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe ASPM hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
            Set-PciAspmHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciAspmApply {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$Mode,[System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciAspmStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) {
            throw 'Cannot build PCIe ASPM apply key: RegistryPath and DeviceKey are empty.'
        }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; Mode = $Mode }
        Start-PolledRunspaceTask -TaskName 'PciAspmApply' -ScriptText (Get-AsyncPciAspmApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciAspmResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe ASPM] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ASPM] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}


function Set-PciLtrObffControlsFromState {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)]$State
    )
    $check = $Controls['PciLtrEnableCheck']
    if ($check -is [System.Windows.Forms.CheckBox]) {
        $check.Checked = [bool]$State.LtrEnabled
        $check.Enabled = [bool]$State.LtrSupported
    }
    $combo = $Controls['PciObffCombo']
    if ($combo -is [System.Windows.Forms.ComboBox]) {
        $support = [int]$State.ObffSupportedMask
        $mode = [Math]::Max(0, [Math]::Min(3, [int]$State.ObffMode))
        $modeText = switch ($mode) { 1 { 'OBFF MsgA' } 2 { 'OBFF MsgB' } 3 { 'OBFF WAKE#' } default { 'OBFF OFF' } }
        $items = New-Object System.Collections.Generic.List[string]
        [void]$items.Add('OBFF OFF')
        if ($support -eq 1 -or $support -eq 3) { [void]$items.Add('OBFF MsgA'); [void]$items.Add('OBFF MsgB') }
        if ($support -eq 2 -or $support -eq 3) { [void]$items.Add('OBFF WAKE#') }
        if (-not $items.Contains($modeText)) { [void]$items.Add($modeText) }
        try { $combo.BeginUpdate() } catch { }
        try {
            $combo.Items.Clear()
            foreach ($item in $items) { [void]$combo.Items.Add($item) }
            $sel = [Math]::Max(0, $combo.Items.IndexOf($modeText))
            $combo.SelectedIndex = $sel
        } finally {
            try { $combo.EndUpdate() } catch { }
        }
        $combo.Enabled = ($support -ne 0)
    }
    $nudSnoop = $Controls['PciLtrMaxSnoopLatencyNsValue']
    if ($nudSnoop -is [System.Windows.Forms.NumericUpDown]) {
        $nudSnoop.Enabled = [bool]$State.LtrExtendedCapabilityPresent
        if ([bool]$State.LtrExtendedCapabilityPresent) {
            $value = [decimal][uint64]$State.LtrMaxSnoopLatencyNs
            if ($value -lt $nudSnoop.Minimum) { $value = $nudSnoop.Minimum }
            if ($value -gt $nudSnoop.Maximum) { $value = $nudSnoop.Maximum }
            $nudSnoop.Value = $value
        } else {
            try { $nudSnoop.Value = $nudSnoop.Minimum } catch { }
        }
    }
    $nudNoSnoop = $Controls['PciLtrMaxNoSnoopLatencyNsValue']
    if ($nudNoSnoop -is [System.Windows.Forms.NumericUpDown]) {
        $nudNoSnoop.Enabled = [bool]$State.LtrExtendedCapabilityPresent
        if ([bool]$State.LtrExtendedCapabilityPresent) {
            $value = [decimal][uint64]$State.LtrMaxNoSnoopLatencyNs
            if ($value -lt $nudNoSnoop.Minimum) { $value = $nudNoSnoop.Minimum }
            if ($value -gt $nudNoSnoop.Maximum) { $value = $nudNoSnoop.Maximum }
            $nudNoSnoop.Value = $value
        } else {
            try { $nudNoSnoop.Value = $nudNoSnoop.Minimum } catch { }
        }
    }
    $button = $Controls['PciLtrObffSetButton']
    if ($button -is [System.Windows.Forms.Button]) {
        $button.Enabled = ([bool]$State.LtrSupported -or ([int]$State.ObffSupportedMask -ne 0) -or [bool]$State.LtrExtendedCapabilityPresent)
    }
    $label = $Controls['PciLtrObffStatusLabel']
    if ($label -is [System.Windows.Forms.Label]) {
        $label.Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
    }
}

function Get-AsyncPciLtrObffWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'Read-PciConfigValue'),
        (Get-FunctionDefinitionText 'Write-PciConfigValue'),
        (Get-FunctionDefinitionText 'Get-PciExpressCapabilityContext'),
        (Get-FunctionDefinitionText 'Get-PciExtendedCapabilityContext'),
        (Get-FunctionDefinitionText 'ConvertTo-PciObffModeName'),
        (Get-FunctionDefinitionText 'ConvertTo-PciObffSupportName'),
        (Get-FunctionDefinitionText 'Test-PciObffModeSupported'),
        (Get-FunctionDefinitionText 'Get-PciLtrLatencyMultiplier'),
        (Get-FunctionDefinitionText 'ConvertTo-PciLtrLatencyNs'),
        (Get-FunctionDefinitionText 'ConvertFrom-PciLtrLatencyNs'),
        (Get-FunctionDefinitionText 'Format-PciLtrLatencyNs'),
        (Get-FunctionDefinitionText 'Get-PciLtrExtendedCapabilityState'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerNullableValueSpecified'),
        (Get-FunctionDefinitionText 'Get-PciLtrObffState')
    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$state = Get-PciLtrObffState -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function)
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

