function Add-DeviceTweakerPciLtrObffFlatResult {
    param(
        [System.Collections.Generic.List[object]]$Target,
        [AllowNull()][object]$Value
    )
    if ($null -eq $Target -or $null -eq $Value) { return }
    $base = $Value
    try {
        if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject }
    } catch { $base = $Value }
    if ($base -is [System.Array]) {
        foreach ($child in @($base)) { Add-DeviceTweakerPciLtrObffFlatResult -Target $Target -Value $child }
        return
    }
    [void]$Target.Add($Value)
}

function Apply-AsyncPciLtrObffResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciLtrObffFlatResult -Target $flatResults -Value $raw }
    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLtrObffStatusLabel')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciLtrObffStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciLtrObffControlsFromState -Controls $ctrls -State $result.State
        }
        else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe LTR/OBFF error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe LTR/OBFF] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe LTR/OBFF] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                $label.Text = ('ERR: {0}' -f $errText)
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
}

function Set-PciLtrObffHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    if ([string]::IsNullOrWhiteSpace($errText)) { $errText = 'Unknown PCIe LTR/OBFF hydration error.' }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLtrObffStatusLabel')) { return }
        $label = $ctrls['PciLtrObffStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) {
            $label.Text = ('ERR: {0}' -f $errText)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
        }
        return
    }
}

function Start-AsyncPciLtrObffHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLtrObffStatusLabel')) { continue }
        $label = $ctrls['PciLtrObffStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciLtrObffReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe LTR/OBFF read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe LTR/OBFF] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe LTR/OBFF] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }
    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciLtrObffHydration' -ScriptText (Get-AsyncPciLtrObffWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciLtrObffResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred PCIe LTR/OBFF hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe LTR/OBFF hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
            Set-PciLtrObffHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciLtrObffApply {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][bool]$EnableLtr,[Parameter(Mandatory=$true)][ValidateRange(0,3)][int]$ObffMode,[AllowNull()][object]$MaxSnoopLatencyNs = $null,[AllowNull()][object]$MaxNoSnoopLatencyNs = $null,[System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciLtrObffStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing LTR/OBFF...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe LTR/OBFF apply key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; EnableLtr = [bool]$EnableLtr; ObffMode = [int]$ObffMode; MaxSnoopLatencyNs = $MaxSnoopLatencyNs; MaxNoSnoopLatencyNs = $MaxNoSnoopLatencyNs }
        Start-PolledRunspaceTask -TaskName 'PciLtrObffApply' -ScriptText (Get-AsyncPciLtrObffApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciLtrObffResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET LTR/OBFF'; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET LTR/OBFF'; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe LTR/OBFF] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe LTR/OBFF] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET LTR/OBFF'; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}


function Set-PciL1ssControlsFromState {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)]$State
    )
    $mask = [int]$State.EnabledMask
    $support = [int]$State.SupportedMask
    $l1ssControlsEnabled = ([bool]$State.L1ssImplemented -and ($support -ne 0))
    $entries = @(
        [pscustomobject]@{ Key = 'PciL1ssAspmL11Check'; Bit = 0x8 },
        [pscustomobject]@{ Key = 'PciL1ssAspmL12Check'; Bit = 0x4 },
        [pscustomobject]@{ Key = 'PciL1ssPciPmL11Check'; Bit = 0x2 },
        [pscustomobject]@{ Key = 'PciL1ssPciPmL12Check'; Bit = 0x1 }
    )
    foreach ($entry in $entries) {
        $keyName = [string]$entry.Key
        $chk = $Controls[$keyName]
        $bit = [int]$entry.Bit
        if ($chk -is [System.Windows.Forms.CheckBox]) {
            $chk.Checked = (($mask -band $bit) -ne 0)
            $chk.Enabled = (($support -band $bit) -ne 0)
            try { $chk.Invalidate() } catch { }
        }
    }
    $nud = $Controls['PciL1ssThresholdNsValue']
    if ($nud -is [System.Windows.Forms.NumericUpDown]) {
        $value = [decimal][uint64]$State.LtrL12ThresholdNs
        if ($value -lt $nud.Minimum) { $value = $nud.Minimum }
        if ($value -gt $nud.Maximum) { $value = $nud.Maximum }
        $nud.Value = $value
        $nud.Enabled = $l1ssControlsEnabled
        try { $nud.Invalidate() } catch { }
    }
    $nudCmrt = $Controls['PciL1ssCommonModeRestoreUsValue']
    if ($nudCmrt -is [System.Windows.Forms.NumericUpDown]) {
        $cmrtValue = [decimal][int]$State.CommonModeRestoreTimeUs
        if ($cmrtValue -lt $nudCmrt.Minimum) { $cmrtValue = $nudCmrt.Minimum }
        if ($cmrtValue -gt $nudCmrt.Maximum) { $cmrtValue = $nudCmrt.Maximum }
        $nudCmrt.Value = $cmrtValue
        $nudCmrt.Enabled = $l1ssControlsEnabled
        try { $nudCmrt.Invalidate() } catch { }
    }
    $nudPwron = $Controls['PciL1ssPowerOnUsValue']
    if ($nudPwron -is [System.Windows.Forms.NumericUpDown]) {
        $pwronValue = [decimal][uint64]$State.TPowerOnUs
        if ($pwronValue -lt $nudPwron.Minimum) { $pwronValue = $nudPwron.Minimum }
        if ($pwronValue -gt $nudPwron.Maximum) { $pwronValue = $nudPwron.Maximum }
        $nudPwron.Value = $pwronValue
        $nudPwron.Enabled = $l1ssControlsEnabled
        try { $nudPwron.Invalidate() } catch { }
    }
    $button = $Controls['PciL1ssSetButton']
    if ($button -is [System.Windows.Forms.Button]) {
        $button.Enabled = ($support -ne 0)
        try { $button.Invalidate() } catch { }
    }
    $thresholdButton = $Controls['PciL1ssThresholdSetButton']
    if ($thresholdButton -is [System.Windows.Forms.Button]) {
        $thresholdButton.Enabled = $l1ssControlsEnabled
        try { $thresholdButton.Invalidate() } catch { }
    }
    $label = $Controls['PciL1ssStatusLabel']
    if ($label -is [System.Windows.Forms.Label]) {
        $label.Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
    }
}

