function Add-DeviceTweakerPciL1ssFlatResult {
    param(
        [System.Collections.Generic.List[object]]$Target,
        [AllowNull()][object]$Value
    )
    if ($null -eq $Target -or $null -eq $Value) { return }
    $base = $Value
    try {
        if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject }
    } catch { $base = $Value }
    if ($base -is [System.Array]) {
        foreach ($child in @($base)) { Add-DeviceTweakerPciL1ssFlatResult -Target $Target -Value $child }
        return
    }
    [void]$Target.Add($Value)
}

function Apply-AsyncPciL1ssResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciL1ssFlatResult -Target $flatResults -Value $raw }
    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciL1ssStatusLabel')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciL1ssStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciL1ssControlsFromState -Controls $ctrls -State $result.State
        }
        else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe L1SS error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe L1SS] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe L1SS] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                $label.Text = ('ERR: {0}' -f $errText)
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
}

function Set-PciL1ssHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    if ([string]::IsNullOrWhiteSpace($errText)) { $errText = 'Unknown PCIe L1SS hydration error.' }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciL1ssStatusLabel')) { return }
        $label = $ctrls['PciL1ssStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) {
            $label.Text = ('ERR: {0}' -f $errText)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
        }
        return
    }
}

function Start-AsyncPciL1ssHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciL1ssStatusLabel')) { continue }
        $label = $ctrls['PciL1ssStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciL1ssReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe L1SS read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe L1SS] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe L1SS] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }
    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciL1ssHydration' -ScriptText (Get-AsyncPciL1ssWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciL1ssResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred PCIe L1SS hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe L1SS hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
            Set-PciL1ssHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciL1ssApply {
    param(
        [Parameter(Mandatory=$true)][object]$Device,
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)][ValidateSet('Mask','Threshold','Timing')][string]$Kind,
        [int]$Mask = 0,
        [uint64]$ThresholdNs = 0,
        [int]$CommonModeRestoreTimeUs = -1,
        [int]$PowerOnUs = -1,
        [System.Windows.Forms.Button]$Button
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciL1ssStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe L1SS apply key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; Kind = $Kind; Mask = $Mask; ThresholdNs = $ThresholdNs; CommonModeRestoreTimeUs = $CommonModeRestoreTimeUs; PowerOnUs = $PowerOnUs }
        Start-PolledRunspaceTask -TaskName 'PciL1ssApply' -ScriptText (Get-AsyncPciL1ssApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciL1ssResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe L1SS] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe L1SS] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

