        `$state = Set-PciMaxPayloadSize -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function) -Bytes ([int]`$spec.Bytes)
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

function Get-AsyncPciDeviceControlApplyWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'ConvertTo-PciPacketSizeBytes'),
        (Get-FunctionDefinitionText 'ConvertTo-PciPacketSizeName'),
        (Get-FunctionDefinitionText 'ConvertFrom-PciPacketSizeBytes'),
        (Get-FunctionDefinitionText 'ConvertTo-PciLinkSpeedName'),
        (Get-FunctionDefinitionText 'ConvertTo-PciSupportedLinkSpeedCodes'),
        (Get-FunctionDefinitionText 'ConvertTo-PciSupportedLinkSpeedNames'),
        (Get-FunctionDefinitionText 'Test-PciLinkSpeedCodeSupported'),
        (Get-FunctionDefinitionText 'ConvertTo-PciExpressPortTypeName'),
        (Get-FunctionDefinitionText 'ConvertTo-PciLinkWidthName'),
        (Get-FunctionDefinitionText 'Read-PciConfigValue'),
        (Get-FunctionDefinitionText 'Write-PciConfigValue'),
        (Get-FunctionDefinitionText 'Get-PciExpressCapabilityContext'),
        (Get-FunctionDefinitionText 'Get-PciExtendedCapabilityContext'),
        (Get-FunctionDefinitionText 'Test-PciFunctionPresent'),
        (Get-FunctionDefinitionText 'Get-PciHeaderType'),
        (Get-FunctionDefinitionText 'Test-PciBridgeFunction'),
        (Get-FunctionDefinitionText 'Get-PciBridgeBusNumbers'),
        (Get-FunctionDefinitionText 'Get-PciExpressPortType'),
        (Get-FunctionDefinitionText 'Test-PciExtendedCapabilityPresent'),
        (Get-FunctionDefinitionText 'Find-PciDownstreamChildFunction'),
        (Get-FunctionDefinitionText 'Find-PciParentBridge'),
        (Get-FunctionDefinitionText 'Resolve-PciAspmLinkContext'),
        (Get-FunctionDefinitionText 'Get-PciDevice2TenBitTagState'),
        (Get-FunctionDefinitionText 'Wait-PciDeviceTransactionsIdle'),
        (Get-FunctionDefinitionText 'Get-PciTenBitTagLinkPolicy'),
        (Get-FunctionDefinitionText 'Get-PciLinkState'),
        (Get-FunctionDefinitionText 'Set-PciDeviceControlOrderingFeatures')
    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$state = Set-PciDeviceControlOrderingFeatures -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function) -EnableRelaxedOrdering ([bool]`$spec.EnableRelaxedOrdering) -EnableExtendedTag ([bool]`$spec.EnableExtendedTag) -EnableTenBitTagRequester ([bool]`$spec.EnableTenBitTagRequester) -EnableNoSnoop ([bool]`$spec.EnableNoSnoop) -EnableClockPowerManagement ([bool]`$spec.EnableClockPowerManagement) -EnableCommonClockConfiguration ([bool]`$spec.EnableCommonClockConfiguration) -EnableExtendedSync ([bool]`$spec.EnableExtendedSync) -EnableIdoRequest ([bool]`$spec.EnableIdoRequest) -EnableIdoCompletion ([bool]`$spec.EnableIdoCompletion) -DisableHardwareAutonomousWidth ([bool]`$spec.DisableHardwareAutonomousWidth) -DisableHardwareAutonomousSpeed ([bool]`$spec.DisableHardwareAutonomousSpeed)
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

function Add-DeviceTweakerPciLinkFlatResult {
    param(
        [System.Collections.Generic.List[object]]$Target,
        [AllowNull()][object]$Value
    )
    if ($null -eq $Target -or $null -eq $Value) { return }

    $base = $Value
    try {
        if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject }
    } catch { $base = $Value }

    if ($base -is [System.Array]) {
        foreach ($child in @($base)) { Add-DeviceTweakerPciLinkFlatResult -Target $Target -Value $child }
        return
    }

    [void]$Target.Add($Value)
}

function Set-PciLinkControlsFromState {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)]$State
    )
    $combo = $Controls['PciMrrsCombo']
    $mpsCombo = $Controls['PciMpsCombo']
    $relaxedCheck = $Controls['PciRelaxedOrderingCheck']
    $extendedTagCheck = $Controls['PciExtendedTagCheck']
    $tenBitTagCheck = $Controls['PciTenBitTagRequesterCheck']
    $noSnoopCheck = $Controls['PciNoSnoopCheck']
    $clockPmCheck = $Controls['PciClockPowerManagementCheck']
    $commonClockCheck = $Controls['PciCommonClockCheck']
    $extendedSyncCheck = $Controls['PciExtendedSyncCheck']
    $idoReqCheck = $Controls['PciIdoRequestCheck']
    $idoCplCheck = $Controls['PciIdoCompletionCheck']
    $hawdCheck = $Controls['PciHardwareAutonomousWidthDisableCheck']
    $hasdCheck = $Controls['PciHardwareAutonomousSpeedDisableCheck']
    $devctlButton = $Controls['PciDeviceControlSetButton']
    $label = $Controls['PciLinkStatusLabel']
    if ($combo -is [System.Windows.Forms.ComboBox]) {
        $code = [int]$State.MrrsCode
        if ($code -ge 0 -and $code -le 5) { $combo.SelectedIndex = $code }
        else { try { $combo.SelectedIndex = -1 } catch { } }
        $combo.Enabled = $true
        try { $combo.Invalidate() } catch { }
    }
    if ($mpsCombo -is [System.Windows.Forms.ComboBox]) {
        $mpsCode = [int]$State.MpsCode
        if ($mpsCode -ge 0 -and $mpsCode -le 5) { $mpsCombo.SelectedIndex = $mpsCode }
        else { try { $mpsCombo.SelectedIndex = -1 } catch { } }
        $mpsCombo.Enabled = $true
        try { $mpsCombo.Invalidate() } catch { }
    }
    if ($relaxedCheck -is [System.Windows.Forms.CheckBox]) {
        $relaxedCheck.Checked = [bool]$State.RelaxedOrderingEnabled
        $relaxedCheck.Enabled = $true
        try { $relaxedCheck.Invalidate() } catch { }
    }
    if ($extendedTagCheck -is [System.Windows.Forms.CheckBox]) {
        $extendedTagCheck.Checked = [bool]$State.ExtendedTagEnabled
        $extendedTagCheck.Enabled = ([bool]$State.ExtendedTagSupported -or [bool]$State.ExtendedTagEnabled)
        try { $extendedTagCheck.Invalidate() } catch { }
    }
    if ($tenBitTagCheck -is [System.Windows.Forms.CheckBox]) {
        $tenBitTagCheck.Checked = [bool]$State.TenBitTagRequesterEnabled
        $tenBitCanEnable = ([bool]$State.TenBitTagSafeToEnable -or [bool]$State.TenBitTagRequesterEnabled)
        $tenBitTagCheck.Enabled = $tenBitCanEnable
        try { $tenBitTagCheck.Text = if ($tenBitCanEnable) { '10TagR' } else { '10TagR!' } } catch { }
        try { $tenBitTagCheck.Invalidate() } catch { }
    }
    if ($noSnoopCheck -is [System.Windows.Forms.CheckBox]) {
        $noSnoopCheck.Checked = [bool]$State.NoSnoopEnabled
        $noSnoopCheck.Enabled = $true
        try { $noSnoopCheck.Invalidate() } catch { }
    }
    if ($clockPmCheck -is [System.Windows.Forms.CheckBox]) {
        $clockPmCheck.Checked = [bool]$State.ClockPowerManagementEnabled
        $clockPmCheck.Enabled = ([bool]$State.ClockPowerManagementSupported -or [bool]$State.ClockPowerManagementEnabled)
        try { $clockPmCheck.Invalidate() } catch { }
    }
    if ($commonClockCheck -is [System.Windows.Forms.CheckBox]) {
        $commonClockCheck.Checked = [bool]$State.CommonClockConfiguration
        $commonClockCheck.Enabled = $true
        try { $commonClockCheck.Invalidate() } catch { }
    }
    if ($extendedSyncCheck -is [System.Windows.Forms.CheckBox]) {
        $extendedSyncCheck.Checked = [bool]$State.ExtendedSync
        $extendedSyncCheck.Enabled = $true
        try { $extendedSyncCheck.Invalidate() } catch { }
    }
    if ($idoReqCheck -is [System.Windows.Forms.CheckBox]) {
        $idoReqCheck.Checked = [bool]$State.IdoRequestEnabled
        $idoReqCheck.Enabled = ([bool]$State.HasDevice2Registers -or [bool]$State.IdoRequestEnabled)
        try { $idoReqCheck.Invalidate() } catch { }
    }
    if ($idoCplCheck -is [System.Windows.Forms.CheckBox]) {
        $idoCplCheck.Checked = [bool]$State.IdoCompletionEnabled
        $idoCplCheck.Enabled = ([bool]$State.HasDevice2Registers -or [bool]$State.IdoCompletionEnabled)
        try { $idoCplCheck.Invalidate() } catch { }
    }
    if ($hawdCheck -is [System.Windows.Forms.CheckBox]) {
        $hawdCheck.Checked = [bool]$State.HardwareAutonomousWidthDisable
        $hawdCheck.Enabled = $true
        try { $hawdCheck.Invalidate() } catch { }
    }
    if ($hasdCheck -is [System.Windows.Forms.CheckBox]) {
        $hasdCheck.Checked = [bool]$State.HardwareAutonomousSpeedDisable
        $hasdCheck.Enabled = ([bool]$State.HasLink2Registers -or [bool]$State.HardwareAutonomousSpeedDisable)
        try { $hasdCheck.Invalidate() } catch { }
    }
    $mrrsButton = $Controls['PciMrrsSetButton']
    if ($mrrsButton -is [System.Windows.Forms.Button]) {
        $mrrsButton.Enabled = $true
        try { $mrrsButton.Invalidate() } catch { }
    }
    $mpsButton = $Controls['PciMpsSetButton']
    if ($mpsButton -is [System.Windows.Forms.Button]) {
        $mpsButton.Enabled = $true
        try { $mpsButton.Invalidate() } catch { }
    }
    if ($devctlButton -is [System.Windows.Forms.Button]) {
        $devctlButton.Enabled = $true
        try { $devctlButton.Invalidate() } catch { }
    }
    if ($label -is [System.Windows.Forms.Label]) {
        $label.Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
    }
}

function Apply-AsyncPciLinkResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }

    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciLinkFlatResult -Target $flatResults -Value $raw }

    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLinkStatusLabel')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciLinkStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciLinkControlsFromState -Controls $ctrls -State $result.State
        }
        else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe link-state error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe Link] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe Link] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                $label.Text = ('ERR: {0}' -f $errText)
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
}

function Set-PciLinkHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    if ([string]::IsNullOrWhiteSpace($errText)) { $errText = 'Unknown PCIe link-state hydration error.' }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLinkStatusLabel')) { return }
        $label = $ctrls['PciLinkStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) {
            $label.Text = ('ERR: {0}' -f $errText)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
        }
        return
    }
}

function Start-AsyncPciLinkHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciLinkStatusLabel')) { continue }
        $label = $ctrls['PciLinkStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciLinkReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe link-state read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe Link] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe Link] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }

    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciLinkHydration' -ScriptText (Get-AsyncPciLinkWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciLinkResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred PCIe link-state hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe link-state hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
            Set-PciLinkHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciDeviceControlApply {
    param([Parameter(Mandatory=$true)][object]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][bool]$EnableRelaxedOrdering,[Parameter(Mandatory=$true)][bool]$EnableExtendedTag,[Parameter(Mandatory=$true)][bool]$EnableTenBitTagRequester,[Parameter(Mandatory=$true)][bool]$EnableNoSnoop,[Parameter(Mandatory=$true)][bool]$EnableClockPowerManagement,[Parameter(Mandatory=$true)][bool]$EnableCommonClockConfiguration,[Parameter(Mandatory=$true)][bool]$EnableExtendedSync,[Parameter(Mandatory=$true)][bool]$EnableIdoRequest,[Parameter(Mandatory=$true)][bool]$EnableIdoCompletion,[Parameter(Mandatory=$true)][bool]$DisableHardwareAutonomousWidth,[Parameter(Mandatory=$true)][bool]$DisableHardwareAutonomousSpeed,[System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciLinkStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing DEV/LNK...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe Device/Link Control apply key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; EnableRelaxedOrdering = [bool]$EnableRelaxedOrdering; EnableExtendedTag = [bool]$EnableExtendedTag; EnableTenBitTagRequester = [bool]$EnableTenBitTagRequester; EnableNoSnoop = [bool]$EnableNoSnoop; EnableClockPowerManagement = [bool]$EnableClockPowerManagement; EnableCommonClockConfiguration = [bool]$EnableCommonClockConfiguration; EnableExtendedSync = [bool]$EnableExtendedSync; EnableIdoRequest = [bool]$EnableIdoRequest; EnableIdoCompletion = [bool]$EnableIdoCompletion; DisableHardwareAutonomousWidth = [bool]$DisableHardwareAutonomousWidth; DisableHardwareAutonomousSpeed = [bool]$DisableHardwareAutonomousSpeed }
        Start-PolledRunspaceTask -TaskName 'PciDeviceControlApply' -ScriptText (Get-AsyncPciDeviceControlApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciLinkResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET DEV/LNK'; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET DEV/LNK'; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe DEV/LNK] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe DEV/LNK] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET DEV/LNK'; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

