            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET MPS'; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe MPS] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe MPS] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET MPS'; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}


$script:PostImodHydrationStarted = $false


function Set-PciAerDpcAcsControlsFromState {
    param([Parameter(Mandatory=$true)][hashtable]$Controls, [Parameter(Mandatory=$true)]$State)
    $Controls['PciAerDpcAcsLastState'] = $State
    $label = $Controls['PciAerDpcAcsStatusLabel']
    if ($label -is [System.Windows.Forms.Label]) { $label.Text = [string]$State.DisplayText; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    if ($Controls.ContainsKey('PciMsiEnableCheck') -and $Controls['PciMsiEnableCheck'] -is [System.Windows.Forms.CheckBox]) {
        $msiText = 'MSI n/a'
        if ([bool]$State.MsiPresent) { $msiText = ('MSI {0}' -f [string]$State.MsiVectorCountText) }
        $Controls['PciMsiEnableCheck'].Text = $msiText
        try { $Controls['PciMsiEnableCheck'].Invalidate() } catch { }
    }
    if ($Controls.ContainsKey('PciMsixEnableCheck') -and $Controls['PciMsixEnableCheck'] -is [System.Windows.Forms.CheckBox]) {
        $msixText = 'MSI-X n/a'
        if ([bool]$State.MsixPresent) { $msixText = ('MSI-X {0}' -f [string]$State.MsixVectorCountText) }
        $Controls['PciMsixEnableCheck'].Text = $msixText
        try { $Controls['PciMsixEnableCheck'].Invalidate() } catch { }
    }
    $pairs = @(
        @('PciAerEcrcGenerationCheck',[bool]$State.AerEcrcGenerationEnabled,([bool]$State.AerPresent -and [bool]$State.AerEcrcGenerationCapable)),
        @('PciAerEcrcCheckCheck',[bool]$State.AerEcrcCheckEnabled,([bool]$State.AerPresent -and [bool]$State.AerEcrcCheckCapable)),
        @('PciDpcFatalEnableCheck',[bool]$State.DpcFatalEnable,[bool]$State.DpcPresent),
        @('PciDpcNonFatalEnableCheck',[bool]$State.DpcNonFatalEnable,[bool]$State.DpcPresent),
        @('PciDpcInterruptEnableCheck',[bool]$State.DpcInterruptEnable,[bool]$State.DpcPresent),
        @('PciMsiEnableCheck',[bool]$State.MsiEnabled,[bool]$State.MsiPresent),
        @('PciMsixEnableCheck',[bool]$State.MsixEnabled,[bool]$State.MsixPresent),
        @('PciMsixFunctionMaskCheck',[bool]$State.MsixFunctionMasked,[bool]$State.MsixPresent),
        @('PciAcsEnableCheck',[bool]$State.AcsAllSupportedEnabled,([bool]$State.AcsPresent -and [uint16]$State.AcsSupportedMask -ne 0)),
        @('PciAtsEnableCheck',[bool]$State.AtsEnabled,[bool]$State.AtsPresent),
        @('PciPriEnableCheck',[bool]$State.PriEnabled,[bool]$State.PriPresent),
        @('PciPasidEnableCheck',[bool]$State.PasidEnabled,[bool]$State.PasidPresent),
        @('PciPtmEnableCheck',[bool]$State.PtmEnabled,([bool]$State.PtmPresent -and ([bool]$State.PtmRequesterCapable -or [bool]$State.PtmResponderCapable -or [bool]$State.PtmRootCapable))),
        @('PciTphEnableCheck',[bool]$State.TphEnabled,[bool]$State.TphPresent),
        @('PciDoeInterruptEnableCheck',[bool]$State.DoeAllInterruptsEnabled,([bool]$State.DoePresent -and [bool]$State.DoeInterruptCapable)),
        @('PciIdeCapabilityCheck',[bool]$State.IdePresent,$false),
        @('PciDvsecCapabilityCheck',[bool]$State.DvsecPresent,$false),
        @('PciVsecCapabilityCheck',[bool]$State.VsecPresent,$false),
        @('PciLmrCapabilityCheck',[bool]$State.LmrPresent,$false),
        @('PciVcEnableCheck',[bool]$State.VcEnabled,([bool]$State.VcPresent -and [int]$State.VcResourceCount -gt 0)),
        @('PciTcEnableCheck',[bool]$State.TcExtendedClassesEnabled,([bool]$State.VcPresent -and [int]$State.VcResourceCount -gt 0))
    )
    foreach ($pair in @($pairs)) {
        $key = [string]$pair[0]
        if ($Controls.ContainsKey($key) -and $Controls[$key] -is [System.Windows.Forms.CheckBox]) { $Controls[$key].Checked = [bool]$pair[1]; $Controls[$key].Enabled = [bool]$pair[2] }
    }
    $lmrControlEnabled = ([bool]$State.LmrPresent -and [bool]$State.LmrSupportedAtCurrentSpeed -and [bool]$State.LmrReady)
    $lmrInputKeys = @('PciLmrApplyCheck','PciLmrCommandCombo','PciLmrReceiverValue','PciLmrLanesText','PciLmrTimingStepsValue','PciLmrVoltageStepsValue','PciLmrErrorLimitValue','PciLmrGoLeftCheck','PciLmrGoDownCheck','PciLmrRawCommandText','PciLmrVerifyEchoCheck')
    foreach ($key in @($lmrInputKeys)) {
        if ($Controls.ContainsKey($key) -and $null -ne $Controls[$key]) { try { $Controls[$key].Enabled = [bool]$lmrControlEnabled } catch { } }
    }
    if ($Controls.ContainsKey('PciLmrApplyCheck') -and $Controls['PciLmrApplyCheck'] -is [System.Windows.Forms.CheckBox]) { $Controls['PciLmrApplyCheck'].Checked = $false }
    if ($Controls.ContainsKey('PciLmrCommandCombo') -and $Controls['PciLmrCommandCombo'] -is [System.Windows.Forms.ComboBox] -and ([int]$Controls['PciLmrCommandCombo'].SelectedIndex) -lt 0) { $Controls['PciLmrCommandCombo'].SelectedIndex = 0 }
    $phyPresetInputKeys = @('PciPhyPresetApplyCheck','PciPhyPresetRateCombo','PciPhyPresetStartLaneValue','PciPhyPresetBytesText')
    foreach ($key in @($phyPresetInputKeys)) { if ($Controls.ContainsKey($key) -and $null -ne $Controls[$key]) { try { $Controls[$key].Enabled = [bool]$State.PciPhysicalLayerPresent } catch { } } }
    if ($Controls.ContainsKey('PciPhyPresetApplyCheck') -and $Controls['PciPhyPresetApplyCheck'] -is [System.Windows.Forms.CheckBox]) { $Controls['PciPhyPresetApplyCheck'].Checked = $false }
    if ($Controls.ContainsKey('PciPhyPresetRateCombo') -and $Controls['PciPhyPresetRateCombo'] -is [System.Windows.Forms.ComboBox]) {
        $combo = $Controls['PciPhyPresetRateCombo']
        if ([bool]$State.PciPhysicalLayer64Present) { $combo.SelectedItem = '64GT' }
        elseif ([bool]$State.PciPhysicalLayer32Present) { $combo.SelectedItem = '32GT' }
        elseif ([bool]$State.PciPhysicalLayer16Present) { $combo.SelectedItem = '16GT' }
        elseif ([int]$combo.SelectedIndex -lt 0 -and $combo.Items.Count -gt 0) { $combo.SelectedIndex = 0 }
    }
    if ($Controls.ContainsKey('PciAerDpcAcsSetButton') -and $Controls['PciAerDpcAcsSetButton'] -is [System.Windows.Forms.Button]) { $Controls['PciAerDpcAcsSetButton'].Enabled = ([bool]$State.MsiPresent -or [bool]$State.MsixPresent -or [bool]$State.AerPresent -or [bool]$State.DpcPresent -or ([bool]$State.AcsPresent -and [uint16]$State.AcsSupportedMask -ne 0) -or [bool]$State.AtsPresent -or [bool]$State.PriPresent -or [bool]$State.PasidPresent -or [bool]$State.PtmPresent -or [bool]$State.TphPresent -or [bool]$State.DoePresent -or [bool]$State.IdePresent -or [bool]$State.DvsecPresent -or [bool]$State.VsecPresent -or [bool]$State.LmrPresent -or [bool]$State.PciPhysicalLayerPresent -or [bool]$State.VndrPresent -or [bool]$State.VcPresent) }
}

