    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$items = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$setParams = @{
            Segment = ([int]`$spec.Segment)
            Bus = ([int]`$spec.Bus)
            Device = ([int]`$spec.Device)
            Function = ([int]`$spec.Function)
        }
        foreach (`$name in @('AerEcrcGenerationEnable','AerEcrcCheckEnable','DpcFatalEnable','DpcNonFatalEnable','DpcInterruptEnable','MsiEnable','MsiMultipleMessageEnable','MsiControlMask','MsiControlValue','MsiMaskBits','MsiMaskBitsSet','MsiMaskBitsClear','MsiMessageAddress','MsiMessageAddressLo','MsiMessageAddressHi','MsiMessageData','MsiRouteDisableWhileWriting','MsiRawDwords','MsiRawDwordStartIndex','MsiCapabilityIndex','MsixEnable','MsixFunctionMask','MsixControlMask','MsixControlValue','MsixRawDwords','MsixRawDwordStartIndex','MsixCapabilityIndex','MsixTableRawDwords','MsixTableRawDwordStartIndex','MsixTableCapabilityIndex','MsixTableVectorMask','MsixTableVectorMaskStartIndex','AcsEnable','AtsEnable','PriEnable','PasidEnable','PasidExecEnable','PasidPrivEnable','AtsSmallestTranslationUnitShift','PriReset','PriAllocatedRequests','AerUncorrectableMask','AerUncorrectableSeverity','AerCorrectableMask','AerRootCommand','AerUncorrectableStatusClearMask','AerCorrectableStatusClearMask','AerRootStatusClearMask','DpcControlMask','DpcStatusClearMask','DpcPioStatusClearMask','DpcPioMask','DpcPioSeverity','DpcPioSysError','DpcPioException','AcsControlMask','AcsControlEnableMask','AcsControlDisableMask','AcsEgressControlVector','PtmEnable','PtmRootSelect','TphEnable','TphMode','TphRequesterEnable','TphSteeringTagVector','VcEnable','TcEnable','VcTrafficClassMap','VcStructureIndex','VcResourceIndex','VcLoadTable','VcControlEnableMask','VcControlDisableMask','DoeInterruptEnable','DoeControlMask','DoeControlValue','DoeRawDwords','DoeRawDwordStartIndex','DoeCapabilityIndex','IdeRawDwords','IdeRawDwordStartIndex','IdeCapabilityIndex','PhysicalLayerRawDwords','PhysicalLayerRawDwordStartIndex','PhysicalLayerRawCapability','PhysicalLayerCapabilityIndex','PhysicalLayerLaneEqualizationPresetBytes','PhysicalLayerLaneEqualizationPresetStartLane','DvsecRawDwords','DvsecRawDwordStartIndex','DvsecCapabilityIndex','VsecRawDwords','VsecRawDwordStartIndex','VsecCapabilityIndex','VndrRawDwords','VndrRawDwordStartIndex','VndrCapabilityIndex','LmrCommand','LmrLanes','LmrReceiverNumber','LmrTimingSteps','LmrVoltageSteps','LmrErrorLimit','LmrGoLeft','LmrGoDown','LmrRawCommand','LmrVerifyEcho','LmrResetToNoCommand','AllowPciExtendedCapabilityHeaderWrite','AllowPciConventionalCapabilityHeaderWrite')) {
            if (`$spec.PSObject.Properties.Match(`$name).Count -gt 0) { `$setParams[`$name] = `$spec.`$name }
        }
        `$state = Set-PciAerDpcAcsState @setParams
        [void]`$items.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$items.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$items.ToArray()
"@
}

function Add-DeviceTweakerPciAerDpcAcsFlatResult {
    param([Parameter(Mandatory=$true)]$Target, [AllowNull()]$Value)
    if ($null -eq $Value) { return }
    $base = $Value
    if ($base -is [System.Management.Automation.PSObject]) { $base = $base.BaseObject }
    if ($base -is [System.Array]) { foreach ($child in @($base)) { Add-DeviceTweakerPciAerDpcAcsFlatResult -Target $Target -Value $child }; return }
    [void]$Target.Add($Value)
}

function Apply-AsyncPciAerDpcAcsResultsToUI {
    param([AllowNull()][object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }

    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciAerDpcAcsFlatResult -Target $flatResults -Value $raw }

    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAerDpcAcsStatusLabel')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciAerDpcAcsStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciAerDpcAcsControlsFromState -Controls $ctrls -State $result.State
        } else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe AER/DPC/ACS error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe AER/DPC/ACS] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe AER/DPC/ACS] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) {
                $label.Text = ('ERR: {0}' -f $errText)
                try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
            }
        }
    }
}

function Set-PciAerDpcAcsHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    if ([string]::IsNullOrWhiteSpace($errText)) { $errText = 'Unknown PCIe AER/DPC/ACS hydration error.' }

    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAerDpcAcsStatusLabel')) { return }
        $label = $ctrls['PciAerDpcAcsStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) {
            $label.Text = ('ERR: {0}' -f $errText)
            try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
        }
        return
    }
}

function Start-AsyncPciAerDpcAcsHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciAerDpcAcsStatusLabel')) { continue }
        $label = $ctrls['PciAerDpcAcsStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciAerDpcAcsReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe AER/DPC/ACS read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe AER/DPC/ACS] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe AER/DPC/ACS] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }
    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciAerDpcAcsHydration' -ScriptText (Get-AsyncPciAerDpcAcsWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciAerDpcAcsResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            try {
                Write-Host ("Deferred PCIe AER/DPC/ACS hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe AER/DPC/ACS hydration failed for {0}: {1}" -f $localKey, $err)) }
            } catch { }
            Set-PciAerDpcAcsHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciAerDpcAcsApply {
    param([Parameter(Mandatory=$true)]$Device,[Parameter(Mandatory=$true)][hashtable]$Controls,[Parameter(Mandatory=$true)][bool]$AerEcrcGenerationEnable,[Parameter(Mandatory=$true)][bool]$AerEcrcCheckEnable,[Parameter(Mandatory=$true)][bool]$DpcFatalEnable,[Parameter(Mandatory=$true)][bool]$DpcNonFatalEnable,[Parameter(Mandatory=$true)][bool]$DpcInterruptEnable,[Parameter(Mandatory=$true)][bool]$MsiEnable,[Parameter(Mandatory=$true)][bool]$MsixEnable,[Parameter(Mandatory=$true)][bool]$MsixFunctionMask,[Parameter(Mandatory=$true)][bool]$AcsEnable,[Parameter(Mandatory=$true)][bool]$AtsEnable,[Parameter(Mandatory=$true)][bool]$PriEnable,[Parameter(Mandatory=$true)][bool]$PasidEnable,[Parameter(Mandatory=$true)][bool]$PtmEnable,[Parameter(Mandatory=$true)][bool]$TphEnable,[Parameter(Mandatory=$true)][bool]$DoeInterruptEnable,[Parameter(Mandatory=$true)][bool]$VcEnable,[Parameter(Mandatory=$true)][bool]$TcEnable,[AllowNull()][object]$LmrCommand = $null,[AllowNull()][object]$LmrLanes = $null,[ValidateRange(0,6)][int]$LmrReceiverNumber = 0,[ValidateRange(0,63)][int]$LmrTimingSteps = 0,[ValidateRange(0,127)][int]$LmrVoltageSteps = 0,[ValidateRange(0,63)][int]$LmrErrorLimit = 0,[bool]$LmrGoLeft = $false,[bool]$LmrGoDown = $false,[AllowNull()][object]$LmrRawCommand = $null,[bool]$LmrVerifyEcho = $false,[bool]$LmrResetToNoCommand = $true,[AllowNull()][object]$PhysicalLayerRawCapability = $null,[AllowNull()][object]$PhysicalLayerLaneEqualizationPresetBytes = $null,[ValidateRange(0,31)][int]$PhysicalLayerLaneEqualizationPresetStartLane = 0,[AllowNull()][System.Windows.Forms.Button]$Button)
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciAerDpcAcsStatusLabel']
    try {
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe AER/DPC/ACS set key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; AerEcrcGenerationEnable = [bool]$AerEcrcGenerationEnable; AerEcrcCheckEnable = [bool]$AerEcrcCheckEnable; DpcFatalEnable = [bool]$DpcFatalEnable; DpcNonFatalEnable = [bool]$DpcNonFatalEnable; DpcInterruptEnable = [bool]$DpcInterruptEnable; MsiEnable = [bool]$MsiEnable; MsixEnable = [bool]$MsixEnable; MsixFunctionMask = [bool]$MsixFunctionMask; AcsEnable = [bool]$AcsEnable; AtsEnable = [bool]$AtsEnable; PriEnable = [bool]$PriEnable; PasidEnable = [bool]$PasidEnable; PtmEnable = [bool]$PtmEnable; TphEnable = [bool]$TphEnable; DoeInterruptEnable = [bool]$DoeInterruptEnable; VcEnable = [bool]$VcEnable; TcEnable = [bool]$TcEnable }
        foreach ($lmrPair in @(@('LmrCommand',$LmrCommand),@('LmrLanes',$LmrLanes),@('LmrReceiverNumber',$LmrReceiverNumber),@('LmrTimingSteps',$LmrTimingSteps),@('LmrVoltageSteps',$LmrVoltageSteps),@('LmrErrorLimit',$LmrErrorLimit),@('LmrGoLeft',$LmrGoLeft),@('LmrGoDown',$LmrGoDown),@('LmrRawCommand',$LmrRawCommand),@('LmrVerifyEcho',$LmrVerifyEcho),@('LmrResetToNoCommand',$LmrResetToNoCommand),@('PhysicalLayerRawCapability',$PhysicalLayerRawCapability),@('PhysicalLayerLaneEqualizationPresetBytes',$PhysicalLayerLaneEqualizationPresetBytes),@('PhysicalLayerLaneEqualizationPresetStartLane',$PhysicalLayerLaneEqualizationPresetStartLane))) { if ($PSBoundParameters.ContainsKey([string]$lmrPair[0])) { $spec | Add-Member -NotePropertyName ([string]$lmrPair[0]) -NotePropertyValue $lmrPair[1] -Force } }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing MSI/MSI-X/AER/DPC/ACS/ATS/PRI/PASID/PTM/TPH/DOE/IDE/DVSEC/VSEC/LMR/PHY-LE/VC/TC...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        Set-DeviceTweakerPciAerDpcAcsReadPending -Controls $Controls
        Start-PolledRunspaceTask -TaskName 'PciAerDpcAcsApply' -ScriptText (Get-AsyncPciAerDpcAcsApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciAerDpcAcsResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET PCIe EXT'; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET PCIe EXT'; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }; $label.Text = ('ERR: {0}' -f $detail); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        try { if ($Button) { $Button.Enabled = $true; $Button.Text = 'SET PCIe EXT'; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $_.Exception.Message); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

function Update-PciRebarSizeComboForSelectedBar {
    param([Parameter(Mandatory=$true)][hashtable]$Controls)
    if (-not $Controls.ContainsKey('PciRebarLastState')) { return }
    $state = $Controls['PciRebarLastState']
    if ($null -eq $state) { return }
    $barCombo = $Controls['PciRebarBarCombo']
    $sizeCombo = $Controls['PciRebarSizeCombo']
    if (-not ($sizeCombo -is [System.Windows.Forms.ComboBox])) { return }
    $barIndex = [int]$state.SelectedBarIndex
    if ($barCombo -is [System.Windows.Forms.ComboBox]) {
        $barText = [string]$barCombo.SelectedItem
        if ($barText -match 'BAR([0-5])') { $barIndex = [int]$Matches[1] }
    }
    $entry = $null
    foreach ($candidate in @($state.Entries)) { if ([int]$candidate.BarIndex -eq $barIndex) { $entry = $candidate; break } }
    if ($null -eq $entry) { $entry = $state.SelectedEntry }
    if ($null -eq $entry) { return }
    $sizeCombo.Items.Clear()
    [void]$sizeCombo.Items.Add('AUTO: enable=max / disable=legacy-min')
    $selected = 0
    $j = 1
    foreach ($enc in @([int[]]$entry.SupportedEncodedSizes)) {
        $text = ('{0} | {1}' -f [int]$enc, (ConvertTo-PciRebarSizeText -Bytes (ConvertTo-PciRebarSizeBytes -Encoded ([int]$enc))))
        [void]$sizeCombo.Items.Add($text)
        if ([int]$enc -eq [int]$entry.CurrentSizeEncoded) { $selected = $j }
        $j++
    }
    if ($sizeCombo.Items.Count -gt 0) { $sizeCombo.SelectedIndex = [Math]::Max(0, [Math]::Min($sizeCombo.Items.Count - 1, $selected)) }
    try { [DeviceTweakerUiHandlers]::AutoSizeComboDropDown($sizeCombo) } catch { }
    $sizeCombo.Enabled = $true
    $chk = $Controls['PciRebarEnableCheck']
    if ($chk -is [System.Windows.Forms.CheckBox]) { $chk.Checked = ([int]$entry.CurrentSizeEncoded -gt 8); $chk.Enabled = $true }
}

function Set-PciRebarControlsFromState {
    param(
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)]$State
    )
    $Controls['PciRebarLastState'] = $State
    $label = $Controls['PciRebarStatusLabel']
    if ($label -is [System.Windows.Forms.Label]) {
        $label.Text = [string]$State.DisplayText
        try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { }
    }
    $chk = $Controls['PciRebarEnableCheck']
    if ($chk -is [System.Windows.Forms.CheckBox]) { $chk.Checked = [bool]$State.EffectiveEnabled; $chk.Enabled = $true }
    $barCombo = $Controls['PciRebarBarCombo']
    if ($barCombo -is [System.Windows.Forms.ComboBox]) {
        $barCombo.Items.Clear()
        $selectedIndex = 0
        $i = 0
        foreach ($entry in @($State.Entries)) {
            $text = ('BAR{0} | cur {1} | max {2}' -f [int]$entry.BarIndex, [string]$entry.CurrentSizeText, [string]$entry.MaxSupportedText)
            [void]$barCombo.Items.Add($text)
            if ([int]$entry.BarIndex -eq [int]$State.SelectedBarIndex) { $selectedIndex = $i }
            $i++
        }
        if ($barCombo.Items.Count -gt 0) { $barCombo.SelectedIndex = [Math]::Max(0, [Math]::Min($barCombo.Items.Count - 1, $selectedIndex)) }
        try { [DeviceTweakerUiHandlers]::AutoSizeComboDropDown($barCombo) } catch { }
        $barCombo.Enabled = $true
    }
    Update-PciRebarSizeComboForSelectedBar -Controls $Controls
    $setButton = $Controls['PciRebarSetButton']
    if ($setButton -is [System.Windows.Forms.Button]) { $setButton.Enabled = $true; try { $setButton.Invalidate() } catch { } }
}

function Get-AsyncPciRebarWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'Read-PciConfigValue'),
        (Get-FunctionDefinitionText 'Get-PciExtendedCapabilityContext'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSizeBytes'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSizeText'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSupportedSizeSummary'),
        (Get-FunctionDefinitionText 'Get-PciRebarBarDescriptor'),
        (Get-FunctionDefinitionText 'Get-PciRebarNormalizedMask'),
        (Get-FunctionDefinitionText 'Get-PciRebarState')
    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$state = Get-PciRebarState -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function) -SelectedBarIndex 0
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

function Get-AsyncPciRebarApplyWorkerScript {
    $defs = @(
        (Get-FunctionDefinitionText 'Is-Admin'),
        (Get-FunctionDefinitionText 'Dec-To-Hex'),
        (Get-FunctionDefinitionText 'Convert-RWEverythingOutputToUInt64'),
        (Get-FunctionDefinitionText 'Resolve-RWEPath'),
        (Get-FunctionDefinitionText 'Get-DeviceTweakerDriverBlockDiagnostics'),
        (Get-FunctionDefinitionText 'Test-DeviceTweakerRWEnNVMeDisabled'),
        (Get-FunctionDefinitionText 'Initialize-DeviceTweakerRWEverything'),
        (Get-FunctionDefinitionText 'Invoke-RWECommand'),
        (Get-FunctionDefinitionText 'Read-PciConfigValue'),
        (Get-FunctionDefinitionText 'Write-PciConfigValue'),
        (Get-FunctionDefinitionText 'Get-PciExtendedCapabilityContext'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSizeBytes'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSizeText'),
        (Get-FunctionDefinitionText 'ConvertTo-PciRebarSupportedSizeSummary'),
        (Get-FunctionDefinitionText 'Get-PciRebarBarDescriptor'),
        (Get-FunctionDefinitionText 'Get-PciRebarNormalizedMask'),
        (Get-FunctionDefinitionText 'Get-PciRebarState'),
        (Get-FunctionDefinitionText 'Set-PciRebarState')
    ) -join "`n`n"
    return @"
param(`$Specs)
`$ErrorActionPreference = 'Stop'
`$rwePath = 'C:\Program Files (x86)\RW-Everything\Rw.exe'
`$script:RWEPreflightResult = `$null
`$script:RWECommandTimeoutMs = 30000
`$script:RWEAllowParallelReadCommands = `$false
`$script:RWEReadParallelThrottle = [Math]::Max(2, [Math]::Min(8, [Environment]::ProcessorCount))
$defs
`$results = New-Object System.Collections.Generic.List[object]
foreach (`$spec in @(`$Specs)) {
    try {
        `$target = `$null
        if (`$null -ne `$spec.TargetSizeEncoded -and [string]`$spec.TargetSizeEncoded -ne '') { `$target = [int]`$spec.TargetSizeEncoded }
        `$state = Set-PciRebarState -Segment ([int]`$spec.Segment) -Bus ([int]`$spec.Bus) -Device ([int]`$spec.Device) -Function ([int]`$spec.Function) -BarIndex ([int]`$spec.BarIndex) -Enable ([bool]`$spec.Enable) -TargetSizeEncoded `$target
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$true; State = `$state; Error = `$null })
    } catch {
        [void]`$results.Add([pscustomobject]@{ Key = [string]`$spec.Key; Success = `$false; State = `$null; Error = (`$_.Exception.Message) })
    }
}
return ,`$results.ToArray()
"@
}

function Add-DeviceTweakerPciRebarFlatResult {
    param(
        [System.Collections.Generic.List[object]]$Target,
        [AllowNull()][object]$Value
    )
    if ($null -eq $Target -or $null -eq $Value) { return }
    $base = $Value
    try { if ($Value -is [System.Management.Automation.PSObject] -and $null -ne $Value.BaseObject) { $base = $Value.BaseObject } } catch { $base = $Value }
    if ($base -is [System.Array]) { foreach ($child in @($base)) { Add-DeviceTweakerPciRebarFlatResult -Target $Target -Value $child }; return }
    [void]$Target.Add($Value)
}

function Apply-AsyncPciRebarResultsToUI {
    param([object[]]$Results)
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $flatResults = New-Object System.Collections.Generic.List[object]
    foreach ($raw in @($Results)) { Add-DeviceTweakerPciRebarFlatResult -Target $flatResults -Value $raw }
    $byKey = @{}
    foreach ($r in @($flatResults.ToArray())) {
        if ($null -eq $r) { continue }
        $keyText = $null
        try { $keyText = [string]$r.Key } catch { $keyText = $null }
        if (-not [string]::IsNullOrWhiteSpace($keyText)) { $byKey[$keyText] = $r }
    }
    if ($byKey.Count -eq 0) { return }
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciRebarStatusLabel')) { continue }
        $key = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key) -or -not $byKey.ContainsKey($key)) { continue }
        $result = $byKey[$key]
        $label = $ctrls['PciRebarStatusLabel']
        if ($result.Success -and $null -ne $result.State) {
            Set-PciRebarControlsFromState -Controls $ctrls -State $result.State
        } else {
            $errText = if ($null -eq $result.Error) { 'Unknown PCIe ReBAR error.' } else { [string]$result.Error }
            try {
                Write-Host ('[PCIe ReBAR] ERROR for {0}' -f $key) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ReBAR] ERROR for {0}{1}{2}' -f $key, [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
}

function Set-PciRebarHydrationFailedLabel {
    param(
        [Parameter(Mandatory=$true)][string]$Key,
        [AllowNull()][object]$ErrorObject
    )
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $controlMap -or $null -eq $script:deviceList) { return }
    $errText = if ($ErrorObject -and $ErrorObject.Exception) { [string]$ErrorObject.Exception.Message } else { [string]$ErrorObject }
    foreach ($device in @($script:deviceList)) {
        $deviceKey = [string](Get-PropValue $device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($deviceKey)) { $deviceKey = [string](Get-PropValue $device 'DeviceKey') }
        if (-not [string]::Equals($deviceKey, $Key, [System.StringComparison]::OrdinalIgnoreCase)) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciRebarStatusLabel')) { return }
        $label = $ctrls['PciRebarStatusLabel']
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        return
    }
}

function Start-AsyncPciRebarHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $controlMap = Get-DeviceTweakerActiveControlMap
    if ($null -eq $script:deviceList -or $null -eq $controlMap) { return }
    $specs = New-Object System.Collections.Generic.List[object]
    foreach ($device in @($script:deviceList)) {
        if ($null -eq $device) { continue }
        $ctrls = $null
        try { if ($controlMap.ContainsKey($device)) { $ctrls = $controlMap[$device] } } catch { }
        if ($null -eq $ctrls -or -not $ctrls.ContainsKey('PciRebarStatusLabel')) { continue }
        $label = $ctrls['PciRebarStatusLabel']
        try {
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Reading...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
            Set-DeviceTweakerPciRebarReadPending -Controls $ctrls
            $bdf = Resolve-PciAspmBdfForDevice -Device $device -Controls $ctrls
            $key = [string](Get-PropValue $device 'RegistryPath')
            if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $device 'DeviceKey') }
            if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe ReBAR read key: RegistryPath and DeviceKey are empty.' }
            [void]$specs.Add([pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function })
        } catch {
            $errText = $_.Exception.Message
            try {
                Write-Host ('[PCIe ReBAR] BDF resolve/read preparation failed for device key {0}' -f (Get-PropValue $device 'RegistryPath')) -ForegroundColor Red
                Write-Host $errText -ForegroundColor Yellow
                if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ReBAR] BDF resolve/read preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
            } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }
    }
    if ($specs.Count -eq 0) { return }
    foreach ($spec in @($specs.ToArray())) {
        $localSpec = $spec
        $localKey = [string]$localSpec.Key
        Start-PolledRunspaceTask -TaskName 'PciRebarHydration' -ScriptText (Get-AsyncPciRebarWorkerScript) -Arguments @(@($localSpec)) -OnCompleted {
            param($Result)
            Apply-AsyncPciRebarResultsToUI -Results @($Result)
        }.GetNewClosure() -OnFailed {
            param($err)
            Write-Host ("Deferred PCIe ReBAR hydration failed for {0}: {1}" -f $localKey, $err) -ForegroundColor Red
            try { if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (("Deferred PCIe ReBAR hydration failed for {0}: {1}" -f $localKey, $err)) } } catch { }
            Set-PciRebarHydrationFailedLabel -Key $localKey -ErrorObject $err
        }.GetNewClosure()
    }
}

function Start-AsyncPciRebarApply {
    param(
        [Parameter(Mandatory=$true)][object]$Device,
        [Parameter(Mandatory=$true)][hashtable]$Controls,
        [Parameter(Mandatory=$true)][ValidateRange(0,5)][int]$BarIndex,
        [Parameter(Mandatory=$true)][bool]$Enable,
        [AllowNull()][object]$TargetSizeEncoded = $null,
        [System.Windows.Forms.Button]$Button
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $label = $Controls['PciRebarStatusLabel']
    try {
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = 'Writing...'; try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        Set-DeviceTweakerPciRebarReadPending -Controls $Controls
        $bdf = Resolve-PciAspmBdfForDevice -Device $Device -Controls $Controls
        $key = [string](Get-PropValue $Device 'RegistryPath')
        if ([string]::IsNullOrWhiteSpace($key)) { $key = [string](Get-PropValue $Device 'DeviceKey') }
        if ([string]::IsNullOrWhiteSpace($key)) { throw 'Cannot build PCIe ReBAR apply key: RegistryPath and DeviceKey are empty.' }
        $spec = [pscustomobject]@{ Key = $key; Segment = $bdf.Segment; Bus = $bdf.Bus; Device = $bdf.Device; Function = $bdf.Function; BarIndex = $BarIndex; Enable = $Enable; TargetSizeEncoded = $TargetSizeEncoded }
        Start-PolledRunspaceTask -TaskName 'PciRebarApply' -ScriptText (Get-AsyncPciRebarApplyWorkerScript) -Arguments @(@($spec)) -OnCompleted {
            param($Result)
            try { Apply-AsyncPciRebarResultsToUI -Results @($Result) } finally { try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { } }
        }.GetNewClosure() -OnFailed {
            param($err)
            try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { }
            if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $err); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
        }.GetNewClosure()
    } catch {
        $errText = $_.Exception.Message
        try {
            Write-Host '[PCIe ReBAR] Apply preparation failed' -ForegroundColor Red
            Write-Host $errText -ForegroundColor Yellow
            if (Get-Command Write-DeviceTweakerPerfFallbackLog -ErrorAction SilentlyContinue) { Write-DeviceTweakerPerfFallbackLog (('[PCIe ReBAR] Apply preparation failed{0}{1}' -f [Environment]::NewLine, $errText)) }
        } catch { }
        try { if ($Button) { $Button.Enabled = $true; $Button.Invalidate() } } catch { }
        if ($label -is [System.Windows.Forms.Label]) { $label.Text = ('ERR: {0}' -f $errText); try { [DeviceEditorBuilder]::SyncScrollableLabel($label) } catch { } }
    }
}

function Start-AsyncPostImodHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    if ($script:PostImodHydrationStarted) { return }
    $script:PostImodHydrationStarted = $true

    try {
        Start-AsyncNVMeInterruptCoalescingHydration
        Start-AsyncHdaRintcntHydration
        Start-AsyncPciAspmHydration
        Start-AsyncPciLinkHydration
        Start-AsyncPciLtrObffHydration
        Start-AsyncPciAerDpcAcsHydration
        Start-AsyncPciL1ssHydration
        Start-AsyncPciRebarHydration
    }
    catch {
        Write-Host "Deferred post-IMOD UI hydration failed: $_" -ForegroundColor Red
    }
}

function Start-AsyncIMODHydration {
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }
    $deviceSpecs = [System.Collections.Generic.List[DeviceTweakerImodHydrationDeviceSpec]]::new()
    $nicDeviceSpecs = [System.Collections.Generic.List[DeviceTweakerImodHydrationDeviceSpec]]::new()
    $usbDeviceSpecs = [System.Collections.Generic.List[DeviceTweakerImodHydrationDeviceSpec]]::new()
    foreach ($device in $deviceList) {
        if (-not $deviceControls.ContainsKey($device)) { continue }
        $ctrls = $deviceControls[$device]
        if ($device.Category -eq 'USB') {
            $spec = [DeviceTweakerImodHydrationDeviceSpec]::new()
            $spec.Key = [string]$device.RegistryPath
            $spec.Category = [string]$device.Category
            $spec.RegistryPath = [string]$device.RegistryPath
            [void]$usbDeviceSpecs.Add($spec)
            continue
        }

        if ($device.Category -eq 'Network' -and $ctrls.ContainsKey('NICIMODInfo') -and $null -ne $ctrls.NICIMODInfo) {
            $spec = [DeviceTweakerImodHydrationDeviceSpec]::new()
            $spec.Key = [string]$device.RegistryPath
            $spec.Category = [string]$device.Category
            $spec.RegistryPath = [string]$device.RegistryPath
            $spec.ConfigPath = [string]$device.ConfigPath
            $spec.NICIMODInfo = $ctrls.NICIMODInfo
            [void]$nicDeviceSpecs.Add($spec)
        }
    }

    foreach ($spec in @($nicDeviceSpecs.ToArray())) { [void]$deviceSpecs.Add($spec) }
    foreach ($spec in @($usbDeviceSpecs.ToArray())) { [void]$deviceSpecs.Add($spec) }

    if ($deviceSpecs.Count -eq 0) {
        Start-AsyncPostImodHydration
        return
    }

    $scriptText = Get-AsyncIMODHydrationWorkerScript
    $controllers = @(Get-CachedUSBControllers)
    $usbEnumResult = if ($script:cachedBIntervalResult) { $script:cachedBIntervalResult } else { $null }
    $hidDevices = if ($script:_cachedHidDevices) { $script:_cachedHidDevices } else { $null }
    $pollingRateLookup = if ($usbEnumResult) { Build-PollingRateLookup -UsbEnumResult $usbEnumResult } else { @{} }
    $audioLookupDetails = if ($script:audioLookupDetails) { $script:audioLookupDetails } else { @{} }

    $script:imodHydrationTask = Start-PolledRunspaceTask -TaskName 'IMODHydration' -ScriptText $scriptText -Arguments @(
        @($deviceSpecs),
        @($controllers),
        $globalDeviceAddressMap,
        $usbEnumResult,
        $hidDevices,
        $pollingRateLookup,
        $audioLookupDetails,
        $userDefinedData,
        $rwePath,
        $globalInterval,
        $globalHCSPARAMSOffset,
        $globalRTSOFF
    ) -OnCompleted {
        param($results)
        try {
            Apply-AsyncHydrationResultsToUI -resultItems $results
        } finally {
            Start-AsyncPostImodHydration
        }
    } -OnFailed {
        param($err)
        try { Write-Host "Deferred IMOD hydration failed: $err" -ForegroundColor Red } finally { Start-AsyncPostImodHydration }
    }
}

function Start-AsyncIRQCountsRefresh {
    $script:irqRefreshTask = Start-PolledRunspaceTask -TaskName 'IRQRefresh' -ScriptText (Get-AsyncIRQWorkerScript) -Arguments @() -OnCompleted {
        param($results)
        $irqInfo = if ($results.Count -gt 0 -and $results[0] -is [hashtable]) { $results[0] } else { @{} }
        Apply-IRQCountsForUI -irqInfo $irqInfo
    } -OnFailed {
        param($err)
        Write-Host "Deferred IRQ refresh failed: $err" -ForegroundColor Red
    }
}

function Start-AsyncUSBIMODApply {
    param(
        [System.Windows.Forms.Button]$button,
        [hashtable]$ctrls,
        $controller,
        $imodValueToApply,
        $interrupterDeviceMap = $null,
        [int]$preferredCount = 0
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }

    $onCompleted = {
        param($results)
        try {
            if ($results.Count -gt 0 -and $results[0].Success) {
                Set-USBIMODControlsFromValues -ctrls $ctrls -imodValues @($results[0].ReadBack)
            }
        } finally {
            if ($null -ne $button) { $button.Text = 'SET' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()

    $onFailed = {
        param($err)
        try {
            $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
            Show-DarkMessageBox -Message ("Failed to apply IMOD settings`n`n$detail") -Title 'Error' -Icon Error
        } finally {
            if ($null -ne $button) { $button.Text = 'SET' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()

    $script:usbApplyTask = Start-PolledRunspaceTask -TaskName 'USBIMODApply' -ScriptText (Get-AsyncUSBIMODApplyWorkerScript) -Arguments @(
        $controller,
        $globalDeviceAddressMap,
        $imodValueToApply,
        $interrupterDeviceMap,
        $preferredCount,
        $userDefinedData,
        $rwePath,
        $globalInterval,
        $globalHCSPARAMSOffset,
        $globalRTSOFF
    ) -OnCompleted $onCompleted -OnFailed $onFailed
}

function Start-AsyncNICIMODApply {
    param(
        [System.Windows.Forms.Button]$button,
        [hashtable]$ctrls,
        $device,
        [hashtable]$nicInfo,
        [uint64]$newValue,
        [uint64[]]$perQueueValues = $null
    )
    if (Test-DeviceTweakerRWEnNVMeDisabled) { return }

    $onCompleted = {
        param($results)
        try {
            if ($results.Count -gt 0 -and $results[0].Success) {
                if ($results[0].PSObject.Properties['NICTopology'] -and $null -ne $results[0].NICTopology) { Set-RealtekIntMitiV2TopologyOnControls -ctrls $ctrls -nicInfo $nicInfo -Topology $results[0].NICTopology }
                $readBack = @($results[0].ReadBack)
                if ($readBack.Count -gt 0) {
                    $ctrls.NICNewIMOD.Text = Format-NICIMODValueListText -values $readBack -nicInfo $nicInfo
                    if ($ctrls.ContainsKey('NICIMODTimeLabel') -and $null -ne $ctrls.NICIMODTimeLabel) {
                        Update-NIC-IMOD-TimeLabel -textBox $ctrls.NICNewIMOD -label $ctrls.NICIMODTimeLabel -nicInfo $nicInfo
                        try {
                            $timeGeo = [DeviceEditorBuilder]::DescribeScrollableLabel($ctrls.NICIMODTimeLabel)
                            $familyGeo = if ($ctrls.ContainsKey('NICFamilyLabel') -and $null -ne $ctrls.NICFamilyLabel) { [DeviceEditorBuilder]::DescribeScrollableLabel($ctrls.NICFamilyLabel) } else { '<no family label>' }
                            Write-NICITRDiagnostic -Level Info -Message ('Async NIC ITR apply UI readback updated. valueCount={0}; inputTextLen={1}; timeLabelTextLen={2}; timeLabelGeometry={3}; familyLabelGeometry={4}' -f @($readBack).Count, ([string]$ctrls.NICNewIMOD.Text).Length, ([string]$ctrls.NICIMODTimeLabel.Text).Length, $timeGeo, $familyGeo)
                        } catch { Write-NICITRDiagnostic -Level Warning -Message 'Async NIC ITR apply UI geometry diagnostic failed.' -Exception $_ }
                    }
                }
            }
        } finally {
            if ($null -ne $button) { $button.Text = 'SET' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()

    $onFailed = {
        param($err)
        try {
            $detail = if ($err -and $err.Exception) { $err.Exception.Message } else { [string]$err }
            Write-NICITRDiagnostic -Level Error -Message ('Async NIC ITR apply task failed: {0}' -f $detail) -Exception $err
            Show-DarkMessageBox -Message ("Failed to apply NIC ITR.`n`n$detail") -Title 'Error' -Icon Error
        } finally {
            if ($null -ne $button) { $button.Text = 'SET' }
            if ($null -ne $button) { $button.Enabled = $true }
            if ($null -ne $button) { try { $button.Invalidate() } catch { } }
        }
    }.GetNewClosure()

    $script:nicApplyTask = Start-PolledRunspaceTask -TaskName 'NICIMODApply' -ScriptText (Get-AsyncNICIMODApplyWorkerScript) -Arguments @(
        $device,
        $globalDeviceAddressMap,
        $nicInfo,
        $newValue,
        $perQueueValues,
        $rwePath
    ) -OnCompleted $onCompleted -OnFailed $onFailed
}

$script:DeviceTweakerStartupFormRedrawGate = $false
$script:DeviceTweakerStartupPanelRedrawGate = $false

function Start-DeviceTweakerStartupFirstPaintGate {
    $script:DeviceTweakerStartupFormRedrawGate = $false
    $script:DeviceTweakerStartupPanelRedrawGate = $false
    try {
        [void]$form.Handle
        [void]$panel.Handle
        [ScrollHelper]::EnableDoubleBufferRecursive($form)
        $script:DeviceTweakerStartupPanelRedrawGate = [ScrollHelper]::BeginConstructionRedraw($panel)
        $script:DeviceTweakerStartupFormRedrawGate = [ScrollHelper]::BeginConstructionRedraw($form)
    } catch {
        $msg = if ($_.Exception) { $_.Exception.Message } else { [string]$_ }
        throw [System.InvalidOperationException]::new(('Startup first-paint gate failed to arm: ' + $msg), $_.Exception)
    }
}

function Complete-DeviceTweakerStartupFirstPaintGate {
    $formGate = [bool]$script:DeviceTweakerStartupFormRedrawGate
    $panelGate = [bool]$script:DeviceTweakerStartupPanelRedrawGate
    $script:DeviceTweakerStartupFormRedrawGate = $false
    $script:DeviceTweakerStartupPanelRedrawGate = $false
    $redrawFailure = $null

    if ($panelGate -and $null -ne $panel -and -not $panel.IsDisposed -and $panel.IsHandleCreated) {
        try { [ScrollHelper]::SetRedraw($panel.Handle, $true) } catch { $redrawFailure = $_.Exception }
    }

    if ($formGate -and $null -ne $form -and -not $form.IsDisposed -and $form.IsHandleCreated) {
        try { [ScrollHelper]::EndConstructionRedraw($form, $true) } catch { $redrawFailure = if ($null -eq $redrawFailure) { $_.Exception } else { [System.AggregateException]::new($redrawFailure, $_.Exception) } }
    } elseif ($panelGate -and $null -ne $panel -and -not $panel.IsDisposed -and $panel.IsHandleCreated) {
        try { [ScrollHelper]::EndConstructionRedraw($panel, $true) } catch { $redrawFailure = if ($null -eq $redrawFailure) { $_.Exception } else { [System.AggregateException]::new($redrawFailure, $_.Exception) } }
    }

    if ($null -ne $redrawFailure) {
        throw [System.InvalidOperationException]::new(('Startup first-paint gate failed to complete: ' + $redrawFailure.Message), $redrawFailure)
    }
}

$form.Add_Shown({
    Complete-DeviceTweakerStartupFirstPaintGate
    [void]$form.BeginInvoke([System.Action]{
        Write-FunctionTimings
        Start-DeviceTweakerAsyncLogWriter
        Invoke-DeviceTweakerDeferredMechanicalDiscoveryAuditLog
        Update-ExovanceDeviceLogSnapshot -Devices $deviceList -LogicalCount $script:cachedLogicalCount -PhysicalCount (Get-PhysicalCoreCount) -Discovery

        try {
            Start-AsyncIRQCountsRefresh
            try {
                Start-AsyncIMODHydration
            } catch {
                Write-Host "Deferred IMOD hydration startup failed: $_" -ForegroundColor Red
                Start-AsyncPostImodHydration
            }
        }
        catch {
            Write-Host "Deferred post-show UI hydration failed: $_" -ForegroundColor Red
        }
    })
})

if ($script:CLIMode) {
    function Show-DarkMessageBox {
        param([string]$Message, [string]$Title, $Buttons, $Icon)
        try { Write-ExovanceDialogLog -Icon $Icon -Title $Title -Message $Message } catch { }
        if ($Message -match 'backup.*before') {
            $answer = if ($script:CLIBackup) { 'Yes' } else { 'No' }
            Write-Host "[CLI] $Title - Backup? -> $answer" -ForegroundColor DarkGray
            return [System.Windows.Forms.DialogResult]::$answer
        }
        if ($Message -match 'MSI.*network') {
            $answer = if ($script:CLINicMsi) { 'Yes' } else { 'No' }
            Write-Host "[CLI] $Title - NIC MSI? -> $answer" -ForegroundColor DarkGray
            return [System.Windows.Forms.DialogResult]::$answer
        }
        $msgClean = ($Message -replace "`n",' ').Substring(0, [Math]::Min($Message.Length, 120))
        Write-Host "[CLI] $Title - $msgClean" -ForegroundColor DarkGray
        return [System.Windows.Forms.DialogResult]::OK
    }

    function Refresh-DeviceUI { Write-Host '[CLI] GUI refresh skipped (headless)' -ForegroundColor DarkGray }

    Start-DeviceTweakerAsyncLogWriter
    Invoke-DeviceTweakerDeferredMechanicalDiscoveryAuditLog
    Update-ExovanceDeviceLogSnapshot -Devices $deviceList -LogicalCount $script:cachedLogicalCount -PhysicalCount (Get-PhysicalCoreCount) -Discovery

    try {
        if ($AutoOptimize) {
            Write-Host '[CLI] Triggering Auto-Optimization...' -ForegroundColor Cyan
            $btnAutoOpt.PerformClick()
        }
        elseif ($SecretOptimize) {
            Write-Host '[CLI] Triggering Alternate Plan...' -ForegroundColor Magenta
            $btnSecretOpt.PerformClick()
        }
        Write-Host ''
        Write-Host '[CLI] Done. Exiting.' -ForegroundColor Green
    }
    catch {
        Write-ExovanceLogEvent -Level Error -Code CliFatal -Stage Runtime -Message $_.Exception.ToString()
        Write-Host "[CLI] FATAL: $_" -ForegroundColor Red
        exit 1
    }
    finally {
        $script:uiShuttingDown = $true
        Stop-DeviceTweakerBackgroundTimers
        Disable-DeviceTweakerConsoleCtrlCGuard
        try { if ($script:scrollState) { $script:scrollState.Dispose(); $script:scrollState = $null } } catch { throw [System.InvalidOperationException]::new(('Native scroll disposal failed during CLI cleanup: ' + $_.Exception.Message), $_.Exception) }
        Write-FunctionTimings
        Stop-DeviceTweakerAsyncLogWriter -Wait
        Stop-DeviceTweakerDiscoveryPool
        Close-ExovanceLogSession
        if ($form -and -not $form.IsDisposed) { $form.Dispose() }
    }
    exit 0
}

Start-DeviceTweakerStartupFirstPaintGate
try {
    [ExovanceVisuals]::ApplyTo($form)
    [void]$form.ShowDialog()
} catch {
    Write-ExovanceLogEvent -Level Error -Code UiFatal -Stage Runtime -Message $_.Exception.ToString()
    throw
} finally {
    try { Complete-DeviceTweakerStartupFirstPaintGate } catch { Write-Host ("Startup first-paint gate cleanup failed: $_") -ForegroundColor Red }
    $script:uiShuttingDown = $true
    Stop-DeviceTweakerBackgroundTimers
    Disable-DeviceTweakerConsoleCtrlCGuard
    try { [WinFormsUnhandledExceptionShield]::Uninstall() } catch { }
    try { if ($script:scrollState) { $script:scrollState.Dispose(); $script:scrollState = $null } } catch { throw [System.InvalidOperationException]::new(('Native scroll disposal failed during UI cleanup: ' + $_.Exception.Message), $_.Exception) }
    Stop-DeviceTweakerAsyncLogWriter -Wait
    Stop-DeviceTweakerDiscoveryPool
    Close-ExovanceLogSession
}
